// ═══════════════════════════════════════════
// LOAD PROJECTS FROM SQL
// ═══════════════════════════════════════════
// Source of truth for the kiosk project picker. Reads /api/projects and
// filters to status === 'In Progress'. The legacy PROJECT TRACKER.xlsx
// read and the hard-coded FALLBACK_PROJECTS list have both been retired —
// every project that should appear here must exist in the SQL Projects
// table (added via the Project Tracker page or auto-created when a quote
// is marked Won).
async function loadProjects() {
  try {
    const rows = await api.get('/api/projects');
    const all = Array.isArray(rows) ? rows : [];

    // Kiosk: workers can only log hours against live projects — restrict to In Progress.
    // Projects page (draftsman): show everything except Archived / Cancelled so newly
    // won projects and On Hold projects are still accessible for job management.
    const isKiosk = CURRENT_PAGE === 'index';
    const list = all
      .filter(p => isKiosk
        ? p.status === 'In Progress'
        : p.status !== 'Archived' && p.status !== 'Cancelled'
      )
      .map(p => ({
        id:     p.project_number,
        dbId:   p.id,
        clientId: p.client_id,
        name:   p.project_name,
        status: p.status,
        client: p.company_name || '',
        // Hide-from-workshop flag (undefined until the 2026-07 migration runs → falsy → shown).
        hidden: !!p.hidden_from_workshop,
        // Delivery-address source for the DN "Deliver to" block.
        site_same_as_client: p.site_same_as_client,
        site_address_line1: p.site_address_line1, site_address_line2: p.site_address_line2,
        site_city: p.site_city, site_county: p.site_county, site_postcode: p.site_postcode,
        site_contact_name: p.site_contact_name, site_contact_phone: p.site_contact_phone,
        client_address_line1: p.address_line1, client_address_line2: p.address_line2,
        client_city: p.city, client_county: p.county, client_postcode: p.postcode,
        client_contact_name: p.contact_name, client_contact_phone: p.contact_phone
      }))
      .sort((a, b) => String(a.id).localeCompare(String(b.id), 'en', { numeric: true, sensitivity: 'base' }));
    state.projects = list;
    console.log(`Projects loaded from SQL: ${list.length} (${CURRENT_PAGE === 'index' ? 'In Progress only' : 'excl. Archived/Cancelled'})`);
  } catch (e) {
    console.warn('SQL projects load failed:', e.message);
    state.projects = [];
  }
}


// ═══════════════════════════════════════════
// SYNC APPROVED HOURS TO LABOUR LOG (SQL)
// ═══════════════════════════════════════════
// Posts ProjectHours rows to /api/labour-log. The endpoint upserts on
// project_hours_id, so re-syncing the same week is safe and reflects any
// edits the office made between syncs. Both productive (S-prefix, C-prefix)
// and unproductive (S000) entries flow through this single call — entry_type
// is derived from project_number.
//
// Replaces the legacy writeApprovedToLabourLog + writeUnproductiveTimeLog
// pair that wrote rows into PROJECT TRACKER.xlsx via Microsoft Graph.
async function writeApprovedToLabourLog(entries) {
  if (!Array.isArray(entries) || !entries.length) return true;
  try {
    setLoading(true);
    const syncedBy = currentManagerUser
      || (typeof AUTH !== 'undefined' && AUTH.getUserName?.())
      || 'unknown';

    const payloadEntries = entries.map(e => ({
      project_hours_id: e.id,
      entry_date:       e.date,
      week_commencing:  e.week_commencing || _weekCommencingFor(e.date),
      employee_id:      e.employee_id || null,
      employee_name:    e.employeeName,
      project_number:   e.projectId,
      project_name:     e.projectName || e.projectId,
      hours:            parseFloat(e.hours) || 0,
      entry_type:       (e.projectId === 'S000' ? 'unproductive' : 'productive')
    }));

    const result = await api.post('/api/labour-log', {
      entries: payloadEntries,
      synced_by: syncedBy
    });

    if (result?.errors?.length) {
      console.warn('LabourLog sync had per-row errors:', result.errors);
      toast(`Labour Log: ${result.total} synced, ${result.errors.length} failed`, 'warning');
    }
    return true;
  } catch (e) {
    console.error('writeApprovedToLabourLog (SQL) error:', e);
    toast(`Labour Log sync error: ${e.message}`, 'error');
    return false;
  } finally {
    setLoading(false);
  }
}

// Compute the Monday of the week containing the given YYYY-MM-DD date,
// returning a YYYY-MM-DD string. Used as a client-side fallback when an
// entry came in without week_commencing populated.
function _weekCommencingFor(dateStr0) {
  if (!dateStr0) return null;
  const d = new Date(dateStr0 + 'T12:00:00');
  const dow = d.getDay();
  const mon = new Date(d);
  mon.setDate(d.getDate() - (dow === 0 ? 6 : dow - 1));
  return dateStr(mon);
}

// ═══════════════════════════════════════════
// WEEK HELPERS
// ═══════════════════════════════════════════
function getWeekDates(offset = 0) {
  const now = new Date();
  const day = now.getDay();
  const mon = new Date(now);
  mon.setDate(now.getDate() - (day === 0 ? 6 : day - 1) + offset * 7);
  const sun = new Date(mon);
  sun.setDate(mon.getDate() + 6);
  return { mon, sun };
}

// Stringify a Date as YYYY-MM-DD using LOCAL time. Using toISOString().slice
// would give the UTC date, which drifts off the local calendar at midnight
// in BST (00:30 BST = 23:30 UTC the previous day). Every caller in this
// file passes a locally-constructed Date (new Date(), new Date(yyyy,mm,dd),
// or copies thereof), so this stays correct in all cases.
// ═══════════════════════════════════════════
// MONEY — one place for all monetary rounding and formatting
// ═══════════════════════════════════════════
// Floating point makes 0.1 + 0.2 = 0.30000000000000004, and that error
// accumulates across line items: a quote summed from 40 lines can land on
// 1290.2999999 and then round DIFFERENTLY depending on which screen renders
// it. Two rules keep every screen and document agreeing:
//
//   1. Round at EVERY monetary step, not just the final .toFixed(2).
//   2. A total is the sum of the ROUNDED lines that are printed next to it —
//      never the rounded sum of unrounded lines — so an invoice always adds up
//      when the client checks it with a calculator.
//
// Use _r2() for a single value and sumMoney() for any list of money.
// Do not write `.reduce((s, x) => s + x.amount, 0)` on monetary values.

const _r2 = v => Math.round((Number(v) || 0) * 100) / 100;

// Sum money so the total equals the sum of the printed (2dp) line values.
// sumMoney(rows, r => r.qty * r.price)  ·  sumMoney(amounts)
function sumMoney(list, pick) {
  return (list || []).reduce((s, item) => {
    const v = pick ? pick(item) : item;
    return _r2(s + _r2(v));
  }, 0);
}

// Percentage of a money value, rounded (retention, VAT, markup).
const pctOf = (value, pct) => _r2(_r2(value) * (Number(pct) || 0) / 100);

// ── Formatting ──
// gbp2      £1,290.30  — invoices, statements, anything reconciled to the penny
// gbpWhole  £1,290     — client-facing quote PDFs (BAMA quotes whole pounds)
// gbpShort  £1.3k      — dashboard tiles only, never on a document
const gbp2 = v => (v === null || v === undefined || v === '') ? '—'
  : '\u00a3' + _r2(v).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const gbpWhole = v => (v === null || v === undefined || v === '') ? '—'
  : '\u00a3' + Math.round(Number(v) || 0).toLocaleString('en-GB');
function gbpShort(v) {
  if (v === null || v === undefined || v === '' || !Number(v)) return '—';
  const n = Number(v);
  if (Math.abs(n) >= 1000000) return '\u00a3' + (n / 1000000).toFixed(1) + 'm';
  if (Math.abs(n) >= 1000)    return '\u00a3' + Math.round(n / 1000) + 'k';
  return '\u00a3' + Math.round(n).toLocaleString('en-GB');
}

function dateStr(d) {
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

function fmtDate(d) {
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
}

// Format a YYYY-MM-DD string to DD/MM/YYYY for display
function fmtDateStr(ds) {
  if (!ds || ds.length < 10) return ds || '';
  const [y, m, d] = ds.split('-');
  return `${d}/${m}/${y}`;
}

function todayStr() { return dateStr(new Date()); }

// Resolve the calendar date "this shift belongs to" for a given employee.
//   - If the employee has an OPEN clocking, return that clocking's date
//     (the shift's start date, even if we've crossed midnight).
//   - Otherwise return today's date.
//
// Used wherever the kiosk needs to filter "today's entries" or "today's
// clocking" — keeps overnight shifts (e.g. Mon 17:00 -> Tue 02:00) anchored
// to the clock-in date instead of jumping forward at midnight.
function activeShiftDate(employeeName) {
  if (employeeName) {
    const open = (state.timesheetData.clockings || []).find(
      c => c.employeeName === employeeName && !c.clockOut
    );
    if (open && open.date) return open.date;
  }
  return todayStr();
}

// ── Pending project-hours entry persistence ──
//
// state.currentEntries holds rows the worker has clicked "Add" on but not yet
// pressed "Submit Day" for. Without persistence these vanish when the kiosk
// navigates back to the home screen, the page reloads, or another worker
// opens their panel — silently losing logged time.
//
// We mirror them into sessionStorage keyed by employee + shift date. When
// openEmployeePanel rehydrates the panel it pulls them back. submitDay()
// clears them on success. If the shift date has rolled over (worker clocked
// in yesterday, never submitted, never clocked out — comes back today) the
// stale key is dropped automatically rather than haunting today's flow.
//
// sessionStorage (not localStorage) is intentional: the kiosk PC is shared,
// staff close the browser at end of day, and we don't want pending entries
// surviving into the next morning by accident.
function _pendingEntriesKey(employeeName, shiftDate) {
  return `bama:pendingEntries:${employeeName}:${shiftDate}`;
}

function loadPendingEntries(employeeName) {
  if (!employeeName) return [];
  const shiftDate = activeShiftDate(employeeName);
  try {
    // Drop any stale keys for this employee from earlier shift dates.
    for (let i = sessionStorage.length - 1; i >= 0; i--) {
      const k = sessionStorage.key(i);
      if (k && k.startsWith(`bama:pendingEntries:${employeeName}:`) && k !== _pendingEntriesKey(employeeName, shiftDate)) {
        sessionStorage.removeItem(k);
      }
    }
    const raw = sessionStorage.getItem(_pendingEntriesKey(employeeName, shiftDate));
    if (!raw) return [];
    const arr = JSON.parse(raw);
    return Array.isArray(arr) ? arr : [];
  } catch (e) {
    console.warn('loadPendingEntries failed:', e.message);
    return [];
  }
}

function savePendingEntries(employeeName) {
  if (!employeeName) return;
  const shiftDate = activeShiftDate(employeeName);
  const key = _pendingEntriesKey(employeeName, shiftDate);
  try {
    if (state.currentEntries && state.currentEntries.length) {
      sessionStorage.setItem(key, JSON.stringify(state.currentEntries));
    } else {
      sessionStorage.removeItem(key);
    }
  } catch (e) {
    console.warn('savePendingEntries failed:', e.message);
  }
}

function clearPendingEntries(employeeName) {
  state.currentEntries = [];
  if (!employeeName) return;
  // Wipe every pending key for this employee — covers the rare case of
  // multiple stale shift dates lingering. submitDay() shouldn't have to know
  // which exact key is current.
  try {
    for (let i = sessionStorage.length - 1; i >= 0; i--) {
      const k = sessionStorage.key(i);
      if (k && k.startsWith(`bama:pendingEntries:${employeeName}:`)) {
        sessionStorage.removeItem(k);
      }
    }
  } catch (e) {
    console.warn('clearPendingEntries failed:', e.message);
  }
}

// ═══════════════════════════════════════════
// EMPLOYEE HOME
// ═══════════════════════════════════════════
function renderHome() {
  const grid = document.getElementById('employeeGrid');
  if (!grid) return; // not on kiosk page
  const today = todayStr();
  grid.innerHTML = '';

  const empList = (state.timesheetData.employees || [])
    .filter(e => e.active !== false)
    .filter(e => (e.staffType || 'workshop') === 'workshop')
    .map(e => e.name);

  if (!empList.length) {
    grid.innerHTML = '<div class="empty-state" style="padding:40px"><div class="icon" style="font-size:32px;margin-bottom:12px">&#128101;</div><div>No employees set up yet.</div><div style="margin-top:8px;font-size:12px">Go to Manager &#8594; Staff to add your team.</div></div>';
    return;
  }

  empList.forEach(name => {
    // Open shift = no clock_out yet. Don't filter by date — overnight shifts
    // (started yesterday, still ongoing) must still light up the green
    // "clocked-in" indicator.
    const clocking = state.timesheetData.clockings.find(
      c => c.employeeName === name && !c.clockOut
    );
    const initials = name.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
    const colors = ['#ff6b00','#e05d00','#c84b00','#a83e00','#ff8c42','#f07030'];

    // Check holiday status — must be declared before use in col
    const isOnHoliday = (state.timesheetData.holidays || []).some(h =>
      h.employeeName === name && h.status === 'approved' &&
      h.dateFrom <= today && h.dateTo >= today
    );
    // Check clocked out today
    const clockedOutToday = state.timesheetData.clockings.find(
      c => c.employeeName === name && c.date === today && c.clockOut
    );

    const col = isOnHoliday ? '#ff69b4' : clocking ? '#3ecf8e' : clockedOutToday ? '#ff4444' : colors[name.charCodeAt(0) % colors.length];

    const div = document.createElement('div');
    div.className = 'emp-btn' + (clocking ? ' clocked-in' : '');

    if (isOnHoliday) {
      div.style.borderColor = '#ff69b4';
      div.style.background = 'rgba(255,105,180,.08)';
    } else if (clocking) {
      // Currently clocked in — green
      div.style.borderColor = 'var(--green)';
      div.style.background = 'rgba(62,207,142,.08)';
    } else if (clockedOutToday) {
      // Clocked out today — red
      div.style.borderColor = 'var(--red)';
      div.style.background = 'rgba(255,68,68,.08)';
    }
    div.innerHTML = `
      <div class="emp-avatar" style="background:linear-gradient(135deg,${col},${isOnHoliday?'#8b0057':clockedOutToday?'#7a0000':'#3e1a00'})">${initials}</div>
      <div class="emp-name">${name}</div>
      <div class="emp-status ${clocking ? 'in' : ''}">
        ${isOnHoliday
          ? '🌴 On Holiday'
          : clocking
          ? `<span class="status-dot"></span>In since ${clocking.clockIn}`
          : clockedOutToday
          ? `✓ Clocked out ${clockedOutToday.clockOut}`
          : 'Not clocked in'}
      </div>
    `;
    div.onclick = () => openEmployee(name);
    grid.appendChild(div);
  });

  // Load workshop notifications (assembly tasks, etc.)
  if (CURRENT_PAGE === 'index') {
    renderWorkshopNotifications();
    // Slight delay so drawingsData has a chance to populate on initial load
    setTimeout(checkNewJobAlerts, 200);
    // Fabrication tile (commit 11 — SPEC §8). First load + poll.
    loadKioskFabrication();
  }
}

// ═══════════════════════════════════════════
// KIOSK FABRICATION TILE (commit 11 — SPEC §8)
// ═══════════════════════════════════════════
//
// ── Bookable shop-floor staff ──────────────────────────────────────────────
// Who can be attributed as fabricator/welder on assembly stage events.
// Workshop staff always; PLUS office staff whose ERP role is Director or
// Project Manager (Mateusz, Leszek) — they fab/weld alongside the shop but
// must NOT appear as kiosk clock-in tiles (renderHome stays workshop-only).
// Fab Output report groups by the stored operator_name, so anyone selectable
// here shows on the report automatically.
function bookableShopStaff() {
  const list = (state.timesheetData.employees || [])
    .filter(e => e.active !== false)
    .filter(e => (e.staffType || 'workshop') === 'workshop'
               || ['director', 'project_manager'].includes(e.erpRole));
  // Workshop first, office (director/PM) below — each group alphabetical —
  // so shop-floor names sit at the top of every picker.
  const grp = e => ((e.staffType || 'workshop') === 'workshop' ? 0 : 1);
  return list.sort((a, b) => grp(a) - grp(b) || String(a.name || '').localeCompare(String(b.name || '')));
}

// Optgroup HTML for the stage-modal operator <select>s: Workshop on top,
// Office at the bottom, so nobody mis-taps into the wrong group.
function shopStaffOptionsHtml() {
  const shop = [], office = [];
  for (const e of bookableShopStaff()) ((e.staffType || 'workshop') === 'workshop' ? shop : office).push(e);
  const opt = w => `<option value="${w.id}" data-name="${escapeHtml(w.name)}">${escapeHtml(w.name)}</option>`;
  let html = '';
  if (shop.length)   html += `<optgroup label="Workshop">${shop.map(opt).join('')}</optgroup>`;
  if (office.length) html += `<optgroup label="Office">${office.map(opt).join('')}</optgroup>`;
  return html;
}

// Full-width section on the kiosk home screen showing pending assemblies
// workshop-wide. Tapping "Mark fabricated" on any card opens the same
// welder+machine modal as projects.html (reused via openMarkFabricatedModal
// with opts.assembly + opts.onSuccess).
//
// Visibility rule: pending assemblies on In Progress projects, PLUS any
// assemblies marked fabricated in the last 24h (dimmed + green tick).
//
// Refresh: initial load on home render + 60s poll while the home screen is
// the active screen.

let _kioskFabData = [];
let _kioskFabFilter = '__all__';
let _kioskFabOpenGroups = new Set(); // group keys (project|job) expanded by the user
let _kioskFabTimer = null;

async function loadKioskFabrication() {
  const tile = document.getElementById('kioskFabricationTile');
  if (!tile) return; // not on kiosk
  try {
    const rows = await api.get('/api/job-assemblies/kiosk');
    _kioskFabData = Array.isArray(rows) ? rows : [];
  } catch (e) {
    console.warn('Kiosk fabrication load failed:', e.message);
    _kioskFabData = [];
  }
  renderKioskFabrication();
  scheduleKioskFabricationPoll();
}

function scheduleKioskFabricationPoll() {
  if (_kioskFabTimer) clearTimeout(_kioskFabTimer);
  _kioskFabTimer = setTimeout(() => {
    // Only poll while the home screen is the active one (don't burn cycles
    // when the user is deep in an employee panel or holiday flow).
    const home = document.getElementById('screenHome');
    if (home && home.classList.contains('active')) {
      loadKioskFabrication();
    } else {
      // Re-arm for later
      scheduleKioskFabricationPoll();
    }
  }, 60000);
}

function renderKioskFabrication() {
  const tile = document.getElementById('kioskFabricationTile');
  if (!tile) return;
  const list = document.getElementById('kioskFabList');
  const chips = document.getElementById('kioskFabChips');
  const countEl = document.getElementById('kioskFabCount');

  if (!_kioskFabData.length) {
    tile.style.display = 'none';
    return;
  }
  tile.style.display = '';

  const pendingCount = _kioskFabData.filter(a => !asmIsTerminal(a)).length;
  const fabCount = _kioskFabData.filter(a => asmIsTerminal(a)).length;
  countEl.textContent = `${pendingCount} pending${fabCount ? ` · ${fabCount} complete (24h)` : ''}`;

  // Project filter chips — one per project that has any rows
  const projects = [...new Map(_kioskFabData.map(a => [a.project_number, a.project_name || a.project_number])).entries()];
  projects.sort((a, b) => String(a[0]).localeCompare(String(b[0]), 'en', { numeric: true }));
  let chipsHtml = `<div class="kfab-chip ${_kioskFabFilter === '__all__' ? 'active' : ''}" onclick="setKioskFabFilter('__all__')">All projects</div>`;
  for (const [num, name] of projects) {
    const active = _kioskFabFilter === num ? 'active' : '';
    chipsHtml += `<div class="kfab-chip ${active}" onclick="setKioskFabFilter('${escapeHtml(num)}')">${escapeHtml(num)}</div>`;
  }
  chips.innerHTML = chipsHtml;

  // Bulk-select toolbar (kiosk). Mirrors the projects.html one.
  _bulkSurface = 'kiosk';
  const filteredForBulk = (_kioskFabFilter === '__all__' ? _kioskFabData
    : _kioskFabData.filter(a => a.project_number === _kioskFabFilter));
  const nonTermKiosk = filteredForBulk.filter(a => !asmIsTerminal(a));
  let bulkBar = '';
  if (nonTermKiosk.length > 1) {
    if (!_bulkSelectMode) {
      bulkBar = `<div style="display:flex;justify-content:flex-end;margin:4px 0 8px">
        <button class="btn btn-ghost" style="padding:5px 14px;font-size:12px" onclick="toggleBulkSelect()">&#9745; Select multiple</button>
      </div>`;
    } else {
      const selCount = filteredForBulk.filter(a => _bulkSelected.has(a.id)).length;
      const visibleIds = JSON.stringify(nonTermKiosk.map(a => a.id));
      bulkBar = `<div style="position:sticky;top:0;z-index:6;background:var(--bg,#1a1a1a);border:1px solid var(--accent);border-radius:10px;padding:10px 14px;margin:4px 0 10px;display:flex;align-items:center;gap:10px;flex-wrap:wrap">
        <span style="font-weight:700;color:var(--accent)">${selCount} selected</span>
        <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick='bulkSelectAllVisible(${visibleIds})'>Select all</button>
        <span style="margin-left:auto;display:flex;gap:6px;flex-wrap:wrap">
          <button class="btn btn-primary" style="padding:5px 12px;font-size:11px${selCount ? '' : ';opacity:.4;pointer-events:none'}" onclick="openBulkStageModal('fab', _kioskFabData, 'kiosk')">&#128296; Fab</button>
          <button class="btn btn-primary" style="padding:5px 12px;font-size:11px;background:rgba(234,179,8,.9);border-color:rgba(234,179,8,.9)${selCount ? '' : ';opacity:.4;pointer-events:none'}" onclick="openBulkStageModal('weld', _kioskFabData, 'kiosk')">&#128293; Weld</button>
          <button class="btn btn-primary" style="padding:5px 12px;font-size:11px${selCount ? '' : ';opacity:.4;pointer-events:none'}" onclick="openBulkStageModal('complete', _kioskFabData, 'kiosk')">&#10003; Complete</button>
          <button class="btn btn-ghost" style="padding:5px 12px;font-size:11px" onclick="toggleBulkSelect()">Cancel</button>
        </span>
      </div>`;
    }
  }

  // Filter + group rendered list by project+job
  const filtered = _kioskFabFilter === '__all__'
    ? _kioskFabData
    : _kioskFabData.filter(a => a.project_number === _kioskFabFilter);

  if (!filtered.length) {
    list.innerHTML = '<div style="color:var(--subtle);font-size:13px;padding:14px;text-align:center">Nothing pending for this project right now.</div>';
    return;
  }

  // Group key = project_number + job_id; render section header per group.
  const groups = new Map();
  for (const a of filtered) {
    const key = `${a.project_number}|${a.job_id}`;
    if (!groups.has(key)) groups.set(key, { project_number: a.project_number, project_name: a.project_name, company_name: a.company_name, job_name: a.job_name, items: [] });
    groups.get(key).items.push(a);
  }

  // ── Collapsible job tiles ──
  // With several live jobs the flat list was unreadable on the shop floor —
  // each project+job group is now a tappable tile, COLLAPSED by default, with
  // summary counts on the header. Lads tap the job they're on, then mark
  // fab/weld/complete inside. Open state persists across the 60s poll
  // re-render via _kioskFabOpenGroups. Exceptions that force-expand:
  //   · exactly one group visible (no ambiguity — save the tap)
  //   · bulk-select mode (checkboxes must be visible to pick)
  let html = bulkBar;
  const groupArr = [...groups.entries()];
  const forceOpen = _bulkSelectMode || groupArr.length === 1;
  for (const [key, g] of groupArr) {
    const isOpen = forceOpen || _kioskFabOpenGroups.has(key);
    const pending = g.items.filter(a => !asmIsTerminal(a));
    const done    = g.items.length - pending.length;
    let sumFab = 0, sumWeld = 0;
    for (const a of pending) { sumFab += asmToFab(a); sumWeld += asmReadyToWeld(a); }

    const chip = (txt, col, bg) => `<span style="background:${bg};color:${col};padding:3px 10px;border-radius:6px;font-size:12px;font-family:var(--font-mono);white-space:nowrap">${txt}</span>`;
    let sumChips = '';
    if (sumFab > 0)  sumChips += chip(`${sumFab} to fab`, '#fca5a5', 'rgba(239,68,68,.14)');
    if (sumWeld > 0) sumChips += chip(`${sumWeld} to weld`, '#fcd34d', 'rgba(234,179,8,.14)');
    if (done > 0)    sumChips += chip(`${done} complete`, 'var(--green)', 'rgba(62,207,142,.12)');
    if (!sumChips)   sumChips = chip('nothing pending', 'var(--subtle)', 'rgba(255,255,255,.05)');

    const marks = pending.slice(0, 8).map(a => escapeHtml(a.assembly_mark)).join(' · ')
      + (pending.length > 8 ? ` · +${pending.length - 8} more` : '');

    // Header tile — big touch target. Chevron rotates when open.
    html += `<div style="background:var(--surface);border:1px solid ${isOpen ? 'var(--accent)' : 'var(--border)'};border-radius:12px;margin:12px 0 0;overflow:hidden">
      <div onclick="toggleKioskFabGroup('${escapeHtml(key)}')" style="cursor:pointer;padding:14px 16px;display:flex;align-items:center;gap:14px;flex-wrap:wrap;-webkit-tap-highlight-color:transparent">
        <span style="font-size:18px;color:var(--accent);flex:0 0 auto;transform:rotate(${isOpen ? 90 : 0}deg);transition:transform .15s">&#9656;</span>
        <div style="flex:1;min-width:200px">
          <div style="font-size:16px;font-weight:700;color:var(--text)">${escapeHtml(g.job_name)}</div>
          <div style="font-size:11px;color:var(--subtle);text-transform:uppercase;letter-spacing:.05em;margin-top:2px">
            ${escapeHtml(g.project_number)}${g.project_name ? ` — ${escapeHtml(g.project_name)}` : ''}${g.company_name ? ` · ${escapeHtml(g.company_name)}` : ''}
          </div>
          ${!isOpen && marks ? `<div style="font-size:11px;color:var(--subtle);font-family:var(--font-mono);margin-top:4px">${marks}</div>` : ''}
        </div>
        <span style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">${sumChips}</span>
      </div>
      ${isOpen ? `<div style="display:flex;flex-direction:column;gap:8px;padding:0 12px 12px">${g.items.map(a => renderKioskFabCard(a)).join('')}</div>` : ''}
    </div>`;
  }
  list.innerHTML = html;
}

function renderKioskFabCard(a) {
  const isFab = asmIsTerminal(a);
  const toFab = asmToFab(a), rtw = asmReadyToWeld(a), bom = asmBomQty(a);
  const finishBadge = a.finish_name
    ? `<span style="background:rgba(99,102,241,.18);color:#a5b4fc;padding:2px 9px;border-radius:6px;font-size:11px">${escapeHtml(a.finish_name)}</span>`
    : a.finish_label_raw
      ? `<span style="background:rgba(234,179,8,.15);color:#fcd34d;border:1px solid rgba(234,179,8,.35);padding:2px 9px;border-radius:6px;font-size:11px" title="Read from drawing — not linked to a finishing service. Add it under Office → Service Types.">${escapeHtml(a.finish_label_raw)}</span>`
      : '<span style="color:var(--subtle);font-size:11px">No finish</span>';

  // Open PDF link (matches projects.html assembly card)
  const pdfLink = a.sharepoint_web_url
    ? `<a href="${escapeHtml(a.sharepoint_web_url)}" target="_blank" rel="noopener"
          class="btn btn-ghost"
          style="padding:6px 12px;font-size:11px;text-decoration:none;color:var(--text)"
          onclick="event.stopPropagation()">&#128279; Open PDF</a>`
    : '';

  // Compact parts table (only for pending — fabricated cards stay slim)
  let partsHtml = '';
  if (!isFab && a.parts && a.parts.length) {
    partsHtml = `<table style="width:100%;font-family:var(--font-mono);font-size:11px;color:var(--text);border-collapse:collapse;margin-top:6px">
      <thead><tr style="color:var(--subtle);text-align:left">
        <th style="font-weight:400;padding:3px 6px 3px 0">Mk</th>
        <th style="font-weight:400;padding:3px 6px">Qty</th>
        <th style="font-weight:400;padding:3px 6px">Profile</th>
        <th style="font-weight:400;padding:3px 6px">Length</th>
        <th style="font-weight:400;padding:3px 6px">Material</th>
      </tr></thead><tbody>`;
    // Highlight heaviest
    let heavyIdx = -1, heavyWt = -Infinity;
    a.parts.forEach((p, i) => {
      const w = Number(p.weight_kg) || 0;
      if (w > heavyWt) { heavyWt = w; heavyIdx = i; }
    });
    for (let i = 0; i < a.parts.length; i++) {
      const p = a.parts[i];
      const hi = i === heavyIdx;
      const tr = hi ? 'background:rgba(255,107,0,.06)' : '';
      const ac = hi ? 'color:var(--accent)' : '';
      partsHtml += `<tr style="${tr}">
        <td style="padding:3px 6px 3px 0">${escapeHtml(p.part_mark)}</td>
        <td style="padding:3px 6px">${Number(p.quantity)}</td>
        <td style="padding:3px 6px;${ac}">${escapeHtml(p.profile)}</td>
        <td style="padding:3px 6px">${p.length_mm != null ? Number(p.length_mm).toFixed(1) : ''}</td>
        <td style="padding:3px 6px">${p.material ? escapeHtml(p.material) : ''}</td>
      </tr>`;
    }
    partsHtml += '</tbody></table>';
  }

  // Action row — staged buttons (Fab / Weld / Complete) or the complete tag.
  // Kiosk = workshop mode: weld/complete capture welder + machine.
  let actions;
  if (isFab) {
    actions = `<span style="margin-left:auto;color:var(--green);font-size:11px">&#10003; Complete ${a.fabricated_at ? new Date(a.fabricated_at).toLocaleString('en-GB', { day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit' }) : ''}${a.fabricated_by ? ' · ' + escapeHtml(a.fabricated_by) : ''}</span>${pdfLink ? '<span>' + pdfLink + '</span>' : ''}`;
  } else {
    let btns = '';
    if (toFab > 0) btns += `<button class="btn btn-primary" style="padding:6px 14px;font-size:12px" onclick="kioskStageAction('fab',${a.id})">&#128296; Fabbed${toFab < Number(a.quantity) ? ` (${toFab})` : ''}</button>`;
    if (rtw > 0)   btns += `<button class="btn btn-primary" style="padding:6px 14px;font-size:12px;background:rgba(234,179,8,.9);border-color:rgba(234,179,8,.9)" onclick="kioskStageAction('weld',${a.id})">&#128293; Welded (${rtw})</button>`;
    if (toFab > 0) btns += `<button class="btn btn-ghost" style="padding:6px 14px;font-size:12px" onclick="kioskStageAction('complete',${a.id})">&#10003; Complete${toFab < Number(a.quantity) ? ` (${toFab})` : ''}</button>`;
    actions = `<span style="margin-left:auto;display:flex;gap:8px;align-items:center;flex-wrap:wrap">${pdfLink}${btns}</span>`;
  }

  // Progress chips (kiosk header)
  let chips = '';
  if (!isFab) {
    const chip = (txt, col, bg) => `<span style="background:${bg};color:${col};padding:2px 8px;border-radius:6px;font-size:11px;font-family:var(--font-mono)">${txt}</span>`;
    if (toFab > 0) chips += chip(`${toFab} to fab`, '#fca5a5', 'rgba(239,68,68,.14)');
    if (rtw > 0)   chips += chip(`${rtw} to weld`, '#fcd34d', 'rgba(234,179,8,.14)');
    if (bom > 0)   chips += chip(`${bom} on BOM`, 'var(--green)', 'rgba(62,207,142,.12)');
  }

  // Bulk-select checkbox (kiosk). Non-terminal cards only.
  const selectable = _bulkSelectMode && !isFab;
  const picked = _bulkSelected.has(a.id);
  const checkbox = selectable
    ? `<span onclick="event.stopPropagation();toggleBulkPick(${a.id})" style="cursor:pointer;width:22px;height:22px;border-radius:5px;border:2px solid ${picked ? 'var(--accent)' : 'var(--border)'};background:${picked ? 'var(--accent)' : 'transparent'};display:inline-flex;align-items:center;justify-content:center;color:#fff;font-size:14px;flex:0 0 auto">${picked ? '&#10003;' : ''}</span>`
    : '';
  const cardClick = selectable ? `onclick="toggleBulkPick(${a.id})" style="cursor:pointer"` : '';
  // In select mode, hide the per-card action buttons to avoid confusion.
  const shownActions = _bulkSelectMode ? '' : actions;

  return `<div ${cardClick} style="background:var(--surface);border:1px solid ${picked ? 'var(--accent)' : 'var(--border)'};border-radius:10px;padding:12px 14px;${isFab ? 'opacity:.55;' : ''}">
    <div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap">
      ${checkbox}
      <span style="font-family:var(--font-mono);font-size:15px;font-weight:700;color:${isFab ? 'var(--text)' : 'var(--accent)'};min-width:50px">${escapeHtml(a.assembly_mark)}</span>
      <span style="font-size:13px;color:var(--text);min-width:60px">${Number(a.quantity)} off</span>
      ${finishBadge}
      <span style="display:flex;gap:6px;flex-wrap:wrap">${chips}</span>
      ${shownActions}
    </div>
    ${_bulkSelectMode ? '' : partsHtml}
  </div>`;
}

function setKioskFabFilter(num) {
  _kioskFabFilter = num;
  renderKioskFabrication();
}

// Expand/collapse one kiosk job tile. Open keys survive re-renders (poll).
function toggleKioskFabGroup(key) {
  if (_kioskFabOpenGroups.has(key)) _kioskFabOpenGroups.delete(key);
  else _kioskFabOpenGroups.add(key);
  renderKioskFabrication();
}

function kioskStageAction(stage, id) {
  const assembly = _kioskFabData.find(a => a.id === id);
  if (!assembly) { toast('Assembly not found.', 'error'); return; }
  openStageActionModal(stage, id, {
    assembly,
    onSuccess: async () => { await loadKioskFabrication(); }
  });
}

// Back-compat: old kiosk entry point → complete stage.
function kioskMarkFabricated(id) {
  return kioskStageAction('complete', id);
}

// ── Workshop Kiosk Notifications ──
function renderWorkshopNotifications() {
  const container = document.getElementById('workshopNotifications');
  if (!container) return;

  // Load drawings data in background if not already loaded
  if (!Object.keys(drawingsData.projects || {}).length) {
    loadDrawingsData().then(() => _renderWorkshopNotifs(container)).catch(() => {});
    return;
  }
  _renderWorkshopNotifs(container);
}

function _renderWorkshopNotifs(container) {
  // Scan all projects/jobs for open assembly tasks, excluding acknowledged jobs
  const ackedJobs = _njaGetAcked();
  const notifications = [];

  for (const projId of Object.keys(drawingsData.projects || {})) {
    const projData = drawingsData.projects[projId];
    const proj = state.projects?.find(p => p.id === projId);
    const projName = proj ? `${proj.id} — ${proj.name}` : projId;
    for (const job of (projData.jobs || [])) {
      if (job.status === 'closed') continue;
      if (ackedJobs.has(_njaJobKey(projId, job.id))) continue; // hide acknowledged jobs
      for (const task of (job.assembly?.tasks || [])) {
        if (task.status === 'complete') continue;
        const created = new Date(task.createdAt).getTime();
        const isNew = created > (Date.now() - 48 * 60 * 60 * 1000);
        notifications.push({
          type: 'assembly',
          projectId: projId,
          project: projName,
          jobId: job.id,
          job: job.name,
          task: task.name,
          finishing: task.finishing,
          createdAt: task.createdAt,
          isNew
        });
      }
    }
  }

  if (!notifications.length) { container.innerHTML = ''; return; }
  notifications.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  const newCount = notifications.filter(n => n.isNew).length;

  let html = '';
  html += `<div style="font-size:13px;font-weight:600;margin-bottom:8px;display:flex;align-items:center;gap:8px">`;
  html += `<span>&#128295; Workshop Tasks</span>`;
  html += `<span style="background:var(--accent);color:#fff;font-size:10px;padding:2px 8px;border-radius:10px;font-weight:700">${notifications.length}</span>`;
  if (newCount) html += `<span style="font-size:11px;color:var(--green);font-weight:500">${newCount} new</span>`;
  html += `</div>`;

  for (const n of notifications) {
    const age = timeAgo(n.createdAt);
    const finLabel = n.finishing && n.finishing !== 'none' ? ` · ${n.finishing}` : '';
    const borderColor = n.isNew ? 'var(--accent)' : 'var(--border)';
    const deepLink = `projects.html?project=${encodeURIComponent(n.projectId)}&job=${encodeURIComponent(n.jobId)}&element=Assembly`;
    html += `<a href="${deepLink}" style="text-decoration:none;color:inherit;display:block">`;
    html += `<div class="notification-banner" style="cursor:pointer;margin-bottom:8px;text-align:left;border-left:3px solid ${borderColor}">`;
    html += `<span class="nb-icon">${n.isNew ? '&#128312;' : '&#128295;'}</span>`;
    html += `<span class="nb-text"><b>${n.isNew ? 'NEW: ' : ''}${n.task}</b>${finLabel}<br><span style="font-size:11px;color:var(--subtle)">${n.project} · ${n.job} · ${age}</span></span>`;
    html += `<span style="font-size:11px;color:var(--accent);margin-left:auto;padding-left:8px">View &rarr;</span>`;
    html += `</div></a>`;
  }
  container.innerHTML = html;
}

let _pendingEmployee = null;

function openEmployee(name) {
  const emp = (state.timesheetData.employees || []).find(e => e.name === name);

  // If employee has a PIN, show PIN modal first
  if (emp && emp.hasPin) {
    _pendingEmployee = name;
    document.getElementById('empPinModalName').textContent = name;
    document.getElementById('empPinInput').value = '';
    document.getElementById('empPinError').textContent = '';
    document.getElementById('empPinModal').classList.add('active');
    setTimeout(() => document.getElementById('empPinInput').focus(), 100);
    return;
  }

  // No PIN — open directly
  openEmployeePanel(name);
}

async function checkEmpPin() {
  const pin = document.getElementById('empPinInput').value;
  const emp = (state.timesheetData.employees || []).find(e => e.name === _pendingEmployee);

  if (!emp) return;

  let result;
  try {
    result = await api.post('/api/auth/verify-pin', { employee_id: emp.id, pin });
  } catch (err) {
    document.getElementById('empPinError').textContent = 'Verification failed — try again';
    return;
  }

  if (result && result.valid) {
    closeEmpPinModal();
    openEmployeePanel(emp.name);
  } else {
    document.getElementById('empPinError').textContent = (result && result.reason) || 'Incorrect PIN — try again';
    document.getElementById('empPinInput').value = '';
    document.getElementById('empPinInput').focus();
  }
}

function closeEmpPinModal() {
  document.getElementById('empPinModal').classList.remove('active');
  _pendingEmployee = null;
}

function openEmployeePanel(name) {
  state.currentEmployee = name;
  // Rehydrate any pending entries saved during a previous panel session
  // (e.g. worker tapped Add, navigated back, came back to log more). These
  // live in sessionStorage keyed by employee+shift date.
  state.currentEntries = loadPendingEntries(name);

  document.getElementById('empPanelName').textContent = name;

  // Show holiday approval/rejection notifications immediately on entry
  checkHolidayClockInNotification(name);

  // Set today's date as shift card title
  const shiftLabel = document.getElementById('shiftDateLabel');
  if (shiftLabel) {
    shiftLabel.textContent = new Date().toLocaleDateString('en-GB', {
      weekday: 'long', day: 'numeric', month: 'long'
    });
  }

  // Always show project time card — employees may log hours before or after clocking out
  const projectCard = document.getElementById('projectTimeCard');
  if (projectCard) projectCard.style.display = '';

  // Time selects
  fillTimeSelects();

  // Render My Week
  renderMyWeek(name);

  // Render Last Week Review (final chance to flag issues before payroll).
  // Async — checks payroll-revisions, may hide the card.
  renderLastWeekReview(name);

  // Render holiday balance
  renderEmpHolidayBalance(name);

  // Render booked/approved/declined holidays (excludes sick + unpaid)
  renderMyHolidays(name);

  // Reload projects live from SQL in background
  loadProjects().then(() => {
    // Refresh the project dropdown if already on screen
    const sel = document.getElementById('projectSelect');
    if (sel) {
      sel.innerHTML = '<option value="">Select project…</option>';
      // Always add Workshop General Duties at the top
      const wgdOpt = document.createElement('option');
      wgdOpt.value = 'WGD';
      wgdOpt.textContent = '🔧 Workshop General Duties';
      sel.appendChild(wgdOpt);
      state.projects.forEach(p => {
        const opt = document.createElement('option');
        opt.value = p.id;
        opt.textContent = `${p.id} — ${p.name}`;
        sel.appendChild(opt);
      });
    }
  }).catch(() => {});

  // Check clocked in. Don't filter by date — overnight shifts started
  // yesterday must still show the "clocked in" UI today.
  const clocking = state.timesheetData.clockings.find(
    c => c.employeeName === name && !c.clockOut
  );

  if (clocking) {
    showClockedIn(clocking);
  } else {
    document.getElementById('clockInSection').style.display = '';
    document.getElementById('clockedInSection').style.display = 'none';
    document.getElementById('statusBar').style.display = 'none';
  }

  // Populate project select
  const sel = document.getElementById('projectSelect');
  sel.innerHTML = '<option value="">Select project…</option>';
  // WGD goes first so it's always available even if SharePoint projects fail to load
  const wgdOpt = document.createElement('option');
  wgdOpt.value = 'WGD';
  wgdOpt.textContent = '🔧 Workshop General Duties';
  sel.appendChild(wgdOpt);
  state.projects.forEach(p => {
    const opt = document.createElement('option');
    opt.value = p.id;
    opt.textContent = `${p.id} — ${p.name}`;
    sel.appendChild(opt);
  });

  // Load today's already-submitted entries
  renderTodayEntries();

  showScreen('screenEmployee');
}

function showClockedIn(clocking) {
  document.getElementById('clockInSection').style.display = 'none';
  document.getElementById('clockedInSection').style.display = '';
  document.getElementById('displayClockIn').textContent = clocking.clockIn;
  document.getElementById('statusBar').style.display = 'flex';
  document.getElementById('statusClockIn').textContent = clocking.clockIn;
  updateWorkingTime(clocking.clockIn);
}

let workingTimer = null;
function updateWorkingTime(clockInStr) {
  clearInterval(workingTimer);
  workingTimer = setInterval(() => {
    const [h, m] = clockInStr.split(':').map(Number);
    const start = new Date(); start.setHours(h, m, 0, 0);
    const diff = Math.floor((Date.now() - start) / 1000);
    if (diff < 0) { clearInterval(workingTimer); return; }
    const hrs = Math.floor(diff / 3600);
    const mins = Math.floor((diff % 3600) / 60);
    document.getElementById('statusWorking').textContent = `${hrs}h ${mins}m`;
  }, 10000);
}

function fillTimeSelects() {
  // Clock in time is now auto-captured — no dropdown to fill
  // Only populate time selects for add-clocking modals that still need them
  ['addClockIn', 'addClockOut', 'mgrClockIn', 'mgrClockOut'].forEach(id => {
    const sel = document.getElementById(id);
    if (sel && sel.tagName === 'SELECT') {
      sel.innerHTML = '';
      CONFIG.timeSlots.forEach(s => {
        const opt = document.createElement('option');
        opt.value = s.val; opt.textContent = s.label;
        sel.appendChild(opt);
      });
    }
  });
}

function onProjectSelect() {
  const id = document.getElementById('projectSelect').value;
  const p = id === 'WGD'
    ? { name: 'Workshop General Duties' }
    : state.projects.find(x => x.id === id);
  document.getElementById('projectNameDisplay').textContent = p ? p.name : '—';
}

function addEntry() {
  const projId = document.getElementById('projectSelect').value;
  const hours = parseFloat(document.getElementById('hoursInput').value);

  if (!projId) { toast('Please select a project', 'error'); return; }
  if (!hours || hours <= 0) { toast('Please enter valid hours', 'error'); return; }

  const proj = projId === 'WGD'
    ? { id: 'WGD', name: 'Workshop General Duties' }
    : state.projects.find(p => p.id === projId);
  state.currentEntries.push({
    id: Date.now().toString(),
    projectId: projId,
    projectName: proj ? proj.name : projId,
    hours
  });
  // Persist so the entry survives navigation, page reload, or another worker
  // opening their panel between Add and Submit.
  savePendingEntries(state.currentEmployee);

  document.getElementById('hoursInput').value = '';
  document.getElementById('projectSelect').value = '';
  document.getElementById('projectNameDisplay').textContent = '—';
  renderTodayEntries();
}

function removeEntry(id) {
  state.currentEntries = state.currentEntries.filter(e => String(e.id) !== String(id));
  savePendingEntries(state.currentEmployee);
  renderTodayEntries();
}

function renderTodayEntries() {
  const container = document.getElementById('todayEntries');
  // If the worker is on an overnight shift, "today's entries" means
  // entries against the shift's start date — not the wall-clock date.
  const shiftDate = activeShiftDate(state.currentEmployee);

  // Submitted entries + current session entries
  const submitted = state.timesheetData.entries.filter(
    e => e.employeeName === state.currentEmployee && e.date === shiftDate
  );

  const all = [
    ...submitted.map(e => ({ ...e, saved: true })),
    ...state.currentEntries.map(e => ({ ...e, saved: false }))
  ];

  if (!all.length) {
    container.innerHTML = '<div class="empty-state" style="padding:20px"><span style="opacity:.4">No entries yet today</span></div>';
    return;
  }

  container.innerHTML = all.map(e => `
    <div class="entry-chip">
      <span class="proj-id">${e.projectId}</span>
      <span class="proj-name">${e.projectName}</span>
      <span class="proj-hrs">${e.hours}h</span>
      ${e.saved
        ? `<span style="font-size:11px;color:var(--muted);margin-left:8px">saved</span>`
        : `<button class="del-btn" onclick="removeEntry('${e.id}')">×</button>`
      }
    </div>
  `).join('');
}

async function doClock(direction) {
  try {
  const today = todayStr();
  const emp = state.currentEmployee;
  if (!emp) { toast('No employee selected', 'error'); return; }
  const empId = empIdByName(emp);
  if (!empId) { toast('Employee not found in system', 'error'); return; }

  if (direction === 'in') {
    // Hard block: workshop is closed on bank holidays.
    // See docs/SPEC-holiday-payroll.md.
    if (isBankHoliday(today)) {
      toast('The workshop is closed today (bank holiday). If this is wrong, speak to the office.', 'error');
      return;
    }

    // Check if already clocked in (local check for instant feedback). Don't
    // filter by date — an open shift from yesterday means the worker forgot
    // to clock out and needs to do that first, otherwise they'd end up with
    // two open shifts.
    const existing = state.timesheetData.clockings.find(
      c => c.employeeName === emp && !c.clockOut
    );
    if (existing) {
      const sameDay = existing.date === today;
      toast(
        sameDay
          ? `${emp} is already clocked in today at ${existing.clockIn}`
          : `${emp} has an open shift from ${fmtDateStr(existing.date)} (clocked in at ${existing.clockIn}). Clock out first.`,
        'error'
      );
      return;
    }

    // Block if already completed a full shift today
    const completedToday = state.timesheetData.clockings.find(
      c => c.employeeName === emp && c.date === today && c.clockOut
    );
    if (completedToday) {
      toast(`${emp} has already clocked in and out today (${completedToday.clockIn} – ${completedToday.clockOut})`, 'error');
      return;
    }

    // Call API
    const result = await api.post('/api/clock-in', {
      employee_id: empId,
      source: 'kiosk'
    });

    // Add to local state
    const newClocking = normaliseClocking(result);
    state.timesheetData.clockings.push(newClocking);

    // Check if they have an approved holiday today
    const hasApprovedHoliday = (state.timesheetData.holidays || []).some(h =>
      h.employeeName === emp && h.status === 'approved' &&
      h.dateFrom <= today && h.dateTo >= today
    );
    if (hasApprovedHoliday) {
      toast(`⚠️ You have approved holiday today — clocking in anyway`, 'info');
    }

    showClockedIn({ clockIn: newClocking.clockIn });
    renderHome();
    toast(`Clocked in at ${newClocking.clockIn}`, 'success');

  } else {
    // CLOCK OUT
    // Find the open shift for this employee. Don't filter by date — overnight
    // shifts (e.g. Mon 17:00 -> Tue 02:00) need to remain closeable after
    // midnight, when today != the clock-in date.
    const clocking = state.timesheetData.clockings.find(
      c => c.employeeName === emp && !c.clockOut
    );
    if (!clocking) { toast('Not clocked in — cannot clock out', 'error'); return; }

    // The shift belongs to its START date. Everything downstream (entry
    // filters, S000 recompute, toast text) is keyed off this, not today.
    const shiftDate = clocking.date;

    const breakEl = document.getElementById('breakDuration');
    let breakMins = breakEl ? (parseInt(breakEl.value) || 30) : 30;

    // Capture exact current time for clock out
    const now = new Date();
    const clockOut = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;

    const ctx = { emp, today: shiftDate, clockOut, breakMins, clocking };

    // Gate 1: unsubmitted pending entries. If the worker hit Add but never
    // hit Submit Day, those rows live only in JS/sessionStorage — they are
    // NOT in SQL yet. Letting them clock out now would silently drop the
    // hours and the server-side S000 recompute would treat the whole shift
    // as unproductive. Force a decision.
    if (Array.isArray(state.currentEntries) && state.currentEntries.length > 0) {
      _pendingClockOutData = ctx;
      openUnsubmittedEntriesModal();
      return;
    }

    await proceedWithClockOut(ctx);
  }
  } catch (err) {
    console.error('doClock error:', err);
    toast('Clock error: ' + err.message, 'error');
  }
}

// Continues the clock-out flow after Gate 1 (unsubmitted entries) has passed.
// Runs Gate 2 (no project hours at all → noProjectModal) and Gate 3
// (remaining unallocated hours → remainingHoursModal). Falls through to
// finishClockOut() if nothing trips.
async function proceedWithClockOut(ctx) {
  const { emp, today: shiftDate, clocking } = ctx;

  const allEntries = state.timesheetData.entries || [];
  // After Gate 1 there should be no pending entries, but include them
  // defensively in case proceedWithClockOut is called from somewhere new.
  const pendingEntries = state.currentEntries || [];
  const todayProjectHrs = [
    ...allEntries.filter(e => e.employeeName === emp && e.date === shiftDate && e.projectId !== 'S000' && e.projectId !== 'WGD'),
    ...pendingEntries.filter(e => e.projectId !== 'S000' && e.projectId !== 'WGD')
  ];
  const todayWGDHrs = [
    ...allEntries.filter(e => e.employeeName === emp && e.date === shiftDate && e.projectId === 'WGD'),
    ...pendingEntries.filter(e => e.projectId === 'WGD')
  ];

  // Gate 2: no project hours at all (existing flow).
  if (todayProjectHrs.length === 0 && todayWGDHrs.length === 0) {
    _pendingClockOutData = ctx;
    const modal = document.getElementById('noProjectModal');
    if (modal) {
      modal.classList.add('active');
    } else {
      toast('Error: noProjectModal not found in page', 'error');
    }
    return;
  }

  // Gate 3: remaining unallocated hours. Worker has logged some project /
  // WGD time, but not enough to cover their full clocked shift. Show them
  // the breakdown and force a choice — allocate or accept as unproductive.
  const clockedHrs = calcHours(clocking.clockIn, ctx.clockOut, ctx.breakMins, shiftDate) || 0;
  const allocatedHrs = [...todayProjectHrs, ...todayWGDHrs].reduce((s, e) => s + (parseFloat(e.hours) || 0), 0);
  const remainingHrs = parseFloat((clockedHrs - allocatedHrs).toFixed(2));

  // 0.1h tolerance — sub-6-minute gaps are clock-rounding artefacts, not
  // unaccounted work, and forcing a modal for them would be infuriating.
  if (remainingHrs > 0.1) {
    _pendingClockOutData = ctx;
    openRemainingHoursModal({ clockedHrs, allocatedHrs, remainingHrs, todayProjectHrs, todayWGDHrs });
    return;
  }

  await finishClockOut(ctx);
}

// Finalises a clock-out. NOTE: `today` here is the shift's START date
// (clocking.date), NOT necessarily the current calendar date — they differ
// for overnight shifts. Everything keyed off it (S000 recompute, entry
// filters) treats the whole shift as a single logical day anchored to the
// clock-in date.
async function finishClockOut({ emp, today, clockOut, breakMins, clocking }) {
    const empId = empIdByName(emp);

    // Call API to clock out — include break_mins so it persists to DB (was lost on refresh before)
    const result = await api.post('/api/clock-out', {
      employee_id: empId,
      break_mins: breakMins
    });

    // Update local state
    clocking.clockOut = clockOut;
    clocking.breakMins = breakMins;

    // Server-side S000 recompute. The API is the source of truth for
    // unproductive hours: it reads ClockEntries + ProjectHours directly,
    // recomputes, and inserts/deletes the S000 row atomically.
    let unproductiveHrs = 0;
    if (empId) {
      try {
        const empName = emp;
        const recompute = await api.post('/api/project-hours/recompute-s000', {
          employee_id: empId,
          date: today
        });
        unproductiveHrs = (recompute && recompute.hours) || 0;
        // Drop any local S000 for today and replace with the server's result.
        state.timesheetData.entries = state.timesheetData.entries.filter(
          e => !(e.employeeName === empName && e.date === today && e.projectId === 'S000')
        );
        if (recompute && recompute.entry) {
          state.timesheetData.entries.push(normaliseEntry({
            ...recompute.entry,
            employee_name: empName,
            project_name: 'Unproductive Time'
          }));
        }
      } catch (e) {
        console.warn('S000 recompute failed:', e.message);
      }
    }

    // Update UI immediately
    document.getElementById('clockedInSection').style.display = 'none';
    document.getElementById('clockInSection').style.display = '';
    document.getElementById('statusBar').style.display = 'none';
    clearInterval(workingTimer);
    renderHome();

    if (unproductiveHrs > 0) {
      toast(`Clocked out at ${clockOut} · ${unproductiveHrs}h added as Unproductive Time`, 'success');
    } else {
      toast(`Clocked out at ${clockOut}`, 'success');
    }
}

async function submitDay() {
  await _doSubmitDay({ thenGoHome: true });
}

// Submits state.currentEntries to /api/project-hours and recomputes S000.
// Extracted from submitDay() so the unsubmitted-entries-on-clock-out flow
// can reuse the submit logic without triggering the auto-goHome (which
// would yank the worker out of the panel mid clock-out).
async function _doSubmitDay({ thenGoHome }) {
  if (!state.currentEntries.length) {
    toast('No new entries to submit', 'error');
    throw new Error('no entries');
  }
  // For overnight shifts, file entries against the shift's start date, not
  // the wall-clock date at the moment of submit. activeShiftDate falls back
  // to todayStr() if the worker isn't currently clocked in.
  const today = activeShiftDate(state.currentEmployee);
  const empId = empIdByName(state.currentEmployee);
  if (!empId) {
    toast('Employee not found in system', 'error');
    throw new Error('no employee id');
  }

  // Disable button immediately to prevent double-submission (creates duplicate rows in DB)
  const submitBtn = document.getElementById('submitDayBtn');
  if (submitBtn) { submitBtn.disabled = true; submitBtn.style.opacity = '.5'; submitBtn.style.cursor = 'wait'; }

  try {
    setLoading(true);

    // Submit each entry to the API
    for (const e of state.currentEntries) {
      const result = await api.post('/api/project-hours', {
        employee_id: empId,
        project_number: e.projectId,
        date: today,
        hours: e.hours
      });

      // Add to local state
      state.timesheetData.entries.push(normaliseEntry({
        ...result,
        employee_name: state.currentEmployee,
        project_name: e.projectName
      }));
    }

    state.currentEntries = [];
    clearPendingEntries(state.currentEmployee);

    // After posting entries, recompute today's S000 server-side. This covers
    // the "log entries first, clock out, THEN submit" sequence: the clock-out
    // recompute saw zero project hours (entries were still in currentEntries
    // locally) and logged the full shift as unproductive. Now that the entries
    // exist in the DB, the recompute will subtract them. Endpoint is no-op /
    // self-clearing if the user isn't clocked out yet for today.
    await recomputeS000Local(state.currentEmployee, today);

    renderTodayEntries();
    toast(`Entries submitted ✓`, 'success');
    if (thenGoHome) setTimeout(goHome, 1500);
  } catch (err) {
    console.error('Submit failed:', err);
    toast('Submit failed — ' + err.message, 'error');
    // Re-enable button on error so user can fix and retry
    if (submitBtn) { submitBtn.disabled = false; submitBtn.style.opacity = '1'; submitBtn.style.cursor = 'pointer'; }
    throw err;
  } finally { setLoading(false); }
}

