function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
}

function goHome() {
  clearInterval(workingTimer);
  state.currentEmployee = null;
  // NOTE: do NOT wipe state.currentEntries here. Pending entries are
  // persisted in sessionStorage by savePendingEntries() and will be
  // rehydrated when the worker reopens their panel. submitDay() and the
  // unsubmitted-entries clock-out modal are the only sanctioned places
  // that should clear them.
  state.currentEntries = [];
  if (CURRENT_PAGE === 'manager') {
    currentManagerUser = null;
    _pendingManagerUser = null;
    showScreen('screenManagerSelect');
    renderManagerEmployeeGrid();
  } else if (CURRENT_PAGE === 'office') {
    currentManagerUser = null;
    _pendingManagerUser = null;
    showScreen('screenOfficeSelect');
    renderOfficeEmployeeGrid();
  } else if (CURRENT_PAGE === 'projects') {
    window.location.href = 'index.html';
  } else if (CURRENT_PAGE === 'templates') {
    window.location.href = 'manager.html';
  } else if (CURRENT_PAGE === 'hub') {
    window.location.href = 'hub.html';
  } else {
    showScreen('screenHome');
    renderHome();
  }
}

// ── Kiosk Auto-Refresh ──────────────────────────────────────────────────────
// Silently refreshes kiosk data every 10 minutes so new jobs created by the
// draftsman appear on screen without any user interaction.
// Only runs when the kiosk is idle: no employee panel open, no modal visible.
// ───────────────────────────────────────────────────────────────────────────
function startKioskPolling() {
  if (CURRENT_PAGE !== 'index') return;
  const POLL_INTERVAL = 10 * 60 * 1000; // 10 minutes

  setInterval(async () => {
    // SQL-COST GUARD (2026-08-10): the workshop kiosk browser stays open
    // 24/7, and a query every 10 min stops the Serverless DB from ever
    // auto-pausing (needs ~60 min of silence). Mirror the keep-warm window:
    // only poll 05:00-20:59 Mon-Sat, and only when the tab is visible.
    // Outside the window the kiosk keeps its last-loaded data; any user
    // interaction still triggers its own fresh API calls as normal.
    const now = new Date();
    const hr = now.getHours(), day = now.getDay(); // 0 = Sunday
    if (day === 0 || hr < 5 || hr > 20) return;
    if (document.hidden) return;

    // Bail if an employee panel is open
    if (state.currentEmployee) return;

    // Bail if any modal is currently visible
    const anyModalOpen = Array.from(document.querySelectorAll('.modal')).some(m => {
      const s = window.getComputedStyle(m);
      return s.display !== 'none' && s.visibility !== 'hidden';
    });
    if (anyModalOpen) return;

    console.log('[kiosk-poll] idle — refreshing data');
    try {
      await Promise.all([
        loadTimesheetData(),
        loadProjects(),
        loadDrawingsData()
      ]);
      renderHome();
      checkNewJobAlerts();
      console.log('[kiosk-poll] refresh complete');
    } catch (e) {
      console.warn('[kiosk-poll] refresh failed:', e.message);
    }
  }, POLL_INTERVAL);
}

// ── New Job Alert (kiosk popup) ─────────────────────────────────────────────
// Shows a pulsating red overlay when the draftsman adds new jobs.
// Acknowledgements are persisted in localStorage so dismissed jobs don't
// reappear. On first load, jobs older than 48 h are silently auto-acked so
// a fresh kiosk session doesn't flood with historical jobs.
// ───────────────────────────────────────────────────────────────────────────
const NJA_STORAGE_KEY = 'bama_acked_jobs'; // localStorage: JSON array of "projectId:jobId"
const NJA_NEW_WINDOW_MS = 48 * 60 * 60 * 1000; // 48 hours

function _njaGetAcked() {
  try { return new Set(JSON.parse(localStorage.getItem(NJA_STORAGE_KEY) || '[]')); }
  catch { return new Set(); }
}

function _njaSaveAcked(set) {
  try { localStorage.setItem(NJA_STORAGE_KEY, JSON.stringify([...set])); } catch {}
}

function _njaJobKey(projectId, jobId) { return `${projectId}:${jobId}`; }

// Auto-ack any job older than 48 h that hasn't been acked yet — prevents
// a flood on a fresh browser or after localStorage is cleared.
function _njaAutoAckOld() {
  const acked = _njaGetAcked();
  let changed = false;
  for (const projId of Object.keys(drawingsData.projects || {})) {
    for (const job of (drawingsData.projects[projId].jobs || [])) {
      const key = _njaJobKey(projId, job.id);
      if (!acked.has(key) && (Date.now() - new Date(job.createdAt).getTime()) > NJA_NEW_WINDOW_MS) {
        acked.add(key);
        changed = true;
      }
    }
  }
  if (changed) _njaSaveAcked(acked);
}

// Return array of unacknowledged jobs created within the last 48 h
function _njaGetUnackedJobs() {
  const acked = _njaGetAcked();
  const unacked = [];
  for (const projId of Object.keys(drawingsData.projects || {})) {
    const proj = state.projects?.find(p => p.id === projId);
    const projName = proj ? `${proj.id} — ${proj.name}` : projId;
    for (const job of (drawingsData.projects[projId].jobs || [])) {
      if (job.status === 'closed') continue;
      const key = _njaJobKey(projId, job.id);
      if (acked.has(key)) continue;
      const age = Date.now() - new Date(job.createdAt).getTime();
      if (age > NJA_NEW_WINDOW_MS) continue;
      unacked.push({ projectId: projId, jobId: job.id, jobName: job.name, projName, createdAt: job.createdAt, key });
    }
  }
  unacked.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  return unacked;
}

function checkNewJobAlerts() {
  if (CURRENT_PAGE !== 'index') return;
  _njaAutoAckOld();
  const jobs = _njaGetUnackedJobs();
  if (!jobs.length) return;

  // Don't interrupt an active employee session
  if (state.currentEmployee) return;
  const anyModalOpen = Array.from(document.querySelectorAll('.modal-overlay')).some(m => m.classList.contains('active'));
  if (anyModalOpen) return;

  _njaShowModal(jobs);
}

function _njaShowModal(jobs) {
  const list = document.getElementById('njaJobList');
  const badge = document.getElementById('njaUnreadBadge');
  const btn = document.getElementById('njaSeenAllBtn');
  if (!list) return;

  badge.textContent = `${jobs.length} unread`;
  btn.className = 'nja-seen-all-btn';
  btn.innerHTML = '<span style="font-size:18px">&#10003;</span> Seen all new jobs';

  list.innerHTML = jobs.map((j, i) => {
    const age = timeAgo(j.createdAt);
    return `
      <div class="nja-job-row" id="njaRow${i}" data-key="${j.key}">
        <div class="nja-job-icon">&#9874;</div>
        <div style="flex:1;min-width:0">
          <div style="font-size:13px;font-weight:600;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${j.jobName}</div>
          <div style="font-size:11px;color:var(--muted)">${j.projName} &nbsp;·&nbsp; added ${age}</div>
        </div>
        <button class="nja-seen-btn" onclick="njaAckOne(${i}, '${j.key}')">&#10003; Seen</button>
      </div>`;
  }).join('');

  document.getElementById('newJobAlertModal').classList.add('active');
}

function njaAckOne(i, key) {
  const acked = _njaGetAcked();
  acked.add(key);
  _njaSaveAcked(acked);

  const btn = document.querySelector(`#njaRow${i} .nja-seen-btn`);
  if (btn) { btn.classList.add('acked'); btn.disabled = true; btn.textContent = '✓ Seen'; }

  const remaining = document.querySelectorAll('.nja-seen-btn:not(.acked)').length;
  const badge = document.getElementById('njaUnreadBadge');
  if (remaining === 0) {
    badge.textContent = 'all seen';
    badge.style.background = 'rgba(62,207,142,.15)';
    badge.style.color = 'var(--green)';
    setTimeout(_njaDismiss, 600);
  } else {
    badge.textContent = `${remaining} unread`;
  }
  renderHome(); // refresh notification banner
}

function njaAckAll() {
  const acked = _njaGetAcked();
  document.querySelectorAll('.nja-job-row[data-key]').forEach(row => acked.add(row.dataset.key));
  _njaSaveAcked(acked);

  const btn = document.getElementById('njaSeenAllBtn');
  btn.classList.add('done');
  btn.innerHTML = '<span style="font-size:18px">&#10003;</span> Done — jobs acknowledged';

  const badge = document.getElementById('njaUnreadBadge');
  badge.textContent = 'all seen';
  badge.style.background = 'rgba(62,207,142,.15)';
  badge.style.color = 'var(--green)';

  setTimeout(() => { _njaDismiss(); renderHome(); }, 800);
}

function _njaDismiss() {
  const overlay = document.getElementById('newJobAlertModal');
  const card = document.getElementById('newJobAlertCard');
  if (!overlay || !card) return;
  card.style.transition = 'opacity .35s, transform .35s';
  card.style.opacity = '0';
  card.style.transform = 'scale(.96)';
  setTimeout(() => overlay.classList.remove('active'), 350);
}

function setLoading(on) {
  document.getElementById('loadingBar').style.width = on ? '70%' : '0';
}

let toastTimer;
function toast(msg, type = 'info') {
  const el = document.getElementById('toast');
  el.textContent = msg;
  el.className = `toast show ${type}`;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove('show'), 3000);
}

// ═══════════════════════════════════════════
// bamaConfirm — styled replacement for window.confirm().
//   await bamaConfirm({ title, body, confirmText, cancelText, icon, tone })
//   → resolves true (confirm) / false (cancel). tone: 'primary' | 'danger'.
// Falls back to window.confirm if the modal markup isn't on the page.
// ═══════════════════════════════════════════
let _bamaConfirmResolver = null;
// Lazily inject the styled confirm modal on pages that don't carry the
// markup — NO page should ever fall back to the browser-native
// window.confirm() (BAMA UI rule: all pop-ups use the styled dialogs).
function _ensureBamaConfirmModal() {
  if (document.getElementById('bamaConfirmModal')) return;
  const wrap = document.createElement('div');
  wrap.innerHTML = `
<div class="modal-overlay" id="bamaConfirmModal" style="z-index:9999">
  <div class="modal" style="max-width:420px;width:92vw">
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:10px">
      <span id="bcIcon" style="font-size:26px;line-height:1">&#9989;</span>
      <div class="modal-title" style="margin:0" id="bcTitle">Are you sure?</div>
    </div>
    <div style="color:var(--muted);font-size:14px;line-height:1.5;margin-bottom:22px" id="bcBody"></div>
    <button class="btn btn-primary btn-full" id="bcConfirmBtn" onclick="bamaConfirmResolve(true)" style="padding:13px;font-size:15px">Confirm</button>
    <button class="btn btn-ghost btn-full" onclick="bamaConfirmResolve(false)" style="margin-top:10px;padding:12px">Cancel</button>
  </div>
</div>`;
  while (wrap.firstElementChild) document.body.appendChild(wrap.firstElementChild);
}

function bamaConfirm(opts) {
  opts = opts || {};
  _ensureBamaConfirmModal();
  const modal = document.getElementById('bamaConfirmModal');
  document.getElementById('bcTitle').textContent = opts.title || 'Are you sure?';
  document.getElementById('bcBody').innerHTML = opts.body || '';
  document.getElementById('bcIcon').innerHTML = opts.icon || '&#10068;'; // ❔ default
  const btn = document.getElementById('bcConfirmBtn');
  btn.textContent = opts.confirmText || 'Confirm';
  // Tone: danger → red button, else the standard primary.
  if (opts.tone === 'danger') {
    btn.style.background = 'var(--red, #e5484d)';
    btn.style.borderColor = 'var(--red, #e5484d)';
  } else {
    btn.style.background = '';
    btn.style.borderColor = '';
  }
  modal.classList.add('active');
  return new Promise((resolve) => { _bamaConfirmResolver = resolve; });
}
function bamaConfirmResolve(val) {
  const modal = document.getElementById('bamaConfirmModal');
  if (modal) modal.classList.remove('active');
  const r = _bamaConfirmResolver;
  _bamaConfirmResolver = null;
  if (r) r(val);
}

// ═══════════════════════════════════════════
// HOLIDAY KIOSK (home screen)
// ═══════════════════════════════════════════
let _hkEmployee = null;

function openHolidayKiosk() {
  const modal = document.getElementById('holidayKioskModal');
  modal.classList.add('active');
  renderHKStep1();
}

function closeHolidayKiosk() {
  document.getElementById('holidayKioskModal').classList.remove('active');
  _hkEmployee = null;
}

function renderHKStep1() {
  document.getElementById('hkStep1').style.display = '';
  document.getElementById('hkStep2').style.display = 'none';
  document.getElementById('hkStep3').style.display = 'none';

  const grid = document.getElementById('hkEmpGrid');
  const employees = (state.timesheetData.employees || []).filter(e => e.active !== false);
  grid.innerHTML = employees.map(emp => {
    const col = ['#ff6b00','#e05d00','#c84b00','#a83e00','#ff8c42','#f07030'][emp.name.charCodeAt(0) % 6];
    const ini = emp.name.split(' ').map(n => n[0]).join('').slice(0,2).toUpperCase();
    return `
      <div class="emp-btn" onclick="hkSelectEmp('${emp.name.replace(/'/g,"\'")}')">
        <div class="emp-avatar" style="width:44px;height:44px;font-size:18px;background:linear-gradient(135deg,${col},#3e1a00);margin-bottom:8px">${ini}</div>
        <div class="emp-name" style="font-size:13px">${emp.name}</div>
      </div>
    `;
  }).join('');
}

function hkSelectEmp(name) {
  _hkEmployee = name;
  const emp = (state.timesheetData.employees || []).find(e => e.name === name);
  if (emp && emp.hasPin) {
    document.getElementById('hkStep1').style.display = 'none';
    document.getElementById('hkStep2').style.display = '';
    document.getElementById('hkPinName').textContent = name;
    document.getElementById('hkPinInput').value = '';
    document.getElementById('hkPinError').textContent = '';
    setTimeout(() => document.getElementById('hkPinInput').focus(), 100);
  } else {
    showHKStep3(name);
  }
}

async function checkHKPin() {
  const pin = document.getElementById('hkPinInput').value;
  const emp = (state.timesheetData.employees || []).find(e => e.name === _hkEmployee);
  if (!emp) return;

  let result;
  try {
    result = await api.post('/api/auth/verify-pin', { employee_id: emp.id, pin });
  } catch (err) {
    document.getElementById('hkPinError').textContent = 'Verification failed — try again';
    return;
  }

  if (result && result.valid) {
    showHKStep3(_hkEmployee);
  } else {
    document.getElementById('hkPinError').textContent = (result && result.reason) || 'Incorrect PIN — try again';
    document.getElementById('hkPinInput').value = '';
  }
}

function hkBack() {
  if (document.getElementById('hkStep2').style.display !== 'none') {
    document.getElementById('hkStep2').style.display = 'none';
    document.getElementById('hkStep1').style.display = '';
  } else if (document.getElementById('hkStep3').style.display !== 'none') {
    document.getElementById('hkStep3').style.display = 'none';
    document.getElementById('hkStep1').style.display = '';
    _hkEmployee = null;
  }
}

function showHKStep3(name) {
  document.getElementById('hkStep1').style.display = 'none';
  document.getElementById('hkStep2').style.display = 'none';
  document.getElementById('hkStep3').style.display = '';
  document.getElementById('hkEmpName').textContent = name;

  // Set default dates
  const today = todayStr();
  document.getElementById('hkFromDate').value = today;
  document.getElementById('hkToDate').value = today;
  document.getElementById('hkReason').value = '';

  // Render balance
  const bal = calculateHolidayBalance(name);
  const balEl = document.getElementById('hkBalance');
  if (bal) {
    balEl.innerHTML = `
      <div class="holiday-balance-bar" style="flex-wrap:wrap">
        <div class="hbal-item"><div class="hbal-value" style="color:var(--green)">${bal.remainingDays}</div><div class="hbal-label">Holidays Available</div></div>
        <div class="hbal-item"><div class="hbal-value">${bal.usedDays}</div><div class="hbal-label">Holidays Used</div></div>
        <div class="hbal-item"><div class="hbal-value" style="color:var(--accent2)">${bal.accruedDays}</div><div class="hbal-label">Holidays Accrued</div></div>
        <div class="hbal-item"><div class="hbal-value" style="color:var(--muted)">${bal.totalAllowance}</div><div class="hbal-label">Holiday Allowance</div></div>
      </div>
    `;
  }

  // Render holiday list
  renderHKHolidayList(name);
}

function renderHKHolidayList(name) {
  const el = document.getElementById('hkHolidayList');
  const hols = (state.timesheetData.holidays || [])
    .filter(h => h.employeeName === name)
    .sort((a, b) => b.dateFrom.localeCompare(a.dateFrom));

  if (!hols.length) {
    el.innerHTML = '<div style="color:var(--subtle);font-size:12px;text-align:center;padding:12px">No holiday requests yet</div>';
    return;
  }

  el.innerHTML = `<table class="summary-table" style="font-size:12px">
    <thead><tr><th>DATES</th><th>TYPE</th><th>DAYS</th><th>REASON</th><th>STATUS</th></tr></thead>
    <tbody>
      ${hols.map(h => `
        <tr>
          <td class="mono">${h.dateFrom}${h.dateFrom !== h.dateTo ? ' → '+h.dateTo : ''}</td>
          <td><span class="htype ${h.type}" style="font-size:10px">${h.type}</span></td>
          <td class="mono">${h.workingDays}d</td>
          <td style="color:var(--muted)">${h.reason || '—'}</td>
          <td><span class="tag tag-${h.status === 'approved' ? 'approved' : h.status === 'rejected' ? 'rejected' : 'pending'}" style="font-size:10px">${h.status}</span></td>
        </tr>
      `).join('')}
    </tbody>
  </table>`;
}

async function submitHKHoliday() {
  const from = document.getElementById('hkFromDate').value;
  const to = document.getElementById('hkToDate').value;
  const type = document.getElementById('hkType').value;
  const reason = document.getElementById('hkReason').value;

  if (!from || !to) { toast('Please select dates', 'error'); return; }
  if (from > to) { toast('End date must be after start date', 'error'); return; }

  let workingDays = countWorkingDays(from, to);
  if (type === 'half') workingDays = 0.5; // Half day always counts as 0.5
  if (workingDays === 0) { toast('No working days in selected range', 'error'); return; }

  if (type === 'paid' || type === 'half') {
    const bal = calculateHolidayBalance(_hkEmployee);
    if (bal && workingDays > bal.remainingDays) {
      toast(`Only ${bal.remainingDays} days remaining — request is ${workingDays} days`, 'error');
      return;
    }
  }

  const empId = empIdByName(_hkEmployee);
  if (!empId) { toast('Employee not found', 'error'); return; }

  try {
    const result = await api.post('/api/holidays', {
      employee_id: empId,
      date_from: from,
      date_to: to,
      type,
      reason,
      working_days: workingDays
    });

    const newHoliday = normaliseHoliday({ ...result, employee_name: _hkEmployee });
    if (!state.timesheetData.holidays) state.timesheetData.holidays = [];
    state.timesheetData.holidays.push(newHoliday);

    await sendHolidayNotificationEmail(newHoliday);
    document.getElementById('hkFromDate').value = todayStr();
    document.getElementById('hkToDate').value = todayStr();
    document.getElementById('hkReason').value = '';
    toast(`Holiday request submitted (${workingDays} working days) ✓`, 'success');
    renderHKHolidayList(_hkEmployee);
    showHKStep3(_hkEmployee);
    // If this modal was opened from the employee panel, refresh that view too
    if (state.currentEmployee === _hkEmployee) {
      renderMyHolidays(state.currentEmployee);
      renderEmpHolidayBalance(state.currentEmployee);
    }
  } catch (err) { toast('Submit failed: ' + err.message, 'error'); }
}

// ── Holiday notification on clock-in ──
// Shows a one-time approval/rejection notification for HOLIDAY requests only
// (paid + half-day). Sickness, unpaid leave, and other absence types do NOT
// trigger this popup. The "seen" state is persisted server-side via
// /api/holidays/:id/notification-seen so the user only sees each one once,
// across devices and browsers.
function checkHolidayClockInNotification(employeeName) {
  const unseen = (state.timesheetData.holidays || []).filter(h => {
    if (h.employeeName !== employeeName) return false;
    // Only paid and half-day holidays trigger the notification.
    if (h.type !== 'paid' && h.type !== 'half') return false;
    // Only show for actioned (approved/rejected) requests.
    if (h.status !== 'approved' && h.status !== 'rejected') return false;
    // Skip if already seen by the employee.
    if (h.notificationSeen) return false;
    return true;
  });

  if (!unseen.length) return;

  // Show notification for each unseen holiday
  unseen.forEach(h => {
    const approved = h.status === 'approved';
    const color = approved ? 'var(--green)' : 'var(--red)';

    // Show a full-screen notification overlay
    const overlay = document.createElement('div');
    overlay.style.cssText = `position:fixed;inset:0;background:rgba(0,0,0,.85);z-index:500;display:flex;align-items:center;justify-content:center;`;
    overlay.innerHTML = `
      <div style="background:var(--card);border:2px solid ${color};border-radius:16px;padding:40px;text-align:center;max-width:400px;margin:20px">
        <div style="font-size:48px;margin-bottom:16px">${approved ? '✅' : '❌'}</div>
        <div style="font-family:var(--font-display);font-size:28px;color:${color};margin-bottom:12px">
          HOLIDAY ${approved ? 'APPROVED' : 'DECLINED'}
        </div>
        <div style="color:var(--muted);font-size:14px;margin-bottom:8px">${h.dateFrom}${h.dateFrom !== h.dateTo ? ' → ' + h.dateTo : ''}</div>
        <div style="color:var(--text);font-size:16px;margin-bottom:24px">${h.workingDays} working days · ${h.type}</div>
        <button class="btn btn-primary" style="width:100%" data-holiday-id="${h.id}">OK</button>
      </div>
    `;
    document.body.appendChild(overlay);

    // Mark seen on dismiss — patch local state immediately so the popup
    // never re-appears in this session even if the API call fails, then
    // persist server-side so it survives logout/refresh.
    const okBtn = overlay.querySelector('button[data-holiday-id]');
    okBtn.addEventListener('click', async () => {
      h.notificationSeen = true;
      overlay.remove();
      try {
        await api.put(`/api/holidays/${h.id}/notification-seen`, {});
      } catch (err) {
        // Non-fatal: notification will reappear next login if persistence failed.
        console.warn('Failed to persist holiday notification seen flag:', err);
      }
    });
  });
}

let _editEntryId = null;

function openEditEntry(id) {
  const entry = state.timesheetData.entries.find(e => String(e.id) === String(id));
  if (!entry) return;
  _editEntryId = id;
  document.getElementById('editEntryProject').textContent = `${entry.projectId} — ${entry.projectName}`;
  document.getElementById('editEntryHours').value = entry.hours;
  document.getElementById('editEntryReason').value = '';
  document.getElementById('editEntryModal').classList.add('active');
}

function closeEditEntry() {
  document.getElementById('editEntryModal').classList.remove('active');
  _editEntryId = null;
}

async function saveEditEntry() {
  if (!_editEntryId) return;
  const entry = state.timesheetData.entries.find(e => String(e.id) === String(_editEntryId));
  if (!entry) return;

  const newHours = parseFloat(document.getElementById('editEntryHours').value);
  const reason = document.getElementById('editEntryReason').value.trim();
  if (!newHours || newHours <= 0) { toast('Please enter valid hours', 'error'); return; }
  if (!reason) { toast('Please provide a reason for the change', 'error'); document.getElementById('editEntryReason').focus(); return; }

  try {
    await api.put(`/api/project-hours/${_editEntryId}`, {
      hours: newHours,
      edit_reason: reason,
      edited_by: state.currentEmployee
      // is_approved kept as-is — project hours no longer require approval
    });

    entry.originalHours = entry.originalHours || entry.hours;
    entry.hours = newHours;
    entry.manuallyEdited = true;
    entry.editReason = reason;
    entry.editedAt = new Date().toISOString();

    // Recalculate S000 for this day if clocked
    const today = entry.date;
    const emp = entry.employeeName;
    const clocking = state.timesheetData.clockings.find(
      c => c.employeeName === emp && c.date === today && c.clockOut
    );
    if (clocking) {
      await recomputeS000Local(emp, today);
    }

    closeEditEntry();
    renderMyWeek(state.currentEmployee);
    toast('Hours updated ✓', 'success');
  } catch (err) { toast('Save failed: ' + err.message, 'error'); }
}

// ── Workshop General Duties / No Project Hours ──
let _pendingClockOutData = null;

function toggleWGDOption() {
  const box = document.getElementById('wgdOptionBox');
  const check = document.getElementById('wgdCheckbox');
  const btn = document.getElementById('noProjectClockOutBtn');
  const isChecked = check.textContent === '✓';

  if (isChecked) {
    check.textContent = '';
    check.style.background = 'var(--card)';
    check.style.borderColor = 'var(--border)';
    box.style.borderColor = 'var(--border)';
    box.style.background = 'var(--surface)';
    btn.disabled = true;
    btn.style.opacity = '.4';
    btn.style.cursor = 'not-allowed';
  } else {
    check.textContent = '✓';
    check.style.background = 'var(--green)';
    check.style.borderColor = 'var(--green)';
    check.style.color = '#fff';
    box.style.borderColor = 'var(--green)';
    box.style.background = 'rgba(62,207,142,.06)';
    btn.disabled = false;
    btn.style.opacity = '1';
    btn.style.cursor = 'pointer';
  }
}

function closeNoProjectModal() {
  document.getElementById('noProjectModal').classList.remove('active');
  _pendingClockOutData = null;
  // Reset checkbox
  const check = document.getElementById('wgdCheckbox');
  const box = document.getElementById('wgdOptionBox');
  const btn = document.getElementById('noProjectClockOutBtn');
  check.textContent = '';
  check.style.background = 'var(--card)';
  check.style.borderColor = 'var(--border)';
  box.style.borderColor = 'var(--border)';
  box.style.background = 'var(--surface)';
  btn.disabled = true;
  btn.style.opacity = '.4';
  btn.style.cursor = 'not-allowed';
}

async function confirmNoProjectClockOut() {
  if (!_pendingClockOutData) return;
  // Snapshot the data — closeNoProjectModal() below clears _pendingClockOutData,
  // and finishClockOut still needs it.
  const data = _pendingClockOutData;
  const { emp, today, clockOut, breakMins, clocking } = data;

  // Log full shift as WGD
  const clockedHrs = calcHours(clocking.clockIn, clockOut, breakMins, today) || 0;
  if (clockedHrs > 0) {
    const empId = empIdByName(emp);
    if (empId) {
      try {
        const result = await api.post('/api/project-hours', {
          employee_id: empId,
          project_number: 'WGD',
          date: today,
          hours: clockedHrs
        });
        state.timesheetData.entries.push(normaliseEntry({
          ...result,
          employee_name: emp,
          project_name: 'Workshop General Duties'
        }));
      } catch (e) {
        // ABORT: if WGD fails to save, do NOT proceed to clock-out — that would
        // log the entire shift as S000 (Unproductive Time) which is wrong.
        console.error('WGD entry save failed:', e.message);
        toast('Could not save Workshop General Duties — please try again', 'error');
        return;  // user stays on the modal, can retry
      }
    }
  }

  closeNoProjectModal();
  // Proceed with clock-out (use the snapshot — closeNoProjectModal nulled the global)
  await finishClockOut(data);
}

// ── Unsubmitted entries modal (clock-out Gate 1) ──
//
// Opens when the worker hits Clock Out while state.currentEntries still has
// rows that haven't been Submit Day'd. Three exits:
//   • Submit & Clock Out  — POST entries, then continue clock-out flow
//   • Discard & Clock Out — drop pending entries, continue clock-out flow
//   • Cancel              — back to the panel, stay clocked in
function openUnsubmittedEntriesModal() {
  const modal = document.getElementById('unsubmittedEntriesModal');
  const list = document.getElementById('unsubmittedEntriesList');
  if (!modal || !list) {
    toast('Error: unsubmittedEntriesModal not found in page', 'error');
    return;
  }

  // Render the pending rows so the worker can see exactly what they'd submit
  // or discard.
  const pending = state.currentEntries || [];
  if (!pending.length) {
    list.innerHTML = '<div style="color:var(--muted);padding:8px">No pending entries.</div>';
  } else {
    const totalH = pending.reduce((s, e) => s + (parseFloat(e.hours) || 0), 0);
    list.innerHTML = pending.map(e => `
      <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--border)">
        <span><span style="font-family:var(--font-mono);color:var(--accent2)">${escapeHtml(e.projectId)}</span> <span style="color:var(--muted)">${escapeHtml(e.projectName || '')}</span></span>
        <span style="font-weight:600">${e.hours}h</span>
      </div>
    `).join('') + `
      <div style="display:flex;justify-content:space-between;padding:8px 0 0;font-weight:700">
        <span>Total pending</span><span>${totalH.toFixed(2)}h</span>
      </div>`;
  }

  modal.classList.add('active');
}

function closeUnsubmittedEntriesModal() {
  const modal = document.getElementById('unsubmittedEntriesModal');
  if (modal) modal.classList.remove('active');
  _pendingClockOutData = null;
}

async function confirmSubmitAndClockOut() {
  const ctx = _pendingClockOutData;
  if (!ctx) return;
  // Close the modal first so the user sees forward motion. submitDay() shows
  // its own toast on success/failure.
  const modal = document.getElementById('unsubmittedEntriesModal');
  if (modal) modal.classList.remove('active');

  try {
    await _doSubmitDay({ thenGoHome: false });
  } catch (e) {
    console.error('submit-and-clockout: submitDay failed', e);
    toast('Submit failed — clock-out cancelled. Please try again.', 'error');
    _pendingClockOutData = null;
    return;
  }

  // submitDay completed; entries are in SQL and S000 has been recomputed.
  // Continue through the remaining clock-out gates.
  await proceedWithClockOut(ctx);
  _pendingClockOutData = null;
}

async function confirmDiscardAndClockOut() {
  const ctx = _pendingClockOutData;
  if (!ctx) return;
  if (!(await bamaConfirm({ title: 'Discard pending entries?', body: 'They will not be saved and the time will be logged as Unproductive.', confirmText: 'Discard', tone: 'danger' }))) {
    return;
  }
  clearPendingEntries(state.currentEmployee);
  renderTodayEntries();
  const modal = document.getElementById('unsubmittedEntriesModal');
  if (modal) modal.classList.remove('active');
  await proceedWithClockOut(ctx);
  _pendingClockOutData = null;
}

// ── Remaining hours modal (clock-out Gate 3) ──
//
// Opens after Gate 1+2 have passed when the worker has logged some, but not
// all, of their clocked time to projects/WGD. Two exits:
//   • Allocate Remaining   — close modal, return to panel with hours prefilled
//   • Mark as Unproductive — proceed to finishClockOut; server-side S000
//                            recompute then logs the gap as S000.
//
// No "skip" path — force allocate or accept (per user's choice).
function openRemainingHoursModal({ clockedHrs, allocatedHrs, remainingHrs, todayProjectHrs, todayWGDHrs }) {
  const modal = document.getElementById('remainingHoursModal');
  if (!modal) {
    toast('Error: remainingHoursModal not found in page', 'error');
    return;
  }

  // Numbers
  const fmt = n => (Math.round(n * 100) / 100).toFixed(2).replace(/\.00$/, '').replace(/(\.\d)0$/, '$1') + 'h';
  const set = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
  set('rhWorked', fmt(clockedHrs));
  set('rhAllocated', fmt(allocatedHrs));
  set('rhRemaining', fmt(remainingHrs));

  // Per-project breakdown (group P-* and WGD by project_number, sum hours).
  const byProject = {};
  [...todayProjectHrs, ...todayWGDHrs].forEach(e => {
    const k = e.projectId;
    if (!byProject[k]) byProject[k] = { name: e.projectName || k, hours: 0 };
    byProject[k].hours += parseFloat(e.hours) || 0;
  });
  const rows = Object.entries(byProject)
    .sort((a, b) => b[1].hours - a[1].hours)
    .map(([id, v]) => `
      <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--border)">
        <span><span style="font-family:var(--font-mono);color:var(--accent2)">${escapeHtml(id)}</span> <span style="color:var(--muted)">${escapeHtml(v.name)}</span></span>
        <span style="font-weight:600">${fmt(v.hours)}</span>
      </div>`);
  const breakdownEl = document.getElementById('rhBreakdown');
  if (breakdownEl) {
    breakdownEl.innerHTML = rows.length
      ? rows.join('')
      : '<div style="color:var(--muted);padding:8px">No allocations yet.</div>';
  }

  // Update the "accept" button label with the actual hour amount
  const btn = document.getElementById('rhAcceptUnproductiveBtn');
  if (btn) btn.textContent = `Mark ${fmt(remainingHrs)} as Unproductive & Clock Out`;

  // Stash for the prefill in rhAllocateNow
  _rhRemainingPrefill = remainingHrs;

  modal.classList.add('active');
}

function closeRemainingHoursModal() {
  const modal = document.getElementById('remainingHoursModal');
  if (modal) modal.classList.remove('active');
}

let _rhRemainingPrefill = 0;

function rhAllocateNow() {
  // Just close — don't drop _pendingClockOutData yet; the worker may come
  // back and click Clock Out again, and we want a clean re-entry through
  // the gates rather than resuming mid-flow.
  closeRemainingHoursModal();
  _pendingClockOutData = null;

  // Prefill the hours input so the worker just has to pick a project.
  const hoursInput = document.getElementById('hoursInput');
  if (hoursInput) {
    hoursInput.value = (_rhRemainingPrefill > 0)
      ? (Math.round(_rhRemainingPrefill * 100) / 100).toString()
      : '';
  }
  // Focus the project picker so they can act immediately.
  const projSel = document.getElementById('projectSelect');
  if (projSel && typeof projSel.focus === 'function') {
    setTimeout(() => projSel.focus(), 100);
  }
}

async function rhAcceptUnproductive() {
  const ctx = _pendingClockOutData;
  if (!ctx) return;
  closeRemainingHoursModal();
  // The server-side S000 recompute inside finishClockOut() reads SQL and
  // computes (clocked - sum of project_hours) as unproductive. No client-side
  // action needed beyond proceeding.
  await finishClockOut(ctx);
  _pendingClockOutData = null;
}

