function renderHolidayCalendar() {
  const wrap = document.getElementById('holidayGanttWrap');
  const rangeLabel = document.getElementById('ganttRangeLabel');
  if (!wrap) return;

  const empFilter = document.getElementById('holidayEmpFilter')?.value || '';
  const employees = (state.timesheetData.employees || [])
    .filter(e => e.active !== false && (!empFilter || e.name === empFilter));

  // Build 3-month date range starting from holidayMonthOffset
  const now = new Date();
  const startMonth = new Date(now.getFullYear(), now.getMonth() + holidayMonthOffset, 1);
  const months = [];
  for (let m = 0; m < 3; m++) {
    const mo = new Date(startMonth.getFullYear(), startMonth.getMonth() + m, 1);
    months.push(mo);
  }

  const endMonth = new Date(months[2].getFullYear(), months[2].getMonth() + 1, 0);

  if (rangeLabel) {
    rangeLabel.textContent = `${startMonth.toLocaleDateString('en-GB',{month:'short',year:'numeric'})} – ${endMonth.toLocaleDateString('en-GB',{month:'short',year:'numeric'})}`;
  }

  // Build all days in the range
  const allDays = [];
  const cur = new Date(startMonth);
  while (cur <= endMonth) {
    allDays.push(dateStr(cur));
    cur.setDate(cur.getDate() + 1);
  }

  // Cell width
  const cellW = 22;
  const labelW = 130;
  const totalW = labelW + allDays.length * cellW;

  // Build HTML
  let ganttHtml = `<div style="min-width:${totalW}px;width:${totalW}px;font-size:11px;font-family:var(--font-mono);display:block">`;

  // Month headers (sticky name placeholder so header aligns with sticky name column)
  ganttHtml += `<div style="display:flex;margin-bottom:2px">`;
  ganttHtml += `<div style="width:${labelW}px;min-width:${labelW}px;position:sticky;left:0;z-index:3;background:var(--card)"></div>`;
  months.forEach(mo => {
    const daysInMo = new Date(mo.getFullYear(), mo.getMonth() + 1, 0).getDate();
    ganttHtml += `<div style="width:${daysInMo * cellW}px;text-align:center;font-size:11px;font-weight:600;color:var(--text);letter-spacing:.5px;border-left:1px solid var(--border);padding:2px 0">
      ${mo.toLocaleDateString('en-GB',{month:'short',year:'numeric'})}
    </div>`;
  });
  ganttHtml += '</div>';

  // Day number header (sticky placeholder)
  ganttHtml += `<div style="display:flex;margin-bottom:4px">`;
  ganttHtml += `<div style="width:${labelW}px;min-width:${labelW}px;position:sticky;left:0;z-index:3;background:var(--card)"></div>`;
  allDays.forEach(ds => {
    const d = new Date(ds + 'T12:00:00');
    const isWE = isWeekend(ds);
    const isBH = isBankHoliday(ds);
    const isToday = ds === todayStr();
    ganttHtml += `<div style="width:${cellW}px;text-align:center;font-size:9px;
      color:${isToday ? 'var(--accent)' : isWE || isBH ? 'var(--subtle)' : 'var(--muted)'};
      font-weight:${isToday ? '700' : '400'}">
      ${d.getDate()}
    </div>`;
  });
  ganttHtml += '</div>';

  // Employee rows
  employees.forEach(emp => {
    ganttHtml += `<div style="display:flex;align-items:center;margin-bottom:3px">`;
    ganttHtml += `<div style="width:${labelW}px;min-width:${labelW}px;padding-right:10px;font-weight:600;font-size:12px;
      color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-family:var(--font-body);
      position:sticky;left:0;z-index:2;background:var(--card)">
      ${emp.name}
    </div>`;

    allDays.forEach(ds => {
      const isWE = isWeekend(ds);
      const isBH = isBankHoliday(ds);
      const isToday = ds === todayStr();

      const hol = (state.timesheetData.holidays || []).find(h =>
        h.employeeName === emp.name && h.dateFrom <= ds && h.dateTo >= ds
      );

      let bg = 'transparent';
      let title = '';
      let border = '1px solid transparent';

      if (isBH) {
        bg = 'rgba(96,165,250,.3)';
        title = 'Bank Holiday';
      } else if (isWE) {
        bg = 'rgba(100,100,100,.15)';
      } else if (hol) {
        if (hol.status === 'pending') {
          bg = 'rgba(236,72,153,.4)';
          title = 'Pending approval';
          border = '1px solid rgba(236,72,153,.6)';
        } else if (hol.status === 'approved') {
          if (hol.type === 'sick') {
            bg = 'rgba(239,68,68,.45)';
            title = 'Sick (approved)';
          } else if (hol.type === 'unpaid') {
            bg = 'rgba(255,159,67,.45)';
            title = 'Unpaid absence (approved)';
          } else {
            bg = 'rgba(62,207,142,.5)';
            title = `${hol.type === 'half' ? 'Half day' : 'Paid'} holiday (approved)`;
          }
        }
      }

      if (isToday) border = '1px solid var(--accent)';

      ganttHtml += `<div style="width:${cellW}px;height:22px;background:${bg};border:${border};
        border-radius:2px;cursor:default" title="${title}"></div>`;
    });

    ganttHtml += '</div>';
  });

  ganttHtml += '</div>';
  wrap.innerHTML = ganttHtml;
}

function changeHolidayMonth(dir) {
  holidayMonthOffset += dir;
  renderHolidayCalendar();
}

function renderHolidayRequests() {
  const container = document.getElementById('holidayRequestsList');
  if (!container) return;
  const empFilter = document.getElementById('holidayEmpFilter')?.value || '';

  let holidays = (state.timesheetData.holidays || [])
    .filter(h => !empFilter || h.employeeName === empFilter)
    .sort((a, b) => b.submittedAt.localeCompare(a.submittedAt));

  if (!holidays.length) {
    container.innerHTML = '<div class="empty-state" style="padding:24px">No holiday requests yet</div>';
    return;
  }

  const pending = holidays.filter(h => h.status === 'pending');
  const others = holidays.filter(h => h.status !== 'pending');

  const renderGroup = (list, title) => list.length ? `
    <div class="section-label" style="margin-bottom:10px;margin-top:${title === 'Pending Approval' ? '0' : '20px'}">${title}</div>
    ${list.map(h => {
      const isOwnRequest = currentManagerUser && h.employeeName === currentManagerUser;
      const loggedInEmp = (state.timesheetData.employees || []).find(e => e.name === currentManagerUser);
      const isDirector = loggedInEmp && loggedInEmp.erpRole === 'director';
      const canApprove = h.status === 'pending' && (!isOwnRequest || isDirector);
      const showEdit = canEditHolidays();
      return `
      <div class="holiday-chip" style="flex-wrap:wrap;gap:8px">
        <span style="font-weight:600;min-width:120px">${h.employeeName}</span>
        <span class="hdate">${fmtDateStr(h.dateFrom)} → ${fmtDateStr(h.dateTo)}</span>
        <span class="htype ${h.type}">${h.type === 'paid' ? 'Paid' : h.type === 'unpaid' ? 'Unpaid Absence' : h.type === 'sick' ? 'Sick' : h.type === 'half' ? 'Half Day' : h.type}</span>
        <span style="font-family:var(--font-mono);font-size:12px;color:var(--accent2)">${h.workingDays}d</span>
        <span style="color:var(--muted);font-size:12px;flex:1">${h.reason || ''}</span>
        <span class="tag tag-${h.status === 'approved' ? 'approved' : h.status === 'rejected' ? 'rejected' : 'pending'}">${h.status}</span>
        ${showEdit ? `<button class="tiny-btn" onclick="openEditHolidayModal('${h.id}')" style="padding:2px 8px;font-size:11px;background:var(--surface2);color:var(--muted);border:1px solid var(--border)" title="Edit">✏️</button>` : ''}
        ${canApprove ? `
          <div class="approve-row">
            <button class="tiny-btn tiny-approve" onclick="approveHoliday('${h.id}')">&#10003; Approve</button>
            <button class="tiny-btn tiny-reject" onclick="rejectHoliday('${h.id}')">&#10005; Reject</button>
          </div>
        ` : (h.status === 'pending' && isOwnRequest ? '<span style="font-size:11px;color:var(--subtle);font-style:italic">Awaiting approval from another user</span>' : '')}
      </div>
    `}).join('')}
  ` : '';

  container.innerHTML = renderGroup(pending, 'Pending Approval') + renderGroup(others, 'Previous Requests');
}

async function approveHoliday(id) {
  const h = (state.timesheetData.holidays || []).find(h => String(h.id) === String(id));
  if (!h) return;
  try {
    await api.put(`/api/holidays/${id}`, { status: 'approved' });
    h.status = 'approved';
    h.approvedAt = new Date().toISOString();
    toast(`Holiday approved for ${h.employeeName} ✓`, 'success');
    renderHolidayTab();
    renderHolidayNotificationBanner();
  } catch (err) { toast('Save failed: ' + err.message, 'error'); }
}

async function rejectHoliday(id) {
  const h = (state.timesheetData.holidays || []).find(h => String(h.id) === String(id));
  if (!h) return;
  try {
    await api.put(`/api/holidays/${id}`, { status: 'rejected' });
    h.status = 'rejected';
    h.rejectedAt = new Date().toISOString();
    toast(`Holiday rejected`, 'success');
    renderHolidayTab();
  } catch (err) { toast('Save failed: ' + err.message, 'error'); }
}

// ═══════════════════════════════════════════
// BOOK ABSENCE — Manager books on behalf of employee
// ═══════════════════════════════════════════
function canBookAbsences() {
  // Check if current user has permission to book absences for others
  const allowedRoles = ['director', 'finance', 'office_admin'];
  const currentEmp = (state.timesheetData.employees || []).find(e => e.name === currentManagerUser);
  if (!currentEmp) return false;

  // Check ERP role
  if (allowedRoles.includes(currentEmp.erpRole)) return true;

  // Check custom permission in settings
  const permitted = state.timesheetData.settings?.absenceBookingPermissions || [];
  if (permitted.includes(currentEmp.name) || permitted.includes(String(currentEmp.id))) return true;

  return false;
}

function openBookAbsenceModal() {
  if (!canBookAbsences()) {
    toast('You don\'t have permission to book absences. Contact a Director or Finance user.', 'error');
    return;
  }

  const sel = document.getElementById('absEmpSelect');
  sel.innerHTML = '<option value="">— Select employee —</option>';
  (state.timesheetData.employees || [])
    .filter(e => e.active !== false)
    .sort((a, b) => a.name.localeCompare(b.name))
    .forEach(e => {
      sel.innerHTML += `<option value="${e.id}">${e.name}</option>`;
    });

  // Set default dates to today
  const today = todayStr();
  document.getElementById('absFromDate').value = today;
  document.getElementById('absToDate').value = today;
  document.getElementById('absType').value = 'paid';
  document.getElementById('absStatus').value = 'approved';
  document.getElementById('absReason').value = '';
  document.getElementById('absBalanceInfo').textContent = '';
  document.getElementById('absDaysInfo').textContent = '';

  document.getElementById('bookAbsenceModal').classList.add('active');
}

function closeBookAbsenceModal() {
  document.getElementById('bookAbsenceModal').classList.remove('active');
}

function updateAbsenceBalance() {
  const empId = document.getElementById('absEmpSelect').value;
  const balEl = document.getElementById('absBalanceInfo');
  if (!empId) { balEl.textContent = ''; return; }

  const emp = (state.timesheetData.employees || []).find(e => String(e.id) === String(empId));
  if (!emp) { balEl.textContent = ''; return; }

  const bal = calculateHolidayBalance(emp.name);
  if (bal) {
    balEl.innerHTML = `<span style="color:var(--green)">${bal.remainingDays} days remaining</span> of ${bal.totalAllowance} · ${bal.usedDays} used${bal.pendingDays > 0 ? ` · <span style="color:var(--amber)">${bal.pendingDays} pending</span>` : ''}`;
  } else {
    balEl.textContent = '';
  }
  updateAbsenceDays();
}

// Sync "to" date: if empty or before the new "from", set it to match "from"
function syncToDate(fromId, toId) {
  const from = document.getElementById(fromId)?.value;
  const to = document.getElementById(toId)?.value;
  if (from && (!to || to < from)) {
    document.getElementById(toId).value = from;
  }
}

function updateAbsenceDays() {
  const from = document.getElementById('absFromDate').value;
  const to = document.getElementById('absToDate').value;
  const type = document.getElementById('absType').value;
  const infoEl = document.getElementById('absDaysInfo');

  if (!from || !to) { infoEl.textContent = ''; return; }

  let days = type === 'half' ? 0.5 : countWorkingDays(from, to);
  if (days === 0 && type !== 'half') {
    infoEl.innerHTML = '<span style="color:var(--red)">No working days in selected range</span>';
    return;
  }

  infoEl.textContent = `${days} working day${days !== 1 ? 's' : ''}`;
}

async function submitBookAbsence() {
  const empId = document.getElementById('absEmpSelect').value;
  const from = document.getElementById('absFromDate').value;
  const to = document.getElementById('absToDate').value;
  const type = document.getElementById('absType').value;
  const status = document.getElementById('absStatus').value;
  const reason = document.getElementById('absReason').value;

  if (!empId) { toast('Please select an employee', 'error'); return; }
  if (!from || !to) { toast('Please select dates', 'error'); return; }
  if (from > to) { toast('End date must be after start date', 'error'); return; }

  let workingDays = type === 'half' ? 0.5 : countWorkingDays(from, to);
  if (workingDays === 0) { toast('No working days in selected range', 'error'); return; }

  const emp = (state.timesheetData.employees || []).find(e => String(e.id) === String(empId));
  const empName = emp ? emp.name : `Employee #${empId}`;

  // Balance check for paid holidays
  if ((type === 'paid' || type === 'half') && status === 'approved' && emp) {
    const bal = calculateHolidayBalance(emp.name);
    if (bal && workingDays > bal.remainingDays) {
      if (!(await bamaConfirm({ title: 'Insufficient balance', body: `${emp.name} only has ${bal.remainingDays} days remaining but this is ${workingDays} days. Book anyway?`, confirmText: 'Book anyway', tone: 'warn' }))) return;
    }
  }

  try {
    const result = await api.post('/api/holidays', {
      employee_id: parseInt(empId),
      date_from: from,
      date_to: to,
      type,
      reason: reason || `Booked by ${currentManagerUser || 'manager'}`,
      working_days: workingDays
    });

    const newHoliday = normaliseHoliday({ ...result, employee_name: empName });

    // If status should be approved, approve it immediately
    if (status === 'approved' && newHoliday.status === 'pending') {
      try {
        await api.put(`/api/holidays/${newHoliday.id}`, { status: 'approved' });
        newHoliday.status = 'approved';
        newHoliday.approvedAt = new Date().toISOString();
      } catch (e) {
        console.warn('Auto-approve failed:', e.message);
      }
    }

    if (!state.timesheetData.holidays) state.timesheetData.holidays = [];
    state.timesheetData.holidays.push(newHoliday);

    closeBookAbsenceModal();
    const typeLabel = { paid:'Holiday', unpaid:'Unpaid Absence', sick:'Sick Leave', half:'Half Day', compassionate:'Compassionate Leave', training:'Training' }[type] || type;
    toast(`${typeLabel} booked for ${empName} (${workingDays}d) ${status === 'approved' ? '✓' : '— pending approval'}`, 'success');
    renderHolidayTab();
  } catch (err) {
    toast('Failed to book absence: ' + err.message, 'error');
  }
}

// ═══════════════════════════════════════════
// EDIT HOLIDAY — Directors / Finance / Office Admin
// ═══════════════════════════════════════════
function canEditHolidays() {
  const allowedRoles = ['director', 'finance', 'office_admin'];
  const currentEmp = (state.timesheetData.employees || []).find(e => e.name === currentManagerUser);
  if (!currentEmp) return false;
  if (allowedRoles.includes(currentEmp.erpRole)) return true;
  return false;
}

function openEditHolidayModal(id) {
  if (!canEditHolidays()) {
    toast('You don\'t have permission to edit holidays. Contact a Director or Finance user.', 'error');
    return;
  }
  const h = (state.timesheetData.holidays || []).find(h => String(h.id) === String(id));
  if (!h) { toast('Holiday record not found', 'error'); return; }

  document.getElementById('editHolId').value = h.id;
  document.getElementById('editHolEmployee').value = h.employeeName || '';
  document.getElementById('editHolFrom').value = h.dateFrom || '';
  document.getElementById('editHolTo').value = h.dateTo || '';
  document.getElementById('editHolType').value = h.type || 'paid';
  document.getElementById('editHolStatus').value = h.status || 'pending';
  document.getElementById('editHolReason').value = h.reason || '';
  updateEditHolidayDays();
  document.getElementById('editHolidayModal').classList.add('active');
}

function closeEditHolidayModal() {
  document.getElementById('editHolidayModal').classList.remove('active');
}

function updateEditHolidayDays() {
  const from = document.getElementById('editHolFrom').value;
  const to = document.getElementById('editHolTo').value;
  const type = document.getElementById('editHolType').value;
  const infoEl = document.getElementById('editHolDaysInfo');
  if (!from || !to) { infoEl.textContent = ''; return; }
  let days = type === 'half' ? 0.5 : countWorkingDays(from, to);
  if (days === 0 && type !== 'half') {
    infoEl.innerHTML = '<span style="color:var(--red)">No working days in selected range</span>';
    return;
  }
  infoEl.textContent = `${days} working day${days !== 1 ? 's' : ''}`;
}

async function submitEditHoliday() {
  const id = document.getElementById('editHolId').value;
  const from = document.getElementById('editHolFrom').value;
  const to = document.getElementById('editHolTo').value;
  const type = document.getElementById('editHolType').value;
  const status = document.getElementById('editHolStatus').value;
  const reason = document.getElementById('editHolReason').value;

  if (!from || !to) { toast('Please select dates', 'error'); return; }
  if (from > to) { toast('End date must be after start date', 'error'); return; }

  let workingDays = type === 'half' ? 0.5 : countWorkingDays(from, to);
  if (workingDays === 0 && type !== 'half') { toast('No working days in selected range', 'error'); return; }

  try {
    await api.put(`/api/holidays/${id}`, {
      date_from: from,
      date_to: to,
      type,
      status,
      reason,
      working_days: workingDays
    });

    // Update local state
    const h = (state.timesheetData.holidays || []).find(h => String(h.id) === String(id));
    if (h) {
      h.dateFrom = from;
      h.dateTo = to;
      h.type = type;
      h.status = status;
      h.reason = reason;
      h.workingDays = workingDays;
    }

    closeEditHolidayModal();
    toast('Holiday updated ✓', 'success');
    renderHolidayTab();
    renderHolidayNotificationBanner();
  } catch (err) {
    toast('Failed to update: ' + err.message, 'error');
  }
}

async function deleteHolidayFromEdit() {
  const id = document.getElementById('editHolId').value;
  const h = (state.timesheetData.holidays || []).find(h => String(h.id) === String(id));
  if (!h) return;

  const label = `${h.employeeName} — ${h.type} (${fmtDateStr(h.dateFrom)} → ${fmtDateStr(h.dateTo)})`;
  if (!(await bamaConfirm({ title: 'Delete record', body: `${label}<br><br>If this was an approved paid holiday, the balance will be restored.`, confirmText: 'Delete', tone: 'danger' }))) return;

  try {
    const result = await api.delete(`/api/holidays/${id}`);
    state.timesheetData.holidays = (state.timesheetData.holidays || []).filter(h => String(h.id) !== String(id));
    closeEditHolidayModal();
    const restored = result?.restored_days;
    toast(`Holiday deleted${restored ? ` — ${restored} day${restored !== 1 ? 's' : ''} restored` : ''} ✓`, 'success');
    renderHolidayTab();
    renderHolidayNotificationBanner();
  } catch (err) {
    toast('Failed to delete: ' + err.message, 'error');
  }
}

function checkHolidayNotifications() {
  // Remove any existing banner first
  const existingBanner = document.getElementById('holidayPendingBanner');
  if (existingBanner) existingBanner.remove();

  const pending = (state.timesheetData.holidays || []).filter(h => h.status === 'pending');
  if (!pending.length) return;

  const banner = document.createElement('div');
  banner.id = 'holidayPendingBanner';
  banner.className = 'notification-banner';
  banner.style.marginBottom = '16px';
  banner.innerHTML = `
    <span class="nb-icon">&#127959;</span>
    <span class="nb-text"><b>${pending.length} holiday request${pending.length > 1 ? 's' : ''}</b> awaiting your approval</span>
    <span class="nb-count">${pending.length}</span>
  `;
  banner.onclick = () => switchTab('holidays');
  const statsRow = document.getElementById('mgrStats');
  if (statsRow && statsRow.parentNode) {
    statsRow.parentNode.insertBefore(banner, statsRow);
  }
}

// ═══════════════════════════════════════════
// PAYROLL ENGINE
// ═══════════════════════════════════════════
let payrollWeekOffset = 0;

// How many holiday hours does this employee have on this date?
//   8 → approved 'paid' holiday covering this date
//   4 → approved 'half' holiday on this date
//   0 → otherwise
// Skips weekends and bank holidays (matches `working_days` at booking time).
function getHolidayHoursForEmployee(empName, ds) {
  const d = new Date(ds + 'T12:00:00');
  const dow = d.getDay();
  if (dow === 0 || dow === 6) return 0;
  if (isBankHoliday(ds)) return 0;

  const matches = (state.timesheetData.holidays || []).filter(h =>
    h.employeeName === empName &&
    h.status === 'approved' &&
    (h.type === 'paid' || h.type === 'half') &&
    h.dateFrom <= ds && h.dateTo >= ds
  );
  if (!matches.length) return 0;
  // Half-day takes precedence if both somehow exist (defensive)
  if (matches.some(h => h.type === 'half')) return 4;
  return 8;
}

// Bank-holiday hours for this date (0 or 8). Active payee employees only —
// CIS contractors and inactive employees get 0.
function getBankHolidayHoursForEmployee(empName, ds) {
  const d = new Date(ds + 'T12:00:00');
  const dow = d.getDay();
  if (dow === 0 || dow === 6) return 0; // defensive: no BH on weekends in our list
  if (!isBankHoliday(ds)) return 0;
  const emp = (state.timesheetData.employees || []).find(e => e.name === empName);
  if (!emp || emp.active === false) return 0;
  if ((emp.payType || 'payee') !== 'payee') return 0;
  return 8;
}

function calculatePayroll(employeeName, weekMon, weekSun) {
  const monStr = dateStr(weekMon);
  const sunStr = dateStr(weekSun);

  // Get all approved clockings for this employee this week
  const clockings = state.timesheetData.clockings.filter(c =>
    c.employeeName === employeeName &&
    c.date >= monStr && c.date <= sunStr &&
    c.approvalStatus !== 'rejected'
  );

  // Calculate hours per day from clockings
  const dayHours = {};
  let workedSaturday = false;
  let workedSunday = false;
  let sundayHours = 0;

  clockings.forEach(c => {
    const hrs = calcHours(c.clockIn, c.clockOut, c.breakMins, c.date) || 0;
    dayHours[c.date] = (dayHours[c.date] || 0) + hrs;

    const d = new Date(c.date + 'T12:00:00');
    const dow = d.getDay(); // 0=Sun, 6=Sat
    if (dow === 6 && hrs > 0) workedSaturday = true;
    if (dow === 0 && hrs > 0) { workedSunday = true; sundayHours += hrs; }
  });

  const workedHours = Object.values(dayHours).reduce((s, h) => s + h, 0);

  // Walk the week to collect holiday + bank-holiday hours
  const dayHoliday = {};      // date → booked-holiday hours (display)
  const dayBankHoliday = {};  // date → bank-holiday hours (display)
  let holidayHours = 0;
  let bankHolidayHours = 0;
  for (let i = 0; i < 7; i++) {
    const d = new Date(weekMon);
    d.setDate(weekMon.getDate() + i);
    const ds = dateStr(d);
    const hh = getHolidayHoursForEmployee(employeeName, ds);
    if (hh > 0) { dayHoliday[ds] = hh; holidayHours += hh; }
    const bh = getBankHolidayHoursForEmployee(employeeName, ds);
    if (bh > 0) { dayBankHoliday[ds] = bh; bankHolidayHours += bh; }
  }

  // Bail only if everything is zero
  if (workedHours === 0 && holidayHours === 0 && bankHolidayHours === 0) {
    return null;
  }

  // Get employee rate
  const emp = (state.timesheetData.employees || []).find(e => e.name === employeeName);
  const rate = emp ? (emp.rate || 0) : 0;

  // Calculate pay breakdown.
  // Holiday + bank-holiday hours fill the 40h bucket FIRST, pushing worked
  // hours into overtime if combined exceeds 40. Both are always paid at
  // basic rate (never OT, never double).
  const nonWorkedPaidHours = holidayHours + bankHolidayHours;
  const doubleTimeApplies = workedSaturday && workedSunday;

  let basicHours, overtimeHours, doubleHours;

  if (doubleTimeApplies) {
    doubleHours = sundayHours;
    const nonSundayWorked = workedHours - sundayHours;
    const nonSundayCombined = nonSundayWorked + nonWorkedPaidHours;
    if (nonSundayCombined <= 40) {
      basicHours = nonSundayWorked;
      overtimeHours = 0;
    } else {
      const cap = Math.max(0, 40 - nonWorkedPaidHours);
      basicHours = Math.min(nonSundayWorked, cap);
      overtimeHours = nonSundayWorked - basicHours;
    }
  } else {
    doubleHours = 0;
    if (workedHours + nonWorkedPaidHours <= 40) {
      basicHours = workedHours;
      overtimeHours = 0;
    } else {
      const cap = Math.max(0, 40 - nonWorkedPaidHours);
      basicHours = Math.min(workedHours, cap);
      overtimeHours = workedHours - basicHours;
    }
  }

  const basicPay        = basicHours        * rate;
  const overtimePay     = overtimeHours     * rate * 1.5;
  const doublePay       = doubleHours       * rate * 2;
  const holidayPay      = holidayHours      * rate;
  const bankHolidayPay  = bankHolidayHours  * rate;
  const totalPay = basicPay + overtimePay + doublePay + holidayPay + bankHolidayPay;
  const totalHours = workedHours + holidayHours + bankHolidayHours;

  return {
    employeeName,
    rate,
    totalHours: parseFloat(totalHours.toFixed(2)),
    basicHours: parseFloat(basicHours.toFixed(2)),
    overtimeHours: parseFloat(overtimeHours.toFixed(2)),
    doubleHours: parseFloat(doubleHours.toFixed(2)),
    holidayHours: parseFloat(holidayHours.toFixed(2)),
    bankHolidayHours: parseFloat(bankHolidayHours.toFixed(2)),
    basicPay: parseFloat(basicPay.toFixed(2)),
    overtimePay: parseFloat(overtimePay.toFixed(2)),
    doublePay: parseFloat(doublePay.toFixed(2)),
    holidayPay: parseFloat(holidayPay.toFixed(2)),
    bankHolidayPay: parseFloat(bankHolidayPay.toFixed(2)),
    totalPay: parseFloat(totalPay.toFixed(2)),
    doubleTimeApplies,
    dayHours,
    dayHoliday,
    dayBankHoliday
  };
}

// ═══════════════════════════════════════════
// REPORTS ENGINE
// ═══════════════════════════════════════════
let rptPeriod = 'week';
let rptOffset = 0;
let rptCharts = {};

function setReportPeriod(period) {
  rptPeriod = period;
  rptOffset = 0; // reset offset when changing period
  ['week','month','year'].forEach(p => {
    const btn = document.getElementById(`rpt-btn-${p}`);
    if (btn) {
      btn.style.background = p === period ? 'var(--accent)' : 'var(--surface)';
      btn.style.color = p === period ? '#fff' : 'var(--muted)';
    }
  });
  renderReports();
}

function changeReportOffset(dir) {
  rptOffset += dir;
  if (rptOffset > 0) rptOffset = 0;
  renderReports();
}

function getReportDateRange() {
  const now = new Date();
  let from, to;

  if (rptPeriod === 'week') {
    const dow = now.getDay();
    const mon = new Date(now);
    mon.setDate(now.getDate() - (dow === 0 ? 6 : dow - 1) + rptOffset * 7);
    mon.setHours(0,0,0,0);
    from = dateStr(mon);
    const sun = new Date(mon); sun.setDate(mon.getDate() + 6);
    to = dateStr(sun);
  } else if (rptPeriod === 'month') {
    const target = new Date(now.getFullYear(), now.getMonth() + rptOffset, 1);
    from = dateStr(target);
    const last = new Date(target.getFullYear(), target.getMonth() + 1, 0);
    to = dateStr(last);
  } else {
    const yr = now.getFullYear() + rptOffset;
    from = `${yr}-01-01`;
    to = `${yr}-12-31`;
  }
  return { from, to };
}

function getWeeklyData(empFilter) {
  // Build week-by-week data from all available data
  const clockings = (state.timesheetData.clockings || [])
    .filter(c => !empFilter || c.employeeName === empFilter);
  const entries = (state.timesheetData.entries || [])
    .filter(e => !empFilter || e.employeeName === empFilter);

  // Collect all unique weeks
  const weekMap = {};
  clockings.forEach(c => {
    const d = new Date(c.date + 'T12:00:00');
    const dow = d.getDay();
    const mon = new Date(d);
    mon.setDate(d.getDate() - (dow === 0 ? 6 : dow - 1));
    const wk = dateStr(mon);
    if (!weekMap[wk]) weekMap[wk] = { label: wk, clocked: 0, project: 0, unproductive: 0 };
    const hrs = calcHours(c.clockIn, c.clockOut, c.breakMins, c.date) || 0;
    weekMap[wk].clocked = Math.round((weekMap[wk].clocked + hrs) * 10) / 10;
  });
  entries.forEach(e => {
    const d = new Date(e.date + 'T12:00:00');
    const dow = d.getDay();
    const mon = new Date(d);
    mon.setDate(d.getDate() - (dow === 0 ? 6 : dow - 1));
    const wk = dateStr(mon);
    if (!weekMap[wk]) return;
    if (e.projectId === 'S000') weekMap[wk].unproductive = Math.round((weekMap[wk].unproductive + e.hours) * 10) / 10;
    else if (e.projectId === 'WGD') weekMap[wk].wgd = Math.round(((weekMap[wk].wgd||0) + e.hours) * 10) / 10;
    else weekMap[wk].project = Math.round((weekMap[wk].project + e.hours) * 10) / 10;
  });
  return Object.values(weekMap).sort((a,b) => a.label.localeCompare(b.label));
}

function getPeriodData(empFilter) {
  const { from, to } = getReportDateRange();
  const clockings = (state.timesheetData.clockings || [])
    .filter(c => c.date >= from && c.date <= to && (!empFilter || c.employeeName === empFilter));
  const entries = (state.timesheetData.entries || [])
    .filter(e => e.date >= from && e.date <= to && (!empFilter || e.employeeName === empFilter));

  const totalClocked = clockings.reduce((s,c) => s + (calcHours(c.clockIn, c.clockOut, c.breakMins, c.date)||0), 0);
  const totalProject = entries.filter(e => e.projectId !== 'S000' && e.projectId !== 'WGD').reduce((s,e) => s + e.hours, 0);
  const totalWGD = entries.filter(e => e.projectId === 'WGD').reduce((s,e) => s + e.hours, 0);
  const totalUnproductive = entries.filter(e => e.projectId === 'S000').reduce((s,e) => s + e.hours, 0);
  const utilisation = totalClocked > 0 ? Math.round(((totalProject + totalWGD) / totalClocked) * 100) : 0;

  // By employee
  const empMap = {};
  clockings.forEach(c => {
    if (!empMap[c.employeeName]) empMap[c.employeeName] = { clocked: 0, project: 0, wgd: 0, unproductive: 0 };
    empMap[c.employeeName].clocked = Math.round((empMap[c.employeeName].clocked + (calcHours(c.clockIn, c.clockOut, c.breakMins, c.date)||0)) * 10) / 10;
  });
  entries.forEach(e => {
    if (!empMap[e.employeeName]) return;
    if (e.projectId === 'S000') empMap[e.employeeName].unproductive = Math.round((empMap[e.employeeName].unproductive + e.hours) * 10) / 10;
    else if (e.projectId === 'WGD') empMap[e.employeeName].wgd = Math.round((empMap[e.employeeName].wgd + e.hours) * 10) / 10;
    else empMap[e.employeeName].project = Math.round((empMap[e.employeeName].project + e.hours) * 10) / 10;
  });

  // By project (exclude S000 and WGD from project doughnut)
  const projMap = {};
  entries.filter(e => e.projectId !== 'S000' && e.projectId !== 'WGD').forEach(e => {
    if (!projMap[e.projectId]) projMap[e.projectId] = { id: e.projectId, name: e.projectName, hours: 0 };
    projMap[e.projectId].hours = Math.round((projMap[e.projectId].hours + e.hours) * 10) / 10;
  });

  return { totalClocked, totalProject, totalWGD, totalUnproductive, utilisation, empMap, projMap, from, to };
}

function renderReports() {
  // Babcock Overview has its own data model (quote-level not employee-hour-
  // level) and FY toggle. Delegate entirely — none of the period/employee
  // wiring below applies to it.
  if (activeReport === 'babcock') {
    renderBabcockReport();
    return;
  }
  // Cost & PO Analysis: own period toggle + own KPI row + own datasource
  // (purchase orders + project hours, not employee clock entries).
  if (activeReport === 'costanalysis') {
    renderCostAnalysisReport();
    return;
  }
  if (activeReport === 'holidays') {
    renderHolidayReport();
    return;
  }
  if (activeReport === 'productivity') {
    renderProductivityReport();
    return;
  }
  if (activeReport === 'faboutput') {
    renderFabOutputReport();
    return;
  }
  if (activeReport === 'cvr') {
    renderCvrReport();
    return;
  }
  if (activeReport === 'paymentsdue') {
    renderPaymentsDueReport();
    return;
  }
  if (activeReport === 'labourpay') {
    renderLabourPayReport();
    return;
  }

  const empFilter = document.getElementById('rptEmployeeFilter')?.value || '';

  // Populate employee filter
  const sel = document.getElementById('rptEmployeeFilter');
  if (sel && sel.options.length <= 1) {
    (state.timesheetData.employees || []).filter(e => e.active !== false).forEach(e => {
      const opt = document.createElement('option');
      opt.value = e.name; opt.textContent = e.name;
      sel.appendChild(opt);
    });
  }

  const { totalClocked, totalProject, totalWGD, totalUnproductive, utilisation, empMap, projMap, from, to } = getPeriodData(empFilter);
  const periodLabels = { week: 'This Week', month: 'This Month', year: 'This Year' };
  let periodLabel = periodLabels[rptPeriod];
  if (rptOffset !== 0) {
    if (rptPeriod === 'week') periodLabel = `Week of ${fmtDateStr(from)}`;
    else if (rptPeriod === 'month') {
      const d = new Date(from + 'T12:00:00');
      periodLabel = d.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
    } else periodLabel = from.slice(0, 4);
  }

  // Update range label
  const label = document.getElementById('rptRangeLabel');
  if (label) label.textContent = `${fmtDateStr(from)} → ${fmtDateStr(to)}`;

  // Calculate attendance rate for the general view
  const attendanceData = getAttendanceData(empFilter);

  // KPI cards — general view (all employees) shows hours + utilisation + attendance only
  const kpiRow = document.getElementById('rptKpiRow');
  if (kpiRow) {
    const kpis = [
      { label: 'Total Hours', value: totalClocked.toFixed(2) + 'h', color: 'var(--accent2)' },
      { label: 'Project Hours', value: totalProject.toFixed(2) + 'h', color: 'var(--green)' },
      { label: 'Workshop General', value: totalWGD.toFixed(2) + 'h', color: '#6366f1' },
      { label: 'Unproductive', value: totalUnproductive.toFixed(2) + 'h', color: 'var(--red)' },
      { label: 'Utilisation', value: utilisation + '%', color: utilisation >= 80 ? 'var(--green)' : utilisation >= 60 ? 'var(--amber)' : 'var(--red)' },
      { label: 'Attendance', value: attendanceData.attendanceRate + '%', color: attendanceData.attendanceRate >= 95 ? 'var(--green)' : attendanceData.attendanceRate >= 85 ? 'var(--amber)' : 'var(--red)' },
    ];
    kpiRow.innerHTML = kpis.map(k => `
      <div style="background:var(--card);border:1px solid var(--border);border-radius:10px;padding:16px 18px">
        <div style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:1px;margin-bottom:6px">${k.label}</div>
        <div style="font-family:var(--font-display);font-size:30px;color:${k.color}">${k.value}</div>
        <div style="font-size:10px;color:var(--subtle);margin-top:4px">${periodLabel}</div>
      </div>
    `).join('');
  }

  // Destroy old charts
  Object.values(rptCharts).forEach(c => { try { c.destroy(); } catch {} });
  rptCharts = {};

  const weeklyData = getWeeklyData(empFilter);
  const weekLabels = weeklyData.map(w => w.label.slice(5)); // MM-DD

  // ── Line chart: hours over time ──
  const lineCtx = document.getElementById('rptLineChart');
  if (lineCtx && weeklyData.length) {
    rptCharts.line = new Chart(lineCtx, {
      type: 'line',
      data: {
        labels: weekLabels,
        datasets: [
          { label: 'Clocked', data: weeklyData.map(w => w.clocked), borderColor: '#ffb347', backgroundColor: 'rgba(255,179,71,.1)', tension: 0.4, fill: true, pointRadius: 4 },
          { label: 'Project', data: weeklyData.map(w => w.project), borderColor: '#3ecf8e', backgroundColor: 'rgba(62,207,142,.1)', tension: 0.4, fill: true, pointRadius: 4 },
          { label: 'Unproductive', data: weeklyData.map(w => w.unproductive), borderColor: '#ff4444', backgroundColor: 'rgba(255,68,68,.1)', tension: 0.4, fill: true, pointRadius: 4 },
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: true,
        plugins: { legend: { labels: { color: '#888', font: { size: 11 } } } },
        scales: {
          x: { ticks: { color: '#888', font: { size: 10 } }, grid: { color: 'rgba(255,255,255,.05)' } },
          y: { ticks: { color: '#888', font: { size: 10 } }, grid: { color: 'rgba(255,255,255,.05)' }, beginAtZero: true }
        }
      }
    });
  }

  // ── Bar chart: hours by employee ──
  const empBarCtx = document.getElementById('rptEmpBar');
  if (empBarCtx) {
    const empNames = Object.keys(empMap);
    const colors = ['#ff6b00','#3ecf8e','#6366f1','#ffb347','#ff4444'];
    rptCharts.empBar = new Chart(empBarCtx, {
      type: 'bar',
      data: {
        labels: empNames.map(n => n.split(' ')[0]),
        datasets: [
          { label: 'Clocked', data: empNames.map(n => empMap[n].clocked), backgroundColor: colors.map(c => c + 'cc') },
          { label: 'Project', data: empNames.map(n => empMap[n].project), backgroundColor: empNames.map(() => 'rgba(62,207,142,.6)') },
          { label: 'Workshop General', data: empNames.map(n => empMap[n].wgd||0), backgroundColor: empNames.map(() => 'rgba(99,102,241,.6)') },
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: true,
        plugins: { legend: { labels: { color: '#888', font: { size: 11 } } } },
        scales: {
          x: { ticks: { color: '#888' }, grid: { color: 'rgba(255,255,255,.05)' } },
          y: { ticks: { color: '#888' }, grid: { color: 'rgba(255,255,255,.05)' }, beginAtZero: true }
        }
      }
    });
  }

  // ── Doughnut: project split ──
  const doughCtx = document.getElementById('rptProjectDoughnut');
  if (doughCtx) {
    const projects = Object.values(projMap).sort((a,b) => b.hours - a.hours).slice(0,8);
    const palette = ['#ff6b00','#3ecf8e','#6366f1','#ffb347','#ff4444','#06b6d4','#a855f7','#f59e0b'];
    rptCharts.dough = new Chart(doughCtx, {
      type: 'doughnut',
      data: {
        labels: projects.map(p => `${p.id}`),
        datasets: [{ data: projects.map(p => p.hours), backgroundColor: palette, borderWidth: 2, borderColor: '#1e1e1e' }]
      },
      options: {
        responsive: true, maintainAspectRatio: true,
        plugins: {
          legend: { position: 'right', labels: { color: '#888', font: { size: 10 }, boxWidth: 12 } },
          tooltip: { callbacks: { label: ctx => ` ${projects[ctx.dataIndex]?.name || ''}: ${ctx.parsed}h` } }
        }
      }
    });
  }

  // ── Unproductive bar per employee ──
  const unprodCtx = document.getElementById('rptUnproductiveBar');
  if (unprodCtx) {
    const empNames = Object.keys(empMap);
    rptCharts.unprod = new Chart(unprodCtx, {
      type: 'bar',
      data: {
        labels: empNames,
        datasets: [
          {
            label: 'Unproductive (S000)',
            data: empNames.map(n => empMap[n].unproductive),
            backgroundColor: 'rgba(255,68,68,.6)',
            borderColor: '#ff4444',
            borderWidth: 1,
            borderRadius: 4
          },
          {
            label: 'Workshop General Duties',
            data: empNames.map(n => empMap[n].wgd||0),
            backgroundColor: 'rgba(99,102,241,.6)',
            borderColor: '#6366f1',
            borderWidth: 1,
            borderRadius: 4
          }
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: true, indexAxis: 'y',
        plugins: { legend: { display: false } },
        scales: {
          x: { ticks: { color: '#888' }, grid: { color: 'rgba(255,255,255,.05)' }, beginAtZero: true },
          y: { ticks: { color: '#aaa' }, grid: { color: 'rgba(255,255,255,.05)' } }
        }
      }
    });
  }

  // ── Attendance report ──
  if (activeReport === 'attendance') renderAttendanceReport(empFilter);
}

// ═══════════════════════════════════════════
// BABCOCK OVERVIEW REPORT (reports.html)
// ═══════════════════════════════════════════
// Quote-level analytics that complement the operational Babcock tracker.
// All metrics are computed client-side against /api/babcock-quotes — the
// volume is small (single-digit to low-hundreds of rows lifetime), so
// no server-side aggregation is needed for v1.
//
// Status buckets (for tile counts):
//   Open quotes:        Quote Received, Quote Sent (not yet converted)
//   Open projects:      Live Project (work in progress)
//   Closed projects:    Project Complete, Bama SW PO Raised,
//                       Bama SW Invoice Received, Approved to Pay,
//                       Payment Received, Paid to Bama SW,
//                       Remittance Sent, Closed
//   Cancelled:          Cancelled (terminal failure)

// FY toggle state — 'current' or 'last' (last full UK financial year)
let _bbkFY = 'current';
let _bbkCharts = {};   // separate from rptCharts so destroys don't collide
let _bbkQuotesCache = null; // cached list to avoid refetch when toggling FY

// Resolve a CSS custom-property name to its computed colour value.
// Chart.js does not parse CSS variables — passing 'var(--muted)' literally
// to a canvas context falls back to the canvas default (black), which is
// invisible on our dark theme. This helper grabs the resolved hex/rgb
// from the page so all chart text + axis ticks render in the correct
// theme colour. Cached per-name so we only hit getComputedStyle once.
const _resolvedCssColours = {};
function cssVar(name, fallback) {
  if (_resolvedCssColours[name]) return _resolvedCssColours[name];
  try {
    const v = getComputedStyle(document.documentElement)
      .getPropertyValue(name).trim();
    if (v) { _resolvedCssColours[name] = v; return v; }
  } catch (e) { /* ignore */ }
  return fallback || '#999';
}

const BABCOCK_OPEN_QUOTE_STATUSES   = ['Quote Received', 'Quote Sent'];
const BABCOCK_OPEN_PROJECT_STATUSES = ['Live Project'];
const BABCOCK_CLOSED_PROJECT_STATUSES = [
  'Project Complete', 'Approved to Pay', 'Payment Received',
  'Bama SW PO Raised', 'Bama SW Invoice Received', 'Paid to Bama SW', 'Remittance Sent', 'Closed'
];

function setBabcockFY(which) {
  _bbkFY = which;
  document.getElementById('bbk-fy-current')?.style.setProperty('background', which === 'current' ? 'var(--accent)' : 'var(--surface)');
  document.getElementById('bbk-fy-current')?.style.setProperty('color',      which === 'current' ? '#fff' : 'var(--muted)');
  document.getElementById('bbk-fy-last')?.style.setProperty('background',    which === 'last'    ? 'var(--accent)' : 'var(--surface)');
  document.getElementById('bbk-fy-last')?.style.setProperty('color',         which === 'last'    ? '#fff' : 'var(--muted)');
  renderBabcockReport();
}

// Return UK financial year boundaries for the requested year-token.
// UK FY runs 1 Apr → 31 Mar. 'current' = the FY that contains today.
// 'last' = the FY immediately before that. Inclusive of both ends.
function getBabcockFYRange(which) {
  const today = new Date();
  // Current FY starts on 1 April of whichever calendar year we're in,
  // or 1 April of the *previous* calendar year if today is Jan/Feb/Mar.
  let fyStart = today.getMonth() >= 3
    ? new Date(today.getFullYear(), 3, 1)
    : new Date(today.getFullYear() - 1, 3, 1);
  if (which === 'last') {
    fyStart = new Date(fyStart.getFullYear() - 1, 3, 1);
  }
  const fyEnd = new Date(fyStart.getFullYear() + 1, 2, 31); // 31 Mar next yr
  return { fyStart, fyEnd, fyLabel: `FY ${fyStart.getFullYear()}/${String((fyStart.getFullYear() + 1) % 100).padStart(2, '0')}` };
}

// Pull a usable "date" off a Babcock-quote row for time-bucketing.
// Prefers `date_sent` (when we actually sent the quote out) then falls
// back to `quotation_date` then `created_at`. Returns a Date or null.
function babcockRowDate(q) {
  const raw = q.date_sent || q.quotation_date || q.created_at;
  if (!raw) return null;
  const d = new Date(String(raw).split('T')[0] + 'T00:00:00');
  return isNaN(d.getTime()) ? null : d;
}

function inRange(d, from, to) {
  if (!d) return false;
  return d >= from && d <= to;
}

function fmtMoneyShort(n) {
  if (n == null || !isFinite(Number(n))) return '£0';
  const abs = Math.abs(Number(n));
  if (abs >= 1_000_000) return '£' + (Number(n) / 1_000_000).toFixed(1) + 'M';
  if (abs >= 10_000)    return '£' + Math.round(Number(n) / 1_000) + 'k';
  return '£' + Number(n).toLocaleString('en-GB', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
}
function fmtMoneyFull(n) {
  if (n == null || !isFinite(Number(n))) return '£0.00';
  return '£' + Number(n).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// ═══════════════════════════════════════════
// COST & PO ANALYSIS REPORT
// ═══════════════════════════════════════════
//
// A spend-analytics report driven by PurchaseOrders + ProjectHours.
// Independent from the kiosk-hours reports that share #rptKpiRow and the
// global Week/Month/Year toolbar.
//
// Data sources, loaded lazily on first render:
//   • /api/purchase-orders   — every PO, with project_id/cost_centre/created_at/total_value/vat_amount
//   • /api/project-hours     — every ProjectHours row across the entire DB
// We don't filter at the API level by date; the dataset is small enough
// (≤500 POs, low thousands of hours rows) that an in-memory filter is fine
// and avoids a round-trip per toggle change.
//
// Period semantics (matches PO Tracker spend tile):
//   thisMonth — current calendar month (UTC)
//   lastMonth — previous calendar month
//   ytd       — Jan 1 → today (current calendar year)
//
// Workshop vs Office split is by cost_centre string match ('8099'/'5099'),
// confirmed in CLAUDE.md / project schema. POs assigned to a project
// (project_id NOT NULL, cost_centre NULL) don't contribute to either —
// they go into the project-totals charts instead.

let _caPeriod = 'thisMonth';
let _caCharts = {};      // separate from rptCharts so chart-destroy in other reports doesn't kill ours
let _caData   = null;    // { pos: [], hours: [] } cached after first fetch

function setCaPeriod(period) {
  _caPeriod = period;
  renderCostAnalysisReport();
}

// Return { start, end, label } for the chosen period.
function _caRange(period) {
  const now = new Date();
  const y = now.getUTCFullYear();
  const m = now.getUTCMonth();
  if (period === 'lastMonth') {
    const start = new Date(Date.UTC(y, m - 1, 1));
    const end   = new Date(Date.UTC(y, m, 1));
    return { start, end, label: 'Last Month — ' + start.toLocaleString('en-GB', { month: 'long', year: 'numeric', timeZone: 'UTC' }) };
  }
  if (period === 'ytd') {
    const start = new Date(Date.UTC(y, 0, 1));
    const end   = new Date(Date.UTC(y + 1, 0, 1));
    return { start, end, label: `YTD ${y} — Jan 1 onwards` };
  }
  // thisMonth (default)
  const start = new Date(Date.UTC(y, m, 1));
  const end   = new Date(Date.UTC(y, m + 1, 1));
  return { start, end, label: 'This Month — ' + start.toLocaleString('en-GB', { month: 'long', year: 'numeric', timeZone: 'UTC' }) };
}

async function _caEnsureData() {
  if (_caData) return _caData;
  try {
    const [pos, hours] = await Promise.all([
      api.get('/api/purchase-orders'),
      api.get('/api/project-hours')
    ]);
    _caData = {
      pos:   Array.isArray(pos)   ? pos   : [],
      hours: Array.isArray(hours) ? hours : []
    };
  } catch (e) {
    console.warn('Cost analysis: data fetch failed:', e);
    _caData = { pos: [], hours: [] };
  }
  return _caData;
}

// Render the period toggle (This Mo / Last Mo / YTD) into #caPeriodToggle.
function _caRenderToggle() {
  const wrap = document.getElementById('caPeriodToggle');
  if (!wrap) return;
  const btn = (token, txt) => {
    const active = _caPeriod === token;
    return `<button class="btn" onclick="setCaPeriod('${token}')"
      style="border-radius:0;border:none;padding:8px 18px;font-size:13px;
             background:${active ? 'var(--accent)' : 'var(--surface)'};
             color:${active ? '#fff' : 'var(--muted)'};cursor:pointer">${txt}</button>`;
  };
  wrap.innerHTML = btn('thisMonth', 'This Month') + btn('lastMonth', 'Last Month') + btn('ytd', 'YTD');
}

// Compute nett (ex-VAT) value for a PO. Falls back to total - vat_amount,
// else total / (1 + vat_rate/100), else total. Matches the math used in
// the PO Tracker render.
function _caNett(p) {
  const total = Number(p.total_value) || 0;
  if (Number(p.vat_amount) >= 0) return _r2(total - Number(p.vat_amount));
  const rate = Number(p.vat_rate);
  if (rate > 0)                  return _r2(total / (1 + rate / 100));
  return _r2(total);
}

async function renderCostAnalysisReport() {
  _caRenderToggle();
  const { start, end, label } = _caRange(_caPeriod);
  const labelEl = document.getElementById('caRangeLabel');
  if (labelEl) labelEl.textContent = label;

  // Tear down any prior charts for this report
  Object.values(_caCharts).forEach(c => { try { c.destroy(); } catch {} });
  _caCharts = {};

  const { pos, hours } = await _caEnsureData();

  // Filter POs to the selected period using created_at
  const posInPeriod = pos.filter(p => {
    const d = p.created_at ? new Date(p.created_at) : null;
    if (!d || isNaN(d)) return false;
    return d >= start && d < end;
  });

  // Filter ProjectHours to the selected period using the `date` column.
  // S000 is non-productive time — excluded from labour cost (matches the
  // Project Tracker labour-cost convention).
  const hoursInPeriod = hours.filter(r => {
    if (r.project_number === 'S000') return false;
    const d = r.date ? new Date(r.date) : null;
    if (!d || isNaN(d)) return false;
    return d >= start && d < end;
  });

  // Build employee_id → rate map from in-memory cache
  const employees = state.timesheetData.employees || [];
  const rateById = {};
  const rateByName = {};
  for (const e of employees) {
    if (e.id != null) rateById[e.id] = Number(e.rate) || 0;
    if (e.name)       rateByName[e.name] = Number(e.rate) || 0;
  }
  const rateFor = r => {
    if (r.employee_id != null && rateById[r.employee_id] !== undefined) return rateById[r.employee_id];
    if (r.employee_name && rateByName[r.employee_name] !== undefined)   return rateByName[r.employee_name];
    return 0;
  };

  // KPI totals
  const totalPoSpend     = posInPeriod.reduce((s, p) => s + _caNett(p), 0);
  const totalLabourCost  = hoursInPeriod.reduce((s, r) => s + (Number(r.hours) || 0) * rateFor(r), 0);
  const workshopSpend    = posInPeriod.filter(p => p.cost_centre === '8099').reduce((s, p) => s + _caNett(p), 0);
  const officeSpend      = posInPeriod.filter(p => p.cost_centre === '5099').reduce((s, p) => s + _caNett(p), 0);

  // KPI tiles
  const kpis = [
    { label: 'PO Spend',       value: fmtMoneyFull(totalPoSpend),    color: 'var(--accent)' },
    { label: 'Labour Cost',    value: fmtMoneyFull(totalLabourCost), color: 'var(--accent2)' },
    { label: 'Workshop (8099)',value: fmtMoneyFull(workshopSpend),   color: '#6366f1' },
    { label: 'Office (5099)',  value: fmtMoneyFull(officeSpend),     color: '#3ecf8e' },
  ];
  const kpiRow = document.getElementById('caKpiRow');
  if (kpiRow) {
    kpiRow.innerHTML = kpis.map(k => `
      <div style="background:var(--card);border:1px solid var(--border);border-radius:10px;padding:16px 18px">
        <div style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:1px;margin-bottom:6px">${k.label}</div>
        <div style="font-family:var(--font-display);font-size:26px;color:${k.color};word-break:break-all">${k.value}</div>
      </div>
    `).join('');
  }

  // ── Top 5 projects by PO spend ──
  // Aggregate by project_id, label by project_number (fall back to id)
  const poByProj = {};
  for (const p of posInPeriod) {
    if (!p.project_id) continue;   // skip overhead POs
    const k = p.project_id;
    if (!poByProj[k]) poByProj[k] = { id: k, label: p.project_number || `#${k}`, name: p.project_name || '', total: 0 };
    poByProj[k].total += _caNett(p);
  }
  const topPo = Object.values(poByProj).sort((a, b) => b.total - a.total).slice(0, 5);

  const topPoCtx = document.getElementById('caTopPoBar');
  if (topPoCtx && typeof Chart !== 'undefined') {
    _caCharts.topPo = new Chart(topPoCtx, {
      type: 'bar',
      data: {
        labels: topPo.map(p => p.label),
        datasets: [{
          label: 'Nett spend (£)',
          data: topPo.map(p => Math.round(p.total * 100) / 100),
          backgroundColor: 'rgba(255,107,0,.65)',
          borderColor:     'rgba(255,107,0,1)',
          borderWidth: 1
        }]
      },
      options: {
        indexAxis: 'y',
        responsive: true, maintainAspectRatio: true,
        plugins: {
          legend: { display: false },
          tooltip: { callbacks: { label: ctx => ` ${topPo[ctx.dataIndex]?.name || ''}: £${ctx.parsed.x.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` } }
        },
        scales: {
          x: { ticks: { color: '#888', callback: v => '£' + Number(v).toLocaleString('en-GB') }, grid: { color: 'rgba(255,255,255,.05)' }, beginAtZero: true },
          y: { ticks: { color: '#888' }, grid: { color: 'rgba(255,255,255,.05)' } }
        }
      }
    });
  }

  // ── Top 5 projects by labour cost ──
  const labByProj = {};
  for (const r of hoursInPeriod) {
    const pn = r.project_number;
    if (!pn) continue;
    if (!labByProj[pn]) labByProj[pn] = { label: pn, total: 0 };
    labByProj[pn].total += (Number(r.hours) || 0) * rateFor(r);
  }
  const topLab = Object.values(labByProj).sort((a, b) => b.total - a.total).slice(0, 5);

  const topLabCtx = document.getElementById('caTopLabourBar');
  if (topLabCtx && typeof Chart !== 'undefined') {
    _caCharts.topLab = new Chart(topLabCtx, {
      type: 'bar',
      data: {
        labels: topLab.map(p => p.label),
        datasets: [{
          label: 'Labour cost (£)',
          data: topLab.map(p => Math.round(p.total * 100) / 100),
          backgroundColor: 'rgba(62,207,142,.65)',
          borderColor:     'rgba(62,207,142,1)',
          borderWidth: 1
        }]
      },
      options: {
        indexAxis: 'y',
        responsive: true, maintainAspectRatio: true,
        plugins: {
          legend: { display: false },
          tooltip: { callbacks: { label: ctx => ` £${ctx.parsed.x.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` } }
        },
        scales: {
          x: { ticks: { color: '#888', callback: v => '£' + Number(v).toLocaleString('en-GB') }, grid: { color: 'rgba(255,255,255,.05)' }, beginAtZero: true },
          y: { ticks: { color: '#888' }, grid: { color: 'rgba(255,255,255,.05)' } }
        }
      }
    });
  }

  // ── Workshop + Office spend over time (line) ──
  // Bucketing strategy:
  //   • month-scope periods (thisMonth, lastMonth) → daily buckets
  //   • year-scope period (ytd)                    → monthly buckets
  const useMonthly = (_caPeriod === 'ytd');
  const buckets = [];  // [{ key, label, start, end }]
  if (useMonthly) {
    // Month buckets from start to end (exclusive)
    const cur = new Date(start);
    while (cur < end) {
      const bs = new Date(cur);
      const be = new Date(Date.UTC(cur.getUTCFullYear(), cur.getUTCMonth() + 1, 1));
      buckets.push({
        key:   `${bs.getUTCFullYear()}-${String(bs.getUTCMonth() + 1).padStart(2, '0')}`,
        label: bs.toLocaleString('en-GB', { month: 'short', timeZone: 'UTC' }),
        start: bs, end: be
      });
      cur.setUTCMonth(cur.getUTCMonth() + 1);
    }
  } else {
    // Day buckets from start to end (exclusive)
    const cur = new Date(start);
    while (cur < end) {
      const bs = new Date(cur);
      const be = new Date(cur); be.setUTCDate(be.getUTCDate() + 1);
      buckets.push({
        key:   bs.toISOString().slice(0, 10),
        label: String(bs.getUTCDate()),
        start: bs, end: be
      });
      cur.setUTCDate(cur.getUTCDate() + 1);
    }
  }

  const bucketize = (filteredPos) => {
    const data = buckets.map(() => 0);
    for (const p of filteredPos) {
      const d = new Date(p.created_at);
      const idx = buckets.findIndex(b => d >= b.start && d < b.end);
      if (idx >= 0) data[idx] += _caNett(p);
    }
    return data;
  };
  const workshopData = bucketize(posInPeriod.filter(p => p.cost_centre === '8099'));
  const officeData   = bucketize(posInPeriod.filter(p => p.cost_centre === '5099'));

  const _lineOptions = {
    responsive: true, maintainAspectRatio: true,
    plugins: {
      legend: { display: false },
      tooltip: { callbacks: { label: ctx => ` £${ctx.parsed.y.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` } }
    },
    scales: {
      x: { ticks: { color: '#888' }, grid: { color: 'rgba(255,255,255,.05)' } },
      y: { ticks: { color: '#888', callback: v => '£' + Number(v).toLocaleString('en-GB') }, grid: { color: 'rgba(255,255,255,.05)' }, beginAtZero: true }
    }
  };

  const wsCtx = document.getElementById('caWorkshopLine');
  if (wsCtx && typeof Chart !== 'undefined') {
    _caCharts.workshop = new Chart(wsCtx, {
      type: 'line',
      data: {
        labels: buckets.map(b => b.label),
        datasets: [{
          label: 'Workshop spend (£)',
          data: workshopData,
          borderColor:     '#6366f1',
          backgroundColor: 'rgba(99,102,241,.15)',
          fill: true, tension: 0.25, pointRadius: 3
        }]
      },
      options: _lineOptions
    });
  }
  const ofCtx = document.getElementById('caOfficeLine');
  if (ofCtx && typeof Chart !== 'undefined') {
    _caCharts.office = new Chart(ofCtx, {
      type: 'line',
      data: {
        labels: buckets.map(b => b.label),
        datasets: [{
          label: 'Office spend (£)',
          data: officeData,
          borderColor:     '#3ecf8e',
          backgroundColor: 'rgba(62,207,142,.15)',
          fill: true, tension: 0.25, pointRadius: 3
        }]
      },
      options: _lineOptions
    });
  }
}



async function renderBabcockReport() {
  // Fetch (cache so FY toggles don't re-hit the API)
  if (!_bbkQuotesCache) {
    try {
      _bbkQuotesCache = await api.get('/api/babcock-quotes');
    } catch (err) {
      console.error('Babcock report fetch failed:', err);
      toast('Failed to load Babcock data: ' + (err.message || 'unknown'), 'error');
      return;
    }
  }
  const all = Array.isArray(_bbkQuotesCache) ? _bbkQuotesCache : [];

  // Empty-state — nothing to report
  const emptyEl = document.getElementById('bbkEmptyState');
  const finKpis = document.getElementById('bbkKpisFinancial');
  const wfKpis  = document.getElementById('bbkKpisWorkflow');
  const grid    = document.getElementById('bbkChartsGrid');
  const aging   = document.getElementById('bbkAgingTable')?.parentElement;
  if (!all.length) {
    if (emptyEl) emptyEl.style.display = '';
    [finKpis, wfKpis, grid, aging].forEach(el => { if (el) el.style.display = 'none'; });
    return;
  }
  if (emptyEl) emptyEl.style.display = 'none';
  if (finKpis) finKpis.style.display = 'grid';
  if (wfKpis)  wfKpis.style.display  = 'grid';
  if (grid)    grid.style.display    = '';
  if (aging)   aging.style.display   = '';

  // FY range
  const { fyStart, fyEnd, fyLabel } = getBabcockFYRange(_bbkFY);
  const fyLabelEl = document.getElementById('bbkFyLabel');
  if (fyLabelEl) {
    fyLabelEl.textContent = `${fyLabel} \u00b7 ${fyStart.toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' })} \u2192 ${fyEnd.toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' })}`;
  }

  // Filter into FY scope, with sensible fallbacks for rows that have no date
  const inFY = all.filter(q => inRange(babcockRowDate(q), fyStart, fyEnd));

  // ─── Financial KPIs (FY-scoped) ───
  const quotesValue = inFY.reduce((s, q) => s + (Number(q.total_value) || 0), 0);
  // What Babcock paid us (COUPA-side). Treat rows at or beyond Approved-to-Pay
  // as "invoiced"; treat rows at or beyond Payment Received as "paid".
  // NOTE: Bama SW PO Raised and Bama SW Invoice Received now sit BEFORE
  // Approved to Pay in the workflow, so they are NOT counted as invoiced.
  const invoicedPaid = inFY
    .filter(q => ['Payment Received', 'Paid to Bama SW', 'Remittance Sent', 'Closed'].includes(q.status))
    .reduce((s, q) => s + (Number(q.coupa_invoice_gross_total) || Number(q.total_value) || 0), 0);

  // Total invoiced (raised), regardless of paid
  const invoicedTotal = inFY
    .filter(q => ['Approved to Pay', 'Payment Received', 'Paid to Bama SW', 'Remittance Sent', 'Closed'].includes(q.status))
    .reduce((s, q) => s + (Number(q.coupa_invoice_gross_total) || Number(q.total_value) || 0), 0);

  // Outstanding pipeline — non-terminal, non-cancelled
  const TERMINAL = new Set(['Closed', 'Cancelled']);
  const outstandingValue = inFY
    .filter(q => !TERMINAL.has(q.status))
    .reduce((s, q) => s + (Number(q.total_value) || 0), 0);

  // Margin — sum of (total_value − pretax_original) where markup_pct > 0
  const margin = inFY.reduce((s, q) => {
    const tv = Number(q.total_value) || 0;
    const mu = Number(q.markup_pct) || 0;
    if (mu <= 0) return s;
    const pretax = _r2(tv / (1 + mu / 100));
    return _r2(s + _r2(tv - pretax));
  }, 0);

  // Avg days to payment
  const paidWithDates = inFY.filter(q => q.payment_received_at && q.date_sent);
  const avgDays = paidWithDates.length
    ? paidWithDates.reduce((s, q) => {
        const sent = new Date(String(q.date_sent).split('T')[0]).getTime();
        const paid = new Date(String(q.payment_received_at).split('T')[0]).getTime();
        return s + Math.max(0, (paid - sent) / 86_400_000);
      }, 0) / paidWithDates.length
    : null;

  // Conversion rate — quotes that reached Live Project or beyond, in FY
  const reachedProject = inFY.filter(q =>
    BABCOCK_OPEN_PROJECT_STATUSES.includes(q.status)
    || BABCOCK_CLOSED_PROJECT_STATUSES.includes(q.status)
  ).length;
  const convPct = inFY.length ? (reachedProject / inFY.length) * 100 : 0;

  if (finKpis) {
    finKpis.innerHTML = [
      { label: 'Quotes raised',     value: fmtMoneyShort(quotesValue), sub: `${inFY.length} quote${inFY.length === 1 ? '' : 's'}`, color: 'var(--accent2)' },
      { label: 'Invoiced (paid)',   value: fmtMoneyShort(invoicedPaid), sub: 'Confirmed by Babcock',          color: 'var(--green)' },
      { label: 'Invoiced (raised)', value: fmtMoneyShort(invoicedTotal), sub: 'Submitted to COUPA',           color: '#6366f1' },
      { label: 'Outstanding',       value: fmtMoneyShort(outstandingValue), sub: 'Pipeline in flight',        color: 'var(--amber)' },
      { label: 'Bama SW margin',    value: fmtMoneyShort(margin),       sub: 'Markup kept on quotes',         color: 'var(--accent)' },
      { label: 'Conversion rate',   value: convPct.toFixed(0) + '%',    sub: `${reachedProject}/${inFY.length} converted`, color: convPct >= 70 ? 'var(--green)' : convPct >= 40 ? 'var(--amber)' : 'var(--red)' },
      { label: 'Avg days to pay',   value: avgDays != null ? Math.round(avgDays) + 'd' : '—', sub: avgDays != null ? `${paidWithDates.length} paid invoice${paidWithDates.length === 1 ? '' : 's'}` : 'No paid invoices yet', color: avgDays == null ? 'var(--muted)' : avgDays <= 30 ? 'var(--green)' : avgDays <= 60 ? 'var(--amber)' : 'var(--red)' }
    ].map(k => `
      <div style="background:var(--card);border:1px solid var(--border);border-radius:8px;padding:10px 12px">
        <div style="font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.8px;margin-bottom:4px">${k.label}</div>
        <div style="font-family:var(--font-display);font-size:20px;color:${k.color};line-height:1.1">${k.value}</div>
        <div style="font-size:10px;color:var(--subtle);margin-top:3px">${k.sub}</div>
      </div>
    `).join('');
  }

  // ─── Workflow KPIs (current snapshot, not FY-filtered) ───
  // These reflect "what's on my plate right now" so they intentionally
  // bypass the FY toggle. A 2-year-old quote that's still Live Project
  // is still relevant to operations today.
  const openQuotes      = all.filter(q => BABCOCK_OPEN_QUOTE_STATUSES.includes(q.status));
  const openProjects    = all.filter(q => BABCOCK_OPEN_PROJECT_STATUSES.includes(q.status));
  const closedProjects  = all.filter(q => BABCOCK_CLOSED_PROJECT_STATUSES.includes(q.status));
  const invoicesDue     = all.filter(q => q.status === 'Approved to Pay');
  const invoicesDueVal  = invoicesDue.reduce((s, q) => s + (Number(q.coupa_invoice_gross_total) || Number(q.total_value) || 0), 0);
  const openQuotesVal   = openQuotes.reduce((s, q) => s + (Number(q.total_value) || 0), 0);
  const openProjectsVal = openProjects.reduce((s, q) => s + (Number(q.total_value) || 0), 0);

  if (wfKpis) {
    wfKpis.innerHTML = [
      { label: 'Open quotes',     value: String(openQuotes.length),     sub: fmtMoneyShort(openQuotesVal) + ' in pipeline', color: 'var(--accent2)' },
      { label: 'Open projects',   value: String(openProjects.length),   sub: fmtMoneyShort(openProjectsVal) + ' active',    color: '#6366f1' },
      { label: 'Closed projects', value: String(closedProjects.length), sub: 'Awaiting / in finance',                       color: 'var(--muted)' },
      { label: 'Invoices due',    value: String(invoicesDue.length),    sub: fmtMoneyShort(invoicesDueVal) + ' total',      color: invoicesDue.length ? 'var(--amber)' : 'var(--green)' }
    ].map(k => `
      <div style="background:var(--card);border:1px solid var(--border);border-radius:8px;padding:10px 12px">
        <div style="font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.8px;margin-bottom:4px">${k.label}</div>
        <div style="font-family:var(--font-display);font-size:24px;color:${k.color};line-height:1.1">${k.value}</div>
        <div style="font-size:10px;color:var(--subtle);margin-top:3px">${k.sub}</div>
      </div>
    `).join('');
  }

  // ─── Destroy old charts before redraw ───
  Object.values(_bbkCharts).forEach(c => { try { c.destroy(); } catch {} });
  _bbkCharts = {};

  // ─── Month buckets (still used by cash flow chart below) ───
  // 12-month bucket array starting from fyStart. Pre-computed once and
  // reused by the cash-flow chart further down. The monthly-trend chart
  // that used to use this directly has been removed.
  const months = [];
  for (let i = 0; i < 12; i++) {
    const m = new Date(fyStart.getFullYear(), fyStart.getMonth() + i, 1);
    months.push({
      label: m.toLocaleDateString('en-GB', { month: 'short' }) + ' ' + String(m.getFullYear() % 100).padStart(2, '0'),
      key:   `${m.getFullYear()}-${String(m.getMonth() + 1).padStart(2, '0')}`
    });
  }

  // Resolved theme colours for chart text — Chart.js does NOT parse CSS
  // variables (they fall through to its default of black, invisible on
  // our dark theme). Resolve once up-front and reuse across all charts.
  const cMuted   = cssVar('--muted',   '#888');
  const cText    = cssVar('--text',    '#eee');
  const cAccent  = cssVar('--accent',  '#ff6b00');
  const cAccent2 = cssVar('--accent2', '#00b3ee');
  const cGreen   = cssVar('--green',   '#2ecc71');
  const cBorder  = 'rgba(255,255,255,.06)';

  // ─── Pipeline funnel (status counts, current snapshot — not FY-filtered) ───
  const STATUS_ORDER = [
    'Quote Received', 'Quote Sent', 'Live Project', 'Project Complete',
    'Bama SW PO Raised', 'Bama SW Invoice Received', 'Approved to Pay',
    'Payment Received', 'Paid to Bama SW', 'Remittance Sent', 'Closed', 'Cancelled'
  ];
  // Status colour map mirrors the badge palette in babcock.html so users
  // recognise statuses across pages.
  const STATUS_COLOURS = {
    'Quote Received':            'rgba(255,193,7,.7)',   // amber
    'Quote Sent':                'rgba(255,107,0,.7)',   // orange
    'Live Project':              'rgba(0,153,255,.7)',   // blue
    'Project Complete':          'rgba(155,89,182,.7)',  // purple
    'Approved to Pay':           'rgba(26,188,156,.7)',  // teal
    'Payment Received':          'rgba(46,204,113,.7)',  // green
    'Bama SW PO Raised':         'rgba(52,152,219,.7)',  // blue
    'Bama SW Invoice Received':  'rgba(230,126,34,.7)',  // orange
    'Paid to Bama SW':           'rgba(39,174,96,.7)',   // green
    'Remittance Sent':           'rgba(149,165,166,.7)', // gray
    'Closed':                    'rgba(100,100,100,.7)', // dark gray
    'Cancelled':                 'rgba(127,140,141,.7)'  // grey
  };
  const funnelCounts = STATUS_ORDER.map(s => all.filter(q => q.status === s).length);
  const funnelCtx = document.getElementById('bbkChartFunnel');
  if (funnelCtx) {
    _bbkCharts.funnel = new Chart(funnelCtx, {
      type: 'bar',
      data: {
        labels: STATUS_ORDER,
        datasets: [{
          label: 'Quotes',
          data: funnelCounts,
          backgroundColor: STATUS_ORDER.map(s => STATUS_COLOURS[s]),
          borderColor: STATUS_ORDER.map(s => STATUS_COLOURS[s]),
          borderRadius: 4
        }]
      },
      options: {
        indexAxis: 'y',
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
          x: { beginAtZero: true, ticks: { color: cMuted, precision: 0, font: { size: 10 } }, grid: { color: cBorder } },
          y: { ticks: { color: cMuted, font: { size: 10 } }, grid: { display: false } }
        }
      }
    });
  }

  // ─── Cash flow (money in vs money out per month, FY-scoped) ───
  const cashMonths = months.map(m => ({ label: m.label, key: m.key, moneyIn: 0, moneyOut: 0 }));
  // Money in = COUPA payment received in that month
  // Money out = Bama SW invoice sent in that month
  // (Both timestamps are stored on the BabcockQuotes row.)
  for (const q of all) {
    if (q.payment_received_at) {
      const d = new Date(String(q.payment_received_at).split('T')[0] + 'T00:00:00');
      if (inRange(d, fyStart, fyEnd)) {
        const idx = cashMonths.findIndex(b => b.key === `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`);
        if (idx >= 0) cashMonths[idx].moneyIn += (Number(q.coupa_invoice_gross_total) || Number(q.total_value) || 0);
      }
    }
    if (q.bama_sw_invoice_sent_at) {
      const d = new Date(String(q.bama_sw_invoice_sent_at).split('T')[0] + 'T00:00:00');
      if (inRange(d, fyStart, fyEnd)) {
        const idx = cashMonths.findIndex(b => b.key === `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`);
        if (idx >= 0) {
          const tv = Number(q.total_value) || 0;
          const mu = Number(q.markup_pct) || 0;
          // Bama SW gets the original pre-markup value (per the invoice flow)
          cashMonths[idx].moneyOut += mu > 0 ? tv / (1 + mu / 100) : tv;
        }
      }
    }
  }
  const cashCtx = document.getElementById('bbkChartCashflow');
  if (cashCtx) {
    _bbkCharts.cash = new Chart(cashCtx, {
      type: 'bar',
      data: {
        labels: cashMonths.map(b => b.label),
        datasets: [
          { label: 'In (COUPA paid)',  data: cashMonths.map(b => b.moneyIn),  backgroundColor: 'rgba(46,204,113,.7)',  borderRadius: 4 },
          { label: 'Out (Bama SW)',    data: cashMonths.map(b => b.moneyOut), backgroundColor: 'rgba(231,76,153,.7)', borderRadius: 4 }
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { position: 'bottom', labels: { color: cMuted, font: { size: 11 } } } },
        scales: {
          x: { ticks: { color: cMuted, font: { size: 10 } }, grid: { display: false } },
          y: { beginAtZero: true, ticks: { color: cMuted, font: { size: 10 }, callback: v => fmtMoneyShort(v) }, grid: { color: cBorder } }
        }
      }
    });
  }

  // ─── Aging table — invoices needing attention ───
  // Group Approved-to-Pay rows by how close to / past their due date.
  // Non-FY-filtered — overdue invoices need attention regardless of FY.
  const agingEl = document.getElementById('bbkAgingTable');
  if (agingEl) {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const rows = invoicesDue.map(q => {
      const dueRaw = q.coupa_invoice_due_date ? String(q.coupa_invoice_due_date).split('T')[0] : null;
      const due = dueRaw ? new Date(dueRaw + 'T00:00:00') : null;
      const daysToDue = due ? Math.round((due - today) / 86_400_000) : null;
      let bucket, bucketColor;
      if (daysToDue == null) { bucket = 'No due date'; bucketColor = 'var(--muted)'; }
      else if (daysToDue < 0)   { bucket = `Overdue ${-daysToDue}d`;  bucketColor = 'var(--red)'; }
      else if (daysToDue <= 7)  { bucket = `Due in ${daysToDue}d`;    bucketColor = 'var(--amber)'; }
      else                       { bucket = `Due in ${daysToDue}d`;    bucketColor = 'var(--muted)'; }
      return {
        quote_ref: q.quote_ref, due, daysToDue, bucket, bucketColor,
        value: Number(q.coupa_invoice_gross_total) || Number(q.total_value) || 0,
        customer: q.quote_for_area || '—',
        invoiceNumber: q.coupa_invoice_number || '—'
      };
    }).sort((a, b) => {
      // Sort: overdue first (most overdue first), then due-soon, then no-date
      if (a.daysToDue == null && b.daysToDue == null) return 0;
      if (a.daysToDue == null) return 1;
      if (b.daysToDue == null) return -1;
      return a.daysToDue - b.daysToDue;
    });
    if (!rows.length) {
      agingEl.innerHTML = `<div style="text-align:center;padding:30px 10px;color:var(--muted);font-size:13px">
        <span style="font-size:28px;display:block;margin-bottom:10px">\u2705</span>
        No invoices currently approved-to-pay.
      </div>`;
    } else {
      agingEl.innerHTML = `
        <table style="width:100%;border-collapse:collapse;font-size:13px">
          <thead>
            <tr style="color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.5px">
              <th style="text-align:left;padding:8px 10px;border-bottom:1px solid var(--border)">Quote</th>
              <th style="text-align:left;padding:8px 10px;border-bottom:1px solid var(--border)">Invoice</th>
              <th style="text-align:left;padding:8px 10px;border-bottom:1px solid var(--border)">Customer / area</th>
              <th style="text-align:left;padding:8px 10px;border-bottom:1px solid var(--border)">Status</th>
              <th style="text-align:right;padding:8px 10px;border-bottom:1px solid var(--border)">Value</th>
            </tr>
          </thead>
          <tbody>
            ${rows.map(r => `
              <tr>
                <td style="padding:8px 10px;border-bottom:1px solid var(--border);font-family:var(--font-mono);color:var(--accent)">${escapeHtml(r.quote_ref || '')}</td>
                <td style="padding:8px 10px;border-bottom:1px solid var(--border);font-family:var(--font-mono);color:var(--muted)">${escapeHtml(r.invoiceNumber)}</td>
                <td style="padding:8px 10px;border-bottom:1px solid var(--border)">${escapeHtml(r.customer)}</td>
                <td style="padding:8px 10px;border-bottom:1px solid var(--border);color:${r.bucketColor};font-weight:600">${r.bucket}</td>
                <td style="padding:8px 10px;border-bottom:1px solid var(--border);text-align:right;font-family:var(--font-mono)">${fmtMoneyFull(r.value)}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>`;
    }
  }
}

// ═══════════════════════════════════════════
// ATTENDANCE REPORT
// ═══════════════════════════════════════════
function getExpectedStart() {
  return (state.timesheetData.settings && state.timesheetData.settings.attendanceStartTime) || '07:00';
}

function getAttendanceData(empFilter) {
  const { from, to } = getReportDateRange();
  const expectedStart = getExpectedStart();
  const [expH, expM] = expectedStart.split(':').map(Number);
  const expMins = expH * 60 + expM;

  const employees = (state.timesheetData.employees || [])
    .filter(e => e.active !== false && (!empFilter || e.name === empFilter));

  const clockings = state.timesheetData.clockings || [];
  const holidays = (state.timesheetData.holidays || []).filter(h => h.status === 'approved');

  // Sick days — approved holidays with type 'sick' in range
  const sickHolidays = holidays.filter(h =>
    h.type === 'sick' && h.dateTo >= from && h.dateFrom <= to &&
    (!empFilter || h.employeeName === empFilter)
  );
  const totalSickDays = sickHolidays.reduce((s, h) => s + (h.workingDays || countWorkingDays(h.dateFrom, h.dateTo)), 0);

  // Holidays taken (paid + half) in range
  const paidHolidays = holidays.filter(h =>
    (h.type === 'paid' || h.type === 'half') && h.dateTo >= from && h.dateFrom <= to &&
    (!empFilter || h.employeeName === empFilter)
  );
  const totalHolidayDays = paidHolidays.reduce((s, h) => s + (h.workingDays || countWorkingDays(h.dateFrom, h.dateTo)), 0);

  // Holiday balance (sum remaining across filtered employees)
  let totalHolidayBalance = 0;
  employees.forEach(emp => {
    const bal = calculateHolidayBalance(emp.name);
    if (bal) totalHolidayBalance += bal.remainingDays;
  });

  // Build absences list for the table
  const absenceList = sickHolidays.map(h => ({
    name: h.employeeName,
    dateFrom: h.dateFrom,
    dateTo: h.dateTo,
    days: h.workingDays || countWorkingDays(h.dateFrom, h.dateTo),
    reason: h.reason || ''
  })).sort((a, b) => b.dateFrom.localeCompare(a.dateFrom));

  // Build list of working days (Mon-Fri) in period up to today
  const workDays = [];
  const d = new Date(from + 'T12:00:00');
  const end = new Date(to + 'T12:00:00');
  while (d <= end) {
    const dow = d.getDay();
    if (dow >= 1 && dow <= 5) workDays.push(dateStr(d));
    d.setDate(d.getDate() + 1);
  }
  const today = todayStr();
  const relevantDays = workDays.filter(wd => wd <= today);

  let totalLate = 0;
  const lateList = [];

  // Late arrivals and avg shift length
  let totalShiftMins = 0, shiftCount = 0;
  employees.forEach(emp => {
    const empClockings = clockings.filter(c => c.employeeName === emp.name);
    relevantDays.forEach(day => {
      const dayClockings = empClockings
        .filter(c => c.date === day && c.clockIn)
        .sort((a, b) => a.clockIn.localeCompare(b.clockIn));
      if (!dayClockings.length) return;

      const firstIn = dayClockings[0].clockIn;
      const [inH, inM] = firstIn.split(':').map(Number);
      const inMins = inH * 60 + inM;

      // Calculate shift length from earliest clock with a clock-out
      const completed = empClockings.filter(c => c.date === day && c.clockIn && c.clockOut);
      if (completed.length) {
        const hrs = completed.reduce((s, c) => s + (calcHours(c.clockIn, c.clockOut, c.breakMins, c.date) || 0), 0);
        if (hrs > 0) { totalShiftMins += hrs * 60; shiftCount++; }
      }

      if (inMins > expMins) {
        totalLate++;
        lateList.push({ name: emp.name, date: day, clockIn: firstIn, minsLate: inMins - expMins });
      }
    });
  });

  const avgShiftMins = shiftCount ? Math.round(totalShiftMins / shiftCount) : 0;
  const avgShiftH = Math.floor(avgShiftMins / 60);
  const avgShiftM = avgShiftMins % 60;
  const avgShiftLength = `${avgShiftH}h ${avgShiftM}m`;

  // Attendance rate: (days with a clocking) / (working days × employees), excluding holidays & sick
  let totalPossible = 0, totalPresent = 0;
  employees.forEach(emp => {
    const empClockings = clockings.filter(c => c.employeeName === emp.name);
    const empHolidays = holidays.filter(h => h.employeeName === emp.name);
    relevantDays.forEach(day => {
      const onLeave = empHolidays.some(h => day >= h.dateFrom && day <= h.dateTo);
      if (onLeave) return; // don't count leave days in attendance rate
      totalPossible++;
      if (empClockings.some(c => c.date === day && c.clockIn)) totalPresent++;
    });
  });
  const attendanceRate = totalPossible > 0 ? Math.round((totalPresent / totalPossible) * 100) : 100;

  return {
    totalSickDays, totalHolidayDays, totalHolidayBalance,
    totalLate, attendanceRate, avgShiftLength, lateList, absenceList,
    expectedStart
  };
}

function renderAttendanceReport(empFilter) {
  const data = getAttendanceData(empFilter);

  // KPI cards
  const kpiRow = document.getElementById('rptAttendanceKpis');
  if (kpiRow) {
    const periodLabels = { week: 'This Week', month: 'This Month', year: 'This Year' };
    let periodLabel = periodLabels[rptPeriod];
    if (rptOffset !== 0) {
      const { from, to } = getReportDateRange();
      if (rptPeriod === 'week') periodLabel = `Week of ${fmtDateStr(from)}`;
      else if (rptPeriod === 'month') {
        const d = new Date(from + 'T12:00:00');
        periodLabel = d.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
      } else periodLabel = from.slice(0, 4);
    }
    kpiRow.innerHTML = [
      { label: 'Attendance Rate', value: data.attendanceRate + '%', color: data.attendanceRate >= 95 ? 'var(--green)' : data.attendanceRate >= 85 ? 'var(--amber)' : 'var(--red)' },
      { label: 'Days Absent', value: data.totalSickDays, color: data.totalSickDays > 0 ? 'var(--red)' : 'var(--green)' },
      { label: 'Late Arrivals', value: data.totalLate, color: data.totalLate > 0 ? 'var(--amber)' : 'var(--green)' },
      { label: 'Holidays Taken', value: data.totalHolidayDays, color: '#6366f1' },
      { label: 'Holiday Balance', value: data.totalHolidayBalance, color: data.totalHolidayBalance > 0 ? 'var(--green)' : 'var(--red)' },
      { label: 'Avg Shift Length', value: data.avgShiftLength, color: 'var(--accent2)' },
    ].map(k => `
      <div style="background:var(--card);border:1px solid var(--border);border-radius:10px;padding:16px 18px">
        <div style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:1px;margin-bottom:6px">${k.label}</div>
        <div style="font-family:var(--font-display);font-size:30px;color:${k.color}">${k.value}</div>
        <div style="font-size:10px;color:var(--subtle);margin-top:4px">${periodLabel}</div>
      </div>
    `).join('');
  }

  // Late arrivals table
  const lateEl = document.getElementById('rptLateArrivals');
  if (lateEl) {
    if (!data.lateList.length) {
      lateEl.innerHTML = `<div style="text-align:center;color:var(--muted);padding:24px;font-size:13px">No late arrivals — everyone on time! Expected start: ${data.expectedStart}</div>`;
    } else {
      const sorted = [...data.lateList].sort((a, b) => b.minsLate - a.minsLate);
      const lateRows = sorted.map(l => {
        const minsStr = l.minsLate >= 60 ? `${Math.floor(l.minsLate / 60)}h ${l.minsLate % 60}m` : `${l.minsLate}m`;
        return `<tr>
          <td style="padding:8px 12px;font-size:13px;color:var(--text)">${l.name}</td>
          <td style="padding:8px 12px;font-size:13px;color:var(--muted)">${fmtDateStr(l.date)}</td>
          <td style="padding:8px 12px;font-size:13px;color:var(--muted)">${l.clockIn}</td>
          <td style="padding:8px 12px;font-size:13px;color:var(--amber);font-weight:600">+${minsStr}</td>
        </tr>`;
      }).join('');
      lateEl.innerHTML = `
        <div style="font-size:11px;color:var(--subtle);margin-bottom:10px">Expected start: ${data.expectedStart} — sorted by latest arrival</div>
        <table style="width:100%;border-collapse:collapse">
          <thead><tr>
            <th style="text-align:left;font-size:11px;color:var(--muted);padding:6px 12px;border-bottom:1px solid var(--border)">Employee</th>
            <th style="text-align:left;font-size:11px;color:var(--muted);padding:6px 12px;border-bottom:1px solid var(--border)">Date</th>
            <th style="text-align:left;font-size:11px;color:var(--muted);padding:6px 12px;border-bottom:1px solid var(--border)">Clock In</th>
            <th style="text-align:left;font-size:11px;color:var(--muted);padding:6px 12px;border-bottom:1px solid var(--border)">Late By</th>
          </tr></thead>
          <tbody>${lateRows}</tbody>
        </table>`;
    }
  }

  // Absences table
  const absEl = document.getElementById('rptAbsences');
  if (absEl) {
    if (!data.absenceList.length) {
      absEl.innerHTML = '<div style="text-align:center;color:var(--muted);padding:24px;font-size:13px">No sick leave recorded in this period</div>';
    } else {
      const absRows = data.absenceList.map(a => {
        const rangeStr = a.dateFrom === a.dateTo ? fmtDateStr(a.dateFrom) : `${fmtDateStr(a.dateFrom)} – ${fmtDateStr(a.dateTo)}`;
        return `<tr>
          <td style="padding:8px 12px;font-size:13px;color:var(--text)">${a.name}</td>
          <td style="padding:8px 12px;font-size:13px;color:var(--muted)">${rangeStr}</td>
          <td style="padding:8px 12px;font-size:13px;color:var(--red);font-weight:600">${a.days} day${a.days !== 1 ? 's' : ''}</td>
          <td style="padding:8px 12px;font-size:13px;color:var(--muted)">${a.reason || '—'}</td>
        </tr>`;
      }).join('');
      absEl.innerHTML = `
        <table style="width:100%;border-collapse:collapse">
          <thead><tr>
            <th style="text-align:left;font-size:11px;color:var(--muted);padding:6px 12px;border-bottom:1px solid var(--border)">Employee</th>
            <th style="text-align:left;font-size:11px;color:var(--muted);padding:6px 12px;border-bottom:1px solid var(--border)">Dates</th>
            <th style="text-align:left;font-size:11px;color:var(--muted);padding:6px 12px;border-bottom:1px solid var(--border)">Duration</th>
            <th style="text-align:left;font-size:11px;color:var(--muted);padding:6px 12px;border-bottom:1px solid var(--border)">Reason</th>
          </tr></thead>
          <tbody>${absRows}</tbody>
        </table>`;
    }
  }
}

// ═══════════════════════════════════════════
// HOLIDAY REPORT (reports.html)
// ═══════════════════════════════════════════
// Shows per-employee entitlement, carry-over, taken, pending and remaining
// balance for the current holiday year. Does not depend on a selected period —
// it reads directly from employee.holidayBalance and filters the holidays array
// to the current holiday year for pending counts.

function renderHolidayReport() {
  const panel = document.getElementById('rptPanel-holidays');
  if (!panel) return;

  const employees = (state.timesheetData.employees || [])
    .filter(e => e.active !== false)
    .sort((a, b) => a.name.localeCompare(b.name));

  const holidays = state.timesheetData.holidays || [];

  // Current holiday year bounds
  const yearStart = new Date(HOLIDAY_YEAR_START + 'T00:00:00');
  const yearEnd   = new Date(yearStart);
  yearEnd.setFullYear(yearEnd.getFullYear() + 1);

  // Sum pending paid-holiday working_days per employee within the current year
  const pendingByEmp = {};
  holidays.forEach(h => {
    if (h.type !== 'paid' && h.type !== 'half') return;
    if (h.status !== 'pending') return;
    const from = new Date(h.dateFrom + 'T00:00:00');
    if (from < yearStart || from >= yearEnd) return;
    pendingByEmp[h.employeeName] = (pendingByEmp[h.employeeName] || 0) + (h.workingDays || 0);
  });

  // Build per-employee data rows
  const rows = employees.map(emp => {
    const entitlement  = emp.annualDays    || 28;
    const carryover    = emp.carryoverDays || 0;
    const totalAllowed = entitlement + carryover;
    const balance      = emp.holidayBalance || 0;
    const taken        = Math.max(0, Math.round((totalAllowed - balance) * 10) / 10);
    const pending      = Math.round((pendingByEmp[emp.name] || 0) * 10) / 10;
    return { name: emp.name, entitlement, carryover, totalAllowed, taken, pending, balance };
  });

  // KPI summary tiles
  const totalEntitlement = rows.reduce((s, r) => s + r.totalAllowed, 0);
  const totalTaken       = rows.reduce((s, r) => s + r.taken, 0);
  const totalBalance     = rows.reduce((s, r) => s + r.balance, 0);
  const totalPending     = rows.reduce((s, r) => s + r.pending, 0);
  const lowCount         = rows.filter(r => r.balance < 5).length;

  const yearEndStr = yearEnd.toISOString().split('T')[0];

  const kpis = [
    { label: 'Employees',          value: rows.length,                color: 'var(--accent2)', sub: 'Active staff' },
    { label: 'Total Entitlement',  value: totalEntitlement + 'd',     color: 'var(--green)',   sub: 'Inc. carry-over' },
    { label: 'Total Taken',        value: totalTaken + 'd',           color: '#6366f1',        sub: 'Approved this year' },
    { label: 'Total Remaining',    value: totalBalance + 'd',         color: totalBalance > 0 ? 'var(--green)' : 'var(--red)', sub: 'All staff combined' },
    { label: 'Pending Approval',   value: totalPending + 'd',         color: 'var(--amber)',   sub: 'Awaiting decision' },
    { label: 'Low Balance (< 5d)', value: lowCount,                   color: lowCount > 0 ? 'var(--red)' : 'var(--green)', sub: 'Staff at risk' },
  ];

  const kpiHTML = kpis.map(k => `
    <div style="background:var(--card);border:1px solid var(--border);border-radius:10px;padding:16px 18px">
      <div style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:1px;margin-bottom:6px">${k.label}</div>
      <div style="font-family:var(--font-display);font-size:30px;color:${k.color}">${k.value}</div>
      <div style="font-size:10px;color:var(--subtle);margin-top:4px">${k.sub}</div>
    </div>
  `).join('');

  // Table rows
  const tableRows = rows.length === 0
    ? `<tr><td colspan="7" style="padding:24px;text-align:center;color:var(--muted);font-size:13px">No active employees found</td></tr>`
    : rows.map(r => {
        const pct      = r.totalAllowed > 0 ? Math.min(100, Math.round((r.taken / r.totalAllowed) * 100)) : 0;
        const barColor = pct >= 80 ? 'var(--red)' : pct >= 50 ? 'var(--amber)' : '#6366f1';
        const balColor = r.balance < 5 ? 'var(--red)' : r.balance < 10 ? 'var(--amber)' : 'var(--green)';
        return `<tr style="border-bottom:1px solid var(--border)">
          <td style="padding:10px 12px;font-size:13px;color:var(--text);font-weight:500">${r.name}</td>
          <td style="padding:10px 12px;font-size:13px;color:var(--muted);text-align:right">${r.entitlement}d</td>
          <td style="padding:10px 12px;font-size:13px;color:${r.carryover > 0 ? 'var(--accent2)' : 'var(--subtle)'};text-align:right">${r.carryover > 0 ? '+' + r.carryover + 'd' : '—'}</td>
          <td style="padding:10px 12px;font-size:13px;color:#6366f1;text-align:right;font-weight:600">${r.taken}d</td>
          <td style="padding:10px 12px;font-size:13px;color:${r.pending > 0 ? 'var(--amber)' : 'var(--subtle)'};text-align:right">${r.pending > 0 ? r.pending + 'd' : '—'}</td>
          <td style="padding:10px 12px;font-size:13px;font-weight:600;color:${balColor};text-align:right">${r.balance}d</td>
          <td style="padding:10px 12px">
            <div style="display:flex;align-items:center;gap:8px">
              <div style="flex:1;height:6px;background:var(--border);border-radius:3px;overflow:hidden">
                <div style="height:100%;width:${pct}%;background:${barColor};border-radius:3px"></div>
              </div>
              <span style="font-size:11px;color:var(--muted);min-width:28px;text-align:right">${pct}%</span>
            </div>
          </td>
        </tr>`;
      }).join('');

  panel.innerHTML = `
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:24px">
      ${kpiHTML}
    </div>

    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
      <div style="font-size:12px;color:var(--muted)">
        Holiday year: <span style="color:var(--text)">${HOLIDAY_YEAR_START} → ${yearEndStr}</span>
      </div>
      <button class="btn btn-ghost" onclick="exportHolidayReportPDF()" style="padding:6px 16px;font-size:12px">&#128438; Export PDF</button>
    </div>

    <div class="card" style="padding:20px">
      <div class="card-title" style="margin-bottom:4px"><span class="icon">🗓️</span> Holiday Balances</div>
      <div style="font-size:12px;color:var(--muted);margin-bottom:16px">
        Entitlement, carry-over, taken and remaining balance per employee for the current holiday year
      </div>
      <table style="width:100%;border-collapse:collapse">
        <thead><tr>
          <th style="text-align:left;font-size:11px;color:var(--muted);padding:8px 12px;border-bottom:1px solid var(--border)">Employee</th>
          <th style="text-align:right;font-size:11px;color:var(--muted);padding:8px 12px;border-bottom:1px solid var(--border)">Entitlement</th>
          <th style="text-align:right;font-size:11px;color:var(--muted);padding:8px 12px;border-bottom:1px solid var(--border)">Carry Over</th>
          <th style="text-align:right;font-size:11px;color:var(--muted);padding:8px 12px;border-bottom:1px solid var(--border)">Taken</th>
          <th style="text-align:right;font-size:11px;color:var(--muted);padding:8px 12px;border-bottom:1px solid var(--border)">Pending</th>
          <th style="text-align:right;font-size:11px;color:var(--muted);padding:8px 12px;border-bottom:1px solid var(--border)">Balance</th>
          <th style="text-align:left;font-size:11px;color:var(--muted);padding:8px 12px;border-bottom:1px solid var(--border);min-width:140px">Used</th>
        </tr></thead>
        <tbody>${tableRows}</tbody>
      </table>
    </div>
  `;
}

async function exportHolidayReportPDF() {
  await loadLogoDataUri();

  const employees = (state.timesheetData.employees || [])
    .filter(e => e.active !== false)
    .sort((a, b) => a.name.localeCompare(b.name));

  const holidays = state.timesheetData.holidays || [];

  const yearStart = new Date(HOLIDAY_YEAR_START + 'T00:00:00');
  const yearEnd   = new Date(yearStart);
  yearEnd.setFullYear(yearEnd.getFullYear() + 1);
  const yearEndStr = yearEnd.toISOString().split('T')[0];

  const pendingByEmp = {};
  holidays.forEach(h => {
    if (h.type !== 'paid' && h.type !== 'half') return;
    if (h.status !== 'pending') return;
    const from = new Date(h.dateFrom + 'T00:00:00');
    if (from < yearStart || from >= yearEnd) return;
    pendingByEmp[h.employeeName] = (pendingByEmp[h.employeeName] || 0) + (h.workingDays || 0);
  });

  const rows = employees.map(emp => {
    const entitlement  = emp.annualDays    || 28;
    const carryover    = emp.carryoverDays || 0;
    const totalAllowed = entitlement + carryover;
    const balance      = emp.holidayBalance || 0;
    const taken        = Math.max(0, Math.round((totalAllowed - balance) * 10) / 10);
    const pending      = Math.round((pendingByEmp[emp.name] || 0) * 10) / 10;
    return { name: emp.name, entitlement, carryover, totalAllowed, taken, pending, balance };
  });

  const logoSrc = _logoDataUriCache || '';
  const now = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' });

  const tableRows = rows.map(r => {
    const pct = r.totalAllowed > 0 ? Math.min(100, Math.round((r.taken / r.totalAllowed) * 100)) : 0;
    const balColor = r.balance < 5 ? '#dc2626' : r.balance < 10 ? '#d97706' : '#16a34a';
    return `<tr>
      <td>${r.name}</td>
      <td style="text-align:right">${r.entitlement}d</td>
      <td style="text-align:right">${r.carryover > 0 ? '+' + r.carryover + 'd' : '—'}</td>
      <td style="text-align:right">${r.taken}d</td>
      <td style="text-align:right">${r.pending > 0 ? r.pending + 'd' : '—'}</td>
      <td style="text-align:right;font-weight:600;color:${balColor}">${r.balance}d</td>
      <td style="text-align:right">${pct}%</td>
    </tr>`;
  }).join('');

  const html = `<!DOCTYPE html><html><head><meta charset="utf-8">
  <title>Holiday Report</title>
  <style>
    body { font-family: Arial, sans-serif; font-size: 12px; color: #111; margin: 0; padding: 24px; }
    .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 24px; border-bottom: 2px solid #1a3a5c; padding-bottom: 16px; }
    .header img { height: 48px; }
    .header-right { text-align: right; }
    h2 { margin: 0 0 4px; font-size: 18px; color: #1a3a5c; }
    .sub { color: #555; font-size: 11px; }
    table { width: 100%; border-collapse: collapse; margin-top: 16px; }
    thead th { background: #1a3a5c; color: #fff; padding: 8px 10px; font-size: 11px; text-align: right; }
    thead th:first-child { text-align: left; }
    tbody tr:nth-child(even) { background: #f8f9fa; }
    tbody td { padding: 7px 10px; border-bottom: 1px solid #e2e8f0; font-size: 12px; }
    tfoot td { padding: 8px 10px; font-weight: 600; border-top: 2px solid #1a3a5c; text-align: right; font-size: 12px; }
    tfoot td:first-child { text-align: left; }
    @media print { body { padding: 0; } }
  </style>
  </head><body>
  <div class="header">
    ${logoSrc ? `<img src="${logoSrc}" alt="BAMA">` : '<div style="font-size:20px;font-weight:700;color:#1a3a5c">BAMA</div>'}
    <div class="header-right">
      <h2>Holiday Report</h2>
      <div class="sub">Holiday year: ${HOLIDAY_YEAR_START} → ${yearEndStr}</div>
      <div class="sub">Generated: ${now}</div>
    </div>
  </div>
  <table>
    <thead><tr>
      <th style="text-align:left">Employee</th>
      <th>Entitlement</th>
      <th>Carry Over</th>
      <th>Taken</th>
      <th>Pending</th>
      <th>Balance</th>
      <th>% Used</th>
    </tr></thead>
    <tbody>${tableRows}</tbody>
    <tfoot><tr>
      <td>Totals (${rows.length} employees)</td>
      <td>${rows.reduce((s,r)=>s+r.totalAllowed,0)}d</td>
      <td>${rows.reduce((s,r)=>s+r.carryover,0)}d</td>
      <td>${rows.reduce((s,r)=>s+r.taken,0)}d</td>
      <td>${rows.reduce((s,r)=>s+r.pending,0)}d</td>
      <td>${rows.reduce((s,r)=>s+r.balance,0)}d</td>
      <td></td>
    </tr></tfoot>
  </table>
  </body></html>`;

  const printWin = window.open('', '_blank');
  printWin.document.write(html + `<script>window.onload = function() { window.print(); }<\/script>`);
  printWin.document.close();
}

async function exportAttendancePDF() {
  const empFilter = document.getElementById('rptEmployeeFilter')?.value || '';
  const data = getAttendanceData(empFilter);
  const general = getPeriodData(empFilter);
  const { from, to } = getReportDateRange();
  const periodLabels = { week: 'This Week', month: 'This Month', year: 'This Year' };
  let periodLabel = periodLabels[rptPeriod];
  if (rptOffset !== 0) {
    if (rptPeriod === 'week') periodLabel = `Week of ${fmtDateStr(from)}`;
    else if (rptPeriod === 'month') {
      const d = new Date(from + 'T12:00:00');
      periodLabel = d.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
    } else periodLabel = from.slice(0, 4);
  }
  const filterLabel = empFilter ? ` — ${empFilter}` : ' — All Employees';

  await loadLogoDataUri();

  const html = buildAttendanceHTML({
    periodLabel,
    from: fmtDateStr(from),
    to: fmtDateStr(to),
    filterLabel,
    general,
    data
  });
  const printWin = window.open('', '_blank');
  printWin.document.write(html + `<script>window.onload = function() { window.print(); }<\/script>`);
  printWin.document.close();
}

// ═══════════════════════════════════════════
// TRACEABILITY — WELDING EQUIPMENT
// ═══════════════════════════════════════════
let _weldingMachines = [];

async function renderWeldingTab() {
  const container = document.getElementById('weldingMachineList');
  if (!container) return;
  try {
    _weldingMachines = await api.get('/api/welding-machines');
  } catch (e) {
    container.innerHTML = '<div class="empty-state">Failed to load welding machines</div>';
    return;
  }

  if (!_weldingMachines.length) {
    container.innerHTML = '<div class="empty-state" style="padding:30px"><div class="icon">&#128293;</div>No welding machines registered yet</div>';
    return;
  }

  container.innerHTML = _weldingMachines.map(m => {
    const expiry = m.expiry_date ? m.expiry_date.split('T')[0] : null;
    const isExpired = expiry && expiry < todayStr();
    const isExpiringSoon = expiry && !isExpired && expiry <= dateStr(new Date(Date.now() + 90 * 86400000));
    const expiryColor = isExpired ? 'var(--red)' : isExpiringSoon ? 'var(--amber)' : 'var(--green)';
    const expiryLabel = isExpired ? 'EXPIRED' : isExpiringSoon ? 'Expiring soon' : 'Valid';
    const welderNames = (m.welders || []).map(w => w.employee_name).join(', ') || 'None assigned';

    return `
      <div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:16px;margin-bottom:10px">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">
          <div>
            <div style="font-weight:600;font-size:15px;margin-bottom:2px">${m.machine_name}</div>
            <div style="font-size:12px;color:var(--muted);font-family:var(--font-mono)">S/N: ${m.serial_number || '—'}</div>
          </div>
          <div style="display:flex;gap:6px">
            <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick="editWeldingMachine(${m.id})">&#9998; Edit</button>
            <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px;color:var(--red)" onclick="deleteWeldingMachine(${m.id}, '${m.machine_name.replace(/'/g, "\\'")}')">&#10005;</button>
          </div>
        </div>
        <div style="display:flex;gap:20px;flex-wrap:wrap;font-size:13px;color:var(--muted)">
          <div>Expiry: <span style="color:${expiryColor};font-weight:600">${expiry ? fmtDateStr(expiry) : '—'}</span> <span style="font-size:10px;color:${expiryColor}">${expiry ? expiryLabel : ''}</span></div>
          <div>Authorised: <span style="color:var(--text)">${welderNames}</span></div>
        </div>
        ${m.notes ? `<div style="font-size:12px;color:var(--subtle);margin-top:6px">${m.notes}</div>` : ''}
      </div>`;
  }).join('');
}

function openAddWeldingMachineForm() {
  document.getElementById('weldEditId').value = '';
  document.getElementById('weldMachineName').value = '';
  document.getElementById('weldSerialNumber').value = '';
  document.getElementById('weldExpiryDate').value = '';
  document.getElementById('weldNotes').value = '';
  document.getElementById('weldingFormTitle').textContent = 'Add Welding Machine';
  populateWelderCheckboxes([]);
  document.getElementById('weldingMachineFormArea').style.display = 'block';
}

function closeWeldingMachineForm() {
  document.getElementById('weldingMachineFormArea').style.display = 'none';
}

function populateWelderCheckboxes(selectedIds) {
  const container = document.getElementById('weldWelderCheckboxes');
  if (!container) return;
  const cb = e => {
    const checked = selectedIds.includes(e.id) ? 'checked' : '';
    return `<label style="display:flex;align-items:center;gap:6px;font-size:13px;background:var(--card);border:1px solid var(--border);border-radius:8px;padding:6px 12px;cursor:pointer">
      <input type="checkbox" class="weld-welder-cb" value="${e.id}" ${checked}> ${e.name}
    </label>`;
  };
  const shop = [], office = [];
  for (const e of bookableShopStaff()) ((e.staffType || 'workshop') === 'workshop' ? shop : office).push(e);
  let html = shop.map(cb).join('');
  if (office.length) {
    html += `<div style="flex-basis:100%;font-size:10px;letter-spacing:0.08em;text-transform:uppercase;color:var(--muted);margin-top:4px">Office</div>`;
    html += office.map(cb).join('');
  }
  container.innerHTML = html;
}

async function editWeldingMachine(id) {
  try {
    const m = await api.get(`/api/welding-machines/${id}`);
    document.getElementById('weldEditId').value = m.id;
    document.getElementById('weldMachineName').value = m.machine_name || '';
    document.getElementById('weldSerialNumber').value = m.serial_number || '';
    document.getElementById('weldExpiryDate').value = m.expiry_date ? m.expiry_date.split('T')[0] : '';
    document.getElementById('weldNotes').value = m.notes || '';
    document.getElementById('weldingFormTitle').textContent = 'Edit Welding Machine';
    populateWelderCheckboxes((m.welders || []).map(w => w.employee_id));
    document.getElementById('weldingMachineFormArea').style.display = 'block';
  } catch (e) { toast('Failed to load machine details', 'error'); }
}

async function saveWeldingMachine() {
  const editId = document.getElementById('weldEditId').value;
  const machineName = document.getElementById('weldMachineName').value.trim();
  const serialNumber = document.getElementById('weldSerialNumber').value.trim();
  const expiryDate = document.getElementById('weldExpiryDate').value;
  const notes = document.getElementById('weldNotes').value.trim();
  const welderIds = [...document.querySelectorAll('.weld-welder-cb:checked')].map(cb => parseInt(cb.value));

  if (!machineName) { toast('Machine name is required', 'error'); return; }

  const body = { machine_name: machineName, serial_number: serialNumber, expiry_date: expiryDate || null, notes: notes || null, welder_ids: welderIds };

  try {
    if (editId) {
      await api.put(`/api/welding-machines/${editId}`, body);
      toast('Machine updated ✓', 'success');
    } else {
      await api.post('/api/welding-machines', body);
      toast('Machine added ✓', 'success');
    }
    closeWeldingMachineForm();
    renderWeldingTab();
  } catch (e) { toast('Save failed: ' + e.message, 'error'); }
}

async function deleteWeldingMachine(id, name) {
  if (!(await bamaConfirm({ title: 'Remove machine', body: `Remove "${name}" from the register?`, confirmText: 'Remove', tone: 'danger' }))) return;
  try {
    await api.delete(`/api/welding-machines/${id}`);
    toast('Machine removed', 'info');
    renderWeldingTab();
  } catch (e) { toast('Delete failed', 'error'); }
}

// ═══════════════════════════════════════════
// TRACEABILITY — SUPPLIERS
// ═══════════════════════════════════════════
let _suppliers = [];
let _supplierSortCol = 'name';   // 'name' | 'openPos' | 'openValue' | 'awaiting' | 'discrep'
let _supplierSortAsc = true;
let _supplierSearchTimeout = null;
let _supplierPoMap = {}; // supplier_id → PO summary, populated by renderSuppliersTab

function onSupplierSearchInput() {
  const input = document.getElementById('supplierSearch');
  const clear = document.getElementById('supplierSearchClear');
  if (clear) clear.style.display = input?.value ? '' : 'none';
  clearTimeout(_supplierSearchTimeout);
  _supplierSearchTimeout = setTimeout(_renderSupplierTable, 180);
}

function clearSupplierSearch() {
  const input = document.getElementById('supplierSearch');
  if (input) { input.value = ''; input.focus(); }
  const clear = document.getElementById('supplierSearchClear');
  if (clear) clear.style.display = 'none';
  const count = document.getElementById('supplierSearchCount');
  if (count) count.textContent = '';
  _renderSupplierTable();
}

function sortSupplierTable(col) {
  _supplierSortAsc = (_supplierSortCol === col) ? !_supplierSortAsc : (col === 'name');
  _supplierSortCol = col;
  _renderSupplierTable();
}
let _serviceTypes = [];

async function loadServiceTypes() {
  try { _serviceTypes = await api.get('/api/service-types'); } catch { _serviceTypes = []; }
}

async function renderSuppliersTab() {
  await loadServiceTypes();
  const container = document.getElementById('supplierList');
  if (!container) return;

  let allPos = [];
  try {
    _suppliers = await api.get('/api/suppliers');
  } catch (e) {
    container.innerHTML = '<div class="empty-state">Failed to load suppliers</div>';
    return;
  }

  // Fetch POs in background — failure here must not block the supplier list
  try {
    allPos = await api.get('/api/purchase-orders');
  } catch (e) {
    console.warn('PO data unavailable for supplier table:', e.message);
  }

  _supplierTilePos = allPos;
  _renderSupplierTilesFromCache();

  // Build per-supplier PO summary (used by _renderSupplierTable)
  const poGroup = po => {
    if (po.status === 'Cancelled' || po.status === 'Closed') return 'closed';
    if (po.reconciliation_status === 'matched')     return 'matched';
    if (po.reconciliation_status === 'discrepancy') return 'discrepancy';
    if (po.supplier_invoice_received_at)            return 'invoiced';
    return 'open';
  };
  _supplierPoMap = {};
  allPos.forEach(po => {
    if (!_supplierPoMap[po.supplier_id]) {
      _supplierPoMap[po.supplier_id] = { open: [], awaiting: [], discrep: [], spent: [], thisMonth: [], lastMonth: [], all: [] };
    }
    const m = _supplierPoMap[po.supplier_id];
    m.all.push(po);
    if (poGroup(po) === 'open') m.open.push(po);
    if (!po.supplier_invoice_received_at && po.status !== 'Cancelled' && po.status !== 'Closed') m.awaiting.push(po);
    if (poGroup(po) === 'discrepancy') m.discrep.push(po);
    if (po.status === 'Closed' || poGroup(po) === 'matched') m.spent.push(po);
    // Month buckets based on when the PO was closed/matched (updated_at as proxy)
    const poDate = new Date(po.updated_at || po.created_at);
    const now = new Date();
    const isThisMonth = poDate.getFullYear() === now.getFullYear() && poDate.getMonth() === now.getMonth();
    const lastMonthDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const isLastMonth = poDate.getFullYear() === lastMonthDate.getFullYear() && poDate.getMonth() === lastMonthDate.getMonth();
    if ((po.status === 'Closed' || poGroup(po) === 'matched') && isThisMonth) m.thisMonth.push(po);
    if ((po.status === 'Closed' || poGroup(po) === 'matched') && isLastMonth) m.lastMonth.push(po);
  });

  _renderSupplierTable();
  renderServiceTypeList();
}

// Separate render function so search/sort can re-run it without re-fetching
function _renderSupplierTable() {
  const container = document.getElementById('supplierList');
  if (!container || !_suppliers.length) return;

  const raw   = (document.getElementById('supplierSearch')?.value || '').trim().toLowerCase();
  const words = raw.split(/\s+/).filter(Boolean);

  // Filter by search
  let list = _suppliers.filter(s => {
    if (!words.length) return true;
    const hay = [
      s.supplier_name,
      s.contact_name  || '',
      s.telephone     || '',
      s.email         || '',
      s.city          || '',
      s.postcode      || '',
      (s.services || []).map(sv => sv.service_name).join(' ')
    ].join(' ').toLowerCase();
    return words.every(w => hay.includes(w));
  });

  // Update count badge
  const countEl = document.getElementById('supplierSearchCount');
  if (countEl) {
    countEl.textContent = words.length
      ? `${list.length} of ${_suppliers.length} suppliers`
      : '';
  }

  if (!list.length) {
    container.innerHTML = words.length
      ? `<div class="empty-state" style="padding:24px"><div class="icon">🔍</div>No suppliers match "${escapeHtml(raw)}"</div>`
      : '<div class="empty-state" style="padding:30px"><div class="icon">&#128666;</div>No suppliers registered yet</div>';
    return;
  }

  // Sort
  const col = _supplierSortCol;
  const asc = _supplierSortAsc;
  list = list.slice().sort((a, b) => {
    const ma = _supplierPoMap[a.id] || { open: [], awaiting: [], discrep: [], spent: [], thisMonth: [], lastMonth: [], all: [] };
    const mb = _supplierPoMap[b.id] || { open: [], awaiting: [], discrep: [], spent: [], thisMonth: [], lastMonth: [], all: [] };
    let diff = 0;
    if      (col === 'name')      diff = a.supplier_name.localeCompare(b.supplier_name);
    else if (col === 'openPos')   diff = ma.open.length - mb.open.length;
    else if (col === 'openValue') diff = ma.open.reduce((s,p)=>s+_poNet(p),0) - mb.open.reduce((s,p)=>s+_poNet(p),0);
    else if (col === 'awaiting')  diff = ma.awaiting.length - mb.awaiting.length;
    else if (col === 'discrep')   diff = ma.discrep.length - mb.discrep.length;
    else if (col === 'thisMonth') diff = ma.thisMonth.reduce((s,p)=>s+_poNet(p),0) - mb.thisMonth.reduce((s,p)=>s+_poNet(p),0);
    else if (col === 'lastMonth') diff = ma.lastMonth.reduce((s,p)=>s+_poNet(p),0) - mb.lastMonth.reduce((s,p)=>s+_poNet(p),0);
    else if (col === 'spent')    diff = ma.spent.reduce((s,p)=>s+_poNet(p),0) - mb.spent.reduce((s,p)=>s+_poNet(p),0);
    return asc ? diff : -diff;
  });

  const fmtVal = v => '£' + Number(v).toLocaleString('en-GB', { minimumFractionDigits: 0, maximumFractionDigits: 0 });

  // Sort indicator helper
  const arrow = c => {
    if (c !== col) return '<span style="color:var(--subtle);margin-left:3px;font-size:9px">⇅</span>';
    return `<span style="margin-left:3px;font-size:9px">${asc ? '▲' : '▼'}</span>`;
  };

  const thBase = 'padding:8px 8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);white-space:nowrap;cursor:pointer;user-select:none;position:sticky;top:0;background:var(--surface);z-index:2';
  const th = (label, c, align) =>
    `<th style="${thBase};text-align:${align||'left'}" onclick="sortSupplierTable('${c}')">${label}${arrow(c)}</th>`;

  let rows = '';
  for (const s of list) {
    const m        = _supplierPoMap[s.id] || { open: [], awaiting: [], discrep: [], spent: [], thisMonth: [], lastMonth: [], all: [] };
    const openVal  = m.open.reduce((sum, p) => sum + _poNet(p), 0);
    const svcNames = (s.services || []).map(sv => sv.service_name).join(', ');
    const spentVal      = m.spent.reduce((sum, p) => sum + _poNet(p), 0);
    const thisMonthVal  = m.thisMonth.reduce((sum, p) => sum + _poNet(p), 0);
    const lastMonthVal  = m.lastMonth.reduce((sum, p) => sum + _poNet(p), 0);
    const awaitCol = m.awaiting.length ? 'var(--amber)' : 'var(--subtle)';
    const discrCol = m.discrep.length  ? 'var(--red)'   : 'var(--subtle)';
    const nameSafe = s.supplier_name.replace(/'/g, "\\'").replace(/"/g, '&quot;');

    rows += `<tr style="border-bottom:1px solid var(--border);cursor:pointer;transition:background .12s"
        onclick="openSupplierDetail(${s.id})"
        onmouseenter="this.style.background='rgba(255,255,255,.03)'" onmouseleave="this.style.background=''">
      <td style="padding:11px 12px 11px 0">
        <div style="font-weight:600">${escapeHtml(s.supplier_name)}${(() => {
          const ap = (typeof SUP_APPROVAL !== 'undefined' && SUP_APPROVAL[s.approval_status]) || null;
          return ap && s.approval_status !== 'unapproved'
            ? ` <span style="background:${ap.color}22;color:${ap.color};border:1px solid ${ap.color}55;border-radius:4px;padding:1px 6px;font-size:9.5px;font-weight:700;vertical-align:1px">${ap.label}</span>` : '';
        })()}</div>
        ${svcNames ? `<div style="font-size:11px;color:var(--accent);margin-top:1px">${escapeHtml(svcNames)}</div>` : ''}
      </td>
      <td style="padding:11px 8px;text-align:center">
        ${m.open.length ? `<span style="font-weight:600">${m.open.length}</span>` : '<span style="color:var(--subtle)">—</span>'}
      </td>
      <td style="padding:11px 8px;text-align:right;font-weight:600;color:${openVal ? 'var(--text)' : 'var(--subtle)'}">
        ${openVal ? fmtVal(openVal) : '—'}
      </td>
      <td style="padding:11px 8px;text-align:center;font-weight:${m.awaiting.length ? '600' : '400'};color:${awaitCol}">
        ${m.awaiting.length ? m.awaiting.length : '<span style="color:var(--subtle)">—</span>'}
      </td>
      <td style="padding:11px 8px;text-align:center;font-weight:${m.discrep.length ? '600' : '400'};color:${discrCol}">
        ${m.discrep.length ? m.discrep.length : '<span style="color:var(--subtle)">—</span>'}
      </td>
      <td style="padding:11px 8px;text-align:right;color:${thisMonthVal ? 'var(--text)' : 'var(--subtle)'}">
        ${thisMonthVal ? fmtVal(thisMonthVal) : '—'}
      </td>
      <td style="padding:11px 8px;text-align:right;color:${lastMonthVal ? 'var(--muted)' : 'var(--subtle)'}">
        ${lastMonthVal ? fmtVal(lastMonthVal) : '—'}
      </td>
      <td style="padding:11px 8px;text-align:right;font-weight:600;color:${spentVal ? 'var(--green)' : 'var(--subtle)'}">
        ${spentVal ? fmtVal(spentVal) : '—'}
      </td>
      <td style="padding:11px 0 11px 8px;white-space:nowrap" onclick="event.stopPropagation()">
        <button class="btn btn-ghost" style="padding:3px 9px;font-size:11px" onclick="editSupplier(${s.id})">&#9998;</button>
      </td>
    </tr>`;
  }

  // Sticky header: thead position:sticky; rows scroll inside the container.
  // max-height keeps the table within the viewport so sticky has a scroll context.
  container.innerHTML = `<div style="max-height:65vh;overflow-y:auto;border:1px solid var(--border);border-radius:8px">
    <table style="width:100%;border-collapse:collapse;font-size:13px">
    <thead><tr style="background:var(--surface);box-shadow:inset 0 -2px 0 var(--border)">
      ${th('Supplier', 'name', 'left')}
      ${th("Open PO's", 'openPos', 'center')}
      ${th('Open Value', 'openValue', 'right')}
      ${th('Awaiting Invoice', 'awaiting', 'center')}
      ${th('Discrepancies', 'discrep', 'center')}
      ${th('£ This Month', 'thisMonth', 'right')}
      ${th('£ Last Month', 'lastMonth', 'right')}
      ${th('Total Spent', 'spent', 'right')}
      <th style="${thBase};cursor:default;background:var(--surface)"></th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table></div>`;
}


function populateServiceCheckboxes(selectedIds) {
  const container = document.getElementById('supplierServiceCheckboxes');
  if (!container) return;
  const _svcSelectedIds = new Set(selectedIds.map(Number));

  container.innerHTML = `
    <div style="position:relative;margin-bottom:8px">
      <input type="text" id="svcSearchBox" class="field-input" placeholder="Search services..." 
        style="padding-left:30px;font-size:13px"
        oninput="filterServiceCheckboxes()">
      <span style="position:absolute;left:10px;top:50%;transform:translateY(-50%);color:var(--muted);font-size:14px;pointer-events:none">&#128269;</span>
    </div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;font-size:12px;color:var(--muted)">
      <span id="svcSelectedCount">${_svcSelectedIds.size} selected</span>
      <span id="svcFilterInfo" style="display:none"></span>
    </div>
    <div id="svcCheckboxList" style="max-height:250px;overflow-y:auto;display:flex;flex-wrap:wrap;gap:8px;padding:2px">
      ${renderServiceCheckboxItems(_serviceTypes, _svcSelectedIds, '')}
    </div>`;
}

function renderServiceCheckboxItems(types, selectedSet, filter) {
  const lower = filter.toLowerCase();
  const sorted = [...types].sort((a, b) => {
    const aChecked = selectedSet.has(a.id) ? 0 : 1;
    const bChecked = selectedSet.has(b.id) ? 0 : 1;
    return aChecked - bChecked || a.name.localeCompare(b.name);
  });
  return sorted.map(st => {
    const match = !lower || st.name.toLowerCase().includes(lower);
    const checked = selectedSet.has(st.id) ? 'checked' : '';
    return `<label style="display:${match ? 'flex' : 'none'};align-items:center;gap:6px;font-size:13px;background:${checked ? 'var(--accent-bg, rgba(59,130,246,0.08))' : 'var(--card)'};border:1px solid ${checked ? 'var(--accent)' : 'var(--border)'};border-radius:8px;padding:6px 12px;cursor:pointer;transition:all .15s" data-svc-id="${st.id}" data-svc-name="${st.name.toLowerCase()}">
      <input type="checkbox" class="supplier-svc-cb" value="${st.id}" ${checked} onchange="onServiceCheckboxChange()"> ${st.name}
    </label>`;
  }).join('');
}

function filterServiceCheckboxes() {
  const search = (document.getElementById('svcSearchBox')?.value || '').toLowerCase();
  const labels = document.querySelectorAll('#svcCheckboxList label');
  let visible = 0;
  labels.forEach(lbl => {
    const name = lbl.dataset.svcName || '';
    const show = !search || name.includes(search);
    lbl.style.display = show ? 'flex' : 'none';
    if (show) visible++;
  });
  const info = document.getElementById('svcFilterInfo');
  if (info) {
    info.style.display = search ? 'inline' : 'none';
    info.textContent = search ? `(${visible} matching)` : '';
  }
}

function onServiceCheckboxChange() {
  const checked = document.querySelectorAll('.supplier-svc-cb:checked');
  const countEl = document.getElementById('svcSelectedCount');
  if (countEl) countEl.textContent = `${checked.length} selected`;
  // Re-sort: move checked to top
  const list = document.getElementById('svcCheckboxList');
  if (!list) return;
  const labels = [...list.querySelectorAll('label')];
  labels.sort((a, b) => {
    const aC = a.querySelector('input').checked ? 0 : 1;
    const bC = b.querySelector('input').checked ? 0 : 1;
    return aC - bC || (a.dataset.svcName || '').localeCompare(b.dataset.svcName || '');
  });
  labels.forEach(lbl => {
    const inp = lbl.querySelector('input');
    lbl.style.background = inp.checked ? 'var(--accent-bg, rgba(59,130,246,0.08))' : 'var(--card)';
    lbl.style.borderColor = inp.checked ? 'var(--accent)' : 'var(--border)';
    list.appendChild(lbl);
  });
}

function openAddSupplierForm() {
  document.getElementById('supplierEditId').value = '';
  document.getElementById('supplierName').value = '';
  document.getElementById('supplierContactName').value = '';
  document.getElementById('supplierTel').value = '';
  document.getElementById('supplierEmail').value = '';
  document.getElementById('supplierAddr1').value = '';
  document.getElementById('supplierAddr2').value = '';
  document.getElementById('supplierCity').value = '';
  document.getElementById('supplierCounty').value = '';
  document.getElementById('supplierPostcode').value = '';
  document.getElementById('supplierFormTitle').textContent = 'Add Supplier';
  populateServiceCheckboxes([]);
  const delBtn = document.getElementById('supplierFormDeleteBtn');
  if (delBtn) delBtn.style.display = 'none';
  document.getElementById('supplierFormArea').style.display = 'block';
}

function closeSupplierForm() {
  document.getElementById('supplierFormArea').style.display = 'none';
}

async function editSupplier(id) {
  try {
    const s = await api.get(`/api/suppliers/${id}`);
    document.getElementById('supplierEditId').value = s.id;
    document.getElementById('supplierName').value = s.supplier_name || '';
    document.getElementById('supplierContactName').value = s.contact_name || '';
    document.getElementById('supplierTel').value = s.telephone || '';
    document.getElementById('supplierEmail').value = s.email || '';
    document.getElementById('supplierAddr1').value = s.address_line1 || '';
    document.getElementById('supplierAddr2').value = s.address_line2 || '';
    document.getElementById('supplierCity').value = s.city || '';
    document.getElementById('supplierCounty').value = s.county || '';
    document.getElementById('supplierPostcode').value = s.postcode || '';
    document.getElementById('supplierFormTitle').textContent = 'Edit Supplier';
    populateServiceCheckboxes((s.services || []).map(sv => sv.service_type_id));
    const delBtn = document.getElementById('supplierFormDeleteBtn');
    if (delBtn) delBtn.style.display = '';
    document.getElementById('supplierFormArea').style.display = 'block';
  } catch (e) { toast('Failed to load supplier details', 'error'); }
}

async function saveSupplier() {
  const editId = document.getElementById('supplierEditId').value;
  const supplierName = document.getElementById('supplierName').value.trim();
  const contactName = document.getElementById('supplierContactName').value.trim();
  const telephone = document.getElementById('supplierTel').value.trim();
  const email = document.getElementById('supplierEmail').value.trim();
  const addr1 = document.getElementById('supplierAddr1').value.trim();
  const addr2 = document.getElementById('supplierAddr2').value.trim();
  const city = document.getElementById('supplierCity').value.trim();
  const county = document.getElementById('supplierCounty').value.trim();
  const postcode = document.getElementById('supplierPostcode').value.trim();
  const serviceTypeIds = [...document.querySelectorAll('.supplier-svc-cb:checked')].map(cb => parseInt(cb.value));

  if (!supplierName) { toast('Supplier name is required', 'error'); return; }
  if (!serviceTypeIds.length) { toast('Please select at least one service', 'error'); return; }

  const body = {
    supplier_name: supplierName,
    contact_name: contactName || null, telephone: telephone || null, email: email || null,
    address_line1: addr1 || null, address_line2: addr2 || null,
    city: city || null, county: county || null, postcode: postcode || null,
    service_type_ids: serviceTypeIds
  };

  try {
    if (editId) {
      await api.put(`/api/suppliers/${editId}`, body);
      toast('Supplier updated ✓', 'success');
    } else {
      await api.post('/api/suppliers', body);
      toast('Supplier added ✓', 'success');
    }
    closeSupplierForm();
    renderSuppliersTab();
  } catch (e) { toast('Save failed: ' + e.message, 'error'); }
}

async function deleteSupplier(id, name) {
  if (!(await bamaConfirm({ title: 'Remove supplier', body: `Remove supplier "${name}"?`, confirmText: 'Remove', tone: 'danger' }))) return;
  try {
    await api.delete(`/api/suppliers/${id}`);
    toast('Supplier removed', 'info');
    renderSuppliersTab();
  } catch (e) { toast('Delete failed', 'error'); }
}

// Called by the Delete button inside the edit form.
async function deleteSupplierFromForm() {
  const id = document.getElementById('supplierEditId').value;
  const name = document.getElementById('supplierName').value.trim() || 'this supplier';
  if (!id) return;
  if (!(await bamaConfirm({ title: 'Remove supplier', body: `Remove supplier "${name}"?<br><br>This hides them from the list but keeps the audit trail. Their existing POs and history are preserved.`, confirmText: 'Remove', tone: 'danger' }))) return;
  try {
    await api.delete(`/api/suppliers/${id}`);
    toast('Supplier removed', 'info');
    closeSupplierForm();
    renderSuppliersTab();
  } catch (e) { toast('Delete failed: ' + e.message, 'error'); }
}

// ── Supplier Detail Panel ────────────────────────────────────────────────────
let _supplierDetailId = null;   // currently open supplier id
let _supplierDetailPos = [];    // POs loaded for the open supplier
let _supplierDetailFilter = 'all'; // active status tab

async function openSupplierDetail(supplierId) {
  const supplier = (_suppliers || []).find(s => s.id === supplierId);
  if (!supplier) return;
  _supplierDetailId = supplierId;
  _supplierDetailFilter = 'all';

  // Reset dropzone for new supplier — always visible
  _supDzState = 'idle'; _supDzFile = null; _supDzParsed = null; _supDzMatchedPoId = null;
  _supDzQueue = []; _supDzQueueIdx = 0;
  const dz = document.getElementById('supplierDetailDropzone');
  if (dz) { dz.style.display = ''; _renderSupplierDropzone(); }

  // Render header immediately, load POs async
  _renderSupplierDetailHeader(supplier);
  _supDocQueue = []; loadSupplierDocs(supplierId);   // D2 docs & approval section
  document.getElementById('supplierDetailPoArea').innerHTML =
    '<div style="padding:20px;text-align:center;color:var(--muted)"><div class="spinner"></div></div>';
  document.getElementById('supplierDetailModal').classList.add('active');

  try {
    _supplierDetailPos = await api.get(`/api/purchase-orders?supplier_id=${supplierId}`);
  } catch (e) {
    _supplierDetailPos = [];
    document.getElementById('supplierDetailPoArea').innerHTML =
      '<div style="padding:20px;color:var(--red)">Failed to load purchase orders</div>';
    return;
  }
  _renderSupplierDetailPos();
}

function _renderSupplierDetailHeader(supplier) {
  const svcNames = (supplier.services || []).map(s => s.service_name).join(', ') || 'No services';
  const info = [
    supplier.contact_name ? `<span>&#128100; ${escapeHtml(supplier.contact_name)}</span>` : '',
    supplier.telephone    ? `<span>&#128222; ${escapeHtml(supplier.telephone)}</span>` : '',
    supplier.email        ? `<span>&#9993; ${escapeHtml(supplier.email)}</span>` : '',
  ].filter(Boolean).join(' &nbsp;·&nbsp; ');

  const addrParts = [
    supplier.address_line1, supplier.address_line2,
    supplier.city, supplier.county, supplier.postcode
  ].filter(Boolean);
  const addressLine = addrParts.length
    ? `<span style="font-size:12px;color:var(--muted)">&#128205; ${escapeHtml(addrParts.join(', '))}</span>`
    : '';

  const termLabel = _fmtPaymentTerms(supplier);
  const termsBadge = termLabel
    ? `<span style="display:inline-block;margin-left:10px;padding:2px 8px;border-radius:6px;background:rgba(59,130,246,.12);border:1px solid rgba(59,130,246,.3);color:var(--accent);font-size:11px;font-family:var(--font-mono)">⏱ ${escapeHtml(termLabel)}</span>`
    : `<span style="display:inline-block;margin-left:10px;padding:2px 8px;border-radius:6px;background:rgba(255,255,255,.04);border:1px solid var(--border);color:var(--subtle);font-size:11px">No terms set</span>`;

  document.getElementById('supplierDetailTitle').textContent = supplier.supplier_name;
  document.getElementById('supplierDetailMeta').innerHTML =
    `<span style="color:var(--accent);font-size:12px">${escapeHtml(svcNames)}</span>${termsBadge}` +
    (info ? `<br><span style="font-size:12px;color:var(--muted);margin-top:4px;display:block">${info}</span>` : '') +
    (addressLine ? `<br><span style="margin-top:2px;display:block">${addressLine}</span>` : '');
}

function _renderSupplierDetailPos() {
  const pos = _supplierDetailPos;
  const f   = _supplierDetailFilter;

  // Status grouping logic
  const poGroup = po => {
    if (po.status === 'Cancelled') return 'cancelled';
    if (po.status === 'Closed')    return 'closed';
    if (po.reconciliation_status === 'matched')     return 'matched';
    if (po.reconciliation_status === 'discrepancy') return 'discrepancy';
    if (po.supplier_invoice_received_at)            return 'invoiced';
    if (po.status === 'Received')  return 'received';
    return 'open'; // Open / Approved / Sent
  };

  const groups = { open:'Open', received:'Received', invoiced:'Invoice Rcvd', matched:'Matched', discrepancy:'Discrepancy', closed:'Closed', cancelled:'Cancelled' };
  const groupColour = { open:'var(--accent)', received:'var(--amber)', invoiced:'#7b9ef8', matched:'var(--green)', discrepancy:'var(--red)', closed:'var(--subtle)', cancelled:'var(--subtle)' };

  // Count badges for tabs
  const counts = {};
  pos.forEach(po => { const g = poGroup(po); counts[g] = (counts[g] || 0) + 1; });
  const total = pos.length;

  // Tab bar
  const tabs = ['all', ...Object.keys(groups)].map(key => {
    const label = key === 'all' ? 'All' : groups[key];
    const count = key === 'all' ? total : (counts[key] || 0);
    if (count === 0 && key !== 'all') return '';
    const active = f === key;
    return `<button onclick="supplierDetailFilterTab('${key}')"
      style="padding:6px 12px;font-size:12px;border:1px solid ${active ? 'var(--accent)' : 'var(--border)'};
             border-radius:6px;background:${active ? 'var(--accent)' : 'transparent'};
             color:${active ? '#fff' : 'var(--muted)'};cursor:pointer;font-family:var(--font-body)">${label}
      ${count > 0 ? `<span style="margin-left:4px;background:rgba(255,255,255,.2);border-radius:8px;padding:1px 6px;font-size:10px">${count}</span>` : ''}
    </button>`;
  }).join('');

  // Filter POs
  const filtered = f === 'all' ? pos : pos.filter(po => poGroup(po) === f);

  if (!filtered.length) {
    document.getElementById('supplierDetailPoArea').innerHTML =
      `<div style="padding:30px;text-align:center;color:var(--subtle);font-size:13px">${pos.length ? 'No POs in this status' : 'No purchase orders yet for this supplier'}</div>`;
    document.getElementById('supplierDetailTabs').innerHTML = tabs;
    return;
  }

  // Sort newest first
  filtered.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

  const rows = filtered.map(po => {
    const g = poGroup(po);
    const col = groupColour[g];
    const statusLabel = groups[g] || po.status;
    const project = po.project_number ? `${po.project_number}` : (po.cost_centre || '—');
    const _poNetVal = po.total_value != null ? _poNet(po) : null;
    // If invoice attached, show the actual invoiced net; otherwise show PO net
    const _displayNet = po.supplier_invoice_received_at && po.supplier_invoice_net != null
      ? Number(po.supplier_invoice_net)
      : _poNetVal;
    const value = _displayNet != null ? `£${_displayNet.toLocaleString('en-GB', {minimumFractionDigits:2,maximumFractionDigits:2})}` : '—';
    const invoiceInfo = po.supplier_invoice_received_at
      ? `<div style="font-size:11px;color:var(--muted);margin-top:3px">Invoice: ${po.supplier_invoice_ref || '—'} &nbsp;<b>£${Number(po.supplier_invoice_net||0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})} net</b> / £${Number(po.supplier_invoice_gross||0).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})} gross</div>`
      : '';

    return `
      <div style="border:1px solid var(--border);border-radius:8px;margin-bottom:6px;overflow:hidden" data-po-id="${po.id}">
        <div style="display:flex;align-items:center;gap:12px;padding:10px 14px;cursor:pointer;background:var(--surface)"
             onclick="toggleSupplierPoDetail(this)">
          <div style="width:8px;height:8px;border-radius:50%;background:${col};flex-shrink:0"></div>
          <a onclick="event.stopPropagation();openPoDetailModal(${po.id})"
             style="font-weight:600;font-size:13px;min-width:90px;color:var(--accent);text-decoration:none;cursor:pointer"
             title="View PO detail">${escapeHtml(po.reference||'—')}</a>
          <div style="font-size:12px;color:var(--muted);flex:1">${escapeHtml(po.description||'').slice(0,60)}</div>
          <div style="font-size:12px;color:var(--muted);min-width:70px">${project}</div>
          <div style="font-size:13px;font-weight:600;min-width:80px;text-align:right">${value}</div>
          <div style="font-size:11px;padding:2px 8px;border-radius:6px;background:rgba(255,255,255,.05);border:1px solid ${col};color:${col};min-width:80px;text-align:center">${statusLabel}</div>
          <div style="font-size:11px;color:var(--subtle)">▼</div>
        </div>
        ${invoiceInfo ? `<div style="padding:0 14px 8px;background:var(--surface)">${invoiceInfo}</div>` : ''}
        <div class="supplier-po-detail" style="display:none;padding:12px 14px;background:var(--bg);border-top:1px solid var(--border)">
          <div class="supplier-po-lineitems-pending" style="font-size:12px;color:var(--subtle)">Loading…</div>
        </div>
      </div>`;
  }).join('');

  // Summary bar
  const openVal = pos.filter(p => poGroup(p) === 'open').reduce((s,p) => s + _poNet(p), 0);
  const receivedVal = pos.filter(p => ['received','invoiced','matched','discrepancy'].includes(poGroup(p))).reduce((s,p) => s + _poNet(p), 0);
  const fmtK = v => v >= 1000 ? `£${(v/1000).toFixed(1)}k` : `£${v.toFixed(0)}`;

  const summary = `
    <div style="display:flex;gap:16px;padding:10px 0;margin-bottom:12px;border-bottom:1px solid var(--border)">
      <div style="font-size:12px;color:var(--muted)">Total POs: <b style="color:var(--text)">${pos.length}</b></div>
      <div style="font-size:12px;color:var(--muted)">Open value: <b style="color:var(--accent)">${fmtK(openVal)}</b></div>
      <div style="font-size:12px;color:var(--muted)">Received value: <b style="color:var(--amber)">${fmtK(receivedVal)}</b></div>
    </div>`;

  document.getElementById('supplierDetailTabs').innerHTML = tabs;
  document.getElementById('supplierDetailPoArea').innerHTML = summary + rows;
}

function _renderPoDetailRows(po) {
  let html = '';

  // Line items
  if (po.line_items && po.line_items.length) {
    html += `<div style="font-size:11px;color:var(--muted);margin-bottom:6px;font-weight:600;text-transform:uppercase;letter-spacing:.05em">Line Items</div>`;
    html += `<table style="width:100%;font-size:12px;border-collapse:collapse">
      <tr style="color:var(--subtle);font-size:11px"><td style="padding:2px 8px 2px 0">Description</td><td style="padding:2px 4px;text-align:center">Qty</td><td style="padding:2px 4px;text-align:right">Unit £</td><td style="padding:2px 0 2px 4px;text-align:right">Total</td></tr>`;
    po.line_items.forEach(li => {
      html += `<tr style="border-top:1px solid var(--border)">
        <td style="padding:4px 8px 4px 0;color:var(--text)">${escapeHtml(li.description||'')}</td>
        <td style="padding:4px;text-align:center;color:var(--muted)">${li.quantity||''}</td>
        <td style="padding:4px;text-align:right;color:var(--muted)">£${Number(li.unit_price||0).toFixed(2)}</td>
        <td style="padding:4px 0 4px 4px;text-align:right;color:var(--text)">£${Number(li.line_total||0).toFixed(2)}</td>
      </tr>`;
    });
    html += `</table>`;
  } else {
    html += `<div style="font-size:12px;color:var(--subtle)">No line items</div>`;
  }

  // Invoice info if present
  if (po.supplier_invoice_received_at) {
    const invAtt = (po.attachments || []).find(a => a.kind === 'supplier_invoice');
    const invUrl = invAtt?.sharepoint_file_url || null;
    const invLinkHtml = invUrl
      ? ` &nbsp;<a href="${escapeHtml(invUrl)}" target="_blank" style="color:var(--accent);font-size:12px;text-decoration:none" title="Open invoice in SharePoint">📄 View invoice</a>`
      : '';
    html += `<div style="margin-top:10px;padding-top:10px;border-top:1px solid var(--border);font-size:12px">
      <span style="color:var(--muted)">Invoice ref:</span> <b>${escapeHtml(po.supplier_invoice_ref||'—')}</b> &nbsp;
      <span style="color:var(--muted)">Gross:</span> <b>£${Number(po.supplier_invoice_gross||0).toFixed(2)}</b> &nbsp;
      <span style="color:var(--muted)">Status:</span> <b style="color:${po.reconciliation_status==='matched'?'var(--green)':'var(--red)'}">${po.reconciliation_status||'—'}</b>${invLinkHtml}
    </div>`;
  }

  // Attach invoice button if not yet received
  if (!po.supplier_invoice_received_at && po.status !== 'Cancelled') {
    html += `<div style="margin-top:10px">
      <button class="btn btn-ghost" style="font-size:12px;padding:5px 12px"
        onclick="openSupplierInvoiceForPo(${po.id})">📎 Attach Invoice</button>
    </div>`;
  }

  return html;
}

function toggleSupplierPoDetail(headerEl) {
  const card = headerEl.closest('div[style*="border-radius:8px"]');
  const detail = card?.querySelector('.supplier-po-detail');
  if (!detail) return;
  const isOpen = detail.style.display !== 'none';
  detail.style.display = isOpen ? 'none' : '';
  const arrow = headerEl.querySelector('div[style*="▼"]');
  if (arrow) arrow.style.transform = isOpen ? '' : 'rotate(180deg)';

  // Fetch line items on first expand (list endpoint omits them)
  if (!isOpen && detail.dataset.loaded !== '1') {
    detail.dataset.loaded = '1';
    const poId = card.dataset.poId;
    if (poId && detail.querySelector('.supplier-po-lineitems-pending')) {
      api.get(`/api/purchase-orders/${poId}`).then(po => {
        const placeholder = detail.querySelector('.supplier-po-lineitems-pending');
        if (placeholder) placeholder.outerHTML = _renderPoDetailRows(po);
      }).catch(() => {});
    }
  }
}

function supplierDetailFilterTab(key) {
  _supplierDetailFilter = key;
  _renderSupplierDetailPos();
}

function closeSupplierDetail() {
  document.getElementById('supplierDetailModal').classList.remove('active');
  _supplierDetailId = null;
  _supplierDetailPos = [];
  // Reset dropzone state
  _supDzState = 'idle'; _supDzFile = null; _supDzParsed = null; _supDzMatchedPoId = null;
  _supDzQueue = []; _supDzQueueIdx = 0;
}

// ── Supplier Payment Terms Modal ──────────────────────────────────────────────

function _fmtPaymentTerms(supplier) {
  if (supplier && supplier.payment_on_account)
    return 'Paid on account' + (supplier.via_amazon ? ' · Amazon' : '');
  if (!supplier || !supplier.payment_term_type || supplier.payment_term_days == null) return null;
  const days = supplier.payment_term_days;
  const labels = {
    days_eom:              `${days} days EOM`,
    days_from_invoice:     `${days} days from invoice`,
    days_following_month:  `${days} days following month`,
  };
  const term = labels[supplier.payment_term_type] || null;
  if (!term) return null;
  return term + (supplier.payment_dd ? ' · DD' : '');
}

function openSupplierTermsModal() {
  const supplier = (_suppliers || []).find(s => s.id === _supplierDetailId);
  if (!supplier) return;

  const nameEl = document.getElementById('supplierTermsSupplierName');
  if (nameEl) nameEl.textContent = supplier.supplier_name;

  // Pre-select existing terms
  document.querySelectorAll('input[name="termType"]').forEach(r => r.checked = false);
  if (supplier.payment_term_type) {
    const radio = document.querySelector(`input[name="termType"][value="${supplier.payment_term_type}"]`);
    if (radio) radio.checked = true;
  }
  const daysEl = document.getElementById('termDaysInput');
  if (daysEl) daysEl.value = supplier.payment_term_days != null ? supplier.payment_term_days : '';

  const ddEl = document.getElementById('termDdCheckbox');
  if (ddEl) ddEl.checked = !!supplier.payment_dd;
  const oaEl = document.getElementById('termOnAccCheckbox');
  if (oaEl) oaEl.checked = !!supplier.payment_on_account;
  const azEl = document.getElementById('termAmazonCheckbox');
  if (azEl) azEl.checked = !!supplier.via_amazon;
  const lbEl = document.getElementById('termLabourCheckbox');
  if (lbEl) lbEl.checked = !!supplier.is_labour_supplier;

  _highlightSelectedTermOption();

  // Highlight on change
  document.querySelectorAll('input[name="termType"]').forEach(r => {
    r.onchange = _highlightSelectedTermOption;
  });

  document.getElementById('supplierTermsModal').classList.add('active');
}

function _highlightSelectedTermOption() {
  ['termOptEom', 'termOptInvoice', 'termOptFollowing'].forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    const radio = el.querySelector('input[type="radio"]');
    el.style.borderColor = radio && radio.checked ? 'var(--accent)' : 'var(--border)';
    el.style.background   = radio && radio.checked ? 'rgba(var(--accent-rgb, 59,130,246),.08)' : '';
  });
}

function closeSupplierTermsModal() {
  document.getElementById('supplierTermsModal').classList.remove('active');
}

async function saveSupplierTerms() {
  const supplierId = _supplierDetailId;
  if (!supplierId) return;

  const selected = document.querySelector('input[name="termType"]:checked');
  const onAccount = document.getElementById('termOnAccCheckbox')?.checked || false;
  const viaAmazon = document.getElementById('termAmazonCheckbox')?.checked || false;
  const isLabour  = document.getElementById('termLabourCheckbox')?.checked || false;
  // On-account (and pure DD) suppliers don't need a due-date rule
  if (!selected && !onAccount) { toast('Please select a payment term type (or tick Paid on Account)', 'warning'); return; }

  const days = parseInt(document.getElementById('termDaysInput').value);
  if (selected && (isNaN(days) || days < 0)) { toast('Please enter a valid number of days', 'warning'); return; }

  try {
    const dd = document.getElementById('termDdCheckbox')?.checked || false;

    const updated = await api.put(`/api/suppliers/${supplierId}`, {
      payment_term_type: selected ? selected.value : null,
      payment_term_days: selected ? days : null,
      payment_dd: dd,
      payment_on_account: onAccount,
      via_amazon: viaAmazon,
      is_labour_supplier: isLabour,
    });

    // Patch local cache
    const idx = (_suppliers || []).findIndex(s => s.id === supplierId);
    if (idx !== -1) {
      _suppliers[idx].payment_term_type = selected ? selected.value : null;
      _suppliers[idx].payment_term_days = selected ? days : null;
      _suppliers[idx].payment_dd = dd;
      _suppliers[idx].payment_on_account = onAccount;
      _suppliers[idx].via_amazon = viaAmazon;
      _suppliers[idx].is_labour_supplier = isLabour;
    }

    closeSupplierTermsModal();
    const supplier = (_suppliers || []).find(s => s.id === supplierId);
    if (supplier) _renderSupplierDetailHeader(supplier);

    // Re-derive due dates on every UNPAID invoice for this supplier so aged
    // creditors / statement check / BACS windows reflect the new terms.
    let recomputed = 0;
    try {
      const res = await api.post('/api/supplier-invoices-recompute-due', { supplier_id: supplierId });
      recomputed = (res && res.updated) || 0;
      if (typeof _invSupInvoices !== 'undefined' && _invSupInvoices.length && typeof loadInvoicingData === 'function'
          && document.getElementById('invSupplierTbody')) {
        await loadInvoicingData();
        renderInvSupplierTable();
      }
    } catch (e) { console.warn('Due-date recompute failed:', e); }
    toast(`Payment terms saved${recomputed ? ` — due dates updated on ${recomputed} unpaid invoice${recomputed === 1 ? '' : 's'}` : ''}`, 'success');
  } catch (e) {
    toast('Failed to save payment terms', 'error');
  }
}


// panel. Drop or pick a PDF/image → Claude vision OCR extracts the supplier's
// PO reference + monetary totals → auto-match against this supplier's POs
// (any status, no invoice attached yet) → user reviews → save uploads to
// SharePoint and POSTs /api/supplier-invoices (ledger row linked to the PO).
// ─────────────────────────────────────────────────────────────────────────────

let _supDzState  = 'idle';    // 'idle' | 'parsing' | 'review' | 'saving'
let _supDzFile   = null;
let _supDzParsed = null;      // { invoice_ref, invoice_date, net, vat, gross, po_reference }
let _supDzMatchedPoId = null; // pre-selected PO id after auto-match
let _supDzQueue  = [];        // pending files when multiple uploaded
let _supDzQueueIdx = 0;       // index of file currently being reviewed

function toggleSupplierDropzone() {
  // Dropzone is always visible — this is now a no-op kept for compatibility
}

function _renderSupplierDropzone() {
  const box = document.getElementById('supplierDetailDropzone');
  if (!box) return;

  if (_supDzState === 'idle') {
    box.innerHTML = `
      <div id="supDzDrop"
           style="border:2px dashed var(--border);border-radius:8px;padding:18px;text-align:center;cursor:pointer;transition:border-color .15s,background .15s"
           onclick="document.getElementById('supDzFile').click()"
           ondragover="event.preventDefault();this.style.borderColor='var(--accent)';this.style.background='rgba(255,255,255,.02)'"
           ondragleave="this.style.borderColor='var(--border)';this.style.background='transparent'"
           ondrop="event.preventDefault();this.style.borderColor='var(--border)';this.style.background='transparent';onSupplierDzFiles(event.dataTransfer.files)">
        <div style="font-size:24px;margin-bottom:6px">📎</div>
        <div style="font-size:13px;color:var(--text);font-weight:600;margin-bottom:2px">Drop invoice(s) here, or click to browse</div>
        <div style="font-size:11px;color:var(--subtle)">PDF, PNG, or JPG · multiple files supported</div>
        <input type="file" id="supDzFile" accept="application/pdf,image/*" multiple style="display:none" onchange="onSupplierDzFiles(this.files)">
      </div>`;
  } else if (_supDzState === 'parsing') {
    const _qProg = _supDzQueue.length > 1 ? ` <span style="color:var(--muted);font-weight:400">(${_supDzQueueIdx + 1} of ${_supDzQueue.length})</span>` : '';
    box.innerHTML = `
      <div style="display:flex;align-items:center;gap:12px;padding:14px;background:var(--surface);border-radius:8px;border:1px solid var(--border)">
        <div class="spinner" style="width:18px;height:18px;flex-shrink:0"></div>
        <div>
          <div style="font-size:13px;font-weight:600">Reading supplier invoice…${_qProg}</div>
          <div style="font-size:11px;color:var(--subtle);margin-top:2px">${escapeHtml(_supDzFile?.name || '')}</div>
        </div>
      </div>`;
  } else if (_supDzState === 'review') {
    _renderSupplierDzReview();
  } else if (_supDzState === 'saving') {
    box.innerHTML = `
      <div style="display:flex;align-items:center;gap:12px;padding:14px;background:var(--surface);border-radius:8px;border:1px solid var(--border)">
        <div class="spinner" style="width:18px;height:18px;flex-shrink:0"></div>
        <div style="font-size:13px;font-weight:600">Uploading to SharePoint and saving…</div>
      </div>`;
  }
}

async function onSupplierDzFiles(files) {
  if (!files || !files.length) return;
  _supDzQueue    = Array.from(files);
  _supDzQueueIdx = 0;
  await _supDzProcessNext();
}

async function onSupplierDzFile(file) {
  if (!file) return;
  await onSupplierDzFiles([file]);
}

async function _supDzProcessNext() {
  if (_supDzQueueIdx >= _supDzQueue.length) {
    _supDzQueue = []; _supDzQueueIdx = 0;
    _supDzState = 'idle'; _supDzFile = null; _supDzParsed = null; _supDzMatchedPoId = null;
    _renderSupplierDropzone();
    return;
  }
  const file = _supDzQueue[_supDzQueueIdx];
  _supDzFile   = file;
  _supDzParsed = null;
  _supDzState  = 'parsing';
  _renderSupplierDropzone();

  try {
    const dataUri = await _fileToDataUri(file);
    const isImg   = file.type.startsWith('image/');
    const result  = await callClaude({
      model: 'claude-sonnet-4-6',
      max_tokens: 800,
      messages: [{
        role: 'user',
        content: [
          isImg
            ? { type: 'image',    source: { type: 'base64', media_type: file.type, data: dataUri.split(',')[1] } }
            : { type: 'document', source: { type: 'base64', media_type: file.type, data: dataUri.split(',')[1] } },
          {
            type: 'text',
            text: `Extract from this UK supplier invoice. Return ONLY JSON, no markdown:
{
  "invoice_ref": "supplier's invoice number",
  "invoice_date": "YYYY-MM-DD",
  "net_amount": 0,
  "vat_amount": 0,
  "gross_amount": 0,
  "po_reference": "BAMA's PO reference if shown on the invoice — looks like P260501 (P + 6 digits)"
}
Set any field to null if not clearly shown. The PO reference belongs to the customer (BAMA) and is usually printed under "Your Order", "Order Ref", "Customer Order", "PO Number" or similar.
IMPORTANT: Use the final printed net total and gross total from the invoice — not a goods-only subtotal. If the invoice has no delivery or other extra charges, the printed total is still correct as-is.`
          }
        ]
      }]
    });
    const text = (result.content?.find(b => b.type === 'text')?.text || '').trim();
    const start = text.indexOf('{'), end = text.lastIndexOf('}');
    _supDzParsed = JSON.parse(text.slice(start, end + 1));

    // Auto-match to one of this supplier's unattached POs
    _supDzMatchedPoId = _matchSupplierPoFromParsed(_supDzParsed);
    _supDzState = 'review';
  } catch (err) {
    console.error('Supplier invoice OCR failed', err);
    _supDzParsed = { _error: err.message || 'Could not read the invoice' };
    _supDzMatchedPoId = null;
    _supDzState = 'review';   // fall through so the user can fill manually
  }
  _renderSupplierDropzone();
}

// Match strategy: PO ref text on invoice first (exact match), then closest
// gross amount among this supplier's POs without an invoice attached.
function _matchSupplierPoFromParsed(parsed) {
  const candidates = (_supplierDetailPos || []).filter(po => !po.supplier_invoice_received_at);
  if (!candidates.length) return null;

  // 1. Exact PO-ref match (case-insensitive, ignore whitespace)
  const ref = (parsed?.po_reference || '').replace(/\s+/g, '').toUpperCase();
  if (ref) {
    const hit = candidates.find(po => (po.reference || '').replace(/\s+/g, '').toUpperCase() === ref);
    if (hit) return hit.id;
    // also try contains, for invoices that say "Order P260501-1" or similar
    const looseHit = candidates.find(po => {
      const r = (po.reference || '').replace(/\s+/g, '').toUpperCase();
      return r && (ref.includes(r) || r.includes(ref));
    });
    if (looseHit) return looseHit.id;
  }

  // 2. Closest net match within £1
  const invoiceNet = Number(parsed?.net_amount);
  if (Number.isFinite(invoiceNet) && invoiceNet > 0) {
    const closeMatches = candidates
      .map(po => ({ po, diff: Math.abs(_poNet(po) - invoiceNet) }))
      .filter(x => x.diff <= 1)
      .sort((a, b) => a.diff - b.diff);
    if (closeMatches.length === 1) return closeMatches[0].po.id;
  }

  return null;   // user picks manually
}

function _supDzCancelCurrent() {
  // Skip current file — advance to next or return to idle
  _supDzFile = null; _supDzParsed = null; _supDzMatchedPoId = null;
  _supDzQueueIdx++;
  _supDzProcessNext();
}

function _renderSupplierDzReview() {
  const box = document.getElementById('supplierDetailDropzone');
  const parsed = _supDzParsed || {};
  const candidates = (_supplierDetailPos || []).filter(po => !po.supplier_invoice_received_at);
  const matched = _supDzMatchedPoId
    ? candidates.find(po => po.id === _supDzMatchedPoId)
    : null;

  // Queue progress header
  const qTotal = _supDzQueue.length;
  const qCurrent = _supDzQueueIdx + 1;
  const progressBar = qTotal > 1
    ? `<div style="display:flex;align-items:center;gap:10px;padding:8px 0 12px;font-size:12px;color:var(--muted)">
        <div style="flex:1;height:4px;background:var(--border);border-radius:2px;overflow:hidden">
          <div style="height:100%;background:var(--accent);width:${Math.round((qCurrent/qTotal)*100)}%;transition:width .3s"></div>
        </div>
        <span style="flex-shrink:0;font-family:var(--font-mono)">${qCurrent} of ${qTotal}</span>
      </div>`
    : '';

  const matchBanner = parsed._error
    ? `<div style="background:rgba(208,2,27,.1);border:1px solid var(--red);color:var(--red);padding:8px 12px;border-radius:6px;font-size:12px;margin-bottom:10px">⚠ Could not read the file — fill in below manually. (${escapeHtml(parsed._error)})</div>`
    : matched
      ? (() => {
          const poN  = _poNet(matched);
          const invN = Number(parsed.net_amount);
          const hasInvN = Number.isFinite(invN) && invN > 0;
          const valOk   = hasInvN && Math.abs(poN - invN) <= 1;
          const valWarn = hasInvN && !valOk;
          const valPart = hasInvN
            ? ` &nbsp;·&nbsp; PO: <b>£${poN.toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})} net</b> / Invoice: <b>£${invN.toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})} net</b>` + (valOk ? ' ✓' : ' <span style="color:var(--amber)">⚠ value mismatch</span>') : '';
          const col = valWarn ? 'var(--amber)' : 'var(--green)';
          const bg  = valWarn ? 'rgba(245,158,11,.1)' : 'rgba(62,207,142,.1)';
          return `<div style="background:${bg};border:1px solid ${col};color:${col};padding:8px 12px;border-radius:6px;font-size:12px;margin-bottom:10px">✓ Matched to <b>${escapeHtml(matched.reference)}</b>${valPart}</div>`;
        })()
      : `<div style="background:rgba(245,158,11,.1);border:1px solid var(--amber);color:var(--amber);padding:8px 12px;border-radius:6px;font-size:12px;margin-bottom:10px">⚠ No PO ref found on the invoice — pick one below.</div>`;

  // Sort candidates by closeness to parsed gross when available
  const gross = Number(parsed.gross_amount);
  const sortedCands = Number.isFinite(gross) && gross > 0
    ? candidates.slice().sort((a, b) =>
        Math.abs(Number(a.total_value || 0) - gross) - Math.abs(Number(b.total_value || 0) - gross))
    : candidates.slice().sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

  const opts = ['<option value="">— pick a PO —</option>']
    .concat(sortedCands.map(po => {
      const sel = po.id === _supDzMatchedPoId ? ' selected' : '';
      const project = po.project_number || po.cost_centre || '—';
      const poNetDisp = _poNet(po);
      return `<option value="${po.id}"${sel}>${escapeHtml(po.reference || '—')} · £${poNetDisp.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} net · ${escapeHtml(project)} · ${escapeHtml((po.description || '').slice(0, 40))}</option>`;
    }))
    .join('');

  const fileLabel = _supDzFile ? `${_supDzFile.name} · ${(_supDzFile.size / 1024).toFixed(0)} KB` : '';

  box.innerHTML = `
    ${progressBar}
    ${matchBanner}
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px 14px;font-size:12px">
      <div style="grid-column:1 / -1">
        <label style="display:block;color:var(--muted);margin-bottom:3px;font-size:11px;text-transform:uppercase;letter-spacing:.05em">PO to attach to</label>
        <select id="supDzPoSelect" class="field-input" style="width:100%;font-size:13px">${opts}</select>
      </div>
      <div>
        <label style="display:block;color:var(--muted);margin-bottom:3px;font-size:11px;text-transform:uppercase;letter-spacing:.05em">Invoice ref</label>
        <input id="supDzRef" class="field-input" type="text" value="${escapeHtml(parsed.invoice_ref || '')}" style="width:100%">
      </div>
      <div>
        <label style="display:block;color:var(--muted);margin-bottom:3px;font-size:11px;text-transform:uppercase;letter-spacing:.05em">Invoice date</label>
        <input id="supDzDate" class="field-input" type="date" value="${escapeHtml(parsed.invoice_date || new Date().toISOString().slice(0, 10))}" style="width:100%">
      </div>
      <div>
        <label style="display:block;color:var(--muted);margin-bottom:3px;font-size:11px;text-transform:uppercase;letter-spacing:.05em">Net £</label>
        <input id="supDzNet" class="field-input" type="number" step="0.01" value="${parsed.net_amount ?? ''}" style="width:100%">
      </div>
      <div>
        <label style="display:block;color:var(--muted);margin-bottom:3px;font-size:11px;text-transform:uppercase;letter-spacing:.05em">VAT £</label>
        <input id="supDzVat" class="field-input" type="number" step="0.01" value="${parsed.vat_amount ?? ''}" style="width:100%">
      </div>
      <div style="grid-column:1 / -1">
        <label style="display:block;color:var(--muted);margin-bottom:3px;font-size:11px;text-transform:uppercase;letter-spacing:.05em">Gross £ <span style="color:var(--red)">*</span></label>
        <input id="supDzGross" class="field-input" type="number" step="0.01" value="${parsed.gross_amount ?? ''}" style="width:100%">
      </div>
      <div style="grid-column:1 / -1">
        <label style="display:block;color:var(--muted);margin-bottom:3px;font-size:11px;text-transform:uppercase;letter-spacing:.05em">Notes (optional)</label>
        <textarea id="supDzNotes" class="field-input" rows="2" style="width:100%;resize:vertical" placeholder="Discrepancy reason, partial delivery, etc."></textarea>
      </div>
    </div>
    <div style="display:flex;align-items:center;justify-content:space-between;margin-top:12px;gap:10px">
      <div style="font-size:11px;color:var(--subtle);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">📄 ${escapeHtml(fileLabel)}</div>
      <div style="display:flex;gap:8px;flex-shrink:0">
        <button class="btn btn-ghost" style="font-size:12px;padding:6px 14px" onclick="_supDzCancelCurrent()">
          ${_supDzQueue.length > 1 ? 'Skip' : 'Cancel'}
        </button>
        <button class="btn btn-primary" id="supDzSaveBtn" style="font-size:12px;padding:6px 14px" onclick="saveSupplierDropzone()">Save Invoice</button>
      </div>
    </div>`;
}

async function saveSupplierDropzone() {
  const poId  = Number(document.getElementById('supDzPoSelect').value);
  const ref   = document.getElementById('supDzRef').value.trim();
  const date  = document.getElementById('supDzDate').value;
  const net   = Number(document.getElementById('supDzNet').value || 0);
  const vat   = Number(document.getElementById('supDzVat').value || 0);
  const gross = Number(document.getElementById('supDzGross').value || 0);
  const notes = document.getElementById('supDzNotes').value.trim();

  if (!poId)  { toast('Pick a PO to attach this invoice to', 'error'); return; }
  if (!_supDzFile) { toast('Upload the invoice file first', 'error'); return; }
  if (!gross) { toast('Gross amount is required', 'error'); return; }

  const po = (_supplierDetailPos || []).find(p => p.id === poId);
  if (!po) { toast('Selected PO not found', 'error'); return; }

  _supDzState = 'saving';
  _renderSupplierDropzone();
  setLoading(true);

  try {
    // 1. SharePoint upload — 01 - Accounts/04 - Supplier Invoices/YYYY/MM/
    const folder = await _findOrCreateSupplierInvoiceFolder(date);
    const stamp  = (po.supplier_name || 'supplier').replace(/\s+/g, '_').slice(0, 30);
    const ext    = (_supDzFile.name.split('.').pop() || 'pdf').toLowerCase();
    const fileName = sanitizeSpFilename(`${date}_${stamp}_${ref || 'no-ref'}.${ext}`);
    const driveItem = await uploadFileToFolder(
      folder.id, fileName, _supDzFile, _supDzFile.type || 'application/octet-stream'
    );

    // 2. Persist on the PO (server reconciles vs total_value within £1)
    await api.post('/api/supplier-invoices', {
      supplier_id:         po.supplier_id || _supplierDetailId,
      po_id:               poId,
      invoice_ref:         ref || null,
      invoice_date:        date || null,
      net:                 net || null,
      vat:                 vat || null,
      gross:               gross,
      sharepoint_file_id:  driveItem.id,
      sharepoint_file_url: driveItem.webUrl,
      filename:            fileName,
      notes:               notes || null
    });

    toast(`Invoice attached to ${po.reference} ✓`, 'success');

    // 3. Refresh PO list, then advance to next queued file (or reset to idle)
    if (_supplierDetailId) {
      _supplierDetailPos = await api.get(`/api/purchase-orders?supplier_id=${_supplierDetailId}`);
      _renderSupplierDetailPos();
    }
    _supDzFile = null; _supDzParsed = null; _supDzMatchedPoId = null;
    _supDzQueueIdx++;
    await _supDzProcessNext();
  } catch (err) {
    console.error('Save supplier invoice failed', err);
    toast('Failed to save invoice: ' + (err.message || 'unknown error'), 'error');
    _supDzState = 'review';
    _renderSupplierDropzone();
  } finally {
    setLoading(false);
  }
}

// The per-PO "📎 Attach Invoice" button inside the supplier detail panel rows
// also routes through the dropzone now (was broken — pointed at a modal that
// only exists on invoice-tracker.html).
function openSupplierInvoiceForPo(poId) {
  const box = document.getElementById('supplierDetailDropzone');
  if (!box) return;
  // Open the dropzone with this PO pre-matched
  _supDzState = 'idle';
  _supDzFile = null;
  _supDzParsed = null;
  _supDzMatchedPoId = poId;
  box.style.display = '';
  _renderSupplierDropzone();
  box.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function closeSupplierPoTileModal() {
  document.getElementById('supplierPoTileModal').classList.remove('active');
}

// ── Supplier quick-access tiles ───────────────────────────────────────────────
// Rendered at the top of the Suppliers tab. Each tile aggregates PO data and
// opens a drill-down modal grouped by supplier on click.
// More tiles can be added here later (e.g. "Discrepancies", "Overdue POs").
// ─────────────────────────────────────────────────────────────────────────────
let _supplierTilePos = []; // cached PO list for the current tile render

async function renderSupplierTiles() {
  const container = document.getElementById('supplierTiles');
  if (!container) return;
  container.innerHTML = '<div style="font-size:12px;color:var(--subtle);padding:4px 0">Loading…</div>';
  try {
    _supplierTilePos = await api.get('/api/purchase-orders');
  } catch (e) {
    container.innerHTML = '';
    return;
  }
  _renderSupplierTilesFromCache();
}

// ── Supplier tile filters ────────────────────────────────────────────────────
// Centralised so the tile render and the drill-down use the exact same logic.
function _getOverdueThresholdDays() {
  const v = state.timesheetData?.settings?.overdue_po_threshold;
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : 30;
}
function _filterAwaitingInvoice(pos) {
  return pos.filter(po =>
    po.status !== 'Cancelled' &&
    po.status !== 'Closed' &&
    !po.supplier_invoice_received_at
  );
}
function _filterDiscrepancy(pos) {
  // Suppress penny-rounding differences of £0.04 or under — these are
  // OCR/rounding artefacts and are not genuine financial discrepancies.
  return pos.filter(po =>
    po.reconciliation_status === 'discrepancy' &&
    _r2(Math.abs(Number(po.supplier_invoice_gross || 0) - Number(po.total_value || 0))) > 0.04
  );
}
function _filterOverdue(pos) {
  const threshold = _getOverdueThresholdDays();
  const cutoff = Date.now() - threshold * 86400000;
  return pos.filter(po =>
    ['Open', 'Approved', 'Sent'].includes(po.status) &&
    !po.delivery_received_at &&
    !po.supplier_invoice_received_at &&
    po.created_at && new Date(po.created_at).getTime() < cutoff
  );
}

function _renderSupplierTilesFromCache() {
  const container = document.getElementById('supplierTiles');
  if (!container) return;

  const awaitingInvoice = _filterAwaitingInvoice(_supplierTilePos);
  const awaitingValue   = awaitingInvoice.reduce((s, p) => s + Number(p.total_value || 0), 0);

  const discrepancies   = _filterDiscrepancy(_supplierTilePos);
  const discDiff        = discrepancies.reduce((s, p) =>
    s + Math.abs(Number(p.supplier_invoice_gross || 0) - Number(p.total_value || 0)), 0);

  const overdue         = _filterOverdue(_supplierTilePos);
  const overdueThresh   = _getOverdueThresholdDays();
  const overdueValue    = overdue.reduce((s, p) => s + Number(p.total_value || 0), 0);

  const fmtVal = v => '£' + v.toLocaleString('en-GB', { minimumFractionDigits: 0, maximumFractionDigits: 0 });

  const tile = (key, icon, label, count, valueColour, subtitle) => `
    <div onclick="openSupplierPoTile('${key}')"
         style="background:var(--surface);border:1px solid var(--border);border-radius:10px;
                padding:16px 18px;cursor:pointer;transition:border-color .15s"
         onmouseenter="this.style.borderColor='var(--accent)'" onmouseleave="this.style.borderColor='var(--border)'">
      <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);margin-bottom:10px">
        ${icon} ${label}
      </div>
      <div style="font-size:32px;font-weight:700;font-family:var(--font-display);color:${valueColour}">
        ${count}
      </div>
      <div style="font-size:12px;color:var(--muted);margin-top:4px">
        ${subtitle}
      </div>
    </div>`;

  container.innerHTML =
    tile('awaiting-invoice', '📄', 'POs Awaiting Invoice', awaitingInvoice.length,
      awaitingInvoice.length ? 'var(--amber)' : 'var(--subtle)',
      awaitingInvoice.length ? `${fmtVal(awaitingValue)} outstanding` : 'All invoices received') +
    tile('discrepancy', '⚠️', 'Discrepancies', discrepancies.length,
      discrepancies.length ? 'var(--red)' : 'var(--subtle)',
      discrepancies.length
        ? `${fmtVal(discDiff)} off PO total${discrepancies.length !== 1 ? 's' : ''}`
        : 'All invoices reconciled') +
    tile('overdue', '⏰', 'Overdue POs', overdue.length,
      overdue.length ? 'var(--amber)' : 'var(--subtle)',
      overdue.length
        ? `${fmtVal(overdueValue)} · >${overdueThresh}d old`
        : `Nothing over ${overdueThresh} days`);
}

function openSupplierPoTile(tileKey) {
  if (tileKey === 'awaiting-invoice') {
    const pos = _filterAwaitingInvoice(_supplierTilePos);
    const totalVal = pos.reduce((s, p) => s + Number(p.total_value || 0), 0);
    document.getElementById('supplierPoTileTitle').textContent = 'POs Awaiting Invoice';
    document.getElementById('supplierPoTileSubtitle').textContent =
      `${pos.length} PO${pos.length !== 1 ? 's' : ''} · £${totalVal.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} total outstanding`;
    _renderAwaitingInvoiceBody(pos);
  } else if (tileKey === 'discrepancy') {
    const pos = _filterDiscrepancy(_supplierTilePos);
    const totalDiff = pos.reduce((s, p) =>
      s + Math.abs(Number(p.supplier_invoice_gross || 0) - Number(p.total_value || 0)), 0);
    document.getElementById('supplierPoTileTitle').textContent = 'Invoice Discrepancies';
    document.getElementById('supplierPoTileSubtitle').textContent =
      `${pos.length} PO${pos.length !== 1 ? 's' : ''} · £${totalDiff.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} total difference`;
    _renderDiscrepancyBody(pos);
  } else if (tileKey === 'overdue') {
    const pos = _filterOverdue(_supplierTilePos);
    const totalVal = pos.reduce((s, p) => s + Number(p.total_value || 0), 0);
    const threshold = _getOverdueThresholdDays();
    document.getElementById('supplierPoTileTitle').textContent = 'Overdue POs';
    document.getElementById('supplierPoTileSubtitle').textContent =
      `${pos.length} PO${pos.length !== 1 ? 's' : ''} over ${threshold} days · £${totalVal.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} outstanding`;
    _renderOverdueBody(pos);
  }
  document.getElementById('supplierPoTileModal').classList.add('active');
}

function _renderAwaitingInvoiceBody(pos) {
  const body = document.getElementById('supplierPoTileBody');
  if (!pos.length) {
    body.innerHTML = '<div style="padding:30px;text-align:center;color:var(--subtle);font-size:13px">No outstanding POs — all invoices received ✓</div>';
    return;
  }

  // Group by supplier name
  const bySupplier = {};
  pos.forEach(po => {
    const name = po.supplier_name || 'Unknown Supplier';
    if (!bySupplier[name]) bySupplier[name] = [];
    bySupplier[name].push(po);
  });

  // Sort suppliers by total outstanding value desc
  const sorted = Object.entries(bySupplier)
    .map(([name, list]) => ({ name, list, total: list.reduce((s, p) => s + Number(p.total_value || 0), 0) }))
    .sort((a, b) => b.total - a.total);

  const statusColour = { Open: 'var(--subtle)', Approved: 'var(--accent)', Sent: 'var(--amber)', Received: 'var(--green)' };
  const daysSince = d => d ? Math.floor((Date.now() - new Date(d).getTime()) / 86400000) : null;

  body.innerHTML = sorted.map(({ name, list, total }) => {
    const rows = list
      .sort((a, b) => new Date(a.created_at) - new Date(b.created_at)) // oldest first
      .map(po => {
        const age = daysSince(po.created_at);
        const ageLabel = age != null ? `${age}d ago` : '';
        const ageColour = age > 30 ? 'var(--red)' : age > 14 ? 'var(--amber)' : 'var(--subtle)';
        const project = po.project_number || po.cost_centre || '—';
        const statusCol = statusColour[po.status] || 'var(--subtle)';
        return `
          <tr style="border-top:1px solid var(--border)">
            <td style="padding:7px 10px 7px 0;font-size:12px;font-weight:600;color:var(--text)">${escapeHtml(po.reference || '—')}</td>
            <td style="padding:7px 4px;font-size:12px;color:var(--muted);max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml((po.description || '').slice(0, 60))}</td>
            <td style="padding:7px 4px;font-size:12px;color:var(--muted)">${escapeHtml(project)}</td>
            <td style="padding:7px 4px;font-size:12px;font-weight:600;text-align:right;white-space:nowrap">£${Number(po.total_value || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
            <td style="padding:7px 4px;font-size:11px;color:${statusCol}">${escapeHtml(po.status || '')}</td>
            <td style="padding:7px 0 7px 4px;font-size:11px;color:${ageColour};white-space:nowrap">${ageLabel}</td>
            <td style="padding:7px 0 7px 8px">
              <button class="btn btn-ghost" style="font-size:11px;padding:3px 9px"
                onclick="closeSupplierPoTileModal();openAttachSupplierInvoiceModal(${po.id})">
                📎 Attach
              </button>
            </td>
          </tr>`;
      }).join('');

    return `
      <div style="margin-bottom:16px">
        <div style="display:flex;align-items:baseline;justify-content:space-between;margin-bottom:6px">
          <div style="font-weight:600;font-size:14px">${escapeHtml(name)}</div>
          <div style="font-size:12px;color:var(--muted)">${list.length} PO${list.length !== 1 ? 's' : ''} · <b style="color:var(--text)">£${total.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</b></div>
        </div>
        <table style="width:100%;border-collapse:collapse">
          <thead>
            <tr style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--subtle)">
              <th style="padding:0 10px 6px 0;text-align:left;font-weight:600">Reference</th>
              <th style="padding:0 4px 6px;text-align:left;font-weight:600">Description</th>
              <th style="padding:0 4px 6px;text-align:left;font-weight:600">Project</th>
              <th style="padding:0 4px 6px;text-align:right;font-weight:600">Value</th>
              <th style="padding:0 4px 6px;text-align:left;font-weight:600">Status</th>
              <th style="padding:0 4px 6px;text-align:left;font-weight:600">Age</th>
              <th></th>
            </tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
      </div>`;
  }).join('<hr style="border:none;border-top:1px solid var(--border);margin:4px 0 16px">');
}

// ── Drill-down: Discrepancies ────────────────────────────────────────────────
// POs whose attached supplier invoice gross differs from the PO total_value by
// more than the £1 reconciliation tolerance. Grouped by supplier sorted by
// total absolute difference desc — biggest financial gaps surface first.
function _renderDiscrepancyBody(pos) {
  const body = document.getElementById('supplierPoTileBody');
  if (!pos.length) {
    body.innerHTML = '<div style="padding:30px;text-align:center;color:var(--subtle);font-size:13px">No discrepancies — all attached invoices reconcile within £1 ✓</div>';
    return;
  }

  const bySupplier = {};
  pos.forEach(po => {
    const name = po.supplier_name || 'Unknown Supplier';
    if (!bySupplier[name]) bySupplier[name] = [];
    bySupplier[name].push(po);
  });

  const sorted = Object.entries(bySupplier)
    .map(([name, list]) => ({
      name, list,
      totalDiff: list.reduce((s, p) =>
        s + Math.abs(Number(p.supplier_invoice_gross || 0) - Number(p.total_value || 0)), 0)
    }))
    .sort((a, b) => b.totalDiff - a.totalDiff);

  body.innerHTML = sorted.map(({ name, list, totalDiff }) => {
    const rows = list
      .sort((a, b) =>
        Math.abs(Number(b.supplier_invoice_gross || 0) - Number(b.total_value || 0)) -
        Math.abs(Number(a.supplier_invoice_gross || 0) - Number(a.total_value || 0)))
      .map(po => {
        const poVal  = Number(po.total_value || 0);
        const invVal = Number(po.supplier_invoice_gross || 0);
        const diff   = invVal - poVal;                  // signed: + means invoice overshoots PO
        const diffCol = diff > 0 ? 'var(--red)' : 'var(--amber)';
        const sign    = diff > 0 ? '+' : '−';
        const project = po.project_number || po.cost_centre || '—';
        return `
          <tr style="border-top:1px solid var(--border)">
            <td style="padding:7px 10px 7px 0;font-size:12px;font-weight:600">${escapeHtml(po.reference || '—')}</td>
            <td style="padding:7px 4px;font-size:12px;color:var(--muted)">${escapeHtml(project)}</td>
            <td style="padding:7px 4px;font-size:12px;color:var(--muted)">${escapeHtml(po.supplier_invoice_ref || '—')}</td>
            <td style="padding:7px 4px;font-size:12px;text-align:right;white-space:nowrap">£${poVal.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
            <td style="padding:7px 4px;font-size:12px;text-align:right;white-space:nowrap">£${invVal.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
            <td style="padding:7px 4px;font-size:12px;font-weight:600;text-align:right;color:${diffCol};white-space:nowrap">${sign}£${Math.abs(diff).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
            <td style="padding:7px 0 7px 8px">
              <button class="btn btn-ghost" style="font-size:11px;padding:3px 9px"
                onclick="closeSupplierPoTileModal();openPoDetailModal(${po.id})">
                View
              </button>
            </td>
          </tr>`;
      }).join('');

    return `
      <div style="margin-bottom:16px">
        <div style="display:flex;align-items:baseline;justify-content:space-between;margin-bottom:6px">
          <div style="font-weight:600;font-size:14px">${escapeHtml(name)}</div>
          <div style="font-size:12px;color:var(--muted)">${list.length} PO${list.length !== 1 ? 's' : ''} · <b style="color:var(--red)">£${totalDiff.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</b> off</div>
        </div>
        <table style="width:100%;border-collapse:collapse">
          <thead>
            <tr style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--subtle)">
              <th style="padding:0 10px 6px 0;text-align:left;font-weight:600">PO Ref</th>
              <th style="padding:0 4px 6px;text-align:left;font-weight:600">Project</th>
              <th style="padding:0 4px 6px;text-align:left;font-weight:600">Invoice Ref</th>
              <th style="padding:0 4px 6px;text-align:right;font-weight:600">PO £</th>
              <th style="padding:0 4px 6px;text-align:right;font-weight:600">Invoice £</th>
              <th style="padding:0 4px 6px;text-align:right;font-weight:600">Difference</th>
              <th></th>
            </tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
      </div>`;
  }).join('<hr style="border:none;border-top:1px solid var(--border);margin:4px 0 16px">');
}

// ── Drill-down: Overdue POs ──────────────────────────────────────────────────
// POs in Open/Approved/Sent older than the configured threshold with no
// delivery and no supplier invoice. Grouped by supplier; within each group,
// oldest first. Suppliers ordered by their oldest PO age (worst offenders top).
function _renderOverdueBody(pos) {
  const body = document.getElementById('supplierPoTileBody');
  const threshold = _getOverdueThresholdDays();
  if (!pos.length) {
    body.innerHTML = `<div style="padding:30px;text-align:center;color:var(--subtle);font-size:13px">Nothing overdue — no live POs older than ${threshold} days ✓</div>`;
    return;
  }

  const daysSince = d => d ? Math.floor((Date.now() - new Date(d).getTime()) / 86400000) : 0;

  const bySupplier = {};
  pos.forEach(po => {
    const name = po.supplier_name || 'Unknown Supplier';
    if (!bySupplier[name]) bySupplier[name] = [];
    bySupplier[name].push(po);
  });

  // Sort suppliers by their oldest PO age desc
  const sorted = Object.entries(bySupplier)
    .map(([name, list]) => ({
      name, list,
      maxAge: Math.max(...list.map(p => daysSince(p.created_at))),
      total:  list.reduce((s, p) => s + Number(p.total_value || 0), 0)
    }))
    .sort((a, b) => b.maxAge - a.maxAge);

  const statusColour = { Open: 'var(--subtle)', Approved: 'var(--accent)', Sent: 'var(--amber)' };

  body.innerHTML = sorted.map(({ name, list, maxAge, total }) => {
    const rows = list
      .sort((a, b) => new Date(a.created_at) - new Date(b.created_at))   // oldest first
      .map(po => {
        const age      = daysSince(po.created_at);
        const ageCol   = age > 60 ? 'var(--red)' : 'var(--amber)';
        const project  = po.project_number || po.cost_centre || '—';
        const statusCol = statusColour[po.status] || 'var(--subtle)';
        return `
          <tr style="border-top:1px solid var(--border)">
            <td style="padding:7px 10px 7px 0;font-size:12px;font-weight:600">${escapeHtml(po.reference || '—')}</td>
            <td style="padding:7px 4px;font-size:12px;color:var(--muted);max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml((po.description || '').slice(0, 60))}</td>
            <td style="padding:7px 4px;font-size:12px;color:var(--muted)">${escapeHtml(project)}</td>
            <td style="padding:7px 4px;font-size:12px;font-weight:600;text-align:right;white-space:nowrap">£${Number(po.total_value || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
            <td style="padding:7px 4px;font-size:11px;color:${statusCol}">${escapeHtml(po.status || '')}</td>
            <td style="padding:7px 0 7px 4px;font-size:11px;font-weight:600;color:${ageCol};white-space:nowrap">${age}d ago</td>
            <td style="padding:7px 0 7px 8px">
              <button class="btn btn-ghost" style="font-size:11px;padding:3px 9px"
                onclick="closeSupplierPoTileModal();openPoDetailModal(${po.id})">
                View
              </button>
            </td>
          </tr>`;
      }).join('');

    return `
      <div style="margin-bottom:16px">
        <div style="display:flex;align-items:baseline;justify-content:space-between;margin-bottom:6px">
          <div style="font-weight:600;font-size:14px">${escapeHtml(name)}</div>
          <div style="font-size:12px;color:var(--muted)">${list.length} PO${list.length !== 1 ? 's' : ''} · oldest <b style="color:var(--red)">${maxAge}d</b> · <b style="color:var(--text)">£${total.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</b></div>
        </div>
        <table style="width:100%;border-collapse:collapse">
          <thead>
            <tr style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--subtle)">
              <th style="padding:0 10px 6px 0;text-align:left;font-weight:600">Reference</th>
              <th style="padding:0 4px 6px;text-align:left;font-weight:600">Description</th>
              <th style="padding:0 4px 6px;text-align:left;font-weight:600">Project</th>
              <th style="padding:0 4px 6px;text-align:right;font-weight:600">Value</th>
              <th style="padding:0 4px 6px;text-align:left;font-weight:600">Status</th>
              <th style="padding:0 4px 6px;text-align:left;font-weight:600">Age</th>
              <th></th>
            </tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
      </div>`;
  }).join('<hr style="border:none;border-top:1px solid var(--border);margin:4px 0 16px">');
}
function openMergeSuppliersModal() {
  const sel = document.getElementById('mergeKeepSelect');
  if (!sel) return;
  sel.innerHTML = '<option value="">Select supplier to keep…</option>';
  (_suppliers || []).slice().sort((a, b) => a.supplier_name.localeCompare(b.supplier_name)).forEach(s => {
    const opt = document.createElement('option');
    opt.value = s.id;
    opt.textContent = s.supplier_name;
    sel.appendChild(opt);
  });
  document.getElementById('mergeDuplicateList').innerHTML =
    '<div style="font-size:12px;color:var(--subtle);padding:10px;text-align:center">Select a supplier to keep first</div>';
  document.getElementById('mergeSummary').style.display = 'none';
  document.getElementById('mergeConfirmBtn').disabled = true;
  document.getElementById('mergeSuppliersModal').classList.add('active');
}

function closeMergeSuppliersModal() {
  document.getElementById('mergeSuppliersModal').classList.remove('active');
}

function onMergeKeepChange() {
  const keepId = parseInt(document.getElementById('mergeKeepSelect').value);
  const list = document.getElementById('mergeDuplicateList');
  if (!keepId) {
    list.innerHTML = '<div style="font-size:12px;color:var(--subtle);padding:10px;text-align:center">Select a supplier to keep first</div>';
    document.getElementById('mergeConfirmBtn').disabled = true;
    return;
  }
  const others = (_suppliers || []).filter(s => s.id !== keepId)
    .sort((a, b) => a.supplier_name.localeCompare(b.supplier_name));
  list.innerHTML = others.map(s => `
    <label style="display:flex;align-items:center;gap:10px;padding:8px 10px;cursor:pointer;border-bottom:1px solid var(--border);font-size:13px" onchange="updateMergeSummary()">
      <input type="checkbox" value="${s.id}" style="width:15px;height:15px;flex-shrink:0">
      <span style="flex:1">${s.supplier_name}</span>
      ${s.city ? `<span style="font-size:11px;color:var(--muted)">${s.city}</span>` : ''}
    </label>`).join('');
  updateMergeSummary();
}

function updateMergeSummary() {
  const checked = document.querySelectorAll('#mergeDuplicateList input[type=checkbox]:checked');
  const btn = document.getElementById('mergeConfirmBtn');
  const summary = document.getElementById('mergeSummary');
  if (!checked.length) {
    btn.disabled = true;
    summary.style.display = 'none';
    return;
  }
  const keepName = document.getElementById('mergeKeepSelect').selectedOptions[0]?.text || '';
  const names = [...checked].map(cb => cb.closest('label').querySelector('span').textContent.trim());
  summary.style.display = 'block';
  summary.innerHTML = `<b>${names.join(', ')}</b> will be merged into <b>${keepName}</b>. Their POs will be repointed and the duplicate entries removed.`;
  btn.disabled = false;
}

async function confirmMergeSuppliers() {
  const keepId = parseInt(document.getElementById('mergeKeepSelect').value);
  const mergeIds = [...document.querySelectorAll('#mergeDuplicateList input[type=checkbox]:checked')].map(cb => parseInt(cb.value));
  if (!keepId || !mergeIds.length) return;

  const keepName = document.getElementById('mergeKeepSelect').selectedOptions[0]?.text || '';
  if (!(await bamaConfirm({ title: 'Merge suppliers', body: `Merge ${mergeIds.length} supplier(s) into "${keepName}"? This cannot be undone.`, confirmText: 'Merge', tone: 'danger' }))) return;

  try {
    const result = await api.post('/api/suppliers/merge', { keep_id: keepId, merge_ids: mergeIds });
    closeMergeSuppliersModal();
    toast(`Merged — ${result.posMoved || 0} PO(s) repointed to ${keepName}`, 'success');
    renderSuppliersTab();
  } catch (e) {
    toast('Merge failed — ' + (e.message || 'unknown error'), 'error');
  }
}

// ── Service Type Management ──
function toggleManageServices() {
  const area = document.getElementById('manageServicesArea');
  if (!area) return;
  area.style.display = area.style.display === 'none' ? 'block' : 'none';
  if (area.style.display === 'block') renderServiceTypeList();
}

function renderServiceTypeList() {
  const container = document.getElementById('serviceTypeList');
  if (!container) return;
  if (!_serviceTypes.length) {
    container.innerHTML = '<div style="font-size:13px;color:var(--muted)">No service types defined</div>';
    return;
  }

  const sorted = [..._serviceTypes].sort((a, b) => a.name.localeCompare(b.name));
  const groups = {};
  sorted.forEach(st => {
    const letter = (st.name[0] || '#').toUpperCase();
    if (!groups[letter]) groups[letter] = [];
    groups[letter].push(st);
  });

  container.innerHTML = `
    <div style="position:relative;margin-bottom:10px">
      <input type="text" id="svcMgmtSearch" class="field-input" placeholder="Filter services..." 
        style="padding-left:30px;font-size:13px"
        oninput="filterServiceTypeList()">
      <span style="position:absolute;left:10px;top:50%;transform:translateY(-50%);color:var(--muted);font-size:14px;pointer-events:none">&#128269;</span>
    </div>
    <div style="font-size:12px;color:var(--muted);margin-bottom:8px">${_serviceTypes.length} service${_serviceTypes.length !== 1 ? 's' : ''} total</div>
    <div id="svcMgmtGroupedList" style="max-height:300px;overflow-y:auto;padding-right:4px">
      ${Object.keys(groups).sort().map(letter => `
        <div class="svc-mgmt-group" data-letter="${letter}">
          <div style="font-size:11px;font-weight:700;color:var(--accent);text-transform:uppercase;letter-spacing:1px;padding:6px 0 4px;border-bottom:1px solid var(--border);margin-bottom:6px">${letter}</div>
          <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px">
            ${groups[letter].map(st => `
              <div class="svc-mgmt-pill" data-svc-name="${st.name.toLowerCase()}" style="display:flex;align-items:center;gap:6px;background:var(--card);border:1px solid var(--border);border-radius:8px;padding:5px 10px;font-size:13px">
                ${st.name}
                <button onclick="toggleServiceTypeFinish(${st.id}, ${st.is_finish ? 1 : 0})"
                  title="${st.is_finish ? 'Finishing service — click to unmark' : 'Click to mark as a finishing service (shows on assembly drawings)'}"
                  style="background:${st.is_finish ? 'rgba(99,102,241,.2)' : 'none'};border:1px solid ${st.is_finish ? 'rgba(99,102,241,.45)' : 'var(--border)'};color:${st.is_finish ? '#a5b4fc' : 'var(--muted)'};border-radius:5px;cursor:pointer;font-size:10px;padding:1px 6px;line-height:1.5">finish</button>
                <button onclick="deleteServiceType(${st.id}, '${st.name.replace(/'/g, "\\'")}')"
                  style="background:none;border:none;color:var(--red);cursor:pointer;font-size:14px;padding:0 2px;line-height:1" title="Remove">&#10005;</button>
              </div>`).join('')}
          </div>
        </div>`).join('')}
    </div>`;
}

function filterServiceTypeList() {
  const search = (document.getElementById('svcMgmtSearch')?.value || '').toLowerCase();
  document.querySelectorAll('.svc-mgmt-group').forEach(group => {
    const pills = group.querySelectorAll('.svc-mgmt-pill');
    let anyVisible = false;
    pills.forEach(pill => {
      const name = pill.dataset.svcName || '';
      const show = !search || name.includes(search);
      pill.style.display = show ? 'flex' : 'none';
      if (show) anyVisible = true;
    });
    group.style.display = anyVisible ? 'block' : 'none';
  });
}

async function addServiceType() {
  const input = document.getElementById('newServiceTypeName');
  const name = (input?.value || '').trim();
  const isFinish = !!document.getElementById('newServiceTypeIsFinish')?.checked;
  if (!name) { toast('Enter a service name', 'error'); return; }
  try {
    await api.post('/api/service-types', { name, is_finish: isFinish });
    input.value = '';
    const fchk = document.getElementById('newServiceTypeIsFinish');
    if (fchk) fchk.checked = false;
    _finishesCache = null; // bust so the assembly finish dropdown picks up new finishes
    await loadServiceTypes();
    renderServiceTypeList();
    toast('Service added ✓', 'success');
  } catch (e) { toast(e.message || 'Failed to add service', 'error'); }
}

// Flag/unflag a service type as a finishing service. Finishing services are the
// ones offered as selectable finishes on assembly drawings (Galvanising, paints,
// primers, etc.) — driven by ServiceTypes.is_finish.
async function toggleServiceTypeFinish(id, current) {
  try {
    await api.put(`/api/service-types/${id}`, { is_finish: current ? 0 : 1 });
    _finishesCache = null; // bust the assembly finishes cache
    await loadServiceTypes();
    renderServiceTypeList();
    toast(current ? 'Removed from finishing services' : 'Marked as finishing service ✓', 'success');
  } catch (e) { toast(e.message || 'Update failed', 'error'); }
}

async function deleteServiceType(id, name) {
  if (!(await bamaConfirm({ title: 'Remove service', body: `Remove service "${name}"? Existing supplier assignments will be unaffected.`, confirmText: 'Remove', tone: 'danger' }))) return;
  try {
    await api.delete(`/api/service-types/${id}`);
    await loadServiceTypes();
    renderServiceTypeList();
    toast('Service removed', 'info');
  } catch (e) { toast('Delete failed', 'error'); }
}

let clockLogWeekOffset = 0;

function changeClockLogWeek(dir) {
  clockLogWeekOffset += dir;
  // Don't allow navigating into the future
  if (clockLogWeekOffset > 0) { clockLogWeekOffset = 0; return; }
  if (clockLogWeekOffset < -1) { clockLogWeekOffset = -1; return; }
  renderClockLogForWeek();
}

function renderClockLogForWeek() {
  const { mon, sun } = getWeekDates(clockLogWeekOffset);
  const monStr = dateStr(mon);
  const sunStr = dateStr(sun);
  const thisWeekMon = dateStr(getWeekDates(0).mon);

  // Update week label
  const label = document.getElementById('clockLogWeekLabel');
  if (label) label.textContent = `${fmtDate(mon)} – ${fmtDate(sun)}`;

  // Update badge — clear visual distinction between this week and last/previous
  const badge = document.getElementById('clockLogWeekBadge');
  if (badge) {
    if (clockLogWeekOffset === 0) {
      badge.innerHTML = '<span>THIS WEEK</span>';
      badge.style.background = 'rgba(62,207,142,.15)';
      badge.style.color = 'var(--green)';
      badge.style.border = '1px solid rgba(62,207,142,.3)';
    } else {
      badge.innerHTML = '<span>LAST WEEK — PENDING REVIEW</span>';
      badge.style.background = 'rgba(245,158,11,.15)';
      badge.style.color = 'var(--amber)';
      badge.style.border = '1px solid rgba(245,158,11,.3)';
    }
  }

  // Show/hide approve week button
  let approveBtn = document.getElementById('approveWeekBtn');
  if (clockLogWeekOffset !== 0) {
    if (!approveBtn) {
      approveBtn = document.createElement('button');
      approveBtn.id = 'approveWeekBtn';
      approveBtn.className = 'btn btn-success';
      approveBtn.style.cssText = 'padding:8px 18px;font-size:13px;font-weight:600';
      approveBtn.textContent = '✓ Approve the week';
      approveBtn.onclick = openApproveWeekModal;
      // Insert after badge
      badge.parentNode.insertBefore(approveBtn, badge.nextSibling);
    }
    approveBtn.style.display = '';
  } else {
    if (approveBtn) approveBtn.style.display = 'none';
  }

  // Filter clockings for this week
  const weekClockings = state.timesheetData.clockings.filter(
    c => c.date >= monStr && c.date <= sunStr
  );
  renderClockLog(weekClockings);
}

function checkArchiveReminder() {
  const today = new Date();
  const dow = today.getDay(); // 0=Sun, 1=Mon
  if (dow !== 1) return; // Only show on Monday

  const { mon } = getWeekDates(-1); // Last week's Monday
  const lastMonStr = dateStr(mon);
  const alreadyArchived = state.timesheetData.archive && state.timesheetData.archive[`week_${lastMonStr}`];
  if (alreadyArchived) return;

  // Show reminder
  const existing = document.getElementById('archiveReminderBanner');
  if (existing) return;
  const banner = document.createElement('div');
  banner.id = 'archiveReminderBanner';
  banner.style.cssText = 'background:rgba(245,158,11,.1);border:1px solid rgba(245,158,11,.3);border-radius:10px;padding:12px 18px;display:flex;align-items:center;gap:12px;margin-bottom:16px;';
  banner.innerHTML = `
    <span style="font-size:18px">📁</span>
    <span style="flex:1;font-size:13px">Last week's timesheet hasn't been archived yet.</span>
    <button class="btn btn-primary" style="padding:6px 14px;font-size:12px" onclick="changePayrollWeek(-1);archiveWeek()">Archive Last Week</button>
  `;
  const payrollTab = document.getElementById('tab-payroll');
  if (payrollTab) payrollTab.insertBefore(banner, payrollTab.firstChild);
}

function getDayHoursForEmployee(empName, dateStr) {
  // Get total approved clocked hours for an employee on a specific date
  const clockings = (state.timesheetData.clockings || []).filter(c =>
    c.employeeName === empName && c.date === dateStr &&
    c.approvalStatus !== 'rejected'
  );
  return clockings.reduce((s, c) => s + (calcHours(c.clockIn, c.clockOut, c.breakMins, c.date) || 0), 0);
}

function renderPayroll() {
  const { mon, sun } = getWeekDates(payrollWeekOffset);
  document.getElementById('payrollWeekLabel').textContent =
    `${fmtDate(mon)} – ${fmtDate(sun)}`;

  const container = document.getElementById('payrollSummary');
  if (!container) return;
  const employees = (state.timesheetData.employees || []).filter(e => e.active !== false && (e.payType || 'payee') !== 'cis');

  if (!employees.length) {
    container.innerHTML = '<div class="empty-state">No employees set up yet.</div>';
    return;
  }

  // Build day columns Mon-Sun
  const days = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(mon);
    d.setDate(mon.getDate() + i);
    days.push({ label: ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i], date: dateStr(d) });
  }

  // Calculate payroll results
  const results = employees.map(e => {
    const payroll = calculatePayroll(e.name, mon, sun);
    const dayHrs = days.map(d => getDayHoursForEmployee(e.name, d.date) || 0);
    const totalHrs = dayHrs.reduce((s, h) => s + h, 0);
    return { emp: e, payroll, dayHrs, totalHrs };
  }).filter(r => r.totalHrs > 0 || r.payroll);

  if (!results.length) {
    container.innerHTML = '<div class="empty-state"><div class="icon">💷</div>No approved clockings this week</div>';
    return;
  }

  const grandTotal = results.reduce((s, r) => s + (r.payroll?.totalPay || 0), 0);
  const totalBasic = results.reduce((s, r) => s + (r.payroll?.basicPay || 0), 0);
  const totalOT    = results.reduce((s, r) => s + (r.payroll?.overtimePay || 0), 0);
  const totalDT    = results.reduce((s, r) => s + (r.payroll?.doublePay || 0), 0);
  const totalHol   = results.reduce((s, r) => s + ((r.payroll?.holidayPay || 0) + (r.payroll?.bankHolidayPay || 0)), 0);

  // Format hours: show up to 2dp (so .25/.75 quarters render correctly) but
  // always at least 1dp for visual consistency (12 → "12.0", 9.75 → "9.75").
  const fmtHrs = (n) => {
    const s = (Math.round(n * 100) / 100).toString();
    return s.includes('.') ? s : s + '.0';
  };

  // Render a single day cell. Combines worked + booked-holiday + bank-holiday
  // into one display. BH and worked never co-occur (clock-in is blocked on
  // bank holidays). Holiday and worked CAN co-occur on a half-day.
  const renderDayCell = (r, ds) => {
    const worked = r.payroll?.dayHours?.[ds] || 0;
    const hol    = r.payroll?.dayHoliday?.[ds] || 0;
    const bh     = r.payroll?.dayBankHoliday?.[ds] || 0;
    const totalHol = hol + bh;

    if (totalHol > 0 && worked === 0) {
      return `<td class="mono" style="text-align:center;color:var(--accent)">${fmtHrs(totalHol)}<sub style="font-size:9px;color:var(--muted);margin-left:1px">H</sub></td>`;
    }
    if (worked > 0 && totalHol > 0) {
      // Half-day holiday + worked half-day
      return `<td class="mono" style="text-align:center">${fmtHrs(worked)}<br><span style="font-size:10px;color:var(--accent)">+${fmtHrs(totalHol)}H</span></td>`;
    }
    return `<td class="mono" style="text-align:center;color:${worked > 0 ? 'var(--text)' : 'var(--subtle)'}">${worked > 0 ? fmtHrs(worked) : '—'}</td>`;
  };

  container.innerHTML = `
    <div style="overflow-x:auto">
      <table class="summary-table" style="min-width:980px">
        <thead>
          <tr>
            <th style="min-width:140px">EMPLOYEE</th>
            ${days.map(d => `<th style="text-align:center;min-width:55px">${d.label}<br><span style="font-weight:400;font-size:9px;color:var(--subtle)">${d.date.slice(8)}</span></th>`).join('')}
            <th style="text-align:center">TOTAL HRS</th>
            <th>STD (£)</th>
            <th>O/T ×1.5 (£)</th>
            <th>DBL ×2 (£)</th>
            <th style="color:var(--accent)">HOL (£)</th>
            <th style="color:var(--green)">TOTAL PAY</th>
          </tr>
        </thead>
        <tbody>
          ${results.map(r => {
            const holHrs = (r.payroll?.holidayHours || 0) + (r.payroll?.bankHolidayHours || 0);
            const holPay = (r.payroll?.holidayPay   || 0) + (r.payroll?.bankHolidayPay   || 0);
            const totalAllHrs = r.totalHrs + holHrs; // include holiday in total hours column
            return `
            <tr>
              <td style="font-weight:600">
                ${r.emp.name}
                ${r.payroll?.doubleTimeApplies ? '<span class="manually-edited-badge" style="background:rgba(62,207,142,.15);color:var(--green);border-color:rgba(62,207,142,.3)">SAT+SUN</span>' : ''}
                <br><span style="font-size:11px;color:var(--muted);font-family:var(--font-mono)">£${(r.emp.rate||0).toFixed(2)}/hr</span>
              </td>
              ${days.map(d => renderDayCell(r, d.date)).join('')}
              <td class="mono" style="text-align:center;font-weight:700">${fmtHrs(totalAllHrs)}</td>
              <td class="mono">${r.payroll?.basicHours||0}h<br><span style="font-size:11px;color:var(--muted)">£${(r.payroll?.basicPay||0).toFixed(2)}</span></td>
              <td class="mono" style="color:var(--amber)">${r.payroll?.overtimeHours > 0 ? r.payroll.overtimeHours+'h' : '—'}<br><span style="font-size:11px;color:var(--muted)">${r.payroll?.overtimeHours > 0 ? '£'+r.payroll.overtimePay.toFixed(2) : ''}</span></td>
              <td class="mono" style="color:var(--accent)">${r.payroll?.doubleHours > 0 ? r.payroll.doubleHours+'h' : '—'}<br><span style="font-size:11px;color:var(--muted)">${r.payroll?.doubleHours > 0 ? '£'+r.payroll.doublePay.toFixed(2) : ''}</span></td>
              <td class="mono" style="color:var(--accent)">${holHrs > 0 ? holHrs+'h' : '—'}<br><span style="font-size:11px;color:var(--muted)">${holHrs > 0 ? '£'+holPay.toFixed(2) : ''}</span></td>
              <td class="mono" style="color:var(--green);font-weight:700;font-size:15px">£${(r.payroll?.totalPay||0).toFixed(2)}</td>
            </tr>
          `;}).join('')}
        </tbody>
        <tfoot>
          <tr style="border-top:2px solid var(--border)">
            <td style="font-weight:700;color:var(--muted);font-size:11px;letter-spacing:1px;text-transform:uppercase">TOTALS</td>
            ${days.map((d, i) => {
              // Day totals include holiday + BH for the day
              const dayTotal = results.reduce((s, r) => {
                const w = r.dayHrs[i] || 0;
                const h = r.payroll?.dayHoliday?.[d.date] || 0;
                const bh = r.payroll?.dayBankHoliday?.[d.date] || 0;
                return s + w + h + bh;
              }, 0);
              return `<td class="mono" style="text-align:center;font-weight:600">${dayTotal > 0 ? fmtHrs(dayTotal) : '—'}</td>`;
            }).join('')}
            <td class="mono" style="text-align:center;font-weight:700">${fmtHrs(results.reduce((s,r)=>{
              const holHrs = (r.payroll?.holidayHours || 0) + (r.payroll?.bankHolidayHours || 0);
              return s + r.totalHrs + holHrs;
            },0))}</td>
            <td class="mono" style="font-weight:600">£${totalBasic.toFixed(2)}</td>
            <td class="mono" style="font-weight:600;color:var(--amber)">£${totalOT.toFixed(2)}</td>
            <td class="mono" style="font-weight:600;color:var(--accent)">£${totalDT.toFixed(2)}</td>
            <td class="mono" style="font-weight:600;color:var(--accent)">£${totalHol.toFixed(2)}</td>
            <td class="mono" style="color:var(--green);font-weight:700;font-size:16px">£${grandTotal.toFixed(2)}</td>
          </tr>
        </tfoot>
      </table>
    </div>
  `;
}

function changePayrollWeek(dir) {
  payrollWeekOffset += dir;
  renderPayroll();
  renderPayrollExtras();
}

function jumpToPayrollWeek(dateValue) {
  if (!dateValue) return;
  const picked = new Date(dateValue);
  const today = new Date();
  // Calculate how many weeks between the current week and the picked date's week
  const todayMon = new Date(today);
  todayMon.setDate(today.getDate() - ((today.getDay() + 6) % 7));
  todayMon.setHours(0,0,0,0);
  const pickedMon = new Date(picked);
  pickedMon.setDate(picked.getDate() - ((picked.getDay() + 6) % 7));
  pickedMon.setHours(0,0,0,0);
  const diffWeeks = Math.round((pickedMon - todayMon) / (7 * 24 * 60 * 60 * 1000));
  payrollWeekOffset = diffWeeks;
  renderPayroll();
  renderPayrollExtras();
}

// ═══════════════════════════════════════════════════════════════════════════
// PAYROLL COMMENTS + REVISIONS
// ═══════════════════════════════════════════════════════════════════════════

let _payrollExtras = { weekKey: null, comments: [], revisions: [] };
let _editingPayrollCommentId = null;

// Year folder name pattern: 2026 -> "00 - 2026", 2027 -> "01 - 2027", etc.
function getPayrollYearFolderName(year) {
  const offset = year - 2026;
  return `${String(offset).padStart(2, '0')} - ${year}`;
}

// "27 Apr 2026 \u2013 03 May 2026" + optional " rev{N}"
function getPayrollFileName(monDate, sunDate, revisionNumber) {
  const fmt = d => d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
  const base = `${fmt(monDate)} \u2013 ${fmt(sunDate)}`;
  const suffix = revisionNumber > 0 ? ` rev${revisionNumber}` : '';
  return `${base}${suffix}.pdf`;
}

// Load comments + revisions for the currently-viewed week
async function loadPayrollExtras(weekCommencing) {
  try {
    const [comments, revisions] = await Promise.all([
      api.get(`/api/payroll-comments?week_commencing=${weekCommencing}`).catch(() => []),
      api.get(`/api/payroll-revisions?week_commencing=${weekCommencing}`).catch(() => [])
    ]);
    _payrollExtras = { weekKey: weekCommencing, comments: comments || [], revisions: revisions || [] };
  } catch (err) {
    console.warn('Failed to load payroll extras:', err);
    _payrollExtras = { weekKey: weekCommencing, comments: [], revisions: [] };
  }
}

// Render the comments + revisions block below the payroll table
async function renderPayrollExtras() {
  const container = document.getElementById('payrollExtras');
  if (!container) return;
  const { mon } = getWeekDates(payrollWeekOffset);
  const monStr = dateStr(mon);

  if (_payrollExtras.weekKey !== monStr) {
    container.innerHTML = '<div class="empty-state" style="padding:12px"><div class="spinner"></div></div>';
    await loadPayrollExtras(monStr);
  }

  const { comments, revisions } = _payrollExtras;
  const fmtDateTime = iso => {
    if (!iso) return '';
    const d = new Date(iso);
    return d.toLocaleString('en-GB', { day:'numeric', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit' });
  };

  let commentsHtml = '';
  if (!comments.length) {
    commentsHtml = `<div style="color:var(--subtle);font-size:13px;padding:12px;text-align:center">No instructions for this payroll week. Click <b>+ Add Payroll Instructions</b> to leave a note.</div>`;
  } else {
    commentsHtml = comments.map(c => {
      const wasEdited = c.updated_at && c.updated_by;
      return `
        <div style="background:var(--surface);border:1px solid var(--border);border-left:3px solid var(--accent2);border-radius:8px;padding:12px 14px;margin-bottom:8px">
          <div style="font-size:13px;color:var(--text);white-space:pre-wrap;margin-bottom:6px">${escapeHtml(c.comment)}</div>
          <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:11px;color:var(--muted)">
            <div>
              <span><b>${escapeHtml(c.created_by)}</b> &middot; ${fmtDateTime(c.created_at)}</span>
              ${wasEdited ? `<span style="margin-left:10px;color:var(--subtle)">(edited by ${escapeHtml(c.updated_by)} &middot; ${fmtDateTime(c.updated_at)})</span>` : ''}
            </div>
            <div style="display:flex;gap:6px">
              <button class="tiny-btn" style="padding:3px 10px;font-size:11px" onclick="editPayrollComment(${c.id})">Edit</button>
              <button class="tiny-btn tiny-reject" style="padding:3px 10px;font-size:11px" onclick="deletePayrollComment(${c.id})">Delete</button>
            </div>
          </div>
        </div>`;
    }).join('');
  }

  let revisionsHtml = '';
  if (revisions.length > 0) {
    revisionsHtml = `
      <div class="card" style="margin-top:14px">
        <div class="card-title" style="font-size:13px"><span class="icon">\u{1F4DC}</span> Revision History</div>
        <div style="font-size:12px;color:var(--muted);margin-bottom:10px">
          This week's payroll has been generated ${revisions.length} time${revisions.length !== 1 ? 's' : ''}. Each generation is preserved on SharePoint.
        </div>
        <table class="summary-table" style="font-size:12px">
          <thead><tr><th>VERSION</th><th>FILE</th><th>BY</th><th>WHEN</th></tr></thead>
          <tbody>
            ${revisions.map(r => `
              <tr>
                <td><b>${r.revision_number === 0 ? 'Original' : `rev${r.revision_number}`}</b></td>
                <td class="mono" style="font-size:11px">
                  ${r.file_url
                    ? `<a href="${escapeHtml(r.file_url)}" target="_blank" style="color:var(--accent2)">${escapeHtml(r.file_name)}</a>`
                    : escapeHtml(r.file_name)}
                </td>
                <td>${escapeHtml(r.created_by)}</td>
                <td>${fmtDateTime(r.created_at)}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>`;
  }

  container.innerHTML = `
    <div class="card">
      <div class="card-title" style="font-size:13px"><span class="icon">\u{1F4DD}</span> Payroll Instructions</div>
      ${commentsHtml}
    </div>
    ${revisionsHtml}
  `;
}

function openPayrollCommentModal() {
  _editingPayrollCommentId = null;
  document.getElementById('payrollCommentModalTitle').textContent = 'Add Payroll Instruction';
  document.getElementById('payrollCommentSaveBtn').textContent = 'Save';
  document.getElementById('payrollCommentText').value = '';
  const { mon, sun } = getWeekDates(payrollWeekOffset);
  document.getElementById('payrollCommentWeekLabel').textContent =
    `Week: ${fmtDate(mon)} \u2013 ${fmtDate(sun)}`;
  document.getElementById('payrollCommentModal').classList.add('active');
  setTimeout(() => document.getElementById('payrollCommentText').focus(), 100);
}

function editPayrollComment(id) {
  const c = (_payrollExtras.comments || []).find(x => x.id === id);
  if (!c) return;
  _editingPayrollCommentId = id;
  document.getElementById('payrollCommentModalTitle').textContent = 'Edit Payroll Instruction';
  document.getElementById('payrollCommentSaveBtn').textContent = 'Save Changes';
  document.getElementById('payrollCommentText').value = c.comment;
  const { mon, sun } = getWeekDates(payrollWeekOffset);
  document.getElementById('payrollCommentWeekLabel').textContent =
    `Week: ${fmtDate(mon)} \u2013 ${fmtDate(sun)}`;
  document.getElementById('payrollCommentModal').classList.add('active');
  setTimeout(() => document.getElementById('payrollCommentText').focus(), 100);
}

function closePayrollCommentModal() {
  document.getElementById('payrollCommentModal').classList.remove('active');
  _editingPayrollCommentId = null;
}

async function savePayrollComment() {
  const text = document.getElementById('payrollCommentText').value.trim();
  if (!text) { toast('Please enter a comment', 'error'); return; }
  const author = currentManagerUser || 'office';
  const { mon } = getWeekDates(payrollWeekOffset);
  const monStr = dateStr(mon);

  try {
    if (_editingPayrollCommentId) {
      await api.put(`/api/payroll-comments/${_editingPayrollCommentId}`, {
        comment: text, updated_by: author
      });
      toast('Comment updated \u2713', 'success');
    } else {
      await api.post('/api/payroll-comments', {
        week_commencing: monStr, comment: text, created_by: author
      });
      toast('Comment added \u2713', 'success');
    }
    closePayrollCommentModal();
    _payrollExtras.weekKey = null;
    await renderPayrollExtras();
  } catch (err) {
    toast('Save failed: ' + err.message, 'error');
  }
}

async function deletePayrollComment(id) {
  if (!(await bamaConfirm({ title: 'Delete instruction', body: 'Delete this payroll instruction?', confirmText: 'Delete', tone: 'danger' }))) return;
  try {
    await api.delete(`/api/payroll-comments/${id}`);
    toast('Comment deleted', 'info');
    _payrollExtras.weekKey = null;
    await renderPayrollExtras();
  } catch (err) {
    toast('Delete failed: ' + err.message, 'error');
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// EMAIL TO PAYROLL — generate PDF, save to SharePoint, open Outlook draft
// ═══════════════════════════════════════════════════════════════════════════

async function findOrCreatePayrollYearFolder(year) {
  const token = await getToken();
  const payrollPath = '01 - Accounts/02 - Payroll';
  const lookup = await fetch(
    `https://graph.microsoft.com/v1.0/drives/${BAMA_DRIVE_ID}/root:/${encodeURIComponent(payrollPath)}`,
    { headers: { 'Authorization': `Bearer ${token}` } }
  );
  if (!lookup.ok) {
    throw new Error(`Cannot find SharePoint folder "01 - Accounts/02 - Payroll" (status ${lookup.status})`);
  }
  const parent = await lookup.json();
  const yearFolderName = getPayrollYearFolderName(year);
  const folder = await getOrCreateSubfolder(parent.id, yearFolderName, BAMA_DRIVE_ID);
  if (!folder) throw new Error(`Could not create year folder "${yearFolderName}"`);
  return folder;
}

// Renders the payroll PDF using the SAME mechanism as the Export to PDF
// button — a real browser window that natively renders the HTML — and uses
// html2pdf inside that window to capture a Blob. This is far more reliable
// than rasterising an off-screen iframe in the parent document context,
// which suffered from layout cropping, dark backgrounds bleeding from
// bama.css, and host-page coordinate confusion in html2canvas.
//
// `popupWin` MUST be opened by the caller synchronously inside the user's
// click handler — popup blockers will reject window.open() if it's called
// after any awaits. The caller should pass the resulting Window in.
async function renderPayrollPDFBlob(weekStr, popupWin) {
  if (!popupWin) throw new Error('Render window not provided — cannot generate PDF');

  const { mon, sun } = getWeekDates(payrollWeekOffset);
  const monStr = dateStr(mon);
  const employees = (state.timesheetData.employees || []).filter(e => e.active !== false && (e.payType || 'payee') !== 'cis');
  const results = employees.map(e => calculatePayroll(e.name, mon, sun)).filter(Boolean);
  if (!results.length) {
    try { popupWin.close(); } catch (e) {}
    throw new Error('No payroll data this week');
  }

  const totals = {
    basic: results.reduce((s, r) => s + r.basicPay, 0),
    ot:    results.reduce((s, r) => s + r.overtimePay, 0),
    dt:    results.reduce((s, r) => s + r.doublePay, 0),
    hol:   results.reduce((s, r) => s + (r.holidayPay || 0) + (r.bankHolidayPay || 0), 0),
    grand: results.reduce((s, r) => s + r.totalPay, 0)
  };

  // Pull payroll instruction comments for this week so they appear in the
  // PDF saved to SharePoint, same as the Export to PDF button.
  let comments = [];
  if (_payrollExtras.weekKey === monStr) {
    comments = _payrollExtras.comments || [];
  } else {
    try { comments = await api.get(`/api/payroll-comments?week_commencing=${monStr}`) || []; }
    catch (e) { console.warn('Could not load payroll comments for PDF:', e); }
  }

  await loadLogoDataUri();
  const baseHtml = buildPayrollHTML({ results, totals, weekStr, comments });

  // Inject the html2pdf library + a tiny capture bridge into the document
  // BEFORE writing it so it executes after the body parses. The bridge
  // signals back to us via a global flag once the PDF Blob is ready.
  const captureScript = `
    <script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"><\/script>
    <script>
      window.__pdfReady = false;
      window.__pdfBlob = null;
      window.__pdfError = null;
      async function __capturePDF() {
        try {
          // Wait for fonts.
          if (document.fonts && document.fonts.ready) {
            try { await document.fonts.ready; } catch (e) {}
          }
          // Wait for images.
          const imgs = Array.from(document.images);
          await Promise.all(imgs.map(img => {
            if (img.complete && img.naturalWidth > 0) return Promise.resolve();
            return new Promise(res => {
              img.addEventListener('load', res, { once: true });
              img.addEventListener('error', res, { once: true });
              setTimeout(res, 3000);
            });
          }));
          // Let layout settle.
          await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
          const blob = await html2pdf().set({
            margin: [10, 10, 10, 10],
            filename: 'payroll.pdf',
            image: { type: 'jpeg', quality: 0.95 },
            html2canvas: { scale: 2, useCORS: true, backgroundColor: '#ffffff' },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
          }).from(document.body).outputPdf('blob');
          window.__pdfBlob = blob;
        } catch (err) {
          window.__pdfError = err && err.message ? err.message : String(err);
        } finally {
          window.__pdfReady = true;
        }
      }
      window.addEventListener('load', __capturePDF);
    <\/script>
  `;

  // Splice the capture script in just before </body>.
  const html = baseHtml.replace(/<\/body>/i, captureScript + '</body>');

  popupWin.document.open();
  popupWin.document.write(html);
  popupWin.document.close();

  // Poll for the bridge to signal completion. 30 s ceiling is generous —
  // a normal capture is < 2 s.
  const start = Date.now();
  while (!popupWin.__pdfReady) {
    if (Date.now() - start > 30000) {
      try { popupWin.close(); } catch (e) {}
      throw new Error('PDF render timed out after 30 s');
    }
    await new Promise(r => setTimeout(r, 100));
  }

  if (popupWin.__pdfError) {
    const errMsg = popupWin.__pdfError;
    try { popupWin.close(); } catch (e) {}
    throw new Error('PDF render failed: ' + errMsg);
  }

  const blob = popupWin.__pdfBlob;
  try { popupWin.close(); } catch (e) {}
  if (!blob) throw new Error('PDF render produced no blob');
  return blob;
}

function fillPayrollEmailTemplate(tpl, ctx) {
  if (!tpl) return '';
  return tpl
    .replace(/\{weekRange\}/g, ctx.weekRange || '')
    .replace(/\{totalPay\}/g, ctx.totalPay || '')
    .replace(/\{totalEmployees\}/g, ctx.totalEmployees != null ? String(ctx.totalEmployees) : '')
    .replace(/\{url\}/g, ctx.url || '')
    .replace(/\{instructions\}/g, ctx.instructions || '');
}

async function emailPayrollReport() {
  const { mon, sun } = getWeekDates(payrollWeekOffset);
  const monStr = dateStr(mon);
  const weekStr = `${fmtDate(mon)} \u2013 ${fmtDate(sun)}`;
  const fmtFull = d => d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
  const weekStrFull = `${fmtFull(mon)} \u2013 ${fmtFull(sun)}`;
  const author = currentManagerUser || 'office';

  let revisions = [];
  try {
    revisions = await api.get(`/api/payroll-revisions?week_commencing=${monStr}`) || [];
  } catch (e) {
    console.warn('Failed to load revisions:', e);
  }

  // Open the render window inside the modal's confirm-click handler so it's
  // a fresh user gesture (popup blockers reject window.open after awaits).
  // The window is positioned mostly off-screen so it doesn't disturb the user.
  const openRenderWindow = () => {
    const w = window.open('', '_blank',
      'width=860,height=400,left=' + (screen.width || 1200) + ',top=0,noopener=no');
    if (w) {
      try { w.document.write('<!DOCTYPE html><html><head><title>Generating payroll PDF…</title><style>body{font-family:sans-serif;color:#666;padding:40px;text-align:center}</style></head><body>Generating payroll PDF…</body></html>'); } catch (e) {}
    }
    return w;
  };

  let popupWin = null;
  if (revisions.length > 0) {
    // Already generated → confirm override (BAMA-styled)
    const lastRev = revisions[revisions.length - 1];
    const lastLabel = lastRev.revision_number === 0 ? 'the original' : `rev${lastRev.revision_number}`;
    const result = await showConfirmAsync(
      'Override existing payroll?',
      `<div style="margin-bottom:14px">Payroll for <b>${escapeHtml(weekStr)}</b> has already been generated (${escapeHtml(lastLabel)}, by <b>${escapeHtml(lastRev.created_by)}</b>).</div>
       <div style="margin-bottom:14px">Do you want to override and generate a <b>new revision</b>?</div>
       <div style="font-size:12px;color:var(--subtle)">The original file will be kept on SharePoint.</div>`,
      { okLabel: 'Generate revision', cancelLabel: 'Cancel', onConfirmSync: openRenderWindow }
    );
    if (!result.ok) return;
    popupWin = result.data;
  } else {
    // First-time generation → confirm to prevent accidental click
    const result = await showConfirmAsync(
      'Email payroll report?',
      `<div style="margin-bottom:14px">This will:</div>
       <ul style="margin:0 0 14px 18px;padding:0;color:var(--muted);font-size:13px;line-height:1.7">
         <li>Generate a payroll PDF for <b>${escapeHtml(weekStr)}</b></li>
         <li>Save it to SharePoint (<code style="font-size:12px">01 - Accounts/02 - Payroll</code>)</li>
         <li>Open an email draft with the file link</li>
       </ul>
       <div style="font-size:12px;color:var(--subtle)">Continue?</div>`,
      { okLabel: 'Generate & email', cancelLabel: 'Cancel', onConfirmSync: openRenderWindow }
    );
    if (!result.ok) return;
    popupWin = result.data;
  }

  if (!popupWin) {
    toast('Popup blocked — allow pop-ups for this site and try again', 'error');
    return;
  }

  const nextRevision = revisions.length === 0
    ? 0
    : Math.max(...revisions.map(r => r.revision_number)) + 1;
  const fileName = getPayrollFileName(mon, sun, nextRevision);

  toast(`Generating payroll PDF (${nextRevision === 0 ? 'original' : 'rev' + nextRevision})...`, 'info');
  setLoading(true);

  try {
    const pdfBlob = await renderPayrollPDFBlob(weekStrFull, popupWin);

    const year = mon.getFullYear();
    const yearFolder = await findOrCreatePayrollYearFolder(year);

    const token = await getToken();
    const uploadUrl = `https://graph.microsoft.com/v1.0/drives/${BAMA_DRIVE_ID}/items/${yearFolder.id}:/${encodeURIComponent(fileName)}:/content`;
    const upRes = await fetch(uploadUrl, {
      method: 'PUT',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/pdf' },
      body: pdfBlob
    });
    if (!upRes.ok) throw new Error(`SharePoint upload failed: ${upRes.status}`);
    const uploaded = await upRes.json();

    await api.post('/api/payroll-revisions', {
      week_commencing: monStr,
      revision_number: nextRevision,
      file_name: fileName,
      file_url: uploaded.webUrl,
      created_by: author
    });

    const employees = (state.timesheetData.employees || []).filter(e => e.active !== false && (e.payType || 'payee') !== 'cis');
    const results = employees.map(e => calculatePayroll(e.name, mon, sun)).filter(Boolean);
    const grandTotal = results.reduce((s, r) => s + r.totalPay, 0);

    // Fetch comments first so they're available for the {instructions}
    // template placeholder.
    let comments = [];
    try { comments = await api.get(`/api/payroll-comments?week_commencing=${monStr}`) || []; }
    catch (e) { /* non-fatal */ }

    // Format instructions as a bulleted list. Empty string if there are
    // none — keeps the template clean (avoids 'Payroll instructions:' with
    // no items underneath).
    const instructionsText = comments.length
      ? comments.map(c => `- ${c.comment}`).join('\n')
      : '';

    const ctx = {
      weekRange: weekStrFull,
      totalPay: '\u00a3' + grandTotal.toFixed(2),
      totalEmployees: results.length,
      url: uploaded.webUrl,
      instructions: instructionsText
    };

    const subjectTpl = tplGet('payroll', 'emailSubject') || 'BAMA Payroll Report \u2014 Week {weekRange}';
    const bodyTpl    = tplGet('payroll', 'emailBody') || '';
    const subject = fillPayrollEmailTemplate(subjectTpl, ctx);
    let body = fillPayrollEmailTemplate(bodyTpl, ctx);

    // Backward-compatible fallback: if the user's template doesn't include
    // {url}, append the URL at the end (so old templates still produce a
    // working email). Same for {instructions}.
    body = body.replace(/\s+$/g, '');
    if (!/\{url\}/.test(bodyTpl)) {
      if (instructionsText && !/\{instructions\}/.test(bodyTpl)) {
        body += '\n\nPayroll Instructions:\n' + instructionsText;
      }
      body += `\n\nPlease find the below payroll file ready for processing:\n${uploaded.webUrl}`;
    }

    _payrollExtras.weekKey = null;
    await renderPayrollExtras();

    setLoading(false);
    toast(`PDF saved to SharePoint as ${fileName} \u2713`, 'success');

    const mailto = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    if (mailto.length > 2000) {
      console.info('Long mailto URL — some email clients may truncate. Body length:', body.length);
    }
    window.location.href = mailto;
  } catch (err) {
    setLoading(false);
    try { if (popupWin && !popupWin.closed) popupWin.close(); } catch (e) {}
    console.error('Payroll email flow failed:', err);
    toast('Failed: ' + err.message, 'error');
  }
}


async function generatePayrollPDF() {
  const { mon, sun } = getWeekDates(payrollWeekOffset);
  const monStr = dateStr(mon);
  const employees = (state.timesheetData.employees || []).filter(e => e.active !== false && (e.payType || 'payee') !== 'cis');
  const results = employees.map(e => calculatePayroll(e.name, mon, sun)).filter(Boolean);

  if (!results.length) { toast('No payroll data to export', 'error'); return; }

  // IMPORTANT: open the print window synchronously while we're still inside
  // the user-gesture stack, otherwise popup blockers will silently kill it
  // after the awaits below.
  const printWin = window.open('', '_blank');
  if (!printWin) {
    toast('Popup blocked — allow pop-ups for this site and try again', 'error');
    return;
  }
  printWin.document.write('<!DOCTYPE html><html><head><title>Generating payroll…</title><style>body{font-family:sans-serif;color:#666;padding:40px;text-align:center}</style></head><body>Generating payroll PDF…</body></html>');

  const totals = {
    basic: results.reduce((s, r) => s + r.basicPay, 0),
    ot: results.reduce((s, r) => s + r.overtimePay, 0),
    dt: results.reduce((s, r) => s + r.doublePay, 0),
    hol: results.reduce((s, r) => s + (r.holidayPay || 0) + (r.bankHolidayPay || 0), 0),
    grand: results.reduce((s, r) => s + r.totalPay, 0)
  };
  const weekStr = `${fmtDate(mon)} – ${fmtDate(sun)}`;

  // Ensure logo is loaded into cache so it embeds in the print window
  await loadLogoDataUri();

  // Pull payroll instruction comments for this week. Use cached value when
  // it matches the visible week; otherwise fetch fresh. Non-fatal on failure.
  let comments = [];
  if (_payrollExtras.weekKey === monStr) {
    comments = _payrollExtras.comments || [];
  } else {
    try { comments = await api.get(`/api/payroll-comments?week_commencing=${monStr}`) || []; }
    catch (e) { console.warn('Could not load payroll comments for PDF:', e); }
  }

  const html = buildPayrollHTML({ results, totals, weekStr, comments });
  // Replace the placeholder content with the real PDF view.
  printWin.document.open();
  printWin.document.write(html + `<script>window.onload = function() { window.print(); }<\/script>`);
  printWin.document.close();
}

// ═══════════════════════════════════════════
// WEEKLY ARCHIVE
// ═══════════════════════════════════════════
async function archiveWeek() {
  const { mon, sun } = getWeekDates(payrollWeekOffset);
  const monStr = dateStr(mon);
  const sunStr = dateStr(sun);

  try {
    // Call the API to approve the week — it calculates payroll server-side
    const result = await api.post('/api/payroll/approve', {
      week_commencing: monStr
    });

    // Store in local state for immediate display
    const weekKey = `week_${monStr}`;
    if (!state.timesheetData.archive) state.timesheetData.archive = {};
    state.timesheetData.archive[weekKey] = {
      weekCommencing: monStr,
      weekEnding: sunStr,
      archivedAt: new Date().toISOString(),
      entries: state.timesheetData.entries.filter(e => e.date >= monStr && e.date <= sunStr),
      clockings: state.timesheetData.clockings.filter(c => c.date >= monStr && c.date <= sunStr),
      payroll: (result.records || []).map(r => ({
        employeeName: empNameById(r.employee_id) || `Employee #${r.employee_id}`,
        totalHours: r.total_hours,
        basicHours: r.basic_hours,
        overtimeHours: r.overtime_hours,
        doubleHours: r.double_hours || 0,
        holidayHours: r.holiday_hours || 0,
        bankHolidayHours: r.bank_holiday_hours || 0,
        rate: r.rate,
        basicPay: r.basic_pay,
        overtimePay: r.overtime_pay,
        doublePay: r.double_pay || 0,
        holidayPay: r.holiday_pay || 0,
        bankHolidayPay: r.bank_holiday_pay || 0,
        totalPay: r.total_pay
      }))
    };

    // Mark entries as approved locally
    state.timesheetData.entries.forEach(e => {
      if (e.date >= monStr && e.date <= sunStr) {
        e.status = 'approved';
        e.is_approved = true;
      }
    });

    toast(`Week of ${fmtDate(mon)} archived ✓ — ${result.employees} employees, £${result.total_payroll.toFixed(2)} total`, 'success');
    renderArchive();
  } catch (err) { toast('Archive failed: ' + err.message, 'error'); }
}

function renderArchive() {
  const area = document.getElementById('archiveArea');
  if (!area) return;
  const archive = state.timesheetData.archive || {};
  const weeks = Object.values(archive).sort((a, b) => b.weekCommencing.localeCompare(a.weekCommencing));

  if (!weeks.length) {
    area.innerHTML = `
      <div class="empty-state">
        <div style="font-size:32px;margin-bottom:12px">&#128196;</div>
        <div>No archived weeks yet.</div>
        <div style="margin-top:8px;font-size:12px;color:var(--subtle)">Go to Payroll tab and click "Archive This Week" to save a week's records.</div>
      </div>`;
    return;
  }

  area.innerHTML = weeks.map(w => {
    const grandTotal = (w.payroll || []).reduce((s, r) => s + r.totalPay, 0);
    const totalHrs = (w.payroll || []).reduce((s, r) => s + r.totalHours, 0);
    return `
      <div class="card" style="margin-bottom:12px">
        <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px">
          <div>
            <div style="font-family:var(--font-display);font-size:20px;letter-spacing:1px">
              WC ${new Date(w.weekCommencing+'T12:00:00').toLocaleDateString('en-GB', {day:'numeric',month:'short',year:'numeric'})}
            </div>
            <div style="font-size:12px;color:var(--muted);margin-top:4px">
              ${(w.payroll||[]).length} employees &nbsp;·&nbsp; ${totalHrs.toFixed(2)} total hours &nbsp;·&nbsp; Archived ${new Date(w.archivedAt).toLocaleDateString('en-GB')}
            </div>
          </div>
          <div style="display:flex;align-items:center;gap:12px">
            <div style="font-family:var(--font-display);font-size:28px;color:var(--green)">£${grandTotal.toFixed(2)}</div>
            <button class="btn btn-ghost" style="padding:6px 12px;font-size:12px" onclick="toggleArchiveDetail('${w.weekCommencing}')">View Details</button>
          </div>
        </div>
        <div id="archive-detail-${w.weekCommencing}" style="display:none;margin-top:16px">
          <table class="summary-table">
            <thead>
              <tr><th>EMPLOYEE</th><th>TOTAL HRS</th><th>BASIC</th><th>O/T ×1.5</th><th>DBL ×2</th><th style="color:var(--accent)">HOL</th><th>TOTAL PAY</th></tr>
            </thead>
            <tbody>
              ${(w.payroll||[]).map(r => {
                const holHrs = (r.holidayHours || 0) + (r.bankHolidayHours || 0);
                const holPay = (r.holidayPay   || 0) + (r.bankHolidayPay   || 0);
                return `
                <tr>
                  <td style="font-weight:600">${r.employeeName}</td>
                  <td class="mono">${r.totalHours.toFixed(2)}h</td>
                  <td class="mono">${r.basicHours}h &nbsp; £${r.basicPay.toFixed(2)}</td>
                  <td class="mono" style="color:var(--amber)">${r.overtimeHours > 0 ? r.overtimeHours+'h &nbsp; £'+r.overtimePay.toFixed(2) : '—'}</td>
                  <td class="mono" style="color:var(--accent)">${r.doubleHours > 0 ? r.doubleHours+'h &nbsp; £'+r.doublePay.toFixed(2) : '—'}</td>
                  <td class="mono" style="color:var(--accent)">${holHrs > 0 ? holHrs+'h &nbsp; £'+holPay.toFixed(2) : '—'}</td>
                  <td class="mono" style="color:var(--green);font-weight:700">£${r.totalPay.toFixed(2)}</td>
                </tr>
              `;}).join('')}
            </tbody>
          </table>
        </div>
      </div>
    `;
  }).join('');
}

function toggleArchiveDetail(weekKey) {
  const el = document.getElementById(`archive-detail-${weekKey}`);
  if (el) el.style.display = el.style.display === 'none' ? 'block' : 'none';
}

