// ── Load element data (approval, parts, site, notes) from SQL ──────────────
async function loadJobElementData(jobId) {
  const id = parseInt(jobId);
  if (!id) return;
  try {
    const data = await api.get(`/api/drawing-elements/${id}`);
    _drawingElementsCache[id] = data;
    // Merge into currentJob if it matches
    if (currentJob && parseInt(currentJob.id) === id) {
      _applyElementDataToJob(currentJob, data);
    }
  } catch (e) {
    console.warn(`loadJobElementData(${id}) failed:`, e.message);
    _drawingElementsCache[id] = { revisions: [], files: {}, notes: {}, site: null };
  }
}

function _applyElementDataToJob(job, data) {
  if (!data) return;
  // Approval
  job.approval = {
    revisions: (data.revisions || []).map(r => ({
      id: r.id,
      type: r.type,
      number: r.number,
      constructionNumber: r.constructionNumber,
      status: r.status,
      statusUpdatedAt: r.statusUpdatedAt,
      isDeleted: !!r.isDeleted,
      uploadedAt: r.uploadedAt,
      files: r.files || []
    })),
    notes: (data.notes && data.notes['approval']) || []
  };
  // Parts
  job.parts = {
    sections: {
      files: (data.files && data.files['parts-sections']) || [],
      notes: (data.notes && data.notes['parts-sections']) || []
    },
    plates: {
      files: (data.files && data.files['parts-plates']) || [],
      notes: (data.notes && data.notes['parts-plates']) || []
    }
  };
  // Site
  const siteFiles = (data.files && data.files['site']) || [];
  const siteNotes = (data.notes && data.notes['site']) || [];
  job.site = {
    files: siteFiles,
    notes: siteNotes,
    completedAt: data.site ? data.site.completedAt : null,
    completedBy: data.site ? data.site.completedBy : null
  };
  // RAMS — generated RAMS PDFs (DrawingElementFiles context 'rams'). The PDFs
  // live in the PROJECT-level 00 - RAMS/<job>/ SharePoint folder (decision B),
  // but they're registered against the job so they list on Site Installation.
  job.rams = { files: (data.files && data.files['rams']) || [] };
}


// ── Load / Save user access data ──
async function loadUserAccessData() {
  try {
    // Load permissions from API
    const [permsData, requestsData] = await Promise.all([
      api.get('/api/user-access').catch(() => []),
      api.get('/api/access-requests').catch(() => [])
    ]);

    // Load globalAdminEmail from settings
    const settings = state.timesheetData.settings || {};
    const adminEmail = settings.globalAdminEmail || '';

    // Build the userAccessData structure from API rows
    const users = {};
    (Array.isArray(permsData) ? permsData : []).forEach(row => {
      const name = row.employee_name;
      if (!name) return;
      users[name] = {
        employee_id: row.employee_id,
        permissions: {
          byProject: !!row.by_project,
          byEmployee: !!row.by_employee,
          clockingInOut: !!row.clocking_in_out,
          payroll: !!row.payroll,
          archive: !!row.archive,
          staff: !!row.staff,
          holidays: !!row.holidays,
          reports: !!row.reports,
          settings: !!row.settings,
          userAccess: !!row.user_access,
          draftsmanMode: !!row.draftsman_mode,
          tenders: !!row.tenders,
          editQuotes: !!row.edit_quotes,
          viewQuotes: !!row.view_quotes,
          editProjects: !!row.edit_projects,
          viewProjects: !!row.view_projects,
          viewPurchaseOrders: !!row.view_purchase_orders,
          editPurchaseOrders: !!row.edit_purchase_orders,
          invoicing: !!row.invoicing,
          afps: !!row.afps,
          reconcile: !!row.reconcile,
          estimatingDashboard: !!row.estimating_dashboard
        }
      };
    });

    userAccessData = {
      globalAdminEmail: adminEmail,
      users,
      accessRequests: (Array.isArray(requestsData) ? requestsData : []).map(r => ({
        id: r.id,
        employeeName: r.employee_name,
        reason: r.reason,
        date: r.created_at ? r.created_at.slice(0, 16).replace('T', ' ') : '',
        status: r.status
      }))
    };
    console.log('User access loaded from API:', Object.keys(users).length, 'users');
  } catch (e) {
    console.warn('User access data load failed:', e.message);
  }
}

