// ── SharePoint folder helpers ──
async function findProjectFolder(projectId) {
  const token = await getToken();
  const searchRes = await fetch(
    `https://graph.microsoft.com/v1.0/drives/${BAMA_DRIVE_ID}/root/search(q='${projectId}')`,
    { headers: { 'Authorization': `Bearer ${token}` } }
  );
  const searchData = await searchRes.json();
  return searchData.value?.find(item => item.folder && item.name.includes(projectId));
}

// Creates a folder under parentItemId. Retries on transient Graph failures
// (429 throttling, 5xx, network drops) with exponential backoff, honouring
// Retry-After when present. SharePoint throttles rapid sequential creates and
// has brief eventual-consistency lag right after a parent folder is made, so
// without this the early folders in a burst (e.g. "01 - Order") can silently
// fail. 201 = created, 409 = already exists (resolved via path GET).
async function createFolderInDrive(parentItemId, folderName, driveId, opts = {}) {
  const dId = driveId || BAMA_DRIVE_ID;
  const maxRetries = opts.maxRetries != null ? opts.maxRetries : 4;
  const wait = ms => new Promise(r => setTimeout(r, ms));
  const backoff = a => Math.min(8000, 400 * Math.pow(2, a)) + Math.floor(Math.random() * 200);
  const TRANSIENT = [429, 500, 502, 503, 504];

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    const token = await getToken();
    let res;
    try {
      res = await fetch(
        `https://graph.microsoft.com/v1.0/drives/${dId}/items/${parentItemId}/children`,
        {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: folderName, folder: {}, '@microsoft.graph.conflictBehavior': 'fail' })
        }
      );
    } catch (netErr) {
      // Network-level failure (dropped connection, DNS, etc.) — retry
      if (attempt < maxRetries) { await wait(backoff(attempt)); continue; }
      throw new Error(`Create folder "${folderName}" failed (network) after ${maxRetries + 1} attempts: ${netErr.message}`);
    }

    if (res.status === 201) return await res.json();

    if (res.status === 409) {
      // Folder already exists — fetch by path (reliable; $filter on children is not)
      const getRes = await fetch(
        `https://graph.microsoft.com/v1.0/drives/${dId}/items/${parentItemId}:/${encodeURIComponent(folderName)}`,
        { headers: { 'Authorization': `Bearer ${token}` } }
      );
      if (getRes.ok) return await getRes.json();
      throw new Error(`Folder "${folderName}" exists (409) but could not be retrieved: ${getRes.status}`);
    }

    // Transient — back off and retry (honour Retry-After header when present)
    if (TRANSIENT.includes(res.status) && attempt < maxRetries) {
      const retryAfter = parseInt(res.headers.get('Retry-After') || '', 10);
      const waitMs = Number.isFinite(retryAfter) ? retryAfter * 1000 : backoff(attempt);
      console.warn(`Graph create "${folderName}" got ${res.status}; retrying in ${waitMs}ms (attempt ${attempt + 1}/${maxRetries})`);
      await wait(waitMs);
      continue;
    }

    throw new Error(`Create folder "${folderName}" failed: ${res.status}`);
  }
  throw new Error(`Create folder "${folderName}" failed after ${maxRetries + 1} attempts`);
}

async function getOrCreateSubfolder(parentItemId, folderName, driveId) {
  const token = await getToken();
  const dId = driveId || BAMA_DRIVE_ID;

  // POST-first: attempt creation. 201 = created, 409 = already exists.
  // Avoids a speculative GET that logs a red 404 in the console every time
  // the folder doesn't exist yet, and avoids the unreliable $filter-on-children
  // fallback that SharePoint Graph often returns empty for even when folder exists.
  const createRes = await fetch(
    `https://graph.microsoft.com/v1.0/drives/${dId}/items/${parentItemId}/children`,
    {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: folderName, folder: {}, '@microsoft.graph.conflictBehavior': 'fail' })
    }
  );

  if (createRes.status === 201) return await createRes.json();

  if (createRes.status === 409) {
    // Already exists — fetch directly by path. Graph is eventually consistent,
    // so the path GET can transiently 404/5xx right after the folder appears;
    // retry a few times before giving up (a single miss used to abort a whole
    // multi-file batch).
    const pathUrl = `https://graph.microsoft.com/v1.0/drives/${dId}/items/${parentItemId}:/${encodeURIComponent(folderName)}`;
    for (let attempt = 0; attempt < 4; attempt++) {
      const getRes = await fetch(pathUrl, { headers: { 'Authorization': `Bearer ${token}` } });
      if (getRes.ok) return await getRes.json();
      if (attempt < 3) { await new Promise(r => setTimeout(r, 400 * (attempt + 1))); continue; }
      throw new Error(`Folder "${folderName}" exists (409) but could not be retrieved: ${getRes.status}`);
    }
  }

  throw new Error(`Create folder "${folderName}" failed: ${createRes.status}`);
}

async function uploadFileToFolder(parentItemId, fileName, fileData, contentType, driveId) {
  const token = await getToken();
  const url = `https://graph.microsoft.com/v1.0/drives/${driveId || BAMA_DRIVE_ID}/items/${parentItemId}:/${encodeURIComponent(fileName)}:/content`;
  // Ensure we send raw bytes — convert File/Blob to ArrayBuffer if needed
  const body = (fileData instanceof File || fileData instanceof Blob)
    ? await fileData.arrayBuffer()
    : fileData;
  const res = await fetch(url, {
    method: 'PUT',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': contentType || 'application/octet-stream' },
    body
  });
  if (!res.ok) {
    let detail = '';
    try { const e = await res.json(); detail = e?.error?.message || JSON.stringify(e); } catch (_) {}
    throw new Error(`Upload failed: ${res.status} ${res.statusText}${detail ? ' — ' + detail : ''}`);
  }
  return await res.json();
}

// Look up a file by name inside a folder. Returns the driveItem if present,
// else null. Used to avoid uploading a duplicate when someone has already
// dropped the PDF into the destination folder by hand.
async function _findFileInFolder(parentItemId, fileName, driveId) {
  const token = await getToken();
  const url = `https://graph.microsoft.com/v1.0/drives/${driveId || BAMA_DRIVE_ID}/items/${parentItemId}:/${encodeURIComponent(fileName)}`;
  try {
    const res = await fetch(url, { headers: { 'Authorization': `Bearer ${token}` } });
    if (res.ok) return await res.json();
    return null; // 404 = not there (the normal case)
  } catch (_) {
    return null; // network hiccup — treat as "not found", upload proceeds
  }
}

// Strips characters SharePoint disallows in filenames: ~ " # % & * : < > ? { | } / \
function sanitizeSpFilename(name) {
  return (name || '').replace(/[~"#%&*:<>?{|}/\\]/g, '_');
}

async function deleteFileFromDrive(fileId, driveId) {
  const token = await getToken();
  const res = await fetch(
    `https://graph.microsoft.com/v1.0/drives/${driveId || BAMA_DRIVE_ID}/items/${fileId}`,
    { method: 'DELETE', headers: { 'Authorization': `Bearer ${token}` } }
  );
  if (!res.ok && res.status !== 404) throw new Error(`Delete failed: ${res.status}`);
}

// ═══════════════════════════════════════════
// OPEN PROJECTS / RENDER TILES
// ═══════════════════════════════════════════
async function openProjects() {
  if (CURRENT_PAGE !== 'projects') {
    window.location.href = 'projects.html';
    return;
  }
  showScreen('screenProjects');
  renderProjectTiles();
  loadDrawingsData().then(() => renderProjectTiles()).catch(() => {});
}

// Active project-grid filter chip. One of: live | new | closed | all | hidden
let projectFilter = 'live';

// Chip click handler (wired from projects.html #projFilterBar).
function setProjectFilter(f, btn) {
  projectFilter = f;
  document.querySelectorAll('#projFilterBar .proj-chip').forEach(c => c.classList.remove('active'));
  const el = btn || document.querySelector(`#projFilterBar .proj-chip[data-filter="${f}"]`);
  if (el) el.classList.add('active');
  renderProjectTiles();
}

function renderProjectTiles() {
  const grid = document.getElementById('projectTilesGrid');
  if (!grid) return;

  // On kiosk state.projects is already In Progress only; on projects page
  // state.projects also includes On Hold. We filter to In Progress only —
  // On Hold projects are reinstated via Project Tracker when work resumes.
  const inProgress  = (state.projects || []).filter(p => p.status === 'In Progress');
  const hiddenList  = inProgress.filter(p => p.hidden);      // other-company / not-our-scope
  const visibleList = inProgress.filter(p => !p.hidden);     // shop-floor view

  // Kiosk / shop-floor (non-draftsman) is locked to Live only — no filter bar,
  // no way to reach closed or not-yet-started projects. The full chip set
  // returns once a draftsman logs in. Job lists already hide closed jobs for
  // non-draftsman, so nothing closed is ever reachable on the kiosk.
  const filterBar = document.getElementById('projFilterBar');
  if (filterBar) filterBar.style.display = isDraftsman ? 'flex' : 'none';
  if (!isDraftsman) projectFilter = 'live';

  // Reveal the Hidden chip only for a logged-in draftsman with hidden projects.
  const hiddenChip = document.querySelector('#projFilterBar .proj-chip-hidden');
  const canSeeHidden = isDraftsman && hiddenList.length > 0;
  if (hiddenChip) hiddenChip.style.display = canSeeHidden ? 'inline-flex' : 'none';
  // Hidden view no longer available (logged out, or last hidden project shown) → fall back.
  if (projectFilter === 'hidden' && !canSeeHidden) { setProjectFilter('live'); return; }

  if (!inProgress.length) {
    grid.innerHTML = '<div class="empty-state" style="grid-column:1/-1">No active projects found</div>';
    return;
  }

  // Annotate a project list with job counts + derived category flags.
  //   new    — no jobs created yet (freshly won, not started)
  //   live   — at least one open job (active work)
  //   closed — jobs exist and every one is closed
  // Categories are mostly exclusive; filters are views over the visible set.
  const annotate = list => list.map(p => {
    const jobs = drawingsData.projects[p.id]?.jobs || [];
    const openJobs   = jobs.filter(j => j.status !== 'closed');
    const closedJobs = jobs.filter(j => j.status === 'closed');
    const cat = {
      new:    jobs.length === 0,
      live:   openJobs.length > 0,
      closed: jobs.length > 0 && openJobs.length === 0,
    };
    return { p, jobs, openCount: openJobs.length, closedCount: closedJobs.length, cat };
  });

  const annotatedVisible = annotate(visibleList);

  // Chip counts: categories over the visible (shop-floor) set; Hidden = hidden count.
  const counts = { live:0, new:0, closed:0, all: annotatedVisible.length, hidden: hiddenList.length };
  annotatedVisible.forEach(a => ['live','new','closed'].forEach(k => { if (a.cat[k]) counts[k]++; }));
  document.querySelectorAll('#projFilterBar .cnt').forEach(el => {
    const k = el.getAttribute('data-cnt');
    el.textContent = counts[k] != null ? counts[k] : '';
  });

  const viewingHidden = projectFilter === 'hidden';
  let shown;
  if (viewingHidden) {
    shown = annotate(hiddenList);
  } else {
    // While the drawings data is still loading, categories aren't reliable yet
    // (every project looks job-less) — show the full visible set so nothing
    // appears to be missing. It re-renders correctly once drawings resolve.
    const applyFilter = _drawingsLoaded && projectFilter !== 'all';
    shown = applyFilter ? annotatedVisible.filter(a => a.cat[projectFilter]) : annotatedVisible;
  }

  if (!shown.length) {
    const labels = { live:'live', new:'new', closed:'closed', hidden:'hidden' };
    const hint = projectFilter === 'hidden' ? '' : ' — try <b>All</b>';
    grid.innerHTML = `<div class="empty-state" style="grid-column:1/-1">No ${labels[projectFilter] || 'active'} projects${hint}</div>`;
    return;
  }

  // Sort: busiest (most open jobs) first, then project ID asc (numeric-aware).
  shown.sort((a, b) => {
    if (a.openCount !== b.openCount) return b.openCount - a.openCount;
    return String(a.p.id).localeCompare(String(b.p.id), 'en', { numeric: true, sensitivity: 'base' });
  });

  grid.innerHTML = shown.map(({ p, jobs, openCount, closedCount }) => {
    // Draftsman-only eye toggle. In the Hidden view it un-hides; elsewhere it hides.
    const hideBtn = isDraftsman
      ? `<button class="tile-hide-btn${viewingHidden ? ' on' : ''}"
                 title="${viewingHidden ? 'Show on shop floor' : 'Hide from shop floor'}"
                 onclick="event.stopPropagation();toggleProjectHidden('${p.id}', ${viewingHidden ? 'false' : 'true'})">&#128065;</button>`
      : '';
    return `
      <div class="project-tile${viewingHidden ? ' tile-hidden' : ''}" onclick="openProjectDetail('${p.id}')">
        ${hideBtn}
        <div class="project-tile-id">${p.id}</div>
        <div class="project-tile-name">${p.name}</div>
        <div class="project-tile-client">${p.client || ''}</div>
        ${jobs.length > 0 ? `
          <div style="margin-top:12px;font-size:11px;font-family:var(--font-mono);color:var(--muted)">
            ${openCount} open${closedCount ? ` · ${closedCount} closed` : ''}
          </div>
          <div style="margin-top:6px;height:3px;background:var(--border);border-radius:2px">
            <div style="height:100%;background:var(--green);border-radius:2px;width:${jobs.length ? Math.round(closedCount/jobs.length*100) : 0}%"></div>
          </div>
        ` : '<div style="margin-top:12px;font-size:11px;color:var(--subtle)">No jobs yet</div>'}
        ${jobs.length > 0 ? `<div class="project-tile-badge">${jobs.length} job${jobs.length>1?'s':''}</div>` : ''}
      </div>
    `;
  }).join('');
}

// Draftsman-only: hide a project from the shop-floor grid, or un-hide it.
// Persists to Projects.hidden_from_workshop (2026-07 migration). Optimistic
// update with rollback on failure.
async function toggleProjectHidden(projectId, hide) {
  if (!isDraftsman) return;
  const proj = (state.projects || []).find(p => p.id === projectId);
  if (!proj || !proj.dbId) { toast('Cannot resolve project', 'error'); return; }
  const prev = proj.hidden;
  proj.hidden = hide;                 // optimistic
  renderProjectTiles();
  try {
    await api.put(`/api/projects/${proj.dbId}`, { hidden_from_workshop: hide });
    toast(hide ? `"${proj.id}" hidden from shop floor` : `"${proj.id}" shown on shop floor`, 'success');
  } catch (e) {
    proj.hidden = prev;               // rollback
    renderProjectTiles();
    toast('Update failed: ' + (e.message || e), 'error');
  }
}

// ═══════════════════════════════════════════
// PROJECT DETAIL — JOB LIST
// ═══════════════════════════════════════════
async function openProjectDetail(projectId) {
  // Await drawings data if it hasn't finished loading yet
  if (_drawingsLoadPromise) await _drawingsLoadPromise.catch(() => {});

  const proj = state.projects.find(p => p.id === projectId);
  if (!proj) return;
  currentProject = proj;
  currentJob = null;
  loadJobSheet(proj.dbId);   // fire-and-forget — cached per project

  document.getElementById('projDetailTitle').textContent = `${proj.id} — ${proj.name}`;
  document.getElementById('projDetailMeta').textContent = proj.client ? `Client: ${proj.client}` : '';
  document.getElementById('draftsmanBar').style.display = isDraftsman ? 'flex' : 'none';

  showScreen('screenProjectDetail');
  renderJobsList(projectId);
}

function renderJobsList(projectId) {
  const container = document.getElementById('jobsList');
  if (!container) return;
  const projData = drawingsData.projects[projectId];
  const allJobs = projData?.jobs || [];
  // Kiosk / shop-floor (non-draftsman) only sees live (open) jobs — closed jobs
  // are hidden. A logged-in draftsman still sees closed jobs for management.
  const jobs = isDraftsman ? allJobs : allJobs.filter(j => j.status !== 'closed');

  if (!jobs.length) {
    const closedOnly = !isDraftsman && allJobs.some(j => j.status === 'closed');
    container.innerHTML = `
      <div class="empty-state" style="padding:60px 24px">
        <div style="font-size:36px;margin-bottom:12px">&#128221;</div>
        <div>${closedOnly ? 'No live jobs' : 'No jobs created yet'}</div>
        ${isDraftsman ? '<div style="margin-top:8px;font-size:12px;color:var(--subtle)">Use the + Add Job button above</div>' : ''}
      </div>
    `;
    return;
  }

  container.innerHTML = jobs.map(job => {
    const isClosed = job.status === 'closed';
    // Calculate element progress
    const progress = getJobProgress(job);

    return `
      <div class="job-card ${isClosed ? 'closed' : ''}" onclick="openJobDetail('${projectId}', '${job.id}')">
        <div class="job-number">${String(job.number).padStart(2, '0')}</div>
        <div style="flex:1">
          <div class="job-name">${job.name}</div>
          <div style="font-size:11px;color:var(--subtle);margin-top:4px">
            Created ${new Date(job.createdAt).toLocaleDateString('en-GB')}
            ${isClosed ? ` · Closed ${new Date(job.closedAt).toLocaleDateString('en-GB')}` : ''}
          </div>
        </div>
        <div style="display:flex;align-items:center;gap:8px;flex-shrink:0">
          ${progress.fabPct >= 0 ? `<span style="font-size:11px;font-family:var(--font-mono);color:${progress.fabPct === 100 ? 'var(--green)' : 'var(--muted)'};font-weight:600">BOM ${progress.fabPct}%</span>` : ''}
          ${progress.tasksTotal > 0 ? `<span style="font-size:11px;font-family:var(--font-mono);color:${progress.tasksDone === progress.tasksTotal ? 'var(--green)' : 'var(--muted)'};font-weight:600">${progress.tasksDone}/${progress.tasksTotal} fab</span>` : ''}
          ${progress.hasNewTasks ? `<span style="font-size:9px;font-weight:700;background:var(--accent);color:#fff;padding:2px 6px;border-radius:4px;letter-spacing:.3px">NEW</span>` : ''}
        </div>
        <div class="job-badge ${isClosed ? 'closed' : 'open'}">${isClosed ? 'CLOSED' : 'OPEN'}</div>
        ${isDraftsman ? `<button class="btn btn-ghost" title="Delete job" style="padding:4px 8px;font-size:13px;opacity:.55;flex-shrink:0;margin-left:4px" onclick="event.stopPropagation();openDeleteJobModal('${job.id}','${job.name.replace(/'/g,"\\'")}')">&#128465;</button>` : ''}
      </div>
    `;
  }).join('');
}

// ── Delete job (draftsman-only, PIN-gated) ────────────────────────────────────
let _pendingDeleteJobId   = null;
let _pendingDeleteJobName = null;

function openDeleteJobModal(jobId, jobName) {
  if (!isDraftsman) return;
  _pendingDeleteJobId   = jobId;
  _pendingDeleteJobName = jobName;
  const modal = document.getElementById('deleteJobModal');
  if (!modal) return;
  document.getElementById('deleteJobName').textContent = jobName;
  document.getElementById('deleteJobPinInput').value = '';
  document.getElementById('deleteJobPinError').textContent = '';
  modal.classList.add('active');
  setTimeout(() => document.getElementById('deleteJobPinInput').focus(), 100);
}

function closeDeleteJobModal() {
  const modal = document.getElementById('deleteJobModal');
  if (modal) modal.classList.remove('active');
  _pendingDeleteJobId   = null;
  _pendingDeleteJobName = null;
}

async function confirmDeleteJob() {
  if (!_pendingDeleteJobId) return;

  const pin = document.getElementById('deleteJobPinInput').value.trim();
  if (!pin) {
    document.getElementById('deleteJobPinError').textContent = 'Please enter your PIN';
    return;
  }

  // Resolve the logged-in draftsman's employee record
  const name = _currentDraftsmanName;
  const emp  = name ? (state.timesheetData.employees || []).find(e => e.name === name) : null;
  if (!emp) {
    document.getElementById('deleteJobPinError').textContent = 'Cannot identify logged-in draftsman — please log out and back in';
    return;
  }

  // Verify PIN server-side
  let result;
  try {
    result = await api.post('/api/auth/verify-pin', { employee_id: emp.id, pin });
  } catch (err) {
    document.getElementById('deleteJobPinError').textContent = 'Verification failed — try again';
    return;
  }
  if (!result || !result.valid) {
    document.getElementById('deleteJobPinError').textContent = (result && result.reason) || 'Incorrect PIN';
    document.getElementById('deleteJobPinInput').value = '';
    return;
  }

  // PIN correct — delete the job
  const jobId = _pendingDeleteJobId;
  closeDeleteJobModal();
  try {
    await api.delete(`/api/drawings/${encodeURIComponent(jobId)}`);
    toast(`Job "${_pendingDeleteJobName || jobId}" deleted.`, 'success');
    // Remove from local drawingsData so the list re-renders immediately
    if (currentProject) {
      const pd = drawingsData.projects[currentProject.id];
      if (pd) pd.jobs = (pd.jobs || []).filter(j => String(j.id) !== String(jobId));
      renderJobsList(currentProject.id);
    }
  } catch (e) {
    toast('Delete failed: ' + e.message, 'error');
  }
}

function getJobProgress(job) {
  const elements = {};
  // BOM progress now reads from the SQL-backed _bomItemsByJob cache
  // (populated by loadJobBomItems in openJobDetail). job.id is a string;
  // the cache is keyed by SQL int — coerce.
  const jobIdInt = job?.id ? parseInt(job.id) : null;
  const bomItems = (jobIdInt && _bomItemsByJob[jobIdInt]) || [];

  // BOM progress: based on item statuses — the primary measure
  if (bomItems.length > 0) {
    const allDone     = bomItems.every(i => i.status === 'on_site' || i.status === 'despatched');
    const anyProgress = bomItems.some(i => i.status !== 'pending');
    elements.bom = allDone ? 'complete' : anyProgress ? 'active' : 'empty';
  } else {
    elements.bom = (job.bom?.files?.length > 0) ? 'active' : 'empty';
  }

  // Approval, Parts, Site — simple indicators, not measured progress
  const revs = (job.approval?.revisions || []).filter(r => !r.isDeleted);
  elements.approval = revs.some(r => r.type === 'CO') ? 'complete' : revs.length > 0 ? 'active' : 'empty';

  elements.parts = ((job.parts?.sections?.files?.length || 0) + (job.parts?.plates?.files?.length || 0)) > 0 ? 'complete' : 'empty';

  // Assembly progress: now from SQL-backed assembly cache rather than
  // the legacy task list. An assembly is 'complete' when all rows are
  // status='fabricated'.
  const assemblies = (jobIdInt && _assembliesByJob[jobIdInt]) || [];
  const allFabricated = assemblies.length > 0 && assemblies.every(a => a.status === 'fabricated');
  elements.assembly = allFabricated ? 'complete' : assemblies.length > 0 ? 'active' : 'empty';

  // Site: just an indicator (no longer reads deliveryNotes from the
  // dead bomDataCache — uses just job.site presence).
  elements.site = job.site?.completedAt ? 'complete' : (job.site?.files?.length > 0) ? 'active' : 'empty';

  // Progress label based on BOM (delivered count) + Assembly (fabricated
  // count). Replaces the legacy 'tasks' counter which read job.assembly.tasks
  // — that field is gone since assemblies now live in SQL (_assembliesByJob).
  const bomDelivered = bomItems.filter(i => i.status === 'on_site' || i.status === 'despatched').length;
  const bomTotal     = bomItems.length;
  const bomPct       = bomTotal > 0 ? Math.round(bomDelivered / bomTotal * 100) : -1;

  const asmFabricated = assemblies.filter(a => a.status === 'fabricated').length;
  const asmTotal      = assemblies.length;

  // 'New' assemblies — uploaded in the last 48h and not yet fabricated.
  // Used by the kiosk to highlight fresh work.
  const newAssemblyCutoff = Date.now() - 48 * 60 * 60 * 1000;
  const hasNewTasks = assemblies.some(a => a.status === 'pending'
                                          && new Date(a.created_at).getTime() > newAssemblyCutoff);

  const label = (bomTotal > 0 || asmTotal > 0)
    ? `BOM: ${bomPct >= 0 ? bomPct + '%' : 'N/A'} · Assembly: ${asmFabricated}/${asmTotal}`
    : 'No progress data';
  // Preserve the legacy return shape so existing callers keep working.
  // (fabPct/tasksDone/tasksTotal are now BOM and assembly counts under
  // their old names — the labels in renderJobsList don't introspect
  // them directly.)
  return {
    elements,
    label,
    fabPct: bomPct,
    tasksDone: asmFabricated,
    tasksTotal: asmTotal,
    hasNewTasks
  };
}

// ═══════════════════════════════════════════
// CREATE JOB
// ═══════════════════════════════════════════
function openCreateJobModal() {
  if (!isDraftsman || !currentProject) return;
  document.getElementById('createJobProjectName').textContent = `${currentProject.id} — ${currentProject.name}`;
  document.getElementById('createJobName').value = '';
  document.getElementById('createJobProgress').style.display = 'none';
  document.getElementById('createJobBtn').disabled = false;
  document.getElementById('createJobModal').classList.add('active');
  setTimeout(() => document.getElementById('createJobName').focus(), 100);
}

function closeCreateJobModal() {
  document.getElementById('createJobModal').classList.remove('active');
}

async function createJob() {
  const jobName = document.getElementById('createJobName').value.trim();
  if (!jobName) { toast('Please enter a job name', 'error'); return; }

  const projectId = currentProject.id;
  if (!drawingsData.projects[projectId]) drawingsData.projects[projectId] = { jobs: [] };
  const jobs = drawingsData.projects[projectId].jobs;
  const jobNumber = jobs.length + 1;
  const folderName = `${String(jobNumber).padStart(2, '0')} - ${jobName}`;

  document.getElementById('createJobProgress').style.display = 'block';
  document.getElementById('createJobBtn').disabled = true;
  document.getElementById('createJobProgressBar').style.width = '10%';
  document.getElementById('createJobProgressText').textContent = 'Finding project folder...';

  try {
    // Find project folder on SharePoint
    const projectFolder = await findProjectFolder(projectId);
    if (!projectFolder) throw new Error('Project folder not found on SharePoint');

    document.getElementById('createJobProgressBar').style.width = '20%';
    document.getElementById('createJobProgressText').textContent = 'Creating 02 - Drawings folder...';

    // Get or create 02 - Drawings folder
    const drawingsFolder = await getOrCreateSubfolder(projectFolder.id, '02 - Drawings');
    if (!drawingsFolder) throw new Error('Could not create Drawings folder');

    document.getElementById('createJobProgressBar').style.width = '35%';
    document.getElementById('createJobProgressText').textContent = `Creating ${folderName}...`;

    // Create job folder
    const jobFolder = await createFolderInDrive(drawingsFolder.id, folderName);
    if (!jobFolder) throw new Error('Could not create job folder');

    // Create element subfolders (driven by ELEMENT_FOLDERS)
    const elementNames = Object.values(ELEMENT_FOLDERS);
    for (let i = 0; i < elementNames.length; i++) {
      const pct = 40 + Math.round((i / elementNames.length) * 40);
      document.getElementById('createJobProgressBar').style.width = `${pct}%`;
      document.getElementById('createJobProgressText').textContent = `Creating ${elementNames[i]}...`;
      const elFolder = await createFolderInDrive(jobFolder.id, elementNames[i]);
      // For Parts, create sub-subfolders
      if (elementNames[i] === ELEMENT_FOLDERS.parts && elFolder) {
        for (const sub of PARTS_SUBFOLDERS) {
          await createFolderInDrive(elFolder.id, sub);
        }
      }
    }

    document.getElementById('createJobProgressBar').style.width = '90%';
    document.getElementById('createJobProgressText').textContent = 'Saving job data...';

    // Create the SQL DrawingJobs row first — its IDENTITY id becomes the
    // canonical job id used everywhere (including the SharePoint blob's
    // nested element data, keyed by string-cast id). If this fails the
    // SharePoint folders are already created; that's tolerable (orphan
    // folders are harmless and the user can retry).
    const driveId = jobFolder.parentReference?.driveId || BAMA_DRIVE_ID;
    let sqlJobId;
    try {
      const sqlRow = await api.post('/api/drawings', {
        project_number:       projectId,
        job_name:             jobName,
        sharepoint_folder_id: jobFolder.id,
        sharepoint_file_id:   null
      });
      sqlJobId = String(sqlRow.id);
    } catch (sqlErr) {
      throw new Error(`SQL save failed: ${sqlErr.message}`);
    }

    // Create job entry in drawingsData (keyed by the SQL id).
    // Nested element data starts empty; Approval/Parts/Site will lazily
    // populate it through their existing flows.
    const newJob = {
      id: sqlJobId,
      number: jobNumber,
      name: jobName,
      folderName,
      spFolderId: jobFolder.id,
      spDriveId: driveId,
      status: 'open',
      createdAt: new Date().toISOString(),
      bom: { files: [], notes: [] },
      approval: { revisions: [], notes: [] },
      parts: {
        sections: { files: [], notes: [] },
        plates: { files: [], notes: [] }
      },
      assembly: { tasks: [] },
      site: { files: [], notes: [] }
    };

    jobs.push(newJob);
    await saveDrawingsData();

    document.getElementById('createJobProgressBar').style.width = '100%';
    document.getElementById('createJobProgressText').textContent = 'Done!';

    setTimeout(() => {
      closeCreateJobModal();
      toast(`Job "${jobName}" created`, 'success');
      renderJobsList(projectId);
    }, 400);

  } catch (e) {
    console.error('Create job error:', e);
    toast(`Failed: ${e.message}`, 'error');
    document.getElementById('createJobProgress').style.display = 'none';
  } finally {
    document.getElementById('createJobBtn').disabled = false;
  }
}

// ═══════════════════════════════════════════
// JOB DETAIL — 5 ELEMENTS VIEW
// ═══════════════════════════════════════════
function openJobDetail(projectId, jobId) {
  const proj = state.projects.find(p => p.id === projectId);
  if (!proj) return;
  currentProject = proj;
  const projData = drawingsData.projects[projectId];
  const job = projData?.jobs?.find(j => j.id === jobId);
  if (!job) return;
  currentJob = job;

  document.getElementById('jobDetailTitle').textContent = `${String(job.number).padStart(2,'0')} — ${job.name}`;
  document.getElementById('jobDetailMeta').textContent = `${proj.id} — ${proj.name}`;
  document.getElementById('jobDraftsmanBar').style.display = isDraftsman ? 'flex' : 'none';

  const badge = document.getElementById('jobStatusBadge');
  if (job.status === 'closed') {
    badge.textContent = 'CLOSED';
    badge.style.cssText = 'font-size:12px;font-weight:600;padding:6px 14px;border-radius:8px;background:rgba(62,207,142,.15);color:var(--green)';
  } else {
    badge.textContent = 'OPEN';
    badge.style.cssText = 'font-size:12px;font-weight:600;padding:6px 14px;border-radius:8px;background:rgba(255,107,0,.12);color:var(--accent)';
  }

  // Collapse all 5 element sections by default on every job open
  // (spec §4 of SPEC-job-fabrication-rework.md). Deep-link expansion
  // in initJobsDeepLink runs AFTER this via setTimeout, so it can still
  // re-open a target section if a ?element=… param was supplied.
  ['BOM', 'Approval', 'Parts', 'Assembly', 'Site'].forEach(name => {
    const body = document.getElementById(`element${name}Body`);
    const chevron = document.getElementById(`element${name}Chevron`);
    if (body) body.classList.add('collapsed');
    if (chevron) chevron.classList.add('collapsed');
  });

  showScreen('screenJobDetail');
  // Load all data in parallel: assemblies, BOM, finishes, and element data (SQL-backed)
  const jobIdInt = parseInt(currentJob.id);
  Promise.all([
    loadJobAssemblies(jobIdInt),
    loadJobBomItems(jobIdInt),
    loadFinishes(),
    loadJobElementData(jobIdInt),
    loadJobSheet(proj.dbId)
  ]).then(() => renderAllElements()).catch(() => renderAllElements());
}

function toggleElement(name) {
  const body = document.getElementById(`element${name}Body`);
  const chevron = document.getElementById(`element${name}Chevron`);
  if (!body) return;
  body.classList.toggle('collapsed');
  chevron.classList.toggle('collapsed');
}

function renderAllElements() {
  if (!currentJob) return;
  renderBOM();
  renderApproval();
  renderParts();
  renderAssembly();
  renderSite();
}

// ═══════════════════════════════════════════

// ═══════════════════════════════════════════
// ELEMENT 1: BOM (job-fabrication rework — see SPEC §6)
// ═══════════════════════════════════════════
//
// The BOM section is now a unified despatch queue driven by SQL
// (JobBomItems). Two routes in:
//   - Route A: Manual upload — supplier slip / quotation PDF, OCR'd
//     to N line items, bulk-saved via /api/job-bom-items/bulk
//   - Route B: Auto from fabricated assembly — created by the
//     fabricate endpoint in commit 8
//
// Status state machine (see SPEC §6):
//   pending → at_supplier → ready_for_despatch → despatched
//   (no-finish items skip to ready_for_despatch on create)

async function loadJobBomItems(jobId) {
  if (!jobId) return [];
  _bomSelected.clear();
  try {
    const rows = await api.get(`/api/job-bom-items?job_id=${encodeURIComponent(jobId)}`);
    _bomItemsByJob[jobId] = Array.isArray(rows) ? rows : [];
    return _bomItemsByJob[jobId];
  } catch (e) {
    console.warn('Load BOM items failed:', e.message);
    _bomItemsByJob[jobId] = [];
    return [];
  }
}

const BOM_STATUS_LABEL = {
  pending:             'Pending',
  at_supplier:         'At supplier',
  ready_for_despatch:  'Ready for despatch',
  despatched:          'Despatched',
  on_site:             'On site'
};

// Map an in-progress finish service name to its past-participle form,
// so that once an item is back from a supplier we can re-label the
// badge to read like a completed state (Galvanising → Galvanised).
// Falls back to the raw name when no mapping is found.
const FINISH_DONE_LABEL = {
  'Galvanising':    'Galvanised',
  'Painting':       'Painted',
  'Powder Coating': 'Powder Coated',
  'Shot Blasting':  'Shot Blasted',
  'Priming':        'Primed'
};
function finishBadgeFor(item) {
  if (!item.finish_name) return '';
  const done = item.status === 'ready_for_despatch'
            || item.status === 'despatched'
            || item.status === 'on_site';
  const text = done ? (FINISH_DONE_LABEL[item.finish_name] || item.finish_name) : item.finish_name;
  const style = done
    ? 'background:rgba(62,207,142,.18);color:#3ecf8e' // green (completed)
    : 'background:rgba(99,102,241,.18);color:#a5b4fc'; // blue (in progress)
  return `<span style="${style};padding:2px 9px;border-radius:6px;font-size:11px;font-weight:500;white-space:nowrap">${escapeHtml(text)}</span>`;
}

function renderBOM() {
  const container = document.getElementById('bomContent');
  if (!container) return;

  const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
  const allItems = (jobId && _bomItemsByJob[jobId]) || [];
  // Fixings/consumables (bolts, anchors, resin) live in the same table but
  // render in their own panel below — they skip the supplier/finish machinery.
  const isFixing = i => i.item_type === 'fixing' || i.item_type === 'consumable';
  const items       = allItems.filter(i => !isFixing(i));   // fabricated only
  const fixingItems = allItems.filter(isFixing);

  // Header status badge — reflects the whole job (fabricated + fixings) so a
  // fixings-only job never reads "Empty".
  const status = document.getElementById('elementBOMStatus');
  if (status) {
    if (allItems.length === 0) {
      status.textContent = 'Empty';
      status.style.cssText = 'color:var(--subtle);font-size:11px;font-weight:600';
    } else {
      const done    = allItems.filter(i => i.status === 'despatched' || i.status === 'on_site').length;
      const total   = allItems.length;
      const allDone = done === total;
      status.textContent = `${total} item${total > 1 ? 's' : ''} · ${done}/${total} delivered`;
      status.style.cssText = allDone
        ? 'color:var(--green);background:rgba(62,207,142,.1);padding:3px 10px;border-radius:4px;font-size:11px;font-weight:600'
        : 'color:var(--accent);background:rgba(255,107,0,.1);padding:3px 10px;border-radius:4px;font-size:11px;font-weight:600';
    }
  }

  let html = '';

  // Toolbar: drop-zone for manual loose-item uploads (draftsman, job open)
  if (isDraftsman && currentJob && currentJob.status !== 'closed') {
    html += `
      <div class="upload-zone" id="bomDropZone"
           style="margin-bottom:14px;cursor:pointer"
           onclick="document.getElementById('bomManualFileInput').click()">
        <div class="upload-zone-icon">&#128228;</div>
        <div class="upload-zone-text">Drop loose-item PDFs here</div>
        <div style="color:var(--subtle);font-size:11px;margin-top:4px">
          quotations, delivery slips, etc. · OCR'd to BOM rows · 1–100+ lines per file
        </div>
      </div>
      <input type="file" id="bomManualFileInput" accept=".pdf,.PDF" multiple
             style="display:none" onchange="onBomManualFilesPicked(this.files)">
    `;
  }

  if (items.length === 0) {
    html += '<div style="color:var(--subtle);font-size:13px;padding:8px 0">No fabricated BOM items yet. Drop a supplier slip above, or mark an assembly fabricated to auto-generate a row.</div>';
    html += renderFixingsSection(jobId, fixingItems);
    container.innerHTML = html;
    wireBomDropZone();
    return;
  }

  // Sort items: by status order, then by created_at asc
  const STATUS_ORDER = { pending: 0, at_supplier: 1, ready_for_despatch: 2, on_site: 3, despatched: 3 };
  const sortedItems = items.slice().sort((a, b) => {
    const sa = STATUS_ORDER[a.status] ?? 99;
    const sb = STATUS_ORDER[b.status] ?? 99;
    if (sa !== sb) return sa - sb;
    return String(a.created_at).localeCompare(String(b.created_at));
  });

  // Toolbar above the table
  const pendingCount = items.filter(i => i.status === 'pending').length;
  if (pendingCount > 0 && isDraftsman) {
    html += `
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
        <div style="font-size:11px;color:var(--subtle);text-transform:uppercase;letter-spacing:.05em">
          ${pendingCount} pending · ${items.length} total
        </div>
        <button class="btn btn-primary" id="bomGenDnBtn"
                style="padding:6px 14px;font-size:12px"
                onclick="openGenerateDnModalSQL()">&#128666; Generate DN</button>
      </div>
    `;
  }

  // Bulk-action toolbar (mirrors the QB takeoff bar) — hidden until a row
  // is ticked. Wired to the bulk-* endpoints so N rows = one request.
  const selCount = _bomSelected.size;
  const atSupplierCount = items.filter(i => i.status === 'at_supplier').length;
  const finishOpts = (_finishesCache || [])
    .map(f => `<option value="${f.id}">${escapeHtml(f.name)}</option>`).join('');

  // One-click shortcut to select everything currently out at a supplier, so a
  // whole batch coming back can be marked returned without ticking each row.
  // Sits above the bulk bar (which only shows once something's selected).
  if (atSupplierCount > 0 && isDraftsman) {
    html += `
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
        <span style="font-size:11px;color:var(--subtle)">${atSupplierCount} item${atSupplierCount>1?'s':''} out at a supplier</span>
        <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px"
                onclick="bomSelectByStatus('at_supplier')">&#10003; Select all returned</button>
      </div>`;
  }

  html += `
    <div id="bomBulkBar" style="display:${selCount ? 'flex' : 'none'};align-items:center;flex-wrap:wrap;gap:8px;padding:8px 12px;background:rgba(255,107,0,.08);border:1px solid rgba(255,107,0,.25);border-radius:7px;margin-bottom:8px">
      <span id="bomSelCount" style="font-size:12px;color:var(--accent);font-weight:600">${selCount} selected</span>
      <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick="bomSelectAll()">Select all</button>
      <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick="bomDeselectAll()">Deselect all</button>
      <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick="bomInvertSelection()">Invert</button>
      <select id="bomBulkFinish" onchange="bomBulkSetFinish(this.value); this.value='__';"
        style="background:var(--surface);border:1px solid var(--border);color:var(--text);border-radius:6px;padding:4px 8px;font-size:11px;cursor:pointer">
        <option value="__">Set finish ▸</option>
        <option value="">— none / in-house —</option>
        ${finishOpts}
      </select>
      <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick="bomBulkStatus('ready_for_despatch')">&#10003; Mark returned</button>
      ${isDraftsman ? `<button class="btn btn-ghost" style="padding:4px 10px;font-size:11px;color:var(--red);border-color:var(--red);margin-left:auto" onclick="bomBulkDelete()">&#128465; Delete selected</button>` : ''}
    </div>`;

  // Table view (commit 11.1 — replaces commit 9's tile-card view)
  html += `<div style="overflow-x:auto;border:1px solid var(--border);border-radius:8px;background:var(--surface)">
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead>
        <tr style="background:var(--bg-darker);color:var(--subtle);text-transform:uppercase;font-size:11px;letter-spacing:.04em">
          <th style="width:34px;text-align:center;padding:8px 8px;border-bottom:1px solid var(--border)"><input type="checkbox" id="bomHeadCb" onchange="bomToggleAllVisible(this.checked)" style="cursor:pointer;accent-color:var(--accent)"></th>
          <th style="text-align:left;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Description</th>
          <th style="text-align:right;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Qty</th>
          <th style="text-align:left;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Finish</th>
          <th style="text-align:left;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Source</th>
          <th style="text-align:left;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Status</th>
          <th style="text-align:right;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Actions</th>
        </tr>
      </thead>
      <tbody>`;

  let prevStatus = null;
  for (const it of sortedItems) {
    // Section header row when the status group changes
    if (it.status !== prevStatus) {
      html += `<tr style="background:rgba(255,255,255,.02)">
        <td style="padding:8px 8px;text-align:center;border-bottom:1px solid var(--border)">
          <input type="checkbox" class="bom-group-cb" data-status="${it.status}" onchange="bomToggleGroup('${it.status}', this.checked)" style="cursor:pointer;accent-color:var(--accent)">
        </td>
        <td colspan="6" style="padding:8px 12px;font-size:11px;color:var(--subtle);text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid var(--border)">
          ${BOM_STATUS_LABEL[it.status] || it.status}
        </td>
      </tr>`;
      prevStatus = it.status;
    }
    html += renderBomRow(it);
  }

  html += `</tbody></table></div>`;

  html += renderFixingsSection(jobId, fixingItems);

  container.innerHTML = html;
  wireBomDropZone();
}

// ─────────────────────────────────────────────────────────────────────────────
// Fixings & loose items panel — bolts, anchors, resin, etc. These sit in
// JobBomItems under item_type='fixing', but arrive already finished (SC/BZP/
// galv), so they skip the finish/supplier flow and land at ready_for_despatch.
// They ship to site on a Site DN under their own heading (Phase 2 adds
// partial/overship qty). Phase 1: hand-entry + inline edit + delete.
// ─────────────────────────────────────────────────────────────────────────────
function renderFixingsSection(jobId, fixings) {
  fixings = fixings || [];
  const canEdit = isDraftsman && currentJob && currentJob.status !== 'closed';

  const totalPieces = fixings.reduce((s, f) => s + (Number(f.quantity) || 0), 0);
  const totalWeight = fixings.reduce(
    (s, f) => s + (Number(f.unit_weight_kg) || 0) * (Number(f.quantity) || 0), 0);
  const weightStr = totalWeight > 0 ? ` · ${totalWeight.toFixed(1)} kg` : '';

  let html = `<div style="margin-top:22px">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">
      <span style="font-size:13px;font-weight:600;color:var(--text)">&#128476;&#65039; Fixings &amp; loose items</span>
      <span style="font-size:11px;color:var(--subtle)">
        ${fixings.length} line${fixings.length === 1 ? '' : 's'} · ${totalPieces} pcs${weightStr}
      </span>
    </div>`;

  // Add-row form (draftsman, job open)
  if (canEdit) {
    html += `<div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:10px">
      <div class="upload-zone" id="fixDropZone" style="flex:1;min-width:240px;margin:0;padding:12px;cursor:pointer"
           onclick="document.getElementById('fixManualFileInput').click()">
        <span style="font-size:13px;color:var(--text)">&#128228; Import bolt / anchor list (PDF)</span>
        <div style="color:var(--subtle);font-size:11px;margin-top:3px">
          our lists or a supplier quotation &middot; reads qty, description &amp; weight &middot; review before saving
        </div>
      </div>
      <input type="file" id="fixManualFileInput" accept=".pdf,.PDF" multiple
             style="display:none" onchange="onFixingFilesPicked(this.files)">
    </div>`;
    html += `<div style="display:flex;flex-wrap:wrap;gap:8px;align-items:flex-end;margin-bottom:10px;padding:10px 12px;background:var(--surface);border:1px solid var(--border);border-radius:8px">
      <div style="flex:1;min-width:200px">
        <label style="display:block;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em;margin-bottom:3px">Description</label>
        <input id="fixDesc" type="text" class="field-input" placeholder="e.g. M16 x 40 8.8 BZP setscrew"
               style="width:100%" onkeydown="if(event.key==='Enter')addFixing()">
      </div>
      <div style="width:80px">
        <label style="display:block;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em;margin-bottom:3px">Qty</label>
        <input id="fixQty" type="number" min="1" step="1" class="field-input" placeholder="0"
               style="width:100%;text-align:right" onkeydown="if(event.key==='Enter')addFixing()">
      </div>
      <div style="width:100px">
        <label style="display:block;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em;margin-bottom:3px">Wt each (kg)</label>
        <input id="fixWeight" type="number" min="0" step="0.001" class="field-input" placeholder="opt."
               style="width:100%;text-align:right" onkeydown="if(event.key==='Enter')addFixing()">
      </div>
      <button class="btn btn-primary" style="padding:8px 16px;font-size:12px" onclick="addFixing()">&#43; Add</button>
    </div>`;
  }

  if (fixings.length === 0) {
    html += `<div style="color:var(--subtle);font-size:12px;padding:6px 0">No fixings yet.${canEdit ? ' Add bolts, anchors and consumables above.' : ''}</div>`;
    return html + '</div>';
  }

  // Table
  html += `<div style="overflow-x:auto;border:1px solid var(--border);border-radius:8px;background:var(--surface)">
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead>
        <tr style="background:var(--bg-darker);color:var(--subtle);text-transform:uppercase;font-size:11px;letter-spacing:.04em">
          <th style="text-align:left;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Description</th>
          <th style="text-align:right;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Qty</th>
          <th style="text-align:right;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Sent</th>
          <th style="text-align:right;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Wt each</th>
          <th style="text-align:right;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Total wt</th>
          <th style="text-align:left;padding:8px 12px;font-weight:600;border-bottom:1px solid var(--border)">Status</th>
          ${canEdit ? '<th style="width:44px;border-bottom:1px solid var(--border)"></th>' : ''}
        </tr>
      </thead>
      <tbody>`;

  const statusStyles = {
    pending:            'background:rgba(255,107,0,.15);color:var(--accent)',
    at_supplier:        'background:rgba(99,102,241,.15);color:#a5b4fc',
    ready_for_despatch: 'background:rgba(62,207,142,.15);color:#3ecf8e',
    despatched:         'background:rgba(140,140,140,.15);color:var(--text)',
    on_site:            'background:rgba(140,140,140,.15);color:var(--text)'
  };

  for (const f of fixings) {
    const qty     = Number(f.quantity) || 0;
    const sent    = Number(f.despatched_qty) || 0;
    const wtEach  = f.unit_weight_kg != null ? Number(f.unit_weight_kg) : null;
    const totWt   = wtEach != null ? (wtEach * qty) : null;
    const pill    = `<span style="${statusStyles[f.status] || ''};padding:2px 9px;border-radius:6px;font-size:11px;font-weight:500;white-space:nowrap">${escapeHtml(BOM_STATUS_LABEL[f.status] || f.status)}</span>`;
    // Sent badge — grey none, amber partial, green complete, blue overship.
    const sentColor = sent === 0 ? 'var(--subtle)'
                    : sent < qty ? 'var(--accent)'
                    : sent === qty ? '#3ecf8e' : '#a5b4fc';
    const sentTxt = sent > qty ? `${sent} (+${sent - qty})` : `${sent}`;
    const sentCell = `<span style="color:${sentColor};font-family:var(--font-mono);font-size:13px">${sentTxt}</span>`;

    if (canEdit) {
      html += `<tr style="border-bottom:1px solid var(--border)">
        <td style="padding:6px 12px">
          <input type="text" value="${escapeHtml(f.description)}"
                 onchange="fixingEditField(${f.id}, 'description', this.value)"
                 style="width:100%;background:transparent;border:1px solid transparent;color:var(--text);font-family:var(--font-mono);font-size:13px;padding:4px 6px;border-radius:5px"
                 onfocus="this.style.borderColor='var(--border)';this.style.background='var(--bg-darker)'"
                 onblur="this.style.borderColor='transparent';this.style.background='transparent'"></td>
        <td style="padding:6px 12px;text-align:right">
          <input type="number" min="1" step="1" value="${qty}"
                 onchange="fixingEditField(${f.id}, 'quantity', this.value)"
                 style="width:70px;background:var(--bg-darker);border:1px solid var(--border);color:var(--text);font-family:var(--font-mono);font-size:13px;padding:4px 6px;border-radius:5px;text-align:right"></td>
        <td style="padding:6px 12px;text-align:right">${sentCell}</td>
        <td style="padding:6px 12px;text-align:right">
          <input type="number" min="0" step="0.001" value="${wtEach != null ? wtEach : ''}" placeholder="—"
                 onchange="fixingEditField(${f.id}, 'unit_weight_kg', this.value)"
                 style="width:80px;background:var(--bg-darker);border:1px solid var(--border);color:var(--text);font-family:var(--font-mono);font-size:13px;padding:4px 6px;border-radius:5px;text-align:right"></td>
        <td style="padding:6px 12px;text-align:right;color:var(--subtle);font-family:var(--font-mono);font-size:13px">${totWt != null ? totWt.toFixed(2) : '—'}</td>
        <td style="padding:6px 12px">${pill}</td>
        <td style="padding:6px 12px;text-align:center">
          <button class="btn btn-ghost" title="Delete" style="padding:5px 9px;font-size:14px;color:var(--subtle)"
                  onclick="deleteBomItem(${f.id})">&#128465;</button></td>
      </tr>`;
    } else {
      html += `<tr style="border-bottom:1px solid var(--border)">
        <td style="padding:10px 12px;color:var(--text);font-family:var(--font-mono);font-size:13px">${escapeHtml(f.description)}</td>
        <td style="padding:10px 12px;text-align:right;color:var(--text);font-family:var(--font-mono);font-size:13px">${qty}</td>
        <td style="padding:10px 12px;text-align:right">${sentCell}</td>
        <td style="padding:10px 12px;text-align:right;color:var(--subtle);font-family:var(--font-mono);font-size:13px">${wtEach != null ? wtEach.toFixed(3) : '—'}</td>
        <td style="padding:10px 12px;text-align:right;color:var(--subtle);font-family:var(--font-mono);font-size:13px">${totWt != null ? totWt.toFixed(2) : '—'}</td>
        <td style="padding:10px 12px">${pill}</td>
      </tr>`;
    }
  }

  html += `</tbody></table></div></div>`;
  return html;
}

async function addFixing() {
  const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
  if (!jobId) { toast('No job selected.', 'error'); return; }

  const descEl = document.getElementById('fixDesc');
  const qtyEl  = document.getElementById('fixQty');
  const wtEl   = document.getElementById('fixWeight');
  const description = (descEl?.value || '').trim();
  const quantity    = parseInt(qtyEl?.value);
  const wtRaw       = (wtEl?.value || '').trim();

  if (!description) { toast('Enter a description.', 'error'); descEl?.focus(); return; }
  if (!quantity || quantity < 1) { toast('Enter a quantity of 1 or more.', 'error'); qtyEl?.focus(); return; }

  try {
    await api.post('/api/job-bom-items', {
      job_id: jobId,
      description,
      quantity,
      item_type: 'fixing',
      unit_weight_kg: wtRaw === '' ? null : Number(wtRaw)
    });
    toast('Fixing added', 'success');
    await loadJobBomItems(jobId);
    renderBOM();
    // Re-focus the description for fast repeat entry
    document.getElementById('fixDesc')?.focus();
  } catch (e) {
    toast('Failed to add fixing: ' + e.message, 'error');
  }
}

async function fixingEditField(id, field, value) {
  const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
  const body = {};
  if (field === 'quantity') {
    const q = parseInt(value);
    if (!q || q < 1) { toast('Quantity must be 1 or more.', 'error'); if (jobId) renderBOM(); return; }
    body.quantity = q;
  } else if (field === 'unit_weight_kg') {
    const v = (value || '').trim();
    body.unit_weight_kg = v === '' ? null : Number(v);
  } else if (field === 'description') {
    const d = (value || '').trim();
    if (!d) { toast('Description cannot be empty.', 'error'); if (jobId) renderBOM(); return; }
    body.description = d;
  } else {
    return;
  }
  try {
    await api.put(`/api/job-bom-items/${id}`, body);
    if (jobId) await loadJobBomItems(jobId);
    renderBOM();
  } catch (e) {
    toast('Failed to update fixing: ' + e.message, 'error');
    if (jobId) renderBOM();
  }
}

// Fixings/anchor list importer: OCR one or more PDFs (our own bolt lists or a
// supplier's fastener quotation) and route them through the shared review
// modal in 'fixing' mode — weight column, no finish, saved as item_type=fixing.
async function onFixingFilesPicked(fileList) {
  if (!fileList || !fileList.length) return;
  if (!currentJob || !currentJob.spFolderId) {
    toast('Job folder not available — try reloading.', 'error');
    return;
  }
  const files = Array.from(fileList).filter(f =>
    f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf'));
  if (!files.length) { toast('Only PDFs accepted.', 'error'); return; }

  const container = document.getElementById('bomContent');
  const banner = document.createElement('div');
  banner.id = 'fixUploadBanner';
  banner.style.cssText = 'background:rgba(255,107,0,.08);border:1px solid rgba(255,107,0,.3);border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:12px;color:var(--text)';
  banner.textContent = `Reading 0 / ${files.length}…`;
  if (container) container.prepend(banner);

  const driveId = currentJob.spDriveId || BAMA_DRIVE_ID;
  let bomFolder;
  try {
    bomFolder = await getOrCreateSubfolder(currentJob.spFolderId, ELEMENT_FOLDERS.bom, driveId);
  } catch (e) {
    banner.remove();
    toast(`Could not access BOM folder: ${e.message}`, 'error');
    return;
  }

  const queue = [];
  for (let i = 0; i < files.length; i++) {
    const file = files[i];
    banner.textContent = `Uploading ${i + 1} / ${files.length} — ${file.name}`;
    try {
      const arrayBuffer = await file.arrayBuffer();
      const uploaded = await uploadFileToFolder(bomFolder.id, file.name, arrayBuffer, file.type, driveId);
      banner.textContent = `Reading ${i + 1} / ${files.length} — ${file.name}`;
      const ocr = await ocrFixingsPdf(file);
      queue.push({
        file,
        sharepoint: {
          fileId:   uploaded.id,
          driveId:  uploaded.parentReference?.driveId || driveId,
          webUrl:   uploaded.webUrl,
          fileName: file.name
        },
        ocr
      });
    } catch (e) {
      console.warn(`Failed on ${file.name}:`, e);
      toast(`${file.name}: ${e.message}`, 'error');
    }
  }
  banner.remove();
  const input = document.getElementById('fixManualFileInput');
  if (input) input.value = '';

  if (!queue.length) { toast('No PDFs were parsed.', 'error'); return; }

  _bmrMode = 'fixing';
  const modal = document.getElementById('bomManualReviewModal');
  if (modal && modal.classList.contains('active') && _bomManualQueue.length) {
    _bomManualQueue.push(...queue);
    toast(`Added ${queue.length} more — ${_bomManualQueue.length} now queued.`, 'info');
  } else {
    _bomManualQueue = queue;
  }
  openBomManualReviewModal();
}

// Claude document read on a fixing/fastener list. Handles BOTH our own bolt &
// anchor lists (with a per-piece weight column) and suppliers' quotations
// (price columns, 'per HUND' pricing units — which are NOT the quantity).
// Returns { items: [{ description, quantity, unit_weight_kg? }] }.
async function ocrFixingsPdf(file) {
  const dataUri = await _fileToDataUri(file);
  const b64 = dataUri.split(',')[1];

  const prompt = `Extract the fixing / fastener line items from this document. It is EITHER our own bolt & anchor list OR a supplier's quotation for fasteners (bolts, nuts, washers, setscrews, studding, anchors, resin, screws).

For each real line item in the main items table, return:
- "description": the full item as written, combining size / length / grade / coating / type into ONE readable string. Examples: "M20 x 45 XOX 8.8 Bright Zinc", "M24 Hexagonal Nut GR8 Bright Zinc", "M16 x 200 HILTI HIT-V 5.8 Bright Zinc", "M12x160 J-Fix Studding Z&Y", "BAPP 410ml Polyester Resin", "M16 Form A Flat Washer Galv".
- "quantity": the number of PIECES as a positive integer, taken from the Quantity column. CRITICAL: pricing units such as "HUND", "per hundred", "per 100", "BOX 50", "EACH" describe the PRICE basis — they are NOT the quantity. Always use the value in the Quantity column as the piece count (e.g. 344, 168, 156, 12).
- "unit_weight_kg": the weight of ONE piece in kg, ONLY if the document has a per-piece "Weight each" / "Weight (kg)" column. This is the small per-piece figure, never the line total. Omit this key entirely for supplier quotations (they have no per-piece weight).

Ignore anything that is not a real fastener line: header rows, group sub-totals, running totals, "Total", net/VAT/carriage/discount lines, payment terms, availability notes, boilerplate, and page footers.

Return ONLY JSON, no markdown, no commentary:
{ "items": [ { "description": "M20 x 45 XOX 8.8 Bright Zinc", "quantity": 64, "unit_weight_kg": 0.17 } ] }

Omit unit_weight_kg where there is no per-piece weight column. Return an empty items array if nothing is recognisable.`;

  const result = await callClaude({
    model: 'claude-sonnet-4-6',
    max_tokens: 6000,
    messages: [{
      role: 'user',
      content: [
        { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } },
        { type: 'text', text: prompt }
      ]
    }]
  });
  const text = (result.content?.find(b => b.type === 'text')?.text || '').trim();
  const s = text.indexOf('{'), e = text.lastIndexOf('}');
  if (s < 0 || e < s) throw new Error('Reader returned no JSON');
  const parsed = JSON.parse(text.slice(s, e + 1));
  if (!parsed.items || !Array.isArray(parsed.items)) parsed.items = [];
  parsed.items = parsed.items.map(r => {
    const out = {
      description: String(r.description || '').trim(),
      quantity: parseInt(r.quantity) || 1
    };
    const w = r.unit_weight_kg;
    if (w != null && w !== '' && !isNaN(Number(w))) out.unit_weight_kg = Number(w);
    return out;
  });
  return parsed;
}

function renderBomRow(it) {
  const sourceLabel = it.source === 'assembly'
    ? (it.source_assembly_mark ? `from ${escapeHtml(it.source_assembly_mark)}` : 'from assembly')
    : (it.file_name ? escapeHtml(it.file_name) : 'manual');
  // Finish is editable in place while the row hasn't yet gone to a supplier.
  // Changing it re-routes the row (a supplied finish → DN queue; an in-house
  // or no finish → ready for despatch) — handled server-side.
  const finishEditable = isDraftsman
    && currentJob && currentJob.status !== 'closed'
    && (it.status === 'pending' || it.status === 'ready_for_despatch');
  const finishBadge = finishEditable ? renderBomFinishSelect(it) : finishBadgeFor(it);
  const pdfLink = it.sharepoint_web_url
    ? `<a href="${escapeHtml(it.sharepoint_web_url)}" target="_blank" rel="noopener"
          style="color:var(--accent);font-size:13px;text-decoration:none;margin-left:6px"
          title="Open source PDF">&#128279;</a>`
    : '';

  // Status pill — same colour scheme as the finish badge but for the workflow state
  const statusStyles = {
    pending:            'background:rgba(255,107,0,.15);color:var(--accent)',
    at_supplier:        'background:rgba(99,102,241,.15);color:#a5b4fc',
    ready_for_despatch: 'background:rgba(62,207,142,.15);color:#3ecf8e',
    despatched:         'background:rgba(140,140,140,.15);color:var(--text)',
    on_site:            'background:rgba(140,140,140,.15);color:var(--text)'
  };
  const statusPill = `<span style="${statusStyles[it.status] || ''};padding:2px 9px;border-radius:6px;font-size:11px;font-weight:500;white-space:nowrap">${escapeHtml(BOM_STATUS_LABEL[it.status] || it.status)}</span>`;
  const supplierTag = it.supplier_name
    ? `<div style="font-size:11px;color:var(--subtle);margin-top:2px">${escapeHtml(it.supplier_name)}</div>`
    : '';

  // Per-status action buttons
  let actionBtn = '';
  if (it.status === 'at_supplier') {
    actionBtn = `<button class="btn btn-success" style="padding:5px 11px;font-size:11px;white-space:nowrap"
                   onclick="bomAdvance(${it.id}, 'ready_for_despatch')">&#10003; Mark returned</button>`;
  } else if (it.status === 'ready_for_despatch') {
    // No manual "Despatched" button — despatch/on-site is set automatically
    // when the Site Delivery Note is generated (via the 🚚 button), so the
    // DN and the status can never diverge.
    actionBtn = `<span style="font-size:11px;color:var(--subtle);white-space:nowrap" title="Generate a Site Delivery Note to despatch">via Site DN &#128666;</span>`;
  } else if (it.status === 'despatched' && isDraftsman) {
    // Recovery path: an item that was pushed to 'despatched' before a DN was
    // generated (e.g. the old manual button) is otherwise stuck out of the
    // SDN queue. Let a draftsman send it back to ready_for_despatch.
    actionBtn = `<button class="btn btn-ghost" style="padding:5px 11px;font-size:11px;white-space:nowrap;color:var(--subtle)"
                   title="Return to the despatch queue so a Site DN can be generated"
                   onclick="bomAdvance(${it.id}, 'ready_for_despatch')">&#8630; Undo despatch</button>`;
  }

  const deleteBtn = isDraftsman
    ? `<button class="btn btn-ghost" title="Delete" style="padding:5px 9px;font-size:14px;color:var(--subtle)"
         onclick="deleteBomItem(${it.id})">&#128465;</button>`
    : '';

  return `<tr style="border-bottom:1px solid var(--border)${_bomSelected.has(it.id) ? ';background:rgba(255,107,0,.06)' : ''}">
    <td style="padding:10px 8px;text-align:center">
      <input type="checkbox" class="bom-row-cb" data-id="${it.id}" data-status="${it.status}" ${_bomSelected.has(it.id) ? 'checked' : ''}
        onchange="bomToggleRow(${it.id}, this.checked)" style="cursor:pointer;accent-color:var(--accent)">
    </td>
    <td style="padding:10px 12px;color:var(--text);font-family:var(--font-mono);font-size:13px">${escapeHtml(it.description)}</td>
    <td style="padding:10px 12px;text-align:right;color:var(--text);font-family:var(--font-mono);font-size:13px">${Number(it.quantity)}</td>
    <td style="padding:10px 12px">${finishBadge}</td>
    <td style="padding:10px 12px;color:var(--text);font-size:12px">${sourceLabel}${pdfLink}</td>
    <td style="padding:10px 12px">
      ${statusPill}
      ${supplierTag}
    </td>
    <td style="padding:10px 12px;text-align:right;white-space:nowrap">
      ${actionBtn}
      ${deleteBtn}
    </td>
  </tr>`;
}

// In-place finish picker for a BOM row. Options come from the same
// _finishesCache the OCR review modal uses (active finishing services).
// If the row's current finish isn't in that list (e.g. it was later
// un-marked as a finish or deactivated), we still surface it as a
// selected option so we never silently blank it.
function renderBomFinishSelect(it) {
  const finishes = _finishesCache || [];
  const curId = it.finish_service_id != null ? Number(it.finish_service_id) : null;
  const curInList = curId != null && finishes.some(f => Number(f.id) === curId);

  let opts = `<option value="">— none / in-house —</option>`;
  if (curId != null && !curInList) {
    opts += `<option value="${curId}" selected>${escapeHtml(it.finish_name || 'current finish')}</option>`;
  }
  for (const f of finishes) {
    const sel = curId === Number(f.id) ? 'selected' : '';
    opts += `<option value="${f.id}" ${sel}>${escapeHtml(f.name)}</option>`;
  }
  return `<select onchange="bomChangeFinish(${it.id}, this.value)"
            title="Change finish — re-routes the item (supplied finish → DN queue, in-house/none → ready for despatch)"
            style="background:var(--surface);border:1px solid var(--border);color:var(--text);border-radius:6px;padding:3px 6px;font-size:11px;max-width:160px;cursor:pointer">
            ${opts}
          </select>`;
}

async function bomChangeFinish(id, val) {
  try {
    await api.put(`/api/job-bom-items/${id}`, {
      finish_service_id: val ? parseInt(val) : null
    });
    const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
    if (jobId) await loadJobBomItems(jobId);
    renderBOM();
  } catch (e) {
    toast('Failed to change finish: ' + e.message, 'error');
  }
}

// ── BOM bulk selection + actions (mirrors the QB takeoff bulk bar) ──────────
function bomToggleRow(id, checked) {
  if (checked) _bomSelected.add(id); else _bomSelected.delete(id);
  const tr = document.querySelector(`.bom-row-cb[data-id="${id}"]`)?.closest('tr');
  if (tr) tr.style.background = checked ? 'rgba(255,107,0,.06)' : '';
  bomUpdateBulkBar();
}
function bomToggleAllVisible(checked) { checked ? bomSelectAll() : bomDeselectAll(); }
function bomSelectAll() {
  document.querySelectorAll('.bom-row-cb').forEach(cb => {
    cb.checked = true; _bomSelected.add(parseInt(cb.dataset.id));
    const tr = cb.closest('tr'); if (tr) tr.style.background = 'rgba(255,107,0,.06)';
  });
  bomUpdateBulkBar();
}
function bomDeselectAll() {
  _bomSelected.clear();
  document.querySelectorAll('.bom-row-cb').forEach(cb => {
    cb.checked = false; const tr = cb.closest('tr'); if (tr) tr.style.background = '';
  });
  bomUpdateBulkBar();
}
function bomInvertSelection() {
  document.querySelectorAll('.bom-row-cb').forEach(cb => {
    const id = parseInt(cb.dataset.id);
    const now = !_bomSelected.has(id);
    cb.checked = now; if (now) _bomSelected.add(id); else _bomSelected.delete(id);
    const tr = cb.closest('tr'); if (tr) tr.style.background = now ? 'rgba(255,107,0,.06)' : '';
  });
  bomUpdateBulkBar();
}
function bomToggleGroup(status, checked) {
  document.querySelectorAll(`.bom-row-cb[data-status="${status}"]`).forEach(cb => {
    const id = parseInt(cb.dataset.id);
    cb.checked = checked; if (checked) _bomSelected.add(id); else _bomSelected.delete(id);
    const tr = cb.closest('tr'); if (tr) tr.style.background = checked ? 'rgba(255,107,0,.06)' : '';
  });
  bomUpdateBulkBar();
}
// Fresh selection of every row in one status (used by "Select all returned"):
// clears whatever was ticked, then selects just that status group.
function bomSelectByStatus(status) {
  bomDeselectAll();
  bomToggleGroup(status, true);
}
function bomUpdateBulkBar() {
  const bar = document.getElementById('bomBulkBar');
  const cnt = document.getElementById('bomSelCount');
  if (cnt) cnt.textContent = `${_bomSelected.size} selected`;
  if (bar) bar.style.display = _bomSelected.size ? 'flex' : 'none';
  // header + group checkbox states
  const allCbs = Array.from(document.querySelectorAll('.bom-row-cb'));
  const head = document.getElementById('bomHeadCb');
  if (head) {
    const n = allCbs.filter(cb => cb.checked).length;
    head.checked = n > 0 && n === allCbs.length;
    head.indeterminate = n > 0 && n < allCbs.length;
  }
  document.querySelectorAll('.bom-group-cb').forEach(gcb => {
    const rows = allCbs.filter(cb => cb.dataset.status === gcb.dataset.status);
    const n = rows.filter(cb => cb.checked).length;
    gcb.checked = n > 0 && n === rows.length;
    gcb.indeterminate = n > 0 && n < rows.length;
  });
}
async function bomReloadAfterBulk() {
  const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
  if (jobId) await loadJobBomItems(jobId); // clears _bomSelected
  renderBOM();
}
async function bomBulkSetFinish(val) {
  if (val === '__') return;                    // placeholder chosen — ignore
  const ids = Array.from(_bomSelected);
  if (!ids.length) return;
  try {
    await api.post('/api/job-bom-items/bulk-finish', {
      item_ids: ids,
      finish_service_id: val === '' ? null : parseInt(val)
    });
    await bomReloadAfterBulk();
    toast('Finish updated on selected rows', 'success');
  } catch (e) { toast('Bulk finish failed: ' + e.message, 'error'); }
}
async function bomBulkStatus(status) {
  const ids = Array.from(_bomSelected);
  if (!ids.length) return;
  try {
    const r = await api.post('/api/job-bom-items/bulk-status', { item_ids: ids, status });
    await bomReloadAfterBulk();
    const n = (r && r.updated != null) ? r.updated : ids.length;
    toast(`${n} row${n === 1 ? '' : 's'} updated`, n ? 'success' : 'info');
  } catch (e) { toast('Bulk status failed: ' + e.message, 'error'); }
}
async function bomBulkDelete() {
  const ids = Array.from(_bomSelected);
  if (!ids.length) return;
  if (!(await bamaConfirm({ title: 'Delete BOM items', body: `Delete ${ids.length} selected BOM item${ids.length === 1 ? '' : 's'}? This cannot be undone.`, confirmText: 'Delete', tone: 'danger' }))) return;
  try {
    const r = await api.post('/api/job-bom-items/bulk-delete', { item_ids: ids });
    await bomReloadAfterBulk();
    const n = (r && r.deleted != null) ? r.deleted : ids.length;
    toast(`${n} item${n === 1 ? '' : 's'} deleted`, 'success');
  } catch (e) { toast('Bulk delete failed: ' + e.message, 'error'); }
}

async function deleteBomItem(id) {
  if (!(await bamaConfirm({ title: 'Delete BOM item', body: 'This cannot be undone.', confirmText: 'Delete', tone: 'danger' }))) return;
  try {
    await api.delete(`/api/job-bom-items/${id}`);
    toast('BOM item deleted', 'success');
    const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
    if (jobId) await loadJobBomItems(jobId);
    renderBOM();
  } catch (e) {
    toast('Failed to delete BOM item: ' + e.message, 'error');
  }
}

async function bomAdvance(id, newStatus) {
  try {
    // Status changes go through the dedicated state-machine endpoint
    // (PUT /api/job-bom-items/{id}/status). The bare PUT /{id} route only
    // edits description/quantity/finish and would reject a `status` body.
    await api.put(`/api/job-bom-items/${id}/status`, { status: newStatus });
    const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
    if (jobId) await loadJobBomItems(jobId);
    renderBOM();
  } catch (e) {
    toast('Failed to update BOM item: ' + e.message, 'error');
  }
}

function wireBomDropZone() {
  const dz = document.getElementById('bomDropZone');
  if (dz) {
    dz.addEventListener('dragover', (e) => { e.preventDefault(); dz.classList.add('drag-over'); });
    dz.addEventListener('dragleave', () => dz.classList.remove('drag-over'));
    dz.addEventListener('drop', (e) => {
      e.preventDefault();
      dz.classList.remove('drag-over');
      const files = Array.from(e.dataTransfer.files)
        .filter(f => f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf'));
      if (files.length) onBomManualFilesPicked(files);
    });
  }
  // Fixings/bolt-list import zone — same drag-and-drop behaviour.
  const fz = document.getElementById('fixDropZone');
  if (fz) {
    fz.addEventListener('dragover', (e) => { e.preventDefault(); fz.classList.add('drag-over'); });
    fz.addEventListener('dragleave', () => fz.classList.remove('drag-over'));
    fz.addEventListener('drop', (e) => {
      e.preventDefault();
      fz.classList.remove('drag-over');
      const files = Array.from(e.dataTransfer.files)
        .filter(f => f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf'));
      if (files.length) onFixingFilesPicked(files);
    });
  }
}


// No-op stub. The pre-11.1 BOM tile view had per-row checkboxes that
// drove the visibility of the Generate-DN button via this function;
// the new table view doesn't (the DN modal handles selection itself).
// Kept as a stub so any stale onchange="updateBomDnButton()" attribute
// doesn't error out during the deploy lag between SWA and an open tab.
function updateBomDnButton() { /* no-op — see comment */ }

// ── Generate DN flow (commit 11.1 — supplier-first selection) ──
//
// New flow per user feedback on commit 10/11:
//   1. User clicks "Generate DN" at the top of the BOM table.
//   2. Modal opens with the SUPPLIER picker (filtered to active +
//      offering at least one finish service we have items for).
//   3. After supplier is chosen, ALL pending + ready_for_despatch BOM
//      items in this job appear with checkboxes. Items matching one of
//      the supplier's services are ticked by default; everything else
//      is unticked but selectable (so bolts/nuts can ride along to the
//      galvaniser, for instance).
//   4. Confirm → backend allocates DN ref + flips only the pending
//      items to at_supplier (ready_for_despatch items stay where they
//      are; they're just listed on the DN as ride-alongs). Frontend
//      then builds the PDF, uploads to SharePoint, and reloads.
let _pendingDn = null;
//   { items:[allEligibleBomItems], supplierId, supplierName, supplierServiceIds:Set }

// ── Multi-job DN / SDN helpers ───────────────────────────────────────────────
// One delivery note can carry several jobs from the SAME project (mirrors the
// RAMS merge). Items are tagged _jobId/_jobName so the modal groups them and
// the printed PDF banners them per job — it must be obvious what belongs where.
let _gdnJobIds = [];   // supplier-DN selected jobs
let _sdnJobIds = [];   // site-DN selected jobs
let _dnRegCache = {};  // projectDbId -> DeliveryNoteRegister rows

// BOM items for a job WITHOUT touching _bomSelected (loadJobBomItems clears
// the grid selection — fine on the BOM tab, wrong mid-modal for other jobs).
async function _dnFetchJobItems(jobId) {
  const id = parseInt(jobId);
  if (!id) return [];
  if (_bomItemsByJob[id]) return _bomItemsByJob[id];
  try {
    const rows = await api.get(`/api/job-bom-items?job_id=${encodeURIComponent(id)}`);
    _bomItemsByJob[id] = Array.isArray(rows) ? rows : [];
  } catch (e) { _bomItemsByJob[id] = []; }
  return _bomItemsByJob[id];
}

function _dnProjectJobs() {
  return (drawingsData.projects?.[currentProject?.id]?.jobs) || [];
}
function _dnJobName(jobId) {
  const j = _dnProjectJobs().find(x => parseInt(x.id) === parseInt(jobId));
  return j ? (j.name || ('Job ' + jobId)) : ('Job ' + jobId);
}

// Generic jobs-covered checkbox list for the DN/SDN modals.
function _dnRenderJobsPicker(elId, selIds, tickFn) {
  const wrap = document.getElementById(elId);
  if (!wrap) return;
  const jobs = _dnProjectJobs();
  if (jobs.length <= 1) { wrap.parentElement && (wrap.parentElement.style.display = 'none'); return; }
  if (wrap.parentElement) wrap.parentElement.style.display = '';
  wrap.innerHTML = jobs.map(j => {
    const jid = parseInt(j.id);
    const on = selIds.includes(jid);
    return `<label style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-bottom:1px solid var(--border);cursor:pointer">
      <input type="checkbox" ${on ? 'checked' : ''} value="${jid}"
             onchange="${tickFn}(${jid}, this.checked)" style="width:14px;height:14px;accent-color:var(--accent)">
      <span style="font-size:12px;color:var(--text)">${escapeHtml(j.name || ('Job ' + jid))}</span>
    </label>`;
  }).join('');
}

const _dnJobChip = name => `<span style="font-size:10px;color:#a78bfa;background:rgba(139,92,246,.12);border:1px solid rgba(139,92,246,.3);border-radius:4px;padding:1px 6px;white-space:nowrap">${escapeHtml(name)}</span>`;

async function openGenerateDnModalSQL() {
  const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
  if (!jobId) { toast('No job selected.', 'error'); return; }

  _gdnJobIds = [jobId];

  // Eligible items = anything not yet despatched (i.e. status pending
  // OR ready_for_despatch OR at_supplier). We include at_supplier too
  // so the user can re-print a DN if needed, but they're shown read-only
  // and ticking is disabled. Union across every ticked job, tagged per job.
  const items = await _gdnEligibleItems();
  if (items.length === 0) {
    toast('Nothing to send. All BOM items are already despatched.', 'error');
    return;
  }

  _pendingDn = { items, supplierId: null, supplierName: '', supplierServiceIds: new Set(), suppliers: [] };

  // Fetch suppliers. Show only suppliers active and offering at least
  // one finish that appears in the eligible items list. That way the
  // operator isn't picking from non-relevant suppliers (e.g. a
  // transport company when nothing on the job needs delivery).
  let suppliers = [];
  try { suppliers = (await api.get('/api/suppliers')) || []; }
  catch (e) { toast('Could not load suppliers: ' + e.message, 'error'); _pendingDn = null; return; }
  _pendingDn.suppliers = suppliers;

  _dnRenderJobsPicker('gdnJobsList', _gdnJobIds, 'gdnJobTick');

  _gdnRenderSuppliers();

  document.getElementById('generateDnModal').classList.add('active');
}

// Eligible items across every ticked job, each tagged _jobId/_jobName.
async function _gdnEligibleItems() {
  const out = [];
  for (const jid of _gdnJobIds) {
    const rows = await _dnFetchJobItems(jid);
    const nm = _dnJobName(jid);
    rows.filter(i => i.status !== 'despatched')
        .forEach(i => out.push({ ...i, _jobId: jid, _jobName: nm }));
  }
  return out;
}

// Job tick on the DN modal — rebuild the eligible union and the supplier list
// (finish relevance follows the items), keeping the picked supplier if it's
// still on the list.
async function gdnJobTick(jobId, on) {
  jobId = parseInt(jobId);
  if (on) { if (!_gdnJobIds.includes(jobId)) _gdnJobIds.push(jobId); }
  else _gdnJobIds = _gdnJobIds.filter(x => x !== jobId);
  if (!_gdnJobIds.length) { _gdnJobIds = [jobId]; }   // never zero jobs
  _dnRenderJobsPicker('gdnJobsList', _gdnJobIds, 'gdnJobTick');
  if (!_pendingDn) return;
  _pendingDn.items = await _gdnEligibleItems();
  _gdnRenderSuppliers();
}

// Supplier list + counters from the current _pendingDn.items. Re-selects the
// previously picked supplier when it survives the re-filter.
function _gdnRenderSuppliers() {
  if (!_pendingDn) return;
  const items = _pendingDn.items;
  const suppliers = _pendingDn.suppliers || [];

  const relevantFinishIds = new Set(items.map(i => i.finish_service_id).filter(Boolean));
  // If the user has *only* no-finish ready_for_despatch items, we should
  // still let them pick any supplier (eg. a transport company). So if
  // relevantFinishIds is empty, fall back to showing all active suppliers.
  const filteredSuppliers = relevantFinishIds.size === 0
    ? suppliers.filter(s => s.is_active !== false)
    : suppliers.filter(s =>
        s.is_active !== false &&
        (s.services || []).some(svc => relevantFinishIds.has(svc.service_type_id))
      );

  document.getElementById('gdnItemCount').textContent = items.length;
  const sumQty = items.reduce((s, i) => s + (Number(i.quantity) || 0), 0);
  document.getElementById('gdnItemQtySum').textContent = sumQty;
  document.getElementById('gdnFinishName').textContent =
    relevantFinishIds.size === 0 ? 'mixed / no finish' : 'various';

  const prevSupplier = _pendingDn.supplierId;

  // Step 1 UI: supplier picker. Items list rendered after pick.
  const sList = document.getElementById('gdnSupplierList');
  if (!filteredSuppliers.length) {
    sList.innerHTML = `<div style="padding:16px;color:var(--subtle);font-size:13px;text-align:center">
      No active suppliers match the finishes on the selected jobs. Add one in Manager &rarr; Suppliers.
    </div>`;
  } else {
    sList.innerHTML = filteredSuppliers.map(s => {
      const addr = [s.address_line1, s.city].filter(Boolean).join(', ');
      const addrLines = [
        s.address_line1, s.address_line2,
        [s.city, s.county].filter(Boolean).join(', '),
        s.postcode
      ].filter(Boolean);
      const svcNames = (s.services || []).map(svc => svc.service_name).filter(Boolean).join(', ');
      return `<label class="gdn-supplier-row" data-id="${s.id}"
                style="display:flex;align-items:center;gap:10px;padding:10px 14px;border:1px solid var(--border);
                       border-radius:8px;margin-bottom:6px;cursor:pointer;background:var(--surface);">
        <input type="radio" name="gdnSupplier" value="${s.id}"
               data-name="${escapeHtml(s.supplier_name)}"
               data-addr="${escapeHtml(JSON.stringify(addrLines))}"
               data-services="${(s.services || []).map(svc => svc.service_type_id).join(',')}"
               style="width:16px;height:16px;accent-color:var(--accent)">
        <div style="flex:1">
          <div style="font-size:13px;font-weight:600;color:var(--text)">${escapeHtml(s.supplier_name)}</div>
          ${svcNames ? `<div style="font-size:11px;color:var(--accent);margin-top:2px">${escapeHtml(svcNames)}</div>` : ''}
          ${addr ? `<div style="font-size:11px;color:var(--subtle);margin-top:2px">${escapeHtml(addr)}</div>` : ''}
        </div>
      </label>`;
    }).join('');
  }

  // Items list cleared (rendered after supplier is picked)
  document.getElementById('gdnItemList').innerHTML =
    '<div style="color:var(--subtle);font-size:12px;text-align:center;padding:20px">Pick a supplier above to choose items.</div>';

  const btn = document.getElementById('gdnConfirmBtn');
  btn.disabled = true; btn.style.opacity = '.4'; btn.style.cursor = 'not-allowed';

  // Wire radio change → render item list with smart defaults
  sList.querySelectorAll('input[name="gdnSupplier"]').forEach(r => {
    r.addEventListener('change', () => {
      const sid = parseInt(r.value);
      const sname = r.dataset.name || '';
      const services = (r.dataset.services || '').split(',').filter(Boolean).map(x => parseInt(x));
      _pendingDn.supplierId = sid;
      _pendingDn.supplierName = sname;
      _pendingDn.supplierServiceIds = new Set(services);
      try { _pendingDn.deliverToLines = JSON.parse(r.dataset.addr || '[]'); }
      catch { _pendingDn.deliverToLines = []; }
      renderGdnItemList();
    });
  });

  // Re-pick the previous supplier if it's still available.
  if (prevSupplier) {
    const keep = sList.querySelector(`input[name="gdnSupplier"][value="${prevSupplier}"]`);
    if (keep) { keep.checked = true; keep.dispatchEvent(new Event('change')); }
    else { _pendingDn.supplierId = null; _pendingDn.supplierName = ''; _pendingDn.supplierServiceIds = new Set(); }
  }
}

function renderGdnItemList() {
  if (!_pendingDn) return;
  const list = document.getElementById('gdnItemList');
  const items = _pendingDn.items;
  const supSvc = _pendingDn.supplierServiceIds;

  let html = `<div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">
    <label style="display:flex;align-items:center;gap:6px;cursor:pointer">
      <input type="checkbox" id="gdnSelectAll" onchange="gdnToggleAll(this.checked)" style="width:14px;height:14px;accent-color:var(--accent)">
      <span style="font-size:11px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Select all</span>
    </label>
    <span style="margin-left:auto;font-size:11px;color:var(--subtle)" id="gdnSelCount">0 selected</span>
  </div>`;

  const multiJob = new Set(items.map(i => i._jobId)).size > 1;
  html += '<div style="border:1px solid var(--border);border-radius:8px;overflow:hidden;max-height:280px;overflow-y:auto">';
  let _lastJob = null;
  const sorted = multiJob ? items.slice().sort((a, b) => String(a._jobName || '').localeCompare(String(b._jobName || ''))) : items;
  sorted.forEach((it, idx) => {
    if (multiJob && it._jobName !== _lastJob) {
      _lastJob = it._jobName;
      html += `<div style="padding:6px 12px;font-size:10px;color:#a78bfa;text-transform:uppercase;letter-spacing:.05em;background:rgba(139,92,246,.08);border-bottom:1px solid var(--border);font-weight:700">${escapeHtml(it._jobName || '')}</div>`;
    }
    const matches = it.finish_service_id && supSvc.has(it.finish_service_id);
    const readonly = it.status === 'at_supplier';
    const checked = matches && !readonly; // default-tick matching items
    const dim = readonly ? 'opacity:.5' : '';

    html += `<label style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid var(--border);cursor:${readonly ? 'not-allowed' : 'pointer'};${dim}">
      <input type="checkbox" class="gdn-item-check" data-id="${it.id}"
             ${checked ? 'checked' : ''} ${readonly ? 'disabled' : ''}
             onchange="gdnUpdateSelCount()"
             style="width:14px;height:14px;accent-color:var(--accent)">
      <span style="font-family:var(--font-mono);font-size:12px;color:var(--text);flex:1">${escapeHtml(it.description)}</span>
      <span style="font-size:12px;color:var(--text);min-width:50px;text-align:right">${Number(it.quantity)}</span>
      <span style="min-width:120px">${finishBadgeFor(it)}</span>
      <span style="font-size:11px;color:var(--subtle)">${it.source === 'assembly'
        ? (it.source_assembly_mark ? `from ${escapeHtml(it.source_assembly_mark)}` : 'assembly')
        : 'manual'}</span>
    </label>`;
  });
  html += '</div>';
  list.innerHTML = html;
  gdnUpdateSelCount();
}

function gdnToggleAll(on) {
  document.querySelectorAll('.gdn-item-check:not(:disabled)').forEach(c => c.checked = on);
  gdnUpdateSelCount();
}

function gdnUpdateSelCount() {
  const checked = document.querySelectorAll('.gdn-item-check:checked').length;
  const el = document.getElementById('gdnSelCount');
  if (el) el.textContent = `${checked} selected`;
  const btn = document.getElementById('gdnConfirmBtn');
  if (btn) {
    btn.disabled = checked === 0;
    btn.style.opacity = checked === 0 ? '.4' : '1';
    btn.style.cursor  = checked === 0 ? 'not-allowed' : 'pointer';
  }
}

function closeGenerateDnModalSQL() {
  document.getElementById('generateDnModal').classList.remove('active');
  _pendingDn = null;
}

async function confirmGenerateDnSQL() {
  if (!_pendingDn || !_pendingDn.supplierId) return;
  const selectedIds = Array.from(document.querySelectorAll('.gdn-item-check:checked'))
    .map(c => parseInt(c.dataset.id));
  if (!selectedIds.length) { toast('Pick at least one item.', 'error'); return; }

  // Split selected items: those still 'pending' need status flip via backend;
  // those already 'ready_for_despatch' just ride along on the printed DN.
  const allSelected = _pendingDn.items.filter(i => selectedIds.includes(i.id));
  const toShip      = allSelected.filter(i => i.status === 'pending');
  const rideAlongs  = allSelected.filter(i => i.status === 'ready_for_despatch');

  // Backend currently rejects multi-finish DNs. New behaviour: only the
  // 'pending' subset is sent to the backend, and we require those to
  // share a single finish. Ride-alongs (ready_for_despatch) are not
  // sent — they just appear on the printed PDF.
  if (toShip.length > 0) {
    const finishIds = new Set(toShip.map(i => i.finish_service_id));
    if (finishIds.size > 1) {
      toast('Items being SENT for finishing must share one finish. Untick the odd ones out or split the DN.', 'error');
      return;
    }
  }
  // If there's nothing pending to ship AND only ride-alongs, that's a
  // print-only DN — let's still allow it (the operator may want to
  // physically deliver bolts to the same supplier on the same trip).

  const btn = document.getElementById('gdnConfirmBtn');
  btn.disabled = true; btn.style.opacity = '.5';

  const proj = currentProject;
  const job  = currentJob;

  try {
    // 1. Allocate the DN ref + flip ONLY the pending items to at_supplier.
    //    If only ride-alongs are selected, we still need a DN ref — we
    //    use a separate endpoint path that doesn't require pending items.
    //    For simplicity, route through generate-dn when there are pending
    //    items, and a tiny inline ref allocation for ride-along-only DNs.
    let dnRef;
    if (toShip.length > 0) {
      const allocRes = await api.post('/api/job-bom-items/generate-dn', {
        item_ids:    toShip.map(i => i.id),
        supplier_id: _pendingDn.supplierId
      });
      dnRef = allocRes.dn_ref;
    } else {
      // Ride-along-only DN: no status flips. Allocate ref via a no-op call
      // to /generate-dn would fail validation. Easiest: skip ref allocation
      // and use a timestamp-based ref for now. (A proper "ride-along only
      // DN" endpoint would be a future improvement.)
      const ts = new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 12);
      dnRef = `DN-RA-${ts}`;
    }

    // 2. Build the DN PDF
    await loadLogoDataUri();
    const dnJobNames = [...new Set(allSelected.map(i => i._jobName).filter(Boolean))];
    const dn = {
      number:          dnRef,
      createdAt:       new Date().toISOString(),
      destinationName: _pendingDn.supplierName,
      deliverTo:       { name: _pendingDn.supplierName, lines: _pendingDn.deliverToLines || [], contact: '' },
      items:           allSelected,
      jobNames:        dnJobNames,
      finishName:      [...new Set(allSelected.map(i => i.finish_name).filter(Boolean))].join(', ') || ''
    };
    // 3. Render PDF blob natively with jsPDF (no html2canvas — the page's CSS
    //    is irrelevant, so no white-on-white / clipping).
    const pdfBlob = await renderDnPdfBlob(dn, proj || {}, job || {}, `${dnRef}.pdf`);

    // 4. Upload to SharePoint: <ProjectFolder>/07 - Deliveries/<JobFolder>/<DN-ref>.pdf
    const projectFolder = await findProjectFolder(proj.id);
    if (!projectFolder) throw new Error('Project folder not found on SharePoint');
    const driveId = projectFolder.parentReference?.driveId || BAMA_DRIVE_ID;
    const deliveriesFolder = await getOrCreateSubfolder(projectFolder.id, '07 - Deliveries', driveId);
    // Multi-job DN files at the 07 - Deliveries root (refs are unique) so it
    // isn't hidden under one arbitrary job's folder; single-job keeps the job
    // folder as before.
    const dnJobIdsUsed = [...new Set(allSelected.map(i => i._jobId).filter(Boolean))];
    const jobSubFolder = (dnJobIdsUsed.length > 1)
      ? deliveriesFolder
      : await getOrCreateSubfolder(deliveriesFolder.id, (job && (job.folderName || job.name)) || 'Unassigned', driveId);
    const dnFileName = `${dnRef}.pdf`;
    const token = await getToken();
    const upUrl = `https://graph.microsoft.com/v1.0/drives/${driveId}/items/${jobSubFolder.id}:/${encodeURIComponent(dnFileName)}:/content`;
    const upRes = await fetch(upUrl, {
      method: 'PUT',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/pdf' },
      body: pdfBlob
    });
    if (!upRes.ok) throw new Error(`DN upload failed: ${upRes.status}`);
    const uploaded = await upRes.json();

    // Deliveries register row — durable "when was it sent + link" record.
    // Non-fatal: the DN is already filed, a register hiccup only warns.
    try {
      await api.post('/api/dn-register', {
        ref: dnRef, kind: 'supplier',
        project_id: parseInt(proj.dbId) || null,
        job_ids: dnJobIdsUsed,
        destination: _pendingDn.supplierName || null,
        line_count: allSelected.length,
        total_qty: allSelected.reduce((s, i) => s + (Number(i.quantity) || 0), 0),
        sharepoint_file_id: uploaded.id || null,
        sharepoint_drive_id: driveId || null,
        sharepoint_web_url: uploaded.webUrl || null,
        file_name: dnFileName,
        created_by: _currentDraftsmanName || null
      });
      delete _dnRegCache[parseInt(proj.dbId)];
    } catch (regErr) {
      toast('DN saved, but the deliveries register entry failed (' + regErr.message + '). Has create-delivery-note-register.sql been run?', 'error');
    }

    closeGenerateDnModalSQL();
    const msg = toShip.length && rideAlongs.length
      ? `${dnRef} generated — ${toShip.length} for finishing + ${rideAlongs.length} ride-along.`
      : (toShip.length
          ? `${dnRef} generated for ${toShip.length} item${toShip.length>1?'s':''}.`
          : `${dnRef} generated for ${rideAlongs.length} ride-along item${rideAlongs.length>1?'s':''}.`);
    toast(msg, 'success');
    // Refresh every job the DN touched (statuses flipped server-side).
    for (const jid of dnJobIdsUsed) {
      delete _bomItemsByJob[jid];
      if (currentJob && parseInt(currentJob.id) === jid) await loadJobBomItems(jid);
      else await _dnFetchJobItems(jid);
    }
    renderBOM();

    if (uploaded.webUrl) window.open(uploaded.webUrl, '_blank');

  } catch (e) {
    toast(`DN failed: ${e.message}`, 'error');
    btn.disabled = false; btn.style.opacity = '1';
    return;
  }
}

// ── Site Delivery Note (SDN) flow ──
//
// Lives on the Site element. Selects items in 'ready_for_despatch'
// (items that have come back from a supplier, or items that never
// needed a finishing supplier), generates an SDN, ships them to site,
// and flips their status to 'on_site'.
//
// Differences from the supplier DN flow:
//   - No supplier picker (destination is implicitly "site" — the
//     client's installation address, which lives on the project).
//   - No state-machine restrictions per finish — anything that's
//     ready can ride along.
//   - Uses Settings.sdn_next_seq → SDN-0001, SDN-0002, …
//   - Terminal status is 'on_site' (not 'despatched').
// ═══════════════════════════════════════════
// JOB SHEET — per-PROJECT site/delivery details
// ═══════════════════════════════════════════
//
// One ProjectSheets row per Projects row (keyed by Projects.id, i.e.
// proj.dbId — NOT the project_number string). Two different site
// addresses within one project is rare, so the sheet lives at project
// level and every job under the project shares it. The UI keeps
// calling it "Job Sheet".
//
// It is the DEFAULT prefill source for the site-facing documents
// (Site DN, Site Pack, RAMS) — see _jobSheetResolved(). When no
// sheet has been saved yet, those documents fall back to the
// project's site address (if set) and then the client address,
// exactly as before.
//
// Supplier DNs (galv / powder coat) are deliberately NOT wired to
// this — they keep using the supplier's own address.

let _currentJobSheet = null;
let _currentJobSheetProjId = null;   // Projects.id the cached sheet belongs to
let _jobSheetLoadPromise = null;     // in-flight fetch — awaited, never raced

async function loadJobSheet(projectDbId) {
  const id = parseInt(projectDbId);
  if (!id) {
    _currentJobSheet = null; _currentJobSheetProjId = null; _jobSheetLoadPromise = null;
    return null;
  }
  // Same project: return the in-flight promise (or the settled cache) so a
  // fast click on "Job Sheet" right after opening the project still gets
  // the SAVED sheet, never a race-empty one.
  if (_currentJobSheetProjId === id && _jobSheetLoadPromise) return _jobSheetLoadPromise;
  _currentJobSheet = null;
  _currentJobSheetProjId = id;
  _jobSheetLoadPromise = (async () => {
    try {
      const row = await api.get(`/api/project-sheet/${id}`);
      if (_currentJobSheetProjId !== id) return null;   // switched project mid-fetch
      _currentJobSheet = (row && row.project_id) ? row : null;
    } catch (e) {
      _currentJobSheet = null;  // degrade gracefully — prefill falls back
    }
    return _currentJobSheet;
  })();
  return _jobSheetLoadPromise;
}

// Resolve the default site/delivery details for site-facing documents.
// Priority: 1) saved Job Sheet  2) project site address  3) client address.
// Returns { source, siteName, lines[], contact, phone, email, po }.
function _jobSheetResolved(proj) {
  const js = _currentJobSheet;
  const jsHasData = js && (js.address_line1 || js.postcode || js.site_name ||
                           js.site_manager_name || js.pm_name || js.commercial_name);
  if (jsHasData) {
    // Site documents want the person actually on site: Site Manager first,
    // then Project Manager, then Commercial as a last resort.
    const c = (js.site_manager_name || js.site_manager_phone)
      ? { n: js.site_manager_name, p: js.site_manager_phone, e: js.site_manager_email }
      : (js.pm_name || js.pm_phone)
        ? { n: js.pm_name, p: js.pm_phone, e: js.pm_email }
        : { n: js.commercial_name, p: js.commercial_phone, e: js.commercial_email };
    return {
      source:   'jobsheet',
      siteName: js.site_name || proj?.name || proj?.project_name || '',
      lines: [js.address_line1, js.address_line2,
              [js.city, js.county].filter(Boolean).join(', '), js.postcode].filter(Boolean),
      contact: c.n || '',
      phone:   c.p || '',
      email:   c.e || '',
      bamaName:  js.bama_contact_name || '',
      bamaPhone: js.bama_contact_phone || '',
      po:      js.client_po_number || proj?.client_po_number || ''
    };
  }
  const useSite = proj && proj.site_same_as_client === false &&
    (proj.site_address_line1 || proj.site_postcode);
  const a = useSite
    ? { l1: proj.site_address_line1, l2: proj.site_address_line2, city: proj.site_city,
        county: proj.site_county, pc: proj.site_postcode,
        contact: proj.site_contact_name, phone: proj.site_contact_phone,
        email: proj.site_contact_email }
    : { l1: proj?.client_address_line1, l2: proj?.client_address_line2, city: proj?.client_city,
        county: proj?.client_county, pc: proj?.client_postcode,
        contact: proj?.client_contact_name, phone: proj?.client_contact_phone,
        email: proj?.client_contact_email };
  return {
    source:   useSite ? 'project-site' : 'client',
    siteName: proj?.name || proj?.project_name || '',
    lines: [a.l1, a.l2, [a.city, a.county].filter(Boolean).join(', '), a.pc].filter(Boolean),
    contact: a.contact || '',
    phone:   a.phone   || '',
    email:   a.email   || '',
    po:      proj?.client_po_number || ''
  };
}

function _jsSetVal(id, v) {
  const el = document.getElementById(id);
  if (el) el.value = (v == null ? '' : v);
}

// Every field id in the modal — cleared wholesale on open so nothing from
// a previously viewed project can bleed through.
const _JS_ALL_FIELD_IDS = [
  'jsSiteName', 'jsAddr1', 'jsAddr2', 'jsCity', 'jsCounty', 'jsPostcode',
  'jsComName', 'jsComPhone', 'jsComEmail',
  'jsPmName', 'jsPmPhone', 'jsPmEmail',
  'jsSmName', 'jsSmPhone', 'jsSmEmail',
  'jsPo', 'jsNotes',
  'jsRevLabel', 'jsRevDesc', 'jsRevFab', 'jsRevDesign', 'jsRevOps', 'jsRevDays'
];

function _jsResetModal() {
  _JS_ALL_FIELD_IDS.forEach(id => _jsSetVal(id, ''));
  const lbl = document.getElementById('jsRevLabel');
  if (lbl) lbl.placeholder = 'Base quote';
  ['jsComSelect', 'jsPmSelect', 'jsSmSelect'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.innerHTML = '<option value="">\u2014 loading client contacts\u2026 \u2014</option>';
  });
  const loading = `<div style="color:var(--subtle);font-size:12px">Loading\u2026</div>`;
  ['jsQuoteStrip', 'jsRevList', 'jsJobStats'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.innerHTML = loading;
  });
  const qBtn = document.getElementById('jsQuoteAddrBtn'); if (qBtn) qBtn.style.display = 'none';
  const sBtn = document.getElementById('jsSeedBaseBtn');  if (sBtn) sBtn.style.display = 'none';
}

async function openJobSheetModal() {
  if (!currentProject?.dbId) { toast('No project selected.', 'error'); return; }
  const projId = parseInt(currentProject.dbId);

  // Wipe the modal FIRST — the DOM persists between projects, so anything
  // not overwritten below would otherwise leak from the last project viewed.
  _jsResetModal();

  const editable = isDraftsman;
  document.querySelectorAll('#jobSheetModal .js-field').forEach(el => { el.disabled = !editable; });
  const saveBtn = document.getElementById('jsSaveBtn');
  if (saveBtn) saveBtn.style.display = editable ? '' : 'none';
  const prefillRow = document.getElementById('jsPrefillRow');
  if (prefillRow) prefillRow.style.display = editable ? 'flex' : 'none';

  document.getElementById('jobSheetModal').classList.add('active');

  // Kick everything for THIS project in parallel. loadJobSheet is awaited
  // (it decides saved-vs-prefill); the extras also gate the auto prefill
  // because the QB quotation is an address source.
  const contactsP = _jsLoadClientContacts();     // dropdowns per this project's CLIENT
  const revsP     = _jsLoadRevisions();
  const [sheet]   = await Promise.all([loadJobSheet(projId), _jsLoadExtras()]);
  const js = (sheet && sheet.project_id === projId) ? sheet : null;

  if (js) {
    _jsSetVal('jsSiteName',   js.site_name);
    _jsSetVal('jsAddr1',      js.address_line1);
    _jsSetVal('jsAddr2',      js.address_line2);
    _jsSetVal('jsCity',       js.city);
    _jsSetVal('jsCounty',     js.county);
    _jsSetVal('jsPostcode',   js.postcode);
    _jsSetVal('jsComName',    js.commercial_name);
    _jsSetVal('jsComPhone',   js.commercial_phone);
    _jsSetVal('jsComEmail',   js.commercial_email);
    _jsSetVal('jsPmName',     js.pm_name);
    _jsSetVal('jsPmPhone',    js.pm_phone);
    _jsSetVal('jsPmEmail',    js.pm_email);
    _jsSetVal('jsSmName',     js.site_manager_name);
    _jsSetVal('jsSmPhone',    js.site_manager_phone);
    _jsSetVal('jsSmEmail',    js.site_manager_email);
    _jsSetVal('jsBamaName',   js.bama_contact_name);
    _jsSetVal('jsBamaPhone',  js.bama_contact_phone);
    _jsSetVal('jsPo',         js.client_po_number);
    _jsSetVal('jsNotes',      js.notes);
  } else {
    jobSheetPrefill('auto');   // seed a fresh sheet (site \u2192 quotation \u2192 client)
  }

  const hint = document.getElementById('jsSourceHint');
  if (hint) {
    hint.textContent = js
      ? `Saved${js.updated_at ? ' ' + new Date(js.updated_at).toLocaleDateString('en-GB') : ''}${js.updated_by ? ' by ' + js.updated_by : ''} \u2014 SDN / Site Pack / RAMS prefill from this sheet.`
      : 'Not saved yet \u2014 prefilled automatically. Save to make this the default source for SDN / Site Pack / RAMS on every job in this project.';
  }
  await Promise.allSettled([contactsP, revsP]);
}

// mode: 'auto' (project site if set, else client) | 'site' | 'client'.
// The two explicit modes back the "Use project site" / "Use client
// address" buttons in the modal, so switching source is one click —
// everything stays editable afterwards.
function jobSheetPrefill(mode) {
  const proj = currentProject || {};
  const site = { l1: proj.site_address_line1, l2: proj.site_address_line2, city: proj.site_city,
                 county: proj.site_county, pc: proj.site_postcode,
                 contact: proj.site_contact_name, phone: proj.site_contact_phone,
                 email: proj.site_contact_email };
  const client = { l1: proj.client_address_line1, l2: proj.client_address_line2, city: proj.client_city,
                   county: proj.client_county, pc: proj.client_postcode,
                   contact: proj.client_contact_name, phone: proj.client_contact_phone,
                   email: proj.client_contact_email };
  // 'quote' mode drops the QB quotation's single-line site address into
  // line 1 — the quotation usually has the site address tucked away, so
  // this surfaces it with one click. Other fields keep their values.
  if (mode === 'quote') {
    const qa = String(_jsExtras?.quote?.site_address || _jsExtras?.quote?.json_site_address || '').trim();
    if (!qa) { toast('No site address on the quotation.', 'error'); return; }
    const parts = qa.split(',').map(s => s.trim()).filter(Boolean);
    _jsSetVal('jsAddr1',    parts[0] || qa);
    _jsSetVal('jsAddr2',    parts.length > 2 ? parts.slice(1, -1).join(', ') : (parts[1] || ''));
    _jsSetVal('jsPostcode', parts.length > 1 ? parts[parts.length - 1] : '');
    return;
  }
  // Auto priority: project site address \u2192 QB quotation site address \u2192
  // client head office (last resort, and never written back to the client).
  const quoteAddr = String(_jsExtras?.quote?.site_address || _jsExtras?.quote?.json_site_address || '').trim();
  if (mode === 'auto' &&
      !(proj.site_same_as_client === false && (proj.site_address_line1 || proj.site_postcode)) &&
      quoteAddr) {
    _jsSetVal('jsSiteName', proj.name || proj.project_name || '');
    const parts = quoteAddr.split(',').map(s => s.trim()).filter(Boolean);
    _jsSetVal('jsAddr1',    parts[0] || quoteAddr);
    _jsSetVal('jsAddr2',    parts.length > 2 ? parts.slice(1, -1).join(', ') : (parts[1] || ''));
    _jsSetVal('jsPostcode', parts.length > 1 ? parts[parts.length - 1] : '');
    _jsSetVal('jsCity', ''); _jsSetVal('jsCounty', '');
    // Contacts: seed the Site Manager from the project's site contact if
    // one exists; otherwise leave the roles for the dropdowns.
    _jsSetVal('jsSmName',  proj.site_contact_name || '');
    _jsSetVal('jsSmPhone', proj.site_contact_phone || '');
    _jsSetVal('jsSmEmail', proj.site_contact_email || '');
    _jsSetVal('jsPo',      proj.client_po_number || '');
    return;
  }
  let a;
  if (mode === 'site')        a = site;
  else if (mode === 'client') a = client;
  else a = (proj.site_same_as_client === false && (proj.site_address_line1 || proj.site_postcode))
    ? site : client;

  _jsSetVal('jsSiteName', proj.name || proj.project_name || '');
  _jsSetVal('jsAddr1',    a.l1);
  _jsSetVal('jsAddr2',    a.l2);
  _jsSetVal('jsCity',     a.city);
  _jsSetVal('jsCounty',   a.county);
  _jsSetVal('jsPostcode', a.pc);
  // Seed the Site Manager from the resolved contact; Commercial / PM are
  // picked from the client-contact dropdowns (or typed) by the user.
  _jsSetVal('jsSmName',   a.contact);
  _jsSetVal('jsSmPhone',  a.phone);
  _jsSetVal('jsSmEmail',  a.email);
  _jsSetVal('jsPo',       proj.client_po_number || '');
}

// ── Client-contact dropdowns (same source as QB: ClientContacts) ──
let _jsClientContacts = [];        // contacts of the current project's client
let _jsClientContactsClientId = null;

async function _jsLoadClientContacts() {
  const clientId = currentProject?.clientId ? parseInt(currentProject.clientId) : null;
  if (!clientId) {
    _jsClientContacts = []; _jsClientContactsClientId = null;
    _jsPopulateContactSelects(); return;
  }
  if (_jsClientContactsClientId !== clientId) {
    _jsClientContacts = [];
    _jsClientContactsClientId = clientId;
    try {
      const rows = await api.get(`/api/client-contacts?client_id=${clientId}`);
      _jsClientContacts = Array.isArray(rows) ? rows : [];
    } catch (e) { _jsClientContacts = []; }
    // Someone may have switched project while we were fetching — only
    // render if this response still belongs to the current client.
    if (_jsClientContactsClientId !== clientId) return;
  }
  _jsPopulateContactSelects();
}

function _jsPopulateContactSelects() {
  const opts = ['<option value="">\u2014 pick from client database \u2014</option>']
    .concat(_jsClientContacts.map((c, i) => {
      const label = [c.contact_name, c.role].filter(Boolean).join(' \u00b7 ');
      return `<option value="${i}">${escapeHtml(label || '(unnamed)')}</option>`;
    })).join('');
  ['jsComSelect', 'jsPmSelect', 'jsSmSelect'].forEach(id => {
    const el = document.getElementById(id);
    if (el) { el.innerHTML = opts; el.value = ''; }
  });
}

// onchange handler for the three dropdowns — fills the editable fields.
// role suffix: 'Com' | 'Pm' | 'Sm'
function jsContactPick(role) {
  const sel = document.getElementById(`js${role}Select`);
  const c = _jsClientContacts[parseInt(sel?.value)];
  if (!c) return;
  _jsSetVal(`js${role}Name`,  c.contact_name);
  _jsSetVal(`js${role}Phone`, c.contact_phone);
  _jsSetVal(`js${role}Email`, c.contact_email);
}

// Save any newly typed contact into the client database so it appears in
// every contact dropdown (Job Sheet, QB, tenders) from now on. Matching is
// by name, case-insensitive; existing contacts are never modified.
async function _jsSyncContactsToClientDb(body) {
  const clientId = currentProject?.clientId ? parseInt(currentProject.clientId) : null;
  if (!clientId) return;
  const roles = [
    { name: body.commercial_name,   phone: body.commercial_phone,   email: body.commercial_email,   role: 'Commercial' },
    { name: body.pm_name,           phone: body.pm_phone,           email: body.pm_email,           role: 'Project Manager' },
    { name: body.site_manager_name, phone: body.site_manager_phone, email: body.site_manager_email, role: 'Site Manager' }
  ];
  const existing = new Set(_jsClientContacts.map(c => String(c.contact_name || '').trim().toLowerCase()).filter(Boolean));
  let added = false;
  for (const r of roles) {
    const nm = String(r.name || '').trim();
    if (!nm || existing.has(nm.toLowerCase())) continue;
    existing.add(nm.toLowerCase());
    try {
      const row = await api.post('/api/client-contacts', {
        client_id:     clientId,
        contact_name:  nm,
        contact_phone: r.phone || '',
        contact_email: r.email || '',
        role:          r.role
      });
      if (row) { _jsClientContacts.push(row); added = true; }
    } catch (e) { console.warn('Client-contact sync failed (non-fatal):', e.message); }
  }
  if (added) _jsPopulateContactSelects();
}

// ── Quotation figures + per-job tonnage (read-only, from QB & assemblies) ──
let _jsExtras = null;             // { quote, jobs } for the current project
let _jsExtrasProjId = null;

async function _jsLoadExtras() {
  const pid = currentProject?.dbId ? parseInt(currentProject.dbId) : null;
  if (!pid) { _jsExtras = null; _jsRenderExtras(); return; }
  if (_jsExtrasProjId !== pid) {
    _jsExtras = null; _jsExtrasProjId = pid;
    try { _jsExtras = await api.get(`/api/project-sheet/${pid}/extras`); }
    catch (e) { _jsExtras = null; }
  }
  _jsRenderExtras();
}

const _jsNum = v => { const n = parseFloat(v); return isFinite(n) ? n : 0; };
const _jsFmtT = kg => (kg >= 1000 ? (kg / 1000).toFixed(2) + ' t' : Math.round(kg) + ' kg');

function _jsRenderExtras() {
  const q = _jsExtras?.quote || null;
  const qEl = document.getElementById('jsQuoteStrip');
  if (qEl) {
    if (q) {
      const chips = [
        { l: q.source === 'tracker' ? 'Quote (Project Tracker)' : 'Quote',
          v: `${q.reference || '\u2014'}${q.revision ? ' rev ' + q.revision : ''}` },
        { l: 'Fab hours', v: _jsNum(q.fab_hours) ? _jsNum(q.fab_hours) + ' hrs' : null },
        { l: 'Design hours', v: _jsNum(q.design_hours) ? _jsNum(q.design_hours) + ' hrs' : null },
        { l: 'Site crew', v: _jsNum(q.inst_operatives)
            ? `${_jsNum(q.inst_operatives)} operative${_jsNum(q.inst_operatives) !== 1 ? 's' : ''}${_jsNum(q.inst_days) ? ' \u00d7 ' + _jsNum(q.inst_days) + ' day' + (_jsNum(q.inst_days) !== 1 ? 's' : '') : ''}` : null },
        { l: 'Quoted tonnage', v: _jsNum(q.total_kg) ? _jsFmtT(_jsNum(q.total_kg)) : null },
        { l: 'Quote value', v: (q.quote_value != null && _jsNum(q.quote_value))
            ? '\u00a3' + Number(q.quote_value).toLocaleString('en-GB', { maximumFractionDigits: 0 }) : null }
      ].filter(c => c.v);
      qEl.innerHTML = chips.map(c =>
        `<div style="background:var(--bg-darker);border:1px solid var(--border);border-radius:8px;padding:8px 12px">
           <div style="font-size:9px;color:var(--subtle);text-transform:uppercase;letter-spacing:.05em">${c.l}</div>
           <div style="font-size:13px;color:var(--text);font-weight:600;margin-top:2px">${escapeHtml(String(c.v))}</div>
         </div>`).join('');
    } else {
      qEl.innerHTML = `<div style="color:var(--subtle);font-size:12px">No QB quotation linked to this project.</div>`;
    }
  }
  const quoteBtn = document.getElementById('jsQuoteAddrBtn');
  if (quoteBtn) quoteBtn.style.display =
    (q && String(q.site_address || q.json_site_address || '').trim()) ? '' : 'none';
  const seedBtn = document.getElementById('jsSeedBaseBtn');
  if (seedBtn) seedBtn.style.display =
    (q && isDraftsman && !(_jsRevisions || []).some(r => /^base/i.test(r.label))) ? '' : 'none';

  // Per-job fabrication stats (members + tonnage)
  const jEl = document.getElementById('jsJobStats');
  if (jEl) {
    const jobs = _jsExtras?.jobs || [];
    if (!jobs.length) {
      jEl.innerHTML = `<div style="color:var(--subtle);font-size:12px">No jobs yet.</div>`;
    } else {
      let members = 0, kg = 0;
      const rows = jobs.map(j => {
        members += _jsNum(j.members); kg += _jsNum(j.weight_kg);
        return `<tr>
          <td style="padding:5px 8px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text)">${escapeHtml(j.job_name || ('Job ' + j.job_id))}</td>
          <td style="padding:5px 8px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text);text-align:right">${_jsNum(j.assembly_marks)}</td>
          <td style="padding:5px 8px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text);text-align:right">${_jsNum(j.members)}</td>
          <td style="padding:5px 8px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text);text-align:right;font-family:var(--font-mono)">${_jsFmtT(_jsNum(j.weight_kg))}</td>
        </tr>`;
      }).join('');
      jEl.innerHTML = `<table style="width:100%;border-collapse:collapse">
        <thead><tr>
          <th style="padding:5px 8px;text-align:left;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Job</th>
          <th style="padding:5px 8px;text-align:right;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Marks</th>
          <th style="padding:5px 8px;text-align:right;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Members</th>
          <th style="padding:5px 8px;text-align:right;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Weight</th>
        </tr></thead>
        <tbody>${rows}</tbody>
        <tfoot><tr>
          <td style="padding:6px 8px;font-size:12px;font-weight:700;color:var(--text)">Total</td><td></td>
          <td style="padding:6px 8px;font-size:12px;font-weight:700;color:var(--text);text-align:right">${members}</td>
          <td style="padding:6px 8px;font-size:12px;font-weight:700;color:var(--accent);text-align:right;font-family:var(--font-mono)">${_jsFmtT(kg)}</td>
        </tr></tfoot>
      </table>`;
    }
  }

  // Populate the revision "job" dropdown from the same stats list
  const jobSel = document.getElementById('jsRevJob');
  if (jobSel) {
    const jobs = _jsExtras?.jobs || [];
    jobSel.innerHTML = `<option value="">Whole project</option>` +
      jobs.map(j => `<option value="${j.job_id}">${escapeHtml(j.job_name || ('Job ' + j.job_id))}</option>`).join('');
  }
}

// ── Revision / VO ledger — what hours were put to which job ──
let _jsRevisions = null;
let _jsRevisionsProjId = null;

async function _jsLoadRevisions(force) {
  const pid = currentProject?.dbId ? parseInt(currentProject.dbId) : null;
  if (!pid) { _jsRevisions = []; _jsRenderRevisions(); return; }
  if (force || _jsRevisionsProjId !== pid) {
    _jsRevisions = []; _jsRevisionsProjId = pid;
    try {
      const rows = await api.get(`/api/project-sheet/${pid}/revisions`);
      _jsRevisions = Array.isArray(rows) ? rows : [];
    } catch (e) { _jsRevisions = []; }
  }
  _jsRenderRevisions();
}

function _jsRenderRevisions() {
  const el = document.getElementById('jsRevList');
  if (!el) return;
  const revs = _jsRevisions || [];
  if (!revs.length) {
    el.innerHTML = `<div style="color:var(--subtle);font-size:12px;padding:6px 0">No revisions yet \u2014 add the base quote hours, then a row per VO.</div>`;
  } else {
    let tf = 0, td = 0;
    const rows = revs.map(r => {
      tf += _jsNum(r.fab_hours); td += _jsNum(r.design_hours);
      const site = _jsNum(r.site_operatives)
        ? `${_jsNum(r.site_operatives)}\u00d7${_jsNum(r.site_days) || '?'}d` : '\u2014';
      const del = isDraftsman
        ? `<button class="btn" onclick="jsDeleteRevision(${r.id})" title="Delete"
              style="padding:2px 8px;font-size:11px;background:rgba(255,68,68,.1);border:1px solid rgba(255,68,68,.3);color:var(--red)">&#128465;</button>`
        : '';
      return `<tr>
        <td style="padding:5px 8px;border-bottom:1px solid var(--border);font-size:12px;font-weight:600;color:var(--accent)">${escapeHtml(r.label)}</td>
        <td style="padding:5px 8px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text)">${escapeHtml(r.job_name || (r.job_id ? 'Job ' + r.job_id : 'Whole project'))}</td>
        <td style="padding:5px 8px;border-bottom:1px solid var(--border);font-size:11px;color:var(--muted)">${escapeHtml(r.description || '')}</td>
        <td style="padding:5px 8px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text);text-align:right">${_jsNum(r.fab_hours) || '\u2014'}</td>
        <td style="padding:5px 8px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text);text-align:right">${_jsNum(r.design_hours) || '\u2014'}</td>
        <td style="padding:5px 8px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text);text-align:right">${site}</td>
        <td style="padding:5px 8px;border-bottom:1px solid var(--border);text-align:right">${del}</td>
      </tr>`;
    }).join('');
    el.innerHTML = `<table style="width:100%;border-collapse:collapse">
      <thead><tr>
        <th style="padding:5px 8px;text-align:left;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Rev</th>
        <th style="padding:5px 8px;text-align:left;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Job</th>
        <th style="padding:5px 8px;text-align:left;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Description</th>
        <th style="padding:5px 8px;text-align:right;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Fab hrs</th>
        <th style="padding:5px 8px;text-align:right;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Design hrs</th>
        <th style="padding:5px 8px;text-align:right;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Site</th>
        <th></th>
      </tr></thead>
      <tbody>${rows}</tbody>
      <tfoot><tr>
        <td style="padding:6px 8px;font-size:12px;font-weight:700;color:var(--text)" colspan="3">Total</td>
        <td style="padding:6px 8px;font-size:12px;font-weight:700;color:var(--accent);text-align:right">${tf || '\u2014'}</td>
        <td style="padding:6px 8px;font-size:12px;font-weight:700;color:var(--accent);text-align:right">${td || '\u2014'}</td>
        <td></td><td></td>
      </tr></tfoot>
    </table>`;
  }
  // Suggest the next label: 'Base quote' first, then VO1, VO2, ...
  const labelEl = document.getElementById('jsRevLabel');
  if (labelEl && !labelEl.value) {
    labelEl.placeholder = revs.length === 0 ? 'Base quote'
      : `VO${revs.filter(r => !/^base/i.test(r.label)).length + 1}`;
  }
  // Add-row + seed visibility follows draftsman mode
  const addRow = document.getElementById('jsRevAddRow');
  if (addRow) addRow.style.display = isDraftsman ? '' : 'none';
}

// Prefill the add-row from the QB quotation (base quote seeding).
function jsSeedBaseFromQuote() {
  const q = _jsExtras?.quote;
  if (!q) return;
  _jsSetVal('jsRevLabel', 'Base quote');
  _jsSetVal('jsRevDesc',  `As quoted ${q.reference}${q.revision ? ' rev ' + q.revision : ''}`);
  _jsSetVal('jsRevFab',   _jsNum(q.fab_hours) || '');
  _jsSetVal('jsRevDesign', _jsNum(q.design_hours) || '');
  _jsSetVal('jsRevOps',   _jsNum(q.inst_operatives) || '');
  _jsSetVal('jsRevDays',  _jsNum(q.inst_days) || '');
}

async function jsAddRevision() {
  if (!currentProject?.dbId) return;
  const v = id => (document.getElementById(id)?.value || '').trim();
  const label = v('jsRevLabel') || document.getElementById('jsRevLabel')?.placeholder || '';
  if (!label) { toast('Give the revision a label (e.g. VO1).', 'error'); return; }
  const btn = document.getElementById('jsRevAddBtn');
  try {
    if (btn) btn.disabled = true;
    const row = await api.post(`/api/project-sheet/${parseInt(currentProject.dbId)}/revisions`, {
      label,
      job_id:          v('jsRevJob') || null,
      description:     v('jsRevDesc') || null,
      fab_hours:       v('jsRevFab') || null,
      design_hours:    v('jsRevDesign') || null,
      site_operatives: v('jsRevOps') || null,
      site_days:       v('jsRevDays') || null,
      created_by:      _currentDraftsmanName || null
    });
    if (row) {
      ['jsRevLabel', 'jsRevDesc', 'jsRevFab', 'jsRevDesign', 'jsRevOps', 'jsRevDays']
        .forEach(id => _jsSetVal(id, ''));
      await _jsLoadRevisions(true);
      _jsRenderExtras();   // seed-button visibility may change
      toast(`${row.label} added.`, 'success');
    }
  } catch (e) {
    toast('Failed to add revision: ' + (e.message || e), 'error');
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function jsDeleteRevision(id) {
  const rev = (_jsRevisions || []).find(r => r.id === id);
  const okGo = (typeof bamaConfirm === 'function')
    ? await bamaConfirm({
        title: 'Delete revision',
        body: `Delete ${rev ? rev.label : 'this revision'} from the ledger?`,
        confirmText: 'Delete', tone: 'danger'
      })
    : confirm('Delete this revision?');
  if (!okGo) return;
  try {
    await api.delete(`/api/project-sheet-revisions/${id}`);
    await _jsLoadRevisions(true);
    _jsRenderExtras();
    toast('Revision deleted.', 'success');
  } catch (e) {
    toast('Failed to delete revision: ' + (e.message || e), 'error');
  }
}

function closeJobSheetModal() {
  document.getElementById('jobSheetModal').classList.remove('active');
}

// ── Job Sheet PDF — native jsPDF, no html2canvas (per CLAUDE.md) ──
// Reads the CURRENT modal fields (so unsaved edits print too) and opens
// the PDF in a new tab. Follows drawDnPDF conventions: letterhead with
// real logo proportions, null-field filtering, splitTextToSize wrapping,
// "Page X of Y" footer, blob-size diagnostic.
async function generateJobSheetPdf() {
  if (!currentProject) return;
  const btn = document.getElementById('jsPdfBtn');
  try {
    if (btn) { btn.disabled = true; btn.textContent = 'Generating\u2026'; }
    await loadLogoDataUri();
    const JsPDFCtor = await resolveJsPDFCtor();
    if (!JsPDFCtor) throw new Error('PDF library failed to load');
    const v = id => (document.getElementById(id)?.value || '').trim();
    const sheet = {
      site_name: v('jsSiteName'),
      addrLines: [v('jsAddr1'), v('jsAddr2'),
                  [v('jsCity'), v('jsCounty')].filter(Boolean).join(', '),
                  v('jsPostcode')].filter(Boolean),
      contacts: [
        { role: 'Commercial',      name: v('jsComName'), phone: v('jsComPhone'), email: v('jsComEmail') },
        { role: 'Project Manager', name: v('jsPmName'),  phone: v('jsPmPhone'),  email: v('jsPmEmail')  },
        { role: 'Site Manager',    name: v('jsSmName'),  phone: v('jsSmPhone'),  email: v('jsSmEmail')  },
        { role: 'BAMA Site Contact', name: v('jsBamaName'), phone: v('jsBamaPhone'), email: '' }
      ].filter(c => c.name || c.phone || c.email),
      clientPo: v('jsPo'),
      notes:    v('jsNotes'),
      quote:     _jsExtras?.quote || null,
      jobStats:  _jsExtras?.jobs  || [],
      revisions: _jsRevisions     || []
    };
    const logo = (typeof _logoDataUriCache !== 'undefined' && _logoDataUriCache) || '';
    const blob = drawJobSheetPDF(JsPDFCtor, sheet, currentProject, logo);
    console.log('[Job Sheet PDF] blob size:', blob.size, 'bytes (native jsPDF)');
    if (blob.size < 8 * 1024) console.warn('[Job Sheet PDF] blob under 8KB \u2014 possible blank render');

    // Save into the project folder on SharePoint (root of the project
    // folder — the sheet is project-level, not job-level). Regenerating
    // overwrites the same file, so the folder always holds the latest.
    let opened = false;
    try {
      const projectFolder = await findProjectFolder(currentProject.id);
      if (projectFolder) {
        const driveId = projectFolder.parentReference?.driveId || BAMA_DRIVE_ID;
        const fileName = `Job Sheet - ${currentProject.id}.pdf`;
        const token = await getToken();
        const upUrl = `https://graph.microsoft.com/v1.0/drives/${driveId}/items/${projectFolder.id}:/${encodeURIComponent(fileName)}:/content`;
        const upRes = await fetch(upUrl, {
          method: 'PUT',
          headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/pdf' },
          body: blob
        });
        if (upRes.ok) {
          const uploaded = await upRes.json();
          toast(`Job Sheet saved to the project folder as ${fileName}.`, 'success');
          if (uploaded.webUrl) { window.open(uploaded.webUrl, '_blank'); opened = true; }
        } else {
          console.warn('[Job Sheet PDF] SharePoint upload failed:', upRes.status);
        }
      }
    } catch (e) {
      console.warn('[Job Sheet PDF] SharePoint upload failed (non-fatal):', e.message);
    }
    if (!opened) {
      // Upload unavailable — still hand the PDF to the user in a new tab.
      window.open(URL.createObjectURL(blob), '_blank');
      toast('Could not reach SharePoint \u2014 PDF opened in a new tab instead.', 'error');
    }
  } catch (e) {
    toast('Job Sheet PDF failed: ' + (e.message || e), 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = '\uD83D\uDDA8 Generate PDF'; }
  }
}

function drawJobSheetPDF(jsPDF, sheet, proj, logoDataUri) {
  const s = (typeof _pickTplSettings === 'function') ? _pickTplSettings() : null;
  const g = (s && s.global) || (typeof TEMPLATE_DEFAULTS !== 'undefined' ? TEMPLATE_DEFAULTS.global
    : { companyName: 'BAMA FABRICATION', address: '', phone: '', email: '', vatNumber: '' });
  const accent = (typeof hexToRgb === 'function' && hexToRgb('#ff6b00')) || [255, 107, 0];

  const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  try {
    doc.setProperties({
      title: `Job Sheet \u2014 ${proj?.id || ''}`,
      subject: `Job Sheet${proj?.name ? ' \u2014 ' + proj.name : ''}`,
      author: 'BAMA Fabrication', creator: 'BAMA Fabrication ERP'
    });
  } catch (e) { /* non-critical */ }

  const pageW = 210, pageH = 297, marginL = 14, marginR = 14, marginB = 16;
  const usableW = pageW - marginL - marginR;
  const TEXT = [30, 30, 30], MUTED = [100, 100, 100], RULE = [205, 205, 205],
        DARKRULE = [120, 120, 120], HEADFILL = [242, 242, 242], ZEBRA = [249, 249, 249];
  const setText = c => doc.setTextColor(c[0], c[1], c[2]);
  const setFill = c => doc.setFillColor(c[0], c[1], c[2]);
  const setDraw = c => doc.setDrawColor(c[0], c[1], c[2]);

  // ── Letterhead: logo (left) + company details to the RIGHT of the logo
  //    (mirrors the Site Pack band) + title/meta far right. ──
  let y = marginL;
  let logoW = 0, logoBottom = y;
  if (logoDataUri) {
    try {
      const RENDER_W = 45;
      const props = doc.getImageProperties(logoDataUri);
      const ratio = (props && props.width && props.height) ? (props.width / props.height) : (55 / 24);
      doc.addImage(logoDataUri, props.fileType || 'PNG', marginL, y, RENDER_W, RENDER_W / ratio, undefined, 'FAST');
      logoW = RENDER_W; logoBottom = y + RENDER_W / ratio;
    } catch (e) { logoW = 0; }
  }
  if (!logoW) {
    doc.setFont('helvetica', 'bold'); doc.setFontSize(18); setText(accent);
    doc.text(g.companyName || 'BAMA FABRICATION', marginL, y + 8);
    logoW = doc.getTextWidth(g.companyName || 'BAMA FABRICATION');
    logoBottom = y + 10;
  }
  // Company details beside the logo — condenses the whole band.
  const coX = marginL + logoW + 8;
  let coY = y + 3;
  setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
  const coLines = [];
  if (g.address) String(g.address).split('\n').forEach(l => coLines.push(l));
  if (g.phone) coLines.push('Tel: ' + g.phone);
  if (g.email) coLines.push(g.email);
  if (g.vatNumber) coLines.push('VAT: ' + g.vatNumber);
  coLines.forEach(l => { doc.text(String(l), coX, coY); coY += 3.6; });
  const leftY = Math.max(logoBottom, coY - 3.6) + 4;

  doc.setFont('helvetica', 'bolditalic'); doc.setFontSize(20); setText(accent);
  doc.text('Job Sheet', pageW - marginR, y + 8, { align: 'right' });

  let rightY = y + 16;
  const fmtDate = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
  const metaRows = [
    { label: 'Project No:', value: proj?.id },
    { label: 'Project:',    value: proj?.name },
    { label: 'Client:',     value: proj?.client },
    { label: 'Client PO:',  value: sheet.clientPo },
    { label: 'Date:',       value: fmtDate }
  ].filter(r => r.value != null && String(r.value).trim() !== '');
  doc.setFontSize(9);
  for (const r of metaRows) {
    setText(TEXT); doc.setFont('helvetica', 'bold');
    doc.text(r.label, pageW - marginR - 42, rightY, { align: 'right' });
    doc.setFont('helvetica', 'normal');
    const vLines = doc.splitTextToSize(String(r.value || ''), 40);
    doc.text(vLines[0] || '', pageW - marginR, rightY, { align: 'right' });
    rightY += 4.4 * Math.max(1, vLines.length);
  }

  y = Math.max(leftY, rightY) + 6;
  setDraw(accent); doc.setLineWidth(1.0);
  doc.line(marginL, y, pageW - marginR, y);
  y += 9;

  // ── Layout helpers ──
  const pageBreakIfNeeded = (needed) => {
    if (y + needed > pageH - marginB - 8) { doc.addPage(); y = marginL + 6; }
  };
  // Section header: accent bar + tinted band, generous whitespace above.
  const sectionHead = (label) => {
    pageBreakIfNeeded(26);
    setFill(accent);
    doc.rect(marginL, y - 4.8, 1.8, 7.6, 'F');
    setFill(HEADFILL);
    doc.rect(marginL + 1.8, y - 4.8, usableW - 1.8, 7.6, 'F');
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
    doc.text(label.toUpperCase(), marginL + 5, y);
    y += 9;
  };
  const cellX = (c) => c.align === 'right' ? c.x + c.w : c.x;
  const cellOpt = (c) => c.align === 'right' ? { align: 'right' } : undefined;
  // Table: filled header band, zebra rows, ruled totals. Page-break aware.
  const drawTable = (cols, rows, foot) => {
    const header = () => {
      setFill(HEADFILL);
      doc.rect(marginL, y - 3.6, usableW, 6, 'F');
      setText(MUTED); doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
      cols.forEach(c => doc.text(c.label.toUpperCase(), cellX(c), y, cellOpt(c)));
      y += 3.4;
      setDraw(DARKRULE); doc.setLineWidth(0.35);
      doc.line(marginL, y, pageW - marginR, y);
      y += 4.6;
    };
    header();
    doc.setFontSize(9.5);
    rows.forEach((cells, idx) => {
      setText(TEXT); doc.setFont('helvetica', 'normal');
      let rowH = 5;
      const wrapped = cells.map((v, i) => {
        const w = doc.splitTextToSize(String(v == null ? '' : v), cols[i].w);
        rowH = Math.max(rowH, w.length * 4.4 + 1);
        return w;
      });
      if (y + rowH > pageH - marginB - 8) {
        doc.addPage(); y = marginL + 6; header();
        setText(TEXT); doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5);
      }
      if (idx % 2 === 1) {  // zebra shading on alternate rows
        setFill(ZEBRA);
        doc.rect(marginL, y - 3.4, usableW, rowH + 1.2, 'F');
        setText(TEXT);
      }
      wrapped.forEach((w, i) => doc.text(w, cellX(cols[i]), y + 1, cellOpt(cols[i])));
      y += rowH + 1.8;
      setDraw(RULE); doc.setLineWidth(0.15);
      doc.line(marginL, y - 1.2, pageW - marginR, y - 1.2);
    });
    if (foot) {
      pageBreakIfNeeded(9);
      setDraw(DARKRULE); doc.setLineWidth(0.45);
      doc.line(marginL, y - 1.2, pageW - marginR, y - 1.2);
      doc.setFont('helvetica', 'bold'); doc.setFontSize(9.5);
      foot.forEach((v, i) => {
        if (v == null || String(v) === '') return;
        setText(i === 0 ? TEXT : accent);
        doc.text(String(v), cellX(cols[i]), y + 2, cellOpt(cols[i]));
      });
      y += 7.5;
      doc.setFont('helvetica', 'normal'); setText(TEXT);
    }
  };
  const numOr = (v, suffix) => { const n = parseFloat(v); return isFinite(n) && n > 0 ? n + (suffix || '') : '\u2014'; };
  const _hasNum = v => { const n = parseFloat(v); return isFinite(n) && n > 0; };
  const fmtT = kg => (kg >= 1000 ? (kg / 1000).toFixed(2) + ' t' : Math.round(kg) + ' kg');

  // ── Site address ──
  sectionHead('Site address');
  if (sheet.site_name) {
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
    const nm = doc.splitTextToSize(sheet.site_name, usableW - 8);
    nm.forEach(w => { doc.text(w, marginL + 5, y + 1); y += 5.4; });
    doc.setFont('helvetica', 'normal');
  }
  doc.setFontSize(10); setText(TEXT);
  const addrLines = (sheet.addrLines && sheet.addrLines.length) ? sheet.addrLines : ['\u2014'];
  for (const line of addrLines) {
    const wrapped = doc.splitTextToSize(String(line), usableW - 8);
    wrapped.forEach(w => { doc.text(w, marginL + 5, y + 1); y += 5; });
  }
  y += 7;

  // ── Contacts ──
  sectionHead('Contacts');
  const contacts = (sheet.contacts && sheet.contacts.length)
    ? sheet.contacts : [{ role: '\u2014', name: '', phone: '', email: '' }];
  drawTable([
    { label: 'Role',  x: marginL + 5,   w: 30 },
    { label: 'Name',  x: marginL + 38,  w: 42 },
    { label: 'Phone', x: marginL + 84,  w: 28 },
    { label: 'Email', x: marginL + 116, w: usableW - 116 - 3 }
  ], contacts.map(c => [c.role, c.name, c.phone, c.email]));
  y += 5;

  // ── Quoted figures (from the QB quotation, if linked) ──
  if (sheet.quote) {
    const q = sheet.quote;
    sectionHead(`Quoted \u2014 ${q.reference}${q.revision ? ' rev ' + q.revision : ''}`);
    const ops = parseFloat(q.inst_operatives), days = parseFloat(q.inst_days);
    const crew = (isFinite(ops) && ops > 0)
      ? `${ops} op${ops !== 1 ? 's' : ''}${(isFinite(days) && days > 0) ? ' \u00d7 ' + days + ' day' + (days !== 1 ? 's' : '') : ''}`
      : '\u2014';
    const qkg = parseFloat(q.total_kg);
    const qval = parseFloat(q.quote_value);
    // Stat cells across the width — label above, bold value below. Only
    // figures the quote actually carries are rendered (a Project Tracker
    // quote has ref + value but no hours; a QB quote has hours + tonnage).
    const stats = [
      { l: 'FAB HOURS',      v: numOr(q.fab_hours, ' hrs'), has: _hasNum(q.fab_hours) },
      { l: 'DESIGN HOURS',   v: numOr(q.design_hours, ' hrs'), has: _hasNum(q.design_hours) },
      { l: 'SITE CREW',      v: crew, has: crew !== '\u2014' },
      { l: 'QUOTED TONNAGE', v: (isFinite(qkg) && qkg > 0) ? fmtT(qkg) : '\u2014', has: isFinite(qkg) && qkg > 0 },
      { l: 'QUOTE VALUE',    v: (isFinite(qval) && qval > 0)
          ? '\u00a3' + qval.toLocaleString('en-GB', { maximumFractionDigits: 0 }) : '\u2014',
        has: isFinite(qval) && qval > 0 }
    ].filter(st => st.has);
    // A QB quote may legitimately have a zero here or there — never render
    // an empty band, and cap at 4 cells per row for readable widths.
    if (!stats.length) stats.push({ l: 'QUOTE', v: q.reference || '\u2014' });
    pageBreakIfNeeded(20);
    const perRow = Math.min(stats.length, 4);
    const cellW = (usableW - (perRow - 1) * 4) / perRow;
    stats.forEach((st, i) => {
      const x = marginL + (i % perRow) * (cellW + 4);
      if (i > 0 && i % perRow === 0) y += 19;
      setFill([252, 250, 248]); setDraw(RULE); doc.setLineWidth(0.2);
      doc.roundedRect(x, y - 3, cellW, 15, 1.2, 1.2, 'FD');
      setText(MUTED); doc.setFont('helvetica', 'bold'); doc.setFontSize(7);
      doc.text(st.l, x + 3, y + 1.5);
      setText(TEXT); doc.setFontSize(11.5);
      doc.text(String(st.v), x + 3, y + 8.5);
    });
    y += 20;
    doc.setFont('helvetica', 'normal'); setText(TEXT);
  }

  // ── Hours & variations ledger (base quote + VOs, per job) ──
  if (sheet.revisions && sheet.revisions.length) {
    sectionHead('Hours & variations');
    let tf = 0, td = 0;
    const rows = sheet.revisions.map(r => {
      const f = parseFloat(r.fab_hours) || 0, d = parseFloat(r.design_hours) || 0;
      tf += f; td += d;
      const ops = parseFloat(r.site_operatives), sd = parseFloat(r.site_days);
      const site = (isFinite(ops) && ops > 0) ? `${ops}\u00d7${(isFinite(sd) && sd > 0) ? sd + 'd' : '?'}` : '\u2014';
      return [ r.label, r.job_name || (r.job_id ? 'Job ' + r.job_id : 'Whole project'),
               r.description || '', f || '\u2014', d || '\u2014', site ];
    });
    drawTable([
      { label: 'Rev',        x: marginL + 5,   w: 20 },
      { label: 'Job',        x: marginL + 28,  w: 32 },
      { label: 'Description',x: marginL + 63,  w: 58 },
      { label: 'Fab hrs',    x: marginL + 124, w: 18, align: 'right' },
      { label: 'Design hrs', x: marginL + 146, w: 18, align: 'right' },
      { label: 'Site',       x: marginL + 168, w: usableW - 168 - 3, align: 'right' }
    ], rows, [ 'Total', '', '', tf || '\u2014', td || '\u2014', '' ]);
    y += 5;
  }

  // ── Fabrication summary — members & tonnage per job ──
  if (sheet.jobStats && sheet.jobStats.length) {
    sectionHead('Fabrication summary');
    let members = 0, kg = 0;
    const rows = sheet.jobStats.map(j => {
      const m = parseFloat(j.members) || 0, w = parseFloat(j.weight_kg) || 0;
      members += m; kg += w;
      return [ j.job_name || ('Job ' + j.job_id),
               parseFloat(j.assembly_marks) || 0, m || '\u2014', w > 0 ? fmtT(w) : '\u2014' ];
    });
    drawTable([
      { label: 'Job',     x: marginL + 5,   w: 84 },
      { label: 'Marks',   x: marginL + 94,  w: 24, align: 'right' },
      { label: 'Members', x: marginL + 124, w: 26, align: 'right' },
      { label: 'Weight',  x: marginL + 156, w: usableW - 156 - 3, align: 'right' }
    ], rows, [ 'Total', '', members || '\u2014', fmtT(kg) ]);
    y += 5;
  }

  // ── Notes (light bordered box) ──
  if (sheet.notes) {
    sectionHead('Notes');
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5); setText(TEXT);
    const wrapped = doc.splitTextToSize(sheet.notes, usableW - 12);
    const boxH = wrapped.length * 4.6 + 7;
    pageBreakIfNeeded(boxH + 4);
    setFill([252, 252, 250]); setDraw(RULE); doc.setLineWidth(0.2);
    doc.roundedRect(marginL, y - 3, usableW, boxH, 1.2, 1.2, 'FD');
    let ny = y + 1.5;
    for (const w of wrapped) { doc.text(w, marginL + 5, ny); ny += 4.6; }
    y += boxH + 4;
  }

  // ── Footer: rule + Page X of Y on every page ──
  const total = doc.getNumberOfPages();
  for (let p = 1; p <= total; p++) {
    doc.setPage(p);
    setDraw(RULE); doc.setLineWidth(0.2);
    doc.line(marginL, pageH - 11, pageW - marginR, pageH - 11);
    setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.text(`Page ${p} of ${total}`, pageW / 2, pageH - 7, { align: 'center' });
    doc.text(`${proj?.id || ''}${proj?.name ? ' \u2014 ' + proj.name : ''}`, marginL, pageH - 7);
    doc.text('Job Sheet', pageW - marginR, pageH - 7, { align: 'right' });
  }

  return doc.output('blob');
}

async function saveJobSheet() {
  if (!currentProject?.dbId) return;
  const val = id => (document.getElementById(id)?.value || '').trim() || null;
  const body = {
    site_name:          val('jsSiteName'),
    address_line1:      val('jsAddr1'),
    address_line2:      val('jsAddr2'),
    city:               val('jsCity'),
    county:             val('jsCounty'),
    postcode:           val('jsPostcode'),
    commercial_name:    val('jsComName'),
    commercial_phone:   val('jsComPhone'),
    commercial_email:   val('jsComEmail'),
    pm_name:            val('jsPmName'),
    pm_phone:           val('jsPmPhone'),
    pm_email:           val('jsPmEmail'),
    site_manager_name:  val('jsSmName'),
    site_manager_phone: val('jsSmPhone'),
    site_manager_email: val('jsSmEmail'),
    bama_contact_name:  val('jsBamaName'),
    bama_contact_phone: val('jsBamaPhone'),
    client_po_number:   val('jsPo'),
    notes:              val('jsNotes'),
    updated_by:         _currentDraftsmanName || null
  };
  const btn = document.getElementById('jsSaveBtn');
  try {
    if (btn) { btn.disabled = true; btn.textContent = 'Saving\u2026'; }
    // Any typed name not already in the client database is saved to
    // ClientContacts (with its role) so it shows in every dropdown from
    // now on — QB included. Non-fatal if it fails.
    await _jsSyncContactsToClientDb(body);
    const saved = await api.put(`/api/project-sheet/${parseInt(currentProject.dbId)}`, body);
    _currentJobSheet = (saved && saved.project_id) ? saved : null;
    _currentJobSheetProjId = parseInt(currentProject.dbId);
    toast('Job sheet saved \u2014 SDN / Site Pack / RAMS will prefill from it.', 'success');
    closeJobSheetModal();
  } catch (e) {
    toast('Failed to save job sheet: ' + (e.message || e), 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Save Job Sheet'; }
  }
}

let _pendingSdn = null;

async function openSiteDnModal() {
  const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
  if (!jobId) { toast('No job selected.', 'error'); return; }

  _sdnJobIds = [jobId];
  const built = await _sdnRebuildList();
  if (!built) {
    toast('Nothing to ship to site. Fabricated items must be ready for despatch first.', 'error');
    return;
  }
  _dnRenderJobsPicker('sdnJobsList', _sdnJobIds, 'sdnJobTick');

  // Prefill the editable delivery details from the project. Everything here is
  // editable in the modal — if the project data is wrong or missing, the user
  // fixes it here and still gets a correct DN without touching the database.
  const proj = currentProject;
  // Job Sheet is the default source (falls back to project site / client
  // details when no job sheet is saved yet) — see _jobSheetResolved().
  const r = _jobSheetResolved(proj);
  const nameGuess = (proj?.client && (r.siteName || proj?.name))
    ? `${proj.client} — ${r.siteName || proj.name}`
    : (proj?.client || r.siteName || proj?.name || '');
  const setVal = (id, v) => { const el = document.getElementById(id); if (el) el.value = v || ''; };
  setVal('sdnDeliverName',  nameGuess);
  setVal('sdnDeliverAddr',  r.lines.join('\n'));
  setVal('sdnContactName',  r.contact);
  setVal('sdnContactPhone', r.phone);
  setVal('sdnBamaName',     r.bamaName || '');
  setVal('sdnBamaPhone',    r.bamaPhone || '');
  setVal('sdnClientPo',     r.po);

  sdnUpdateSelCount();
  document.getElementById('siteDnModal').classList.add('active');
}

// Job tick on the SDN modal — rebuild the eligible union across jobs.
async function sdnJobTick(jobId, on) {
  jobId = parseInt(jobId);
  if (on) { if (!_sdnJobIds.includes(jobId)) _sdnJobIds.push(jobId); }
  else _sdnJobIds = _sdnJobIds.filter(x => x !== jobId);
  if (!_sdnJobIds.length) _sdnJobIds = [jobId];   // never zero jobs
  _dnRenderJobsPicker('sdnJobsList', _sdnJobIds, 'sdnJobTick');
  await _sdnRebuildList();
}

// Build the SDN eligible union across every ticked job and render the item
// list, grouped per job when several jobs are covered (fabricated + fixings
// sub-groups inside each job). Returns false when nothing is eligible.
async function _sdnRebuildList() {
  const isLoose = i => i.item_type === 'fixing' || i.item_type === 'consumable';
  const outstandingOf = i => Math.max(0, (Number(i.quantity) || 0) - (Number(i.despatched_qty) || 0));

  // Fabricated marks: shippable while ready_for_despatch with qty still out.
  // Fixings/consumables: shippable while ready_for_despatch OR already on_site
  // (overship / send replacements — erectors lose bolts).
  const perJob = [];
  for (const jid of _sdnJobIds) {
    const all = await _dnFetchJobItems(jid);
    const nm = _dnJobName(jid);
    const tag = i => ({ ...i, _jobId: jid, _jobName: nm });
    const fabItems = all.filter(i => !isLoose(i) && i.status === 'ready_for_despatch' && outstandingOf(i) > 0).map(tag);
    const fixItems = all.filter(i =>  isLoose(i) && (i.status === 'ready_for_despatch' || i.status === 'on_site')).map(tag);
    if (fabItems.length || fixItems.length) perJob.push({ jid, nm, fabItems, fixItems });
  }
  const eligible = perJob.flatMap(g => [...g.fabItems, ...g.fixItems]);
  if (!eligible.length) {
    // Keep the modal usable if it's already open (a tick removed the last
    // eligible job) — show the empty message rather than a dead list.
    if (_pendingSdn) {
      _pendingSdn.items = [];
      const list0 = document.getElementById('sdnItemList');
      if (list0) list0.innerHTML = '<div style="color:var(--subtle);font-size:12px;padding:12px">Nothing eligible on the selected jobs.</div>';
      sdnUpdateSelCount();
      return false;
    }
    return false;
  }

  _pendingSdn = _pendingSdn || {};
  _pendingSdn.items = eligible;

  const cEl = document.getElementById('sdnItemCount');
  if (cEl) cEl.textContent = eligible.length;

  // Row template — checkbox, description, outstanding, editable "this delivery" qty.
  const rowHtml = (it) => {
    const out = outstandingOf(it);
    const loose = isLoose(it);
    // Default qty this delivery = outstanding; complete fixings default blank + unticked.
    const defQty = out > 0 ? out : '';
    const ticked = out > 0;
    const maxAttr = loose ? '' : `max="${out}"`;   // fabricated capped; fixings uncapped
    const outLabel = out > 0
      ? `<span style="font-size:11px;color:var(--subtle)">out: <b style="color:var(--text)">${out}</b></span>`
      : `<span style="font-size:11px;color:#3ecf8e">complete${loose ? ' · can top up' : ''}</span>`;
    return `<div style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid var(--border)">
      <input type="checkbox" class="sdn-item-check" data-id="${it.id}" data-loose="${loose ? 1 : 0}" data-out="${out}" ${ticked ? 'checked' : ''}
             onchange="sdnUpdateSelCount()" style="width:14px;height:14px;accent-color:var(--accent)">
      <span style="font-family:var(--font-mono);font-size:12px;color:var(--text);flex:1">${escapeHtml(it.description)}</span>
      ${outLabel}
      <input type="number" min="1" ${maxAttr} step="1" value="${defQty}" placeholder="qty"
             class="sdn-qty" id="sdnQty_${it.id}" data-id="${it.id}"
             oninput="sdnUpdateSelCount()"
             style="width:64px;text-align:right;background:var(--bg-darker);border:1px solid var(--border);color:var(--text);font-family:var(--font-mono);font-size:12px;padding:4px 6px;border-radius:5px">
    </div>`;
  };

  const list = document.getElementById('sdnItemList');
  let html = `<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
    <label style="display:flex;align-items:center;gap:6px;cursor:pointer">
      <input type="checkbox" id="sdnSelectAll" checked onchange="sdnToggleAll(this.checked)" style="width:14px;height:14px;accent-color:var(--accent)">
      <span style="font-size:11px;color:var(--subtle);text-transform:uppercase;letter-spacing:.04em">Select all</span>
    </label>
    <span style="margin-left:auto;font-size:11px;color:var(--subtle)" id="sdnSelCount"></span>
  </div>`;

  const groupHead = (label) => `<div style="padding:6px 12px;font-size:10px;color:var(--subtle);text-transform:uppercase;letter-spacing:.05em;background:rgba(255,255,255,.03);border-bottom:1px solid var(--border)">${label}</div>`;
  const jobHead = (label) => `<div style="padding:6px 12px;font-size:10px;color:#a78bfa;text-transform:uppercase;letter-spacing:.05em;background:rgba(139,92,246,.08);border-bottom:1px solid var(--border);font-weight:700">${escapeHtml(label)}</div>`;
  const multiJob = perJob.length > 1;

  html += '<div style="border:1px solid var(--border);border-radius:8px;overflow:hidden;max-height:340px;overflow-y:auto">';
  for (const g of perJob) {
    if (multiJob) html += jobHead(g.nm);
    if (g.fabItems.length) html += groupHead('Fabricated items') + g.fabItems.map(rowHtml).join('');
    if (g.fixItems.length) html += groupHead('🔩 Fixings &amp; loose items') + g.fixItems.map(rowHtml).join('');
  }
  html += '</div>';
  if (list) list.innerHTML = html;
  sdnUpdateSelCount();
  return true;
}

// Read the ship-qty a row is set to (its number input), or 0 if blank/invalid.
function sdnRowQty(id) {
  const el = document.getElementById(`sdnQty_${id}`);
  const v = parseInt(el?.value);
  return (!v || v < 1) ? 0 : v;
}

function sdnToggleAll(on) {
  document.querySelectorAll('.sdn-item-check').forEach(c => {
    c.checked = on;
    // Ticking a blank (complete) row seeds qty 1 so it's shippable; unticking leaves it.
    if (on) {
      const q = document.getElementById(`sdnQty_${c.dataset.id}`);
      if (q && (!q.value || parseInt(q.value) < 1)) q.value = 1;
    }
  });
  sdnUpdateSelCount();
}

function sdnUpdateSelCount() {
  let checked = 0, qtySum = 0;
  document.querySelectorAll('.sdn-item-check:checked').forEach(c => {
    checked++;
    qtySum += sdnRowQty(c.dataset.id);
  });
  const el = document.getElementById('sdnSelCount');
  if (el) el.textContent = `${checked} line${checked === 1 ? '' : 's'} · ${qtySum} pcs this delivery`;
  const sumEl = document.getElementById('sdnItemQtySum');
  if (sumEl) sumEl.textContent = qtySum;
  const btn = document.getElementById('sdnConfirmBtn');
  if (btn) {
    const ok = checked > 0 && qtySum > 0;
    btn.disabled = !ok;
    btn.style.opacity = ok ? '1' : '.4';
    btn.style.cursor  = ok ? 'pointer' : 'not-allowed';
  }
}

function closeSiteDnModal() {
  document.getElementById('siteDnModal').classList.remove('active');
  _pendingSdn = null;
}

async function confirmSiteDn() {
  if (!_pendingSdn) return;
  // Collect ticked rows + their per-line "this delivery" qty.
  const checks = Array.from(document.querySelectorAll('.sdn-item-check:checked'));
  const lines = [];
  for (const c of checks) {
    const id = parseInt(c.dataset.id);
    const qty = sdnRowQty(id);
    const loose = c.dataset.loose === '1';
    const out = parseInt(c.dataset.out) || 0;
    if (qty < 1) { toast('Enter a delivery qty of 1 or more on every ticked line.', 'error'); return; }
    if (!loose && qty > out) {
      toast(`A fabricated line is set to ship ${qty} but only ${out} outstanding — can't overship fabricated marks.`, 'error');
      return;
    }
    lines.push({ item_id: id, qty });
  }
  if (!lines.length) { toast('Tick at least one item.', 'error'); return; }

  // Item objects for the PDF, tagged with the qty shipped on THIS note.
  const qtyById = new Map(lines.map(l => [l.item_id, l.qty]));
  const items = _pendingSdn.items
    .filter(i => qtyById.has(i.id))
    .map(i => ({ ...i, _shipQty: qtyById.get(i.id) }));
  const totalPcs = lines.reduce((s, l) => s + l.qty, 0);

  const btn = document.getElementById('sdnConfirmBtn');
  btn.disabled = true; btn.style.opacity = '.5';

  const proj = currentProject;
  const job  = currentJob;

  try {
    // 1. Allocate SDN ref + write despatch ledger + bump despatched_qty
    const allocRes = await api.post('/api/job-bom-items/generate-sdn', { lines });
    const sdnRef = allocRes.sdn_ref;

    // 2. Build the SDN PDF. Delivery details come from the (editable) modal
    //    fields, not re-derived from the project — so any correction the user
    //    made in the modal is what actually prints.
    await loadLogoDataUri();
    const getVal = id => (document.getElementById(id)?.value || '').trim();
    const deliverName    = getVal('sdnDeliverName');
    const deliverToLines = getVal('sdnDeliverAddr').split('\n').map(l => l.trim()).filter(Boolean);
    const contactName    = getVal('sdnContactName');
    const contactPhone   = getVal('sdnContactPhone');
    const bamaName       = getVal('sdnBamaName');
    const bamaPhone      = getVal('sdnBamaPhone');
    const clientPo       = getVal('sdnClientPo');
    const deliverToContact = [contactName, contactPhone].filter(Boolean).join(' \u00b7 ');
    const siteName = deliverName || (proj?.client || proj?.name || 'Site delivery');
    const sdnJobNames = [...new Set(items.map(i => i._jobName).filter(Boolean))];
    const dn = {
      number:          sdnRef,
      createdAt:       new Date().toISOString(),
      docType:         'client',            // drives client-facing labels in drawDnPDF
      clientPo:        clientPo || '',
      destinationName: siteName,
      deliverTo:       { name: deliverName || 'Site', lines: deliverToLines, contact: deliverToContact },
      finishName:      'Site delivery',
      jobNames:        sdnJobNames,
      bamaContact:     (bamaName || bamaPhone) ? { name: bamaName, phone: bamaPhone } : null,
      items
    };
    // 3. Render PDF natively with jsPDF (no html2canvas).
    const pdfBlob = await renderDnPdfBlob(dn, proj || {}, job || {}, `${sdnRef}.pdf`);

    // 4. Upload to SharePoint: same path as supplier DNs (per spec).
    const projectFolder = await findProjectFolder(proj.id);
    if (!projectFolder) throw new Error('Project folder not found on SharePoint');
    const driveId = projectFolder.parentReference?.driveId || BAMA_DRIVE_ID;
    const deliveriesFolder = await getOrCreateSubfolder(projectFolder.id, '07 - Deliveries', driveId);
    // Multi-job SDN files at the 07 - Deliveries root (refs are unique);
    // single-job keeps the job folder as before.
    const sdnJobIdsUsed = [...new Set(items.map(i => i._jobId).filter(Boolean))];
    const jobSubFolder = (sdnJobIdsUsed.length > 1)
      ? deliveriesFolder
      : await getOrCreateSubfolder(deliveriesFolder.id, (job && (job.folderName || job.name)) || 'Unassigned', driveId);
    const sdnFileName = `${sdnRef}.pdf`;
    const token = await getToken();
    const upUrl = `https://graph.microsoft.com/v1.0/drives/${driveId}/items/${jobSubFolder.id}:/${encodeURIComponent(sdnFileName)}:/content`;
    const upRes = await fetch(upUrl, {
      method: 'PUT',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/pdf' },
      body: pdfBlob
    });
    if (!upRes.ok) throw new Error(`SDN upload failed: ${upRes.status}`);
    const uploaded = await upRes.json();

    // 5. Backfill the SharePoint refs onto the ledger + item rows so the
    //    "open PDF" link resolves and any SDN is reprintable from data.
    try {
      await api.post('/api/job-bom-items/generate-sdn/files', {
        sdn_ref:             sdnRef,
        sharepoint_file_id:  uploaded.id || null,
        sharepoint_drive_id: driveId || null,
        sharepoint_web_url:  uploaded.webUrl || null,
        file_name:           sdnFileName
      });
    } catch (e) { console.warn('SDN file backfill failed (non-fatal):', e.message); }

    // Deliveries register row (non-fatal — the SDN is already filed).
    try {
      await api.post('/api/dn-register', {
        ref: sdnRef, kind: 'site',
        project_id: parseInt(proj.dbId) || null,
        job_ids: sdnJobIdsUsed,
        destination: siteName || null,
        line_count: lines.length,
        total_qty: totalPcs,
        sharepoint_file_id: uploaded.id || null,
        sharepoint_drive_id: driveId || null,
        sharepoint_web_url: uploaded.webUrl || null,
        file_name: sdnFileName,
        created_by: _currentDraftsmanName || null
      });
      delete _dnRegCache[parseInt(proj.dbId)];
    } catch (regErr) {
      toast('SDN saved, but the deliveries register entry failed (' + regErr.message + '). Has create-delivery-note-register.sql been run?', 'error');
    }

    closeSiteDnModal();
    toast(`${sdnRef} generated — ${totalPcs} pc${totalPcs > 1 ? 's' : ''} across ${lines.length} line${lines.length > 1 ? 's' : ''}${sdnJobNames.length > 1 ? ` from ${sdnJobNames.length} jobs` : ''} sent to site.`, 'success');
    // Refresh every job the SDN touched (despatched_qty bumped server-side).
    for (const jid of sdnJobIdsUsed) {
      delete _bomItemsByJob[jid];
      if (currentJob && parseInt(currentJob.id) === jid) await loadJobBomItems(jid);
      else await _dnFetchJobItems(jid);
    }
    renderBOM();
    renderSite();

    if (uploaded.webUrl) window.open(uploaded.webUrl, '_blank');

  } catch (e) {
    toast(`SDN failed: ${e.message}`, 'error');
    btn.disabled = false; btn.style.opacity = '1';
    return;
  }
}


// ── SDN edit & reissue ───────────────────────────────────────────────────────
// Any SDN with despatch-ledger rows (JobBomDespatches) can be edited after the
// fact: change per-line quantities, drop lines entirely, correct the delivery
// details, and reissue the PDF OVER THE SAME SharePoint file (same ref, same
// filename — anyone holding the old link sees the corrected note). The server
// (/api/sdn-amend) adjusts despatched_qty and item status by the exact delta
// in one transaction, so partial-despatch maths and the SDN queue stay right.
// Weight columns always redraw from CURRENT assembly unit weights, so fixing
// a wrong unit weight (pencil on the assembly card) then reissuing the SDN is
// the recovery path for batch-total OCR mistakes.
let _sdnEdit = null;   // { ref, reg, lines }

async function openSdnEditModal(ref) {
  const proj = currentProject;
  if (!proj?.dbId) { toast('Open the project first.', 'error'); return; }
  let detail;
  try {
    detail = await api.get(`/api/sdn-detail?ref=${encodeURIComponent(ref)}`);
  } catch (e) {
    toast('Could not load ' + ref + ': ' + e.message, 'error');
    return;
  }
  const pid = parseInt(proj.dbId);
  let reg = (_dnRegCache[pid] || []).find(r => r.ref === ref);
  if (!reg) {
    try {
      _dnRegCache[pid] = await api.get(`/api/dn-register?projectId=${pid}`);
      reg = (_dnRegCache[pid] || []).find(r => r.ref === ref);
    } catch (e) { /* register row optional — fall back below */ }
  }
  _sdnEdit = { ref, reg: reg || null, lines: detail.lines || [] };

  // Line rows: qty editable; 0 (or the bin) removes the line from the note.
  const isLoose = l => l.item_type === 'fixing' || l.item_type === 'consumable';
  const rowHtml = (l) => {
    // Max this line can hold = current ship qty + item's remaining headroom
    // (fabricated capped; fixings uncapped — same rules as generation).
    const headroom = Math.max(0, (Number(l.quantity) || 0) - (Number(l.despatched_qty) || 0));
    const maxAttr = isLoose(l) ? '' : `max="${Number(l.ship_qty) + headroom}"`;
    const mark = l.source === 'assembly' ? (l.source_assembly_mark || '') : '';
    return `<div style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid var(--border)" id="sdnE_row_${l.ledger_id}">
      <span style="font-family:var(--font-mono);font-size:12px;color:var(--text);flex:1">${mark ? `<b>${escapeHtml(mark)}</b> · ` : ''}${escapeHtml(l.description || '')}</span>
      <span style="font-size:11px;color:var(--subtle);white-space:nowrap">was <b style="color:var(--text)">${Number(l.ship_qty)}</b></span>
      <input type="number" min="0" ${maxAttr} step="1" value="${Number(l.ship_qty)}"
             class="sdnE-qty" id="sdnE_qty_${l.ledger_id}" data-lid="${l.ledger_id}"
             oninput="sdnEditUpdateCount()"
             style="width:64px;text-align:right;background:var(--bg-darker);border:1px solid var(--border);color:var(--text);font-family:var(--font-mono);font-size:12px;padding:4px 6px;border-radius:5px">
      <button class="btn btn-ghost" title="Remove this line from the note" style="padding:4px 8px;font-size:11px"
              onclick="document.getElementById('sdnE_qty_${l.ledger_id}').value=0;sdnEditUpdateCount()">&#128465;</button>
    </div>`;
  };
  const listEl = document.getElementById('sdnEditItemList');
  if (listEl) listEl.innerHTML =
    `<div style="border:1px solid var(--border);border-radius:8px;overflow:hidden;max-height:340px;overflow-y:auto">${_sdnEdit.lines.map(rowHtml).join('')}</div>`;

  // Delivery details: not persisted with the note, so prefill from the Job
  // Sheet exactly like generation — fix anything here before reissuing.
  const r = _jobSheetResolved(proj);
  const nameGuess = reg?.destination
    || ((proj?.client && (r.siteName || proj?.name)) ? `${proj.client} — ${r.siteName || proj.name}` : (proj?.client || r.siteName || proj?.name || ''));
  const setVal = (id, v) => { const el = document.getElementById(id); if (el) el.value = v || ''; };
  setVal('sdnE_DeliverName',  nameGuess);
  setVal('sdnE_DeliverAddr',  r.lines.join('\n'));
  setVal('sdnE_ContactName',  r.contact);
  setVal('sdnE_ContactPhone', r.phone);
  setVal('sdnE_BamaName',     r.bamaName || '');
  setVal('sdnE_BamaPhone',    r.bamaPhone || '');
  setVal('sdnE_ClientPo',     r.po);

  const title = document.getElementById('sdnEditTitle');
  if (title) title.textContent = `Edit ${ref}`;
  const dateEl = document.getElementById('sdnEditOrigDate');
  if (dateEl) dateEl.textContent = reg?.created_at
    ? `Originally issued ${new Date(reg.created_at).toLocaleDateString('en-GB')} — the reissued PDF keeps that date and adds a "Reissued" stamp.`
    : 'The reissued PDF overwrites the original file.';
  sdnEditUpdateCount();
  document.getElementById('sdnEditModal').classList.add('active');
}

function closeSdnEditModal() {
  document.getElementById('sdnEditModal').classList.remove('active');
  _sdnEdit = null;
}

function sdnEditUpdateCount() {
  if (!_sdnEdit) return;
  let lines = 0, pcs = 0;
  for (const l of _sdnEdit.lines) {
    const el = document.getElementById(`sdnE_qty_${l.ledger_id}`);
    const q = parseInt(el?.value) || 0;
    const row = document.getElementById(`sdnE_row_${l.ledger_id}`);
    if (row) row.style.opacity = q > 0 ? '1' : '.4';
    if (q > 0) { lines++; pcs += q; }
  }
  const el = document.getElementById('sdnEditSelCount');
  if (el) el.textContent = `${lines} line${lines === 1 ? '' : 's'} · ${pcs} pcs after edit`;
  const btn = document.getElementById('sdnEditConfirmBtn');
  if (btn) {
    const ok = lines > 0;
    btn.disabled = !ok;
    btn.style.opacity = ok ? '1' : '.4';
    btn.style.cursor  = ok ? 'pointer' : 'not-allowed';
  }
}

async function confirmSdnEdit() {
  if (!_sdnEdit) return;
  const ref = _sdnEdit.ref;
  const edits = [];
  for (const l of _sdnEdit.lines) {
    const q = parseInt(document.getElementById(`sdnE_qty_${l.ledger_id}`)?.value);
    if (isNaN(q) || q < 0) { toast('Quantities must be 0 or more (0 removes the line).', 'error'); return; }
    edits.push({ ledger_id: l.ledger_id, qty: q, _line: l });
  }
  if (!edits.some(e => e.qty > 0)) { toast('An SDN must keep at least one line.', 'error'); return; }

  const btn = document.getElementById('sdnEditConfirmBtn');
  btn.disabled = true; btn.style.opacity = '.5';
  const proj = currentProject;
  try {
    // 1. Amend the ledger + item quantities server-side (one transaction).
    const amendRes = await api.post('/api/sdn-amend', {
      ref, lines: edits.map(e => ({ ledger_id: e.ledger_id, qty: e.qty }))
    });

    // 2. Re-fetch the note from data — weights redraw from CURRENT assembly
    //    unit weights, so any corrected figure prints right on the reissue.
    const detail = await api.get(`/api/sdn-detail?ref=${encodeURIComponent(ref)}`);
    const items = (detail.lines || []).map(l => ({
      ...l,
      _shipQty: Number(l.ship_qty) || 0,
      _jobId:   l.job_id,
      _jobName: _dnJobName(l.job_id)
    }));

    // 3. Rebuild the DN object from the modal's (editable) delivery details.
    await loadLogoDataUri();
    const getVal = id => (document.getElementById(id)?.value || '').trim();
    const deliverName    = getVal('sdnE_DeliverName');
    const deliverToLines = getVal('sdnE_DeliverAddr').split('\n').map(x => x.trim()).filter(Boolean);
    const contactName    = getVal('sdnE_ContactName');
    const contactPhone   = getVal('sdnE_ContactPhone');
    const bamaName       = getVal('sdnE_BamaName');
    const bamaPhone      = getVal('sdnE_BamaPhone');
    const clientPo       = getVal('sdnE_ClientPo');
    const sdnJobNames = [...new Set(items.map(i => i._jobName).filter(Boolean))];
    const dn = {
      number:          ref,
      createdAt:       _sdnEdit.reg?.created_at || new Date().toISOString(),
      reissuedAt:      new Date().toISOString(),
      docType:         'client',
      clientPo:        clientPo || '',
      destinationName: deliverName || (proj?.client || proj?.name || 'Site delivery'),
      deliverTo:       { name: deliverName || 'Site', lines: deliverToLines, contact: [contactName, contactPhone].filter(Boolean).join(' \u00b7 ') },
      finishName:      'Site delivery',
      jobNames:        sdnJobNames,
      bamaContact:     (bamaName || bamaPhone) ? { name: bamaName, phone: bamaPhone } : null,
      items
    };
    const pdfBlob = await renderDnPdfBlob(dn, proj || {}, currentJob || {}, `${ref}.pdf`);

    // 4. Overwrite the ORIGINAL SharePoint file so every existing link shows
    //    the corrected note. File id comes off the ledger (backfilled at
    //    generation); path-upload fallback covers notes missing it.
    const token = await getToken();
    const led = (detail.lines || [])[0] || {};
    const fileId  = led.sdn_sharepoint_file_id  || _sdnEdit.reg?.sharepoint_file_id  || null;
    const driveId = led.sdn_sharepoint_drive_id || _sdnEdit.reg?.sharepoint_drive_id || null;
    let uploaded = null;
    if (fileId && driveId) {
      const upRes = await fetch(`https://graph.microsoft.com/v1.0/drives/${driveId}/items/${fileId}/content`, {
        method: 'PUT',
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/pdf' },
        body: pdfBlob
      });
      if (!upRes.ok) throw new Error(`Reissue upload failed: ${upRes.status}`);
      uploaded = await upRes.json();
    } else {
      // No stored file id — file by path at the 07 - Deliveries root (refs unique).
      const projectFolder = await findProjectFolder(proj.id);
      if (!projectFolder) throw new Error('Project folder not found on SharePoint');
      const dId = projectFolder.parentReference?.driveId || BAMA_DRIVE_ID;
      const deliveriesFolder = await getOrCreateSubfolder(projectFolder.id, '07 - Deliveries', dId);
      const upRes = await fetch(`https://graph.microsoft.com/v1.0/drives/${dId}/items/${deliveriesFolder.id}:/${encodeURIComponent(ref + '.pdf')}:/content`, {
        method: 'PUT',
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/pdf' },
        body: pdfBlob
      });
      if (!upRes.ok) throw new Error(`Reissue upload failed: ${upRes.status}`);
      uploaded = await upRes.json();
      // Backfill the refs so the next edit hits the fast path.
      try {
        await api.post('/api/job-bom-items/generate-sdn/files', {
          sdn_ref: ref,
          sharepoint_file_id:  uploaded.id || null,
          sharepoint_drive_id: dId || null,
          sharepoint_web_url:  uploaded.webUrl || null,
          file_name:           `${ref}.pdf`
        });
      } catch (e) { console.warn('SDN reissue file backfill failed (non-fatal):', e.message); }
    }

    // 5. Refresh everything the amend touched.
    const pid = parseInt(proj.dbId);
    delete _dnRegCache[pid];
    const touchedJobs = [...new Set(items.map(i => i._jobId).filter(Boolean))];
    for (const jid of touchedJobs) {
      delete _bomItemsByJob[jid];
      if (currentJob && parseInt(currentJob.id) === jid) await loadJobBomItems(jid);
    }
    closeSdnEditModal();
    if (currentJob) { renderBOM(); renderSite(); }   // guards: edit can open from the project-level register with no job open
    toast(`${ref} reissued — ${amendRes.total_qty} pc${amendRes.total_qty === 1 ? '' : 's'} across ${amendRes.line_count} line${amendRes.line_count === 1 ? '' : 's'}. The PDF was overwritten in place.`, 'success');
    if (uploaded?.webUrl) window.open(uploaded.webUrl, '_blank');
  } catch (e) {
    toast(`SDN edit failed: ${e.message}`, 'error');
    btn.disabled = false; btn.style.opacity = '1';
  }
}

// ── Delivery Note PDF — native jsPDF, no html2canvas ─────────────────────
// The html2canvas approach was abandoned after repeated blank/clipped output:
// it captures the element AS LAID OUT on the live app page, so bama.css's dark
// theme and layout bleed in (white-on-white text, left column clipped). The
// Babcock quote PDF already solved this by drawing natively with jsPDF
// (doc.text / doc.addImage) — the page's CSS is then completely irrelevant.
// This mirrors that renderer. buildDnHtmlV2() is kept only for the template
// preview (iframe.srcdoc); the actual PDF is drawn here from the same data.
async function renderDnPdfBlob(dn, proj, job, filename) {
  // Reuse the Babcock jsPDF resolver + logo cache (loadLogoDataUri already ran
  // in the caller). renderBabcockQuotePDF resolves the constructor for us.
  const JsPDFCtor = await resolveJsPDFCtor();
  if (!JsPDFCtor) throw new Error('PDF library failed to load');
  const logo = (typeof _logoDataUriCache !== 'undefined' && _logoDataUriCache) || '';
  const blob = drawDnPDF(JsPDFCtor, dn, proj, job, logo);
  console.log('[DN PDF] blob size:', blob.size, 'bytes (native jsPDF)');
  return blob;
}

// ═══════════════════════════════════════════════════════════════════════════
// BAMA HOUSE STYLE — shared PDF chrome (extracted from the delivery-note look)
// ───────────────────────────────────────────────────────────────────────────
// One letterhead, one section rule, one footer, so every BAMA document reads
// as the same family: real logo + company block top-left, big italic accent
// title top-right with a right-aligned label/value meta grid, a full-width
// rule beneath, accent section headings, and a small muted "Page X of Y"
// footer. Renderers call these instead of hand-rolling a header each time.
// Colours come from TEMPLATE_DEFAULTS/global settings so a future settings
// change (accent, company details, logo) flows to every document at once.
// ───────────────────────────────────────────────────────────────────────────
function _houseGlobal() {
  const s = (typeof _pickTplSettings === 'function') ? _pickTplSettings() : null;
  return (s && s.global) || (typeof TEMPLATE_DEFAULTS !== 'undefined' ? TEMPLATE_DEFAULTS.global
    : { companyName: 'BAMA FABRICATION', address: '', phone: '', email: '', vatNumber: '' });
}
function _houseAccent(hex) {
  return (typeof hexToRgb === 'function' && hexToRgb(hex || '#ff6b00')) || [255, 107, 0];
}
// Shared palette — keep in step with drawDnPDF.
const HOUSE_INK   = [34, 34, 34];
const HOUSE_MUTED = [90, 90, 90];
const HOUSE_SOFT  = [68, 68, 68];
const HOUSE_RULE  = [204, 204, 204];
const HOUSE_HEAD  = [245, 245, 245];

// Draw the standard BAMA letterhead. Returns { y } — the first free y below
// the header rule. opts: { title, accent, meta:[{label,value}], showLogo,
// showCompanyDetails, marginL, marginR }.
// Layout: logo top-left, company details to the RIGHT of the logo (not
// beneath), big italic accent title top-right with a right-aligned meta grid
// below it, full-width rule under the tallest column.
function bamaDocHeader(doc, logoDataUri, opts) {
  opts = opts || {};
  const g = _houseGlobal();
  const accent = opts.accent || _houseAccent();
  const pageW = opts.pageW || 210;   // pass 297 for landscape documents
  const mL = opts.marginL != null ? opts.marginL : 14;
  const mR = opts.marginR != null ? opts.marginR : 14;
  const setText = c => doc.setTextColor(c[0], c[1], c[2]);
  const y0 = mL;
  let leftBottom = y0;   // lowest y reached by the logo / company block
  let coX = mL;          // x where the company block starts (right of logo)
  let logoBottom = y0;

  // LEFT: logo (proportional). Company details sit to its right.
  let logoDrawn = false;
  if (opts.showLogo !== false && logoDataUri) {
    try {
      const RENDER_W = 46; // mm — a touch narrower so the address fits beside it
      const props = doc.getImageProperties(logoDataUri);
      const ratio = (props && props.width && props.height) ? (props.width / props.height) : (46 / 20);
      const renderH = RENDER_W / ratio;
      doc.addImage(logoDataUri, props.fileType || 'PNG', mL, y0, RENDER_W, renderH, undefined, 'FAST');
      coX = mL + RENDER_W + 6;
      logoBottom = y0 + renderH;
      logoDrawn = true;
    } catch (e) { logoDrawn = false; }
  }
  if (!logoDrawn) {
    doc.setFont('helvetica', 'bold'); doc.setFontSize(20); setText(accent);
    doc.text(g.companyName || 'BAMA FABRICATION', mL, y0 + 8);
    coX = mL + doc.getTextWidth(g.companyName || 'BAMA FABRICATION') + 8;
    logoBottom = y0 + 10;
  }

  // Company block, vertically roughly centred against the logo, to its right.
  if (opts.showCompanyDetails !== false) {
    const coLines = [];
    if (g.address) String(g.address).split('\n').forEach(l => coLines.push(l));
    if (g.phone)  coLines.push('Tel: ' + g.phone);
    if (g.email)  coLines.push(g.email);
    if (g.vatNumber) coLines.push('VAT: ' + g.vatNumber);
    // Keep the company block clear of the right-hand title/meta column.
    const coWrapW = Math.max(40, (pageW - mR - 62) - coX);
    setText(HOUSE_MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5);
    // Nudge down so the first line aligns with the top third of the logo.
    let coY = y0 + 3.5;
    coLines.forEach(l => {
      doc.splitTextToSize(String(l), coWrapW).forEach(w => { doc.text(w, coX, coY); coY += 3.8; });
    });
    leftBottom = Math.max(logoBottom, coY - 3.8);
  } else {
    leftBottom = logoBottom;
  }

  // RIGHT: italic accent title + meta grid.
  // Auto-shrink the title if it's too long for the space to the right of the
  // company block, so long titles (e.g. 'RAMS ACKNOWLEDGEMENT') don't overlap
  // the address. Shorter titles keep the full size-20 look.
  const titleStr = String(opts.title || '');
  doc.setFont('helvetica', 'bolditalic');
  const titleRightX = pageW - mR;
  // Left boundary the title must not cross: a little right of the company block.
  const titleLeftLimit = (opts.showCompanyDetails !== false) ? (pageW - mR - 66) : (mL + 4);
  const titleMaxW = titleRightX - titleLeftLimit;
  let titleSize = 20;
  doc.setFontSize(titleSize);
  while (titleSize > 11 && doc.getTextWidth(titleStr) > titleMaxW) { titleSize -= 0.5; doc.setFontSize(titleSize); }
  setText(accent);
  doc.text(titleStr, titleRightX, y0 + 8, { align: 'right' });

  let rightY = y0 + 16;
  const meta = (opts.meta || []).filter(r => r && r.label && r.value != null && String(r.value).trim() !== '');
  doc.setFontSize(9);
  const valX = pageW - mR;
  const valWrapW = 44;                 // value wrap width (mm)
  const labelX = pageW - mR - valWrapW - 2;
  for (const r of meta) {
    setText(HOUSE_INK); doc.setFont('helvetica', 'bold');
    doc.text(String(r.label), labelX, rightY, { align: 'right' });
    doc.setFont('helvetica', 'normal');
    const vLines = doc.splitTextToSize(String(r.value), valWrapW);
    // Print every wrapped line (previously only the first was drawn, so long
    // project names / POs silently truncated even though the space was kept).
    vLines.forEach((ln, i) => doc.text(ln, valX, rightY + i * 4.4, { align: 'right' }));
    rightY += 4.4 * Math.max(1, vLines.length);
  }

  let y = Math.max(leftBottom, rightY) + 2;
  doc.setDrawColor(HOUSE_INK[0], HOUSE_INK[1], HOUSE_INK[2]); doc.setLineWidth(0.5);
  doc.line(mL, y, pageW - mR, y);
  return { y: y + 7 };
}

// Accent section heading with an underline rule. Returns the y below it.
function bamaSectionHeading(doc, y, label, opts) {
  opts = opts || {};
  const accent = opts.accent || _houseAccent();
  const mL = opts.marginL != null ? opts.marginL : 14;
  const usableW = opts.usableW != null ? opts.usableW : ((opts.pageW || 210) - mL - (opts.marginR != null ? opts.marginR : 14));
  doc.setFont('helvetica', 'bold'); doc.setFontSize(opts.size || 9); doc.setTextColor(accent[0], accent[1], accent[2]);
  doc.text(String(label), mL, y);
  doc.setDrawColor(accent[0], accent[1], accent[2]); doc.setLineWidth(0.3);
  doc.line(mL, y + 1.6, mL + usableW, y + 1.6);
  return y + 6.5;
}

// Muted "Page X of Y" footer on every page, with an optional left caption.
function bamaDocFooter(doc, opts) {
  opts = opts || {};
  const pageW = opts.pageW || 210, pageH = opts.pageH || 297;
  const mL = opts.marginL != null ? opts.marginL : 14;
  const mR = opts.marginR != null ? opts.marginR : 14;
  const total = doc.internal.getNumberOfPages();
  for (let p = 1; p <= total; p++) {
    doc.setPage(p);
    doc.setTextColor(HOUSE_MUTED[0], HOUSE_MUTED[1], HOUSE_MUTED[2]);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(opts.size || 8);
    if (opts.caption) doc.text(String(opts.caption), mL, pageH - 8);
    doc.text(`Page ${p} of ${total}`, pageW - mR, pageH - 8, { align: 'right' });
  }
}

// Slim strip for page 2+ of a house-style document: small accent italic title
// left, muted ref right, ink rule beneath. Multi-page documents stay in the
// family without repeating the full letterhead on every page break.
// opts: { title, ref, accent, pageW, marginL, marginR }. Returns { y }.
function bamaDocContinuation(doc, opts) {
  opts = opts || {};
  const accent = opts.accent || _houseAccent();
  const pageW = opts.pageW || 210;
  const mL = opts.marginL != null ? opts.marginL : 14;
  const mR = opts.marginR != null ? opts.marginR : 14;
  doc.setFont('helvetica', 'bolditalic'); doc.setFontSize(11);
  doc.setTextColor(accent[0], accent[1], accent[2]);
  doc.text(String(opts.title || ''), mL, 14);
  if (opts.ref) {
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.setTextColor(HOUSE_MUTED[0], HOUSE_MUTED[1], HOUSE_MUTED[2]);
    doc.text(String(opts.ref), pageW - mR, 14, { align: 'right' });
  }
  doc.setDrawColor(HOUSE_INK[0], HOUSE_INK[1], HOUSE_INK[2]); doc.setLineWidth(0.4);
  doc.line(mL, 16.5, pageW - mR, 16.5);
  return { y: 22.5 };
}

// Native jsPDF delivery-note renderer. Returns a Blob. Modelled on
// drawBabcockQuotePDF — same margins, colour approach and page-break logic.
function drawDnPDF(jsPDF, dn, proj, job, logoDataUri) {
  const s = (typeof _pickTplSettings === 'function') ? _pickTplSettings() : null;
  const g = (s && s.global)       || (typeof TEMPLATE_DEFAULTS !== 'undefined' ? TEMPLATE_DEFAULTS.global       : { companyName:'BAMA FABRICATION', address:'', phone:'', email:'', vatNumber:'' });
  const t = (s && s.deliveryNote) || (typeof TEMPLATE_DEFAULTS !== 'undefined' ? TEMPLATE_DEFAULTS.deliveryNote : { title:'Delivery Note', accentColor:'#ff6b00', showLogo:true, showCompanyDetails:true, showSignatureBlock:true, termsText:'' });
  const accent = hexToRgb(t.accentColor || '#ff6b00') || [255, 107, 0];

  const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  try {
    doc.setProperties({
      title: `${dn.number || 'Delivery Note'}`,
      subject: `Delivery Note${proj && proj.name ? ' — ' + proj.name : ''}`,
      author: 'BAMA Fabrication', creator: 'BAMA Fabrication ERP'
    });
  } catch (e) { /* non-critical */ }

  const pageW = 210, pageH = 297, marginL = 14, marginR = 14, marginB = 14;
  const usableW = pageW - marginL - marginR;
  const TEXT = [34, 34, 34], MUTED = [90, 90, 90], RULE = [204, 204, 204], HEADFILL = [245, 245, 245];
  const setText = c => doc.setTextColor(c[0], c[1], c[2]);
  const setFill = c => doc.setFillColor(c[0], c[1], c[2]);
  const setDraw = c => doc.setDrawColor(c[0], c[1], c[2]);

  const fmtDate = new Date(dn.createdAt).toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' });

  // ── Header — shared BAMA letterhead (logo left, company block right of it,
  //    italic accent title + meta grid hard-right). Client-facing DNs (site
  //    delivery) relabel supplier-oriented fields and add the client's PO;
  //    supplier DNs (galvanising / powder etc.) keep 'Supplier:'.
  const isClient = dn.docType === 'client';
  const metaRows = [
    { label: 'DN Number:',  value: dn.number },
    { label: 'Date:',       value: fmtDate },
    { label: 'Project:',    value: proj && proj.name },
    { label: 'Project No:', value: proj && proj.id },
    { label: (Array.isArray(dn.jobNames) && dn.jobNames.length > 1) ? 'Jobs:' : 'Job:',
      value: (Array.isArray(dn.jobNames) && dn.jobNames.length) ? dn.jobNames.join(', ') : (job && job.name) },
    { label: isClient ? 'Client PO:' : null, value: isClient ? dn.clientPo : null },
    { label: isClient ? 'Client:' : 'Supplier:', value: dn.destinationName },
    { label: isClient ? null : 'For:', value: isClient ? null : dn.finishName },
    { label: 'Reissued:', value: dn.reissuedAt ? new Date(dn.reissuedAt).toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' }) : null }
  ];
  const _hdr = bamaDocHeader(doc, (t.showLogo !== false ? logoDataUri : ''), {
    title: t.title || 'Delivery Note',
    accent,
    marginL, marginR,
    showCompanyDetails: t.showCompanyDetails !== false,
    meta: metaRows
  });
  let y = _hdr.y;

  // ── Deliver-to panel ──────────────────
  const dt = dn.deliverTo || {};
  const dtLines = (dt.lines || []).filter(l => l != null && String(l).trim() !== '');
  // Split "Name · 01234 567890" back into a bold name + a phone line beneath.
  let dtContactName = '', dtContactPhone = '';
  if (dt.contact && String(dt.contact).trim()) {
    const parts = String(dt.contact).split('\u00b7').map(p => p.trim()).filter(Boolean);
    dtContactName  = parts[0] || '';
    dtContactPhone = parts.slice(1).join(' \u00b7 ');
  }
  const hasDeliverTo = (dt.name && String(dt.name).trim()) || dtLines.length || dtContactName || dtContactPhone;
  if (hasDeliverTo) {
    const boxX = marginL, boxW = 110, boxPad = 4;
    const innerW = boxW - boxPad * 2; // wrap width — keep text inside the frame
    const boxTop = y;
    let ty = y + 5;
    // Helper: draw one logical line, wrapping to the box width, advancing ty.
    const drawWrapped = (text, lineH) => {
      doc.splitTextToSize(String(text), innerW).forEach(w => {
        doc.text(w, boxX + boxPad, ty); ty += lineH;
      });
    };
    setText(MUTED); doc.setFont('helvetica', 'bold'); doc.setFontSize(7.5);
    doc.text('DELIVER TO', boxX + boxPad, ty); ty += 4.8;
    if (dt.name && String(dt.name).trim()) {
      setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
      drawWrapped(dt.name, 4.6);
    }
    if (dtLines.length) {
      setText([68, 68, 68]); doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
      dtLines.forEach(l => drawWrapped(l, 4));
    }
    // Site contact — name in bold, phone on the line below.
    if (dtContactName || dtContactPhone) {
      ty += 1.5;
      setText(MUTED); doc.setFont('helvetica', 'bold'); doc.setFontSize(7.5);
      doc.text('SITE CONTACT', boxX + boxPad, ty); ty += 4.2;
      if (dtContactName) {
        setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(9.5);
        drawWrapped(dtContactName, 4.2);
      }
      if (dtContactPhone) {
        setText([68, 68, 68]); doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
        drawWrapped(dtContactPhone, 4);
      }
    }
    // BAMA's own person on site — so the driver can call either side.
    if (dn.bamaContact && (dn.bamaContact.name || dn.bamaContact.phone)) {
      ty += 1.5;
      setText(MUTED); doc.setFont('helvetica', 'bold'); doc.setFontSize(7.5);
      doc.text('BAMA CONTACT', boxX + boxPad, ty); ty += 4.2;
      if (dn.bamaContact.name) {
        setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(9.5);
        drawWrapped(dn.bamaContact.name, 4.2);
      }
      if (dn.bamaContact.phone) {
        setText([68, 68, 68]); doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
        drawWrapped(dn.bamaContact.phone, 4);
      }
    }
    setDraw(RULE); doc.setLineWidth(0.3);
    doc.roundedRect(boxX, boxTop, boxW, (ty - boxTop) + 2, 1.5, 1.5);
    y = ty + 8;
  }

  // ── Items tables ──────────────────
  // Fabricated marks print Mark/Profile/Length/Weight from their assembly.
  // Fixings/loose items (bolts, anchors) print under their own heading with a
  // simple Description/Qty/Wt table. Qty shown is the amount on THIS note
  // (_shipQty) — which may be a partial of the full ordered line.
  const isLoose  = it => it.item_type === 'fixing' || it.item_type === 'consumable';
  const shipQtyOf = it => (it._shipQty != null ? Number(it._shipQty) : (Number(it.quantity) || 0));
  // Multi-job note: sort rows by job and banner each job's block so it's
  // unmistakable on paper which items belong to which job.
  const dnMultiJob = new Set((dn.items || []).map(it => it._jobId).filter(x => x != null)).size > 1;
  const byJob = (a, b) => String(a._jobName || '').localeCompare(String(b._jobName || ''));
  const fabRows = (dn.items || []).filter(it => !isLoose(it)).sort(dnMultiJob ? byJob : () => 0);
  const fixRows = (dn.items || []).filter(isLoose).sort(dnMultiJob ? byJob : () => 0);

  let grandWeight = 0, grandAnyWeight = false;

  const cellTextIn = (c, txt, ypos) => {
    const str = String(txt == null ? '' : txt);
    if (c.align === 'right')  doc.text(str, c.x + c.w - 2, ypos, { align: 'right' });
    else if (c.align === 'center') doc.text(str, c.x + c.w / 2, ypos, { align: 'center' });
    else doc.text(str, c.x + 2, ypos);
  };
  const layoutCols = (cols) => { let cx = marginL; cols.forEach(c => { c.x = cx; cx += c.w; }); return cols; };
  const drawColsHeader = (cols) => {
    setFill(HEADFILL); doc.rect(marginL, y, usableW, 7, 'F');
    setDraw(RULE); doc.setLineWidth(0.2); doc.rect(marginL, y, usableW, 7);
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(8.5);
    cols.forEach(c => cellTextIn(c, c.title, y + 4.7));
    y += 7;
  };
  // Accent-tinted full-width banner naming the job a block of rows belongs to
  // (multi-job notes only).
  const drawJobBanner = (name, cols) => {
    const h = 6.5;
    if (y + h > pageH - marginB - 30) { doc.addPage(); y = marginL + 4; drawColsHeader(cols); }
    doc.setFillColor(255, 240, 228); doc.rect(marginL, y, usableW, h, 'F');
    setDraw(RULE); doc.setLineWidth(0.15); doc.rect(marginL, y, usableW, h);
    setText(accent); doc.setFont('helvetica', 'bold'); doc.setFontSize(8.5);
    doc.text(`JOB: ${String(name || '').toUpperCase()}`, marginL + 2, y + 4.4);
    setText(TEXT); doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
    y += h;
  };

  // — Fabricated items —
  if (fabRows.length) {
    const cols = layoutCols([
      { key:'mark',   title:'Mark',          w: 42, align:'left'  },
      { key:'qty',    title:'Qty',           w: 10, align:'center'},
      { key:'profile',title:'Profile',       w: 34, align:'left'  },
      { key:'length', title:'Length (mm)',   w: 22, align:'right' },
      { key:'unit',   title:'Unit Wt. (kg)', w: 22, align:'right' },
      { key:'total',  title:'Line Wt. (kg)', w: 24, align:'right' },
      { key:'finish', title:'Finish',        w: usableW - 42 - 10 - 34 - 22 - 22 - 24, align:'left' }
    ]);
    drawColsHeader(cols);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
    let tQty = 0, tWt = 0, anyWt = false;
    let _fabLastJob = null;
    for (const it of fabRows) {
      if (dnMultiJob && it._jobName !== _fabLastJob) { _fabLastJob = it._jobName; drawJobBanner(it._jobName, cols); }
      const qty     = shipQtyOf(it);
      const unitWt  = it.assembly_weight_kg != null ? Number(it.assembly_weight_kg) : null;
      const lengthM = it.assembly_max_length_mm != null ? Number(it.assembly_max_length_mm) : null;
      const lineWt  = unitWt != null ? unitWt * qty : null;
      const mark    = it.source === 'assembly' ? (it.source_assembly_mark || 'assembly') : '\u2014';
      tQty += qty;
      if (lineWt != null) { tWt += lineWt; anyWt = true; }
      // Mark prints BOLD — measure it in bold too, or long sketch-style names
      // ("Basement Column 1-B & 2-B") overflow into the Qty/Profile columns.
      doc.setFont('helvetica', 'bold');
      const markLines = doc.splitTextToSize(String(mark), cols[0].w - 3);
      doc.setFont('helvetica', 'normal');
      const profLines = doc.splitTextToSize(String(it.description || ''), cols[2].w - 3);
      const finLines  = doc.splitTextToSize(String(it.finish_name || dn.finishName || ''), cols[6].w - 3);
      const nLines = Math.max(1, markLines.length, profLines.length, finLines.length);
      const rowH = nLines * 4.2 + 2;
      if (y + rowH > pageH - marginB - 30) { doc.addPage(); y = marginL + 4; drawColsHeader(cols); doc.setFont('helvetica','normal'); doc.setFontSize(9); }
      const baseY = y + 4.5;
      setText(TEXT);
      doc.setFont('helvetica', 'bold');
      markLines.forEach((l, i) => cellTextIn(cols[0], l, baseY + i * 4.2));
      doc.setFont('helvetica', 'normal');
      cellTextIn(cols[1], qty, baseY);
      profLines.forEach((l, i) => cellTextIn(cols[2], l, baseY + i * 4.2));
      cellTextIn(cols[3], lengthM != null ? lengthM.toLocaleString('en-GB', { maximumFractionDigits: 1 }) : '\u2014', baseY);
      cellTextIn(cols[4], unitWt != null ? String(Math.ceil(unitWt)) : '\u2014', baseY);
      cellTextIn(cols[5], lineWt != null ? String(Math.ceil(lineWt)) : '\u2014', baseY);
      finLines.forEach((l, i) => cellTextIn(cols[6], l, baseY + i * 4.2));
      setDraw(RULE); doc.setLineWidth(0.15); doc.line(marginL, y + rowH, pageW - marginR, y + rowH);
      y += rowH;
    }
    const totH = 7;
    if (y + totH > pageH - marginB - 20) { doc.addPage(); y = marginL + 4; }
    setFill(HEADFILL); doc.rect(marginL, y, usableW, totH, 'F');
    setDraw(RULE); doc.setLineWidth(0.2); doc.rect(marginL, y, usableW, totH);
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
    cellTextIn(cols[0], fixRows.length ? 'SUBTOTAL' : 'TOTAL', y + 4.7);
    cellTextIn(cols[1], tQty, y + 4.7);
    cellTextIn(cols[5], anyWt ? String(Math.ceil(tWt)) : '\u2014', y + 4.7);
    y += totH + 5;
    if (anyWt) { grandWeight += tWt; grandAnyWeight = true; }
  }

  // — Fixings / loose items —
  if (fixRows.length) {
    if (y > pageH - marginB - 44) { doc.addPage(); y = marginL + 6; }
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(9.5);
    doc.text('FIXINGS & LOOSE ITEMS', marginL, y + 1); y += 5;
    const cols = layoutCols([
      { key:'desc', title:'Description',   w: usableW - 18 - 30 - 34, align:'left'  },
      { key:'qty',  title:'Qty',           w: 18, align:'center' },
      { key:'wte',  title:'Wt each (kg)',  w: 30, align:'right' },
      { key:'line', title:'Line Wt. (kg)', w: 34, align:'right' }
    ]);
    drawColsHeader(cols);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
    let tQty = 0, tWt = 0, anyWt = false;
    let _fixLastJob = null;
    for (const it of fixRows) {
      if (dnMultiJob && it._jobName !== _fixLastJob) { _fixLastJob = it._jobName; drawJobBanner(it._jobName, cols); }
      const qty    = shipQtyOf(it);
      const wtEach = it.unit_weight_kg != null ? Number(it.unit_weight_kg) : null;
      const lineWt = wtEach != null ? wtEach * qty : null;
      tQty += qty;
      if (lineWt != null) { tWt += lineWt; anyWt = true; }
      const descLines = doc.splitTextToSize(String(it.description || ''), cols[0].w - 3);
      const rowH = Math.max(1, descLines.length) * 4.2 + 2;
      if (y + rowH > pageH - marginB - 30) { doc.addPage(); y = marginL + 4; drawColsHeader(cols); doc.setFont('helvetica','normal'); doc.setFontSize(9); }
      const baseY = y + 4.5;
      setText(TEXT);
      descLines.forEach((l, i) => cellTextIn(cols[0], l, baseY + i * 4.2));
      cellTextIn(cols[1], qty, baseY);
      cellTextIn(cols[2], wtEach != null ? wtEach.toFixed(3) : '\u2014', baseY);
      cellTextIn(cols[3], lineWt != null ? lineWt.toFixed(2) : '\u2014', baseY);
      setDraw(RULE); doc.setLineWidth(0.15); doc.line(marginL, y + rowH, pageW - marginR, y + rowH);
      y += rowH;
    }
    const totH = 7;
    if (y + totH > pageH - marginB - 20) { doc.addPage(); y = marginL + 4; }
    setFill(HEADFILL); doc.rect(marginL, y, usableW, totH, 'F');
    setDraw(RULE); doc.setLineWidth(0.2); doc.rect(marginL, y, usableW, totH);
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
    cellTextIn(cols[0], 'FIXINGS TOTAL', y + 4.7);
    cellTextIn(cols[1], tQty, y + 4.7);
    cellTextIn(cols[3], anyWt ? tWt.toFixed(2) : '\u2014', y + 4.7);
    y += totH + 5;
    if (anyWt) { grandWeight += tWt; grandAnyWeight = true; }
  }

  // Grand total-weight summary (both sections)
  if (grandAnyWeight) {
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
    doc.text(`Total Weight: ${Math.ceil(grandWeight)} kg`, pageW - marginR, y, { align: 'right' });
    y += 7;
  } else {
    setText(MUTED); doc.setFont('helvetica', 'italic'); doc.setFontSize(8);
    doc.text('Weights unavailable for these items.', marginL, y);
    y += 6;
  }

  // ── Signatures ──────────────────
  if (t.showSignatureBlock !== false) {
    // Client DNs get a taller 'received' box with Name / Signature / Date plus
    // a condition/damage-notes line — someone on site signs for the goods and
    // records any damage on delivery. Same frame style as before.
    const boxH = isClient ? 34 : 26;
    if (y > pageH - marginB - (boxH + 10)) { doc.addPage(); y = marginL + 6; }
    y += 4;
    const boxW = (usableW - 8) / 2;
    const leftBox  = { x: marginL,            label: 'Delivered By (BAMA):' };
    const rightBox = { x: marginL + boxW + 8, label: isClient ? 'Received By (Client):' : 'Received By (Supplier):' };

    // Left box — unchanged: signature line + date.
    setDraw(RULE); doc.setLineWidth(0.3); doc.rect(leftBox.x, y, boxW, boxH);
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(8.5);
    doc.text(leftBox.label, leftBox.x + 3, y + 6);
    setDraw([150, 150, 150]); doc.setLineWidth(0.2);
    doc.line(leftBox.x + 3, y + 17, leftBox.x + boxW - 3, y + 17);
    setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.text('Date:', leftBox.x + 3, y + 22);

    // Right box — client version adds Name + condition-on-delivery line.
    setDraw(RULE); doc.setLineWidth(0.3); doc.rect(rightBox.x, y, boxW, boxH);
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(8.5);
    doc.text(rightBox.label, rightBox.x + 3, y + 6);
    setDraw([150, 150, 150]); doc.setLineWidth(0.2);
    if (isClient) {
      setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
      doc.text('Name:', rightBox.x + 3, y + 12);
      doc.line(rightBox.x + 16, y + 12, rightBox.x + boxW - 3, y + 12);
      doc.text('Signature:', rightBox.x + 3, y + 19);
      doc.line(rightBox.x + 22, y + 19, rightBox.x + boxW - 3, y + 19);
      doc.text('Date:', rightBox.x + 3, y + 26);
      doc.line(rightBox.x + 16, y + 26, rightBox.x + boxW - 3, y + 26);
      doc.text('Condition / damage on delivery:', rightBox.x + 3, y + 31.5);
    } else {
      doc.line(rightBox.x + 3, y + 17, rightBox.x + boxW - 3, y + 17);
      setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
      doc.text('Date:', rightBox.x + 3, y + 22);
    }
    y += boxH + 6;
  }

  // ── Terms ──────────────────
  if (t.termsText) {
    if (y > pageH - marginB - 16) { doc.addPage(); y = marginL + 6; }
    setDraw([238, 238, 238]); doc.setLineWidth(0.3); doc.line(marginL, y, pageW - marginR, y); y += 4;
    setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.splitTextToSize(String(t.termsText), usableW).forEach(l => { doc.text(l, marginL, y); y += 3.6; });
  }

  // ── Footer: "Page X of Y" bottom-right on every page ──────────
  // Stamped last so the total page count is known and the footer sits on
  // whatever pages the content ended up spanning.
  const pageCount = doc.internal.getNumberOfPages();
  for (let p = 1; p <= pageCount; p++) {
    doc.setPage(p);
    setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.text(`Page ${p} of ${pageCount}`, pageW - marginR, pageH - 8, { align: 'right' });
  }

  return doc.output('blob');
}

// Small helpers shared by the native DN renderer.
function hexToRgb(hex) {
  const m = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(String(hex || ''));
  return m ? [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16)] : null;
}
// Resolve the jsPDF constructor the same way renderBabcockQuotePDF does,
// including the last-resort CDN load.
async function resolveJsPDFCtor() {
  const pick = () => {
    if (typeof window.jspdf !== 'undefined' && typeof window.jspdf.jsPDF === 'function') return window.jspdf.jsPDF;
    if (typeof window.jsPDF === 'function') return window.jsPDF;
    if (typeof window.html2pdf !== 'undefined' && typeof window.html2pdf.jsPDF === 'function') return window.html2pdf.jsPDF;
    return null;
  };
  let ctor = pick();
  if (ctor) return ctor;
  await new Promise((resolve, reject) => {
    const existing = document.querySelector('script[data-jspdf-loaded]');
    if (existing) {
      let tries = 0;
      const tick = () => { if (pick()) return resolve(); if (++tries > 50) return reject(new Error('jsPDF load timed out')); setTimeout(tick, 100); };
      return tick();
    }
    const sc = document.createElement('script');
    sc.src = 'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
    sc.dataset.jspdfLoaded = '1';
    sc.onload = resolve;
    sc.onerror = () => reject(new Error('Failed to load jsPDF from CDN'));
    document.head.appendChild(sc);
  });
  return pick();
}


// ═══════════════════════════════════════════════════════════════════════════
// SITE PACK — native jsPDF renderer + generation flow
// ───────────────────────────────────────────────────────────────────────────
// Mirrors the delivery-note approach exactly (drawDnPDF): everything is drawn
// natively with jsPDF (doc.text / doc.addImage / doc.rect) so the live page's
// dark bama.css is completely irrelevant — no html2canvas, no blank/clipped
// captures. Two-engine split, same as QB:
//   • DETERMINISTIC (no AI): header, site address, and the fixings table —
//     the fixings come straight from the job BOM (item_type fixing/consumable).
//   • AI (claude-proxy, reads the drawing): ONLY the Scope of Work prose.
// Everything is editable in the modal before the PDF is drawn.
// ═══════════════════════════════════════════════════════════════════════════

// Native Site Pack renderer. Returns a Blob. `pack` is assembled from the
// (editable) modal fields; proj/job give fallback context for the meta rows.
function drawSitePackPDF(jsPDF, pack, proj, job, logoDataUri) {
  const s = (typeof _pickTplSettings === 'function') ? _pickTplSettings() : null;
  const g = (s && s.global) || (typeof TEMPLATE_DEFAULTS !== 'undefined' ? TEMPLATE_DEFAULTS.global
            : { companyName:'BAMA FABRICATION', address:'', phone:'', email:'', vatNumber:'' });
  const accent = (typeof hexToRgb === 'function' && hexToRgb('#ff6b00')) || [255, 107, 0];

  const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  try {
    doc.setProperties({
      title: `Site Pack${pack.contract ? ' — ' + pack.contract : ''}`,
      subject: `Site Installation Pack${proj && proj.name ? ' — ' + proj.name : ''}`,
      author: 'BAMA Fabrication', creator: 'BAMA Fabrication ERP'
    });
  } catch (e) { /* non-critical */ }

  const pageW = 210, pageH = 297, marginL = 14, marginR = 14, marginB = 14;
  const usableW = pageW - marginL - marginR;
  const TEXT = [34, 34, 34], MUTED = [90, 90, 90], RULE = [204, 204, 204], HEADFILL = [245, 245, 245];
  const setText = c => doc.setTextColor(c[0], c[1], c[2]);
  const setFill = c => doc.setFillColor(c[0], c[1], c[2]);
  const setDraw = c => doc.setDrawColor(c[0], c[1], c[2]);

  const fmtDate = pack.dateStr || new Date(pack.createdAt || Date.now())
    .toLocaleDateString('en-GB', { day:'numeric', month:'long', year:'numeric' });

  // ── Header: logo (left) + company details (to the RIGHT of the logo) +
  //    title (far right). Address beside the logo condenses the whole band. ──
  let y = marginL;
  let logoW = 0, logoBottom = y;
  if (logoDataUri) {
    try {
      const RENDER_W = 48; // mm — slightly smaller so the address sits neatly beside it
      const props = doc.getImageProperties(logoDataUri);
      const ratio = (props && props.width && props.height) ? (props.width / props.height) : (55 / 24);
      const renderH = RENDER_W / ratio;
      doc.addImage(logoDataUri, props.fileType || 'PNG', marginL, y, RENDER_W, renderH, undefined, 'FAST');
      logoW = RENDER_W; logoBottom = y + renderH;
    } catch (e) { logoW = 0; }
  }
  if (!logoW) {
    doc.setFont('helvetica', 'bold'); doc.setFontSize(18); setText(accent);
    doc.text(g.companyName || 'BAMA FABRICATION', marginL, y + 7);
    logoW = doc.getTextWidth(g.companyName || 'BAMA FABRICATION');
    logoBottom = y + 10;
  }

  // Company details — to the RIGHT of the logo.
  const coX = marginL + logoW + 8;
  let coY = y + 3.5;
  setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
  const coLines = [];
  if (g.address) String(g.address).split('\n').forEach(l => coLines.push(l));
  if (g.phone)  coLines.push('Tel: ' + g.phone);
  if (g.email)  coLines.push(g.email);
  coLines.forEach(l => { doc.text(String(l), coX, coY); coY += 3.6; });

  // RIGHT: italic title
  doc.setFont('helvetica', 'bolditalic'); doc.setFontSize(20); setText(accent);
  doc.text('Site Pack', pageW - marginR, y + 8, { align: 'right' });

  // Details as a full-width info table (fills the page width; the site address
  // sits INSIDE it, above the divider). Drawing refs move to a full-width band
  // BELOW the divider so any number of them wrap horizontally instead of
  // stacking in a narrow right-hand column.
  const site = pack.site || {};
  const siteAddrStr = [site.name, ...(site.lines || [])]
    .map(l => (l == null ? '' : String(l).trim())).filter(Boolean).join(', ');
  const contactStr = [site.contactName, site.contactPhone]
    .map(l => (l == null ? '' : String(l).trim())).filter(Boolean).join(' \u00b7 ');

  // Drop below the tallest of logo / company details / title.
  y = Math.max(logoBottom, coY, y + 12) + 4;

  // 4-column grid: label | value | label | value, full page width.
  const spLabelW = 26;
  const spValW = (usableW - spLabelW * 2) / 2;
  const colX = [marginL, marginL + spLabelW, marginL + spLabelW + spValW, marginL + spLabelW * 2 + spValW];
  const drawCell = (x, w, text, isLabel, rowH) => {
    if (isLabel && text) { setFill(HEADFILL); doc.rect(x, y, w, rowH, 'F'); }
    setDraw(RULE); doc.setLineWidth(0.15); doc.rect(x, y, w, rowH);
    setText(TEXT); doc.setFont('helvetica', isLabel ? 'bold' : 'normal');
    doc.splitTextToSize(String(text == null ? '' : text), w - 3).forEach((ln, i) => doc.text(ln, x + 2, y + 4 + i * 3.9));
  };
  const pairRows = [
    [['Project No', pack.projectNo || (proj && (proj.project_number || proj.id))], ['Client', pack.client || (proj && proj.client)]],
    [['Contract', pack.contract || (proj && (proj.project_name || proj.name))],   ['Prepared by', pack.preparedBy]],
    [['Finish', pack.finish], ['Grade', pack.grade]],
    [['Date', fmtDate], ['Site Contact', contactStr]]
  ];
  doc.setFontSize(8.5);
  for (const row of pairRows) {
    const cellDefs = [
      { x: colX[0], w: spLabelW, text: row[0][0], label: true },
      { x: colX[1], w: spValW,   text: row[0][1], label: false },
      { x: colX[2], w: spLabelW, text: row[1][0], label: true },
      { x: colX[3], w: spValW,   text: row[1][1], label: false }
    ];
    let maxLines = 1;
    cellDefs.forEach(c => { const n = doc.splitTextToSize(String(c.text == null ? '' : c.text), c.w - 3).length; if (n > maxLines) maxLines = n; });
    const rowH = maxLines * 3.9 + 2.4;
    cellDefs.forEach(c => drawCell(c.x, c.w, c.text, c.label, rowH));
    y += rowH;
  }
  // Site Address — full-width value row (label + value spanning cols 2-4).
  if (siteAddrStr) {
    const valW2 = usableW - spLabelW;
    const nLines = doc.splitTextToSize(siteAddrStr, valW2 - 3).length;
    const rowH = nLines * 3.9 + 2.4;
    drawCell(colX[0], spLabelW, 'Site Address', true, rowH);
    drawCell(colX[1], valW2, siteAddrStr, false, rowH);
    y += rowH;
  }

  y += 4;
  // ── Black divider ──────────────────
  setDraw(TEXT); doc.setLineWidth(0.5); doc.line(marginL, y, pageW - marginR, y);
  y += 6;

  // ── Drawings band (below the line, full width) ──────────
  if (pack.drawingRef && String(pack.drawingRef).trim()) {
    setText(MUTED); doc.setFont('helvetica', 'bold'); doc.setFontSize(7.5);
    doc.text('DRAWINGS', marginL, y + 3);
    setText(TEXT); doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5);
    const dLabelW = 22;
    const dLines = doc.splitTextToSize(String(pack.drawingRef), usableW - dLabelW);
    dLines.forEach((ln, i) => doc.text(ln, marginL + dLabelW, y + 3 + i * 4));
    y += Math.max(4, dLines.length * 4) + 5;
  }

  // ── Scope of Work ──────────────────
  const scope = (pack.scopeLines || []).map(l => String(l == null ? '' : l).trim()).filter(Boolean);
  if (scope.length) {
    if (y > pageH - marginB - 24) { doc.addPage(); y = marginL + 6; }
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5);
    doc.text('SCOPE OF WORK', marginL, y); y += 2;
    setDraw(accent); doc.setLineWidth(0.5); doc.line(marginL, y, pageW - marginR, y); y += 6;

    const numX = marginL, txtX = marginL + 8, txtW = usableW - 8;
    doc.setFontSize(9.5);
    scope.forEach((line, idx) => {
      // Strip any leading "1." / "1)" the AI or user may have typed — we number.
      const clean = line.replace(/^\s*\d+[.)]\s*/, '');
      const wrapped = doc.splitTextToSize(clean, txtW);
      const rowH = wrapped.length * 4.6 + 2.5;
      if (y + rowH > pageH - marginB - 10) { doc.addPage(); y = marginL + 6; }
      setText(accent); doc.setFont('helvetica', 'bold');
      doc.text(String(idx + 1) + '.', numX, y + 3.5);
      setText(TEXT); doc.setFont('helvetica', 'normal');
      wrapped.forEach((w, i) => doc.text(w, txtX, y + 3.5 + i * 4.6));
      y += rowH;
    });
    y += 4;
  }

  // ── Fasteners & Items to Take to Site ──────────────────
  const fixings = (pack.fixings || []).filter(f => (f.description && String(f.description).trim()) || f.qty);
  if (fixings.length) {
    if (y > pageH - marginB - 30) { doc.addPage(); y = marginL + 6; }
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5);
    doc.text('FASTENERS & ITEMS TO TAKE TO SITE', marginL, y); y += 2;
    setDraw(accent); doc.setLineWidth(0.5); doc.line(marginL, y, pageW - marginR, y); y += 5;

    const cols = [
      { key:'qty',  title:'Qty',            w: 18, align:'left'  },
      { key:'desc', title:'Description',    w: usableW - 18 - 46, align:'left' },
      { key:'coat', title:'Grade / Coating',w: 46, align:'left' }
    ];
    let cx = marginL; cols.forEach(c => { c.x = cx; cx += c.w; });
    const cellIn = (c, txt, ypos) => {
      const str = String(txt == null ? '' : txt);
      if (c.align === 'right') doc.text(str, c.x + c.w - 2, ypos, { align:'right' });
      else if (c.align === 'center') doc.text(str, c.x + c.w / 2, ypos, { align:'center' });
      else doc.text(str, c.x + 2, ypos);
    };
    const drawHead = () => {
      setFill(HEADFILL); doc.rect(marginL, y, usableW, 7, 'F');
      setDraw(RULE); doc.setLineWidth(0.2); doc.rect(marginL, y, usableW, 7);
      setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(8.5);
      cols.forEach(c => cellIn(c, c.title, y + 4.7));
      y += 7;
    };
    drawHead();
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
    let tQty = 0;
    for (const f of fixings) {
      const q = Number(f.qty) || 0; tQty += q;
      const descLines = doc.splitTextToSize(String(f.description || ''), cols[1].w - 3);
      const coatLines = doc.splitTextToSize(String(f.coating || ''), cols[2].w - 3);
      const nLines = Math.max(1, descLines.length, coatLines.length);
      const rowH = nLines * 4.2 + 2;
      if (y + rowH > pageH - marginB - 16) { doc.addPage(); y = marginL + 4; drawHead(); doc.setFont('helvetica','normal'); doc.setFontSize(9); }
      const baseY = y + 4.5;
      setText(TEXT);
      cellIn(cols[0], q || '', baseY);
      descLines.forEach((l, i) => cellIn(cols[1], l, baseY + i * 4.2));
      coatLines.forEach((l, i) => cellIn(cols[2], l, baseY + i * 4.2));
      setDraw(RULE); doc.setLineWidth(0.15); doc.line(marginL, y + rowH, pageW - marginR, y + rowH);
      y += rowH;
    }
    const totH = 7;
    if (y + totH > pageH - marginB - 10) { doc.addPage(); y = marginL + 4; }
    setFill(HEADFILL); doc.rect(marginL, y, usableW, totH, 'F');
    setDraw(RULE); doc.setLineWidth(0.2); doc.rect(marginL, y, usableW, totH);
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
    cellIn(cols[0], tQty, y + 4.7);
    cellIn(cols[1], 'TOTAL ITEMS', y + 4.7);
    y += totH + 5;
  }

  // ── Notes (optional free text) ──────────────────
  if (pack.notes && String(pack.notes).trim()) {
    if (y > pageH - marginB - 16) { doc.addPage(); y = marginL + 6; }
    setText(MUTED); doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
    doc.text('NOTES', marginL, y); y += 4;
    setText([68,68,68]); doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5);
    doc.splitTextToSize(String(pack.notes), usableW).forEach(l => { doc.text(l, marginL, y); y += 4; });
  }

  // ── Footer: "Page X of Y" on every page ──────────
  const pageCount = doc.internal.getNumberOfPages();
  for (let p = 1; p <= pageCount; p++) {
    doc.setPage(p);
    setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.text(`Page ${p} of ${pageCount}`, pageW - marginR, pageH - 8, { align: 'right' });
    doc.text('BAMA Fabrication Ltd — Site Installation Pack', marginL, pageH - 8);
  }

  return doc.output('blob');
}

// Blob wrapper — resolves the jsPDF ctor + logo cache exactly like the DN flow.
async function renderSitePackPdfBlob(pack, proj, job) {
  const JsPDFCtor = await resolveJsPDFCtor();
  if (!JsPDFCtor) throw new Error('PDF library failed to load');
  const logo = (typeof _logoDataUriCache !== 'undefined' && _logoDataUriCache) || '';
  const blob = drawSitePackPDF(JsPDFCtor, pack, proj, job, logo);
  console.log('[Site Pack PDF] blob size:', blob.size, 'bytes (native jsPDF)');
  return blob;
}

// Map a filename to a Claude content-block media type. PDFs go as documents,
// raster images as images; unknown extensions default to PDF (the common case).
function _sitePackMediaType(name) {
  const ext = ((String(name || '').match(/\.([a-z0-9]+)$/i) || [])[1] || '').toLowerCase();
  if (ext === 'png')  return { media: 'image/png',  isImage: true };
  if (ext === 'jpg' || ext === 'jpeg') return { media: 'image/jpeg', isImage: true };
  if (ext === 'webp') return { media: 'image/webp', isImage: true };
  if (ext === 'gif')  return { media: 'image/gif',  isImage: true };
  return { media: 'application/pdf', isImage: false };
}

// Pull a SharePoint drive item down as raw base64 (no data-URI prefix) so it
// can be attached to a claude-proxy call. Same Graph path the logo loader uses.
async function _sitePackFetchBase64(fileId, driveId) {
  const token = await getToken();
  const res = await fetch(
    `https://graph.microsoft.com/v1.0/drives/${driveId || BAMA_DRIVE_ID}/items/${fileId}/content`,
    { headers: { 'Authorization': `Bearer ${token}` } }
  );
  if (!res.ok) throw new Error('drawing fetch failed (' + res.status + ')');
  const blob = await res.blob();
  const dataUri = await new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(r.result);
    r.onerror = () => reject(new Error('file read failed'));
    r.readAsDataURL(blob);
  });
  return String(dataUri).split(',')[1] || '';
}

// Read the current fixings-table rows out of the modal.
function _sitePackCollectFixings() {
  return [...document.querySelectorAll('#spFixingsBody .sp-fix-row')].map(r => ({
    qty:         (r.querySelector('.sp-fix-qty')?.value  || '').trim(),
    description: (r.querySelector('.sp-fix-desc')?.value || '').trim(),
    coating:     (r.querySelector('.sp-fix-coat')?.value || '').trim()
  })).filter(f => f.description || f.qty);
}

// Append one editable fixings row (blank if no args).
function sitePackAddFixingRow(qty, desc, coat) {
  const body = document.getElementById('spFixingsBody');
  if (!body) return;
  const div = document.createElement('div');
  div.className = 'sp-fix-row';
  div.style.cssText = 'display:flex;gap:8px;margin-bottom:6px';
  div.innerHTML =
    `<input class="sp-fix-qty field-input" type="number" min="0" step="1" value="${qty != null ? escapeHtml(String(qty)) : ''}" placeholder="Qty" style="width:70px;text-align:right">` +
    `<input class="sp-fix-desc field-input" type="text" value="${desc != null ? escapeHtml(desc) : ''}" placeholder="Description" style="flex:1">` +
    `<input class="sp-fix-coat field-input" type="text" value="${coat != null ? escapeHtml(coat) : ''}" placeholder="Grade / Coating" style="width:150px">` +
    `<button class="btn" onclick="this.closest('.sp-fix-row').remove()" style="padding:4px 10px;background:rgba(255,68,68,.1);border:1px solid rgba(255,68,68,.3);color:var(--red)">&#128465;</button>`;
  body.appendChild(div);
}

// Open the Site Pack modal, prefilling everything the job already holds.
// Header + site address + fixings are deterministic; the Scope textarea is
// left for the "Generate from drawing" AI step (or manual typing).
function openSitePackModal() {
  const proj = currentProject, job = currentJob;
  if (!job?.id) { toast('No job selected.', 'error'); return; }
  const jobId = parseInt(job.id);

  const setV = (id, v) => { const el = document.getElementById(id); if (el) el.value = (v == null ? '' : v); };

  // — Header —
  setV('spProjectNo',  proj?.project_number || proj?.id || '');
  setV('spContract',   proj?.project_name || proj?.name || '');
  setV('spClient',     proj?.client || '');
  setV('spPreparedBy', _currentDraftsmanName || '');
  setV('spDate',       new Date().toISOString().slice(0, 10));
  setV('spGrade',      'Sections S355 / Plates & fittings S275');   // BAMA default — editable
  setV('spScopeText',  '');
  setV('spNotes',      '');
  const spStatus = document.getElementById('spScopeStatus'); if (spStatus) spStatus.textContent = '';

  // — Site address (Job Sheet first; falls back to project site / client) —
  const r = _jobSheetResolved(proj);
  setV('spSiteName',   r.siteName);
  setV('spSiteAddr',   r.lines.join('\n'));
  setV('spSiteContact', r.contact);
  setV('spSitePhone',   r.phone);

  // — Drawings picker (from the Site Installation files on this job) —
  // These are drawings to READ. Exclude our own previously-generated Site Packs
  // (don't reference/read our own output) and dedupe by fileId — approval
  // drawings can land in the folder more than once.
  const allSiteFiles = (job.site && job.site.files) || [];
  const isGenPack = f => /^site pack\b/i.test(String(f.name || f.fileName || ''));
  const _seenDraw = new Set();
  const files = allSiteFiles.filter(f => {
    if (isGenPack(f)) return false;
    const key = f.fileId || (f.name || f.fileName);
    if (_seenDraw.has(key)) return false;
    _seenDraw.add(key); return true;
  });
  const drawWrap = document.getElementById('spDrawingList');
  if (drawWrap) {
    if (files.length) {
      drawWrap.innerHTML = files.map(f => {
        const nm = f.name || f.fileName || 'drawing';
        return `<label style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-bottom:1px solid var(--border);cursor:pointer">
          <input type="checkbox" class="sp-draw-check" checked
                 data-fileid="${escapeHtml(f.fileId || '')}" data-driveid="${escapeHtml(f.driveId || '')}"
                 data-fname="${escapeHtml(f.fileName || nm)}" style="width:14px;height:14px;accent-color:var(--accent)">
          <span style="font-size:12px;color:var(--text)">${escapeHtml(nm)}</span>
        </label>`;
      }).join('');
    } else {
      drawWrap.innerHTML = `<div style="color:var(--subtle);font-size:12px;padding:8px 0">No drawings uploaded to Site Installation yet — upload one first, or type the scope manually below.</div>`;
    }
  }
  // Drawing Ref default = unique clean drawing names (packs/dupes already gone).
  const refNames = [...new Set(files.map(f => f.name || f.fileName).filter(Boolean))];
  setV('spDrawingRef', refNames.join(', '));

  // — Fixings (BOM loose items: item_type fixing/consumable) —
  const body = document.getElementById('spFixingsBody');
  if (body) {
    body.innerHTML = '';
    const bom = _bomItemsByJob[jobId] || [];
    const loose = bom.filter(i => i.item_type === 'fixing' || i.item_type === 'consumable');
    if (loose.length) {
      loose.forEach(i => sitePackAddFixingRow(Number(i.quantity) || '', i.description || '', i.finish_name || ''));
    } else {
      sitePackAddFixingRow('', '', '');   // one blank starter row
    }
    // Finish default = most common finish among fabricated BOM items.
    const fabFin = bom.filter(i => !(i.item_type === 'fixing' || i.item_type === 'consumable') && i.finish_name)
                      .map(i => i.finish_name);
    const finCount = {};
    fabFin.forEach(f => { finCount[f] = (finCount[f] || 0) + 1; });
    const topFin = Object.keys(finCount).sort((x, y) => finCount[y] - finCount[x])[0] || '';
    setV('spFinish', topFin);
  }

  document.getElementById('sitePackModal').classList.add('active');
}

function closeSitePackModal() {
  document.getElementById('sitePackModal').classList.remove('active');
}

// ═══════════════════════════════════════════
// RAMS GENERATOR (Site Installation)
// Phase 1: modal shell + prefill + drawing picker. Mirrors the Site Pack flow
// (openSitePackModal / confirmSitePack). Later phases: AI drawing-read (2),
// native jsPDF render + risk library (3), tier wiring (4), site-plan pin (5),
// SharePoint save to <Project>/00 - RAMS/<job>/ + 'rams' file context (6 — DONE),
// DOCX (7).
// ═══════════════════════════════════════════
let _ramsSitePlanDataUri = null;   // set by ramsPreviewSitePlan(); embedded in the PDF site-plan section.

// ── RAMS register state (numbering / revisions / multi-job merge) ──────────
let _ramsEditDoc      = null;   // RamsDocuments row when REVISING; null for a new RAMS
let _ramsAssignedNo   = null;   // rams_no handed out by /api/rams-next-no
let _ramsRevisionInt  = 0;      // 0 = first issue; printed as Rev 00 / 01 / …
let _ramsJobIds       = [];     // selected job ids (merge = several)
let _ramsJobsLocked   = false;  // revisions open with the job list locked
let _ramsDocNoManual  = false;  // user typed into the Doc No box — stop auto-sync
let _ramsDocsCache    = {};     // projectId -> RamsDocuments register rows
const _ramsPad = (n, w) => String(Math.max(0, parseInt(n) || 0)).padStart(w, '0');
let _ramsSitePlanPin = null;       // {x,y} in % of the image (phase 5 click-to-pin); drawn as a work-area marker in the PDF.

async function openRamsModal(existingDocId) {
  const proj = currentProject, job = currentJob;
  if (!job?.id) { toast('No job selected.', 'error'); return; }
  const setV = (id, v) => { const el = document.getElementById(id); if (el) el.value = (v == null ? '' : v); };

  // ── Register state: revising an existing RAMS, or numbering a new one ──
  _ramsEditDoc = null; _ramsDocNoManual = false;
  let savedRams = null;
  try {
    if (existingDocId) {
      // REVISION: load the saved row + next revision number; jobs locked.
      const row = await api.get(`/api/rams-docs/${existingDocId}`);
      const next = await api.get(`/api/rams-next-no?projectId=${row.project_id}&ramsNo=${row.rams_no}`);
      _ramsEditDoc = row;
      _ramsAssignedNo = row.rams_no;
      _ramsRevisionInt = next.revision;
      _ramsJobIds = (() => { try { return (JSON.parse(row.job_ids || '[]') || []).map(Number); } catch (e) { return []; } })();
      if (!_ramsJobIds.length) _ramsJobIds = [parseInt(job.id)];
      _ramsJobsLocked = true;
      try { savedRams = row.rams_data ? JSON.parse(row.rams_data) : null; } catch (e) { savedRams = null; }
    } else {
      // NEW: next free number for the project. If the register API/table is
      // missing, fall back to the legacy behaviour (no numbering) gracefully.
      // proj.id is the project NUMBER string ("S1982"); the SQL id is proj.dbId
      // (same trap as the Job Sheet — see loadJobSheet).
      const next = proj?.dbId
        ? await api.get(`/api/rams-next-no?projectId=${parseInt(proj.dbId)}`).catch(() => null)
        : null;
      _ramsAssignedNo = next ? next.rams_no : null;
      _ramsRevisionInt = 0;
      _ramsJobIds = [parseInt(job.id)];
      _ramsJobsLocked = false;
    }
  } catch (e) {
    toast('Could not load the RAMS register: ' + e.message, 'error');
    return;
  }
  const mTitle = document.getElementById('ramsModalTitle');
  if (mTitle) mTitle.innerHTML = _ramsEditDoc
    ? `\u{1F4CB} Revise RAMS \u2014 Rev ${_ramsPad(_ramsRevisionInt, 2)}`
    : '\u{1F4CB} Generate RAMS';

  // reset site-plan upload state (image + work-area pin)
  _ramsSitePlanDataUri = null;
  _ramsSitePlanPin = null;
  const prev = document.getElementById('ramsSitePlanPreview');
  if (prev) prev.src = '';
  const spWrap = document.getElementById('ramsSitePlanWrap'); if (spWrap) spWrap.style.display = 'none';
  const spRow  = document.getElementById('ramsSitePlanPinRow'); if (spRow) spRow.style.display = 'none';
  const spInput = document.getElementById('ramsSitePlanInput');
  if (spInput) spInput.value = '';

  // — Header —
  const contractNo = proj?.project_number || proj?.id || '';
  const sr = savedRams;   // saved modal state when revising (may be null)
  setV('ramsContractNo', sr?.contractNo ?? contractNo);
  setV('ramsTitle',      sr?.title ?? (job?.name || proj?.project_name || ''));
  // Doc no: "<project> - 001 - <title>" from the register; legacy fallback if
  // the register was unavailable. Auto-resyncs while the title is edited
  // until the user types into the Doc No box directly.
  setV('ramsDocNo', sr?.docNo || ramsComposeDocNo());
  if (sr?.docNo && sr.docNo !== ramsComposeDocNo()) _ramsDocNoManual = true;
  setV('ramsContract',   sr?.contract ?? (proj?.project_name || proj?.name || ''));
  setV('ramsClient',     sr?.client ?? (proj?.client || ''));
  setV('ramsPrincipal',  sr?.principal ?? (proj?.client || ''));   // default: same as client — editable
  setV('ramsPreparedBy', sr?.preparedBy ?? (_currentDraftsmanName || 'Mateusz Braczyk'));
  setV('ramsDate',       new Date().toISOString().slice(0, 10));
  setV('ramsRev',        _ramsRevisionInt > 0 ? `${_ramsPad(_ramsRevisionInt, 2)} \u2013 Revision` : '00 \u2013 First Issue');
  const tierSel = document.getElementById('ramsTier'); if (tierSel) tierSel.value = sr?.tier || 'complex';
  setV('ramsHours',      sr?.hours ?? '07:30\u201317:00 Monday to Friday (or as directed at site induction)');
  setV('ramsAE',         sr?.ae ?? '');
  setV('ramsScopeText',  (sr?.scopeLines || []).join('\n'));
  setV('ramsTasksText',  sr?.tasks?.length
    ? sr.tasks.map(t => [`${t.title}${t.detail ? ': ' + t.detail : ''}`, ...(t.steps || []).map(s => '- ' + s)].join('\n')).join('\n\n')
    : '');
  setV('ramsNotes',      sr?.notes ?? '');
  setV('ramsWorkBrief',  sr?.workBrief ?? '');
  const rStatus = document.getElementById('ramsScopeStatus'); if (rStatus) rStatus.textContent = '';

  // — Jobs covered (merge picker; locked on revision, with an Edit unlock) —
  ramsRenderJobsList();

  // — Personnel (phase 2b roster picker; falls back to a freeform textarea if
  //   the roster API is unavailable, preserving the old behaviour) —
  ramsInitPersonnel(sr?.personnel || null);

  // — Standard sections (phase 3b pick/add — defaults, or saved state) —
  ramsRenderStandardSections(sr || null);

  // — Risk assessment picker (phase 3c — full library, or saved state) —
  ramsRenderRiskPicker(sr?.risks || null);

  // — Site plan (restored on revision) —
  if (sr?.sitePlanDataUri) {
    _ramsSitePlanDataUri = sr.sitePlanDataUri;
    _ramsSitePlanPin = sr.sitePlanPin || null;
    const img = document.getElementById('ramsSitePlanPreview');
    if (img) { img.src = sr.sitePlanDataUri; }
    const spWrap2 = document.getElementById('ramsSitePlanWrap'); if (spWrap2) spWrap2.style.display = '';
    const spRow2  = document.getElementById('ramsSitePlanPinRow'); if (spRow2) spRow2.style.display = 'flex';
    _ramsPositionSitePlanPin();
  }

  // — Site address (saved state first, then Job Sheet / project / client) —
  const r = _jobSheetResolved(proj);
  setV('ramsSiteName',    sr?.site?.name ?? r.siteName);
  setV('ramsSiteAddr',    sr?.site?.lines ? sr.site.lines.join('\n') : r.lines.join('\n'));
  setV('ramsSiteContact', sr?.site?.contactName ?? r.contact);
  setV('ramsSitePhone',   sr?.site?.contactPhone ?? r.phone);

  // — Drawings picker (union of Site Installation files across selected jobs) —
  await ramsRenderDrawingsList(sr?.drawingRef || null);

  document.getElementById('ramsModal').classList.add('active');
}

// Compose the register doc number: "<project> - 001 - <title>". Falls back to
// the legacy "<project>-RAMS-01" if the register was unavailable at open.
function ramsComposeDocNo() {
  const proj = currentProject;
  const contractNo = proj?.project_number || proj?.id || '';
  const title = (document.getElementById('ramsTitle')?.value || '').trim()
    || (currentJob?.name || '');
  const no = _ramsAssignedNo || 1;   // register unreachable — format stays right, number provisional
  return [contractNo, _ramsPad(no, 3), title].filter(Boolean).join(' - ');
}

// Title input hook — keep the Doc No in sync until it's edited by hand.
function ramsSyncDocNo() {
  if (_ramsDocNoManual) return;
  const el = document.getElementById('ramsDocNo');
  if (el) el.value = ramsComposeDocNo();
}

// ── Jobs-covered picker (merge) ─────────────────────────────────────────────
// New RAMS: all live jobs on the project are tickable, current job pre-ticked.
// Revision: the original job set is LOCKED by default (same document scope);
// "Edit jobs" unlocks it so a job can be added or removed at the new revision.
function ramsRenderJobsList() {
  const wrap = document.getElementById('ramsJobsList');
  if (!wrap) return;
  const proj = currentProject;
  const jobs = (drawingsData.projects?.[proj?.id]?.jobs) || [];
  const lockNote = document.getElementById('ramsJobsLockNote');
  const editBtn  = document.getElementById('ramsJobsEditBtn');
  if (lockNote) lockNote.style.display = (_ramsEditDoc && _ramsJobsLocked) ? '' : 'none';
  if (editBtn)  editBtn.style.display  = (_ramsEditDoc && _ramsJobsLocked) ? '' : 'none';
  if (!jobs.length) {
    wrap.innerHTML = `<div style="color:var(--subtle);font-size:12px;padding:8px 10px">Only this job \u2014 no other jobs on the project.</div>`;
    return;
  }
  wrap.innerHTML = jobs.map(j => {
    const jid = parseInt(j.id);
    const on = _ramsJobIds.includes(jid);
    const dis = _ramsJobsLocked ? 'disabled' : '';
    return `<label style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-bottom:1px solid var(--border);cursor:${_ramsJobsLocked ? 'default' : 'pointer'};opacity:${_ramsJobsLocked && !on ? '.45' : '1'}">
      <input type="checkbox" class="rams-job-check" ${on ? 'checked' : ''} ${dis} value="${jid}"
             onchange="ramsJobTick(${jid}, this.checked)" style="width:14px;height:14px;accent-color:var(--accent)">
      <span style="font-size:12px;color:var(--text)">${escapeHtml(j.name || ('Job ' + jid))}</span>
      ${on && jobs.length > 1 ? `<span style="font-size:10px;color:var(--subtle)">covered</span>` : ''}
    </label>`;
  }).join('');
}

function ramsJobTick(jobId, on) {
  jobId = parseInt(jobId);
  if (on) { if (!_ramsJobIds.includes(jobId)) _ramsJobIds.push(jobId); }
  else _ramsJobIds = _ramsJobIds.filter(x => x !== jobId);
  ramsRenderJobsList();
  ramsRenderDrawingsList();   // drawings union follows the job selection
}

function ramsToggleJobsLock() {
  _ramsJobsLocked = false;
  ramsRenderJobsList();
}

// Union of Site Installation files across every selected job (our own
// generated Site Pack / RAMS output filtered out, deduped by fileId).
async function ramsRenderDrawingsList(savedRef) {
  const drawWrap = document.getElementById('ramsDrawingList');
  if (!drawWrap) return;
  const isGenerated = f => /^(site pack|rams)\b/i.test(String(f.name || f.fileName || ''));
  const _seen = new Set();
  const files = [];
  for (const jid of _ramsJobIds) {
    let siteFiles;
    if (currentJob && parseInt(currentJob.id) === jid) {
      siteFiles = (currentJob.site && currentJob.site.files) || [];
    } else {
      if (!_drawingElementsCache[jid]) { try { await loadJobElementData(jid); } catch (e) {} }
      siteFiles = (_drawingElementsCache[jid]?.files?.['site']) || [];
    }
    for (const f of siteFiles) {
      if (isGenerated(f)) continue;
      const key = f.fileId || (f.name || f.fileName);
      if (_seen.has(key)) continue;
      _seen.add(key);
      files.push(f);
    }
  }
  drawWrap.innerHTML = files.length
    ? files.map(f => {
        const nm = f.name || f.fileName || 'drawing';
        return `<label style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-bottom:1px solid var(--border);cursor:pointer">
          <input type="checkbox" class="rams-draw-check" checked
                 data-fileid="${escapeHtml(f.fileId || '')}" data-driveid="${escapeHtml(f.driveId || '')}"
                 data-fname="${escapeHtml(f.fileName || nm)}" style="width:14px;height:14px;accent-color:var(--accent)">
          <span style="font-size:12px;color:var(--text)">${escapeHtml(nm)}</span>
        </label>`;
      }).join('')
    : `<div style="color:var(--subtle);font-size:12px;padding:8px 0">No drawings in Site Installation yet \u2014 upload one first, or write the scope manually below.</div>`;
  const refNames = [...new Set(files.map(f => f.name || f.fileName).filter(Boolean))];
  const refEl = document.getElementById('ramsDrawingRef');
  if (refEl) refEl.value = savedRef != null ? savedRef : refNames.join(', ');
}

function closeRamsModal() {
  document.getElementById('ramsModal').classList.remove('active');
}

// Preview the uploaded site plan and stash it as a data URI. Phase 5: the
// preview is clickable — the user drops a work-area pin, stored as {x,y} in %
// of the image so it lands in the same spot regardless of render size.
function ramsPreviewSitePlan(input) {
  const file = input && input.files && input.files[0];
  const wrap = document.getElementById('ramsSitePlanWrap');
  const prev = document.getElementById('ramsSitePlanPreview');
  const row  = document.getElementById('ramsSitePlanPinRow');
  _ramsSitePlanPin = null; _ramsPositionSitePlanPin();
  if (!file) {
    _ramsSitePlanDataUri = null;
    if (prev) prev.src = '';
    if (wrap) wrap.style.display = 'none';
    if (row)  row.style.display  = 'none';
    return;
  }
  const reader = new FileReader();
  reader.onload = () => {
    _ramsSitePlanDataUri = reader.result;
    if (prev) prev.src = reader.result;
    if (wrap) wrap.style.display = 'block';
    if (row)  row.style.display  = 'flex';
  };
  reader.readAsDataURL(file);
}

// Click on the preview → store the pin as % coordinates and place the marker.
function ramsSitePlanClick(ev) {
  const img = ev.target;
  const r = img.getBoundingClientRect();
  if (!r.width || !r.height) return;
  const x = ((ev.clientX - r.left) / r.width)  * 100;
  const y = ((ev.clientY - r.top)  / r.height) * 100;
  _ramsSitePlanPin = { x: Math.max(0, Math.min(100, x)), y: Math.max(0, Math.min(100, y)) };
  _ramsPositionSitePlanPin();
}

function ramsClearSitePlanPin() { _ramsSitePlanPin = null; _ramsPositionSitePlanPin(); }

function _ramsPositionSitePlanPin() {
  const mark = document.getElementById('ramsSitePlanPinMark');
  const sts  = document.getElementById('ramsSitePlanPinStatus');
  if (!mark) return;
  if (!_ramsSitePlanPin) {
    mark.style.display = 'none';
    if (sts) sts.textContent = 'Click the plan to mark the work area.';
    return;
  }
  mark.style.display = 'block';
  mark.style.left = _ramsSitePlanPin.x + '%';
  mark.style.top  = _ramsSitePlanPin.y + '%';
  if (sts) sts.textContent = `Work-area pin set (${_ramsSitePlanPin.x.toFixed(0)}%, ${_ramsSitePlanPin.y.toFixed(0)}% of the plan).`;
}

// ─────────────────────────────────────────────────────────────────────────────
// RAMS phase 2b — Site Personnel roster picker
//
// The freeform "Name — Role — Competency" textarea is replaced by a searchable
// tile picker backed by the SitePersonnel roster (+ inline add-person). If the
// roster API is unavailable (e.g. the migration hasn't been run yet) we quietly
// fall back to the old freeform textarea so RAMS is never blocked.
// ─────────────────────────────────────────────────────────────────────────────
let _ramsRoster           = [];    // active personnel [{id,name,site_role,type,company,phone,certs:[]}]
let _ramsCertTypes        = [];     // active cert types [{id,name}]
let _ramsSelectedIds      = [];     // ordered selected personnel ids
let _ramsSelectedPersonnel = [];    // structured selection consumed by the phase-3 renderer
let _ramsRosterAvailable  = false;
let _ramsResultsListenerBound = false;

const _RAMS_FALLBACK_PERSONNEL =
  'Leszek Spychalski \u2014 Project Manager \u2014 CSCS, SMSTS\n' +
  'Jason Lambie \u2014 Site Supervisor \u2014 CSCS, SSSTS\n' +
  'Adrian Smith \u2014 Steel Erector / Installer \u2014 CSCS, CPCS';

function ramsInitPersonnel(savedPersonnel) {
  _ramsSelectedIds = [];
  _ramsSelectedPersonnel = [];
  _ramsSavedPersonnel = Array.isArray(savedPersonnel) ? savedPersonnel : null;
  const search = document.getElementById('ramsPersonnelSearch'); if (search) search.value = '';
  const form   = document.getElementById('ramsAddPersonForm');   if (form) form.style.display = 'none';
  ramsHideResults();
  // Default to showing the picker; the loader flips to the textarea on failure.
  const picker = document.getElementById('ramsPersonnelPicker'); if (picker) picker.style.display = '';
  const ta     = document.getElementById('ramsPersonnel');       if (ta) ta.style.display = 'none';
  // Close the results dropdown when clicking outside the picker (bind once).
  if (!_ramsResultsListenerBound) {
    document.addEventListener('click', (e) => {
      const wrap = document.getElementById('ramsPersonnelPicker');
      if (wrap && !wrap.contains(e.target)) ramsHideResults();
    });
    _ramsResultsListenerBound = true;
  }
  ramsLoadRoster();
}

let _ramsSavedPersonnel = null;   // saved selection to restore on revision

async function ramsLoadRoster() {
  try {
    const [roster, certTypes] = await Promise.all([
      api.get('/api/site-personnel'),
      api.get('/api/cert-types')
    ]);
    _ramsRoster    = Array.isArray(roster) ? roster : [];
    _ramsCertTypes = Array.isArray(certTypes) ? certTypes : [];
    _ramsRosterAvailable = true;

    if (_ramsSavedPersonnel && _ramsSavedPersonnel.length) {
      // Revision: restore the saved selection — by id, name fallback.
      _ramsSelectedIds = _ramsSavedPersonnel
        .map(sp => _ramsRoster.find(p => (sp.id && p.id === sp.id) || p.name === sp.name)?.id)
        .filter(Boolean);
    } else {
      // Preselect the known site crew (matches the old textarea defaults).
      const preferred = ['Leszek Spychalski', 'Jason Lambie', 'Adrian Smith'];
      _ramsSelectedIds = _ramsRoster
        .filter(p => preferred.includes(p.name))
        .sort((a, b) => preferred.indexOf(a.name) - preferred.indexOf(b.name))
        .map(p => p.id);
    }

    ramsPopulateEmployeeDropdown();
    ramsRenderCertCheckboxes();
    ramsRenderTiles();
  } catch (e) {
    // Roster unavailable — reveal the freeform textarea with the old defaults.
    _ramsRosterAvailable = false;
    const picker = document.getElementById('ramsPersonnelPicker'); if (picker) picker.style.display = 'none';
    const ta = document.getElementById('ramsPersonnel');
    if (ta) { ta.style.display = ''; if (!ta.value.trim()) ta.value = _RAMS_FALLBACK_PERSONNEL; }
  }
}

function ramsHideResults() {
  const res = document.getElementById('ramsPersonnelResults');
  if (res) { res.style.display = 'none'; res.innerHTML = ''; }
}

function _ramsPersonById(id) { return _ramsRoster.find(p => p.id === id); }

function _ramsCertNames(p) {
  return (p.certs || []).map(c => c.cert_type).filter(Boolean);
}

function ramsRenderTiles() {
  const wrap = document.getElementById('ramsPersonnelTiles');
  if (!wrap) return;
  if (!_ramsSelectedIds.length) {
    wrap.innerHTML = '<span style="font-size:12px;color:var(--subtle)">No one added yet — search the roster or add a person.</span>';
  } else {
    wrap.innerHTML = _ramsSelectedIds.map(id => {
      const p = _ramsPersonById(id);
      if (!p) return '';
      const certs = _ramsCertNames(p);
      const sub = p.type === 'subcontractor' && p.company ? ` · ${escapeHtml(p.company)}` : '';
      const role = p.site_role ? escapeHtml(p.site_role) : '<span style="color:var(--subtle)">no role set</span>';
      return `<span style="display:inline-flex;align-items:center;gap:8px;padding:6px 10px;border:1px solid var(--border);border-radius:20px;background:var(--bg-darker);font-size:12px">
        <span><b>${escapeHtml(p.name)}</b> — ${role}${sub}${certs.length ? ` <span style="color:var(--muted)">(${escapeHtml(certs.join(', '))})</span>` : ''}</span>
        <span onclick="ramsRemovePerson(${p.id})" title="Remove" style="cursor:pointer;color:var(--muted);font-weight:700">&times;</span>
      </span>`;
    }).join('');
  }
  ramsSerializePersonnel();
}

// Keep a structured selection for the phase-3 renderer AND a human-readable
// summary in the (hidden) textarea so nothing downstream breaks today.
function ramsSerializePersonnel() {
  _ramsSelectedPersonnel = _ramsSelectedIds.map(id => {
    const p = _ramsPersonById(id);
    if (!p) return null;
    return {
      id: p.id, name: p.name, site_role: p.site_role || '',
      type: p.type || 'staff', company: p.company || '', phone: p.phone || '',
      certs: _ramsCertNames(p)
    };
  }).filter(Boolean);
  const ta = document.getElementById('ramsPersonnel');
  if (ta) {
    ta.value = _ramsSelectedPersonnel.map(p => {
      const bits = [p.name, p.site_role || '(role TBC)'];
      const comp = p.type === 'subcontractor' && p.company ? `${p.company}` : '';
      const certs = p.certs.length ? p.certs.join(', ') : '';
      return [bits.join(' \u2014 '), comp, certs].filter(Boolean).join(' \u2014 ');
    }).join('\n');
  }
}

function ramsFilterRoster(term) {
  const res = document.getElementById('ramsPersonnelResults');
  if (!res) return;
  const t = String(term || '').trim().toLowerCase();
  const pool = _ramsRoster.filter(p => !_ramsSelectedIds.includes(p.id));
  const matches = (t
    ? pool.filter(p =>
        (p.name || '').toLowerCase().includes(t) ||
        (p.site_role || '').toLowerCase().includes(t) ||
        (p.company || '').toLowerCase().includes(t))
    : pool).slice(0, 30);
  if (!matches.length) {
    res.innerHTML = `<div style="padding:8px 10px;font-size:12px;color:var(--subtle)">${_ramsRoster.length ? 'No matches — try “Add person”.' : 'Roster is empty — add a person.'}</div>`;
  } else {
    res.innerHTML = matches.map(p => {
      const certs = _ramsCertNames(p);
      const badge = p.type === 'subcontractor'
        ? `<span style="font-size:10px;color:#a78bfa;border:1px solid rgba(139,92,246,.4);border-radius:4px;padding:1px 5px;margin-left:6px">SUB${p.company ? ' · ' + escapeHtml(p.company) : ''}</span>`
        : '';
      return `<div onclick="ramsSelectPerson(${p.id})" style="padding:8px 10px;border-bottom:1px solid var(--border);cursor:pointer;font-size:12px">
        <b>${escapeHtml(p.name)}</b>${badge}
        <div style="color:var(--muted);font-size:11px">${escapeHtml(p.site_role || 'no role set')}${certs.length ? ' · ' + escapeHtml(certs.join(', ')) : ''}</div>
      </div>`;
    }).join('');
  }
  res.style.display = 'block';
}

function ramsSelectPerson(id) {
  id = parseInt(id);
  if (!_ramsSelectedIds.includes(id)) _ramsSelectedIds.push(id);
  const search = document.getElementById('ramsPersonnelSearch'); if (search) search.value = '';
  ramsHideResults();
  ramsRenderTiles();
}

function ramsRemovePerson(id) {
  id = parseInt(id);
  _ramsSelectedIds = _ramsSelectedIds.filter(x => x !== id);
  ramsRenderTiles();
}

// ── inline add-person form ─────────────────────────────────────────────────────
function ramsToggleAddPerson() {
  const form = document.getElementById('ramsAddPersonForm');
  if (!form) return;
  const opening = form.style.display === 'none';
  form.style.display = opening ? 'block' : 'none';
  if (opening) {
    ['ramsNpName','ramsNpRole','ramsNpCompany','ramsNpPhone','ramsNpNewCertType'].forEach(id => {
      const el = document.getElementById(id); if (el) el.value = '';
    });
    const typeSel = document.getElementById('ramsNpType'); if (typeSel) typeSel.value = 'staff';
    const emp = document.getElementById('ramsNpEmployee'); if (emp) emp.value = '';
    ramsToggleCompany();
    ramsPopulateEmployeeDropdown();
    ramsRenderCertCheckboxes();
    const sts = document.getElementById('ramsNpStatus'); if (sts) sts.textContent = '';
  }
}

function ramsToggleCompany() {
  const type = document.getElementById('ramsNpType')?.value || 'staff';
  const wrap = document.getElementById('ramsNpCompanyWrap');
  if (wrap) wrap.style.display = type === 'subcontractor' ? '' : 'none';
}

function ramsPopulateEmployeeDropdown() {
  const sel = document.getElementById('ramsNpEmployee');
  if (!sel) return;
  const emps = (state?.timesheetData?.employees || []).slice().sort((a, b) => (a.name || '').localeCompare(b.name || ''));
  sel.innerHTML = '<option value="">\u2014 choose an employee \u2014</option>' +
    emps.map(e => `<option value="${e.id}">${escapeHtml(e.name)}</option>`).join('');
}

function ramsPullFromEmployee(empId) {
  if (!empId) return;
  const name = (typeof empNameById === 'function') ? empNameById(parseInt(empId)) : null;
  const nameInput = document.getElementById('ramsNpName');
  if (name && nameInput) nameInput.value = name;
  const typeSel = document.getElementById('ramsNpType'); if (typeSel) { typeSel.value = 'staff'; ramsToggleCompany(); }
}

function ramsRenderCertCheckboxes() {
  const wrap = document.getElementById('ramsNpCerts');
  if (!wrap) return;
  if (!_ramsCertTypes.length) {
    wrap.innerHTML = '<span style="font-size:11px;color:var(--subtle)">No cert types yet — add one below.</span>';
    return;
  }
  wrap.innerHTML = _ramsCertTypes.map(ct =>
    `<label style="display:inline-flex;align-items:center;gap:5px;font-size:11px;border:1px solid var(--border);border-radius:6px;padding:3px 8px;cursor:pointer">
      <input type="checkbox" class="rams-np-cert" value="${escapeHtml(ct.name)}" style="width:12px;height:12px;accent-color:var(--accent)">
      ${escapeHtml(ct.name)}
    </label>`).join('');
}

async function ramsAddCertType() {
  const input = document.getElementById('ramsNpNewCertType');
  const name = (input?.value || '').trim();
  const sts = document.getElementById('ramsNpStatus');
  if (!name) return;
  try {
    const ct = await api.post('/api/cert-types', { name });
    if (!_ramsCertTypes.some(x => x.name === ct.name)) _ramsCertTypes.push(ct);
    _ramsCertTypes.sort((a, b) => (a.sort_order || 99) - (b.sort_order || 99) || a.name.localeCompare(b.name));
    if (input) input.value = '';
    ramsRenderCertCheckboxes();
    if (sts) { sts.style.color = 'var(--muted)'; sts.textContent = `Added cert type “${ct.name}”.`; }
  } catch (e) {
    if (sts) { sts.style.color = 'var(--red)'; sts.textContent = 'Could not add cert type: ' + e.message; }
  }
}

async function ramsSubmitNewPerson() {
  const sts = document.getElementById('ramsNpStatus');
  const name = (document.getElementById('ramsNpName')?.value || '').trim();
  if (!name) { if (sts) { sts.style.color = 'var(--red)'; sts.textContent = 'Name is required.'; } return; }
  const type = document.getElementById('ramsNpType')?.value === 'subcontractor' ? 'subcontractor' : 'staff';
  const empSel = document.getElementById('ramsNpEmployee');
  const certs = [...document.querySelectorAll('.rams-np-cert:checked')].map(c => c.value);
  const payload = {
    name,
    site_role: (document.getElementById('ramsNpRole')?.value || '').trim(),
    type,
    company:   type === 'subcontractor' ? (document.getElementById('ramsNpCompany')?.value || '').trim() : '',
    phone:     (document.getElementById('ramsNpPhone')?.value || '').trim(),
    employee_id: (type === 'staff' && empSel?.value) ? parseInt(empSel.value) : null,
    certs
  };
  if (sts) { sts.style.color = 'var(--muted)'; sts.textContent = 'Saving…'; }
  try {
    const person = await api.post('/api/site-personnel', payload);
    _ramsRoster.push(person);
    _ramsRoster.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    ramsSelectPerson(person.id);
    ramsToggleAddPerson();
  } catch (e) {
    if (sts) { sts.style.color = 'var(--red)'; sts.textContent = 'Could not save: ' + e.message; }
  }
}

// Phase 2 — AI reads the ticked drawing(s) and drafts BOTH the Scope of Works
// and the Sequence of Works (tasks) into their textareas.
// Two-engine principle (same as QB / Site Pack): the AI READS the drawing and
// describes what/how — it NEVER computes quantities, dimensions or weights. On
// any failure a deterministic template is dropped in so the user is never
// blocked. Mirrors sitePackGenerateScope (429 retry + fallback).
async function ramsGenerateScope() {
  const checks  = [...document.querySelectorAll('.rams-draw-check:checked')];
  const btn     = document.getElementById('ramsGenScopeBtn');
  const sts     = document.getElementById('ramsScopeStatus');
  const scopeTa = document.getElementById('ramsScopeText');
  const tasksTa = document.getElementById('ramsTasksText');
  if (!scopeTa || !tasksTa) return;

  const contract  = (document.getElementById('ramsContract')?.value   || '').trim();
  const title     = (document.getElementById('ramsTitle')?.value      || '').trim();
  const client    = (document.getElementById('ramsClient')?.value     || '').trim();
  const principal = (document.getElementById('ramsPrincipal')?.value  || '').trim();
  const drawRef   = (document.getElementById('ramsDrawingRef')?.value || '').trim();
  const tier      = (document.getElementById('ramsTier')?.value       || 'complex');

  if (!checks.length) {
    if (sts) { sts.style.color = 'var(--red)'; sts.textContent = 'Tick at least one drawing to read (or write the scope & sequence manually).'; }
    return;
  }
  if (btn) { btn.disabled = true; btn.style.opacity = '.5'; }
  if (sts) { sts.style.color = 'var(--muted)'; sts.textContent = 'Reading drawing\u2026'; }

  // Build the drawing content blocks (reuse the site-pack fetch/media helpers —
  // the .rams-draw-check checkboxes carry the same data-fileid/driveid/fname).
  const blocks = [];
  try {
    for (const c of checks) {
      const b64 = await _sitePackFetchBase64(c.dataset.fileid, c.dataset.driveid);
      const mt  = _sitePackMediaType(c.dataset.fname);
      blocks.push(mt.isImage
        ? { type: 'image',    source: { type: 'base64', media_type: mt.media, data: b64 } }
        : { type: 'document', source: { type: 'base64', media_type: mt.media, data: b64 }, title: c.dataset.fname });
    }
  } catch (e) {
    if (sts) { sts.style.color = 'var(--red)'; sts.textContent = 'Could not load drawing: ' + e.message; }
    if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
    return;
  }

  // Tier nudges how much sequencing detail we ask for. The full tier -> document
  // depth wiring lives in the PDF renderer (phase 4); here it only sets the
  // rough number of scope points / sequence tasks.
  const tierRule = tier === 'brief'
    ? 'Keep it lean: 3-5 scope points and 4-6 sequence tasks. Each task needs only its one-sentence intro \u2014 leave every "steps" array empty.'
    : tier === 'tier1'
      ? 'Be thorough for a Tier-1 principal contractor: 5-8 scope points and 7-10 sequence tasks. Every task MUST carry 4-7 "steps" \u2014 concrete, auditable actions (preparation, positioning, fixing, alignment checks, safety/QA) exactly like a full professional method statement.'
      : 'Standard depth: 4-7 scope points and 6-8 sequence tasks covering mobilisation through to completion. Every task MUST carry 3-5 "steps" \u2014 the concrete actions carried out in that stage.';

  const systemPrompt = `You are a site-installation planner for BAMA Fabrication, a structural steel fabricator in Peterborough, drafting the works description for a RAMS (Risk Assessment & Method Statement). Read the supplied drawing(s) and produce (1) a SCOPE OF WORKS and (2) a SEQUENCE OF WORKS for the installation crew.\n\nYou are a READER, not a calculator: describe WHAT is to be installed and HOW it is fixed and sequenced, based on what the drawing shows. Do NOT invent or calculate quantities, dimensions, member counts or weights that are not shown on the drawing. If something is not shown, describe it generically rather than guessing a number.`;

  const userPrompt = `Contract / project: ${contract || '(unspecified)'}
Works title: ${title || '(unspecified)'}
Client: ${client || '(unspecified)'}    Principal contractor: ${principal || '(unspecified)'}
Drawing reference: ${drawRef || '(see attached)'}

Read the attached drawing(s) and draft the works description for the RAMS.
${tierRule}

Return ONLY a JSON object, no preamble and no Markdown fences, in exactly this shape:
{
  "scope": ["short scope point", "..."],
  "tasks": [{ "title": "Stage title", "intro": "one concise sentence summarising the stage", "steps": ["concrete action carried out in this stage", "..."] }]
}

RULES:
- "scope" = plain WHAT-works-are-being-carried-out points (one clause each, NO leading numbers — the renderer numbers them). Match the nature of the works (install / remove / alter) exactly. Reference the drawing where relevant.
- "tasks" = the ordered SEQUENCE OF WORKS. "title" is a short stage title, "intro" one summary sentence, "steps" the ordered concrete actions within that stage (the renderer letters them a. b. c.). Start with mobilisation / site set-up and end with demobilisation / handover, with the real work stages in between — installation: setting out, lifting & positioning, fixing, bolting-up, checking; removal: services/isolation checks, temporary support & stability checks, cutting & dismantling, lowering & removing sections, waste segregation, making good.
- Strictly UK English, concise, imperative in the task detail ("Install\u2026", "Set out\u2026", "Cut\u2026", "Remove\u2026", "Lower\u2026").
- Do NOT invent quantities or dimensions not shown on the drawing.
- Output valid JSON only.`;

  try {
    const requestBody = {
      model: 'claude-sonnet-4-6', max_tokens: 4000, system: systemPrompt,
      messages: [{ role: 'user', content: [ ...blocks, { type: 'text', text: userPrompt } ] }]
    };
    const doFetch = () => fetch(API_BASE + '/api/claude-proxy', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${sessionStorage.getItem('bama_token')}` },
      body: JSON.stringify(requestBody)
    });
    let response = await doFetch();
    let data = await response.json();
    if (response.status === 429) {
      if (sts) sts.textContent = 'Rate limit \u2014 waiting 30s before retry\u2026';
      await new Promise(r => setTimeout(r, 30000));
      response = await doFetch(); data = await response.json();
      if (response.status === 429) throw new Error('still rate limited \u2014 wait a minute and retry');
    }
    if (data.error) throw new Error(data.error.message);
    const rawText = (data.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
    if (!rawText) throw new Error('empty response');

    // Strip any ```json fences, then parse. Fall back to first {...} block.
    const jsonStr = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
    let parsed;
    try { parsed = JSON.parse(jsonStr); }
    catch (_) {
      const m = jsonStr.match(/\{[\s\S]*\}/);
      if (!m) throw new Error('could not parse AI response');
      parsed = JSON.parse(m[0]);
    }
    const scopeArr = Array.isArray(parsed.scope) ? parsed.scope.map(s => String(s).trim()).filter(Boolean) : [];
    // Tasks may be strings (legacy "Title: detail") or {title, intro, steps[]}.
    // Textarea format: title line ("Title: intro"), then one "- step" line per
    // sub-step, blank line between tasks \u2014 fully hand-editable.
    const fmtTask = t => {
      if (t == null) return '';
      if (typeof t === 'string') return t.trim();
      const head = [String(t.title || '').trim(), String(t.intro || t.detail || '').trim()].filter(Boolean).join(': ');
      const steps = Array.isArray(t.steps) ? t.steps.map(s => String(s).trim()).filter(Boolean).map(s => '- ' + s) : [];
      return [head, ...steps].filter(Boolean).join('\n');
    };
    const tasksArr = Array.isArray(parsed.tasks) ? parsed.tasks.map(fmtTask).filter(Boolean) : [];
    if (!scopeArr.length && !tasksArr.length) throw new Error('no scope or tasks returned');

    if (scopeArr.length) scopeTa.value = scopeArr.join('\n');
    if (tasksArr.length) tasksTa.value = tasksArr.join('\n\n');
    if (sts) { sts.style.color = '#3ecf8e'; sts.textContent = 'Scope & sequence drafted from the drawing \u2014 edit as needed.'; }
  } catch (e) {
    // Deterministic fallback so the user is never blocked. Only fill empty
    // fields so we don't clobber anything the user already typed. The template
    // is INSTALLATION-shaped, so it's skipped when a Work Brief is set (a
    // removal brief + install template would be worse than an empty box).
    if (!brief && !scopeTa.value.trim()) {
      scopeTa.value = [
        `Install ${title || contract || 'the fabricated steelwork'} as per drawing ${drawRef || '(see RAMS)'}.`,
        'Fix all items to the structure / substrate as detailed on the drawing.',
        'Provide all connections, splices and bolted joints as shown.'
      ].join('\n');
    }
    if (!brief && !tasksTa.value.trim()) {
      tasksTa.value = [
        'Mobilisation & site set-up: attend induction, stage materials and establish the work area.',
        '- Attend the site-specific induction and agree access, welfare and storage with the principal contractor.',
        '- Deliver and stage all fabricated items, fixings and equipment in the designated area.',
        '- Erect barriers and signage to segregate the installation zone.',
        '',
        'Setting out: verify dimensions and mark fixing positions before any work starts.',
        '- Check reference lines and levels on site against the issued drawing.',
        '- Mark all fixing / baseplate positions and confirm squareness and centres.',
        '- Scan the structure for concealed services before drilling.',
        '',
        'Lift & position: lift members into place using suitable lifting equipment.',
        '- Plan each lift and prepare the landing area before lifting.',
        '- Lift members into position using approved equipment and secure temporarily.',
        '- Maintain exclusion zones \u2014 no personnel beneath suspended loads.',
        '',
        'Fixing & bolting-up: make all permanent connections.',
        '- Install all bolts / anchors as detailed on the drawing.',
        '- Tighten fixings incrementally and in a balanced pattern.',
        '- Torque all bolts to the specified values and record as required.',
        '',
        'Checking: verify the completed installation.',
        '- Check line, level, plumb and diagonals across the complete assembly.',
        '- Verify all connections are complete and the finish is free from damage.',
        '',
        'Demobilisation & handover: clear the work area and hand back to site.',
        '- Remove all tools, temporary works and waste from the work area.',
        '- Present the completed works to the principal contractor for inspection and sign-off.'
      ].join('\n');
    }
    if (sts) { sts.style.color = 'var(--muted)'; sts.textContent = brief
      ? 'AI unavailable (' + e.message + ') \u2014 standard install template skipped because a Work Brief is set; write the scope & sequence manually or retry.'
      : 'AI unavailable \u2014 inserted a standard template (' + e.message + '). Edit as needed.'; }
  }
  if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
}

// ── Import an externally-produced RAMS (e.g. drafted in chat) ───────────────
// Flow: pick the PDF → the normal RAMS modal opens (next register number) →
// the AI parses the document into the modal fields for an EYEBALL CHECK →
// Generate re-renders it in the house template and registers it, so future
// revisions happen in-system like any other RAMS. Two-engine: the AI only
// READS the document; risk rows are MATCHED against RAMS_RISK_LIBRARY by
// meaning (refs only) — scores and control wording always come from the
// library, never from the imported document. Hazards with no library match
// are reported for a manual ＋ custom-risk add.
function importRamsDoc() {
  if (!currentJob?.id) { toast('Open a job first.', 'error'); return; }
  let input = document.getElementById('ramsImportInput');
  if (!input) {
    input = document.createElement('input');
    input.type = 'file'; input.accept = '.pdf,application/pdf';
    input.id = 'ramsImportInput'; input.style.display = 'none';
    document.body.appendChild(input);
  }
  input.value = '';
  input.onchange = async () => {
    const file = input.files && input.files[0];
    if (!file) return;
    if (!/\.pdf$/i.test(file.name)) { toast('Import a PDF — export the chat RAMS as PDF first.', 'error'); return; }
    try { await openRamsModal(); } catch (e) { return; }
    _ramsParseImport(file);
  };
  input.click();
}

async function _ramsParseImport(file) {
  const sts = document.getElementById('ramsScopeStatus');
  const btn = document.getElementById('ramsGenScopeBtn');
  if (btn) { btn.disabled = true; btn.style.opacity = '.5'; }
  if (sts) { sts.style.color = 'var(--muted)'; sts.textContent = 'Reading imported RAMS "' + file.name + '"\u2026'; }
  try {
    const b64 = await new Promise((res, rej) => {
      const r = new FileReader();
      r.onload = () => res(String(r.result).split(',')[1]);
      r.onerror = () => rej(new Error('could not read file'));
      r.readAsDataURL(file);
    });
    const libDigest = RAMS_RISK_LIBRARY.map(r => `${r.ref}: ${r.activity} \u2014 ${r.hazard}`).join('\n');
    const systemPrompt = `You are reading an existing RAMS (Risk Assessment & Method Statement) document for BAMA Fabrication, a structural steel fabricator, so it can be re-issued from their document system. You are a READER: extract only what the document states — never invent, recalculate or embellish. Keep the document's intent exactly (installation vs removal vs alteration of structure). Where a field is not present, return null (or an empty array).`;
    const userPrompt = `Extract the RAMS content from the attached document and return ONLY a JSON object, no preamble and no Markdown fences, in exactly this shape:
{
  "title": "works title or null",
  "client": "client name or null",
  "principal": "principal contractor name or null",
  "drawingRef": "drawing reference(s) or null",
  "hours": "working-hours line or null",
  "workBrief": "one or two sentences stating what the works actually are (nature of works, key methods/tools, exclusions), or null",
  "scope": ["scope of works point", "..."],
  "tasks": [{ "title": "Stage title", "intro": "one concise sentence summarising the stage", "steps": ["concrete action in this stage", "..."] }],
  "personnel": ["Full Name", "..."],
  "libraryRefs": ["R01", "..."],
  "extraHazards": ["hazard assessed in the document with NO library match (short title)", "..."],
  "notes": "any additional notes / special requirements, or null"
}
RULES:
- "scope" and "tasks" come from the document's Scope of Works and Method Statement / Sequence of Works, reworded only as much as needed to fit the shape.
- "libraryRefs": BAMA's curated risk library is listed below. Return the refs whose activity/hazard matches a risk assessed in the document — match on MEANING, not exact wording. Do NOT return refs for hazards the document does not cover.
- "extraHazards": hazards the document assesses that have no matching library row.
- Strictly UK English. Output valid JSON only.

BAMA RISK LIBRARY:
${libDigest}`;
    const requestBody = {
      model: 'claude-sonnet-4-6', max_tokens: 6000, system: systemPrompt,
      messages: [{ role: 'user', content: [
        { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 }, title: file.name },
        { type: 'text', text: userPrompt }
      ] }]
    };
    const doFetch = () => fetch(API_BASE + '/api/claude-proxy', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${sessionStorage.getItem('bama_token')}` },
      body: JSON.stringify(requestBody)
    });
    let response = await doFetch();
    let data = await response.json();
    if (response.status === 429) {
      if (sts) sts.textContent = 'Rate limit \u2014 waiting 30s before retry\u2026';
      await new Promise(r => setTimeout(r, 30000));
      response = await doFetch(); data = await response.json();
      if (response.status === 429) throw new Error('still rate limited \u2014 wait a minute and retry');
    }
    if (data.error) throw new Error(data.error.message);
    const rawText = (data.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
    if (!rawText) throw new Error('empty response');
    const jsonStr = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
    let p;
    try { p = JSON.parse(jsonStr); }
    catch (_) {
      const m = jsonStr.match(/\{[\s\S]*\}/);
      if (!m) throw new Error('could not parse AI response');
      p = JSON.parse(m[0]);
    }

    // ── Fill the modal (only where the document actually had something) ──
    const setIf = (id, v) => { if (v) { const el = document.getElementById(id); if (el) el.value = String(v).trim(); } };
    setIf('ramsTitle', p.title); ramsSyncDocNo();
    setIf('ramsClient', p.client);
    setIf('ramsPrincipal', p.principal);
    setIf('ramsDrawingRef', p.drawingRef);
    setIf('ramsHours', p.hours);
    setIf('ramsWorkBrief', p.workBrief);
    setIf('ramsNotes', p.notes);
    if (Array.isArray(p.scope) && p.scope.length) {
      const ta = document.getElementById('ramsScopeText');
      if (ta) ta.value = p.scope.map(s => String(s).trim()).filter(Boolean).join('\n');
    }
    if (Array.isArray(p.tasks) && p.tasks.length) {
      const ta = document.getElementById('ramsTasksText');
      const fmtTask = t => {
        if (t == null) return '';
        if (typeof t === 'string') return t.trim();
        const head = [String(t.title || '').trim(), String(t.intro || t.detail || '').trim()].filter(Boolean).join(': ');
        const steps = Array.isArray(t.steps) ? t.steps.map(s => String(s).trim()).filter(Boolean).map(s => '- ' + s) : [];
        return [head, ...steps].filter(Boolean).join('\n');
      };
      if (ta) ta.value = p.tasks.map(fmtTask).filter(Boolean).join('\n\n');
    }
    // Personnel: restore-by-name against the roster (same path as a revision);
    // names not on the roster simply stay unticked for a manual add.
    if (Array.isArray(p.personnel) && p.personnel.length) {
      ramsInitPersonnel(p.personnel.map(n => ({ name: String(n).trim() })).filter(x => x.name));
    }
    // Risks: matched library refs come back TICKED, the rest unticked (same
    // render path as a revision) — scores/controls stay 100% library.
    const refs = new Set(Array.isArray(p.libraryRefs) ? p.libraryRefs.map(String) : []);
    const matched = RAMS_RISK_LIBRARY.filter(r => refs.has(r.ref)).map(r => ({ ...r, controls: (r.controls || []).slice() }));
    if (matched.length) ramsRenderRiskPicker(matched);

    const extras = (Array.isArray(p.extraHazards) ? p.extraHazards : []).map(s => String(s).trim()).filter(Boolean);
    if (sts) {
      sts.style.color = extras.length ? '#e0a800' : '#3ecf8e';
      sts.textContent = `Imported \u2014 check every field, then Generate to file & register it. ${matched.length} risk row${matched.length === 1 ? '' : 's'} matched to the library.`
        + (extras.length ? ` NO library match (add via \uFF0B custom risk if needed): ${extras.join('; ')}.` : '');
    }
    toast('RAMS imported into the form \u2014 review and Generate to register it.', 'success');
  } catch (e) {
    if (sts) { sts.style.color = 'var(--red)'; sts.textContent = 'Import failed (' + e.message + ') \u2014 fill the form manually.'; }
  } finally {
    if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// RAMS phase 3 — native jsPDF renderer + curated hazard library
// ───────────────────────────────────────────────────────────────────────────
// Modelled 1:1 on drawDnPDF / drawSitePackPDF: everything is drawn natively
// (doc.text / doc.rect / doc.addImage) so the live dark bama.css NEVER leaks
// into the capture — no html2canvas, no blank/clipped output. Two-engine
// principle: the L/S/R scores and control wording in RAMS_RISK_LIBRARY are a
// CURATED library (seeded from BAMA's example RAMS). The AI never invents
// scores or control text; at most (later phase) it selects which rows apply and
// tailors the "when/where" note. Every value here is tunable.
// SharePoint save + the 'rams' drawing-elements context shipped in phase 6; this
// phase renders the PDF and opens it for review.
// ═══════════════════════════════════════════════════════════════════════════

const _RAMS_R_OPS = 'Operatives';
const _RAMS_R_OPS_OTH = 'Operatives, others on site';
const _RAMS_R_ALL = 'Operatives, others on site, public';

// Curated hazard library for structural-steel site installation.
// ref, activity, hazard, who, iL/iS (initial L/S, R = L×S), controls[],
// rL/rS (residual), whenWhere.
const RAMS_RISK_LIBRARY = [
  { ref: 'R01', activity: 'General site work / mobilisation', hazard: 'Slips, trips and falls on the level', who: _RAMS_R_OPS_OTH, iL: 3, iS: 3,
    controls: ['Maintain good housekeeping; keep access routes and work areas clear.', 'Route and secure trailing leads and hoses off walkways.', 'Report and clear spillages and debris immediately.', 'Suitable footwear worn; adequate task lighting provided.'],
    rL: 1, rS: 3, whenWhere: 'Throughout the works' },
  { ref: 'R02', activity: 'Handling steel sections, fixings & equipment', hazard: 'Manual handling injury / musculoskeletal strain', who: _RAMS_R_OPS, iL: 3, iS: 3,
    controls: ['Use mechanical lifting aids wherever practicable.', 'Team lifts for awkward or heavy loads; loads split where possible.', 'Manual-handling assessment carried out; good kinetic technique used.', 'Handling gloves worn.'],
    rL: 2, rS: 2, whenWhere: 'Loading, offloading and positioning' },
  { ref: 'R03', activity: 'Erection and fixing at height', hazard: 'Fall from height', who: _RAMS_R_OPS, iL: 4, iS: 5,
    controls: ['MEWP, scaffold or edge protection used as the primary means of access.', 'Harness and lanyard clipped to a suitable anchor when in a MEWP or where edge protection is incomplete.', 'Access equipment inspected before use and within thorough-examination date.', 'No work at height in adverse weather; area below cordoned off.'],
    rL: 2, rS: 5, whenWhere: 'All elevated works' },
  { ref: 'R04', activity: 'Use of MEWP / cherry picker', hazard: 'Overturn, entrapment, ejection or collapse', who: _RAMS_R_OPS, iL: 3, iS: 5,
    controls: ['IPAF-trained and certified operators only.', 'Daily pre-use checks; LOLER thorough examination in date.', 'Ground assessed for bearing capacity and level; outriggers deployed where fitted.', 'Harness worn; no overreaching; secondary guarding used where available; rescue plan in place.'],
    rL: 1, rS: 5, whenWhere: 'During elevated access' },
  { ref: 'R05', activity: 'Lifting operations (crane / telehandler)', hazard: 'Falling load, struck-by, load failure', who: _RAMS_R_OPS_OTH, iL: 3, iS: 5,
    controls: ['Lift plan prepared and supervised by an appointed person.', 'Trained slinger / signaller and plant operator; SWL never exceeded.', 'Exclusion zone established; no persons beneath a suspended load.', 'Tag lines used to control loads; landing area prepared before lift.'],
    rL: 1, rS: 5, whenWhere: 'During all mechanical lifts' },
  { ref: 'R06', activity: 'Use of lifting accessories', hazard: 'Sling / shackle / chain failure', who: _RAMS_R_OPS, iL: 2, iS: 5,
    controls: ['Colour-coded, in-date, LOLER-inspected accessories only.', 'Correct rating and sling angle selected for the load.', 'Pre-use visual check; damaged gear quarantined and removed.'],
    rL: 1, rS: 5, whenWhere: 'During all mechanical lifts' },
  { ref: 'R07', activity: 'Hot works — welding, grinding, cutting', hazard: 'Fire, burns, arc-eye, welding fume', who: _RAMS_R_OPS_OTH, iL: 3, iS: 4,
    controls: ['Hot-works permit obtained where required by the site.', 'Combustibles removed or screened; fire extinguisher to hand.', 'Fire watch maintained and a 60-minute post-works check carried out.', 'Welding screens, local extraction / RPE for fume, and full welding PPE used by competent welders.'],
    rL: 1, rS: 4, whenWhere: 'During on-site welding / cutting' },
  { ref: 'R08', activity: 'Use of hand and power tools', hazard: 'Cuts, entanglement, HAVS, ejected particles', who: _RAMS_R_OPS, iL: 3, iS: 3,
    controls: ['Correct tool for the task, inspected and PAT tested; guards fitted.', 'Trained operators only; HAVS trigger-time managed.', 'Eye and hearing protection worn; 110V or battery tools preferred.'],
    rL: 1, rS: 3, whenWhere: 'During cutting / drilling / grinding' },
  { ref: 'R09', activity: 'Temporary electrics on site', hazard: 'Electric shock or burns', who: _RAMS_R_OPS, iL: 2, iS: 4,
    controls: ['110V CTE or battery tools used; equipment and leads PAT tested.', 'No damaged cables; RCD protection provided.', 'Leads routed off the ground; generators sited and earthed correctly.'],
    rL: 1, rS: 4, whenWhere: 'Throughout the works' },
  { ref: 'R10', activity: 'Working above others / open edges', hazard: 'Falling objects striking persons below', who: _RAMS_R_ALL, iL: 3, iS: 4,
    controls: ['Exclusion zone / barriers beneath elevated works.', 'Tool tethers / lanyards used at height; no loose materials left at edges.', 'Toe-boards or netting provided where applicable; hard hats worn.'],
    rL: 1, rS: 4, whenWhere: 'During work at height' },
  { ref: 'R11', activity: 'Site traffic and plant movement', hazard: 'Collision or crush by vehicles / MHE', who: _RAMS_R_ALL, iL: 2, iS: 5,
    controls: ['Segregate pedestrians from vehicles; follow the site traffic plan.', 'Banksman for reversing and blind manoeuvres.', 'Hi-vis worn; agreed routes and speed limits observed.'],
    rL: 1, rS: 5, whenWhere: 'During deliveries and plant use' },
  { ref: 'R12', activity: 'Handling fabricated steel', hazard: 'Lacerations from sharp edges and swarf', who: _RAMS_R_OPS, iL: 3, iS: 2,
    controls: ['Cut-resistant gloves worn; edges deburred.', 'Swarf and offcuts cleared regularly.', 'Care taken handling long or awkward sections.'],
    rL: 1, rS: 2, whenWhere: 'During handling and fixing' },
  { ref: 'R13', activity: 'Grinding / cutting / impact', hazard: 'Noise-induced hearing damage', who: _RAMS_R_OPS, iL: 3, iS: 3,
    controls: ['Hearing protection worn in designated noisy areas.', 'Exposure time reduced; low-noise methods used where practicable.'],
    rL: 1, rS: 2, whenWhere: 'During noisy operations' },
  { ref: 'R14', activity: 'Grinding dust, weld fume, coatings (COSHH)', hazard: 'Respiratory irritation / exposure to substances', who: _RAMS_R_OPS, iL: 3, iS: 3,
    controls: ['COSHH assessments held for coatings and consumables; MSDS available.', 'RPE (FFP3 / half-mask) worn for dust and fume.', 'On-tool extraction used where practicable; work in ventilated areas.'],
    rL: 1, rS: 3, whenWhere: 'During grinding / welding / coating' },
  { ref: 'R15', activity: 'Adverse weather / environment', hazard: 'Wind affecting lifts and work at height, cold, poor visibility', who: _RAMS_R_OPS, iL: 3, iS: 4,
    controls: ['Weather forecast monitored.', 'Lifting and work at height suspended in high winds or poor visibility per the lift plan.', 'Appropriate clothing worn; work reassessed after adverse weather.'],
    rL: 2, rS: 3, whenWhere: 'Throughout outdoor works' },
  { ref: 'R16', activity: 'Restricted access (lift shafts, plant rooms)', hazard: 'Entrapment, poor egress, working in tight spaces', who: _RAMS_R_OPS, iL: 2, iS: 4,
    controls: ['Access and egress assessed before entry; adequate lighting provided.', 'Lone working avoided in restricted areas; clear escape route maintained.', 'Where a true confined space is identified, a separate permit and procedure apply.'],
    rL: 1, rS: 4, whenWhere: 'When working in restricted areas' },
  { ref: 'R17', activity: 'Working near services', hazard: 'Contact with overhead lines or buried / concealed services', who: _RAMS_R_OPS, iL: 2, iS: 5,
    controls: ['Services identified from drawings and site information before work.', 'Safe clearances maintained from overhead lines; permits used near services.', 'Structure scanned before drilling or fixing.'],
    rL: 1, rS: 5, whenWhere: 'When fixing / drilling near services' },
  { ref: 'R18', activity: 'Site emergency / injury', hazard: 'Fire, injury or delayed emergency response', who: _RAMS_R_ALL, iL: 2, iS: 4,
    controls: ['Site induction and emergency procedures followed; assembly point known.', 'Trained first-aider and kit on site.', 'Extinguishers provided for hot works; nearest A&E identified.'],
    rL: 1, rS: 4, whenWhere: 'Throughout the works' }
];

// Deterministic standard boilerplate. Always included; tunable per-job later.
const RAMS_STANDARD = {
  inductions: ['Site induction \u2014 all personnel attend the site-specific induction before commencing any activities.', 'Certification \u2014 all operatives hold valid CSCS, CPCS or equivalent cards, presented at induction.', 'Lift plans \u2014 where required for the movement of materials, prepared and signed off by a competent person before execution.', 'Mandatory PPE \u2014 the specified PPE is worn at all times on site, as detailed in the risk assessment.', 'Task briefing \u2014 a detailed task briefing is given before each task; attendance and understanding recorded on a signed register.', 'Supervision \u2014 work parties supervised by a competent individual to ensure adherence to this method statement.'],
  dab: ['Mandatory use of PPE.', 'Safe handling and operation of power tools.', 'COSHH assessments and associated risks.', 'Manual handling best practices.', 'Lifting operations and material movement plans.', 'Site traffic and walkway routes.', 'Allocated tasks for the day and break times.', 'HAV (Hand-Arm Vibration) monitoring and recording.', 'Pre-use inspections of plant, access equipment and lifting equipment.'],
  plant: ['MEWP / cherry picker (as required for elevated access)', 'Telehandler or mobile crane (for mechanical lifting)', 'LOLER-inspected lifting accessories — slings, shackles, chains', '110V / battery power tools — drills, impact wrenches, grinders', 'Welding / cutting equipment (where site welding is required)', 'Hand tools, spanners, torque wrenches, spirit levels', 'Podium steps / mobile access tower (low-level work)'],
  materials: ['Fabricated structural steelwork (as per the issued drawings)', 'Structural bolts, nuts and washers (grade as specified)', 'Anchors and fixings for connection to the substrate', 'Touch-up paint / galvanising repair (as required)'],
  ppe: ['Hard hat', 'Safety boots (steel toe/midsole)', 'Hi-vis clothing', 'Safety glasses', 'Gloves (cut-resistant / handling)', 'Hearing protection (in noisy areas)', 'RPE (for dust / fume)', 'Full-body harness and lanyard (for MEWP / work at height)', 'Welding PPE (where hot works are carried out)'],
  access: ['Access to and around the work area agreed with the principal contractor at induction.', 'MEWP, scaffold or mobile tower used for work at height as the primary access.', 'Exclusion zones set up beneath elevated works and around lifting operations.', 'Emergency escape routes kept clear at all times.'],
  environment: ['Waste segregated and removed to the designated site waste points.', 'Offcuts and swarf collected and disposed of responsibly.', 'Fuels, oils and coatings stored and handled to prevent spillage; spill kit available.', 'Noise and dust minimised so far as reasonably practicable.'],
  monitoring: ['This RAMS is briefed to all operatives before work starts and recorded in Appendix B.', 'Supervisor to monitor compliance throughout and stop work if conditions change.', 'RAMS reviewed if the scope, method, personnel or site conditions change materially.']
};

const _ramsRiskFill = r => (r <= 6 ? [212, 237, 218] : r <= 12 ? [255, 243, 205] : [248, 215, 218]);

// ── Standard-section picker (phase 3b) ─────────────────────────────────────
// The six deterministic sections are rendered as checkbox groups in the modal
// (all ticked by default). The user unticks anything not needed and can add
// missing items. confirmRams reads the ticked items per section; drawRamsPDF
// draws only what it receives (an empty section is dropped and the remaining
// sections renumber automatically).
const RAMS_SECTION_DEFS = [
  { key: 'inductions',  label: 'Inductions & Briefings \u2014 pre-requisites' },
  { key: 'dab',         label: 'Daily Activity Briefing topics' },
  { key: 'plant',       label: 'Plant & Equipment' },
  { key: 'materials',   label: 'Materials' },
  { key: 'ppe',         label: 'PPE' },
  { key: 'access',      label: 'Access & Egress' },
  { key: 'environment', label: 'Environmental & Waste' },
  { key: 'monitoring',  label: 'Monitoring & Review' }
];

function _ramsSecRow(item, checked) {
  if (checked === undefined) checked = true;
  const v = escapeHtml(item);
  return `<label style="display:flex;align-items:flex-start;gap:8px;cursor:pointer">
    <input type="checkbox" class="rams-sec-check" ${checked ? 'checked' : ''} value="${v}" style="width:13px;height:13px;margin-top:2px;accent-color:var(--accent)">
    <span style="font-size:12px;color:var(--text);line-height:1.35">${v}</span>
  </label>`;
}

// Rebuild the checkbox groups from RAMS_STANDARD (all ticked). On a REVISION,
// `saved` carries the previously-ticked items per section: those render ticked
// (in their saved order, custom items included) and any standard item that was
// dropped renders unticked so it can be re-added.
function ramsRenderStandardSections(saved) {
  const wrap = document.getElementById('ramsStandardSections');
  if (!wrap) return;
  wrap.innerHTML = RAMS_SECTION_DEFS.map(def => {
    let items;
    if (saved && Array.isArray(saved[def.key])) {
      const on = saved[def.key];
      const extra = (RAMS_STANDARD[def.key] || []).filter(x => !on.includes(x));
      items = on.map(x => _ramsSecRow(x, true)).concat(extra.map(x => _ramsSecRow(x, false))).join('');
    } else {
      items = (RAMS_STANDARD[def.key] || []).map(x => _ramsSecRow(x, true)).join('');
    }
    return `<div style="border:1px solid var(--border);border-radius:8px;padding:10px 12px;margin-bottom:10px;background:var(--bg-darker)">
      <div style="font-size:12px;font-weight:600;color:var(--text);margin-bottom:8px">${escapeHtml(def.label)}</div>
      <div class="rams-sec-items" data-key="${def.key}" style="display:flex;flex-direction:column;gap:6px;margin-bottom:8px">${items}</div>
      <div style="display:flex;gap:6px">
        <input class="field-input" id="ramsAdd_${def.key}" placeholder="Add item\u2026" style="flex:1;font-size:12px"
               onkeydown="if(event.key==='Enter'){event.preventDefault();ramsAddSectionItem('${def.key}');}">
        <button class="btn" onclick="ramsAddSectionItem('${def.key}')" style="padding:5px 12px;font-size:11px">&#43; Add</button>
      </div>
    </div>`;
  }).join('');
}

// Append a user-typed item to a section as a new ticked checkbox.
function ramsAddSectionItem(key) {
  const input = document.getElementById('ramsAdd_' + key);
  const val = (input?.value || '').trim();
  if (!val) return;
  const items = document.querySelector(`.rams-sec-items[data-key="${key}"]`);
  if (!items) return;
  items.insertAdjacentHTML('beforeend', _ramsSecRow(val));
  input.value = '';
  input.focus();
}

// Return the ticked items (in DOM order) for one section.
function ramsCollectSection(key) {
  const wrap = document.querySelector(`.rams-sec-items[data-key="${key}"]`);
  if (!wrap) return (RAMS_STANDARD[key] || []).slice();   // modal never opened — safe default
  return [...wrap.querySelectorAll('.rams-sec-check:checked')].map(c => c.value);
}

// ── Tier presets (phase 4) ─────────────────────────────────────────────────
// The Brief / Complex / Tier-1 selector drives document depth deterministically:
// which standard-section groups are ticked by default, how condensed the fixed
// text is, and how many Appendix-B briefing rows are printed. Changing the tier
// RE-APPLIES the group defaults (individual ticks inside a group are reset) —
// the user can still re-tick anything afterwards.
const RAMS_TIER_PRESETS = {
  brief:   { sections: { inductions: false, dab: false, plant: true, materials: true, ppe: true, access: true, environment: false, monitoring: false }, briefingRows: 8 },
  complex: { sections: { inductions: true,  dab: true,  plant: true, materials: true, ppe: true, access: true, environment: true,  monitoring: true  }, briefingRows: 12 },
  tier1:   { sections: { inductions: true,  dab: true,  plant: true, materials: true, ppe: true, access: true, environment: true,  monitoring: true  }, briefingRows: 16 }
};

function ramsApplyTierPreset() {
  const tier = document.getElementById('ramsTier')?.value || 'complex';
  const preset = RAMS_TIER_PRESETS[tier] || RAMS_TIER_PRESETS.complex;
  RAMS_SECTION_DEFS.forEach(def => {
    const on = preset.sections[def.key] !== false;
    document.querySelectorAll(`.rams-sec-items[data-key="${def.key}"] .rams-sec-check`)
      .forEach(c => { c.checked = on; });
  });
}

// ── Risk-row picker (phase 3c) ─────────────────────────────────────────────
// The 18 library rows are shown as ticked checkboxes; the user unticks any that
// don't apply and can add a fully-scored custom risk. State lives on the row
// objects (_on) so a re-render (after adding) preserves every tick.
let _ramsRiskRows = [];

function ramsRenderRiskPicker(savedRisks) {
  if (Array.isArray(savedRisks) && savedRisks.length) {
    // Revision: saved rows (custom risks included) come back ticked; library
    // rows that were dropped render unticked for easy re-adding.
    const savedHaz = new Set(savedRisks.map(r => r.hazard));
    _ramsRiskRows = savedRisks.map(r => ({ ...r, controls: (r.controls || []).slice(), _on: true }))
      .concat(RAMS_RISK_LIBRARY.filter(r => !savedHaz.has(r.hazard))
        .map(r => ({ ...r, controls: (r.controls || []).slice(), _on: false })));
  } else {
    _ramsRiskRows = RAMS_RISK_LIBRARY.map(r => ({ ...r, controls: (r.controls || []).slice(), _on: true }));
  }
  const form = document.getElementById('ramsAddRiskForm'); if (form) form.style.display = 'none';
  _ramsRenderRiskList();
}

function _ramsRenderRiskList() {
  const wrap = document.getElementById('ramsRiskList');
  if (!wrap) return;
  wrap.innerHTML = _ramsRiskRows.map((r, i) => {
    const iR = r.iL * r.iS;
    const band = iR <= 6 ? '#3ecf8e' : iR <= 12 ? '#e0a800' : '#e5484d';
    return `<label style="display:flex;align-items:flex-start;gap:8px;padding:6px 8px;border-bottom:1px solid var(--border);cursor:pointer">
      <input type="checkbox" class="rams-risk-check" data-idx="${i}" ${r._on !== false ? 'checked' : ''}
             onchange="ramsToggleRisk(${i}, this.checked)" style="width:14px;height:14px;margin-top:2px;accent-color:var(--accent)">
      <span style="font-size:12px;color:var(--text);line-height:1.35">
        <b>${escapeHtml(r.ref)}</b> \u00b7 ${escapeHtml(r.activity || '')} \u2014 ${escapeHtml(r.hazard || '')}
        <span style="color:${band};font-weight:600">(R=${iR})</span>
      </span>
    </label>`;
  }).join('');
}

function ramsToggleRisk(i, on) { if (_ramsRiskRows[i]) _ramsRiskRows[i]._on = !!on; }

// Ticked rows only, stripped of the internal _on flag — this is what the
// renderer consumes as Appendix A.
function ramsCollectRisks() {
  return _ramsRiskRows.filter(r => r._on !== false).map(r => { const { _on, ...rest } = r; return rest; });
}

function ramsToggleAddRisk() {
  const form = document.getElementById('ramsAddRiskForm');
  if (!form) return;
  const show = form.style.display === 'none';
  form.style.display = show ? '' : 'none';
  if (show) {
    ['ramsCrActivity', 'ramsCrHazard', 'ramsCrControls', 'ramsCrWhen'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
    const who = document.getElementById('ramsCrWho'); if (who) who.value = 'Operatives';
    [['ramsCrIL', '3'], ['ramsCrIS', '3'], ['ramsCrRL', '1'], ['ramsCrRS', '3']].forEach(([id, v]) => { const el = document.getElementById(id); if (el) el.value = v; });
    const sts = document.getElementById('ramsCrStatus'); if (sts) sts.textContent = '';
  }
}

function ramsSubmitCustomRisk() {
  const g = id => (document.getElementById(id)?.value || '').trim();
  const sts = document.getElementById('ramsCrStatus');
  const hazard = g('ramsCrHazard');
  if (!hazard) { if (sts) { sts.style.color = 'var(--red)'; sts.textContent = 'Hazard is required.'; } return; }
  const clamp = v => Math.max(1, Math.min(5, parseInt(v) || 1));
  const controls = g('ramsCrControls').split('\n').map(l => l.trim()).filter(Boolean);
  const nCustom = _ramsRiskRows.filter(r => /^C\d+$/.test(r.ref)).length;
  _ramsRiskRows.push({
    ref: 'C' + String(nCustom + 1).padStart(2, '0'),
    activity: g('ramsCrActivity'),
    hazard,
    who: g('ramsCrWho') || 'Operatives',
    iL: clamp(g('ramsCrIL')), iS: clamp(g('ramsCrIS')),
    controls: controls.length ? controls : ['Control measures to be confirmed on site.'],
    rL: clamp(g('ramsCrRL')), rS: clamp(g('ramsCrRS')),
    whenWhere: g('ramsCrWhen'),
    _on: true
  });
  _ramsRenderRiskList();
  ramsToggleAddRisk();
  const wrap = document.getElementById('ramsRiskList'); if (wrap) wrap.scrollTop = wrap.scrollHeight;
}

// Native RAMS renderer. Returns a Blob. `rams` is assembled from the editable
// modal fields (+ personnel roster, site-plan image, and the risk library).
function drawRamsPDF(jsPDF, rams, logoDataUri) {
  const tier = rams.tier || 'complex';   // brief | complex | tier1 — drives document depth (phase 4)
  const s = (typeof _pickTplSettings === 'function') ? _pickTplSettings() : null;
  const g = (s && s.global) || (typeof TEMPLATE_DEFAULTS !== 'undefined' ? TEMPLATE_DEFAULTS.global
    : { companyName: 'BAMA FABRICATION', address: '', phone: '', email: '', vatNumber: '' });
  const accent = (typeof hexToRgb === 'function' && hexToRgb((s && s.deliveryNote && s.deliveryNote.accentColor) || '#ff6b00')) || [255, 107, 0];

  const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  try {
    doc.setProperties({
      title: `${rams.docNo || 'RAMS'}${rams.title ? ' — ' + rams.title : ''}`,
      subject: 'Risk Assessment & Method Statement',
      author: 'BAMA Fabrication', creator: 'BAMA Fabrication ERP'
    });
  } catch (e) { /* non-critical */ }

  const marginL = 14, marginR = 14, marginB = 16;
  let pageW = 210, pageH = 297;                       // per-page — Appendix A flips to landscape
  let usableW = pageW - marginL - marginR;
  let orient = 'portrait';
  const setOrient = o => {                            // takes effect from the NEXT newPage()
    orient = o;
    pageW = o === 'landscape' ? 297 : 210;
    pageH = o === 'landscape' ? 210 : 297;
    usableW = pageW - marginL - marginR;
  };
  const TEXT = [34, 34, 34], MUTED = [90, 90, 90], RULE = [204, 204, 204], HEADFILL = [242, 242, 242];
  const setText = c => doc.setTextColor(c[0], c[1], c[2]);
  const setFill = c => doc.setFillColor(c[0], c[1], c[2]);
  const setDraw = c => doc.setDrawColor(c[0], c[1], c[2]);
  let y = marginL;

  const newPage = () => { doc.addPage('a4', orient); y = marginL; };
  const ensureSpace = h => { if (y + h > pageH - marginB) newPage(); };

  const sectionHeading = (txt) => {
    ensureSpace(12); y += 2;
    setDraw(accent); doc.setLineWidth(0.8); doc.line(marginL, y, marginL + 14, y);
    setText(accent); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
    doc.text(String(txt).toUpperCase(), marginL, y + 4.5);
    y += 8;
  };
  const para = (txt, opts) => {
    opts = opts || {};
    const size = opts.size || 9.5, lh = opts.lh || 4.4;
    setText(opts.color || TEXT); doc.setFont('helvetica', opts.bold ? 'bold' : (opts.italic ? 'italic' : 'normal'));
    doc.setFontSize(size);
    doc.splitTextToSize(String(txt), usableW).forEach(ln => { ensureSpace(lh + 1); doc.text(ln, marginL, y + 3); y += lh; });
  };
  const list = (items, numbered) => {
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5); setText(TEXT);
    const indent = numbered ? 7 : 5;
    items.forEach((it, i) => {
      const marker = numbered ? `${i + 1}.` : '\u2022';
      const lines = doc.splitTextToSize(String(it), usableW - indent);
      const h = lines.length * 4.4 + 1.5;
      ensureSpace(h);
      setText(MUTED); doc.text(marker, marginL, y + 3);
      setText(TEXT); lines.forEach((ln, j) => doc.text(ln, marginL + indent, y + 3 + j * 4.4));
      y += h;
    });
    y += 2;
  };

  // ═══ COVER PAGE (Complex & Tier 1) ═══
  // Classic BAMA method-statement front sheet: centred logo, document title,
  // ruled Details block and an Authorisation block with wet-signature space.
  // Complex & Tier 1 also reserve page 2 for a CONTENTS page (filled in at the
  // end, once every section's page number is known). Brief stays compact.
  const hasCover = tier !== 'brief';
  const hasToc   = tier !== 'brief';   // contents page for Complex AND Tier 1
  const toc = [];                     // { label, page } — collected as headings are drawn
  if (hasCover) {
    let cy = 30;
    if (logoDataUri) {
      try {
        const props = doc.getImageProperties(logoDataUri);
        const LW = 72;
        const LH = (props && props.width && props.height) ? LW * props.height / props.width : 32;
        doc.addImage(logoDataUri, (props && props.fileType) || 'PNG', (pageW - LW) / 2, cy, LW, LH, undefined, 'FAST');
        cy += LH + 12;
      } catch (e) { cy += 8; }
    } else {
      doc.setFont('helvetica', 'bold'); doc.setFontSize(24); setText(accent);
      doc.text(g.companyName || 'BAMA FABRICATION', pageW / 2, cy + 10, { align: 'center' });
      cy += 24;
    }
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(20);
    doc.text('RISK ASSESSMENT &', pageW / 2, cy + 6, { align: 'center' });
    doc.text('METHOD STATEMENT', pageW / 2, cy + 15, { align: 'center' });
    cy += 34;

    doc.setFont('helvetica', 'bold'); doc.setFontSize(11); setText(TEXT);
    doc.text('Details', marginL + 6, cy);
    setDraw(TEXT); doc.setLineWidth(0.4); doc.line(marginL + 6, cy + 1.8, pageW - marginR - 6, cy + 1.8);
    cy += 9;
    const coverRow = (label, value) => {
      if (value == null || String(value).trim() === '') return;
      doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5); setText(TEXT);
      doc.text(label + ':', marginL + 6, cy);
      doc.setFont('helvetica', 'normal');
      const lines = doc.splitTextToSize(String(value), usableW - 64);
      lines.forEach((ln, i) => doc.text(ln, marginL + 58, cy + i * 5));
      cy += Math.max(1, lines.length) * 5 + 3;   // row height follows the wrap
    };
    coverRow('Contract name', rams.contract);
    coverRow('Contract No', rams.contractNo);
    coverRow('Client', rams.client);
    coverRow('Principal contractor', rams.principal);
    coverRow('Title', rams.title);
    if (Array.isArray(rams.jobsCovered) && rams.jobsCovered.length > 1)
      coverRow('Jobs covered', rams.jobsCovered.join(', '));
    coverRow('Document No', rams.docNo);
    coverRow('Revision', rams.rev);
    coverRow('Issue date', rams.dateStr);
    cy += 12;

    doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
    doc.text('Authorisation', marginL + 6, cy);
    setDraw(TEXT); doc.setLineWidth(0.4); doc.line(marginL + 6, cy + 1.8, pageW - marginR - 6, cy + 1.8);
    cy += 13;
    const signRow = (label, name) => {
      doc.setFont('helvetica', 'normal'); doc.setFontSize(10.5); setText(TEXT);
      doc.text(`${label}: ${name || ''}`, marginL + 6, cy);
      doc.text('Signature:', pageW / 2 + 16, cy);
      setDraw(MUTED); doc.setLineWidth(0.3);
      doc.line(pageW / 2 + 37, cy + 1.2, pageW - marginR - 6, cy + 1.2);
      setDraw(RULE); doc.setLineWidth(0.2); doc.line(marginL + 6, cy + 10, pageW - marginR - 6, cy + 10);
      cy += 20;
    };
    signRow('Prepared by', rams.preparedBy);
    signRow('Approved by', rams.preparedBy);
    newPage();
    if (hasToc) newPage();            // reserve page 2 for CONTENTS
  }

  // ═══ HEADER ═══
  let leftY = y, logoDrawn = false;
  if (logoDataUri) {
    try {
      const RENDER_W = 52;
      const props = doc.getImageProperties(logoDataUri);
      const ratio = (props && props.width && props.height) ? (props.width / props.height) : (52 / 24);
      const renderH = RENDER_W / ratio;
      doc.addImage(logoDataUri, props.fileType || 'PNG', marginL, y, RENDER_W, renderH, undefined, 'FAST');
      leftY = y + renderH + 3; logoDrawn = true;
    } catch (e) { logoDrawn = false; }
  }
  if (!logoDrawn) {
    doc.setFont('helvetica', 'bold'); doc.setFontSize(19); setText(accent);
    doc.text(g.companyName || 'BAMA FABRICATION', marginL, y + 7); leftY = y + 13;
  }
  setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
  const coLines = [];
  if (g.address) String(g.address).split('\n').forEach(l => coLines.push(l));
  if (g.phone) coLines.push('Tel: ' + g.phone);
  if (g.email) coLines.push(g.email);
  coLines.forEach(l => { doc.text(String(l), marginL, leftY + 2.5); leftY += 3.6; });

  doc.setFont('helvetica', 'bolditalic'); doc.setFontSize(16); setText(accent);
  doc.text('RAMS', pageW - marginR, y + 6, { align: 'right' });
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5); setText(MUTED);
  doc.text('Risk Assessment & Method Statement', pageW - marginR, y + 10.5, { align: 'right' });

  let rightY = y + 16;
  const metaRows = [
    { label: 'Document No:', value: rams.docNo },
    { label: 'Revision:', value: rams.rev },
    { label: 'Date:', value: rams.dateStr },
    { label: 'Prepared by:', value: rams.preparedBy }
  ].filter(r => r.value != null && String(r.value).trim() !== '');
  doc.setFontSize(8.5);
  for (const r of metaRows) {
    setText(TEXT); doc.setFont('helvetica', 'bold');
    doc.text(r.label, pageW - marginR - 40, rightY, { align: 'right' });
    doc.setFont('helvetica', 'normal');
    const vLines = doc.splitTextToSize(String(r.value), 40);
    doc.text(vLines[0] || '', pageW - marginR, rightY, { align: 'right' });
    rightY += 4.2 * Math.max(1, vLines.length);
  }
  y = Math.max(leftY + 2.5, rightY) + 2;
  setDraw(TEXT); doc.setLineWidth(0.5); doc.line(marginL, y, pageW - marginR, y);
  y += 6;

  // ═══ PROJECT DETAILS ═══
  const detailRows = [
    ['Contract / Project', rams.contract],
    ['Works title', rams.title],
    ['Client', rams.client],
    ['Principal contractor', rams.principal],
    ['Contract No', rams.contractNo],
    ['Drawing reference', rams.drawingRef],
    ['Site', rams.site && rams.site.name],
    ['Site address', (rams.site && rams.site.lines || []).join(', ')],
    ['Site contact', [rams.site && rams.site.contactName, rams.site && rams.site.contactPhone].filter(Boolean).join(' \u00b7 ')],
    ['Working hours', rams.hours],
    ['Nearest A&E', rams.ae]
  ].filter(r => r[1] != null && String(r[1]).trim() !== '');
  const labX = marginL, valX = marginL + 44;
  doc.setFontSize(9);
  for (const [lab, val] of detailRows) {
    const vLines = doc.splitTextToSize(String(val), usableW - 44);
    const h = Math.max(4.6, vLines.length * 4.4);
    ensureSpace(h);
    setText(MUTED); doc.setFont('helvetica', 'bold'); doc.text(lab, labX, y + 3);
    setText(TEXT); doc.setFont('helvetica', 'normal');
    vLines.forEach((ln, i) => doc.text(ln, valX, y + 3 + i * 4.4));
    y += h;
  }
  y += 2;

  // Running section number — sections drop out when empty (unticked), so the
  // numbering is computed rather than hard-coded to keep it sequential.
  let secNum = 0;
  const numHeading = t => {
    secNum++;
    const label = secNum + '. ' + t;
    sectionHeading(label);
    toc.push({ label, page: doc.internal.getNumberOfPages() });
  };

  // ═══ DOCUMENT CONTROL (tier 1 only) ═══
  // Tier-1 principal contractors expect a formal approval trail: a revision
  // line plus a Prepared / Reviewed / Approved sign-off table with wet-signature
  // space. Brief/Complex keep the compact header meta only.
  if (tier === 'tier1') {
    numHeading('Document Control & Approval');
    para(`Revision ${rams.rev || '00'}${rams.dateStr ? ' \u2014 issued ' + rams.dateStr : ''}. This document will be reviewed and re-issued if the scope, site conditions or method of work change.`, { size: 9 });
    y += 1;
    const dcCols = [
      { title: 'Role', w: 30 }, { title: 'Name', w: 55 },
      { title: 'Signature', w: usableW - 30 - 55 - 28 }, { title: 'Date', w: 28 }
    ];
    let dcx = marginL; dcCols.forEach(c => { c.x = dcx; dcx += c.w; });
    ensureSpace(6.5 + 3 * 9 + 3);
    setFill(HEADFILL); doc.rect(marginL, y, usableW, 6.5, 'F');
    setDraw(RULE); doc.setLineWidth(0.2); doc.rect(marginL, y, usableW, 6.5);
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
    dcCols.forEach(c => doc.text(c.title, c.x + 1.5, y + 4.3));
    y += 6.5;
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5);
    const dcRows = [
      ['Prepared by', rams.preparedBy || ''],
      ['Reviewed by', ''],
      ['Approved by', '']
    ];
    for (const [role, name] of dcRows) {
      const rh = 9;
      setDraw(RULE); doc.setLineWidth(0.15); doc.rect(marginL, y, usableW, rh);
      dcCols.forEach(c => { if (c.x > marginL) doc.line(c.x, y, c.x, y + rh); });
      setText(TEXT); doc.setFont('helvetica', 'bold'); doc.text(role, dcCols[0].x + 1.5, y + 5.6);
      doc.setFont('helvetica', 'normal'); doc.text(String(name), dcCols[1].x + 1.5, y + 5.6);
      y += rh;
    }
    y += 3;
  }

  // ═══ SCOPE ═══
  if ((rams.scopeLines || []).length) { numHeading('Scope of Works'); list(rams.scopeLines, true); }

  // ═══ PROGRAMME ═══
  numHeading('Programme & Working Hours');
  para(tier === 'brief'
    ? (rams.hours
        ? `Working hours: ${rams.hours}. Programme to be agreed with the principal contractor.`
        : 'Programme and working hours to be agreed with the principal contractor.')
    : (rams.hours
        ? `Works will be carried out during the following hours: ${rams.hours}. Actual dates and durations to be confirmed with the principal contractor and coordinated at site induction.`
        : 'Working hours and programme to be confirmed with the principal contractor at site induction.'));

  // ═══ INDUCTIONS & BRIEFINGS (Complex & Tier 1 by default) ═══
  const inductions = rams.inductions || RAMS_STANDARD.inductions;
  const dab        = rams.dab        || RAMS_STANDARD.dab;
  if (inductions.length || dab.length) {
    numHeading('Inductions & Briefings');
    if (inductions.length) {
      para('This RAMS and the associated task briefings will be reviewed, updated and re-issued if the methodology changes or additional tasks are introduced. Pre-requisites before works commence:', { size: 9 });
      y += 1;
      list(inductions, false);
    }
    if (dab.length) {
      para('Daily Activity Briefing', { bold: true });
      para('Before starting any works, all operatives will participate in a Daily Activity Briefing covering:', { size: 9 });
      y += 1;
      list(dab, false);
    }
  }

  // ═══ SEQUENCE ═══
  if ((rams.tasks || []).length) {
    numHeading('Sequence of Works');
    rams.tasks.forEach((t, i) => {
      const steps = Array.isArray(t.steps) ? t.steps : [];
      doc.setFontSize(9.5);
      const titleLines  = doc.splitTextToSize(`${i + 1}. ${t.title}`, usableW - 2);
      const detailLines = t.detail ? doc.splitTextToSize(t.detail, usableW - 7) : [];
      const headH = titleLines.length * 4.6 + detailLines.length * 4.4 + 1.5;
      ensureSpace(headH + (steps.length ? 6 : 0));   // never orphan a title at a page break
      setText(TEXT); doc.setFont('helvetica', 'bold');
      titleLines.forEach((ln, j) => doc.text(ln, marginL, y + 3 + j * 4.6));
      const yy = y + 3 + titleLines.length * 4.6;
      if (detailLines.length) {
        setText([70, 70, 70]); doc.setFont('helvetica', 'normal');
        detailLines.forEach((ln, j) => doc.text(ln, marginL + 7, yy + j * 4.4));
      }
      y += headH;
      // Sub-steps — lettered a. b. c. like the classic method-statement tasks.
      doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5);
      steps.forEach((st, k) => {
        const lines = doc.splitTextToSize(String(st), usableW - 14);
        const h = lines.length * 4.4 + 1.2;
        ensureSpace(h);
        setText(MUTED); doc.text(String.fromCharCode(97 + (k % 26)) + '.', marginL + 7, y + 3);
        setText(TEXT); lines.forEach((ln, j) => doc.text(ln, marginL + 12, y + 3 + j * 4.4));
        y += h;
      });
      y += 2.5;
    });
    y += 1;
  }

  // ═══ KEY PERSONNEL ═══
  numHeading('Key Personnel & Competency');
  const people = rams.personnel || [];
  if (people.length) {
    const cols = [
      { title: 'Name', w: 46 }, { title: 'Site role', w: 44 },
      { title: 'Company', w: 40 }, { title: 'Certifications', w: usableW - 46 - 44 - 40 }
    ];
    let cx = marginL; cols.forEach(c => { c.x = cx; cx += c.w; });
    const cell = (c, txt, yy) => doc.text(String(txt == null ? '' : txt), c.x + 1.5, yy);
    const drawHead = () => {
      setFill(HEADFILL); doc.rect(marginL, y, usableW, 6.5, 'F');
      setDraw(RULE); doc.setLineWidth(0.2); doc.rect(marginL, y, usableW, 6.5);
      setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
      cols.forEach(c => cell(c, c.title, y + 4.4));
      y += 6.5;
    };
    ensureSpace(14); drawHead();
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5);
    for (const p of people) {
      const wrap = (t, c) => doc.splitTextToSize(String(t || ''), c.w - 3);
      const nameL = wrap(p.name, cols[0]);
      const roleL = wrap(p.site_role || p.role || '\u2014', cols[1]);
      const compL = wrap('BAMA Fabrication', cols[2]);   // everyone works under the BAMA banner on site
      const certL = wrap((p.certs || []).join(', ') || '\u2014', cols[3]);
      const n = Math.max(nameL.length, roleL.length, compL.length, certL.length, 1);
      const rowH = n * 4 + 2;
      if (y + rowH > pageH - marginB) { newPage(); drawHead(); doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5); }
      const b = y + 4;
      setText(TEXT);
      doc.setFont('helvetica', 'bold'); nameL.forEach((l, i) => cell(cols[0], l, b + i * 4)); doc.setFont('helvetica', 'normal');
      roleL.forEach((l, i) => cell(cols[1], l, b + i * 4));
      compL.forEach((l, i) => cell(cols[2], l, b + i * 4));
      certL.forEach((l, i) => cell(cols[3], l, b + i * 4));
      setDraw(RULE); doc.setLineWidth(0.15); doc.line(marginL, y + rowH, pageW - marginR, y + rowH);
      y += rowH;
    }
    y += 3;
  } else {
    para('Site personnel to be confirmed at induction. All operatives to hold valid CSCS (or equivalent) and task-specific competency cards.', { italic: true, color: MUTED, size: 9 });
  }

  // ═══ STANDARD SECTIONS (only what was ticked in the modal) ═══
  // Each array is user-picked in the modal; an empty array means the user
  // unticked everything, so the section is dropped. `undefined` (modal never
  // opened) falls back to the full standard list.
  const plant       = rams.plant       || RAMS_STANDARD.plant;
  const materials   = rams.materials   || RAMS_STANDARD.materials;
  const ppe         = rams.ppe         || RAMS_STANDARD.ppe;
  const access      = rams.access      || RAMS_STANDARD.access;
  const environment = rams.environment || RAMS_STANDARD.environment;
  const monitoring  = rams.monitoring  || RAMS_STANDARD.monitoring;

  if (plant.length || materials.length) {
    numHeading('Plant, Equipment & Materials');
    if (plant.length)     { para('Plant & equipment:', { bold: true, size: 9.5 }); list(plant, false); }
    if (materials.length) { para('Materials:', { bold: true, size: 9.5 }); list(materials, false); }
  }

  if (ppe.length) {
    numHeading('Personal Protective Equipment (PPE)');
    para('The following PPE is mandatory / task-specific as noted. Minimum site PPE (hard hat, boots, hi-vis, glasses, gloves) worn at all times:', { size: 9 });
    list(ppe, false);
  }

  if (access.length)      { numHeading('Access & Egress'); list(access, false); }
  if (environment.length) { numHeading('Environmental & Waste'); list(environment, false); }

  // Emergency arrangements are always included (dynamic — uses the A&E field).
  numHeading('Emergency Arrangements');
  const emergencyLines = tier === 'brief'
    ? [
        'On discovering an emergency, raise the alarm and follow the site emergency procedure. Trained first-aider and first-aid kit available on site.',
        rams.ae ? `Nearest A&E: ${rams.ae}.` : 'Nearest A&E to be confirmed at site induction.',
        'Report all accidents, incidents and near-misses to the site manager and BAMA office.'
      ]
    : [
        'On discovering an emergency, raise the alarm and follow the site emergency procedure.',
        'Make the area safe if it is safe to do so; do not put yourself at risk.',
        'Trained first-aider and first-aid kit available on site.',
        rams.ae ? `Nearest A&E: ${rams.ae}.` : 'Nearest A&E to be confirmed at site induction.',
        'Report all accidents, incidents and near-misses to the site manager and BAMA office.'
      ];
  if (tier === 'tier1') {
    emergencyLines.push('All RIDDOR-reportable injuries, diseases and dangerous occurrences will be reported to the HSE in line with statutory requirements and notified to the principal contractor.');
    emergencyLines.push('Emergency contact numbers and muster points to be obtained from the principal contractor at induction and held by the BAMA supervisor.');
  }
  list(emergencyLines, false);

  if (monitoring.length) { numHeading('Monitoring & Review'); list(monitoring, false); }

  if (rams.notes && String(rams.notes).trim()) { numHeading('Additional Notes'); para(rams.notes); }

  // ═══ SITE PLAN ═══
  if (rams.sitePlanDataUri) {
    numHeading('Site Plan');
    try {
      const props = doc.getImageProperties(rams.sitePlanDataUri);
      const maxW = usableW, maxH = 170;
      let w = maxW, h = (props && props.width && props.height) ? maxW * (props.height / props.width) : maxW * 0.6;
      if (h > maxH) { h = maxH; w = (props && props.width && props.height) ? maxH * (props.width / props.height) : maxH * 1.4; }
      ensureSpace(h + 4);
      const px = marginL + (usableW - w) / 2;
      doc.addImage(rams.sitePlanDataUri, props.fileType || 'PNG', px, y, w, h, undefined, 'FAST');
      setDraw(RULE); doc.setLineWidth(0.3); doc.rect(px, y, w, h);
      // Work-area pin (phase 5): {x,y} stored as % of the image in the modal,
      // drawn here as a vector marker (jsPDF helvetica has no emoji) — stem
      // apex on the exact clicked point, red head above, WORK AREA label.
      if (rams.sitePlanPin && isFinite(rams.sitePlanPin.x) && isFinite(rams.sitePlanPin.y)) {
        const pinX = px + w * rams.sitePlanPin.x / 100;
        const pinY = y  + h * rams.sitePlanPin.y / 100;
        const PIN = [229, 72, 77];
        doc.setFillColor(PIN[0], PIN[1], PIN[2]);
        doc.triangle(pinX - 1.7, pinY - 3.4, pinX + 1.7, pinY - 3.4, pinX, pinY, 'F');
        doc.circle(pinX, pinY - 4.6, 2.5, 'F');
        doc.setFillColor(255, 255, 255);
        doc.circle(pinX, pinY - 4.6, 1.0, 'F');
        doc.setFont('helvetica', 'bold'); doc.setFontSize(6.5);
        doc.setTextColor(PIN[0], PIN[1], PIN[2]);
        const labelAbove = rams.sitePlanPin.y > 10;   // near the top edge → label under the point instead
        doc.text('WORK AREA', Math.max(px + 9, Math.min(px + w - 9, pinX)),
                 labelAbove ? pinY - 8.4 : pinY + 3.6, { align: 'center' });
        setText(TEXT);
      }
      y += h + 4;
    } catch (e) { para('(Site plan image could not be embedded.)', { italic: true, color: MUTED, size: 8.5 }); }
  }

  // ═══ APPENDIX A — RISK ASSESSMENT ═══
  setOrient('landscape');                             // risk table gets the full A4 width
  newPage();
  sectionHeading('Appendix A — Risk Assessment');
  toc.push({ label: 'Appendix A — Risk Assessment', page: doc.internal.getNumberOfPages() });
  para('Risk rating R = Likelihood (L, 1\u20135) \u00d7 Severity (S, 1\u20135). "Initial" is the risk before controls; "Residual" is the risk with the controls below applied. Bands: 1\u20136 low, 7\u201312 medium, 13\u201325 high.', { size: 8, color: MUTED });
  y += 1;

  // 5×5 risk-matrix legend (Complex & Tier 1) — the classic Appendix A key.
  if (tier !== 'brief') {
    const cell = 8.2, gx = marginL + 16;
    ensureSpace(cell * 5 + 26);
    const gy = y + 3;
    doc.setFontSize(6.8);
    for (let sv = 5; sv >= 1; sv--) {
      for (let lk = 1; lk <= 5; lk++) {
        const r = sv * lk;
        const cx = gx + (lk - 1) * cell, cyy = gy + (5 - sv) * cell;
        setFill(_ramsRiskFill(r)); setDraw(RULE); doc.setLineWidth(0.15);
        doc.rect(cx, cyy, cell, cell, 'FD');
        setText(TEXT); doc.setFont('helvetica', 'normal');
        doc.text(String(r), cx + cell / 2, cyy + cell / 2 + 1.1, { align: 'center' });
      }
      setText(MUTED);
      doc.text(String(sv), gx - 3.2, gy + (5 - sv) * cell + cell / 2 + 1.1, { align: 'center' });
    }
    setText(MUTED);
    for (let lk = 1; lk <= 5; lk++) doc.text(String(lk), gx + (lk - 1) * cell + cell / 2, gy + 5 * cell + 3.6, { align: 'center' });
    doc.setFont('helvetica', 'bold');
    doc.text('Likelihood', gx + cell * 2.5, gy + 5 * cell + 7.6, { align: 'center' });
    doc.text('Severity', gx - 8.5, gy + cell * 2.5 + 6, { angle: 90 });
    const keyX = gx + cell * 5 + 12;
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(7.2);
    doc.text('Likelihood', keyX, gy + 2.6);
    doc.text('Severity', keyX + 46, gy + 2.6);
    doc.setFont('helvetica', 'normal'); setText(MUTED); doc.setFontSize(6.8);
    ['1 = Very unlikely', '2 = Unlikely', '3 = Likely', '4 = Very likely', '5 = Almost certain']
      .forEach((t, i) => doc.text(t, keyX, gy + 7 + i * 3.9));
    ['1 = No injury', '2 = Minor injury or illness', '3 = "7 day" injury or illness', '4 = Major injury or illness', '5 = Fatality, disabling injury, etc.']
      .forEach((t, i) => doc.text(t, keyX + 46, gy + 7 + i * 3.9));
    doc.setFont('helvetica', 'bold');
    doc.text('Risk = Likelihood \u00d7 Severity', keyX, gy + 7 + 5 * 3.9 + 2.5);
    const chipY = gy + 5 * cell + 13;
    const chip = (x, fill, label) => {
      setFill(fill); setDraw(RULE); doc.rect(x, chipY - 2.8, 9, 3.6, 'FD');
      setText(MUTED); doc.setFont('helvetica', 'normal'); doc.text(label, x + 11, chipY);
    };
    chip(marginL, [212, 237, 218], 'Acceptable (1\u20136)');
    chip(marginL + 55, [255, 243, 205], 'Further review (7\u201312)');
    chip(marginL + 118, [248, 215, 218], 'Unacceptable (13\u201325)');
    y = chipY + 6;
  }

  const risks = Array.isArray(rams.risks) ? rams.risks : RAMS_RISK_LIBRARY;
  const rc = [
    { key: 'ref', title: 'Ref', w: 9, align: 'left' },
    { key: 'haz', title: 'Activity / Hazard', w: 40, align: 'left' },
    { key: 'who', title: 'At risk', w: 22, align: 'left' },
    { key: 'iL', title: 'L', w: 6, align: 'center' },
    { key: 'iS', title: 'S', w: 6, align: 'center' },
    { key: 'iR', title: 'R', w: 7, align: 'center' },
    { key: 'ctrl', title: 'Control measures', w: 0, align: 'left' },
    { key: 'rL', title: 'L', w: 6, align: 'center' },
    { key: 'rS', title: 'S', w: 6, align: 'center' },
    { key: 'rR', title: 'R', w: 7, align: 'center' }
  ];
  rc.find(c => c.key === 'ctrl').w = usableW - rc.reduce((a, c) => a + c.w, 0);
  let rx = marginL; rc.forEach(c => { c.x = rx; rx += c.w; });
  const rcell = (c, txt, yy) => {
    const str = String(txt == null ? '' : txt);
    if (c.align === 'center') doc.text(str, c.x + c.w / 2, yy, { align: 'center' });
    else doc.text(str, c.x + 1.3, yy);
  };
  const drawRiskHead = () => {
    setFill([232, 232, 232]);
    const iL = rc.find(c => c.key === 'iL'), iR = rc.find(c => c.key === 'iR');
    const rL = rc.find(c => c.key === 'rL'), rR = rc.find(c => c.key === 'rR');
    doc.rect(iL.x, y, (iR.x + iR.w) - iL.x, 4.6, 'F');
    doc.rect(rL.x, y, (rR.x + rR.w) - rL.x, 4.6, 'F');
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(6.5);
    doc.text('INITIAL', (iL.x + iR.x + iR.w) / 2, y + 3.2, { align: 'center' });
    doc.text('RESIDUAL', (rL.x + rR.x + rR.w) / 2, y + 3.2, { align: 'center' });
    y += 4.6;
    setFill(HEADFILL); doc.rect(marginL, y, usableW, 6, 'F');
    setDraw(RULE); doc.setLineWidth(0.2); doc.rect(marginL, y, usableW, 6);
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(7.5);
    rc.forEach(c => rcell(c, c.title, y + 4));
    y += 6;
  };
  ensureSpace(20); drawRiskHead();

  for (const r of risks) {
    const iR = r.iL * r.iS, rR = r.rL * r.rS;
    const hazL = doc.splitTextToSize(`${r.activity ? r.activity + ' \u2014 ' : ''}${r.hazard}`, rc[1].w - 2.5);
    const whoL = doc.splitTextToSize(String(r.who || ''), rc[2].w - 2.5);
    const ctrlCol = rc.find(c => c.key === 'ctrl');
    let ctrlLines = [];
    (r.controls || []).forEach(ci => { doc.splitTextToSize('\u2022 ' + ci, ctrlCol.w - 2.5).forEach(l => ctrlLines.push(l)); });
    if (r.whenWhere) doc.splitTextToSize('When/where: ' + r.whenWhere, ctrlCol.w - 2.5).forEach(l => ctrlLines.push(l));
    const n = Math.max(hazL.length, whoL.length, ctrlLines.length, 1);
    const rowH = n * 3.4 + 2.5;
    if (y + rowH > pageH - marginB) { newPage(); drawRiskHead(); }
    setFill(_ramsRiskFill(iR)); doc.rect(rc[5].x, y, rc[5].w, rowH, 'F');
    setFill(_ramsRiskFill(rR)); doc.rect(rc[9].x, y, rc[9].w, rowH, 'F');
    const b = y + 3.6;
    setText(TEXT); doc.setFont('helvetica', 'normal'); doc.setFontSize(7.2);
    doc.setFont('helvetica', 'bold'); rcell(rc[0], r.ref, b); doc.setFont('helvetica', 'normal');
    hazL.forEach((l, i) => rcell(rc[1], l, b + i * 3.4));
    whoL.forEach((l, i) => rcell(rc[2], l, b + i * 3.4));
    rcell(rc[3], r.iL, b); rcell(rc[4], r.iS, b);
    doc.setFont('helvetica', 'bold'); rcell(rc[5], iR, b); doc.setFont('helvetica', 'normal');
    ctrlLines.forEach((l, i) => rcell(ctrlCol, l, b + i * 3.4));
    rcell(rc[7], r.rL, b); rcell(rc[8], r.rS, b);
    doc.setFont('helvetica', 'bold'); rcell(rc[9], rR, b); doc.setFont('helvetica', 'normal');
    setDraw(RULE); doc.setLineWidth(0.15);
    doc.line(marginL, y + rowH, pageW - marginR, y + rowH);
    [rc[1].x, rc[2].x, rc[3].x, rc[6].x, rc[7].x].forEach(vx => doc.line(vx, y, vx, y + rowH));
    y += rowH;
  }
  y += 3;

  // ═══ APPENDIX B — BRIEFING REGISTER ═══
  setOrient('portrait');                              // signature register back to portrait
  newPage();
  sectionHeading('Appendix B — Briefing Register');
  toc.push({ label: 'Appendix B — Briefing Register', page: doc.internal.getNumberOfPages() });
  para('I confirm that I have read, or have had explained to me, this Risk Assessment & Method Statement and I understand its contents and will comply with it.', { size: 8.5, color: MUTED });
  y += 1;
  const bc = [
    { title: 'Name', w: 55 }, { title: 'Company', w: 40 },
    { title: 'Signature', w: usableW - 55 - 40 - 30 }, { title: 'Date', w: 30 }
  ];
  let bx = marginL; bc.forEach(c => { c.x = bx; bx += c.w; });
  const drawRegHead = () => {
    setFill(HEADFILL); doc.rect(marginL, y, usableW, 6.5, 'F');
    setDraw(RULE); doc.setLineWidth(0.2); doc.rect(marginL, y, usableW, 6.5);
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
    bc.forEach(c => doc.text(c.title, c.x + 1.5, y + 4.3));
    y += 6.5; doc.setFont('helvetica', 'normal');
  };
  drawRegHead();
  const roster = rams.personnel || [];
  const rowH2 = 8;
  const regRowCount = Math.max(
    ((RAMS_TIER_PRESETS[tier] || RAMS_TIER_PRESETS.complex).briefingRows) || 12,
    roster.length);
  for (let i = 0; i < regRowCount; i++) {
    if (y + rowH2 > pageH - marginB) { newPage(); drawRegHead(); }
    setDraw(RULE); doc.setLineWidth(0.15); doc.rect(marginL, y, usableW, rowH2);
    bc.forEach(c => { if (c.x > marginL) doc.line(c.x, y, c.x, y + rowH2); });
    const p = roster[i];
    if (p) {
      setText([70, 70, 70]); doc.setFontSize(8.5);
      doc.text(String(p.name || ''), bc[0].x + 1.5, y + 5.2);
      doc.text('BAMA Fabrication', bc[1].x + 1.5, y + 5.2);
    }
    y += rowH2;
  }

  // ═══ CONTENTS (Complex & Tier 1) — page 2, filled in on the second pass ═══
  if (hasToc && toc.length) {
    doc.setPage(2);
    let ty = 26;
    setDraw(accent); doc.setLineWidth(0.8); doc.line(marginL, ty, marginL + 14, ty);
    setText(accent); doc.setFont('helvetica', 'bold'); doc.setFontSize(12);
    doc.text('CONTENTS', marginL, ty + 5);
    ty += 17;
    let appHdrDone = false;
    for (const t of toc) {
      const isApp = /^Appendix/i.test(t.label);
      if (isApp && !appHdrDone) {
        ty += 4;
        setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5);
        doc.text('APPENDICES', marginL, ty); ty += 8.5;
        appHdrDone = true;
      }
      setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
      const lbl = doc.splitTextToSize(t.label, usableW - 26)[0];
      doc.text(lbl, marginL + 2, ty);
      if (typeof doc.setLineDashPattern === 'function') {
        setDraw(RULE); doc.setLineWidth(0.2); doc.setLineDashPattern([0.5, 1.4], 0);
        doc.line(marginL + 2 + doc.getTextWidth(lbl) + 3, ty - 0.9, pageW - marginR - 10, ty - 0.9);
        doc.setLineDashPattern([], 0);
      }
      setText(MUTED); doc.setFont('helvetica', 'normal');
      doc.text(String(t.page), pageW - marginR, ty, { align: 'right' });
      ty += 7.5;
    }
  }

  // ═══ FOOTER + running header (second pass) ═══
  const pageCount = doc.internal.getNumberOfPages();
  const firstContentPage = 1 + (hasCover ? 1 : 0) + (hasToc ? 1 : 0);
  for (let p = 1; p <= pageCount; p++) {
    doc.setPage(p);
    const pw = doc.internal.pageSize.getWidth(), ph = doc.internal.pageSize.getHeight();
    if (hasCover && p === 1) continue;               // clean cover — no header/footer
    if (p > firstContentPage) {                      // running header on continuation pages
      setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
      doc.text(`${g.companyName || 'BAMA Fabrication'} \u2014 ${rams.docNo || 'RAMS'}${rams.title ? ' \u00b7 ' + rams.title : ''}`, marginL, 8.5);
      setDraw(RULE); doc.setLineWidth(0.2); doc.line(marginL, 10.3, pw - marginR, 10.3);
    }
    setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.text(`${rams.docNo || 'RAMS'}${rams.rev ? ' \u00b7 Rev ' + rams.rev : ''}`, marginL, ph - 9);
    doc.text(`Page ${p} of ${pageCount}`, pw - marginR, ph - 9, { align: 'right' });
  }

  return doc.output('blob');
}

async function renderRamsPdfBlob(rams) {
  const JsPDFCtor = await resolveJsPDFCtor();
  if (!JsPDFCtor) throw new Error('PDF library failed to load');
  const logo = (typeof _logoDataUriCache !== 'undefined' && _logoDataUriCache) || '';
  const blob = drawRamsPDF(JsPDFCtor, rams, logo);
  console.log('[RAMS PDF] blob size:', blob.size, 'bytes (native jsPDF)');
  if (blob.size < 8000) console.warn('[RAMS PDF] blob suspiciously small (<8KB) — check capture');
  return blob;
}

// ═══════════════════════════════════════════════════════════════════════════
// RAMS DOCX renderer (phase 7) — second deterministic renderer consuming the
// SAME structured `rams` object as drawRamsPDF, so generation code never
// changes. Built on docx.js (dolanmiu/docx v9, UMD from jsDelivr — the lib is
// not hosted on cdnjs). Word output is editable: the principal contractor can
// tweak wording without asking us to re-issue.
//
// Split mirrors the PDF path exactly:
//   • renderRamsDocxBlob(rams)  — async shell: loads the library, resolves
//     image dimensions (browser Image()), composites the site-plan pin onto
//     the image via canvas (docx has no vector overlay), then packs.
//   • drawRamsDOCX(docx, rams, assets) — PURE + synchronous: consumes
//     pre-resolved image assets, returns a docx.Document. Node-testable.
// ═══════════════════════════════════════════════════════════════════════════

async function resolveDocxLib() {
  const pick = () => (typeof window.docx !== 'undefined' && typeof window.docx.Document === 'function') ? window.docx : null;
  let lib = pick();
  if (lib) return lib;
  await new Promise((resolve, reject) => {
    const existing = document.querySelector('script[data-docx-loaded]');
    if (existing) {
      let tries = 0;
      const tick = () => { if (pick()) return resolve(); if (++tries > 60) return reject(new Error('docx.js load timed out')); setTimeout(tick, 100); };
      return tick();
    }
    const sc = document.createElement('script');
    sc.src = 'https://cdn.jsdelivr.net/npm/docx@9.7.1/dist/index.umd.cjs';
    sc.dataset.docxLoaded = '1';
    sc.onload = resolve;
    sc.onerror = () => reject(new Error('Failed to load docx.js from CDN'));
    document.head.appendChild(sc);
  });
  return pick();
}

// data:image/png;base64,xxxx → Uint8Array
function _dataUriToU8(dataUri) {
  const b64 = String(dataUri).split(',')[1] || '';
  const bin = atob(b64);
  const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return u8;
}
function _dataUriImgType(dataUri) {
  const m = String(dataUri).match(/^data:image\/(\w+)/);
  const t = (m && m[1] || 'png').toLowerCase();
  return t === 'jpeg' ? 'jpg' : (['png', 'jpg', 'gif', 'bmp'].includes(t) ? t : 'png');
}
// Natural pixel dimensions of a data-URI image (data URIs have no
// naturalWidth until decoded — same lesson as jsPDF's getImageProperties).
function _dataUriDims(dataUri) {
  return new Promise(resolve => {
    try {
      const img = new Image();
      img.onload = () => resolve({ w: img.naturalWidth || img.width, h: img.naturalHeight || img.height });
      img.onerror = () => resolve(null);
      img.src = dataUri;
    } catch (e) { resolve(null); }
  });
}
// Burn the WORK AREA pin into the site-plan image via canvas — docx can only
// embed flat images, so the vector marker the PDF draws is composited here.
async function _ramsCompositePin(dataUri, pin) {
  if (!pin || !isFinite(pin.x) || !isFinite(pin.y)) return dataUri;
  try {
    const dims = await _dataUriDims(dataUri);
    if (!dims || !dims.w || !dims.h) return dataUri;
    const img = new Image();
    await new Promise((res, rej) => { img.onload = res; img.onerror = rej; img.src = dataUri; });
    const cv = document.createElement('canvas');
    cv.width = dims.w; cv.height = dims.h;
    const ctx = cv.getContext('2d');
    ctx.drawImage(img, 0, 0);
    const px = dims.w * pin.x / 100, py = dims.h * pin.y / 100;
    const u = Math.max(dims.w, dims.h) / 210;          // ~1 "mm" at A4 scale
    ctx.fillStyle = '#e5484d';
    ctx.beginPath();                                    // teardrop stem, apex on the point
    ctx.moveTo(px - 1.7 * u, py - 3.4 * u); ctx.lineTo(px + 1.7 * u, py - 3.4 * u); ctx.lineTo(px, py);
    ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.arc(px, py - 4.6 * u, 2.5 * u, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.arc(px, py - 4.6 * u, 1.0 * u, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#e5484d';
    ctx.font = 'bold ' + Math.round(3.2 * u) + 'px Arial';
    ctx.textAlign = 'center';
    const labelAbove = pin.y > 10;
    ctx.fillText('WORK AREA', Math.max(9 * u, Math.min(dims.w - 9 * u, px)), labelAbove ? py - 8.4 * u : py + 3.9 * u);
    return cv.toDataURL('image/png');
  } catch (e) { return dataUri; }
}

// Pure renderer. `assets` = { logo: {u8,type,w,h}|null, plan: {u8,type,w,h}|null }
// with w/h already scaled to render size in PIXELS (96dpi).
function drawRamsDOCX(docx, rams, assets) {
  const tier = rams.tier || 'complex';
  const s = (typeof _pickTplSettings === 'function') ? _pickTplSettings() : null;
  const g = (s && s.global) || (typeof TEMPLATE_DEFAULTS !== 'undefined' ? TEMPLATE_DEFAULTS.global
    : { companyName: 'BAMA FABRICATION', address: '', phone: '', email: '', vatNumber: '' });
  const ACCENT = 'FF6B00', TEXT = '222222', MUTED = '5A5A5A', RULE = 'CCCCCC', HEADFILL = 'F2F2F2';
  const riskHex = r => (r <= 6 ? 'D4EDDA' : r <= 12 ? 'FFF3CD' : 'F8D7DA');
  const MM = 56.6929;                                   // mm → twips
  const M = Math.round(14 * MM);                        // 14mm margins, same as the PDF
  const A4W = 11906, A4H = 16838;
  const PORTRAIT_USABLE = A4W - 2 * M, LANDSCAPE_USABLE = A4H - 2 * M;

  const { Document, Paragraph, TextRun, ImageRun, Table, TableRow, TableCell, Header, Footer,
          AlignmentType, WidthType, BorderStyle, HeadingLevel, PageOrientation, PageNumber,
          TableOfContents, VerticalAlign, ShadingType } = docx;

  const NOB = { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' };
  const NOBORDERS = { top: NOB, bottom: NOB, left: NOB, right: NOB, insideHorizontal: NOB, insideVertical: NOB };
  const thin = c => ({ style: BorderStyle.SINGLE, size: 4, color: c || RULE });
  const GRID = { top: thin(), bottom: thin(), left: thin(), right: thin(), insideHorizontal: thin(), insideVertical: thin() };

  const run = (t, o) => new TextRun(Object.assign({ text: String(t == null ? '' : t), font: 'Arial' }, o || {}));
  const para = (t, o) => {
    o = o || {};
    return new Paragraph({
      alignment: o.align, spacing: o.spacing || { after: 80 },
      children: [run(t, { size: o.size || 19, bold: o.bold, italics: o.italic, color: o.color || TEXT })]
    });
  };
  const bullets = items => (items || []).map(it => new Paragraph({
    bullet: { level: 0 }, spacing: { after: 60 },
    children: [run(it, { size: 19 })]
  }));
  const numbered = items => (items || []).map((it, i) => new Paragraph({
    spacing: { after: 60 }, indent: { left: 360, hanging: 360 },
    children: [run((i + 1) + '.\u2002', { size: 19, color: MUTED }), run(it, { size: 19 })]
  }));

  let secNum = 0;
  const numHeading = t => { secNum++; return new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 240, after: 100 }, children: [run(secNum + '. ' + t, { size: 22, bold: true, color: ACCENT })] }); };
  const appHeading = t => new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 120, after: 100 }, children: [run(t, { size: 22, bold: true, color: ACCENT })] });

  const cellPara = (t, o) => new Paragraph({ spacing: { after: 20 }, alignment: o && o.align, children: [run(t, Object.assign({ size: 17 }, o || {}))] });
  const cell = (children, o) => new TableCell(Object.assign({
    children: Array.isArray(children) ? children : [children],
    verticalAlign: VerticalAlign.CENTER,
    margins: { top: 40, bottom: 40, left: 80, right: 80 }
  }, o || {}));

  // Two-column label/value table (borderless) — cover Details & project details.
  const kvTable = (rows, labelMm, usableTw) => new Table({
    width: { size: usableTw, type: WidthType.DXA },
    columnWidths: [Math.round(labelMm * MM), usableTw - Math.round(labelMm * MM)],
    borders: NOBORDERS,
    rows: rows.map(([lab, val]) => new TableRow({
      children: [
        cell(cellPara(lab, { bold: true, color: MUTED, size: 18 })),
        cell(cellPara(val, { size: 18 }))
      ]
    }))
  });

  // ── Running header / footer (defined per section; cover stays clean) ──
  const runningHeader = () => new Header({
    children: [new Paragraph({
      spacing: { after: 60 },
      border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: RULE, space: 2 } },
      children: [run(`${g.companyName || 'BAMA Fabrication'} \u2014 ${rams.docNo || 'RAMS'}${rams.title ? ' \u00b7 ' + rams.title : ''}`, { size: 15, color: MUTED })]
    })]
  });
  const runningFooter = () => new Footer({
    children: [new Paragraph({
      tabStops: [{ type: 'right', position: PORTRAIT_USABLE }],
      children: [
        run(`${rams.docNo || 'RAMS'}${rams.rev ? ' \u00b7 Rev ' + rams.rev : ''}`, { size: 15, color: MUTED }),
        new TextRun({ text: '\tPage ', font: 'Arial', size: 15, color: MUTED }),
        new TextRun({ children: [PageNumber.CURRENT], font: 'Arial', size: 15, color: MUTED }),
        new TextRun({ text: ' of ', font: 'Arial', size: 15, color: MUTED }),
        new TextRun({ children: [PageNumber.TOTAL_PAGES], font: 'Arial', size: 15, color: MUTED })
      ]
    })]
  });
  const emptyHF = { headers: { default: new Header({ children: [] }) }, footers: { default: new Footer({ children: [] }) } };

  const pagePortrait = { size: { width: A4W, height: A4H, orientation: PageOrientation.PORTRAIT }, margin: { top: M, right: M, bottom: M, left: M } };
  // NB: docx.js swaps width/height itself when orientation is LANDSCAPE —
  // always pass PORTRAIT dims here or it double-swaps back to portrait.
  const pageLandscape = { size: { width: A4W, height: A4H, orientation: PageOrientation.LANDSCAPE }, margin: { top: M, right: M, bottom: M, left: M } };

  const sections = [];
  const hasCover = tier !== 'brief';

  // ═══ COVER (Complex & Tier 1) ═══
  if (hasCover) {
    const cov = [];
    cov.push(new Paragraph({ spacing: { after: 200 }, children: [] }));
    if (assets && assets.logo) {
      cov.push(new Paragraph({
        alignment: AlignmentType.CENTER, spacing: { after: 300 },
        children: [new ImageRun({ type: assets.logo.type, data: assets.logo.u8, transformation: { width: assets.logo.w, height: assets.logo.h } })]
      }));
    } else {
      cov.push(para(g.companyName || 'BAMA FABRICATION', { align: AlignmentType.CENTER, size: 48, bold: true, color: ACCENT, spacing: { after: 300 } }));
    }
    cov.push(para('RISK ASSESSMENT &', { align: AlignmentType.CENTER, size: 40, bold: true, spacing: { after: 40 } }));
    cov.push(para('METHOD STATEMENT', { align: AlignmentType.CENTER, size: 40, bold: true, spacing: { after: 400 } }));

    cov.push(new Paragraph({
      spacing: { after: 140 },
      border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: TEXT, space: 2 } },
      children: [run('Details', { size: 22, bold: true })]
    }));
    const coverRows = [
      ['Contract name', rams.contract], ['Contract No', rams.contractNo], ['Client', rams.client],
      ['Principal contractor', rams.principal], ['Title', rams.title],
      ['Jobs covered', (Array.isArray(rams.jobsCovered) && rams.jobsCovered.length > 1) ? rams.jobsCovered.join(', ') : null],
      ['Document No', rams.docNo],
      ['Revision', rams.rev], ['Issue date', rams.dateStr]
    ].filter(r => r[1] != null && String(r[1]).trim() !== '');
    cov.push(kvTable(coverRows.map(([l, v]) => [l + ':', v]), 52, PORTRAIT_USABLE));
    cov.push(new Paragraph({ spacing: { after: 200 }, children: [] }));
    cov.push(new Paragraph({
      spacing: { after: 200 },
      border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: TEXT, space: 2 } },
      children: [run('Authorisation', { size: 22, bold: true })]
    }));
    const signLine = (label, name) => new Paragraph({
      spacing: { after: 360 },
      children: [
        run(`${label}: ${name || ''}`, { size: 21 }),
        run('        Signature: ', { size: 21 }),
        run('\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0\u00a0', { size: 21, underline: {} })
      ]
    });
    cov.push(signLine('Prepared by', rams.preparedBy));
    cov.push(signLine('Approved by', rams.preparedBy));
    sections.push(Object.assign({ properties: { page: pagePortrait }, children: cov }, emptyHF));

    // ═══ CONTENTS — a live Word TOC field (updates on open via updateFields) ═══
    sections.push({
      properties: { page: pagePortrait },
      headers: { default: runningHeader() }, footers: { default: runningFooter() },
      children: [
        new Paragraph({ spacing: { before: 200, after: 160 }, children: [run('CONTENTS', { size: 24, bold: true, color: ACCENT })] }),
        new TableOfContents('Contents', { hyperlink: true, headingStyleRange: '1-1' })
      ]
    });
  }

  // ═══ MAIN BODY ═══
  const body = [];
  if (assets && assets.logoSmall) {
    body.push(new Paragraph({ spacing: { after: 60 }, children: [new ImageRun({ type: assets.logoSmall.type, data: assets.logoSmall.u8, transformation: { width: assets.logoSmall.w, height: assets.logoSmall.h } })] }));
  } else {
    body.push(para(g.companyName || 'BAMA FABRICATION', { size: 34, bold: true, color: ACCENT, spacing: { after: 40 } }));
  }
  const coLines = [];
  if (g.address) String(g.address).split('\n').forEach(l => coLines.push(l));
  if (g.phone) coLines.push('Tel: ' + g.phone);
  if (g.email) coLines.push(g.email);
  coLines.forEach(l => body.push(para(l, { size: 16, color: MUTED, spacing: { after: 20 } })));
  body.push(new Paragraph({
    spacing: { before: 80, after: 60 },
    children: [run('RAMS \u2014 Risk Assessment & Method Statement', { size: 26, bold: true, italics: true, color: ACCENT })]
  }));
  const metaRows = [
    ['Document No', rams.docNo], ['Revision', rams.rev], ['Date', rams.dateStr], ['Prepared by', rams.preparedBy]
  ].filter(r => r[1] != null && String(r[1]).trim() !== '');
  if (metaRows.length) body.push(kvTable(metaRows.map(([l, v]) => [l + ':', v]), 34, Math.round(PORTRAIT_USABLE * 0.55)));
  body.push(new Paragraph({
    spacing: { after: 140 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: TEXT, space: 4 } },
    children: []
  }));

  const detailRows = [
    ['Contract / Project', rams.contract],
    ['Works title', rams.title],
    ['Client', rams.client],
    ['Principal contractor', rams.principal],
    ['Contract No', rams.contractNo],
    ['Drawing reference', rams.drawingRef],
    ['Site', rams.site && rams.site.name],
    ['Site address', (rams.site && rams.site.lines || []).join(', ')],
    ['Site contact', [rams.site && rams.site.contactName, rams.site && rams.site.contactPhone].filter(Boolean).join(' \u00b7 ')],
    ['Working hours', rams.hours],
    ['Nearest A&E', rams.ae]
  ].filter(r => r[1] != null && String(r[1]).trim() !== '');
  if (detailRows.length) body.push(kvTable(detailRows, 44, PORTRAIT_USABLE));

  // ── Document Control (tier 1 only) ──
  if (tier === 'tier1') {
    body.push(numHeading('Document Control & Approval'));
    body.push(para(`Revision ${rams.rev || '00'}${rams.dateStr ? ' \u2014 issued ' + rams.dateStr : ''}. This document will be reviewed and re-issued if the scope, site conditions or method of work change.`, { size: 18 }));
    const dcW = [30, 55, 69, 28].map(mm => Math.round(mm * MM));
    body.push(new Table({
      width: { size: PORTRAIT_USABLE, type: WidthType.DXA }, columnWidths: dcW, borders: GRID,
      rows: [
        new TableRow({ tableHeader: true, children: ['Role', 'Name', 'Signature', 'Date'].map(t => cell(cellPara(t, { bold: true, size: 16 }), { shading: { type: ShadingType.CLEAR, fill: HEADFILL } })) }),
        ...[['Prepared by', rams.preparedBy || ''], ['Reviewed by', ''], ['Approved by', '']].map(([role, name]) =>
          new TableRow({ height: { value: 500, rule: 'atLeast' }, children: [cell(cellPara(role, { bold: true })), cell(cellPara(name)), cell(cellPara('')), cell(cellPara(''))] }))
      ]
    }));
  }

  // ── Scope ──
  if ((rams.scopeLines || []).length) { body.push(numHeading('Scope of Works')); numbered(rams.scopeLines).forEach(p => body.push(p)); }

  // ── Programme ──
  body.push(numHeading('Programme & Working Hours'));
  body.push(para(tier === 'brief'
    ? (rams.hours
        ? `Working hours: ${rams.hours}. Programme to be agreed with the principal contractor.`
        : 'Programme and working hours to be agreed with the principal contractor.')
    : (rams.hours
        ? `Works will be carried out during the following hours: ${rams.hours}. Actual dates and durations to be confirmed with the principal contractor and coordinated at site induction.`
        : 'Working hours and programme to be confirmed with the principal contractor at site induction.')));

  // ── Inductions & briefings ──
  const inductions = rams.inductions || RAMS_STANDARD.inductions;
  const dab        = rams.dab        || RAMS_STANDARD.dab;
  if (inductions.length || dab.length) {
    body.push(numHeading('Inductions & Briefings'));
    if (inductions.length) {
      body.push(para('This RAMS and the associated task briefings will be reviewed, updated and re-issued if the methodology changes or additional tasks are introduced. Pre-requisites before works commence:', { size: 18 }));
      bullets(inductions).forEach(p => body.push(p));
    }
    if (dab.length) {
      body.push(para('Daily Activity Briefing', { bold: true }));
      body.push(para('Before starting any works, all operatives will participate in a Daily Activity Briefing covering:', { size: 18 }));
      bullets(dab).forEach(p => body.push(p));
    }
  }

  // ── Sequence of works ──
  if ((rams.tasks || []).length) {
    body.push(numHeading('Sequence of Works'));
    rams.tasks.forEach((t, i) => {
      body.push(new Paragraph({ spacing: { before: 100, after: 40 }, children: [run(`${i + 1}. ${t.title}`, { size: 19, bold: true })] }));
      if (t.detail) body.push(new Paragraph({ spacing: { after: 40 }, indent: { left: 400 }, children: [run(t.detail, { size: 19, color: '464646' })] }));
      (Array.isArray(t.steps) ? t.steps : []).forEach((st, k) => {
        body.push(new Paragraph({
          spacing: { after: 40 }, indent: { left: 760, hanging: 280 },
          children: [run(String.fromCharCode(97 + (k % 26)) + '.\u2002', { size: 19, color: MUTED }), run(st, { size: 19 })]
        }));
      });
    });
  }

  // ── Key personnel ──
  body.push(numHeading('Key Personnel & Competency'));
  const people = rams.personnel || [];
  if (people.length) {
    const pcW = [46, 44, 40, 52].map(mm => Math.round(mm * MM));
    body.push(new Table({
      width: { size: PORTRAIT_USABLE, type: WidthType.DXA }, columnWidths: pcW, borders: GRID,
      rows: [
        new TableRow({ tableHeader: true, children: ['Name', 'Site role', 'Company', 'Certifications'].map(t => cell(cellPara(t, { bold: true, size: 16 }), { shading: { type: ShadingType.CLEAR, fill: HEADFILL } })) }),
        ...people.map(p => new TableRow({
          children: [
            cell(cellPara(p.name, { bold: true })),
            cell(cellPara(p.site_role || p.role || '\u2014')),
            cell(cellPara('BAMA Fabrication')),
            cell(cellPara((p.certs || []).join(', ') || '\u2014'))
          ]
        }))
      ]
    }));
  } else {
    body.push(para('Site personnel to be confirmed at induction. All operatives to hold valid CSCS (or equivalent) and task-specific competency cards.', { italic: true, color: MUTED, size: 18 }));
  }

  // ── Standard sections (ticked in the modal) ──
  const plant       = rams.plant       || RAMS_STANDARD.plant;
  const materials   = rams.materials   || RAMS_STANDARD.materials;
  const ppe         = rams.ppe         || RAMS_STANDARD.ppe;
  const access      = rams.access      || RAMS_STANDARD.access;
  const environment = rams.environment || RAMS_STANDARD.environment;
  const monitoring  = rams.monitoring  || RAMS_STANDARD.monitoring;

  if (plant.length || materials.length) {
    body.push(numHeading('Plant, Equipment & Materials'));
    if (plant.length)     { body.push(para('Plant & equipment:', { bold: true })); bullets(plant).forEach(p => body.push(p)); }
    if (materials.length) { body.push(para('Materials:', { bold: true })); bullets(materials).forEach(p => body.push(p)); }
  }
  if (ppe.length) {
    body.push(numHeading('Personal Protective Equipment (PPE)'));
    body.push(para('The following PPE is mandatory / task-specific as noted. Minimum site PPE (hard hat, boots, hi-vis, glasses, gloves) worn at all times:', { size: 18 }));
    bullets(ppe).forEach(p => body.push(p));
  }
  if (access.length)      { body.push(numHeading('Access & Egress'));       bullets(access).forEach(p => body.push(p)); }
  if (environment.length) { body.push(numHeading('Environmental & Waste')); bullets(environment).forEach(p => body.push(p)); }

  body.push(numHeading('Emergency Arrangements'));
  const emergencyLines = tier === 'brief'
    ? [
        'On discovering an emergency, raise the alarm and follow the site emergency procedure. Trained first-aider and first-aid kit available on site.',
        rams.ae ? `Nearest A&E: ${rams.ae}.` : 'Nearest A&E to be confirmed at site induction.',
        'Report all accidents, incidents and near-misses to the site manager and BAMA office.'
      ]
    : [
        'On discovering an emergency, raise the alarm and follow the site emergency procedure.',
        'Make the area safe if it is safe to do so; do not put yourself at risk.',
        'Trained first-aider and first-aid kit available on site.',
        rams.ae ? `Nearest A&E: ${rams.ae}.` : 'Nearest A&E to be confirmed at site induction.',
        'Report all accidents, incidents and near-misses to the site manager and BAMA office.'
      ];
  if (tier === 'tier1') {
    emergencyLines.push('All RIDDOR-reportable injuries, diseases and dangerous occurrences will be reported to the HSE in line with statutory requirements and notified to the principal contractor.');
    emergencyLines.push('Emergency contact numbers and muster points to be obtained from the principal contractor at induction and held by the BAMA supervisor.');
  }
  bullets(emergencyLines).forEach(p => body.push(p));

  if (monitoring.length) { body.push(numHeading('Monitoring & Review')); bullets(monitoring).forEach(p => body.push(p)); }
  if (rams.notes && String(rams.notes).trim()) { body.push(numHeading('Additional Notes')); body.push(para(rams.notes)); }

  // ── Site plan (pin already composited into the image by the async shell) ──
  if (assets && assets.plan) {
    body.push(numHeading('Site Plan'));
    body.push(new Paragraph({
      alignment: AlignmentType.CENTER, spacing: { after: 80 },
      children: [new ImageRun({ type: assets.plan.type, data: assets.plan.u8, transformation: { width: assets.plan.w, height: assets.plan.h } })]
    }));
  }

  sections.push({
    properties: { page: pagePortrait },
    headers: { default: runningHeader() }, footers: { default: runningFooter() },
    children: body
  });

  // ═══ APPENDIX A — RISK ASSESSMENT (landscape) ═══
  const appA = [];
  appA.push(appHeading('Appendix A \u2014 Risk Assessment'));
  appA.push(para('Risk rating R = Likelihood (L, 1\u20135) \u00d7 Severity (S, 1\u20135). "Initial" is the risk before controls; "Residual" is the risk with the controls below applied. Bands: 1\u20136 low, 7\u201312 medium, 13\u201325 high.', { size: 16, color: MUTED }));

  if (tier !== 'brief') {
    // 5×5 matrix legend as a shaded table (severity rows top-down 5→1).
    const mW = Math.round(11 * MM);
    const matrixRows = [];
    for (let sv = 5; sv >= 1; sv--) {
      matrixRows.push(new TableRow({
        children: [
          cell(cellPara(String(sv), { align: AlignmentType.CENTER, color: MUTED, size: 15 }), { borders: NOBORDERS }),
          ...[1, 2, 3, 4, 5].map(lk => cell(cellPara(String(sv * lk), { align: AlignmentType.CENTER, size: 15 }), { shading: { type: ShadingType.CLEAR, fill: riskHex(sv * lk) } }))
        ]
      }));
    }
    matrixRows.push(new TableRow({
      children: [cell(cellPara('S \u2191 / L \u2192', { align: AlignmentType.CENTER, color: MUTED, size: 13 }), { borders: NOBORDERS }),
        ...[1, 2, 3, 4, 5].map(lk => cell(cellPara(String(lk), { align: AlignmentType.CENTER, color: MUTED, size: 15 }), { borders: NOBORDERS }))]
    }));
    appA.push(new Table({ width: { size: mW * 6, type: WidthType.DXA }, columnWidths: [mW, mW, mW, mW, mW, mW], borders: GRID, rows: matrixRows }));
    appA.push(para('Likelihood: 1 = Very unlikely \u00b7 2 = Unlikely \u00b7 3 = Likely \u00b7 4 = Very likely \u00b7 5 = Almost certain', { size: 15, color: MUTED, spacing: { before: 80, after: 20 } }));
    appA.push(para('Severity: 1 = No injury \u00b7 2 = Minor injury or illness \u00b7 3 = "7 day" injury or illness \u00b7 4 = Major injury or illness \u00b7 5 = Fatality, disabling injury, etc.', { size: 15, color: MUTED, spacing: { after: 20 } }));
    appA.push(para('Bands: 1\u20136 acceptable \u00b7 7\u201312 further review \u00b7 13\u201325 unacceptable', { size: 15, color: MUTED, spacing: { after: 120 } }));
  }

  const risks = Array.isArray(rams.risks) ? rams.risks : RAMS_RISK_LIBRARY;
  const raW = [10, 44, 24, 8, 8, 9, 121, 8, 8, 9].map(mm => Math.round(mm * MM)); // sums 249mm < 269 usable
  raW[6] = LANDSCAPE_USABLE - raW.reduce((a, w, i) => i === 6 ? a : a + w, 0);
  const raHead = ['Ref', 'Activity / Hazard', 'At risk', 'L', 'S', 'R', 'Control measures', 'L', 'S', 'R'];
  const riskRows = [new TableRow({
    tableHeader: true,
    children: raHead.map((t, i) => cell(cellPara(t + (i === 3 ? ' (initial)' : i === 7 ? ' (residual)' : ''), { bold: true, size: 14, align: i >= 3 && i !== 6 ? AlignmentType.CENTER : undefined }), { shading: { type: ShadingType.CLEAR, fill: 'E8E8E8' } }))
  })];
  for (const r of risks) {
    const iR = r.iL * r.iS, rR = r.rL * r.rS;
    const ctrlParas = (r.controls || []).map(ci => new Paragraph({ bullet: { level: 0 }, spacing: { after: 20 }, children: [run(ci, { size: 15 })] }));
    if (r.whenWhere) ctrlParas.push(new Paragraph({ spacing: { after: 20 }, children: [run('When/where: ', { size: 15, bold: true, color: MUTED }), run(r.whenWhere, { size: 15, color: MUTED })] }));
    riskRows.push(new TableRow({
      children: [
        cell(cellPara(r.ref, { bold: true, size: 15 })),
        cell(cellPara(`${r.activity ? r.activity + ' \u2014 ' : ''}${r.hazard}`, { size: 15 })),
        cell(cellPara(r.who || '', { size: 15 })),
        cell(cellPara(r.iL, { align: AlignmentType.CENTER, size: 15 })),
        cell(cellPara(r.iS, { align: AlignmentType.CENTER, size: 15 })),
        cell(cellPara(iR, { align: AlignmentType.CENTER, bold: true, size: 15 }), { shading: { type: ShadingType.CLEAR, fill: riskHex(iR) } }),
        cell(ctrlParas.length ? ctrlParas : [cellPara('')]),
        cell(cellPara(r.rL, { align: AlignmentType.CENTER, size: 15 })),
        cell(cellPara(r.rS, { align: AlignmentType.CENTER, size: 15 })),
        cell(cellPara(rR, { align: AlignmentType.CENTER, bold: true, size: 15 }), { shading: { type: ShadingType.CLEAR, fill: riskHex(rR) } })
      ]
    }));
  }
  appA.push(new Table({ width: { size: LANDSCAPE_USABLE, type: WidthType.DXA }, columnWidths: raW, borders: GRID, rows: riskRows }));

  sections.push({
    properties: { page: pageLandscape },
    headers: { default: runningHeader() }, footers: { default: runningFooter() },
    children: appA
  });

  // ═══ APPENDIX B — BRIEFING REGISTER (portrait) ═══
  const appB = [];
  appB.push(appHeading('Appendix B \u2014 Briefing Register'));
  appB.push(para('I confirm that I have read, or have had explained to me, this Risk Assessment & Method Statement and I understand its contents and will comply with it.', { size: 17, color: MUTED }));
  const bcW = [55, 40, 57, 30].map(mm => Math.round(mm * MM));
  const roster = rams.personnel || [];
  const regRowCount = Math.max(
    ((RAMS_TIER_PRESETS[tier] || RAMS_TIER_PRESETS.complex).briefingRows) || 12,
    roster.length);
  const regRows = [new TableRow({
    tableHeader: true,
    children: ['Name', 'Company', 'Signature', 'Date'].map(t => cell(cellPara(t, { bold: true, size: 16 }), { shading: { type: ShadingType.CLEAR, fill: HEADFILL } }))
  })];
  for (let i = 0; i < regRowCount; i++) {
    const p = roster[i];
    regRows.push(new TableRow({
      height: { value: 460, rule: 'atLeast' },
      children: [
        cell(cellPara(p ? (p.name || '') : '', { size: 17, color: '464646' })),
        cell(cellPara(p ? 'BAMA Fabrication' : '', { size: 17, color: '464646' })),
        cell(cellPara('')), cell(cellPara(''))
      ]
    }));
  }
  appB.push(new Table({ width: { size: PORTRAIT_USABLE, type: WidthType.DXA }, columnWidths: bcW, borders: GRID, rows: regRows }));

  sections.push({
    properties: { page: pagePortrait },
    headers: { default: runningHeader() }, footers: { default: runningFooter() },
    children: appB
  });

  return new Document({
    creator: 'BAMA Fabrication ERP',
    title: `${rams.docNo || 'RAMS'}${rams.title ? ' \u2014 ' + rams.title : ''}`,
    subject: 'Risk Assessment & Method Statement',
    features: { updateFields: true },                   // Word refreshes the CONTENTS field on open
    styles: { default: { document: { run: { font: 'Arial', size: 19, color: TEXT } } } },
    sections
  });
}

// Async shell: library + image assets (dims via Image(), pin via canvas), pack.
async function renderRamsDocxBlob(rams) {
  const docxLib = await resolveDocxLib();
  if (!docxLib) throw new Error('DOCX library failed to load');

  const MM2PX = 96 / 25.4;                              // 96dpi px per mm — matches the PDF's mm sizing
  const prepImage = async (dataUri, maxWmm, maxHmm) => {
    if (!dataUri) return null;
    const dims = await _dataUriDims(dataUri);
    const ratio = (dims && dims.w && dims.h) ? dims.w / dims.h : 1.6;
    let wmm = maxWmm, hmm = wmm / ratio;
    if (maxHmm && hmm > maxHmm) { hmm = maxHmm; wmm = hmm * ratio; }
    return { u8: _dataUriToU8(dataUri), type: _dataUriImgType(dataUri), w: Math.round(wmm * MM2PX), h: Math.round(hmm * MM2PX) };
  };

  const logoUri = (typeof _logoDataUriCache !== 'undefined' && _logoDataUriCache) || '';
  let planUri = rams.sitePlanDataUri || null;
  if (planUri && rams.sitePlanPin) planUri = await _ramsCompositePin(planUri, rams.sitePlanPin);

  const assets = {
    logo:      logoUri ? await prepImage(logoUri, 72) : null,        // cover — 72mm wide, ratio preserved
    logoSmall: logoUri ? await prepImage(logoUri, 52) : null,        // body header — 52mm
    plan:      planUri ? await prepImage(planUri, 182, 170) : null   // usable width × 170mm cap, same as PDF
  };

  const doc = drawRamsDOCX(docxLib, rams, assets);
  const blob = await docxLib.Packer.toBlob(doc);
  console.log('[RAMS DOCX] blob size:', blob.size, 'bytes (docx.js)');
  if (blob.size < 4000) console.warn('[RAMS DOCX] blob suspiciously small (<4KB) \u2014 check content');
  return blob;
}

// Assemble the (editable) modal fields into a rams object, render natively with
// jsPDF, upload to the PROJECT-level 00 - RAMS/<job>/ SharePoint folder, and
// register it via POST /api/drawing-elements/{jobId}/file (fileContext 'rams').
async function confirmRams() {
  const proj = currentProject, job = currentJob;
  const btn = document.getElementById('ramsConfirmBtn');
  if (!job?.id) { toast('No job selected \u2014 cannot save.', 'error'); return; }
  if (!_ramsJobIds.length) { toast('Tick at least one job for this RAMS to cover.', 'error'); return; }
  if (btn) { btn.disabled = true; btn.style.opacity = '.5'; }
  try {
    await loadLogoDataUri();
    const getV = id => (document.getElementById(id)?.value || '').trim();
    const dateRaw = getV('ramsDate');
    const dateStr = dateRaw
      ? new Date(dateRaw + 'T12:00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })
      : '';

    // Sequence tasks: a title line ("Title: intro"), then optional "- step"
    // lines that belong to it. Blank lines just separate tasks.
    const tasks = [];
    getV('ramsTasksText').split('\n').forEach(raw => {
      const line = raw.trim();
      if (!line) return;
      const m = line.match(/^[-\u2022*]\s*(.+)$/);
      if (m && tasks.length) { tasks[tasks.length - 1].steps.push(m[1].trim()); return; }
      const idx = line.indexOf(':');
      tasks.push(idx > 0
        ? { title: line.slice(0, idx).trim(), detail: line.slice(idx + 1).trim(), steps: [] }
        : { title: line, detail: '', steps: [] });
    });

    // Personnel: prefer the structured roster selection; fall back to the
    // freeform textarea if the roster API was unavailable.
    if (typeof ramsSerializePersonnel === 'function') { try { ramsSerializePersonnel(); } catch (e) {} }
    let personnel = (typeof _ramsSelectedPersonnel !== 'undefined' && Array.isArray(_ramsSelectedPersonnel))
      ? _ramsSelectedPersonnel.slice() : [];
    if (!personnel.length) {
      personnel = getV('ramsPersonnel').split('\n').map(l => l.trim()).filter(Boolean).map(line => {
        const parts = line.split('\u2014').map(p => p.trim());
        return { name: parts[0] || line, site_role: parts[1] || '', type: 'staff', company: '', certs: parts[2] ? parts[2].split(',').map(c => c.trim()).filter(Boolean) : [] };
      });
    }

    const fmt = getV('ramsFormat') || 'pdf';   // 'pdf' | 'pdf-docx' (phase 7)

    const rams = {
      createdAt: new Date().toISOString(),
      docNo: getV('ramsDocNo'),
      contractNo: getV('ramsContractNo'),
      contract: getV('ramsContract'),
      title: getV('ramsTitle'),
      client: getV('ramsClient'),
      principal: getV('ramsPrincipal'),
      preparedBy: getV('ramsPreparedBy'),
      dateStr,
      rev: getV('ramsRev'),
      tier: getV('ramsTier') || 'complex',
      drawingRef: getV('ramsDrawingRef'),
      site: {
        name: getV('ramsSiteName'),
        lines: getV('ramsSiteAddr').split('\n').map(l => l.trim()).filter(Boolean),
        contactName: getV('ramsSiteContact'),
        contactPhone: getV('ramsSitePhone')
      },
      hours: getV('ramsHours'),
      ae: getV('ramsAE'),
      scopeLines: getV('ramsScopeText').split('\n').map(l => l.trim()).filter(Boolean),
      tasks,
      personnel,
      // Standard sections — only the ticked items (empty array = section dropped).
      inductions:  ramsCollectSection('inductions'),
      dab:         ramsCollectSection('dab'),
      plant:       ramsCollectSection('plant'),
      materials:   ramsCollectSection('materials'),
      ppe:         ramsCollectSection('ppe'),
      access:      ramsCollectSection('access'),
      environment: ramsCollectSection('environment'),
      monitoring:  ramsCollectSection('monitoring'),
      risks: ramsCollectRisks(),
      sitePlanDataUri: (typeof _ramsSitePlanDataUri !== 'undefined' && _ramsSitePlanDataUri) || null,
      sitePlanPin: (typeof _ramsSitePlanPin !== 'undefined' && _ramsSitePlanPin) || null,
      notes: getV('ramsNotes'),
      workBrief: getV('ramsWorkBrief'),
      // Register fields (numbering / revisions / merge)
      ramsNo: _ramsAssignedNo,
      revisionInt: _ramsRevisionInt,
      jobIds: _ramsJobIds.slice(),
      jobsCovered: _ramsJobIds.map(jid => {
        const jj = (drawingsData.projects?.[proj?.id]?.jobs || []).find(x => parseInt(x.id) === jid);
        return jj ? (jj.name || ('Job ' + jid)) : ('Job ' + jid);
      })
    };

    if (!rams.scopeLines.length && !rams.tasks.length) {
      toast('Add a scope of works or a sequence of works before generating.', 'error');
      if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
      return;
    }

    const blob = await renderRamsPdfBlob(rams);

    // Save to SharePoint: <ProjectFolder>/00 - RAMS/<folder>/<file>.pdf
    // (decision B — the PROJECT-level RAMS folder). Single-job RAMS files
    // under the job folder as before; a MERGED RAMS files under a folder named
    // after the document title. The PDF is registered against EVERY covered
    // job via DrawingElementFiles context 'rams' so it lists on each job's
    // Site Installation tab.
    const stamp = new Date().toISOString().slice(0, 10);
    const baseName = (rams.docNo || `RAMS - ${proj?.id || 'project'} - ${stamp}`).replace(/[\/\\:*?"<>|]/g, '-');
    const revTag = ` Rev ${_ramsPad(_ramsRevisionInt, 2)}`;
    const fileName = baseName + revTag + '.pdf';

    let uploaded, docxUploaded = null;
    try {
      const projectFolder = await findProjectFolder(proj.id);
      if (!projectFolder) throw new Error('project folder not found on SharePoint');
      const driveId = projectFolder.parentReference?.driveId || BAMA_DRIVE_ID;
      const ramsRoot = await getOrCreateSubfolder(projectFolder.id, '00 - RAMS', driveId);
      const jobFolderName = (_ramsJobIds.length > 1)
        ? (rams.title || baseName).replace(/[\/\\:*?"<>|]/g, '-')
        : (job.folderName || job.name || 'Unassigned');
      const jobSub = await getOrCreateSubfolder(ramsRoot.id, jobFolderName, driveId);
      const arrayBuffer = await blob.arrayBuffer();
      uploaded = await uploadFileToFolder(jobSub.id, fileName, arrayBuffer, 'application/pdf', driveId);

      // Register against every covered job. currentJob keeps its in-memory
      // list fresh; other jobs pick it up from SQL on next open.
      for (const jid of _ramsJobIds) {
        try {
          const saved = await api.post(`/api/drawing-elements/${jid}/file`, {
            fileContext: 'rams', name: baseName + revTag, fileName,
            fileId: uploaded.id, driveId: uploaded.parentReference?.driveId || driveId,
            webUrl: uploaded.webUrl, uploadedAt: new Date().toISOString(),
            uploadedBy: _currentDraftsmanName || null
          });
          if (parseInt(job.id) === jid) {
            if (!job.rams) job.rams = { files: [] };
            job.rams.files.push({ ...saved });
          }
        } catch (regErr) {
          toast(`RAMS saved, but registering it on job ${jid} failed: ${regErr.message}`, 'error');
        }
      }

      // Phase 7 — editable Word twin. Same rams object, second deterministic
      // renderer (docx.js). A DOCX failure never sinks the flow: the PDF is
      // already saved, so warn and carry on.
      if (fmt === 'pdf-docx') {
        try {
          const docxBlob = await renderRamsDocxBlob(rams);
          const docxName = baseName + revTag + '.docx';
          const ab2 = await docxBlob.arrayBuffer();
          const up2 = await uploadFileToFolder(jobSub.id, docxName, ab2,
            'application/vnd.openxmlformats-officedocument.wordprocessingml.document', driveId);
          docxUploaded = up2;
          for (const jid of _ramsJobIds) {
            try {
              const saved2 = await api.post(`/api/drawing-elements/${jid}/file`, {
                fileContext: 'rams', name: baseName + revTag + ' (Word)', fileName: docxName,
                fileId: up2.id, driveId: up2.parentReference?.driveId || driveId,
                webUrl: up2.webUrl, uploadedAt: new Date().toISOString(),
                uploadedBy: _currentDraftsmanName || null
              });
              if (parseInt(job.id) === jid) job.rams.files.push({ ...saved2 });
            } catch (regErr) { /* PDF registration toast already covers the pattern */ }
          }
        } catch (docxErr) {
          toast('PDF saved, but the Word (.docx) version failed: ' + docxErr.message, 'error');
        }
      }

      // ── RAMS register row (numbering / revisions). Non-fatal: the PDF is
      // already filed, so a register failure warns rather than sinks the flow.
      if (_ramsAssignedNo) {
        try {
          await api.post('/api/rams-docs', {
            project_id: parseInt(proj.dbId),
            rams_no: _ramsAssignedNo,
            revision: _ramsRevisionInt,
            title: rams.title || null,
            doc_no: rams.docNo || null,
            job_ids: _ramsJobIds,
            rams_data: rams,
            pdf_file_id: uploaded.id,
            pdf_drive_id: uploaded.parentReference?.driveId || driveId,
            pdf_web_url: uploaded.webUrl,
            docx_file_id: docxUploaded?.id || null,
            docx_drive_id: docxUploaded?.parentReference?.driveId || null,
            docx_web_url: docxUploaded?.webUrl || null,
            created_by: _currentDraftsmanName || null
          });
          delete _ramsDocsCache[parseInt(proj.dbId)];
        } catch (regErr) {
          toast('RAMS saved, but the register entry failed (' + regErr.message + ') \u2014 revisions of this document won\u2019t be available. Has create-rams-documents.sql been run?', 'error');
        }
      }
    } catch (saveErr) {
      // Never lose the document: open it for a manual save and say why.
      const url = URL.createObjectURL(blob);
      window.open(url, '_blank');
      setTimeout(() => URL.revokeObjectURL(url), 60000);
      toast('RAMS generated but SharePoint save failed (' + saveErr.message + ') \u2014 PDF opened in a new tab, save it manually.', 'error');
      return;
    }

    closeRamsModal();
    toast(fmt === 'pdf-docx' ? 'RAMS generated \u2014 PDF + Word saved to 00 - RAMS.' : 'RAMS generated & saved to 00 - RAMS.', 'success');
    renderSite();
    if (uploaded.webUrl) window.open(uploaded.webUrl, '_blank');
  } catch (e) {
    toast('RAMS generation failed: ' + e.message, 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
  }
}

// AI step — read the selected drawing(s) and draft the numbered Scope of Work.
// Two-engine: AI reads the drawing, never computes quantities. On any failure
// it drops in a deterministic template so the user is never blocked.
async function sitePackGenerateScope() {
  const checks = [...document.querySelectorAll('.sp-draw-check:checked')];
  const btn = document.getElementById('spGenScopeBtn');
  const sts = document.getElementById('spScopeStatus');
  const ta  = document.getElementById('spScopeText');
  if (!ta) return;

  const contract = (document.getElementById('spContract')?.value    || '').trim();
  const finish   = (document.getElementById('spFinish')?.value      || '').trim();
  const grade    = (document.getElementById('spGrade')?.value       || '').trim();
  const drawRef  = (document.getElementById('spDrawingRef')?.value  || '').trim();
  const fixText  = _sitePackCollectFixings().map(f => `${f.qty} x ${f.description} (${f.coating})`).join('\n') || '(none listed)';

  if (!checks.length) {
    if (sts) { sts.style.color = 'var(--red)'; sts.textContent = 'Tick at least one drawing to read (or type the scope manually).'; }
    return;
  }
  if (btn) { btn.disabled = true; btn.style.opacity = '.5'; }
  if (sts) { sts.style.color = 'var(--muted)'; sts.textContent = 'Reading drawing…'; }

  // Build the drawing content blocks.
  const blocks = [];
  try {
    for (const c of checks) {
      const b64 = await _sitePackFetchBase64(c.dataset.fileid, c.dataset.driveid);
      const mt = _sitePackMediaType(c.dataset.fname);
      blocks.push(mt.isImage
        ? { type: 'image',    source: { type: 'base64', media_type: mt.media, data: b64 } }
        : { type: 'document', source: { type: 'base64', media_type: mt.media, data: b64 }, title: c.dataset.fname });
    }
  } catch (e) {
    if (sts) { sts.style.color = 'var(--red)'; sts.textContent = 'Could not load drawing: ' + e.message; }
    if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
    return;
  }

  const systemPrompt = `You are a site-installation planner for BAMA Fabrication, a structural steel fabricator in Peterborough. Read the supplied drawing(s) and write a clear, numbered SCOPE OF WORK for the installation crew on site.\n\nYou are a READER, not a calculator: describe WHAT is to be installed and HOW it is fixed, based on what the drawing shows. Do NOT invent or calculate quantities, dimensions, or member counts that are not shown — the fixings list supplied by the user is authoritative for quantities.`;

  // Brief (default) is the working document erectors scan on site — the detailed
  // method statement lives in the RAMS, so keep it lean. Extended is for jobs
  // with no RAMS or a non-standard install.
  const detail = (document.getElementById('spScopeDetail')?.value || 'brief');
  const detailRule = detail === 'extended'
    ? '- LENGTH: fuller scope — cover the install sequence in more detail: setting-out, fixing method per element, and any splice/joint requirements. Longer sentences are fine, but keep it to numbered install steps, NOT a method statement.'
    : '- LENGTH: keep it BRIEF — this pack is for erectors and the detailed method statement lives in the RAMS. Essential install steps only, each a single short imperative sentence. Aim for 3-6 lines. Each step must still say WHAT to install and HOW to fix it, but no elaboration, no sequencing prose, no health-and-safety notes, no sub-steps.';

  const userPrompt = `Project / contract: ${contract || '(unspecified)'}\nFinish: ${finish || '(unspecified)'}    Grade: ${grade || '(unspecified)'}\nDrawing reference: ${drawRef || '(see attached)'}\n\nItems being taken to site (from the job BOM — authoritative for quantities):\n${fixText}\n\nWrite the SCOPE OF WORK as numbered installation instructions for the crew.\nRULES:\n- Output ONLY numbered lines ("1.", "2.", ...), one instruction each. No heading, no preamble, no sign-off.\n- Say WHAT to install and HOW to fix it, referencing the drawing by its reference where relevant.\n- Use the fixings above to describe the fixing method (plugs + screws, bolts, splice locks, etc.).\n- Call out any splice / joint / lock / setting-out requirements the drawing shows.\n- Do NOT restate the fixings table as a list, and do NOT invent quantities or dimensions not shown.\n- Strictly UK English, concise, imperative ("Install...", "Fix...", "Provide...").\n${detailRule}`;

  try {
    const requestBody = {
      model: 'claude-sonnet-4-6', max_tokens: 1200, system: systemPrompt,
      messages: [{ role: 'user', content: [ ...blocks, { type: 'text', text: userPrompt } ] }]
    };
    const doFetch = () => fetch(API_BASE + '/api/claude-proxy', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${sessionStorage.getItem('bama_token')}` },
      body: JSON.stringify(requestBody)
    });
    let response = await doFetch();
    let data = await response.json();
    if (response.status === 429) {
      if (sts) sts.textContent = 'Rate limit — waiting 30s before retry…';
      await new Promise(r => setTimeout(r, 30000));
      response = await doFetch(); data = await response.json();
      if (response.status === 429) throw new Error('still rate limited — wait a minute and retry');
    }
    if (data.error) throw new Error(data.error.message);
    const text = (data.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
    if (!text) throw new Error('empty response');
    ta.value = text;
    if (sts) { sts.style.color = '#3ecf8e'; sts.textContent = 'Scope drafted from the drawing — edit as needed.'; }
  } catch (e) {
    ta.value = `1. Install ${contract || 'the fabricated items'} as per drawing ${drawRef || '(see site pack)'}. Fix all items to the substrate using the supplied fixings listed below.\n2. Provide splice locks / connections at all joints as shown on the drawing.\n3. Ensure all bolted connections are fully tightened with nut and washer where applicable.`;
    if (sts) { sts.style.color = 'var(--muted)'; sts.textContent = 'AI unavailable — inserted a standard template (' + e.message + '). Edit as needed.'; }
  }
  if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
}

// Build the PDF from the (editable) modal fields, save it into the Site
// Installation SharePoint folder, and record it as a site file so it appears
// in the file list. Mirrors the SDN save flow.
async function confirmSitePack() {
  const proj = currentProject, job = currentJob;
  const btn = document.getElementById('spConfirmBtn');
  if (!job?.spFolderId) { toast('Job has no SharePoint folder — cannot save.', 'error'); return; }
  if (btn) { btn.disabled = true; btn.style.opacity = '.5'; }

  try {
    await loadLogoDataUri();
    const getV = id => (document.getElementById(id)?.value || '').trim();
    const dateRaw = getV('spDate');
    const dateStr = dateRaw
      ? new Date(dateRaw + 'T12:00:00').toLocaleDateString('en-GB', { day:'numeric', month:'long', year:'numeric' })
      : '';

    const pack = {
      createdAt:  new Date().toISOString(),
      dateStr,
      projectNo:  getV('spProjectNo'),
      contract:   getV('spContract'),
      client:     getV('spClient'),
      drawingRef: getV('spDrawingRef'),
      finish:     getV('spFinish'),
      grade:      getV('spGrade'),
      preparedBy: getV('spPreparedBy'),
      site: {
        name:         getV('spSiteName'),
        lines:        getV('spSiteAddr').split('\n').map(l => l.trim()).filter(Boolean),
        contactName:  getV('spSiteContact'),
        contactPhone: getV('spSitePhone')
      },
      scopeLines: getV('spScopeText').split('\n').map(l => l.trim()).filter(Boolean),
      fixings:    _sitePackCollectFixings(),
      notes:      getV('spNotes')
    };

    if (!pack.scopeLines.length && !pack.fixings.length) {
      toast('Add a scope of work or at least one item before generating.', 'error');
      if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
      return;
    }

    const blob = await renderSitePackPdfBlob(pack, proj || {}, job || {});

    const stamp = new Date().toISOString().slice(0, 10);
    const baseName = `Site Pack - ${(pack.projectNo || proj?.id || 'project')} - ${stamp}`.replace(/[\/\\:*?"<>|]/g, '-');
    const fileName = baseName + '.pdf';

    const driveId = job.spDriveId || BAMA_DRIVE_ID;
    const siteFolder = await getOrCreateSubfolder(job.spFolderId, ELEMENT_FOLDERS.site, driveId);
    const arrayBuffer = await blob.arrayBuffer();
    const uploaded = await uploadFileToFolder(siteFolder.id, fileName, arrayBuffer, 'application/pdf', driveId);

    const jobIdInt = parseInt(job.id);
    if (!job.site) job.site = { files: [], notes: [] };
    const saved = await api.post(`/api/drawing-elements/${jobIdInt}/file`, {
      fileContext: 'site', name: baseName, fileName,
      fileId: uploaded.id, driveId: uploaded.parentReference?.driveId || driveId,
      webUrl: uploaded.webUrl, uploadedAt: new Date().toISOString(),
      uploadedBy: _currentDraftsmanName || null
    });
    job.site.files.push({ ...saved });

    closeSitePackModal();
    toast('Site Pack generated & saved to Site Installation.', 'success');
    renderSite();
    if (uploaded.webUrl) window.open(uploaded.webUrl, '_blank');

  } catch (e) {
    toast('Site Pack failed: ' + e.message, 'error');
    if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
  }
}


function buildDnHtmlV2(dn, proj, job) {
  const s = (typeof _pickTplSettings === 'function') ? _pickTplSettings() : null;
  const g = (s && s.global)         || (typeof TEMPLATE_DEFAULTS !== 'undefined' ? TEMPLATE_DEFAULTS.global       : { companyName: 'BAMA FABRICATION', address: '', phone: '', email: '', vatNumber: '' });
  const t = (s && s.deliveryNote)   || (typeof TEMPLATE_DEFAULTS !== 'undefined' ? TEMPLATE_DEFAULTS.deliveryNote : { title: 'Delivery Note', accentColor: '#ff6b00', showLogo: true, showCompanyDetails: true, showSignatureBlock: true, termsText: '' });
  const logo = (typeof _logoDataUriCache !== 'undefined' && _logoDataUriCache) || '';
  const showLogo = t.showLogo !== false && logo;
  const showCo   = t.showCompanyDetails !== false;
  const accent   = t.accentColor || '#ff6b00';
  const date     = new Date(dn.createdAt).toLocaleDateString('en-GB', { day:'numeric', month:'short', year:'numeric' });

  // "Deliver to" panel — destination name + address lines + contact.
  const dt = dn.deliverTo || {};
  const dtLines = (dt.lines || []).filter(Boolean);
  const deliverToHtml = (dt.name || dtLines.length)
    ? `<div class="deliver-to">
        <div class="deliver-to-label">Deliver to</div>
        ${dt.name ? `<div class="deliver-to-name">${escapeHtml(dt.name)}</div>` : ''}
        ${dtLines.map(l => `<div class="deliver-to-line">${escapeHtml(l)}</div>`).join('')}
        ${dt.contact ? `<div class="deliver-to-contact">Contact: ${escapeHtml(dt.contact)}</div>` : ''}
      </div>`
    : '';

  let html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
<title>${escapeHtml(dn.number)} - Delivery Note</title>
<style>
  /* Every rule is scoped to .dn-root. Two reasons this matters:
     (1) The PDF path injects this markup into the live app page. A bare
         'body { color:#222 }' rule can never match a <div>, so the text used
         to inherit bama.css's body colour (#f0f0f0) and render white-on-white
         — that was the "blank white PDF".
     (2) Bare element selectors (table/th/td) and a global '*' reset would
         leak out and restyle the surrounding app during capture.
     Scoped like this the same stylesheet works standalone (iframe preview)
     and injected (PDF capture). */
  .dn-root, .dn-root * { margin:0; padding:0; box-sizing:border-box; }
  .dn-root { font-family: Arial, sans-serif; font-size: 12px; padding: 20px; color: #222; background: #fff; }
  .dn-root .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 20px; padding-bottom: 16px; border-bottom: 2px solid #222; gap: 20px; }
  .dn-root .company { font-size: 22px; font-weight: 700; color: ${accent}; letter-spacing: 1px; }
  .dn-root .company-sub { font-size: 9px; color: #666; margin-top: 4px; line-height: 1.4; white-space: pre-line; }
  .dn-root .header-logo { max-width: 110px; max-height: 60px; object-fit: contain; margin-right: 12px; }
  .dn-root .header-left { display: flex; align-items: flex-start; flex: 1; }
  .dn-root .header-right { text-align: right; }
  .dn-root .dn-title { font-size: 20px; font-weight: 700; font-style: italic; color: ${accent}; margin-bottom: 8px; }
  .dn-root .meta-grid { display: grid; grid-template-columns: auto 1fr; gap: 4px 12px; font-size: 11px; text-align: left; }
  .dn-root .meta-label { font-weight: 600; }
  .dn-root table { width: 100%; border-collapse: collapse; margin: 16px 0; }
  .dn-root th { background: #f5f5f5; border: 1px solid #ccc; padding: 6px 8px; text-align: left; font-size: 11px; font-weight: 600; color: #222; }
  .dn-root td { border: 1px solid #ccc; padding: 5px 8px; font-size: 11px; color: #222; }
  .dn-root .sign-section { margin-top: 30px; display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
  .dn-root .sign-box { border: 1px solid #ccc; padding: 12px; min-height: 60px; }
  .dn-root .sign-label { font-weight: 600; font-size: 10px; margin-bottom: 20px; }
  .dn-root .terms { margin-top: 20px; font-size: 10px; color: #666; padding-top: 10px; border-top: 1px solid #eee; white-space: pre-line; }
  .dn-root .deliver-to { border: 1px solid #ccc; border-radius: 6px; padding: 10px 12px; margin-bottom: 8px; background: #fafafa; max-width: 340px; }
  .dn-root .deliver-to-label { font-size: 9px; text-transform: uppercase; letter-spacing: .05em; color: #888; font-weight: 700; margin-bottom: 4px; }
  .dn-root .deliver-to-name { font-weight: 700; font-size: 12px; color: #222; }
  .dn-root .deliver-to-line { font-size: 11px; color: #444; line-height: 1.4; }
  .dn-root .deliver-to-contact { font-size: 11px; color: #444; margin-top: 4px; }
  .dn-root td.num, .dn-root th.num { text-align: right; }
  .dn-root .total-row td { font-weight: 700; background: #f5f5f5; }
  @media print { .dn-root { padding: 10px; } }
</style></head><body>
<div class="dn-root">
<div class="header">
  <div class="header-left">
    ${showLogo ? `<img src="${logo}" class="header-logo" alt="">` : ''}
    <div>
      <div class="company">${escapeHtml(g.companyName)}</div>
      ${showCo ? `<div class="company-sub">${escapeHtml(g.address || '')}${g.phone ? '\nTel: '+escapeHtml(g.phone) : ''}${g.email ? ' \u00b7 '+escapeHtml(g.email) : ''}${g.vatNumber ? '\nVAT: '+escapeHtml(g.vatNumber) : ''}</div>` : ''}
    </div>
  </div>
  <div class="header-right">
    <div class="dn-title">${escapeHtml(t.title || 'Delivery Note')}</div>
    <div class="meta-grid">
      <span class="meta-label">DN Number:</span><span>${escapeHtml(dn.number)}</span>
      <span class="meta-label">Date:</span><span>${date}</span>
      <span class="meta-label">Project:</span><span>${escapeHtml(proj.name || '')}</span>
      <span class="meta-label">Project No:</span><span>${escapeHtml(proj.id || '')}</span>
      ${job && job.name ? `<span class="meta-label">Job:</span><span>${escapeHtml(job.name)}</span>` : ''}
      <span class="meta-label">Supplier:</span><span>${escapeHtml(dn.destinationName || '')}</span>
      <span class="meta-label">For:</span><span>${escapeHtml(dn.finishName || '')}</span>
    </div>
  </div>
</div>
${deliverToHtml}
<table>
<thead><tr>
  <th>Mark</th><th>Qty</th><th>Profile</th>
  <th class="num">Length (mm)</th><th class="num">Unit Wt. (kg)</th><th class="num">Total Wt. (kg)</th>
  <th>Finish</th>
</tr></thead>
<tbody>`;

  // Length and weight come from the source assembly: total_weight_kg is the
  // weight of ONE assembly (sum of its parts), and the length shown is the
  // LONGEST part on that assembly — the figure that matters for transport
  // and galvanising bath capacity. Manual BOM rows carry neither, so they
  // print as '—' rather than a made-up number.
  let totQty = 0, totWeight = 0, anyWeight = false;

  for (const it of (dn.items || [])) {
    const qty     = Number(it.quantity) || 0;
    const unitWt  = it.assembly_weight_kg != null ? Number(it.assembly_weight_kg) : null;
    const lengthM = it.assembly_max_length_mm != null ? Number(it.assembly_max_length_mm) : null;
    const lineWt  = unitWt != null ? unitWt * qty : null;
    const mark    = it.source === 'assembly'
      ? (it.source_assembly_mark || 'assembly')
      : '\u2014';

    totQty += qty;
    if (lineWt != null) { totWeight += lineWt; anyWeight = true; }

    html += `<tr>
      <td style="font-weight:600">${escapeHtml(mark)}</td>
      <td>${qty}</td>
      <td>${escapeHtml(it.description)}</td>
      <td class="num">${lengthM != null ? lengthM.toLocaleString('en-GB', { maximumFractionDigits: 1 }) : '\u2014'}</td>
      <td class="num">${unitWt != null ? unitWt.toFixed(2) : '\u2014'}</td>
      <td class="num">${lineWt != null ? lineWt.toFixed(2) : '\u2014'}</td>
      <td>${escapeHtml(it.finish_name || dn.finishName || '')}</td>
    </tr>`;
  }

  html += `<tr class="total-row">
    <td>TOTAL</td><td>${totQty}</td><td></td><td class="num"></td><td class="num"></td>
    <td class="num">${anyWeight ? totWeight.toFixed(2) : '\u2014'}</td><td></td>
  </tr>`;
  html += `</tbody></table>`;

  if (!anyWeight) {
    html += `<div style="font-size:10px;color:#888;margin-top:-8px">Weights unavailable — no assembly data on these items.</div>`;
  }

  if (t.showSignatureBlock !== false) {
    html += `<div class="sign-section">
      <div class="sign-box">
        <div class="sign-label">Delivered By (BAMA):</div>
        <div style="border-bottom:1px solid #999;margin-top:24px;padding-bottom:4px"></div>
        <div style="font-size:10px;color:#666;margin-top:4px">Date:</div>
      </div>
      <div class="sign-box">
        <div class="sign-label">Received By (Supplier):</div>
        <div style="border-bottom:1px solid #999;margin-top:24px;padding-bottom:4px"></div>
        <div style="font-size:10px;color:#666;margin-top:4px">Date:</div>
      </div>
    </div>`;
  }
  if (t.termsText) {
    html += `<div class="terms">${escapeHtml(t.termsText)}</div>`;
  }
  html += `</div></body></html>`;
  return html;
}

// ── Manual BOM upload pipeline (SPEC §6 Route A) ──
async function onBomManualFilesPicked(fileList) {
  if (!fileList || !fileList.length) return;
  if (!currentJob || !currentJob.spFolderId) {
    toast('Job folder not available — try reloading.', 'error');
    return;
  }
  const files = Array.from(fileList).filter(f =>
    f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf')
  );
  if (!files.length) { toast('Only PDFs accepted for BOM upload.', 'error'); return; }

  // Progress banner inside the BOM section while we upload + OCR
  const container = document.getElementById('bomContent');
  const banner = document.createElement('div');
  banner.id = 'bomUploadBanner';
  banner.style.cssText = 'background:rgba(255,107,0,.08);border:1px solid rgba(255,107,0,.3);border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:12px;color:var(--text)';
  banner.textContent = `Uploading 0 / ${files.length}…`;
  container.prepend(banner);

  const driveId = currentJob.spDriveId || BAMA_DRIVE_ID;
  let bomFolder;
  try {
    bomFolder = await getOrCreateSubfolder(currentJob.spFolderId, ELEMENT_FOLDERS.bom, driveId);
  } catch (e) {
    banner.remove();
    toast(`Could not access BOM folder: ${e.message}`, 'error');
    return;
  }

  const queue = [];
  for (let i = 0; i < files.length; i++) {
    const file = files[i];
    banner.textContent = `Uploading ${i + 1} / ${files.length} — ${file.name}`;
    try {
      const arrayBuffer = await file.arrayBuffer();
      const uploaded = await uploadFileToFolder(bomFolder.id, file.name, arrayBuffer, file.type, driveId);

      banner.textContent = `Parsing ${i + 1} / ${files.length} — ${file.name}`;
      const ocr = await ocrLooseItemsPdf(file);

      queue.push({
        file,
        sharepoint: {
          fileId:   uploaded.id,
          driveId:  uploaded.parentReference?.driveId || driveId,
          webUrl:   uploaded.webUrl,
          fileName: file.name
        },
        ocr
      });
    } catch (e) {
      console.warn(`Failed on ${file.name}:`, e);
      toast(`${file.name}: ${e.message}`, 'error');
    }
  }
  banner.remove();
  const input = document.getElementById('bomManualFileInput');
  if (input) input.value = '';

  if (!queue.length) { toast('No PDFs were parsed.', 'error'); return; }

  _bmrMode = 'fabricated';
  const modal = document.getElementById('bomManualReviewModal');
  if (modal && modal.classList.contains('active') && _bomManualQueue.length) {
    _bomManualQueue.push(...queue);
    toast(`Added ${queue.length} more — ${_bomManualQueue.length} now queued.`, 'info');
  } else {
    _bomManualQueue = queue;
  }
  openBomManualReviewModal();
}

// Claude vision OCR on a loose-items PDF (supplier slip / quotation).
// Returns { items: [{ description, quantity, extras }] } where extras is
// a freeform object of whatever else the table contained (size, weight,
// part number, unit price, supplier code, etc.). Caller throws on bad JSON.
async function ocrLooseItemsPdf(file) {
  const dataUri = await _fileToDataUri(file);
  const b64 = dataUri.split(',')[1];

  const prompt = `Extract line items from this supplier quotation or delivery slip PDF.

For each line item in the main items table, return:
- "description": the item description as written (e.g. "M16 x 50 hex bolt", "PLT10x60", "Self-drilling screw 12mm")
- "quantity": the quantity as a positive integer (1 if not specified)
- "extras": an object with any OTHER columns present in the table — size, length, weight, material, part_number, supplier_code, unit_price, line_total, etc. Use the column header as the key (lowercased, underscored). Numeric values as numbers; strings as strings.

Ignore lines that are headers, separators, subtotals, tax, discount, shipping, totals, payment terms, notes, or boilerplate.

Return ONLY JSON, no markdown, no commentary:
{
  "items": [
    {
      "description": "M16 x 50 hex bolt",
      "quantity": 100,
      "extras": { "size": "M16 x 50", "unit_price": 0.42, "line_total": 42.00 }
    }
  ]
}

If a value is unknown, omit the key (don't use null in extras). Return an empty items array if no line items are recognisable.`;

  const result = await callClaude({
    model: 'claude-sonnet-4-6',
    max_tokens: 4000,
    messages: [{
      role: 'user',
      content: [
        { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } },
        { type: 'text', text: prompt }
      ]
    }]
  });
  const text = (result.content?.find(b => b.type === 'text')?.text || '').trim();
  const s = text.indexOf('{'), e = text.lastIndexOf('}');
  if (s < 0 || e < s) throw new Error('OCR returned no JSON');
  const parsed = JSON.parse(text.slice(s, e + 1));
  if (!parsed.items || !Array.isArray(parsed.items)) parsed.items = [];
  return parsed;
}

// ── Review modal: walks _bomManualQueue, lets user edit before save ──
// ── Review modal (batch) ──
// Single scrollable screen: every uploaded PDF is a collapsible card holding
// its own finish + line items. Tick "looks good" per PDF (or "Accept all"),
// then "Save all ticked" commits every ticked PDF in one pass. New uploads
// append to the queue instead of replacing it.
function openBomManualReviewModal() {
  if (!_bomManualQueue.length) return;
  const modal = document.getElementById('bomManualReviewModal');
  if (!modal) { console.warn('bomManualReviewModal not found'); return; }
  modal.classList.add('active');
  renderBomManualBatch();
}

function closeBomManualReviewModal() {
  const modal = document.getElementById('bomManualReviewModal');
  if (modal) modal.classList.remove('active');
  _bomManualQueue = [];
  _bomManualReviewIndex = 0;
  _bmrMode = 'fabricated';
}

// A PDF is saveable once it has at least one line with a description.
function _bomItemValid(item) {
  const items = (item.ocr && item.ocr.items) || [];
  return items.some(r => (r.description || '').trim() !== '');
}

function _bmrRowsHtml(rows, qi) {
  const fixMode = _bmrMode === 'fixing';
  let html = '';
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i] || {};
    if (fixMode) {
      const w = (r.unit_weight_kg != null && r.unit_weight_kg !== '') ? r.unit_weight_kg : '';
      html += `<tr class="bmr-row" data-i="${i}">
        <td style="padding:4px 6px 4px 0"><input data-f="description" value="${escapeHtml(r.description || '')}" class="bmr-cell" style="width:100%"></td>
        <td style="padding:4px"><input data-f="quantity" type="number" min="1" value="${r.quantity ?? 1}" class="bmr-cell" style="width:100%;text-align:right"></td>
        <td style="padding:4px"><input data-f="unit_weight_kg" type="number" min="0" step="0.001" value="${w}" placeholder="—" class="bmr-cell" style="width:100%;text-align:right"></td>
        <td style="padding:4px 0 4px 4px;text-align:right"><button class="btn btn-ghost" style="padding:2px 8px;font-size:14px" onclick="bmrRemoveRow(${qi}, ${i})" title="Remove">&times;</button></td>
      </tr>`;
    } else {
      const extras = r.extras || {};
      const extrasStr = Object.keys(extras).length
        ? Object.entries(extras).map(([k, v]) => `${k}: ${v}`).join(' · ')
        : '';
      html += `<tr class="bmr-row" data-i="${i}">
        <td style="padding:4px 6px 4px 0"><input data-f="description" value="${escapeHtml(r.description || '')}" class="bmr-cell" style="width:100%"></td>
        <td style="padding:4px"><input data-f="quantity" type="number" min="1" value="${r.quantity ?? 1}" class="bmr-cell" style="width:60px;text-align:right"></td>
        <td style="padding:4px;color:var(--subtle);font-size:11px;font-family:var(--font-mono);max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${escapeHtml(extrasStr)}">${escapeHtml(extrasStr)}</td>
        <td style="padding:4px 0 4px 4px;text-align:right"><button class="btn btn-ghost" style="padding:2px 8px;font-size:14px" onclick="bmrRemoveRow(${qi}, ${i})" title="Remove">&times;</button></td>
      </tr>`;
    }
  }
  return html;
}

function renderBomManualBatch() {
  const list = document.getElementById('bmrBatchList');
  if (!list) return;
  const total = _bomManualQueue.length;

  const counter = document.getElementById('bmrCounter');
  if (counter) counter.textContent = total ? `${total} PDF${total > 1 ? 's' : ''} queued` : '';

  const fixMode = _bmrMode === 'fixing';
  const finishes = _finishesCache || [];
  const finishOptsFor = (selId) => {
    let o = '<option value="">(No finish — ready for despatch)</option>';
    for (const f of finishes) {
      o += `<option value="${f.id}"${String(f.id) === String(selId) ? ' selected' : ''}>${escapeHtml(f.name)}</option>`;
    }
    return o;
  };

  let html = '';
  for (let qi = 0; qi < total; qi++) {
    const item = _bomManualQueue[qi];
    if (item._reviewed === undefined) item._reviewed = false;
    if (item._collapsed === undefined) item._collapsed = false;
    if (item._finishId === undefined) item._finishId = '';
    const rows = (item.ocr && item.ocr.items) || [];
    const valid = _bomItemValid(item);
    const lineCount = rows.filter(r => (r.description || '').trim()).length;

    const flag = !valid
      ? '<span style="color:var(--red);font-size:11px" title="No line items with a description">empty</span>'
      : `<span style="color:var(--subtle);font-size:11px">${lineCount} line${lineCount > 1 ? 's' : ''}</span>`;

    html += `<div class="bmr-card" data-qi="${qi}" style="border:1px solid var(--border);border-radius:8px;margin-bottom:10px;overflow:hidden">
      <div style="display:flex;align-items:center;gap:10px;padding:8px 10px;background:var(--bg-darker);cursor:pointer" onclick="bmrToggleCollapse(${qi})">
        <span class="bmr-chev" style="font-size:11px;color:var(--subtle);width:12px">${item._collapsed ? '&#9656;' : '&#9662;'}</span>
        <label onclick="event.stopPropagation()" style="display:flex;align-items:center;gap:6px;cursor:pointer;user-select:none">
          <input type="checkbox" class="bmr-ok" ${item._reviewed ? 'checked' : ''} onchange="bmrToggleReviewed(${qi}, this.checked)">
          <span style="font-size:11px;color:var(--subtle)">looks good</span>
        </label>
        <span style="font-size:12px;color:var(--muted);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(item.sharepoint.fileName || '')}</span>
        ${flag}
        <button class="btn btn-ghost" style="padding:2px 8px;font-size:14px" onclick="event.stopPropagation();bmrRemoveCard(${qi})" title="Remove from queue">&times;</button>
      </div>
      <div class="bmr-card-body" style="padding:12px;display:${item._collapsed ? 'none' : 'block'}">
        ${fixMode ? `
        <div style="font-size:11px;color:var(--subtle);margin-bottom:10px">
          Imported as <b style="color:#3ecf8e">fixings</b> — bolts/anchors arrive finished, so they land in <i>Ready for despatch</i>. Edit any line below.
        </div>` : `
        <div style="margin-bottom:12px">
          <div class="field-label">FINISH (applies to all lines from this PDF)</div>
          <select class="field-input bmr-finish" onchange="bmrSetFinish(${qi}, this.value)">${finishOptsFor(item._finishId)}</select>
          <div style="font-size:11px;color:var(--subtle);margin-top:4px">No finish = lines land in <i>Ready for despatch</i>. Pick a finish to send them to a supplier first.</div>
        </div>`}
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
          <div class="field-label" style="margin:0">LINES</div>
          <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick="bmrAddRow(${qi})">&#43; Add row</button>
        </div>
        <div style="background:var(--bg-darker);border:1px solid var(--border);border-radius:8px;padding:8px;overflow:auto;max-height:34vh">
          <table style="width:100%;font-size:12px;border-collapse:collapse;min-width:520px;${fixMode ? 'table-layout:fixed' : ''}">
            <thead><tr style="color:var(--subtle);text-align:left">
              <th style="font-weight:400;padding:4px 6px 4px 0">Description</th>
              <th style="font-weight:400;padding:4px 6px;text-align:right;${fixMode ? 'width:72px' : ''}">Qty</th>
              ${fixMode
                ? '<th style="font-weight:400;padding:4px 6px;text-align:right;width:104px">Wt each (kg)</th>'
                : '<th style="font-weight:400;padding:4px 6px">Extras (read-only — discarded on save)</th>'}
              <th style="${fixMode ? 'width:34px' : ''}"></th>
            </tr></thead>
            <tbody id="bmrRows_${qi}">${_bmrRowsHtml(rows, qi)}</tbody>
          </table>
        </div>
      </div>
    </div>`;
  }
  list.innerHTML = html || '<div style="color:var(--subtle);font-size:12px;padding:20px;text-align:center">Nothing queued.</div>';
  _bmrUpdateBar();
}

function _bmrUpdateBar() {
  const bar = document.getElementById('bmrBar');
  if (!bar) return;
  const total = _bomManualQueue.length;
  const ticked = _bomManualQueue.filter(it => it._reviewed && _bomItemValid(it)).length;
  bar.textContent = total ? `${ticked} of ${total} ticked & ready to save` : '';
}

function _bmrSyncCardToItem(qi) {
  const card = document.querySelector(`.bmr-card[data-qi="${qi}"]`);
  if (!card) return;
  const item = _bomManualQueue[qi];
  if (!item) return;
  const fixMode = _bmrMode === 'fixing';
  const finEl = card.querySelector('.bmr-finish');
  if (finEl) item._finishId = finEl.value || '';
  const ocrItems = (item.ocr && item.ocr.items) || [];
  const out = [];
  card.querySelectorAll('.bmr-row').forEach(tr => {
    const i = parseInt(tr.dataset.i);
    const desc = tr.querySelector('input[data-f="description"]')?.value?.trim() || '';
    const qtyRaw = tr.querySelector('input[data-f="quantity"]')?.value;
    const qty = parseInt(qtyRaw);
    const row = { description: desc, quantity: qty || 1 };
    if (fixMode) {
      const wRaw = tr.querySelector('input[data-f="unit_weight_kg"]')?.value;
      const w = (wRaw == null || String(wRaw).trim() === '') ? null : Number(wRaw);
      if (w != null && !isNaN(w)) row.unit_weight_kg = w;
    } else {
      row.extras = ocrItems[i]?.extras || {};
    }
    out.push(row);
  });
  item.ocr = item.ocr || {};
  item.ocr.items = out;
}

function _bmrSyncAll() {
  for (let qi = 0; qi < _bomManualQueue.length; qi++) _bmrSyncCardToItem(qi);
}

function bmrToggleCollapse(qi) {
  const card = document.querySelector(`.bmr-card[data-qi="${qi}"]`);
  if (!card) return;
  const item = _bomManualQueue[qi];
  if (!item) return;
  item._collapsed = !item._collapsed;
  const body = card.querySelector('.bmr-card-body');
  const chev = card.querySelector('.bmr-chev');
  if (body) body.style.display = item._collapsed ? 'none' : 'block';
  if (chev) chev.innerHTML = item._collapsed ? '&#9656;' : '&#9662;';
}

function bmrToggleReviewed(qi, checked) {
  if (_bomManualQueue[qi]) _bomManualQueue[qi]._reviewed = checked;
  _bmrUpdateBar();
}

function bmrSetFinish(qi, val) {
  if (_bomManualQueue[qi]) _bomManualQueue[qi]._finishId = val || '';
}

function bmrRemoveCard(qi) {
  _bmrSyncAll();
  _bomManualQueue.splice(qi, 1);
  if (!_bomManualQueue.length) { closeBomManualReviewModal(); return; }
  renderBomManualBatch();
}

function bmrAddRow(qi) {
  _bmrSyncCardToItem(qi);
  const item = _bomManualQueue[qi];
  if (!item) return;
  item.ocr = item.ocr || {};
  item.ocr.items = item.ocr.items || [];
  item.ocr.items.push({ description: '', quantity: 1, extras: {} });
  const tb = document.getElementById(`bmrRows_${qi}`);
  if (tb) tb.innerHTML = _bmrRowsHtml(item.ocr.items, qi);
}

function bmrRemoveRow(qi, i) {
  _bmrSyncCardToItem(qi);
  const item = _bomManualQueue[qi];
  if (!item || !item.ocr) return;
  (item.ocr.items || []).splice(i, 1);
  const tb = document.getElementById(`bmrRows_${qi}`);
  if (tb) tb.innerHTML = _bmrRowsHtml(item.ocr.items || [], qi);
}

function bmrAcceptAll() {
  _bmrSyncAll();
  let n = 0;
  for (const item of _bomManualQueue) {
    if (_bomItemValid(item)) { item._reviewed = true; item._collapsed = true; n++; }
    else { item._reviewed = false; item._collapsed = false; }
  }
  renderBomManualBatch();
  if (n < _bomManualQueue.length) {
    toast(`Ticked ${n}. ${_bomManualQueue.length - n} have no line items.`, 'info');
  }
}

async function bmrSaveAll() {
  if (!currentJob) { toast('No job selected.', 'error'); return; }
  _bmrSyncAll();

  const targets = [];
  for (let qi = 0; qi < _bomManualQueue.length; qi++) {
    const item = _bomManualQueue[qi];
    if (item._reviewed && _bomItemValid(item)) targets.push(qi);
  }
  if (!targets.length) {
    toast('Tick "looks good" on the PDFs to save — or hit "Accept all".', 'error');
    return;
  }

  const saveBtn = document.getElementById('bmrSaveBtn');
  if (saveBtn) { saveBtn.disabled = true; saveBtn.style.opacity = '.6'; }

  const savedIdx = [];
  let savedPdfs = 0, savedLines = 0;
  for (const qi of targets) {
    const item = _bomManualQueue[qi];
    const rows = ((item.ocr && item.ocr.items) || []).filter(r => (r.description || '').trim());
    if (!rows.length) continue;
    const finishServiceId = item._finishId ? parseInt(item._finishId) : null;
    try {
      const payload = {
        job_id:              parseInt(currentJob.id),
        finish_service_id:   finishServiceId,
        sharepoint_file_id:  item.sharepoint.fileId,
        sharepoint_drive_id: item.sharepoint.driveId,
        sharepoint_web_url:  item.sharepoint.webUrl,
        file_name:           item.sharepoint.fileName,
        items:               rows.map(r => (_bmrMode === 'fixing'
          ? { description: r.description, quantity: r.quantity, unit_weight_kg: (r.unit_weight_kg != null ? r.unit_weight_kg : null) }
          : { description: r.description, quantity: r.quantity }))
      };
      if (_bmrMode === 'fixing') payload.item_type = 'fixing';
      await api.post('/api/job-bom-items/bulk', payload);
      savedPdfs++; savedLines += rows.length; savedIdx.push(qi);
    } catch (e) {
      toast(`${item.sharepoint.fileName}: save failed — ${e.message}`, 'error');
    }
  }

  if (saveBtn) { saveBtn.disabled = false; saveBtn.style.opacity = '1'; }

  savedIdx.sort((a, b) => b - a).forEach(qi => _bomManualQueue.splice(qi, 1));

  if (currentJob?.id) await loadJobBomItems(parseInt(currentJob.id));
  renderBOM();

  if (!_bomManualQueue.length) {
    closeBomManualReviewModal();
    toast(`Saved ${savedLines} BOM line${savedLines === 1 ? '' : 's'} from ${savedPdfs} PDF${savedPdfs === 1 ? '' : 's'}.`, 'success');
  } else {
    toast(`Saved ${savedLines} line${savedLines === 1 ? '' : 's'}. ${_bomManualQueue.length} PDF${_bomManualQueue.length === 1 ? '' : 's'} still queued.`, savedPdfs ? 'success' : 'info');
    renderBomManualBatch();
  }
}


// ═══════════════════════════════════════════
// ELEMENT 2: APPROVAL
// ═══════════════════════════════════════════
// A revision's display label follows its approval state, not just which button
// created it: pending/rejected → "PO1", approved → "C01". The C-counter is a
// per-job monotonic sequence assigned at first approval (stored as
// construction_number in DB), independent of the PO number — so the first
// approved revision is always C01 regardless of how many PO rounds preceded
// it. Folder names in SharePoint mirror this (renamed on approve — see
// updateApprovalStatus).
function approvalRevLabel(type, number, status, constructionNumber) {
  // Construction (CO) revisions show C## ; every P revision shows P##
  // (zero-padded) regardless of its review outcome — an approved P is still a
  // P, and the Construction drawing is a separate upload with its own C number.
  if (type === 'CO') {
    const cnum = (constructionNumber != null) ? constructionNumber : number;
    return 'C' + String(cnum).padStart(2, '0');
  }
  return 'P' + String(number).padStart(2, '0');
}

// Human label + colour for a revision's status.
function approvalStatusMeta(rev) {
  if (rev.type === 'CO') return { text: 'Construction Issued', color: 'var(--green)', bg: 'rgba(62,207,142,.15)', border: 'rgba(62,207,142,.45)' };
  switch (rev.status) {
    case 'approved': return { text: 'Approved', color: 'var(--green)', bg: 'rgba(62,207,142,.15)', border: 'rgba(62,207,142,.45)' };
    case 'minor':    return { text: 'Minor comments', color: '#f5b544', bg: 'rgba(245,166,35,.15)', border: 'rgba(245,166,35,.45)' };
    case 'major':
    case 'rejected': return { text: 'Major comments', color: 'var(--red)', bg: 'rgba(255,68,68,.12)', border: 'rgba(255,68,68,.4)' };
    default:         return { text: 'Sent to Engineer', color: '#60a5fa', bg: 'rgba(59,130,246,.15)', border: 'rgba(59,130,246,.4)' };
  }
}

// The label the NEXT upload will get = highest live revision number of that
// type + 1 (matches the server). Deleted revisions don't count, so numbering
// simply reflects what's actually in the approval list.
function nextApprovalLabel(job, subElement) {
  const revs = (job?.approval?.revisions || []).filter(r => !r.isDeleted);
  if (subElement === 'CO') {
    const maxCon = revs.reduce((m, r) => r.type === 'CO' ? Math.max(m, r.constructionNumber || 0) : m, 0);
    return 'C' + String(maxCon + 1).padStart(2, '0');
  }
  const maxP = revs.reduce((m, r) => r.type === 'PO' ? Math.max(m, r.number || 0) : m, 0);
  return 'P' + String(maxP + 1).padStart(2, '0');
}

function renderApproval() {
  const container = document.getElementById('approvalContent');
  if (!container) return;
  const approval = currentJob.approval || { revisions: [], notes: [] };
  const revisions = approval.revisions || [];
  const statusEl = document.getElementById('elementApprovalStatus');
  const editable = isDraftsman && currentJob.status !== 'closed';

  // Soft-deleted revisions stay in `revisions` (so numbering never reuses their
  // numbers) but are hidden everywhere in the UI.
  const sortedDesc = [...revisions].filter(r => !r.isDeleted).reverse();
  const latestP = sortedDesc.find(r => r.type === 'PO');   // most recent for-approval issue
  const latestC = sortedDesc.find(r => r.type === 'CO');   // most recent construction issue
  const hasConstruction = !!latestC;
  const pLabel = latestP ? approvalRevLabel(latestP.type, latestP.number) : '';

  // ── Headline pill on the element card ────────────────────────────────────
  if (latestC) {
    statusEl.textContent = `${approvalRevLabel(latestC.type, latestC.number, latestC.status, latestC.constructionNumber)} Construction Issued`;
    statusEl.style.cssText = 'color:var(--green);background:rgba(62,207,142,.12);padding:3px 10px;border-radius:4px;font-size:11px;font-weight:600';
  } else if (latestP) {
    const m = approvalStatusMeta(latestP);
    statusEl.textContent = `${pLabel} ${m.text}`;
    statusEl.style.cssText = `color:${m.color};background:${m.bg};padding:3px 10px;border-radius:4px;font-size:11px;font-weight:600`;
  } else {
    statusEl.textContent = 'No submissions';
    statusEl.style.cssText = 'color:var(--subtle);font-size:11px;font-weight:600';
  }

  let html = '';

  // ── Draftsman controls ───────────────────────────────────────────────────
  if (editable) {
    const constructionBtn = `<button class="btn" style="padding:8px 16px;font-size:12px;background:rgba(62,207,142,.12);border:1px solid rgba(62,207,142,.35);color:var(--green)" onclick="openUploadFileModal('approval','CO')">&#43; Upload Construction Issue Drawing</button>`;
    const newPBtn = (label) => `<button class="btn btn-primary" style="padding:8px 16px;font-size:12px" onclick="openUploadFileModal('approval','PO')">&#43; ${label}</button>`;
    const canIssueC = latestP && (latestP.status === 'approved' || latestP.status === 'minor');
    const canRaiseP = !latestP || ['minor', 'major', 'rejected'].includes(latestP.status);

    html += '<div style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;align-items:center">';
    if (latestP && latestP.status === 'sent') {
      html += `<span style="font-size:12px;color:var(--muted)">${pLabel} is with the engineer — set the outcome below once comments are back.</span>`;
    } else {
      if (canIssueC) html += constructionBtn;
      if (canRaiseP) html += newPBtn(latestP ? 'Raise new P for re-approval' : 'Upload Drawing for Approval');
    }
    html += '</div>';

    // Outcome setter / changer for the latest P. id passed UNQUOTED so the
    // numeric revision id matches rev.id (the old quoted-string form silently
    // failed the strict-equality lookup and nothing saved).
    if (latestP && !hasConstruction) {
      const sel = latestP.status;
      const chip = (val, label) =>
        `<label class="toggle-chip"><input type="radio" name="pOutcome" value="${val}" ${sel === val ? 'checked' : ''} style="display:none" onchange="updateApprovalStatus(${latestP.id},'${val}')"><span>${label}</span></label>`;
      const prompt = sel === 'sent'
        ? 'Comments back from the engineer? Set the outcome:'
        : `${pLabel} outcome (change if needed):`;
      html += `<div style="margin-bottom:16px">
        <div style="font-size:12px;color:var(--muted);font-weight:500;margin-bottom:6px">${prompt}</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          ${chip('approved', '&#9989; A — Approved')}
          ${chip('minor', '&#128221; B — Minor comments')}
          ${chip('major', '&#10060; C — Major comments')}
        </div>
      </div>`;
    }

    // Standing notice / hint keyed to the outcome (clears once construction is issued)
    if (latestP && !hasConstruction) {
      if (latestP.status === 'approved') {
        html += `<div style="margin-bottom:16px;padding:10px 14px;border-radius:6px;background:rgba(245,166,35,.1);border:1px solid rgba(245,166,35,.35);color:#f5b544;font-size:12.5px;line-height:1.5">
          &#9888;&#65039; <strong>${pLabel} approved — no comments.</strong> Remember to issue the Construction drawing (C01) and upload it here.
        </div>`;
      } else if (latestP.status === 'minor') {
        html += `<div style="margin-bottom:16px;padding:10px 14px;border-radius:6px;background:rgba(245,166,35,.08);border:1px solid rgba(245,166,35,.25);color:var(--muted);font-size:12.5px;line-height:1.5">
          Minor comments — either incorporate them straight into the Construction drawing, or raise a new P for re-approval.
        </div>`;
      } else if (latestP.status === 'major' || latestP.status === 'rejected') {
        html += `<div style="margin-bottom:16px;padding:10px 14px;border-radius:6px;background:rgba(255,68,68,.07);border:1px solid rgba(255,68,68,.22);color:var(--muted);font-size:12.5px;line-height:1.5">
          Major comments — raise a new P revision and re-issue for approval.
        </div>`;
      }
    }
  }

  // ── Revision list (latest first) ─────────────────────────────────────────
  // "Current" (un-grayed for workshop staff) = latest construction issue if any,
  // else the latest approved P, else the latest P.
  const currentId = (latestC && latestC.id)
    || (sortedDesc.find(r => r.type === 'PO' && r.status === 'approved') || {}).id
    || (latestP && latestP.id);

  sortedDesc.forEach(rev => {
    const isCurrent = (rev.id === currentId);
    const isGrayed = !isDraftsman && !isCurrent;
    const m = approvalStatusMeta(rev);
    html += `<div class="revision-group ${isCurrent ? 'current' : ''} ${isGrayed ? 'grayed' : ''}">
      <div class="revision-header">
        <span class="revision-badge" style="background:${m.bg};color:${m.color}">${approvalRevLabel(rev.type, rev.number, rev.status, rev.constructionNumber)}</span>
        <span style="color:${m.color};background:${m.bg};border:1px solid ${m.border};padding:2px 10px;border-radius:4px;font-size:11px;font-weight:600;letter-spacing:.3px">${m.text}</span>
        <span style="font-size:11px;color:var(--subtle);margin-left:auto">${new Date(rev.uploadedAt).toLocaleDateString('en-GB')}</span>
        ${editable ? `<button class="btn" title="Delete this revision" style="padding:3px 8px;font-size:11px;margin-left:10px;background:rgba(255,68,68,.1);border:1px solid rgba(255,68,68,.3);color:var(--red)" onclick="confirmDeleteRevision(${rev.id})">&#128465;</button>` : ''}
      </div>`;
    if (rev.files?.length > 0) {
      html += '<div style="padding:8px 14px">';
      rev.files.forEach(f => {
        if (isCurrent || isDraftsman) {
          // Per-file delete is disabled for approval — the revision is the unit,
          // so use the revision-level delete above (keeps the number retired).
          html += renderFileRow(f, 'approval', false);
        } else {
          html += `<div class="file-row grayed"><div class="file-row-icon">&#128196;</div><div class="file-row-name">${f.name || f.fileName}</div></div>`;
        }
      });
      html += '</div>';
    }
    html += '</div>';
  });

  if (!sortedDesc.length) {
    html += '<div style="color:var(--subtle);font-size:13px;padding:12px 0">No approval submissions yet</div>';
  }

  html += renderNotesSection(approval.notes, 'approval');
  container.innerHTML = html;
}
async function updateApprovalStatus(revisionId, newStatus) {
  if (!currentJob || !currentProject) return;
  const jobIdInt = parseInt(currentJob.id);
  // Loose compare: the id arrives from an inline onclick and rev.id is numeric.
  const rev = currentJob.approval?.revisions?.find(r => r.id == revisionId);   // eslint-disable-line eqeqeq
  if (!rev) return;
  try {
    setLoading(true);
    await api.patch(`/api/drawing-elements/${jobIdInt}/approval-revision/${revisionId}/status`, { status: newStatus });
    rev.status = newStatus;
    rev.statusUpdatedAt = new Date().toISOString();
    // No SharePoint folder rename here: a P revision keeps its P## folder
    // whatever its outcome. The Construction (C##) folder is created only when
    // an actual Construction drawing is uploaded.
    const label = { sent: 'Sent to Engineer', approved: 'Approved (A)', minor: 'Minor comments (B)', major: 'Major comments (C)', rejected: 'Major comments (C)' }[newStatus] || newStatus;
    toast(`Outcome set: ${label}`, 'success');
    renderApproval();
  } catch (e) { toast('Save failed: ' + e.message, 'error'); }
  finally { setLoading(false); }
}

// Delete an approval revision. It's removed from the list and its number is
// freed — deleting the top revision means the next upload reuses that number.
async function confirmDeleteRevision(revId) {
  if (!currentJob) return;
  const rev = (currentJob.approval?.revisions || []).find(r => r.id == revId);   // eslint-disable-line eqeqeq
  if (!rev) return;
  const label = approvalRevLabel(rev.type, rev.number, rev.status, rev.constructionNumber);
  showConfirm('Delete revision',
    `Delete ${label} and its file(s)? Its number is freed, so the next upload can reuse ${label}.`,
    async () => {
      try {
        setLoading(true);
        for (const f of (rev.files || [])) {
          if (f.fileId) {
            try { await deleteFileFromDrive(f.fileId, f.driveId); }
            catch (e) { console.warn('SharePoint delete skipped:', e.message); }
          }
        }
        const jobIdInt = parseInt(currentJob.id);
        await api.delete(`/api/drawing-elements/${jobIdInt}/approval-revision/${revId}`);
        const arr = currentJob.approval.revisions;
        const i = arr.indexOf(rev);
        if (i >= 0) arr.splice(i, 1);
        toast(`${label} deleted — number freed`, 'success');
        renderApproval();
      } catch (e) { toast('Delete failed: ' + e.message, 'error'); }
      finally { setLoading(false); }
    });
}
// id isn't persisted, so we derive it from the parent of one of the revision's
// files, then PATCH the folder name. File item IDs are stable across a rename,
// so Print (which uses fileId) keeps working; View also fetches fresh by fileId
// (see viewFile) so renamed paths don't 404.
async function renameApprovalRevisionFolder(rev, newName) {
  const anchor = (rev.files || []).find(f => f.fileId && f.driveId);
  if (!anchor) throw new Error('no file to locate folder');
  const token = await getToken();
  const drive = anchor.driveId || BAMA_DRIVE_ID;

  const metaRes = await fetch(
    `https://graph.microsoft.com/v1.0/drives/${drive}/items/${anchor.fileId}?$select=parentReference`,
    { headers: { 'Authorization': `Bearer ${token}` } }
  );
  if (!metaRes.ok) throw new Error('meta ' + metaRes.status);
  const meta = await metaRes.json();
  const folderId = meta.parentReference?.id;
  if (!folderId) throw new Error('no parent folder');

  const patchRes = await fetch(
    `https://graph.microsoft.com/v1.0/drives/${drive}/items/${folderId}`,
    {
      method: 'PATCH',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: newName })
    }
  );
  if (!patchRes.ok) throw new Error('rename ' + patchRes.status);
}

// Open a SharePoint file by fetching its current webUrl from its (stable) item
// id. Used for approval file rows, whose folder may be renamed on approval —
// the stored webUrl can go stale, but the item id never changes.
async function viewFile(fileId, driveId) {
  if (!fileId) return;
  try {
    setLoading(true);
    const token = await getToken();
    const drive = driveId || BAMA_DRIVE_ID;
    const res = await fetch(
      `https://graph.microsoft.com/v1.0/drives/${drive}/items/${fileId}?$select=webUrl`,
      { headers: { 'Authorization': `Bearer ${token}` } }
    );
    if (!res.ok) throw new Error('File not found');
    const meta = await res.json();
    if (meta.webUrl) window.open(meta.webUrl, '_blank', 'noopener');
    else throw new Error('No link available');
  } catch (e) { toast('Open failed: ' + e.message, 'error'); }
  finally { setLoading(false); }
}

// ═══════════════════════════════════════════
// ELEMENT 3: PARTS
// ═══════════════════════════════════════════
function renderParts() {
  const container = document.getElementById('partsContent');
  if (!container) return;
  const parts = currentJob.parts || { sections: { files: [], notes: [] }, plates: { files: [], notes: [] } };
  const secCount = parts.sections?.files?.length || 0;
  const platCount = parts.plates?.files?.length || 0;

  const status = document.getElementById('elementPartsStatus');
  if (secCount > 0 || platCount > 0) {
    status.textContent = `Sec: ${secCount} · Plt: ${platCount}`;
    status.style.cssText = 'color:var(--green);background:rgba(62,207,142,.1);padding:3px 10px;border-radius:4px;font-size:11px;font-weight:600';
  } else {
    status.textContent = 'Empty';
    status.style.cssText = 'color:var(--subtle);font-size:11px;font-weight:600';
  }

  let html = '';

  // Sections
  const secPdfCount = (parts.sections?.files || []).filter(f => (f.fileName || f.name || '').toLowerCase().endsWith('.pdf')).length;
  html += `<div class="parts-sub">
    <div class="parts-sub-header">
      <span>&#128297; Sections</span>
      <div style="display:flex;gap:8px;align-items:center">
        ${secPdfCount > 0 ? `<button class="btn btn-ghost" style="padding:6px 12px;font-size:11px" onclick="printAllParts('sections')">&#128438; Print All (${secPdfCount})</button>` : ''}
        ${isDraftsman && currentJob.status !== 'closed' ? `<button class="btn btn-primary" style="padding:6px 12px;font-size:11px" onclick="openUploadFileModal('parts','sections')">&#43; Upload</button>` : ''}
      </div>
    </div>
    <div style="padding:12px 14px">`;
  if (secCount > 0) {
    html += parts.sections.files.map(f => renderFileRow(f, 'parts-sections')).join('');
  } else {
    html += '<div style="color:var(--subtle);font-size:12px">No section files yet</div>';
  }
  html += renderNotesSection(parts.sections?.notes || [], 'parts-sections');
  html += '</div></div>';

  // Plates
  const platPdfCount = (parts.plates?.files || []).filter(f => (f.fileName || f.name || '').toLowerCase().endsWith('.pdf')).length;
  html += `<div class="parts-sub">
    <div class="parts-sub-header">
      <span>&#128297; Plates</span>
      <div style="display:flex;gap:8px;align-items:center">
        ${platPdfCount > 0 ? `<button class="btn btn-ghost" style="padding:6px 12px;font-size:11px" onclick="printAllParts('plates')">&#128438; Print All (${platPdfCount})</button>` : ''}
        ${isDraftsman && currentJob.status !== 'closed' ? `<button class="btn btn-primary" style="padding:6px 12px;font-size:11px" onclick="openUploadFileModal('parts','plates')">&#43; Upload</button>` : ''}
      </div>
    </div>
    <div style="padding:12px 14px">`;
  if (platCount > 0) {
    html += parts.plates.files.map(f => renderFileRow(f, 'parts-plates')).join('');
  } else {
    html += '<div style="color:var(--subtle);font-size:12px">No plate files yet</div>';
  }
  html += renderNotesSection(parts.plates?.notes || [], 'parts-plates');
  html += '</div></div>';

  container.innerHTML = html;
}

// ═══════════════════════════════════════════
// ELEMENT 4: ASSEMBLY  (job-fabrication rework — see SPEC §5)
// ═══════════════════════════════════════════
//
// New flow: one PDF per assembly. Upload triggers Claude vision OCR,
// review modal opens, on confirm we INSERT into JobAssemblies +
// JobAssemblyParts (single txn via /api/job-assemblies). The Assembly
// section is now driven by SQL, NOT by drawingsData.projects[].jobs[].assembly.tasks.

async function loadJobAssemblies(jobId) {
  if (!jobId) return [];
  try {
    const rows = await api.get(`/api/job-assemblies?job_id=${encodeURIComponent(jobId)}`);
    _assembliesByJob[jobId] = Array.isArray(rows) ? rows : [];
    return _assembliesByJob[jobId];
  } catch (e) {
    console.warn('Load assemblies failed:', e.message);
    _assembliesByJob[jobId] = [];
    return [];
  }
}

async function loadFinishes() {
  if (_finishesCache) return _finishesCache;
  try {
    const rows = await api.get('/api/service-types');
    _finishesCache = (rows || []).filter(r => r.is_finish && r.is_active);
  } catch (e) {
    console.warn('Load finishes failed:', e.message);
    _finishesCache = [];
  }
  return _finishesCache;
}

// Return the index (in parts[]) of the heaviest part by weight_kg.
// Ties: first one wins. Used for status display AND the BOM row name
// generated on fabricate (commit 8).
function heaviestPartIndex(parts) {
  if (!parts || !parts.length) return -1;
  let best = -1, bestWt = -Infinity;
  for (let i = 0; i < parts.length; i++) {
    const w = Number(parts[i].weight_kg) || 0;
    if (w > bestWt) { bestWt = w; best = i; }
  }
  return best;
}

// ── Assembly per-ONE weight chip + editor ────────────────────────────────────
// JobAssemblies.total_weight_kg is the weight of ONE assembly — every consumer
// (DN Unit Wt. × qty, fab-output kg, project tonnage) multiplies it by qty.
// The chip makes that figure visible on the card; the pencil (draftsman, job
// open) corrects it when OCR stored the drawing's BATCH total instead — the
// classic symptom is a delivery note whose Unit Wt. equals the whole mark's
// weight and whose Line Wt. is qty× too big.
function asmWeightChip(a) {
  const canEdit = isDraftsman && currentJob && currentJob.status !== 'closed';
  const has = a.total_weight_kg != null && isFinite(Number(a.total_weight_kg));
  const label = has ? `${Number(a.total_weight_kg).toFixed(Number(a.total_weight_kg) < 10 ? 2 : 1)} kg ea` : 'no unit wt';
  const pencil = canEdit
    ? `<span onclick="event.stopPropagation();openAsmWeightEdit(${a.id})" title="Edit the per-ONE-assembly weight (feeds DN unit weight and tonnage)" style="cursor:pointer;margin-left:4px">&#9998;</span>`
    : '';
  const col = has ? 'color:#93c5fd;background:rgba(59,130,246,.12);border:1px solid rgba(59,130,246,.25)'
                  : 'color:#fcd34d;background:rgba(234,179,8,.12);border:1px solid rgba(234,179,8,.3)';
  return `<span style="${col};padding:2px 9px;border-radius:6px;font-size:11px;font-family:var(--font-mono);white-space:nowrap">${label}${pencil}</span>`;
}

// Self-injecting modal (BAMA UI rule — never window.prompt).
function openAsmWeightEdit(asmId) {
  const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
  const a = ((jobId && _assembliesByJob[jobId]) || []).find(x => x.id === asmId);
  if (!a) { toast('Assembly not found — refresh and retry.', 'error'); return; }
  document.getElementById('asmWtModal')?.remove();
  const qty = Number(a.quantity) || 1;
  const cur = a.total_weight_kg != null ? Number(a.total_weight_kg) : null;
  // ÷qty quick fix — only meaningful when several off and a stored figure exists.
  const divHint = (qty > 1 && cur != null) ? `
    <button class="btn btn-ghost" style="padding:6px 12px;font-size:11px;margin-top:8px" onclick="document.getElementById('asmWtInput').value='${(cur / qty).toFixed(3)}'">
      Stored figure is the batch total for all ${qty} &rarr; use ${(cur / qty).toFixed(2)} kg each
    </button>` : '';
  const div = document.createElement('div');
  div.id = 'asmWtModal';
  div.className = 'modal-overlay active';
  div.innerHTML = `<div class="modal" style="width:420px;max-width:94vw">
    <div class="modal-title" style="margin-bottom:6px">Unit weight — ${escapeHtml(a.assembly_mark)}</div>
    <div style="color:var(--muted);font-size:12px;margin-bottom:14px">
      Weight of <b>ONE</b> assembly in kg. Delivery notes print this as Unit Wt. and multiply by the quantity shipped (${qty} off on this mark), so a batch total entered here doubles up on every note.
    </div>
    <label style="font-size:11px;color:var(--muted)">Weight of one assembly (kg)</label>
    <input id="asmWtInput" type="number" min="0.001" step="0.001" class="field-input" value="${cur != null ? cur : ''}" placeholder="kg each">
    ${divHint}
    <button class="btn btn-primary btn-full" style="margin-top:16px;padding:12px" onclick="saveAsmWeightEdit(${asmId})">Save</button>
    <button class="btn btn-ghost btn-full" style="margin-top:8px;padding:10px" onclick="document.getElementById('asmWtModal').remove()">Cancel</button>
  </div>`;
  document.body.appendChild(div);
  setTimeout(() => document.getElementById('asmWtInput')?.focus(), 50);
}

async function saveAsmWeightEdit(asmId) {
  const v = Number(document.getElementById('asmWtInput')?.value);
  if (!isFinite(v) || v <= 0) { toast('Enter a weight above zero.', 'error'); return; }
  try {
    const res = await api.put(`/api/job-assemblies/${asmId}/weight`, { total_weight_kg: v });
    const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
    if (jobId && _assembliesByJob[jobId]) {
      const idx = _assembliesByJob[jobId].findIndex(x => x.id === asmId);
      if (idx >= 0) _assembliesByJob[jobId][idx].total_weight_kg = res.assembly?.total_weight_kg ?? v;
      delete _bomItemsByJob[jobId];   // assembly_weight_kg is joined into BOM rows
    }
    document.getElementById('asmWtModal')?.remove();
    toast('Unit weight saved — new delivery notes use the corrected figure. Already-issued SDNs can be reissued from the deliveries register.', 'success');
    renderAssembly();
    if (jobId) { await loadJobBomItems(jobId); renderBOM(); }
  } catch (e) {
    toast('Save failed: ' + e.message, 'error');
  }
}

function renderAssembly() {
  const container = document.getElementById('assemblyContent');
  if (!container) return;

  const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
  const assemblies = (jobId && _assembliesByJob[jobId]) || [];

  // Update header status badge
  const status = document.getElementById('elementAssemblyStatus');
  if (status) {
    const terminal = assemblies.filter(a => asmIsTerminal(a)).length;
    if (assemblies.length > 0) {
      status.textContent = `${terminal}/${assemblies.length} complete`;
      status.style.cssText = terminal === assemblies.length
        ? 'color:var(--green);background:rgba(62,207,142,.1);padding:3px 10px;border-radius:4px;font-size:11px;font-weight:600'
        : 'color:var(--accent);background:rgba(255,107,0,.1);padding:3px 10px;border-radius:4px;font-size:11px;font-weight:600';
    } else {
      status.textContent = 'No assemblies';
      status.style.cssText = 'color:var(--subtle);font-size:11px;font-weight:600';
    }
  }

  let html = '';

  // Bulk-select toolbar. Only offered when there's more than one assembly and
  // the job isn't closed. In select mode, a floating action bar appears.
  const nonTerminal = assemblies.filter(a => !asmIsTerminal(a));
  if (currentJob && currentJob.status !== 'closed' && assemblies.length > 1) {
    _bulkSurface = 'projects';
    if (!_bulkSelectMode) {
      html += `<div style="display:flex;justify-content:flex-end;margin-bottom:8px">
        <button class="btn btn-ghost" style="padding:5px 14px;font-size:12px" onclick="toggleBulkSelect()">&#9745; Select multiple</button>
      </div>`;
    } else {
      const selCount = assemblies.filter(a => _bulkSelected.has(a.id)).length;
      const selPieces = assemblies.filter(a => _bulkSelected.has(a.id)).reduce((s, a) => s + asmToFab(a) + asmReadyToWeld(a), 0);
      const visibleIds = JSON.stringify(nonTerminal.map(a => a.id));
      html += `<div style="position:sticky;top:0;z-index:5;background:var(--bg,#1a1a1a);border:1px solid var(--accent);border-radius:10px;padding:10px 14px;margin-bottom:10px;display:flex;align-items:center;gap:10px;flex-wrap:wrap">
        <span style="font-weight:700;color:var(--accent)">${selCount} selected</span>
        <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick='bulkSelectAllVisible(${visibleIds})'>Select all</button>
        <span style="margin-left:auto;display:flex;gap:6px;flex-wrap:wrap">
          <button class="btn btn-primary" style="padding:5px 12px;font-size:11px${selCount ? '' : ';opacity:.4;pointer-events:none'}" onclick="openBulkStageModal('fab', _assembliesByJob[${jobId}], 'projects')">&#128296; Fab</button>
          <button class="btn btn-primary" style="padding:5px 12px;font-size:11px;background:rgba(234,179,8,.9);border-color:rgba(234,179,8,.9)${selCount ? '' : ';opacity:.4;pointer-events:none'}" onclick="openBulkStageModal('weld', _assembliesByJob[${jobId}], 'projects')">&#128293; Weld</button>
          <button class="btn btn-primary" style="padding:5px 12px;font-size:11px${selCount ? '' : ';opacity:.4;pointer-events:none'}" onclick="openBulkStageModal('complete', _assembliesByJob[${jobId}], 'projects')">&#10003; Complete</button>
          ${isDraftsman ? `<button class="btn btn-ghost" style="padding:5px 12px;font-size:11px;color:var(--red);border-color:rgba(239,68,68,.4)${selCount ? '' : ';opacity:.4;pointer-events:none'}" onclick="bulkDeleteAssemblies(_assembliesByJob[${jobId}])">&#128465; Delete</button>` : ''}
          <button class="btn btn-ghost" style="padding:5px 12px;font-size:11px" onclick="toggleBulkSelect()">Cancel</button>
        </span>
      </div>`;
    }
  }

  // Drop zone (draftsman only, job not closed)
  if (isDraftsman && currentJob && currentJob.status !== 'closed') {
    html += `
      <div class="upload-zone" id="assemblyDropZone"
           style="margin-bottom:8px;cursor:pointer"
           onclick="document.getElementById('assemblyFileInput').click()">
        <div class="upload-zone-icon">&#128228;</div>
        <div class="upload-zone-text">Drop assembly PDFs here</div>
        <div style="color:var(--subtle);font-size:11px;margin-top:4px">
          or click to browse · one PDF per assembly · 1–100+ accepted
        </div>
      </div>
      <input type="file" id="assemblyFileInput" accept=".pdf,.PDF" multiple
             style="display:none" onchange="onAssemblyFilesPicked(this.files)">
      <div style="text-align:center;margin-bottom:14px">
        <button class="btn btn-ghost" style="font-size:12px;padding:5px 14px"
                onclick="openManualAssemblyModal()">&#43; Add manually (no PDF)</button>
      </div>
    `;
  }

  // Sort: unfinished first (most-recent on top), then terminal (most-recent on top)
  const sorted = assemblies.slice().sort((a, b) => {
    const at = asmIsTerminal(a), bt = asmIsTerminal(b);
    if (at !== bt) return at ? 1 : -1;
    return String(b.created_at).localeCompare(String(a.created_at));
  });

  if (!sorted.length) {
    html += '<div style="color:var(--subtle);font-size:13px;padding:8px 0">No assemblies uploaded yet</div>';
  }

  for (const a of sorted) {
    const isFabricated = asmIsTerminal(a);
    const toFab = asmToFab(a), rtw = asmReadyToWeld(a), bom = asmBomQty(a);
    const finishBadge = a.finish_name
      ? `<span style="background:rgba(99,102,241,.18);color:#a5b4fc;padding:2px 9px;border-radius:6px;font-size:11px">${escapeHtml(a.finish_name)}</span>`
      : a.finish_label_raw
        ? `<span style="background:rgba(234,179,8,.15);color:#fcd34d;border:1px solid rgba(234,179,8,.35);padding:2px 9px;border-radius:6px;font-size:11px" title="Read from drawing — not linked to a finishing service. Add it under Office → Service Types.">${escapeHtml(a.finish_label_raw)}</span>`
        : `<span style="color:var(--subtle);font-size:11px">No finish</span>`;
    const heaviestIdx = heaviestPartIndex(a.parts || []);

    // Progress chips shown on the header when work is partway through.
    let progressChips = '';
    if (!isFabricated) {
      const chip = (txt, col, bg) => `<span style="background:${bg};color:${col};padding:2px 8px;border-radius:6px;font-size:11px;font-family:var(--font-mono)">${txt}</span>`;
      if (toFab > 0) progressChips += chip(`${toFab} to fab`, '#fca5a5', 'rgba(239,68,68,.14)');
      if (rtw > 0)   progressChips += chip(`${rtw} to weld`, '#fcd34d', 'rgba(234,179,8,.14)');
      if (bom > 0)   progressChips += chip(`${bom} on BOM`, 'var(--green)', 'rgba(62,207,142,.12)');
    }

    // Header line — always visible. In bulk-select mode the whole header
    // toggles selection instead of expanding; terminal cards aren't selectable.
    const selectable = _bulkSelectMode && !isFabricated;
    const picked = _bulkSelected.has(a.id);
    const headerClick = selectable
      ? `toggleBulkPick(${a.id})`
      : `this.nextElementSibling.classList.toggle('collapsed')`;
    const checkbox = selectable
      ? `<span style="width:20px;height:20px;border-radius:5px;border:2px solid ${picked ? 'var(--accent)' : 'var(--border)'};background:${picked ? 'var(--accent)' : 'transparent'};display:inline-flex;align-items:center;justify-content:center;color:#fff;font-size:13px;flex:0 0 auto">${picked ? '&#10003;' : ''}</span>`
      : '';
    html += `<div class="task-card ${isFabricated ? 'complete' : ''}" style="${isFabricated ? 'opacity:.65;' : ''}${picked ? 'outline:2px solid var(--accent);outline-offset:1px;' : ''}">
      <div class="task-header" style="cursor:pointer" onclick="${headerClick}">
        ${checkbox}
        <div style="font-family:var(--font-mono);font-size:15px;font-weight:700;color:${isFabricated ? 'var(--text)' : 'var(--accent)'};min-width:48px">${escapeHtml(a.assembly_mark)}</div>
        <div style="font-size:13px;color:var(--text);min-width:60px">${Number(a.quantity)} off</div>
        ${finishBadge}
        ${asmWeightChip(a)}
        <span style="display:flex;gap:6px;flex-wrap:wrap">${progressChips}</span>
        ${isFabricated
          ? `<span style="margin-left:auto;color:var(--green);font-size:11px">&#10003; Complete ${a.fabricated_at ? new Date(a.fabricated_at).toLocaleString('en-GB', { day:'2-digit', month:'2-digit', hour:'2-digit', minute:'2-digit' }) : ''}${a.fabricated_by ? ' · ' + escapeHtml(a.fabricated_by) : ''}</span>`
          : `<span style="margin-left:auto"></span>`
        }
      </div>
      <div class="task-body${isFabricated || _bulkSelectMode ? ' collapsed' : ''}">`;

    // Parts table
    if (a.parts && a.parts.length) {
      html += `<table style="width:100%;font-family:var(--font-mono);font-size:11px;color:var(--text);border-collapse:collapse;margin-top:6px">
        <thead><tr style="color:var(--subtle);text-align:left">
          <th style="font-weight:400;padding:3px 6px 3px 0">Mk</th>
          <th style="font-weight:400;padding:3px 6px">Qty</th>
          <th style="font-weight:400;padding:3px 6px">Profile</th>
          <th style="font-weight:400;padding:3px 6px">Length</th>
          <th style="font-weight:400;padding:3px 6px">Material</th>
          <th style="font-weight:400;padding:3px 6px;text-align:right">Area</th>
          <th style="font-weight:400;padding:3px 0 3px 6px;text-align:right">Weight</th>
        </tr></thead><tbody>`;
      for (let i = 0; i < a.parts.length; i++) {
        const p = a.parts[i];
        const isHeaviest = i === heaviestIdx;
        const rowStyle = isHeaviest ? 'background:rgba(255,107,0,.06)' : '';
        const accent = isHeaviest ? 'color:var(--accent)' : '';
        html += `<tr style="${rowStyle}">
          <td style="padding:3px 6px 3px 0">${escapeHtml(p.part_mark)}</td>
          <td style="padding:3px 6px">${Number(p.quantity)}</td>
          <td style="padding:3px 6px;${accent}">${escapeHtml(p.profile)}</td>
          <td style="padding:3px 6px">${p.length_mm != null ? Number(p.length_mm).toFixed(1) : ''}</td>
          <td style="padding:3px 6px">${p.material ? escapeHtml(p.material) : ''}</td>
          <td style="padding:3px 6px;text-align:right">${p.area_m2 != null ? Number(p.area_m2).toFixed(2) : ''}</td>
          <td style="padding:3px 0 3px 6px;text-align:right;${accent}">${p.weight_kg != null ? Number(p.weight_kg).toFixed(2) : ''}</td>
        </tr>`;
      }
      html += '</tbody></table>';
    }

    // Action row. Mark-fabricated is open to BOTH workshop staff (their
    // core job) and draftsmen (admin override) — gated only by job
    // status. Delete assembly is destructive, draftsman-only.
    html += '<div style="display:flex;gap:8px;margin-top:12px;align-items:center;flex-wrap:wrap">';
    if (a.sharepoint_web_url) {
      html += `<a href="${escapeHtml(a.sharepoint_web_url)}" target="_blank" rel="noopener" class="btn btn-ghost" style="padding:6px 12px;font-size:11px;text-decoration:none">&#128279; Open PDF</a>`;
    }
    if (isDraftsman && !a.sharepoint_web_url && currentJob.status !== 'closed') {
      html += `<button class="btn btn-ghost" style="padding:6px 12px;font-size:11px" onclick="event.stopPropagation();triggerAttachPdf(${a.id})">&#128206; Attach PDF</button>`;
    }
    if (!isFabricated && currentJob.status !== 'closed') {
      // Fab & Complete offered while raw pieces remain; Weld while fabbed
      // pieces are waiting. Each opens the qty-picker modal (defaults to all
      // remaining for that stage).
      if (toFab > 0) {
        html += `<button class="btn btn-primary" style="padding:6px 14px;font-size:11px" onclick="event.stopPropagation();openStageActionModal('fab',${a.id})">&#128296; Mark fabbed${toFab < Number(a.quantity) ? ` (${toFab})` : ''}</button>`;
      }
      if (rtw > 0) {
        html += `<button class="btn btn-primary" style="padding:6px 14px;font-size:11px;background:rgba(234,179,8,.9);border-color:rgba(234,179,8,.9)" onclick="event.stopPropagation();openStageActionModal('weld',${a.id})">&#128293; Mark welded (${rtw})</button>`;
      }
      if (toFab > 0) {
        html += `<button class="btn btn-ghost" style="padding:6px 14px;font-size:11px" onclick="event.stopPropagation();openStageActionModal('complete',${a.id})" title="Complete pieces directly (skips the weld step)">&#10003; Complete${toFab < Number(a.quantity) ? ` (${toFab})` : ''}</button>`;
      }
      if (isDraftsman) {
        html += `<button class="btn btn-ghost" title="Delete assembly" style="padding:6px 10px;font-size:11px;margin-left:auto" onclick="event.stopPropagation();deleteAssembly(${a.id})">&#128465;</button>`;
      }
    }
    html += '</div>';

    // Undo row — draftsman only. Sends pieces back a stage. Un-fab needs
    // fabbed-not-welded pieces; un-weld/un-complete need welded/completed
    // pieces (server blocks any already on a raised DN).
    if (isDraftsman && currentJob.status !== 'closed') {
      const canUnfab = (Number(a.qty_fabbed||0) - Number(a.qty_welded||0)) > 0;
      const canUnweld = Number(a.qty_welded||0) > 0;
      const canUncomplete = Number(a.qty_completed||0) > 0;
      if (canUnfab || canUnweld || canUncomplete) {
        html += '<div style="display:flex;gap:6px;margin-top:8px;align-items:center;flex-wrap:wrap;border-top:1px dashed var(--border);padding-top:8px">';
        html += '<span style="color:var(--subtle);font-size:10px;text-transform:uppercase;letter-spacing:.05em;margin-right:2px">Undo</span>';
        if (canUnfab)      html += `<button class="btn btn-ghost" style="padding:4px 10px;font-size:10px" onclick="event.stopPropagation();openRollbackModal('fab',${a.id})">&#8630; Un-fab</button>`;
        if (canUnweld)     html += `<button class="btn btn-ghost" style="padding:4px 10px;font-size:10px" onclick="event.stopPropagation();openRollbackModal('weld',${a.id})">&#8630; Un-weld</button>`;
        if (canUncomplete) html += `<button class="btn btn-ghost" style="padding:4px 10px;font-size:10px" onclick="event.stopPropagation();openRollbackModal('complete',${a.id})">&#8630; Un-complete</button>`;
        html += '</div>';
      }
    }

    html += '</div></div>';
  }

  container.innerHTML = html;

  // Drag-and-drop wiring for the drop zone
  const dz = document.getElementById('assemblyDropZone');
  if (dz) {
    dz.addEventListener('dragover', (e) => { e.preventDefault(); dz.classList.add('drag-over'); });
    dz.addEventListener('dragleave', () => dz.classList.remove('drag-over'));
    dz.addEventListener('drop', (e) => {
      e.preventDefault();
      dz.classList.remove('drag-over');
      const files = Array.from(e.dataTransfer.files).filter(f => f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf'));
      if (files.length) onAssemblyFilesPicked(files);
    });
  }
}

// ═══════════════════════════════════════════
// ELEMENT 5: SITE INSTALLATION
// ═══════════════════════════════════════════
function renderSite() {
  const container = document.getElementById('siteContent');
  if (!container) return;
  const site = currentJob.site || { files: [], notes: [] };

  const status = document.getElementById('elementSiteStatus');
  if (site.completedAt) {
    status.textContent = 'Complete';
    status.style.cssText = 'color:var(--green);background:rgba(62,207,142,.1);padding:3px 10px;border-radius:4px;font-size:11px;font-weight:600';
  } else if (site.files?.length > 0) {
    status.textContent = `${site.files.length} file${site.files.length>1?'s':''}`;
    status.style.cssText = 'color:var(--accent);background:rgba(255,107,0,.1);padding:3px 10px;border-radius:4px;font-size:11px;font-weight:600';
  } else {
    status.textContent = 'Empty';
    status.style.cssText = 'color:var(--subtle);font-size:11px;font-weight:600';
  }

  let html = '';

  // Buttons row. Site Delivery Note generates an SDN for items in
  // ready_for_despatch status (returned from supplier, or never needed
  // one) — see SPEC §7 + the Site DN follow-up commit.
  if (currentJob.status !== 'closed') {
    html += '<div style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap">';
    if (isDraftsman) {
      html += `<button class="btn btn-primary" style="padding:8px 16px;font-size:12px" onclick="openUploadFileModal('site')">&#43; Upload File</button>`;
      html += `<button class="btn" style="padding:8px 16px;font-size:12px;background:rgba(255,107,0,.1);border:1px solid rgba(255,107,0,.3);color:var(--accent)" onclick="openSitePackModal()">&#128203; Generate Site Pack</button>`;
      html += `<button class="btn" style="padding:8px 16px;font-size:12px;background:rgba(139,92,246,.1);border:1px solid rgba(139,92,246,.3);color:#a78bfa" onclick="openRamsModal()">&#128203; Generate RAMS</button>`;
      html += `<button class="btn" style="padding:8px 16px;font-size:12px;background:rgba(139,92,246,.06);border:1px solid rgba(139,92,246,.25);color:#a78bfa" onclick="importRamsDoc()">&#128229; Import RAMS</button>`;
    }
    if (isDraftsman) {
      // Count items eligible for an SDN so the button can show a count
      // (or hide if there's nothing to ship).
      const jobIdInt = parseInt(currentJob.id);
      const eligible = (_bomItemsByJob[jobIdInt] || []).filter(i => i.status === 'ready_for_despatch');
      if (eligible.length > 0) {
        html += `<button class="btn" style="padding:8px 16px;font-size:12px;background:rgba(59,130,246,.08);border:1px solid rgba(59,130,246,.25);color:#60a5fa" onclick="openSiteDnModal()">&#128666; Site Delivery Note (${eligible.length} ready)</button>`;
      }
    }
    if (!site.completedAt) {
      html += `<button class="btn btn-success" style="padding:8px 16px;font-size:12px" onclick="openCloseJobModal()">&#127919; Mark Site Complete &amp; Close Job</button>`;
    }
    html += '</div>';
  }

  // File list
  if (site.files?.length > 0) {
    html += site.files.map(f => renderFileRow(f, 'site')).join('');
  } else {
    html += '<div style="color:var(--subtle);font-size:13px;padding:12px 0">No site installation files yet</div>';
  }

  // Generated RAMS documents — context 'rams'. PDFs live in the project-level
  // 00 - RAMS/<job>/ folder; delete removes both the SharePoint file and the row.
  const ramsFiles = (currentJob.rams && currentJob.rams.files) || [];
  if (ramsFiles.length > 0) {
    html += `<div style="margin-top:14px;margin-bottom:4px;color:var(--subtle);font-size:10px;text-transform:uppercase;letter-spacing:.05em;font-weight:700">RAMS documents</div>`;
    html += ramsFiles.map(f => renderFileRow(f, 'rams')).join('');
  }

  // RAMS register — numbered documents covering this job, with Revise buttons.
  // Loaded lazily (progressive render) so renderSite stays synchronous.
  html += `<div id="ramsRegisterWrap"></div>`;
  setTimeout(() => _ramsRenderRegister(currentProject?.dbId, currentJob?.id), 0);

  // Deliveries register — every DN/SDN covering this job, newest first,
  // with the destination, quantity and a link to the PDF. Lazy like RAMS.
  html += `<div id="dnRegisterWrap"></div>`;
  setTimeout(() => _dnRenderRegister(currentProject?.dbId, currentJob?.id), 0);

  // Notes
  html += renderNotesSection(site.notes || [], 'site');

  // (DN history + dispatch progress sections removed in commit 12 —
  // they read from the legacy bomDataCache which is no longer populated.
  // Replacement Site-DN flow is on the TODO list.)

  if (site.completedAt) {
    html += `<div style="margin-top:12px;padding:12px;background:rgba(62,207,142,.08);border:1px solid rgba(62,207,142,.2);border-radius:8px;font-size:13px;color:var(--green)">
      &#127919; Site installation completed by ${site.completedBy} on ${new Date(site.completedAt).toLocaleDateString('en-GB')}
    </div>`;
  }

  container.innerHTML = html;
}

// ── RAMS register block (Site Installation) ─────────────────────────────────
// Groups RamsDocuments rows by rams_no, shows the LATEST revision of each
// document covering this job, with a Revise button that reopens the modal
// prefilled (jobs locked, rev auto-bumped). Superseded revisions are counted.
async function _ramsRenderRegister(projectId, jobId) {
  const wrap = document.getElementById('ramsRegisterWrap');
  if (!wrap || !projectId || !jobId) return;
  projectId = parseInt(projectId); jobId = parseInt(jobId);
  let rows;
  try {
    if (!_ramsDocsCache[projectId]) _ramsDocsCache[projectId] = await api.get(`/api/rams-docs?projectId=${projectId}`);
    rows = _ramsDocsCache[projectId];
  } catch (e) { return; }   // register API/table not available — legacy view only
  if (!Array.isArray(rows) || !rows.length) return;
  const covers = r => { try { return (JSON.parse(r.job_ids || '[]') || []).map(Number).includes(jobId); } catch (e) { return false; } };
  const mine = rows.filter(covers);
  if (!mine.length) return;
  const byNo = {};
  mine.forEach(r => {
    const g = byNo[r.rams_no] || (byNo[r.rams_no] = { latest: r, count: 0 });
    if (r.revision > g.latest.revision) g.latest = r;
    g.count += 1;
  });
  const canRevise = isDraftsman && currentJob?.status !== 'closed';
  let html = `<div style="margin-top:14px;margin-bottom:4px;color:var(--subtle);font-size:10px;text-transform:uppercase;letter-spacing:.05em;font-weight:700">RAMS register</div>`;
  html += Object.keys(byNo).sort((a, b) => a - b).map(no => {
    const g = byNo[no], r = g.latest;
    const jobsN = (() => { try { return (JSON.parse(r.job_ids || '[]') || []).length; } catch (e) { return 1; } })();
    const dateStr = r.created_at ? new Date(r.created_at).toLocaleDateString('en-GB') : '';
    return `<div class="file-row">
      <div class="file-row-icon">&#128203;</div>
      <div class="file-row-name">${escapeHtml(r.doc_no || ('RAMS ' + _ramsPad(r.rams_no, 3)))}
        <span style="color:var(--subtle);font-size:11px"> \u2014 Rev ${_ramsPad(r.revision, 2)}${g.count > 1 ? ` (${g.count - 1} superseded)` : ''}${jobsN > 1 ? ` \u00b7 covers ${jobsN} jobs` : ''}</span>
      </div>
      <div class="file-row-date">${dateStr}</div>
      <div class="file-row-actions">
        ${r.pdf_web_url ? `<a href="${r.pdf_web_url}" target="_blank" class="btn btn-ghost" style="padding:4px 10px;font-size:11px;text-decoration:none">&#128065; View</a>` : ''}
        ${canRevise ? `<button class="btn" style="padding:4px 10px;font-size:11px;background:rgba(139,92,246,.1);border:1px solid rgba(139,92,246,.3);color:#a78bfa" onclick="openRamsModal(${r.id})">&#9998; Revise</button>` : ''}
      </div>
    </div>`;
  }).join('');
  wrap.innerHTML = html;
}

// ── Deliveries register block (Site Installation) ───────────────────────────
// Lists every DN (supplier) and SDN (site) that covers this job, newest first:
// ref, destination, pieces, date, covers-N-jobs marker and the PDF link.
async function _dnRenderRegister(projectId, jobId) {
  const wrap = document.getElementById('dnRegisterWrap');
  if (!wrap || !projectId || !jobId) return;
  projectId = parseInt(projectId); jobId = parseInt(jobId);
  let rows;
  try {
    if (!_dnRegCache[projectId]) _dnRegCache[projectId] = await api.get(`/api/dn-register?projectId=${projectId}`);
    rows = _dnRegCache[projectId];
  } catch (e) { return; }   // register API/table not available yet — skip quietly
  if (!Array.isArray(rows) || !rows.length) return;
  const covers = r => { try { return (JSON.parse(r.job_ids || '[]') || []).map(Number).includes(jobId); } catch (e) { return false; } };
  const mine = rows.filter(covers);
  if (!mine.length) return;
  let html = `<div style="margin-top:14px;margin-bottom:4px;color:var(--subtle);font-size:10px;text-transform:uppercase;letter-spacing:.05em;font-weight:700">Deliveries register</div>`;
  html += mine.map(r => {
    const jobsN = (() => { try { return (JSON.parse(r.job_ids || '[]') || []).length; } catch (e) { return 1; } })();
    const dateStr = r.created_at ? new Date(r.created_at).toLocaleDateString('en-GB') : '';
    const isSite = r.kind === 'site';
    const chip = isSite
      ? `<span style="font-size:10px;color:#3ecf8e;background:rgba(62,207,142,.1);border:1px solid rgba(62,207,142,.3);border-radius:4px;padding:1px 6px;white-space:nowrap">&rarr; Site</span>`
      : `<span style="font-size:10px;color:var(--accent);background:rgba(255,107,0,.1);border:1px solid rgba(255,107,0,.3);border-radius:4px;padding:1px 6px;white-space:nowrap">&rarr; ${escapeHtml(r.destination || 'Supplier')}</span>`;
    return `<div class="file-row">
      <div class="file-row-icon">&#128666;</div>
      <div class="file-row-name"><b>${escapeHtml(r.ref)}</b> ${chip}
        <span style="color:var(--subtle);font-size:11px"> \u2014 ${r.total_qty || 0} pcs \u00b7 ${r.line_count || 0} line${(r.line_count || 0) === 1 ? '' : 's'}${jobsN > 1 ? ` \u00b7 covers ${jobsN} jobs` : ''}${isSite && r.destination ? ` \u00b7 ${escapeHtml(r.destination)}` : ''}</span>
      </div>
      <div class="file-row-date">${dateStr}</div>
      <div class="file-row-actions">
        ${r.sharepoint_web_url ? `<a href="${r.sharepoint_web_url}" target="_blank" class="btn btn-ghost" style="padding:4px 10px;font-size:11px;text-decoration:none">&#128065; View</a>` : ''}
        ${isSite && isDraftsman ? `<button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick="openSdnEditModal('${escapeHtml(r.ref)}')" title="Edit quantities / remove lines and reissue the PDF over the same file">&#9998; Edit</button>` : ''}
      </div>
    </div>`;
  }).join('');
  wrap.innerHTML = html;
}

// ── Project-level deliveries register (modal + PDF export) ──────────────────
// One place for the WHOLE project: every DN/SDN, which jobs it covered, when
// it went, and the PDF link. Export renders the register as a single
// house-style document (bamaDocHeader/bamaSectionHeading/bamaDocFooter).
async function openProjectDeliveriesModal() {
  const proj = currentProject;
  if (!proj?.dbId) { toast('No project selected.', 'error'); return; }
  const pid = parseInt(proj.dbId);
  let rows = [];
  try {
    if (!_dnRegCache[pid]) _dnRegCache[pid] = await api.get(`/api/dn-register?projectId=${pid}`);
    rows = _dnRegCache[pid] || [];
  } catch (e) {
    toast('Could not load the deliveries register: ' + e.message + ' \u2014 has create-delivery-note-register.sql been run?', 'error');
    return;
  }
  const list = document.getElementById('projDeliveriesList');
  const btn = document.getElementById('projDelExportBtn');
  if (btn) { btn.disabled = !rows.length; btn.style.opacity = rows.length ? '1' : '.4'; }
  if (list) {
    list.innerHTML = rows.length
      ? rows.map(r => {
          const names = _dnRegJobNames(r);
          const dateStr = r.created_at ? new Date(r.created_at).toLocaleDateString('en-GB') : '';
          const isSite = r.kind === 'site';
          const chip = isSite
            ? `<span style="font-size:10px;color:#3ecf8e;background:rgba(62,207,142,.1);border:1px solid rgba(62,207,142,.3);border-radius:4px;padding:1px 6px;white-space:nowrap">&rarr; Site</span>`
            : `<span style="font-size:10px;color:var(--accent);background:rgba(255,107,0,.1);border:1px solid rgba(255,107,0,.3);border-radius:4px;padding:1px 6px;white-space:nowrap">&rarr; ${escapeHtml(r.destination || 'Supplier')}</span>`;
          return `<div class="file-row">
            <div class="file-row-icon">&#128666;</div>
            <div class="file-row-name"><b>${escapeHtml(r.ref)}</b> ${chip}
              <div style="color:var(--subtle);font-size:11px;margin-top:2px">${escapeHtml(names.join(', ') || '\u2014')} \u00b7 ${r.total_qty || 0} pcs \u00b7 ${r.line_count || 0} line${(r.line_count || 0) === 1 ? '' : 's'}</div>
            </div>
            <div class="file-row-date">${dateStr}</div>
            <div class="file-row-actions">
              ${r.sharepoint_web_url ? `<a href="${r.sharepoint_web_url}" target="_blank" class="btn btn-ghost" style="padding:4px 10px;font-size:11px;text-decoration:none">&#128065; View</a>` : ''}
              ${isSite && isDraftsman ? `<button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick="closeProjectDeliveriesModal();openSdnEditModal('${escapeHtml(r.ref)}')" title="Edit quantities / remove lines and reissue the PDF over the same file">&#9998; Edit</button>` : ''}
            </div>
          </div>`;
        }).join('')
      : `<div style="color:var(--subtle);font-size:13px;padding:16px;text-align:center">No delivery notes registered on this project yet. Notes generated from now on register automatically.</div>`;
  }
  document.getElementById('projDeliveriesModal').classList.add('active');
}

function closeProjectDeliveriesModal() {
  document.getElementById('projDeliveriesModal').classList.remove('active');
}

// Job names for a register row — resolved from the loaded project jobs list.
function _dnRegJobNames(r) {
  let ids = [];
  try { ids = (JSON.parse(r.job_ids || '[]') || []).map(Number); } catch (e) {}
  return ids.map(_dnJobName);
}

// House-style register document: one table, newest first — Ref, Date, To,
// Jobs covered, Lines, Pcs. Opens in a new tab for print / save.
async function exportProjectDeliveriesPdf() {
  const proj = currentProject;
  if (!proj?.dbId) return;
  const pid = parseInt(proj.dbId);
  const rows = _dnRegCache[pid] || [];
  if (!rows.length) { toast('Nothing to export yet.', 'error'); return; }
  try {
    const logoDataUri = await loadLogoDataUri();
    const JsPDFCtor = await resolveJsPDFCtor();
    if (!JsPDFCtor) throw new Error('PDF library failed to load');
    const doc = new JsPDFCtor({ unit: 'mm', format: 'a4', orientation: 'portrait' });
    const marginL = 14, marginR = 14, marginB = 16, pageW = 210, pageH = 297;
    const usableW = pageW - marginL - marginR;
    const TEXT = [34, 34, 34], MUTED = [90, 90, 90], RULE = [204, 204, 204], HEADFILL = [245, 245, 245];
    const setText = c => doc.setTextColor(c[0], c[1], c[2]);
    try { doc.setProperties({ title: `Deliveries Register — ${proj.id}`, author: 'BAMA Fabrication', creator: 'BAMA Fabrication ERP' }); } catch (e) {}

    const _hdr = bamaDocHeader(doc, logoDataUri || '', {
      title: 'Deliveries Register',
      marginL, marginR,
      meta: [
        { label: 'Project:', value: `${proj.id} \u2014 ${proj.name || ''}` },
        { label: 'Client:', value: proj.client || '' },
        { label: 'Generated:', value: new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) },
        { label: 'Notes:', value: String(rows.length) }
      ]
    });
    let y = _hdr.y + 2;
    y = bamaSectionHeading(doc, y, 'DELIVERY NOTES \u2014 NEWEST FIRST', { marginL, usableW });

    const cols = [
      { title: 'Ref',   w: 24, align: 'left'  },
      { title: 'Date',  w: 22, align: 'left'  },
      { title: 'To',    w: 44, align: 'left'  },
      { title: 'Jobs covered', w: usableW - 24 - 22 - 44 - 14 - 14, align: 'left' },
      { title: 'Lines', w: 14, align: 'right' },
      { title: 'Pcs',   w: 14, align: 'right' }
    ];
    let cx = marginL; cols.forEach(c => { c.x = cx; cx += c.w; });
    const cellTxt = (c, txt, yy) => {
      const s = String(txt == null ? '' : txt);
      if (c.align === 'right') doc.text(s, c.x + c.w - 2, yy, { align: 'right' });
      else doc.text(s, c.x + 1.5, yy);
    };
    const drawHead = () => {
      doc.setFillColor(HEADFILL[0], HEADFILL[1], HEADFILL[2]); doc.rect(marginL, y, usableW, 7, 'F');
      doc.setDrawColor(RULE[0], RULE[1], RULE[2]); doc.setLineWidth(0.2); doc.rect(marginL, y, usableW, 7);
      setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(8.5);
      cols.forEach(c => cellTxt(c, c.title, y + 4.7));
      y += 7;
    };
    drawHead();
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5);
    let tPcs = 0, tLines = 0;
    for (const r of rows) {
      const names = _dnRegJobNames(r).join(', ') || '\u2014';
      const to = r.kind === 'site' ? `Site${r.destination ? ' \u2014 ' + r.destination : ''}` : (r.destination || 'Supplier');
      const dateStr = r.created_at ? new Date(r.created_at).toLocaleDateString('en-GB') : '';
      const toL = doc.splitTextToSize(to, cols[2].w - 3);
      const jobsL = doc.splitTextToSize(names, cols[3].w - 3);
      const n = Math.max(toL.length, jobsL.length, 1);
      const rowH = n * 4 + 2.5;
      if (y + rowH > pageH - marginB) { doc.addPage(); y = marginL + 4; drawHead(); doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5); }
      const b = y + 4.3;
      setText(TEXT);
      doc.setFont('helvetica', 'bold'); cellTxt(cols[0], r.ref, b); doc.setFont('helvetica', 'normal');
      cellTxt(cols[1], dateStr, b);
      toL.forEach((l, i) => cellTxt(cols[2], l, b + i * 4));
      jobsL.forEach((l, i) => cellTxt(cols[3], l, b + i * 4));
      cellTxt(cols[4], r.line_count || 0, b);
      cellTxt(cols[5], r.total_qty || 0, b);
      doc.setDrawColor(RULE[0], RULE[1], RULE[2]); doc.setLineWidth(0.15);
      doc.line(marginL, y + rowH, pageW - marginR, y + rowH);
      y += rowH;
      tPcs += (Number(r.total_qty) || 0); tLines += (Number(r.line_count) || 0);
    }
    const totH = 7;
    if (y + totH > pageH - marginB) { doc.addPage(); y = marginL + 4; }
    doc.setFillColor(HEADFILL[0], HEADFILL[1], HEADFILL[2]); doc.rect(marginL, y, usableW, totH, 'F');
    doc.setDrawColor(RULE[0], RULE[1], RULE[2]); doc.setLineWidth(0.2); doc.rect(marginL, y, usableW, totH);
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
    cellTxt(cols[0], 'TOTAL', y + 4.7);
    cellTxt(cols[4], tLines, y + 4.7);
    cellTxt(cols[5], tPcs, y + 4.7);
    y += totH;

    bamaDocFooter(doc, { marginL, marginR, caption: `Deliveries Register \u2014 ${proj.id}${proj.name ? ' \u00b7 ' + proj.name : ''}` });

    const blob = doc.output('blob');
    console.log('Deliveries register PDF blob:', blob.size, 'bytes');
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
    setTimeout(() => URL.revokeObjectURL(url), 60000);
  } catch (e) {
    toast('Register export failed: ' + e.message, 'error');
  }
}

// ═══════════════════════════════════════════
// SHARED: FILE ROW RENDERER
// ═══════════════════════════════════════════
function renderFileRow(file, context, showDelete) {
  if (showDelete === undefined) showDelete = isDraftsman && currentJob?.status !== 'closed';
  const dateStr = file.uploadedAt ? new Date(file.uploadedAt).toLocaleDateString('en-GB') : '';
  return `
    <div class="file-row">
      <div class="file-row-icon">&#128196;</div>
      <div class="file-row-name">${file.name || file.fileName}</div>
      <div class="file-row-date">${dateStr}</div>
      <div class="file-row-actions">
        ${context === 'approval'
          ? `<button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick="viewFile('${file.fileId}','${file.driveId || ''}')">&#128065; View</button>`
          : (file.webUrl ? `<a href="${file.webUrl}" target="_blank" class="btn btn-ghost" style="padding:4px 10px;font-size:11px;text-decoration:none">&#128065; View</a>` : '')}
        <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick="printFile('${file.fileId}','${file.driveId || ''}')">&#128438; Print</button>
        ${showDelete ? `<button class="btn" style="padding:4px 10px;font-size:11px;background:rgba(255,68,68,.1);border:1px solid rgba(255,68,68,.3);color:var(--red)" onclick="confirmDeleteFile('${context}','${file.id}')">&#128465;</button>` : ''}
      </div>
    </div>
  `;
}

// ═══════════════════════════════════════════
// SHARED: NOTES SECTION RENDERER
// ═══════════════════════════════════════════
function renderNotesSection(notes, context) {
  notes = notes || [];
  const draftsmanNotes = notes.filter(n => n.type === 'draftsman');
  const workshopNotes = notes.filter(n => n.type === 'workshop');
  const employees = (state.timesheetData.employees || []).filter(e => e.active !== false);

  let html = '<div class="notes-section" style="margin-top:12px">';

  // Draftsman notes
  html += '<div>';
  html += '<div class="notes-col-title draftsman">&#9998; Draftsman Notes</div>';
  if (draftsmanNotes.length) {
    html += draftsmanNotes.map(n => `
      <div class="note-item draftsman-note">
        <div class="note-author draftsman-note">${n.author} <span class="note-time">${new Date(n.timestamp).toLocaleDateString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</span></div>
        <div class="note-text">${n.text}</div>
      </div>`).join('');
  } else {
    html += '<div style="color:var(--subtle);font-size:12px;padding:8px 0">No draftsman notes</div>';
  }
  if (isDraftsman) {
    html += `<div class="add-note-row" style="margin-top:8px">
      <input type="text" class="field-input" id="dn-${context}" placeholder="Add draftsman note..." style="font-size:12px;padding:7px 10px">
      <button class="btn btn-primary" style="padding:7px 12px;font-size:12px;white-space:nowrap" onclick="addElementNote('${context}','draftsman')">Add</button>
    </div>`;
  }
  html += '</div>';

  // Workshop notes
  html += '<div>';
  html += '<div class="notes-col-title workshop">&#128296; Workshop Notes</div>';
  if (workshopNotes.length) {
    html += workshopNotes.map(n => `
      <div class="note-item workshop-note">
        <div class="note-author workshop-note">${n.author} <span class="note-time">${new Date(n.timestamp).toLocaleDateString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</span></div>
        <div class="note-text">${n.text}</div>
      </div>`).join('');
  } else {
    html += '<div style="color:var(--subtle);font-size:12px;padding:8px 0">No workshop notes</div>';
  }
  html += `<div class="add-note-row" style="margin-top:8px">
    <input type="text" class="field-input" id="wn-${context}" placeholder="Add workshop note..." style="font-size:12px;padding:7px 10px">
    <select class="field-input" id="wna-${context}" style="font-size:12px;padding:7px 10px;max-width:130px">
      <option value="">Your name...</option>
      ${employees.map(e => `<option value="${e.name}">${e.name}</option>`).join('')}
    </select>
    <button class="btn btn-success" style="padding:7px 12px;font-size:12px;white-space:nowrap" onclick="addElementNote('${context}','workshop')">Add</button>
  </div>`;
  html += '</div>';

  html += '</div>';
  return html;
}

// ═══════════════════════════════════════════
// ADD NOTES (Element-level)
// ═══════════════════════════════════════════
async function addElementNote(context, type) {
  if (!currentJob || !currentProject) return;
  const inputEl = document.getElementById(`${type === 'draftsman' ? 'dn' : 'wn'}-${context}`);
  const text = inputEl?.value?.trim();
  if (!text) { toast('Please type a note', 'error'); return; }

  let author = '';
  if (type === 'draftsman') {
    author = 'Draftsman';
  } else {
    const authorEl = document.getElementById(`wna-${context}`);
    author = authorEl?.value;
    if (!author) { toast('Please select your name', 'error'); return; }
  }

  const note = {
    id: Date.now().toString(),
    type,
    author,
    text,
    timestamp: new Date().toISOString()
  };

  // Find the right notes array based on context
  const notesArr = getNotesArray(context);
  if (!notesArr) { toast('Error: could not find notes location', 'error'); return; }
  notesArr.push(note);

  try {
    const jobIdInt = parseInt(currentJob.id);
    const saved = await api.post(`/api/drawing-elements/${jobIdInt}/note`, {
      noteContext: context,
      noteType: type,
      author,
      text
    });
    // Update local state
    notesArr.push({ id: saved.id, type: saved.type, author: saved.author, text: saved.text, timestamp: saved.timestamp });
    inputEl.value = '';
    toast('Note added', 'success');
    renderAllElements();
  } catch (e) { toast('Save failed: ' + e.message, 'error'); }
}

function getNotesArray(context) {
  if (!currentJob) return null;
  if (context === 'bom') return currentJob.bom?.notes;
  if (context === 'approval') return currentJob.approval?.notes;
  if (context === 'parts-sections') return currentJob.parts?.sections?.notes;
  if (context === 'parts-plates') return currentJob.parts?.plates?.notes;
  if (context === 'site') return currentJob.site?.notes;
  // Assembly task notes
  if (context.startsWith('assembly-')) {
    const taskId = context.replace('assembly-', '');
    const task = currentJob.assembly?.tasks?.find(t => t.id === taskId);
    return task?.notes;
  }
  return null;
}

// ═══════════════════════════════════════════
// UPLOAD FILE MODAL (shared across all elements)
// ═══════════════════════════════════════════
function openUploadFileModal(element, subElement) {
  if (!currentJob || !currentProject) return;
  _uploadFiles = [];
  _uploadContext = {
    element,
    subElement: subElement || null,
    jobId: currentJob.id,
    projectId: currentProject.id
  };

  const modal = document.getElementById('uploadFileModal');
  document.getElementById('uploadFileName').value = '';
  document.getElementById('uploadFileZoneText').textContent = 'Click or drag files here';
  document.getElementById('uploadFileList').innerHTML = '';
  document.getElementById('uploadFileProgress').style.display = 'none';
  document.getElementById('uploadFileBtn').disabled = false;
  document.getElementById('uploadFileInput').value = '';

  // Title & context
  let title = 'Upload File';
  let ctx = `${currentJob.name}`;
  if (element === 'bom') { title = 'Upload BOM File'; }
  else if (element === 'approval') {
    // Show the exact revision it will become (same rule the server uses) so the
    // reviewer sees P05 / C02 up front.
    const lbl = nextApprovalLabel(currentJob, subElement);
    title = (subElement === 'CO' ? 'Upload Construction Issue Drawing' : 'Upload Drawing for Approval') + ` \u2192 ${lbl}`;
  }
  else if (element === 'parts') {
    title = subElement === 'sections' ? 'Upload Sections File' : 'Upload Plates File';
  }
  else if (element === 'assembly') { title = 'Upload Assembly File'; }
  else if (element === 'site') { title = 'Upload Site Installation File'; }

  document.getElementById('uploadFileTitle').textContent = title;
  document.getElementById('uploadFileContext').textContent = ctx;

  // The old in-modal approval-status picker is gone: a fresh P upload is always
  // "sent to engineer" and a C upload is always the construction issue. The
  // review outcome (A/B/C) is set later on the revision itself.
  document.getElementById('uploadApprovalSection').style.display = 'none';

  modal.classList.add('active');
}

function closeUploadFileModal() {
  document.getElementById('uploadFileModal').classList.remove('active');
  _uploadFiles = [];
  _uploadContext = null;
}

// Add newly picked/dropped files to the pending list instead of replacing it,
// so files can be added one at a time (drop one, then drop another). Dedupes
// by name+size+lastModified. Shared by every upload context in Projects.
function _appendUploadFiles(list) {
  const incoming = Array.from(list || []);
  if (!incoming.length) return;
  const key = f => `${f.name}|${f.size}|${f.lastModified}`;
  const seen = new Set(_uploadFiles.map(key));
  for (const f of incoming) {
    const k = key(f);
    if (!seen.has(k)) { _uploadFiles.push(f); seen.add(k); }
  }
  updateUploadFileListUI();
}

function onUploadFilesSelected() {
  const input = document.getElementById('uploadFileInput');
  _appendUploadFiles(input.files);
  input.value = '';   // reset so re-picking the same file still fires onchange
}

// Drag-and-drop onto the upload modal drop zone. The file <input> is never
// populated on a drop, so we take the dropped FileList directly. Without the
// matching ondrop/ondragover preventDefault on the zone, the browser navigates
// to the dropped file instead of uploading it.
function onUploadFilesDropped(fileList) {
  _appendUploadFiles(fileList);
}

function updateUploadFileListUI() {
  const container = document.getElementById('uploadFileList');
  const nameInput = document.getElementById('uploadFileName');

  if (_uploadFiles.length === 0) {
    container.innerHTML = '';
    document.getElementById('uploadFileZoneText').textContent = 'Click or drag files here';
    return;
  }

  if (_uploadFiles.length === 1) {
    document.getElementById('uploadFileZoneText').textContent = `&#128196; ${_uploadFiles[0].name} (${(_uploadFiles[0].size/1024).toFixed(0)}KB)`;
    if (!nameInput.value) {
      nameInput.value = _uploadFiles[0].name.replace(/\.[^.]+$/, '');
    }
  } else {
    document.getElementById('uploadFileZoneText').textContent = `${_uploadFiles.length} files selected`;
  }

  container.innerHTML = _uploadFiles.map((f, i) => `
    <div style="display:flex;align-items:center;gap:8px;padding:6px 8px;font-size:12px;background:var(--surface);border:1px solid var(--border);border-radius:6px;margin-bottom:4px">
      <span style="flex:1">&#128196; ${f.name} <span style="color:var(--subtle)">(${(f.size/1024).toFixed(0)}KB)</span></span>
      <button class="btn btn-ghost" style="padding:2px 8px;font-size:10px;color:var(--red)" onclick="removeUploadFile(${i})">&#10005;</button>
    </div>
  `).join('');
}

function removeUploadFile(index) {
  _uploadFiles.splice(index, 1);
  updateUploadFileListUI();
}

function updateApprovalChips() {
  document.querySelectorAll('#uploadApprovalSection .toggle-chip').forEach(chip => {
    chip.classList.toggle('active', chip.querySelector('input').checked);
  });
}

// ── Revision-match verification (approval uploads) ──────────────────────────
// Two-engine rule: the model ONLY reads the drawing's title block; the compare
// is plain JS. Normalise a marking to {letter,num} so "P2" == "P02", "C1"=="C01".
function _normRev(s) {
  if (!s) return null;
  const m = String(s).toUpperCase().match(/\b([PC])\s*0*(\d{1,3})\b/);
  return m ? { letter: m[1], num: parseInt(m[2], 10) } : null;
}

// Ask the model for the revision stamped in the drawing's title block.
// Returns { rev, confident } or null if the call/parse fails.
async function readDrawingRevision(file) {
  try {
    const b64 = (await _fileToDataUri(file)).split(',')[1];
    const isPdf = file.type === 'application/pdf' || /\.pdf$/i.test(file.name || '');
    const block = isPdf
      ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } }
      : { type: 'image', source: { type: 'base64', media_type: file.type || 'image/png', data: b64 } };
    const prompt = `You are reading a fabrication/engineering drawing. Find the DRAWING REVISION marking in the title block — usually the bottom-right "REV"/"REVISION" box, but it may sit elsewhere, and there is often a revision-history table (take the latest/highest one). Return the current revision code exactly as printed, e.g. "P1", "P02", "C01".
Return ONLY JSON, no markdown, no commentary:
{ "rev": "P02", "confident": true }
If you cannot clearly find a revision marking, return { "rev": null, "confident": false }.`;
    const result = await callClaude({
      model: 'claude-sonnet-4-6',
      max_tokens: 300,
      messages: [{ role: 'user', content: [block, { type: 'text', text: prompt }] }]
    });
    const text = (result.content?.find(b => b.type === 'text')?.text || '').trim();
    const s = text.indexOf('{'), e = text.lastIndexOf('}');
    if (s < 0 || e < s) return null;
    const parsed = JSON.parse(text.slice(s, e + 1));
    return { rev: parsed.rev || null, confident: !!parsed.confident };
  } catch (e) {
    console.warn('readDrawingRevision failed:', e.message);
    return null;
  }
}

// Soft gate run before an approval upload. Returns true to proceed, false to
// abort. Warns + allows override on a confident mismatch; proceeds with a
// notice when the revision can't be read.
async function verifyRevisionBeforeUpload(file, expectedLabel) {
  if (!file) return true;
  let detected = null;
  try { setLoading(true); detected = await readDrawingRevision(file); }
  finally { setLoading(false); }

  const en = _normRev(expectedLabel);
  const dn = detected ? _normRev(detected.rev) : null;

  if (!detected || !detected.confident || !dn) {
    toast(`Couldn't verify the revision on this drawing — uploading as ${expectedLabel}.`, 'info');
    return true;
  }
  if (en && dn.letter === en.letter && dn.num === en.num) {
    toast(`Revision verified: drawing marked ${detected.rev} → ${expectedLabel}.`, 'success');
    return true;
  }
  const ok = await showConfirmAsync(
    'Revision mismatch',
    `This drawing appears to be marked <strong>${detected.rev}</strong>, but you're about to upload it as <strong>${expectedLabel}</strong>.<br><br>Check you've got the right file going into the right slot. Upload anyway?`,
    { okLabel: 'Upload anyway', cancelLabel: 'Cancel', danger: true }
  );
  if (ok) console.warn(`Revision override: drawing ${detected.rev} uploaded as ${expectedLabel}`);
  return ok;
}

async function confirmUploadFile() {
  if (!_uploadFiles.length) { toast('Please select a file', 'error'); return; }
  if (!_uploadContext) return;

  // Pre-check token before starting upload to avoid mid-upload redirect
  const preToken = AUTH.getStoredToken();
  if (!preToken) {
    toast('Session expired — please log in again. Your draftsman session will be preserved.', 'error');
    return;
  }

  const { element, subElement, jobId, projectId } = _uploadContext;
  const projData = drawingsData.projects[projectId];
  const job = projData?.jobs?.find(j => j.id === jobId);
  if (!job) { toast('Job not found', 'error'); return; }

  // Approval uploads: verify the drawing's stamped revision matches the slot
  // BEFORE touching SharePoint (so a cancel aborts cleanly). Soft gate.
  if (element === 'approval') {
    const proceed = await verifyRevisionBeforeUpload(_uploadFiles[0], nextApprovalLabel(job, subElement));
    if (!proceed) return;   // user cancelled on a mismatch
  }

  document.getElementById('uploadFileProgress').style.display = 'block';
  document.getElementById('uploadFileBtn').disabled = true;

  try {
    const token = await getToken();
    // Determine the SharePoint target folder path
    let targetFolderId = job.spFolderId;
    const driveId = job.spDriveId || BAMA_DRIVE_ID;

    document.getElementById('uploadFileProgressBar').style.width = '15%';
    document.getElementById('uploadFileProgressText').textContent = 'Finding target folder...';

    // Navigate to the right subfolder
    if (element === 'bom') {
      const folder = await getOrCreateSubfolder(targetFolderId, ELEMENT_FOLDERS.bom, driveId);
      targetFolderId = folder.id;
    } else if (element === 'approval') {
      const approvalFolder = await getOrCreateSubfolder(targetFolderId, ELEMENT_FOLDERS.approval, driveId);
      // Folder name matches the in-app label (P##/C##); numbering is MAX incl.
      // soft-deleted so numbers are never reused. A P folder never renames on
      // approval — the C folder is only created by a Construction upload.
      const folderName = nextApprovalLabel(job, subElement);
      const revFolder = await createFolderInDrive(approvalFolder.id, folderName, driveId);
      targetFolderId = revFolder.id;
    } else if (element === 'parts') {
      const partsFolder = await getOrCreateSubfolder(targetFolderId, ELEMENT_FOLDERS.parts, driveId);
      const subName = subElement === 'sections' ? PARTS_SUBFOLDERS[0] : PARTS_SUBFOLDERS[1];
      const subFolder = await getOrCreateSubfolder(partsFolder.id, subName, driveId);
      targetFolderId = subFolder.id;
    } else if (element === 'assembly') {
      const asmFolder = await getOrCreateSubfolder(targetFolderId, ELEMENT_FOLDERS.assembly, driveId);
      // subElement is taskId — find or create task folder
      const task = job.assembly?.tasks?.find(t => t.id === subElement);
      if (task) {
        const taskFolderName = `${String(task.number).padStart(2,'0')} - ${task.name}`;
        const taskFolder = await getOrCreateSubfolder(asmFolder.id, taskFolderName, driveId);
        targetFolderId = taskFolder.id;
      } else {
        targetFolderId = asmFolder.id;
      }
    } else if (element === 'site') {
      const folder = await getOrCreateSubfolder(targetFolderId, ELEMENT_FOLDERS.site, driveId);
      targetFolderId = folder.id;
    }

    // Upload files
    const uploadedFiles = [];
    for (let i = 0; i < _uploadFiles.length; i++) {
      const file = _uploadFiles[i];
      const pct = 20 + Math.round((i / _uploadFiles.length) * 65);
      document.getElementById('uploadFileProgressBar').style.width = `${pct}%`;
      document.getElementById('uploadFileProgressText').textContent = `Uploading ${i + 1} of ${_uploadFiles.length}...`;

      const arrayBuffer = await file.arrayBuffer();
      const uploaded = await uploadFileToFolder(targetFolderId, file.name, arrayBuffer, file.type, driveId);
      uploadedFiles.push({
        id: Date.now().toString() + '-' + i,
        name: document.getElementById('uploadFileName').value.trim() || file.name.replace(/\.[^.]+$/, ''),
        fileName: file.name,
        fileId: uploaded.id,
        driveId: uploaded.parentReference?.driveId || driveId,
        webUrl: uploaded.webUrl,
        uploadedAt: new Date().toISOString()
      });
    }

    document.getElementById('uploadFileProgressBar').style.width = '90%';
    document.getElementById('uploadFileProgressText').textContent = 'Saving data...';

    // Save to SQL (approval, parts, site) or local blob state (bom, assembly legacy)
    const jobIdInt = parseInt(job.id);
    if (element === 'bom') {
      if (!job.bom) job.bom = { files: [], notes: [] };
      job.bom.files.push(...uploadedFiles);
      // BOM files are tracked in JobBomItems — no extra save needed here
    } else if (element === 'approval') {
      if (!job.approval) job.approval = { revisions: [], notes: [] };
      const type = subElement || 'PO';
      // Status is derived server-side: a fresh P lands as 'sent', a C as
      // 'approved'. The client no longer supplies it.
      const saved = await api.post(`/api/drawing-elements/${jobIdInt}/approval-revision`, {
        type,
        uploadedBy: _currentDraftsmanName || null,
        files: uploadedFiles.map(f => ({
          name: f.name, fileName: f.fileName,
          fileId: f.fileId, driveId: f.driveId,
          webUrl: f.webUrl, uploadedAt: f.uploadedAt
        }))
      });
      job.approval.revisions.push({
        id: saved.id, type: saved.type, number: saved.number,
        constructionNumber: saved.constructionNumber,
        status: saved.status, uploadedAt: saved.uploadedAt,
        files: saved.files
      });
    } else if (element === 'parts') {
      if (!job.parts) job.parts = { sections: { files: [], notes: [] }, plates: { files: [], notes: [] } };
      const fileContext = subElement === 'sections' ? 'parts-sections' : 'parts-plates';
      const target = subElement === 'sections' ? job.parts.sections : job.parts.plates;
      if (!target.files) target.files = [];
      for (const f of uploadedFiles) {
        const saved = await api.post(`/api/drawing-elements/${jobIdInt}/file`, {
          fileContext, name: f.name, fileName: f.fileName,
          fileId: f.fileId, driveId: f.driveId,
          webUrl: f.webUrl, uploadedAt: f.uploadedAt,
          uploadedBy: _currentDraftsmanName || null
        });
        target.files.push({ ...saved });
      }
    } else if (element === 'assembly') {
      // Assembly PDFs handled by the separate assembly upload flow — no-op here
    } else if (element === 'site') {
      if (!job.site) job.site = { files: [], notes: [] };
      for (const f of uploadedFiles) {
        const saved = await api.post(`/api/drawing-elements/${jobIdInt}/file`, {
          fileContext: 'site', name: f.name, fileName: f.fileName,
          fileId: f.fileId, driveId: f.driveId,
          webUrl: f.webUrl, uploadedAt: f.uploadedAt,
          uploadedBy: _currentDraftsmanName || null
        });
        job.site.files.push({ ...saved });
      }
    }

    document.getElementById('uploadFileProgressBar').style.width = '100%';
    document.getElementById('uploadFileProgressText').textContent = 'Done!';

    setTimeout(() => {
      closeUploadFileModal();
      toast(`${uploadedFiles.length} file${uploadedFiles.length>1?'s':''} uploaded`, 'success');
      renderAllElements();
    }, 400);

  } catch (e) {
    console.error('Upload error:', e);
    toast(`Upload failed: ${e.message}`, 'error');
    document.getElementById('uploadFileProgress').style.display = 'none';
  } finally {
    document.getElementById('uploadFileBtn').disabled = false;
  }
}

// ═══════════════════════════════════════════
// DELETE FILE
// ═══════════════════════════════════════════
function confirmDeleteFile(context, fileId) {
  if (!currentJob || !currentProject) return;

  // Resolve the file and the array it lives in. Approval files live inside
  // revisions, so getFilesArray() returns null for them — search the revisions.
  let filesArr = getFilesArray(context);
  let file = filesArr?.find(f => String(f.id) === String(fileId));
  if (!file && context === 'approval') {
    for (const rev of (currentJob.approval?.revisions || [])) {
      const f = (rev.files || []).find(x => String(x.id) === String(fileId));
      if (f) { file = f; filesArr = rev.files; break; }
    }
  }
  if (!file) return;

  showConfirm('Delete File', `Delete "${file.name || file.fileName}"? This cannot be undone.`, async () => {
    try {
      setLoading(true);
      // Delete from SharePoint
      if (file.fileId) {
        await deleteFileFromDrive(file.fileId, file.driveId);
      }
      // Delete from SQL
      const jobIdInt = parseInt(currentJob.id);
      if (context === 'parts-sections' || context === 'parts-plates' || context === 'site' || context === 'rams') {
        await api.delete(`/api/drawing-elements/${jobIdInt}/file/${fileId}`);
      } else if (context === 'approval') {
        await api.delete(`/api/drawing-elements/${jobIdInt}/revision-file/${fileId}`);
      }
      // Remove from local state
      const idx = filesArr.indexOf(file);
      if (idx >= 0) filesArr.splice(idx, 1);
      toast('File deleted', 'success');
      renderAllElements();
    } catch (e) { toast('Delete failed: ' + e.message, 'error'); }
    finally { setLoading(false); }
  });
}

function getFilesArray(context) {
  if (!currentJob) return null;
  if (context === 'bom') return currentJob.bom?.files;
  if (context === 'parts-sections') return currentJob.parts?.sections?.files;
  if (context === 'parts-plates') return currentJob.parts?.plates?.files;
  if (context === 'site') return currentJob.site?.files;
  if (context === 'rams') return currentJob.rams?.files;
  if (context.startsWith('assembly-')) {
    const taskId = context.replace('assembly-', '');
    const task = currentJob.assembly?.tasks?.find(t => t.id === taskId);
    return task?.files;
  }
  // Approval files are inside revisions, handled separately
  return null;
}

// ═══════════════════════════════════════════
// PRINT FILE
// ═══════════════════════════════════════════
async function printFile(fileId, driveId) {
  if (!fileId) { toast('No file to print', 'error'); return; }
  try {
    setLoading(true);
    const token = await getToken();
    const drive = driveId || BAMA_DRIVE_ID;
    const res = await fetch(
      `https://graph.microsoft.com/v1.0/drives/${drive}/items/${fileId}`,
      { headers: { 'Authorization': `Bearer ${token}` } }
    );
    if (!res.ok) throw new Error('File not found');
    const meta = await res.json();
    const downloadUrl = meta['@microsoft.graph.downloadUrl'];
    if (downloadUrl) {
      const pdfRes = await fetch(downloadUrl);
      const blob = await pdfRes.blob();
      const blobUrl = URL.createObjectURL(blob);
      const printWin = window.open(blobUrl);
      if (printWin) {
        printWin.onload = () => { printWin.print(); };
      }
    } else if (meta.webUrl) {
      window.open(meta.webUrl, '_blank');
    }
  } catch (e) {
    toast('Print failed: ' + e.message, 'error');
  } finally {
    setLoading(false);
  }
}

// ═══════════════════════════════════════════
// PRINT ALL — merge many SharePoint PDFs into one and open the print dialog.
// Used by the Parts element's "Print All" buttons (Sections / Plates) where
// the workshop may have 1–200 individual drawing PDFs and needs them as a
// single printable file. pdf-lib copies source pages as vectors (no
// rasterising), so the merged document stays crisp and small even at hundreds
// of pages. Files that aren't PDFs, or that fail to download/parse, are
// skipped and reported rather than aborting the whole batch.
// ═══════════════════════════════════════════
async function printMergedPdfs(files, label) {
  if (typeof PDFLib === 'undefined') {
    toast('PDF library not loaded — refresh and try again', 'error');
    return;
  }
  const pdfFiles = (files || []).filter(f =>
    f.fileId && (f.fileName || f.name || '').toLowerCase().endsWith('.pdf'));
  const skipped = (files || []).length - pdfFiles.length;
  if (!pdfFiles.length) { toast('No PDF files to print', 'error'); return; }

  setLoading(true);
  try {
    const token = await getToken();
    const merged = await PDFLib.PDFDocument.create();
    const failed = [];

    for (let i = 0; i < pdfFiles.length; i++) {
      const f = pdfFiles[i];
      toast(`Preparing ${label}: ${i + 1}/${pdfFiles.length}…`, 'info');
      try {
        const drive = f.driveId || BAMA_DRIVE_ID;
        const metaRes = await fetch(
          `https://graph.microsoft.com/v1.0/drives/${drive}/items/${f.fileId}`,
          { headers: { 'Authorization': `Bearer ${token}` } }
        );
        if (!metaRes.ok) throw new Error('meta ' + metaRes.status);
        const meta = await metaRes.json();
        const url = meta['@microsoft.graph.downloadUrl'];
        if (!url) throw new Error('no download url');
        const bytes = await (await fetch(url)).arrayBuffer();
        const src = await PDFLib.PDFDocument.load(bytes, { ignoreEncryption: true });
        const pages = await merged.copyPages(src, src.getPageIndices());
        pages.forEach(p => merged.addPage(p));
      } catch (e) {
        console.warn('Print All: skipped', f.fileName || f.name, e.message);
        failed.push(f.fileName || f.name || 'unnamed');
      }
    }

    if (!merged.getPageCount()) {
      toast('Could not load any PDFs to print', 'error');
      return;
    }

    const out = await merged.save();
    const blobUrl = URL.createObjectURL(new Blob([out], { type: 'application/pdf' }));
    const win = window.open(blobUrl);
    if (win) {
      win.onload = () => { try { win.print(); } catch (_) {} };
    } else {
      // Popup blocked — fall back to a download so the user still gets the file.
      const a = document.createElement('a');
      a.href = blobUrl;
      a.download = `${label.replace(/\s+/g, '-')}.pdf`;
      a.click();
    }
    setTimeout(() => URL.revokeObjectURL(blobUrl), 60000);

    const pages = merged.getPageCount();
    let msg = `${label}: ${pages} page${pages > 1 ? 's' : ''} ready`;
    if (failed.length) msg += ` · ${failed.length} skipped`;
    if (skipped) msg += ` · ${skipped} non-PDF ignored`;
    toast(msg, (failed.length || skipped) ? 'info' : 'success');
  } catch (e) {
    toast('Print All failed: ' + e.message, 'error');
  } finally {
    setLoading(false);
  }
}

// onclick wrapper for the Parts "Print All" buttons. sub = 'sections' | 'plates'.
function printAllParts(sub) {
  if (!currentJob) return;
  const files = sub === 'plates'
    ? (currentJob.parts?.plates?.files || [])
    : (currentJob.parts?.sections?.files || []);
  printMergedPdfs(files, sub === 'plates' ? 'Plates' : 'Sections');
}


// ═══════════════════════════════════════════
// ASSEMBLY: UPLOAD + OCR + REVIEW + SAVE
// (job-fabrication rework — see SPEC §5)
// ═══════════════════════════════════════════
//
// Flow: drop-zone collects PDFs → each PDF uploaded to SharePoint under
// `04 - Assembly/<filename>.pdf` → vision OCR via callClaude → results
// pushed to _assemblyQueue → review modal walks the queue one by one,
// user edits + confirms → POST /api/job-assemblies (assembly + parts
// in one txn). On duplicate (job_id, assembly_mark) the API returns
// 409 with error='duplicate_mark' and we show the replace-confirm
// prompt; on confirm we DELETE the old then retry.

// Opens the assembly review modal with blank fields and a manual-entry
// stub so the draftsman can enter parts directly without uploading a PDF.
// Used when OCR cannot read the drawing (e.g. hand-drawn or non-standard
// drawing formats). sharepoint_file_id is set to 'manual-entry' as a
// placeholder; the "Open PDF" button will not appear on the assembly card.
function openManualAssemblyModal() {
  if (!currentJob) { toast('No job selected.', 'error'); return; }
  const blank = {
    file: { name: 'Manual entry' },
    sharepoint: {
      fileId:   'manual-entry',
      driveId:  currentJob.spDriveId || BAMA_DRIVE_ID,
      webUrl:   null,
      fileName: 'Manual entry'
    },
    ocr: { assembly_mark: '', quantity: null, finish_label_raw: null,
           total_area_m2: null, total_weight_kg: null,
           parts: [{ part_mark: '', quantity: 1, profile: '', length_mm: null,
                     material: 'S355JR', area_m2: null, weight_kg: null }] },
    ocrFailed: false, _reviewed: false, _collapsed: false
  };
  // Append to the open batch if the review modal is already up, otherwise start fresh.
  const modal = document.getElementById('assemblyReviewModal');
  if (modal && modal.classList.contains('active') && _assemblyQueue.length) {
    _assemblyQueue.push(blank);
  } else {
    _assemblyQueue = [blank];
  }
  openAssemblyReviewModal();
}

// Assembly drawings usually arrive as ONE multi-page PDF per paper size
// (Tekla output — each PAGE is a separate assembly with its own titleblock
// and material list). The whole bundle is too big to OCR in one call and
// holds many assemblies, so split it into per-page PDFs; each page then
// becomes its own review card. Single-page PDFs (or anything pdf-lib can't
// parse) pass straight through unchanged.
async function _splitPdfIntoPages(file) {
  if (typeof PDFLib === 'undefined' || !PDFLib.PDFDocument) return [file];
  let src;
  try {
    const buf = await file.arrayBuffer();
    src = await PDFLib.PDFDocument.load(buf, { ignoreEncryption: true });
  } catch (e) {
    console.warn(`Couldn't parse ${file.name} for splitting — using whole file:`, e);
    return [file];
  }
  const n = src.getPageCount();
  if (n <= 1) return [file];
  const stem = file.name.replace(/\.pdf$/i, '');
  const out = [];
  for (let p = 0; p < n; p++) {
    const doc = await PDFLib.PDFDocument.create();
    const [copied] = await doc.copyPages(src, [p]);
    doc.addPage(copied);
    const bytes = await doc.save();
    const pageNo = String(p + 1).padStart(2, '0');
    out.push(new File([bytes], `${stem}_p${pageNo}.pdf`, { type: 'application/pdf' }));
  }
  return out;
}

// Make an assembly mark unique against BOTH the current queue and the job's
// existing assemblies (case-insensitive). "X" → "X (2)" → "X (3)"…
function _armDedupeMark(mark, pendingQueue) {
  const base = String(mark || '').trim();
  if (!base) return base;
  const taken = new Set();
  for (const it of [...(_assemblyQueue || []), ...(pendingQueue || [])]) {
    const m = it && it.ocr && it.ocr.assembly_mark;
    if (m) taken.add(String(m).toLowerCase());
  }
  const existing = (typeof currentJob !== 'undefined' && currentJob)
    ? (_assembliesByJob[parseInt(currentJob.id)] || []) : [];
  for (const a of existing) {
    if (a && a.assembly_mark) taken.add(String(a.assembly_mark).toLowerCase());
  }
  if (!taken.has(base.toLowerCase())) return base;
  for (let n = 2; n < 100; n++) {
    const candidate = `${base} (${n})`;
    if (!taken.has(candidate.toLowerCase())) return candidate;
  }
  return base;
}

async function onAssemblyFilesPicked(fileList) {
  if (!fileList || !fileList.length) return;
  if (!currentJob || !currentJob.spFolderId) {
    toast('Job folder not available — try reloading.', 'error');
    return;
  }
  const files = Array.from(fileList).filter(f =>
    f.type === 'application/pdf' || f.name.toLowerCase().endsWith('.pdf')
  );
  if (!files.length) {
    toast('Only PDFs accepted for assembly upload.', 'error');
    return;
  }

  // Show a small progress banner inside the Assembly section while we
  // upload+OCR each file. We DON'T open the review modal until ALL
  // files are OCR'd — that way the draftsman gets a single sequential
  // review session at the end, with a clear N-of-M counter.
  const container = document.getElementById('assemblyContent');
  const banner = document.createElement('div');
  banner.id = 'assemblyUploadBanner';
  banner.style.cssText = 'background:rgba(255,107,0,.08);border:1px solid rgba(255,107,0,.3);border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:12px;color:var(--text)';
  banner.textContent = `Uploading 0 / ${files.length}…`;
  container.prepend(banner);

  const driveId = currentJob.spDriveId || BAMA_DRIVE_ID;
  let asmFolder;
  try {
    asmFolder = await getOrCreateSubfolder(currentJob.spFolderId, ELEMENT_FOLDERS.assembly, driveId);
  } catch (e) {
    banner.remove();
    toast(`Could not access Assembly folder: ${e.message}`, 'error');
    return;
  }

  // Expand multi-page bundles into one PDF per page (= one assembly each).
  banner.textContent = 'Preparing drawings…';
  const pages = [];
  for (const f of files) {
    try {
      const split = await _splitPdfIntoPages(f);
      pages.push(...split);
    } catch (e) {
      console.warn(`Split failed on ${f.name}, using whole file:`, e);
      pages.push(f);
    }
  }
  if (pages.length > files.length) {
    toast(`${files.length} PDF${files.length > 1 ? 's' : ''} → ${pages.length} drawings (one per page).`, 'info');
  }

  const queue = [];
  for (let i = 0; i < pages.length; i++) {
    const file = pages[i];
    banner.textContent = `Uploading ${i + 1} / ${pages.length} — ${file.name}`;

    // Step 1 — upload to SharePoint. If THIS fails there's no file in SP,
    // so skip the item entirely (nothing to recover).
    let uploaded;
    try {
      const arrayBuffer = await file.arrayBuffer();
      uploaded = await uploadFileToFolder(asmFolder.id, file.name, arrayBuffer, file.type, driveId);
    } catch (e) {
      console.warn(`Upload failed on ${file.name}:`, e);
      toast(`${file.name}: upload failed — ${e.message}`, 'error');
      continue;
    }

    const sharepoint = {
      fileId:  uploaded.id,
      driveId: uploaded.parentReference?.driveId || driveId,
      webUrl:  uploaded.webUrl,
      fileName: file.name
    };

    // Step 2 — OCR. The file is ALREADY in SharePoint at this point, so an
    // OCR failure must NOT discard it (that's what left files orphaned in SP
    // with no JobAssemblies row). Instead, queue it for manual entry with a
    // blank-but-editable OCR stub, carrying the real SharePoint reference so
    // the saved assembly still gets a working "Open PDF" link.
    banner.textContent = `Parsing ${i + 1} / ${pages.length} — ${file.name}`;
    let envelope, ocrFailed = false;
    try {
      envelope = await ocrAssemblyPdf(file);
    } catch (e) {
      console.warn(`OCR failed on ${file.name} (file is in SharePoint, queued for manual entry):`, e);
      toast(`${file.name}: couldn't auto-read the drawing — enter the details manually.`, 'warn');
      ocrFailed = true;
      envelope = { assemblies: [{
        assembly_mark: '', quantity: null, finish_label_raw: null,
        total_area_m2: null, total_weight_kg: null,
        parts: [{ part_mark: '', quantity: 1, profile: '', length_mm: null,
                  material: 'S355JR', area_m2: null, weight_kg: null }]
      }] };
    }

    // GA / overview sheets are uploaded to SharePoint (useful reference) but
    // are NOT fabricatable assemblies — skip them in the review queue.
    if (envelope.skip) {
      toast(`${file.name}: skipped (${envelope.reason}) — file kept in SharePoint.`, 'info');
      continue;
    }

    // One sheet can hold several assemblies (e.g. "Column 1-C & 2-C, qty 1
    // of each") — queue one review card per assembly, all pointing at the
    // same SharePoint file.
    for (const ocr of envelope.assemblies) {
      if (!ocr) continue;
      if (!Array.isArray(ocr.parts) || !ocr.parts.length) {
        ocr.parts = [{ part_mark: '', quantity: 1, profile: '', length_mm: null,
                       material: 'S355JR', area_m2: null, weight_kg: null }];
      }
      // Sketch drawings carry no part marks — default them so the save
      // endpoint (part_mark NOT NULL) never rejects the card.
      ocr.parts.forEach((p, i) => {
        if (p && !p.part_mark && (p.profile || '').trim()) {
          const pref = (String(p.profile).match(/^[A-Za-z]+/) || [''])[0].toUpperCase();
          p.part_mark = pref && pref !== 'PLT' ? pref : `P${i + 1}`;
        }
      });
      // Duplicate assembly marks (same title on two sheets, or a mark that
      // already exists on the job) → suffix (2), (3)… so the UNIQUE
      // (job_id, mark) constraint doesn't 409 half way through a batch.
      ocr.assembly_mark = _armDedupeMark(ocr.assembly_mark, queue);
      _armFillWeightsFromSteelDb(ocr);   // steel-DB weights for anything the drawing didn't state
      queue.push({ file, sharepoint, ocr, ocrFailed });
    }
  }

  banner.remove();
  // Clear the file input so picking the same files again retriggers change
  const input = document.getElementById('assemblyFileInput');
  if (input) input.value = '';

  if (!queue.length) {
    toast('No assemblies were parsed.', 'error');
    return;
  }

  // If a review batch is already open, ADD these to it (don't wipe the ones
  // still waiting to be reviewed — that was the "second batch replaces first"
  // bug). Otherwise start a fresh batch.
  const modal = document.getElementById('assemblyReviewModal');
  if (modal && modal.classList.contains('active') && _assemblyQueue.length) {
    _assemblyQueue.push(...queue);
    toast(`Added ${queue.length} more — ${_assemblyQueue.length} now queued.`, 'info');
  } else {
    _assemblyQueue = queue;
  }
  openAssemblyReviewModal();
}

// Run Claude vision OCR on one assembly PDF.
// Returns { assembly_mark, quantity, finish_label_raw, total_area_m2,
//           total_weight_kg, parts:[{part_mark,quantity,profile,
//           length_mm,material,area_m2,weight_kg}, ...] }
// Caller catches and surfaces any error.
async function ocrAssemblyPdf(file) {
  const dataUri = await _fileToDataUri(file);
  const b64 = dataUri.split(',')[1];

  const prompt = `Extract data from this UK steel-fabrication assembly drawing. Drawings arrive in TWO different layouts — detect which one this is and read accordingly.

LAYOUT 1 — Tekla assembly drawing: a SUMMARY TABLE in the top-right corner with columns
  Mark | Quantity | Profile | Length | Material | Area (m²) | Weight (kg)
The FIRST row is the assembly itself (e.g. RL1 | 26 | "Values for ONE assembly"). Subsequent rows are the parts making up ONE assembly. The LAST row is "Totals for ONE assembly" (area + weight). CRITICAL: never include the first (assembly) row or the totals row in "parts" — parts are ONLY the component rows between them, and their quantities are per ONE assembly. "total_weight_kg" MUST be the printed "Totals for ONE assembly" weight figure, copied as printed. Near the bottom centre there may be finish text like "26 No. Mkd RL1 (Galvanised)" — the parenthesised text is the finish.

LAYOUT 2 — sketch/SolidWorks-style sheet (title block bottom-right with fields like "Sketch Contents", "Quantity required", "Dwg No", "Sheet", "Project"): there is NO parts table. Instead:
- assembly name = the "Sketch Contents" field (e.g. "Basement Column 1-A"). Prefer a short mark if the sheet gives one (e.g. "B-Column-1-A"), else use the sketch contents text.
- quantity = the "Quantity required" title-block field and/or a "QUANTITY N" box near the notes. If they disagree, use the QUANTITY box.
- parts = derive from the section/plate CALLOUTS on the views, e.g. "SHS 180 x 180 x 10" with the "Overall Height" dimension as its length; "20mm Plate"/"15mm Capped End" as plate parts (profile "PLT20", "PLT15"; length null unless dimensioned). One entry per distinct callout, quantity 1 each unless clearly repeated (e.g. top plate + base plate = two plate entries).
- part_mark = a SHORT descriptive mark since these sheets have no Tekla marks: "SHS" / "RHS" for the main member, "TOP PLT" / "BASE PLT" / "CAP PLT" / "GUSSET" for plates. Never leave part_mark null.
- material = from notes like "All plates S355" (use "S355" for plates; main section material null unless stated).
- finish_label_raw = from notes like "-Paint Red Oxide" → "Red Oxide Paint" ("Galvanised" if stated, etc.); null if no finish note.
- area/weight are NOT shown on this layout — return null, never estimate them.

SPECIAL CASES:
- If the sheet is a GENERAL ARRANGEMENT / overview / isometric key (title like "General Arrangement", multiple assemblies labelled with leader lines, no single QUANTITY), it is NOT a fabricatable assembly: return {"skip": true, "reason": "general arrangement"}.
- If ONE sheet covers MULTIPLE variants (e.g. "Column 1-C & 2-C", "QUANTITY 1 (OF EACH)", different overall heights listed like "B1C = 2530 / B2C = 2830"), return one assembly PER VARIANT, each with its own mark, quantity and part lengths.
- A sheet like "Thermal Break Plate" with several plates each with its own QUANTITY box: return one assembly per plate variant (mark from its caption, e.g. "Thermal Break — Column 1A"), parts = the plate itself.

Return ONLY JSON, no markdown, no commentary. ALWAYS use this envelope shape (a single-assembly sheet is just an array of one):
{
  "assemblies": [
    {
      "assembly_mark": "RL1",
      "quantity": 26,
      "finish_label_raw": "Galvanised" | null,
      "total_area_m2": 0.25 | null,
      "total_weight_kg": 6.47 | null,
      "parts": [
        { "part_mark": "F20", "quantity": 1, "profile": "PLT10x60", "length_mm": 150.0, "material": "S275JR", "area_m2": 0.02, "weight_kg": 0.69 }
      ]
    }
  ]
}
or {"skip": true, "reason": "..."}

Set any field you cannot determine to null. Use null (not 0) for missing numerics. Copy dimensions as printed — do NOT calculate or invent any number.`;

  const result = await callClaude({
    model: 'claude-sonnet-4-6',
    max_tokens: 3000,
    messages: [{
      role: 'user',
      content: [
        { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } },
        { type: 'text', text: prompt }
      ]
    }]
  });
  const text = (result.content?.find(b => b.type === 'text')?.text || '').trim();
  const jsonStart = text.indexOf('{'), jsonEnd = text.lastIndexOf('}');
  if (jsonStart < 0 || jsonEnd < jsonStart) throw new Error('OCR returned no JSON');
  const parsed = JSON.parse(text.slice(jsonStart, jsonEnd + 1));
  // Normalise: {skip}, {assemblies:[...]}, or legacy single object → envelope
  if (parsed && parsed.skip) return { skip: true, reason: parsed.reason || 'not an assembly sheet' };
  if (parsed && Array.isArray(parsed.assemblies)) return { assemblies: parsed.assemblies.filter(a => a) };
  return { assemblies: [parsed] };
}

// ── Review modal ──
// ── Review modal (batch) ──
// The review is a single scrollable screen: every queued drawing is a
// collapsible card. Tick "looks good" on the ones you've checked (or hit
// "Accept all" to tick every readable one at once), then "Save all ticked"
// commits them in one go. New uploads append to this queue rather than
// replacing it.
function openAssemblyReviewModal() {
  if (!_assemblyQueue.length) return;
  const modal = document.getElementById('assemblyReviewModal');
  if (!modal) return;
  modal.classList.add('active');
  renderAssemblyBatch();
}

function closeAssemblyReviewModal() {
  const modal = document.getElementById('assemblyReviewModal');
  if (modal) modal.classList.remove('active');
  _assemblyQueue = [];
  _assemblyReviewIndex = 0;
}

// A queued drawing is "valid" (saveable) once it has a mark, qty >= 1 and at
// least one part with a mark or profile. Incomplete/unreadable ones can't be
// auto-ticked by Accept-all and are flagged in their card header.
function _asmItemValid(item) {
  const ocr = item.ocr || {};
  const hasMark = (ocr.assembly_mark || '').trim() !== '';
  const qty = parseInt(ocr.quantity);
  const parts = (ocr.parts || []).filter(p => (p.part_mark || p.profile));
  return hasMark && qty >= 1 && parts.length >= 1;
}

// Preselect a finish for an item from its raw OCR text, once, storing the id
// on the item so re-renders keep the user's choice.
function _asmResolveFinishId(item) {
  if (item._finishId !== undefined) return item._finishId;
  const finishes = _finishesCache || [];
  const raw = ((item.ocr && item.ocr.finish_label_raw) || '').trim().toLowerCase();
  let matched = '';
  if (raw) {
    for (const f of finishes) {
      const fname = (f.name || '').toLowerCase();
      if (fname === raw || raw.startsWith(fname) || fname.startsWith(raw) ||
          (raw.length > 4 && fname.includes(raw.slice(0, 5))) ||
          (fname.length > 4 && raw.includes(fname.slice(0, 5)))) {
        matched = String(f.id); break;
      }
    }
  }
  item._finishId = matched;
  return matched;
}

// ── Steel-DB auto-weight (same principle as QB take-off) ─────────────────
// lookupKgM/findSteelProfile come from steel-data.js (loaded per page).
// Deterministic: weight PER PIECE = kg/m × length_m. The save-time total
// already multiplies by part quantity — do NOT multiply here.
function _armAutoWeightPart(p) {
  if (typeof lookupKgM !== 'function') return null;
  const kgm = lookupKgM(p.profile || '');
  const lenM = (Number(p.length_mm) || 0) / 1000;
  if (!kgm || kgm <= 0 || lenM <= 0) return null;
  return Number((kgm * lenM).toFixed(2));
}

// Fill any MISSING part weights from the steel DB (never overwrites an
// OCR'd or typed value). Called right after OCR before queueing.
function _armFillWeightsFromSteelDb(ocr) {
  if (!ocr || !Array.isArray(ocr.parts)) return;
  for (const p of ocr.parts) {
    if (p && (p.weight_kg === null || p.weight_kg === undefined || p.weight_kg === '')) {
      const w = _armAutoWeightPart(p);
      if (w !== null) { p.weight_kg = w; p._auto_weight = true; }
    }
  }
}

// Live recompute while editing a part row in the review card. Only touches
// the weight cell if it is empty or was auto-filled (data-auto flag) — a
// hand-typed weight is never overwritten.
function armPartCellInput(inp) {
  const tr = inp.closest('tr');
  if (!tr) return;
  const get = f => tr.querySelector(`.arm-cell[data-f="${f}"]`);
  const profEl = get('profile'), lenEl = get('length_mm'), wEl = get('weight_kg');
  if (!profEl || !wEl) return;

  // kg/m tooltip on the profile cell
  if (typeof findSteelProfile === 'function') {
    const m = findSteelProfile(profEl.value || '');
    profEl.title = (m && m.kgm)
      ? `${m.canonical} — ${m.kgm} kg/m${m.confidence === 'fuzzy' ? ' (nearest match)' : ''}`
      : (profEl.value ? 'Not in steel database' : '');
  }

  const manual = wEl.value !== '' && wEl.dataset.auto !== '1';
  if (manual) return;
  const w = _armAutoWeightPart({
    profile: profEl.value,
    length_mm: lenEl ? lenEl.value : null
  });
  if (w !== null) {
    wEl.value = w;
    wEl.dataset.auto = '1';
    wEl.style.color = 'var(--green)';
  } else if (wEl.dataset.auto === '1') {
    wEl.value = '';
    wEl.dataset.auto = '';
    wEl.style.color = '';
  }
}

function _armPartsRowsHtml(parts, qi) {
  const heavyIdx = heaviestPartIndex(parts);
  let rows = '';
  for (let i = 0; i < parts.length; i++) {
    const p = parts[i] || {};
    const hi = i === heavyIdx;
    const trStyle = hi ? 'background:rgba(255,107,0,.08)' : '';
    const accent = hi ? 'color:var(--accent)' : '';
    rows += `<tr class="arm-part-row" style="${trStyle}" data-i="${i}">
      <td style="padding:3px 4px 3px 0"><input data-f="part_mark" value="${escapeHtml(p.part_mark || '')}" style="width:48px;${accent}" class="arm-cell"/></td>
      <td style="padding:3px 4px"><input data-f="quantity" type="number" value="${p.quantity ?? ''}" style="width:42px" class="arm-cell"/></td>
      <td style="padding:3px 4px"><input data-f="profile" value="${escapeHtml(p.profile || '')}" style="width:88px;${accent}" class="arm-cell" oninput="armPartCellInput(this)"/></td>
      <td style="padding:3px 4px"><input data-f="length_mm" type="number" step="0.1" value="${p.length_mm ?? ''}" style="width:66px" class="arm-cell" oninput="armPartCellInput(this)"/></td>
      <td style="padding:3px 4px"><input data-f="material" value="${escapeHtml(p.material || '')}" style="width:60px" class="arm-cell"/></td>
      <td style="padding:3px 4px"><input data-f="area_m2" type="number" step="0.001" value="${p.area_m2 ?? ''}" style="width:54px;text-align:right" class="arm-cell"/></td>
      <td style="padding:3px 4px"><input data-f="weight_kg" type="number" step="0.001" value="${p.weight_kg ?? ''}" ${p._auto_weight ? 'data-auto="1"' : ''} style="width:60px;text-align:right;${p._auto_weight ? 'color:var(--green)' : accent}" class="arm-cell" oninput="this.dataset.auto=''; this.style.color=''"/></td>
      <td style="padding:3px 0 3px 4px"><button class="btn btn-ghost" style="padding:2px 6px;font-size:12px" onclick="armRemoveRow(${qi}, ${i})" title="Remove">&times;</button></td>
    </tr>`;
  }
  return rows;
}

function renderAssemblyBatch() {
  const list = document.getElementById('armBatchList');
  if (!list) return;
  const total = _assemblyQueue.length;

  const counter = document.getElementById('armCounter');
  if (counter) counter.textContent = total ? `${total} drawing${total > 1 ? 's' : ''} queued` : '';

  const finishes = _finishesCache || [];
  const finishOptsFor = (selId) => {
    let o = '<option value="">(No finish required)</option>';
    for (const f of finishes) {
      o += `<option value="${f.id}"${String(f.id) === String(selId) ? ' selected' : ''}>${escapeHtml(f.name)}</option>`;
    }
    return o;
  };

  let html = '';
  for (let qi = 0; qi < total; qi++) {
    const item = _assemblyQueue[qi];
    if (item._reviewed === undefined) item._reviewed = false;
    if (item._collapsed === undefined) item._collapsed = false;
    const ocr = item.ocr || {};
    const valid = _asmItemValid(item);
    const finishId = _asmResolveFinishId(item);

    const flag = item.ocrFailed
      ? '<span style="color:#fcd34d;font-size:11px" title="OCR could not read this — fill it in">&#9888; manual</span>'
      : (!valid ? '<span style="color:var(--red);font-size:11px" title="Needs mark, qty and at least one part">incomplete</span>' : '');

    const failNotice = item.ocrFailed
      ? `<div style="background:rgba(234,179,8,.1);border:1px solid rgba(234,179,8,.35);color:#fcd34d;border-radius:8px;padding:8px 10px;font-size:11px;margin-bottom:10px;line-height:1.4">&#9888; Couldn't auto-read this drawing. It's saved in SharePoint &mdash; enter the mark, quantity and parts, then tick &ldquo;looks good&rdquo;.</div>`
      : '';

    html += `<div class="arm-card" data-qi="${qi}" style="border:1px solid var(--border);border-radius:8px;margin-bottom:10px;overflow:hidden">
      <div style="display:flex;align-items:center;gap:10px;padding:8px 10px;background:var(--bg-darker);cursor:pointer" onclick="armToggleCollapse(${qi})">
        <span class="arm-chev" style="font-size:11px;color:var(--subtle);width:12px">${item._collapsed ? '&#9656;' : '&#9662;'}</span>
        <label onclick="event.stopPropagation()" style="display:flex;align-items:center;gap:6px;cursor:pointer;user-select:none">
          <input type="checkbox" class="arm-ok" ${item._reviewed ? 'checked' : ''} onchange="armToggleReviewed(${qi}, this.checked)">
          <span style="font-size:11px;color:var(--subtle)">looks good</span>
        </label>
        <span style="font-family:var(--font-mono);font-size:12px;color:var(--text)">${escapeHtml(ocr.assembly_mark || '(no mark)')}</span>
        <span style="font-size:11px;color:var(--muted);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(item.sharepoint.fileName || '')}</span>
        ${flag}
        <button class="btn btn-ghost" style="padding:2px 8px;font-size:14px" onclick="event.stopPropagation();armRemoveCard(${qi})" title="Remove from queue">&times;</button>
      </div>
      <div class="arm-card-body" style="padding:12px;display:${item._collapsed ? 'none' : 'block'}">
        ${failNotice}
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px">
          <div>
            <div class="field-label">ASSEMBLY MARK</div>
            <input type="text" class="field-input arm-mark" value="${escapeHtml(ocr.assembly_mark || '')}" placeholder="e.g. RL1" style="font-family:var(--font-mono)">
          </div>
          <div>
            <div class="field-label">QUANTITY</div>
            <input type="number" class="field-input arm-qty" min="1" value="${ocr.quantity ?? ''}" style="font-family:var(--font-mono)">
          </div>
        </div>
        <div style="margin-bottom:12px">
          <div class="field-label">FINISH</div>
          <select class="field-input arm-finish" onchange="armSetFinish(${qi}, this.value)">${finishOptsFor(finishId)}</select>
        </div>
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
          <div class="field-label" style="margin:0">PARTS <span style="color:var(--subtle);font-weight:400;text-transform:none">&mdash; heaviest highlighted</span></div>
          <button class="btn btn-ghost" style="padding:4px 10px;font-size:11px" onclick="armAddRow(${qi})">&#43; Add row</button>
        </div>
        <div style="background:var(--bg-darker);border:1px solid var(--border);border-radius:8px;padding:8px;overflow-x:auto">
          <table style="width:100%;font-family:var(--font-mono);font-size:11px;border-collapse:collapse;min-width:560px">
            <thead><tr style="color:var(--subtle);text-align:left">
              <th style="font-weight:400;padding:4px 4px 4px 0">Mk</th>
              <th style="font-weight:400;padding:4px">Qty</th>
              <th style="font-weight:400;padding:4px">Profile</th>
              <th style="font-weight:400;padding:4px">Length</th>
              <th style="font-weight:400;padding:4px">Mat'l</th>
              <th style="font-weight:400;padding:4px;text-align:right">Area</th>
              <th style="font-weight:400;padding:4px;text-align:right">Wt (kg)</th>
              <th></th>
            </tr></thead>
            <tbody id="armParts_${qi}">${_armPartsRowsHtml(ocr.parts || [], qi)}</tbody>
          </table>
          ${(() => {
            const aw = _asmWeights(ocr);
            if (!isFinite(aw.weightKg)) return '';
            const src = aw.printedWt != null ? "drawing's totals row" : 'Σ parts';
            let warn = '';
            if (aw.batchSuspect) warn = `<div style="background:rgba(234,179,8,.1);border:1px solid rgba(234,179,8,.35);color:#fcd34d;border-radius:6px;padding:6px 8px;font-size:11px;margin-top:6px;line-height:1.4">&#9888; Parts quantities look like the WHOLE BATCH (&Sigma; parts &asymp; drawing total &times; ${parseInt(ocr.quantity)||1}). Using the drawing's per-assembly total instead.</div>`;
            else if (aw.mismatch) warn = `<div style="background:rgba(234,179,8,.1);border:1px solid rgba(234,179,8,.35);color:#fcd34d;border-radius:6px;padding:6px 8px;font-size:11px;margin-top:6px;line-height:1.4">&#9888; &Sigma; parts (${aw.sumWt.toFixed(1)} kg) &ne; drawing's per-assembly total (${aw.printedWt.toFixed(1)} kg) &mdash; using the drawing total. Check the parts list.</div>`;
            return `<div style="text-align:right;font-size:11px;color:var(--muted);padding:5px 2px 0">Weight of ONE assembly: <span style="font-family:var(--font-mono);color:var(--text);font-weight:600">${aw.weightKg.toFixed(2)} kg</span> <span style="color:var(--subtle)">(${src})</span></div>${warn}`;
          })()}
        </div>
      </div>
    </div>`;
  }
  list.innerHTML = html || '<div style="color:var(--subtle);font-size:12px;padding:20px;text-align:center">Nothing queued.</div>';
  _armUpdateBar();
}

function _armUpdateBar() {
  const bar = document.getElementById('armBar');
  if (!bar) return;
  const total = _assemblyQueue.length;
  const ticked = _assemblyQueue.filter(it => it._reviewed && _asmItemValid(it)).length;
  bar.textContent = total ? `${ticked} of ${total} ticked & ready to save` : '';
}

// Read one card's DOM back into its queue item (mark, qty, finish, parts).
function _armSyncCardToItem(qi) {
  const card = document.querySelector(`.arm-card[data-qi="${qi}"]`);
  if (!card) return;
  const item = _assemblyQueue[qi];
  if (!item) return;
  const ocr = item.ocr || (item.ocr = {});
  const markEl = card.querySelector('.arm-mark');
  if (markEl) ocr.assembly_mark = markEl.value.trim();
  const qtyEl = card.querySelector('.arm-qty');
  if (qtyEl) { const n = parseInt(qtyEl.value); ocr.quantity = isNaN(n) ? null : n; }
  const finEl = card.querySelector('.arm-finish');
  if (finEl) item._finishId = finEl.value || '';
  const parts = [];
  card.querySelectorAll('.arm-part-row').forEach(tr => {
    const row = {};
    tr.querySelectorAll('.arm-cell').forEach(inp => {
      const f = inp.dataset.f, v = inp.value.trim();
      if (v === '') row[f] = (f === 'part_mark' || f === 'profile' || f === 'material') ? '' : null;
      else if (f === 'part_mark' || f === 'profile' || f === 'material') row[f] = v;
      else { const nn = Number(v); row[f] = isNaN(nn) ? null : nn; }
    });
    parts.push(row);
  });
  if (parts.length) ocr.parts = parts;
}

function _armSyncAll() {
  for (let qi = 0; qi < _assemblyQueue.length; qi++) _armSyncCardToItem(qi);
}

function armToggleCollapse(qi) {
  const card = document.querySelector(`.arm-card[data-qi="${qi}"]`);
  if (!card) return;
  const item = _assemblyQueue[qi];
  if (!item) return;
  item._collapsed = !item._collapsed;
  const body = card.querySelector('.arm-card-body');
  const chev = card.querySelector('.arm-chev');
  if (body) body.style.display = item._collapsed ? 'none' : 'block';
  if (chev) chev.innerHTML = item._collapsed ? '&#9656;' : '&#9662;';
}

function armToggleReviewed(qi, checked) {
  if (_assemblyQueue[qi]) _assemblyQueue[qi]._reviewed = checked;
  _armUpdateBar();
}

function armSetFinish(qi, val) {
  if (_assemblyQueue[qi]) _assemblyQueue[qi]._finishId = val || '';
}

function armRemoveCard(qi) {
  _armSyncAll();
  _assemblyQueue.splice(qi, 1);
  if (!_assemblyQueue.length) { closeAssemblyReviewModal(); return; }
  renderAssemblyBatch();
}

function armAddRow(qi) {
  _armSyncCardToItem(qi);
  const item = _assemblyQueue[qi];
  if (!item) return;
  item.ocr = item.ocr || {};
  item.ocr.parts = item.ocr.parts || [];
  item.ocr.parts.push({ part_mark: '', quantity: 1, profile: '', length_mm: null, material: '', area_m2: null, weight_kg: null });
  const tb = document.getElementById(`armParts_${qi}`);
  if (tb) tb.innerHTML = _armPartsRowsHtml(item.ocr.parts, qi);
}

function armRemoveRow(qi, i) {
  _armSyncCardToItem(qi);
  const item = _assemblyQueue[qi];
  if (!item || !item.ocr) return;
  (item.ocr.parts || []).splice(i, 1);
  const tb = document.getElementById(`armParts_${qi}`);
  if (tb) tb.innerHTML = _armPartsRowsHtml(item.ocr.parts || [], qi);
}

// "Accept all — don't check": tick every readable, complete card and collapse
// them. Cards that failed OCR or are incomplete stay unticked and expanded.
function armAcceptAll() {
  _armSyncAll();
  let n = 0;
  for (const item of _assemblyQueue) {
    if (_asmItemValid(item)) { item._reviewed = true; item._collapsed = true; n++; }
    else { item._reviewed = false; item._collapsed = false; }
  }
  renderAssemblyBatch();
  if (n < _assemblyQueue.length) {
    toast(`Ticked ${n}. ${_assemblyQueue.length - n} still need attention (unreadable or incomplete).`, 'info');
  }
}

// Save every ticked, valid card in one pass. Saved cards leave the queue;
// unticked/incomplete ones stay so you can finish them.
async function armSaveAll() {
  if (!currentJob) { toast('No job selected.', 'error'); return; }
  _armSyncAll();

  const targets = [];
  for (let qi = 0; qi < _assemblyQueue.length; qi++) {
    const item = _assemblyQueue[qi];
    if (item._reviewed && _asmItemValid(item)) targets.push(qi);
  }
  if (!targets.length) {
    toast('Tick "looks good" on the drawings to save — or hit "Accept all".', 'error');
    return;
  }

  const saveBtn = document.getElementById('armSaveBtn');
  if (saveBtn) { saveBtn.disabled = true; saveBtn.style.opacity = '.6'; }

  const savedIdx = [];
  let saved = 0;
  for (const qi of targets) {
    const item = _assemblyQueue[qi];
    const ocr = item.ocr || {};
    const mark = (ocr.assembly_mark || '').trim();
    const qty = parseInt(ocr.quantity);
    const finishServiceId = item._finishId ? parseInt(item._finishId) : null;
    const parts = _asmCleanParts(ocr);
    const w = _asmWeights(ocr);
    const totalAreaM2 = w.areaM2;      // NaN → stored null (weights print as — on the DN)
    const totalWeightKg = w.weightKg;  // per ONE assembly — drawing's printed total wins

    try {
      await postAssemblyCreate(item, mark, qty, finishServiceId, ocr.finish_label_raw ?? null, totalAreaM2, totalWeightKg, parts);
      saved++; savedIdx.push(qi);
    } catch (err) {
      if (err && err.body && err.body.error === 'duplicate_mark') {
        const existing = (_assembliesByJob[parseInt(currentJob.id)] || [])
          .find(a => (a.assembly_mark || '').toLowerCase() === mark.toLowerCase());
        const onBom = existing && asmBomQty(existing) > 0;
        const body = onBom
          ? `<strong style="color:var(--text)">"${escapeHtml(mark)}"</strong> already exists and has pieces on the BOM (which may already be at a supplier or despatched).<br><br>Replacing deletes the old assembly and its BOM row. Continue?`
          : `<strong style="color:var(--text)">"${escapeHtml(mark)}"</strong> already exists on this job.<br><br>Replacing will delete the old assembly. Continue?`;
        const proceed = await bamaConfirm({
          title: 'Assembly already exists',
          body,
          confirmText: 'Replace',
          icon: onBom ? '&#9888;' : '&#10068;',
          tone: onBom ? 'danger' : 'primary'
        });
        if (proceed) {
          try {
            const force = onBom ? '?force=1' : '';
            if (existing) await api.delete(`/api/job-assemblies/${existing.id}${force}`);
            await postAssemblyCreate(item, mark, qty, finishServiceId, ocr.finish_label_raw ?? null, totalAreaM2, totalWeightKg, parts);
            saved++; savedIdx.push(qi);
          } catch (replaceErr) {
            toast(`${mark}: replace failed — ${replaceErr.message}`, 'error');
          }
        }
      } else {
        toast(`${mark}: save failed — ${err.message}`, 'error');
      }
    }
  }

  if (saveBtn) { saveBtn.disabled = false; saveBtn.style.opacity = '1'; }

  // Drop saved cards (descending so indices stay valid).
  savedIdx.sort((a, b) => b - a).forEach(qi => _assemblyQueue.splice(qi, 1));

  await loadJobAssemblies(parseInt(currentJob.id));
  renderAssembly();

  if (!_assemblyQueue.length) {
    closeAssemblyReviewModal();
    toast(`Saved ${saved} assembl${saved === 1 ? 'y' : 'ies'}.`, 'success');
  } else {
    toast(`Saved ${saved}. ${_assemblyQueue.length} still queued (unticked or incomplete).`, saved ? 'success' : 'info');
    renderAssemblyBatch();
  }
}

// ── Per-ONE-assembly weight/area (DN unit-weight fix, 2026-08-06) ──
// JobAssemblies.total_weight_kg must be the weight of ONE assembly — every
// consumer (DN Unit Wt., fab-output kg, project tonnage, despatch %)
// multiplies it by quantity. Two OCR failure modes inflated it to the
// whole batch, which then got multiplied by qty AGAIN on the DN:
//   1. The Layout-1 summary table's FIRST row (the assembly itself,
//      e.g. RL1 | 26 | ...) misread as a part → Σ parts includes 26×.
//   2. Drawings whose parts list shows BATCH quantities (total pieces
//      for all N assemblies) rather than per-one counts.
// Deterministic guards, no AI arithmetic (two-engine principle):
//   - drop any "part" whose mark equals the assembly mark;
//   - the drawing's PRINTED "Totals for ONE assembly" figure
//     (ocr.total_weight_kg) is authoritative when present; Σ parts is
//     only the fallback when the drawing prints no total (Layout 2).
function _asmCleanParts(ocr) {
  const mark = String(ocr.assembly_mark || '').trim().toLowerCase();
  return (ocr.parts || []).filter(p => {
    if (!(p.part_mark || p.profile)) return false;
    const pm = String(p.part_mark || '').trim().toLowerCase();
    return !(mark && pm && pm === mark);   // assembly summary row leaked into parts
  });
}

function _asmWeights(ocr) {
  const parts   = _asmCleanParts(ocr);
  const sumWt   = parts.reduce((s, p) => s + ((Number(p.weight_kg) || 0) * (Number(p.quantity) || 1)), 0);
  const sumArea = parts.reduce((s, p) => s + ((Number(p.area_m2)  || 0) * (Number(p.quantity) || 1)), 0);
  const pWt   = Number(ocr.total_weight_kg);
  const pArea = Number(ocr.total_area_m2);
  const printedWt   = (ocr.total_weight_kg != null && isFinite(pWt)   && pWt   > 0) ? pWt   : null;
  const printedArea = (ocr.total_area_m2  != null && isFinite(pArea) && pArea > 0) ? pArea : null;
  const qty = parseInt(ocr.quantity) || 1;
  // Σ parts ≈ printed × qty ⇒ the parts list carries batch counts
  const batchSuspect = printedWt != null && qty > 1 && sumWt > 0 &&
    Math.abs(sumWt - printedWt * qty) / (printedWt * qty) < 0.05;
  const mismatch = !batchSuspect && printedWt != null && sumWt > 0 &&
    Math.abs(sumWt - printedWt) / printedWt > 0.05;
  return {
    weightKg: printedWt != null ? printedWt : (sumWt > 0 ? sumWt : NaN),
    areaM2:   printedArea != null ? printedArea : (sumArea > 0 ? sumArea : NaN),
    sumWt, printedWt, batchSuspect, mismatch
  };
}

async function postAssemblyCreate(item, mark, qty, finishServiceId, finishLabelRaw, totalAreaM2, totalWeightKg, parts) {
  return await api.post('/api/job-assemblies', {
    job_id:             parseInt(currentJob.id),
    assembly_mark:      mark,
    quantity:           qty,
    finish_service_id:  finishServiceId,
    finish_label_raw:   finishLabelRaw,
    total_area_m2:      isFinite(totalAreaM2) ? Number(totalAreaM2.toFixed(3)) : null,
    total_weight_kg:    isFinite(totalWeightKg) ? Number(totalWeightKg.toFixed(3)) : null,
    sharepoint_file_id: item.sharepoint.fileId,
    sharepoint_drive_id: item.sharepoint.driveId,
    sharepoint_web_url: item.sharepoint.webUrl,
    file_name:          item.sharepoint.fileName,
    parts:              parts.map((p, i) => ({
      part_mark: p.part_mark, quantity: p.quantity || 1, profile: p.profile,
      length_mm: p.length_mm, material: p.material,
      area_m2: p.area_m2, weight_kg: p.weight_kg
    }))
  });
}

async function deleteAssembly(id) {
  if (!id) return;
  const ok = await bamaConfirm({
    title: 'Delete assembly?',
    body: 'This removes the assembly and its parts. The PDF stays in SharePoint.',
    confirmText: 'Delete',
    icon: '&#128465;',
    tone: 'danger'
  });
  if (!ok) return;
  try {
    await api.delete(`/api/job-assemblies/${id}`);
    await loadJobAssemblies(parseInt(currentJob.id));
    renderAssembly();
    toast('Assembly deleted.', 'success');
  } catch (e) {
    if (e && e.body && e.body.error === 'fabricated_protected') {
      toast('Cannot delete — this assembly has been marked as fabricated. Roll back BOM first.', 'error');
    } else {
      toast(`Delete failed: ${e.message}`, 'error');
    }
  }
}

// Bulk delete — draftsman only, from the Assembly section's multi-select bar.
// Reuses DELETE /api/job-assemblies/:id per selected assembly. Fabricated
// assemblies are protected server-side (409 fabricated_protected) and are
// skipped with a count in the summary toast rather than aborting the batch.
async function bulkDeleteAssemblies(pool) {
  const selected = (pool || []).filter(a => _bulkSelected.has(a.id));
  if (!selected.length) return;
  const ok = await bamaConfirm({
    title: `Delete ${selected.length} assembl${selected.length > 1 ? 'ies' : 'y'}?`,
    body: 'This removes the selected assemblies and their parts. PDFs stay in SharePoint. Assemblies already marked as fabricated will be skipped (roll back BOM first).',
    confirmText: 'Delete',
    icon: '&#128465;',
    tone: 'danger'
  });
  if (!ok) return;
  setLoading(true);
  let deleted = 0, protectedCount = 0, failed = 0;
  for (const a of selected) {
    try {
      await api.delete(`/api/job-assemblies/${a.id}`);
      deleted++;
    } catch (e) {
      if (e && e.body && e.body.error === 'fabricated_protected') protectedCount++;
      else failed++;
    }
  }
  setLoading(false);
  _bulkSelected.clear();
  _bulkSelectMode = false;
  await loadJobAssemblies(parseInt(currentJob.id));
  renderAssembly();
  const bits = [`${deleted} deleted`];
  if (protectedCount) bits.push(`${protectedCount} skipped (fabricated — roll back BOM first)`);
  if (failed) bits.push(`${failed} failed`);
  toast(bits.join(' · '), failed ? 'error' : (protectedCount ? 'warn' : 'success'));
}

// ── Attach PDF to a manual-entry assembly ────────────────────────────────────
// Creates a hidden <input type=file> on demand, waits for the user to pick
// a PDF, uploads it to the job's Assembly folder in SharePoint, then calls
// PUT /api/job-assemblies/:id/attach-pdf to link it.
// The "Attach PDF" button is shown on any assembly card that has no webUrl.

let _attachPdfInput = null;

function triggerAttachPdf(assemblyId) {
  if (!currentJob || !currentJob.spFolderId) {
    toast('Job folder not available — try reloading.', 'error');
    return;
  }
  if (!_attachPdfInput) {
    _attachPdfInput = document.createElement('input');
    _attachPdfInput.type = 'file';
    _attachPdfInput.accept = '.pdf,.PDF';
    _attachPdfInput.style.display = 'none';
    document.body.appendChild(_attachPdfInput);
  }
  _attachPdfInput.onchange = () => {
    const file = _attachPdfInput.files[0];
    _attachPdfInput.value = '';
    if (file) attachPdfToAssembly(assemblyId, file);
  };
  _attachPdfInput.click();
}

async function attachPdfToAssembly(assemblyId, file) {
  toast('Uploading PDF…', 'info');
  try {
    const driveId = currentJob.spDriveId || BAMA_DRIVE_ID;
    const asmFolder = await getOrCreateSubfolder(currentJob.spFolderId, ELEMENT_FOLDERS.assembly, driveId);
    const arrayBuffer = await file.arrayBuffer();
    const uploaded = await uploadFileToFolder(asmFolder.id, file.name, arrayBuffer, file.type, driveId);

    await api.put(`/api/job-assemblies/${assemblyId}/attach-pdf`, {
      sharepoint_file_id:  uploaded.id,
      sharepoint_drive_id: uploaded.parentReference?.driveId || driveId,
      sharepoint_web_url:  uploaded.webUrl || null,
      file_name:           file.name
    });

    // Refresh the local cache so the card re-renders with the Open PDF button
    await loadJobAssemblies(parseInt(currentJob.id));
    renderAssembly();
    toast('PDF attached — lads can now open it from the card.', 'success');
  } catch (e) {
    toast(`Attach failed: ${e.message}`, 'error');
  }
}

async function loadWeldingMachinesIfNeeded() {
  if (_weldingMachines && _weldingMachines.length) return;
  try {
    _weldingMachines = await api.get('/api/welding-machines');
  } catch (e) {
    console.warn('Load welding machines failed:', e.message);
    _weldingMachines = [];
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// STAGE ACTION MODAL — staged partial fabrication (fab / weld / complete)
//
// One modal drives all three stages. openStageActionModal(stage, assemblyId,
// opts?) sets it up; the title, operator label, machine visibility and qty cap
// adapt to the stage. Draftsman mode makes operator + machine optional.
//
//   stage: 'fab' | 'weld' | 'complete'
//   opts.assembly   — pre-loaded assembly (kiosk, where _assembliesByJob is
//                     not populated for that job)
//   opts.onSuccess  — async callback after success (kiosk list refresh)
// ═══════════════════════════════════════════════════════════════════════════
let _saStage = null;
let _saAssembly = null;
let _saMax = 0;
let _saOnSuccess = null;
let _saRollback = false;   // true when the modal is undoing a stage

// Piece-count helpers (mirror the backend derivation).
function asmToFab(a)       { return Math.max(0, Number(a.quantity) - Number(a.qty_fabbed||0) - Number(a.qty_completed||0)); }
function asmReadyToWeld(a) { return Math.max(0, Number(a.qty_fabbed||0) - Number(a.qty_welded||0)); }
function asmBomQty(a)      { return Number(a.qty_welded||0) + Number(a.qty_completed||0); }
function asmIsTerminal(a)  { return asmBomQty(a) >= Number(a.quantity); }

// Human progress line, e.g. "2 to fab · 3 ready to weld · 4 on BOM"
function asmProgressLine(a) {
  const q = Number(a.quantity);
  const parts = [];
  const toFab = asmToFab(a), rtw = asmReadyToWeld(a), bom = asmBomQty(a);
  parts.push(`${q} off`);
  if (toFab > 0) parts.push(`${toFab} to fab`);
  if (rtw > 0)   parts.push(`${rtw} ready to weld`);
  if (bom > 0)   parts.push(`${bom} on BOM`);
  return parts.join(' · ');
}

// Open the modal in ROLLBACK mode — undo N pieces of a stage (draftsman).
// Caps mirror the backend: un-fab ≤ fabbed-not-welded; un-weld/un-complete ≤
// pieces still on an open (no-DN) BOM row.
async function openRollbackModal(stage, assemblyId, opts) {
  if (!assemblyId || !stage) return;
  opts = opts || {};
  let assembly = opts.assembly;
  if (!assembly) {
    const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
    assembly = (_assembliesByJob[jobId] || []).find(a => a.id === assemblyId);
  }
  if (!assembly) { toast('Assembly not found — please reload.', 'error'); return; }

  // Cap per stage. For weld/complete the true cap also depends on how many
  // pieces are still on an open BOM row; the client can't see BOM rows here,
  // so we cap by the count and let the server enforce the DN guard (it returns
  // a clear message if some are already on a DN).
  let max;
  if (stage === 'fab')       max = Math.max(0, Number(assembly.qty_fabbed||0) - Number(assembly.qty_welded||0));
  else if (stage === 'weld') max = Number(assembly.qty_welded||0);
  else                       max = Number(assembly.qty_completed||0);
  if (max <= 0) {
    toast(stage === 'fab'
      ? 'Nothing to un-fab (welded pieces must be un-welded first).'
      : `No ${stage === 'weld' ? 'welded' : 'completed'} pieces to undo.`, 'info');
    return;
  }

  _saStage = stage;
  _saAssembly = assembly;
  _saMax = max;
  _saRollback = true;
  _saOnSuccess = typeof opts.onSuccess === 'function' ? opts.onSuccess : null;

  const titleMap = { fab: 'Undo — send back to raw', weld: 'Undo weld — back to “ready to weld”', complete: 'Undo complete — back to raw' };
  document.getElementById('saTitle').textContent = titleMap[stage];
  document.getElementById('saMark').textContent = assembly.assembly_mark;
  document.getElementById('saProgress').textContent = asmProgressLine(assembly);

  const finishEl = document.getElementById('saFinish');
  if (assembly.finish_name) { finishEl.textContent = assembly.finish_name; finishEl.style.display = ''; }
  else { finishEl.style.display = 'none'; }

  // Qty stepper — default all
  const qtyEl = document.getElementById('saQty');
  qtyEl.max = max;
  qtyEl.value = max;
  document.getElementById('saMaxHint').textContent = `of ${max}`;
  document.getElementById('saQtyLabel').textContent =
    stage === 'fab' ? 'HOW MANY TO UN-FAB?' : stage === 'weld' ? 'HOW MANY TO UN-WELD?' : 'HOW MANY TO UN-COMPLETE?';

  // Rollback doesn't capture operator/machine — hide both.
  document.getElementById('saOperatorWrap').style.display = 'none';
  document.getElementById('saMachineWrap').style.display = 'none';

  // Danger-styled confirm button.
  const btn = document.getElementById('saConfirmBtn');
  btn.textContent = 'Roll back';
  btn.style.background = 'var(--red, #ff4444)';
  btn.style.borderColor = 'var(--red, #ff4444)';

  saClampQty();
  updateStageConfirmState();
  document.getElementById('stageActionModal').classList.add('active');
}

async function openStageActionModal(stage, assemblyId, opts) {
  if (!assemblyId || !stage) return;
  opts = opts || {};
  let assembly = opts.assembly;
  if (!assembly) {
    const jobId = currentJob?.id ? parseInt(currentJob.id) : null;
    assembly = (_assembliesByJob[jobId] || []).find(a => a.id === assemblyId);
  }
  if (!assembly) { toast('Assembly not found — please reload.', 'error'); return; }

  // Cap per stage
  let max;
  if (stage === 'fab')      max = asmToFab(assembly);
  else if (stage === 'weld') max = asmReadyToWeld(assembly);
  else                       max = asmToFab(assembly); // complete = raw remaining
  if (max <= 0) {
    toast(stage === 'weld' ? 'Nothing fabricated is waiting to be welded.' : 'No pieces left for that action.', 'info');
    return;
  }

  _saStage = stage;
  _saAssembly = assembly;
  _saMax = max;
  _saRollback = false;
  _saOnSuccess = typeof opts.onSuccess === 'function' ? opts.onSuccess : null;

  const titleMap = { fab: 'Mark fabricated', weld: 'Mark welded', complete: 'Mark complete' };
  const opLabelMap = { fab: 'FABRICATOR', weld: 'WELDER', complete: 'WELDER' };
  document.getElementById('saTitle').textContent = titleMap[stage];
  document.getElementById('saMark').textContent = assembly.assembly_mark;
  document.getElementById('saProgress').textContent = asmProgressLine(assembly);

  const finishEl = document.getElementById('saFinish');
  if (assembly.finish_name) { finishEl.textContent = assembly.finish_name; finishEl.style.display = ''; }
  else { finishEl.style.display = 'none'; }

  // Restore normal (non-rollback) button + operator visibility in case a
  // rollback modal was the previous occupant of this shared DOM.
  const confBtn = document.getElementById('saConfirmBtn');
  confBtn.textContent = 'Confirm';
  confBtn.style.background = '';
  confBtn.style.borderColor = '';
  document.getElementById('saOperatorWrap').style.display = '';

  // Qty stepper — default all-remaining
  const qtyEl = document.getElementById('saQty');
  qtyEl.max = max;
  qtyEl.value = max;
  document.getElementById('saMaxHint').textContent = `of ${max}`;
  document.getElementById('saQtyLabel').textContent =
    stage === 'fab' ? 'HOW MANY TO FABRICATE?' : stage === 'weld' ? 'HOW MANY TO WELD?' : 'HOW MANY TO COMPLETE?';

  // Operator dropdown. Fab → fabricators; weld/complete → welders. Lists all
  // bookable shop-floor staff (workshop + director/PM — see bookableShopStaff)
  // for every stage (the shop knows who fabs vs welds; no separate flag yet).
  const opWrap = document.getElementById('saOperatorWrap');
  const opLabel = document.getElementById('saOperatorLabel');
  const opSel = document.getElementById('saOperator');
  opLabel.textContent = opLabelMap[stage] + (isDraftsman ? ' (optional)' : '');
  opSel.innerHTML = `<option value="">${isDraftsman ? '— none —' : 'Select…'}</option>` + shopStaffOptionsHtml();

  // Machine dropdown — hidden for fab, shown for weld/complete
  const machWrap = document.getElementById('saMachineWrap');
  if (stage === 'fab') {
    machWrap.style.display = 'none';
  } else {
    machWrap.style.display = '';
    await loadWeldingMachinesIfNeeded();
    const machSel = document.getElementById('saMachine');
    machSel.querySelector && (machSel.innerHTML = `<option value="">${isDraftsman ? '— none —' : 'Select…'}</option>`);
    for (const m of (_weldingMachines || [])) {
      if (m.is_active === false) continue;
      machSel.innerHTML += `<option value="${m.id}">${escapeHtml(m.machine_name || ('Machine #' + m.id))}</option>`;
    }
    document.querySelector('#saMachineWrap .field-label').textContent = 'WELDING MACHINE' + (isDraftsman ? ' (optional)' : '');
  }

  saClampQty();
  updateStageConfirmState();
  opSel.onchange = updateStageConfirmState;
  const machSel2 = document.getElementById('saMachine');
  if (machSel2) machSel2.onchange = updateStageConfirmState;

  document.getElementById('stageActionModal').classList.add('active');
}

function saStep(delta) {
  const el = document.getElementById('saQty');
  el.value = (parseInt(el.value) || 0) + delta;
  saClampQty();
}
function saAllRemaining() {
  document.getElementById('saQty').value = _saMax;
  saClampQty();
}
function saClampQty() {
  const el = document.getElementById('saQty');
  let v = parseInt(el.value);
  if (isNaN(v)) v = 1;
  if (v < 1) v = 1;
  if (v > _saMax) v = _saMax;
  el.value = v;
  updateStageConfirmState();
}
function updateStageConfirmState() {
  const btn = document.getElementById('saConfirmBtn');
  const qty = parseInt(document.getElementById('saQty').value) || 0;
  // In workshop/kiosk mode, weld & complete require operator + machine.
  // In draftsman mode everything but qty is optional.
  let ready = qty >= 1 && qty <= _saMax;
  if (ready && !_saRollback && !isDraftsman && (_saStage === 'weld' || _saStage === 'complete')) {
    const op = document.getElementById('saOperator').value;
    const mc = document.getElementById('saMachine').value;
    ready = !!op && !!mc;
  }
  btn.disabled = !ready;
  btn.style.opacity = ready ? '1' : '.4';
  btn.style.cursor = ready ? 'pointer' : 'not-allowed';
}
function closeStageActionModal() {
  document.getElementById('stageActionModal').classList.remove('active');
  _saStage = null; _saAssembly = null; _saMax = 0; _saOnSuccess = null; _saRollback = false;
}

async function confirmStageAction() {
  const stage = _saStage, assembly = _saAssembly;
  if (!stage || !assembly) return;
  const qty = parseInt(document.getElementById('saQty').value) || 0;
  if (qty < 1 || qty > _saMax) return;

  const opSel = document.getElementById('saOperator');
  const opId = opSel.value ? parseInt(opSel.value) : null;
  const opName = opSel.selectedOptions[0]?.dataset?.name || null;
  const machSel = document.getElementById('saMachine');
  const machId = (stage !== 'fab' && machSel && machSel.value) ? parseInt(machSel.value) : null;

  const btn = document.getElementById('saConfirmBtn');
  btn.disabled = true; btn.style.opacity = '.5';
  const cb = _saOnSuccess;

  // Rollback path — undo N pieces of the stage.
  if (_saRollback) {
    try {
      await api.put(`/api/job-assemblies/${assembly.id}/rollback`, { stage, qty });
      closeStageActionModal();
      const verb = stage === 'fab' ? 'un-fabbed' : stage === 'weld' ? 'un-welded' : 'un-completed';
      toast(`${qty} piece${qty > 1 ? 's' : ''} ${verb}.`, 'success');
      if (cb) { try { await cb(); } catch (e) { console.warn('post-rollback callback failed:', e); } }
      if (currentJob?.id) {
        await loadJobAssemblies(parseInt(currentJob.id));
        renderAssembly();
      }
    } catch (e) {
      toast(`Failed: ${e.body?.message || e.message}`, 'error');
      btn.disabled = false; btn.style.opacity = '1';
    }
    return;
  }

  // Build the body per stage
  let body, path;
  if (stage === 'fab') {
    path = `/api/job-assemblies/${assembly.id}/fab`;
    body = { qty, operator_id: opId, operator_name: opName };
  } else if (stage === 'weld') {
    path = `/api/job-assemblies/${assembly.id}/weld`;
    body = { qty, welder_id: opId, welder_name: opName, welding_machine_id: machId };
  } else {
    path = `/api/job-assemblies/${assembly.id}/complete`;
    body = { qty, operator_id: opId, operator_name: opName, welding_machine_id: machId };
  }

  try {
    await api.put(path, body);
    closeStageActionModal();
    const verb = stage === 'fab' ? 'fabricated' : stage === 'weld' ? 'welded' : 'complete';
    toast(`${qty} piece${qty > 1 ? 's' : ''} marked ${verb}.`, 'success');
    if (cb) { try { await cb(); } catch (e) { console.warn('post-stage callback failed:', e); } }
    if (currentJob?.id) {
      await loadJobAssemblies(parseInt(currentJob.id));
      renderAssembly();
    }
  } catch (e) {
    toast(`Failed: ${e.message}`, 'error');
    btn.disabled = false; btn.style.opacity = '1';
  }
}

// Back-compat shims for any caller still using the old names (kiosk was
// updated to openStageActionModal; these forward "mark fabricated" to the
// weld stage — welding is the terminal step in the fab→weld path).
async function openMarkFabricatedModal(assemblyId, opts) {
  return openStageActionModal('complete', assemblyId, opts);
}
function closeMarkFabricatedModal() { return closeStageActionModal(); }

// ═══════════════════════════════════════════════════════════════════════════
// BULK STAGE MARKING — tick many assemblies, mark fab/weld/complete in one go.
//
// Selection state is a Set of assembly ids, plus a flag for which surface
// (projects vs kiosk) is in select mode so the two don't collide. The bulk
// modal shows a per-assembly qty box pre-filled to that stage's remaining
// (editable), skipping assemblies with nothing left for the chosen stage.
// One optional operator + machine is applied to the whole batch. Confirm runs
// the per-assembly calls sequentially with a progress toast.
// ═══════════════════════════════════════════════════════════════════════════
let _bulkSelectMode = false;         // projects.html Assembly section
let _bulkSelected = new Set();       // assembly ids
let _bulkStage = null;               // 'fab' | 'weld' | 'complete'
let _bulkRows = [];                  // [{assembly, max, qty}]
let _bulkSurface = 'projects';       // 'projects' | 'kiosk' — which refresh path

// Remaining pieces available for a given stage on an assembly.
function stageRemaining(a, stage) {
  if (stage === 'fab')      return asmToFab(a);
  if (stage === 'weld')     return asmReadyToWeld(a);
  return asmToFab(a); // complete = raw remaining
}

// projects.html: toggle select mode on the Assembly section.
function toggleBulkSelect() {
  _bulkSelectMode = !_bulkSelectMode;
  if (!_bulkSelectMode) _bulkSelected.clear();
  renderAssembly();
}

function toggleBulkPick(id) {
  id = parseInt(id);
  if (_bulkSelected.has(id)) _bulkSelected.delete(id);
  else _bulkSelected.add(id);
  // Re-render just enough — cheap to re-render the whole section.
  if (_bulkSurface === 'kiosk') renderKioskFabrication();
  else renderAssembly();
}

function bulkSelectAllVisible(ids) {
  const arr = (ids || []).map(Number);
  const allPicked = arr.length && arr.every(i => _bulkSelected.has(i));
  if (allPicked) arr.forEach(i => _bulkSelected.delete(i));
  else arr.forEach(i => _bulkSelected.add(i));
  if (_bulkSurface === 'kiosk') renderKioskFabrication();
  else renderAssembly();
}

// Open the bulk modal for a stage. `pool` is the array of candidate assemblies
// (projects: _assembliesByJob[job]; kiosk: _kioskFabData). surface controls
// the refresh path after confirm.
async function openBulkStageModal(stage, pool, surface) {
  _bulkStage = stage;
  _bulkSurface = surface || 'projects';
  const selected = (pool || []).filter(a => _bulkSelected.has(a.id));
  // Only keep assemblies with something to do for this stage.
  _bulkRows = selected
    .map(a => ({ assembly: a, max: stageRemaining(a, stage), qty: stageRemaining(a, stage) }))
    .filter(r => r.max > 0);

  if (_bulkRows.length === 0) {
    toast(stage === 'weld'
      ? 'None of the selected assemblies have fabricated pieces waiting to weld.'
      : 'None of the selected assemblies have pieces left for that action.', 'info');
    return;
  }

  const titleMap = { fab: 'Mark fabricated — bulk', weld: 'Mark welded — bulk', complete: 'Mark complete — bulk' };
  const opLabelMap = { fab: 'FABRICATOR', weld: 'WELDER', complete: 'WELDER' };
  document.getElementById('bsTitle').textContent = titleMap[stage];
  document.getElementById('bsSubtitle').textContent =
    `${_bulkRows.length} assembl${_bulkRows.length > 1 ? 'ies' : 'y'} · qty pre-filled to all remaining — edit any box to do a partial.`;
  document.getElementById('bsOperatorLabel').textContent = opLabelMap[stage];

  // Operator dropdown (optional in bulk regardless of surface)
  const opSel = document.getElementById('bsOperator');
  opSel.innerHTML = '<option value="">— who did it? —</option>';
  opSel.innerHTML += shopStaffOptionsHtml();
  // Remember-last: attribution feeds the Fab output report, so the picker is
  // required — but pre-filled from last time, so it costs zero taps normally.
  const lastOp = localStorage.getItem('bama_last_operator');
  if (lastOp && [...opSel.options].some(o => o.value === lastOp)) opSel.value = lastOp;

  // Machine dropdown — hidden for fab
  const machWrap = document.getElementById('bsMachineWrap');
  if (stage === 'fab') {
    machWrap.style.display = 'none';
  } else {
    machWrap.style.display = '';
    await loadWeldingMachinesIfNeeded();
    const machSel = document.getElementById('bsMachine');
    machSel.innerHTML = '<option value="">— none —</option>';
    for (const m of (_weldingMachines || [])) {
      if (m.is_active === false) continue;
      machSel.innerHTML += `<option value="${m.id}">${escapeHtml(m.machine_name || ('Machine #' + m.id))}</option>`;
    }
  }

  renderBulkRows();
  document.getElementById('bulkStageModal').classList.add('active');
}

function renderBulkRows() {
  const list = document.getElementById('bsList');
  let html = '';
  for (let i = 0; i < _bulkRows.length; i++) {
    const r = _bulkRows[i];
    const a = r.assembly;
    html += `<div style="display:flex;align-items:center;gap:10px;background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:8px 12px">
      <span style="font-family:var(--font-mono);font-weight:700;color:var(--accent);min-width:50px">${escapeHtml(a.assembly_mark)}</span>
      <span style="font-size:12px;color:var(--muted);flex:1">${Number(a.quantity)} off · ${r.max} available</span>
      <button class="btn btn-ghost" style="padding:4px 10px;font-size:15px;line-height:1" onclick="bulkRowStep(${i},-1)">&minus;</button>
      <input type="number" class="field-input" min="1" max="${r.max}" value="${r.qty}"
             style="text-align:center;font-weight:700;max-width:70px" oninput="bulkRowSet(${i},this.value)">
      <button class="btn btn-ghost" style="padding:4px 10px;font-size:15px;line-height:1" onclick="bulkRowStep(${i},1)">&plus;</button>
    </div>`;
  }
  list.innerHTML = html;
  updateBulkTotals();
}

function bulkRowStep(i, d) {
  const r = _bulkRows[i];
  r.qty = Math.min(r.max, Math.max(1, (r.qty || 0) + d));
  renderBulkRows();
}
function bulkRowSet(i, v) {
  const r = _bulkRows[i];
  let n = parseInt(v);
  if (isNaN(n)) n = 1;
  r.qty = Math.min(r.max, Math.max(1, n));
  updateBulkTotals();
}
function updateBulkTotals() {
  const pieces = _bulkRows.reduce((s, r) => s + (r.qty || 0), 0);
  const verb = _bulkStage === 'fab' ? 'fabricate' : _bulkStage === 'weld' ? 'weld' : 'complete';
  document.getElementById('bsTotals').textContent =
    `Will ${verb} ${pieces} piece${pieces !== 1 ? 's' : ''} across ${_bulkRows.length} assembl${_bulkRows.length > 1 ? 'ies' : 'y'}.`;
}
function closeBulkStageModal() {
  document.getElementById('bulkStageModal').classList.remove('active');
  _bulkStage = null;
  _bulkRows = [];
}

async function confirmBulkStage() {
  const stage = _bulkStage;
  if (!stage || !_bulkRows.length) return;
  const rows = _bulkRows.slice();
  const pieces = rows.reduce((s, r) => s + (r.qty || 0), 0);
  const verb = stage === 'fab' ? 'fabricated' : stage === 'weld' ? 'welded' : 'complete';

  // Confirmation guard (styled) — "you selected N assemblies to mark …"
  const iconMap = { fab: '&#128296;', weld: '&#128293;', complete: '&#10003;' };
  const ok = await bamaConfirm({
    title: `Mark ${verb} — ${rows.length} assembl${rows.length > 1 ? 'ies' : 'y'}`,
    body: `You're about to mark <strong style="color:var(--text)">${pieces} piece${pieces !== 1 ? 's' : ''}</strong> as <strong style="color:var(--text)">${verb}</strong> across <strong style="color:var(--text)">${rows.length}</strong> assembl${rows.length > 1 ? 'ies' : 'y'}.<br><br>This can't be undone from here.`,
    confirmText: `Yes, mark ${verb}`,
    icon: iconMap[stage] || '&#10003;'
  });
  if (!ok) return;

  const opSel = document.getElementById('bsOperator');
  if (!opSel.value) {
    toast(`Pick who ${stage === 'fab' ? 'fabricated' : 'welded'} these — it feeds the Fab output report`, 'error');
    opSel.focus();
    const btn0 = document.getElementById('bsConfirmBtn');
    btn0.disabled = false; btn0.style.opacity = '1';
    return;
  }
  localStorage.setItem('bama_last_operator', opSel.value);
  const opId = opSel.value ? parseInt(opSel.value) : null;
  const opName = opSel.selectedOptions[0]?.dataset?.name || null;
  const machSel = document.getElementById('bsMachine');
  const machId = (stage !== 'fab' && machSel && machSel.value) ? parseInt(machSel.value) : null;

  const btn = document.getElementById('bsConfirmBtn');
  btn.disabled = true; btn.style.opacity = '.5';

  let done = 0, failed = 0;
  for (const r of rows) {
    const id = r.assembly.id;
    let path, body;
    if (stage === 'fab') { path = `/api/job-assemblies/${id}/fab`; body = { qty: r.qty, operator_id: opId, operator_name: opName }; }
    else if (stage === 'weld') { path = `/api/job-assemblies/${id}/weld`; body = { qty: r.qty, welder_id: opId, welder_name: opName, welding_machine_id: machId }; }
    else { path = `/api/job-assemblies/${id}/complete`; body = { qty: r.qty, operator_id: opId, operator_name: opName, welding_machine_id: machId }; }
    try { await api.put(path, body); done++; }
    catch (e) { failed++; console.warn(`bulk ${stage} failed for ${r.assembly.assembly_mark}:`, e.message); }
  }

  closeBulkStageModal();
  _bulkSelected.clear();
  _bulkSelectMode = false;
  toast(failed
    ? `${done} done, ${failed} failed — reloading.`
    : `${done} assembl${done > 1 ? 'ies' : 'y'} marked ${verb}.`, failed ? 'error' : 'success');

  // Refresh the right surface
  if (_bulkSurface === 'kiosk') {
    await loadKioskFabrication();
  } else if (currentJob?.id) {
    await loadJobAssemblies(parseInt(currentJob.id));
    renderAssembly();
  }
}

// ═══════════════════════════════════════════
// SITE INSTALLATION: CLOSE JOB
// ═══════════════════════════════════════════
function openCloseJobModal() {
  if (!currentJob || !currentProject) return;
  _pendingCloseJob = currentJob;
  document.getElementById('closeJobMessage').textContent = `This will mark site installation as complete and close the job "${currentJob.name}". Notifications will be sent.`;

  const sel = document.getElementById('closeJobPerson');
  sel.innerHTML = '<option value="">Select your name...</option>';
  (state.timesheetData.employees || []).filter(e => e.active !== false).forEach(e => {
    sel.innerHTML += `<option value="${e.name}">${e.name}</option>`;
  });
  sel.onchange = () => {
    const ready = !!sel.value;
    const btn = document.getElementById('closeJobConfirmBtn');
    btn.disabled = !ready; btn.style.opacity = ready ? '1' : '.4'; btn.style.cursor = ready ? 'pointer' : 'not-allowed';
  };

  const btn = document.getElementById('closeJobConfirmBtn');
  btn.disabled = true; btn.style.opacity = '.4'; btn.style.cursor = 'not-allowed';

  document.getElementById('closeJobModal').classList.add('active');
}

function closeCloseJobModal() {
  document.getElementById('closeJobModal').classList.remove('active');
  _pendingCloseJob = null;
}

async function confirmCloseJob() {
  if (!_pendingCloseJob || !currentJob || !currentProject) return;
  const person = document.getElementById('closeJobPerson').value;
  if (!person) return;

  // Guard: all BOM items must be 'despatched' before the job can close.
  // Reads from the SQL-backed _bomItemsByJob cache (populated by
  // loadJobBomItems in openJobDetail).
  // A job can close once all BOM items are either:
  //   - 'on_site'    — shipped to site via SDN (typical end state)
  //   - 'despatched' — shipped direct from supplier without an SDN
  // Both count as "done".
  const jobId = parseInt(currentJob.id);
  const items = (jobId && _bomItemsByJob[jobId]) || [];
  if (items.length > 0) {
    const notDone = items.filter(i => i.status !== 'on_site' && i.status !== 'despatched');
    if (notDone.length > 0) {
      const pending    = notDone.filter(i => i.status === 'pending').length;
      const atSupplier = notDone.filter(i => i.status === 'at_supplier').length;
      const ready      = notDone.filter(i => i.status === 'ready_for_despatch').length;
      let detail = `${notDone.length} BOM item${notDone.length > 1 ? 's' : ''} not yet delivered:`;
      if (pending)    detail += `\n• ${pending} pending (need a DN to a supplier)`;
      if (atSupplier) detail += `\n• ${atSupplier} at supplier (still being processed)`;
      if (ready)      detail += `\n• ${ready} ready for despatch (generate a Site DN)`;
      toast(detail, 'error');
      return;
    }
  }

  const job = _pendingCloseJob;
  job.site.completedAt = new Date().toISOString();
  job.site.completedBy = person;
  job.status = 'closed';
  job.closedAt = new Date().toISOString();
  job.closedBy = person;

  // Add completion note to local state (will be persisted via API below)
  if (!job.site.notes) job.site.notes = [];
  const closingNote = {
    type: 'workshop', author: person,
    text: `🏁 Site installation complete. Job closed.`,
    timestamp: new Date().toISOString()
  };

  try {
    setLoading(true);
    const jobIdInt = parseInt(job.id);

    // Persist site completion + closing note to SQL
    await api.put(`/api/drawing-elements/${jobIdInt}/site-complete`, { completedBy: person });
    try {
      const saved = await api.post(`/api/drawing-elements/${jobIdInt}/note`, {
        noteContext: 'site', noteType: 'workshop', author: person,
        text: closingNote.text
      });
      closingNote.id = saved.id;
    } catch (_) {}
    job.site.notes.push(closingNote);

    // Update DrawingJobs.is_complete in SQL
    try {
      await api.put(`/api/drawings/${encodeURIComponent(job.id)}`, {
        is_complete:  true,
        completed_by: person
      });
    } catch (sqlErr) {
      console.warn('Close job SQL mirror failed:', sqlErr.message);
      toast('Job closed locally; backend sync failed (will retry on reload).', 'error');
    }

    closeCloseJobModal();
    toast(`Job "${job.name}" closed`, 'success');

    // Re-render
    renderAllElements();
    openJobDetail(currentProject.id, job.id);

    // Send emails
    await sendJobClosedEmail(job, person);
  } catch (e) { toast('Save failed: ' + e.message, 'error'); }
  finally { setLoading(false); }
}

async function sendJobClosedEmail(job, person) {
  const settings = state.timesheetData.settings || {};
  const draftsmanEmail = settings.draftsmanEmail || 'daniel@bamafabrication.co.uk';
  const siteEmailList = settings.siteCompletionEmails || '';
  const recipients = [draftsmanEmail];
  if (siteEmailList) {
    siteEmailList.split(',').map(e => e.trim()).filter(Boolean).forEach(e => {
      if (!recipients.includes(e)) recipients.push(e);
    });
  }
  // Always include daniel
  if (!recipients.includes('daniel@bamafabrication.co.uk')) recipients.push('daniel@bamafabrication.co.uk');

  const proj = currentProject;
  try {
    const token = await getToken();
    await fetch('https://graph.microsoft.com/v1.0/me/sendMail', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ message: {
        subject: `Job Closed — ${job.name} (${proj?.id})`,
        body: { contentType: 'HTML', content: `
          <h2 style="color:#ff6b00;font-family:sans-serif">BAMA FABRICATION</h2>
          <h3 style="font-family:sans-serif">Job Completed & Closed</h3>
          <table style="font-family:sans-serif;font-size:13px">
            <tr><td style="padding:6px 16px 6px 0;color:#888">Job</td><td><b>${job.name}</b></td></tr>
            <tr><td style="padding:6px 16px 6px 0;color:#888">Project</td><td>${proj?.id} — ${proj?.name}</td></tr>
            <tr><td style="padding:6px 16px 6px 0;color:#888">Closed by</td><td>${person}</td></tr>
            <tr><td style="padding:6px 16px 6px 0;color:#888">Date/Time</td><td>${new Date().toLocaleString('en-GB')}</td></tr>
          </table>
          <p style="margin-top:16px;font-family:sans-serif;font-size:13px;padding:12px;border-radius:8px;background:#e8fae8;color:#166534">
            🏁 Site installation is complete. This job has been closed.
          </p>
          <p style="font-family:sans-serif;font-size:11px;color:#aaa;margin-top:12px"><a href="https://proud-dune-0dee63110.2.azurestaticapps.net" style="color:#ff6b00">Open BAMA Workshop</a></p>
        `},
        toRecipients: recipients.map(e => ({ emailAddress: { address: e } }))
      }, saveToSentItems: false })
    });
  } catch (e) { console.warn('Job closed email failed:', e.message); }
}

// ═══════════════════════════════════════════
// DRAFTSMAN LOGIN / LOGOUT (Per-User)
// ═══════════════════════════════════════════
function openDraftsmanLogin() {
  _pendingDraftsmanUser = null;
  const grid = document.getElementById('draftsmanEmpGrid');
  if (!grid) return;

  const empList = (state.timesheetData.employees || []).filter(e => e.active !== false);
  if (!empList.length) {
    grid.innerHTML = '<div class="empty-state" style="padding:20px">No employees set up yet.</div>';
  } else {
    grid.innerHTML = empList.map(emp => {
      const ini = (emp.name || '').split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
      const col = empColor(emp.name);
      return `
        <div class="emp-btn" onclick="selectDraftsmanUser('${emp.name.replace(/'/g, "\\'")}')" style="padding:18px 12px 14px">
          <div class="emp-avatar" style="width:42px;height:42px;font-size:17px;background:linear-gradient(135deg,${col},#3e1a00)">${ini}</div>
          <div class="emp-name" style="font-size:12px">${emp.name}</div>
        </div>
      `;
    }).join('');
  }

  document.getElementById('draftsmanLoginModal').classList.add('active');
}

function closeDraftsmanLogin() {
  document.getElementById('draftsmanLoginModal').classList.remove('active');
}

function selectDraftsmanUser(name) {
  const emp = (state.timesheetData.employees || []).find(e => e.name === name);
  if (!emp) return;

  if (!emp.hasPin) {
    toast('No PIN set for this user. Set one in Manager → Staff first.', 'error');
    return;
  }

  _pendingDraftsmanUser = name;
  closeDraftsmanLogin();

  const ini = name.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
  const col = empColor(name);

  const avatar = document.getElementById('draftPinAvatar');
  if (avatar) {
    avatar.innerHTML = ini;
    avatar.style.background = `linear-gradient(135deg,${col},#3e1a00)`;
  }
  const nameEl = document.getElementById('draftPinName');
  if (nameEl) nameEl.textContent = name;

  document.getElementById('draftsmanPinInput').value = '';
  document.getElementById('draftsmanPinError').textContent = '';
  document.getElementById('draftsmanPinModal').classList.add('active');
  setTimeout(() => document.getElementById('draftsmanPinInput').focus(), 100);
}

function closeDraftsmanPinModal() {
  document.getElementById('draftsmanPinModal').classList.remove('active');
}

async function checkDraftsmanPin() {
  const pin = document.getElementById('draftsmanPinInput').value;
  const emp = (state.timesheetData.employees || []).find(e => e.name === _pendingDraftsmanUser);

  if (!emp || !emp.hasPin) {
    document.getElementById('draftsmanPinError').textContent = 'No PIN set for this user';
    return;
  }

  let result;
  try {
    result = await api.post('/api/auth/verify-pin', { employee_id: emp.id, pin });
  } catch (err) {
    document.getElementById('draftsmanPinError').textContent = 'Verification failed — try again';
    return;
  }

  if (!result || !result.valid) {
    document.getElementById('draftsmanPinError').textContent = (result && result.reason) || 'Incorrect PIN';
    document.getElementById('draftsmanPinInput').value = '';
    return;
  }

  // PIN correct — check draftsman permission
  const perms = getUserPermissions(_pendingDraftsmanUser);
  if (!perms || !perms.draftsmanMode) {
    document.getElementById('draftsmanPinError').textContent = 'You do not have draftsman access. Contact an admin.';
    document.getElementById('draftsmanPinInput').value = '';
    return;
  }

  // Authorised — enter draftsman mode
  isDraftsman = true;
  _currentDraftsmanName = _pendingDraftsmanUser;
  // Persist in sessionStorage so the mode survives a page refresh
  // (per user's PC, tab-lifetime is acceptable safety boundary).
  try { sessionStorage.setItem('bama_draftsman', '1'); sessionStorage.setItem('bama_draftsman_name', _pendingDraftsmanUser); } catch (_) {}
  closeDraftsmanPinModal();
  toast(`Draftsman mode active — ${_pendingDraftsmanUser}`, 'success');
  _pendingDraftsmanUser = null;

  // Update UI
  const badge = document.getElementById('draftsmanBadge');
  const loginBtn = document.getElementById('draftsmanLoginBtn');
  if (badge) badge.style.display = 'flex';
  if (loginBtn) loginBtn.style.display = 'none';

  // Re-render current view
  if (currentJob) {
    document.getElementById('jobDraftsmanBar').style.display = 'flex';
    renderAllElements();
  } else if (currentProject) {
    document.getElementById('draftsmanBar').style.display = 'flex';
    renderJobsList(currentProject.id);
  } else {
    renderProjectTiles();
  }
}

function logoutDraftsman() {
  isDraftsman = false;
  _currentDraftsmanName = null;
  try { sessionStorage.removeItem('bama_draftsman'); sessionStorage.removeItem('bama_draftsman_name'); } catch (_) {}
  const badge = document.getElementById('draftsmanBadge');
  const loginBtn = document.getElementById('draftsmanLoginBtn');
  if (badge) badge.style.display = 'none';
  if (loginBtn) loginBtn.style.display = '';

  const bar = document.getElementById('draftsmanBar');
  if (bar) bar.style.display = 'none';
  const jobBar = document.getElementById('jobDraftsmanBar');
  if (jobBar) jobBar.style.display = 'none';

  toast('Draftsman mode exited', 'info');

  // Re-render to hide edit buttons
  if (currentJob) {
    renderAllElements();
  } else if (currentProject) {
    renderJobsList(currentProject.id);
  } else {
    renderProjectTiles();
  }
}

// ═══════════════════════════════════════════
// USER ACCESS TAB
// ═══════════════════════════════════════════
function renderUserAccessTab() {
  // Load global admin email
  const adminInput = document.getElementById('globalAdminEmail');
  if (adminInput) adminInput.value = userAccessData.globalAdminEmail || '';

  // Render employee permission cards
  const container = document.getElementById('userAccessList');
  if (!container) return;

  const employees = (state.timesheetData.employees || []).filter(e => e.active !== false);
  if (!employees.length) {
    container.innerHTML = '<div class="empty-state" style="padding:30px">No employees to show.</div>';
    return;
  }

  container.innerHTML = employees.map(emp => {
    const ini = (emp.name || '').split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
    const col = empColor(emp.name);
    const perms = getUserPermissions(emp.name) || {};
    const enabledCount = Object.values(perms).filter(v => v === true).length;
    const safeName = emp.name.replace(/'/g, "\\'");

    return `
      <div class="ua-card" id="uaCard-${emp.id}">
        <div class="ua-card-header" onclick="toggleUACard('${emp.id}')">
          <div class="emp-avatar" style="width:38px;height:38px;font-size:16px;flex-shrink:0;background:linear-gradient(135deg,${col},#3e1a00)">${ini}</div>
          <div style="flex:1;min-width:0">
            <div style="font-weight:600;font-size:14px">${emp.name}</div>
            <div style="font-size:11px;color:var(--muted)">${enabledCount > 0 ? enabledCount + ' permission' + (enabledCount > 1 ? 's' : '') + ' enabled' : 'No permissions'}</div>
          </div>
          <div style="font-size:11px;color:var(--subtle)">&#9660;</div>
        </div>
        <div class="ua-card-body" id="uaBody-${emp.id}" style="display:none">
          ${PERMISSION_DEFS.map(p => {
            const checked = perms[p.key] === true;
            return `
              <div class="ua-perm-row">
                <div>
                  <div class="ua-perm-label">${p.label}</div>
                  <div class="ua-perm-desc">${p.desc}</div>
                </div>
                <label class="perm-switch">
                  <input type="checkbox" ${checked ? 'checked' : ''}
                    onchange="toggleUserPermission('${safeName}', '${p.key}', this.checked)">
                  <span class="slider"></span>
                </label>
              </div>
            `;
          }).join('')}
        </div>
      </div>
    `;
  }).join('');

  // Render access requests
  renderAccessRequests();
}

function toggleUACard(empId) {
  const body = document.getElementById(`uaBody-${empId}`);
  const card = document.getElementById(`uaCard-${empId}`);
  if (!body || !card) return;

  const isOpen = body.style.display !== 'none';
  body.style.display = isOpen ? 'none' : 'block';
  card.classList.toggle('expanded', !isOpen);
}

async function toggleUserPermission(empName, permKey, enabled) {
  // Find employee_id
  const emp = (state.timesheetData.employees || []).find(e => e.name === empName);
  if (!emp) { toast('Employee not found', 'error'); return; }

  // Update local state
  if (!userAccessData.users[empName]) {
    userAccessData.users[empName] = {
      employee_id: emp.id,
      permissions: {
        byProject: false, byEmployee: false, clockingInOut: false,
        payroll: false, archive: false, staff: false, holidays: false,
        reports: false, settings: false, userAccess: false, draftsmanMode: false,
        tenders: false, editQuotes: false, viewQuotes: false,
        editProjects: false, viewProjects: false,
        viewPurchaseOrders: false, editPurchaseOrders: false,
        invoicing: false, afps: false, reconcile: false, estimatingDashboard: false
      }
    };
  }
  userAccessData.users[empName].permissions[permKey] = enabled;

  try {
    await api.put(`/api/user-access/${emp.id}`, { [permKey]: enabled });
    toast(`${empName}: ${permKey} ${enabled ? 'enabled' : 'disabled'} ✓`, 'success');
  } catch (e) {
    toast('Failed to save permission', 'error');
    console.error('Permission save error:', e);
  }
}

async function saveGlobalAdminEmail() {
  const input = document.getElementById('globalAdminEmail');
  if (!input) return;
  const email = input.value.trim();

  if (email && !email.includes('@')) {
    toast('Please enter a valid email address', 'error');
    return;
  }

  userAccessData.globalAdminEmail = email;
  try {
    await api.put('/api/settings', { globalAdminEmail: email });
    toast('Global admin email saved ✓', 'success');
  } catch { toast('Save failed', 'error'); }
}

function renderAccessRequests() {
  const card = document.getElementById('accessRequestsCard');
  const list = document.getElementById('accessRequestsList');
  if (!card || !list) return;

  const requests = userAccessData.accessRequests || [];
  if (!requests.length) {
    card.style.display = 'none';
    return;
  }

  card.style.display = 'block';
  list.innerHTML = requests.map((req, i) => `
    <div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:14px 16px;margin-bottom:8px">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">
        <span style="font-weight:600;font-size:14px">${req.employeeName || 'Unknown'}</span>
        <span style="font-size:11px;color:var(--subtle);font-family:var(--font-mono)">${req.date || ''}</span>
      </div>
      <div style="font-size:13px;color:var(--muted);margin-bottom:8px">${req.reason || 'No reason given'}</div>
      <button class="tiny-btn" style="background:var(--surface);color:var(--muted);border:1px solid var(--border);font-size:11px;padding:4px 10px"
        onclick="dismissAccessRequest(${i})">Dismiss</button>
    </div>
  `).join('');
}

async function dismissAccessRequest(index) {
  const req = userAccessData.accessRequests[index];
  if (!req || !req.id) {
    userAccessData.accessRequests.splice(index, 1);
    renderAccessRequests();
    return;
  }
  try {
    await api.put(`/api/access-requests/${req.id}`, { status: 'dismissed' });
    userAccessData.accessRequests.splice(index, 1);
    renderAccessRequests();
    toast('Request dismissed', 'info');
  } catch { toast('Save failed', 'error'); }
}

// ═══════════════════════════════════════════
// REQUEST ACCESS (from Access Denied screen)
// ═══════════════════════════════════════════
function openRequestAccessModal() {
  const textarea = document.getElementById('accessRequestReason');
  if (textarea) textarea.value = '';
  document.getElementById('requestAccessModal').classList.add('active');
}

function closeRequestAccessModal() {
  document.getElementById('requestAccessModal').classList.remove('active');
}

async function submitAccessRequest() {
  const reason = (document.getElementById('accessRequestReason')?.value || '').trim();
  if (!reason) {
    toast('Please provide a reason for your request', 'error');
    return;
  }

  const empName = currentManagerUser || _pendingManagerUser || 'Unknown';
  const adminEmail = userAccessData.globalAdminEmail;

  // Save request via API
  try {
    const result = await api.post('/api/access-requests', {
      employee_name: empName,
      reason: reason
    });
    if (!userAccessData.accessRequests) userAccessData.accessRequests = [];
    userAccessData.accessRequests.push({
      id: result.id,
      employeeName: empName,
      reason: reason,
      date: new Date().toISOString().slice(0, 16).replace('T', ' ')
    });
  } catch (e) {
    console.warn('Failed to save access request:', e.message);
  }

  // Send email if admin email is configured
  if (adminEmail) {
    try {
      const token = await getToken();
      const emailBody = {
        message: {
          subject: `BAMA ERP — Access Request from ${empName}`,
          body: {
            contentType: 'HTML',
            content: `
              <h2 style="color:#ff6b00;font-family:sans-serif">BAMA FABRICATION — Access Request</h2>
              <p style="font-family:sans-serif;font-size:14px"><b>Employee:</b> ${empName}</p>
              <p style="font-family:sans-serif;font-size:14px"><b>Reason:</b></p>
              <div style="background:#f5f5f5;padding:16px;border-radius:8px;font-family:sans-serif;font-size:14px;margin:12px 0">${reason}</div>
              <p style="font-family:sans-serif;font-size:13px;color:#888">
                To grant access, go to Office → User Access tab and enable the relevant permissions for this user.
              </p>
              <p style="margin-top:20px;font-family:sans-serif;font-size:11px;color:#aaa">
                Generated by BAMA Workshop ERP — ${new Date().toLocaleString('en-GB')}
              </p>
            `
          },
          toRecipients: [{ emailAddress: { address: adminEmail } }]
        },
        saveToSentItems: true
      };

      const res = await fetch('https://graph.microsoft.com/v1.0/me/sendMail', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(emailBody)
      });

      if (res.ok || res.status === 202) {
        toast('Access request sent ✓', 'success');
      } else {
        console.error('Email error:', await res.text());
        toast('Request logged but email failed', 'info');
      }
    } catch (e) {
      console.error('Email send error:', e);
      toast('Request logged but email failed', 'info');
    }
  } else {
    toast('Request logged (no admin email configured)', 'info');
  }

  closeRequestAccessModal();
}

// ═══════════════════════════════════════════
// CONFIRM MODAL HELPER
// ═══════════════════════════════════════════
function showConfirm(title, message, onConfirm) {
  const modal = document.getElementById('confirmModal');
  const titleEl = document.getElementById('confirmTitle');
  const msgEl = document.getElementById('confirmMsg');
  const btnEl = document.getElementById('confirmOk');
  if (titleEl) titleEl.textContent = title;
  if (msgEl) msgEl.textContent = message;
  if (btnEl) {
    const newBtn = btnEl.cloneNode(true);
    // showConfirmAsync may have left the OK button relabelled ("Upload anyway")
    // and restyled (btn-danger). Reset to the neutral default for a plain confirm.
    newBtn.textContent = 'Confirm';
    newBtn.className = 'btn btn-primary';
    newBtn.onclick = () => { closeModal(); onConfirm(); };
    btnEl.parentNode.replaceChild(newBtn, btnEl);
  }
  const cancelBtn = modal.querySelector('.modal-actions .btn-ghost');
  if (cancelBtn) {
    const newCancel = cancelBtn.cloneNode(true);
    newCancel.textContent = 'Cancel';
    newCancel.onclick = () => closeModal();
    cancelBtn.parentNode.replaceChild(newCancel, cancelBtn);
  }
  modal.classList.add('active');
}

// Promise-returning confirm with HTML message support and customisable
// button labels. Resolves true on confirm, false on cancel/dismiss.
// Usage: const ok = await showConfirmAsync('Title', '<p>HTML body</p>', { okLabel: 'Generate' });
function showConfirmAsync(title, htmlMessage, options = {}) {
  return new Promise(resolve => {
    const modal = document.getElementById('confirmModal');
    if (!modal) { resolve(false); return; }
    const titleEl = document.getElementById('confirmTitle');
    const msgEl = document.getElementById('confirmMsg');
    const btnEl = document.getElementById('confirmOk');
    const cancelBtn = modal.querySelector('.modal-actions .btn-ghost');

    if (titleEl) titleEl.textContent = title;
    if (msgEl) msgEl.innerHTML = htmlMessage;

    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      closeModal();
      resolve(value);
    };

    if (btnEl) {
      const newBtn = btnEl.cloneNode(true);
      if (options.okLabel) newBtn.textContent = options.okLabel;
      if (options.danger) {
        newBtn.classList.remove('btn-primary');
        newBtn.classList.add('btn-danger');
      }
      newBtn.onclick = () => {
        // onConfirmSync runs inside the user-gesture click stack, before
        // the promise resolves. Useful for window.open() which would
        // otherwise be blocked by popup blockers if it ran after an await.
        // The return value is passed through as the second value, so the
        // caller can do: const { ok, data } = await showConfirmAsync(...)
        let syncResult;
        if (typeof options.onConfirmSync === 'function') {
          try { syncResult = options.onConfirmSync(); }
          catch (e) { console.error('onConfirmSync threw:', e); }
        }
        finish(options.onConfirmSync ? { ok: true, data: syncResult } : true);
      };
      btnEl.parentNode.replaceChild(newBtn, btnEl);
    }
    if (cancelBtn) {
      const newCancel = cancelBtn.cloneNode(true);
      if (options.cancelLabel) newCancel.textContent = options.cancelLabel;
      newCancel.onclick = () => finish(options.onConfirmSync ? { ok: false, data: null } : false);
      cancelBtn.parentNode.replaceChild(newCancel, cancelBtn);
    }

    modal.classList.add('active');
  });
}

function closeModal() {
  document.getElementById('confirmModal').classList.remove('active');
  const modalEl = document.getElementById('confirmModal').querySelector('.modal');
  if (modalEl) modalEl.style.width = '';
}


