// Source filter for the Project Tracker list.
// 'all' shows everything. 'bama' shows projects whose number starts with C
// (and not BC) — the existing main quote-conversion flow. 'babcock' shows
// projects whose number starts with BC — the Babcock conversion flow.
// Persists across re-renders within the session via this module-level var.
let _projectSourceFilter = 'all';

function projectSourceClass(project) {
  const num = String(project.project_number || '').toUpperCase();
  if (num.startsWith('BC')) return 'babcock';
  if (num.startsWith('C'))  return 'bama';
  return 'other';
}

function setProjectSourceFilter(source) {
  _projectSourceFilter = source || 'all';
  document.querySelectorAll('#projectSourceFilter .source-filter-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.source === _projectSourceFilter);
  });
  const titleEl = document.getElementById('projectListTitle');
  if (titleEl) {
    titleEl.textContent = ({
      all:     'All Projects',
      bama:    'BAMA Projects',
      babcock: 'Babcock Projects'
    })[_projectSourceFilter] || 'All Projects';
  }
  renderProjectTrackerList();
}

function renderProjectTrackerList() {
  const container = document.getElementById('projectTrackerListContainer');
  if (!container) return;

  const search = (document.getElementById('projectSearch')?.value || '').toLowerCase();
  const statusFilter = document.getElementById('projectStatusFilter')?.value || '';
  const deadlineFilter = document.getElementById('projectDeadlineFilter')?.value || '';

  let list = [...projectsData];
  if (_projectSourceFilter && _projectSourceFilter !== 'all') {
    list = list.filter(p => projectSourceClass(p) === _projectSourceFilter);
  }
  if (statusFilter) list = list.filter(p => p.status === statusFilter);
  if (search) {
    list = list.filter(p => {
      const hay = `${p.project_number} ${p.project_name} ${p.company_name || ''}`.toLowerCase();
      return hay.includes(search);
    });
  }

  // Deadline filter — buckets relative to today (UTC midnight to dodge TZ drift)
  if (deadlineFilter) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const dayMs = 86400000;
    list = list.filter(p => {
      const raw = p.deadline_date ? String(p.deadline_date).split('T')[0] : null;
      if (deadlineFilter === 'none') return !raw;
      if (!raw) return false;
      const d = new Date(raw + 'T00:00:00');
      const diffDays = Math.floor((d - today) / dayMs);
      switch (deadlineFilter) {
        case 'overdue':  return diffDays < 0 && p.status !== 'Complete' && p.status !== 'Archived' && p.status !== 'Cancelled';
        case '7':        return diffDays >= 0 && diffDays <= 7;
        case '30':       return diffDays >= 0 && diffDays <= 30;
        case '90':       return diffDays >= 0 && diffDays <= 90;
        case 'future':   return diffDays > 90;
        default:         return true;
      }
    });
  }

  if (!list.length) {
    container.innerHTML = '<div class="empty-state" style="padding:24px"><div class="icon">🏗️</div>No projects match the current filters</div>';
    return;
  }

  const statusMeta = {
    'In Progress': { cls: 'tag-approved' },
    'On Hold':     { cls: 'tag-pending'  },
    'Complete':    { cls: 'tag-approved' },
    'Archived':    { cls: 'tag-pending'  },
    'Cancelled':   { cls: 'tag-rejected' }
  };

  // Today (UTC midnight) for "overdue" highlight on the deadline cell
  const todayMid = new Date();
  todayMid.setHours(0, 0, 0, 0);

  container.innerHTML = list.map(p => {
    const meta = statusMeta[p.status] || { cls: 'tag-pending' };
    const rawDate = p.deadline_date ? String(p.deadline_date).split('T')[0] : '';
    const deadline = rawDate ? fmtDateStr(rawDate) : '—';
    let deadlineColor = 'var(--muted)';
    if (rawDate) {
      const d = new Date(rawDate + 'T00:00:00');
      const isLive = p.status !== 'Complete' && p.status !== 'Archived' && p.status !== 'Cancelled';
      if (d < todayMid && isLive) deadlineColor = 'var(--red)';
    }
    const pct = Math.max(0, Math.min(100, parseFloat(p.progress_pct) || 0));
    return `
      <div class="quote-row" onclick="openProjectTrackerDetail(${p.id})">
        <div class="quote-col-ref">${escapeHtml(p.project_number)}</div>
        <div class="quote-col-project">
          <div style="font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escapeHtml(p.project_name)}</div>
          <div style="font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${escapeHtml(p.company_name || '—')}</div>
        </div>
        <div class="quote-col-date" style="color:${deadlineColor};font-size:12px">${deadline}</div>
        <div class="quote-col-progress">
          <div class="pt-list-progress">
            <div class="pt-list-progress-bar"><div class="pt-list-progress-fill" style="width:${pct}%"></div></div>
            <div class="pt-list-progress-num">${pct.toFixed(0)}%</div>
          </div>
        </div>
        <div class="quote-col-status"><span class="tag ${meta.cls}">${escapeHtml(p.status)}</span></div>
      </div>`;
  }).join('');
}

// ── Project detail page (Project Tracker / office) ──
//
// NOTE: Renamed from openProjectDetail to openProjectTrackerDetail to avoid
// colliding with the kiosk's openProjectDetail in shared.js (~line 7678).
// Both files load shared.js, so duplicate function declarations with the
// same name caused the second definition to silently win — clicks on the
// kiosk Workshop Projects tiles fired the office function, which couldn't
// find the project in projectsData (empty on the kiosk page) and returned
// a 'Project not found' toast at best, or did nothing visible at worst.
async function openProjectTrackerDetail(id) {
  let project = projectsData.find(p => String(p.id) === String(id));
  if (!project) { toast('Project not found', 'error'); return; }

  try {
    const full = await api.get(`/api/projects/${id}`);
    Object.assign(project, full);
  } catch (e) { console.warn('Could not refresh project:', e); }

  currentProjectRecord = project;
  _projectDetailDirty = false;

  document.querySelectorAll('#projectTrackerLayout .tab-content').forEach(el => {
    el.classList.remove('active'); el.style.display = 'none';
  });
  const detailEl = document.getElementById('tab-projectDetail');
  if (detailEl) { detailEl.style.display = ''; detailEl.classList.add('active'); }

  const saveBtn = document.getElementById('pdSaveBtn');
  const discardBtn = document.getElementById('pdDiscardBtn');
  if (saveBtn) saveBtn.style.display = 'none';
  if (discardBtn) discardBtn.style.display = 'none';

  _populateProjectDetailFields(project);
}

// Build the SharePoint-style folder name from the currently-loaded project +
// whatever the user has typed in the project-name input. Format matches the
// folder structure created on new-project submit:
//   "<NUMBER> - <CLIENT> - <PROJECT NAME>"
function _buildProjectFolderName() {
  const p = currentProjectRecord || {};
  const number  = (p.project_number || '').trim();
  const company = (p.company_name   || '').trim();
  const nameEl  = document.getElementById('pd-projectName');
  const name    = (nameEl ? nameEl.value : (p.project_name || '')).trim();
  return [number, company, name].filter(Boolean).join(' - ');
}

function updateProjectFolderNamePreview() {
  const el = document.getElementById('projectDetailFolderName');
  if (!el) return;
  const name = _buildProjectFolderName();
  el.textContent = name || '—';
}

async function copyProjectFolderName() {
  const name = _buildProjectFolderName();
  if (!name) { toast('Nothing to copy', 'warning'); return; }
  try {
    await navigator.clipboard.writeText(name);
    toast('Folder name copied ✓', 'success');
  } catch (e) {
    // Fallback for older browsers / non-secure contexts
    const ta = document.createElement('textarea');
    ta.value = name;
    ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); toast('Folder name copied ✓', 'success'); }
    catch (_) { toast('Copy failed — copy manually: ' + name, 'error'); }
    document.body.removeChild(ta);
  }
}

function _populateProjectDetailFields(project) {
  const setVal = (id, v) => { const el = document.getElementById(id); if (el) el.value = v ?? ''; };
  const setText = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v ?? '—'; };

  setText('projectDetailNumber', project.project_number);
  setVal('pd-projectName', project.project_name || '');
  updateProjectFolderNamePreview();
  setVal('pd-status', project.status || 'In Progress');
  setVal('pd-deadline', project.deadline_date ? String(project.deadline_date).split('T')[0] : '');
  setVal('pd-startDate', project.start_date ? String(project.start_date).split('T')[0] : '');
  setVal('pd-completionDate', project.completion_date ? String(project.completion_date).split('T')[0] : '');

  // ── Babcock cascade hint ─────────────────────────────────────────────
  // If this project came from a Babcock quote, show a subtle note under
  // the status dropdown so the user knows that marking Complete here
  // will also advance the Babcock tracker. Backend (projects.js PUT)
  // owns the actual cascade; this is just messaging.
  const statusHint = document.getElementById('pd-statusHint');
  if (statusHint) {
    if (project.source_babcock_quote_id) {
      statusHint.textContent =
        'Linked to Babcock quote — marking Complete will also advance the Babcock tracker.';
      statusHint.style.display = '';
    } else {
      statusHint.style.display = 'none';
      statusHint.textContent = '';
    }
  }

  // Re-lock lockable fields after setting values (project name, dates).
  // The user must press the pencil button again to edit.
  _relockProjectDetailFields();

  // Default to Client tab on every open
  switchProjectCapTab('client');

  // Client info
  const clientInfo = document.getElementById('projectDetailClientInfo');
  if (clientInfo) {
    const addressLine = [project.address_line1, project.address_line2, project.city, project.county, project.postcode].filter(Boolean).join(', ');
    clientInfo.innerHTML = `
      <div style="font-weight:600;font-size:15px;color:var(--text);margin-bottom:6px">${escapeHtml(project.company_name || '—')}</div>
      ${addressLine ? `<div style="margin-bottom:8px;color:var(--muted)">${escapeHtml(addressLine)}</div>` : ''}
      ${project.contact_name ? `<div style="font-size:13px"><span style="color:var(--subtle);font-weight:600">Contact:</span> ${escapeHtml(project.contact_name)}</div>` : ''}
      ${project.contact_email ? `<div style="font-size:13px"><span style="color:var(--subtle);font-weight:600">Email:</span> <a href="mailto:${escapeHtml(project.contact_email)}" style="color:var(--accent2);text-decoration:none">${escapeHtml(project.contact_email)}</a></div>` : ''}
      ${project.contact_phone ? `<div style="font-size:13px"><span style="color:var(--subtle);font-weight:600">Phone:</span> ${escapeHtml(project.contact_phone)}</div>` : ''}`;
  }

  // SharePoint folder link.
  // Three possible states:
  //   1. Folder already linked + user can edit  → "Open in SharePoint" + small re-link
  //   2. Folder already linked + view-only      → "Open in SharePoint" only
  //   3. No folder linked + user can edit       → "Link to existing folder" button
  //   4. No folder linked + view-only           → "No folder linked" subtle text
  const folderLink = document.getElementById('projectDetailFolderLink');
  if (folderLink) {
    const perms = getUserPermissions(currentManagerUser);
    const canEdit = !!(perms && perms.editProjects);

    if (project.sharepoint_folder_id) {
      folderLink.innerHTML = `
        <button class="btn btn-ghost" onclick="openProjectFolder()" style="font-size:12px">📁 Open in SharePoint ↗</button>
        ${canEdit ? `<button class="btn btn-ghost" onclick="openLinkFolderModal()" title="Re-link to a different folder" style="font-size:12px;padding:4px 8px;margin-left:4px">✎</button>` : ''}
      `;
    } else if (canEdit) {
      folderLink.innerHTML = `<button class="btn btn-ghost" onclick="openLinkFolderModal()" style="font-size:12px">🔗 Link to existing folder</button>`;
    } else {
      folderLink.innerHTML = '<span style="font-size:12px;color:var(--subtle)">No folder linked</span>';
    }
  }

  // ── Site Address (toggle defaults to "same as client") ──
  // mssql returns BIT as boolean; older rows may be null (treat as 1).
  const sameAsClient = (project.site_same_as_client === false || project.site_same_as_client === 0)
    ? false : true;
  const sameToggle = document.getElementById('pd-siteSameAsClient');
  if (sameToggle) sameToggle.checked = sameAsClient;
  setVal('pd-siteAddressLine1', project.site_address_line1 || '');
  setVal('pd-siteAddressLine2', project.site_address_line2 || '');
  setVal('pd-siteCity',         project.site_city || '');
  setVal('pd-siteCounty',       project.site_county || '');
  setVal('pd-sitePostcode',     project.site_postcode || '');
  setVal('pd-siteContactName',  project.site_contact_name || '');
  setVal('pd-siteContactEmail', project.site_contact_email || '');
  setVal('pd-siteContactPhone', project.site_contact_phone || '');
  _refreshSiteSection(project);

  // ── Additional contacts and comments — fetched async ──
  loadProjectContacts(project.id).catch(e => console.warn('contacts load failed', e));
  loadProjectComments(project.id).catch(e => console.warn('comments load failed', e));

  // ── Financial dashboard — attached quotes + line items + progress ──
  loadProjectFinancials(project.id).catch(e => console.warn('financials load failed', e));

  // ── Purchase Orders for this project ──
  loadProjectPos(project.id).catch(e => console.warn('project POs load failed', e));
}

// Build the "summary" text shown above the site fields when they're hidden.
function _siteAddressSummary(project) {
  if (!project) return 'Same as client address';
  const sameAsClient = (project.site_same_as_client === false || project.site_same_as_client === 0)
    ? false : true;
  if (sameAsClient) return 'Same as client address';
  const parts = [
    project.site_address_line1, project.site_address_line2,
    project.site_city, project.site_county, project.site_postcode
  ].filter(Boolean);
  return parts.length ? parts.join(', ') : 'Different from client — no address entered yet';
}

// Show/hide the site fields panel based on the toggle state. Also updates summary.
function _refreshSiteSection(project) {
  const sameToggle = document.getElementById('pd-siteSameAsClient');
  const fieldsBlock = document.getElementById('pd-siteFields');
  const summary = document.getElementById('pd-siteSummary');
  if (!sameToggle || !fieldsBlock) return;
  fieldsBlock.style.display = sameToggle.checked ? 'none' : '';
  if (summary) summary.textContent = _siteAddressSummary(project || currentProjectRecord || {});
}

// Toggle handler — flips visibility, marks dirty, refreshes summary.
function onSiteSameToggle() {
  markProjectDirty();
  // Build a mock object reflecting the current toggle so the summary is fresh.
  const sameToggle = document.getElementById('pd-siteSameAsClient');
  const mock = Object.assign({}, currentProjectRecord || {}, {
    site_same_as_client: sameToggle ? sameToggle.checked : true,
    site_address_line1: document.getElementById('pd-siteAddressLine1')?.value,
    site_address_line2: document.getElementById('pd-siteAddressLine2')?.value,
    site_city:          document.getElementById('pd-siteCity')?.value,
    site_county:        document.getElementById('pd-siteCounty')?.value,
    site_postcode:      document.getElementById('pd-sitePostcode')?.value
  });
  _refreshSiteSection(mock);
}

async function openProjectFolder() {
  if (!currentProjectRecord || !currentProjectRecord.sharepoint_folder_id) return;
  try {
    const token = await getToken();
    const res = await fetch(
      `https://graph.microsoft.com/v1.0/drives/${BAMA_DRIVE_ID}/items/${currentProjectRecord.sharepoint_folder_id}`,
      { headers: { 'Authorization': `Bearer ${token}` } }
    );
    if (!res.ok) throw new Error(`Lookup failed: ${res.status}`);
    const data = await res.json();
    if (data.webUrl) window.open(data.webUrl, '_blank');
  } catch (e) {
    toast('Could not open folder: ' + e.message, 'error');
  }
}

// ═══════════════════════════════════════════
// LINK EXISTING SHAREPOINT FOLDER TO PROJECT
// ═══════════════════════════════════════════
// For S-prefix legacy projects (which never had folders auto-created),
// or any project where sharepoint_folder_id ended up NULL. Searches the
// BAMA drive for folders whose name matches the user's query, lists
// matches with their parent path so the user can disambiguate, and
// PUTs the chosen item ID onto the project.

function openLinkFolderModal() {
  if (!currentProjectRecord) return;
  const perms = getUserPermissions(currentManagerUser);
  if (!perms || !perms.editProjects) {
    toast("You don't have permission to edit this project", 'error');
    return;
  }

  // Pre-fill the search box with the project number — this is what the
  // legacy folder name almost always starts with (e.g. "S1953 - Bama - …").
  const queryInput = document.getElementById('linkFolderQuery');
  if (queryInput) queryInput.value = currentProjectRecord.project_number || '';

  // Reset results panel
  const results = document.getElementById('linkFolderResults');
  if (results) results.innerHTML = '<div style="font-size:12px;color:var(--muted);padding:8px">Click "Search" or press Enter to find folders matching the query above.</div>';

  document.getElementById('linkFolderModal').classList.add('active');

  // Auto-run the initial search since we know the project number is the
  // best starting query — saves the user a click.
  setTimeout(() => searchLinkFolderCandidates(), 50);
}

function closeLinkFolderModal() {
  document.getElementById('linkFolderModal').classList.remove('active');
}

function onLinkFolderQueryKey(e) {
  if (e.key === 'Enter') {
    e.preventDefault();
    searchLinkFolderCandidates();
  }
}

async function searchLinkFolderCandidates() {
  const queryInput = document.getElementById('linkFolderQuery');
  const results    = document.getElementById('linkFolderResults');
  const searchBtn  = document.getElementById('linkFolderSearchBtn');
  if (!queryInput || !results) return;

  const q = queryInput.value.trim();
  if (q.length < 2) {
    results.innerHTML = '<div style="font-size:12px;color:var(--red);padding:8px">Enter at least 2 characters to search.</div>';
    return;
  }

  if (searchBtn) { searchBtn.disabled = true; searchBtn.textContent = 'Searching…'; }
  results.innerHTML = '<div style="font-size:12px;color:var(--muted);padding:8px">Searching SharePoint…</div>';

  try {
    const token = await getToken();
    // Graph search across the entire drive. Single quotes inside the query
    // would break the OData syntax — strip them just in case.
    const safeQ = q.replace(/'/g, '');
    const res = await fetch(
      `https://graph.microsoft.com/v1.0/drives/${BAMA_DRIVE_ID}/root/search(q='${encodeURIComponent(safeQ)}')?$top=25`,
      { headers: { 'Authorization': `Bearer ${token}` } }
    );
    if (!res.ok) throw new Error(`Search failed: ${res.status}`);
    const data = await res.json();

    // Filter to folders only (search returns files too).
    const folders = (data.value || []).filter(it => it.folder);

    if (!folders.length) {
      results.innerHTML = `
        <div style="font-size:12px;color:var(--muted);padding:8px;line-height:1.5">
          No folders found containing <strong>${escapeHtml(q)}</strong>.<br>
          Try a different part of the folder name (client name, etc.).
        </div>`;
      return;
    }

    // Render each folder with its parent path so the user can tell two
    // similarly-named folders apart. parentReference.path looks like
    // "/drives/{id}/root:/Projects/2024 Archive" — strip the prefix for display.
    results.innerHTML = folders.map(f => {
      const parentPath = (f.parentReference && f.parentReference.path) || '';
      const cleanPath  = parentPath.replace(/^\/drives\/[^/]+\/root:?/, '') || '/';
      const childCount = (f.folder && f.folder.childCount != null) ? f.folder.childCount : '?';
      return `
        <div class="ac-result-row" style="display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px;border-bottom:1px solid var(--border)">
          <div style="min-width:0;flex:1">
            <div style="font-weight:600;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">📁 ${escapeHtml(f.name)}</div>
            <div style="font-size:11px;color:var(--muted);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${escapeHtml(cleanPath)}">${escapeHtml(cleanPath)} · ${childCount} item${childCount === 1 ? '' : 's'}</div>
          </div>
          <button class="btn btn-primary" style="font-size:12px;padding:6px 12px;flex:none"
            onclick="confirmLinkFolder('${f.id}', ${JSON.stringify(f.name).replace(/"/g, '&quot;')})">
            Link this
          </button>
        </div>`;
    }).join('');
  } catch (e) {
    console.error('Folder search failed:', e);
    results.innerHTML = `<div style="font-size:12px;color:var(--red);padding:8px">Search failed: ${escapeHtml(e.message)}</div>`;
  } finally {
    if (searchBtn) { searchBtn.disabled = false; searchBtn.textContent = 'Search'; }
  }
}

async function confirmLinkFolder(folderId, folderName) {
  if (!currentProjectRecord || !folderId) return;

  // If a folder is already linked, confirm the swap so re-linking isn't a
  // silent surprise.
  if (currentProjectRecord.sharepoint_folder_id &&
      currentProjectRecord.sharepoint_folder_id !== folderId) {
    if (!(await bamaConfirm({ title: 'Replace linked folder', body: `Replace the currently linked folder with "${folderName}"?<br><br>The project's existing folder won't be modified — only the link is updated.`, confirmText: 'Replace', tone: 'warn' }))) {
      return;
    }
  }

  try {
    const updated = await api.put(`/api/projects/${currentProjectRecord.id}`, {
      sharepoint_folder_id: folderId
    });

    // Patch local state and refresh the detail view header.
    if (updated && updated.id) {
      currentProjectRecord = updated;
      // Also patch projectsData so the list view doesn't show stale data.
      const idx = projectsData.findIndex(p => p.id === updated.id);
      if (idx !== -1) projectsData[idx] = updated;
    } else {
      currentProjectRecord.sharepoint_folder_id = folderId;
    }

    closeLinkFolderModal();
    // Re-render the detail page so the folder-link area picks up the new state.
    _populateProjectDetailFields(currentProjectRecord);
    toast(`Folder linked: ${folderName}`, 'success');
  } catch (e) {
    console.error('Link folder failed:', e);
    toast('Failed to link folder: ' + (e.message || 'unknown error'), 'error');
  }
}

function markProjectDirty() {
  _projectDetailDirty = true;
  const sb = document.getElementById('pdSaveBtn');
  const db = document.getElementById('pdDiscardBtn');
  if (sb) sb.style.display = '';
  if (db) db.style.display = '';
}

async function saveProjectChanges() {
  if (!currentProjectRecord) return;
  const sameToggle = document.getElementById('pd-siteSameAsClient');
  const siteSame = sameToggle ? sameToggle.checked : true;

  const body = {
    project_name:    document.getElementById('pd-projectName')?.value.trim() || currentProjectRecord.project_name,
    status:          document.getElementById('pd-status')?.value || currentProjectRecord.status,
    deadline_date:   document.getElementById('pd-deadline')?.value || null,
    start_date:      document.getElementById('pd-startDate')?.value || null,
    completion_date: document.getElementById('pd-completionDate')?.value || null,

    // Site address — when toggle is ON ("same as client") we still send the
    // toggle so it persists, but null out the site fields to avoid stale data.
    site_same_as_client: siteSame,
    site_address_line1: siteSame ? null : (document.getElementById('pd-siteAddressLine1')?.value.trim() || null),
    site_address_line2: siteSame ? null : (document.getElementById('pd-siteAddressLine2')?.value.trim() || null),
    site_city:          siteSame ? null : (document.getElementById('pd-siteCity')?.value.trim() || null),
    site_county:        siteSame ? null : (document.getElementById('pd-siteCounty')?.value.trim() || null),
    site_postcode:      siteSame ? null : (document.getElementById('pd-sitePostcode')?.value.trim() || null),
    site_contact_name:  siteSame ? null : (document.getElementById('pd-siteContactName')?.value.trim() || null),
    site_contact_email: siteSame ? null : (document.getElementById('pd-siteContactEmail')?.value.trim() || null),
    site_contact_phone: siteSame ? null : (document.getElementById('pd-siteContactPhone')?.value.trim() || null)
  };

  try {
    await api.put(`/api/projects/${currentProjectRecord.id}`, body);
    Object.assign(currentProjectRecord, body);
    const idx = projectsData.findIndex(p => String(p.id) === String(currentProjectRecord.id));
    if (idx !== -1) Object.assign(projectsData[idx], body);

    _projectDetailDirty = false;
    document.getElementById('pdSaveBtn').style.display = 'none';
    document.getElementById('pdDiscardBtn').style.display = 'none';
    _refreshSiteSection(currentProjectRecord);
    _relockProjectDetailFields();
    toast('Project saved ✓', 'success');
  } catch (err) {
    toast('Save failed: ' + err.message, 'error');
  }
}

function discardProjectChanges() {
  if (!currentProjectRecord) return;
  _populateProjectDetailFields(currentProjectRecord);
  _projectDetailDirty = false;
  document.getElementById('pdSaveBtn').style.display = 'none';
  document.getElementById('pdDiscardBtn').style.display = 'none';
}

// ─────────────────────────────────────────────────────────────────────────────
// Lockable detail fields (project name, dates) — pencil-button toggle.
// Fields are readonly/disabled by default; clicking the pencil unlocks them
// for one editing session. Save / discard re-locks via _relockProjectDetailFields.
// ─────────────────────────────────────────────────────────────────────────────
function togglePdFieldEdit(inputId, btn) {
  const input = document.getElementById(inputId);
  if (!input) return;
  const isDate = input.type === 'date';
  const isLocked = isDate ? input.disabled : input.hasAttribute('readonly');

  if (isLocked) {
    if (isDate) input.disabled = false;
    else        input.removeAttribute('readonly');
    input.classList.add('pd-editing');
    if (btn) {
      btn.classList.add('pd-editing');
      btn.textContent = '✓';
      btn.title = 'Lock field';
    }
    setTimeout(() => {
      input.focus();
      // Date inputs: try to open the picker for a frictionless edit.
      if (isDate) { try { input.showPicker?.(); } catch (_) { /* not all browsers */ } }
    }, 10);
  } else {
    if (isDate) input.disabled = true;
    else        input.setAttribute('readonly', '');
    input.classList.remove('pd-editing');
    if (btn) {
      btn.classList.remove('pd-editing');
      btn.textContent = '✎';
      btn.title = 'Edit field';
    }
  }
}

function _relockProjectDetailFields() {
  // Re-lock all .pd-locked-input elements + reset their pencil buttons
  document.querySelectorAll('.pd-locked-input').forEach(input => {
    if (input.type === 'date') input.disabled = true;
    else                       input.setAttribute('readonly', '');
    input.classList.remove('pd-editing');
  });
  document.querySelectorAll('.pd-edit-btn').forEach(btn => {
    btn.classList.remove('pd-editing');
    btn.textContent = '✎';
    btn.title = 'Edit field';
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Contacts & Addresses tabbed card — switch between Client / Site / Other Contacts.
// (Replaces the old three separate cards.)
// ─────────────────────────────────────────────────────────────────────────────
function switchProjectCapTab(tabName) {
  document.querySelectorAll('[data-cap-tab]').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.capTab === tabName);
  });
  document.querySelectorAll('[data-cap-pane]').forEach(pane => {
    const isActive = pane.dataset.capPane === tabName;
    pane.classList.toggle('active', isActive);
    pane.style.display = isActive ? '' : 'none';
  });
}

async function closeProjectDetail() {
  if (_projectDetailDirty) {
    const ok = await showConfirmAsync(
      'Discard unsaved changes?',
      'You have unsaved changes on this project. Closing now will lose them.',
      { okLabel: 'Discard', danger: true }
    );
    if (!ok) return;
  }
  currentProjectRecord = null;
  _projectDetailDirty = false;
  document.querySelectorAll('#projectTrackerLayout .tab-content').forEach(el => {
    el.classList.remove('active'); el.style.display = 'none';
  });
  const listTab = document.getElementById('tab-projectTrackerList');
  if (listTab) { listTab.style.display = ''; listTab.classList.add('active'); }
}

// ─────────────────────────────────────────────────────────────────────────────
// Project Contacts (additional people on a project — site foremen, QSs, etc.)
// Mirrors the tender contactModal CRUD pattern.
// ─────────────────────────────────────────────────────────────────────────────
let _projectContactsCache = [];

async function loadProjectContacts(projectId) {
  if (!projectId) return;
  try {
    const rows = await api.get(`/api/project-contacts?project_id=${projectId}`);
    _projectContactsCache = Array.isArray(rows) ? rows : [];
  } catch (e) {
    console.warn('loadProjectContacts failed:', e);
    _projectContactsCache = [];
  }
  renderProjectContacts();
}

function renderProjectContacts() {
  const list = document.getElementById('projectContactsList');
  const badge = document.getElementById('projectContactsCount');
  if (badge) badge.textContent = String(_projectContactsCache.length);
  if (!list) return;
  if (!_projectContactsCache.length) {
    list.innerHTML = '<div style="color:var(--subtle);padding:8px 0">No additional contacts yet.</div>';
    return;
  }
  list.innerHTML = _projectContactsCache.map(c => {
    const head = [c.contact_name, c.role].filter(Boolean).join(' · ');
    const emailLink = c.contact_email
      ? `<a href="mailto:${escapeHtml(c.contact_email)}" style="color:var(--accent2);text-decoration:none">${escapeHtml(c.contact_email)}</a>`
      : '';
    const bits = [emailLink, c.contact_phone ? escapeHtml(c.contact_phone) : ''].filter(Boolean).join(' · ');
    return `
      <div style="display:flex;align-items:flex-start;gap:10px;padding:10px 0;border-bottom:1px solid var(--border)">
        <div style="flex:1;min-width:0">
          <div style="font-weight:600;color:var(--text)">${escapeHtml(head || '(unnamed)')}</div>
          ${bits ? `<div style="font-size:12px;color:var(--muted);margin-top:2px">${bits}</div>` : ''}
          ${c.notes ? `<div style="font-size:12px;color:var(--subtle);margin-top:4px;white-space:pre-wrap">${escapeHtml(c.notes)}</div>` : ''}
        </div>
        <button class="btn btn-ghost" style="font-size:11px;padding:4px 10px" onclick="openEditProjectContact(${c.id})">Edit</button>
      </div>
    `;
  }).join('');
}

function openAddProjectContact() {
  if (!currentProjectRecord) return;
  document.getElementById('projectContactModalTitle').textContent = '👤 Add Contact';
  document.getElementById('pcId').value = '';
  document.getElementById('pcProjectId').value = currentProjectRecord.id;
  document.getElementById('pcName').value = '';
  document.getElementById('pcRole').value = '';
  document.getElementById('pcEmail').value = '';
  document.getElementById('pcPhone').value = '';
  document.getElementById('pcNotes').value = '';
  document.getElementById('pcDeleteBtn').style.display = 'none';
  document.getElementById('projectContactModal').classList.add('active');
  setTimeout(() => document.getElementById('pcName')?.focus(), 50);
}

function openEditProjectContact(id) {
  const c = _projectContactsCache.find(x => String(x.id) === String(id));
  if (!c) return;
  document.getElementById('projectContactModalTitle').textContent = '👤 Edit Contact';
  document.getElementById('pcId').value = c.id;
  document.getElementById('pcProjectId').value = c.project_id;
  document.getElementById('pcName').value  = c.contact_name  || '';
  document.getElementById('pcRole').value  = c.role          || '';
  document.getElementById('pcEmail').value = c.contact_email || '';
  document.getElementById('pcPhone').value = c.contact_phone || '';
  document.getElementById('pcNotes').value = c.notes         || '';
  document.getElementById('pcDeleteBtn').style.display = '';
  document.getElementById('projectContactModal').classList.add('active');
  setTimeout(() => document.getElementById('pcName')?.focus(), 50);
}

function closeProjectContactModal() {
  document.getElementById('projectContactModal').classList.remove('active');
}

async function submitProjectContactModal() {
  const id        = document.getElementById('pcId').value;
  const projectId = parseInt(document.getElementById('pcProjectId').value);
  const body = {
    contact_name:  document.getElementById('pcName').value.trim()  || null,
    contact_email: document.getElementById('pcEmail').value.trim() || null,
    contact_phone: document.getElementById('pcPhone').value.trim() || null,
    role:          document.getElementById('pcRole').value.trim()  || null,
    notes:         document.getElementById('pcNotes').value.trim() || null
  };
  if (!body.contact_name && !body.contact_email && !body.contact_phone) {
    toast('Enter at least a name, email, or phone', 'error');
    return;
  }

  try {
    if (id) {
      await api.put(`/api/project-contacts/${id}`, body);
    } else {
      body.project_id = projectId;
      await api.post('/api/project-contacts', body);
    }
    closeProjectContactModal();
    await loadProjectContacts(projectId || currentProjectRecord?.id);
    toast(id ? 'Contact updated ✓' : 'Contact added ✓', 'success');
  } catch (err) {
    toast('Save failed: ' + err.message, 'error');
  }
}

async function deleteProjectContactFromModal() {
  const id        = document.getElementById('pcId').value;
  const projectId = parseInt(document.getElementById('pcProjectId').value);
  if (!id) return;
  const confirmed = await showConfirmAsync(
    'Delete contact?',
    'This contact will be removed from the project. The client record is unaffected.',
    { okLabel: 'Delete', danger: true }
  );
  if (!confirmed) return;
  try {
    await api.delete(`/api/project-contacts/${id}`);
    closeProjectContactModal();
    await loadProjectContacts(projectId || currentProjectRecord?.id);
    toast('Contact deleted ✓', 'success');
  } catch (err) {
    toast('Delete failed: ' + err.message, 'error');
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Project Comments (threaded, append-only log). Mirrors tender comments UI.
// ─────────────────────────────────────────────────────────────────────────────
let _projectCommentsCache = [];

async function loadProjectComments(projectId) {
  if (!projectId) return;
  try {
    const rows = await api.get(`/api/project-comments?project_id=${projectId}`);
    _projectCommentsCache = Array.isArray(rows) ? rows : [];
  } catch (e) {
    console.warn('loadProjectComments failed:', e);
    _projectCommentsCache = [];
  }
  renderProjectComments();
}

function renderProjectComments() {
  const list = document.getElementById('projectCommentsList');
  if (!list) return;
  if (!_projectCommentsCache.length) {
    list.innerHTML = '<div style="color:var(--subtle);padding:8px 0">No comments yet.</div>';
    return;
  }
  const me = currentManagerUser || '';
  list.innerHTML = _projectCommentsCache.map(c => {
    const when = c.created_at ? new Date(c.created_at).toLocaleString('en-GB', {
      day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit'
    }) : '';
    const author = c.created_by || 'Unknown';
    const canDelete = me && (author === me);
    return `
      <div style="padding:10px 0;border-bottom:1px solid var(--border)">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
          <div style="font-weight:600;font-size:12px;color:var(--text)">${escapeHtml(author)}</div>
          <div style="display:flex;align-items:center;gap:8px">
            <div style="font-size:11px;color:var(--subtle)">${escapeHtml(when)}</div>
            ${canDelete ? `<button class="btn btn-ghost" style="font-size:11px;padding:2px 8px" onclick="deleteProjectComment(${c.id})">Delete</button>` : ''}
          </div>
        </div>
        <div style="white-space:pre-wrap;font-size:13px;color:var(--muted)">${escapeHtml(c.comment || '')}</div>
      </div>
    `;
  }).join('');
}

async function addProjectComment() {
  if (!currentProjectRecord) return;
  const ta = document.getElementById('pd-newComment');
  if (!ta) return;
  const text = ta.value.trim();
  if (!text) { toast('Type a comment first', 'error'); return; }
  try {
    await api.post('/api/project-comments', {
      project_id: currentProjectRecord.id,
      comment: text,
      created_by: currentManagerUser || null
    });
    ta.value = '';
    await loadProjectComments(currentProjectRecord.id);
  } catch (err) {
    toast('Could not post comment: ' + err.message, 'error');
  }
}

async function deleteProjectComment(id) {
  const ok = await showConfirmAsync(
    'Delete this comment?',
    'This will remove the comment from the project log. Comments cannot be edited, only re-added.',
    { okLabel: 'Delete', danger: true }
  );
  if (!ok) return;
  try {
    await api.delete(`/api/project-comments/${id}`);
    if (currentProjectRecord) await loadProjectComments(currentProjectRecord.id);
  } catch (err) {
    toast('Delete failed: ' + err.message, 'error');
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Project Financial Dashboard (Session 3 of the Issue 6 build)
// Loads attached quotes, their line items, and per-line progress; renders the
// 3 tiles (Contract / Labour / Running) plus a per-quote table.
// ─────────────────────────────────────────────────────────────────────────────

// Cache shape:
//   _projectFinancials = {
//     quotes:   [ { project_id, tender_id, is_primary, reference, ..., _lineItems: [...] }, ... ],
//     progress: { [quote_line_item_id]: percent_complete }
//   }
let _projectFinancials = { quotes: [], progress: {} };

async function loadProjectFinancials(projectId) {
  if (!projectId) return;

  // Reset UI to loading.
  const container = document.getElementById('ptQuotesContainer');
  if (container) container.innerHTML = '<div style="padding:14px;text-align:center;color:var(--subtle);font-size:12px">Loading…</div>';

  let quotes = [];
  let progress = [];
  try {
    [quotes, progress] = await Promise.all([
      api.get(`/api/project-quotes?project_id=${projectId}`),
      api.get(`/api/project-line-progress?project_id=${projectId}`)
    ]);
  } catch (e) {
    console.warn('financials fetch failed:', e);
    if (container) container.innerHTML = '<div style="padding:14px;color:var(--subtle);font-size:12px">Could not load financials.</div>';
    return;
  }

  // For each attached quote, fetch (and seed if needed) its line items.
  // QB-sourced quotes link via qb_quote_id (tender_id is NULL); Tender-sourced
  // quotes link via tender_id.
  const withLines = await Promise.all((quotes || []).map(async q => {
    let lines = [];
    const isQb = q.qb_quote_id != null && q.tender_id == null;
    try {
      if (isQb) {
        lines = await api.get(`/api/quote-line-items?qb_quote_id=${q.qb_quote_id}`);
        if (!Array.isArray(lines) || lines.length === 0) {
          lines = await api.post(`/api/quote-line-items/seed-qb/${q.qb_quote_id}`, {});
        }
      } else {
        lines = await api.get(`/api/quote-line-items?tender_id=${q.tender_id}`);
        if (!Array.isArray(lines) || lines.length === 0) {
          lines = await api.post(`/api/quote-line-items/seed/${q.tender_id}`, {});
        }
      }
    } catch (e) {
      console.warn(`line items fetch failed for quote ${q.qb_quote_id || q.tender_id}:`, e);
    }
    return Object.assign({}, q, { _lineItems: (lines || []).slice().sort((a, b) => a.line_no - b.line_no) });
  }));

  // Index progress by quote_line_item_id.
  const progressMap = {};
  for (const p of (progress || [])) {
    progressMap[p.quote_line_item_id] = parseFloat(p.percent_complete) || 0;
  }

  _projectFinancials = { quotes: withLines, progress: progressMap };

  // Load running labour hours from the LabourLog for this project.
  // Keyed by project_number — same string format used in the kiosk feed.
  await _loadLabourHoursLogged(currentProjectRecord ? currentProjectRecord.project_number : null);

  renderProjectFinancialDashboard();
  try { renderJobCosting(); } catch (e) { /* card may not be on this page */ }
}

// Sum (qty × unit_price) across all line items of all quotes; optional filter.
function _sumLineItems(filterFn) {
  let total = 0;
  for (const q of _projectFinancials.quotes) {
    for (const li of (q._lineItems || [])) {
      if (filterFn && !filterFn(li, q)) continue;
      const qty   = parseFloat(li.quantity)   || 0;
      const price = parseFloat(li.unit_price) || 0;
      total += qty * price;
    }
  }
  return total;
}

// Weighted progress: progress * line value, divided by total line value.
// Lines with zero value contribute nothing — the user can still set their
// % but it doesn't move the headline number, which is what we want.
function _weightedProjectProgress() {
  let weightedSum = 0, totalWeight = 0;
  for (const q of _projectFinancials.quotes) {
    for (const li of (q._lineItems || [])) {
      const qty   = parseFloat(li.quantity)   || 0;
      const price = parseFloat(li.unit_price) || 0;
      const value = qty * price;
      const pct   = _projectFinancials.progress[li.id] || 0;
      weightedSum += value * pct;
      totalWeight += value;
    }
  }
  return totalWeight > 0 ? (weightedSum / totalWeight) : 0;
}

// Sum hours (qty) on Labour-flagged lines across all attached quotes.
// ═══════════════════════════════════════════════════════════════════════════
// JOB COSTING — estimate vs actual (Phase C1)
// ═══════════════════════════════════════════════════════════════════════════
// Estimated costs: QB's NET cost buckets carried on each attached quote row
// (est_* columns from /api/project-quotes — published every time the quote is
// saved in QB). Actual labour: kiosk ProjectHours × basic rate (S000 excluded,
// CIS included, no OT uplift — established convention). Actual bought-in:
// nett committed on active POs. Committed ≠ invoiced: this view leads cash.
let _projectPoNetTotal = null;   // null until loadProjectPos resolves
let _projectPoCount    = 0;

function _jcEstimates() {
  const LABOUR = ['est_fabrication', 'est_installation', 'est_design', 'est_survey'];
  const BOUGHT = ['est_material', 'est_painting', 'est_galvanising', 'est_delivery', 'est_prelims'];
  let labour = 0, bought = 0, any = false;
  for (const q of _projectFinancials.quotes) {
    LABOUR.forEach(k => { if (q[k] != null) { labour += parseFloat(q[k]) || 0; any = true; } });
    BOUGHT.forEach(k => { if (q[k] != null) { bought += parseFloat(q[k]) || 0; any = true; } });
  }
  return { labour, bought, total: labour + bought, any };
}

function renderJobCosting() {
  const card = document.getElementById('ptJobCostingCard');
  const body = document.getElementById('ptJobCostingBody');
  if (!card || !body) return;
  if (!_projectFinancials.quotes.length) { card.style.display = 'none'; return; }
  card.style.display = '';

  const est = _jcEstimates();
  const estHrs   = _sumLabourHoursScheduled();
  const actHrs   = _projectLabourHoursLogged || 0;
  const actLab   = _projectLabourCostLogged || 0;
  const actPo    = _projectPoNetTotal;          // may still be null (loading)
  const contract = _sumLineItems();

  const money = v => v == null ? '—' : '£' + Math.round(v).toLocaleString('en-GB');
  const hrs   = v => v == null ? '—' : (Math.round(v * 10) / 10).toLocaleString('en-GB') + ' h';
  const varCell = (e, a) => {
    if (e == null || a == null || !(e > 0)) return '<td style="padding:7px 10px;text-align:right;color:var(--subtle)">—</td>';
    const d = a - e, pct = Math.round(d / e * 100);
    const col = d > 0 ? 'var(--red)' : 'var(--green)';
    return `<td style="padding:7px 10px;text-align:right;font-family:var(--font-mono);color:${col};white-space:nowrap">${d > 0 ? '▲' : '▼'} ${money(Math.abs(d))} <span style="font-size:10px;opacity:.8">(${d > 0 ? '+' : ''}${pct}%)</span></td>`;
  };
  const td  = 'padding:7px 10px;text-align:right;font-family:var(--font-mono);white-space:nowrap';
  const tdL = 'padding:7px 10px;text-align:left';

  const rows = [
    { label: 'Labour', sub: `${hrs(estHrs || null)} estimated · ${hrs(actHrs)} logged`,
      e: est.any ? est.labour : null, a: actLab },
    { label: 'Bought-in (material, finishing, delivery, prelims)',
      sub: actPo == null ? 'POs loading…' : `${_projectPoCount} active PO${_projectPoCount === 1 ? '' : 's'} committed (nett)`,
      e: est.any ? est.bought : null, a: actPo },
  ];
  const totE = est.any ? est.total : null;
  const totA = (actPo == null) ? null : actLab + actPo;

  let html = `<table style="width:100%;border-collapse:collapse;font-size:12.5px">
    <thead><tr style="color:var(--muted);font-size:10.5px;text-transform:uppercase;letter-spacing:.04em">
      <th style="${tdL};font-weight:600">Category</th>
      <th style="${td};font-weight:600">Estimated (QB net cost)</th>
      <th style="${td};font-weight:600">Actual to date</th>
      <th style="${td};font-weight:600">Variance</th>
    </tr></thead><tbody>`;
  rows.forEach(r => {
    html += `<tr style="border-top:1px solid var(--border)">
      <td style="${tdL}"><div>${r.label}</div><div style="font-size:10.5px;color:var(--subtle)">${r.sub}</div></td>
      <td style="${td}">${money(r.e)}</td>
      <td style="${td}">${money(r.a)}</td>
      ${varCell(r.e, r.a)}
    </tr>`;
  });
  html += `<tr style="border-top:2px solid var(--border);font-weight:700">
      <td style="${tdL}">Total cost</td>
      <td style="${td}">${money(totE)}</td>
      <td style="${td}">${money(totA)}</td>
      ${varCell(totE, totA)}
    </tr></tbody></table>`;

  const marginEst = (totE != null && contract > 0) ? contract - totE : null;
  const marginRun = (totA != null && contract > 0) ? contract - totA : null;
  html += `<div style="display:flex;gap:18px;flex-wrap:wrap;margin-top:10px;padding-top:10px;border-top:1px solid var(--border);font-size:12px">
      <div><span style="color:var(--muted)">Contract value</span> <strong style="font-family:var(--font-mono)">${money(contract || null)}</strong></div>
      <div><span style="color:var(--muted)">Margin at estimate</span> <strong style="font-family:var(--font-mono);color:${marginEst != null && marginEst < 0 ? 'var(--red)' : 'var(--text)'}">${money(marginEst)}</strong></div>
      <div><span style="color:var(--muted)">Contract − cost to date</span> <strong style="font-family:var(--font-mono);color:${marginRun != null && marginRun < 0 ? 'var(--red)' : 'var(--green)'}">${money(marginRun)}</strong> <span style="font-size:10px;color:var(--subtle)">(labour + PO commitments so far — not final margin)</span></div>
    </div>`;
  if (!est.any) {
    html += `<div style="margin-top:8px;font-size:11px;color:var(--accent)">No estimated costs on the attached quote(s) yet — open the quote in QB and save once to publish its cost breakdown here.</div>`;
  }
  body.innerHTML = html;
}

// Native jsPDF one-pager of the costing table (CLAUDE.md PDF rules).
async function exportJobCostingPDF() {
  const JsPDFCtor = await resolveJsPDFCtor();
  const proj = currentProjectRecord || {};
  const est = _jcEstimates();
  const actPo = _projectPoNetTotal, actLab = _projectLabourCostLogged || 0;
  const contract = _sumLineItems();
  await (typeof loadLogoDataUri === 'function' ? loadLogoDataUri() : Promise.resolve());
  const logo = (typeof _logoDataUriCache !== 'undefined' && _logoDataUriCache) || '';
  const doc = new JsPDFCtor({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  const pageW = 210, mL = 14, mR = 14, W = pageW - 28;
  const accent = _houseAccent();
  const TEXT = HOUSE_INK, MUTED = HOUSE_MUTED, RED = [208,2,27], GREEN = [22,140,80], RULE = HOUSE_RULE, HEAD = HOUSE_HEAD;
  const sT = c => doc.setTextColor(c[0],c[1],c[2]);
  const money = v => v == null ? '\u2014' : '\u00A3' + Math.round(v).toLocaleString('en-GB');
  let y = bamaDocHeader(doc, logo, {
    title: 'JOB COSTING', accent, marginL: mL, marginR: mR,
    meta: [
      { label: 'Project:',  value: `${proj.project_number || ''}${proj.project_name ? ' \u2014 ' + proj.project_name : ''}` },
      { label: 'Prepared:', value: new Date().toLocaleDateString('en-GB') }
    ]
  }).y;
  y = bamaSectionHeading(doc, y, 'ESTIMATE VS ACTUAL', { accent, marginL: mL, usableW: W });
  const rows = [
    ['Labour', est.any ? est.labour : null, actLab,
     `${(_sumLabourHoursScheduled()||0).toFixed(0)}h est \u00B7 ${(_projectLabourHoursLogged||0).toFixed(0)}h logged`],
    ['Bought-in (material, finishing, delivery, prelims)', est.any ? est.bought : null, actPo,
     `${_projectPoCount} active POs (nett committed)`],
    ['TOTAL COST', est.any ? est.total : null, actPo == null ? null : actLab + actPo, '']
  ];
  doc.setFontSize(8);
  doc.setFillColor(HEAD[0],HEAD[1],HEAD[2]); doc.rect(mL, y, W, 7, 'F');
  doc.setDrawColor(RULE[0],RULE[1],RULE[2]); doc.setLineWidth(0.2); doc.rect(mL, y, W, 7);
  sT(TEXT); doc.setFont('helvetica','bold');
  doc.text('CATEGORY', mL + 2, y + 4.7);
  doc.text('ESTIMATED', mL + W - 78, y + 4.7, { align: 'right' });
  doc.text('ACTUAL', mL + W - 42, y + 4.7, { align: 'right' });
  doc.text('VARIANCE', mL + W - 2, y + 4.7, { align: 'right' });
  y += 7;
  rows.forEach(([label, e, a, sub], i) => {
    const bold = i === rows.length - 1;
    const rh = sub ? 10 : 8;
    sT(TEXT); doc.setFont('helvetica', bold ? 'bold' : 'normal'); doc.setFontSize(9);
    doc.splitTextToSize(label, W - 90).forEach((l, li) => doc.text(l, mL + 2, y + 4.5 + li * 3.6));
    if (sub) { sT(MUTED); doc.setFontSize(7); doc.text(sub, mL + 2, y + 8.4); }
    sT(TEXT); doc.setFont('helvetica', bold ? 'bold' : 'normal'); doc.setFontSize(9);
    doc.text(money(e), mL + W - 78, y + 4.5, { align: 'right' });
    doc.text(money(a), mL + W - 42, y + 4.5, { align: 'right' });
    if (e != null && a != null && e > 0) {
      const d = a - e; sT(d > 0 ? RED : GREEN);
      doc.text(`${d > 0 ? '+' : '\u2212'}${money(Math.abs(d)).slice(0)} (${d > 0 ? '+' : ''}${Math.round(d / e * 100)}%)`, mL + W - 2, y + 4.5, { align: 'right' });
    } else { sT(MUTED); doc.text('\u2014', mL + W - 2, y + 4.5, { align: 'right' }); }
    doc.setDrawColor(215,218,224); doc.setLineWidth(bold ? 0.5 : 0.15);
    doc.line(mL, y + rh, mL + W, y + rh);
    y += rh;
  });
  y += 8;
  const marginEst = (est.any && contract > 0) ? contract - est.total : null;
  const marginRun = (actPo != null && contract > 0) ? contract - (actLab + actPo) : null;
  sT(TEXT); doc.setFont('helvetica','normal'); doc.setFontSize(9.5);
  doc.text(`Contract value: ${money(contract || null)}     Margin at estimate: ${money(marginEst)}     Contract \u2212 cost to date: ${money(marginRun)}`, mL, y);
  y += 8;
  sT(MUTED); doc.setFontSize(7.5);
  doc.splitTextToSize('Estimated = QB net cost buckets published on quote save. Actual labour = kiosk hours \u00D7 basic rate (S000 excluded, CIS included, no OT uplift). Actual bought-in = nett committed on active POs \u2014 commitments, not supplier invoices, so this leads cash. Contract \u2212 cost to date is not final margin until the job closes.', W).forEach(l => { doc.text(l, mL, y); y += 3.6; });
  bamaDocFooter(doc, { marginL: mL, marginR: mR, size: 7,
    caption: `Job Costing  \u00b7  ${proj.project_number || ''}  \u00b7  BAMA Fabrication Ltd` });
  const blob = doc.output('blob');
  console.log('[JobCosting PDF] blob size:', blob.size);
  doc.save(`Job-Costing-${proj.project_number || 'project'}-${new Date().toISOString().slice(0,10)}.pdf`);
}

function _sumLabourHoursScheduled() {
  // Hours come from the dedicated labour_hours column (transferred from QB's
  // real estimates at mark-won — Fault Register F1). Legacy fallback: on rows
  // predating the column, the old convention was hours-in-quantity, but ONLY
  // when quantity>1 (the qty=1 seed pattern was meaningless, not 1 hour).
  let total = 0;
  for (const q of _projectFinancials.quotes) {
    for (const li of (q._lineItems || [])) {
      if (!li.is_labour) continue;
      if (li.labour_hours != null && li.labour_hours !== '') {
        total += parseFloat(li.labour_hours) || 0;
      } else {
        const qty = parseFloat(li.quantity) || 0;
        if (qty > 1) total += qty;   // legacy hand-entered hours
      }
    }
  }
  return total;
}

// Cache of running (logged) labour hours + cost for the current project.
// Refreshed each time loadProjectFinancials runs.
//
// Cost is sum(hours × employee.rate) across all ProjectHours rows for the
// project, excluding S000 (non-productive time). Flat — no OT multiplier;
// OT is treated as overhead, not project cost, by design. CIS workers ARE
// included (they're labour on the project even though payroll excludes
// them from PAYE/NI runs). Roadmap item #7 — Labour Cost tile pointing at
// actuals instead of the quote-line budget — is closed by this.
let _projectLabourHoursLogged = 0;
let _projectLabourCostLogged  = 0;

// ── Purchase Orders for project detail ──────────────────────────────────────
async function loadProjectPos(projectId) {
  const container = document.getElementById('ptPoList');
  if (!container) return;
  container.innerHTML = '<div style="padding:14px;text-align:center;color:var(--subtle);font-size:12px">Loading…</div>';
  // Clear the Running Cost tile to a neutral state — renderProjectPoList
  // will set it definitively (PO total or '—') once the fetch resolves.
  // This also covers project-switching: stops the previous project's
  // figure lingering while the new fetch is in flight.
  const runningEl = document.getElementById('ptTileRunningValue');
  if (runningEl) runningEl.textContent = '—';
  try {
    const pos = await api.get(`/api/purchase-orders?project_id=${projectId}`);
    renderProjectPoList(pos || []);
  } catch (e) {
    container.innerHTML = '<div style="padding:14px;color:var(--subtle);font-size:12px">Could not load POs.</div>';
    // Leave Running Cost tile at '—' set above.
  }
}

function renderProjectPoList(pos) {
  const container = document.getElementById('ptPoList');
  const totalEl   = document.getElementById('ptPoSpendTotal');
  if (!container) return;

  const active = pos.filter(p => p.status !== 'Cancelled');
  const totalGross = active.reduce((s, p) => s + (Number(p.total_value) || 0), 0);
  const totalNett  = active.reduce((s, p) => s + (_poNet(p) || 0), 0);
  _projectPoNetTotal = totalNett;          // consumed by Job Costing (C1)
  _projectPoCount    = active.length;
  try { renderJobCosting(); } catch (e) { /* card may not be on this page */ }

  if (totalEl) {
    totalEl.textContent = active.length
      ? `${active.length} PO${active.length !== 1 ? 's' : ''} · Nett ${fmtMoneyFull(totalNett)} · Gross ${fmtMoneyFull(totalGross)}`
      : '';
  }

  // Update Running Cost tile with PO spend
  const runningEl = document.getElementById('ptTileRunningValue');
  if (runningEl) runningEl.textContent = active.length ? fmtMoneyFull(totalNett) : '—';
  const runningMeta = document.getElementById('ptTile-running');
  if (runningMeta) {
    const metaEl = runningMeta.querySelector('.pt-tile-meta');
    if (metaEl) metaEl.textContent = active.length
      ? `${active.length} PO${active.length !== 1 ? 's' : ''} · nett spend`
      : 'No POs raised yet';
  }

  if (!active.length && !pos.length) {
    container.innerHTML = '<div style="padding:14px;color:var(--subtle);font-size:12px">No purchase orders raised for this project yet.</div>';
    return;
  }

  const statusColour = { Open: 'var(--accent)', Received: 'var(--yellow)', Closed: 'var(--green)', Cancelled: 'var(--subtle)' };

  container.innerHTML = `
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead>
        <tr style="border-bottom:1px solid var(--border);color:var(--muted);font-size:11px;letter-spacing:.4px;text-transform:uppercase">
          <th style="text-align:left;padding:6px 8px;font-weight:600">PO Ref</th>
          <th style="text-align:left;padding:6px 8px;font-weight:600">Supplier</th>
          <th style="text-align:left;padding:6px 8px;font-weight:600">Description</th>
          <th style="text-align:right;padding:6px 8px;font-weight:600">Nett</th>
          <th style="text-align:right;padding:6px 8px;font-weight:600">Gross</th>
          <th style="text-align:center;padding:6px 8px;font-weight:600">Status</th>
        </tr>
      </thead>
      <tbody>
        ${pos.map(p => {
          const nett  = Number(p.total_value || 0) - Number(p.vat_amount || 0);
          const gross = Number(p.total_value || 0);
          const colour = statusColour[p.status] || 'var(--muted)';
          return `<tr style="border-bottom:1px solid var(--border);cursor:pointer"
                      onclick="openPoDetailModal(${p.id})"
                      onmouseover="this.style.background='var(--bg-light)'"
                      onmouseout="this.style.background=''">
            <td style="padding:7px 8px;font-family:var(--font-mono);color:var(--accent)">${escapeHtml(p.reference)}</td>
            <td style="padding:7px 8px">${escapeHtml(p.supplier_name || '—')}</td>
            <td style="padding:7px 8px;color:var(--muted)">${escapeHtml(p.description || p.job_number || '—')}</td>
            <td style="padding:7px 8px;text-align:right;font-family:var(--font-mono)">${fmtMoneyFull(nett)}</td>
            <td style="padding:7px 8px;text-align:right;font-family:var(--font-mono)">${fmtMoneyFull(gross)}</td>
            <td style="padding:7px 8px;text-align:center">
              <span style="font-size:11px;font-weight:600;color:${colour}">${p.status}</span>
            </td>
          </tr>`;
        }).join('')}
      </tbody>
      <tfoot>
        <tr style="border-top:2px solid var(--border);font-weight:600">
          <td colspan="3" style="padding:7px 8px;color:var(--muted);font-size:12px">
            ${active.length} active PO${active.length !== 1 ? 's' : ''}
          </td>
          <td style="padding:7px 8px;text-align:right;font-family:var(--font-mono)">${fmtMoneyFull(totalNett)}</td>
          <td style="padding:7px 8px;text-align:right;font-family:var(--font-mono)">${fmtMoneyFull(totalGross)}</td>
          <td></td>
        </tr>
      </tfoot>
    </table>`;
}

// Reads actual hours from ProjectHours directly (live data), falling back
// to LabourLog if the primary call fails. ProjectHours is the source of
// truth for the project tracker — LabourLog only has data after a manual
// "Sync to Labour Log" on the payroll page, which would otherwise leave
// the actual-hours tile empty until that step is taken.
//
// Also computes labour cost — sum(hours × employee.rate) across the same
// rows. Rate is looked up via the in-memory employees cache. If a rate
// can't be resolved for an employee, that employee's hours contribute to
// the hours total but £0 to the cost total.
async function _loadLabourHoursLogged(projectNumber) {
  if (!projectNumber) {
    _projectLabourHoursLogged = 0;
    _projectLabourCostLogged  = 0;
    return 0;
  }
  // Build a name+id → rate lookup once.
  const employees = state.timesheetData.employees || [];
  const rateById   = {};
  const rateByName = {};
  for (const e of employees) {
    if (e.id != null)   rateById[e.id]     = Number(e.rate) || 0;
    if (e.name)         rateByName[e.name] = Number(e.rate) || 0;
  }
  const rateFor = row => {
    if (row.employee_id != null && rateById[row.employee_id] !== undefined) return rateById[row.employee_id];
    if (row.employee_name && rateByName[row.employee_name] !== undefined)   return rateByName[row.employee_name];
    return 0;
  };

  try {
    const rows = await api.get(`/api/project-hours?project_number=${encodeURIComponent(projectNumber)}`);
    const filtered = (Array.isArray(rows) ? rows : []).filter(r => r.project_number !== 'S000');
    const totalH = filtered.reduce((sum, r) => sum + (parseFloat(r.hours) || 0), 0);
    const totalC = filtered.reduce((sum, r) => sum + (parseFloat(r.hours) || 0) * rateFor(r), 0);
    _projectLabourHoursLogged = totalH;
    _projectLabourCostLogged  = totalC;
    return totalH;
  } catch (e) {
    console.warn('project-hours fetch failed, falling back to labour-log:', e);
    // Fallback: try LabourLog if project-hours endpoint is unavailable
    try {
      const rows = await api.get(`/api/labour-log?project_number=${encodeURIComponent(projectNumber)}`);
      const list = Array.isArray(rows) ? rows : [];
      const totalH = list.reduce((sum, r) => sum + (parseFloat(r.hours) || 0), 0);
      const totalC = list.reduce((sum, r) => sum + (parseFloat(r.hours) || 0) * rateFor(r), 0);
      _projectLabourHoursLogged = totalH;
      _projectLabourCostLogged  = totalC;
      return totalH;
    } catch (e2) {
      console.warn('labour-log fallback also failed:', e2);
      _projectLabourHoursLogged = 0;
      _projectLabourCostLogged  = 0;
      return 0;
    }
  }
}

function renderProjectFinancialDashboard() {
  const fmtMoney = n => '£' + (n || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const fmtHrs   = n => (n || 0).toLocaleString('en-GB', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + ' h';

  // Tile values
  const contract       = _sumLineItems();
  const labour         = _projectLabourCostLogged;        // actuals: Σ(hours × rate). Roadmap #7.
  const labourBudget   = _sumLineItems(li => !!li.is_labour); // for variance vs quote, when quotes attached
  const hoursScheduled = _sumLabourHoursScheduled();
  const hoursLogged    = _projectLabourHoursLogged;
  const setText = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };

  setText('ptTileContractValue', fmtMoney(contract));
  setText('ptTileLabourValue',   fmtMoney(labour));
  setText('ptTileHoursBudgetValue', hoursScheduled > 0 ? fmtHrs(hoursScheduled) : '—');
  setText('ptTileHoursActualValue', fmtHrs(hoursLogged));
  // ⚠️ Do NOT touch ptTileRunningValue here — it's owned by loadProjectPos()
  // which runs in parallel. Writing '—' clobbers the PO total whenever this
  // function happens to finish second.

  // Tile meta
  const nq = _projectFinancials.quotes.length;
  setText('ptTileContractMeta', `${nq} ${nq === 1 ? 'quote' : 'quotes'} attached`);

  // Labour Cost meta — show variance vs quote budget if we have one, else show "actuals from logged hours"
  let labourMeta;
  if (labourBudget > 0) {
    const pctOfBudget = (labour / labourBudget) * 100;
    labourMeta = `${pctOfBudget.toFixed(0)}% of labour budget (${fmtMoney(labourBudget)})`;
  } else if (hoursLogged > 0) {
    labourMeta = `Actual: ${fmtHrs(hoursLogged)} logged @ basic rate`;
  } else {
    labourMeta = 'No hours logged yet';
  }
  setText('ptTileLabourMeta', labourMeta);

  // Project progress bar inside Labour Cost tile — shown when contract value exists
  const progressPct = _weightedProjectProgress();
  const progWrap = document.getElementById('ptTileProgressWrap');
  const progFill = document.getElementById('ptTileProgressFill');
  const progNum  = document.getElementById('ptTileProgressNum');
  if (progWrap && progFill && progNum) {
    if (contract > 0) {
      progWrap.style.display = '';
      progFill.style.width = Math.max(0, Math.min(100, progPct(progressPct))) + '%';
      progNum.textContent  = progressPct.toFixed(0) + '%';
    } else {
      progWrap.style.display = 'none';
    }
  }

  // Hours scheduled meta (sum across N labour lines)
  let labourLineCount = 0;
  for (const q of _projectFinancials.quotes) {
    for (const li of (q._lineItems || [])) if (li.is_labour) labourLineCount++;
  }
  setText('ptTileHoursBudgetMeta', hoursScheduled > 0
    ? `Across ${labourLineCount} labour ${labourLineCount === 1 ? 'line' : 'lines'}`
    : 'No labour-flagged lines yet');

  // Hours logged tile — variance vs scheduled, plus over-budget flag
  const hoursActualTile = document.getElementById('ptTile-hoursActual');
  const variancePct = hoursScheduled > 0 ? (hoursLogged / hoursScheduled) * 100 : 0;
  setText('ptTileHoursActualMeta', hoursScheduled > 0
    ? `${variancePct.toFixed(0)}% of scheduled hours used`
    : (hoursLogged > 0 ? 'No scheduled hours to compare' : 'No hours logged yet'));

  const varWrap = document.getElementById('ptTileHoursVarianceWrap');
  const varFill = document.getElementById('ptTileHoursVarianceFill');
  const varNum  = document.getElementById('ptTileHoursVarianceNum');
  if (varWrap && varFill && varNum) {
    if (hoursScheduled > 0) {
      varWrap.style.display = '';
      // The bar fills up to 100% of scheduled. Anything over flips the tile red
      // but the visual bar still pegs at 100% to convey "over budget".
      const pct = Math.min(100, variancePct);
      varFill.style.width = pct + '%';
      varNum.textContent  = variancePct.toFixed(0) + '%';
    } else {
      varWrap.style.display = 'none';
    }
  }
  if (hoursActualTile) {
    hoursActualTile.classList.toggle('over-budget', hoursScheduled > 0 && hoursLogged > hoursScheduled);
  }

  // Per-quote tables
  const container = document.getElementById('ptQuotesContainer');
  if (!container) return;
  if (!_projectFinancials.quotes.length) {
    container.innerHTML = `
      <div style="padding:18px;text-align:center;color:var(--subtle);font-size:13px">
        No quotes attached. Use <strong>+ Add Quote</strong> to attach won quotes
        and feed the financial tiles.
      </div>`;
    return;
  }

  container.innerHTML = _projectFinancials.quotes.map(q => {
    const scope = (q.quote_comments || '').trim();
    const lines = q._lineItems || [];
    const linesHtml = lines.map(li => {
      const qty   = parseFloat(li.quantity)   || 0;
      const price = parseFloat(li.unit_price) || 0;
      const excl  = qty * price;
      const pct   = _projectFinancials.progress[li.id] || 0;
      const earned = excl * (pct / 100);
      const labelTag = li.is_labour
        ? '<span style="font-size:10px;color:var(--accent2);margin-left:6px">LABOUR</span>'
        : '';
      return `
        <div class="pt-line-grid pt-line-row${li.is_labour ? ' pt-line-labour' : ''}" data-line-id="${li.id}">
          <div class="pt-num">${li.line_no}</div>
          <div>${escapeHtml(li.description || '')}${labelTag}</div>
          <div class="pt-amount">${qty.toFixed(2)}</div>
          <div class="pt-amount">£${price.toFixed(2)}</div>
          <div class="pt-amount">£${excl.toFixed(2)}</div>
          <div style="display:flex;align-items:center;gap:8px">
            <div class="pt-progress-bar" style="flex:1"><div class="pt-progress-fill" style="width:${pct}%"></div></div>
            <input type="number" class="pt-progress-input" min="0" max="100" step="1" value="${pct}" onchange="onProjectLineProgressChange(${li.id}, this.value)" title="${escapeHtml('£' + earned.toFixed(2) + ' earned')}">
          </div>
          <div style="text-align:right;color:var(--subtle);font-family:var(--font-mono)">${pct.toFixed(0)}%</div>
        </div>
      `;
    }).join('');

    const exclTotal = lines.reduce((sum, li) => sum + ((parseFloat(li.quantity) || 0) * (parseFloat(li.unit_price) || 0)), 0);
    const labourTotal = lines.filter(li => li.is_labour).reduce((sum, li) => sum + ((parseFloat(li.quantity) || 0) * (parseFloat(li.unit_price) || 0)), 0);

    return `
      <div class="pt-quote-block" data-tender-id="${q.tender_id}">
        <div class="pt-quote-block-head">
          <div>
            <span class="pt-quote-ref">${escapeHtml(q.reference || 'Q?')}</span>
            ${q.is_primary ? '<span style="font-size:10px;color:var(--accent);margin-left:8px;letter-spacing:.5px">PRIMARY</span>' : ''}
            <span style="font-size:12px;color:var(--muted);margin-left:8px">${escapeHtml(q.quote_project_name || '')}</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px">
            <span style="font-size:11px;color:var(--subtle)">Excl. £${exclTotal.toFixed(2)} • Labour £${labourTotal.toFixed(2)}</span>
            ${q.is_primary
              ? ''
              : `<button class="btn btn-ghost" style="font-size:11px;padding:4px 10px" onclick="detachProjectQuote('${q.qb_quote_id != null && q.tender_id == null ? 'qb:' + q.qb_quote_id : q.tender_id}')">Detach</button>`}
          </div>
        </div>
        ${scope ? `<div class="pt-quote-scope">${escapeHtml(scope)}</div>` : ''}
        <div class="pt-line-grid pt-line-header">
          <div>#</div><div>Line</div>
          <div style="text-align:right">Qty</div>
          <div style="text-align:right">Unit</div>
          <div style="text-align:right">Excl.</div>
          <div>Progress</div>
          <div style="text-align:right">%</div>
        </div>
        ${linesHtml || '<div style="padding:12px;color:var(--subtle);font-size:12px">No line items captured for this quote.</div>'}
      </div>
    `;
  }).join('');
}

// Tiny clamp helper for the progress fill
function progPct(v) { return Math.max(0, Math.min(100, v)); }

// Throttled saver — when the user fiddles with a progress slider quickly we
// don't want to hammer the API on every keystroke.
const _progressSaveTimers = {};
async function onProjectLineProgressChange(quoteLineItemId, value) {
  if (!currentProjectRecord) return;
  const pct = Math.max(0, Math.min(100, parseFloat(value) || 0));
  _projectFinancials.progress[quoteLineItemId] = pct;

  // Cheap re-render of the affected row's bar + tiles only.
  const row = document.querySelector(`#ptQuotesContainer .pt-line-row[data-line-id="${quoteLineItemId}"]`);
  if (row) {
    const fill = row.querySelector('.pt-progress-fill');
    if (fill) fill.style.width = pct + '%';
    const numCell = row.children[6];
    if (numCell) numCell.textContent = pct.toFixed(0) + '%';
  }
  // Update the labour tile's secondary text + project progress bar inside the tile.
  const projPct = _weightedProjectProgress();
  const meta = document.getElementById('ptTileLabourMeta');
  if (meta) meta.textContent = `${projPct.toFixed(0)}% project progress (value-weighted)`;
  const tileFill = document.getElementById('ptTileProgressFill');
  const tileNum  = document.getElementById('ptTileProgressNum');
  if (tileFill) tileFill.style.width = Math.max(0, Math.min(100, projPct)) + '%';
  if (tileNum)  tileNum.textContent  = projPct.toFixed(0) + '%';

  // Debounce the network write — 600ms after the last change.
  clearTimeout(_progressSaveTimers[quoteLineItemId]);
  _progressSaveTimers[quoteLineItemId] = setTimeout(async () => {
    try {
      await api.put('/api/project-line-progress', {
        project_id: currentProjectRecord.id,
        quote_line_item_id: quoteLineItemId,
        percent_complete: pct,
        last_updated_by: currentManagerUser || null
      });
    } catch (err) {
      toast('Could not save progress: ' + err.message, 'error');
    }
  }, 600);
}

async function detachProjectQuote(ref) {
  if (!currentProjectRecord) return;
  const refStr = String(ref);
  const isQb = refStr.startsWith('qb:');
  const q = isQb
    ? _projectFinancials.quotes.find(x => String(x.qb_quote_id) === refStr.slice(3))
    : _projectFinancials.quotes.find(x => String(x.tender_id) === refStr);
  if (q && q.is_primary) { toast('Cannot detach the primary quote', 'error'); return; }
  const note = isQb
    ? 'Its line items will be removed too, so re-attaching will pull fresh values from the quote.'
    : 'Its line items remain on the quote — only the link is removed. Per-line progress on this project will be orphaned.';
  const ok = await showConfirmAsync(
    'Detach this quote?',
    `Quote <strong>${escapeHtml(q?.reference || '')}</strong> will be removed from this project. ${note}`,
    { okLabel: 'Detach', danger: true }
  );
  if (!ok) return;
  try {
    await api.delete(`/api/project-quotes/${currentProjectRecord.id}/${encodeURIComponent(refStr)}`);
    await loadProjectFinancials(currentProjectRecord.id);
    toast('Quote detached', 'success');
  } catch (err) {
    toast('Detach failed: ' + err.message, 'error');
  }
}

// ── Attach Quote modal ──
let _attachQuoteCandidates = [];

async function openAttachQuoteModal() {
  if (!currentProjectRecord) return;
  document.getElementById('aqSearch').value = '';
  document.getElementById('aqList').innerHTML = '<div style="padding:14px;text-align:center;color:var(--subtle);font-size:12px">Loading…</div>';
  document.getElementById('attachQuoteModal').classList.add('active');

  // Pull won quotes that aren't already attached.
  let allWon = [];
  try {
    allWon = await api.get('/api/tenders?status=won');
  } catch (e) {
    document.getElementById('aqList').innerHTML = '<div style="padding:14px;color:var(--subtle);font-size:12px">Could not load quotes.</div>';
    return;
  }
  const attachedIds = new Set(_projectFinancials.quotes.map(q => q.tender_id));
  _attachQuoteCandidates = (allWon || []).filter(t => !attachedIds.has(t.id));
  renderAttachQuoteList();
}

function renderAttachQuoteList() {
  const term = (document.getElementById('aqSearch')?.value || '').toLowerCase().trim();
  const filtered = _attachQuoteCandidates.filter(t => {
    if (!term) return true;
    const hay = `${t.reference || ''} ${t.project_name || ''} ${t.company_name || ''}`.toLowerCase();
    return hay.includes(term);
  });
  const list = document.getElementById('aqList');
  if (!list) return;
  if (!filtered.length) {
    list.innerHTML = '<div style="padding:14px;text-align:center;color:var(--subtle);font-size:12px">No matching won quotes available to attach.</div>';
    return;
  }
  list.innerHTML = filtered.map(t => `
    <div class="aq-row" onclick="confirmAttachQuote(${t.id})">
      <div><span class="aq-ref">${escapeHtml(t.reference || '')}</span> <span style="color:var(--text);font-size:13px">${escapeHtml(t.project_name || '')}</span></div>
      <div class="aq-meta">${escapeHtml(t.company_name || '')} • Value £${(parseFloat(t.value) || 0).toFixed(2)}</div>
    </div>
  `).join('');
}
function filterAttachQuoteList() { renderAttachQuoteList(); }
function closeAttachQuoteModal() { document.getElementById('attachQuoteModal').classList.remove('active'); }

async function confirmAttachQuote(tenderId) {
  if (!currentProjectRecord) return;
  try {
    await api.post('/api/project-quotes', {
      project_id: currentProjectRecord.id,
      tender_id: tenderId,
      is_primary: false,
      added_by: currentManagerUser || null
    });
    closeAttachQuoteModal();
    await loadProjectFinancials(currentProjectRecord.id);
    toast('Quote attached ✓', 'success');
  } catch (err) {
    toast('Attach failed: ' + err.message, 'error');
  }
}

// ═══════════════════════════════════════════
// CREATE NEW PROJECT (manual, no source quote)
// ═══════════════════════════════════════════
// Mints the next available C-reference, creates the SharePoint folder
// structure (same 9 subfolders as the Won-quote path), creates or finds
// the client, and writes the Project row. Mirrors convertQuoteToProject
// but starts from form input instead of a tender. source_quote_id is left
// null and ProjectQuotes is not seeded — a quote can be attached later
// via the "+ Add Quote" button on the project detail page.

let _npClientSearchTimeout = null;

async function getNextProjectNumber() {
  const yy = String(new Date().getFullYear()).slice(-2); // "26"
  const prefix = `C${yy}`;
  let highest = 0;

  // Scan loaded projectsData (covers both manual and quote-derived projects).
  // Quote-derived projects come in as e.g. C260502 (from Q260502); manual
  // projects mint sequentially from the same pool, so we scan all C{yy}*.
  const re = new RegExp(`^${prefix}(\\d+)$`);
  (projectsData || []).forEach(p => {
    const m = String(p.project_number || '').match(re);
    if (m) {
      const n = parseInt(m[1], 10);
      if (n > highest) highest = n;
    }
  });

  return `${prefix}${String(highest + 1).padStart(2, '0')}`;
}

async function openCreateProjectModal() {
  const perms = getUserPermissions(currentManagerUser);
  if (!perms || !perms.editProjects) {
    toast("You don't have permission to create projects", 'error');
    return;
  }

  // Make sure clients are loaded for autocomplete (project-tracker page
  // doesn't load them by default — only tenders/quotes pages do).
  if (!clientsData.length) {
    try {
      const clients = await api.get('/api/clients');
      clientsData = clients || [];
    } catch (e) {
      console.warn('Failed to load clients for autocomplete:', e);
    }
  }

  // Reset all form fields
  ['npClientId','npCompanyName','npAddress1','npAddress2','npCity','npCounty','npPostcode',
   'npContactName','npContactEmail','npContactPhone',
   'npProjectName','npQuoteValue','npComments','npDeadline',
   'npSiteAddressLine1','npSiteAddressLine2','npSiteCity','npSiteCounty','npSitePostcode',
   'npSiteContactName','npSiteContactEmail','npSiteContactPhone'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });

  // Default site-same toggle to ON, hide site fields
  const siteSame = document.getElementById('npSiteSameAsClient');
  if (siteSame) siteSame.checked = true;
  const siteFields = document.getElementById('npSiteFields');
  if (siteFields) siteFields.style.display = 'none';

  // Default start date to today (matches new-tender default behaviour)
  const today = new Date();
  const todayStr = `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;
  const startEl = document.getElementById('npStartDate');
  if (startEl) startEl.value = todayStr;

  document.getElementById('npClientSuggestions').style.display = 'none';

  // Generate next project number (default — user can override for legacy/existing projects)
  const npRefEl = document.getElementById('npProjectNumber');
  try {
    const ref = await getNextProjectNumber();
    npRefEl.value = ref;
  } catch (e) {
    console.error('Project number generation failed:', e);
    npRefEl.value = '';
  }
  onNpProjectNumberChange(); // seed the hint text

  document.getElementById('newProjectModal').classList.add('active');
}

function closeCreateProjectModal() {
  document.getElementById('newProjectModal').classList.remove('active');
}

// Auto-uppercase + drive the hint that tells the user whether SharePoint
// folders will be created. S-prefix = legacy/existing project (folders
// already live somewhere in the SharePoint tree, so we skip creation).
// Anything else (default C-prefix or a custom value) = brand new project,
// folder structure gets created automatically.
function onNpProjectNumberChange() {
  const el = document.getElementById('npProjectNumber');
  if (!el) return;

  // Uppercase as the user types, preserving cursor position
  const upper = el.value.toUpperCase();
  if (upper !== el.value) {
    const pos = el.selectionStart;
    el.value = upper;
    try { el.setSelectionRange(pos, pos); } catch (_) {}
  }

  const hint = document.getElementById('npProjectNumberHint');
  if (!hint) return;
  const val = el.value.trim();

  if (!val) {
    hint.innerHTML = '<span style="color:var(--red)">A project number is required.</span>';
  } else if (/^S/.test(val)) {
    hint.innerHTML = '<span style="color:var(--accent2)"><strong>Existing project</strong> — SharePoint folders will <strong>not</strong> be created. The folder is assumed to already exist in the legacy tree.</span>';
  } else {
    hint.innerHTML = '<span style="color:var(--muted)">New project — the standard SharePoint folder structure will be created automatically.</span>';
  }
}

function onNpClientSearch(value) {
  clearTimeout(_npClientSearchTimeout);
  const dropdown = document.getElementById('npClientSuggestions');

  if (!value || value.length < 2) {
    dropdown.style.display = 'none';
    document.getElementById('npClientId').value = '';
    return;
  }

  _npClientSearchTimeout = setTimeout(() => {
    const matches = clientsData.filter(c =>
      c.company_name && c.company_name.toLowerCase().includes(value.toLowerCase())
    );

    if (!matches.length) {
      dropdown.style.display = 'none';
      document.getElementById('npClientId').value = '';
      return;
    }

    dropdown.innerHTML = matches.map(c => `
      <div class="autocomplete-item" onclick="selectNpClient(${c.id})">
        <div class="ac-company">${escapeHtml(c.company_name)}</div>
        <div class="ac-contact">${escapeHtml(c.contact_name || '')} ${c.contact_email ? '· ' + escapeHtml(c.contact_email) : ''}</div>
      </div>
    `).join('');
    dropdown.style.display = '';
  }, 200);
}

function selectNpClient(clientId) {
  const client = clientsData.find(c => c.id === clientId);
  if (!client) return;

  document.getElementById('npClientId').value = client.id;
  document.getElementById('npCompanyName').value = client.company_name;
  document.getElementById('npAddress1').value = client.address_line1 || '';
  document.getElementById('npAddress2').value = client.address_line2 || '';
  document.getElementById('npCity').value = client.city || '';
  document.getElementById('npCounty').value = client.county || '';
  document.getElementById('npPostcode').value = client.postcode || '';
  // Contact fields left blank — they vary per project/site
  document.getElementById('npContactName').value = '';
  document.getElementById('npContactEmail').value = '';
  document.getElementById('npContactPhone').value = '';
  document.getElementById('npClientSuggestions').style.display = 'none';
}

function onNpSiteSameToggle() {
  const same = document.getElementById('npSiteSameAsClient').checked;
  document.getElementById('npSiteFields').style.display = same ? 'none' : '';
}

async function submitCreateProject() {
  const projectNumber = document.getElementById('npProjectNumber').value.trim();
  const companyName   = document.getElementById('npCompanyName').value.trim();
  const projectName   = document.getElementById('npProjectName').value.trim();

  if (!projectNumber || projectNumber === '—') { toast('Project number could not be generated', 'error'); return; }
  if (!companyName) { toast('Client / company name is required', 'error'); return; }
  if (!projectName) { toast('Project name is required', 'error'); return; }

  const submitBtn = document.getElementById('npSubmitBtn');
  if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = 'Creating…'; }

  try {
    // Step 1: Create or find client
    let clientId = document.getElementById('npClientId').value;
    let clientRecord = null;

    if (!clientId) {
      // New client — create it
      clientRecord = await api.post('/api/clients', {
        company_name:  companyName,
        address_line1: document.getElementById('npAddress1').value.trim() || null,
        address_line2: document.getElementById('npAddress2').value.trim() || null,
        city:          document.getElementById('npCity').value.trim() || null,
        county:        document.getElementById('npCounty').value.trim() || null,
        postcode:      document.getElementById('npPostcode').value.trim() || null,
        contact_name:  document.getElementById('npContactName').value.trim() || null,
        contact_email: document.getElementById('npContactEmail').value.trim() || null,
        contact_phone: document.getElementById('npContactPhone').value.trim() || null
      });
      clientId = clientRecord.id;
      clientsData.push(clientRecord);
    } else {
      clientRecord = clientsData.find(c => String(c.id) === String(clientId)) || null;
    }

    // Step 2: Create SharePoint folder structure — but ONLY for new projects.
    // S-prefix means the project already lives in the legacy folder tree, so
    // we skip creation and leave sharepoint_folder_id NULL. The project detail
    // page handles a missing folder ID gracefully (the "Open SharePoint" link
    // just won't appear).
    let projectFolderId = null;
    const isExistingLegacyProject = /^S/i.test(projectNumber);

    if (!isExistingLegacyProject) {
      try {
        const token = await getToken();
        // BC-prefixed (Babcock) projects live in <year>/01 - Babcock; everything
        // else sits directly in the year folder.
        const projectsRoot = /^BC/i.test(projectNumber)
          ? await spBabcockProjectParent()
          : await spNewProjectParent();
        const clientPart  = sanitiseFolderSegment(companyName);
        const projectPart = sanitiseFolderSegment(projectName);
        const folderName  = [projectNumber, clientPart, projectPart].filter(Boolean).join(' - ');
        const projectFolder = await createFolderInDrive(projectsRoot.id, folderName);
        projectFolderId = projectFolder.id;

        // Standard 9 subfolders. createFolderInDrive now retries transient
        // Graph throttling/5xx internally; any folder that still fails after
        // retries is collected and surfaced rather than silently skipped.
        const failedSubs = [];
        for (const sub of PROJECT_SUBFOLDERS) {
          try {
            await createFolderInDrive(projectFolder.id, sub);
          } catch (e) {
            console.warn(`Subfolder "${sub}" creation failed:`, e);
            failedSubs.push(sub);
          }
        }
        if (failedSubs.length) {
          toast(`Project created, but these folders failed: ${failedSubs.join(', ')} — open SharePoint and add them manually`, 'warning');
        }
      } catch (e) {
        console.warn('SharePoint folder creation failed (non-fatal):', e);
        toast('Project created, but SharePoint folders could not be created — check your access', 'warning');
      }
    }

    // Step 3: Build site address payload (PUT it after the create to set
    // the site_* columns — the POST handler doesn't accept them, but PUT does).
    const siteSame = document.getElementById('npSiteSameAsClient').checked;
    const sitePayload = siteSame
      ? {
          site_same_as_client: 1,
          site_address_line1: null, site_address_line2: null,
          site_city: null, site_county: null, site_postcode: null,
          site_contact_name: null, site_contact_email: null, site_contact_phone: null
        }
      : {
          site_same_as_client: 0,
          site_address_line1: document.getElementById('npSiteAddressLine1').value.trim() || null,
          site_address_line2: document.getElementById('npSiteAddressLine2').value.trim() || null,
          site_city:          document.getElementById('npSiteCity').value.trim() || null,
          site_county:        document.getElementById('npSiteCounty').value.trim() || null,
          site_postcode:      document.getElementById('npSitePostcode').value.trim() || null,
          site_contact_name:  document.getElementById('npSiteContactName').value.trim() || null,
          site_contact_email: document.getElementById('npSiteContactEmail').value.trim() || null,
          site_contact_phone: document.getElementById('npSiteContactPhone').value.trim() || null
        };

    // Step 4: Create the Projects DB row
    const quoteValueRaw = document.getElementById('npQuoteValue').value.trim();
    const deadline      = document.getElementById('npDeadline').value;
    const startDate     = document.getElementById('npStartDate').value;

    const created = await api.post('/api/projects', {
      project_number: projectNumber,
      project_name:   projectName,
      client_id:      parseInt(clientId),
      status:         'In Progress',
      source_quote_id: null,
      quote_value:    quoteValueRaw ? parseFloat(quoteValueRaw) : null,
      deadline_date:  deadline || null,
      start_date:     startDate || null,
      comments:       document.getElementById('npComments').value.trim() || null,
      sharepoint_folder_id: projectFolderId,
      sharepoint_quote_folder_id: null,
      created_by:     currentManagerUser || (typeof AUTH !== 'undefined' && AUTH.getUserName?.()) || 'unknown'
    });

    // Step 5: PUT the site address fields. The PUT handler returns the row
    // joined with client data (company_name etc), so we use its response.
    let project = created;
    try {
      const updated = await api.put(`/api/projects/${created.id}`, sitePayload);
      if (updated && updated.id) project = updated;
    } catch (e) {
      console.warn('Site address update failed:', e);
      // Non-fatal — the project exists, the user can edit site fields on the detail page.
    }

    // Step 6: Auto-save contact to ClientContacts (deduped server-side by name+email).
    //   Mirrors the behaviour of the new-tender flow.
    const contactName  = document.getElementById('npContactName').value.trim();
    const contactEmail = document.getElementById('npContactEmail').value.trim();
    const contactPhone = document.getElementById('npContactPhone').value.trim();
    if (contactName || contactEmail || contactPhone) {
      try {
        await api.post('/api/client-contacts', {
          client_id:     parseInt(clientId),
          contact_name:  contactName  || null,
          contact_email: contactEmail || null,
          contact_phone: contactPhone || null
        });
      } catch (e) {
        console.warn('Failed to save contact to client database:', e);
      }
    }

    // Step 7: Patch local state and refresh UI. Make sure company_name is
    // populated so the list row renders correctly without a full refetch.
    if (!project.company_name) project.company_name = companyName;
    projectsData.unshift(project);

    closeCreateProjectModal();
    renderProjectTrackerList();
    if (isExistingLegacyProject) {
      toast(`Existing project ${projectNumber} added ✓`, 'success');
    } else {
      toast(`Project ${projectNumber} created ✓`, 'success');
    }

    // Jump straight to the new project's detail view.
    setTimeout(() => openProjectTrackerDetail(project.id), 100);
  } catch (err) {
    console.error('Failed to create project:', err);
    toast('Failed to create project: ' + (err.message || 'unknown error'), 'error');
  } finally {
    if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = 'Create Project'; }
  }
}

// ── Project Tracker page init ──
async function initProjectTrackerPage() {
  // Re-use the manager PIN gate pattern. The page will require viewProjects permission.
  const authed = pinSessionGet();
  if (authed) {
    currentManagerUser = authed;
    const perms = getUserPermissions(currentManagerUser);
    if (perms && (perms.viewProjects || perms.editProjects)) {
      document.getElementById('screenProjectTrackerSelect').style.display = 'none';
      document.getElementById('projectTrackerLayout').style.display = 'flex';
      renderUnifiedSidebar();
      await loadProjectsData();
      renderProjectTrackerList();
      return;
    }
  }
  // Otherwise show login screen
  renderProjectTrackerEmployeeGrid();
}

function renderProjectTrackerEmployeeGrid() {
  const grid = document.getElementById('projectTrackerEmployeeGrid');
  if (!grid) return;

  // Mirror the tender/quotes pattern: office staff only.
  const empList = (state.timesheetData.employees || []).filter(e => e.active !== false && (e.staffType || 'workshop') === 'office');

  if (!empList.length) {
    grid.innerHTML = '<div class="empty-state" style="padding:30px"><div style="font-size:28px;margin-bottom:10px">&#128101;</div><div>No office staff set up yet.</div><div style="margin-top:8px;font-size:12px;color:var(--subtle)">Go to Manager → Staff to add office employees.</div></div>';
    return;
  }

  grid.innerHTML = empList.map(emp => {
    const ini = (emp.name || '').split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
    const col = empColor(emp.name);
    return `
      <div class="emp-btn" onclick="selectProjectTrackerUser('${emp.name.replace(/'/g, "\\\\'")}')" style="padding:22px 14px 16px">
        <div class="emp-avatar" style="width:48px;height:48px;font-size:19px;background:linear-gradient(135deg,${col},#3e1a00)">${ini}</div>
        <div class="emp-name" style="font-size:13px">${emp.name}</div>
        <div style="font-size:10px;color:var(--subtle);margin-top:3px">${emp.hasPin ? '&#128274; PIN set' : '&#128275; No PIN'}</div>
      </div>
    `;
  }).join('');
}

function selectProjectTrackerUser(name) {
  _pendingManagerUser = name;
  document.getElementById('projectTrackerPinUser').textContent = name;
  document.getElementById('projectTrackerPinInput').value = '';
  document.getElementById('projectTrackerPinError').textContent = '';
  document.getElementById('projectTrackerPinModal').classList.add('active');
  setTimeout(() => document.getElementById('projectTrackerPinInput')?.focus(), 50);
}

async function verifyProjectTrackerPin() {
  const name = _pendingManagerUser;
  const pin = document.getElementById('projectTrackerPinInput').value.trim();
  const errEl = document.getElementById('projectTrackerPinError');
  errEl.textContent = '';
  if (!pin) { errEl.textContent = 'Enter your PIN'; return; }

  try {
    const employee = (state.timesheetData?.employees || []).find(e => e.name === name);
    if (!employee) { errEl.textContent = 'Employee not found'; return; }
    const result = await api.post('/api/auth/verify-pin', { employee_id: employee.id, pin });
    if (!result.valid) { errEl.textContent = 'Incorrect PIN'; return; }

    const perms = getUserPermissions(name);
    if (!perms || (!perms.viewProjects && !perms.editProjects)) {
      errEl.textContent = 'You don\'t have permission to view projects';
      return;
    }

    currentManagerUser = name;
    pinSessionSet(name);
    document.getElementById('projectTrackerPinModal').classList.remove('active');
    document.getElementById('screenProjectTrackerSelect').style.display = 'none';
    document.getElementById('projectTrackerLayout').style.display = 'flex';

    renderUnifiedSidebar();
    await loadProjectsData();
    renderProjectTrackerList();
  } catch (err) {
    errEl.textContent = 'PIN verification failed';
  }
}

function switchProjectTrackerTab(tab) {
  document.querySelectorAll('#projectTrackerLayout .sidebar-nav-item').forEach(b => b.classList.remove('active'));
  document.querySelector(`#projectTrackerLayout .sidebar-nav-item[data-tab="${tab}"]`)?.classList.add('active');

  document.querySelectorAll('#projectTrackerLayout .tab-content').forEach(el => {
    el.classList.remove('active'); el.style.display = 'none';
  });
  const target = document.getElementById(`tab-${tab}`);
  if (target) { target.style.display = ''; target.classList.add('active'); }

  if (tab === 'projectTrackerList') renderProjectTrackerList();
}

