// ═══════════════════════════════════════════════════════════════════════════
// PRODUCTIVITY GRID — who did what, per day (Phase C1b)
// ═══════════════════════════════════════════════════════════════════════════
// Person × date (or job × date) matrix from kiosk ProjectHours: each cell
// lists job numbers + hours for that day. Dates only, no clock times, by
// design — the point is output per person per job, not attendance policing.
let _pgRows = null, _pgMeta = null;

async function renderProductivityReport(run) {
  const grid = document.getElementById('pgGrid');
  if (!grid) return;
  const fromEl = document.getElementById('pgFrom'), toEl = document.getElementById('pgTo');
  if (fromEl && !fromEl.value) {
    const t = new Date(); const f = new Date(t.getTime() - 13 * 86400000);
    fromEl.value = f.toISOString().slice(0, 10);
    toEl.value   = t.toISOString().slice(0, 10);
  }
  if (!run && !_pgRows) return;   // panel opened — wait for explicit Run
  const from = fromEl?.value, to = toEl?.value;
  if (!from || !to || from > to) { grid.innerHTML = '<div style="padding:20px;color:var(--red);font-size:12px">Pick a valid date range.</div>'; return; }
  const days = Math.round((new Date(to) - new Date(from)) / 86400000) + 1;
  if (days > 31) { grid.innerHTML = '<div style="padding:20px;color:var(--red);font-size:12px">Range capped at 31 days — narrow the dates.</div>'; return; }

  if (run) {
    grid.innerHTML = '<div style="padding:30px;text-align:center;color:var(--muted);font-size:12px">Loading…</div>';
    try {
      _pgRows = await api.get(`/api/project-hours?from=${from}&to=${to}`);
      _pgMeta = { from, to };
    } catch (e) {
      grid.innerHTML = `<div style="padding:20px;color:var(--red);font-size:12px">Could not load hours: ${escapeHtml(e.message)}</div>`;
      return;
    }
  }

  const incS000 = document.getElementById('pgIncS000')?.checked;
  const view = document.getElementById('pgView')?.value || 'person';
  const rows = (_pgRows || []).filter(r => incS000 || r.project_number !== 'S000');

  // date columns
  const dates = [];
  for (let d = new Date(_pgMeta.from + 'T12:00:00'); d <= new Date(_pgMeta.to + 'T12:00:00'); d = new Date(d.getTime() + 86400000)) {
    dates.push(d.toISOString().slice(0, 10));
  }
  const dayName = iso => new Date(iso + 'T12:00:00').toLocaleDateString('en-GB', { weekday: 'short' });
  const isWeekend = iso => [0, 6].includes(new Date(iso + 'T12:00:00').getDay());

  // Consistent colour per job — hash → hue, so S1996 is the SAME colour on
  // every row, every day, every run. Legend below the grid.
  const jobHue = key => {
    let h = 0; const s = String(key);
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    return h % 360;
  };
  const chipStyle = key => {
    const hue = jobHue(key);
    return `display:inline-flex;align-items:center;gap:4px;padding:1px 7px;border-radius:20px;` +
           `background:hsla(${hue},70%,55%,.14);border:1px solid hsla(${hue},70%,60%,.45);` +
           `color:hsl(${hue},75%,72%);font-size:10.5px;line-height:1.7;white-space:nowrap`;
  };

  // matrix[rowKey][date] = { cellKey: hours }
  const matrix = {}, rowTotals = {}, dayTotals = {}, jobTotals = {};
  for (const r of rows) {
    const date = String(r.date).slice(0, 10);
    const rowKey = view === 'person' ? (r.employee_name || 'Unknown') : (r.project_number || '—');
    const cellKey = view === 'person' ? (r.project_number || '—') : (r.employee_name || 'Unknown');
    const h = parseFloat(r.hours) || 0;
    ((matrix[rowKey] = matrix[rowKey] || {})[date] = matrix[rowKey][date] || {});
    matrix[rowKey][date][cellKey] = (matrix[rowKey][date][cellKey] || 0) + h;
    rowTotals[rowKey] = (rowTotals[rowKey] || 0) + h;
    dayTotals[date]   = (dayTotals[date]   || 0) + h;
    const jobKey = r.project_number || '—';
    jobTotals[jobKey] = (jobTotals[jobKey] || 0) + h;
  }
  const rowKeys = Object.keys(matrix).sort();
  if (!rowKeys.length) { grid.innerHTML = '<div style="padding:20px;color:var(--muted);font-size:12px">No hours in this range.</div>'; return; }

  const csvBtn = document.getElementById('pgCsvBtn'); if (csvBtn) csvBtn.style.display = '';
  const fmtH = v => (Math.round(v * 10) / 10).toLocaleString('en-GB');

  const STICKY_L = 'position:sticky;left:0;background:var(--card,#161616);z-index:2;box-shadow:2px 0 6px rgba(0,0,0,.35)';
  const STICKY_R = 'position:sticky;right:0;background:var(--card,#161616);z-index:2;box-shadow:-2px 0 6px rgba(0,0,0,.35)';
  const th = 'padding:8px 6px;font-size:9.5px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;border-bottom:2px solid var(--border);white-space:nowrap;text-align:center';

  let html = `<div style="overflow-x:auto;border:1px solid var(--border);border-radius:10px;background:var(--card,#161616)">
    <table style="border-collapse:separate;border-spacing:0;font-size:11px;min-width:100%">
    <thead><tr>
      <th style="${th};text-align:left;${STICKY_L};padding-left:12px">${view === 'person' ? 'Person' : 'Job'}</th>
      ${dates.map(d => `<th style="${th};${isWeekend(d) ? 'color:var(--border)' : ''}">${dayName(d)}<br><span style="font-size:10.5px;color:${isWeekend(d) ? 'var(--border)' : 'var(--text)'}">${d.slice(8)}/${d.slice(5, 7)}</span></th>`).join('')}
      <th style="${th};text-align:right;${STICKY_R};padding-right:12px">Total</th>
    </tr></thead><tbody>`;

  rowKeys.forEach((rk, ri) => {
    const zebra = ri % 2 ? 'background:rgba(255,255,255,.018)' : '';
    html += `<tr>
      <td style="padding:8px 12px;font-weight:600;white-space:nowrap;${STICKY_L};border-bottom:1px solid var(--border)">${escapeHtml(rk)}</td>`;
    for (const d of dates) {
      const cell = matrix[rk][d];
      const we = isWeekend(d) ? 'background:rgba(255,255,255,.025);' : zebra + ';';
      if (!cell) { html += `<td style="padding:6px;text-align:center;color:rgba(255,255,255,.08);border-bottom:1px solid var(--border);${we}">·</td>`; continue; }
      const parts = Object.entries(cell).sort((a, b) => b[1] - a[1])
        .map(([k, h]) => `<span style="${chipStyle(k)}" title="${escapeHtml(k)} — ${fmtH(h)}h">${escapeHtml(k)} <strong style="font-family:var(--font-mono);font-weight:700">${fmtH(h)}</strong></span>`);
      html += `<td style="padding:5px 6px;vertical-align:top;border-bottom:1px solid var(--border);${we}"><div style="display:flex;flex-direction:column;gap:3px;align-items:flex-start">${parts.join('')}</div></td>`;
    }
    html += `<td style="padding:8px 12px;text-align:right;font-family:var(--font-mono);font-weight:700;${STICKY_R};border-bottom:1px solid var(--border)">${fmtH(rowTotals[rk])}</td></tr>`;
  });

  // Footer: per-day totals so the grand total is ALWAYS visible (pinned right)
  const grand = Object.values(rowTotals).reduce((s, v) => s + v, 0);
  html += `<tr>
      <td style="padding:8px 12px;font-weight:700;${STICKY_L};border-top:2px solid var(--border)">Total</td>
      ${dates.map(d => `<td style="padding:6px;text-align:center;font-family:var(--font-mono);font-size:10.5px;color:var(--muted);border-top:2px solid var(--border)">${dayTotals[d] ? fmtH(dayTotals[d]) : ''}</td>`).join('')}
      <td style="padding:8px 12px;text-align:right;font-family:var(--font-mono);font-weight:700;font-size:12.5px;color:var(--accent);${STICKY_R};border-top:2px solid var(--border)">${fmtH(grand)}</td>
    </tr></tbody></table></div>`;

  // Job legend with range totals — the at-a-glance "where did the fortnight go"
  const legend = Object.entries(jobTotals).sort((a, b) => b[1] - a[1])
    .map(([k, h]) => `<span style="${chipStyle(k)};font-size:11px;padding:3px 10px">${escapeHtml(k)} <strong style="font-family:var(--font-mono)">${fmtH(h)}h</strong> <span style="opacity:.65;font-size:10px">${grand ? Math.round(h / grand * 100) : 0}%</span></span>`).join(' ');
  html += `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;align-items:center">
      <span style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em">Jobs this period</span>${legend}
    </div>
    <div style="font-size:10.5px;color:var(--subtle);margin-top:8px">Hours per job per day from the kiosk. ${incS000 ? 'Including' : 'Excluding'} S000 non-productive time. Weekends shaded. Colours are consistent per job.</div>`;
  grid.innerHTML = html;
}

// ═══════════════════════════════════════════════════════════════════════════
// CVR / WIP — value vs cost per live project (Phase C4)
// ═══════════════════════════════════════════════════════════════════════════
// Facts come from /api/cvr-summary; every derived figure (margin, billing
// position) is computed here in plain arithmetic, definitions in the help.
let _cvrRows = null;

function _cvrDerive(r) {
  const contract  = +r.contract_value || 0;
  const certified = +r.certified_net || 0;
  const applied   = +r.applied_net || 0;
  const value     = certified > 0 ? certified : applied;   // certified wins
  const valueIsApplied = certified <= 0 && applied > 0;
  const cost      = (+r.labour_cost || 0) + (+r.po_nett || 0);
  const margin    = value - cost;
  const billing   = value - (+r.invoiced_net || 0);        // + = under-billed WIP
  const pctComplete = contract > 0 ? Math.min(100, Math.round(value / contract * 100)) : null;
  return { contract, value, valueIsApplied, cost, margin, billing, pctComplete };
}

async function renderCvrReport(run) {
  const tbl = document.getElementById('cvrTable');
  if (!tbl) return;
  if (run || !_cvrRows) {
    tbl.innerHTML = '<div style="padding:30px;text-align:center;color:var(--muted);font-size:12px">Loading…</div>';
    try {
      const all = document.getElementById('cvrAll')?.checked ? '?all=1' : '';
      _cvrRows = await api.get('/api/cvr-summary' + all);
    } catch (e) {
      tbl.innerHTML = `<div style="padding:20px;color:var(--red);font-size:12px">Could not load CVR: ${escapeHtml(e.message)}</div>`;
      return;
    }
  }
  const rows = (_cvrRows || []).map(r => ({ ...r, _d: _cvrDerive(r) }))
    .sort((a, b) => (b._d.value || 0) - (a._d.value || 0));
  if (!rows.length) { tbl.innerHTML = '<div style="padding:20px;color:var(--muted);font-size:12px">No live projects.</div>'; return; }

  document.getElementById('cvrPdfBtn').style.display = '';
  document.getElementById('cvrCsvBtn').style.display = '';

  const money = v => v == null ? '—' : '£' + Math.round(v).toLocaleString('en-GB');
  const hue = key => { let h = 0; const s = String(key); for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h % 360; };

  // KPI strip
  const sum = k => rows.reduce((s, r) => s + (r._d[k] || 0), 0);
  const sumRaw = k => rows.reduce((s, r) => s + (+r[k] || 0), 0);
  const kpi = (label, val, col) => `<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:12px 16px;min-width:150px">
      <div style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em">${label}</div>
      <div style="font-size:19px;font-weight:700;font-family:var(--font-mono);color:${col || 'var(--text)'}">${val}</div></div>`;
  const kEl = document.getElementById('cvrKpis');
  kEl.style.display = 'flex'; kEl.style.gap = '10px'; kEl.style.flexWrap = 'wrap';
  const totMargin = sum('margin'), totBilling = sum('billing');
  kEl.innerHTML =
    kpi('Contract book', money(sum('contract'))) +
    kpi('Value to date', money(sum('value'))) +
    kpi('Cost to date', money(sum('cost'))) +
    kpi('Margin to date', money(totMargin), totMargin < 0 ? 'var(--red)' : 'var(--green)') +
    kpi('Under-billed (WIP)', money(totBilling), totBilling > 0 ? 'var(--accent)' : 'var(--green)') +
    kpi('Cash outstanding', money(sumRaw('outstanding_gross')), sumRaw('outstanding_gross') > 0 ? 'var(--accent)' : 'var(--text)') +
    kpi('Retention held', money(sumRaw('retention_held')));

  const th = 'padding:8px 8px;font-size:9.5px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;border-bottom:2px solid var(--border);text-align:right;white-space:nowrap';
  const td = 'padding:8px 8px;border-bottom:1px solid var(--border);text-align:right;font-family:var(--font-mono);font-size:12px;white-space:nowrap';
  let html = `<div style="overflow-x:auto;border:1px solid var(--border);border-radius:10px;background:var(--card,#161616)">
    <table style="border-collapse:separate;border-spacing:0;min-width:100%">
    <thead><tr>
      <th style="${th};text-align:left;position:sticky;left:0;background:var(--card,#161616);z-index:2;padding-left:12px">Project</th>
      <th style="${th}">Contract</th><th style="${th}">Value to date</th><th style="${th}">% </th>
      <th style="${th}">Cost to date</th><th style="${th}">Margin</th>
      <th style="${th}">Billing position</th>
      <th style="${th}">Invoiced</th><th style="${th}">Paid</th><th style="${th}">Outstanding</th><th style="${th}">Retention</th>
    </tr></thead><tbody>`;
  rows.forEach((r, ri) => {
    const d = r._d;
    const h = hue(r.project_number);
    const zebra = ri % 2 ? 'background:rgba(255,255,255,.018);' : '';
    html += `<tr>
      <td style="padding:8px 12px;border-bottom:1px solid var(--border);white-space:nowrap;position:sticky;left:0;background:var(--card,#161616);z-index:2;${zebra}">
        <span style="display:inline-flex;align-items:center;gap:5px;padding:2px 9px;border-radius:20px;background:hsla(${h},70%,55%,.14);border:1px solid hsla(${h},70%,60%,.45);color:hsl(${h},75%,72%);font-size:11px">${escapeHtml(r.project_number)}</span>
        <span style="font-size:11px;color:var(--muted);margin-left:6px">${escapeHtml((r.project_name || '').slice(0, 34))}</span>
        ${r.last_afp_ref ? `<span style="font-size:10px;color:var(--subtle);margin-left:4px">${escapeHtml(r.last_afp_ref)}</span>` : ''}
      </td>
      <td style="${td};${zebra}">${money(d.contract || null)}</td>
      <td style="${td};${zebra};${d.valueIsApplied ? 'color:var(--accent)' : ''}" title="${d.valueIsApplied ? 'Applied — awaiting certification' : 'Certified'}">${money(d.value || null)}${d.valueIsApplied ? '<span style="font-size:9px"> appl.</span>' : ''}</td>
      <td style="${td};${zebra};color:var(--muted)">${d.pctComplete != null ? d.pctComplete + '%' : '—'}</td>
      <td style="${td};${zebra}" title="Labour ${money(+r.labour_cost)} (${Math.round(+r.labour_hours || 0)}h) + POs ${money(+r.po_nett)}">${money(d.cost || null)}</td>
      <td style="${td};${zebra};color:${d.margin < 0 ? 'var(--red)' : 'var(--green)'};font-weight:700">${money(d.margin)}</td>
      <td style="${td};${zebra};color:${d.billing > 0 ? 'var(--accent)' : 'var(--green)'}" title="${d.billing > 0 ? 'Under-billed — earned value not yet invoiced' : 'Fully billed / cash ahead'}">${d.billing > 0 ? '▲ ' : ''}${money(Math.abs(d.billing))}</td>
      <td style="${td};${zebra}">${money(+r.invoiced_net || null)}</td>
      <td style="${td};${zebra}">${money(+r.paid_gross || null)}</td>
      <td style="${td};${zebra};${+r.outstanding_gross > 0 ? 'color:var(--accent)' : ''}">${money(+r.outstanding_gross || null)}</td>
      <td style="${td};${zebra};color:var(--muted)">${money(+r.retention_held || null)}</td>
    </tr>`;
  });
  html += `</tbody></table></div>
    <div style="font-size:10.5px;color:var(--subtle);margin-top:8px">Sorted by value to date. Cost = kiosk labour at basic rate + nett PO commitments (leads supplier invoices). Hover cells for breakdowns.</div>`;
  tbl.innerHTML = html;
}

function exportCvrCsv() {
  if (!_cvrRows) { toast('Refresh first', 'error'); return; }
  const lines = ['project,name,status,contract,value_to_date,value_basis,pct_complete,labour_cost,labour_hours,po_nett,cost_to_date,margin_to_date,billing_position,invoiced_net,paid_gross,outstanding,retention_held'];
  _cvrRows.forEach(r => {
    const d = _cvrDerive(r);
    lines.push([r.project_number, `"${(r.project_name || '').replace(/"/g, '""')}"`, r.status,
      d.contract, d.value, d.valueIsApplied ? 'applied' : 'certified', d.pctComplete ?? '',
      +r.labour_cost || 0, +r.labour_hours || 0, +r.po_nett || 0, d.cost, d.margin, d.billing,
      +r.invoiced_net || 0, +r.paid_gross || 0, +r.outstanding_gross || 0, +r.retention_held || 0].join(','));
  });
  const blob = new Blob([lines.join('\n')], { type: 'text/csv' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `cvr-${new Date().toISOString().slice(0, 10)}.csv`;
  a.click(); URL.revokeObjectURL(a.href);
}

// Native jsPDF CVR pack — landscape A4 management one-pager (CLAUDE.md rules)
async function exportCvrPDF() {
  if (!_cvrRows) { toast('Refresh first', 'error'); return; }
  const JsPDFCtor = await resolveJsPDFCtor();
  await (typeof loadLogoDataUri === 'function' ? loadLogoDataUri() : Promise.resolve());
  const logo = (typeof _logoDataUriCache !== 'undefined' && _logoDataUriCache) || '';
  const doc = new JsPDFCtor({ unit: 'mm', format: 'a4', orientation: 'landscape' });
  const pageW = 297, pageH = 210, mL = 12, mR = 12, W = pageW - 24;
  const accent = _houseAccent();
  const TEXT = HOUSE_INK, MUTED = HOUSE_MUTED, RED = [208,2,27], GREEN = [22,140,80], AMBER = [200,110,0], RULE = HOUSE_RULE, HEAD = HOUSE_HEAD;
  const sT = c => doc.setTextColor(c[0],c[1],c[2]);
  const money = v => v == null ? '\u2014' : '\u00A3' + Math.round(v).toLocaleString('en-GB');
  const rows = (_cvrRows || []).map(r => ({ ...r, _d: _cvrDerive(r) })).sort((a, b) => (b._d.value || 0) - (a._d.value || 0));
  const sum = k => rows.reduce((s, r) => s + (r._d[k] || 0), 0);
  const sumRaw = k => rows.reduce((s, r) => s + (+r[k] || 0), 0);

  let y = bamaDocHeader(doc, logo, {
    title: 'CVR / WIP', pageW, accent, marginL: mL, marginR: mR,
    meta: [
      { label: 'Projects:', value: String(rows.length) },
      { label: 'Prepared:', value: new Date().toLocaleDateString('en-GB') }
    ]
  }).y;

  // KPI band
  const kpis = [
    ['CONTRACT BOOK', money(sum('contract')), TEXT], ['VALUE TO DATE', money(sum('value')), TEXT],
    ['COST TO DATE', money(sum('cost')), TEXT], ['MARGIN', money(sum('margin')), sum('margin') < 0 ? RED : GREEN],
    ['UNDER-BILLED WIP', money(sum('billing')), sum('billing') > 0 ? AMBER : GREEN],
    ['OUTSTANDING', money(sumRaw('outstanding_gross')), AMBER], ['RETENTION', money(sumRaw('retention_held')), MUTED]
  ];
  const kw = W / kpis.length;
  kpis.forEach((k, i) => {
    const x = mL + i * kw;
    doc.setFillColor(HEAD[0],HEAD[1],HEAD[2]); doc.setDrawColor(RULE[0],RULE[1],RULE[2]); doc.setLineWidth(0.2); doc.roundedRect(x + 1, y, kw - 2, 14, 1.5, 1.5, 'FD');
    sT(MUTED); doc.setFontSize(5.8); doc.setFont('helvetica','bold'); doc.text(k[0], x + 3.5, y + 5);
    sT(k[2]); doc.setFontSize(10); doc.text(k[1], x + 3.5, y + 11);
  });
  y += 19;
  y = bamaSectionHeading(doc, y, 'COST & VALUE RECONCILIATION', { accent, pageW, marginL: mL, usableW: W });

  const cols = [
    ['PROJECT', 62, 'left'], ['CONTRACT', 24], ['VALUE', 26], ['%', 10],
    ['COST', 24], ['MARGIN', 24], ['BILLING POS.', 24], ['INVOICED', 24], ['PAID', 24], ['OUTST.', 22], ['RETN.', 20]
  ];
  const xs = []; let acc = mL; cols.forEach(c => { xs.push(acc); acc += c[1]; });
  const head = () => {
    doc.setFillColor(HEAD[0],HEAD[1],HEAD[2]); doc.rect(mL, y, W, 6.5, 'F');
    doc.setDrawColor(RULE[0],RULE[1],RULE[2]); doc.setLineWidth(0.2); doc.rect(mL, y, W, 6.5);
    sT(TEXT); doc.setFont('helvetica','bold'); doc.setFontSize(6.5);
    cols.forEach((c, i) => doc.text(c[0], c[2] === 'left' ? xs[i] + 2 : xs[i] + c[1] - 2, y + 4.4, { align: c[2] === 'left' ? 'left' : 'right' }));
    y += 6.5;
  };
  head();
  doc.setFontSize(7.6);
  const cell = (i, txt, col, bold) => {
    sT(col || TEXT); doc.setFont('helvetica', bold ? 'bold' : 'normal');
    doc.text(String(txt), cols[i][2] === 'left' ? xs[i] + 2 : xs[i] + cols[i][1] - 2, y + 4.2, { align: cols[i][2] === 'left' ? 'left' : 'right' });
  };
  for (const r of rows) {
    if (y + 6 > pageH - 14) { doc.addPage(); y = bamaDocContinuation(doc, { title: 'CVR / WIP', ref: new Date().toLocaleDateString('en-GB'), pageW, marginL: mL, marginR: mR }).y; head(); doc.setFontSize(7.6); }
    const d = r._d;
    cell(0, `${r.project_number}  ${(r.project_name || '').slice(0, 30)}`, TEXT, true);
    cell(1, money(d.contract || null));
    cell(2, money(d.value || null) + (d.valueIsApplied ? '*' : ''), d.valueIsApplied ? AMBER : TEXT);
    cell(3, d.pctComplete != null ? d.pctComplete + '%' : '\u2014', MUTED);
    cell(4, money(d.cost || null));
    cell(5, money(d.margin), d.margin < 0 ? RED : GREEN, true);
    cell(6, money(d.billing), d.billing > 0 ? AMBER : GREEN);
    cell(7, money(+r.invoiced_net || null));
    cell(8, money(+r.paid_gross || null));
    cell(9, money(+r.outstanding_gross || null), +r.outstanding_gross > 0 ? AMBER : TEXT);
    cell(10, money(+r.retention_held || null), MUTED);
    doc.setDrawColor(215,218,224); doc.setLineWidth(0.12); doc.line(mL, y + 6, mL + W, y + 6);
    y += 6;
  }
  y += 6;
  sT(MUTED); doc.setFont('helvetica','normal'); doc.setFontSize(6.5);
  doc.splitTextToSize('Value = certified AFP value to date (* = applied, awaiting certification). Cost = kiosk labour at basic rates + nett PO commitments (leads supplier invoices; excludes overheads). Margin = value \u2212 cost. Billing position = value \u2212 invoiced (positive = under-billed WIP being funded by BAMA). Figures are live from the ERP at time of printing.', W).forEach(l => { doc.text(l, mL, y); y += 3.2; });
  bamaDocFooter(doc, { pageW, pageH, marginL: mL, marginR: mR, size: 7,
    caption: 'CVR / WIP pack  \u00b7  BAMA Fabrication Ltd' });
  const blob = doc.output('blob');
  console.log('[CVR PDF] blob size:', blob.size);
  doc.save(`CVR-WIP-${new Date().toISOString().slice(0, 10)}.pdf`);
}

// ═══════════════════════════════════════════════════════════════════════════
// PAYMENTS DUE — unpaid supplier invoices to pay by a chosen date
// Facts come from /api/supplier-invoices?status=unpaid; all bucketing/summing
// is plain arithmetic here. Two toggles (both off by default): include overdue,
// include direct debits. Definitions live in the panel Help.
// ═══════════════════════════════════════════════════════════════════════════
let _pdrRows = null;   // raw unpaid supplier invoices (cached)
let _pdrMeta = null;   // { byDate, overdue, dd } snapshot of last render

function _pdrEndOfMonth(offset) {
  // offset 0 = this month, 1 = next month. Returns YYYY-MM-DD of last day.
  const t = new Date();
  const d = new Date(t.getFullYear(), t.getMonth() + offset + 1, 0);
  return d.toISOString().slice(0, 10);
}

function pdrPreset(kind) {
  const el = document.getElementById('pdrByDate');
  if (!el) return;
  if (kind === 'eom')  el.value = _pdrEndOfMonth(0);
  else if (kind === 'eonm') el.value = _pdrEndOfMonth(1);
  else {
    const days = parseInt(kind, 10) || 0;
    el.value = new Date(Date.now() + days * 86400000).toISOString().slice(0, 10);
  }
  renderPaymentsDueReport(true);
}

// Filtered + grouped view of the cached rows against the current controls.
function _pdrData() {
  const byDate  = document.getElementById('pdrByDate')?.value || null;
  const overdue = !!document.getElementById('pdrOverdue')?.checked;
  const inclDd  = !!document.getElementById('pdrDd')?.checked;
  const today   = new Date().toISOString().slice(0, 10);

  const open = (_pdrRows || []).filter(inv => {
    if (inv.paid_at) return false;
    if (Number(inv.gross || 0) <= 0.005) return false;
    if (inv.is_dd) return inclDd;                 // DD only if opted in
    const due = inv.due_date ? String(inv.due_date).slice(0, 10) : null;
    if (!due) return false;                       // no due date → not schedulable
    if (byDate && due > byDate) return false;     // past the window
    if (!overdue && due < today) return false;    // overdue excluded unless opted in
    return true;
  });

  const bySupplier = new Map();
  let total = 0, overdueTotal = 0;
  for (const inv of open) {
    const key = inv.supplier_name || '— Unknown —';
    const amt = Number(inv.gross || 0);
    const due = inv.due_date ? String(inv.due_date).slice(0, 10) : null;
    const isOverdue = !inv.is_dd && due && due < today;
    if (!bySupplier.has(key)) bySupplier.set(key, { supplier: key, total: 0, overdue: 0, invoices: [] });
    const row = bySupplier.get(key);
    row.total += amt;
    if (isOverdue) row.overdue += amt;
    row.invoices.push({ ...inv, _amt: amt, _overdue: isOverdue });
    total += amt;
    if (isOverdue) overdueTotal += amt;
  }
  const rows = Array.from(bySupplier.values()).sort((a, b) => b.total - a.total);
  for (const r of rows) {
    r.invoices.sort((a, b) => String(a.due_date || '9999').localeCompare(String(b.due_date || '9999')));
  }
  return { rows, total, overdueTotal, count: open.length, byDate, overdue, inclDd };
}

async function renderPaymentsDueReport(run) {
  const tbl = document.getElementById('pdrTable');
  if (!tbl) return;
  // Default the date to end of this month on first open
  const dateEl = document.getElementById('pdrByDate');
  if (dateEl && !dateEl.value) dateEl.value = _pdrEndOfMonth(0);

  if (run || !_pdrRows) {
    tbl.innerHTML = '<div style="padding:30px;text-align:center;color:var(--muted);font-size:12px">Loading…</div>';
    try {
      _pdrRows = await api.get('/api/supplier-invoices?status=unpaid');
    } catch (e) {
      tbl.innerHTML = `<div style="padding:20px;color:var(--red);font-size:12px">Could not load supplier invoices: ${escapeHtml(e.message)}</div>`;
      return;
    }
  }

  const { rows, total, overdueTotal, count, byDate, inclDd } = _pdrData();
  _pdrMeta = { byDate, overdue: !!document.getElementById('pdrOverdue')?.checked, dd: inclDd };

  const pdfBtn = document.getElementById('pdrPdfBtn'), csvBtn = document.getElementById('pdrCsvBtn');

  if (!rows.length) {
    if (pdfBtn) pdfBtn.style.display = 'none';
    if (csvBtn) csvBtn.style.display = 'none';
    const kEl = document.getElementById('pdrKpis'); if (kEl) kEl.style.display = 'none';
    tbl.innerHTML = '<div style="padding:24px;text-align:center;color:var(--muted);font-size:12px">Nothing due in this window. 🎉</div>';
    return;
  }
  if (pdfBtn) pdfBtn.style.display = '';
  if (csvBtn) csvBtn.style.display = '';

  const hue = key => { let h = 0; const s = String(key); for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h % 360; };
  const fmtDue = iso => iso ? new Date(iso + 'T00:00:00').toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' }) : '—';

  // KPI strip
  const kEl = document.getElementById('pdrKpis');
  const kpi = (label, val, col) => `<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:12px 16px;min-width:150px">
      <div style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em">${label}</div>
      <div style="font-size:19px;font-weight:700;font-family:var(--font-mono);color:${col || 'var(--text)'}">${val}</div></div>`;
  kEl.style.display = 'flex'; kEl.style.gap = '10px'; kEl.style.flexWrap = 'wrap';
  kEl.innerHTML =
    kpi('Total to pay', gbp2(total), 'var(--accent)') +
    kpi('Invoices', String(count)) +
    kpi('Suppliers', String(rows.length)) +
    (overdueTotal > 0 ? kpi('Of which overdue', gbp2(overdueTotal), 'var(--red)') : '') +
    kpi('Due on or before', byDate ? fmtDue(byDate) : 'any');

  const th = 'padding:8px;font-size:9.5px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;border-bottom:2px solid var(--border);text-align:right;white-space:nowrap';
  const td = 'padding:8px;border-bottom:1px solid var(--border);text-align:right;font-family:var(--font-mono);font-size:12px;white-space:nowrap';
  let html = `<div style="overflow-x:auto;border:1px solid var(--border);border-radius:10px;background:var(--card,#161616)">
    <table style="border-collapse:separate;border-spacing:0;min-width:100%">
    <thead><tr>
      <th style="${th};text-align:left;padding-left:12px">Supplier / Invoice</th>
      <th style="${th};text-align:left">PO</th>
      <th style="${th};text-align:left">Project</th>
      <th style="${th}">Due</th>
      <th style="${th}">Gross</th>
    </tr></thead><tbody>`;

  rows.forEach(r => {
    const h = hue(r.supplier);
    html += `<tr>
      <td style="padding:9px 12px;border-bottom:1px solid var(--border);white-space:nowrap;font-weight:700">
        <span style="display:inline-flex;align-items:center;gap:5px;padding:2px 9px;border-radius:20px;background:hsla(${h},70%,55%,.14);border:1px solid hsla(${h},70%,60%,.45);color:hsl(${h},75%,72%);font-size:12px">${escapeHtml(r.supplier)}</span>
        ${r.overdue > 0 ? `<span style="font-size:10px;color:var(--red);margin-left:6px">${gbp2(r.overdue)} overdue</span>` : ''}
      </td>
      <td style="border-bottom:1px solid var(--border)"></td>
      <td style="border-bottom:1px solid var(--border)"></td>
      <td style="border-bottom:1px solid var(--border)"></td>
      <td style="${td};font-weight:700">${gbp2(r.total)}</td>
    </tr>`;
    r.invoices.forEach((inv, ii) => {
      const zebra = ii % 2 ? 'background:rgba(255,255,255,.018);' : '';
      html += `<tr>
        <td style="padding:6px 12px 6px 26px;border-bottom:1px solid var(--border);font-family:var(--font-mono);font-size:11.5px;color:var(--muted);${zebra}">
          ${escapeHtml(inv.invoice_ref || ('#' + inv.id))}
          ${inv.invoice_type === 'subcontractor' ? '<span style="color:#b596e8;font-size:10px;margin-left:6px">CIS</span>' : ''}
          ${inv.is_dd ? '<span style="color:var(--subtle);font-size:10px;margin-left:6px">DD</span>' : ''}
        </td>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border);font-family:var(--font-mono);font-size:11px;color:var(--muted);text-align:left;${zebra}">${escapeHtml(inv.po_reference || '')}</td>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border);font-size:11px;color:var(--muted);text-align:left;${zebra}">${escapeHtml(inv.project_number || inv.job_number || inv.cost_centre || '')}</td>
        <td style="${td};${zebra};${inv._overdue ? 'color:var(--red);font-weight:600' : 'color:var(--muted)'}">${inv.is_dd ? 'DD' : fmtDue(inv.due_date ? String(inv.due_date).slice(0, 10) : null)}</td>
        <td style="${td};${zebra}">${gbp2(inv._amt)}</td>
      </tr>`;
    });
  });
  html += `</tbody>
    <tfoot><tr>
      <td style="padding:10px 12px;border-top:2px solid var(--border);font-weight:700">TOTAL TO PAY</td>
      <td style="border-top:2px solid var(--border)"></td>
      <td style="border-top:2px solid var(--border)"></td>
      <td style="border-top:2px solid var(--border)"></td>
      <td style="${td};border-top:2px solid var(--border);border-bottom:none;font-weight:700;color:var(--accent)">${gbp2(total)}</td>
    </tr></tfoot>
    </table></div>
    <div style="font-size:10.5px;color:var(--subtle);margin-top:8px">Gross (VAT-inclusive) unpaid supplier invoices due on or before the selected date. Paid invoices excluded. ${inclDd ? 'Direct debits included (flagged DD).' : 'Direct debits excluded.'}</div>`;
  tbl.innerHTML = html;
}

function exportPaymentsDueCsv() {
  if (!_pdrRows) { toast('Refresh first', 'error'); return; }
  const { rows, total, byDate } = _pdrData();
  if (!rows.length) { toast('Nothing to export', 'error'); return; }
  const esc = v => `"${String(v == null ? '' : v).replace(/"/g, '""')}"`;
  const lines = [['Supplier', 'Invoice Ref', 'PO Ref', 'Project', 'Invoice Date', 'Due Date', 'Gross'].map(esc).join(',')];
  for (const r of rows) {
    for (const inv of r.invoices) {
      lines.push([r.supplier, inv.invoice_ref || '', inv.po_reference || '',
        inv.project_number || inv.job_number || inv.cost_centre || '',
        String(inv.invoice_date || '').slice(0, 10),
        inv.is_dd ? 'DD' : String(inv.due_date || '').slice(0, 10),
        Number(inv._amt || 0).toFixed(2)].map(esc).join(','));
    }
  }
  lines.push('');
  lines.push(['PAYMENT PER SUPPLIER', '', '', '', '', '', ''].map(esc).join(','));
  for (const r of rows) lines.push([r.supplier, '', '', '', '', '', r.total.toFixed(2)].map(esc).join(','));
  lines.push(['', '', '', '', '', 'TOTAL', total.toFixed(2)].map(esc).join(','));
  const blob = new Blob(['\ufeff' + lines.join('\r\n')], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `payments-due-${byDate || new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 5000);
}

// Native jsPDF Payments Due schedule — portrait A4, BAMA house style.
async function exportPaymentsDuePDF() {
  if (!_pdrRows) { toast('Refresh first', 'error'); return; }
  const { rows, total, overdueTotal, count, byDate, inclDd } = _pdrData();
  if (!rows.length) { toast('Nothing to export', 'error'); return; }
  const JsPDFCtor = await resolveJsPDFCtor();
  await (typeof loadLogoDataUri === 'function' ? loadLogoDataUri() : Promise.resolve());
  const logo = (typeof _logoDataUriCache !== 'undefined' && _logoDataUriCache) || '';
  const doc = new JsPDFCtor({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  try { doc.setProperties({ title: 'Payments Due', subject: 'Supplier invoices to pay', author: 'BAMA Fabrication', creator: 'BAMA Fabrication ERP' }); } catch (e) {}
  const pageW = 210, pageH = 297, mL = 14, mR = 14, W = pageW - mL - mR;
  const accent = _houseAccent();
  const TEXT = HOUSE_INK, MUTED = HOUSE_MUTED, RED = [208,2,27], RULE = HOUSE_RULE, HEAD = HOUSE_HEAD;
  const sT = c => doc.setTextColor(c[0],c[1],c[2]);
  const money = v => v == null ? '\u2014' : gbp2(v);
  const fmtDue = iso => iso ? new Date(iso + 'T00:00:00').toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' }) : '\u2014';
  const today = new Date().toISOString().slice(0, 10);

  // ── Letterhead ──
  const _h = bamaDocHeader(doc, logo, {
    title: 'PAYMENTS DUE',
    accent, marginL: mL, marginR: mR,
    meta: [
      { label: 'Due by:',    value: byDate ? fmtDue(byDate) : 'any date' },
      { label: 'Invoices:',  value: String(count) },
      { label: 'Prepared:',  value: new Date().toLocaleDateString('en-GB') }
    ]
  });
  let y = _h.y;

  // ── KPI band (framed cards, house palette) ──
  const kpis = [
    ['TOTAL TO PAY', money(total), accent],
    ['INVOICES', String(count), TEXT],
    ['SUPPLIERS', String(rows.length), TEXT],
    ['OVERDUE', money(overdueTotal), overdueTotal > 0 ? RED : MUTED],
    ['DIRECT DEBITS', inclDd ? 'incl.' : 'excl.', MUTED]
  ];
  const kw = W / kpis.length;
  kpis.forEach((k, i) => {
    const x = mL + i * kw;
    doc.setFillColor(HEAD[0],HEAD[1],HEAD[2]); doc.setDrawColor(RULE[0],RULE[1],RULE[2]); doc.setLineWidth(0.2);
    doc.roundedRect(x + 1, y, kw - 2, 15, 1.5, 1.5, 'FD');
    sT(MUTED); doc.setFontSize(6); doc.setFont('helvetica','bold'); doc.text(k[0], x + 3.5, y + 5.5);
    sT(k[2]); doc.setFontSize(11); doc.text(k[1], x + 3.5, y + 11.5);
  });
  y += 22;

  // ── Section heading ──
  y = bamaSectionHeading(doc, y, 'SUPPLIER INVOICES TO PAY', { accent, marginL: mL, usableW: W });

  const cols = [['Supplier / Invoice', 76, 'left'], ['PO', 26, 'left'], ['Project', 34, 'left'], ['Due', 22, 'right'], ['Gross', 26, 'right']];
  const xs = []; let acc = mL; cols.forEach(c => { xs.push(acc); acc += c[1]; });
  const head = () => {
    doc.setFillColor(HEAD[0],HEAD[1],HEAD[2]); doc.rect(mL, y, W, 6.5, 'F');
    doc.setDrawColor(RULE[0],RULE[1],RULE[2]); doc.setLineWidth(0.2); doc.rect(mL, y, W, 6.5);
    sT(TEXT); doc.setFont('helvetica','bold'); doc.setFontSize(7.2);
    cols.forEach((c, i) => doc.text(c[0], c[2] === 'left' ? xs[i] + 2 : xs[i] + c[1] - 2, y + 4.4, { align: c[2] === 'left' ? 'left' : 'right' }));
    y += 6.5;
  };
  head();

  const ensure = h => { if (y + h > pageH - 18) { doc.addPage(); y = mL + 4; head(); } };
  for (const r of rows) {
    ensure(7);
    // Supplier group row
    doc.setFillColor(250, 244, 238); doc.rect(mL, y, W, 6, 'F'); // faint warm band
    sT(TEXT); doc.setFont('helvetica','bold'); doc.setFontSize(8.2);
    doc.text(doc.splitTextToSize(r.supplier, cols[0][1] + cols[1][1] + cols[2][1] - 4)[0], xs[0] + 2, y + 4.2);
    if (r.overdue > 0) { sT(RED); doc.setFont('helvetica','normal'); doc.setFontSize(6.4); doc.text(`${money(r.overdue)} overdue`, xs[3] + cols[3][1] - 2, y + 4.2, { align: 'right' }); }
    sT(TEXT); doc.setFont('helvetica','bold'); doc.setFontSize(8.2);
    doc.text(money(r.total), xs[4] + cols[4][1] - 2, y + 4.2, { align: 'right' });
    y += 6;
    // Invoice lines
    doc.setFontSize(7.6); doc.setFont('helvetica','normal');
    r.invoices.forEach((inv, ii) => {
      ensure(5.2);
      if (ii % 2) { doc.setFillColor(250,250,251); doc.rect(mL, y, W, 5.2, 'F'); }
      const dueStr = inv.due_date ? String(inv.due_date).slice(0, 10) : null;
      const od = !inv.is_dd && dueStr && dueStr < today;
      sT(MUTED);
      const ref = (inv.invoice_ref || ('#' + inv.id)) + (inv.invoice_type === 'subcontractor' ? '  CIS' : '') + (inv.is_dd ? '  DD' : '');
      doc.text('   ' + doc.splitTextToSize(ref, cols[0][1] - 8)[0], xs[0] + 2, y + 3.7);
      doc.text(doc.splitTextToSize(inv.po_reference || '', cols[1][1] - 2)[0] || '', xs[1] + 2, y + 3.7);
      doc.text(doc.splitTextToSize(inv.project_number || inv.job_number || inv.cost_centre || '', cols[2][1] - 2)[0] || '', xs[2] + 2, y + 3.7);
      sT(od ? RED : MUTED);
      doc.text(inv.is_dd ? 'DD' : fmtDue(dueStr), xs[3] + cols[3][1] - 2, y + 3.7, { align: 'right' });
      sT(TEXT);
      doc.text(money(inv._amt), xs[4] + cols[4][1] - 2, y + 3.7, { align: 'right' });
      doc.setDrawColor(RULE[0],RULE[1],RULE[2]); doc.setLineWidth(0.1); doc.line(mL, y + 5.2, mL + W, y + 5.2);
      y += 5.2;
    });
  }

  // ── Grand total band ──
  ensure(10);
  y += 2;
  doc.setFillColor(HEAD[0],HEAD[1],HEAD[2]); doc.rect(mL, y, W, 8, 'F');
  doc.setDrawColor(accent[0],accent[1],accent[2]); doc.setLineWidth(0.5); doc.line(mL, y, mL + W, y);
  sT(TEXT); doc.setFont('helvetica','bold'); doc.setFontSize(10);
  doc.text('TOTAL TO PAY', xs[0] + 2, y + 5.4);
  sT(accent); doc.text(money(total), xs[4] + cols[4][1] - 2, y + 5.4, { align: 'right' });
  y += 13;

  sT(MUTED); doc.setFont('helvetica','normal'); doc.setFontSize(7);
  doc.splitTextToSize('Gross (VAT-inclusive) unpaid supplier invoices due on or before the selected date, grouped by supplier. Invoices already marked paid (Pay & Remit / BACS run) are excluded. ' + (inclDd ? 'Direct debits are included and flagged DD.' : 'Direct debits are excluded.') + ' Due dates derive from each supplier\u2019s payment terms. Figures are live from the ERP at time of printing.', W).forEach(l => { if (y > pageH - 18) { doc.addPage(); y = mL + 4; } doc.text(l, mL, y); y += 3.4; });

  bamaDocFooter(doc, { marginL: mL, marginR: mR, caption: 'Payments Due  \u00b7  BAMA Fabrication Ltd' });
  const blob = doc.output('blob');
  console.log('[Payments Due PDF] blob size:', blob.size);
  doc.save(`payments-due-${byDate || new Date().toISOString().slice(0, 10)}.pdf`);
}

// ═══════════════════════════════════════════════════════════════════════════
// LABOUR & SUBCONTRACTOR PAYMENTS — weekly spend on agency + subcontract labour
//   Source: SupplierInvoices. A row counts as labour when it is either
//     • a CIS subcontractor invoice (invoice_type = 'subcontractor'), or
//     • from a supplier tagged is_labour_supplier (a labour agency, e.g. WPS).
//   Materials suppliers are excluded. Gross = amount payable (bank outflow);
//   CIS retained = deduction held for HMRC (subcontractors only).
// ═══════════════════════════════════════════════════════════════════════════
let _lprRows = null;   // raw supplier-invoice cache for this report

// Week-ending Sunday for a given ISO date (BAMA labour invoices run to Sunday).
function _lprWeekEnding(iso) {
  if (!iso) return null;
  const d = new Date(String(iso).slice(0, 10) + 'T00:00:00');
  if (isNaN(d)) return null;
  const dow = d.getDay();                 // 0 = Sun
  const add = (7 - dow) % 7;              // days forward to Sunday
  d.setDate(d.getDate() + add);
  return d.toISOString().slice(0, 10);
}

function _lprIsLabour(inv) {
  return inv.invoice_type === 'subcontractor' || !!inv.is_labour_supplier;
}

function _lprPreset(kind) {           // sets the From/To inputs
  const fromEl = document.getElementById('lprFrom'), toEl = document.getElementById('lprTo');
  if (!fromEl || !toEl) return;
  const today = new Date();
  const iso = d => d.toISOString().slice(0, 10);
  if (kind === '4w') {
    const from = new Date(today); from.setDate(from.getDate() - 27);
    fromEl.value = iso(from); toEl.value = iso(today);
  } else if (kind === 'tm') {
    fromEl.value = iso(new Date(today.getFullYear(), today.getMonth(), 1));
    toEl.value = iso(new Date(today.getFullYear(), today.getMonth() + 1, 0));
  } else if (kind === 'fy') {
    // UK FY: 1 Apr → 31 Mar
    const y = today.getMonth() >= 3 ? today.getFullYear() : today.getFullYear() - 1;
    fromEl.value = `${y}-04-01`; toEl.value = `${y + 1}-03-31`;
  }
}
function lprPreset(kind) { _lprPreset(kind); renderLabourPayReport(true); }

// Filter the cache to labour invoices inside the date window (by invoice_date).
function _lprData() {
  const from = document.getElementById('lprFrom')?.value || null;
  const to   = document.getElementById('lprTo')?.value || null;
  const unpaidOnly = !!document.getElementById('lprUnpaidOnly')?.checked;
  const groupBy = document.getElementById('lprGroup')?.value || 'supplier';

  const inWindow = (_lprRows || []).filter(inv => {
    if (!_lprIsLabour(inv)) return false;
    if (Number(inv.gross || 0) <= 0.005) return false;
    if (unpaidOnly && inv.paid_at) return false;
    const d = inv.invoice_date ? String(inv.invoice_date).slice(0, 10) : null;
    if (!d) return false;
    if (from && d < from) return false;
    if (to && d > to) return false;
    return true;
  }).map(inv => {
    const gross = Number(inv.gross || 0);
    const cis   = inv.invoice_type === 'subcontractor' ? Number(inv.cis_deduction || 0) : 0;
    const kind  = inv.invoice_type === 'subcontractor' ? 'sub' : 'agency';
    return { ...inv, _gross: gross, _cis: cis, _kind: kind, _wk: _lprWeekEnding(inv.invoice_date) };
  });

  // Totals
  let total = 0, cisRetained = 0, subTotal = 0, agencyTotal = 0;
  for (const inv of inWindow) {
    total += inv._gross; cisRetained += inv._cis;
    if (inv._kind === 'sub') subTotal += inv._gross; else agencyTotal += inv._gross;
  }

  // Grouping
  const groups = new Map();
  const keyOf = inv => groupBy === 'week'
    ? (inv._wk || '— no date —')
    : (inv.supplier_name || '— Unknown —');
  for (const inv of inWindow) {
    const key = keyOf(inv);
    if (!groups.has(key)) groups.set(key, { key, total: 0, cis: 0, sub: 0, agency: 0, invoices: [] });
    const g = groups.get(key);
    g.total += inv._gross; g.cis += inv._cis;
    if (inv._kind === 'sub') g.sub += inv._gross; else g.agency += inv._gross;
    g.invoices.push(inv);
  }
  const rows = Array.from(groups.values());
  if (groupBy === 'week') rows.sort((a, b) => String(b.key).localeCompare(String(a.key)));       // newest week first
  else rows.sort((a, b) => b.total - a.total);                                                    // biggest payee first
  for (const r of rows) {
    r.invoices.sort((a, b) => String(b.invoice_date || '').localeCompare(String(a.invoice_date || '')));
  }
  return { rows, total, cisRetained, subTotal, agencyTotal, count: inWindow.length, from, to, groupBy, unpaidOnly };
}

async function renderLabourPayReport(run) {
  const tbl = document.getElementById('lprTable');
  if (!tbl) return;
  // Default to last 4 weeks on first open
  const fromEl = document.getElementById('lprFrom');
  if (fromEl && !fromEl.value) _lprPreset('4w');

  if (run || !_lprRows) {
    tbl.innerHTML = '<div style="padding:30px;text-align:center;color:var(--muted);font-size:12px">Loading…</div>';
    try {
      _lprRows = await api.get('/api/supplier-invoices');
    } catch (e) {
      tbl.innerHTML = `<div style="padding:20px;color:var(--red);font-size:12px">Could not load supplier invoices: ${escapeHtml(e.message)}</div>`;
      return;
    }
  }

  const { rows, total, cisRetained, subTotal, agencyTotal, count, groupBy, unpaidOnly } = _lprData();
  const pdfBtn = document.getElementById('lprPdfBtn'), csvBtn = document.getElementById('lprCsvBtn');
  const kEl = document.getElementById('lprKpis');

  if (!rows.length) {
    if (pdfBtn) pdfBtn.style.display = 'none';
    if (csvBtn) csvBtn.style.display = 'none';
    if (kEl) kEl.style.display = 'none';
    tbl.innerHTML = '<div style="padding:24px;text-align:center;color:var(--muted);font-size:12px">No labour or subcontractor invoices in this window.</div>';
    return;
  }
  if (pdfBtn) pdfBtn.style.display = '';
  if (csvBtn) csvBtn.style.display = '';

  const hue = key => { let h = 0; const s = String(key); for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h % 360; };
  const fmtD = iso => iso ? new Date(iso + 'T00:00:00').toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' }) : '—';

  // KPI strip
  const kpi = (label, val, col) => `<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:12px 16px;min-width:150px">
      <div style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em">${label}</div>
      <div style="font-size:19px;font-weight:700;font-family:var(--font-mono);color:${col || 'var(--text)'}">${val}</div></div>`;
  kEl.style.display = 'flex'; kEl.style.gap = '10px'; kEl.style.flexWrap = 'wrap';
  kEl.innerHTML =
    kpi('Total labour spend', gbp2(total), 'var(--accent)') +
    kpi('Labour agencies', gbp2(agencyTotal)) +
    kpi('Subcontractors', gbp2(subTotal)) +
    (cisRetained > 0.005 ? kpi('CIS retained (HMRC)', gbp2(cisRetained), '#b596e8') : '') +
    kpi('Invoices', String(count));

  const groupHdr = groupBy === 'week' ? 'Week ending / invoice' : 'Supplier / invoice';
  const th = 'padding:8px;font-size:9.5px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;border-bottom:2px solid var(--border);text-align:right;white-space:nowrap';
  const td = 'padding:8px;border-bottom:1px solid var(--border);text-align:right;font-family:var(--font-mono);font-size:12px;white-space:nowrap';
  let html = `<div style="overflow-x:auto;border:1px solid var(--border);border-radius:10px;background:var(--card,#161616)">
    <table style="border-collapse:separate;border-spacing:0;min-width:100%">
    <thead><tr>
      <th style="${th};text-align:left;padding-left:12px">${groupHdr}</th>
      <th style="${th};text-align:left">Type</th>
      <th style="${th};text-align:left">Project</th>
      <th style="${th}">Date</th>
      <th style="${th}">CIS held</th>
      <th style="${th}">Gross</th>
    </tr></thead><tbody>`;

  const badge = (inv) => inv._kind === 'sub'
    ? '<span style="display:inline-block;padding:1px 7px;border-radius:8px;font-size:10px;font-weight:600;background:rgba(147,112,219,.18);color:#b596e8">CIS sub</span>'
    : '<span style="display:inline-block;padding:1px 7px;border-radius:8px;font-size:10px;font-weight:600;background:rgba(22,110,180,.18);color:#6fb0e0">Agency</span>';

  rows.forEach(r => {
    const h = hue(r.key);
    const label = groupBy === 'week' ? ('w/e ' + fmtD(r.key)) : r.key;
    html += `<tr>
      <td style="padding:9px 12px;border-bottom:1px solid var(--border);white-space:nowrap;font-weight:700">
        <span style="display:inline-flex;align-items:center;gap:5px;padding:2px 9px;border-radius:20px;background:hsla(${h},70%,55%,.14);border:1px solid hsla(${h},70%,60%,.45);color:hsl(${h},75%,72%);font-size:12px">${escapeHtml(label)}</span>
      </td>
      <td style="border-bottom:1px solid var(--border)"></td>
      <td style="border-bottom:1px solid var(--border)"></td>
      <td style="border-bottom:1px solid var(--border)"></td>
      <td style="${td};color:#b596e8">${r.cis > 0.005 ? gbp2(r.cis) : ''}</td>
      <td style="${td};font-weight:700">${gbp2(r.total)}</td>
    </tr>`;
    r.invoices.forEach((inv, ii) => {
      const zebra = ii % 2 ? 'background:rgba(255,255,255,.018);' : '';
      const sub = groupBy === 'week' ? (inv.supplier_name || '') : (inv.invoice_ref || ('#' + inv.id));
      html += `<tr>
        <td style="padding:6px 12px 6px 26px;border-bottom:1px solid var(--border);font-family:var(--font-mono);font-size:11.5px;color:var(--muted);${zebra}">
          ${escapeHtml(sub)}${inv.paid_at ? '<span style="color:#4ea56b;font-size:10px;margin-left:6px">paid</span>' : '<span style="color:var(--subtle);font-size:10px;margin-left:6px">unpaid</span>'}
        </td>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border);text-align:left;${zebra}">${badge(inv)}</td>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border);font-size:11px;color:var(--muted);text-align:left;${zebra}">${escapeHtml(inv.project_number || inv.job_number || inv.cost_centre || '')}</td>
        <td style="${td};${zebra};color:var(--muted)">${fmtD(inv.invoice_date ? String(inv.invoice_date).slice(0, 10) : null)}</td>
        <td style="${td};${zebra};color:#b596e8">${inv._cis > 0.005 ? gbp2(inv._cis) : ''}</td>
        <td style="${td};${zebra}">${gbp2(inv._gross)}</td>
      </tr>`;
    });
  });
  html += `</tbody>
    <tfoot><tr>
      <td style="padding:10px 12px;border-top:2px solid var(--border);font-weight:700">TOTAL LABOUR SPEND</td>
      <td style="border-top:2px solid var(--border)"></td>
      <td style="border-top:2px solid var(--border)"></td>
      <td style="border-top:2px solid var(--border)"></td>
      <td style="${td};border-top:2px solid var(--border);border-bottom:none;color:#b596e8">${cisRetained > 0.005 ? gbp2(cisRetained) : ''}</td>
      <td style="${td};border-top:2px solid var(--border);border-bottom:none;font-weight:700;color:var(--accent)">${gbp2(total)}</td>
    </tr></tfoot>
    </table></div>
    <div style="font-size:10.5px;color:var(--subtle);margin-top:8px">Gross (amount payable) labour invoices by invoice date. Agencies = labour-supplier-tagged companies; CIS sub = subcontractor invoices (deduction retained for HMRC). ${unpaidOnly ? 'Unpaid only.' : 'Paid + unpaid.'} Materials suppliers excluded.</div>`;
  tbl.innerHTML = html;
}

function exportLabourPayCsv() {
  if (!_lprRows) { toast('Refresh first', 'error'); return; }
  const { rows, total, cisRetained, groupBy, from, to } = _lprData();
  if (!rows.length) { toast('Nothing to export', 'error'); return; }
  const esc = v => `"${String(v == null ? '' : v).replace(/"/g, '""')}"`;
  const lines = [['Group', 'Supplier', 'Invoice Ref', 'Type', 'Project', 'Invoice Date', 'Week Ending', 'Paid', 'CIS Retained', 'Gross'].map(esc).join(',')];
  for (const r of rows) {
    const groupLabel = groupBy === 'week' ? ('w/e ' + r.key) : r.key;
    for (const inv of r.invoices) {
      lines.push([
        groupLabel, inv.supplier_name || '', inv.invoice_ref || '',
        inv._kind === 'sub' ? 'CIS subcontractor' : 'Labour agency',
        inv.project_number || inv.job_number || inv.cost_centre || '',
        String(inv.invoice_date || '').slice(0, 10),
        inv._wk || '', inv.paid_at ? 'paid' : 'unpaid',
        inv._cis ? inv._cis.toFixed(2) : '', inv._gross.toFixed(2)
      ].map(esc).join(','));
    }
  }
  lines.push('');
  lines.push([groupBy === 'week' ? 'PER WEEK' : 'PER SUPPLIER', '', '', '', '', '', '', '', 'CIS', 'Gross'].map(esc).join(','));
  for (const r of rows) lines.push([groupBy === 'week' ? ('w/e ' + r.key) : r.key, '', '', '', '', '', '', '', r.cis ? r.cis.toFixed(2) : '', r.total.toFixed(2)].map(esc).join(','));
  lines.push(['', '', '', '', '', '', '', 'TOTAL', cisRetained.toFixed(2), total.toFixed(2)].map(esc).join(','));
  const blob = new Blob(['\ufeff' + lines.join('\r\n')], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `labour-payments-${from || ''}_${to || ''}.csv`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 5000);
}

// Native jsPDF Labour & Subcontractor Payments schedule — portrait A4 (CLAUDE.md PDF rules)
async function exportLabourPayPDF() {
  if (!_lprRows) { toast('Refresh first', 'error'); return; }
  const { rows, total, cisRetained, subTotal, agencyTotal, count, groupBy, from, to, unpaidOnly } = _lprData();
  if (!rows.length) { toast('Nothing to export', 'error'); return; }
  const JsPDFCtor = await resolveJsPDFCtor();
  await (typeof loadLogoDataUri === 'function' ? loadLogoDataUri() : Promise.resolve());
  const logo = (typeof _logoDataUriCache !== 'undefined' && _logoDataUriCache) || '';
  const doc = new JsPDFCtor({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  const pageW = 210, pageH = 297, mL = 12, mR = 12, W = pageW - 24;
  const accent = _houseAccent();
  const TEXT = HOUSE_INK, MUTED = HOUSE_MUTED, PURPLE = [128,90,180], RULE = HOUSE_RULE, HEAD = HOUSE_HEAD;
  const sT = c => doc.setTextColor(c[0],c[1],c[2]);
  const money = v => v == null ? '\u2014' : gbp2(v);
  const fmtD = iso => iso ? new Date(iso + 'T00:00:00').toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' }) : '\u2014';

  const period = (from ? fmtD(from) : 'start') + ' \u2013 ' + (to ? fmtD(to) : 'today');
  let y = bamaDocHeader(doc, logo, {
    title: 'LABOUR PAYMENTS', accent, marginL: mL, marginR: mR,
    meta: [
      { label: 'Period:',   value: period },
      { label: 'Invoices:', value: `${count}${unpaidOnly ? ' (unpaid only)' : ''}` },
      { label: 'Prepared:', value: new Date().toLocaleDateString('en-GB') }
    ]
  }).y;

  const kpis = [
    ['TOTAL LABOUR SPEND', money(total), accent],
    ['AGENCIES', money(agencyTotal), TEXT],
    ['SUBCONTRACTORS', money(subTotal), TEXT],
    ['CIS RETAINED', money(cisRetained), cisRetained > 0.005 ? PURPLE : MUTED],
    ['INVOICES', String(count), MUTED]
  ];
  const kw = W / kpis.length;
  kpis.forEach((k, i) => {
    const x = mL + i * kw;
    doc.setFillColor(HEAD[0],HEAD[1],HEAD[2]); doc.setDrawColor(RULE[0],RULE[1],RULE[2]); doc.setLineWidth(0.2); doc.roundedRect(x + 1, y, kw - 2, 14, 1.5, 1.5, 'FD');
    sT(MUTED); doc.setFontSize(5.6); doc.setFont('helvetica','bold'); doc.text(k[0], x + 3, y + 5);
    sT(k[2]); doc.setFontSize(9.5); doc.text(k[1], x + 3, y + 11);
  });
  y += 20;
  y = bamaSectionHeading(doc, y, 'LABOUR & SUBCONTRACTOR PAYMENTS', { accent, marginL: mL, usableW: W });

  const cols = [[groupBy === 'week' ? 'WEEK ENDING / INVOICE' : 'SUPPLIER / INVOICE', 70, 'left'], ['TYPE', 22, 'left'], ['PROJECT', 30, 'left'], ['DATE', 20], ['CIS', 20], ['GROSS', 24]];
  const xs = []; let acc = mL; cols.forEach(c => { xs.push(acc); acc += c[1]; });
  const head = () => {
    doc.setFillColor(HEAD[0],HEAD[1],HEAD[2]); doc.rect(mL, y, W, 6.5, 'F');
    doc.setDrawColor(RULE[0],RULE[1],RULE[2]); doc.setLineWidth(0.2); doc.rect(mL, y, W, 6.5);
    sT(TEXT); doc.setFont('helvetica','bold'); doc.setFontSize(6.6);
    cols.forEach((c, i) => doc.text(c[0], c[2] === 'left' ? xs[i] + 2 : xs[i] + c[1] - 2, y + 4.4, { align: c[2] === 'left' ? 'left' : 'right' }));
    y += 6.5;
  };
  head();

  const ensure = h => { if (y + h > pageH - 16) { doc.addPage(); y = bamaDocContinuation(doc, { title: 'LABOUR PAYMENTS', ref: period, marginL: mL, marginR: mR }).y; head(); } };
  for (const r of rows) {
    ensure(7);
    const label = groupBy === 'week' ? ('w/e ' + fmtD(r.key)) : r.key;
    doc.setFillColor(244,246,249); doc.rect(mL, y, W, 6, 'F');
    sT(TEXT); doc.setFont('helvetica','bold'); doc.setFontSize(8);
    doc.text(doc.splitTextToSize(label, cols[0][1] - 4)[0], xs[0] + 2, y + 4.2);
    if (r.cis > 0.005) { sT(PURPLE); doc.setFont('helvetica','normal'); doc.setFontSize(7.4); doc.text(money(r.cis), xs[4] + cols[4][1] - 2, y + 4.2, { align: 'right' }); }
    sT(TEXT); doc.setFont('helvetica','bold'); doc.setFontSize(8);
    doc.text(money(r.total), xs[5] + cols[5][1] - 2, y + 4.2, { align: 'right' });
    y += 6;
    doc.setFontSize(7.2); doc.setFont('helvetica','normal');
    for (const inv of r.invoices) {
      ensure(5);
      const sub2 = groupBy === 'week' ? (inv.supplier_name || '') : (inv.invoice_ref || ('#' + inv.id));
      sT(MUTED);
      doc.text('   ' + doc.splitTextToSize(sub2, cols[0][1] - 8)[0], xs[0] + 2, y + 3.8);
      doc.text(inv._kind === 'sub' ? 'CIS sub' : 'Agency', xs[1] + 2, y + 3.8);
      doc.text(doc.splitTextToSize(inv.project_number || inv.job_number || inv.cost_centre || '', cols[2][1] - 2)[0] || '', xs[2] + 2, y + 3.8);
      doc.text(fmtD(inv.invoice_date ? String(inv.invoice_date).slice(0, 10) : null), xs[3] + cols[3][1] - 2, y + 3.8, { align: 'right' });
      if (inv._cis > 0.005) { sT(PURPLE); doc.text(money(inv._cis), xs[4] + cols[4][1] - 2, y + 3.8, { align: 'right' }); }
      sT(TEXT); doc.text(money(inv._gross), xs[5] + cols[5][1] - 2, y + 3.8, { align: 'right' });
      doc.setDrawColor(RULE[0],RULE[1],RULE[2]); doc.setLineWidth(0.1); doc.line(mL, y + 5, mL + W, y + 5);
      y += 5;
    }
  }
  ensure(9);
  y += 2;
  doc.setDrawColor(TEXT[0],TEXT[1],TEXT[2]); doc.setLineWidth(0.4); doc.line(mL, y, mL + W, y);
  y += 5;
  sT(TEXT); doc.setFont('helvetica','bold'); doc.setFontSize(10);
  doc.text('TOTAL LABOUR SPEND', xs[0] + 2, y);
  if (cisRetained > 0.005) { sT(PURPLE); doc.setFontSize(8); doc.text('CIS ' + money(cisRetained), xs[4] + cols[4][1] - 2, y, { align: 'right' }); }
  sT(accent); doc.setFontSize(10); doc.text(money(total), xs[5] + cols[5][1] - 2, y, { align: 'right' });
  y += 8;
  sT(MUTED); doc.setFont('helvetica','normal'); doc.setFontSize(6.5);
  doc.splitTextToSize('Gross (amount payable) labour invoices by invoice date. "Agency" = a labour-supplier-tagged company (e.g. WPS) supplying workers; "CIS sub" = a subcontractor invoice with the CIS deduction retained for HMRC. ' + (unpaidOnly ? 'Unpaid invoices only. ' : 'Paid and unpaid invoices. ') + 'Materials suppliers are excluded. Figures are live from the ERP at time of printing.', W).forEach(l => { doc.text(l, mL, y); y += 3.2; });

  bamaDocFooter(doc, { marginL: mL, marginR: mR, size: 7,
    caption: 'Labour & Subcontractor Payments  \u00b7  BAMA Fabrication Ltd' });
  const blob = doc.output('blob');
  console.log('[Labour Pay PDF] blob size:', blob.size);
  doc.save(`labour-payments-${from || ''}_${to || ''}.pdf`);
}

// ═══════════════════════════════════════════════════════════════════════════
// FAB OUTPUT — kg per person per day from JobAssemblyActions (Phase C2b)
// ═══════════════════════════════════════════════════════════════════════════
let _foRows = null, _foMeta = null;

async function renderFabOutputReport(run) {
  const grid = document.getElementById('foGrid');
  if (!grid) return;
  const fromEl = document.getElementById('foFrom'), toEl = document.getElementById('foTo');
  if (fromEl && !fromEl.value) {
    const t = new Date(); const f = new Date(t.getTime() - 13 * 86400000);
    fromEl.value = f.toISOString().slice(0, 10);
    toEl.value   = t.toISOString().slice(0, 10);
  }
  if (!run && !_foRows) return;
  const from = fromEl?.value, to = toEl?.value;
  if (!from || !to || from > to) { grid.innerHTML = '<div style="padding:20px;color:var(--red);font-size:12px">Pick a valid date range.</div>'; return; }
  const days = Math.round((new Date(to) - new Date(from)) / 86400000) + 1;
  if (days > 31) { grid.innerHTML = '<div style="padding:20px;color:var(--red);font-size:12px">Range capped at 31 days — narrow the dates.</div>'; return; }

  if (run) {
    grid.innerHTML = '<div style="padding:30px;text-align:center;color:var(--muted);font-size:12px">Loading…</div>';
    const stage = document.getElementById('foStage')?.value || '';
    try {
      _foRows = await api.get(`/api/fab-output?from=${from}&to=${to}${stage ? '&stage=' + stage : ''}`);
      _foMeta = { from, to, stage };
    } catch (e) {
      grid.innerHTML = `<div style="padding:20px;color:var(--red);font-size:12px">Could not load fab output: ${escapeHtml(e.message)}</div>`;
      return;
    }
  }

  const rows = _foRows || [];
  const dates = [];
  for (let d = new Date(_foMeta.from + 'T12:00:00'); d <= new Date(_foMeta.to + 'T12:00:00'); d = new Date(d.getTime() + 86400000)) {
    dates.push(d.toISOString().slice(0, 10));
  }
  const dayName = iso => new Date(iso + 'T12:00:00').toLocaleDateString('en-GB', { weekday: 'short' });
  const isWeekend = iso => [0, 6].includes(new Date(iso + 'T12:00:00').getDay());
  const jobHue = key => { let h = 0; const s = String(key); for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h % 360; };
  const chipStyle = key => {
    const hue = jobHue(key);
    return `display:inline-flex;align-items:center;gap:4px;padding:1px 7px;border-radius:20px;` +
           `background:hsla(${hue},70%,55%,.14);border:1px solid hsla(${hue},70%,60%,.45);` +
           `color:hsl(${hue},75%,72%);font-size:10.5px;line-height:1.7;white-space:nowrap`;
  };
  const fmtKg = v => v >= 1000 ? (Math.round(v / 100) / 10).toLocaleString('en-GB') + 't' : Math.round(v).toLocaleString('en-GB') + 'kg';

  // matrix[person][date][job] = {kg, pcs}
  const matrix = {}, rowTotals = {}, dayTotals = {}, jobTotals = {};
  for (const r of rows) {
    const person = r.operator || 'Unassigned';
    const job = r.project_number || '—';
    const kg = parseFloat(r.kg) || 0, pcs = parseInt(r.qty) || 0;
    ((matrix[person] = matrix[person] || {})[r.date] = matrix[person][r.date] || {});
    const c = matrix[person][r.date][job] = matrix[person][r.date][job] || { kg: 0, pcs: 0 };
    c.kg += kg; c.pcs += pcs;
    rowTotals[person] = (rowTotals[person] || 0) + kg;
    dayTotals[r.date] = (dayTotals[r.date] || 0) + kg;
    jobTotals[job]    = (jobTotals[job]    || 0) + kg;
  }
  const people = Object.keys(matrix).sort((a, b) => (rowTotals[b] || 0) - (rowTotals[a] || 0));
  if (!people.length) { grid.innerHTML = '<div style="padding:20px;color:var(--muted);font-size:12px">No stage moves in this range.</div>'; return; }

  const csvBtn = document.getElementById('foCsvBtn'); if (csvBtn) csvBtn.style.display = '';

  const STICKY_L = 'position:sticky;left:0;background:var(--card,#161616);z-index:2;box-shadow:2px 0 6px rgba(0,0,0,.35)';
  const STICKY_R = 'position:sticky;right:0;background:var(--card,#161616);z-index:2;box-shadow:-2px 0 6px rgba(0,0,0,.35)';
  const th = 'padding:8px 6px;font-size:9.5px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;border-bottom:2px solid var(--border);white-space:nowrap;text-align:center';

  let html = `<div style="overflow-x:auto;border:1px solid var(--border);border-radius:10px;background:var(--card,#161616)">
    <table style="border-collapse:separate;border-spacing:0;font-size:11px;min-width:100%">
    <thead><tr>
      <th style="${th};text-align:left;${STICKY_L};padding-left:12px">Person</th>
      ${dates.map(d => `<th style="${th};${isWeekend(d) ? 'color:var(--border)' : ''}">${dayName(d)}<br><span style="font-size:10.5px;color:${isWeekend(d) ? 'var(--border)' : 'var(--text)'}">${d.slice(8)}/${d.slice(5, 7)}</span></th>`).join('')}
      <th style="${th};text-align:right;${STICKY_R};padding-right:12px">Total</th>
    </tr></thead><tbody>`;
  people.forEach((pk, ri) => {
    const zebra = ri % 2 ? 'background:rgba(255,255,255,.018)' : '';
    html += `<tr>
      <td style="padding:8px 12px;font-weight:600;white-space:nowrap;${STICKY_L};border-bottom:1px solid var(--border);${pk === 'Unassigned' ? 'color:var(--muted);font-style:italic' : ''}">${escapeHtml(pk)}</td>`;
    for (const d of dates) {
      const cell = matrix[pk][d];
      const we = isWeekend(d) ? 'background:rgba(255,255,255,.025);' : zebra + ';';
      if (!cell) { html += `<td style="padding:6px;text-align:center;color:rgba(255,255,255,.08);border-bottom:1px solid var(--border);${we}">·</td>`; continue; }
      const parts = Object.entries(cell).sort((a, b) => b[1].kg - a[1].kg)
        .map(([job, c]) => `<span style="${chipStyle(job)}" title="${escapeHtml(job)} — ${fmtKg(c.kg)} across ${c.pcs} piece${c.pcs !== 1 ? 's' : ''}">${escapeHtml(job)} <strong style="font-family:var(--font-mono);font-weight:700">${fmtKg(c.kg)}</strong><span style="opacity:.6;font-size:9.5px">·${c.pcs}pc</span></span>`);
      html += `<td style="padding:5px 6px;vertical-align:top;border-bottom:1px solid var(--border);${we}"><div style="display:flex;flex-direction:column;gap:3px;align-items:flex-start">${parts.join('')}</div></td>`;
    }
    html += `<td style="padding:8px 12px;text-align:right;font-family:var(--font-mono);font-weight:700;${STICKY_R};border-bottom:1px solid var(--border)">${fmtKg(rowTotals[pk] || 0)}</td></tr>`;
  });
  const grand = Object.values(rowTotals).reduce((s, v) => s + v, 0);
  html += `<tr>
      <td style="padding:8px 12px;font-weight:700;${STICKY_L};border-top:2px solid var(--border)">Total</td>
      ${dates.map(d => `<td style="padding:6px;text-align:center;font-family:var(--font-mono);font-size:10.5px;color:var(--muted);border-top:2px solid var(--border)">${dayTotals[d] ? fmtKg(dayTotals[d]) : ''}</td>`).join('')}
      <td style="padding:8px 12px;text-align:right;font-family:var(--font-mono);font-weight:700;font-size:12.5px;color:var(--accent);${STICKY_R};border-top:2px solid var(--border)">${fmtKg(grand)}</td>
    </tr></tbody></table></div>`;

  const legend = Object.entries(jobTotals).sort((a, b) => b[1] - a[1])
    .map(([k, kg]) => `<span style="${chipStyle(k)};font-size:11px;padding:3px 10px">${escapeHtml(k)} <strong style="font-family:var(--font-mono)">${fmtKg(kg)}</strong> <span style="opacity:.65;font-size:10px">${grand ? Math.round(kg / grand * 100) : 0}%</span></span>`).join(' ');
  html += `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;align-items:center">
      <span style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em">Jobs this period</span>${legend}
    </div>
    <div style="font-size:10.5px;color:var(--subtle);margin-top:8px">Kilograms = pieces × assembly weight from the drawing. ${_foMeta.stage ? 'Stage: ' + _foMeta.stage + '.' : 'All stages (a piece fabricated then welded counts in both).'} People sorted by output. Weekends shaded.</div>`;
  grid.innerHTML = html;
}

function exportFabOutputCsv() {
  if (!_foRows || !_foMeta) { toast('Run the report first', 'error'); return; }
  const lines = ['date,person,stage,job,assembly,pieces,kg'];
  (_foRows || []).slice().sort((a, b) => String(a.date).localeCompare(String(b.date)))
    .forEach(r => lines.push([r.date, `"${(r.operator || 'Unassigned').replace(/"/g, '""')}"`, r.stage, r.project_number || '', r.assembly_mark || '', r.qty || 0, r.kg || 0].join(',')));
  const blob = new Blob([lines.join('\n')], { type: 'text/csv' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `fab-output-${_foMeta.from}-to-${_foMeta.to}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
  toast('CSV downloaded', 'success');
}

function exportProductivityCsv() {
  if (!_pgRows || !_pgMeta) { toast('Run the report first', 'error'); return; }
  const incS000 = document.getElementById('pgIncS000')?.checked;
  const rows = (_pgRows || []).filter(r => incS000 || r.project_number !== 'S000');
  const lines = ['date,employee,job,hours'];
  rows.slice().sort((a, b) => String(a.date).localeCompare(String(b.date)) || String(a.employee_name).localeCompare(String(b.employee_name)))
    .forEach(r => lines.push([String(r.date).slice(0, 10), `"${(r.employee_name || '').replace(/"/g, '""')}"`, r.project_number || '', parseFloat(r.hours) || 0].join(',')));
  const blob = new Blob([lines.join('\n')], { type: 'text/csv' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `productivity-${_pgMeta.from}-to-${_pgMeta.to}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
  toast('CSV downloaded', 'success');
}

function selectReportsEmployee(name) {
  const emp = (state.timesheetData.employees || []).find(e => e.name === name);
  if (!emp) return;
  if (!emp.hasPin) { toast('No PIN set for this user.', 'error'); return; }
  _pendingReportsUser = { name, empId: emp.id };
  document.getElementById('reportsPinUser').textContent = name;
  document.getElementById('reportsPinInput').value = '';
  document.getElementById('reportsPinError').textContent = '';
  document.getElementById('reportsPinModal').classList.add('active');
  setTimeout(() => document.getElementById('reportsPinInput').focus(), 200);
}

async function verifyReportsPin() {
  if (!_pendingReportsUser) return;
  const pin = document.getElementById('reportsPinInput').value;
  if (!pin) return;
  try {
    const result = await api.post('/api/auth/verify-pin', { employee_id: _pendingReportsUser.empId, pin });
    if (!result || !result.valid) {
      document.getElementById('reportsPinError').textContent = (result && result.reason) || 'Incorrect PIN';
      document.getElementById('reportsPinInput').value = '';
      return;
    }
    currentManagerUser = _pendingReportsUser.name;
    pinSessionSet(currentManagerUser);
    document.getElementById('reportsPinModal').classList.remove('active');
    const perms = getUserPermissions(currentManagerUser);
    if (!perms || !perms.reports) {
      showReportsPermDenied();
      return;
    }
    showReportsLayout();
  } catch (err) {
    document.getElementById('reportsPinError').textContent = 'PIN verification failed';
    document.getElementById('reportsPinInput').value = '';
  }
}

// ═══════════════════════════════════════════
// BABCOCK QUOTES PAGE
// ═══════════════════════════════════════════

let _babcockWorkbook = null;    // parsed XLSX workbook
let _babcockOriginalFile = null; // raw File object — needed to upload to SharePoint
let _babcockRawData = null;     // array of line items extracted from Quote tab
let _babcockHeader = null;      // header metadata extracted from Quote tab
let _babcockParsedByAI = false; // true when the AI fallback parser was used (upload path)
let _babcockEntryMode = 'upload'; // 'upload' | 'manual'
let _pendingBabcockUser = null;
let _babcockQuotes = [];        // tracker list (loaded from API)
let _babcockLastGenerated = null; // cached payload for "Save to Tracker"
let _babcockSort = { col: null, dir: 'asc' }; // tracker column sort state
let _babcockLineItemsRecord = null; // full record open in line-items edit modal
let _babcockNextRefCache = null;  // cached suggested next reference

// Lightweight email validator. Not RFC-perfect by design — we just want
// to catch obvious typos before pushing the value to the DB / using it
// as a "To:" recipient. Rules: must contain @, must contain . after the
// @, no internal whitespace.
function isPlausibleEmail(s) {
  if (!s) return false;
  const trimmed = String(s).trim();
  if (!trimmed) return false;
  if (/\s/.test(trimmed)) return false;
  const at = trimmed.indexOf('@');
  if (at < 1) return false; // need at least one char before @
  const domain = trimmed.slice(at + 1);
  if (!domain.includes('.')) return false;
  if (domain.endsWith('.')) return false;
  return true;
}

// ─────────────────────────────────────────────────────────────────────
// EMAIL COMPOSER (Babcock workflow)
// ─────────────────────────────────────────────────────────────────────
// Reusable in-app New Email window — used by every Babcock workflow
// step that sends mail (Generate Quote → client; Bama SW Invoice →
// Bama SW; Bama SW Final Invoice → Bama SW). On Send, the email goes
// via Microsoft Graph sendMail, attachment included as a base64 blob.
// The email lands in the user's actual Outlook Sent folder as if they'd
// composed it themselves — no Outlook desktop window opens.
//
// Caller API:
//   await openBabcockEmailModal({
//     title: 'Email Quote',                     // modal heading
//     templateKey: 'emailQuoteSent',            // which body template
//     tokens: { quote_ref: 'B0011', ... },      // values to substitute
//     to: 'john@babcock.com',                   // initial To (editable)
//     cc: '',                                   // initial Cc (optional)
//     attachment: {                             // optional but expected
//       name: 'B0011 - ....pdf',
//       contentType: 'application/pdf',
//       contentBase64: 'JVBERi0xLjQK...'        // raw base64, no data: prefix
//     },
//     onSent: (result) => { ... }               // called after success
//   });
// Returns the result object on send, null on cancel.

// Cached state for the active modal session — populated by open(),
// consumed by send(). Cleared by close().
let _bemailContext = null;

// One-shot cache of the logged-in Microsoft user's display name + email.
// Pulled from Graph /me on first need; null until then. Used to populate
// the From: line and the {{sender_email}} token. Falls back gracefully
// if the call ever fails — we'd rather send the email with the address
// missing than block on it.
let _meCache = null;
async function getCurrentMicrosoftUser() {
  if (_meCache) return _meCache;
  try {
    const token = await getToken();
    const res = await fetch('https://graph.microsoft.com/v1.0/me', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    if (!res.ok) return null;
    const me = await res.json();
    _meCache = {
      name:  me.displayName || '',
      email: me.mail || me.userPrincipalName || ''
    };
    return _meCache;
  } catch (e) {
    console.warn('Graph /me lookup failed (non-fatal):', e.message);
    return null;
  }
}

// Build the full token map used for Subject/Body/Signature substitution.
// The caller passes per-email tokens (quote_ref, project_name, etc.);
// we layer on the user-side tokens (sender_*, date_today). User-side
// tokens are async because of the Graph /me call.
async function buildBabcockEmailTokens(callerTokens) {
  const me = await getCurrentMicrosoftUser();
  // Pull role from the BAMA Employees row matching currentManagerUser.
  // Falls back to the Microsoft display name if we don't have an
  // Employees row — useful in dev / first-run scenarios.
  let senderName = currentManagerUser || (me && me.name) || 'Accounts Team';
  let senderRole = '';
  if (currentManagerUser && state.timesheetData && state.timesheetData.employees) {
    const emp = state.timesheetData.employees.find(e => e.name === currentManagerUser);
    if (emp && emp.erpRole) senderRole = emp.erpRole;
  }
  // Signature role line: "Role — BAMA Fabrication" or just the company
  const senderSigRole = senderRole ? `${senderRole} \u2014 BAMA Fabrication` : 'BAMA Fabrication';
  // Today's date in UK format ("07 May 2026") — matches the rest of the app.
  const todayLong = new Date().toLocaleDateString('en-GB', {
    day: '2-digit', month: 'long', year: 'numeric'
  });
  // Logo: load the SharePoint data URI so the signature renders with the
  // actual image rather than the red BAMA text fallback. Silently falls
  // back to the red span if no logo is uploaded or the fetch fails.
  const logoDataUri = await loadLogoDataUri();
  const logoImg = logoDataUri
    ? `<img src="${logoDataUri}" alt="BAMA Fabrication" style="height:48px;width:auto;display:block">`
    : `<span style="display:inline-block;background:#D0021B;color:#fff;padding:6px 14px;font-weight:bold;letter-spacing:1px;border-radius:3px">BAMA</span>`;
  return Object.assign({}, callerTokens || {}, {
    sender_name:  senderName,
    sender_sig_role: senderSigRole,
    sender_role:  senderRole,
    sender_email: (me && me.email) || '',
    date_today:   todayLong,
    logo_img:     logoImg
  });
}

// Read a template's draft value (subject / body / html) from saved
// Settings, falling back to the in-code TEMPLATE_DEFAULTS. This is
// what we render on Send — never read from tplDraft (that's the
// editor's working copy on the templates page only).
function getEmailTemplateField(templateKey, field) {
  const tpls = (state.timesheetData.settings && state.timesheetData.settings.templates) || {};
  const block = tpls[templateKey] || {};
  if (block[field] !== undefined && block[field] !== null && block[field] !== '') return block[field];
  return TEMPLATE_DEFAULTS[templateKey] ? (TEMPLATE_DEFAULTS[templateKey][field] || '') : '';
}

async function openBabcockEmailModal(opts) {
  if (!opts || !opts.templateKey) {
    console.error('openBabcockEmailModal: templateKey is required');
    return null;
  }

  // Build the resolved tokens (caller tokens + sender_*, date_today)
  const tokens = await buildBabcockEmailTokens(opts.tokens || {});

  // Resolve subject and body from templates with substitution
  const subjectTpl = getEmailTemplateField(opts.templateKey, 'subject');
  const bodyTpl    = getEmailTemplateField(opts.templateKey, 'body');
  const sigHtmlTpl = getEmailTemplateField('emailSignature', 'html');

  const resolvedSubject = renderTemplate(subjectTpl, tokens);
  const resolvedBody    = renderTemplate(bodyTpl, tokens);
  const resolvedSig     = renderTemplate(sigHtmlTpl, tokens);

  // Wire up the From: row using the cached Graph user
  const me = await getCurrentMicrosoftUser();
  const fromText = me
    ? `${me.name || 'BAMA Fabrication'} <${me.email || ''}>`
    : 'BAMA Fabrication (sending from your account)';
  // The email goes out via Graph /me/sendMail — i.e. from whichever
  // Microsoft account this browser session is signed in as, which may not
  // be the person who PIN'd into the ERP. Make the mismatch loud.
  const _mismatch = !!(me && me.name && typeof currentManagerUser === 'string' && currentManagerUser
    && me.name.toLowerCase() !== currentManagerUser.toLowerCase());

  // Stash everything we'll need on Send
  _bemailContext = {
    templateKey: opts.templateKey,
    tokens,
    resolvedSubject,
    resolvedBody,
    resolvedSig,
    attachment: opts.attachment || null,
    fromName: (me && me.name) || 'BAMA Fabrication',
    fromEmail: (me && me.email) || '',
    onSent: typeof opts.onSent === 'function' ? opts.onSent : null,
    // Promise plumbing — openBabcockEmailModal can be awaited
    _resolve: null,
    sentResult: null
  };

  _bemailContext.aiDraft = opts.aiDraft || null;
  _bemailContext.fallbackBody = resolvedBody;

  // Populate the modal
  document.getElementById('bemailTitle').textContent  = opts.title || 'New Email';
  const fromEl = document.getElementById('bemailFrom');
  fromEl.textContent = fromText;
  fromEl.style.color = _mismatch ? '#ffa500' : 'var(--text)';
  fromEl.title = _mismatch
    ? `This browser is signed into Microsoft as ${me.name} — the email will be sent from their mailbox, not ${currentManagerUser}'s.`
    : '';
  let warnEl = document.getElementById('bemailFromWarn');
  if (!warnEl) {
    warnEl = document.createElement('div');
    warnEl.id = 'bemailFromWarn';
    warnEl.style.cssText = 'font-size:11px;color:#ffa500;margin-top:2px';
    fromEl.parentNode.appendChild(warnEl);
  }
  warnEl.textContent = _mismatch
    ? `⚠ Sends from ${me.name}'s mailbox (this browser's Microsoft login) — sign in with your own account to send as yourself.`
    : '';
  document.getElementById('bemailTo').value           = opts.to || '';
  document.getElementById('bemailCc').value           = opts.cc || '';
  document.getElementById('bemailSubject').value      = resolvedSubject;
  document.getElementById('bemailBody').value         = resolvedBody;

  // AI drafting bar (tone select + redraft) — injected once, shown only
  // when the caller supplies an aiDraft context. Mirrors the QB flow.
  _ensureBemailToneBar(!!opts.aiDraft);
  if (opts.aiDraft) {
    const toneSel = document.getElementById('bemailTone');
    if (toneSel) toneSel.value = opts.aiDraft.defaultTone || 'warm';
    draftBabcockEmailBody();
  }

  // Signature preview (collapsed by default — toggle expands)
  const sigPreview = document.getElementById('bemailSigPreview');
  sigPreview.innerHTML = resolvedSig;
  sigPreview.style.display = 'none';
  document.getElementById('bemailSigToggleArrow').textContent = '\u25B8';
  document.getElementById('bemailSigToggleText').textContent  = 'Show signature';

  // Attachment row
  const atName = document.getElementById('bemailAttachName');
  const atSize = document.getElementById('bemailAttachSize');
  if (opts.attachment && opts.attachment.name) {
    atName.textContent = opts.attachment.name;
    // base64-encoded → original byte size = b64.length * 3/4 (minus padding).
    // Good enough for a UI hint without decoding.
    if (opts.attachment.contentBase64) {
      const padding = (opts.attachment.contentBase64.match(/=+$/) || [''])[0].length;
      const bytes   = Math.floor(opts.attachment.contentBase64.length * 3 / 4) - padding;
      atSize.textContent = formatFileSize(bytes);
    } else {
      atSize.textContent = '';
    }
  } else {
    atName.textContent = 'No attachment';
    atSize.textContent = '—';
  }

  // Reset the Send button (in case a previous send left it disabled)
  const btn = document.getElementById('bemailSendBtn');
  if (btn) { btn.disabled = false; btn.textContent = 'Send Email'; }
  document.getElementById('babcockEmailModal').classList.add('active');
  setTimeout(() => document.getElementById('bemailTo')?.focus(), 80);

  // Return a promise that resolves on send/cancel — enables `await`
  return await new Promise(resolve => { _bemailContext._resolve = resolve; });
}

// ── Tender notification modal ────────────────────────────────────────────────
// Opens the email modal for a new tender notification.
// Returns 'sent' | 'later' | 'skip' based on user action.
// Also always creates an office task for the assigned person.

// ── Reassign tender to a different person ────────────────────────────────────

// ── Send quote to client from Quote Builder ──────────────────────────────────
// Called by the "✉ Send to Client" button in QB.
// Generates the client-facing PDF, then opens the email modal pre-filled
// with the client contact details from the saved quote.
async function sendQuoteToClient(quote, pdfBase64) {
  if (!quote) { toast('No quote loaded', 'error'); return; }

  const contactEmail = quote.clientEmail || quote.contact_email || '';
  const contactName  = quote.clientName  || quote.contact_name  || '';
  const companyName  = quote.company     || quote.company_name  || '';

  // CC = currently logged-in user
  const me = await getCurrentMicrosoftUser();
  const myEmail = (me && me.email) || '';

  const grandTotal = typeof quote.grandTotal === 'number'
    ? '£' + quote.grandTotal.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
    : '';

  const attachment = pdfBase64 ? {
    name: `${quote.ref || 'Quote'} - ${companyName || 'Client'}.pdf`,
    contentType: 'application/pdf',
    contentBase64: pdfBase64
  } : null;

  await openBabcockEmailModal({
    title: 'Send Quote to Client',
    templateKey: 'emailQuoteClient',
    to:  contactEmail,
    cc:  myEmail,
    tokens: {
      contact_name: contactName,
      quote_ref:    quote.ref     || '',
      project_name: quote.project || '',
      company_name: companyName,
      total_value:  grandTotal
    },
    attachment
  });
}

function closeBabcockEmailModal() {
  document.getElementById('babcockEmailModal').classList.remove('active');
  if (_bemailContext && _bemailContext._resolve) {
    _bemailContext._resolve(_bemailContext.sentResult || null);
  }
  _bemailContext = null;
}


function toggleBabcockEmailSignature() {
  const div    = document.getElementById('bemailSigPreview');
  const arrow  = document.getElementById('bemailSigToggleArrow');
  const text   = document.getElementById('bemailSigToggleText');
  const open   = div.style.display !== 'none';
  div.style.display = open ? 'none' : '';
  arrow.textContent = open ? '\u25B8' : '\u25BE';
  text.textContent  = open ? 'Show signature' : 'Hide signature';
}

// Send via Graph /me/sendMail. Body is plain-text from the textarea —
// converted to HTML (newlines → <br>, escaped) and concatenated with
// the signature HTML. Attachment is included as base64 if present.
// ── AI drafting for the generic composer (QB-style: warm/brief/firm) ──────
function _ensureBemailToneBar(show) {
  let bar = document.getElementById('bemailToneBar');
  const bodyEl = document.getElementById('bemailBody');
  if (!bar && bodyEl) {
    bar = document.createElement('div');
    bar.id = 'bemailToneBar';
    bar.style.cssText = 'display:flex;gap:8px;align-items:center;margin-bottom:6px';
    bar.innerHTML = `
      <span style="font-size:11px;color:var(--muted)">AI draft:</span>
      <select id="bemailTone" onchange="draftBabcockEmailBody()"
              style="background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:5px 8px;color:var(--text);font-size:12px">
        <option value="warm">Warm</option>
        <option value="brief">Brief</option>
        <option value="firm">Firm</option>
      </select>
      <button type="button" class="btn btn-ghost" id="bemailRedraftBtn"
              style="padding:4px 10px;font-size:12px" onclick="draftBabcockEmailBody()">↻ Redraft</button>
      <span id="bemailDraftStatus" style="font-size:11px;color:var(--muted)"></span>`;
    bodyEl.parentNode.insertBefore(bar, bodyEl);
  }
  if (bar) bar.style.display = show ? 'flex' : 'none';
}

async function draftBabcockEmailBody() {
  if (!_bemailContext || !_bemailContext.aiDraft) return;
  const bodyEl = document.getElementById('bemailBody');
  const btn = document.getElementById('bemailRedraftBtn');
  const sts = document.getElementById('bemailDraftStatus');
  if (!bodyEl) return;

  const tone = document.getElementById('bemailTone')?.value || 'warm';
  const toneGuide = {
    warm:  'Warm and friendly, relationship-first. Light and unhurried.',
    brief: 'Very short and to the point — three or four sentences maximum, no filler.',
    firm:  'Polite but direct — convey quiet professionalism, without being pushy.'
  }[tone];

  bodyEl.value = 'Drafting…';
  if (btn) btn.disabled = true;
  if (sts) sts.textContent = '';

  const prompt = `${_bemailContext.aiDraft.context}

Tone: ${toneGuide}

RULES:
- Write ONLY the email body. No subject line, no "Subject:", no preamble.
- Open with an appropriate greeting using the contact's first name if available, otherwise "Dear Sir/Madam".
- Do NOT write any sign-off, "Kind regards", name, company name, or signature block at the end — a signature is added automatically. End with the last sentence of the message.
- Strictly UK English. Natural, professional, no marketing fluff, no exclamation marks.`;

  try {
    const requestBody = {
      model: 'claude-sonnet-4-6',
      max_tokens: 800,
      messages: [{ role: 'user', content: prompt }]
    };
    const doFetch = () => fetch(API_BASE + '/api/claude-proxy', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${sessionStorage.getItem('bama_token')}` },
      body: JSON.stringify(requestBody)
    });
    let response = await doFetch();
    let data = await response.json();
    if (response.status === 429) {
      if (sts) sts.textContent = 'Rate limit — waiting 30s…';
      await new Promise(r => setTimeout(r, 30000));
      response = await doFetch();
      data = await response.json();
    }
    if (data.error) throw new Error(data.error.message);
    const text = (data.content || []).filter(x => x.type === 'text').map(x => x.text).join('\n').trim();
    bodyEl.value = text || _bemailContext.fallbackBody;
    if (sts) sts.textContent = '';
  } catch (e) {
    bodyEl.value = _bemailContext.fallbackBody;
    if (sts) sts.textContent = 'AI draft unavailable — using standard template';
    console.warn('AI email draft failed:', e);
  }
  if (btn) btn.disabled = false;
}

async function sendBabcockEmail() {
  if (!_bemailContext) return;

  const to       = (document.getElementById('bemailTo').value || '').trim();
  const ccRaw    = (document.getElementById('bemailCc').value || '').trim();
  const subject  = (document.getElementById('bemailSubject').value || '').trim();
  const bodyText = document.getElementById('bemailBody').value || '';

  // Validate required fields
  if (!isPlausibleEmail(to)) {
    toast(to ? 'Recipient email doesn\u2019t look valid' : 'Recipient email is required', 'error');
    document.getElementById('bemailTo').focus();
    return;
  }
  if (!subject) {
    toast('Subject line is required', 'error');
    document.getElementById('bemailSubject').focus();
    return;
  }

  // Parse Cc (comma-separated). Silently drop invalid entries — not
  // worth blocking the send, but warn in console for debugging.
  const ccList = ccRaw
    ? ccRaw.split(',').map(s => s.trim()).filter(Boolean)
    : [];
  const ccRecipients = [];
  for (const cc of ccList) {
    if (isPlausibleEmail(cc)) {
      ccRecipients.push({ emailAddress: { address: cc } });
    } else {
      console.warn('Skipping invalid Cc address:', cc);
    }
  }

  // Build HTML body: escape user text + convert newlines + append signature
  const escapedBody = escapeHtml(bodyText).replace(/\n/g, '<br>');
  const htmlBody = `
    <div style="font-family:'Segoe UI',system-ui,sans-serif;font-size:14px;color:#222;line-height:1.6">
      ${escapedBody}
    </div>
    ${_bemailContext.resolvedSig || ''}
  `;

  // Build the Graph payload
  const message = {
    subject: subject,
    body: { contentType: 'HTML', content: htmlBody },
    toRecipients: [{ emailAddress: { address: to } }]
  };
  if (ccRecipients.length) message.ccRecipients = ccRecipients;
  if (_bemailContext.attachment && _bemailContext.attachment.contentBase64) {
    message.attachments = [{
      '@odata.type':    '#microsoft.graph.fileAttachment',
      name:             _bemailContext.attachment.name || 'attachment',
      contentType:      _bemailContext.attachment.contentType || 'application/octet-stream',
      contentBytes:     _bemailContext.attachment.contentBase64
    }];
  }

  // Disable the button + show progress
  const btn = document.getElementById('bemailSendBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Sending\u2026'; }

  try {
    const token = await getToken();
    const res = await fetch('https://graph.microsoft.com/v1.0/me/sendMail', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ message, saveToSentItems: true })
    });

    if (res.ok || res.status === 202) {
      const result = {
        ok: true,
        sent: true,
        to,
        cc: ccList,
        subject,
        sentAt: new Date().toISOString()
      };
      _bemailContext.sentResult = result;
      toast(`Email sent to ${to} \u2713`, 'success');
      // Fire the caller callback BEFORE close so it can do follow-up
      // work (e.g. a status PUT) without the modal disappearing yet.
      if (_bemailContext.onSent) {
        try { await _bemailContext.onSent(result); }
        catch (cbErr) { console.error('onSent callback failed:', cbErr); }
      }
      closeBabcockEmailModal();
    } else {
      const errText = await res.text().catch(() => '');
      console.error('sendMail failed:', res.status, errText);
      toast(`Email failed: ${res.status} \u2014 check console`, 'error');
      if (btn) { btn.disabled = false; btn.textContent = 'Send Email'; }
    }
  } catch (e) {
    console.error('sendMail error:', e);
    toast('Email failed: ' + (e.message || 'unknown error'), 'error');
    if (btn) { btn.disabled = false; btn.textContent = 'Send Email'; }
  }
}

async function initBabcockPage() {
  const authed = pinSessionGet();
  if (authed) {
    currentManagerUser = authed;
    const perms = getUserPermissions(currentManagerUser);
    if (perms && perms.tenders) {
      document.getElementById('screenBabcockSelect').style.display = 'none';
      document.getElementById('babcockLayout').style.display = 'flex';
      loadBabcockTracker();
      return;
    }
  }
  renderBabcockEmployeeGrid();
}

function renderBabcockEmployeeGrid() {
  const grid = document.getElementById('babcockEmployeeGrid');
  if (!grid) return;
  const empList = (state.timesheetData.employees || []).filter(e => e.active !== false && (e.staffType || 'workshop') === 'office');
  if (!empList.length) {
    grid.innerHTML = '<div class="empty-state" style="padding:30px"><div style="font-size:28px;margin-bottom:10px">&#128101;</div><div>No office staff set up yet.</div></div>';
    return;
  }
  grid.innerHTML = empList.map(emp => {
    const ini = (emp.name || '').split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
    const col = empColor(emp.name);
    return `
      <div class="emp-btn" onclick="selectBabcockEmployee('${emp.name.replace(/'/g, "\\\\'")}')">
        <div class="emp-avatar" style="width:48px;height:48px;font-size:19px;background:linear-gradient(135deg,${col},#3e1a00)">${ini}</div>
        <div class="emp-name" style="font-size:13px">${emp.name}</div>
        <div style="font-size:10px;color:var(--subtle);margin-top:3px">${emp.hasPin ? '&#128274; PIN set' : '&#128275; No PIN'}</div>
      </div>`;
  }).join('');
}

function selectBabcockEmployee(name) {
  const emp = (state.timesheetData.employees || []).find(e => e.name === name);
  if (!emp) return;
  if (!emp.hasPin) { toast('No PIN set for this user.', 'error'); return; }
  _pendingBabcockUser = { name, empId: emp.id };
  document.getElementById('babcockPinUser').textContent = name;
  document.getElementById('babcockPinInput').value = '';
  document.getElementById('babcockPinError').textContent = '';
  document.getElementById('babcockPinModal').classList.add('active');
  setTimeout(() => document.getElementById('babcockPinInput').focus(), 200);
}

async function verifyBabcockPin() {
  if (!_pendingBabcockUser) return;
  const pin = document.getElementById('babcockPinInput').value;
  if (!pin) return;
  try {
    const result = await api.post('/api/auth/verify-pin', { employee_id: _pendingBabcockUser.empId, pin });
    if (!result || !result.valid) {
      document.getElementById('babcockPinError').textContent = (result && result.reason) || 'Incorrect PIN';
      document.getElementById('babcockPinInput').value = '';
      return;
    }
    currentManagerUser = _pendingBabcockUser.name;
    pinSessionSet(currentManagerUser);
    document.getElementById('babcockPinModal').classList.remove('active');
    const perms = getUserPermissions(currentManagerUser);
    if (!perms || !perms.tenders) {
      toast('You don\'t have permission to access Babcock Quotes.', 'error');
      currentManagerUser = null;
      pinSessionClear();
      return;
    }
    document.getElementById('screenBabcockSelect').style.display = 'none';
    document.getElementById('babcockLayout').style.display = 'flex';
    loadBabcockTracker();
  } catch (err) {
    document.getElementById('babcockPinError').textContent = 'PIN verification failed';
    document.getElementById('babcockPinInput').value = '';
  }
}

// ── File handling ──
function handleBabcockDrop(event) {
  const file = event.dataTransfer?.files?.[0];
  if (file) handleBabcockFileSelect(file);
}

async function handleBabcockFileSelect(file) {
  if (!file) return;
  const ext = file.name.split('.').pop().toLowerCase();
  if (!['xlsx', 'xls', 'pdf'].includes(ext)) {
    toast('Please upload an .xlsx, .xls or .pdf file', 'error');
    return;
  }

  // Show file info
  document.getElementById('babcockFileInfo').style.display = '';
  document.getElementById('babcockFileName').textContent = file.name;
  document.getElementById('babcockFileSize').textContent = formatFileSize(file.size);
  _babcockOriginalFile = file;
  _babcockParsedByAI = false;

  try {
    let parsed = null;
    let usedAI = false;

    if (ext === 'pdf') {
      // No deterministic PDF parser — go straight to AI vision.
      toast('Reading PDF with AI…', 'info');
      setLoading(true);
      parsed = await parseBabcockWithAI({ kind: 'pdf', file });
      usedAI = true;
    } else {
      // XLSX: try the strict parser first (free, exact). Fall back to AI
      // only if it throws or finds no line items (layout/header drift).
      const buf = await file.arrayBuffer();
      _babcockWorkbook = XLSX.read(buf, { type: 'array' });
      try {
        parsed = parseBabcockQuoteTab(_babcockWorkbook);
        if (!parsed.lineItems || !parsed.lineItems.length) throw new Error('no line items found');
      } catch (strictErr) {
        console.warn('Strict Babcock parse failed, falling back to AI:', strictErr.message);
        toast('Standard parse failed — reading with AI…', 'info');
        setLoading(true);
        parsed = await parseBabcockWithAI({ kind: 'csv', text: babcockWorkbookToCsv(_babcockWorkbook) });
        usedAI = true;
      }
    }

    if (!parsed || !parsed.lineItems || !parsed.lineItems.length) {
      toast('No line items could be extracted from this file.', 'error');
      return;
    }

    _babcockHeader = parsed.header;
    _babcockRawData = parsed.lineItems;
    _babcockParsedByAI = usedAI;

    populateBabcockValidationFields(_babcockHeader, parsed.missingFields || []);
    const markup = babcockCurrentMarkup();
    renderBabcockPreviewTable(markup);
    updateBabcockMarkedUpTotal(markup);
    document.getElementById('babcockRowCount').textContent = `${_babcockRawData.length} line item${_babcockRawData.length === 1 ? '' : 's'}`;
    setBabcockAiBadge(usedAI);
    document.getElementById('babcockValidateCard').style.display = '';
    document.getElementById('babcockValidateCard').scrollIntoView({ behavior: 'smooth', block: 'start' });

    const aiNote = usedAI ? ' (AI-parsed — please verify every line)' : '';
    if (parsed.missingFields && parsed.missingFields.length) {
      const labels = parsed.missingFields.map(m => m.label).join(', ');
      toast(`Loaded ${file.name}${aiNote} — please fill in: ${labels}`, 'info');
    } else {
      toast(`Loaded ${file.name} — ${_babcockRawData.length} line items extracted${aiNote}`, 'success');
    }
  } catch (err) {
    console.error('Babcock parse failed:', err);
    toast('Failed to read file: ' + (err.message || err), 'error');
  } finally {
    setLoading(false);
  }
}

function clearBabcockFile() {
  _babcockWorkbook = null;
  _babcockOriginalFile = null;
  _babcockRawData = null;
  _babcockHeader = null;
  _babcockLastGenerated = null;
  _babcockParsedByAI = false;
  setBabcockAiBadge(false);
  document.getElementById('babcockFileInput').value = '';
  document.getElementById('babcockFileInfo').style.display = 'none';
  document.getElementById('babcockValidateCard').style.display = 'none';
  // Reset markup to default
  const m = document.getElementById('babcockMarkup');
  if (m) m.value = 10;
  // Clear the email input + hint, and re-enable the Generate button so
  // the next upload starts from a clean slate.
  const emailEl = document.getElementById('bvCustomerEmail');
  if (emailEl) emailEl.value = '';
  const hintEl = document.getElementById('bvCustomerEmailHint');
  if (hintEl) {
    hintEl.textContent = 'Required — used to send the quote.';
    hintEl.style.color = 'var(--subtle)';
  }
  const btn = document.getElementById('babcockGenerateBtn');
  if (btn) { btn.disabled = false; btn.title = ''; }
}

// ── Parse the BAMA South West Babcock template's "Quote" tab ───────
// Parse the BAMA SW Babcock template's "Quote" tab.
//
// Uses LABEL-ANCHORED lookups: each header field is found by scanning for
// its label text (case-insensitive, colon-stripped) and reading the cell
// to its right. This way the spreadsheet template can move blocks around,
// add or remove rows, etc., without breaking the parser — labels are the
// contract, not coordinates. Multiple alternate spellings per field are
// supported via HEADER_FIELDS[…].labels.
//
// Sheet-name resolution is forgiving:
//   1. exact "Quote" wins
//   2. otherwise any sheet whose trimmed lowercase name == "quote" or "quotation"
//   3. otherwise any sheet whose name contains "quote" (e.g. "Quote v2", "Quotes")
// If nothing matches, throws an error listing the sheets that ARE present —
// usually that's enough to spot a renamed tab or the wrong file.
//
// Required fields (Customer ID, Work Order no., Quotation For) throw if
// missing — the validation form would otherwise silently get blank
// mandatory fields. Optional fields (Area, Address, Email, Comments)
// fall back to ''.
//
// Line items are anchored on the row containing all five column headers
// (Item, Description, Unit Price, Quantity, Amount) — table can move
// vertically as the spreadsheet evolves.
//
// Returns { header, lineItems } where any missing/blank optional field is ''.
// ── AI fallback parser for Babcock quotes ─────────────────────────
// Used when the strict label-anchored XLSX parser fails (layout/header
// drift) or when the upload is a PDF (no deterministic parser exists).
// Returns the SAME { header, lineItems, missingFields } shape as
// parseBabcockQuoteTab so the downstream preview/markup/generate flow is
// unchanged. input is { kind:'csv', text } or { kind:'pdf', file }.
async function parseBabcockWithAI(input) {
  const schemaPrompt = `You are extracting a quotation for a UK steel fabrication company (BAMA).
Return ONLY valid JSON, no markdown fences, no commentary, in exactly this shape:
{
  "header": {
    "quotationDate": "YYYY-MM-DD or empty string",
    "quoteRef": "the supplier's own quotation number if present, else empty string",
    "customerId": "",
    "workOrderNo": "",
    "validUntil": "YYYY-MM-DD or empty string",
    "preparedBy": "",
    "quoteFor": "short description of who/what the quote is for",
    "customerEmail": "",
    "area": "",
    "address": "",
    "comments": ""
  },
  "lineItems": [
    { "itemNum": 1, "description": "...", "unitPrice": 0, "quantity": 0, "amount": 0 }
  ]
}
Rules:
- Each line item must have a non-empty description and a numeric amount (the line total).
- If only a unit price and quantity are shown, set amount = unitPrice * quantity.
- unitPrice and quantity may be null if not shown; amount must still be the line total.
- Do NOT include the TOTAL / grand-total row or any "VAT exclusive" note as a line item.
- All money values are plain numbers: no currency symbols, no thousands separators.
- Use empty string "" for any header field you cannot find. Never invent values.`;

  let content;
  if (input.kind === 'pdf') {
    const dataUri = await _fileToDataUri(input.file);
    content = [
      { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: dataUri.split(',')[1] } },
      { type: 'text', text: schemaPrompt }
    ];
  } else {
    content = [
      { type: 'text', text: `${schemaPrompt}\n\nHere is the quotation as CSV (rows from the spreadsheet):\n\n${input.text}` }
    ];
  }

  const result = await callClaude({
    model: 'claude-sonnet-4-6',
    max_tokens: 4000,
    messages: [{ role: 'user', content }]
  });

  const rawText = (result.content?.find(b => b.type === 'text')?.text || '').trim();
  const s = rawText.indexOf('{'), e = rawText.lastIndexOf('}');
  if (s < 0 || e < 0) throw new Error('AI parser returned no JSON');
  let parsed;
  try { parsed = JSON.parse(rawText.slice(s, e + 1)); }
  catch (err) { throw new Error('AI parser returned malformed JSON'); }

  const h = parsed.header || {};
  const header = {
    quotationDate: excelToISODate(h.quotationDate),
    quoteRef:      String(h.quoteRef || '').trim(),
    customerId:    String(h.customerId || '').trim(),
    workOrderNo:   String(h.workOrderNo || '').trim(),
    validUntil:    excelToISODate(h.validUntil),
    preparedBy:    String(h.preparedBy || '').trim(),
    quoteFor:      String(h.quoteFor || '').trim(),
    customerEmail: String(h.customerEmail || '').trim(),
    area:          String(h.area || '').trim(),
    address:       String(h.address || '').trim(),
    comments:      String(h.comments || '').trim()
  };

  const num = v => {
    if (v === null || v === undefined || v === '') return null;
    const n = Number(v);
    return isFinite(n) ? n : null;
  };
  const lineItems = (Array.isArray(parsed.lineItems) ? parsed.lineItems : [])
    .map((l, i) => {
      const description = String(l.description || '').trim();
      const upNum  = num(l.unitPrice);
      const qtyNum = num(l.quantity);
      let amtNum   = num(l.amount);
      if (amtNum === null && upNum !== null && qtyNum !== null) amtNum = upNum * qtyNum;
      return { itemNum: l.itemNum ?? (i + 1), description, unitPrice: upNum, quantity: qtyNum, amount: amtNum };
    })
    .filter(l => l.description && l.amount !== null);

  const SOFT_REQUIRED = [
    { key: 'customerId',  label: 'Customer ID' },
    { key: 'workOrderNo', label: 'Work Order no.' },
    { key: 'quoteFor',    label: 'Quotation For' }
  ];
  const missingFields = SOFT_REQUIRED.filter(f => !header[f.key]);

  return { header, lineItems, missingFields };
}

// Resolve the "Quote" sheet from a workbook with the same forgiving logic
// the strict parser uses, falling back to the first sheet. Returns a SheetJS
// worksheet object (or null).
function babcockResolveQuoteSheet(wb) {
  const names = wb.SheetNames || [];
  if (wb.Sheets['Quote']) return wb.Sheets['Quote'];
  const norm = x => String(x || '').trim().toLowerCase();
  const name = names.find(x => norm(x) === 'quote' || norm(x) === 'quotation')
            || names.find(x => norm(x).includes('quote'))
            || names[0];
  return name ? wb.Sheets[name] : null;
}

// Workbook → CSV text of the Quote sheet, for feeding to the AI parser.
function babcockWorkbookToCsv(wb) {
  const sheet = babcockResolveQuoteSheet(wb);
  if (!sheet) throw new Error('No sheet found in workbook');
  return XLSX.utils.sheet_to_csv(sheet, { blankrows: false });
}

// Toggle the "AI-parsed — verify" badge on the validate card.
function setBabcockAiBadge(on) {
  const el = document.getElementById('babcockAiBadge');
  if (el) el.style.display = on ? '' : 'none';
}

// Effective markup for the current quote. In manual mode the markup
// checkbox can switch markup off entirely (return 0). Otherwise use the
// markup % input, defaulting to 10.
function babcockCurrentMarkup() {
  const chk = document.getElementById('babcockManualMarkupChk');
  if (_babcockEntryMode === 'manual' && chk && !chk.checked) return 0;
  const n = parseFloat(document.getElementById('babcockMarkup')?.value);
  return isFinite(n) ? n : 10;
}

function parseBabcockQuoteTab(wb) {
  const sheetNames = wb.SheetNames || [];

  let resolvedName = null;
  if (wb.Sheets['Quote']) {
    resolvedName = 'Quote';
  } else {
    const norm = s => String(s || '').trim().toLowerCase();
    const exact = sheetNames.find(n => norm(n) === 'quote' || norm(n) === 'quotation');
    if (exact) {
      resolvedName = exact;
    } else {
      const fuzzy = sheetNames.find(n => norm(n).includes('quote'));
      if (fuzzy) resolvedName = fuzzy;
    }
  }

  if (!resolvedName) {
    const list = sheetNames.length ? sheetNames.map(n => `"${n}"`).join(', ') : '(none)';
    throw new Error(`Sheet "Quote" not found. This file has: ${list}. Is this the correct Babcock template?`);
  }

  const sheet = wb.Sheets[resolvedName];
  if (!sheet) throw new Error(`Sheet "${resolvedName}" could not be read.`);

  // Pull as a 2D array — easiest for label-anchored scanning
  const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });

  const cell = (r, c) => {
    const row = rows[r];
    if (!row) return '';
    const v = row[c];
    return v === undefined || v === null ? '' : v;
  };

  // ── Label-anchored lookup ──
  // Old parser used hard-coded coordinates (cell(2,4) etc.) which broke if
  // anyone shifted the header block. Now: each field declares its label(s),
  // we scan every cell to find the match, then read the adjacent value cell.
  // Labels are matched case-insensitively and ignore trailing colons/whitespace.
  // Direction defaults to 'right' (most labels have their value in the next
  // column). 'below' supported for stacked layouts.
  const normaliseLabel = s => String(s || '').trim().replace(/[:：]\s*$/, '').toLowerCase();

  // Build an index of every non-empty text cell once, for O(1) lookups
  // during the field scan rather than re-walking the sheet per field.
  const labelIndex = new Map(); // normalised label → [{r, c}, ...]
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r] || [];
    for (let c = 0; c < row.length; c++) {
      const v = row[c];
      if (v === undefined || v === null || v === '') continue;
      // Only index text-ish cells (numbers can't be labels; dates aren't either)
      if (typeof v === 'number' || v instanceof Date) continue;
      const key = normaliseLabel(v);
      if (!key) continue;
      if (!labelIndex.has(key)) labelIndex.set(key, []);
      labelIndex.get(key).push({ r, c });
    }
  }

  // Find the value cell adjacent to a label. Tries every alternate label
  // (case-insensitive, colon-stripped) until one matches. If a label
  // occurs more than once on the sheet, we take the first. Returns the
  // cell value, or '' if no label match.
  function findValueByLabel(labels, direction = 'right') {
    const tries = Array.isArray(labels) ? labels : [labels];
    for (const lbl of tries) {
      const hits = labelIndex.get(normaliseLabel(lbl));
      if (!hits || !hits.length) continue;
      const { r, c } = hits[0];
      if (direction === 'right') return cell(r, c + 1);
      if (direction === 'below') return cell(r + 1, c);
      if (direction === 'left')  return cell(r, c - 1);
      if (direction === 'above') return cell(r - 1, c);
    }
    return '';
  }

  // Header field map. `alternates` lets the spreadsheet's wording drift
  // slightly without breaking the parse — add new variants here as needed.
  const HEADER_FIELDS = {
    quotationDate:    { labels: ['Date'] },
    quoteRef:         { labels: ['Quotation no.', 'Quotation Number', 'Quote no.', 'Quote Number'] },
    customerId:       { labels: ['Customer ID', 'Customer Id'] },
    workOrderNo:      { labels: ['Work Order no.', 'Work Order Number', 'Work Order'] },
    validUntil:       { labels: ['Quotation valid until', 'Valid until', 'Quote valid until'] },
    preparedBy:       { labels: ['Prepared by'] },
    quoteFor:         { labels: ['Quotation For', 'Quote For'] },
    customerEmail:    { labels: ['Email', 'E-mail'] },
    area:             { labels: ['Area'] },
    address:          { labels: ['Address'] },
  };

  const header = {};
  for (const [key, def] of Object.entries(HEADER_FIELDS)) {
    header[key] = findValueByLabel(def.labels, def.direction || 'right');
  }

  // Comments block — the heading "Comments or Special Instructions" sits
  // above a 3-row merged area. SheetJS unmerges into the top-left cell.
  // Read the 3 cells immediately below the heading.
  const commentsHits = labelIndex.get(normaliseLabel('Comments or Special Instructions'));
  if (commentsHits && commentsHits.length) {
    const { r: cr, c: cc } = commentsHits[0];
    header.comments = [cell(cr + 1, cc), cell(cr + 2, cc), cell(cr + 3, cc)]
      .map(s => String(s || '').trim()).filter(Boolean).join('\n');
  } else {
    header.comments = '';
  }

  // Soft-required header fields — empty values used to throw, but that
  // blocked the upload entirely when Lee just needed to fill in a missing
  // value manually on the validate form. Now we surface the list of
  // missing fields so the UI can flag them (red border + toast) and let
  // the user fill them in before pressing Generate & Save. The save-side
  // handler already has its own "Generate Anyway / Go Back & Fix" prompt
  // for fields still blank at submit time.
  const SOFT_REQUIRED = ['customerId', 'workOrderNo', 'quoteFor'];
  const missingFields = SOFT_REQUIRED
    .filter(k => !String(header[k] || '').trim())
    .map(k => ({ key: k, label: HEADER_FIELDS[k].labels[0] }));

  // Normalise dates — Excel may give a JS Date object, a number (serial), or a string.
  header.quotationDate = excelToISODate(header.quotationDate);
  header.validUntil    = excelToISODate(header.validUntil);

  // Trim string fields
  for (const k of ['quoteRef', 'customerId', 'workOrderNo', 'preparedBy',
                   'quoteFor', 'area', 'address', 'customerEmail']) {
    header[k] = String(header[k] || '').trim();
  }

  // ── Line items table ──
  // Anchored on the row containing all five column headers (Item, Description,
  // Unit Price, Quantity, Amount). This row could move up or down as the
  // spreadsheet evolves; finding it dynamically makes the parser robust.
  function findLineItemsHeaderRow() {
    const want = ['item', 'description', 'unit price', 'quantity', 'amount'];
    for (let r = 0; r < rows.length; r++) {
      const row = (rows[r] || []).map(v => normaliseLabel(v));
      // Need every wanted heading to appear somewhere in this row, in order
      let cursor = 0;
      const colMap = {};
      for (let c = 0; c < row.length; c++) {
        if (cursor >= want.length) break;
        if (row[c] === want[cursor]) {
          colMap[want[cursor]] = c;
          cursor++;
        }
      }
      if (cursor === want.length) return { r, colMap };
    }
    return null;
  }

  const liHeader = findLineItemsHeaderRow();
  if (!liHeader) {
    throw new Error(
      'Could not find the line items table on the Quote tab. ' +
      'Expected a row with headers: Item, Description, Unit Price, Quantity, Amount.'
    );
  }
  const C_ITEM   = liHeader.colMap['item'];
  const C_DESC   = liHeader.colMap['description'];
  const C_PRICE  = liHeader.colMap['unit price'];
  const C_QTY    = liHeader.colMap['quantity'];
  const C_AMT    = liHeader.colMap['amount'];

  const lineItems = [];
  for (let r = liHeader.r + 1; r < rows.length; r++) {
    const itemNum     = cell(r, C_ITEM);
    const description = String(cell(r, C_DESC) || '').trim();
    const unitPrice   = cell(r, C_PRICE);
    const quantity    = cell(r, C_QTY);
    const amount      = cell(r, C_AMT);

    // Stop when we hit the TOTAL row or the VAT-exclusive note.
    if (description === 'All quotes are VAT exclusive' || description === 'TOTAL') break;
    if (cell(r, C_QTY) === 'TOTAL' || cell(r, C_AMT) === 'TOTAL') break;

    // Skip rows where description is empty AND no numeric data — these are blank template rows.
    if (!description && unitPrice === '' && quantity === '' && amount === '') continue;
    // Skip rows with only an item number (e.g. blank line slots in the default template)
    if (!description) continue;

    const qtyNum = quantity === '' ? null : Number(quantity);
    const upNum  = unitPrice === '' ? null : Number(unitPrice);
    const amtNum = amount === '' ? null : Number(amount);

    lineItems.push({
      itemNum:     itemNum === '' ? null : itemNum,
      description,
      unitPrice:   isFinite(upNum) ? upNum : null,
      quantity:    isFinite(qtyNum) ? qtyNum : null,
      amount:      isFinite(amtNum) ? amtNum : ((isFinite(upNum) && isFinite(qtyNum)) ? upNum * qtyNum : null)
    });
  }

  return { header, lineItems, missingFields };
}

// Excel cell value → ISO date string ('YYYY-MM-DD'), or '' if not a date.
// Handles JS Date objects, Excel serial numbers, and ISO/UK-formatted strings.
function excelToISODate(v) {
  if (!v && v !== 0) return '';
  if (v instanceof Date) {
    return v.toISOString().split('T')[0];
  }
  if (typeof v === 'number' && isFinite(v)) {
    // Excel serial: days since 1899-12-30 (which corrects for the 1900 leap-year bug)
    const ms = (v - 25569) * 86400 * 1000;
    const d = new Date(ms);
    if (!isNaN(d.getTime())) return d.toISOString().split('T')[0];
  }
  const s = String(v).trim();
  // Already ISO?
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  // UK format dd/mm/yyyy
  const m = s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})$/);
  if (m) {
    let [, d, mo, y] = m;
    if (y.length === 2) y = (parseInt(y) > 50 ? '19' : '20') + y;
    return `${y}-${mo.padStart(2,'0')}-${d.padStart(2,'0')}`;
  }
  return '';
}

// Push parsed header values into the Validate card form. Pre-fills the
// "Quotation number" hint with the next available B#### so Lee can see
// what the system would auto-allocate (he can override by typing a value).
function populateBabcockValidationFields(header, missingFields = []) {
  const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val ?? ''; };

  // Clear any prior red-border highlights from a previous upload — important
  // when the user replaces a bad upload with a corrected one in the same
  // session and we don't want stale warnings sticking around.
  for (const id of ['bvCustomerId', 'bvWorkOrderNo', 'bvQuoteFor']) {
    const el = document.getElementById(id);
    if (el) {
      el.style.borderColor = '';
      el.style.boxShadow = '';
    }
  }

  // NOTE: header.quoteRef is intentionally ignored. The Bama SW template
  // carries its own internal QP###### reference in cell E3, but Babcock
  // quotes use the BAMA B#### sequence (B0092 onwards). The system always
  // allocates the next free B#### — the user can override only if they
  // really need to (e.g. backfilling a pre-existing manual quote).
  set('bvQuoteRef',    '');
  set('bvQuoteDate',   header.quotationDate || todayStr());
  set('bvValidUntil',  header.validUntil || '');
  set('bvCustomerId',  header.customerId || '');
  set('bvWorkOrderNo', header.workOrderNo || '');
  set('bvPreparedBy',  header.preparedBy || currentManagerUser || '');
  set('bvQuoteFor',    header.quoteFor || '');
  set('bvCustomerEmail', header.customerEmail || '');
  set('bvArea',        header.area || '');
  set('bvAddress',     header.address || '');
  set('bvComments',    header.comments || '');

  // Re-paint the email field's hint colour and (de)activate the
  // Generate & Save button based on whether the spreadsheet supplied
  // a plausible email value. If not, the user has to type one in.
  onBabcockEmailChange();

  // Fetch + display the next available B#### ref. We pre-fill the input
  // (rather than just the placeholder) so the user can see what they're
  // about to allocate. They can still type over it if needed.
  const refEl = document.getElementById('bvQuoteRef');
  if (refEl) {
    refEl.value = '';
    refEl.placeholder = 'Loading next ref…';
    api.get('/api/babcock-quote-next-ref').then(r => {
      if (r && r.reference) {
        _babcockNextRefCache = r.reference;
        refEl.value = r.reference;
        refEl.placeholder = `Auto: ${r.reference}`;
      } else {
        refEl.placeholder = 'Auto-allocated on save';
      }
    }).catch(() => {
      refEl.placeholder = 'Auto-allocated on save';
    });
  }

  // ── Flag fields the spreadsheet couldn't supply ──
  // The parser surfaces a `missingFields` list (Customer ID / Work Order
  // no. / Quotation For) when the template's value cells came back empty.
  // We paint those inputs with a red border so the user spots them, then
  // clear the highlight on first input so it doesn't linger after fix.
  const idMap = {
    customerId:  'bvCustomerId',
    workOrderNo: 'bvWorkOrderNo',
    quoteFor:    'bvQuoteFor',
  };
  for (const { key } of missingFields) {
    const el = document.getElementById(idMap[key]);
    if (!el) continue;
    el.style.borderColor = 'var(--red)';
    el.style.boxShadow = '0 0 0 1px var(--red)';
    const clearWarning = () => {
      el.style.borderColor = '';
      el.style.boxShadow = '';
      el.removeEventListener('input', clearWarning);
    };
    el.addEventListener('input', clearWarning);
  }
}

// Shared 2dp rounding helper for all Babcock financial calculations
// Net value of a PO row (total_value is gross; subtract vat_amount, or derive from vat_rate)
const _poNet = p => {
  if (p.total_value == null) return 0;
  const gross = Number(p.total_value);
  if (p.vat_amount != null && Number(p.vat_amount) > 0) return Math.round((gross - Number(p.vat_amount)) * 100) / 100;
  if (p.vat_rate  != null && Number(p.vat_rate)  > 0) return Math.round((gross / (1 + Number(p.vat_rate) / 100)) * 100) / 100;
  return gross;
};
// Shared GBP formatter for Babcock tracker (replaces 3 local copies)
const _fmtGBP = gbp2;   // canonical: see the MONEY section at the top

function updateBabcockMarkedUpTotal(markup) {
  if (!_babcockRawData) return;
  const factor = 1 + (markup / 100);
  let originalTotal = 0;
  let markedUpTotal = 0;
  _babcockRawData.forEach(r => {
    const lineTotal = _r2(r.amount !== null ? r.amount
                     : (r.unitPrice !== null && r.quantity !== null
                        ? _r2(r.unitPrice * r.quantity) : 0));
    originalTotal = _r2(originalTotal + lineTotal);
    markedUpTotal = _r2(markedUpTotal + _r2(lineTotal * factor));
  });
  const elOrig = document.getElementById('babcockOriginalTotal');
  const elMkup = document.getElementById('babcockMarkedUpTotal');
  if (elOrig) elOrig.textContent = _fmtGBP(originalTotal);
  if (elMkup) elMkup.textContent = _fmtGBP(markedUpTotal);
}

function renderBabcockPreviewTable(markup) {
  if (!_babcockRawData) return;
  const factor = 1 + (markup / 100);

  document.getElementById('babcockPreviewHead').innerHTML = `<tr>
    <th style="width:40px">#</th>
    <th style="min-width:240px">Description</th>
    <th style="text-align:right">Unit Price</th>
    <th style="text-align:right">Qty</th>
    <th style="text-align:right">Amount</th>
    <th style="text-align:right;color:var(--green)">+${markup}% → Our Price</th>
  </tr>`;

  document.getElementById('babcockPreviewBody').innerHTML = _babcockRawData.map((r, i) => {
    const amount   = r.amount !== null ? _r2(r.amount)
                    : (r.unitPrice !== null && r.quantity !== null
                       ? _r2(r.unitPrice * r.quantity) : null);
    const ourPrice = amount !== null ? _r2(amount * factor) : null;
    return `<tr>
      <td style="color:var(--subtle);font-family:var(--font-mono)">${r.itemNum ?? (i + 1)}</td>
      <td title="${escapeHtml(String(r.description))}">${escapeHtml(String(r.description))}</td>
      <td class="num-cell">${r.unitPrice !== null ? _fmtGBP(r.unitPrice) : '—'}</td>
      <td class="num-cell">${r.quantity !== null ? r.quantity : '—'}</td>
      <td class="num-cell">${amount !== null ? _fmtGBP(amount) : '—'}</td>
      <td class="markup-cell">${ourPrice !== null ? _fmtGBP(ourPrice) : '—'}</td>
    </tr>`;
  }).join('');
}

// ── Generate PDF + upload both files to SharePoint + save DB row ───
// Single button, single user gesture. Flow:
//   1. Validate at least one line item exists
//   2. Open render popup synchronously (popup blockers reject post-await)
//   3. Build PDF in popup via html2pdf
//   4. Upload original .xlsx to "...Bama South West Quotes/Quotes received/"
//   5. Upload generated .pdf to "...Bama South West Quotes/"
//   6. POST to /api/babcock-quotes with all metadata + file links
async function generateAndSaveBabcockQuote() {
  // Manual mode: the editable grid is the source of truth — harvest it now.
  if (_babcockEntryMode === 'manual') harvestBabcockManualRows();

  if (!_babcockRawData || !_babcockRawData.length) {
    toast(_babcockEntryMode === 'manual' ? 'Add at least one line item' : 'Upload a quote template first', 'error');
    return;
  }
  // Uploaded quotes carry a source file; manual quotes don't.
  if (_babcockEntryMode !== 'manual' && !_babcockOriginalFile) {
    toast('Original file not in memory — please re-upload', 'error');
    return;
  }

  // Gather form values up-front so we can validate before doing anything else.
  const markup = babcockCurrentMarkup();
  const factor = 1 + (markup / 100);

  const formData = {
    quoteRef:     (document.getElementById('bvQuoteRef').value || '').trim(),
    quoteDate:    document.getElementById('bvQuoteDate').value || todayStr(),
    validUntil:   document.getElementById('bvValidUntil').value || '',
    customerId:   (document.getElementById('bvCustomerId').value || '').trim(),
    workOrderNo:  (document.getElementById('bvWorkOrderNo').value || '').trim(),
    preparedBy:   (document.getElementById('bvPreparedBy').value || '').trim(),
    quoteFor:     (document.getElementById('bvQuoteFor').value || '').trim(),
    customerEmail:(document.getElementById('bvCustomerEmail').value || '').trim(),
    area:         (document.getElementById('bvArea').value || '').trim(),
    address:      (document.getElementById('bvAddress').value || '').trim(),
    comments:     (document.getElementById('bvComments').value || '').trim()
  };

  // ── Email is hard-required ──
  // Unlike the other "required" fields below (which let the user override
  // via "Generate Anyway"), email is a hard-block — we can't email the
  // quote at step 1 without it, and that's the whole point of capturing it.
  if (!isPlausibleEmail(formData.customerEmail)) {
    toast(formData.customerEmail
      ? 'Customer email doesn\u2019t look valid — please correct it'
      : 'Customer email is required', 'error');
    const el = document.getElementById('bvCustomerEmail');
    if (el) { el.focus(); el.scrollIntoView({ behavior: 'smooth', block: 'center' }); }
    return;
  }

  // ── Required-field check ───────────────────────────────────────
  // These six fields are needed for a properly formatted quote that
  // Babcock will accept. Comments / Area / Address are optional.
  // If any are missing we show a confirm modal listing them — the user
  // can either "Generate anyway" or "Go back" to fill them in.
  const requiredFields = [
    { key: 'quoteDate',    label: 'Quotation Date' },
    { key: 'validUntil',   label: 'Valid Until' },
    { key: 'customerId',   label: 'Customer ID' },
    { key: 'workOrderNo',  label: 'Work Order Number' },
    { key: 'preparedBy',   label: 'Prepared By' },
    { key: 'quoteFor',     label: 'Quotation For' }
  ];
  const missing = requiredFields.filter(f => !formData[f.key]).map(f => f.label);
  if (missing.length) {
    const list = missing.map(m => `<li style="margin:4px 0">${escapeHtml(m)}</li>`).join('');
    const proceed = await showConfirmAsync(
      '⚠️ Missing Information',
      `<p style="margin:0 0 10px">The following required field${missing.length === 1 ? ' is' : 's are'} missing:</p>
       <ul style="margin:0 0 10px;padding-left:20px;color:var(--red)">${list}</ul>
       <p style="margin:0;font-size:13px;color:var(--muted)">Do you want to generate the quote anyway?</p>`,
      { okLabel: 'Generate Anyway', cancelLabel: 'Go Back & Fix' }
    );
    if (!proceed) {
      // Focus the first missing input so the user lands on it
      const firstMissingKey = requiredFields.find(f => !formData[f.key]).key;
      const idMap = {
        quoteDate: 'bvQuoteDate', validUntil: 'bvValidUntil', customerId: 'bvCustomerId',
        workOrderNo: 'bvWorkOrderNo', preparedBy: 'bvPreparedBy', quoteFor: 'bvQuoteFor'
      };
      const el = document.getElementById(idMap[firstMissingKey]);
      if (el) { el.focus(); el.scrollIntoView({ behavior: 'smooth', block: 'center' }); }
      return;
    }
  }

  const btn = document.getElementById('babcockGenerateBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Generating…'; }

  // If user didn't override, use the cached suggestion; if that's missing, server will allocate.
  if (!formData.quoteRef && _babcockNextRefCache) formData.quoteRef = _babcockNextRefCache;

  // Build marked-up line items + grand total
  let grandTotal = 0;
  const markedLines = _babcockRawData.map((r, i) => {
    const amount   = r.amount !== null ? _r2(r.amount)
                    : (r.unitPrice !== null && r.quantity !== null
                       ? _r2(r.unitPrice * r.quantity) : 0);
    const ourPrice = _r2(amount * factor);
    grandTotal = _r2(grandTotal + ourPrice);
    return {
      itemNum:    r.itemNum ?? (i + 1),
      description: r.description,
      unitPrice:  r.unitPrice !== null ? _r2(r.unitPrice * factor) : null,
      quantity:   r.quantity,
      amount:     ourPrice
    };
  });

  // jsPDF renders directly in the page — no popup window needed.
  // (Earlier html2canvas-based renderer needed an isolated popup for
  // a clean DOM, which is what the popup logic here was for.)

  setLoading(true);

  try {
    // Pre-load the BAMA logo as a data URI for embedding in the PDF
    await loadLogoDataUri();

    // Render PDF (returns a Blob)
    const pdfBlob = await renderBabcockQuotePDF({
      ...formData,
      markup,
      grandTotal,
      lineItems: markedLines
    });

    // STEP 4 — upload both files to SharePoint
    toast('Uploading files to SharePoint…', 'info');
    const folders = await findOrCreateBabcockFolders();
    const safeRef = sanitizeSpFilename(formData.quoteRef || 'BAMA-quote');
    const dateForName = (formData.quoteDate || todayStr()).replace(/-/g, '');
    const pdfFileName = `${safeRef} - ${sanitizeSpFilename(formData.quoteFor || 'Quote')} - ${dateForName}.pdf`;

    // Manual quotes have no source file — only upload the original when present.
    let originalUploaded = null;
    if (_babcockOriginalFile) {
      const originalFileName = `${safeRef} - ${_babcockOriginalFile.name}`;
      const origExt = (_babcockOriginalFile.name.split('.').pop() || '').toLowerCase();
      const origMime = origExt === 'pdf'
        ? 'application/pdf'
        : 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
      originalUploaded = await uploadFileToFolder(
        folders.received.id,
        originalFileName,
        await _babcockOriginalFile.arrayBuffer(),
        origMime
      );
    }

    const pdfUploaded = await uploadFileToFolder(
      folders.parent.id,
      pdfFileName,
      pdfBlob,
      'application/pdf'
    );

    // STEP 5 — save DB row
    toast('Saving to tracker…', 'info');
    const payload = {
      quote_ref:          formData.quoteRef || undefined, // server allocates if empty
      date_sent:          formData.quoteDate,
      total_value:        +grandTotal.toFixed(2),
      markup_pct:         markup,
      line_items:         markedLines,
      source_filename:    _babcockOriginalFile ? _babcockOriginalFile.name : null,
      created_by:         currentManagerUser || null,
      quotation_date:     formData.quoteDate || null,
      customer_id:        formData.customerId || null,
      work_order_no:      formData.workOrderNo || null,
      valid_until:        formData.validUntil || null,
      prepared_by:        formData.preparedBy || null,
      quote_for_area:     [formData.quoteFor, formData.area].filter(Boolean).join(' — ') || null,
      quote_for_address:  formData.address || null,
      comments:           formData.comments || null,
      original_file_id:   originalUploaded ? originalUploaded.id : null,
      original_file_url:  originalUploaded ? originalUploaded.webUrl : null,
      generated_file_id:  pdfUploaded.id,
      generated_file_url: pdfUploaded.webUrl,
      // Captured from the spreadsheet (or typed by the user) — used at
      // step 1 of the lifecycle to email the quote to the client.
      customer_email:     formData.customerEmail || null,
      // Preserve the source spreadsheet's own reference (QP######)
      // for traceability — does not appear on the customer PDF.
      original_quote_ref: (_babcockHeader && _babcockHeader.quoteRef) || null
    };

    const saved = await api.post('/api/babcock-quotes', payload);

    setLoading(false);
    toast(`Quote ${saved.quote_ref} saved ✓`, 'success');

    // Reset and return to tracker
    clearBabcockFile();
    showBabcockTracker();
  } catch (err) {
    setLoading(false);
    console.error('Babcock generate/save failed:', err);
    toast('Failed: ' + (err.message || 'unknown error'), 'error');
    if (btn) { btn.disabled = false; btn.textContent = '⚙️ Generate & Save'; }
  }
}

// ── Find/create the SharePoint folder structure for Babcock quotes ─
// Original uploads → "Quotation/00 - Babcock 2026/Bama South West Quotes/Quotes received"
// Generated PDFs   → "Quotation/00 - Babcock 2026/Bama South West Quotes"
// Returns { parent, received } as Graph item objects with .id and .webUrl
async function findOrCreateBabcockFolders() {
  const token = await getToken();
  const basePath = 'Quotation/00 - Babcock 2026/Bama South West Quotes';
  const lookup = await fetch(
    `https://graph.microsoft.com/v1.0/drives/${BAMA_DRIVE_ID}/root:/${encodeURIComponent(basePath)}`,
    { headers: { 'Authorization': `Bearer ${token}` } }
  );
  if (!lookup.ok) {
    throw new Error(`Cannot find SharePoint folder "${basePath}" (status ${lookup.status})`);
  }
  const parent = await lookup.json();
  const received = await getOrCreateSubfolder(parent.id, 'Quotes received', BAMA_DRIVE_ID);
  if (!received) throw new Error('Could not find or create "Quotes received" subfolder');
  return { parent, received };
}

// ── Build the quote PDF using jsPDF (native text — selectable!) ───
// Previously used html2pdf.js (html2canvas + jsPDF) which rasterised
// the entire document to a JPEG before embedding — meaning text wasn't
// selectable, copyable, or searchable. We now draw directly with jsPDF
// vector + text primitives so the resulting PDF has selectable text,
// is much smaller, and prints crisp at any zoom level.
//
// `popupWin` is an opaque opt-in: if a popup is provided we close it
// once rendering is done (used to keep popup-blocker behaviour stable
// for the moment, but the popup is no longer required for rendering).
async function renderBabcockQuotePDF(data, popupWin) {
  // Close the unused popup — we render inline now.
  try { if (popupWin && !popupWin.closed) popupWin.close(); } catch (e) {}

  // Wait for the BAMA logo data URI to be ready (loadLogoDataUri was
  // called in the parent function before this).
  const logo = _logoDataUriCache || '';

  // Resolve jsPDF constructor. Tried in order:
  //   1. window.jspdf.jsPDF — the standalone UMD jspdf script tag we
  //      include in babcock.html (canonical global).
  //   2. window.jsPDF        — older standalone builds.
  //   3. html2pdf bundle internal — html2pdf.bundle.min.js bundles jsPDF
  //      but exposes it inconsistently across versions; this is a best-
  //      effort fallback so the page still works if the standalone tag
  //      ever drops out.
  //   4. Dynamic load of the standalone UMD as a last resort.
  function resolveJsPDF() {
    if (typeof window.jspdf !== 'undefined' && typeof window.jspdf.jsPDF === 'function') {
      return window.jspdf.jsPDF;
    }
    if (typeof window.jsPDF === 'function') {
      return window.jsPDF;
    }
    if (typeof window.html2pdf !== 'undefined') {
      try {
        // Some bundle versions hang jsPDF off the html2pdf factory function.
        if (typeof window.html2pdf.jsPDF === 'function') return window.html2pdf.jsPDF;
      } catch (e) { /* */ }
    }
    return null;
  }

  let JsPDFCtor = resolveJsPDF();
  if (!JsPDFCtor) {
    // Last-resort dynamic load of the standalone UMD build.
    await new Promise((resolve, reject) => {
      const existing = document.querySelector('script[data-jspdf-loaded]');
      if (existing) {
        // Already-injected tag may still be loading — poll briefly.
        let tries = 0;
        const tick = () => {
          if (resolveJsPDF()) return resolve();
          if (++tries > 50) return reject(new Error('jsPDF load timed out'));
          setTimeout(tick, 100);
        };
        tick();
        return;
      }
      const s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
      s.dataset.jspdfLoaded = '1';
      s.onload = resolve;
      s.onerror = () => reject(new Error('Failed to load jsPDF from CDN'));
      document.head.appendChild(s);
    });
    JsPDFCtor = resolveJsPDF();
  }

  if (!JsPDFCtor) {
    throw new Error('PDF library failed to load — check your internet connection and try again');
  }

  const blob = await drawBabcockQuotePDF(JsPDFCtor, data, logo);
  return blob;
}

// Native jsPDF rendering. Returns a Blob.
async function drawBabcockQuotePDF(jsPDF, d, logoDataUri) {
  const fmtNum = v => typeof v === 'number'
    ? v.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
    : '';
  const fmtDate = s => {
    if (!s) return '';
    const m = String(s).match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (!m) return s;
    return `${m[3]}/${m[2]}/${m[1]}`;
  };

  const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  // Set PDF metadata (shows up in viewer "Properties")
  try {
    doc.setProperties({
      title: `BAMA Quotation ${d.quoteRef || ''}`.trim(),
      subject: `Quotation${d.quoteFor ? ' for ' + d.quoteFor : ''}`,
      author: 'BAMA Fabrication',
      creator: 'BAMA Fabrication ERP'
    });
  } catch (e) { /* setProperties not critical */ }

  const pageW = 210;          // A4 width mm
  const pageH = 297;          // A4 height mm
  const marginL = 14;
  const marginR = 14;
  const marginB = 14;
  const usableW = pageW - marginL - marginR;

  // Brand colours
  const RED = [208, 2, 27];          // #D0021B
  const NAVY = [31, 53, 82];          // #1F3552
  const TEXT = [34, 34, 34];          // #222
  const MUTED = [85, 85, 85];         // #555
  const RULE = [212, 212, 212];       // #d4d4d4
  const HEADRULE = [68, 68, 68];      // #444

  // Helper: set fill / draw / text colour with a 3-tuple
  const setText  = (rgb) => doc.setTextColor(rgb[0], rgb[1], rgb[2]);
  const setFill  = (rgb) => doc.setFillColor(rgb[0], rgb[1], rgb[2]);
  const setDraw  = (rgb) => doc.setDrawColor(rgb[0], rgb[1], rgb[2]);

  // ── Top header: logo left, "Quotation" right ──────────
  let y = marginL; // we'll reuse y as cursor

  // Logo (best-effort — if data URI missing, fall back to red text)
  if (logoDataUri) {
    try {
      // Approximate sizing — keeps logo within ~75x32mm box
      doc.addImage(logoDataUri, 'PNG', marginL, y, 75, 32, undefined, 'FAST');
    } catch (e) {
      // fallback to text
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(22);
      setText(RED);
      doc.text('BAMA FABRICATION', marginL, y + 12);
    }
  } else {
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(22);
    setText(RED);
    doc.text('BAMA FABRICATION', marginL, y + 12);
  }

  // "Quotation" wordmark — light, large, right-aligned
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(34);
  setText([43, 43, 43]);
  doc.text('Quotation', pageW - marginR, y + 16, { align: 'right' });

  y = marginL + 42;  // step past header block (extra gap below logo)

  // ── Body header: left = company / quote-for, right = meta table ──
  const leftColW = usableW * 0.6;
  const rightColX = marginL + leftColW + 4;
  const rightColW = usableW - leftColW - 4;

  let leftY = y;
  let rightY = y;

  // LEFT: Company Address
  setText(TEXT);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10.5);
  doc.text('Company Address', marginL, leftY);
  leftY += 4.5;
  setText(TEXT);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(10);
  doc.text('11 Enterprise Way. Enterprise Park, Yaxley,', marginL + 4, leftY);
  leftY += 4;
  doc.text('PE7 3WY, Peterborough', marginL + 4, leftY);
  leftY += 4;
  doc.text('01733 855212', marginL + 4, leftY);
  leftY += 7;

  // LEFT: Quotation For (only if any of the three values exist)
  if (d.quoteFor || d.area || d.address) {
    setText(TEXT);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10.5);
    doc.text('Quotation For', marginL, leftY);
    leftY += 4.5;
    setText(TEXT);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    if (d.quoteFor) {
      // quoteFor may contain a combined " — " value from the DB; split back into lines
      const parts = String(d.quoteFor).split(/\s+—\s+|\n/);
      parts.forEach(part => {
        const wrapped = doc.splitTextToSize(part.trim(), leftColW - 4);
        wrapped.forEach(line => { doc.text(line, marginL + 4, leftY); leftY += 4; });
      });
      leftY += 1; // small gap between fields
    }
    if (d.area) {
      const wrapped = doc.splitTextToSize(String(d.area), leftColW - 4);
      wrapped.forEach(line => { doc.text(line, marginL + 4, leftY); leftY += 4; });
      leftY += 1;
    }
    if (d.address) {
      const wrapped = doc.splitTextToSize(String(d.address), leftColW - 4);
      wrapped.forEach(line => { doc.text(line, marginL + 4, leftY); leftY += 4; });
    }
    leftY += 3;
  }

  // RIGHT: meta table — labels right-aligned, values in black
  const metaRows = [
    { label: 'Date',                    value: fmtDate(d.quoteDate) },
    { label: 'Quotation #',             value: d.quoteRef || '' },
    { label: 'Customer ID',             value: d.customerId || '' },
    { label: 'Work Order',              value: d.workOrderNo || '', gapAfter: true },
    { label: 'Quotation valid until:',  value: fmtDate(d.validUntil) },
    { label: 'Prepared by:',            value: d.preparedBy || '' }
  ];
  doc.setFontSize(10);
  const labelColX = rightColX;
  const labelColW = rightColW * 0.55;
  const valueColX = rightColX + labelColW + 2;
  for (const row of metaRows) {
    setText(TEXT);
    doc.setFont('helvetica', 'bold');
    doc.text(row.label, labelColX + labelColW, rightY, { align: 'right' });
    setText(TEXT);
    doc.setFont('helvetica', 'normal');
    doc.text(String(row.value || ''), valueColX, rightY);
    rightY += row.gapAfter ? 7.5 : 4.5;
  }

  // Move main y past whichever side is taller
  y = Math.max(leftY, rightY) + 4;

  // ── Comments block (only if non-empty) ──────────────────
  // Fix #5: skip the section entirely when there are no special notes.
  if (d.comments && String(d.comments).trim()) {
    setText(TEXT);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10.5);
    doc.text('Comments or Special Instructions', marginL, y);
    y += 4.5;
    setText(TEXT);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    const wrapped = doc.splitTextToSize(String(d.comments).trim(), usableW - 4);
    wrapped.forEach(line => {
      // Page-break check
      if (y > pageH - marginB - 20) { doc.addPage(); y = marginL; }
      doc.text(line, marginL + 4, y);
      y += 4.2;
    });
    y += 4;
  }

  // ── Line items table ──────────────────────────────────────
  // Columns: # | Description | Unit Price | Qty | Amount
  const colItem  = { x: marginL,           w: 14, align: 'center' };
  const colAmt   = { w: 28, align: 'right' };
  const colQty   = { w: 18, align: 'center' };
  const colPrice = { w: 26, align: 'right' };
  // Description = whatever's left
  const colDesc  = { w: usableW - colItem.w - colPrice.w - colQty.w - colAmt.w, align: 'left' };
  colDesc.x  = colItem.x + colItem.w;
  colPrice.x = colDesc.x + colDesc.w;
  colQty.x   = colPrice.x + colPrice.w;
  colAmt.x   = colQty.x + colQty.w;

  // Header row
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  setText(TEXT);
  doc.text('Item',        colItem.x + colItem.w / 2,   y, { align: 'center' });
  doc.text('Description', colDesc.x + 1,                y);
  doc.text('Unit Price',  colPrice.x + colPrice.w - 1,  y, { align: 'right' });
  doc.text('Quantity',    colQty.x + colQty.w / 2,      y, { align: 'center' });
  doc.text('Amount',      colAmt.x + colAmt.w - 1,      y, { align: 'right' });
  y += 1.5;
  setDraw(HEADRULE);
  doc.setLineWidth(0.4);
  doc.line(marginL, y, pageW - marginR, y);
  y += 3;

  // Body rows
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(10);
  setDraw(RULE);
  doc.setLineWidth(0.15);
  for (let i = 0; i < d.lineItems.length; i++) {
    const l = d.lineItems[i];
    const desc = String(l.description || '');
    // Wrap description so long lines don't overflow
    const descLines = doc.splitTextToSize(desc, colDesc.w - 2);
    const rowH = Math.max(5, descLines.length * 4.2 + 1);

    // Page break if needed (leave room for footer below)
    if (y + rowH > pageH - marginB - 30) {
      doc.addPage();
      y = marginL + 6;
    }

    // # column
    setText(MUTED);
    doc.text(String(l.itemNum ?? (i + 1)), colItem.x + colItem.w / 2, y + 3.5, { align: 'center' });

    // Description column
    setText(TEXT);
    let descY = y + 3.5;
    for (const line of descLines) {
      doc.text(line, colDesc.x + 1, descY);
      descY += 4.2;
    }

    // Unit price
    if (l.unitPrice !== null && l.unitPrice !== undefined) {
      doc.text(fmtNum(l.unitPrice), colPrice.x + colPrice.w - 1, y + 3.5, { align: 'right' });
    }

    // Quantity
    if (l.quantity !== null && l.quantity !== undefined && l.quantity !== '') {
      doc.text(String(l.quantity), colQty.x + colQty.w / 2, y + 3.5, { align: 'center' });
    }

    // Amount
    doc.text(fmtNum(l.amount), colAmt.x + colAmt.w - 1, y + 3.5, { align: 'right' });

    // Row separator
    setDraw(RULE);
    doc.setLineWidth(0.15);
    doc.line(marginL, y + rowH, pageW - marginR, y + rowH);
    y += rowH;
  }

  y += 6;

  // Page-break for footer if needed
  if (y > pageH - marginB - 28) {
    doc.addPage();
    y = marginL + 6;
  }

  // ── Footer: VAT note left, TOTAL pill right ────────────────
  setText(TEXT);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10.5);
  doc.text('All quotes are VAT exclusive', marginL, y + 5);

  // TOTAL label + navy pill
  doc.setFontSize(12);
  doc.text('TOTAL', pageW - marginR - 38, y + 5, { align: 'right' });

  const pillX = pageW - marginR - 35;
  const pillY = y;
  const pillW = 35;
  const pillH = 9;
  setFill(NAVY);
  doc.rect(pillX, pillY, pillW, pillH, 'F');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(13);
  setText([255, 255, 255]);
  doc.text(fmtNum(d.grandTotal), pillX + pillW - 3, pillY + 6.2, { align: 'right' });

  y += pillH + 6;

  // Bottom contact line
  setText([68, 68, 68]);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9.5);
  if (y > pageH - marginB - 12) { doc.addPage(); y = marginL + 6; }
  doc.text('If you have any further questions, please contact: info@bamafabrication.co.uk', marginL, y);
  y += 4;
  doc.text('Thank you for your business', marginL, y);

  // Output as Blob
  const blob = doc.output('blob');
  return blob;
}


// ── Tracker view switching ──
function showBabcockTracker() {
  document.getElementById('babcockTrackerView').style.display = '';
  document.getElementById('babcockGeneratorView').style.display = 'none';
  const btn = document.getElementById('babcockNewQuoteBtn');
  if (btn) btn.style.display = '';
  loadBabcockTracker();
}

function showBabcockGenerator() {
  document.getElementById('babcockTrackerView').style.display = 'none';
  document.getElementById('babcockGeneratorView').style.display = '';
  const btn = document.getElementById('babcockNewQuoteBtn');
  if (btn) btn.style.display = 'none';
  // Start from a clean slate every time the generator is opened
  setBabcockEntryMode('upload');
  _babcockLastGenerated = null;
}

// ── Manual quote entry ───────────────────────────────────────────
// Lets the user type a quote from scratch (no upload). Produces the same
// _babcockRawData / header-form state the upload path produces, then funnels
// into the identical generate/save flow. A per-quote markup toggle decides
// whether the typed line amounts are Babcock prices (apply markup) or the
// final customer prices (markup off).
function setBabcockEntryMode(mode) {
  _babcockEntryMode = (mode === 'manual') ? 'manual' : 'upload';
  clearBabcockFile();

  const uploadCard   = document.getElementById('babcockUploadCard');
  const previewWrap  = document.getElementById('babcockPreviewWrap');
  const manualWrap   = document.getElementById('babcockManualWrap');
  const validateCard = document.getElementById('babcockValidateCard');
  const markupRow    = document.getElementById('babcockMarkupToggleRow');
  const btnUpload    = document.getElementById('babcockModeUpload');
  const btnManual    = document.getElementById('babcockModeManual');

  if (btnUpload) btnUpload.classList.toggle('active', _babcockEntryMode === 'upload');
  if (btnManual) btnManual.classList.toggle('active', _babcockEntryMode === 'manual');

  if (_babcockEntryMode === 'manual') {
    if (uploadCard)   uploadCard.style.display = 'none';
    if (previewWrap)  previewWrap.style.display = 'none';
    if (manualWrap)   manualWrap.style.display = '';
    if (markupRow)    markupRow.style.display = '';
    // Seed an empty grid
    const body = document.getElementById('babcockManualBody');
    if (body) {
      body.innerHTML = '';
      body.insertAdjacentHTML('beforeend', _buildBabcockManualRow());
      body.insertAdjacentHTML('beforeend', _buildBabcockManualRow());
      body.insertAdjacentHTML('beforeend', _buildBabcockManualRow());
    }
    // Markup checkbox defaults to ON; enable/disable the % input accordingly
    const chk = document.getElementById('babcockManualMarkupChk');
    if (chk) chk.checked = true;
    const mk = document.getElementById('babcockMarkup');
    if (mk) mk.disabled = false;
    // Clean header form: blank fields, today's date, next B#### ref, email-gated button
    populateBabcockValidationFields({}, []);
    if (validateCard) validateCard.style.display = '';
    harvestBabcockManualRows();
    if (validateCard) validateCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
  } else {
    if (uploadCard)   uploadCard.style.display = '';
    if (previewWrap)  previewWrap.style.display = '';
    if (manualWrap)   manualWrap.style.display = 'none';
    if (markupRow)    markupRow.style.display = 'none';
    if (validateCard) validateCard.style.display = 'none';
  }
}

function _buildBabcockManualRow(desc = '', unit = null, qty = null, amount = null) {
  const inp = 'background:var(--surface-2);border:1px solid var(--border);border-radius:5px;padding:6px 8px;color:var(--text);font-size:13px';
  return `<tr>
    <td style="padding:4px"><input class="bm-desc" type="text" value="${escapeHtml(String(desc))}" placeholder="Description"
         style="${inp};width:100%" oninput="harvestBabcockManualRows()"></td>
    <td style="padding:4px"><input class="bm-unit" type="number" step="0.01" value="${unit ?? ''}" placeholder="0.00"
         style="${inp};width:100px;text-align:right" oninput="bmRowAmount(this)"></td>
    <td style="padding:4px"><input class="bm-qty" type="number" step="any" value="${qty ?? ''}" placeholder="0"
         style="${inp};width:80px;text-align:right" oninput="bmRowAmount(this)"></td>
    <td style="padding:4px"><input class="bm-amount" type="number" step="0.01" value="${amount ?? ''}" placeholder="0.00"
         style="${inp};width:110px;text-align:right" oninput="harvestBabcockManualRows()"></td>
    <td style="padding:4px;text-align:center"><button class="btn btn-ghost" style="padding:4px 9px;font-size:12px"
         onclick="removeBabcockManualRow(this)">✕</button></td>
  </tr>`;
}

function addBabcockManualRow() {
  const body = document.getElementById('babcockManualBody');
  if (!body) return;
  body.insertAdjacentHTML('beforeend', _buildBabcockManualRow());
  body.querySelectorAll('tr')[body.querySelectorAll('tr').length - 1]?.querySelector('.bm-desc')?.focus();
  harvestBabcockManualRows();
}

function removeBabcockManualRow(btn) {
  const row = btn.closest('tr');
  if (row) row.remove();
  const body = document.getElementById('babcockManualBody');
  if (body && !body.querySelector('tr')) body.insertAdjacentHTML('beforeend', _buildBabcockManualRow());
  harvestBabcockManualRows();
}

// Auto-fill the line amount from unit price × quantity when both are present.
function bmRowAmount(input) {
  const row = input.closest('tr');
  if (!row) return;
  const unit = parseFloat(row.querySelector('.bm-unit')?.value);
  const qty  = parseFloat(row.querySelector('.bm-qty')?.value);
  const amtEl = row.querySelector('.bm-amount');
  if (amtEl && isFinite(unit) && isFinite(qty)) amtEl.value = _r2(unit * qty).toFixed(2);
  harvestBabcockManualRows();
}

// Read the manual grid into _babcockRawData and refresh the totals.
function harvestBabcockManualRows() {
  const rows = document.querySelectorAll('#babcockManualBody tr');
  const data = [];
  rows.forEach((row, i) => {
    const desc  = row.querySelector('.bm-desc')?.value?.trim() || '';
    const unitV = row.querySelector('.bm-unit')?.value;
    const qtyV  = row.querySelector('.bm-qty')?.value;
    const amtV  = row.querySelector('.bm-amount')?.value;
    const unit = unitV !== '' && unitV != null ? Number(unitV) : null;
    const qty  = qtyV  !== '' && qtyV  != null ? Number(qtyV)  : null;
    let amt    = amtV  !== '' && amtV  != null ? Number(amtV)  : null;
    if (amt === null && unit !== null && qty !== null) amt = _r2(unit * qty);
    if (!desc && amt === null) return; // skip blank rows
    data.push({
      itemNum: i + 1,
      description: desc,
      unitPrice: (unit !== null && isFinite(unit)) ? unit : null,
      quantity:  (qty  !== null && isFinite(qty))  ? qty  : null,
      amount:    (amt  !== null && isFinite(amt))  ? amt  : null
    });
  });
  _babcockRawData = data;
  updateBabcockMarkedUpTotal(babcockCurrentMarkup());
  const rc = document.getElementById('babcockRowCount');
  if (rc) rc.textContent = `${data.length} line item${data.length === 1 ? '' : 's'}`;
}

// Markup on/off toggle for manual quotes. When off, the % input is
// disabled and the effective markup is 0 (typed amounts are final prices).
function toggleBabcockManualMarkup() {
  const chk = document.getElementById('babcockManualMarkupChk');
  const mk  = document.getElementById('babcockMarkup');
  if (mk) mk.disabled = chk ? !chk.checked : false;
  harvestBabcockManualRows();
}

// ── Load tracker list from API ──
async function loadBabcockTracker() {
  renderUnifiedSidebar();
  const tbody = document.getElementById('babcockTrackerBody');
  if (!tbody) return;
  try {
    const list = await api.get('/api/babcock-quotes');
    _babcockQuotes = Array.isArray(list) ? list : [];
    renderBabcockTracker();
  } catch (err) {
    console.warn('Babcock tracker load failed:', err);
    tbody.innerHTML = `<tr><td colspan="10" style="padding:30px;text-align:center;color:var(--red)">
      Failed to load quotes. ${escapeHtml(err.message || '')}
    </td></tr>`;
  }
}

// ── Render tracker table (filters + search) ──
function renderBabcockTracker() {
  const tbody = document.getElementById('babcockTrackerBody');
  const countEl = document.getElementById('babcockTrackerCount');
  if (!tbody) return;

  const search = (document.getElementById('babcockTrackerSearch')?.value || '').toLowerCase();
  const statusFilter = document.getElementById('babcockTrackerStatusFilter')?.value || '';
  const showClosed = document.getElementById('babcockShowClosed')?.checked || false;

  const list = _babcockQuotes.filter(q => {
    if (!showClosed && q.status === 'Closed') return false;
    if (statusFilter && q.status !== statusFilter) return false;
    if (search && !`${q.quote_ref || ''} ${q.work_order_no || ''} ${q.po_number || ''} ${q.bama_sw_po_number || ''}`.toLowerCase().includes(search)) return false;
    return true;
  });

  // Apply column sort
  if (_babcockSort.col) {
    const { col, dir } = _babcockSort;
    const statusOrder = ['Quote Received','Quote Sent','Live Project','Project Complete',
                         'Bama SW PO Raised','Bama SW Invoice Received','Approved to Pay',
                         'Payment Received','Paid to Bama SW','Remittance Sent','Closed','Cancelled'];
    list.sort((a, b) => {
      let va, vb;
      if (col === 'status') {
        va = statusOrder.indexOf(a.status || 'Quote Received');
        vb = statusOrder.indexOf(b.status || 'Quote Received');
        if (va === -1) va = 99; if (vb === -1) vb = 99;
      } else if (col === 'total_value' || col === 'bama_sw_received_invoice_amount') {
        va = Number(a[col]) || 0;
        vb = Number(b[col]) || 0;
      } else if (col === 'date_sent') {
        va = a.date_sent || a.created_at || '';
        vb = b.date_sent || b.created_at || '';
      } else if (col === 'updated_at') {
        va = a.updated_at || '';
        vb = b.updated_at || '';
      } else {
        va = String(a[col] || '').toLowerCase();
        vb = String(b[col] || '').toLowerCase();
      }
      if (va < vb) return dir === 'asc' ? -1 : 1;
      if (va > vb) return dir === 'asc' ? 1 : -1;
      return 0;
    });
  }

  if (countEl) countEl.textContent = `${list.length} quote${list.length === 1 ? '' : 's'}`;

  if (!list.length) {
    tbody.innerHTML = `<tr><td colspan="10" style="padding:40px;text-align:center;color:var(--muted)">
      <div style="font-size:32px;margin-bottom:8px">📋</div>
      No quotes yet. Click <b>+ New Quote</b> to create one.
    </td></tr>`;
    _updateBabcockSortIndicators();
    return;
  }

  const fmtDate = v => {
    if (!v) return '—';
    const s = String(v).split('T')[0];
    return fmtDateStr(s);
  };

  tbody.innerHTML = list.map(q => {
    const next = babcockNextStatus(q.status);
    const advanceLabel = babcockAdvanceLabel(q.status);
    const statusBadge = `<span class="status-badge status-${babcockStatusClass(q.status)}">${escapeHtml(q.status || 'Quote Received')}</span>`;

    // For Approved-to-Pay rows, show the COUPA invoice due date below
    // the badge so the user can see at a glance which invoices are
    // approaching their due date without opening the row.
    let dueDateInline = '';
    if (q.status === 'Approved to Pay' && q.coupa_invoice_due_date) {
      const due = String(q.coupa_invoice_due_date).split('T')[0];
      const dueObj = new Date(due + 'T00:00:00');
      const today = new Date(); today.setHours(0,0,0,0);
      const daysToDue = Math.round((dueObj - today) / 86400000);
      let dueColour = 'var(--subtle)';
      let dueLabel  = `Due ${fmtDateStr(due)}`;
      if (daysToDue < 0)        { dueColour = 'var(--red)';   dueLabel = `⚠ Overdue (was ${fmtDateStr(due)})`; }
      else if (daysToDue <= 7)  { dueColour = '#ffc945';      dueLabel = `Due in ${daysToDue}d (${fmtDateStr(due)})`; }
      dueDateInline = `<div style="font-size:10px;color:${dueColour};margin-top:4px;font-weight:600">${dueLabel}</div>`;
    }

    const nextBtn = next
      ? `<button class="btn btn-primary" style="padding:5px 12px;font-size:11px;font-weight:600;letter-spacing:.3px"
              onclick="event.stopPropagation();advanceBabcockQuoteStatus(${q.id})">${escapeHtml(advanceLabel || '→ ' + next)}</button>`
      : `<span style="font-size:11px;color:var(--green);font-weight:600">✓ Complete</span>`;
    const revTag = (q.revision && q.revision > 0)
      ? ` <span style="font-size:10px;font-family:var(--font-mono);color:var(--accent);background:rgba(255,107,0,.1);padding:1px 5px;border-radius:3px;font-weight:600;vertical-align:middle">rev${q.revision}</span>`
      : '';

    return `
    <tr class="clickable-row" onclick="viewBabcockQuoteDetail(${q.id})" title="Last updated: ${fmtDate(q.updated_at)}">
      <td class="ref-cell">${escapeHtml(q.quote_ref || '')}${revTag}</td>
      <td style="font-family:var(--font-mono);font-size:12px;color:var(--accent2)">${escapeHtml(q.bama_sw_po_number || '—')}</td>
      <td style="font-family:var(--font-mono);font-size:12px;color:var(--accent2)">${escapeHtml(q.po_number || '—')}</td>
      <td style="font-family:var(--font-mono);font-size:12px;color:var(--muted)">${escapeHtml(q.work_order_no || '—')}</td>
      <td>${fmtDate(q.date_sent || q.created_at)}</td>
      <td class="num-cell">${_fmtGBP(q.total_value)}</td>
      <td class="num-cell">${_fmtGBP(q.bama_sw_received_invoice_amount)}</td>
      <td>${statusBadge}${dueDateInline}</td>
      <td>${nextBtn}</td>
      <td style="text-align:right;white-space:nowrap">
        <button class="row-action" title="Edit" onclick="event.stopPropagation();editBabcockQuote(${q.id})">✏️</button>
        <button class="row-action" title="Edit Line Items" onclick="event.stopPropagation();editBabcockLineItems(${q.id})">📋</button>
        <button class="row-action" title="Delete" onclick="event.stopPropagation();deleteBabcockQuote(${q.id}, '${escapeHtml(q.quote_ref || '')}')">🗑</button>
      </td>
    </tr>`;
  }).join('');
  _updateBabcockSortIndicators();
}

// ── Babcock tracker column sorting ──────────────────────────────────
function sortBabcockTracker(col) {
  if (_babcockSort.col === col) {
    _babcockSort.dir = _babcockSort.dir === 'asc' ? 'desc' : 'asc';
  } else {
    _babcockSort.col = col;
    _babcockSort.dir = 'asc';
  }
  renderBabcockTracker();
}

function _updateBabcockSortIndicators() {
  const sortableCols = ['quote_ref','bama_sw_po_number','po_number','work_order_no','date_sent','total_value','bama_sw_received_invoice_amount','status','updated_at'];
  for (const col of sortableCols) {
    const el = document.getElementById(`bsi_${col}`);
    if (!el) continue;
    if (_babcockSort.col !== col) {
      el.textContent = ' ⇅';
      el.style.color = 'var(--subtle)';
    } else {
      el.textContent = _babcockSort.dir === 'asc' ? ' ↑' : ' ↓';
      el.style.color = 'var(--accent)';
    }
  }
}

// ── Babcock line items edit modal ────────────────────────────────────
let _bliComputedTotal = 0;

async function editBabcockLineItems(id) {
  const summary = _babcockQuotes.find(q => q.id === id);
  if (!summary) { toast('Quote not found', 'error'); return; }

  const modal = document.getElementById('babcockLineItemsModal');
  if (!modal) { toast('Line items editor not available', 'error'); return; }

  document.getElementById('bliQuoteId').value = id;
  document.getElementById('bliRefHeader').textContent = summary.quote_ref || `#${id}`;
  document.getElementById('bliTableBody').innerHTML =
    '<tr><td colspan="6" style="padding:20px;text-align:center;color:var(--muted)"><div class="spinner" style="margin:0 auto 8px"></div>Loading…</td></tr>';
  modal.classList.add('active');

  let full = summary;
  try { full = await api.get(`/api/babcock-quotes/${id}`); }
  catch (err) { console.warn('Line items fetch failed:', err); }

  _babcockLineItemsRecord = full;

  const lineItems = Array.isArray(full.line_items) ? full.line_items
    : (typeof full.line_items === 'string' && full.line_items
        ? (() => { try { return JSON.parse(full.line_items); } catch { return []; } })()
        : []);

  _renderBabcockLineItemsTable(lineItems);
}

function _renderBabcockLineItemsTable(lineItems) {
  const tbody = document.getElementById('bliTableBody');
  if (!tbody) return;
  if (!lineItems.length) {
    tbody.innerHTML = `<tr><td colspan="6" style="padding:16px;text-align:center;color:var(--muted);font-style:italic">
      No line items yet. Click <b>+ Add Row</b> to add one.
    </td></tr>`;
    bliUpdateTotal();
    return;
  }
  tbody.innerHTML = lineItems.map((l, i) => _buildBliRowHtml(
    l.description || '',
    l.unitPrice !== null && l.unitPrice !== undefined ? l.unitPrice : null,
    l.quantity   !== null && l.quantity   !== undefined ? l.quantity   : null,
    l.amount     !== null && l.amount     !== undefined ? l.amount     : null
  )).join('');
  _updateBliRowNums();
  bliUpdateTotal();
}

function _buildBliRowHtml(description, unitPrice, qty, amount) {
  const upVal  = unitPrice !== null && unitPrice !== undefined ? unitPrice : '';
  const qtyVal = qty       !== null && qty       !== undefined ? qty       : '';
  const amtVal = amount    !== null && amount    !== undefined ? amount    : '';
  return `<tr>
    <td style="width:28px;text-align:center;color:var(--subtle);font-size:12px;padding:4px 2px" class="bli-row-num">?</td>
    <td style="padding:3px 4px"><input type="text" class="field-input bli-desc"
        value="${escapeHtml(String(description))}"
        style="font-size:12px;padding:5px 8px;width:100%;min-width:160px"
        placeholder="Description"></td>
    <td style="padding:3px 4px"><input type="number" step="0.01" min="0" class="field-input bli-unit"
        value="${escapeHtml(String(upVal))}"
        style="font-size:12px;padding:5px 8px;width:90px;text-align:right"
        placeholder="0.00"
        oninput="bliAutoCalc(this)"></td>
    <td style="padding:3px 4px"><input type="number" step="0.01" min="0" class="field-input bli-qty"
        value="${escapeHtml(String(qtyVal))}"
        style="font-size:12px;padding:5px 8px;width:70px;text-align:right"
        placeholder="1"
        oninput="bliAutoCalc(this)"></td>
    <td style="padding:3px 4px"><input type="number" step="0.01" min="0" class="field-input bli-amount"
        value="${escapeHtml(String(amtVal))}"
        style="font-size:12px;padding:5px 8px;width:90px;text-align:right;color:var(--green)"
        placeholder="0.00"
        oninput="bliUpdateTotal()"></td>
    <td style="width:36px;padding:3px 2px;text-align:center">
      <button class="row-action" title="Remove row" onclick="removeBabcockLineItemRow(this)"
              style="padding:4px 7px;font-size:13px">🗑</button>
    </td>
  </tr>`;
}

function bliAutoCalc(input) {
  const row = input.closest('tr');
  if (!row) return;
  const unit = parseFloat(row.querySelector('.bli-unit')?.value);
  const qty  = parseFloat(row.querySelector('.bli-qty')?.value);
  const amtInput = row.querySelector('.bli-amount');
  if (amtInput && isFinite(unit) && isFinite(qty)) {
    amtInput.value = _r2(unit * qty).toFixed(2);
  }
  bliUpdateTotal();
}

function bliUpdateTotal() {
  let total = 0;
  document.querySelectorAll('#bliTableBody .bli-amount').forEach(inp => {
    total = _r2(total + (_r2(parseFloat(inp.value) || 0)));
  });
  _bliComputedTotal = total;
  const el = document.getElementById('bliGrandTotal');
  if (el) el.textContent = `£${total.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function addBabcockLineItemRow() {
  const tbody = document.getElementById('bliTableBody');
  if (!tbody) return;
  // Remove the "no items" placeholder if present
  if (tbody.querySelector('td[colspan]')) tbody.innerHTML = '';
  tbody.insertAdjacentHTML('beforeend', _buildBliRowHtml('', null, null, null));
  _updateBliRowNums();
  bliUpdateTotal();
  // Focus the new description input
  const rows = tbody.querySelectorAll('tr');
  rows[rows.length - 1]?.querySelector('.bli-desc')?.focus();
}

function removeBabcockLineItemRow(btn) {
  const row = btn.closest('tr');
  if (!row) return;
  const tbody = document.getElementById('bliTableBody');
  row.remove();
  if (tbody && !tbody.querySelectorAll('tr').length) {
    tbody.innerHTML = `<tr><td colspan="6" style="padding:16px;text-align:center;color:var(--muted);font-style:italic">
      No line items. Click <b>+ Add Row</b> to add one.
    </td></tr>`;
  }
  _updateBliRowNums();
  bliUpdateTotal();
}

function _updateBliRowNums() {
  document.querySelectorAll('#bliTableBody tr').forEach((row, i) => {
    const numEl = row.querySelector('.bli-row-num');
    if (numEl) numEl.textContent = i + 1;
  });
}

function closeBabcockLineItemsModal() {
  const modal = document.getElementById('babcockLineItemsModal');
  if (modal) modal.classList.remove('active');
  _babcockLineItemsRecord = null;
  _bliComputedTotal = 0;
}

async function submitBabcockLineItemsEdit() {
  const orig = _babcockLineItemsRecord;
  if (!orig) return;
  const id = parseInt(document.getElementById('bliQuoteId')?.value, 10);
  if (!id) return;

  // Collect rows
  const newLineItems = [];
  let validationError = false;
  document.querySelectorAll('#bliTableBody tr').forEach((row, i) => {
    if (row.querySelector('td[colspan]')) return; // placeholder row
    const desc   = row.querySelector('.bli-desc')?.value?.trim() || '';
    const unit   = row.querySelector('.bli-unit')?.value;
    const qty    = row.querySelector('.bli-qty')?.value;
    const amount = row.querySelector('.bli-amount')?.value;
    if (!desc && !amount) return; // skip blank rows silently
    newLineItems.push({
      itemNum:   i + 1,
      description: desc,
      unitPrice:  unit   !== '' && unit   !== null ? Number(unit)   : null,
      quantity:   qty    !== '' && qty    !== null ? Number(qty)    : null,
      amount:     amount !== '' && amount !== null ? Number(amount) : null
    });
  });

  if (validationError) return;

  const newTotal = newLineItems.reduce((s, l) => _r2(s + _r2(Number(l.amount) || 0)), 0);
  const origTotal = Number(orig.total_value) || 0;
  const totalChanged = Math.abs(newTotal - origTotal) > 0.001;

  const totalNote = totalChanged
    ? `<p style="margin:8px 0 0;font-size:12px;background:rgba(255,107,0,.08);border:1px solid rgba(255,107,0,.3);border-radius:5px;padding:8px 10px">
        <b style="color:var(--accent)">Total value will update</b><br>
        <span style="color:var(--muted)">
          Current: <b>£${origTotal.toLocaleString('en-GB',{minimumFractionDigits:2})}</b> →
          New: <b style="color:var(--green)">£${newTotal.toLocaleString('en-GB',{minimumFractionDigits:2})}</b>
        </span>
      </p>`
    : '';

  const proceed = await showConfirmAsync(
    '📋 Save Line Items & Regenerate PDF?',
    `<p style="margin:0 0 6px">Updating line items will regenerate the customer-facing PDF.</p>
     <p style="margin:0;font-size:13px;color:var(--muted)">A new revision will be uploaded to SharePoint.
     The original files stay in place.</p>${totalNote}`,
    { okLabel: 'Save & Regenerate', cancelLabel: 'Cancel' }
  );
  if (!proceed) return;

  const saveBtn = document.querySelector('#babcockLineItemsModal .btn-primary');
  if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = 'Regenerating…'; }

  try {
    setLoading(true);
    await loadLogoDataUri();

    const nextRev = (parseInt(orig.revision, 10) || 0) + 1;
    const grandTotal = newTotal || newLineItems.reduce((s, l) => _r2(s + _r2(Number(l.amount) || 0)), 0);

    const pdfBlob = await renderBabcockQuotePDF({
      quoteRef:    orig.quote_ref,
      quoteDate:   orig.date_sent,
      validUntil:  orig.valid_until,
      customerId:  orig.customer_id,
      workOrderNo: orig.work_order_no,
      preparedBy:  orig.prepared_by,
      quoteFor:    orig.quote_for_area,
      area:        '',
      address:     orig.quote_for_address,
      comments:    orig.comments,
      markup:      orig.markup_pct ?? 10,
      grandTotal,
      lineItems:   newLineItems
    });

    toast('Uploading revised PDF…', 'info');
    const folders = await findOrCreateBabcockFolders();
    const safeRef      = sanitizeSpFilename(orig.quote_ref || 'BAMA-quote');
    const dateForName  = ((orig.date_sent || '').split('T')[0] || todayStr()).replace(/-/g, '');
    const safeCustomer = sanitizeSpFilename(orig.quote_for_area || 'Quote');
    const pdfFileName  = `${safeRef} - ${safeCustomer} - ${dateForName} - rev${nextRev}.pdf`;

    const pdfUploaded = await uploadFileToFolder(
      folders.parent.id, pdfFileName, pdfBlob, 'application/pdf'
    );

    const payload = {
      line_items:          newLineItems,
      total_value:         totalChanged ? newTotal : orig.total_value,
      generated_file_id:   pdfUploaded.id,
      generated_file_url:  pdfUploaded.webUrl,
      revision:            nextRev
    };

    const updated = await api.put(`/api/babcock-quotes/${id}`, payload);
    const idx = _babcockQuotes.findIndex(q => q.id === id);
    if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };

    setLoading(false);
    renderBabcockTracker();
    closeBabcockLineItemsModal();
    toast(`${orig.quote_ref} line items saved — rev${nextRev} ✓`, 'success');
  } catch (err) {
    setLoading(false);
    console.error('Line items save failed:', err);
    toast('Save failed: ' + (err.message || 'unknown error'), 'error');
    if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = 'Save & Regenerate PDF'; }
  }
}


// Map a status to the next status in the workflow.
// Returns null if there is no next action (terminal states).
//
// Note: this powers the inline "→ Next" advance button on the tracker.
// Some transitions need extra side-effects (e.g. opening a modal,
// uploading a file, generating a PDF) — those are handled by
// advanceBabcockQuoteStatus(), not just by this map. For statuses
// that require a non-trivial transition flow we still return the next
// status here; the advance handler is responsible for short-circuiting
// to the right modal rather than just doing a status PUT.
function babcockNextStatus(current) {
  const flow = {
    'Quote Received':            'Quote Sent',           // generate PDF + email modal
    'Quote Sent':                'Live Project',          // convert-to-project modal
    'Live Project':              'Project Complete',      // mark complete
    'Project Complete':          'Bama SW PO Raised',     // generate PO to Bama SW
    'Bama SW PO Raised':         'Bama SW Invoice Received',  // upload their invoice
    'Bama SW Invoice Received':  'Approved to Pay',       // upload COUPA-approved invoice + OCR
    'Approved to Pay':           'Payment Received',      // user confirms payment landed
    'Payment Received':          'Paid to Bama SW',       // mark Bama SW as paid + capture date
    'Paid to Bama SW':           'Remittance Sent',       // create + email remittance
    'Remittance Sent':           'Closed',                // mark as closed
    'Closed':                    null,                    // terminal
    'Cancelled':                 null
  };
  return flow[current || 'Quote Received'];
}

// CSS class suffix for the status badge colour.
// Each status gets a distinct colour so the eye can scan the tracker
// quickly. The colours roughly follow the workflow's mood:
//   amber/yellow for in-progress states (early lifecycle),
//   blue for active project work,
//   purple/violet for invoicing,
//   green when money's in,
//   teal for outbound Bama SW,
//   grey for cancelled.
function babcockStatusClass(status) {
  return ({
    'Quote Received':            'received',
    'Quote Sent':                'sent',
    'Live Project':              'live',
    'Project Complete':          'pcomplete',
    'Approved to Pay':           'approved',
    'Payment Received':          'paid',
    'Bama SW PO Raised':         'bsw-po-raised',
    'Bama SW Invoice Received':  'bsw-inv-rcvd',
    'Paid to Bama SW':           'bsw-paid',
    'Remittance Sent':           'bsw-remittance',
    'Closed':                    'closed',
    'Cancelled':                 'cancelled'
  })[status || 'Quote Received'] || 'received';
}

// Friendly label for the inline "advance" button. Most are just "→ Next",
// but a few have action-oriented verbs that read better than the bare
// status name. e.g. moving from "Quote Sent" to "Live Project" is more
// naturally labelled "Convert to Project" than "→ Live Project".
function babcockAdvanceLabel(currentStatus) {
  return ({
    'Quote Received':   'Generate Quote',
    'Quote Sent':       'Convert to Project',
    'Live Project':     'Complete Project',
    'Project Complete':          'Raise PO to Bama SW',
    'Bama SW PO Raised':         'Upload Bama SW Invoice',
    'Bama SW Invoice Received':  'Approved to Pay',
    'Approved to Pay':           'Payment Received',
    'Payment Received':          'Mark Bama SW as Paid',
    'Paid to Bama SW':           'Create Remittance Advice',
    'Remittance Sent':           'Mark as Closed'
  })[currentStatus] || null;
}

// Advance a quote to the next status in the workflow (one-click button).
async function advanceBabcockQuoteStatus(id) {
  const q = _babcockQuotes.find(x => x.id === id);
  if (!q) return;
  const next = babcockNextStatus(q.status);
  if (!next) return;

  // Each transition in the lifecycle that needs a side-effect (PDF
  // generation + email, project conversion, file upload + OCR, etc.)
  // has its own handler. Transitions without a registered handler fall
  // through to the plain status PUT — the row still moves correctly,
  // just without the bells and whistles.
  const handler = _babcockAdvanceHandlers[q.status];
  if (handler) {
    return handler(q, next);
  }

  try {
    const updated = await api.put(`/api/babcock-quotes/${id}`, { status: next });
    const idx = _babcockQuotes.findIndex(x => x.id === id);
    if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };
    toast(`${updated.quote_ref} \u2192 ${next}`, 'success');
    renderBabcockTracker();
  } catch (err) {
    toast('Status update failed: ' + (err.message || 'unknown error'), 'error');
    loadBabcockTracker();
  }
}

// Registry of side-effect handlers keyed on the CURRENT status.
// Each handler receives (currentRow, nextStatus) and is responsible for:
//   - Doing whatever work the transition needs (modals, file uploads, etc.)
//   - PUTing the new status to the API on success
//   - Patching _babcockQuotes locally and calling renderBabcockTracker()
//   - Not calling the API at all on Cancel — the row should stay put
//
// NOTE: Handler function NAMES retain their historical "FromXxx" labels for
// stability, but the workflow order was re-ordered so the wiring no longer
// matches the names 1:1. The mapping below is what's authoritative.
// New order: Project Complete → Bama SW PO → Bama SW Invoice → Approved
// to Pay → Payment Received → Paid to Bama SW → Remittance → Closed.
// ── Babcock payment-cascade toast ───────────────────────────────────────
// Payment endpoints (sales invoice payments, supplier payment runs, supplier
// invoice mark-paid) return a `babcock` result when the invoice is linked to
// a Babcock job — see api/src/babcock-cascade.js. Surface it to Natasza:
//   advanced → success toast (+ patch local tracker cache if loaded)
//   skipped  → warning toast — tracker was NOT at the expected step, needs
//              a manual look on the Babcock tracker
//   noop/null → silent
function babcockCascadeToast(result) {
  const list = Array.isArray(result) ? result : (result ? [result] : []);
  for (const r of list) {
    if (!r || !r.action) continue;
    if (r.action === 'advanced') {
      toast(`Babcock tracker: ${r.quote_ref} → ${r.to} ✓`, 'success');
      if (typeof _babcockQuotes !== 'undefined' && Array.isArray(_babcockQuotes)) {
        const row = _babcockQuotes.find(x => x.quote_ref === r.quote_ref);
        if (row) row.status = r.to;
      }
    } else if (r.action === 'skipped') {
      toast(`Babcock tracker NOT updated — ${r.quote_ref} is at "${r.status}" (expected "${r.expected}"). Advance it manually on the Babcock tracker.`, 'warning');
    }
  }
}

const _babcockAdvanceHandlers = {
  'Quote Received':   handleAdvanceFromQuoteReceived,
  'Quote Sent':       handleAdvanceFromQuoteSent,         // 1f
  'Live Project':     handleAdvanceFromLiveProject,       // 1f
  // Project Complete → Bama SW PO Raised — raise PO to Bama SW (handler name
  // says "FromPaymentReceived" because in the old flow that's where this sat).
  'Project Complete':          handleAdvanceFromPaymentReceived,
  // Bama SW PO Raised → Bama SW Invoice Received — upload Bama SW's invoice.
  'Bama SW PO Raised':         handleAdvanceFromBamaSwPoRaised,
  // Bama SW Invoice Received → Approved to Pay — COUPA upload + OCR
  // (handler name says "FromProjectComplete" because in the old flow that's where this sat).
  'Bama SW Invoice Received':  handleAdvanceFromProjectComplete,
  // Approved to Pay → Payment Received — Babcock has paid us.
  'Approved to Pay':           handleAdvanceFromApprovedToPay,
  // Payment Received → Paid to Bama SW — we've paid Bama SW
  // (handler name says "FromBamaSwInvoiceReceived" because in the old flow that's where this sat).
  'Payment Received':          handleAdvanceFromBamaSwInvoiceReceived,
  // Paid to Bama SW → Remittance Sent — create + email remittance advice.
  'Paid to Bama SW':           handleAdvanceFromPaidToBamaSw,
  // Remittance Sent → Closed — mark closed.
  'Remittance Sent':           handleAdvanceFromRemittanceSent
};

// ── Handler: Remittance Sent → Closed (1l) ──
// Simple confirm — all money has been sent and received. Marks the
// job as fully closed so it drops off the default tracker view.
async function handleAdvanceFromRemittanceSent(q, next) {
  const confirmed = await showConfirmAsync(
    '🔒 Close Job',
    `<p style="margin:0">Mark <b>${escapeHtml(q.quote_ref || '')}</b> as Closed?</p>
     <p style="margin:8px 0 0;font-size:12px;color:var(--muted)">
       This job will be hidden from the tracker by default. Use the "Show Closed" toggle to view it again.
     </p>`,
    { okLabel: 'Mark as Closed', cancelLabel: 'Cancel' }
  );
  if (!confirmed) return;

  setLoading(true);
  try {
    const updated = await api.put(`/api/babcock-quotes/${q.id}`, { status: next });
    const idx = _babcockQuotes.findIndex(x => x.id === q.id);
    if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };
    setLoading(false);
    toast(`${updated.quote_ref} → Closed`, 'success');
    renderBabcockTracker();
  } catch (err) {
    setLoading(false);
    toast('Update failed: ' + (err.message || 'unknown error'), 'error');
    loadBabcockTracker();
  }
}

// ── Helper: convert a Blob to base64 (no data: prefix) ──
// Used to encode PDFs as attachments for the Graph sendMail payload.
function blobToBase64(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result || '';
      // FileReader returns "data:<mime>;base64,<payload>" — strip the prefix
      const i = String(result).indexOf(',');
      resolve(i >= 0 ? String(result).slice(i + 1) : '');
    };
    reader.onerror = () => reject(new Error('Failed to encode attachment'));
    reader.readAsDataURL(blob);
  });
}

// ── Helper: pull contact name out of the merged "Contact — Area" string ──
// generateAndSaveBabcockQuote stores the contact and area joined as
// "<quoteFor> \u2014 <area>" in quote_for_area. This recovers the contact
// portion (the bit before the first em-dash) for the email template's
// {{contact_name}} token. If there's no separator, returns the whole
// string trimmed.
function babcockExtractContactName(quoteForArea) {
  if (!quoteForArea) return '';
  const s = String(quoteForArea);
  // Match either em-dash with optional surrounding whitespace, or a
  // hyphen-with-spaces (which some users may type instead of em-dash).
  const m = s.split(/\s[\u2014-]\s/);
  return (m[0] || '').trim();
}

// ── Helper: format a YYYY-MM-DD date as UK long ("14 June 2026") ──
function fmtDateLong(s) {
  if (!s) return '';
  const isoDate = String(s).split('T')[0];
  const d = new Date(isoDate + 'T00:00:00');
  if (isNaN(d.getTime())) return String(s);
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' });
}

// ── Handler: Quote Received → Quote Sent ──
// Re-renders the customer-facing PDF from the stored DB row, then opens
// the email composer with the PDF pre-attached, recipient pre-filled
// from customer_email, subject + body resolved from the emailQuoteSent
// template. On Send: PUTs status='Quote Sent' and stamps date_sent=today.
// On Cancel: row stays at Quote Received so the user can retry.
async function handleAdvanceFromQuoteReceived(qSummary, next) {
  // Sanity-check: we need a customer email to send to. Should always be
  // present (Fix 1b made it required at create time) but legacy rows
  // pre-Fix-1b may have it empty.
  if (!qSummary.customer_email) {
    toast('No customer email on this quote \u2014 add one via Edit before sending', 'error');
    editBabcockQuote(qSummary.id);
    return;
  }
  if (!isPlausibleEmail(qSummary.customer_email)) {
    toast('Customer email looks invalid \u2014 fix it via Edit before sending', 'error');
    editBabcockQuote(qSummary.id);
    return;
  }

  // The list endpoint doesn't include line_items — fetch the full row
  // so the PDF can be re-rendered with all line-item data.
  let q;
  try {
    q = await api.get(`/api/babcock-quotes/${qSummary.id}`);
  } catch (err) {
    toast('Failed to load quote: ' + (err.message || 'unknown error'), 'error');
    return;
  }
  if (!q) return;

  setLoading(true);
  let pdfBlob;
  try {
    // Re-render the PDF from the stored row. Mirrors the logic in the
    // edit-modal regen flow so output is byte-identical.
    await loadLogoDataUri();
    const lineItems = Array.isArray(q.line_items) ? q.line_items
                    : (typeof q.line_items === 'string' && q.line_items
                        ? (() => { try { return JSON.parse(q.line_items); } catch { return []; } })()
                        : []);
    let grandTotal = q.total_value;
    if (grandTotal === null || grandTotal === undefined || !isFinite(grandTotal)) {
      grandTotal = sumMoney(lineItems, l => l.amount);
    }
    pdfBlob = await renderBabcockQuotePDF({
      quoteRef:    q.quote_ref,
      quoteDate:   q.date_sent || q.quotation_date,
      validUntil:  q.valid_until,
      customerId:  q.customer_id,
      workOrderNo: q.work_order_no,
      preparedBy:  q.prepared_by,
      quoteFor:    q.quote_for_area,
      area:        '', // already merged into quote_for_area
      address:     q.quote_for_address,
      comments:    q.comments,
      markup:      q.markup_pct ?? 10,
      grandTotal,
      lineItems
    });
  } catch (err) {
    setLoading(false);
    console.error('PDF render failed:', err);
    toast('Failed to render PDF: ' + (err.message || 'unknown error'), 'error');
    return;
  }
  setLoading(false);

  // Encode the PDF for the email attachment + build a friendly filename
  let pdfBase64;
  try {
    pdfBase64 = await blobToBase64(pdfBlob);
  } catch (err) {
    toast('Failed to encode PDF for email', 'error');
    return;
  }
  const safeRef    = (q.quote_ref || 'BAMA-quote').replace(/[/\\]/g, '_');
  const safeCust   = (q.customer_id || 'Customer').replace(/[/\\]/g, '_');
  const safeWO     = (q.work_order_no || 'WO').replace(/[/\\]/g, '_');
  const pdfFileName = `${safeRef} - ${safeCust} - ${safeWO}.pdf`;

  // Build the tokens used by the emailQuoteSent template
  // Canonical formatter (MONEY section, top of file); '£0.00' rather than '—'
  // because this feeds email body text where a dash reads as a mistake.
  const fmtGBP = v => (v === null || v === undefined || v === '') ? '\u00a30.00' : gbp2(v);

  const tokens = {
    contact_name:  babcockExtractContactName(q.quote_for_area) || 'Sir or Madam',
    quote_ref:     q.quote_ref || '',
    project_name:  q.quote_for_area || '',
    customer_id:   q.customer_id || '',
    work_order_no: q.work_order_no || '',
    valid_until:   fmtDateLong(q.valid_until),
    total_value:   _fmtGBP(q.total_value)
  };

  // Open the composer. Promise resolves on send (with result) or cancel (null).
  await openBabcockEmailModal({
    title: 'Email Quote',
    templateKey: 'emailQuoteSent',
    tokens,
    to: q.customer_email || 'info@bamasw.co.uk',
    attachment: {
      name: pdfFileName,
      contentType: 'application/pdf',
      contentBase64: pdfBase64
    },
    // Fires after the Graph send succeeds; modal is still up so toasts
    // and DB writes happen synchronously before the user sees it close.
    onSent: async () => {
      try {
        const today = todayStr();
        const updated = await api.put(`/api/babcock-quotes/${q.id}`, {
          status: next,
          date_sent: today
        });
        const idx = _babcockQuotes.findIndex(x => x.id === q.id);
        if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };
        renderBabcockTracker();
      } catch (err) {
        // Email DID go out — only the status update failed. Tell the
        // user explicitly so they can fix the row state manually. We
        // don't unsend the email obviously.
        console.error('Status update after email failed:', err);
        toast(
          'Email sent OK but couldn\u2019t update status \u2014 please refresh and edit the row to set status=Quote Sent',
          'error'
        );
        loadBabcockTracker();
      }
    }
  });
  // If user cancelled, the modal resolves with null and we leave the
  // row untouched — no API call made.
}

// ─────────────────────────────────────────────────────────────────────
// CONVERT TO PROJECT — modal + conversion (used by 1f handlers)
// ─────────────────────────────────────────────────────────────────────

// Module-level promise resolver for the convert modal — same Promise-
// based pattern as openBabcockEmailModal. Set when the modal opens.
let _bcvResolve = null;
let _bcvProjectNumber = null; // cached so confirmBabcockConvert can use it

// Derive the project number for a Babcock quote: B0011 → BC0011.
// Insert C immediately after the leading B. If the ref doesn't start
// with B, fall back to prefixing with BC for safety.
function babcockProjectNumberFor(quoteRef) {
  const s = String(quoteRef || '');
  const m = s.match(/^B(\d.*)$/i);
  if (m) return 'BC' + m[1];
  return 'BC' + s;
}

// Suggest a project name from the merged "Contact — Area" string.
// Take the part AFTER the em-dash (the area); if no separator, return
// the full string. So "John Smith — Plant Room Refurb" → "Plant Room
// Refurb"; bare "Plant Room" → "Plant Room".
function babcockSuggestProjectName(quoteForArea) {
  if (!quoteForArea) return '';
  const s = String(quoteForArea);
  const parts = s.split(/\s[\u2014-]\s/);
  if (parts.length >= 2) return parts.slice(1).join(' \u2014 ').trim();
  return s.trim();
}

// Open the convert modal. Pre-fills the project number preview and
// suggests a project name. Returns a Promise resolving to
// {poNumber, projectName} on Convert, or null on Cancel.
function openBabcockConvertModal(quote) {
  _bcvProjectNumber = babcockProjectNumberFor(quote.quote_ref);

  // Reset inputs
  document.getElementById('bcvPoNumber').value = quote.po_number || '';
  document.getElementById('bcvProjectName').value = quote.work_order_no || babcockSuggestProjectName(quote.quote_for_area);
  document.getElementById('bcvProjectNumberPreview').textContent = _bcvProjectNumber;
  document.getElementById('bcvConfirmBtn').disabled = false;
  document.getElementById('bcvConfirmBtn').textContent = 'Convert';

  document.getElementById('babcockConvertModal').classList.add('active');
  setTimeout(() => document.getElementById('bcvPoNumber')?.focus(), 60);

  return new Promise(resolve => { _bcvResolve = resolve; });
}

function closeBabcockConvertModal() {
  document.getElementById('babcockConvertModal').classList.remove('active');
  if (_bcvResolve) {
    const r = _bcvResolve;
    _bcvResolve = null;
    r(null);
  }
}

function confirmBabcockConvert() {
  const poNumber = (document.getElementById('bcvPoNumber').value || '').trim();
  const projectName = (document.getElementById('bcvProjectName').value || '').trim();
  if (!poNumber) {
    toast('Client PO number is required', 'error');
    document.getElementById('bcvPoNumber').focus();
    return;
  }
  if (!projectName) {
    toast('Project name is required', 'error');
    document.getElementById('bcvProjectName').focus();
    return;
  }
  // Resolve before closing so the caller can see the values
  document.getElementById('babcockConvertModal').classList.remove('active');
  if (_bcvResolve) {
    const r = _bcvResolve;
    _bcvResolve = null;
    r({ poNumber, projectName, projectNumber: _bcvProjectNumber });
  }
}

// ── Convert a Babcock quote to a Project ──
// Mirrors convertQuoteToProject for the main tender flow, with these
// differences:
//  - Project number is B0011 → BC0011 (insert C, not swap)
//  - Writes source_babcock_quote_id (Fix 1a column) not source_quote_id
//  - No ProjectQuotes link table insert (that's tender-side only)
//  - No quote-line-items seed (Babcock quotes don't use the 9 categories)
// Idempotent: if a Project already exists for this Babcock quote, returns
// the existing row without creating duplicates.
async function convertBabcockQuoteToProject(q, opts) {
  if (!q) throw new Error('No Babcock quote supplied');
  const { poNumber, projectName, projectNumber } = opts || {};
  if (!projectNumber) throw new Error('projectNumber required');
  if (!projectName)   throw new Error('projectName required');
  if (!poNumber)      throw new Error('poNumber required');

  // Idempotency check — has this quote already been converted?
  try {
    const existing = await api.get(`/api/projects-by-babcock-quote/${q.id}`);
    if (existing && existing.id) {
      console.warn('Project already exists for this Babcock quote:', existing.project_number);
      return existing;
    }
  } catch (e) {
    // 404/empty fine — proceed
  }

  // Secondary check — catch orphaned project rows with the same number
  // (e.g. a previous failed conversion that created the DB row but didn't
  // write linked_project_id back to the quote)
  try {
    const orphan = await api.get(`/api/projects-by-number/${encodeURIComponent(projectNumber)}`);
    if (orphan && orphan.id) {
      console.warn('Found orphaned project with same number — reusing:', orphan.project_number);
      return orphan;
    }
  } catch (e) {
    // Not found — proceed to create
  }

  // Build folder name: "BC0011 - <Customer ID> - <Project Name>"
  const custPart    = sanitiseFolderSegment(q.customer_id || 'Babcock');
  const woPart      = sanitiseFolderSegment(q.work_order_no || projectName);
  const folderName  = [projectNumber, custPart, woPart].filter(Boolean).join(' - ');

  // 1. Create SharePoint folders. Babcock projects get their own subfolder
  //    inside the year folder: 06 - Projects / <year> / 01 - Babcock / BC…
  //    (Mateusz 2026-08-08 — keeps BC jobs out of the main project list).
  const token = await getToken();
  const projectsRoot = await spBabcockProjectParent();   // <year>/01 - Babcock
  const projectFolder = await createFolderInDrive(projectsRoot.id, folderName);

  // Create the standard 9 subfolders
  const subfolderMap = {};
  for (const sub of PROJECT_SUBFOLDERS) {
    const sf = await createFolderInDrive(projectFolder.id, sub);
    subfolderMap[sub] = sf;
  }

  // 2. Copy the Babcock quote PDF + original .xlsx into 03 - Quote
  //    The Babcock quote uploads live in the Quotation tree, not under
  //    Projects. We copy individual files (not a whole folder) since
  //    the parent Babcock folder may contain other quotes too.
  const quoteSubfolder = subfolderMap['03 - Quote'];
  if (quoteSubfolder) {
    const fileIdsToCopy = [q.original_file_id, q.generated_file_id].filter(Boolean);
    for (const fileId of fileIdsToCopy) {
      try {
        await fetch(
          `https://graph.microsoft.com/v1.0/drives/${BAMA_DRIVE_ID}/items/${fileId}/copy`,
          {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
            body: JSON.stringify({
              parentReference: { driveId: BAMA_DRIVE_ID, id: quoteSubfolder.id }
            })
          }
        );
      } catch (e) {
        console.warn('Failed to copy file to 03 - Quote (non-fatal):', e);
      }
    }
  }

  // 3. Create the Projects DB row
  const projectRow = await api.post('/api/projects', {
    project_number: projectNumber,
    project_name:   projectName,
    client_id:      null,  // Babcock doesn't currently use the Clients table — quotes are standalone
    status:         'In Progress',
    source_babcock_quote_id: q.id,
    quote_value:    q.total_value != null ? parseFloat(q.total_value) : null,
    deadline_date:  q.valid_until ? String(q.valid_until).split('T')[0] : null,
    comments:       q.comments || null,
    sharepoint_folder_id: projectFolder.id,
    sharepoint_quote_folder_id: null,  // Babcock quotes live in a different tree
    created_by:     currentManagerUser || (typeof AUTH !== 'undefined' && AUTH.getUserName?.()) || 'unknown'
  });

  // Cache locally so the Project Tracker picks it up without reload
  if (Array.isArray(projectsData)) projectsData.unshift(projectRow);

  return projectRow;
}

// ── Handler: Quote Sent → Live Project (Convert to Project) ──
async function handleAdvanceFromQuoteSent(q, next) {
  // Permission gate — converting writes to the Projects table, which
  // sits behind the editProjects permission on the main app.
  const perms = getUserPermissions(currentManagerUser) || {};
  if (!perms.editProjects) {
    toast('You don\u2019t have permission to create projects', 'error');
    return;
  }

  const result = await openBabcockConvertModal(q);
  if (!result) return; // user cancelled

  setLoading(true);
  let projectRow;
  try {
    projectRow = await convertBabcockQuoteToProject(q, result);
  } catch (err) {
    setLoading(false);
    console.error('Convert to Project failed:', err);
    toast('Convert failed: ' + (err.message || 'unknown error'), 'error');
    return;
  }

  // Patch the Babcock quote with new status + PO + linked project id
  try {
    const updated = await api.put(`/api/babcock-quotes/${q.id}`, {
      status: next,
      po_number: result.poNumber,
      linked_project_id: projectRow.id
    });
    const idx = _babcockQuotes.findIndex(x => x.id === q.id);
    if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };
    setLoading(false);
    toast(`Project ${projectRow.project_number} created \u2713`, 'success');
    renderBabcockTracker();
  } catch (err) {
    setLoading(false);
    // Project DID get created — only the status update failed. Tell the
    // user so they can fix the row manually rather than retry-and-duplicate.
    console.error('Status update after convert failed:', err);
    toast(
      `Project ${projectRow.project_number} created but couldn\u2019t update quote \u2014 refresh and edit to set status=Live Project, PO=${result.poNumber}`,
      'error'
    );
    loadBabcockTracker();
  }
}

// ── Handler: Live Project → Project Complete ──
// Marks both the BabcockQuotes row and its linked Project row complete.
async function handleAdvanceFromLiveProject(q, next) {
  // Confirm modal — destructive-ish, deserves a yes/no gate
  const confirmed = await showConfirmAsync(
    '🏁 Complete Project',
    `<p style="margin:0">Mark project as complete?</p>
     <p style="margin:8px 0 0;font-size:12px;color:var(--muted)">
       This will set both <b>${escapeHtml(q.quote_ref || '')}</b> and its linked project to <b>Complete</b>.
       You can continue the finance workflow (Bama SW PO → Bama SW Invoice → COUPA approval → payment) afterwards.
     </p>`,
    { okLabel: 'Mark Complete', cancelLabel: 'Cancel' }
  );
  if (!confirmed) return;

  setLoading(true);
  try {
    // Update the linked Project row first (if there is one). Non-fatal
    // if it's missing — the Babcock quote is still the source of truth
    // for the workflow state.
    if (q.linked_project_id) {
      try {
        await api.put(`/api/projects/${q.linked_project_id}`, {
          status: 'Complete',
          completion_date: todayStr()
        });
        // Also patch projectsData if present so Project Tracker reflects it
        if (Array.isArray(projectsData)) {
          const pIdx = projectsData.findIndex(p => p.id === q.linked_project_id);
          if (pIdx !== -1) {
            projectsData[pIdx] = {
              ...projectsData[pIdx],
              status: 'Complete',
              completion_date: todayStr()
            };
          }
        }
      } catch (err) {
        // Log but don't block — the Babcock row state is still authoritative
        console.warn('Linked project completion update failed (non-fatal):', err);
      }
    }

    // Update the Babcock quote
    const updated = await api.put(`/api/babcock-quotes/${q.id}`, { status: next });
    const idx = _babcockQuotes.findIndex(x => x.id === q.id);
    if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };

    setLoading(false);
    toast(`${updated.quote_ref} \u2192 Project Complete`, 'success');
    renderBabcockTracker();
  } catch (err) {
    setLoading(false);
    toast('Update failed: ' + (err.message || 'unknown error'), 'error');
    loadBabcockTracker();
  }
}

// ─────────────────────────────────────────────────────────────────────
// APPROVED TO PAY — COUPA invoice upload + OCR (1g)
// ─────────────────────────────────────────────────────────────────────
//
// User clicks "Approved to Pay" on a Project Complete row. We open a
// modal, they pick the COUPA-approved invoice PDF, PDF.js extracts the
// invoice number / due date / gross total / customer PO ref via regex
// over the text content, user reviews + edits, hits Confirm — we then
// upload the PDF to SharePoint and PUT the row with the new fields.
//
// OCR fields (per the sample COUPA invoice analysed earlier):
//   Invoice Number       → `Invoice Number\s+(INV\d+)` (also appears in header)
//   Payment Due Date     → `Payment Due Date\s+(\d{1,2}\s+\w+\s+\d{4})`
//   Gross Total          → `Gross Total\s+([\d,]+\.\d{2})\s+GBP`
//   COUPA PO Ref         → `CP\d+(-\d+)?` from the line-item column
//
// On OCR failure (regex misses), modal still opens with empty fields
// and a "couldn't auto-fill" notice — user types them manually.

// Module-level state for the open modal session
let _bapContext = null; // { quote, next, file, parsed }

function closeBabcockApprovedToPayModal() {
  document.getElementById('babcockApprovedToPayModal').classList.remove('active');
  _bapContext = null;
}

// Open the modal, fresh state. Called from handleAdvanceFromProjectComplete.
function openBabcockApprovedToPayModal(quote, next) {
  _bapContext = { quote, next, file: null, parsed: null };

  // Reset UI
  document.getElementById('bapFields').style.display = 'none';
  document.getElementById('bapDropZoneText').textContent = 'Click to pick PDF';
  document.getElementById('bapFileInput').value = '';
  document.getElementById('bapConfirmBtn').disabled = true;
  document.getElementById('bapConfirmBtn').textContent = 'Confirm & Save';

  for (const id of ['bapInvoiceNumber', 'bapDueDate', 'bapGrossTotal', 'bapCoupaPoRef']) {
    const el = document.getElementById(id);
    if (el) el.value = '';
  }

  // Wire drag-and-drop on the drop zone (idempotent — checks _wired flag)
  const dz = document.getElementById('bapDropZone');
  if (dz && !dz._dragWired) {
    dz._dragWired = true;
    dz.addEventListener('dragover', (e) => {
      e.preventDefault();
      dz.style.borderColor = 'var(--accent)';
    });
    dz.addEventListener('dragleave', () => {
      dz.style.borderColor = '';
    });
    dz.addEventListener('drop', (e) => {
      e.preventDefault();
      dz.style.borderColor = '';
      const file = e.dataTransfer.files && e.dataTransfer.files[0];
      if (file) onBabcockApprovedFilePicked(file);
    });
  }

  document.getElementById('babcockApprovedToPayModal').classList.add('active');
}

// Triggered when the user picks a PDF in the modal. Runs OCR, populates
// the fields, surfaces a coloured status banner depending on how much
// was extracted.
async function onBabcockApprovedFilePicked(file) {
  if (!file || !_bapContext) return;
  if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
    toast('Please pick a PDF file', 'error');
    return;
  }

  _bapContext.file = file;
  document.getElementById('bapDropZoneText').textContent = file.name;
  document.getElementById('bapFields').style.display = '';

  const statusEl = document.getElementById('bapOcrStatus');
  statusEl.textContent = 'Reading PDF…';
  statusEl.style.background = 'rgba(255,107,0,.08)';
  statusEl.style.color = 'var(--accent)';
  statusEl.style.border = '1px solid rgba(255,107,0,.2)';

  let parsed;
  try {
    parsed = await extractCoupaInvoiceFields(file);
    _bapContext.parsed = parsed;
  } catch (err) {
    console.error('PDF OCR failed:', err);
    parsed = { invoiceNumber: '', dueDateIso: '', grossTotal: '', coupaPoRef: '', failed: true };
  }

  // Populate
  if (parsed.invoiceNumber) document.getElementById('bapInvoiceNumber').value = parsed.invoiceNumber;
  if (parsed.dueDateIso)    document.getElementById('bapDueDate').value       = parsed.dueDateIso;
  if (parsed.grossTotal)    document.getElementById('bapGrossTotal').value    = parsed.grossTotal;
  if (parsed.coupaPoRef)    document.getElementById('bapCoupaPoRef').value    = parsed.coupaPoRef;

  // Status banner: count what we got
  const fieldsFound = ['invoiceNumber', 'dueDateIso', 'grossTotal', 'coupaPoRef']
    .filter(k => parsed[k]).length;

  if (parsed.failed || fieldsFound === 0) {
    statusEl.textContent = '⚠ Couldn\u2019t auto-fill — please enter the fields manually below.';
    statusEl.style.background = 'rgba(220,53,69,.08)';
    statusEl.style.color = 'var(--red)';
    statusEl.style.border = '1px solid rgba(220,53,69,.25)';
  } else if (fieldsFound < 4) {
    statusEl.textContent = `Found ${fieldsFound} of 4 fields — please check and fill any blanks.`;
    statusEl.style.background = 'rgba(255,193,7,.08)';
    statusEl.style.color = '#ffc945';
    statusEl.style.border = '1px solid rgba(255,193,7,.25)';
  } else {
    statusEl.textContent = '✓ All four fields extracted — review and confirm.';
    statusEl.style.background = 'rgba(46,204,113,.08)';
    statusEl.style.color = 'var(--green)';
    statusEl.style.border = '1px solid rgba(46,204,113,.25)';
  }

  document.getElementById('bapConfirmBtn').disabled = false;
}

// ── PDF.js text extraction + COUPA-specific regex parsing ──
// Returns { invoiceNumber, dueDateIso, grossTotal, coupaPoRef }.
// Any field that the regex can't match comes back empty — UI shows
// the "couldn't auto-fill" banner when none match.
// ── Extract fields from a Bama SW invoice PDF ──
// Template: TAX INVOICE from Bama South West Ltd.
// Key fields: Invoice Number, Invoice Date, Reference (our PO),
// Total GBP, Due Date, reverse charge flag.
async function extractBamaSwInvoiceFields(file) {
  const result = { invoiceNumber: '', invoiceDate: '', reference: '', totalGbp: '', dueDateIso: '', isReverseCharge: false, failed: false };
  try {
    if (typeof pdfjsLib === 'undefined') throw new Error('PDF.js not loaded');
    const arrayBuffer = await file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    let fullText = '';
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const content = await page.getTextContent();
      fullText += content.items.map(it => it.str).join(' ') + '\n';
    }
    const text = fullText.replace(/\s+/g, ' ');

    // Invoice Number — "Invoice Number INV-0007"
    const invMatch = text.match(/Invoice\s+Number\s+(INV[-\w]+)/i)
                  || text.match(/\b(INV[-\w]{3,})\b/);
    if (invMatch) result.invoiceNumber = invMatch[1].trim();

    // Invoice Date — "Invoice Date 14 May 2026"
    const invDateMatch = text.match(/Invoice\s+Date\s+(\d{1,2}\s+[A-Za-z]+\s+\d{4})/i);
    if (invDateMatch) result.invoiceDate = invDateMatch[1].trim();

    // Reference (our PO number) — "Reference P260449"
    const refMatch = text.match(/Reference\s+([A-Z]\d{5,})/i);
    if (refMatch) result.reference = refMatch[1].trim();

    // Total GBP — "TOTAL GBP 1,173.00"
    const totalMatch = text.match(/TOTAL\s+GBP\s+([\d,]+\.\d{2})/i);
    if (totalMatch) result.totalGbp = totalMatch[1].replace(/,/g, '');

    // Due Date — "Due Date: 14 May 2026"
    const dueMatch = text.match(/Due\s+Date[:\s]+(\d{1,2}\s+[A-Za-z]+\s+\d{4})/i);
    if (dueMatch) result.dueDateIso = parseUkLongDateToIso(dueMatch[1]);

    // Reverse charge — any mention of domestic reverse charge
    result.isReverseCharge = /reverse\s+charge/i.test(text);

  } catch (e) {
    console.error('Bama SW invoice parse failed:', e);
    result.failed = true;
  }
  return result;
}

async function extractCoupaInvoiceFields(file) {
  if (typeof pdfjsLib === 'undefined') {
    throw new Error('PDF.js not loaded');
  }
  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
  let fullText = '';
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    fullText += content.items.map(it => it.str).join(' ') + '\n';
  }

  // Normalise whitespace for stabler regex matches
  const text = fullText.replace(/\s+/g, ' ');

  // Invoice number — matches the "Invoice Number" labelled row.
  // The COUPA sample has it appearing twice; we capture the first.
  let invoiceNumber = '';
  const invMatch = text.match(/Invoice Number\s+(INV\d+)/i)
                || text.match(/\b(INV\d{4,})\b/);  // fallback to bare INV-prefix
  if (invMatch) invoiceNumber = invMatch[1];

  // Payment due date — matches "Payment Due Date 04 June 2026" style
  let dueDateIso = '';
  const dueMatch = text.match(/Payment Due Date\s+(\d{1,2}\s+[A-Za-z]+\s+\d{4})/);
  if (dueMatch) dueDateIso = parseUkLongDateToIso(dueMatch[1]);

  // Gross total — matches "Gross Total 984.00 GBP" style
  let grossTotal = '';
  const totMatch = text.match(/Gross Total\s+([\d,]+\.\d{2})\s+GBP/i);
  if (totMatch) grossTotal = totMatch[1].replace(/,/g, '');

  // COUPA PO ref — pattern CP##### or CP#####-#
  let coupaPoRef = '';
  const poMatch = text.match(/\b(CP\d+(?:-\d+)?)\b/);
  if (poMatch) coupaPoRef = poMatch[1];

  return { invoiceNumber, dueDateIso, grossTotal, coupaPoRef };
}

// Helper: parse "04 June 2026" → "2026-06-04" (ISO date)
function parseUkLongDateToIso(s) {
  if (!s) return '';
  const months = { jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11,
                   january:0,february:1,march:2,april:3,june:5,july:6,august:7,
                   september:8,october:9,november:10,december:11 };
  const m = String(s).trim().match(/^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})$/);
  if (!m) return '';
  const day = parseInt(m[1], 10);
  const mon = months[m[2].toLowerCase()];
  const year = parseInt(m[3], 10);
  if (mon === undefined || isNaN(day) || isNaN(year)) return '';
  const dd = String(day).padStart(2, '0');
  const mm = String(mon + 1).padStart(2, '0');
  return `${year}-${mm}-${dd}`;
}

// ── Confirm: validate, upload PDF, PUT row ──
async function confirmBabcockApprovedToPay() {
  if (!_bapContext || !_bapContext.file) {
    toast('Pick a PDF first', 'error');
    return;
  }

  const invoiceNumber = (document.getElementById('bapInvoiceNumber').value || '').trim();
  const dueDateIso    = (document.getElementById('bapDueDate').value || '').trim();
  const grossTotalRaw = (document.getElementById('bapGrossTotal').value || '').trim();
  const coupaPoRef    = (document.getElementById('bapCoupaPoRef').value || '').trim();

  // Validate the three required fields
  if (!invoiceNumber) {
    toast('Invoice number is required', 'error');
    document.getElementById('bapInvoiceNumber').focus();
    return;
  }
  if (!dueDateIso) {
    toast('Due date is required', 'error');
    document.getElementById('bapDueDate').focus();
    return;
  }
  if (!grossTotalRaw) {
    toast('Gross total is required', 'error');
    document.getElementById('bapGrossTotal').focus();
    return;
  }
  const grossTotalNum = parseFloat(grossTotalRaw);
  if (isNaN(grossTotalNum) || grossTotalNum <= 0) {
    toast('Gross total must be a positive number', 'error');
    document.getElementById('bapGrossTotal').focus();
    return;
  }

  const q = _bapContext.quote;
  const next = _bapContext.next;
  const file = _bapContext.file;

  // Lock the button + show progress
  const btn = document.getElementById('bapConfirmBtn');
  btn.disabled = true;
  btn.textContent = 'Uploading…';

  try {
    // Upload to SharePoint. Filename: "<quote-ref> - <invoice-number>.pdf"
    // so files sort naturally by quote ref in the Approved Invoices folder.
    const folders = await findOrCreateBabcockFolders();
    const approvedFolder = await getOrCreateSubfolder(folders.parent.id, 'Approved Invoices', BAMA_DRIVE_ID);
    if (!approvedFolder) throw new Error('Could not create Approved Invoices folder');

    const safeRef = (q.quote_ref || 'Babcock').replace(/[/\\]/g, '_');
    const safeInv = (invoiceNumber || 'INV').replace(/[/\\]/g, '_');
    const fileName = `${safeRef} - ${safeInv}.pdf`;

    const uploaded = await uploadFileToFolder(
      approvedFolder.id,
      fileName,
      await file.arrayBuffer(),
      'application/pdf'
    );

    // PUT the Babcock row with all the new fields
    btn.textContent = 'Saving…';
    const updated = await api.put(`/api/babcock-quotes/${q.id}`, {
      status: next,
      coupa_invoice_pdf_url: uploaded.webUrl || null,
      coupa_invoice_pdf_id:  uploaded.id || null,
      coupa_invoice_number:  invoiceNumber,
      coupa_invoice_due_date: dueDateIso,
      coupa_invoice_gross_total: grossTotalNum,
      coupa_po_ref:          coupaPoRef || null
    });
    const idx = _babcockQuotes.findIndex(x => x.id === q.id);
    if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };

    toast(`${updated.quote_ref} \u2192 Approved to Pay`, 'success');
    closeBabcockApprovedToPayModal();
    renderBabcockTracker();
  } catch (err) {
    console.error('Approved-to-pay save failed:', err);
    toast('Save failed: ' + (err.message || 'unknown error'), 'error');
    btn.disabled = false;
    btn.textContent = 'Confirm & Save';
  }
}

// ── Handler: COUPA invoice upload + OCR ──
// Wired under the new workflow as: Bama SW Invoice Received → Approved to Pay.
// (Function name retained for stability — see _babcockAdvanceHandlers map.)
async function handleAdvanceFromProjectComplete(q, next) {
  openBabcockApprovedToPayModal(q, next);
}

// ── Handler: Approved to Pay → Payment Received ──
// Simple status flip + stamps payment_received_at = now so we know
// when the money landed. Useful for reporting / chasing dashboards.
async function handleAdvanceFromApprovedToPay(q, next) {
  const confirmed = await showConfirmAsync(
    '💰 Payment Received',
    `<p style="margin:0">Mark <b>${escapeHtml(q.quote_ref || '')}</b> as paid by Babcock?</p>
     <p style="margin:8px 0 0;font-size:12px;color:var(--muted)">
       The next step will be to mark Bama SW as paid.
     </p>`,
    { okLabel: 'Confirm Payment', cancelLabel: 'Cancel' }
  );
  if (!confirmed) return;

  setLoading(true);
  try {
    const updated = await api.put(`/api/babcock-quotes/${q.id}`, {
      status: next,
      payment_received_at: new Date().toISOString()
    });
    const idx = _babcockQuotes.findIndex(x => x.id === q.id);
    if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };
    setLoading(false);
    toast(`${updated.quote_ref} \u2192 Payment Received`, 'success');
    renderBabcockTracker();
  } catch (err) {
    setLoading(false);
    toast('Update failed: ' + (err.message || 'unknown error'), 'error');
    loadBabcockTracker();
  }
}

// ─────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────
// RAISE PO TO BAMA SW (1h)
// ─────────────────────────────────────────────────────────────────────
// At "Payment Received", Babcock has paid us. We now raise a Purchase
// Order to Bama South West (our subcontractor) for the pre-markup value
// minus any project expenses, generate a PO PDF, upload to SharePoint
// and email it to Bama SW.

let _bpoToBswContext = null;

function closeBabcockPoToBamaSwModal() {
  document.getElementById('babcockPoToBamaSwModal').classList.remove('active');
  _bpoToBswContext = null;
}

async function handleAdvanceFromPaymentReceived(q, next) {
  const total     = Number(q.total_value || 0);
  const markupPct = Number(q.markup_pct  || 0);
  const original  = _r2(markupPct > 0 ? total / (1 + markupPct / 100) : total);

  // Subtract the project's PO expenses (materials etc. bought by BAMA) so the
  // Bama SW figure is the pre-markup value NET of what we already spent.
  // Same definition as Project Tracker's Running Cost: every non-Cancelled PO
  // on the linked project, netted of VAT via _poNet. The Bama SW PO itself is
  // never a PurchaseOrders row (PDF + babcock-quotes fields only), so there is
  // no self-double-count. Non-fatal: if the fetch fails we fall back to the
  // undeducted figure and say so — the user confirms the amount in the modal.
  let poExpenses = 0, poCount = 0, poFetchFailed = false;
  if (q.linked_project_id) {
    try {
      const pos    = await api.get(`/api/purchase-orders?project_id=${q.linked_project_id}`);
      const active = (pos || []).filter(p => p.status !== 'Cancelled');
      poExpenses   = sumMoney(active, _poNet);
      poCount      = active.length;
    } catch (e) {
      poFetchFailed = true;
      console.warn('Could not load project POs for Bama SW deduction:', e);
    }
  }
  const netTotal = Math.max(0, _r2(original - poExpenses));

  let projectNumber = '';
  try {
    const proj = (projectsData || []).find(p => p.id === q.linked_project_id);
    projectNumber = (proj && proj.project_number) || babcockProjectNumberFor(q.quote_ref || '');
  } catch (e) {
    projectNumber = babcockProjectNumberFor(q.quote_ref || '');
  }

  _bpoToBswContext = { quote: q, next, netTotal, projectNumber };

  document.getElementById('bptbsProjectRef').textContent = projectNumber || q.quote_ref || '';
  const amountEl = document.getElementById('bptbsAmount');
  amountEl.textContent = fmtCurrency(netTotal);
  amountEl.title = poCount
    ? `Pre-markup ${fmtCurrency(original)} − ${poCount} project PO${poCount !== 1 ? 's' : ''} (nett) ${fmtCurrency(poExpenses)}`
    : `Pre-markup value ${fmtCurrency(original)} — no project PO expenses to deduct`;
  const breakdownEl = document.getElementById('bptbsBreakdown');
  if (breakdownEl) {
    breakdownEl.textContent = poCount
      ? `Pre-markup ${fmtCurrency(original)} − ${poCount} PO${poCount !== 1 ? 's' : ''} nett ${fmtCurrency(poExpenses)}`
      : (poFetchFailed ? '⚠ Could not load project POs — no expense deduction applied' : '');
  }
  if (poFetchFailed) toast('Could not load project POs — amount shown WITHOUT expense deduction', 'warning');
  document.getElementById('bptbsPoNumber').value         = q.bama_sw_po_number || '';
  const due = new Date(); due.setDate(due.getDate() + 30);
  document.getElementById('bptbsDueDate').value          = due.toISOString().split('T')[0];
  document.getElementById('bptbsConfirmBtn').disabled    = false;
  document.getElementById('bptbsConfirmBtn').textContent = 'Generate & Email';

  document.getElementById('babcockPoToBamaSwModal').classList.add('active');
  setTimeout(() => document.getElementById('bptbsPoNumber')?.focus(), 60);
}

async function confirmRaisePOToBamaSw() {
  if (!_bpoToBswContext) return;

  const poNumber   = (document.getElementById('bptbsPoNumber').value  || '').trim();
  const dueDateIso = (document.getElementById('bptbsDueDate').value   || '').trim();

  if (!poNumber)   { toast('PO number is required',  'error'); document.getElementById('bptbsPoNumber').focus();  return; }
  if (!dueDateIso) { toast('Due date is required',   'error'); document.getElementById('bptbsDueDate').focus();   return; }

  const { quote: q, next, netTotal, projectNumber } = _bpoToBswContext;
  const btn = document.getElementById('bptbsConfirmBtn');
  btn.disabled = true; btn.textContent = 'Generating…';

  // 1. Generate PO PDF
  let pdfBlob;
  try {
    pdfBlob = await renderBamaSwPoPDF({
      poNumber,
      poDate:        fmtDateStr(todayStr()),
      dueDate:       fmtDateStr(dueDateIso),
      projectNumber,
      projectName:   q.quote_for_area || '',
      quoteRef:      q.quote_ref || '',
      netTotal
    });
  } catch (err) {
    console.error('PO PDF render failed:', err);
    toast('PDF render failed: ' + (err.message || 'unknown error'), 'error');
    btn.disabled = false; btn.textContent = 'Generate & Email';
    return;
  }

  // 2. Upload to SharePoint
  let pdfUploaded = null;
  try {
    btn.textContent = 'Uploading PDF…';
    const folders   = await findOrCreateBabcockFolders();
    const poFolder  = await getOrCreateSubfolder(folders.parent.id, 'Bama SW Purchase Orders', BAMA_DRIVE_ID);
    if (!poFolder) throw new Error('Could not create Bama SW Purchase Orders folder');
    const safeRef  = (q.quote_ref || 'Babcock').replace(/[/\\]/g, '_');
    const fileName = `${poNumber} - ${safeRef} - PO.pdf`;
    pdfUploaded    = await uploadFileToFolder(poFolder.id, fileName, await pdfBlob.arrayBuffer(), 'application/pdf');
  } catch (err) {
    console.error('PO PDF upload failed:', err);
    toast('SharePoint upload failed: ' + (err.message || 'unknown error'), 'error');
    btn.disabled = false; btn.textContent = 'Generate & Email';
    return;
  }

  // 3. Encode for email
  btn.textContent = 'Opening email…';
  let pdfBase64;
  try { pdfBase64 = await blobToBase64(pdfBlob); }
  catch (err) { toast('Failed to encode PDF for email', 'error'); btn.disabled = false; btn.textContent = 'Generate & Email'; return; }

  document.getElementById('babcockPoToBamaSwModal').classList.remove('active');
  const sentCtx = { quote: q, next, poNumber, dueDateIso, pdfUploaded, netTotal, projectNumber };
  _bpoToBswContext = null;

  const safeRefEmail = (q.quote_ref || 'Babcock').replace(/[/\\]/g, '_');
  await openBabcockEmailModal({
    title:       'Email PO to Bama SW',
    templateKey: 'emailBamaSwPo',
    tokens: {
      bama_sw_po_number:   poNumber,
      project_number:      projectNumber,
      project_name:        q.quote_for_area || '',
      po_value:            fmtCurrency(netTotal),
      bama_sw_po_due_date: fmtDateStr(dueDateIso)
    },
    to:  tplGet('emailBamaSwPo', 'to') || 'info@bamasw.co.uk',
    cc:  '',
    attachment: {
      name:          `${poNumber} - ${safeRefEmail} - PO.pdf`,
      contentType:   'application/pdf',
      contentBase64: pdfBase64
    },
    onSent: async () => {
      try {
        const updated = await api.put(`/api/babcock-quotes/${sentCtx.quote.id}`, {
          status:              sentCtx.next,
          bama_sw_po_number:   sentCtx.poNumber,
          bama_sw_po_pdf_url:  sentCtx.pdfUploaded?.webUrl || null,
          bama_sw_po_pdf_id:   sentCtx.pdfUploaded?.id     || null
        });
        const idx = _babcockQuotes.findIndex(x => x.id === sentCtx.quote.id);
        if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };
        renderBabcockTracker();
        toast(`${sentCtx.quote.quote_ref} → Bama SW PO Raised`, 'success');
      } catch (err) {
        console.error('Status update after PO send failed:', err);
        toast(`Email sent OK but couldn\'t update status — please refresh and edit to set status=Bama SW PO Raised`, 'error');
        loadBabcockTracker();
      }
    }
  });
}

// ─────────────────────────────────────────────────────────────────────
// RECEIVE BAMA SW INVOICE (1i)
// ─────────────────────────────────────────────────────────────────────
// Once we've sent the PO, Bama SW sends us their invoice. User uploads
// the PDF, enters their invoice number + amount. Amount is validated
// against expected (warn but don't block). PDF saved to SharePoint.

let _briiContext = null;

function closeBamaSwReceiveInvoiceModal() {
  document.getElementById('babcockReceiveInvoiceModal').classList.remove('active');
  _briiContext = null;
}

async function handleAdvanceFromBamaSwPoRaised(q, next) {
  const total     = Number(q.total_value || 0);
  const markupPct = Number(q.markup_pct  || 0);
  const original  = markupPct > 0 ? total / (1 + markupPct / 100) : total;
  const expected  = Math.max(0, original);

  _briiContext = { quote: q, next, expectedAmount: expected, file: null, invoiceNumber: '', parsed: null };

  document.getElementById('briiExpectedAmt').textContent     = fmtCurrency(expected);
  document.getElementById('briiDropZoneText').textContent    = 'Drop PDF here or click to upload';
  document.getElementById('briiDropZone').style.borderColor  = 'var(--border)';
  document.getElementById('briiFileInput').value             = '';
  document.getElementById('briiInvoiceNumberDisplay').textContent = '—';
  document.getElementById('briiInvoiceAmount').value         = '';
  document.getElementById('briiAmountWarning').style.display = 'none';
  document.getElementById('briiParseStatus').style.display   = 'none';
  document.getElementById('briiParsedData').style.display    = 'none';
  document.getElementById('briiComparison').style.display    = 'none';
  document.getElementById('briiConfirmBtn').disabled         = true;
  document.getElementById('briiConfirmBtn').textContent      = 'Save & Confirm';

  document.getElementById('babcockReceiveInvoiceModal').classList.add('active');
  setTimeout(() => document.getElementById('briiInvoiceNumber')?.focus(), 60);
}

function onBamaSwInvoiceFilePicked(file) {
  if (!file || !_briiContext) return;
  if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
    toast('Please upload a PDF file', 'error'); return;
  }
  _briiContext.file = file;
  document.getElementById('briiDropZoneText').textContent = `✓ ${file.name}`;
  document.getElementById('briiDropZone').style.borderColor = 'var(--green)';
  document.getElementById('briiParseStatus').textContent = 'Parsing invoice…';
  document.getElementById('briiParseStatus').style.display = 'block';
  document.getElementById('briiParsedData').style.display = 'none';

  // Parse the PDF in the background
  extractBamaSwInvoiceFields(file).then(parsed => {
    _briiContext.parsed = parsed;

    // Auto-fill invoice number from PDF
    if (parsed.invoiceNumber) {
      _briiContext.invoiceNumber = parsed.invoiceNumber;
      document.getElementById('briiInvoiceNumberDisplay').textContent = parsed.invoiceNumber;
    } else {
      document.getElementById('briiInvoiceNumberDisplay').textContent = '(not detected — enter manually)';
    }

    // Auto-fill amount
    if (parsed.totalGbp) {
      document.getElementById('briiInvoiceAmount').value = parsed.totalGbp;
      onBriiAmountChange();
    }

    // Show parsed data block
    document.getElementById('briiParsedInvDate').textContent = parsed.invoiceDate || '—';
    document.getElementById('briiParsedRef').textContent     = parsed.reference   || '—';
    document.getElementById('briiParsedVat').textContent     = parsed.isReverseCharge ? 'Domestic Reverse Charge (£0.00)' : '—';
    document.getElementById('briiParseStatus').style.display = 'none';
    document.getElementById('briiParsedData').style.display  = 'block';

    // PO vs invoice comparison
    const poValue  = _briiContext.expectedAmount;
    const invValue = parseFloat(parsed.totalGbp || '0');
    const compEl   = document.getElementById('briiComparison');
    const fmt = v  => `£${Number(v).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    if (parsed.totalGbp) {
      const match = Math.abs(invValue - poValue) <= 0.01;
      compEl.innerHTML = `
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:12px">
          <div style="color:var(--muted)">PO value sent</div>
          <div style="font-family:var(--font-mono);font-weight:600">${fmt(poValue)}</div>
          <div style="color:var(--muted)">Invoice amount</div>
          <div style="font-family:var(--font-mono);font-weight:600;color:${match ? 'var(--green)' : 'var(--yellow)'}">${fmt(invValue)}</div>
        </div>
        ${!match ? `<div style="margin-top:8px;padding:8px;background:rgba(255,193,7,.08);border:1px solid rgba(255,193,7,.3);border-radius:4px;font-size:12px;color:var(--yellow)">
          ⚠ Invoice amount differs from PO by ${fmt(Math.abs(invValue - poValue))} — verify before confirming.
        </div>` : `<div style="margin-top:6px;font-size:12px;color:var(--green)">✓ Invoice matches PO value</div>`}`;
      compEl.style.display = 'block';
    }

    checkBriiCanSubmit();
  }).catch(err => {
    document.getElementById('briiParseStatus').textContent = 'Could not parse PDF — please enter details manually.';
    checkBriiCanSubmit();
  });
}

function onBamaSwInvoiceDrop(e) {
  e.preventDefault();
  document.getElementById('briiDropZone').style.borderColor = 'var(--border)';
  const file = e.dataTransfer?.files?.[0];
  if (file) onBamaSwInvoiceFilePicked(file);
}

function onBriiAmountChange() {
  if (!_briiContext) return;
  const val      = parseFloat(document.getElementById('briiInvoiceAmount').value);
  const expected = _briiContext.expectedAmount;
  const warn     = document.getElementById('briiAmountWarning');
  if (!isNaN(val) && Math.abs(val - expected) > 0.01) {
    warn.textContent    = `⚠ Amount differs from expected ${fmtCurrency(expected)} — verify before confirming`;
    warn.style.display  = 'block';
  } else {
    warn.style.display  = 'none';
  }
  checkBriiCanSubmit();
}

function checkBriiCanSubmit() {
  if (!_briiContext) return;
  const hasFile    = !!_briiContext.file;
  const hasInvNum  = !!(_briiContext.invoiceNumber || '').trim();
  const hasAmount  = !isNaN(parseFloat(document.getElementById('briiInvoiceAmount')?.value));
  document.getElementById('briiConfirmBtn').disabled = !(hasFile && hasInvNum && hasAmount);
}

async function confirmBamaSwInvoiceReceived() {
  if (!_briiContext || !_briiContext.file) return;

  const invoiceNumber = (_briiContext.invoiceNumber || '').trim();
  const invoiceAmount = parseFloat(document.getElementById('briiInvoiceAmount').value);

  if (!invoiceNumber)                             { toast('Invoice number could not be parsed — re-upload or try a different PDF', 'error'); return; }
  if (isNaN(invoiceAmount) || invoiceAmount <= 0) { toast('Invoice amount is required', 'error'); return; }

  const { quote: q, next, file } = _briiContext;
  const btn = document.getElementById('briiConfirmBtn');
  btn.disabled = true; btn.textContent = 'Uploading…';

  try {
    const folders    = await findOrCreateBabcockFolders();
    const rcvdFolder = await getOrCreateSubfolder(folders.parent.id, 'Bama SW Received Invoices', BAMA_DRIVE_ID);
    if (!rcvdFolder) throw new Error('Could not create Bama SW Received Invoices folder');

    const safeRef  = (q.quote_ref     || 'Babcock').replace(/[/\\]/g, '_');
    const safeInv  = (invoiceNumber   || 'INV').replace(/[/\\]/g, '_');
    const fileName = `${safeInv} - ${safeRef} - Bama SW Invoice.pdf`;
    const uploaded = await uploadFileToFolder(rcvdFolder.id, fileName, await file.arrayBuffer(), 'application/pdf');

    btn.textContent = 'Saving…';
    const updated = await api.put(`/api/babcock-quotes/${q.id}`, {
      status:                           next,
      bama_sw_received_invoice_number:  invoiceNumber,
      bama_sw_received_invoice_amount:  invoiceAmount,
      bama_sw_received_invoice_pdf_url: uploaded.webUrl || null,
      bama_sw_received_invoice_pdf_id:  uploaded.id     || null
    });
    const idx = _babcockQuotes.findIndex(x => x.id === q.id);
    if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };
    toast(`${q.quote_ref} → Bama SW Invoice Received`, 'success');
    closeBamaSwReceiveInvoiceModal();
    renderBabcockTracker();
  } catch (err) {
    console.error('Receive invoice save failed:', err);
    toast('Save failed: ' + (err.message || 'unknown error'), 'error');
    btn.disabled = false; btn.textContent = 'Save & Confirm';
  }
}

// ─────────────────────────────────────────────────────────────────────
// MARK AS PAID (1j)
// ─────────────────────────────────────────────────────────────────────
// Simple confirm with a date picker. Captures bama_sw_paid_at so the
// remittance advice can reference the actual payment date.

async function handleAdvanceFromBamaSwInvoiceReceived(q, next) {
  const total     = Number(q.total_value || 0);
  const markupPct = Number(q.markup_pct  || 0);
  const original  = markupPct > 0 ? total / (1 + markupPct / 100) : total;
  const amount    = fmtCurrency(Number(q.bama_sw_received_invoice_amount || original));

  const confirmed = await showConfirmAsync(
    '✅ Mark as Paid',
    `<p style="margin:0">Record payment to Bama South West for <b>${amount}</b>?</p>
     <div style="margin-top:12px">
       <div style="font-size:11px;color:var(--muted);margin-bottom:4px;letter-spacing:.5px">PAYMENT DATE</div>
       <input type="date" id="bswPaidDateInput" value="${todayStr()}"
              style="width:100%;padding:8px;background:var(--surface-2);border:1px solid var(--border);
                     border-radius:4px;color:var(--text);font-size:13px">
     </div>`,
    { okLabel: 'Confirm Payment', cancelLabel: 'Cancel' }
  );
  if (!confirmed) return;

  const paymentDate = document.getElementById('bswPaidDateInput')?.value || todayStr();
  setLoading(true);
  try {
    const updated = await api.put(`/api/babcock-quotes/${q.id}`, {
      status:           next,
      bama_sw_paid_at:  new Date(paymentDate + 'T00:00:00').toISOString()
    });
    const idx = _babcockQuotes.findIndex(x => x.id === q.id);
    if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };
    setLoading(false);
    toast(`${q.quote_ref} → Paid to Bama SW`, 'success');
    renderBabcockTracker();
  } catch (err) {
    setLoading(false);
    toast('Update failed: ' + (err.message || 'unknown error'), 'error');
    loadBabcockTracker();
  }
}

// BAMA SW INVOICE GENERATION (1h)
// ─────────────────────────────────────────────────────────────────────
//
// At "Payment Received", the customer has paid. Now Bama Fabrication
// raises an invoice to Bama South West for the original (pre-markup)
// quote value, minus the linked project's PO spend (every non-Cancelled
// PO on linked_project_id, netted of VAT via _poNet and summed with
// sumMoney — same definition as Project Tracker's Running Cost tile;
// see handleAdvanceFromPaymentReceived).
//
// The invoice number is entered manually by the user (the SharePoint
// tracker integration has been removed — a SQL-backed alternative is TBD).
//
// Outputs:
//   - PDF in SharePoint Babcock folder
//   - Email to info@bamasw.co.uk with PDF attached
//   - BabcockQuotes row updated with bama_sw_invoice_* fields and
//     status='Remittance Sent'

// Invoice number: entered manually by the user (SharePoint tracker link
// deleted). A SQL-backed sequential invoice-number sequence is a possible
// future enhancement — tracked in ROADMAP.md, not blocking.

// Default recipient for Bama SW invoices. Cc is freely editable in the
// email composer so additional addresses can be added per-send.
const BAMA_SW_INVOICE_DEFAULT_TO = 'info@bamasw.co.uk';

// Module-level state for the open invoice modal session
let _bswContext = null;
// { quote, next, originalAmount, deductionsAmount, netTotal,
//   suggestedInvoiceNumber, trackerItem (Graph driveItem), trackerEtag }

function closeBabcockBswInvoiceModal() {
  document.getElementById('babcockBswInvoiceModal').classList.remove('active');
  _bswContext = null;
}

// ── Graph: resolve the tracker file via the share link ──
// Microsoft Graph /shares accepts a base64url-encoded URL prefixed with
// 'u!'. We use this rather than the file path so the integration keeps
// working if the file gets moved within the site.
async function resolveSharedDriveItem(shareUrl) {
  const token = await getToken();
  // Encode the URL: base64 → url-safe → prefix 'u!'
  // btoa works on ASCII, share URLs are ASCII so we're fine
  const b64 = btoa(shareUrl).replace(/=+$/, '').replace(/\//g, '_').replace(/\+/g, '-');
  const shareToken = 'u!' + b64;
  const res = await fetch(
    `https://graph.microsoft.com/v1.0/shares/${shareToken}/driveItem`,
    { headers: { 'Authorization': `Bearer ${token}` } }
  );
  if (!res.ok) {
    const errText = await res.text().catch(() => '');
    throw new Error(`Couldn't resolve shared link: ${res.status} ${errText}`);
  }
  return await res.json();
}

// ── Download the tracker XLSX as an ArrayBuffer ──
async function downloadDriveItemContent(driveItem) {
  const token = await getToken();
  const driveId = driveItem.parentReference?.driveId;
  const url = `https://graph.microsoft.com/v1.0/drives/${driveId}/items/${driveItem.id}/content`;
  const res = await fetch(url, { headers: { 'Authorization': `Bearer ${token}` } });
  if (!res.ok) throw new Error(`Couldn't download tracker: ${res.status}`);
  return await res.arrayBuffer();
}

// ── Upload arbitrary bytes back to a drive item (replace contents) ──
// If etag is provided, uses If-Match for optimistic concurrency control —
// the write fails with 412 if someone else's edit landed since we read.
async function uploadDriveItemContent(driveItem, bytes, etag) {
  const token = await getToken();
  const driveId = driveItem.parentReference?.driveId;
  const url = `https://graph.microsoft.com/v1.0/drives/${driveId}/items/${driveItem.id}/content`;
  const headers = {
    'Authorization': `Bearer ${token}`,
    'Content-Type': 'application/octet-stream'
  };
  if (etag) headers['If-Match'] = etag;
  const res = await fetch(url, { method: 'PUT', headers, body: bytes });
  if (!res.ok) {
    if (res.status === 412) {
      throw new Error('Tracker was modified by someone else — please refresh and try again');
    }
    const errText = await res.text().catch(() => '');
    throw new Error(`Tracker write failed: ${res.status} ${errText}`);
  }
  return await res.json();
}

// ── Append a tracker row using the Excel Graph API ──
// Uses Excel's calculation engine rather than raw file bytes, so it works
// even when someone has the tracker open in Excel or a browser tab.
// A workbook session is created for the operation so the usedRange read
// and the range write are coherent, then closed immediately afterwards.
async function appendRowToTrackerViaExcelApi(driveItem, sheetName, rowData) {
  const token   = await getToken();
  const driveId = driveItem.parentReference?.driveId;
  const itemId  = driveItem.id;
  const base    = `https://graph.microsoft.com/v1.0/drives/${driveId}/items/${itemId}/workbook`;
  // Sessionless — each call uses an implicit transient session that commits
  // immediately and never holds a file lock, so the tracker stays openable.
  const hdr = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };

  const enc   = encodeURIComponent(sheetName);
  const urRes = await fetch(
    `${base}/worksheets/${enc}/usedRange`,
    { headers: hdr }
  );
  if (!urRes.ok) throw new Error(`usedRange failed: ${urRes.status}`);
  const ur = await urRes.json();
  const nextExcelRow = ur.rowIndex + ur.rowCount + 1;
  const address      = `A${nextExcelRow}:M${nextExcelRow}`;

  const toSerial = d => d ? Math.round((d.getTime() - Date.UTC(1899, 11, 30)) / 86400000) : null;

  const values = [[
    rowData.invoiceNumber,
    toSerial(rowData.invoiceDate),
    toSerial(rowData.dueDate),
    rowData.customer,
    null,
    rowData.cost          ?? null,
    rowData.reverseCharge ?? null,
    null, null,
    rowData.total         ?? null,
    null,
    rowData.outstanding   ?? null,
    null
  ]];

  const pRes = await fetch(
    `${base}/worksheets/${enc}/range(address='${address}')`,
    { method: 'PATCH', headers: hdr, body: JSON.stringify({ values }) }
  );
  if (!pRes.ok) {
    const txt = await pRes.text().catch(() => '');
    throw new Error(`Excel write failed: ${pRes.status} ${txt}`);
  }
}

// ── Parse the tracker: find the next INV#### number ──
// Reads the "Sales Invoices" tab, scans column A for INV#### entries,
// returns the highest seen + 1. If no entries found returns 'INV0001'.
function nextInvoiceNumberFromTracker(arrayBuffer) {
  const wb = XLSX.read(arrayBuffer, { type: 'array' });
  const sheetName = wb.SheetNames.find(n => /sales\s*invoices?/i.test(n));
  if (!sheetName) throw new Error('Sales Invoices tab not found in tracker');
  const sheet = wb.Sheets[sheetName];
  const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });

  let highest = 0;
  for (let r = 0; r < rows.length; r++) {
    const cell = rows[r] && rows[r][0]; // column A
    if (!cell) continue;
    const m = String(cell).match(/^INV(\d+)$/i);
    if (!m) continue;
    const n = parseInt(m[1], 10);
    if (isFinite(n) && n > highest) highest = n;
  }
  const nextN = highest + 1;
  return {
    next: 'INV' + String(nextN).padStart(4, '0'),
    highestExisting: highest > 0 ? 'INV' + String(highest).padStart(4, '0') : null,
    sheetName
  };
}

// ── Append a row to the Sales Invoices tab and re-serialise the workbook ──
// We re-read the file in memory and append the new row to the same sheet,
// then write back the whole workbook. SheetJS preserves the existing
// formulas + formatting in untouched rows.
function appendRowToInvoiceTracker(arrayBuffer, rowData) {
  const wb = XLSX.read(arrayBuffer, { type: 'array', cellStyles: true });
  const sheetName = wb.SheetNames.find(n => /sales\s*invoices?/i.test(n));
  if (!sheetName) throw new Error('Sales Invoices tab not found in tracker');
  const sheet = wb.Sheets[sheetName];

  // Find next empty row in column A by scanning the existing range
  const ref = sheet['!ref'];
  const range = XLSX.utils.decode_range(ref);
  let nextRowIdx = range.e.r + 1; // append after the last existing row

  // But check if there are pre-existing empty placeholder rows below the
  // last data row (the screenshot showed rows 256, 257, 258 as blank
  // template rows with VAT formulas). If so, prefer the first one that
  // has an empty column A.
  for (let r = range.e.r; r >= 0; r--) {
    const aCell = sheet[XLSX.utils.encode_cell({ r, c: 0 })];
    if (aCell && aCell.v) {
      // Found the last data row in A; next is r+1
      nextRowIdx = r + 1;
      break;
    }
  }

  // Write each column
  const setCell = (col, value, type) => {
    const addr = XLSX.utils.encode_cell({ r: nextRowIdx, c: col });
    if (value === null || value === undefined || value === '') {
      // leave blank (don't overwrite any existing cell)
      if (!sheet[addr]) return;
      return;
    }
    sheet[addr] = { t: type || 's', v: value };
  };

  // A: Invoice No, B: Date, C: Due Date, D: Customer, E: VAT (blank for
  // reverse charge), F: Cost, G: Reverse charge (20% of cost), H: Retention,
  // I: VAT (blank for reverse charge), J: Total, K: Date Received,
  // L: Outstanding, M: Retention Due Date
  setCell(0, rowData.invoiceNumber, 's');
  if (rowData.invoiceDate)  setCell(1, rowData.invoiceDate, 'd');  // Date type
  if (rowData.dueDate)      setCell(2, rowData.dueDate, 'd');      // Date type
  setCell(3, rowData.customer, 's');
  // E (VAT yes/no) — blank for Babcock reverse charge
  setCell(5, rowData.cost, 'n');
  setCell(6, rowData.reverseCharge, 'n');
  // H (Retention) — leave blank for now
  // I (VAT collected) — blank for reverse charge
  setCell(9, rowData.total, 'n');
  // K (Date Received) — blank
  setCell(11, rowData.outstanding, 'n');
  // M (Retention Due Date) — blank

  // Extend the sheet range to include the new row
  if (nextRowIdx > range.e.r) {
    range.e.r = nextRowIdx;
    sheet['!ref'] = XLSX.utils.encode_range(range);
  }

  // Serialise back to a binary array buffer
  const out = XLSX.write(wb, { bookType: 'xlsx', type: 'array', cellStyles: true });
  return out;
}


// ── Build the Purchase Order PDF sent to Bama South West ──
async function renderBamaSwPoPDF(data) {
  await loadLogoDataUri();
  const logo = _logoDataUriCache || '';
  const JsPDFCtor = (window.jspdf && window.jspdf.jsPDF) || window.jsPDF;
  if (!JsPDFCtor) throw new Error('jsPDF not loaded');

  const doc = new JsPDFCtor({ unit: 'mm', format: 'a4' });
  const W = doc.internal.pageSize.getWidth();
  const M = 18;
  let y = 18;

  // Logo top-left
  if (logo) { try { doc.addImage(logo, 'PNG', M, y, 38, 17); } catch (e) { /* ignore */ } }

  // Title top-right
  doc.setFont('helvetica', 'bold'); doc.setFontSize(20); doc.setTextColor(0);
  doc.text('PURCHASE ORDER', W - M, y + 12, { align: 'right' });

  y += 26;
  doc.setDrawColor(208, 2, 27); doc.setLineWidth(0.6);
  doc.line(M, y, W - M, y); y += 6;

  // FROM / TO
  doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
  doc.text('FROM', M, y); doc.text('TO', W / 2 + 8, y); y += 4;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  const fromLines = ['BAMA Fabrication Ltd', '11 Enterprise Way, Enterprise Park', 'Yaxley, Peterborough, PE7 3WY', 'United Kingdom'];
  const toLines   = ['Bama South West', 'Unit 9 Gwel Avon, Business Park', 'Saltash, PL12 6TW', 'United Kingdom'];
  fromLines.forEach((l, i) => doc.text(l, M,          y + i * 4.2));
  toLines.forEach(  (l, i) => doc.text(l, W / 2 + 8, y + i * 4.2));
  y += Math.max(fromLines.length, toLines.length) * 4.2 + 4;

  // Meta box
  doc.setFillColor(245, 245, 245);
  doc.rect(M, y, W - M * 2, 22, 'F');
  const metaCols = [
    { label: 'PO NUMBER', value: data.poNumber    || '' },
    { label: 'DATE',      value: data.poDate       || '' },
    { label: 'PROJECT',   value: data.projectNumber || '' },
    { label: 'PAY BY',    value: data.dueDate       || '' }
  ];
  const colW = (W - M * 2) / metaCols.length;
  metaCols.forEach((c, i) => {
    const cx = M + i * colW + 4;
    doc.setFont('helvetica', 'bold');   doc.setFontSize(8);  doc.setTextColor(120);
    doc.text(c.label, cx, y + 7);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(11); doc.setTextColor(0);
    doc.text(String(c.value), cx, y + 14);
  });
  y += 28;

  // Line items header
  doc.setFillColor(50, 50, 50);
  doc.rect(M, y, W - M * 2, 8, 'F');
  doc.setTextColor(255); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
  doc.text('DESCRIPTION', M + 4, y + 5.5);
  doc.text('AMOUNT', W - M - 4, y + 5.5, { align: 'right' });
  y += 8; doc.setTextColor(0);

  // Description row
  const descLines = [`Works as per quote ${data.quoteRef || ''}`, data.projectName || ''].filter(Boolean);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  const rowH = Math.max(10, descLines.length * 4.5 + 4);
  doc.line(M, y + rowH, W - M, y + rowH);
  descLines.forEach((l, i) => doc.text(l, M + 4, y + 5 + i * 4.5));
  doc.text(fmtCurrency(data.netTotal), W - M - 4, y + 5, { align: 'right' });
  y += rowH + 6;

  // Totals
  const totalsX = W - M - 70; const totalsW = 70;
  const totalsRow = (label, value, bold) => {
    doc.setFont('helvetica', bold ? 'bold' : 'normal'); doc.setFontSize(bold ? 11 : 10);
    doc.text(label, totalsX, y); doc.text(value, totalsX + totalsW, y, { align: 'right' }); y += 5;
  };
  doc.setDrawColor(60, 60, 60);
  doc.line(totalsX, y, totalsX + totalsW, y); y += 5;
  totalsRow('TOTAL PAYABLE', fmtCurrency(data.netTotal), true);

  y += 8;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
  doc.text(`Please issue your invoice against Purchase Order number: ${data.poNumber || ''}`, M, y);

  return doc.output('blob');
}

// ── Build the Bama SW invoice PDF ──
// Mirrors the customer-facing quote PDF's visual style (BAMA red header,
// table, footer) but with "Invoice" branding and a single summary row
// rather than itemised lines — Bama SW just needs to know the net total.
async function renderBamaSwInvoicePDF(data) {
  await loadLogoDataUri();
  const logo = _logoDataUriCache || '';
  const JsPDFCtor = (window.jspdf && window.jspdf.jsPDF) || window.jsPDF;
  if (!JsPDFCtor) throw new Error('jsPDF not loaded');

  const doc = new JsPDFCtor({ unit: 'mm', format: 'a4' });
  const W = doc.internal.pageSize.getWidth();
  const M = 18; // left margin
  let y = 18;

  // Logo top-left
  if (logo) {
    try { doc.addImage(logo, 'PNG', M, y, 38, 17); } catch (e) { /* ignore image errors */ }
  }

  // Title top-right
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(20);
  doc.setTextColor(0);
  doc.text('REMITTANCE ADVICE', W - M, y + 12, { align: 'right' });

  y += 26;
  doc.setDrawColor(208, 2, 27);
  doc.setLineWidth(0.6);
  doc.line(M, y, W - M, y);
  y += 6;

  // Two-column header block: From (left) / To (right)
  doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
  doc.text('FROM', M, y);
  doc.text('TO', W / 2 + 8, y);
  y += 4;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  const fromLines = [
    'BAMA Fabrication Ltd',
    '11 Enterprise Way, Enterprise Park',
    'Yaxley, Peterborough, PE7 3WY',
    'United Kingdom'
  ];
  const toLines = [
    'Bama South West',
    'Unit 9 Gwel Avon, Business Park',
    'Saltash, PL12 6TW',
    'United Kingdom'
  ];
  fromLines.forEach((l, i) => doc.text(l, M, y + i * 4.2));
  toLines.forEach((l, i) => doc.text(l, W / 2 + 8, y + i * 4.2));
  y += Math.max(fromLines.length, toLines.length) * 4.2 + 4;

  // Invoice meta box. PO column appears only on the post-PO-received
  // revision (1i flow); the original invoice (1h) has 4 columns.
  doc.setFillColor(245, 245, 245);
  doc.rect(M, y, W - M * 2, 22, 'F');
  doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
  const metaCols = [
    { label: 'REFERENCE',      value: data.invoiceNumber || '' },
    { label: 'DATE',           value: data.invoiceDate || '' },
    { label: 'PROJECT',        value: data.projectNumber || '' }
  ];
  if (data.bamaSwPo) {
    metaCols.push({ label: 'BAMA SW PO', value: data.bamaSwPo });
  }
  const colW = (W - M * 2) / metaCols.length;
  metaCols.forEach((c, i) => {
    const cx = M + i * colW + 4;
    doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
    doc.setTextColor(120);
    doc.text(c.label, cx, y + 7);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(11);
    doc.setTextColor(0);
    doc.text(String(c.value), cx, y + 14);
  });
  y += 28;

  // Line items table — header (neutral dark, not red)
  doc.setFillColor(50, 50, 50);
  doc.rect(M, y, W - M * 2, 8, 'F');
  doc.setTextColor(255); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
  doc.text('DESCRIPTION', M + 4, y + 5.5);
  doc.text('AMOUNT', W - M - 4, y + 5.5, { align: 'right' });
  y += 8;
  doc.setTextColor(0);

  // Single description row
  const descLines = [
    `Project ${data.projectNumber || ''}`,
    data.projectName ? data.projectName : ''
  ].filter(Boolean);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  const rowH = Math.max(10, descLines.length * 4.5 + 4);
  doc.line(M, y + rowH, W - M, y + rowH); // bottom border
  descLines.forEach((l, i) => doc.text(l, M + 4, y + 5 + i * 4.5));
  doc.text(fmtCurrency(data.netTotal), W - M - 4, y + 5, { align: 'right' });
  y += rowH + 6;

  // Totals block (right-aligned)
  const totalsX = W - M - 70;
  const totalsW = 70;
  const totalsRow = (label, value, bold) => {
    doc.setFont('helvetica', bold ? 'bold' : 'normal');
    doc.setFontSize(bold ? 11 : 10);
    doc.text(label, totalsX, y);
    doc.text(value, totalsX + totalsW, y, { align: 'right' });
    y += 5;
  };
  totalsRow('Net total', fmtCurrency(data.netTotal));
  totalsRow('VAT (Reverse charge)', '£0.00');
  doc.setDrawColor(60, 60, 60);
  doc.line(totalsX, y, totalsX + totalsW, y); y += 5;
  totalsRow('AMOUNT PAYABLE', fmtCurrency(data.netTotal), true);

  y += 8;

  return doc.output('blob');
}

function fmtCurrency(n) {
  if (n === null || n === undefined || n === '' || !isFinite(Number(n))) return '£0.00';
  return '£' + Number(n).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Re-read the tracker (used by the modal's ⟳ Refresh button)
async function refreshBswInvoiceNumber() {
  if (!_bswContext) return;
  const inp = document.getElementById('bswInvoiceNumber');
  const status = document.getElementById('bswTrackerStatus');
  inp.disabled = false;
  inp.value = '';
  inp.placeholder = 'Enter invoice number manually';
  document.getElementById('bswConfirmBtn').disabled = false;
  setTrackerStatus('Enter the invoice number manually — tracker integration pending replacement.', 'warn');
}

function setTrackerStatus(text, kind) {
  const el = document.getElementById('bswTrackerStatus');
  if (!el) return;
  el.textContent = text;
  if (kind === 'success') {
    el.style.background = 'rgba(46,204,113,.08)';
    el.style.color = 'var(--green)';
    el.style.border = '1px solid rgba(46,204,113,.25)';
  } else if (kind === 'warn') {
    el.style.background = 'rgba(255,193,7,.08)';
    el.style.color = '#ffc945';
    el.style.border = '1px solid rgba(255,193,7,.25)';
  } else {
    el.style.background = 'rgba(255,107,0,.08)';
    el.style.color = 'var(--accent)';
    el.style.border = '1px solid rgba(255,107,0,.2)';
  }
}

// ── Handler: Paid to Bama SW → Remittance Sent (1k) ──
async function handleAdvanceFromPaidToBamaSw(q, next) {
  // Need the linked Project to derive the project number (BC####)
  if (!q.linked_project_id) {
    toast('No linked project on this row — was it converted properly?', 'error');
    return;
  }

  // Use the Bama SW invoice amount stored at the previous step
  const netTotal = Number(q.bama_sw_received_invoice_amount || 0);
  const storedInvNumber = q.bama_sw_received_invoice_number || '';

  // Payment date was captured at the previous step (Mark as Paid).
  // The remittance is dated on that day — no separate due date.
  const paymentDateIso = (String(q.bama_sw_paid_at || '').split('T')[0]) || todayStr();

  // Open modal
  _bswContext = {
    quote: q,
    next,
    netTotal,
    storedInvNumber,
    paymentDateIso,
    trackerItem: null,
    trackerEtag: null,
    trackerBuffer: null
  };

  // Populate the invoice-on-file block
  document.getElementById('bswStoredInvNumber').textContent = storedInvNumber || '(none on file)';
  document.getElementById('bswStoredInvAmount').textContent = fmtCurrency(netTotal);

  // Populate the calc block
  document.getElementById('bswOriginalAmt').textContent = fmtCurrency(netTotal);
  document.getElementById('bswNetTotal').textContent    = fmtCurrency(netTotal);

  // Show the remittance date (= payment date)
  document.getElementById('bswRemitDateDisplay').textContent = fmtDateStr(paymentDateIso);

  document.getElementById('bswConfirmBtn').disabled = !storedInvNumber;
  document.getElementById('bswConfirmBtn').textContent = 'Create Remittance Advice';

  document.getElementById('babcockBswInvoiceModal').classList.add('active');
}

// ── Confirm: generate PDF + upload SP + append tracker + open email ──
async function confirmBabcockBswInvoice() {
  if (!_bswContext) return;

  const invoiceNumber = (_bswContext.storedInvNumber || '').trim();
  const paymentDateIso = (_bswContext.paymentDateIso || '').trim();

  if (!invoiceNumber) {
    toast('No Bama SW invoice number on file — ensure the previous step was completed', 'error');
    return;
  }
  if (!paymentDateIso) {
    toast('No payment date on file — ensure the previous step was completed', 'error');
    return;
  }

  const q = _bswContext.quote;
  const next = _bswContext.next;
  const netTotal = _bswContext.netTotal;

  const btn = document.getElementById('bswConfirmBtn');
  btn.disabled = true;
  btn.textContent = 'Generating…';

  let projectNumber = '';
  try {
    // Fetch linked project for its project_number (BC####)
    const proj = (projectsData || []).find(p => p.id === q.linked_project_id);
    projectNumber = (proj && proj.project_number) || babcockProjectNumberFor(q.quote_ref || '');
  } catch (e) {
    projectNumber = babcockProjectNumberFor(q.quote_ref || '');
  }

  // 1. Generate PDF — remittance is dated on the payment date (no separate due date)
  let pdfBlob;
  try {
    pdfBlob = await renderBamaSwInvoicePDF({
      invoiceNumber,
      invoiceDate:   fmtDateStr(paymentDateIso),
      projectNumber,
      projectName:   q.quote_for_area || '',
      netTotal,
      paymentDate:   fmtDateStr(paymentDateIso)
    });
  } catch (err) {
    console.error('Bama SW invoice PDF render failed:', err);
    toast('PDF render failed: ' + (err.message || 'unknown error'), 'error');
    btn.disabled = false;
    btn.textContent = 'Create Remittance Advice';
    return;
  }

  // 2. Upload PDF to SharePoint
  let pdfUploaded = null;
  try {
    btn.textContent = 'Uploading PDF…';
    const folders = await findOrCreateBabcockFolders();
    const bswFolder = await getOrCreateSubfolder(folders.parent.id, 'Bama SW Invoices', BAMA_DRIVE_ID);
    if (!bswFolder) throw new Error('Could not create Bama SW Invoices folder');
    const fileName = `${invoiceNumber} - ${(q.quote_ref || 'Babcock').replace(/[/\\]/g, '_')} - Remittance.pdf`;
    pdfUploaded = await uploadFileToFolder(
      bswFolder.id, fileName,
      await pdfBlob.arrayBuffer(), 'application/pdf'
    );
  } catch (err) {
    console.error('Bama SW invoice upload failed:', err);
    toast('SharePoint upload failed: ' + (err.message || 'unknown error'), 'error');
    btn.disabled = false;
    btn.textContent = 'Create Remittance Advice';
    return;
  }

  // 3. Invoice tracker update removed — pending replacement solution.
  //    User must update their invoice record manually for now.
  const trackerUpdated = false;

  // 4. Open email composer with the PDF
  btn.textContent = 'Opening email…';
  let pdfBase64;
  try {
    pdfBase64 = await blobToBase64(pdfBlob);
  } catch (err) {
    toast('Failed to encode PDF for email', 'error');
    btn.disabled = false;
    btn.textContent = 'Create Remittance Advice';
    return;
  }

  // Close the invoice modal so the email composer is the only thing visible
  document.getElementById('babcockBswInvoiceModal').classList.remove('active');

  const sentCtx = {
    quote: q,
    next,
    invoiceNumber,
    paymentDateIso,
    netTotal,
    projectNumber,
    pdfUploaded
  };
  _bswContext = null;

  await openBabcockEmailModal({
    title: 'Email Bama SW Remittance',
    templateKey: 'emailBamaSwInvoice',
    tokens: {
      bama_sw_invoice_number:   invoiceNumber,
      project_number:           projectNumber,
      project_name:             q.quote_for_area || '',
      net_invoice_total:        fmtCurrency(netTotal),
      bama_sw_invoice_due_date: fmtDateStr(paymentDateIso)
    },
    to: tplGet('emailBamaSwInvoice', 'to') || 'info@bamasw.co.uk',
    cc: '',
    attachment: {
      name: `${invoiceNumber} - ${(q.quote_ref || 'Babcock').replace(/[/\\]/g, '_')} - Remittance.pdf`,
      contentType: 'application/pdf',
      contentBase64: pdfBase64
    },
    onSent: async () => {
      try {
        const updated = await api.put(`/api/babcock-quotes/${sentCtx.quote.id}`, {
          status: sentCtx.next,
          bama_sw_invoice_number:    sentCtx.invoiceNumber,
          bama_sw_invoice_pdf_url:   sentCtx.pdfUploaded?.webUrl || null,
          bama_sw_invoice_pdf_id:    sentCtx.pdfUploaded?.id || null,
          bama_sw_invoice_sent_at:   new Date().toISOString()
        });
        const idx = _babcockQuotes.findIndex(x => x.id === sentCtx.quote.id);
        if (idx !== -1) _babcockQuotes[idx] = { ..._babcockQuotes[idx], ...updated };
        renderBabcockTracker();
        const trackerMsg = sentCtx.trackerUpdated
          ? '' : ' (remember to add to SharePoint tracker)';
        toast(`Invoice ${sentCtx.invoiceNumber} sent${trackerMsg}`, 'success');
      } catch (err) {
        console.error('Status update after Bama SW invoice send failed:', err);
        toast(
          `Email sent OK but couldn\u2019t update status \u2014 please refresh and edit to set status=Remittance Sent`,
          'error'
        );
        loadBabcockTracker();
      }
    }
  });
}

