let _poList            = [];
let _poProjectsCache   = [];   // populated from /api/projects on init
let _poSuppliersCache  = [];   // populated from /api/suppliers on init
let _poCostCentres     = {};   // { "5099": "Office", "8099": "Workshop", ... } — from settings
let _poNewState        = null; // { scope, projectId, supplierId, jobNumber, lineItems[] }
let _poPendingPinUser  = null;
let _poEditingId       = null; // when set, savePoNew() updates instead of creating
let _poEditingRef      = null; // human reference (P######) of the PO being edited, for the delete prompt
let _poProjectBudgets  = {};   // { projectId: { contractValue, poSpend } } — for budget warn

// ── Page entry ──
async function initPoTrackerPage() {
  const authed = pinSessionGet();
  if (authed) {
    currentManagerUser = authed;
    const perms = getUserPermissions(currentManagerUser) || {};
    if (perms.viewPurchaseOrders || perms.editPurchaseOrders) {
      document.getElementById('screenPoSelect').style.display = 'none';
      document.getElementById('poLayout').style.display = 'flex';
      renderUnifiedSidebar();
      await loadPoSupportData();
      await loadPoTracker();
      return;
    }
  }
  renderPoEmployeeGrid();
}

function renderPoEmployeeGrid() {
  const grid = document.getElementById('poEmployeeGrid');
  if (!grid) return;
  const empList = (state.timesheetData.employees || [])
    .filter(e => e.active !== false && (e.staffType || 'workshop') === 'office');
  if (!empList.length) {
    grid.innerHTML = '<div class="empty-state" style="padding:30px"><div style="font-size:28px;margin-bottom:10px">&#128101;</div><div>No office staff set up yet.</div></div>';
    return;
  }
  grid.innerHTML = empList.map(emp => {
    const ini = (emp.name || '').split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
    const col = empColor(emp.name);
    return `
      <div class="emp-btn" onclick="selectPoEmployee('${emp.name.replace(/'/g, "\\\\'")}')">
        <div class="emp-avatar" style="width:48px;height:48px;font-size:19px;background:linear-gradient(135deg,${col},#3e1a00)">${ini}</div>
        <div class="emp-name" style="font-size:13px">${emp.name}</div>
        <div style="font-size:10px;color:var(--subtle);margin-top:3px">${emp.hasPin ? '&#128274; PIN set' : '&#128275; No PIN'}</div>
      </div>`;
  }).join('');
}

function selectPoEmployee(name) {
  const emp = (state.timesheetData.employees || []).find(e => e.name === name);
  if (!emp) return;
  if (!emp.hasPin) { toast('No PIN set for this user.', 'error'); return; }
  _poPendingPinUser = { name, empId: emp.id };
  document.getElementById('poPinUser').textContent = name;
  document.getElementById('poPinInput').value = '';
  document.getElementById('poPinError').textContent = '';
  document.getElementById('poPinModal').classList.add('active');
  setTimeout(() => document.getElementById('poPinInput').focus(), 200);
}

async function verifyPoPin() {
  if (!_poPendingPinUser) return;
  const pin = document.getElementById('poPinInput').value;
  if (!pin) return;
  try {
    const result = await api.post('/api/auth/verify-pin', { employee_id: _poPendingPinUser.empId, pin });
    if (!result || !result.valid) {
      document.getElementById('poPinError').textContent = (result && result.reason) || 'Incorrect PIN';
      document.getElementById('poPinInput').value = '';
      return;
    }
    currentManagerUser = _poPendingPinUser.name;
    pinSessionSet(currentManagerUser);
    document.getElementById('poPinModal').classList.remove('active');
    const perms = getUserPermissions(currentManagerUser) || {};
    if (!perms.viewPurchaseOrders && !perms.editPurchaseOrders) {
      toast('You don\'t have permission to access Purchase Orders.', 'error');
      currentManagerUser = null;
      pinSessionClear();
      return;
    }
    document.getElementById('screenPoSelect').style.display = 'none';
    document.getElementById('poLayout').style.display = 'flex';
    renderUnifiedSidebar();
    await loadPoSupportData();
    await loadPoTracker();
  } catch (err) {
    document.getElementById('poPinError').textContent = 'PIN verification failed';
    document.getElementById('poPinInput').value = '';
  }
}

// ── Support data: projects, suppliers, cost centres ──
async function loadPoSupportData() {
  try {
    const [projects, suppliers, ccSetting] = await Promise.all([
      api.get('/api/projects').catch(() => []),
      api.get('/api/suppliers').catch(() => []),
      api.get('/api/settings/purchase_order_cost_centres').catch(() => null)
    ]);
    _poProjectsCache  = Array.isArray(projects)  ? projects  : [];
    _poSuppliersCache = Array.isArray(suppliers) ? suppliers : [];
    let cc = {};
    if (ccSetting && ccSetting.value) {
      try {
        const parsed = typeof ccSetting.value === 'string' ? JSON.parse(ccSetting.value) : ccSetting.value;
        // Support old array format ["Office","Workshop"] and new object {"5099":"Office"}
        if (Array.isArray(parsed)) {
          parsed.forEach((label, i) => { cc[String(i + 5099)] = label; });
        } else if (parsed && typeof parsed === 'object') {
          cc = parsed;
        }
      } catch (e) { cc = {}; }
    }
    _poCostCentres = cc;
  } catch (e) {
    console.warn('PO support data load failed:', e);
  }
}

// ── Tracker load + render ──
async function loadPoTracker() {
  const tbody = document.getElementById('poTrackerTbody');
  if (tbody) tbody.innerHTML = '<tr><td colspan="8" class="empty-state" style="padding:30px"><div class="spinner"></div></td></tr>';
  try {
    _poList = await api.get('/api/purchase-orders');
    if (!Array.isArray(_poList)) _poList = [];
  } catch (e) {
    _poList = [];
    console.warn('PO list load failed:', e);
  }
  renderPoKpis();
  renderPoTracker();

  // Auto-open edit modal if navigated here from another page (e.g. supplier list)
  const pendingEditId = sessionStorage.getItem('bama_po_edit');
  if (pendingEditId) {
    sessionStorage.removeItem('bama_po_edit');
    openPoEditModal(parseInt(pendingEditId, 10));
  }
}

// Period toggle for the spend KPI tile.
// 'thisMonth' | 'lastMonth' | 'ytd'
let _poSpendPeriod = 'thisMonth';

// Return { start, end, label } for the selected period.
// All boundaries are inclusive on the left, exclusive on the right.
function _poSpendRange(period) {
  const now = new Date();
  const y = now.getUTCFullYear();
  const m = now.getUTCMonth(); // 0-indexed
  if (period === 'lastMonth') {
    const start = new Date(Date.UTC(y, m - 1, 1));
    const end   = new Date(Date.UTC(y, m, 1));
    return { start, end, label: 'Last Month' };
  }
  if (period === 'ytd') {
    const start = new Date(Date.UTC(y, 0, 1));
    const end   = new Date(Date.UTC(y + 1, 0, 1));
    return { start, end, label: 'YTD ' + y };
  }
  // thisMonth (default)
  const start = new Date(Date.UTC(y, m, 1));
  const end   = new Date(Date.UTC(y, m + 1, 1));
  return { start, end, label: 'This Month' };
}

function setPoSpendPeriod(period) {
  _poSpendPeriod = period;
  renderPoKpis();
}

function renderPoKpis() {
  const tiles = document.getElementById('poKpiTiles');
  if (!tiles) return;
  const open       = _poList.filter(p => p.status === 'Open').length;
  const received   = _poList.filter(p => p.status === 'Received').length;
  const closed     = _poList.filter(p => p.status === 'Closed').length;

  // Period-aware spend total (replaces fixed "this month" tile)
  const { start, end, label } = _poSpendRange(_poSpendPeriod);
  const spendTotal = _poList.reduce((s, p) => {
    const d = p.created_at ? new Date(p.created_at) : null;
    if (!d || isNaN(d)) return s;
    return (d >= start && d < end) ? s + (Number(p.total_value) || 0) : s;
  }, 0);

  // Variance flagged = POs with an invoice_value differing from total_value by > £0.01
  const variance = _poList.filter(p =>
    p.invoice_received_at &&
    Number(p.invoice_value || 0) > 0 &&
    Math.abs(Number(p.invoice_value) - Number(p.total_value || 0)) > 0.01
  ).length;

  // Build the period toggle: 3 segmented buttons inside the spend tile
  const seg = (token, txt) => {
    const active = _poSpendPeriod === token;
    return `<button type="button" onclick="setPoSpendPeriod('${token}')"
      style="background:${active ? 'var(--accent)' : 'transparent'};
             color:${active ? '#fff' : 'var(--muted)'};
             border:1px solid var(--border);
             padding:3px 9px;font-size:10px;font-weight:600;
             border-radius:6px;cursor:pointer;letter-spacing:.3px">${txt}</button>`;
  };
  const spendToggleTile = `
    <div class="card" style="padding:12px 14px">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:4px">
        <div style="font-size:11px;color:var(--muted);letter-spacing:.5px;text-transform:uppercase">💷 ${label}</div>
      </div>
      <div style="font-size:22px;font-weight:700;font-family:var(--font-mono);margin-top:2px">${fmtMoneyFull(spendTotal)}</div>
      <div style="display:flex;gap:4px;margin-top:8px">
        ${seg('thisMonth', 'This Mo')}${seg('lastMonth', 'Last Mo')}${seg('ytd', 'YTD')}
      </div>
    </div>`;

  tiles.innerHTML = `
    ${kpiTile('🟢 Open',       open,     'open POs awaiting delivery')}
    ${kpiTile('📦 Received',   received, 'delivered, pending invoice/payment')}
    ${kpiTile('✅ Closed',     closed,   'paid and complete')}
    ${kpiTile('⚠️ Variance',   variance, 'invoice ≠ PO total')}
    ${spendToggleTile}
  `;
}

function kpiTile(label, value, hint) {
  return `
    <div class="card" style="padding:12px 14px">
      <div style="font-size:11px;color:var(--muted);letter-spacing:.5px;text-transform:uppercase">${label}</div>
      <div style="font-size:22px;font-weight:700;font-family:var(--font-mono);margin-top:4px">${value}</div>
      <div style="font-size:10px;color:var(--subtle);margin-top:2px">${hint}</div>
    </div>`;
}

let _poSortCol = 'created_at';
let _poSortDir = 'desc';  // 'asc' | 'desc'

function sortPoTracker(col) {
  if (_poSortCol === col) {
    _poSortDir = _poSortDir === 'asc' ? 'desc' : 'asc';
  } else {
    _poSortCol = col;
    _poSortDir = col === 'created_at' || col === 'total_value' ? 'desc' : 'asc';
  }
  renderPoTracker();
}

function _poSortValue(p, col) {
  switch (col) {
    case 'reference':      return p.reference || '';
    case 'supplier_name':  return (p.supplier_name || '').toLowerCase();
    case 'scope':          return (p.project_number || p.cost_centre || '').toLowerCase();
    case 'created_at':     return p.created_at || '';
    case 'delivery_date':  return p.delivery_date || '';
    case 'total_value':    return Number(p.total_value) || 0;
    case 'status':         return p.status || '';
    default:               return '';
  }
}
function _updatePoSearchClearBtn() {
  const input = document.getElementById('poTrackerSearch');
  const btn   = document.getElementById('poTrackerSearchClear');
  if (!input || !btn) return;
  btn.style.display = input.value ? '' : 'none';
}

function clearPoTrackerSearch() {
  const input = document.getElementById('poTrackerSearch');
  if (!input) return;
  input.value = '';
  _updatePoSearchClearBtn();
  renderPoTracker();
  input.focus();
}

function renderPoTracker() {
  const tbody = document.getElementById('poTrackerTbody');
  if (!tbody) return;
  const q       = (document.getElementById('poTrackerSearch')?.value || '').toLowerCase().trim();
  const status  = document.getElementById('poTrackerStatusFilter')?.value || '';
  const scope   = document.getElementById('poTrackerScopeFilter')?.value  || '';

  const rows = _poList.filter(p => {
    if (status && p.status !== status) return false;
    if (scope === 'project'  && !p.project_id) return false;
    if (scope === 'overhead' &&  p.project_id) return false;
    if (q) {
      const hay = `${p.reference || ''} ${p.supplier_name || ''} ${p.project_number || ''} ${p.project_name || ''} ${p.cost_centre || ''} ${p.description || ''}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  }).slice().sort((a, b) => {
    const av = _poSortValue(a, _poSortCol);
    const bv = _poSortValue(b, _poSortCol);
    const cmp = typeof av === 'number'
      ? av - bv
      : String(av).localeCompare(String(bv), undefined, { numeric: true });
    return _poSortDir === 'asc' ? cmp : -cmp;
  });

  document.getElementById('poTrackerCount').textContent =
    `${rows.length} of ${_poList.length} POs`;

  // Update sort indicators on headers
  ['reference','supplier_name','scope','created_at','delivery_date','total_value','status'].forEach(col => {
    const el = document.getElementById(`poSort-${col}`);
    if (!el) return;
    el.textContent = _poSortCol === col ? (_poSortDir === 'asc' ? ' ↑' : ' ↓') : '';
  });

  if (rows.length === 0) {
    tbody.innerHTML = `<tr><td colspan="8" class="empty-state" style="padding:30px">
      <div style="font-size:28px;margin-bottom:8px">🧾</div>
      <div>No purchase orders ${q || status || scope ? 'match the current filters' : 'yet'}.</div>
    </td></tr>`;
    return;
  }

  tbody.innerHTML = rows.map(p => {
    const scope = p.project_id
      ? `<div style="display:flex;align-items:baseline;gap:5px;min-width:0">
           <span style="font-family:var(--font-mono);font-size:12px;color:var(--accent);flex-shrink:0">${escapeHtml(p.project_number || '—')}</span>
           <span style="color:var(--muted);font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHtml(p.project_name || '')}</span>
         </div>`
      : `<div style="display:flex;align-items:baseline;gap:5px;min-width:0">
           <span style="font-family:var(--font-mono);font-size:12px;flex-shrink:0">${escapeHtml(p.cost_centre || '—')}</span>
           ${_poCostCentres[p.cost_centre] ? `<span style="color:var(--muted);font-size:12px">${escapeHtml(_poCostCentres[p.cost_centre])}</span>` : ''}
         </div>`;
    const orderDate    = p.created_at    ? p.created_at.slice(0,10)    : '—';
    const deliveryDate = p.delivery_date ? p.delivery_date.slice(0,10) : '<span style="color:var(--subtle)">—</span>';
    const nett  = (p.total_value != null) ? _poNet(p) : null;
    const gross = (p.total_value != null) ? Number(p.total_value) : null;
    const moneyCell = nett != null
      ? `<div style="font-family:var(--font-mono);font-size:13px;font-weight:600">${fmtMoneyFull(nett)}</div>
         <div style="font-family:var(--font-mono);font-size:11px;color:var(--muted)">Gross ${fmtMoneyFull(gross)}</div>`
      : '<span style="color:var(--subtle)">—</span>';

    return `
      <tr style="cursor:pointer" onclick="openPoDetailModal(${p.id})"
          onmouseover="this.style.background='var(--bg-light)'" onmouseout="this.style.background=''">
        <td style="padding:10px 12px">
          <div style="font-family:var(--font-mono);font-weight:700;font-size:13px;color:var(--accent)">${escapeHtml(p.reference || '')}</div>
          <div style="font-size:11px;color:var(--muted);margin-top:2px">${orderDate}</div>
        </td>
        <td style="padding:10px 12px">
          <div style="font-size:13px;font-weight:500">${escapeHtml(p.supplier_name || '—')}</div>
          ${p.description ? `<div style="font-size:11px;color:var(--muted);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:200px">${escapeHtml(p.description)}</div>` : ''}
        </td>
        <td style="padding:10px 12px;max-width:220px">${scope}</td>
        <td style="padding:10px 12px;white-space:nowrap;font-size:12px;color:var(--muted)">${deliveryDate}</td>
        <td style="padding:10px 12px;text-align:right">${moneyCell}</td>
        <td style="padding:10px 12px">${poStatusBadge(p)}</td>
        <td style="padding:6px 8px;text-align:right">
          <button class="btn btn-ghost" style="padding:4px 8px;font-size:14px;line-height:1" title="Edit" onclick="event.stopPropagation();openPoEditModal(${p.id})">✏️</button>
        </td>
      </tr>`;
  }).join('');
}

function poStatusBadge(p) {
  const map = {
    'Open':      { bg:'#22372d', fg:'#7fdca6' },
    'Received':  { bg:'#2d2a3e', fg:'#a99dff' },
    'Invoiced':  { bg:'#2a3020', fg:'#b5d97a' },
    'Closed':    { bg:'#1f2a3a', fg:'#7fb2f0' },
    'Cancelled': { bg:'#3a2222', fg:'#ff8a8a' }
  };
  const s = map[p.status] || { bg:'#333', fg:'#bbb' };
  const invLink = p.status === 'Invoiced' && p.sharepoint_url
    ? ` <a href="${escapeHtml(p.sharepoint_url)}" target="_blank" onclick="event.stopPropagation()" title="View invoice" style="color:inherit;opacity:.7;font-size:13px;text-decoration:none;margin-left:4px">📄</a>`
    : '';
  return `<span style="background:${s.bg};color:${s.fg};font-size:11px;padding:3px 8px;border-radius:6px;font-weight:600;display:inline-flex;align-items:center">${escapeHtml(p.status || '—')}${invLink}</span>`;
}

function poNextAction(p) {
  if (p.status === 'Cancelled') return 'Cancelled';
  if (p.status === 'Closed')    return '✅ Done';
  if (!p.approved_at)           return '→ Approve & send to supplier';
  if (!p.sent_at)               return '→ Send to supplier';
  if (!p.delivery_received_at)  return '→ Confirm delivery';
  if (!p.invoice_received_at)   return '→ Attach invoice';
  if (!p.paid_at)               return '→ Mark paid';
  return '—';
}

// ── PO quote parsing — "Parse from supplier quote" in the New PO modal ────────
//
// Supports PDF (sent as base64 document to Claude API) and Excel (parsed
// client-side with SheetJS, sent as structured text to Claude API).
// On success: line items are pushed into _poNewState and the modal re-renders;
// supplier name is fuzzy-matched against _poSuppliersCache and auto-selected.
// ─────────────────────────────────────────────────────────────────────────────

function openPoQuoteFilePicker() {
  const input = document.getElementById('poQuoteFileInput');
  if (input) { input.value = ''; input.click(); }
}

// ── Paste-text path: lets the user paste a supplier email body or quote
// text directly, no file required. Routes through the same parse-with-Claude
// pipeline as the file picker, so line items + supplier fuzzy-match work
// the same way.
function openPoPasteTextModal() {
  const modal = document.getElementById('poPasteTextModal');
  if (!modal) return;
  document.getElementById('poPasteTextInput').value = '';
  document.getElementById('poPasteTextError').textContent = '';
  const btn = document.getElementById('poPasteTextParseBtn');
  if (btn) { btn.disabled = false; btn.textContent = 'Parse'; }
  modal.classList.add('active');
  setTimeout(() => document.getElementById('poPasteTextInput').focus(), 100);
}

async function parsePoPastedText() {
  const ta  = document.getElementById('poPasteTextInput');
  const err = document.getElementById('poPasteTextError');
  const btn = document.getElementById('poPasteTextParseBtn');
  err.textContent = '';
  const text = (ta.value || '').trim();
  if (text.length < 20) {
    err.textContent = 'Paste a bit more text — at least a line or two with items and prices.';
    return;
  }
  btn.disabled = true;
  btn.textContent = 'Parsing…';
  // Close the paste modal so the parse status strip in the New PO modal is visible
  document.getElementById('poPasteTextModal').classList.remove('active');
  _poQuoteParseStatus('📧 Extracting from pasted text…', 'loading');
  try {
    await _parsePoQuoteWithClaude({ type: 'text', text, filename: 'Pasted text' });
  } catch (e) {
    _poQuoteParseStatus('Parse failed — ' + (e.message || ''), 'error');
  } finally {
    btn.disabled = false;
    btn.textContent = 'Parse';
  }
}

function _poQuoteParseStatus(msg, type) {
  // type: 'loading' | 'success' | 'error' | 'hidden'
  const el = document.getElementById('poQuoteParseStatus');
  if (!el) return;
  if (type === 'hidden') { el.style.display = 'none'; return; }
  const colours = { loading: 'var(--muted)', success: 'var(--green)', error: 'var(--red)' };
  el.style.display = 'block';
  el.style.color   = colours[type] || 'var(--muted)';
  el.textContent   = msg;
}

async function handlePoQuoteFile(file) {
  if (!file) return;
  const ext = file.name.split('.').pop().toLowerCase();

  if (ext === 'pdf') {
    _poQuoteParseStatus('📄 Reading PDF…', 'loading');
    try {
      const b64 = await blobToBase64(file);
      await _parsePoQuoteWithClaude({ type: 'pdf', b64, filename: file.name });
    } catch (e) {
      _poQuoteParseStatus('Failed to read PDF: ' + e.message, 'error');
    }
  } else if (['xlsx', 'xls'].includes(ext)) {
    _poQuoteParseStatus('📊 Reading spreadsheet…', 'loading');
    try {
      const buf = await file.arrayBuffer();
      const wb  = XLSX.read(buf, { type: 'array' });
      // Use the first sheet
      const sheetName = wb.SheetNames[0];
      const sheet     = wb.Sheets[sheetName];
      // Convert to array-of-arrays then to a readable text block
      const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });
      const text = rows
        .filter(r => r.some(c => c !== ''))
        .map(r => r.map(c => String(c == null ? '' : c).trim()).join('\t'))
        .join('\n');
      await _parsePoQuoteWithClaude({ type: 'excel', text, filename: file.name });
    } catch (e) {
      _poQuoteParseStatus('Failed to read spreadsheet: ' + e.message, 'error');
    }
  } else {
    _poQuoteParseStatus('Unsupported file type — use PDF or Excel (.xlsx/.xls)', 'error');
  }
}

async function _parsePoQuoteWithClaude({ type, b64, text, filename }) {
  _poQuoteParseStatus('🤖 Extracting line items…', 'loading');

  const systemPrompt = `You extract purchase order data from supplier quotes.

Return ONLY a JSON object with this shape (use null for anything not found):
{
  "supplier_name": string | null,
  "quote_ref":     string | null,
  "line_items": [
    {
      "description": string,
      "qty":         number | null,
      "unit_price":  number | null,
      "line_total":  number | null
    }
  ]
}

Rules:
- line_items must only contain actual goods/services being purchased — exclude header rows, totals rows, VAT rows, delivery rows, and blank rows
- description: the item name/description as written on the quote
- qty: numeric quantity only — null if not present or not a number
- unit_price: nett unit price in GBP — null if not present
- line_total: nett line total in GBP — null if not present
- All monetary values must be nett (ex-VAT) and numeric only — no £ symbols, no commas
- supplier_name: the company issuing this quote (not the recipient)
- quote_ref: the supplier's own reference/quote number if visible
- Return only the JSON object — no explanation, no markdown fences`;

  const userContent = type === 'pdf'
    ? [
        { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } },
        { type: 'text', text: 'Extract the purchase order data from this supplier quote.' }
      ]
    : `File: ${filename}\n\n${text}`;

  try {
    const data  = await callClaude({
      model: 'claude-sonnet-4-6',
      max_tokens: 2000,
      system: systemPrompt,
      messages: [{ role: 'user', content: userContent }]
    });

    const raw   = (data.content || []).find(b => b.type === 'text')?.text || '';
    const clean = raw.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(clean);

    _applyParsedPoQuote(parsed);
  } catch (e) {
    _poQuoteParseStatus('Parse failed — ' + e.message, 'error');
    console.error('PO quote parse error:', e);
  }
}

function _applyParsedPoQuote(parsed) {
  const lines = Array.isArray(parsed.line_items) ? parsed.line_items : [];

  if (!lines.length) {
    _poQuoteParseStatus('No line items found — check the file and try again, or add lines manually.', 'error');
    return;
  }

  // ── Populate line items ──
  _poNewState.lineItems = lines.map(li => ({
    description: li.description || '',
    quantity:    li.qty != null    ? String(li.qty)        : '',
    unit_price:  li.unit_price != null ? String(li.unit_price) : '',
    line_total:  li.line_total != null ? String(Number(li.line_total).toFixed(2)) : ''
  }));
  renderPoLineRows();
  recalcPoTotal();

  // ── Fuzzy-match supplier ──
  let supplierNote = '';
  if (parsed.supplier_name) {
    const match = _fuzzyMatchPoSupplier(parsed.supplier_name);
    if (match) {
      selectPoSupplier(match.id);
      supplierNote = ` · Supplier matched: ${match.supplier_name}`;
    } else {
      // Pre-fill the search box so they can see what was extracted
      const search = document.getElementById('poNewSupplierSearch');
      if (search) search.value = parsed.supplier_name;
      supplierNote = ` · Supplier "${parsed.supplier_name}" not found — select manually`;
    }
  }

  const refNote = parsed.quote_ref ? ` · Ref: ${parsed.quote_ref}` : '';
  _poQuoteParseStatus(
    `✓ ${lines.length} line${lines.length > 1 ? 's' : ''} imported${refNote}${supplierNote} — review before saving`,
    'success'
  );
}

function _fuzzyMatchPoSupplier(name) {
  if (!name || !(_poSuppliersCache || []).length) return null;
  const norm = s => String(s).toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
  const target = norm(name);

  let best = null, bestScore = 0;
  for (const s of _poSuppliersCache) {
    const candidate = norm(s.supplier_name || '');
    if (!candidate) continue;
    // Score: exact match = 1.0; one contains the other = 0.8; shared words = fraction
    let score = 0;
    if (candidate === target) {
      score = 1.0;
    } else if (candidate.includes(target) || target.includes(candidate)) {
      score = 0.8;
    } else {
      const tw = new Set(target.split(' '));
      const cw = candidate.split(' ');
      const shared = cw.filter(w => w.length > 2 && tw.has(w)).length;
      score = shared / Math.max(tw.size, cw.length);
    }
    if (score > bestScore) { bestScore = score; best = s; }
  }
  // Require at least 0.5 to avoid false positives
  return bestScore >= 0.5 ? best : null;
}

// ── New PO modal ──
function openPoNewModal() {
  const perms = getUserPermissions(currentManagerUser) || {};
  if (!perms.editPurchaseOrders) {
    toast('You don\'t have permission to raise POs.', 'error');
    return;
  }
  _poEditingId = null;
  _poNewState = { scope: null, projectId: null, supplierId: null, jobNumber: '', lineItems: [] };
  document.querySelector('#poNewModal .modal-title').textContent = '📝 New Purchase Order';
  document.getElementById('poNewRef').value = '';
  document.getElementById('poNewDate').value = new Date().toISOString().slice(0, 10);
  document.getElementById('poNewProjectSearch').value = '';
  document.getElementById('poNewProjectDropdown').innerHTML = '';
  document.getElementById('poNewProjectSelected').textContent = '';
  document.getElementById('poNewSupplierSearch').value = '';
  document.getElementById('poNewSupplierDropdown').innerHTML = '';
  document.getElementById('poNewSupplierSelected').textContent = '';
  document.getElementById('poNewDeliveryDate').value = '';
  document.getElementById('poNewDeliveryAddress').value = '11 Enterprise Way, Enterprise Park, Peterborough, PE7 3WY';
  document.getElementById('poNewDeliveryCharge').value = '';
  document.getElementById('poNewCollectionCharge').value = '';
  document.getElementById('poNewVatRate').value = '20';
  document.getElementById('poNewNett').value = '';
  document.getElementById('poNewVatAmount').value = '';
  document.getElementById('poNewTotal').value = '';
  document.getElementById('poNewDescription').value = '';
  document.getElementById('poNewJobNumber').value = '';
  document.getElementById('poNewLineItems').innerHTML = '';
  document.getElementById('poNewError').textContent = '';
  document.getElementById('poNewBudgetWarn').textContent = '';
  _poQuoteParseStatus('', 'hidden');
  document.getElementById('poNewSaveBtn').textContent = 'Create PO';
  document.getElementById('poDeleteBtn').style.display = 'none';

  // Populate cost-centre dropdown
  const ccSel = document.getElementById('poNewCostCentre');
  ccSel.innerHTML = '<option value="">—</option>' +
    Object.entries(_poCostCentres).map(([code, label]) =>
      `<option value="${escapeHtml(code)}">${escapeHtml(code)} — ${escapeHtml(label)}</option>`
    ).join('');

  setPoScope('project'); // default

  // Pre-fetch next reference
  api.get('/api/purchase-orders-next-reference').then(r => {
    document.getElementById('poNewRef').value = (r && r.reference) || '';
  }).catch(() => {});

  document.getElementById('poNewModal').classList.add('active');
}

function closePoNewModal() {
  document.getElementById('poNewModal').classList.remove('active');
  _poEditingId = null;
  _poNewState = null;
}

function setPoScope(scope) {
  if (!_poNewState) return;
  _poNewState.scope = scope;
  document.getElementById('poNewProjectWrap').style.display  = scope === 'project'  ? '' : 'none';
  document.getElementById('poNewOverheadWrap').style.display = scope === 'overhead' ? '' : 'none';
  // Visual toggle on buttons
  const projBtn = document.getElementById('poScopeProjectBtn');
  const ovrBtn  = document.getElementById('poScopeOverheadBtn');
  if (scope === 'project')  { projBtn.classList.add('btn-primary'); projBtn.classList.remove('btn-ghost');
                              ovrBtn.classList.remove('btn-primary'); ovrBtn.classList.add('btn-ghost'); }
  else                       { ovrBtn.classList.add('btn-primary');  ovrBtn.classList.remove('btn-ghost');
                              projBtn.classList.remove('btn-primary'); projBtn.classList.add('btn-ghost'); }
  // Clear the *other* scope's selection so we can't get into a bad state
  if (scope === 'project') {
    document.getElementById('poNewCostCentre').value = '';
  } else {
    _poNewState.projectId = null;
    _poNewState.jobNumber = '';
    document.getElementById('poNewProjectSearch').value = '';
    document.getElementById('poNewProjectSelected').textContent = '';
    document.getElementById('poNewJobNumber').value = '';
  }
  updatePoBudgetWarn();
}

function filterPoProjects(q) {
  const dd = document.getElementById('poNewProjectDropdown');
  if (!q || q.length < 1) { dd.innerHTML = ''; return; }
  const qLo = q.toLowerCase();
  const matches = _poProjectsCache
    .filter(p => `${p.project_number || ''} ${p.project_name || ''}`.toLowerCase().includes(qLo))
    .filter(p => p.status !== 'Archived' && p.status !== 'Cancelled')
    .slice(0, 20);
  if (matches.length === 0) {
    dd.innerHTML = '<div style="padding:8px;color:var(--subtle);font-size:12px">No projects match</div>';
    return;
  }
  dd.innerHTML = matches.map(p => `
    <div style="padding:8px 10px;cursor:pointer;border-bottom:1px solid var(--border);background:var(--bg-darker)"
         onmouseover="this.style.background='var(--bg-darker-2,#22252b)'"
         onmouseout="this.style.background='var(--bg-darker)'"
         onclick="selectPoProject(${p.id})">
      <div style="font-family:var(--font-mono);font-weight:600">${escapeHtml(p.project_number || '')}</div>
      <div style="font-size:12px;color:var(--muted)">${escapeHtml(p.project_name || '')}</div>
    </div>`).join('');
}

function selectPoProject(projectId) {
  const p = _poProjectsCache.find(x => x.id === projectId);
  if (!p) return;
  _poNewState.projectId = p.id;
  _poNewState.jobNumber = p.project_number || '';
  document.getElementById('poNewProjectSearch').value = `${p.project_number} — ${p.project_name || ''}`;
  document.getElementById('poNewProjectDropdown').innerHTML = '';
  document.getElementById('poNewProjectSelected').textContent =
    `Selected: ${p.project_number}${p.project_name ? ' · ' + p.project_name : ''}`;
  document.getElementById('poNewJobNumber').value = p.project_number || '';
  updatePoBudgetWarn();
}

function filterPoSuppliers(q) {
  const dd = document.getElementById('poNewSupplierDropdown');
  if (!q || q.length < 1) { dd.innerHTML = ''; return; }
  // Ltd/Limited-insensitive normalised matching (same principle as the
  // Clients matcher) — "outside structure" finds "Outside Structure
  // Solutions Ltd", punctuation and suffixes ignored.
  const norm = s => String(s || '').toLowerCase()
    .replace(/\b(ltd|limited|plc|llp|uk)\b/g, '').replace(/[^a-z0-9 ]/g, '')
    .replace(/\s+/g, ' ').trim();
  const qN = norm(q);
  const matches = _poSuppliersCache
    .filter(s => {
      const hay = norm(`${s.supplier_name || ''} ${s.contact_name || ''}`);
      const sN  = norm(s.supplier_name);
      return hay.includes(qN) || (!!sN && qN.includes(sN));
    })
    .slice(0, 12);

  const rows = matches.map(s => `
    <div style="padding:8px 10px;cursor:pointer;border-bottom:1px solid var(--border);background:var(--bg-darker)"
         onmouseover="this.style.background='var(--surface)'"
         onmouseout="this.style.background='var(--bg-darker)'"
         onmousedown="event.preventDefault(); selectPoSupplier(${s.id})">
      <div style="font-weight:600">${escapeHtml(s.supplier_name || '')}</div>
      <div style="font-size:12px;color:var(--muted)">${escapeHtml((s.address_line1 || '') + (s.city ? ' · ' + s.city : ''))}</div>
    </div>`);

  // Always offer creating what was typed — no more dead-end "No suppliers match".
  rows.push(`
    <div style="padding:8px 10px;cursor:pointer;background:var(--bg-darker);color:var(--accent);font-weight:600"
         onmouseover="this.style.background='var(--surface)'"
         onmouseout="this.style.background='var(--bg-darker)'"
         onmousedown="event.preventDefault(); showPoNewSupplier()">
      ＋ Add "${escapeHtml(q)}" as a new supplier
    </div>`);

  dd.innerHTML = `<div style="position:absolute;top:0;left:0;right:0;z-index:30;border:1px solid var(--border);
       border-radius:8px;overflow:hidden;max-height:260px;overflow-y:auto;box-shadow:0 8px 24px rgba(0,0,0,.35)">
    ${matches.length === 0 ? '<div style="padding:8px 10px;color:var(--subtle);font-size:12px;background:var(--bg-darker)">No supplier with a similar name — add it below</div>' : ''}
    ${rows.join('')}
  </div>`;
}

// ── Inline new-supplier flow inside the New PO modal ──────────────────────
function showPoNewSupplier() {
  const q = (document.getElementById('poNewSupplierSearch').value || '').trim();
  document.getElementById('poNewSupplierDropdown').innerHTML = '';
  _poNewState.supplierId = null;
  document.getElementById('poNewSupplierSelected').textContent = '';
  const form = document.getElementById('poNewSupplierForm');
  if (!form) { toast('Add-supplier form not available on this page.', 'error'); return; }
  form.style.display = 'block';
  const nameEl = document.getElementById('poNsName');
  if (q) nameEl.value = q;
  nameEl.focus();
}

function cancelPoNewSupplier() {
  const form = document.getElementById('poNewSupplierForm');
  if (form) form.style.display = 'none';
  ['poNsName','poNsContact','poNsPhone','poNsEmail','poNsAddr1','poNsAddr2','poNsCity','poNsCounty','poNsPostcode'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
}

async function savePoNewSupplier() {
  const name = (document.getElementById('poNsName').value || '').trim();
  if (!name) { toast('Supplier name is required.', 'error'); return; }
  // Guard against near-duplicates one last time (exact normalised match)
  const norm = s => String(s || '').toLowerCase()
    .replace(/\b(ltd|limited|plc|llp|uk)\b/g, '').replace(/[^a-z0-9 ]/g, '')
    .replace(/\s+/g, ' ').trim();
  const dup = (_poSuppliersCache || []).find(s => norm(s.supplier_name) === norm(name));
  if (dup) {
    const useExisting = await bamaConfirm({
      title: 'Similar supplier exists',
      body: `<strong style="color:var(--text)">"${escapeHtml(dup.supplier_name)}"</strong> is already in the database.<br><br>Use the existing supplier instead of creating a duplicate?`,
      confirmText: 'Use existing', cancelText: 'Create new anyway', icon: '🔍', tone: 'primary'
    });
    if (useExisting) {
      cancelPoNewSupplier();
      selectPoSupplier(dup.id);
      return;
    }
  }
  const btn = document.getElementById('poNsSaveBtn');
  btn.disabled = true;
  try {
    const val = id => (document.getElementById(id)?.value || '').trim() || null;
    const created = await api.post('/api/suppliers', {
      supplier_name: name,
      contact_name:  val('poNsContact'),
      telephone:     val('poNsPhone'),
      email:         val('poNsEmail'),
      address_line1: val('poNsAddr1'),
      address_line2: val('poNsAddr2'),
      city:          val('poNsCity'),
      county:        val('poNsCounty'),
      postcode:      val('poNsPostcode')
    });
    if (!created?.address_line1 && !created?.postcode) {
      toast('⚠ Supplier saved with no address — the PO will print without one.', 'warning');
    }
    if (!created || !created.id) throw new Error('No supplier returned');
    _poSuppliersCache.push(created);
    cancelPoNewSupplier();
    selectPoSupplier(created.id);
    toast(`Supplier "${created.supplier_name}" saved.`, 'success');
  } catch (e) {
    toast('Could not save supplier: ' + e.message, 'error');
  } finally {
    btn.disabled = false;
  }
}

function selectPoSupplier(supplierId) {
  const s = _poSuppliersCache.find(x => x.id === supplierId);
  if (!s) return;
  _poNewState.supplierId = s.id;
  document.getElementById('poNewSupplierSearch').value = s.supplier_name || '';
  document.getElementById('poNewSupplierDropdown').innerHTML = '';
  document.getElementById('poNewSupplierSelected').textContent =
    `Selected: ${s.supplier_name}${s.contact_name ? ' · ' + s.contact_name : ''}`;
}

// ── Line items in the modal ──
function addPoLineRow(prefill) {
  const row = prefill || { description: '', quantity: '', unit_price: '', line_total: '' };
  _poNewState.lineItems.push(row);
  renderPoLineRows();
}

function removePoLineRow(idx) {
  _poNewState.lineItems.splice(idx, 1);
  renderPoLineRows();
  recalcPoTotal();
}

function renderPoLineRows() {
  const wrap = document.getElementById('poNewLineItems');
  wrap.innerHTML = _poNewState.lineItems.map((li, i) => `
    <div style="display:grid;grid-template-columns:1.5fr 80px 90px 90px 28px;gap:6px;align-items:center">
      <input type="text" class="field-input" placeholder="Description" value="${escapeHtml(li.description || '')}"
             oninput="_poNewState.lineItems[${i}].description=this.value">
      <input type="number" step="0.001" class="field-input" placeholder="Qty" value="${escapeHtml(li.quantity || '')}"
             oninput="_poNewState.lineItems[${i}].quantity=this.value;recalcPoLine(${i})">
      <input type="number" step="0.0001" class="field-input" placeholder="£ rate" value="${escapeHtml(li.unit_price || '')}"
             oninput="_poNewState.lineItems[${i}].unit_price=this.value;recalcPoLine(${i})">
      <input type="number" step="0.01" class="field-input" placeholder="£ total"
             value="${escapeHtml(li.line_total || '')}"
             oninput="_poNewState.lineItems[${i}].line_total=this.value;recalcPoTotal()"
             style="font-family:var(--font-mono);font-weight:600">
      <button type="button" class="btn btn-ghost" style="padding:2px 6px;font-size:14px;color:var(--red)"
              onclick="removePoLineRow(${i})">×</button>
    </div>
  `).join('');
}

function recalcPoLine(i) {
  const li = _poNewState.lineItems[i];
  if (!li) return;
  const q = Number(li.quantity);
  const u = Number(li.unit_price);
  if (!isNaN(q) && !isNaN(u)) {
    li.line_total = (q * u).toFixed(2);
    // Update only the line_total input for this row — avoids full re-render which kills focus
    const rows = document.querySelectorAll('#poNewLineItems > div');
    if (rows[i]) {
      const totalInput = rows[i].querySelectorAll('input[type="number"]')[2];
      if (totalInput) totalInput.value = li.line_total;
    }
  }
  recalcPoTotal();
}

function recalcPoTotal() {
  // Sum line item totals
  let lineSum = 0;
  for (const li of (_poNewState?.lineItems || [])) {
    const lt = Number(li.line_total);
    if (!isNaN(lt)) lineSum += lt;
  }
  // Delivery + collection are Nett (VAT-able). HMRC: when goods are
  // standard-rated, delivery follows the same rate. We add to Nett, then
  // apply VAT on the whole subtotal.
  const dc = Number(document.getElementById('poNewDeliveryCharge').value) || 0;
  const cc = Number(document.getElementById('poNewCollectionCharge').value) || 0;
  const nett = lineSum + dc + cc;
  const rateEl = document.getElementById('poNewVatRate');
  const vr = rateEl && rateEl.value !== '' ? Number(rateEl.value) : 20;
  const vat   = Math.round(nett * vr) / 100;          // 2dp
  const gross = Math.round((nett + vat) * 100) / 100; // 2dp

  document.getElementById('poNewNett').value      = nett.toFixed(2);
  document.getElementById('poNewVatAmount').value = vat.toFixed(2);
  document.getElementById('poNewTotal').value     = gross.toFixed(2);
  updatePoBudgetWarn();
}

// ── Budget soft-warn ──
function updatePoBudgetWarn() {
  const el = document.getElementById('poNewBudgetWarn');
  if (!el) return;
  el.textContent = '';
  if (!_poNewState || _poNewState.scope !== 'project' || !_poNewState.projectId) return;
  const proj = _poProjectsCache.find(p => p.id === _poNewState.projectId);
  if (!proj || !proj.quote_value) return;
  const existing = _poList
    .filter(p => p.project_id === _poNewState.projectId && p.status !== 'Cancelled' && p.id !== _poEditingId)
    .reduce((s, p) => s + (Number(p.total_value) || 0), 0);
  const thisTotal = Number(document.getElementById('poNewTotal').value) || 0;
  const combined = existing + thisTotal;
  if (combined > Number(proj.quote_value)) {
    el.textContent = `⚠️ Existing POs (${fmtMoneyFull(existing)}) + this PO (${fmtMoneyFull(thisTotal)}) = ${fmtMoneyFull(combined)} — exceeds project quote value of ${fmtMoneyFull(proj.quote_value)}. Soft warning only — you can still raise it.`;
  }
}

// ── Save ──
async function savePoNew() {
  const errEl = document.getElementById('poNewError');
  errEl.textContent = '';
  if (!_poNewState) return;

  // Validate
  if (!_poNewState.scope) { errEl.textContent = 'Pick a scope (Project or Overhead).'; return; }
  if (_poNewState.scope === 'project'  && !_poNewState.projectId) { errEl.textContent = 'Select a project.';      return; }
  if (_poNewState.scope === 'overhead' && !document.getElementById('poNewCostCentre').value) {
    errEl.textContent = 'Select a cost centre.'; return;
  }
  if (!_poNewState.supplierId) { errEl.textContent = 'Select a supplier.'; return; }

  const body = {
    supplier_id:        _poNewState.supplierId,
    description:        document.getElementById('poNewDescription').value || null,
    job_number:         document.getElementById('poNewJobNumber').value || null,
    delivery_date:      document.getElementById('poNewDeliveryDate').value || null,
    delivery_address:   document.getElementById('poNewDeliveryAddress').value || null,
    delivery_charge:    document.getElementById('poNewDeliveryCharge').value || null,
    collection_charge:  document.getElementById('poNewCollectionCharge').value || null,
    vat_rate:           document.getElementById('poNewVatRate').value || null,
    vat_amount:         document.getElementById('poNewVatAmount').value || null,
    total_value:        document.getElementById('poNewTotal').value || null,
    created_by:         currentManagerUser || null,
    line_items:         (_poNewState.lineItems || []).filter(li => li.description || li.quantity || li.unit_price || li.line_total)
  };
  if (_poNewState.scope === 'project') {
    body.project_id  = _poNewState.projectId;
  } else {
    body.cost_centre = document.getElementById('poNewCostCentre').value;
  }

  const btn = document.getElementById('poNewSaveBtn');
  btn.disabled = true;
  btn.textContent = _poEditingId ? 'Saving…' : 'Creating…';
  try {
    if (_poEditingId) {
      await api.put(`/api/purchase-orders/${_poEditingId}`, body);
      toast('PO updated ✓', 'success');
    } else {
      await api.post('/api/purchase-orders', body);
      toast('PO created ✓', 'success');
    }
    closePoNewModal();
    await loadPoTracker();
  } catch (e) {
    console.error('PO save failed:', e);
    errEl.textContent = (e && e.message) ? e.message : 'Save failed';
  } finally {
    btn.disabled = false;
    btn.textContent = _poEditingId ? 'Save Changes' : 'Create PO';
  }
}

// Hard-delete the PO currently open in the edit modal. Gated by the same
// editPurchaseOrders permission as edit. Cascades POLineItems + POAttachments
// (FK ON DELETE CASCADE); nothing else in the schema references po_id.
async function deletePoFromEdit() {
  if (!_poEditingId) return;
  const perms = getUserPermissions(currentManagerUser) || {};
  if (!perms.editPurchaseOrders) { toast('You don\'t have permission to delete POs.', 'error'); return; }

  const ref = _poEditingRef || `#${_poEditingId}`;
  const confirmed = await showConfirmAsync(
    `Delete ${escapeHtml(ref)}?`,
    `<div style="margin-bottom:14px">This permanently removes purchase order <b>${escapeHtml(ref)}</b>, along with its line items and any attached delivery notes / supplier invoices.</div>
     <div style="font-size:12px;color:var(--subtle)">This can't be undone. If the PO was already sent to the supplier, consider editing its status to <b>Cancelled</b> instead to keep the audit trail.</div>`,
    { okLabel: 'Delete PO', cancelLabel: 'Cancel', danger: true }
  );
  if (!confirmed) return;

  const btn = document.getElementById('poDeleteBtn');
  const errEl = document.getElementById('poNewError');
  errEl.textContent = '';
  btn.disabled = true;
  btn.textContent = 'Deleting…';
  try {
    await api.delete(`/api/purchase-orders/${_poEditingId}`);
    toast(`${ref} deleted ✓`, 'success');
    closePoNewModal();
    await loadPoTracker();
  } catch (e) {
    console.error('PO delete failed:', e);
    errEl.textContent = (e && e.message) ? e.message : 'Delete failed';
  } finally {
    btn.disabled = false;
    btn.textContent = 'Delete PO';
  }
}

// ── Detail modal ──
//
// The #poDetailModal markup lives in po-tracker.html. Other pages
// (project-tracker.html) also need to open this modal — e.g. when the
// PO list on a project detail is clicked. To avoid duplicating the
// markup across HTML files and keeping them in sync, this helper
// lazily injects the modal into <body> the first time it's needed
// on a page that doesn't already have it.
function _ensurePoDetailModal() {
  if (document.getElementById('poDetailModal')) return;
  const wrap = document.createElement('div');
  wrap.innerHTML = `
    <div class="modal-overlay" id="poDetailModal">
      <div class="modal" style="max-width:820px;width:95vw;max-height:90vh;overflow-y:auto">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px">
          <div>
            <div class="modal-title" id="poDetailRef" style="margin-bottom:4px">—</div>
            <div id="poDetailSub" style="color:var(--muted);font-size:13px">—</div>
          </div>
          <div id="poDetailStatusBadge" style="font-size:11px;padding:4px 10px;border-radius:6px;font-weight:600">—</div>
        </div>
        <div id="poDetailBody"></div>
        <div class="modal-actions">
          <button class="btn btn-ghost" onclick="document.getElementById('poDetailModal').classList.remove('active')">Close</button>
          <button class="btn btn-primary" id="poDetailEditBtn" onclick="editPoFromDetail()">✏️ Edit</button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(wrap.firstElementChild);
}

async function openPoDetailModal(poId) {
  _ensurePoDetailModal();
  document.getElementById('poDetailRef').textContent = '—';
  document.getElementById('poDetailSub').textContent = 'Loading…';
  document.getElementById('poDetailBody').innerHTML  = '<div style="padding:20px;text-align:center"><div class="spinner"></div></div>';
  document.getElementById('poDetailStatusBadge').outerHTML = '<div id="poDetailStatusBadge" style="font-size:11px;padding:4px 10px;border-radius:6px;font-weight:600">—</div>';
  document.getElementById('poDetailModal').classList.add('active');
  try {
    const p = await api.get(`/api/purchase-orders/${poId}`);
    renderPoDetail(p);
  } catch (e) {
    document.getElementById('poDetailBody').innerHTML = `<div style="color:var(--red);padding:20px">Failed to load PO: ${escapeHtml(e.message || '')}</div>`;
  }
}

function renderPoDetail(p) {
  document.getElementById('poDetailRef').textContent = p.reference || '';

  // Sub-header: project/overhead + supplier
  const ccLabel = _poCostCentres[p.cost_centre] || '';
  const scopeLine = p.project_id
    ? `${p.project_number} — ${p.project_name || ''}`
    : `${p.cost_centre || ''}${ccLabel ? ' — ' + ccLabel : ''}`;
  document.getElementById('poDetailSub').textContent =
    [scopeLine, p.supplier_name].filter(Boolean).join('  ·  ');

  const badge = document.getElementById('poDetailStatusBadge');
  if (badge) badge.outerHTML = poStatusBadge(p).replace('<span', '<span id="poDetailStatusBadge"');

  // ── Line items table ──
  const nett  = Math.max(0, Number(p.total_value || 0) - Number(p.vat_amount || 0));
  const gross = Number(p.total_value || 0);
  const hasLines = p.line_items && p.line_items.length > 0;
  const lineItemsHtml = hasLines
    ? `<table style="width:100%;border-collapse:collapse;font-size:12px">
        <thead>
          <tr style="border-bottom:2px solid var(--border);color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.4px">
            <th style="text-align:left;padding:6px 8px;font-weight:600">Description</th>
            <th style="text-align:right;padding:6px 8px;font-weight:600;width:55px">Qty</th>
            <th style="text-align:right;padding:6px 8px;font-weight:600;width:90px">Unit</th>
            <th style="text-align:right;padding:6px 8px;font-weight:600;width:95px">Total</th>
          </tr>
        </thead>
        <tbody>
          ${p.line_items.map((li, i) => `
            <tr style="border-bottom:1px solid var(--border);background:${i%2===1?'var(--bg-darker)':''}">
              <td style="padding:7px 8px">${escapeHtml(li.description || '')}</td>
              <td style="padding:7px 8px;text-align:right;font-family:var(--font-mono)">${li.quantity != null ? Number(li.quantity) : ''}</td>
              <td style="padding:7px 8px;text-align:right;font-family:var(--font-mono)">${li.unit_price != null ? fmtMoneyFull(li.unit_price) : ''}</td>
              <td style="padding:7px 8px;text-align:right;font-family:var(--font-mono);font-weight:600">${li.line_total != null ? fmtMoneyFull(li.line_total) : ''}</td>
            </tr>`).join('')}
        </tbody>
      </table>`
    : `<div style="color:var(--subtle);font-size:12px;padding:8px 0">No line items — single-value PO.</div>`;

  // ── Project link info ──
  const projInfo = p.project_id
    ? `<span style="font-family:var(--font-mono);color:var(--accent)">${escapeHtml(p.project_number || '')}</span> <span style="color:var(--muted)">— ${escapeHtml(p.project_name || '')}</span>`
    : `<span style="color:var(--subtle)">Unlinked overhead PO</span>`;

  // ── Workflow step helper ──
  const wfRow = (done, doneText, pendingText, btnLabel, btnStep, poId, isLast) => `
    <div style="display:flex;align-items:center;gap:10px;padding:8px 0;${isLast?'':'border-bottom:1px solid var(--border)'}">
      <div style="width:20px;text-align:center;flex-shrink:0">${done ? '✅' : '⬜'}</div>
      <div style="flex:1;font-size:13px;color:${done?'var(--text)':'var(--muted)'}">${done ? doneText : pendingText}</div>
      ${!done && btnStep ? `<button class="btn btn-ghost" style="font-size:11px;padding:4px 12px;flex-shrink:0" onclick="poMarkStep(${poId},'${btnStep}')">${btnLabel}</button>` : ''}
      ${done && btnStep === 'paid' ? `<button class="btn btn-ghost" style="font-size:11px;padding:4px 12px;flex-shrink:0;color:var(--subtle)" onclick="poMarkStep(${poId},'unpaid')">Undo</button>` : ''}
    </div>`;

  document.getElementById('poDetailBody').innerHTML = `

    <!-- ── Row 1: Key info grid ── -->
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--border);border-radius:8px;overflow:hidden;margin-bottom:16px">
      <div style="background:var(--bg-dark);padding:10px 14px">
        <div style="font-size:10px;color:var(--muted);letter-spacing:.6px;text-transform:uppercase;margin-bottom:3px">Supplier</div>
        <div style="font-size:13px;font-weight:600">${escapeHtml(p.supplier_name || '—')}</div>
      </div>
      <div style="background:var(--bg-dark);padding:10px 14px">
        <div style="font-size:10px;color:var(--muted);letter-spacing:.6px;text-transform:uppercase;margin-bottom:3px">Order Date</div>
        <div style="font-size:13px">${p.created_at ? p.created_at.slice(0,10) : '—'}</div>
      </div>
      <div style="background:var(--bg-dark);padding:10px 14px">
        <div style="font-size:10px;color:var(--muted);letter-spacing:.6px;text-transform:uppercase;margin-bottom:3px">Delivery Date</div>
        <div style="font-size:13px">${p.delivery_date ? p.delivery_date.slice(0,10) : '—'}</div>
      </div>
      <div style="background:var(--bg-dark);padding:10px 14px">
        <div style="font-size:10px;color:var(--muted);letter-spacing:.6px;text-transform:uppercase;margin-bottom:3px">Job Number</div>
        <div style="font-size:13px;font-family:var(--font-mono)">${escapeHtml(p.job_number || '—')}</div>
      </div>
      <div style="background:var(--bg-dark);padding:10px 14px">
        <div style="font-size:10px;color:var(--muted);letter-spacing:.6px;text-transform:uppercase;margin-bottom:3px">Raised by</div>
        <div style="font-size:13px">${escapeHtml(p.created_by || '—')}</div>
      </div>
      <div style="background:var(--bg-dark);padding:10px 14px">
        <div style="font-size:10px;color:var(--muted);letter-spacing:.6px;text-transform:uppercase;margin-bottom:3px">Delivery Address</div>
        <div style="font-size:12px;color:var(--muted);line-height:1.4">${escapeHtml(p.delivery_address || '—')}</div>
      </div>
    </div>

    <!-- ── Row 2: Description (if set) ── -->
    ${p.description ? `<div style="margin-bottom:16px;font-size:13px;color:var(--muted)">${escapeHtml(p.description)}</div>` : ''}

    <!-- ── Row 3: Line items + totals ── -->
    <div style="margin-bottom:16px">
      ${lineItemsHtml}
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:0;margin-top:8px;padding:10px 12px;background:var(--bg-darker);border-radius:6px">
        ${Number(p.delivery_charge||0) > 0 ? `<div style="font-size:12px;color:var(--muted);grid-column:1/-1;margin-bottom:4px">Delivery charge: <b>${fmtMoneyFull(p.delivery_charge)}</b></div>` : ''}
        <div style="font-size:12px"><span style="color:var(--muted)">Nett</span><br><b style="font-family:var(--font-mono);font-size:15px">${fmtMoneyFull(nett)}</b></div>
        <div style="font-size:12px;text-align:center"><span style="color:var(--muted)">VAT ${Number(p.vat_rate||0).toFixed(0)}%</span><br><b style="font-family:var(--font-mono);font-size:15px">${fmtMoneyFull(p.vat_amount||0)}</b></div>
        <div style="font-size:12px;text-align:right"><span style="color:var(--muted)">Gross</span><br><b style="font-family:var(--font-mono);font-size:18px">${fmtMoneyFull(gross)}</b></div>
      </div>
    </div>

    <!-- ── Row 4: Project link ── -->
    <div style="margin-bottom:16px;padding:10px 14px;background:var(--bg-darker);border-radius:8px">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap">
        <div>
          <div style="font-size:10px;color:var(--muted);letter-spacing:.6px;text-transform:uppercase;margin-bottom:4px">Linked Project</div>
          <div style="font-size:13px">${projInfo}</div>
        </div>
        <button id="poDetailReassignBtn" class="btn btn-ghost" style="font-size:12px;padding:5px 12px"
                onclick="openPoReassignPanel(${p.id})">
          🔗 ${p.project_id ? 'Change' : 'Assign to project'}
        </button>
      </div>
      <div id="poReassignPanel" style="display:none;margin-top:10px;padding-top:10px;border-top:1px solid var(--border)"
           data-po-id="${p.id}">
        <input id="poReassignSearch" type="text" class="field-input" placeholder="Project number or name…"
               style="width:100%;font-size:13px;margin-bottom:6px"
               oninput="searchPoReassignProjects(this.value)">
        <div id="poReassignDropdown" style="background:var(--bg-dark);border:1px solid var(--border);border-radius:6px;max-height:160px;overflow-y:auto;display:none"></div>
        <div style="margin-top:8px;display:flex;gap:8px">
          <button class="btn btn-ghost" style="font-size:12px"
                  onclick="document.getElementById('poReassignPanel').style.display='none'">Cancel</button>
          ${p.project_id ? `<button class="btn btn-ghost" style="font-size:12px;color:var(--red)" onclick="confirmPoUnlink(${p.id})">Unlink</button>` : ''}
        </div>
      </div>
    </div>

    <!-- ── Row 5: Workflow ── -->
    <div style="padding:10px 14px;background:var(--bg-darker);border-radius:8px">
      <div style="font-size:10px;color:var(--muted);letter-spacing:.6px;text-transform:uppercase;margin-bottom:4px">Workflow</div>
      ${wfRow(!!p.approved_at,
        `Approved by ${escapeHtml(p.approved_by||'')} · ${(p.approved_at||'').slice(0,10)}`,
        'Awaiting approval (legacy)', null, null, p.id, false)}
      ${wfRow(!!p.delivery_received_at,
        `Delivery confirmed · ${(p.delivery_received_at||'').slice(0,10)}`,
        'Awaiting delivery', 'Confirm delivery', 'delivery_received', p.id, false)}
      ${wfRow(!!(p.invoice_received_at || p.supplier_invoice_received_at),
        p.supplier_invoice_received_at
          ? `Invoice ${escapeHtml(p.supplier_invoice_ref||p.invoice_ref||'')} received · ${(p.supplier_invoice_received_at||'').slice(0,10)}`
          : `Invoice ${escapeHtml(p.invoice_ref||'')} received · ${(p.invoice_received_at||'').slice(0,10)}`,
        'Awaiting invoice', 'Mark invoiced', 'invoice_received', p.id, false)}
      ${wfRow(!!p.paid_at,
        `Paid · ${(p.paid_at||'').slice(0,10)}`,
        'Not yet paid', 'Mark paid & close', 'paid', p.id, true)}
    </div>
  `;

  const editBtn = document.getElementById('poDetailEditBtn');
  editBtn.dataset.poId = p.id;
  const perms = getUserPermissions(currentManagerUser) || {};
  const hasEditModal = !!document.getElementById('poNewModal');
  if (perms.editPurchaseOrders) {
    editBtn.style.display = '';
    if (hasEditModal) {
      editBtn.textContent = '✏️ Edit';
      editBtn.onclick = editPoFromDetail;
    } else {
      // On pages without the edit modal (office, project-tracker etc.)
      // navigate to po-tracker.html and open the edit modal there.
      editBtn.textContent = '✏️ Edit in PO Tracker';
      editBtn.onclick = () => {
        sessionStorage.setItem('bama_po_edit', p.id);
        window.location.href = 'po-tracker.html';
      };
    }
  } else {
    editBtn.style.display = 'none';
  }
}


// ── Workflow step advance / undo ─────────────────────────────────────
//
// Backs the four ✅/⬜ buttons in the PO detail modal's Workflow row.
// The buttons call poMarkStep(poId, step) with step ∈ {
//   'approved', 'delivery_received', 'invoice_received', 'paid', 'unpaid'
// }
//
// Status enum:
//   Open     — raised but not delivered yet (approval is just a flag, doesn't move status)
//   Received — delivered, possibly invoiced, not yet paid
//   Closed   — paid
//
// Server-side: the PUT endpoint accepts both the timestamp columns and a
// status string; we set both at once for clarity, matching the schema's
// documented contract (status is a UI-level summary of the underlying
// timestamps).
async function poMarkStep(poId, step) {
  if (!poId || !step) return;
  const who = currentManagerUser || 'office';
  const nowIso = new Date().toISOString();
  let body = {};
  let confirmMsg = '';

  switch (step) {
    case 'approved':
      confirmMsg = 'Mark this PO as approved?';
      body = { approved_at: nowIso, approved_by: who };
      break;

    case 'delivery_received':
      confirmMsg = 'Confirm goods/services received?';
      body = { delivery_received_at: nowIso, delivery_received_by: who, status: 'Received' };
      break;

    case 'invoice_received': {
      // Need invoice ref + value before we can mark
      const ref = window.prompt('Supplier invoice reference? (e.g. INV-12345)');
      if (ref === null) return;                          // cancel
      if (!ref.trim()) { toast('Invoice reference required', 'error'); return; }
      const rawVal = window.prompt(`Invoice value (gross £)?\n\nLeave blank to use the PO total.`, '');
      if (rawVal === null) return;                       // cancel
      const valNum = rawVal.trim() === '' ? null : Number(String(rawVal).replace(/[^\d.\-]/g, ''));
      if (valNum !== null && (isNaN(valNum) || valNum < 0)) {
        toast('Invoice value must be a non-negative number', 'error');
        return;
      }
      body = {
        invoice_received_at: nowIso,
        invoice_received_by: who,
        invoice_ref: ref.trim(),
        status: 'Received'
      };
      if (valNum !== null) body.invoice_value = valNum;
      break;
    }

    case 'paid':
      confirmMsg = 'Mark this PO as paid? This closes the PO.';
      body = { paid_at: nowIso, paid_by: who, status: 'Closed' };
      break;

    case 'unpaid':
      confirmMsg = 'Undo the paid status? The PO will return to Received.';
      body = { paid_at: null, paid_by: null, status: 'Received' };
      break;

    default:
      console.warn('Unknown PO workflow step:', step);
      return;
  }

  if (confirmMsg) {
    const ok = await showConfirmAsync(confirmMsg, 'Confirm', 'Cancel');
    if (!ok) return;
  }

  try {
    await api.put(`/api/purchase-orders/${poId}`, body);
    toast('Workflow updated ✓', 'success');
    // Re-fetch + re-render detail
    await openPoDetailModal(poId);
    // Refresh the tracker list if we're on the PO Tracker page, or the
    // project's PO panel if we're on Project Tracker. On other pages
    // (e.g. quickly opened from a deep link) neither refreshes — the
    // detail modal already reflects the new state.
    if (document.getElementById('poTrackerTbody') && typeof loadPoTracker === 'function') {
      loadPoTracker();
    }
    if (document.getElementById('ptPoList') && currentProjectRecord && typeof loadProjectPos === 'function') {
      loadProjectPos(currentProjectRecord.id);
    }
  } catch (e) {
    toast('Update failed: ' + (e.message || ''), 'error');
  }
}


// ── PO → Project reassignment ──
function openPoReassignPanel(poId) {
  const panel = document.getElementById('poReassignPanel');
  if (!panel) return;
  panel.style.display = panel.style.display === 'none' ? '' : 'none';
  if (panel.style.display !== 'none') {
    document.getElementById('poReassignSearch').value = '';
    document.getElementById('poReassignDropdown').style.display = 'none';
  }
}

function searchPoReassignProjects(q) {
  const dd = document.getElementById('poReassignDropdown');
  if (!q || q.length < 2) { dd.style.display = 'none'; dd.innerHTML = ''; return; }
  const needle = q.toLowerCase();
  const matches = _poProjectsCache.filter(p =>
    (p.project_number || '').toLowerCase().includes(needle) ||
    (p.project_name   || '').toLowerCase().includes(needle)
  ).slice(0, 12);
  if (!matches.length) { dd.style.display = 'none'; return; }
  dd.style.display = '';
  dd.innerHTML = matches.map(m =>
    `<div style="padding:7px 10px;cursor:pointer;font-size:13px;border-bottom:1px solid var(--border)"
          onmousedown="selectPoReassignProject(${m.id},${JSON.stringify(m.project_number).replace(/"/g,'&quot;')},${JSON.stringify(m.project_name || '').replace(/"/g,'&quot;')})"
          onmouseover="this.style.background='var(--bg-light)'" onmouseout="this.style.background=''">
       <span style="font-family:var(--font-mono);color:var(--accent)">${escapeHtml(m.project_number)}</span>
       <span style="color:var(--muted);margin-left:8px">${escapeHtml(m.project_name || '')}</span>
     </div>`
  ).join('');
}

async function selectPoReassignProject(projectId, projectNumber, projectName) {
  const panel = document.getElementById('poReassignPanel');
  const poId  = parseInt(panel.dataset.poId || panel.getAttribute('data-po-id') || '0', 10);
  if (!poId || !projectId) return;
  document.getElementById('poReassignSearch').value = `${projectNumber} — ${projectName}`;
  document.getElementById('poReassignDropdown').style.display = 'none';
  const btn = document.getElementById('poDetailReassignBtn');
  const originalLabel = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
  try {
    await api.put(`/api/purchase-orders/${poId}`, { project_id: projectId, cost_centre: null, job_number: projectNumber });
    panel.style.display = 'none';
    toast(`PO linked to ${projectNumber} ✓`, 'success');
    await openPoDetailModal(poId);
    loadPoTracker();
  } catch (e) {
    toast('Link failed: ' + (e.message || 'Unknown error'), 'error');
    if (btn) { btn.disabled = false; btn.textContent = originalLabel || 'Assign to project'; }
  }
}

async function confirmPoUnlink(poId) {
  const ok = await showConfirmAsync('Remove project link from this PO and set it to Overhead?', 'Unlink', 'Cancel');
  if (!ok) return;
  try {
    const po = _poList.find(x => x.id === poId);
    await api.put(`/api/purchase-orders/${poId}`, { project_id: null, cost_centre: po ? (po.job_number || '8099') : '8099' });
    toast('Project link removed', 'success');
    await openPoDetailModal(poId);
    loadPoTracker();
  } catch (e) {
    toast('Unlink failed: ' + (e.message || ''), 'error');
  }
}

function editPoFromDetail() {
  const id = parseInt(document.getElementById('poDetailEditBtn').dataset.poId || '0', 10);
  if (!id) return;
  document.getElementById('poDetailModal').classList.remove('active');
  openPoEditModal(id);
}

async function openPoEditModal(poId) {
  const perms = getUserPermissions(currentManagerUser) || {};
  if (!perms.editPurchaseOrders) { toast('You don\'t have permission to edit POs.', 'error'); return; }
  let p;
  try { p = await api.get(`/api/purchase-orders/${poId}`); }
  catch (e) { toast('Failed to load PO', 'error'); return; }

  // Open the new-PO modal but pre-fill for edit
  _poEditingId = poId;
  _poNewState = {
    scope:     p.project_id ? 'project' : 'overhead',
    projectId: p.project_id || null,
    supplierId: p.supplier_id,
    jobNumber: p.job_number || '',
    lineItems: (p.line_items || []).map(li => ({
      description: li.description || '',
      quantity:    li.quantity    !== null ? String(li.quantity)    : '',
      unit_price:  li.unit_price  !== null ? String(li.unit_price)  : '',
      line_total:  li.line_total  !== null ? String(li.line_total)  : ''
    }))
  };

  document.querySelector('#poNewModal .modal-title').textContent = `✏️ Edit ${p.reference}`;
  document.getElementById('poNewRef').value = p.reference || '';
  document.getElementById('poNewDate').value = (p.created_at || '').slice(0, 10);

  // Populate cost-centre dropdown first (in case scope is overhead)
  const ccSel = document.getElementById('poNewCostCentre');
  ccSel.innerHTML = '<option value="">—</option>' +
    Object.entries(_poCostCentres).map(([code, label]) =>
      `<option value="${escapeHtml(code)}">${escapeHtml(code)} — ${escapeHtml(label)}</option>`
    ).join('');

  setPoScope(_poNewState.scope);

  if (_poNewState.scope === 'project') {
    const proj = _poProjectsCache.find(x => x.id === p.project_id);
    if (proj) {
      document.getElementById('poNewProjectSearch').value = `${proj.project_number} — ${proj.project_name || ''}`;
      document.getElementById('poNewProjectSelected').textContent =
        `Selected: ${proj.project_number}${proj.project_name ? ' · ' + proj.project_name : ''}`;
    }
    document.getElementById('poNewJobNumber').value = p.job_number || '';
  } else {
    ccSel.value = p.cost_centre || '';
  }

  // Supplier
  const sup = _poSuppliersCache.find(s => s.id === p.supplier_id);
  if (sup) {
    document.getElementById('poNewSupplierSearch').value = sup.supplier_name || '';
    document.getElementById('poNewSupplierSelected').textContent =
      `Selected: ${sup.supplier_name}${sup.contact_name ? ' · ' + sup.contact_name : ''}`;
  }

  document.getElementById('poNewDeliveryDate').value     = p.delivery_date    || '';
  document.getElementById('poNewDeliveryAddress').value  = p.delivery_address || '';
  document.getElementById('poNewDeliveryCharge').value   = p.delivery_charge   !== null && p.delivery_charge   !== undefined ? p.delivery_charge   : '';
  document.getElementById('poNewCollectionCharge').value = p.collection_charge !== null && p.collection_charge !== undefined ? p.collection_charge : '';
  document.getElementById('poNewVatRate').value          = (p.vat_rate !== null && p.vat_rate !== undefined) ? p.vat_rate : 20;
  document.getElementById('poNewVatAmount').value        = (p.vat_amount !== null && p.vat_amount !== undefined) ? Number(p.vat_amount).toFixed(2) : '';
  document.getElementById('poNewTotal').value            = p.total_value       !== null && p.total_value       !== undefined ? p.total_value       : '';
  document.getElementById('poNewDescription').value      = p.description       || '';

  renderPoLineRows();
  recalcPoTotal();  // populate Nett field + reconcile any rounding

  document.getElementById('poNewError').textContent = '';
  document.getElementById('poNewBudgetWarn').textContent = '';
  document.getElementById('poNewSaveBtn').textContent = 'Save Changes';
  _poEditingRef = p.reference || null;
  document.getElementById('poDeleteBtn').style.display = 'inline-flex';

  document.getElementById('poNewModal').classList.add('active');
  updatePoBudgetWarn();
}

// ── Cross-page nav ──
// ── Instant PO ────────────────────────────────────────────────────────────────
// Phone-to-supplier shortcut: allocates a PO ref immediately with minimal input.
// Creates a stub PO + follow-up office task assigned to the current user.
// ─────────────────────────────────────────────────────────────────────────────

let _instantPoState = {
  scope: null,        // 'project' | 'overhead'
  projectId: null,
  supplierId: null,
  newSupplierMode: false
};

function openInstantPoModal() {
  _instantPoState = { scope: null, projectId: null, supplierId: null, newSupplierMode: false };

  // Reset fields
  document.getElementById('instantPoSupplierSearch').value = '';
  const supDd = document.getElementById('instantPoSupplierDropdown');
  supDd.innerHTML = ''; supDd.style.display = 'none';
  document.getElementById('instantPoSupplierSelected').innerHTML = '';
  document.getElementById('instantPoProjectSearch').value = '';
  const projDd = document.getElementById('instantPoProjectDropdown');
  projDd.innerHTML = ''; projDd.style.display = 'none';
  document.getElementById('instantPoProjectSelected').innerHTML = '';
  document.getElementById('instantPoCostCentre').value = '';
  document.getElementById('instantPoDescription').value = '';
  document.getElementById('instantPoError').textContent = '';

  // New supplier sub-form
  document.getElementById('instantPoNewSupplierWrap').style.display = 'none';
  document.getElementById('instantPoNewSupplierName').value = '';
  document.getElementById('instantPoNewSupplierContact').value = '';
  document.getElementById('instantPoNewSupplierPhone').value = '';
  document.getElementById('instantPoNewSupplierEmail').value = '';

  setInstantPoScope('project');
  document.getElementById('instantPoModal').classList.add('active');

  // Close dropdowns when clicking outside them (use capture so it fires before focus)
  setTimeout(() => {
    function ipoOutsideClick(e) {
      const modal = document.getElementById('instantPoModal');
      if (!modal || !modal.classList.contains('active')) {
        document.removeEventListener('mousedown', ipoOutsideClick, true);
        return;
      }
      ['instantPoProjectDropdown','instantPoSupplierDropdown'].forEach(id => {
        const dd = document.getElementById(id);
        const input = document.getElementById(id.replace('Dropdown','Search'));
        if (dd && input && !dd.contains(e.target) && e.target !== input) {
          dd.style.display = 'none';
        }
      });
    }
    document.addEventListener('mousedown', ipoOutsideClick, true);
  }, 0);
}

function closeInstantPoModal() {
  document.getElementById('instantPoModal').classList.remove('active');
}

function setInstantPoScope(scope) {
  _instantPoState.scope = scope;
  _instantPoState.projectId = null;

  const projBtn  = document.getElementById('instantPoScopeProjectBtn');
  const ohBtn    = document.getElementById('instantPoScopeOverheadBtn');
  const projWrap = document.getElementById('instantPoProjectWrap');
  const ohWrap   = document.getElementById('instantPoOverheadWrap');

  if (scope === 'project') {
    projBtn.classList.add('btn-primary'); projBtn.classList.remove('btn-ghost');
    ohBtn.classList.add('btn-ghost');     ohBtn.classList.remove('btn-primary');
    projWrap.style.display = 'block';
    ohWrap.style.display   = 'none';
  } else {
    ohBtn.classList.add('btn-primary');   ohBtn.classList.remove('btn-ghost');
    projBtn.classList.add('btn-ghost');   projBtn.classList.remove('btn-primary');
    projWrap.style.display = 'none';
    ohWrap.style.display   = 'block';
    // Populate cost centre select from loaded settings
    const ccSel = document.getElementById('instantPoCostCentre');
    ccSel.innerHTML = '<option value="">— Select cost centre —</option>' +
      Object.entries(_poCostCentres || {}).map(([code, label]) =>
        `<option value="${escapeHtml(code)}">${escapeHtml(code)} — ${escapeHtml(label)}</option>`
      ).join('');
  }
}

function filterInstantPoProjects(q) {
  const dd   = document.getElementById('instantPoProjectDropdown');
  const term = (q || '').toLowerCase().trim();

  // Only show C/S/BC projects that are In Progress
  const pool = (_poProjectsCache || []).filter(p => {
    const s = (p.status || '').toLowerCase();
    return s === 'in progress' || s === 'in_progress';
  });

  const matches = pool.filter(p =>
    !term ||
    (p.project_number || '').toLowerCase().includes(term) ||
    (p.project_name   || '').toLowerCase().includes(term) ||
    (p.client_name    || '').toLowerCase().includes(term)
  ).slice(0, 12);

  if (!matches.length) { dd.style.display = 'none'; dd.innerHTML = ''; return; }

  dd.innerHTML = matches.map(p => `
    <div class="ipo-dropdown-item" data-pid="${p.id}">
      <span style="font-weight:600">${escapeHtml(p.project_number || '')}</span>
      <span style="color:var(--muted);margin-left:8px">${escapeHtml(p.project_name || '')}</span>
      ${p.client_name ? `<div class="ipo-sub">${escapeHtml(p.client_name)}</div>` : ''}
    </div>`
  ).join('');

  dd.querySelectorAll('.ipo-dropdown-item').forEach(row => {
    row.addEventListener('mousedown', e => {
      e.preventDefault();
      selectInstantPoProject(parseInt(row.dataset.pid, 10));
    });
  });

  dd.style.display = 'block';
}

function selectInstantPoProject(projectId) {
  const proj = (_poProjectsCache || []).find(p => p.id === projectId);
  if (!proj) return;
  _instantPoState.projectId = projectId;
  document.getElementById('instantPoProjectSearch').value = `${proj.project_number} — ${proj.project_name}`;
  const dd = document.getElementById('instantPoProjectDropdown');
  dd.style.display = 'none'; dd.innerHTML = '';
  document.getElementById('instantPoProjectSelected').innerHTML =
    `<span class="ipo-selected-badge">✓ ${escapeHtml(proj.project_number)}</span>`;
}

function filterInstantPoSuppliers(q) {
  const dd   = document.getElementById('instantPoSupplierDropdown');
  const term = (q || '').toLowerCase().trim();

  const matches = (_poSuppliersCache || []).filter(s =>
    !term || (s.supplier_name || '').toLowerCase().includes(term)
  ).slice(0, 12);

  let rows = matches.map(s => `
    <div class="ipo-dropdown-item" data-sid="${s.id}">
      ${escapeHtml(s.supplier_name || '')}
    </div>`
  );

  rows.push(`<div class="ipo-dropdown-item ipo-dropdown-add" data-action="new">
    ＋ Add "${escapeHtml(q || 'new supplier')}"
  </div>`);

  dd.innerHTML = rows.join('');

  dd.querySelectorAll('.ipo-dropdown-item').forEach(row => {
    row.addEventListener('mousedown', e => {
      e.preventDefault();
      if (row.dataset.action === 'new') {
        showInstantPoNewSupplier();
      } else {
        selectInstantPoSupplier(parseInt(row.dataset.sid, 10));
      }
    });
  });

  dd.style.display = 'block';
}

function selectInstantPoSupplier(supplierId) {
  const sup = (_poSuppliersCache || []).find(s => s.id === supplierId);
  if (!sup) return;
  _instantPoState.supplierId = supplierId;
  _instantPoState.newSupplierMode = false;
  document.getElementById('instantPoSupplierSearch').value = sup.supplier_name;
  const dd = document.getElementById('instantPoSupplierDropdown');
  dd.style.display = 'none'; dd.innerHTML = '';
  document.getElementById('instantPoSupplierSelected').innerHTML =
    `<span class="ipo-selected-badge">✓ ${escapeHtml(sup.supplier_name)}</span>`;
  document.getElementById('instantPoNewSupplierWrap').style.display = 'none';
}

function showInstantPoNewSupplier() {
  const q = document.getElementById('instantPoSupplierSearch').value.trim();
  _instantPoState.supplierId = null;
  _instantPoState.newSupplierMode = true;
  const dd = document.getElementById('instantPoSupplierDropdown');
  dd.innerHTML = ''; dd.style.display = 'none';
  document.getElementById('instantPoSupplierSelected').innerHTML = '';
  document.getElementById('instantPoNewSupplierWrap').style.display = 'block';
  document.getElementById('instantPoParsePanel').style.display = 'none';
  if (q) document.getElementById('instantPoNewSupplierName').value = q;
  document.getElementById('instantPoNewSupplierName').focus();
}

function toggleInstantPoParsePanel() {
  const panel = document.getElementById('instantPoParsePanel');
  const isHidden = panel.style.display === 'none';
  panel.style.display = isHidden ? 'block' : 'none';
  if (isHidden) document.getElementById('instantPoParseText').focus();
}

async function parseInstantPoSupplier() {
  const text = document.getElementById('instantPoParseText').value.trim();
  if (!text) return;

  const btn    = document.getElementById('instantPoParseRunBtn');
  const status = document.getElementById('instantPoParseStatus');
  btn.disabled = true;
  btn.textContent = 'Parsing…';
  status.textContent = '';

  try {
    // ── Build few-shot examples from confirmed supplier parsings ──
    // Any supplier in the cache that has a parse_source_text was created via
    // this feature and confirmed by a human — use up to 5 as examples.
    const examples = (_poSuppliersCache || [])
      .filter(s => s.parse_source_text && s.parse_source_text.trim())
      .slice(0, 5);

    let fewShotSection = '';
    if (examples.length) {
      fewShotSection = '\n\nHere are confirmed examples from this company\'s supplier database:\n\n' +
        examples.map((s, i) => {
          const output = JSON.stringify({
            supplier_name: s.supplier_name || null,
            contact_name:  s.contact_name  || null,
            telephone:     s.telephone     || null,
            email:         s.email         || null
          });
          return `Example ${i + 1}:\nINPUT:\n${s.parse_source_text.trim()}\nOUTPUT:\n${output}`;
        }).join('\n\n');
    }

    const systemPrompt =
      `You extract supplier contact details from pasted text (email signatures, quote headers, invoice footers, website footers, etc.).

Return ONLY a JSON object with these fields — use null for anything not found:
{
  "supplier_name": string | null,
  "contact_name":  string | null,
  "telephone":     string | null,
  "email":         string | null
}

Rules:
- supplier_name: the company/trading name, not a person's name
- contact_name: the individual's name (first + last if available)
- telephone: include country code if present, keep formatting as-is
- email: only a real email address, not a website URL
- Do not invent or guess values — only extract what is explicitly present in the text
- Return only the JSON object, no explanation, no markdown` + fewShotSection;

    const data = await callClaude({
      model: 'claude-sonnet-4-6',
      max_tokens: 1000,
      system: systemPrompt,
      messages: [{ role: 'user', content: text }]
    });

    const raw = (data.content || []).find(b => b.type === 'text')?.text || '';
    const clean = raw.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(clean);

    // Pre-fill fields — only overwrite if the parsed value is non-null
    if (parsed.supplier_name) document.getElementById('instantPoNewSupplierName').value    = parsed.supplier_name;
    if (parsed.contact_name)  document.getElementById('instantPoNewSupplierContact').value = parsed.contact_name;
    if (parsed.telephone)     document.getElementById('instantPoNewSupplierPhone').value   = parsed.telephone;
    if (parsed.email)         document.getElementById('instantPoNewSupplierEmail').value   = parsed.email;

    const found = [parsed.supplier_name, parsed.contact_name, parsed.telephone, parsed.email]
      .filter(Boolean).length;
    const exStr = examples.length ? ` (${examples.length} example${examples.length > 1 ? 's' : ''} used)` : '';
    status.textContent = found
      ? `✓ ${found} field${found > 1 ? 's' : ''} filled${exStr} — review and adjust`
      : 'Nothing found — paste more detail';
    status.style.color = found ? 'var(--green)' : 'var(--orange, #e67e22)';

    // Collapse the parse panel so the user focuses on reviewing the filled fields
    if (found) {
      setTimeout(() => {
        document.getElementById('instantPoParsePanel').style.display = 'none';
        status.textContent = '';
      }, 2500);
    }
  } catch (e) {
    status.textContent = 'Parse failed — check console';
    status.style.color = 'var(--red)';
    console.error('Supplier parse error:', e);
  } finally {
    btn.disabled = false;
    btn.textContent = 'Parse';
  }
}

async function saveInstantPo() {
  const btn = document.getElementById('instantPoSaveBtn');
  const errEl = document.getElementById('instantPoError');
  errEl.textContent = '';

  // ── Validate ──
  if (!_instantPoState.supplierId && !_instantPoState.newSupplierMode) {
    errEl.textContent = 'Select a supplier or add a new one.';
    return;
  }
  if (_instantPoState.newSupplierMode) {
    const nm = document.getElementById('instantPoNewSupplierName').value.trim();
    if (!nm) { errEl.textContent = 'Supplier name is required.'; return; }
  }
  if (_instantPoState.scope === 'project' && !_instantPoState.projectId) {
    errEl.textContent = 'Select a project, or switch to Overhead PO.';
    return;
  }

  btn.disabled = true;
  btn.textContent = 'Saving…';

  try {
    // ── 1. Create supplier if new ──
    let supplierId = _instantPoState.supplierId;
    if (_instantPoState.newSupplierMode) {
      const parseText = document.getElementById('instantPoParseText').value.trim();
      const newSup = await api.post('/api/suppliers', {
        supplier_name:      document.getElementById('instantPoNewSupplierName').value.trim(),
        contact_name:       document.getElementById('instantPoNewSupplierContact').value.trim() || null,
        telephone:          document.getElementById('instantPoNewSupplierPhone').value.trim() || null,
        email:              document.getElementById('instantPoNewSupplierEmail').value.trim() || null,
        parse_source_text:  parseText || null   // stored as a confirmed few-shot example
      });
      supplierId = newSup.id;
      // Add to cache so it shows in future searches this session
      _poSuppliersCache.push(newSup);
    }

    // ── 2. Allocate PO ref and create stub PO ──
    const poPayload = {
      supplier_id:  supplierId,
      status:       'Open',
      total_value:  0,
      vat_rate:     20,
      vat_amount:   0,
      description:  document.getElementById('instantPoDescription').value.trim() || null,
      created_by:   currentManagerUser || (typeof AUTH !== 'undefined' && AUTH.getUserName?.()) || 'unknown'
    };

    if (_instantPoState.scope === 'project' && _instantPoState.projectId) {
      poPayload.project_id = _instantPoState.projectId;
      const proj = (_poProjectsCache || []).find(p => p.id === _instantPoState.projectId);
      if (proj) poPayload.job_number = proj.project_number;
    } else {
      const cc = document.getElementById('instantPoCostCentre').value.trim();
      if (cc) poPayload.cost_centre = cc;
    }

    const newPo = await api.post('/api/purchase-orders', poPayload);
    const poRef = newPo.reference;

    // ── 3. Create follow-up office task assigned to the person who raised it ──
    const taskOwner = currentManagerUser || (typeof AUTH !== 'undefined' && AUTH.getUserName?.()) || 'unknown';
    const supplierName = _instantPoState.newSupplierMode
      ? document.getElementById('instantPoNewSupplierName').value.trim()
      : ((_poSuppliersCache || []).find(s => s.id === supplierId) || {}).supplier_name || 'supplier';

    try {
      await api.post('/api/office-tasks', {
        title: `Complete PO ${poRef} — ${supplierName}`,
        description: `Instant PO raised by ${taskOwner}. Add line items, value and delivery details.`,
        assigned_to: taskOwner,
        assigned_by: taskOwner,
        priority: 'high',
        source: 'instant_po',
        source_ref: poRef
      });
    } catch (taskErr) {
      console.warn('Instant PO task creation failed (non-fatal):', taskErr.message);
    }

    toast(`⚡ PO ${poRef} created — complete it from your task queue`, 'success');
    closeInstantPoModal();
    await loadPoTracker();
  } catch (e) {
    errEl.textContent = e.message || 'Save failed';
  } finally {
    btn.disabled = false;
    btn.textContent = '⚡ Get PO Number';
  }
}

