// Minimal HTML escape — same impl used across the file. Defined locally as
// a fallback in case the shared one is hoisted later in the file ordering.
if (typeof window.escapeHtml !== 'function') {
  window.escapeHtml = function(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  };
}


// ═══════════════════════════════════════════
// PAGE DETECTION
// ═══════════════════════════════════════════
const CURRENT_PAGE = (() => {
  const path = window.location.pathname.toLowerCase();
  if (path.includes('manager')) return 'manager';
  if (path.includes('office')) return 'office';
  if (path.includes('templates')) return 'templates';
  if (path.includes('babcock')) return 'babcock';
  if (path.includes('project-tracker')) return 'projectTracker';
  if (path.includes('po-tracker')) return 'poTracker';
  if (path.includes('invoice-tracker')) return 'invoiceTracker';
  if (path.includes('reconcile')) return 'reconcile';
  if (path.includes('dashboard')) return 'dashboard';
  if (path.includes('reports')) return 'reports';
  if (path.includes('projects') || path.includes('project')) return 'projects';
  if (path.includes('hub')) return 'hub';
  return 'index'; // default kiosk
})();

// Track whether we successfully loaded data from the API
let _dataLoadedFromAPI = false;

async function init() {
  setLoading(true);

  // Handle token from Microsoft login redirect
  const justLoggedIn = AUTH.handleRedirect();
  if (justLoggedIn) console.log('Just returned from login, token stored');

  // Fire a warm-up ping immediately — no auth needed, wakes the Function App from cold start
  const warmupPromise = fetch(`${API_BASE}/api/health`).catch(() => {});

  // Load core data from SQL API with retry
  // Generous timeouts to handle Azure Function cold starts (can take 15-25s on free tier)
  const loadDataWithRetry = async () => {
    await warmupPromise; // wait for warmup to complete first
    for (let attempt = 1; attempt <= 3; attempt++) {
      try {
        await Promise.race([
          loadTimesheetData(),
          new Promise((_, rej) => setTimeout(() => rej(new Error('Timeout')), attempt === 1 ? 30000 : 20000))
        ]);
        _dataLoadedFromAPI = true;
        return;
      } catch (e) {
        console.warn(`API data load attempt ${attempt}/3 failed:`, e.message);
        if (attempt < 3) {
          console.log(`Retrying in ${attempt}s...`);
          await new Promise(r => setTimeout(r, attempt * 1000));
        }
      }
    }
    if (!state.timesheetData.employees || state.timesheetData.employees.length === 0) {
      console.warn('No employee data loaded after 3 attempts — app will be read-only until data loads');
    }
  };
  const dataPromise = loadDataWithRetry();

  // Projects Excel only needed on kiosk and projects pages (still from SharePoint)
  const projectsPromise = (CURRENT_PAGE === 'index' || CURRENT_PAGE === 'projects')
    ? Promise.race([
        loadProjects(),
        new Promise((_, rej) => setTimeout(() => rej(new Error('Timeout')), 8000))
      ]).catch(e => { console.warn('Project load skipped, using fallback:', e.message); state.projects = []; })
    : Promise.resolve();

  // User access needed on manager and office pages (still from SharePoint for now)
  const userAccessPromise = (CURRENT_PAGE === 'manager' || CURRENT_PAGE === 'office' || CURRENT_PAGE === 'projects' || CURRENT_PAGE === 'projectTracker' || CURRENT_PAGE === 'poTracker' || CURRENT_PAGE === 'invoiceTracker' || CURRENT_PAGE === 'babcock' || CURRENT_PAGE === 'reports' || CURRENT_PAGE === 'reconcile' || CURRENT_PAGE === 'dashboard')
    ? Promise.race([
        loadUserAccessData(),
        new Promise((_, rej) => setTimeout(() => rej(new Error('Timeout')), 6000))
      ]).catch(e => { console.warn('User access load skipped:', e.message); })
    : Promise.resolve();

  // Office tasks only needed on office page (still from SharePoint for now)
  const officeTasksPromise = (CURRENT_PAGE === 'office')
    ? Promise.race([
        loadOfficeTasksData(),
        new Promise((_, rej) => setTimeout(() => rej(new Error('Timeout')), 6000))
      ]).catch(e => { console.warn('Office tasks load skipped:', e.message); })
    : Promise.resolve();

  // Run all loads in parallel
  await Promise.all([dataPromise, projectsPromise, userAccessPromise, officeTasksPromise]);

  setLoading(false);

  // Page-specific startup
  if (CURRENT_PAGE === 'manager') {
    showScreen('screenManagerSelect');
    renderManagerEmployeeGrid();
  } else if (CURRENT_PAGE === 'office') {
    const _authedUser = pinSessionGet();
    const _pendingTab = new URLSearchParams(window.location.search).get('tab');
    if (_authedUser) {
      // Session still valid — skip PIN gate and go straight to office layout
      currentManagerUser = _authedUser;
      const perms = getUserPermissions(currentManagerUser) || {};
      filterSidebarTabs(perms);
      showScreen('screenOffice');
      renderUnifiedSidebar();
      switchTab(_pendingTab || 'dashboard');
      renderManagerView();
      initGlobalInvDz();
    } else {
      // Store pending tab so checkOfficePin can use it after auth
      if (_pendingTab) sessionStorage.setItem('bama_pending_tab', _pendingTab);
      showScreen('screenOfficeSelect');
      renderOfficeEmployeeGrid();
    }
  } else if (CURRENT_PAGE === 'projects') {
    showScreen('screenProjects');

    // Restore draftsman mode from sessionStorage if set. Survives a page
    // refresh; cleared on tab close or manual logout. Done BEFORE the
    // first renderProjectTiles so the UI starts in the right state and
    // doesn't flicker from non-draftsman to draftsman.
    try {
      if (sessionStorage.getItem('bama_draftsman') === '1') {
        isDraftsman = true;
        _currentDraftsmanName = sessionStorage.getItem('bama_draftsman_name') || null;
        const badge = document.getElementById('draftsmanBadge');
        const loginBtn = document.getElementById('draftsmanLoginBtn');
        if (badge) badge.style.display = 'flex';
        if (loginBtn) loginBtn.style.display = 'none';
      }
    } catch (_) {}

    renderProjectTiles();
    // Load job data then re-render tiles with job counts, and handle deep links
    loadDrawingsData().then(() => {
      renderProjectTiles();
      // Deep link: ?project=X&job=Y&element=Assembly
      const params = new URLSearchParams(window.location.search);
      const deepProject = params.get('project');
      const deepJob = params.get('job');
      const deepElement = params.get('element');
      if (deepProject && deepJob) {
        // Clear URL params so back button doesn't re-trigger
        window.history.replaceState({}, '', window.location.pathname);
        // Navigate directly — openJobDetail handles its own data load
        // (loadJobAssemblies + loadJobBomItems + loadFinishes via Promise.all).
        openJobDetail(deepProject, deepJob);
        if (deepElement) {
          setTimeout(() => {
            // Expand the target element section
            const body = document.getElementById(`element${deepElement}Body`);
            if (body && body.classList.contains('collapsed')) toggleElement(deepElement);
            // Scroll to it
            const card = document.getElementById(`element${deepElement}`);
            if (card) card.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }, 300);
        }
      }
    }).catch(e => console.warn('Job data load failed:', e.message));
  } else if (CURRENT_PAGE === 'templates') {
    initTemplatesPage();
  } else if (CURRENT_PAGE === 'projectTracker') {
    initProjectTrackerPage();
  } else if (CURRENT_PAGE === 'poTracker') {
    initPoTrackerPage();
  } else if (CURRENT_PAGE === 'invoiceTracker') {
    initInvoiceTrackerPage();
  } else if (CURRENT_PAGE === 'babcock') {
    initBabcockPage();
  } else if (CURRENT_PAGE === 'reports') {
    initReportsPage();
  } else if (CURRENT_PAGE === 'reconcile') {
    initReconcilePage();
  } else if (CURRENT_PAGE === 'hub') {
    // hub has its own simple rendering
  } else {
    renderHome();
    startKioskPolling();
  }

  // Start the idle-PIN monitor for all non-kiosk pages
  startPinIdleMonitor();
}

init();

// ═══════════════════════════════════════════════════════════════════════════
// INVOICE TRACKER — page logic (invoice-tracker.html)
// ═══════════════════════════════════════════════════════════════════════════
// Phase 1, Commit 1 — page shell only. Login screen + PIN gate + four tabs
// (AFPs, Sales Invoices, Supplier Invoices, Receipts) wired up to empty
// placeholder views. Commits 2 + 3 will fill in CRUD, PDFs, OCR and AFP flow.
// ───────────────────────────────────────────────────────────────────────────

let _invPendingPinUser = null;
let _invCurrentTab = 'sales';           // 'afps' | 'sales' | 'supplier'
let _invAfpList = [];
let _invInvoiceList = [];
let _invSupplierPoList = [];            // POs with received supplier invoices
let _invSupInvoices = [];               // SupplierInvoices ledger rows (new AP model)
let _invProjectsCache = [];
let _invClientsCache = [];

async function initInvoiceTrackerPage() {
  const authed = pinSessionGet();
  if (authed) {
    currentManagerUser = authed;
    const perms = getUserPermissions(currentManagerUser) || {};
    if (perms.invoicing) {
      document.getElementById('screenInvSelect').style.display = 'none';
      document.getElementById('invLayout').style.display = 'flex';
      renderUnifiedSidebar();
      await loadInvoicingSupportData();
      await loadInvoicingData();
      switchInvTab(_invCurrentTab);
      return;
    }
  }
  renderInvEmployeeGrid();
}

function renderInvEmployeeGrid() {
  const grid = document.getElementById('invEmployeeGrid');
  if (!grid) return;
  const empList = (state.timesheetData.employees || [])
    .filter(e => e.active !== false && (e.staffType || 'workshop') === 'office');
  if (!empList.length) {
    grid.innerHTML = '<div class="empty-state" style="padding:30px"><div style="font-size:28px;margin-bottom:10px">&#128101;</div><div>No office staff set up yet.</div></div>';
    return;
  }
  grid.innerHTML = empList.map(emp => {
    const ini = (emp.name || '').split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
    const col = empColor(emp.name);
    return `
      <div class="emp-btn" onclick="selectInvEmployee('${emp.name.replace(/'/g, "\\'")}')">
        <div class="emp-avatar" style="width:48px;height:48px;font-size:19px;background:linear-gradient(135deg,${col},#3e1a00)">${ini}</div>
        <div class="emp-name" style="font-size:13px">${emp.name}</div>
        <div style="font-size:10px;color:var(--subtle);margin-top:3px">${emp.hasPin ? '&#128274; PIN set' : '&#128275; No PIN'}</div>
      </div>`;
  }).join('');
}

function selectInvEmployee(name) {
  const emp = (state.timesheetData.employees || []).find(e => e.name === name);
  if (!emp) return;
  if (!emp.hasPin) { toast('No PIN set for this user.', 'error'); return; }
  _invPendingPinUser = { name, empId: emp.id };
  document.getElementById('invPinUser').textContent = name;
  document.getElementById('invPinInput').value = '';
  document.getElementById('invPinError').textContent = '';
  document.getElementById('invPinModal').classList.add('active');
  setTimeout(() => document.getElementById('invPinInput').focus(), 200);
}

async function verifyInvPin() {
  if (!_invPendingPinUser) return;
  const pin = document.getElementById('invPinInput').value;
  if (!pin) return;
  try {
    const result = await api.post('/api/auth/verify-pin', { employee_id: _invPendingPinUser.empId, pin });
    if (!result || !result.valid) {
      document.getElementById('invPinError').textContent = (result && result.reason) || 'Incorrect PIN';
      document.getElementById('invPinInput').value = '';
      return;
    }
    currentManagerUser = _invPendingPinUser.name;
    pinSessionSet(currentManagerUser);
    document.getElementById('invPinModal').classList.remove('active');

    // Bootstrap: if nobody has invoicing perm yet, grant it to the first user in.
    // Matches the existing pattern from manager/office/quotes bootstraps.
    const anyHasInvoicing = Object.values(userAccessData.users || {})
      .some(u => u.permissions && u.permissions.invoicing);
    if (!anyHasInvoicing) {
      try {
        await api.put(`/api/user-access/${_invPendingPinUser.empId}`, { invoicing: true });
        if (!userAccessData.users[currentManagerUser]) {
          userAccessData.users[currentManagerUser] = { employee_id: _invPendingPinUser.empId, permissions: {} };
        }
        userAccessData.users[currentManagerUser].permissions.invoicing = true;
        toast('Bootstrap: invoicing permission granted to ' + currentManagerUser, 'success');
      } catch (e) {
        console.warn('Bootstrap grant failed:', e);
      }
    }

    const perms = getUserPermissions(currentManagerUser) || {};
    if (!perms.invoicing) {
      toast("You don't have permission to access the Invoice Tracker.", 'error');
      currentManagerUser = null;
      pinSessionClear();
      return;
    }
    document.getElementById('screenInvSelect').style.display = 'none';
    document.getElementById('invLayout').style.display = 'flex';
    renderUnifiedSidebar();
    await loadInvoicingSupportData();
    await loadInvoicingData();
    switchInvTab(_invCurrentTab);
  } catch (err) {
    document.getElementById('invPinError').textContent = 'PIN verification failed';
    document.getElementById('invPinInput').value = '';
  }
}

// ── Support data ──────────────────────────────────────────────────────────
async function loadInvoicingSupportData() {
  try {
    const [projects, clients] = await Promise.all([
      api.get('/api/projects').catch(() => []),
      api.get('/api/clients').catch(() => [])
    ]);
    _invProjectsCache = Array.isArray(projects) ? projects : [];
    _invClientsCache  = Array.isArray(clients)  ? clients  : [];
  } catch (e) {
    console.warn('Invoice tracker support data load failed:', e);
  }
}

// ── Load the four streams ─────────────────────────────────────────────────
async function loadInvoicingData() {
  try {
    const [afps, invoices, pos, supInvs] = await Promise.all([
      api.get('/api/applications').catch(() => []),
      api.get('/api/invoices').catch(() => []),
      api.get('/api/purchase-orders').catch(() => []),
      api.get('/api/supplier-invoices').catch(() => []),
    ]);
    _invAfpList     = Array.isArray(afps)     ? afps     : [];
    _invInvoiceList = Array.isArray(invoices) ? invoices : [];
    // Legacy view: POs that have received a supplier invoice (aggregates)
    _invSupplierPoList = (Array.isArray(pos) ? pos : [])
      .filter(po => po.supplier_invoice_received_at);
    // New AP model: SupplierInvoices ledger rows
    _invSupInvoices = Array.isArray(supInvs) ? supInvs : [];
  } catch (e) {
    console.warn('Invoice tracker data load failed:', e);
  }
  renderInvKpis();
}

// ── KPI tiles ─────────────────────────────────────────────────────────────
function renderInvKpis() {
  const el = document.getElementById('invKpiTiles');
  if (!el) return;

  const outstandingAR = _invInvoiceList
    .filter(i => i.kind === 'invoice' && i.status !== 'Paid' && i.status !== 'Cancelled' && i.status !== 'Void')
    .reduce((s, i) => _r2(s + _r2(i.total_outstanding || i.gross_amount || 0)), 0);

  const today = new Date().toISOString().slice(0, 10);
  const overdueCount = _invInvoiceList
    .filter(i => i.kind === 'invoice' && i.status !== 'Paid' && i.status !== 'Cancelled' && i.status !== 'Void'
                  && i.due_date && i.due_date < today)
    .length;

  const awaitingCert = _invAfpList.filter(a => a.status === 'Submitted').length;

  const supplierUnpaid = _invSupInvoices
    .filter(inv => !inv.paid_at)
    .reduce((s, inv) => s + Number(inv.gross || 0), 0);

  const tile = (label, value, hint) => `
    <div class="card" style="padding:14px 16px">
      <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--muted)">${escapeHtml(label)}</div>
      <div style="font-size:22px;font-weight:700;margin-top:4px">${escapeHtml(value)}</div>
      ${hint ? `<div style="font-size:11px;color:var(--subtle);margin-top:3px">${escapeHtml(hint)}</div>` : ''}
    </div>`;

  el.innerHTML =
    tile('Outstanding AR', `£${outstandingAR.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`, 'Invoices not yet paid') +
    tile('Overdue', String(overdueCount), 'Past due date, unpaid') +
    tile('Awaiting Cert', String(awaitingCert), 'AFPs submitted, no certificate yet') +
    tile('Supplier AP Unpaid', `£${supplierUnpaid.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`, 'Supplier invoices outstanding');
}

// ── Tab switching ─────────────────────────────────────────────────────────
function switchInvTab(tab) {
  _invCurrentTab = tab;
  // Tab buttons
  ['afps','sales','supplier'].forEach(t => {
    const btn = document.getElementById('invTabBtn-' + t);
    if (btn) {
      btn.classList.toggle('active', t === tab);
      btn.style.background = (t === tab) ? 'var(--accent)' : '';
      btn.style.color = (t === tab) ? '#fff' : '';
    }
  });
  // Panels
  ['afps','sales','supplier'].forEach(t => {
    const pane = document.getElementById('invPane-' + t);
    if (pane) pane.style.display = (t === tab) ? '' : 'none';
  });
  // Render the active table
  if (tab === 'afps')      renderInvAfpsTable();
  if (tab === 'sales')     renderInvSalesTable();
  if (tab === 'supplier')  renderInvSupplierTable();
}

// ── Placeholder renderers (full bodies land in Commits 2 + 3) ────────────
// ═════════════════════════════════════════════════════════════════════════
// AFP TWO-PANE RENDER
// ═════════════════════════════════════════════════════════════════════════
let _afpSelectedProjectId = null;  // currently-selected project in the sidebar

function renderInvAfpsTable() {
  // Now a two-pane render. This is called from switchInvTab('afps').
  renderAfpProjectSidebar();
  renderAfpRightPane();
}

function _afpsForProject(projectId) {
  const showCancelled = document.getElementById('afpShowCancelled')?.checked;
  return _invAfpList
    .filter(a => a.project_id === projectId && (showCancelled || a.status !== 'Cancelled'))
    .sort((a, b) => b.application_no - a.application_no);
}

function renderAfpProjectSidebar() {
  const wrap = document.getElementById('afpProjectSidebar');
  if (!wrap) return;
  const q = (document.getElementById('afpProjectSearch')?.value || '').toLowerCase().trim();
  const showCancelled = document.getElementById('afpShowCancelled')?.checked;

  // Group AFPs by project; build a list of projects that have at least 1 AFP
  // (or all AFPs are cancelled if showCancelled is off, in which case they're hidden)
  const visibleAfps = _invAfpList.filter(a => showCancelled || a.status !== 'Cancelled');
  const projectIds = [...new Set(visibleAfps.map(a => a.project_id))];

  // Build entries with project info + counts
  let projects = projectIds.map(pid => {
    const sample = visibleAfps.find(a => a.project_id === pid);
    const afps = visibleAfps.filter(a => a.project_id === pid);
    return {
      id: pid,
      project_number: sample?.project_number || '',
      project_name:   sample?.project_name || '(unnamed)',
      afp_count:      afps.length,
      submitted:      afps.filter(a => a.status === 'Submitted').length,
      certified:      afps.filter(a => a.status === 'Certified').length
    };
  });

  // Filter by search
  if (q) {
    projects = projects.filter(p =>
      (p.project_number + ' ' + p.project_name).toLowerCase().includes(q)
    );
  }

  // Sort alphabetically by project name
  projects.sort((a, b) => (a.project_name || '').localeCompare(b.project_name || ''));

  if (!projects.length) {
    wrap.innerHTML = '<div style="padding:20px 8px;color:var(--subtle);font-size:12px;text-align:center">' +
                     (q ? 'No matches' : 'No AFPs yet — click + New AFP') +
                     '</div>';
    return;
  }

  wrap.innerHTML = projects.map(p => {
    const isSelected = p.id === _afpSelectedProjectId;
    const badges = [];
    if (p.submitted) badges.push(`<span style="display:inline-block;padding:1px 6px;border-radius:8px;font-size:9px;background:rgba(59,130,246,.2);color:#60a5fa">${p.submitted} cert?</span>`);
    if (p.certified) badges.push(`<span style="display:inline-block;padding:1px 6px;border-radius:8px;font-size:9px;background:rgba(255,165,0,.2);color:#ffa500">${p.certified} inv?</span>`);
    return `
      <div onclick="selectAfpProject(${p.id})"
           style="padding:8px 10px;border-radius:6px;cursor:pointer;
                  ${isSelected ? 'background:var(--surface2);border-left:3px solid var(--accent)' : 'border-left:3px solid transparent'};
                  font-size:13px"
           onmouseover="if(${p.id}!==_afpSelectedProjectId) this.style.background='var(--surface2)'"
           onmouseout="if(${p.id}!==_afpSelectedProjectId) this.style.background=''">
        <div style="font-family:var(--font-mono);font-weight:600;font-size:11px;color:var(--muted)">${escapeHtml(p.project_number || '')}</div>
        <div style="font-weight:600;margin:2px 0">${escapeHtml(p.project_name)}</div>
        <div style="display:flex;gap:4px;flex-wrap:wrap;align-items:center">
          <span style="font-size:10px;color:var(--subtle)">${p.afp_count} AFP${p.afp_count !== 1 ? 's' : ''}</span>
          ${badges.join(' ')}
        </div>
      </div>`;
  }).join('');
}

function selectAfpProject(projectId) {
  _afpSelectedProjectId = projectId;
  renderAfpProjectSidebar();
  renderAfpRightPane();
}

function renderAfpRightPane() {
  const pane = document.getElementById('afpRightPane');
  if (!pane) return;

  if (!_afpSelectedProjectId) {
    pane.innerHTML = `
      <div class="card" style="padding:60px;text-align:center;color:var(--muted)">
        <div style="font-size:48px;margin-bottom:12px">📋</div>
        <div style="font-weight:600;margin-bottom:6px">Select a project</div>
        <div style="font-size:13px">Pick a project from the left to view its AFPs, or click <b>+ New AFP</b> to start a new application.</div>
      </div>`;
    return;
  }

  const afps = _afpsForProject(_afpSelectedProjectId);
  const projectInfo = _invAfpList.find(a => a.project_id === _afpSelectedProjectId);
  const projectLabel = projectInfo
    ? `${projectInfo.project_number || ''} — ${projectInfo.project_name || ''}`
    : '';

  if (!afps.length) {
    pane.innerHTML = `
      <div class="card" style="padding:14px 16px;margin-bottom:14px">
        <div style="font-size:11px;color:var(--muted);text-transform:uppercase">Project</div>
        <div style="font-weight:700;font-size:16px">${escapeHtml(projectLabel)}</div>
      </div>
      <div class="card" style="padding:40px;text-align:center;color:var(--muted)">
        <div style="font-size:36px;margin-bottom:10px">📄</div>
        <div style="font-weight:600;margin-bottom:6px">No AFPs for this project yet</div>
        <button class="btn btn-primary" onclick="openNewAfpModal(${_afpSelectedProjectId})">+ Create First AFP</button>
      </div>`;
    return;
  }

  pane.innerHTML = `
    <div class="card" style="padding:14px 16px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:center">
      <div>
        <div style="font-size:11px;color:var(--muted);text-transform:uppercase">Project</div>
        <div style="font-weight:700;font-size:16px">${escapeHtml(projectLabel)}</div>
      </div>
      <button class="btn btn-primary" onclick="openNewAfpModal(${_afpSelectedProjectId})">+ New AFP</button>
    </div>
    <div style="display:flex;flex-direction:column;gap:10px">
      ${afps.map(_renderAfpCard).join('')}
    </div>`;
}

function _renderAfpCard(a) {
  const cancelled = a.status === 'Cancelled';
  const period = a.period_start && a.period_end
    ? `${new Date(a.period_start).toLocaleDateString('en-GB')} – ${new Date(a.period_end).toLocaleDateString('en-GB')}`
    : (a.period_label || '');
  const finalBadge = a.is_final
    ? `<span style="display:inline-block;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:600;background:rgba(208,2,27,.15);color:var(--red)">FINAL</span>`
    : '';
  return `
    <div class="card" style="padding:12px 14px;cursor:pointer;${cancelled ? 'opacity:.5' : ''}"
         onclick="openAfpDetail(${a.id})"
         onmouseover="this.style.background='var(--surface2)'"
         onmouseout="this.style.background=''">
      <div style="display:grid;grid-template-columns:90px 1fr 130px 130px 110px;gap:10px;align-items:center">
        <div>
          <div style="font-family:var(--font-mono);font-weight:700;font-size:15px">${escapeHtml(a.ref || '')}</div>
          <div style="display:flex;gap:4px;margin-top:3px">${finalBadge}</div>
        </div>
        <div>
          <div style="font-size:11px;color:var(--muted);text-transform:uppercase">Period</div>
          <div style="font-size:13px">${escapeHtml(period) || '—'}</div>
        </div>
        <div style="text-align:right">
          <div style="font-size:11px;color:var(--muted);text-transform:uppercase">Applied Gross</div>
          <div style="font-weight:600">£${Number(a.applied_gross || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 })}</div>
        </div>
        <div style="text-align:right">
          <div style="font-size:11px;color:var(--muted);text-transform:uppercase">Certified</div>
          <div style="font-weight:600">${a.certified_gross != null ? '£' + Number(a.certified_gross).toLocaleString('en-GB', { minimumFractionDigits: 2 }) : '—'}</div>
          ${(() => {
            if (a.certified_value_net == null || (a.status !== 'Certified' && a.status !== 'Invoiced')) return '';
            const diff = Number(a.applied_value_net || 0) - Number(a.certified_value_net || 0);
            return diff > 0.01
              ? `<div style="display:inline-block;margin-top:3px;padding:1px 7px;border-radius:9px;font-size:10px;font-weight:700;background:rgba(208,2,27,.15);color:var(--red)">▼ PAYLESS £${diff.toLocaleString('en-GB', { minimumFractionDigits: 2 })}</div>`
              : '';
          })()}
        </div>
        <div style="text-align:right">
          ${a.status === 'Certified'
            ? `<span style="display:inline-block;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:rgba(62,207,142,.2);color:var(--green)">✓ READY TO INVOICE</span>`
            : `${invStatusBadge(a.status)}`}
          ${a.invoice_ref ? `<div style="font-size:10px;color:var(--subtle);margin-top:3px">→ ${escapeHtml(a.invoice_ref)}</div>` : ''}
        </div>
      </div>
    </div>`;
}

// ═══════════════════════════════════════════════════════════════════════════
// AGED DEBT — outstanding sales invoices bucketed by days overdue
// ═══════════════════════════════════════════════════════════════════════════
let _invAgedCollapsed = false;
let _invAgedExpanded = new Set();   // customer keys with expanded invoice rows

function toggleInvAgedDebt() {
  _invAgedCollapsed = !_invAgedCollapsed;
  const body = document.getElementById('invAgedBody');
  const tiles = document.getElementById('invAgedTiles');
  const chev = document.getElementById('invAgedChevron');
  if (body)  body.style.display  = _invAgedCollapsed ? 'none' : '';
  if (tiles) tiles.style.display = _invAgedCollapsed ? 'none' : 'grid';
  if (chev)  chev.textContent    = _invAgedCollapsed ? '▶' : '▼';
}

const _INV_AGED_BUCKETS = [
  { key: 'current', label: 'Not yet due', color: 'var(--green)' },
  { key: 'b30',     label: '1–30 days',   color: '#60a5fa' },
  { key: 'b60',     label: '31–60 days',  color: '#ffa500' },
  { key: 'b90',     label: '61–90 days',  color: '#ff7043' },
  { key: 'b90p',    label: '90+ days',    color: 'var(--red)' }
];

function _invAgedBucketOf(inv, todayMs) {
  const dueStr = _invToDateStr(inv.due_date) || _invToDateStr(inv.invoice_date);
  if (!dueStr) return 'current';
  const days = Math.floor((todayMs - new Date(dueStr + 'T00:00:00').getTime()) / 86400000);
  if (days <= 0)  return 'current';
  if (days <= 30) return 'b30';
  if (days <= 60) return 'b60';
  if (days <= 90) return 'b90';
  return 'b90p';
}

function _invAgedData() {
  const todayMs = new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00').getTime();
  const open = (_invInvoiceList || []).filter(i =>
    i.kind === 'invoice' &&
    (i.status === 'Issued' || i.status === 'Partially Paid') &&
    Number(i.total_outstanding || 0) > 0.005
  );
  const byCustomer = new Map();
  const totals = { current: 0, b30: 0, b60: 0, b90: 0, b90p: 0, all: 0 };
  for (const inv of open) {
    const key = inv.client_company_name || inv.customer_text || '— Unassigned —';
    const bucket = _invAgedBucketOf(inv, todayMs);
    const amt = Number(inv.total_outstanding || 0);
    if (!byCustomer.has(key)) {
      byCustomer.set(key, { customer: key, current: 0, b30: 0, b60: 0, b90: 0, b90p: 0, all: 0, invoices: [] });
    }
    const row = byCustomer.get(key);
    row[bucket] += amt; row.all += amt;
    row.invoices.push({ ...inv, _bucket: bucket, _outstanding: amt });
    totals[bucket] += amt; totals.all += amt;
  }
  const rows = Array.from(byCustomer.values()).sort((a, b) => b.all - a.all);
  for (const r of rows) {
    r.invoices.sort((a, b) => String(a.due_date || a.invoice_date || '').localeCompare(String(b.due_date || b.invoice_date || '')));
  }
  return { rows, totals };
}

function renderInvAgedDebt() {
  const tilesEl = document.getElementById('invAgedTiles');
  const bodyEl = document.getElementById('invAgedBody');
  if (!tilesEl || !bodyEl) return;

  const { rows, totals } = _invAgedData();
  const fmt = v => '£' + Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  tilesEl.innerHTML = _INV_AGED_BUCKETS.map(b => `
    <div style="background:var(--bg-darker);border:1px solid var(--border);border-radius:8px;padding:10px 12px">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.5px;color:var(--muted)">${b.label}</div>
      <div style="font-size:17px;font-weight:700;margin-top:2px;color:${totals[b.key] > 0 ? b.color : 'var(--muted)'}">${fmt(totals[b.key])}</div>
    </div>`).join('') + `
    <div style="background:var(--bg-darker);border:1px solid var(--accent);border-radius:8px;padding:10px 12px">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.5px;color:var(--muted)">Total outstanding</div>
      <div style="font-size:17px;font-weight:700;margin-top:2px;color:var(--accent)">${fmt(totals.all)}</div>
    </div>`;

  if (!rows.length) {
    bodyEl.innerHTML = '<div style="font-size:12px;color:var(--muted)">Nothing outstanding — all issued invoices are paid. 🎉</div>';
    return;
  }

  const th = (t, right) => `<th style="padding:6px 8px;font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;text-align:${right ? 'right' : 'left'};border-bottom:1px solid var(--border)">${t}</th>`;
  const td = (t, right, color, bold) => `<td style="padding:6px 8px;text-align:${right ? 'right' : 'left'};${color ? `color:${color};` : ''}${bold ? 'font-weight:600;' : ''}border-bottom:1px solid var(--border)">${t}</td>`;

  bodyEl.innerHTML = `
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead><tr>
        ${th('Customer')}${_INV_AGED_BUCKETS.map(b => th(b.label, true)).join('')}${th('Total', true)}
      </tr></thead>
      <tbody>
        ${rows.map(r => {
          const key = encodeURIComponent(r.customer);
          const expanded = _invAgedExpanded.has(r.customer);
          const main = `
            <tr style="cursor:pointer" onclick="invAgedToggleCustomer('${key}')"
                onmouseover="this.style.background='var(--surface2)'" onmouseout="this.style.background=''">
              ${td(`${expanded ? '▾' : '▸'} ${escapeHtml(r.customer)}`, false, null, true)}
              ${_INV_AGED_BUCKETS.map(b => td(r[b.key] > 0 ? fmt(r[b.key]) : '—', true, r[b.key] > 0 ? b.color : 'var(--subtle)')).join('')}
              ${td(fmt(r.all), true, null, true)}
            </tr>`;
          const detail = expanded ? r.invoices.map(inv => {
            const bucket = _INV_AGED_BUCKETS.find(b => b.key === inv._bucket);
            return `
            <tr style="cursor:pointer;background:var(--bg-darker)" onclick="openInvoiceDetail(${inv.id})">
              ${td(`<span style="font-family:var(--font-mono);margin-left:18px">${escapeHtml(inv.ref)}</span>
                    <span style="color:var(--muted);font-size:11px;margin-left:8px">due ${inv.due_date ? new Date(inv.due_date).toLocaleDateString('en-GB') : new Date(inv.invoice_date).toLocaleDateString('en-GB')}</span>
                    ${inv.status === 'Partially Paid' ? '<span style="color:#60a5fa;font-size:11px;margin-left:8px">part-paid</span>' : ''}
                    <button class="btn btn-ghost" style="padding:1px 8px;font-size:11px;margin-left:10px"
                            onclick="event.stopPropagation(); chaseInvoiceById(${inv.id})">📨 Chase</button>`)}
              ${_INV_AGED_BUCKETS.map(b => td(b.key === inv._bucket ? fmt(inv._outstanding) : '', true, bucket ? bucket.color : null)).join('')}
              ${td(fmt(inv._outstanding), true)}
            </tr>`;
          }).join('') : '';
          return main + detail;
        }).join('')}
      </tbody>
    </table>`;
}

function invAgedToggleCustomer(encodedKey) {
  const key = decodeURIComponent(encodedKey);
  if (_invAgedExpanded.has(key)) _invAgedExpanded.delete(key);
  else _invAgedExpanded.add(key);
  renderInvAgedDebt();
}

let _invSalesSearchTerm = '';

function renderInvSalesTable() {
  renderInvAgedDebt();
  renderInvRetention();
  const tbody = document.getElementById('invSalesTbody');
  if (!tbody) return;
  if (!_invInvoiceList.length) {
    tbody.innerHTML = `<tr><td colspan="9" class="empty-state" style="padding:40px;text-align:center;color:var(--muted)">
      <div style="font-size:32px;margin-bottom:8px">🧾</div>
      <div style="font-weight:600;margin-bottom:4px">No invoices yet</div>
      <div style="font-size:12px">Click <b>+ New Invoice</b> at the top right to create one.</div>
    </td></tr>`;
    return;
  }
  // Search filter: ref, customer, project number/name, status
  const term = (_invSalesSearchTerm || '').toLowerCase().trim();
  const list = term
    ? _invInvoiceList.filter(i =>
        `${i.ref} ${i.client_company_name || ''} ${i.customer_text || ''} ${i.project_number || ''} ${i.project_name || ''} ${i.status || ''}`
          .toLowerCase().includes(term))
    : _invInvoiceList;
  const countEl = document.getElementById('invSalesSearchCount');
  if (countEl) countEl.textContent = term ? `${list.length} of ${_invInvoiceList.length}` : '';
  if (term && !list.length) {
    tbody.innerHTML = `<tr><td colspan="9" style="padding:30px;text-align:center;color:var(--muted)">No invoices match "${escapeHtml(term)}"</td></tr>`;
    return;
  }

  tbody.innerHTML = list.map(i => {
    const customer = i.client_company_name || i.customer_text || '—';
    const project  = i.project_number ? `${i.project_number}` : '';
    const kindBadge = i.kind === 'pro_forma' ? `<span style="display:inline-block;padding:1px 6px;border-radius:8px;font-size:10px;background:rgba(255,165,0,.15);color:#ffa500;margin-right:4px">PRO</span> `
                   : i.kind === 'credit_note' ? `<span style="display:inline-block;padding:1px 6px;border-radius:8px;font-size:10px;background:rgba(208,2,27,.15);color:var(--red);margin-right:4px">CN</span> `
                   : i.is_retention_release ? `<span style="display:inline-block;padding:1px 6px;border-radius:8px;font-size:10px;background:rgba(59,130,246,.15);color:#60a5fa;margin-right:4px" title="Retention release">RET</span> `
                   : '';
    return `
      <tr style="cursor:pointer" onclick="openInvoiceDetail(${i.id})"
          onmouseover="this.style.background='var(--surface2)'"
          onmouseout="this.style.background=''">
        <td style="font-family:var(--font-mono);font-weight:600">${kindBadge}${escapeHtml(i.ref)}</td>
        <td>${escapeHtml(customer)}</td>
        <td>${escapeHtml(project)}</td>
        <td>${i.invoice_date ? new Date(i.invoice_date).toLocaleDateString('en-GB') : ''}</td>
        <td>${i.due_date ? new Date(i.due_date).toLocaleDateString('en-GB') : ''}</td>
        <td style="text-align:right">£${Number(i.net_amount || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 })}</td>
        <td style="text-align:right">£${Number(i.vat_amount || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 })}</td>
        <td style="text-align:right">£${Number(i.gross_amount || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 })}</td>
        <td>${invStatusBadge(i.status)}</td>
      </tr>`;
  }).join('');
}

let _invSupplierSearchTerm = '';
let _invSupChip = 'all';   // all | unmatched | unpaid | overdue | paid | dd | cn
let _invSupSortKey = null;  // supplier | po | invref | project | invdate | due | gross | recon | paid
let _invSupSortDir = 1;     // 1 = asc (a→z), -1 = desc (z→a)

function _invSupIsOverdue(inv) {
  if (inv.paid_at || !inv.due_date) return false;
  return String(inv.due_date).slice(0, 10) < new Date().toISOString().slice(0, 10);
}

// Value a column sorts on (string for text columns, number for numeric/date)
function _invSupSortVal(inv, key) {
  switch (key) {
    case 'supplier': return (inv.supplier_name || '').toLowerCase();
    case 'po':       return (inv.po_reference || '').toLowerCase();
    case 'invref':   return (inv.invoice_ref || '').toLowerCase();
    case 'project':  return (inv.job_number || inv.cost_centre || '').toLowerCase();
    case 'invdate':  return inv.invoice_date ? new Date(inv.invoice_date).getTime() : 0;
    case 'due':      return inv.is_dd ? Infinity : (inv.due_date ? new Date(inv.due_date).getTime() : 0);
    case 'gross':    return Number(inv.gross || 0);
    case 'recon':    return inv.po_id ? _invPoRecon(inv) : '';
    case 'paid':     return inv.paid_at ? 1 : 0;
    default:         return '';
  }
}

function invSupSort(key) {
  if (_invSupSortKey === key) _invSupSortDir = -_invSupSortDir;
  else { _invSupSortKey = key; _invSupSortDir = 1; }
  _invSupUpdateSortArrows();
  renderInvSupplierTable();
}

function _invSupUpdateSortArrows() {
  ['supplier','po','invref','project','invdate','due','gross','recon','paid'].forEach(k => {
    const el = document.getElementById('invSupSortArrow-' + k);
    if (el) el.textContent = (_invSupSortKey === k) ? (_invSupSortDir === 1 ? '▲' : '▼') : '';
  });
}

function invSupSetChip(chip) {
  _invSupChip = chip;
  ['all','unmatched','unpaid','overdue','paid','dd','cn'].forEach(c => {
    const el = document.getElementById('invSupChip-' + c);
    if (el) el.classList.toggle('active', c === chip);
  });
  renderInvSupplierTable();
}

function _invSupplierFiltered() {
  let list = _invSupInvoices;
  if (_invSupChip === 'unmatched') list = list.filter(i => !i.po_id);
  else if (_invSupChip === 'unpaid')  list = list.filter(i => !i.paid_at);
  else if (_invSupChip === 'overdue') list = list.filter(i => _invSupIsOverdue(i));
  else if (_invSupChip === 'paid')    list = list.filter(i => i.paid_at);
  else if (_invSupChip === 'dd')      list = list.filter(i => i.is_dd);
  else if (_invSupChip === 'cn')      list = list.filter(i => Number(i.gross) < 0);
  const term = (_invSupplierSearchTerm || '').toLowerCase().trim();
  if (term) {
    list = list.filter(inv =>
      `${inv.supplier_name || ''} ${inv.po_reference || ''} ${(inv.allocations || []).map(a => `${a.po_reference || ''} ${a.job_number || ''}`).join(' ')} ${inv.invoice_ref || ''} ${inv.job_number || ''} ${inv.cost_centre || ''} ${inv.babcock_quote_ref || ''} ${inv.notes || ''} ${inv.paid_at ? 'paid' : 'unpaid'}`
        .toLowerCase().includes(term));
  }
  if (_invSupSortKey) {
    list = list.slice().sort((a, b) => {
      const va = _invSupSortVal(a, _invSupSortKey);
      const vb = _invSupSortVal(b, _invSupSortKey);
      if (va < vb) return -1 * _invSupSortDir;
      if (va > vb) return  1 * _invSupSortDir;
      return 0;
    });
  }
  return list;
}

function _invSupFmtDate(s) {
  if (!s) return '';
  const d = new Date(s);
  return isNaN(d) ? '' : d.toLocaleDateString('en-GB');
}

function renderInvSupplierTable() {
  const tbody = document.getElementById('invSupplierTbody');
  if (!tbody) return;
  // Drop selections for invoices that are now paid / gone
  for (const id of Array.from(_invRemitSelected)) {
    const inv = _invSupInvoices.find(i => i.id === id);
    if (!inv || inv.paid_at) _invRemitSelected.delete(id);
  }
  _invRemitUpdateBtn();
  renderInvAgedCreditors();
  _invSupUpdateSortArrows();

  if (!_invSupInvoices.length) {
    tbody.innerHTML = `<tr><td colspan="11" class="empty-state" style="padding:40px;text-align:center;color:var(--muted)">
      <div style="font-size:32px;margin-bottom:8px">📥</div>
      <div style="font-weight:600;margin-bottom:4px">No supplier invoices yet</div>
      <div style="font-size:12px;margin-bottom:14px">Attach one to a PO, or add one manually.</div>
      <button class="btn btn-primary" onclick="openSupAddInvoiceModal()">+ Add Supplier Invoice</button>
    </td></tr>`;
    return;
  }
  const list = _invSupplierFiltered();
  const countEl = document.getElementById('invSupplierSearchCount');
  if (countEl) countEl.textContent =
    ((_invSupplierSearchTerm || '').trim() || _invSupChip !== 'all') ? `${list.length} of ${_invSupInvoices.length}` : '';
  const selAll = document.getElementById('invRemitSelAll');
  if (selAll) {
    const unpaidVisible = list.filter(i => !i.paid_at);
    selAll.checked = unpaidVisible.length > 0 && unpaidVisible.every(i => _invRemitSelected.has(i.id));
    selAll.disabled = unpaidVisible.length === 0;
  }
  if (!list.length) {
    tbody.innerHTML = `<tr><td colspan="11" style="padding:30px;text-align:center;color:var(--muted)">No supplier invoices match the current filter</td></tr>`;
    return;
  }
  const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 });
  // Credit-note register strip — visible when the CN chip is active
  let cnStrip = '';
  if (_invSupChip === 'cn') {
    const tot  = list.reduce((s, i) => s + Math.abs(Number(i.gross) || 0), 0);
    const out  = list.filter(i => !i.paid_at);
    const outV = out.reduce((s, i) => s + Math.abs(Number(i.gross) || 0), 0);
    const unlinked = list.filter(i => !i.credits_invoice_id).length;
    cnStrip = `<tr><td colspan="11" style="padding:8px 12px;background:rgba(239,68,68,.06);border-bottom:1px solid var(--border);font-size:12px">
      <strong>${list.length}</strong> credit note${list.length === 1 ? '' : 's'} · £${fmt2(tot)} total
      · <span style="color:#fbbf24;font-weight:600">£${fmt2(outV)} outstanding (${out.length})</span>
      · <span style="color:var(--green);font-weight:600">£${fmt2(tot - outV)} settled</span>
      ${unlinked ? ` · <span style="color:#fbbf24">${unlinked} not linked to an invoice</span>` : ''}
    </td></tr>`;
  }
  tbody.innerHTML = cnStrip + list.map(inv => {
    const overdue = _invSupIsOverdue(inv);
    const isCN = Number(inv.gross) < 0;
    const cnOrig = (isCN && inv.credits_invoice_id) ? _invSupInvoices.find(x => x.id === inv.credits_invoice_id) : null;
    const cnSub = !isCN ? '' : (cnOrig || inv.credits_invoice_id
      ? `<div style="font-size:10px;color:var(--muted)">credits ${escapeHtml((cnOrig && cnOrig.invoice_ref) || ('#' + inv.credits_invoice_id))} <a href="javascript:void(0)" onclick="invCnLink(${inv.id})" title="Change linked invoice" style="text-decoration:none">✏️</a></div>`
      : `<div style="font-size:10px"><a href="javascript:void(0)" onclick="invCnLink(${inv.id})" style="color:#fbbf24;text-decoration:none" title="Which invoice does this credit note relate to?">⚠ not linked — link to invoice</a></div>`);
    const allocs = Array.isArray(inv.allocations) ? inv.allocations : [];
    const poCell = allocs.length > 1
      ? `<span style="font-family:var(--font-mono);font-weight:600" title="${escapeHtml(allocs.map(a => `${a.po_reference || ('#' + a.po_id)} £${Number(a.net != null ? a.net : a.gross).toFixed(2)}`).join(' · '))}">${escapeHtml(allocs[0].po_reference || ('#' + allocs[0].po_id))} <span style="display:inline-block;padding:1px 6px;border-radius:8px;font-size:10px;font-weight:700;background:rgba(96,165,250,.15);color:#60a5fa">🔀 +${allocs.length - 1}</span></span>`
      : inv.po_id
      ? `<span style="font-family:var(--font-mono);font-weight:600">${escapeHtml(inv.po_reference || ('#' + inv.po_id))}</span>`
      : `<span style="display:inline-block;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600;background:rgba(255,165,0,.15);color:#ffa500">no PO</span>`;
    const dueCell = inv.is_dd
      ? `<span style="font-size:11px;color:var(--muted)">DD</span>`
      : (inv.due_date
          ? `<span style="${overdue ? 'color:var(--red);font-weight:600' : ''}">${_invSupFmtDate(inv.due_date)}</span>`
          : '<span style="color:var(--muted)">—</span>');
    const fileLink = inv.sharepoint_file_url
      ? ` <a href="${escapeHtml(inv.sharepoint_file_url)}" target="_blank" title="Open invoice file" style="text-decoration:none">📎</a>` : '';
    return `
    <tr>
      <td style="text-align:center">${inv.paid_at ? '' :
        `<input type="checkbox" ${_invRemitSelected.has(inv.id) ? 'checked' : ''}
                onchange="invRemitToggle(${inv.id}, this.checked)" title="Select">`}</td>
      <td>${escapeHtml(inv.supplier_name || '')}${inv.invoice_type === 'subcontractor' ? ' <span style="display:inline-block;padding:1px 6px;border-radius:8px;font-size:10px;font-weight:600;background:rgba(147,112,219,.18);color:#b596e8" title="Subcontractor — CIS deduction £' + Number(inv.cis_deduction || 0).toFixed(2) + '">CIS</span>' : ''}</td>
      <td>${escapeHtml(inv.invoice_ref || '')}${isCN ? ` <span style="display:inline-block;padding:1px 6px;border-radius:8px;font-size:10px;font-weight:700;background:rgba(239,68,68,.18);color:#f87171" title="Credit note">CN</span>` : ''}${fileLink}${cnSub}</td>
      <td>${poCell}</td>
      <td>${escapeHtml(inv.job_number || inv.cost_centre || '')}${inv.babcock_quote_ref ? ` <span style="font-size:10px;color:var(--muted);font-family:var(--font-mono)">${escapeHtml(inv.babcock_quote_ref)}</span>` : ''}</td>
      <td>${_invSupFmtDate(inv.invoice_date)}</td>
      <td>${dueCell}</td>
      <td style="text-align:right;${Number(inv.gross) < 0 ? 'color:#f87171;font-weight:600' : ''}">£${fmt2(inv.gross)}</td>
      <td>${inv.po_id ? invStatusBadge(_invPoRecon(inv)) : ''}</td>
      <td>${inv.paid_at ? `<span style="color:var(--green);font-weight:600" title="${escapeHtml(inv.paid_ref || '')}">✓ ${isCN ? 'Settled' : 'Paid'}</span>
        <div style="font-size:10px;color:var(--muted)">${_invSupFmtDate(inv.paid_at)}${inv.run_ref ? ' · ' + escapeHtml(inv.run_ref) : (inv.paid_ref ? ' · ' + escapeHtml(inv.paid_ref) : '')}</div>` :
        (isCN ? '<span style="font-size:11px;color:#fbbf24;font-weight:600" title="Credit not yet refunded or offset against a payment">⏳ outstanding</span>' : '')}</td>
      <td style="text-align:center;white-space:nowrap">${inv.paid_at ?
        `<button class="btn btn-ghost" style="padding:2px 6px;font-size:11px" title="Undo payment — mark unpaid"
                 onclick="undoSupInvoicePaid(${inv.id})">↩</button>` :
        `${isCN ? `<button class="btn btn-ghost" style="padding:2px 6px;font-size:11px;color:var(--green)"
                 title="Mark settled — credit refunded to the bank (offsets in a payment run settle automatically)"
                 onclick="invCnMarkSettled(${inv.id})">✓</button>` : ''}<button class="btn btn-ghost" style="padding:2px 6px;font-size:11px"
                 title="Amend invoice" onclick="openSupAddInvoiceModal(${inv.id})">✏️</button>
         <button class="btn btn-ghost" style="padding:2px 6px;font-size:11px;color:var(--red)"
                 title="Delete invoice" onclick="deleteSupInvoice(${inv.id})">🗑</button>`}</td>
    </tr>`;
  }).join('');
}

// PO-level reconciliation shown per row (all rows of the same PO share it)
function _invPoRecon(inv) {
  if (!inv.po_id) return 'unmatched';
  const poTotal = Number(inv.po_total_value || 0);
  if (!poTotal) return 'unmatched';
  const sum = _invSupInvoices.filter(i => i.po_id === inv.po_id)
                             .reduce((s, i) => _r2(s + _r2(i.gross)), 0);
  if (Math.abs(sum - poTotal) <= 1.00) return 'matched';
  if (sum > poTotal + 1.00) return 'discrepancy';
  return 'unmatched';
}

// ── Credit-note register (CN chip in the supplier ledger) ──────────────────
// A CN is any negative-gross row. "Settled" = paid_at set: payment runs set
// it automatically when the CN nets off a run; a cash refund from the
// supplier is marked manually via invCnMarkSettled. invCnLink stores/edits
// credits_invoice_id so every CN can be justified against its invoice.

async function invCnLink(id) {
  const inv = _invSupInvoices.find(i => i.id === id);
  if (!inv) return;
  const candidates = _invSupInvoices
    .filter(x => x.id !== id && String(x.supplier_id) === String(inv.supplier_id) && Number(x.gross) >= 0)
    .sort((a, b) => new Date(b.invoice_date || 0) - new Date(a.invoice_date || 0));
  if (!candidates.length) {
    toast('No invoices from this supplier in the ledger yet — import the original invoice first.', 'info');
    return;
  }
  const opts = candidates.map(x =>
    `<option value="${x.id}"${Number(inv.credits_invoice_id) === x.id ? ' selected' : ''}>${escapeHtml(x.invoice_ref || ('#' + x.id))} · ${_invSupFmtDate(x.invoice_date)} · £${Number(x.gross || 0).toFixed(2)}</option>`).join('');
  const ok = await bamaConfirm({
    title: 'Link credit note to invoice',
    body: `<div style="font-size:12px;line-height:1.5;margin-bottom:10px">${escapeHtml(inv.invoice_ref || ('#' + id))} · ${escapeHtml(inv.supplier_name || '')} · <strong style="color:#f87171">£${Math.abs(Number(inv.gross || 0)).toFixed(2)} credit</strong> — which invoice does it relate to?</div>
      <select id="cnLinkSel" style="width:100%;padding:7px 8px;background:var(--card);color:var(--text);border:1px solid var(--border);border-radius:6px;font-size:12px">${opts}</select>`,
    confirmText: 'Link', icon: '&#128279;'
  });
  if (!ok) return;
  const sel = parseInt(document.getElementById('cnLinkSel')?.value);
  if (!sel) return;
  setLoading(true);
  try {
    await api.put(`/api/supplier-invoices/${id}`, { credits_invoice_id: sel });
    toast('Credit note linked ✓', 'success');
    await loadInvoicingData();
  } catch (e) {
    toast('Link failed — ' + e.message, 'error');
  } finally { setLoading(false); }
}

async function invCnMarkSettled(id) {
  const inv = _invSupInvoices.find(i => i.id === id);
  if (!inv) return;
  const ok = await bamaConfirm({
    title: 'Mark credit note settled',
    body: `<div style="font-size:12px;line-height:1.5;margin-bottom:10px">${escapeHtml(inv.invoice_ref || ('#' + id))} · ${escapeHtml(inv.supplier_name || '')} · <strong style="color:#f87171">£${Math.abs(Number(inv.gross || 0)).toFixed(2)} credit</strong><br>
      <span style="color:var(--muted)">Use this when the supplier has refunded the money to the bank. Credits offset against a payment run are settled by the run automatically.</span></div>
      <label style="display:block;font-size:11px;color:var(--muted);margin-bottom:3px">Settled date</label>
      <input type="date" id="cnSettleDate" value="${new Date().toISOString().slice(0, 10)}" style="width:100%;padding:7px 8px;background:var(--card);color:var(--text);border:1px solid var(--border);border-radius:6px;font-size:12px;margin-bottom:8px">
      <label style="display:block;font-size:11px;color:var(--muted);margin-bottom:3px">Reference — how it came back</label>
      <input type="text" id="cnSettleRef" placeholder="e.g. BACS refund 12/08 · seen on statement" style="width:100%;padding:7px 8px;background:var(--card);color:var(--text);border:1px solid var(--border);border-radius:6px;font-size:12px">`,
    confirmText: 'Mark Settled', icon: '&#9989;'
  });
  if (!ok) return;
  const date = document.getElementById('cnSettleDate')?.value || new Date().toISOString().slice(0, 10);
  const ref  = (document.getElementById('cnSettleRef')?.value || '').trim() || 'refund received';
  setLoading(true);
  try {
    await api.put(`/api/supplier-invoices/${id}`, { paid_at: date, paid_ref: ref });
    toast('Credit note marked settled ✓', 'success');
    await loadInvoicingData();
  } catch (e) {
    toast('Failed — ' + e.message, 'error');
  } finally { setLoading(false); }
}

async function undoSupInvoicePaid(id) {
  const inv = _invSupInvoices.find(i => i.id === id);
  if (!inv) return;
  const okGo = await bamaConfirm({
    title: 'Undo payment?',
    message: `Mark ${inv.invoice_ref || '#' + id} (£${Number(inv.gross || 0).toFixed(2)}) from ${inv.supplier_name || 'supplier'} as UNPAID again?\n\nCurrently: paid ${inv.paid_at ? new Date(inv.paid_at).toLocaleDateString('en-GB') : ''}${inv.paid_ref ? ' · ' + inv.paid_ref : ''}${inv.run_ref ? ' · run ' + inv.run_ref : ''}. It will go back into aged creditors, statement checks and BACS runs.`,
    confirmText: 'Mark Unpaid'
  });
  if (!okGo) return;
  setLoading(true);
  try {
    await api.put(`/api/supplier-invoices/${id}`, {
      paid_at: null, paid_by: null, paid_ref: null, payment_run_id: null
    });
    toast('Payment undone — invoice is unpaid again ✓', 'success');
    await loadInvoicingData();
    renderInvSupplierTable();
  } catch (e) {
    toast('Undo failed: ' + (e.message || 'unknown error'), 'error');
  } finally { setLoading(false); }
}

async function deleteSupInvoice(id) {
  const inv = _invSupInvoices.find(i => i.id === id);
  if (!inv) return;
  const okGo = await bamaConfirm({
    title: 'Delete supplier invoice?',
    message: `Delete invoice ${inv.invoice_ref || '#' + id} (£${Number(inv.gross || 0).toFixed(2)}) from ${inv.supplier_name || 'supplier'}? The PO reconciliation will be recalculated.`,
    confirmText: 'Delete', danger: true
  });
  if (!okGo) return;
  setLoading(true);
  try {
    await api.delete(`/api/supplier-invoices/${id}`);
    toast('Invoice deleted', 'success');
    await loadInvoicingData();
    renderInvSupplierTable();
  } catch (e) {
    toast('Delete failed: ' + (e.message || 'unknown error'), 'error');
  } finally { setLoading(false); }
}

// ── Aged creditors — mirrors the sales Aged Debt view (who we owe most) ────
let _invAgedCredOpen = true;
let _invApAgedExpanded = new Set();
let _invApAgedSortKey = 'all';  // supplier | current | b30 | b60 | b90 | b90p | all
let _invApAgedSortDir = -1;     // default: biggest total first

function invApAgedSort(key) {
  if (_invApAgedSortKey === key) _invApAgedSortDir = -_invApAgedSortDir;
  else { _invApAgedSortKey = key; _invApAgedSortDir = (key === 'supplier') ? 1 : -1; }
  renderInvAgedCreditors();
}

function toggleInvAgedCreditors() {
  _invAgedCredOpen = !_invAgedCredOpen;
  const body = document.getElementById('invAgedCredBody');
  const chev = document.getElementById('invAgedCredChevron');
  if (body) body.style.display = _invAgedCredOpen ? '' : 'none';
  if (chev) chev.textContent = _invAgedCredOpen ? '▼' : '▶';
}

function _invApAgedBucketOf(inv, todayMs) {
  const dueStr = inv.due_date ? String(inv.due_date).slice(0, 10)
               : (inv.invoice_date ? String(inv.invoice_date).slice(0, 10) : null);
  if (!dueStr) return 'current';
  const dueMs = new Date(dueStr + 'T00:00:00').getTime();
  const days = Math.floor((todayMs - dueMs) / 86400000);
  if (days <= 0) return 'current';
  if (days <= 30) return 'b30';
  if (days <= 60) return 'b60';
  if (days <= 90) return 'b90';
  return 'b90p';
}

function _invApAgedData() {
  const todayMs = new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00').getTime();
  const open = (_invSupInvoices || []).filter(i => !i.paid_at && Number(i.gross || 0) > 0.005);
  const bySupplier = new Map();
  const totals = { current: 0, b30: 0, b60: 0, b90: 0, b90p: 0, all: 0 };
  for (const inv of open) {
    const key = inv.supplier_name || '— Unknown —';
    const bucket = inv.is_dd ? 'current' : _invApAgedBucketOf(inv, todayMs);
    const amt = Number(inv.gross || 0);
    if (!bySupplier.has(key)) {
      bySupplier.set(key, { supplier: key, current: 0, b30: 0, b60: 0, b90: 0, b90p: 0, all: 0, invoices: [] });
    }
    const row = bySupplier.get(key);
    row[bucket] += amt; row.all += amt;
    row.invoices.push({ ...inv, _bucket: bucket, _outstanding: amt });
    totals[bucket] += amt; totals.all += amt;
  }
  const rows = Array.from(bySupplier.values()).sort((a, b) => {
    let va, vb;
    if (_invApAgedSortKey === 'supplier') {
      va = (a.supplier || '').toLowerCase(); vb = (b.supplier || '').toLowerCase();
      if (va < vb) return -1 * _invApAgedSortDir;
      if (va > vb) return  1 * _invApAgedSortDir;
      return 0;
    }
    va = a[_invApAgedSortKey] || 0; vb = b[_invApAgedSortKey] || 0;
    return (va - vb) * _invApAgedSortDir;
  });
  for (const r of rows) {
    r.invoices.sort((a, b) => String(a.due_date || a.invoice_date || '').localeCompare(String(b.due_date || b.invoice_date || '')));
  }
  return { rows, totals };
}

function renderInvAgedCreditors() {
  const tilesEl = document.getElementById('invAgedCredTiles');
  const bodyEl = document.getElementById('invAgedCredBody');
  if (!tilesEl || !bodyEl) return;

  const { rows, totals } = _invApAgedData();
  const fmt = v => '£' + Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  tilesEl.innerHTML = _INV_AGED_BUCKETS.map(b => `
    <div style="background:var(--bg-darker);border:1px solid var(--border);border-radius:8px;padding:10px 12px">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.5px;color:var(--muted)">${b.label}</div>
      <div style="font-size:17px;font-weight:700;margin-top:2px;color:${totals[b.key] > 0 ? b.color : 'var(--muted)'}">${fmt(totals[b.key])}</div>
    </div>`).join('') + `
    <div style="background:var(--bg-darker);border:1px solid var(--accent);border-radius:8px;padding:10px 12px">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.5px;color:var(--muted)">Total we owe</div>
      <div style="font-size:17px;font-weight:700;margin-top:2px;color:var(--accent)">${fmt(totals.all)}</div>
    </div>`;

  if (!rows.length) {
    bodyEl.innerHTML = '<div style="font-size:12px;color:var(--muted)">Nothing outstanding — every supplier invoice is paid. 🎉</div>';
    return;
  }

  const arrow = k => _invApAgedSortKey === k ? (_invApAgedSortDir === 1 ? ' ▲' : ' ▼') : '';
  const th = (t, right, sortKey) => `<th style="padding:6px 8px;font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;text-align:${right ? 'right' : 'left'};border-bottom:1px solid var(--border)${sortKey ? ';cursor:pointer;user-select:none' : ''}"${sortKey ? ` onclick="invApAgedSort('${sortKey}')" title="Sort"` : ''}>${t}${sortKey ? arrow(sortKey) : ''}</th>`;
  const td = (t, right, color, bold) => `<td style="padding:6px 8px;text-align:${right ? 'right' : 'left'};${color ? `color:${color};` : ''}${bold ? 'font-weight:600;' : ''}border-bottom:1px solid var(--border)">${t}</td>`;

  bodyEl.innerHTML = `
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead><tr>
        ${th('Supplier', false, 'supplier')}${_INV_AGED_BUCKETS.map(b => th(b.label, true, b.key)).join('')}${th('Total', true, 'all')}
      </tr></thead>
      <tbody>
        ${rows.map(r => {
          const key = encodeURIComponent(r.supplier);
          const expanded = _invApAgedExpanded.has(r.supplier);
          const main = `
            <tr style="cursor:pointer" onclick="invApAgedToggleSupplier('${key}')"
                onmouseover="this.style.background='var(--surface2)'" onmouseout="this.style.background=''">
              ${td(`${expanded ? '▾' : '▸'} ${escapeHtml(r.supplier)}`, false, null, true)}
              ${_INV_AGED_BUCKETS.map(b => td(r[b.key] > 0 ? fmt(r[b.key]) : '—', true, r[b.key] > 0 ? b.color : 'var(--subtle)')).join('')}
              ${td(fmt(r.all), true, null, true)}
            </tr>`;
          const detail = expanded ? r.invoices.map(inv => {
            const bucket = _INV_AGED_BUCKETS.find(b => b.key === inv._bucket);
            return `
            <tr style="cursor:pointer;background:var(--bg-darker)" onclick="openSupAddInvoiceModal(${inv.id})">
              ${td(`<span style="font-family:var(--font-mono);margin-left:18px">${escapeHtml(inv.invoice_ref || inv.po_reference || ('#' + inv.id))}</span>
                    <span style="color:var(--muted);font-size:11px;margin-left:8px">due ${inv.due_date ? new Date(inv.due_date).toLocaleDateString('en-GB') : (inv.is_dd ? 'DD' : '—')}</span>
                    ${inv.invoice_type === 'subcontractor' ? '<span style="color:#b596e8;font-size:11px;margin-left:8px">CIS</span>' : ''}`)}
              ${_INV_AGED_BUCKETS.map(b => td(b.key === inv._bucket ? fmt(inv._outstanding) : '', true, bucket ? bucket.color : null)).join('')}
              ${td(fmt(inv._outstanding), true)}
            </tr>`;
          }).join('') : '';
          return main + detail;
        }).join('')}
      </tbody>
    </table>`;
}

function invApAgedToggleSupplier(encodedKey) {
  const key = decodeURIComponent(encodedKey);
  if (_invApAgedExpanded.has(key)) _invApAgedExpanded.delete(key);
  else _invApAgedExpanded.add(key);
  renderInvAgedCreditors();
}

// ═════════════════════════════════════════════════════════════════════════
// STATEMENT CHECK — reconcile a supplier statement against the ERP ledger
// Claude reads the statement lines; ALL matching/totals are deterministic JS.
// ═════════════════════════════════════════════════════════════════════════
let _stmtFile = null;
let _stmtParsed = null;

async function openStatementCheckModal() {
  _stmtFile = null; _stmtParsed = null;
  const supSel = document.getElementById('stmtSupplier');
  supSel.innerHTML = '<option value="">Loading…</option>';
  document.getElementById('stmtDate').value = new Date().toISOString().slice(0, 10);
  document.getElementById('stmtFileLabel').textContent = 'No statement yet';
  document.getElementById('stmtResults').innerHTML =
    '<div style="padding:24px;text-align:center;color:var(--muted);font-size:12px">Pick the supplier and drop their statement — every line gets checked against the ERP.</div>';
  document.getElementById('invStmtModal').classList.add('active');
  const suppliers = await _invGetSuppliersList();
  supSel.innerHTML = '<option value="">Select supplier…</option>' + suppliers
    .slice().sort((a, b) => String(a.supplier_name).localeCompare(String(b.supplier_name)))
    .map(s => `<option value="${s.id}">${escapeHtml(s.supplier_name)}</option>`).join('');
}

function closeStatementCheckModal() {
  document.getElementById('invStmtModal').classList.remove('active');
}

function stmtDragOver(ev) { ev.preventDefault(); ev.currentTarget.style.borderColor = 'var(--accent)'; }
function stmtDragLeave(ev) { ev.currentTarget.style.borderColor = 'var(--border)'; }
function stmtDrop(ev) {
  ev.preventDefault();
  ev.currentTarget.style.borderColor = 'var(--border)';
  const file = ev.dataTransfer.files && ev.dataTransfer.files[0];
  if (file) _stmtHandleFile(file);
}
function onStmtFilePicked(input) {
  const file = input.files && input.files[0] ? input.files[0] : null;
  if (file) _stmtHandleFile(file);
}

async function _stmtHandleFile(file) {
  if (!document.getElementById('stmtSupplier').value) {
    toast('Pick the supplier first', 'error'); return;
  }
  _stmtFile = file;
  const label = document.getElementById('stmtFileLabel');
  label.innerHTML = `<span class="spinner" style="width:12px;height:12px;display:inline-block;vertical-align:middle"></span> Reading ${escapeHtml(file.name)}…`;
  try {
    const dataUri = await _fileToDataUri(file);
    const isImg = file.type.startsWith('image/');
    const result = await callClaude({
      model: 'claude-sonnet-4-6',
      max_tokens: 3000,
      messages: [{
        role: 'user',
        content: [
          isImg
            ? { type: 'image',    source: { type: 'base64', media_type: file.type, data: dataUri.split(',')[1] } }
            : { type: 'document', source: { type: 'base64', media_type: file.type, data: dataUri.split(',')[1] } },
          {
            type: 'text',
            text: `This is a UK supplier statement of account sent to BAMA Fabrication. Extract EVERY line item. Return ONLY JSON, no markdown:
{
  "statement_date": "YYYY-MM-DD or null",
  "lines": [
    { "invoice_ref": "the invoice/document number", "invoice_date": "YYYY-MM-DD or null",
      "due_date": "YYYY-MM-DD or null — the statement's Due Date column if present",
      "amount": 0, "type": "invoice" or "credit" or "payment" }
  ],
  "total_outstanding": "the statement's balance/total due, or null"
}
Rules: amounts as positive numbers; mark credit notes as type "credit" and payments/receipts as type "payment"; everything else is "invoice". Include lines even if partially unreadable — set unknown fields to null.`
          }
        ]
      }]
    });
    const text = (result.content?.find(b => b.type === 'text')?.text || '').trim();
    const s = text.indexOf('{'), e = text.lastIndexOf('}');
    _stmtParsed = JSON.parse(text.slice(s, e + 1));
    label.innerHTML = `${escapeHtml(file.name)} — <span style="color:var(--green);font-weight:600">read ✓</span> (${(_stmtParsed.lines || []).length} lines)`;
    if (_stmtParsed.statement_date) document.getElementById('stmtDate').value = String(_stmtParsed.statement_date).slice(0, 10);
    _stmtReconcile();
  } catch (err) {
    console.error('Statement parse failed', err);
    label.textContent = `${file.name} — couldn't read it`;
    toast('Could not read the statement: ' + (err.message || 'unknown error'), 'error');
  }
}

function _stmtNormRef(r) {
  return String(r || '').toUpperCase().replace(/[^A-Z0-9]/g, '').replace(/^0+/, '');
}

// Deterministic reconciliation — no AI involved past this point
function _stmtReconcile() {
  const supplierId = parseInt(document.getElementById('stmtSupplier').value);
  const box = document.getElementById('stmtResults');
  if (!supplierId || !_stmtParsed) return;

  const ours = _invSupInvoices.filter(i => i.supplier_id === supplierId);
  const oursByRef = new Map();
  for (const inv of ours) {
    const k = _stmtNormRef(inv.invoice_ref);
    if (k) oursByRef.set(k, inv);
  }

  const fmt = v => '£' + Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const lines = (_stmtParsed.lines || []).filter(l => l.type !== 'payment');
  const usedOurIds = new Set();
  const results = [];

  for (const line of lines) {
    const amt = Number(line.amount || 0) * (line.type === 'credit' ? -1 : 1);
    let match = oursByRef.get(_stmtNormRef(line.invoice_ref)) || null;
    if (!match && line.invoice_date) {
      // Fallback: same gross within 2p and invoice date within 5 days
      const lMs = new Date(String(line.invoice_date).slice(0, 10) + 'T00:00:00').getTime();
      match = ours.find(inv => !usedOurIds.has(inv.id)
        && Math.abs(Number(inv.gross || 0) - Math.abs(amt)) <= 0.02
        && inv.invoice_date
        && Math.abs(new Date(String(inv.invoice_date).slice(0, 10) + 'T00:00:00').getTime() - lMs) <= 5 * 86400000) || null;
    }
    if (match) usedOurIds.add(match.id);

    let status, color, note = '';
    if (!match) {
      status = 'NOT IN ERP'; color = 'var(--red)';
      note = 'Missing — chase the supplier for a copy or add it';
    } else if (Math.abs(Number(match.gross || 0) - Math.abs(amt)) > 0.02) {
      status = 'AMOUNT DIFFERS'; color = '#ffa500';
      note = `ERP has ${fmt(match.gross)}`;
    } else if (match.paid_at) {
      status = 'PAID BY US'; color = '#60a5fa';
      note = `Paid ${new Date(match.paid_at).toLocaleDateString('en-GB')}${match.paid_ref ? ' · ' + match.paid_ref : ''} — tell them to allocate it`;
    } else {
      status = 'MATCHED'; color = 'var(--green)';
      note = match.due_date ? `Due ${new Date(match.due_date).toLocaleDateString('en-GB')}` : '';
    }
    results.push({ line, amt, match, status, color, note });
  }

  // Our unpaid invoices for this supplier that the statement doesn't show
  const notOnStatement = ours.filter(inv => !inv.paid_at && !usedOurIds.has(inv.id));

  const stmtTotal = sumMoney(results, r => (r.match && r.match.paid_at ? 0 : r.amt));
  const ourOutstanding = sumMoney(ours.filter(i => !i.paid_at), i => i.gross);
  const claimed = _stmtParsed.total_outstanding != null ? Number(_stmtParsed.total_outstanding) : null;

  // Due-date buckets — supplier terms matter (60d EOM ≠ payable today).
  // Our ledger due_date wins; statement's own due-date column is the fallback.
  const todayStr = new Date().toISOString().slice(0, 10);
  const now = new Date();
  const eomStr = new Date(Date.UTC(now.getFullYear(), now.getMonth() + 1, 0, 12)).toISOString().slice(0, 10);
  const dueBuckets = { overdue: 0, thisMonth: 0, later: 0, noDue: 0 };
  for (const r of results) {
    if (r.match && r.match.paid_at) continue;           // paid — not owed
    const due = (r.match && r.match.due_date) ? String(r.match.due_date).slice(0, 10)
              : (r.line.due_date ? String(r.line.due_date).slice(0, 10) : null);
    if (!due)                dueBuckets.noDue     += r.amt;
    else if (due < todayStr) dueBuckets.overdue   += r.amt;
    else if (due <= eomStr)  dueBuckets.thisMonth += r.amt;
    else                     dueBuckets.later     += r.amt;
  }
  const eomUk = new Date(eomStr + 'T00:00:00').toLocaleDateString('en-GB');

  const counts = {
    matched: results.filter(r => r.status === 'MATCHED').length,
    missing: results.filter(r => r.status === 'NOT IN ERP').length,
    differs: results.filter(r => r.status === 'AMOUNT DIFFERS').length,
    paid:    results.filter(r => r.status === 'PAID BY US').length
  };

  const tile = (label, value, col) => `
    <div style="background:var(--bg-darker);border:1px solid var(--border);border-radius:8px;padding:8px 10px">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.5px;color:var(--muted)">${label}</div>
      <div style="font-size:15px;font-weight:700;margin-top:2px;color:${col || 'inherit'}">${value}</div>
    </div>`;

  const badge = (t, c) => `<span style="display:inline-block;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:${c}22;color:${c}">${t}</span>`;
  const th = t => `<th style="padding:5px 8px;font-size:10px;color:var(--muted);text-transform:uppercase;text-align:left;border-bottom:1px solid var(--border)">${t}</th>`;
  const td = (t, right) => `<td style="padding:5px 8px;border-bottom:1px solid var(--border);${right ? 'text-align:right' : ''}">${t}</td>`;

  box.innerHTML = `
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;margin-bottom:12px">
      ${tile('Matched', counts.matched, 'var(--green)')}
      ${tile('Paid by us', counts.paid, '#60a5fa')}
      ${tile('Amount differs', counts.differs, counts.differs ? '#ffa500' : null)}
      ${tile('Not in ERP', counts.missing, counts.missing ? 'var(--red)' : null)}
      ${tile('Statement says due', claimed != null ? fmt(claimed) : '—')}
      ${tile('We agree owing', fmt(stmtTotal), Math.abs((claimed ?? stmtTotal) - stmtTotal) > 0.02 ? '#ffa500' : 'var(--green)')}
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin-bottom:12px">
      ${tile('Overdue — pay now', fmt(dueBuckets.overdue), dueBuckets.overdue > 0.005 ? 'var(--red)' : null)}
      ${tile('Due by ' + eomUk, fmt(dueBuckets.thisMonth), dueBuckets.thisMonth > 0.005 ? '#ffa500' : null)}
      ${tile('Not yet due (terms)', fmt(dueBuckets.later), 'var(--green)')}
      ${dueBuckets.noDue > 0.005 ? tile('No due date', fmt(dueBuckets.noDue)) : ''}
    </div>
    <div style="font-size:11px;color:var(--subtle);margin-bottom:12px">
      Buckets use OUR computed due dates from the supplier's payment terms (statement's due-date column as fallback for lines not in the ERP).
      "PAID BY US" lines are excluded from every owed figure — that flag comes from the ERP's own payment record (Pay &amp; Remit / BACS run), not from the bank.
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;margin-bottom:14px">
      <thead><tr>${th('Statement line')}${th('Date')}${th('Amount')}${th('Status')}${th('Note')}${th('')}</tr></thead>
      <tbody>${results.map(r => `
        <tr>
          ${td(`<span style="font-family:var(--font-mono)">${escapeHtml(r.line.invoice_ref || '—')}</span>${r.line.type === 'credit' ? ' ' + badge('CREDIT', '#b596e8') : ''}`)}
          ${td(r.line.invoice_date ? new Date(String(r.line.invoice_date).slice(0,10) + 'T00:00:00').toLocaleDateString('en-GB') : '—')}
          ${td(fmt(r.amt), true)}
          ${td(badge(r.status, r.color))}
          ${td(`<span style="font-size:11px;color:var(--muted)">${escapeHtml(r.note)}</span>`)}
          ${td(r.status === 'NOT IN ERP' && r.line.type !== 'credit'
              ? `<button class="btn btn-ghost" style="padding:1px 8px;font-size:10px" onclick="stmtAddMissing(${results.indexOf(r)})">+ Add</button>` : '')}
        </tr>`).join('')}
      </tbody>
    </table>
    ${notOnStatement.length ? `
      <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--muted);font-weight:600;margin-bottom:6px">
        In our ERP but NOT on their statement (${notOnStatement.length})
      </div>
      <table style="width:100%;border-collapse:collapse;font-size:12px">
        <tbody>${notOnStatement.map(inv => `
          <tr>
            ${td(`<span style="font-family:var(--font-mono)">${escapeHtml(inv.invoice_ref || ('#' + inv.id))}</span>`)}
            ${td(inv.invoice_date ? new Date(inv.invoice_date).toLocaleDateString('en-GB') : '—')}
            ${td(fmt(inv.gross), true)}
            ${td(`<span style="font-size:11px;color:var(--muted)">unpaid in ERP — maybe newer than the statement, or a duplicate entry</span>`)}
          </tr>`).join('')}
        </tbody>
      </table>` : ''}`;
}

// "+ Add" on a missing statement line → Add Invoice modal pre-filled
let _stmtLastResults = null;
function stmtAddMissing(idx) {
  const supplierId = document.getElementById('stmtSupplier').value;
  const line = (_stmtParsed.lines || []).filter(l => l.type !== 'payment')[idx];
  if (!line) return;
  closeStatementCheckModal();
  openSupAddInvoiceModal().then(async () => {
    document.getElementById('supAddSupplier').value = supplierId;
    await onSupAddSupplierPicked();
    _supAddUpdateDueHint();
    if (line.invoice_ref)  document.getElementById('supAddRef').value = line.invoice_ref;
    if (line.invoice_date) document.getElementById('supAddDate').value = String(line.invoice_date).slice(0, 10);
    if (line.amount != null) document.getElementById('supAddGross').value = Number(line.amount).toFixed(2);
    toast('Pre-filled from the statement — check it and save', 'success');
  });
}

// ═════════════════════════════════════════════════════════════════════════
// BULK IMPORT — drop a pile of invoice PDFs, Claude reads each one, we
// review the cards and save the lot. Duplicates flagged with "add anyway".
// AI reads only; supplier matching, dup detection and totals = deterministic.
// ═════════════════════════════════════════════════════════════════════════
let _bimpItems = [];       // per-file card state
let _bimpPos = [];         // all POs, filtered client-side per supplier
let _bimpBusy = false;

async function openBulkImportModal() {
  _bimpItems = [];
  _bimpBusy = false;
  document.getElementById('bimpList').innerHTML =
    '<div style="padding:30px;text-align:center;color:var(--muted);font-size:12px">Drop a pile of invoice PDFs above — supplier and subcontractor invoices can be mixed.</div>';
  _bimpUpdateFooter();
  document.getElementById('invBulkImpModal').classList.add('active');
  // Warm the caches
  _invGetSuppliersList();
  api.get('/api/purchase-orders').then(pos => { _bimpPos = Array.isArray(pos) ? pos : []; }).catch(() => { _bimpPos = []; });
}

function closeBulkImportModal() {
  if (_bimpBusy) { toast('Import in progress — wait for it to finish', 'warning'); return; }
  document.getElementById('invBulkImpModal').classList.remove('active');
}

function bimpDragOver(ev) { ev.preventDefault(); ev.currentTarget.style.borderColor = 'var(--accent)'; }
function bimpDragLeave(ev) { ev.currentTarget.style.borderColor = 'var(--border)'; }
function bimpDrop(ev) {
  ev.preventDefault();
  ev.currentTarget.style.borderColor = 'var(--border)';
  if (ev.dataTransfer.files?.length) _bimpAddFiles(ev.dataTransfer.files);
}
function onBimpFilesPicked(input) {
  if (input.files?.length) _bimpAddFiles(input.files);
  input.value = '';
}

async function _bimpAddFiles(fileList) {
  const startIdx = _bimpItems.length;
  for (const file of Array.from(fileList)) {
    _bimpItems.push({ file, status: 'queued', include: true, type: 'supplier',
                      supplierId: '', newSupplier: null, ref: '', date: '', net: '', vat: '',
                      gross: '', labour: '', cisRate: 20, cisDed: '', payable: '', poId: '', dup: null });
  }
  _bimpRenderList();
  // Parse sequentially — claude-proxy has its own retry/backoff
  for (let i = startIdx; i < _bimpItems.length; i++) await _bimpParseOne(i);
}

// ═════════════════════════════════════════════════════════════════════════
// QUICK PO-CREATOR — invoice quotes a P-number the ERP doesn't have
// (human error: PO never raised, or raised without a number). From the bulk
// card the user can create that PO on the spot (booked to a job or cost
// centre, valued at the invoice's own printed figures) or fold the amount
// into an existing PO instead. All values are read off the invoice; VAT is
// pro-rata from the invoice's own net:vat ratio — plain arithmetic.
// ═════════════════════════════════════════════════════════════════════════
let _bimpQcData = null;      // { cc: {code: label}, projects: [{id, project_number, project_name}] }
let _bimpQcLoading = false;

async function _bimpQcLoad() {
  if (_bimpQcData || _bimpQcLoading) return;
  _bimpQcLoading = true;
  try {
    const [settings, projects] = await Promise.all([
      api.get('/api/settings').catch(() => ({})),
      api.get('/api/projects').catch(() => [])
    ]);
    _bimpQcData = {
      cc: (settings && settings.purchase_order_cost_centres) || { '8099': 'Workshop', '5099': 'Office' },
      projects: (Array.isArray(projects) ? projects : [])
        .filter(p => p.status === 'In Progress')
        .sort((a, b) => String(b.project_number || '').localeCompare(String(a.project_number || '')))
    };
  } finally {
    _bimpQcLoading = false;
    _bimpItems.forEach((_, idx) => _bimpRenderCard(idx)); // enable the selects
  }
}

function _bimpQcBookOptions(label) {
  if (!_bimpQcData) return '<option value="">loading jobs…</option>';
  const cc = Object.entries(_bimpQcData.cc)
    .map(([code, lab]) => `<option value="cc:${code}">${escapeHtml(code)} — ${escapeHtml(lab)}</option>`).join('');
  const pj = _bimpQcData.projects
    .map(p => `<option value="pj:${p.id}">${escapeHtml(p.project_number || ('#' + p.id))} — ${escapeHtml((p.project_name || '').slice(0, 40))}</option>`).join('');
  // Stated P-number is KEPT on the created PO; name-tagged lines get a brand
  // new PO with the next free number (we have no orders starting with names).
  const head = _isPoRef(label)
    ? `➕ create ${escapeHtml(label)} (keeps this number) — book to…`
    : `➕ create new PO (next free number) — book to…`;
  return `<option value="">${head}</option>`
       + (cc ? `<optgroup label="Cost centres">${cc}</optgroup>` : '')
       + (pj ? `<optgroup label="Live projects">${pj}</optgroup>` : '');
}

async function bimpQcCreate(i, idx, val) {
  const it = _bimpItems[i];
  const lo = it && it.poLeftover && it.poLeftover[idx];
  if (!lo || !val) return;
  const [kind, id] = val.split(':');
  const bookLabel = kind === 'cc'
    ? `${id} — ${(_bimpQcData?.cc || {})[id] || 'cost centre'}`
    : (() => { const p = (_bimpQcData?.projects || []).find(x => String(x.id) === id); return p ? `${p.project_number} — ${p.project_name || ''}` : 'project'; })();

  // VAT pro-rata from the invoice's own printed figures (fallback 20%)
  const invNet = parseFloat(it.net), invVat = parseFloat(it.vat);
  const ratio = Number.isFinite(invNet) && invNet > 0 && Number.isFinite(invVat) ? invVat / invNet : 0.2;
  const vat = Math.round(lo.net * ratio * 100) / 100;
  const gross = Math.round((lo.net + vat) * 100) / 100;

  const isRealRef = _isPoRef(lo.label);
  const goAhead = await bamaConfirm({
    title: isRealRef ? `Create PO ${lo.label}?` : `Create a new PO for "${lo.label}"?`,
    message: isRealRef
      ? `A PO with this number isn't in the ERP — probably never raised.\n\nCreate ${lo.label} — keeping this exact number — for this supplier at £${lo.net.toFixed(2)} net (£${gross.toFixed(2)} incl VAT), booked to ${bookLabel}?\n\nYou can edit details in the PO tracker afterwards.`
      : `"${lo.label}" isn't a PO number — someone ordered under a name.\n\nCreate a NEW PO (next free number) for this supplier at £${lo.net.toFixed(2)} net (£${gross.toFixed(2)} incl VAT), booked to ${bookLabel}? The tag "${lo.label}" is kept in the PO description.\n\nYou can edit details in the PO tracker afterwards.`,
    confirmText: 'Create PO'
  });
  if (!goAhead) { _bimpRenderCard(i); return; }

  setLoading(true);
  try {
    const created = await api.post('/api/purchase-orders', {
      ...(isRealRef ? { reference: lo.label } : {}),
      supplier_id: parseInt(it.supplierId),
      ...(kind === 'cc' ? { cost_centre: id } : { project_id: parseInt(id) }),
      total_value: gross,
      vat_rate: Math.round(ratio * 100),
      vat_amount: vat,
      description: `Created from supplier invoice ${it.ref || it.file.name} (bulk import)${isRealRef ? '' : ` — ordered as "${lo.label}"`}`
    });
    _bimpPos.push(created);
    it.poAllocs = it.poAllocs || [];
    it.poAllocs.push({ poId: created.id, ref: created.reference || lo.label, net: lo.net });
    if (!it.poId) it.poId = String(created.id);
    it.poLeftover.splice(idx, 1);
    if (!it.poLeftover.length) it.poLeftover = null;
    if (it.multiPoNote && it.multiPoNote.startsWith('no PO found')) it.multiPoNote = null;
    toast(`PO ${created.reference || lo.label} created ✓`, 'success');
  } catch (e) {
    toast('Could not create the PO: ' + (e.message || 'unknown error'), 'error');
  } finally {
    setLoading(false);
    _bimpRenderCard(i);
    _bimpUpdateFooter();
  }
}

function bimpQcAssign(i, idx, poId) {
  const it = _bimpItems[i];
  const lo = it && it.poLeftover && it.poLeftover[idx];
  if (!lo || !poId) return;
  const po = _bimpPos.find(p => String(p.id) === String(poId));
  if (!po) return;
  it.poAllocs = it.poAllocs || [];
  const existing = it.poAllocs.find(a => String(a.poId) === String(poId));
  if (existing) existing.net = Math.round((existing.net + lo.net) * 100) / 100;
  else it.poAllocs.push({ poId: po.id, ref: po.reference || ('#' + po.id), net: lo.net });
  if (!it.poId) it.poId = String(po.id);
  it.poLeftover.splice(idx, 1);
  if (!it.poLeftover.length) it.poLeftover = null;
  if (it.multiPoNote && it.multiPoNote.startsWith('no PO found')) it.multiPoNote = null;
  _bimpRenderCard(i);
  _bimpUpdateFooter();
}

// Order-reference helpers shared by parse resolution, card render and the
// quick PO-creator: cleaned = uppercase, no spaces, suffix after "/" dropped.
const _poClean = r => String(r || '').toUpperCase().replace(/\s+/g, '').split('/')[0];
const _isPoRef = s => /^P\d{6,8}$/.test(s);

async function _bimpParseOne(i) {
  const it = _bimpItems[i];
  it.status = 'parsing'; _bimpRenderCard(i);
  try {
    const dataUri = await _fileToDataUri(it.file);
    const isImg = it.file.type.startsWith('image/');
    const result = await callClaude({
      model: 'claude-sonnet-4-6',
      max_tokens: 2000,
      messages: [{
        role: 'user',
        content: [
          isImg
            ? { type: 'image',    source: { type: 'base64', media_type: it.file.type, data: dataUri.split(',')[1] } }
            : { type: 'document', source: { type: 'base64', media_type: it.file.type, data: dataUri.split(',')[1] } },
          {
            type: 'text',
            text: `Extract from this UK invoice sent to BAMA Fabrication. It is either a SUPPLIER invoice (VAT invoice from a company) or a SUBCONTRACTOR invoice (individual/small firm charging for labour, often with a CIS deduction like "Less 20%", a UTR number, bank details). Return ONLY JSON, no markdown:
{
  "document_kind": "invoice" or "credit_note" — credit notes say CREDIT NOTE in the header and credit money back to us,
  "credits_invoice_ref": "credit notes only: the original invoice number being credited, e.g. from 'REF TO INVOICE NO 00758726' — else null",
  "invoice_type": "supplier" or "subcontractor",
  "supplier_name": "the company/person that ISSUED and is OWED money on this invoice — the SELLER. This is NOT the customer/recipient.",
  "invoice_ref": "invoice number if shown",
  "invoice_date": "YYYY-MM-DD",
  "net_amount": 0, "vat_amount": 0, "gross_amount": 0,
  "labour_subtotal": "subcontractor: subtotal BEFORE CIS deduction",
  "cis_rate": "subcontractor: deduction % as a number",
  "cis_deduction": "subcontractor: deducted amount",
  "amount_payable": "subcontractor: final amount due",
  "utr_number": "subcontractor: UTR if shown",
  "bank_sort_code": "subcontractor: sort code if shown",
  "bank_account_no": "subcontractor: account number if shown",
  "po_reference": "BAMA's PO reference if shown — starts with P followed by 6-8 digits, e.g. P260501 or P2607101. Suffixes like P260752/8099 or P260768/S1982 mean PO P260752 / P260768 — return just the P-number. When several are shown, the first one.",
  "po_references": ["EVERY distinct BAMA P-number shown anywhere on the invoice — consolidated invoices often quote several"],
  "po_lines": [{"po_reference": "P260501", "net": 5.40}] — one entry PER LINE ITEM when the lines are tagged with an order reference (printed under or beside each line, or as section headings). net = that line's printed total. Repeat the same po_reference for every line belonging to it. If a line's tag is a name or word rather than a P-number (e.g. LESZEK), still return it as po_reference exactly as printed. Copy printed figures exactly — do NO arithmetic. Return null when lines carry no order references.,
  "sold_via": "amazon" if this is an Amazon / Amazon Business marketplace invoice (Amazon branding, amazon.co.uk order number, "Sold by ..." seller line) — otherwise null,
  "amazon_seller": "when sold_via is amazon: the actual seller/merchant name, else null"
}
CRITICAL — who is the supplier:
- The invoice is ADDRESSED TO "Bama Fabrication" / "BAMA Fabrication Ltd" — that is US, the CUSTOMER. NEVER return a Bama/BAMA name as supplier_name.
- The SELLER (supplier_name) is the party on the letterhead/logo who issues the "Sales Invoice", quotes their own VAT number, and gives bank/remittance details for payment. Their name usually appears at the very top (logo) and again in "Bank Details / remittances to". Trading divisions: return the trading entity as shown (e.g. "Laser Profiles" or "WEC Group Ltd").
- If the only company name you can read is a Bama variant, set supplier_name to null rather than guessing.
Classify as subcontractor ONLY when it's labour/days/hours from an INDIVIDUAL and it mentions CIS, a % deduction, or a UTR. A LABOUR AGENCY — a limited company (name ends "Ltd"/"Limited") that supplies named workers by the week/day with NO CIS deduction and no UTR (often reverse-charge or 0% VAT) — is a normal "supplier", NOT a subcontractor. Null anything not clearly shown. Use the final printed totals.`
          }
        ]
      }]
    });
    const text = (result.content?.find(b => b.type === 'text')?.text || '').trim();
    const p = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
    await _bimpApplyParsed(i, p);
    it.status = 'ready';
  } catch (err) {
    console.error('Bulk parse failed for', it.file.name, err);
    it.status = 'error';
    it.error = err.message || 'Could not read the file';
  }
  _bimpRenderCard(i);
  _bimpUpdateFooter();
}

// Post-parse cleanup shared by both import paths:
//  • never let BAMA (the customer) be read as the supplier — that's a misread
//  • when the invoice is Amazon-brokered, the SUPPLIER we track is Amazon
//    (POs are always raised to Amazon), keeping the real seller as a note so
//    it's still searchable. Mutates & returns the parsed object.
function _invNormaliseParsedSupplier(p) {
  if (!p) return p;
  const norm = v => String(v || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const n = norm(p.supplier_name);
  // "bama" / "bamafabrication" / "bamafabricationltd" → the model grabbed the addressee
  if (n && (n === 'bama' || n.startsWith('bamafab'))) {
    p._supplierWasBama = true;   // used to warn the user
    p.supplier_name = null;
  }
  if (p.sold_via === 'amazon') {
    if (p.supplier_name && norm(p.supplier_name) !== 'amazon' && !p.amazon_seller) {
      p.amazon_seller = p.supplier_name;   // preserve what was read as the seller
    }
    p.supplier_name = 'Amazon';            // track & match under Amazon
  }
  return p;
}

async function _bimpApplyParsed(i, p) {
  const it = _bimpItems[i];
  _invNormaliseParsedSupplier(p);
  it.parsed = p;
  it.type = p.invoice_type === 'subcontractor' ? 'subcontractor' : 'supplier';
  it.ref  = p.invoice_ref || '';
  it.date = p.invoice_date ? String(p.invoice_date).slice(0, 10) : '';
  // Date sanity: a mis-read date (e.g. 2008, or a future year) sorts wildly out
  // of place in the date-ordered ledger. Flag it amber so it's checked, not
  // silently saved. Plausible window: 2020-01-01 .. today + 60 days.
  it.dateWarn = false;
  if (it.date) {
    const d = new Date(it.date + 'T00:00:00');
    const floor = new Date('2020-01-01T00:00:00');
    const ceil = new Date(); ceil.setDate(ceil.getDate() + 60);
    it.dateWarn = isNaN(d) || d < floor || d > ceil;
  } else {
    it.dateWarn = true; // no date read at all
  }
  if (it.type === 'subcontractor') {
    it.labour  = p.labour_subtotal != null ? Number(p.labour_subtotal).toFixed(2) : '';
    it.cisRate = p.cis_rate != null && [0, 20, 30].includes(Number(p.cis_rate)) ? Number(p.cis_rate) : 20;
    _bimpCalcCis(it);
    // Trust the printed payable when it disagrees with the maths
    if (p.amount_payable != null && Math.abs(Number(p.amount_payable) - (parseFloat(it.payable) || 0)) > 0.02) {
      it.payable = Number(p.amount_payable).toFixed(2);
      if (p.cis_deduction != null) it.cisDed = Number(p.cis_deduction).toFixed(2);
      it.cisWarn = true;
    }
  } else {
    // Credit notes save as NEGATIVE rows — every sum in the system then nets
    // them off (PO reconciliation, payments due, payment runs). Suppliers
    // print CN amounts positive; the sign is ours.
    it.isCreditNote = p.document_kind === 'credit_note';
    const sign = it.isCreditNote ? -1 : 1;
    const s2 = v => (sign * Math.abs(Number(v))).toFixed(2);
    it.net   = p.net_amount   != null ? s2(p.net_amount)   : '';
    it.vat   = p.vat_amount   != null ? s2(p.vat_amount)   : '';
    it.gross = p.gross_amount != null ? s2(p.gross_amount)
             : (p.net_amount != null || p.vat_amount != null
                ? s2(Number(p.net_amount || 0) + Number(p.vat_amount || 0)) : '');
  }

  // Supplier match — variant-aware (handles initials: "John Taylor Crane Services" ↔ "JT Cranes")
  const suppliers = await _invGetSuppliersList();
  const matched = _bimpMatchSupplier(p.supplier_name, it.type, suppliers);
  if (matched) {
    it.supplierId = String(matched.id);
    // The ERP record is the source of truth for the type — flip the card BOTH ways
    if (matched.is_subcontractor && it.type !== 'subcontractor') _bimpApplyType(it, 'subcontractor');
    else if (!matched.is_subcontractor && it.type === 'subcontractor') _bimpApplyType(it, 'supplier');
  } else if (p.supplier_name) {
    // Will be created on save — badge it clearly. Amazon marketplace sellers
    // get flagged via_amazon + paid-on-account (paid at purchase).
    const viaAmazon = p.sold_via === 'amazon';
    it.newSupplier = {
      supplier_name: p.supplier_name,
      is_subcontractor: it.type === 'subcontractor',
      utr_number: p.utr_number || null,
      cis_rate: it.type === 'subcontractor' ? it.cisRate : null,
      bank_sort_code: p.bank_sort_code || null,
      bank_account_no: p.bank_account_no || null,
      via_amazon: viaAmazon,
      payment_on_account: viaAmazon
    };
  }
  it.viaAmazon = p.sold_via === 'amazon';
  // Existing supplier already flagged on-account? The server will mark it paid.
  if (it.supplierId) {
    const s = (_invSuppliersCache || []).find(x => String(x.id) === String(it.supplierId));
    it.willBePaid = !!(s && s.payment_on_account);
  } else {
    it.willBePaid = !!(it.newSupplier && it.newSupplier.payment_on_account);
  }

  // ── PO match by our reference(s) ───────────────────────────────────────────
  // Preferred path: the AI returns one entry per LINE with its printed total
  // and PO tag (po_lines). JS groups and sums per PO — deterministic
  // arithmetic on printed figures only. Lines tagged with a name instead of a
  // P-number (e.g. "LESZEK") become an unallocated leftover, not a failure.
  it.poAllocs = null;      // [{poId, ref, net}] — resolved split, saved as allocations
  it.poLeftover = null;    // [{label, net}] — read off the invoice but no PO to book it to
  it.multiPoNote = null;   // hint when several POs are quoted but can't be split cleanly
  const _supPosForItem = it.supplierId
    ? _bimpPos.filter(po => String(po.supplier_id) === it.supplierId) : [];
  const _bimpFindPo = (ref) => {
    const want = _poClean(ref);
    return want ? _supPosForItem.find(po => _poClean(po.reference) === want) : null;
  };
  const refs = [...new Set(
    (Array.isArray(p.po_references) && p.po_references.length ? p.po_references : (p.po_reference ? [p.po_reference] : []))
      .map(_poClean).filter(Boolean))];
  const invNet = parseFloat(it.net);
  const lines = Array.isArray(p.po_lines) ? p.po_lines : null;

  if (it.supplierId && lines && lines.length) {
    // Group printed line totals by their (cleaned) tag
    const grouped = new Map();
    const lnSign = it.isCreditNote ? -1 : 1;
    for (const ln of lines) {
      const net = lnSign * Math.abs(Number(ln.net));
      if (!Number.isFinite(net)) continue;
      const c = _poClean(ln.po_reference) || '(no ref)';
      const g = grouped.get(c) || { label: c, net: 0 };
      g.net = Math.round((g.net + net) * 100) / 100;
      grouped.set(c, g);
    }
    const resolved = [], leftover = [];
    for (const g of grouped.values()) {
      const hit = _isPoRef(g.label) ? _bimpFindPo(g.label) : null;
      if (hit) resolved.push({ poId: hit.id, ref: hit.reference, net: g.net });
      else leftover.push({ label: g.label, net: g.net });
    }
    const totalRead = Math.round(
      (resolved.reduce((s, a) => s + a.net, 0) + leftover.reduce((s, a) => s + a.net, 0)) * 100) / 100;
    const sumOk = Number.isFinite(invNet) && Math.abs(totalRead - invNet) <= 1.00;

    if (sumOk) {
      // Figures reconcile — trust the grouping. Anything unbooked (a name tag,
      // or a P-number we don't have) surfaces as an actionable leftover.
      if (resolved.length > 1 || (resolved.length === 1 && leftover.length)) {
        it.poAllocs = resolved;
        it.poId = String(resolved[0].poId);
      } else if (resolved.length === 1) {
        it.poId = String(resolved[0].poId);
      }
      it.poLeftover = leftover.length ? leftover : null;
      const unres = leftover.filter(l => _isPoRef(l.label)).map(l => l.label);
      if (unres.length && !resolved.length)
        it.multiPoNote = `no PO found for ${unres.join(', ')} — create it or add to an existing PO below`;
    } else if (grouped.size) {
      // Lines were read but don't add up to the invoice net — misread figures,
      // don't act on them. Say exactly what was read.
      if (resolved.length) it.poId = String(resolved[0].poId);
      it.multiPoNote = `read ${grouped.size} order refs but the line totals don't reconcile (£${totalRead.toFixed(2)} read vs £${Number.isFinite(invNet) ? invNet.toFixed(2) : '?'} invoice net) — check the figures, save, then 🔗 Match → Split`;
    }
  }

  // Fallback: header-level refs only (no line tags read)
  if (!it.poAllocs && !it.poId && !it.multiPoNote && refs.length && it.supplierId) {
    if (refs.length > 1) {
      const first = _bimpFindPo(refs[0]);
      if (first) it.poId = String(first.id);
      it.multiPoNote = `quotes ${refs.length} POs (${refs.join(', ')}) — save, then 🔗 Match → Split to spread it`;
    } else {
      const hit = _bimpFindPo(refs[0]);
      if (hit) it.poId = String(hit.id);
    }
  }

  // Credit note → find the invoice it credits in the ledger (same supplier,
  // same normalised ref). Prefill the original's PO when the CN quotes none.
  it.creditsInvoiceId = null;
  it.creditsInfo = null;
  if (it.isCreditNote && p.credits_invoice_ref && it.supplierId) {
    const wantRef = _stmtNormRef(p.credits_invoice_ref);
    const orig = wantRef ? _invSupInvoices.find(inv =>
      String(inv.supplier_id) === String(it.supplierId) &&
      _stmtNormRef(inv.invoice_ref) === wantRef) : null;
    if (orig) {
      it.creditsInvoiceId = orig.id;
      it.creditsInfo = `credits invoice ${orig.invoice_ref} (£${Number(orig.gross || 0).toFixed(2)}) ✓`;
      if (!it.poId && !it.poAllocs && orig.po_id) it.poId = String(orig.po_id);
    } else {
      it.creditsInfo = `credits invoice ${p.credits_invoice_ref} — not found in the ledger yet (import the invoice first to link them)`;
    }
  }

  _bimpCheckDup(i);
  await _bimpCheckFileExists(i);
}

// Option (c): warn on the card when a file of the same computed name is already
// in the destination folder (hand-dropped by someone). Non-fatal — any error
// just leaves it.fileExists false so the upload proceeds normally.
async function _bimpCheckFileExists(i) {
  const it = _bimpItems[i];
  it.fileExists = false;
  try {
    // Resolve the same supplier name + folder + filename the save step will use.
    const suppliers = await _invGetSuppliersList();
    const sName = it.supplierId
      ? ((suppliers.find(x => String(x.id) === String(it.supplierId)) || {}).supplier_name || '')
      : (it.newSupplier ? it.newSupplier.supplier_name : '');
    if (!sName) return; // no supplier resolved yet — can't know the folder
    const folder = await _findOrCreateSupplierInvoiceFolder(it.date || new Date().toISOString().slice(0, 10));
    const stamp = sName.replace(/\s+/g, '_').slice(0, 30);
    const ext = (it.file.name.split('.').pop() || 'pdf').toLowerCase();
    const fileName = sanitizeSpFilename(`${it.date || 'undated'}_${stamp}_${it.ref || 'no-ref'}.${ext}`);
    const existing = await _findFileInFolder(folder.id, fileName);
    it.fileExists = !!existing;
    it.forceUpload = false; // default: reuse the existing file
  } catch (_) {
    it.fileExists = false;
  }
  _bimpRenderCard(i);
}

function _bimpCalcCis(it) {
  const labour = parseFloat(it.labour) || 0;
  const ded = +(labour * (Number(it.cisRate) || 0) / 100).toFixed(2);
  it.cisDed = labour ? ded.toFixed(2) : '';
  it.payable = labour ? (labour - ded).toFixed(2) : '';
}

// Re-evaluate the date-plausibility flag after a manual edit in the card.
function _bimpRecheckDate(i) {
  const it = _bimpItems[i];
  if (!it) return;
  if (it.date) {
    const d = new Date(it.date + 'T00:00:00');
    const floor = new Date('2020-01-01T00:00:00');
    const ceil = new Date(); ceil.setDate(ceil.getDate() + 60);
    it.dateWarn = isNaN(d) || d < floor || d > ceil;
  } else {
    it.dateWarn = true;
  }
}

// Duplicate check: same supplier + same normalised ref in the ERP, or an
// identical ref+amount earlier in this batch. Flag, don't block.
// ── Name matching & type override ───────────────────────────────────────────
// Variants of a company name for matching: full squashed form plus forms where
// the leading 1..n-1 words collapse to initials — so "John Taylor Crane Services"
// also yields "jtcraneservices", which substring-matches the ERP's "JT Cranes".
function _bimpNameVariants(raw) {
  const words = String(raw || '').toLowerCase()
    .replace(/\b(ltd|limited|plc|llp|co|company|uk|services|service|and|the)\b/g, ' ')
    .split(/[^a-z0-9]+/).filter(Boolean);
  const out = new Set();
  if (words.length) out.add(words.join(''));
  for (let k = 1; k < words.length; k++) {
    out.add(words.slice(0, k).map(w => w[0]).join('') + words.slice(k).join(''));
  }
  return [...out].filter(v => v.length >= 3);
}

// Deterministic fuzzy match against the suppliers list. Prefers the pool that
// matches `type`, then falls back to the whole list (the ERP record wins on type).
function _bimpMatchSupplier(name, type, suppliers) {
  const list = suppliers || _invSuppliersCache || [];
  const tv = _bimpNameVariants(name);
  if (!tv.length) return null;
  const score = s => {
    const cv = _bimpNameVariants(s.supplier_name);
    if (cv.some(c => tv.includes(c))) return 2;                                   // exact variant hit
    if (cv.some(c => tv.some(t => (t.length >= 6 && c.includes(t)) || (c.length >= 6 && t.includes(c))))) return 1; // substring, length-guarded
    return 0;
  };
  const pool = list.filter(s => type === 'subcontractor' ? s.is_subcontractor : !s.is_subcontractor);
  const rest = list.filter(s => !pool.includes(s));
  for (const grp of [pool, rest]) {
    const exact = grp.find(s => score(s) === 2); if (exact) return exact;
    const partial = grp.find(s => score(s) === 1); if (partial) return partial;
  }
  return null;
}

// Switch a card's type, filling the new type's fields from the parsed invoice
// where they're blank. Never invents figures — only copies what the AI read.
function _bimpApplyType(it, type) {
  it.type = type;
  const p = it.parsed || {};
  if (type === 'subcontractor') {
    if (it.labour == null || it.labour === '') {
      it.labour = p.labour_subtotal != null ? Number(p.labour_subtotal).toFixed(2)
                : p.net_amount != null ? Number(p.net_amount).toFixed(2) : '';
    }
    if (it.cisRate == null || it.cisRate === '') {
      it.cisRate = (p.cis_rate != null && [0, 20, 30].includes(Number(p.cis_rate))) ? Number(p.cis_rate) : 20;
    }
    _bimpCalcCis(it);
    if (p.amount_payable != null && Math.abs(Number(p.amount_payable) - (parseFloat(it.payable) || 0)) > 0.02) {
      it.payable = Number(p.amount_payable).toFixed(2);
      if (p.cis_deduction != null) it.cisDed = Number(p.cis_deduction).toFixed(2);
      it.cisWarn = true;
    }
  } else {
    it.isCreditNote = p.document_kind === 'credit_note';
    const sign = it.isCreditNote ? -1 : 1;
    const s2 = v => (sign * Math.abs(Number(v))).toFixed(2);
    if (it.net   == null || it.net   === '') it.net   = p.net_amount   != null ? s2(p.net_amount)   : (p.labour_subtotal != null ? s2(p.labour_subtotal) : '');
    if (it.vat   == null || it.vat   === '') it.vat   = p.vat_amount   != null ? s2(p.vat_amount)   : '';
    if (it.gross == null || it.gross === '') it.gross = p.gross_amount != null ? s2(p.gross_amount)
      : (p.net_amount != null || p.vat_amount != null ? s2(Number(p.net_amount || 0) + Number(p.vat_amount || 0)) : '');
  }
}

// Badge click — flip supplier ↔ subcontractor when the AI classified it wrong.
function bimpTypeToggle(i) {
  const it = _bimpItems[i];
  if (!it || (it.status !== 'ready')) return;
  const newType = it.type === 'subcontractor' ? 'supplier' : 'subcontractor';
  _bimpApplyType(it, newType);
  // Selected entity from the wrong pool no longer applies
  const sel = (_invSuppliersCache || []).find(x => String(x.id) === String(it.supplierId));
  if (sel && !!sel.is_subcontractor !== (newType === 'subcontractor')) {
    it.supplierId = ''; it.poId = ''; it.poAllocs = null; it.poLeftover = null; it.multiPoNote = null;
  }
  if (it.newSupplier) {
    it.newSupplier.is_subcontractor = newType === 'subcontractor';
    it.newSupplier.cis_rate = newType === 'subcontractor' ? (Number(it.cisRate) || 20) : null;
  }
  // Nothing picked yet? Try the name against the other pool — this is how
  // "John Taylor Crane Services" lands on the existing JT Cranes supplier.
  if (!it.supplierId && it.parsed?.supplier_name) {
    const m = _bimpMatchSupplier(it.parsed.supplier_name, newType);
    if (m) { it.supplierId = String(m.id); it.newSupplier = null; }
  }
  const s = (_invSuppliersCache || []).find(x => String(x.id) === String(it.supplierId));
  it.willBePaid = it.supplierId ? !!(s && s.payment_on_account) : !!(it.newSupplier && it.newSupplier.payment_on_account);
  _bimpCheckDup(i);
  _bimpRenderCard(i);
  _bimpUpdateFooter();
  _bimpCheckFileExists(i);
}

// Live CIS recompute without rebuilding the card (rebuilding kills input focus):
// write the computed figures straight into the sibling inputs.
function _bimpPatchCis(i) {
  const it = _bimpItems[i];
  const d = document.getElementById(`bimp_${i}_cisDed`);  if (d) d.value = it.cisDed  ?? '';
  const pay = document.getElementById(`bimp_${i}_payable`); if (pay) pay.value = it.payable ?? '';
  _bimpUpdateFooter();
}

function _bimpCheckDup(i) {
  const it = _bimpItems[i];
  it.dup = null;
  const nr = _stmtNormRef(it.ref);
  if (!nr) return;
  const amt = parseFloat(it.type === 'subcontractor' ? it.payable : it.gross) || 0;
  const inErp = _invSupInvoices.find(inv =>
    String(inv.supplier_id) === String(it.supplierId) && _stmtNormRef(inv.invoice_ref) === nr);
  if (inErp) {
    it.dup = { where: 'ERP', detail: `${inErp.invoice_ref} · £${Number(inErp.gross || 0).toFixed(2)} · ${inErp.invoice_date ? new Date(inErp.invoice_date).toLocaleDateString('en-GB') : '?'}${inErp.paid_at ? ' · PAID' : ''}`,
               sameAmount: Math.abs(Number(inErp.gross || 0) - amt) <= 0.02 };
    it.include = false; // default OFF for duplicates — tick to add anyway
    return;
  }
  const inBatch = _bimpItems.find((o, j) => j !== i && o.status !== 'error'
    && _stmtNormRef(o.ref) === nr
    && (String(o.supplierId) === String(it.supplierId) || (o.newSupplier && it.newSupplier
        && o.newSupplier.supplier_name === it.newSupplier.supplier_name)));
  if (inBatch) it.dup = { where: 'batch', detail: inBatch.file.name, sameAmount: true };
}

// ── Card rendering ──────────────────────────────────────────────────────────
function _bimpRenderList() {
  const box = document.getElementById('bimpList');
  if (!_bimpItems.length) return;
  box.innerHTML = _bimpItems.map((_, i) => `<div id="bimpCard-${i}"></div>`).join('');
  _bimpItems.forEach((_, i) => _bimpRenderCard(i));
  _bimpUpdateFooter();
}

function _bimpRenderCard(i) {
  const host = document.getElementById(`bimpCard-${i}`);
  if (!host) return;
  const it = _bimpItems[i];
  const fmtIn = (id, label, val, oninput, width) => `
    <div style="${width ? `width:${width}px` : 'flex:1'}">
      <div style="font-size:9px;text-transform:uppercase;color:var(--muted)">${label}</div>
      <input class="field-input" id="bimp_${i}_${id}" style="font-size:12px;padding:4px 8px" value="${escapeHtml(String(val ?? ''))}" ${oninput}>
    </div>`;

  if (it.status === 'queued' || it.status === 'parsing') {
    host.innerHTML = `<div class="card" style="padding:10px 14px;margin-bottom:8px;display:flex;align-items:center;gap:10px">
      <span class="spinner" style="width:14px;height:14px"></span>
      <span style="font-size:12px">${it.status === 'parsing' ? 'Reading' : 'Queued'} — ${escapeHtml(it.file.name)}</span></div>`;
    return;
  }
  if (it.status === 'error') {
    host.innerHTML = `<div class="card" style="padding:10px 14px;margin-bottom:8px;border-color:var(--red)">
      <div style="font-size:12px;color:var(--red)">✗ ${escapeHtml(it.file.name)} — ${escapeHtml(it.error || 'failed')}</div>
      <div style="font-size:11px;color:var(--muted);margin-top:2px">Add it via + Add Invoice instead.</div></div>`;
    return;
  }
  if (it.status === 'saved') {
    host.innerHTML = `<div class="card" style="padding:10px 14px;margin-bottom:8px;border-color:var(--green)">
      <span style="font-size:12px;color:var(--green)">✓ Saved — ${escapeHtml(it.file.name)}</span></div>`;
    return;
  }

  const isSub = it.type === 'subcontractor';
  const suppliers = _invSuppliersCache || [];
  const pool = suppliers.filter(s => isSub ? s.is_subcontractor : !s.is_subcontractor)
    .slice().sort((a, b) => String(a.supplier_name).localeCompare(String(b.supplier_name)));
  const supOptions = `<option value="">${it.newSupplier ? '' : 'Pick…'}</option>` +
    (it.newSupplier ? `<option value="__new__" selected>➕ NEW: ${escapeHtml(it.newSupplier.supplier_name)}</option>` : '') +
    pool.map(s => `<option value="${s.id}" ${String(s.id) === String(it.supplierId) ? 'selected' : ''}>${escapeHtml(s.supplier_name)}</option>`).join('');

  const supPos = _bimpPos.filter(po => String(po.supplier_id) === String(it.supplierId) && po.status !== 'Cancelled');
  const poOptions = '<option value="">— No PO —</option>' + supPos.map(po =>
    `<option value="${po.id}" ${String(po.id) === String(it.poId) ? 'selected' : ''}>${escapeHtml(po.reference || ('#' + po.id))} — £${Number(po.total_value || 0).toFixed(2)}</option>`).join('');

  const dupBanner = it.dup ? `
    <div style="display:flex;align-items:center;gap:10px;background:rgba(255,165,0,.12);border:1px solid #ffa500;border-radius:6px;padding:6px 10px;margin-top:8px">
      <span style="font-size:11px;color:#ffa500;font-weight:600">⚠ ${it.dup.where === 'ERP'
        ? `Already in ERP: ${escapeHtml(it.dup.detail)}${it.dup.sameAmount ? '' : ' (different amount)'}`
        : `Same invoice # as ${escapeHtml(it.dup.detail)} in this batch`}</span>
      <label style="display:flex;align-items:center;gap:5px;font-size:11px;margin-left:auto;white-space:nowrap;cursor:pointer">
        <input type="checkbox" ${it.include ? 'checked' : ''} onchange="_bimpItems[${i}].include=this.checked;_bimpUpdateFooter()">
        add anyway (same # different period happens)
      </label>
    </div>` : '';

  const fileBanner = it.fileExists ? `
    <div style="display:flex;align-items:center;gap:10px;background:rgba(96,165,250,.10);border:1px solid #60a5fa;border-radius:6px;padding:6px 10px;margin-top:8px">
      <span style="font-size:11px;color:#60a5fa;font-weight:600">📎 A file with this name is already in the folder — it will be reused (no duplicate uploaded)</span>
      <label style="display:flex;align-items:center;gap:5px;font-size:11px;margin-left:auto;white-space:nowrap;cursor:pointer">
        <input type="checkbox" ${it.forceUpload ? 'checked' : ''} onchange="_bimpItems[${i}].forceUpload=this.checked">
        upload a fresh copy instead
      </label>
    </div>` : '';

  host.innerHTML = `
    <div class="card" style="padding:12px 14px;margin-bottom:8px;${!it.include && it.dup ? 'opacity:.65;' : ''}border-left:3px solid ${isSub ? '#b596e8' : 'var(--accent)'}">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
        ${it.dup ? '' : `<input type="checkbox" ${it.include ? 'checked' : ''} onchange="_bimpItems[${i}].include=this.checked;_bimpUpdateFooter()" title="Include in save">`}
        <span style="font-size:11px;color:var(--muted);font-family:var(--font-mono)">${escapeHtml(it.file.name)}</span>
        <span style="display:inline-block;padding:1px 8px;border-radius:8px;font-size:10px;font-weight:700;cursor:pointer;user-select:none;background:${isSub ? 'rgba(147,112,219,.18)' : 'rgba(59,130,246,.15)'};color:${isSub ? '#b596e8' : '#60a5fa'}" title="Wrong? Click to switch supplier ↔ subcontractor" onclick="bimpTypeToggle(${i})">${isSub ? '👷 SUBCONTRACTOR (CIS)' : '🏭 SUPPLIER'} ⇄</span>
        ${it.newSupplier ? `<span style="display:inline-block;padding:1px 8px;border-radius:8px;font-size:10px;font-weight:700;background:rgba(62,207,142,.15);color:var(--green)">NEW ${isSub ? 'SUBBIE' : 'SUPPLIER'} — will be created${it.newSupplier.utr_number ? ' · UTR ' + escapeHtml(it.newSupplier.utr_number) : ''}</span>` : ''}
        ${it.isCreditNote ? '<span style="display:inline-block;padding:1px 8px;border-radius:8px;font-size:10px;font-weight:700;background:rgba(239,68,68,.18);color:#f87171">📕 CREDIT NOTE — saves negative</span>' : ''}
        ${it.viaAmazon ? '<span style="display:inline-block;padding:1px 8px;border-radius:8px;font-size:10px;font-weight:700;background:rgba(255,153,0,.18);color:#ff9900">🛒 via AMAZON</span>' : ''}
        ${it.willBePaid ? '<span style="display:inline-block;padding:1px 8px;border-radius:8px;font-size:10px;font-weight:700;background:rgba(62,207,142,.15);color:var(--green)">will land as PAID (on account)</span>' : ''}
        ${it.cisWarn ? '<span style="font-size:10px;color:#ffa500">⚠ printed payable ≠ labour × rate — using the invoice figure</span>' : ''}
        <button class="btn btn-ghost" style="margin-left:auto;padding:1px 8px;font-size:11px;color:var(--red)"
                onclick="_bimpItems.splice(${i},1);_bimpRenderList()">✕</button>
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end">
        <div style="flex:2;min-width:170px">
          <div style="font-size:9px;text-transform:uppercase;color:var(--muted)">${isSub ? 'Subcontractor' : 'Supplier'}</div>
          <select class="field-input" style="font-size:12px;padding:4px 8px" onchange="bimpSupplierPicked(${i}, this.value)">${supOptions}</select>
        </div>
        ${fmtIn('ref', 'Invoice #', it.ref, `oninput="_bimpItems[${i}].ref=this.value" onchange="_bimpCheckDup(${i});_bimpRenderCard(${i});_bimpUpdateFooter()"`, 120)}
        <div style="width:130px">
          <div style="font-size:9px;text-transform:uppercase;color:${it.dateWarn ? '#ffa500' : 'var(--muted)'}">Date${it.dateWarn ? ' ⚠ check' : ''}</div>
          <input type="date" class="field-input" style="font-size:12px;padding:4px 8px${it.dateWarn ? ';border-color:#ffa500' : ''}" value="${escapeHtml(it.date)}"
                 onchange="_bimpItems[${i}].date=this.value;_bimpRecheckDate(${i});_bimpRenderCard(${i})">
        </div>
        ${isSub ? `
          ${fmtIn('labour', 'Labour £', it.labour, `oninput="_bimpItems[${i}].labour=this.value;_bimpCalcCis(_bimpItems[${i}]);_bimpPatchCis(${i})"`, 95)}
          <div style="width:90px">
            <div style="font-size:9px;text-transform:uppercase;color:var(--muted)">CIS rate</div>
            <select class="field-input" style="font-size:12px;padding:4px 8px"
                    onchange="_bimpItems[${i}].cisRate=this.value;_bimpCalcCis(_bimpItems[${i}]);_bimpPatchCis(${i})">
              ${[20, 30, 0].map(r => `<option value="${r}" ${Number(it.cisRate) === r ? 'selected' : ''}>${r}%</option>`).join('')}
            </select>
          </div>
          ${fmtIn('cisDed', 'Deduction £', it.cisDed, `oninput="_bimpItems[${i}].cisDed=this.value"`, 95)}
          ${fmtIn('payable', 'Payable £', it.payable, `oninput="_bimpItems[${i}].payable=this.value;_bimpUpdateFooter()"`, 95)}
        ` : `
          ${fmtIn('net', 'Net £', it.net, `oninput="_bimpItems[${i}].net=this.value"`, 90)}
          ${fmtIn('vat', 'VAT £', it.vat, `oninput="_bimpItems[${i}].vat=this.value"`, 90)}
          ${fmtIn('gross', 'Gross £', it.gross, `oninput="_bimpItems[${i}].gross=this.value;_bimpUpdateFooter()" onchange="_bimpCheckDup(${i});_bimpRenderCard(${i})"`, 95)}
          <div style="flex:1.5;min-width:150px">
            <div style="font-size:9px;text-transform:uppercase;color:var(--muted)">PO</div>
            ${it.poAllocs ? `
              <div style="display:flex;align-items:center;gap:6px;border:1px solid #60a5fa;border-radius:6px;padding:4px 8px;background:rgba(96,165,250,.10)">
                <span style="font-size:11px;color:#60a5fa;font-weight:600" title="${escapeHtml(it.poAllocs.map(a => `${a.ref} £${a.net.toFixed(2)}`).join(' · ') + (it.poLeftover ? ' · unallocated: ' + it.poLeftover.map(l => `${l.label} £${l.net.toFixed(2)}`).join(', ') : ''))}">🔀 split across ${it.poAllocs.length} PO${it.poAllocs.length === 1 ? '' : 's'}</span>
                <button class="btn btn-ghost" style="margin-left:auto;padding:0 6px;font-size:11px" title="Clear the split — pick one PO instead"
                        onclick="_bimpItems[${i}].poAllocs=null;_bimpRenderCard(${i})">✕</button>
              </div>` : `
              <select class="field-input" style="font-size:12px;padding:4px 8px" onchange="_bimpItems[${i}].poId=this.value">${poOptions}</select>`}
          </div>
        `}
      </div>
      ${it.poAllocs ? `<div style="font-size:10px;color:#60a5fa;margin-top:6px">🔀 ${escapeHtml(it.poAllocs.map(a => `${a.ref} £${a.net.toFixed(2)} net`).join(' · '))} — read off the invoice, saved as a split</div>` : ''}
      ${it.poLeftover ? (_bimpQcLoad(), it.poLeftover.map((lo, li) => `
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;background:rgba(255,165,0,.08);border:1px solid rgba(255,165,0,.4);border-radius:6px;padding:5px 10px;margin-top:6px">
          <span style="font-size:11px;color:#ffa500;font-weight:600">⚠ ${escapeHtml(lo.label)} £${lo.net.toFixed(2)} — ${_isPoRef(lo.label) ? 'this PO isn\'t in the ERP' : 'not tied to a PO'}</span>
          <div style="display:flex;gap:6px;margin-left:auto;flex-wrap:wrap">
            <select class="field-input" style="font-size:11px;padding:2px 6px;max-width:280px" ${_bimpQcData ? '' : 'disabled'}
                    onchange="bimpQcCreate(${i}, ${li}, this.value)">${_bimpQcBookOptions(lo.label)}</select>
            <select class="field-input" style="font-size:11px;padding:2px 6px;max-width:220px"
                    onchange="bimpQcAssign(${i}, ${li}, this.value)">
              <option value="">→ add to an existing PO…</option>
              ${_bimpPos.filter(po => String(po.supplier_id) === String(it.supplierId) && po.status !== 'Cancelled')
                        .map(po => `<option value="${po.id}">${escapeHtml(po.reference || ('#' + po.id))}${po.job_number ? ' · ' + escapeHtml(po.job_number) : ''}</option>`).join('')}
            </select>
          </div>
        </div>`).join('')) : ''}
      ${it.creditsInfo ? `<div style="font-size:10px;color:${it.creditsInvoiceId ? 'var(--green)' : '#ffa500'};margin-top:6px">📕 ${escapeHtml(it.creditsInfo)}</div>` : ''}
      ${it.multiPoNote ? `<div style="font-size:10px;color:#ffa500;margin-top:6px">⚠ ${escapeHtml(it.multiPoNote)}</div>` : ''}
      ${dupBanner}
      ${fileBanner}
    </div>`;
}

function bimpSupplierPicked(i, val) {
  const it = _bimpItems[i];
  if (val === '__new__') return; // keep the pending new-supplier entry
  it.newSupplier = null;
  it.supplierId = val;
  it.poId = '';
  it.poAllocs = null;
  it.poLeftover = null;
  it.multiPoNote = null;
  const s = (_invSuppliersCache || []).find(x => String(x.id) === String(val));
  it.willBePaid = !!(s && s.payment_on_account);
  _bimpCheckDup(i);
  _bimpRenderCard(i);
  _bimpUpdateFooter();
  _bimpCheckFileExists(i); // supplier changed → destination folder changed
}

function _bimpUpdateFooter() {
  const ready = _bimpItems.filter(it => it.status === 'ready' && it.include);
  const total = ready.reduce((s, it) => s + (parseFloat(it.type === 'subcontractor' ? it.payable : it.gross) || 0), 0);
  const el = document.getElementById('bimpFooterInfo');
  if (el) el.textContent = ready.length
    ? `${ready.length} invoice${ready.length === 1 ? '' : 's'} ready · £${total.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
    : '';
  const btn = document.getElementById('bimpSaveBtn');
  if (btn) btn.disabled = _bimpBusy || ready.length === 0;
}

// ── Save the batch ──────────────────────────────────────────────────────────
async function bimpSaveAll() {
  const items = _bimpItems.filter(it => it.status === 'ready' && it.include);
  if (!items.length) return;

  // Validation pass first — nothing saves until every ticked card is sound
  for (const it of items) {
    const amt = parseFloat(it.type === 'subcontractor' ? it.payable : it.gross);
    if (!it.supplierId && !it.newSupplier) { toast(`${it.file.name}: pick the ${it.type === 'subcontractor' ? 'subcontractor' : 'supplier'}`, 'error'); return; }
    if (!amt) { toast(`${it.file.name}: amount missing`, 'error'); return; }
  }

  _bimpBusy = true;
  _bimpUpdateFooter();
  setLoading(true);
  let okCount = 0, failCount = 0;
  const createdByName = new Map(); // avoid creating the same new supplier twice

  for (const it of items) {
    const i = _bimpItems.indexOf(it);
    try {
      // 1. Create the new supplier/subcontractor once per name
      let supplierId = it.supplierId ? parseInt(it.supplierId) : null;
      if (!supplierId && it.newSupplier) {
        const keyName = it.newSupplier.supplier_name;
        if (createdByName.has(keyName)) supplierId = createdByName.get(keyName);
        else {
          const created = await api.post('/api/suppliers', {
            ...it.newSupplier,
            notes: it.newSupplier.is_subcontractor ? 'Subcontractor (CIS) — created by bulk import' : 'Created by bulk import'
          });
          supplierId = created.id;
          createdByName.set(keyName, supplierId);
          _invSuppliersCache = null;
          if (Array.isArray(_suppliers)) _suppliers.push(created);
        }
      }

      // 2. File → SharePoint. If a file with the same name is already in the
      // destination folder (someone dropped it there by hand), reuse it rather
      // than uploading a duplicate — unless the user explicitly chose to upload
      // a fresh copy on the review card (it.forceUpload).
      const suppliers = await _invGetSuppliersList();
      const sName = (suppliers.find(x => x.id === supplierId) || {}).supplier_name || 'supplier';
      const folder = await _findOrCreateSupplierInvoiceFolder(it.date || new Date().toISOString().slice(0, 10));
      const stamp = sName.replace(/\s+/g, '_').slice(0, 30);
      const ext = (it.file.name.split('.').pop() || 'pdf').toLowerCase();
      const fileName = sanitizeSpFilename(`${it.date || 'undated'}_${stamp}_${it.ref || 'no-ref'}.${ext}`);
      let driveItem = null;
      if (!it.forceUpload) {
        driveItem = await _findFileInFolder(folder.id, fileName);
      }
      if (!driveItem) {
        driveItem = await uploadFileToFolder(folder.id, fileName, it.file, it.file.type || 'application/octet-stream');
      }

      // 3. Ledger row
      const isSub = it.type === 'subcontractor';
      await api.post('/api/supplier-invoices', {
        supplier_id: supplierId,
        po_id: !isSub && it.poId ? parseInt(it.poId) : null,
        allocations: !isSub && it.poAllocs
          ? it.poAllocs.map(a => ({ po_id: a.poId, net: a.net }))
          : undefined,
        credits_invoice_id: it.creditsInvoiceId || undefined,
        invoice_type: it.type,
        invoice_ref: it.ref || null,
        invoice_date: it.date || null,
        net: isSub ? (parseFloat(it.labour) || null) : (parseFloat(it.net) || null),
        vat: isSub ? null : (parseFloat(it.vat) || null),
        gross: parseFloat(isSub ? it.payable : it.gross),
        labour_gross: isSub ? (parseFloat(it.labour) || null) : null,
        cis_rate: isSub ? Number(it.cisRate) : null,
        cis_deduction: isSub ? (parseFloat(it.cisDed) || 0) : null,
        sharepoint_file_id: driveItem.id,
        sharepoint_file_url: driveItem.webUrl,
        filename: fileName,
        source: 'manual',
        notes: it.viaAmazon && (it.parsed?.amazon_seller)
          ? `Bulk import · via Amazon — seller: ${it.parsed.amazon_seller}`
          : 'Bulk import'
      });

      it.status = 'saved';
      okCount++;
    } catch (err) {
      console.error('Bulk save failed for', it.file.name, err);
      it.status = 'error';
      it.error = 'Save failed: ' + (err.message || 'unknown');
      failCount++;
    }
    _bimpRenderCard(i);
  }

  _bimpBusy = false;
  setLoading(false);
  toast(`Imported ${okCount} invoice${okCount === 1 ? '' : 's'}${failCount ? ` — ${failCount} failed (see the cards)` : ' ✓'}`,
        failCount ? 'error' : 'success');
  await loadInvoicingData();
  renderInvSupplierTable();
  _bimpUpdateFooter();
  if (!failCount && !_bimpItems.some(it => it.status === 'ready')) closeBulkImportModal();
}

// ═════════════════════════════════════════════════════════════════════════
// MATCH TO PO — tick invoices, link them to a PO, over-match guard
// ═════════════════════════════════════════════════════════════════════════
async function openSupMatchModal() {
  const sel = _invRemitSelection();
  if (!sel.length) { toast('Tick at least one invoice first', 'error'); return; }
  const supplierIds = [...new Set(sel.map(i => i.supplier_id))];
  if (supplierIds.length > 1) {
    toast('Matching works one supplier at a time — select invoices from a single supplier', 'error');
    return;
  }
  const supplierId = supplierIds[0];
  const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const netTotal = sumMoney(sel, i => i.net != null ? i.net : i.gross);
  const allHaveNet = sel.every(i => i.net != null);

  document.getElementById('invSupMatchLabel').textContent =
    `${sel.length} invoice${sel.length === 1 ? '' : 's'} from ${sel[0].supplier_name || 'supplier'} — £${fmt2(netTotal)} ${allHaveNet ? 'net' : '(gross — no net figure on some)'}`;

  // Split mode is only offered for a single ticked invoice
  _supMatchMode = 'single';
  _supMatchSplits = new Map();
  const modeWrap = document.getElementById('invSupMatchModeWrap');
  if (modeWrap) modeWrap.style.display = sel.length === 1 ? 'flex' : 'none';
  supMatchSetMode('single');

  // PO list: this supplier's POs with net + already-matched (from allocations)
  const poSel = document.getElementById('invSupMatchPo');
  poSel.innerHTML = '<option value="">Loading POs…</option>';
  document.getElementById('invSupMatchModal').classList.add('active');
  _supMatchPos = [];
  try {
    const pos = await api.get(`/api/purchase-orders?supplier_id=${supplierId}`);
    const active = (pos || []).filter(po => po.status !== 'Cancelled');

    // Matched-so-far per PO from allocations (fallback: legacy single po_id),
    // EXCLUDING the ticked invoices themselves so re-matching reads sanely.
    const selIds = new Set(sel.map(i => i.id));
    const matchedByPo = {};
    for (const inv of _invSupInvoices) {
      if (selIds.has(inv.id)) continue;
      const allocs = Array.isArray(inv.allocations) && inv.allocations.length
        ? inv.allocations
        : (inv.po_id ? [{ po_id: inv.po_id, net: inv.net, gross: inv.gross }] : []);
      for (const a of allocs) {
        matchedByPo[a.po_id] = (matchedByPo[a.po_id] || 0) + Number(a.net != null ? a.net : a.gross || 0);
      }
    }
    _supMatchPos = active.map(po => ({
      ...po,
      _net: _poNet(po),
      _matched: Math.round((matchedByPo[po.id] || 0) * 100) / 100
    })).sort((a, b) => String(b.reference || '').localeCompare(String(a.reference || '')));

    poSel.innerHTML = '<option value="">— Unmatch (no PO) —</option>' + _supMatchPos.map(po => {
      const remaining = Math.max(0, Math.round((po._net - po._matched) * 100) / 100);
      return `<option value="${po.id}">${escapeHtml(po.reference || ('#' + po.id))} — £${fmt2(po._net)} net${po._matched ? ` (£${fmt2(remaining)} left)` : ''}${po.job_number ? ' · ' + escapeHtml(po.job_number) : ''}</option>`;
    }).join('');
    if (_supMatchMode === 'split') _supMatchRenderSplitList();
  } catch (e) {
    poSel.innerHTML = '<option value="">Failed to load POs</option>';
  }

  // Babcock quote dropdown — only for BAMA South West invoices
  const bqSel = document.getElementById('invSupMatchBabcock');
  const bqWrap = document.getElementById('invSupMatchBabcockWrap');
  const isSw = _invIsBamaSw(sel[0].supplier_name);
  if (bqWrap) bqWrap.style.display = isSw ? '' : 'none';
  if (bqSel && isSw) {
    bqSel.innerHTML = '<option value="">— No Babcock quote —</option>';
    _invLoadBabcockOptions(bqSel, sel.find(i => i.babcock_quote_id)?.babcock_quote_id || null);
  } else if (bqSel) {
    bqSel.innerHTML = '<option value="">— No Babcock quote —</option>';
  }
}

// ── Split-mode state & helpers ───────────────────────────────────────────────
let _supMatchMode = 'single';    // 'single' | 'split'
let _supMatchPos = [];           // supplier's POs with _net + _matched computed
let _supMatchSplits = new Map(); // po_id → net £ string

function supMatchSetMode(mode) {
  _supMatchMode = mode;
  const one = document.getElementById('invSupMatchModeSingle');
  const spl = document.getElementById('invSupMatchModeSplit');
  if (one) one.classList.toggle('active', mode === 'single');
  if (spl) spl.classList.toggle('active', mode === 'split');
  const sw = document.getElementById('invSupMatchSingleWrap');
  const pw = document.getElementById('invSupMatchSplitWrap');
  if (sw) sw.style.display = mode === 'single' ? '' : 'none';
  if (pw) pw.style.display = mode === 'split' ? '' : 'none';
  if (mode === 'split') { _supMatchRenderSplitList(); _supMatchUpdateBar(); }
}

// The single ticked invoice being split (split mode is gated to one invoice)
function _supMatchSplitInvoice() {
  const sel = _invRemitSelection();
  return sel.length === 1 ? sel[0] : null;
}

function _supMatchRenderSplitList() {
  const host = document.getElementById('invSupMatchSplitList');
  if (!host) return;
  const q = (document.getElementById('invSupMatchSplitSearch')?.value || '').toLowerCase().trim();
  const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const list = _supMatchPos.filter(po => !q ||
    `${po.reference || ''} ${po.job_number || ''} ${po.description || ''}`.toLowerCase().includes(q));
  if (!list.length) {
    host.innerHTML = '<div style="padding:16px;text-align:center;font-size:12px;color:var(--muted)">No POs match</div>';
    return;
  }
  host.innerHTML = list.map(po => {
    const on = _supMatchSplits.has(po.id);
    const remaining = Math.max(0, Math.round((po._net - po._matched) * 100) / 100);
    return `
    <div style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid var(--border);${on ? 'background:var(--surface2);' : ''}">
      <input type="checkbox" ${on ? 'checked' : ''} onchange="supMatchToggleSplitPo(${po.id}, this.checked)">
      <div style="flex:1;min-width:0">
        <span style="font-family:var(--font-mono);font-weight:600;font-size:12px">${escapeHtml(po.reference || ('#' + po.id))}</span>
        ${po.job_number ? `<span style="font-size:11px;color:var(--muted)"> · ${escapeHtml(po.job_number)}</span>` : ''}
        <div style="font-size:10px;color:var(--subtle)">${po._net > 0 ? `£${fmt2(po._net)} net` : '<span style="color:#ffa500">no value on this PO — type the amount</span>'}${po._matched ? ` · £${fmt2(po._matched)} matched${po._net > 0 ? ` · £${fmt2(remaining)} left` : ''}` : ''}</div>
      </div>
      <div style="width:110px">
        <input type="number" step="0.01" class="field-input" placeholder="net £"
               style="font-size:12px;padding:4px 8px;text-align:right"
               value="${on ? escapeHtml(_supMatchSplits.get(po.id)) : ''}" ${on ? '' : 'disabled'}
               oninput="supMatchSplitAmtChanged(${po.id}, this.value)">
      </div>
    </div>`;
  }).join('');
}

function supMatchToggleSplitPo(poId, checked) {
  if (checked) {
    // Prefill with what's left on the PO, capped by what's still unallocated
    // on the invoice — plain arithmetic, always editable.
    const inv = _supMatchSplitInvoice();
    const invNet = inv ? Number(inv.net != null ? inv.net : inv.gross) || 0 : 0;
    const allocated = [..._supMatchSplits.values()].reduce((s, v) => s + (parseFloat(v) || 0), 0);
    const po = _supMatchPos.find(p => p.id === poId);
    const poHasValue = po && po._net > 0;
    const remainingPo = po ? Math.max(0, Math.round((po._net - po._matched) * 100) / 100) : 0;
    const remainingInv = Math.max(0, Math.round((invNet - allocated) * 100) / 100);
    // A PO with no value entered (£0 — human error or open order) gives us
    // nothing to prefill FROM: leave the box empty for the user to type,
    // instead of dumping the whole remaining invoice into the first tick.
    const prefill = poHasValue ? Math.min(remainingPo, remainingInv) : 0;
    _supMatchSplits.set(poId, prefill > 0 ? prefill.toFixed(2) : '');
  } else {
    _supMatchSplits.delete(poId);
  }
  _supMatchRenderSplitList();
  _supMatchUpdateBar();
}

function supMatchSplitAmtChanged(poId, val) {
  if (_supMatchSplits.has(poId)) _supMatchSplits.set(poId, val);
  _supMatchUpdateBar();
}

function _supMatchUpdateBar() {
  const bar = document.getElementById('invSupMatchSplitBar');
  if (!bar) return;
  const inv = _supMatchSplitInvoice();
  const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const invNet = inv ? Number(inv.net != null ? inv.net : inv.gross) || 0 : 0;
  const hasNet = inv && inv.net != null;
  const allocated = Math.round([..._supMatchSplits.values()].reduce((s, v) => s + (parseFloat(v) || 0), 0) * 100) / 100;
  const diff = Math.round((allocated - invNet) * 100) / 100;
  const okish = Math.abs(diff) <= 1.00 && _supMatchSplits.size > 0;
  bar.style.background = okish ? 'rgba(62,207,142,.12)' : 'rgba(255,165,0,.12)';
  bar.style.border = `1px solid ${okish ? 'var(--green)' : '#ffa500'}`;
  bar.style.color = okish ? 'var(--green)' : '#ffa500';
  if (!_supMatchSplits.size) {
    bar.textContent = `Nothing allocated yet — invoice is £${fmt2(invNet)} ${hasNet ? 'net' : 'gross'}`;
  } else if (okish) {
    bar.textContent = `✓ £${fmt2(allocated)} allocated across ${_supMatchSplits.size} PO${_supMatchSplits.size === 1 ? '' : 's'} — matches the invoice (£${fmt2(invNet)} ${hasNet ? 'net' : 'gross'})`;
  } else {
    bar.textContent = `⚠ £${fmt2(allocated)} allocated vs £${fmt2(invNet)} invoice ${hasNet ? 'net' : 'gross'} — ${diff > 0 ? '£' + fmt2(diff) + ' over' : '£' + fmt2(-diff) + ' short'}`;
  }
}

// Babcock quotes only ever come through BAMA South West — the picker is
// gated to that supplier and hides quotes already matched to an invoice.
function _invIsBamaSw(supplierName) {
  const n = String(supplierName || '').toLowerCase().replace(/[^a-z]/g, '');
  return n.includes('bamasouthwest') || n === 'bamasw' || n.includes('bamaswltd');
}

async function _invLoadBabcockOptions(selectEl, preselectId) {
  try {
    const quotes = await api.get('/api/babcock-quotes');
    // Quote ids already matched to a (non-deleted) supplier invoice — taken.
    // The one preselected on the invoice being edited stays available.
    const used = new Set(
      _invSupInvoices.filter(i => i.babcock_quote_id && i.babcock_quote_id !== preselectId)
                     .map(i => i.babcock_quote_id));
    const list = (Array.isArray(quotes) ? quotes : (quotes.rows || quotes.quotes || []))
      .filter(q => !used.has(q.id))
      .sort((a, b) => String(b.quote_ref || '').localeCompare(String(a.quote_ref || '')));
    selectEl.innerHTML = '<option value="">— No Babcock quote —</option>' + list.map(q =>
      `<option value="${q.id}" ${preselectId === q.id ? 'selected' : ''}>${escapeHtml(q.quote_ref || ('#' + q.id))}${q.description ? ' — ' + escapeHtml(String(q.description).slice(0, 50)) : ''}</option>`
    ).join('');
  } catch (e) { /* leave the no-quote option */ }
}

function closeSupMatchModal() {
  document.getElementById('invSupMatchModal').classList.remove('active');
}

async function confirmSupMatch() {
  const sel = _invRemitSelection();
  if (!sel.length) { closeSupMatchModal(); return; }
  const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const bqWrapEl = document.getElementById('invSupMatchBabcockWrap');
  const bqEl = document.getElementById('invSupMatchBabcock');
  const bqVisible = bqWrapEl && bqWrapEl.style.display !== 'none';
  const babcockId = bqVisible && bqEl && bqEl.value ? parseInt(bqEl.value) : (bqVisible ? null : undefined);

  // Turn the server's warnings[] into one readable bamaConfirm message
  const warningsText = (warnings) => (warnings || []).map(w => {
    if (w.kind === 'sum_mismatch')
      return `The splits total £${fmt2(w.allocated_net)} but the invoice is £${fmt2(w.invoice_net)} net — £${fmt2(Math.abs(w.diff))} ${w.diff > 0 ? 'over' : 'short'}.`;
    if (w.kind === 'po_over')
      return `PO ${w.po_reference} is £${fmt2(w.po_net)} net, but its matched invoices would total £${fmt2(w.matched_net)} — £${fmt2(w.over_by)} over the order value.`;
    return '';
  }).filter(Boolean).join('\n\n');

  // ═══ SPLIT mode — one invoice allocated across several POs ═══
  if (_supMatchMode === 'split') {
    const inv = _supMatchSplitInvoice();
    if (!inv) { toast('Split works with exactly one ticked invoice', 'error'); return; }
    const allocations = [..._supMatchSplits.entries()]
      .map(([po_id, v]) => ({ po_id, net: parseFloat(v) }))
      .filter(a => Number.isFinite(a.net) && a.net !== 0);
    if (!allocations.length) { toast('Tick at least one PO and enter its net amount', 'error'); return; }

    setLoading(true);
    try {
      let res = await api.post('/api/supplier-invoices-match', { invoice_id: inv.id, allocations });
      if (res && res.needs_confirm) {
        setLoading(false);
        const goAnyway = await bamaConfirm({
          title: 'Are you sure these are the right amounts for these orders?',
          message: warningsText(res.warnings) + '\n\nMatch anyway?',
          confirmText: 'Match anyway', danger: true
        });
        if (!goAnyway) return;
        setLoading(true);
        res = await api.post('/api/supplier-invoices-match', { invoice_id: inv.id, allocations, force: true });
      }
      toast(`Invoice split across ${allocations.length} PO${allocations.length === 1 ? '' : 's'} ✓`, 'success');
      _invRemitSelected.clear();
      closeSupMatchModal();
      await loadInvoicingData();
      renderInvSupplierTable();
    } catch (e) {
      toast('Split failed: ' + (e.message || 'unknown error'), 'error');
    } finally { setLoading(false); }
    return;
  }

  // ═══ SINGLE mode — all ticked invoices onto one PO (or unmatch) ═══
  const poId = document.getElementById('invSupMatchPo').value || null;
  const ids = sel.map(i => i.id);

  setLoading(true);
  try {
    let res = await api.post('/api/supplier-invoices-match', {
      invoice_ids: ids, po_id: poId ? parseInt(poId) : null, babcock_quote_id: babcockId
    });
    if (res && res.needs_confirm) {
      setLoading(false);
      const goAnyway = await bamaConfirm({
        title: 'Are you sure? Maybe one invoice too many?',
        message: `PO ${res.po_reference} totals £${fmt2(res.po_total)}${res.basis === 'net' ? ' net' : ''}, but the ${res.invoice_count} matched invoice${res.invoice_count === 1 ? '' : 's'} would total £${fmt2(res.matched_total)} — that's £${fmt2(res.over_by)} over the order value.\n\nMatch anyway?`,
        confirmText: 'Match anyway', danger: true
      });
      if (!goAnyway) return;
      setLoading(true);
      res = await api.post('/api/supplier-invoices-match', {
        invoice_ids: ids, po_id: parseInt(poId), babcock_quote_id: babcockId, force: true
      });
    }
    toast(poId ? `${ids.length} invoice${ids.length === 1 ? '' : 's'} matched ✓` : 'Invoices unmatched from PO', 'success');
    _invRemitSelected.clear();
    closeSupMatchModal();
    await loadInvoicingData();
    renderInvSupplierTable();
  } catch (e) {
    toast('Match failed: ' + (e.message || 'unknown error'), 'error');
  } finally { setLoading(false); }
}

// ═════════════════════════════════════════════════════════════════════════
// ADD SUPPLIER INVOICE MANUALLY — no PO required, optional file + links
// ═════════════════════════════════════════════════════════════════════════
let _supAddFile = null;
let _supAddBabcockPreselect = null;
let _supAddType = 'supplier';     // 'supplier' | 'subcontractor'
let _supAddEditingId = null;      // SupplierInvoices id when amending (null = new)

async function openSupAddInvoiceModal(editInvoiceId) {
  _supAddFile = null;
  _supAddEditingId = editInvoiceId || null;
  const editing = _supAddEditingId ? _invSupInvoices.find(i => i.id === _supAddEditingId) : null;

  const supSel = document.getElementById('supAddSupplier');
  supSel.innerHTML = '<option value="">Loading…</option>';
  ['supAddRef','supAddNet','supAddVat','supAddGross','supAddNotes',
   'supAddLabour','supAddCisDeduction','supAddPayable','supAddDueOverride'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  document.getElementById('supAddDate').value = editing && editing.invoice_date
    ? String(editing.invoice_date).slice(0, 10) : new Date().toISOString().slice(0, 10);
  document.getElementById('supAddPo').innerHTML = '<option value="">— No PO —</option>';
  document.getElementById('supAddFileLabel').textContent = editing ? (editing.filename || 'Keeping existing file') : 'No file yet';
  document.getElementById('supAddDueHint').textContent = '';
  const titleEl = document.getElementById('invSupAddTitle');
  if (titleEl) titleEl.textContent = editing ? '✏️ Amend Invoice' : '➕ Add Invoice';
  const saveBtn = document.getElementById('supAddSaveBtn');
  if (saveBtn) saveBtn.textContent = editing ? 'Save Changes' : 'Save Invoice';
  document.getElementById('supAddNewSubForm').style.display = 'none';

  supAddSetType(editing ? (editing.invoice_type === 'subcontractor' ? 'subcontractor' : 'supplier') : 'supplier');
  document.getElementById('invSupAddModal').classList.add('active');

  await _supAddFillSupplierOptions();

  _supAddBabcockPreselect = editing ? editing.babcock_quote_id : null;
  const bqWrap0 = document.getElementById('supAddBabcockWrap');
  if (bqWrap0) bqWrap0.style.display = 'none'; // shown only when a BAMA SW supplier is picked

  // Prefill when amending
  if (editing) {
    document.getElementById('supAddSupplier').value = String(editing.supplier_id);
    await onSupAddSupplierPicked();
    _supAddUpdateDueHint();
    if (editing.po_id) document.getElementById('supAddPo').value = String(editing.po_id);
    document.getElementById('supAddRef').value = editing.invoice_ref || '';
    if (editing.invoice_type === 'subcontractor') {
      document.getElementById('supAddLabour').value = editing.labour_gross != null ? Number(editing.labour_gross).toFixed(2) : '';
      const rateSel = document.getElementById('supAddCisRate');
      if (rateSel && editing.cis_rate != null) rateSel.value = String(Number(editing.cis_rate));
      document.getElementById('supAddCisDeduction').value = editing.cis_deduction != null ? Number(editing.cis_deduction).toFixed(2) : '';
      document.getElementById('supAddPayable').value = Number(editing.gross || 0).toFixed(2);
    } else {
      document.getElementById('supAddNet').value   = editing.net  != null ? Number(editing.net).toFixed(2)  : '';
      document.getElementById('supAddVat').value   = editing.vat  != null ? Number(editing.vat).toFixed(2)  : '';
      document.getElementById('supAddGross').value = Number(editing.gross || 0).toFixed(2);
    }
    if (editing.due_date) document.getElementById('supAddDueOverride').value = String(editing.due_date).slice(0, 10);
    document.getElementById('supAddNotes').value = editing.notes || '';
  }
}

async function _supAddFillSupplierOptions() {
  const supSel = document.getElementById('supAddSupplier');
  const suppliers = await _invGetSuppliersList();
  const wantSub = _supAddType === 'subcontractor';
  const pool = suppliers.filter(s => wantSub ? s.is_subcontractor : !s.is_subcontractor);
  const keep = supSel.value;
  supSel.innerHTML = `<option value="">${wantSub ? 'Select subcontractor…' : 'Select supplier…'}</option>` + pool
    .slice().sort((a, b) => String(a.supplier_name).localeCompare(String(b.supplier_name)))
    .map(s => `<option value="${s.id}">${escapeHtml(s.supplier_name)}</option>`).join('');
  if (keep && pool.some(s => String(s.id) === keep)) supSel.value = keep;
}

// Type toggle — swaps the amounts row between VAT maths and CIS maths
function supAddSetType(type) {
  _supAddType = type === 'subcontractor' ? 'subcontractor' : 'supplier';
  const isSub = _supAddType === 'subcontractor';
  document.getElementById('supAddTypeSupplier').classList.toggle('active', !isSub);
  document.getElementById('supAddTypeSub').classList.toggle('active', isSub);
  document.getElementById('supAddVatRow').style.display = isSub ? 'none' : 'grid';
  document.getElementById('supAddCisRow').style.display = isSub ? 'grid' : 'none';
  document.getElementById('supAddNewSubBtn').style.display = isSub ? '' : 'none';
  document.getElementById('supAddSupplierLabel').textContent = isSub ? 'Subcontractor *' : 'Supplier *';
  _supAddFillSupplierOptions();
}

// CIS maths (deterministic): deduction = labour × rate, payable = labour − deduction
function onSupAddCis() {
  const labour = parseFloat(document.getElementById('supAddLabour').value) || 0;
  const rate = parseFloat(document.getElementById('supAddCisRate').value) || 0;
  const ded = +(labour * rate / 100).toFixed(2);
  document.getElementById('supAddCisDeduction').value = labour ? ded.toFixed(2) : '';
  document.getElementById('supAddPayable').value = labour ? (labour - ded).toFixed(2) : '';
}

// ── Quick-create subcontractor inline ────────────────────────────────────────
function supAddToggleNewSub(show) {
  const form = document.getElementById('supAddNewSubForm');
  form.style.display = show ? '' : 'none';
  if (show) {
    ['nsubName','nsubUtr','nsubSort','nsubAccount','nsubEmail'].forEach(id => {
      const el = document.getElementById(id); if (el) el.value = '';
    });
    document.getElementById('nsubCisRate').value = '20';
    document.getElementById('nsubName').focus();
  }
}

async function supAddCreateSubcontractor() {
  const name = document.getElementById('nsubName').value.trim();
  if (!name) { toast('Name is required', 'error'); return; }
  setLoading(true);
  try {
    const created = await api.post('/api/suppliers', {
      supplier_name: name,
      is_subcontractor: true,
      utr_number: document.getElementById('nsubUtr').value.trim() || null,
      cis_rate: parseFloat(document.getElementById('nsubCisRate').value),
      bank_sort_code: document.getElementById('nsubSort').value.trim() || null,
      bank_account_no: document.getElementById('nsubAccount').value.trim() || null,
      email: document.getElementById('nsubEmail').value.trim() || null,
      notes: 'Subcontractor (CIS)'
    });
    _invSuppliersCache = null; // refresh cache
    if (Array.isArray(_suppliers)) _suppliers.push(created);
    await _supAddFillSupplierOptions();
    document.getElementById('supAddSupplier').value = String(created.id);
    // Default the CIS rate on the invoice from the new record
    if (created.cis_rate != null) {
      document.getElementById('supAddCisRate').value = String(Number(created.cis_rate));
      onSupAddCis();
    }
    supAddToggleNewSub(false);
    _supAddUpdateDueHint();
    toast(`Subcontractor ${name} added ✓`, 'success');
  } catch (e) {
    toast('Failed to add subcontractor: ' + (e.message || 'unknown error'), 'error');
  } finally { setLoading(false); }
}

async function _invGetSuppliersList() {
  if (!_invSuppliersCache) {
    try { _invSuppliersCache = await api.get('/api/suppliers'); }
    catch (e) { _invSuppliersCache = []; }
  }
  return _invSuppliersCache || [];
}

function closeSupAddInvoiceModal() {
  document.getElementById('invSupAddModal').classList.remove('active');
}

async function onSupAddSupplierPicked() {
  const supplierId = parseInt(document.getElementById('supAddSupplier').value);
  const poSel = document.getElementById('supAddPo');
  poSel.innerHTML = '<option value="">— No PO —</option>';
  _supAddUpdateDueHint();

  // Babcock picker only for BAMA South West
  const bqWrap = document.getElementById('supAddBabcockWrap');
  const bqSel  = document.getElementById('supAddBabcock');
  const suppliersAll = await _invGetSuppliersList();
  const picked = suppliersAll.find(x => x.id === supplierId);
  const isSw = picked && _invIsBamaSw(picked.supplier_name);
  if (bqWrap) bqWrap.style.display = isSw ? '' : 'none';
  if (bqSel) {
    bqSel.innerHTML = '<option value="">— No Babcock quote —</option>';
    if (isSw) _invLoadBabcockOptions(bqSel, _supAddBabcockPreselect);
  }

  if (!supplierId) return;
  try {
    const pos = await api.get(`/api/purchase-orders?supplier_id=${supplierId}`);
    const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    poSel.innerHTML = '<option value="">— No PO —</option>' + (pos || [])
      .filter(po => po.status !== 'Cancelled')
      .map(po => `<option value="${po.id}">${escapeHtml(po.reference || ('#' + po.id))} — £${fmt2(po.total_value)}${po.job_number ? ' · ' + escapeHtml(po.job_number) : ''}</option>`)
      .join('');
  } catch (e) { /* keep no-PO */ }
}

async function _supAddUpdateDueHint() {
  const hint = document.getElementById('supAddDueHint');
  if (!hint) return;
  const supplierId = parseInt(document.getElementById('supAddSupplier').value);
  if (!supplierId) { hint.textContent = ''; return; }
  const suppliers = await _invGetSuppliersList();
  const s = suppliers.find(x => x.id === supplierId);
  const terms = typeof _fmtPaymentTerms === 'function' ? _fmtPaymentTerms(s) : null;
  hint.textContent = terms ? `Terms: ${terms} — due date will be set automatically` :
    (s && s.payment_dd ? 'Direct debit — no due date' : 'No payment terms set for this supplier — due date will be blank');
}

function onSupAddNetVat() {
  const net = parseFloat(document.getElementById('supAddNet').value) || 0;
  const vatEl = document.getElementById('supAddVat');
  const grossEl = document.getElementById('supAddGross');
  if (net && vatEl.value === '') vatEl.value = (net * 0.2).toFixed(2);
  const vat = parseFloat(vatEl.value) || 0;
  if (net || vat) grossEl.value = (net + vat).toFixed(2);
}

function onSupAddFilePicked(input) {
  const file = input.files && input.files[0] ? input.files[0] : null;
  if (file) _supAddHandleFile(file);
}

// Drag & drop onto the modal dropzone
function supAddDragOver(ev) {
  ev.preventDefault();
  ev.currentTarget.style.borderColor = 'var(--accent)';
}
function supAddDragLeave(ev) {
  ev.currentTarget.style.borderColor = 'var(--border)';
}
function supAddDrop(ev) {
  ev.preventDefault();
  ev.currentTarget.style.borderColor = 'var(--border)';
  const file = ev.dataTransfer.files && ev.dataTransfer.files[0];
  if (file) _supAddHandleFile(file);
}

// Take the file → Claude reads it → prefill every field (AI reads only;
// all arithmetic and matching stays deterministic JS)
async function _supAddHandleFile(file) {
  _supAddFile = file;
  const label = document.getElementById('supAddFileLabel');
  label.innerHTML = `<span class="spinner" style="width:12px;height:12px;display:inline-block;vertical-align:middle"></span> Reading ${escapeHtml(file.name)}…`;

  let parsed = null;
  try {
    const dataUri = await _fileToDataUri(file);
    const isImg = file.type.startsWith('image/');
    const result = await callClaude({
      model: 'claude-sonnet-4-6',
      max_tokens: 1500,
      messages: [{
        role: 'user',
        content: [
          isImg
            ? { type: 'image',    source: { type: 'base64', media_type: file.type, data: dataUri.split(',')[1] } }
            : { type: 'document', source: { type: 'base64', media_type: file.type, data: dataUri.split(',')[1] } },
          {
            type: 'text',
            text: `Extract from this UK invoice sent to BAMA Fabrication. It is either a SUPPLIER invoice (VAT invoice from a company) or a SUBCONTRACTOR invoice (an individual/small firm charging for labour, often with a CIS deduction like "Less 20%", a UTR number, and bank details). Return ONLY JSON, no markdown:
{
  "document_kind": "invoice" or "credit_note" — credit notes say CREDIT NOTE in the header and credit money back to us,
  "credits_invoice_ref": "credit notes only: the original invoice number being credited, e.g. from 'REF TO INVOICE NO 00758726' — else null",
  "invoice_type": "supplier" or "subcontractor",
  "supplier_name": "the company/person that ISSUED and is OWED money on this invoice — the SELLER. NOT the customer/recipient.",
  "invoice_ref": "invoice number if shown",
  "invoice_date": "YYYY-MM-DD",
  "net_amount": 0,
  "vat_amount": 0,
  "gross_amount": 0,
  "labour_subtotal": "subcontractor only: the subtotal BEFORE the CIS deduction",
  "cis_rate": "subcontractor only: the deduction percentage as a number, e.g. 20",
  "cis_deduction": "subcontractor only: the deducted amount",
  "amount_payable": "subcontractor only: the final amount due after deduction",
  "utr_number": "subcontractor only: UTR if shown",
  "bank_sort_code": "subcontractor only: sort code if shown",
  "bank_account_no": "subcontractor only: account number if shown",
  "po_reference": "BAMA's PO reference if shown — starts with P followed by 6-8 digits, e.g. P260501 or P2607101. Suffixes like P260768/S1982 mean PO P260768 — return just the P-number. When several are shown, the first one.",
  "po_references": ["EVERY distinct BAMA P-number shown anywhere on the invoice — consolidated invoices often quote several"],
  "sold_via": "amazon" if this is an Amazon / Amazon Business marketplace invoice (Amazon branding, amazon.co.uk order number, "Sold by ..." line) — otherwise null,
  "amazon_seller": "when sold_via is amazon: the actual seller/merchant name, else null"
}
CRITICAL — who is the supplier:
- The invoice is ADDRESSED TO "Bama Fabrication" / "BAMA Fabrication Ltd" — that is US, the CUSTOMER. NEVER return a Bama/BAMA name as supplier_name.
- The SELLER (supplier_name) is the party on the letterhead/logo who issues the invoice, quotes their own VAT number, and gives bank/remittance details for payment. Their name usually appears at the top (logo) and again in "Bank Details / remittances to". For trading divisions return the trading entity as shown (e.g. "Laser Profiles").
- If the only company name you can read is a Bama variant, set supplier_name to null rather than guessing.
Classify as subcontractor ONLY when the invoice is for labour/days/hours from an INDIVIDUAL and mentions CIS, a percentage deduction, or a UTR number. A LABOUR AGENCY — a limited company (name ends "Ltd"/"Limited") supplying named workers by the week/day with NO CIS deduction and no UTR (often reverse-charge or 0% VAT) — is a normal "supplier", NOT a subcontractor. Set any field to null if not clearly shown.
IMPORTANT: Use the final printed totals from the invoice — not a goods-only subtotal.`
          }
        ]
      }]
    });
    const text = (result.content?.find(b => b.type === 'text')?.text || '').trim();
    const s = text.indexOf('{'), e = text.lastIndexOf('}');
    parsed = JSON.parse(text.slice(s, e + 1));
    _invNormaliseParsedSupplier(parsed);
  } catch (err) {
    console.error('Add-invoice parse failed', err);
    label.textContent = `${file.name} · ${(file.size / 1024).toFixed(0)} KB — couldn't read it, fill in manually`;
    return;
  }

  // Fill the form (deterministic)
  const parsedIsSub = parsed.invoice_type === 'subcontractor';
  if (parsedIsSub !== (_supAddType === 'subcontractor')) supAddSetType(parsedIsSub ? 'subcontractor' : 'supplier');
  if (parsed.invoice_ref)  document.getElementById('supAddRef').value  = parsed.invoice_ref;
  if (parsed.invoice_date) document.getElementById('supAddDate').value = String(parsed.invoice_date).slice(0, 10);
  if (parsedIsSub) {
    if (parsed.labour_subtotal != null) document.getElementById('supAddLabour').value = Number(parsed.labour_subtotal).toFixed(2);
    if (parsed.cis_rate != null) {
      const rateSel = document.getElementById('supAddCisRate');
      const r = String(Number(parsed.cis_rate));
      if ([...rateSel.options].some(o => o.value === r)) rateSel.value = r;
    }
    onSupAddCis(); // deterministic: deduction + payable from labour × rate
    // If the invoice printed different figures to our calculation, trust the invoice but flag it
    if (parsed.amount_payable != null) {
      const calc = parseFloat(document.getElementById('supAddPayable').value) || 0;
      const printed = Number(parsed.amount_payable);
      if (Math.abs(calc - printed) > 0.02) {
        document.getElementById('supAddPayable').value = printed.toFixed(2);
        if (parsed.cis_deduction != null)
          document.getElementById('supAddCisDeduction').value = Number(parsed.cis_deduction).toFixed(2);
        toast(`Heads up: invoice shows £${printed.toFixed(2)} payable but labour × rate gives £${calc.toFixed(2)} — check it`, 'warning');
      }
    }
  } else {
    if (parsed.net_amount   != null) document.getElementById('supAddNet').value   = Number(parsed.net_amount).toFixed(2);
    if (parsed.vat_amount   != null) document.getElementById('supAddVat').value   = Number(parsed.vat_amount).toFixed(2);
    if (parsed.gross_amount != null) document.getElementById('supAddGross').value = Number(parsed.gross_amount).toFixed(2);
    else if (parsed.net_amount != null || parsed.vat_amount != null)
      document.getElementById('supAddGross').value =
        (Number(parsed.net_amount || 0) + Number(parsed.vat_amount || 0)).toFixed(2);
  }

  // Auto-pick the supplier/subcontractor by name (exact → contains, normalised)
  let matchedSupplier = null;
  if (parsed.supplier_name) {
    const suppliers = await _invGetSuppliersList();
    const norm = v => String(v || '').toLowerCase().replace(/\b(ltd|limited|plc|llp|co|company|uk)\b/g, '').replace(/[^a-z0-9]/g, '');
    const target = norm(parsed.supplier_name);
    // Prefer entries matching the parsed type, but fall back across the whole list
    const pool = suppliers.filter(s => parsedIsSub ? s.is_subcontractor : !s.is_subcontractor);
    const findIn = list =>
      list.find(x => norm(x.supplier_name) === target) ||
      list.find(x => target && (norm(x.supplier_name).includes(target) || target.includes(norm(x.supplier_name)))) ||
      null;
    matchedSupplier = findIn(pool) || findIn(suppliers);
    if (matchedSupplier) {
      // If the match sits in the other pool, flip the toggle so it's selectable
      if (!!matchedSupplier.is_subcontractor !== (_supAddType === 'subcontractor'))
        supAddSetType(matchedSupplier.is_subcontractor ? 'subcontractor' : 'supplier');
      await _supAddFillSupplierOptions();
      document.getElementById('supAddSupplier').value = String(matchedSupplier.id);
      await onSupAddSupplierPicked();
      _supAddUpdateDueHint();
    } else if (parsedIsSub) {
      // Unknown subcontractor — open the quick-create form pre-filled from the invoice
      supAddToggleNewSub(true);
      document.getElementById('nsubName').value = parsed.supplier_name || '';
      if (parsed.utr_number)      document.getElementById('nsubUtr').value = parsed.utr_number;
      if (parsed.cis_rate != null) {
        const r = String(Number(parsed.cis_rate));
        if ([...document.getElementById('nsubCisRate').options].some(o => o.value === r))
          document.getElementById('nsubCisRate').value = r;
      }
      if (parsed.bank_sort_code)  document.getElementById('nsubSort').value = parsed.bank_sort_code;
      if (parsed.bank_account_no) document.getElementById('nsubAccount').value = parsed.bank_account_no;
    }
  }

  // Amazon-brokered: keep the real seller searchable in the notes field
  if (parsed.sold_via === 'amazon' && parsed.amazon_seller) {
    const notesEl = document.getElementById('supAddNotes');
    if (notesEl && !notesEl.value.trim()) notesEl.value = `via Amazon — seller: ${parsed.amazon_seller}`;
  }

  // Auto-pick the PO when the invoice quotes our reference
  let poMatched = false;
  if (parsed.po_reference && matchedSupplier) {
    const want = String(parsed.po_reference).replace(/\s+/g, '').toUpperCase();
    const poSel = document.getElementById('supAddPo');
    for (const opt of poSel.options) {
      const refPart = (opt.textContent.split('—')[0] || '').replace(/\s+/g, '').toUpperCase();
      if (opt.value && refPart === want) { poSel.value = opt.value; poMatched = true; break; }
    }
  }

  const bits = [];
  const who = parsedIsSub ? 'subcontractor' : 'supplier';
  if (parsed._supplierWasBama) {
    bits.push('couldn\'t read the seller (invoice is addressed to BAMA) — pick the supplier manually');
  } else {
    bits.push(matchedSupplier ? `${who}: ${matchedSupplier.supplier_name}` :
              (parsed.supplier_name ? (parsedIsSub
                ? `new subcontractor "${parsed.supplier_name}" — details pre-filled below, hit Save Subcontractor`
                : `supplier "${parsed.supplier_name}" not found — pick manually`) : ''));
  }
  if (parsed.document_kind === 'credit_note') {
    // Flip the printed amounts negative so the ledger nets it off
    ['supAddNet', 'supAddVat', 'supAddGross'].forEach(id => {
      const el = document.getElementById(id);
      if (el && el.value !== '' && Number(el.value) > 0) el.value = (-Math.abs(Number(el.value))).toFixed(2);
    });
    bits.push(`📕 CREDIT NOTE${parsed.credits_invoice_ref ? ` against invoice ${parsed.credits_invoice_ref}` : ''} — amounts saved as negative so it deducts from what's owed`);
  }
  const _multiPo = Array.isArray(parsed.po_references) ? [...new Set(parsed.po_references.filter(Boolean))] : [];
  if (_multiPo.length > 1) {
    bits.push(`⚠ quotes ${_multiPo.length} POs (${_multiPo.join(', ')}) — 📥 Bulk Import splits these automatically; or save here, tick it in the ledger and 🔗 Match → Split`);
  } else if (parsed.po_reference) {
    bits.push(poMatched ? `PO ${parsed.po_reference} matched` : `PO ${parsed.po_reference} not found`);
  }
  if (parsed.sold_via === 'amazon') bits.push(`Amazon${parsed.amazon_seller ? ' (seller: ' + parsed.amazon_seller + ')' : ''} — tracked under Amazon`);
  label.innerHTML = `${escapeHtml(file.name)} · ${(file.size / 1024).toFixed(0)} KB — <span style="color:var(--green);font-weight:600">parsed ✓</span>${bits.filter(Boolean).length ? ' <span style="color:var(--muted)">(' + escapeHtml(bits.filter(Boolean).join(', ')) + ')</span>' : ''}`;
}

async function saveSupAddInvoice() {
  const supplierId = parseInt(document.getElementById('supAddSupplier').value);
  if (!supplierId) { toast(_supAddType === 'subcontractor' ? 'Pick a subcontractor' : 'Pick a supplier', 'error'); return; }

  const isSub = _supAddType === 'subcontractor';
  let net = null, vat = null, gross = null, labour = null, cisRate = null, cisDed = null;
  if (isSub) {
    labour  = parseFloat(document.getElementById('supAddLabour').value) || null;
    cisRate = parseFloat(document.getElementById('supAddCisRate').value);
    cisDed  = parseFloat(document.getElementById('supAddCisDeduction').value) || 0;
    gross   = parseFloat(document.getElementById('supAddPayable').value);
    if (!gross && labour) gross = +(labour - cisDed).toFixed(2);
    if (!gross) { toast('Amount payable is required — enter the labour subtotal', 'error'); return; }
    net = labour; // for reporting: pre-deduction value
  } else {
    net   = parseFloat(document.getElementById('supAddNet').value) || null;
    vat   = parseFloat(document.getElementById('supAddVat').value) || null;
    gross = parseFloat(document.getElementById('supAddGross').value);
    if (!gross) { toast('Gross amount is required', 'error'); return; }
  }
  const date = document.getElementById('supAddDate').value || null;
  const ref  = document.getElementById('supAddRef').value.trim();
  const dueOverride = document.getElementById('supAddDueOverride').value || null;

  setLoading(true);
  try {
    // Optional file → SharePoint (same folder scheme as parsed invoices)
    let spId = null, spUrl = null, fileName = null;
    if (_supAddFile) {
      const suppliers = await _invGetSuppliersList();
      const s = suppliers.find(x => x.id === supplierId);
      const folder = await _findOrCreateSupplierInvoiceFolder(date || new Date().toISOString().slice(0, 10));
      const stamp = ((s && s.supplier_name) || 'supplier').replace(/\s+/g, '_').slice(0, 30);
      const ext = (_supAddFile.name.split('.').pop() || 'pdf').toLowerCase();
      fileName = sanitizeSpFilename(`${date || 'undated'}_${stamp}_${ref || 'no-ref'}.${ext}`);
      const driveItem = await uploadFileToFolder(folder.id, fileName, _supAddFile, _supAddFile.type || 'application/octet-stream');
      spId = driveItem.id; spUrl = driveItem.webUrl;
    }

    const payload = {
      supplier_id: supplierId,
      po_id: document.getElementById('supAddPo').value || null,
      babcock_quote_id: (document.getElementById('supAddBabcockWrap')?.style.display !== 'none'
                          && document.getElementById('supAddBabcock')?.value) || null,
      invoice_type: _supAddType,
      invoice_ref: ref || null,
      invoice_date: date,
      net, vat, gross,
      labour_gross: labour,
      cis_rate: isSub && Number.isFinite(cisRate) ? cisRate : null,
      cis_deduction: isSub ? cisDed : null,
      notes: document.getElementById('supAddNotes').value.trim() || null
    };
    if (dueOverride) payload.due_date = dueOverride;
    if (spId) { payload.sharepoint_file_id = spId; payload.sharepoint_file_url = spUrl; payload.filename = fileName; }

    if (_supAddEditingId) {
      await api.put(`/api/supplier-invoices/${_supAddEditingId}`, payload);
      toast('Invoice updated ✓', 'success');
    } else {
      payload.source = 'manual';
      await api.post('/api/supplier-invoices', payload);
      toast(isSub ? 'Subcontractor invoice added ✓' : 'Supplier invoice added ✓', 'success');
    }

    closeSupAddInvoiceModal();
    await loadInvoicingData();
    renderInvSupplierTable();
  } catch (e) {
    toast('Save failed: ' + (e.message || 'unknown error'), 'error');
  } finally { setLoading(false); }
}

// ═════════════════════════════════════════════════════════════════════════
// BACS RUN — pick a due-date window, tick invoices, one run marks them paid,
// CSV for the bank + per-supplier remittance PDFs to SharePoint
// ═════════════════════════════════════════════════════════════════════════
let _bacsSelected = new Set();
let _bacsCandidates = [];

function openBacsRunModal() {
  const today = new Date();
  const to = new Date(today); to.setDate(to.getDate() + 7);
  document.getElementById('bacsRunDate').value = today.toISOString().slice(0, 10);
  document.getElementById('bacsFrom').value = '';
  document.getElementById('bacsTo').value = to.toISOString().slice(0, 10);
  document.getElementById('bacsRunRef').value = 'BACS-' + today.toISOString().slice(0, 10).replace(/-/g, '');
  document.getElementById('bacsIncludeDd').checked = false;
  document.getElementById('bacsIncludeNoDue').checked = true;
  _bacsSelected = new Set();
  _bacsRefreshCandidates();
  document.getElementById('invBacsRunModal').classList.add('active');
}

function closeBacsRunModal() {
  document.getElementById('invBacsRunModal').classList.remove('active');
}

function _bacsRefreshCandidates() {
  const from = document.getElementById('bacsFrom').value || null;
  const to   = document.getElementById('bacsTo').value || null;
  const inclDd    = document.getElementById('bacsIncludeDd').checked;
  const inclNoDue = document.getElementById('bacsIncludeNoDue').checked;

  _bacsCandidates = _invSupInvoices.filter(inv => {
    if (inv.paid_at) return false;
    if (inv.is_dd && !inclDd) return false;
    const due = inv.due_date ? String(inv.due_date).slice(0, 10) : null;
    if (!due) return inclNoDue;
    if (from && due < from) return false;
    if (to && due > to) return false;
    return true;
  }).sort((a, b) => String(a.supplier_name || '').localeCompare(String(b.supplier_name || ''))
                 || String(a.due_date || '').localeCompare(String(b.due_date || '')));

  // Default: everything in the window selected
  _bacsSelected = new Set(_bacsCandidates.map(i => i.id));
  _bacsRenderList();
}

function bacsToggle(id, checked) {
  if (checked) _bacsSelected.add(id); else _bacsSelected.delete(id);
  _bacsRenderTotals();
}

function bacsToggleAll(checked) {
  _bacsSelected = checked ? new Set(_bacsCandidates.map(i => i.id)) : new Set();
  _bacsRenderList();
}

function _bacsRenderList() {
  const box = document.getElementById('bacsList');
  if (!box) return;
  const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (!_bacsCandidates.length) {
    box.innerHTML = '<div style="padding:24px;text-align:center;color:var(--muted);font-size:12px">No unpaid invoices due in this window</div>';
    _bacsRenderTotals();
    return;
  }
  box.innerHTML = `
    <table style="width:100%;border-collapse:collapse;font-size:12px">
      <thead><tr>
        <th style="width:30px;text-align:center;padding:5px 6px;border-bottom:1px solid var(--border)">
          <input type="checkbox" checked onchange="bacsToggleAll(this.checked)"></th>
        ${['Supplier','Invoice #','PO','Due','Gross (£)'].map((h, i) => `
          <th style="text-align:${i === 4 ? 'right' : 'left'};padding:5px 6px;font-size:10px;color:var(--muted);text-transform:uppercase;border-bottom:1px solid var(--border)">${h}</th>`).join('')}
      </tr></thead>
      <tbody>${_bacsCandidates.map(inv => `
        <tr>
          <td style="text-align:center;padding:4px 6px;border-bottom:1px solid var(--border)">
            <input type="checkbox" ${_bacsSelected.has(inv.id) ? 'checked' : ''} onchange="bacsToggle(${inv.id}, this.checked)"></td>
          <td style="padding:4px 6px;border-bottom:1px solid var(--border)">${escapeHtml(inv.supplier_name || '')}${inv.is_dd ? ' <span style="font-size:10px;color:var(--muted)">DD</span>' : ''}</td>
          <td style="padding:4px 6px;border-bottom:1px solid var(--border)">${escapeHtml(inv.invoice_ref || '—')}</td>
          <td style="padding:4px 6px;border-bottom:1px solid var(--border);font-family:var(--font-mono)">${escapeHtml(inv.po_reference || '')}</td>
          <td style="padding:4px 6px;border-bottom:1px solid var(--border);${_invSupIsOverdue(inv) ? 'color:var(--red);font-weight:600' : ''}">${_invSupFmtDate(inv.due_date) || '—'}</td>
          <td style="padding:4px 6px;text-align:right;border-bottom:1px solid var(--border)">£${fmt2(inv.gross)}</td>
        </tr>`).join('')}
      </tbody>
    </table>`;
  _bacsRenderTotals();
}

function _bacsRenderTotals() {
  const sel = _bacsCandidates.filter(i => _bacsSelected.has(i.id));
  const total = sumMoney(sel, i => i.gross);
  const suppliers = new Set(sel.map(i => i.supplier_id)).size;
  document.getElementById('bacsTotals').textContent =
    `${sel.length} invoice${sel.length === 1 ? '' : 's'} · ${suppliers} supplier${suppliers === 1 ? '' : 's'} · £${total.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  const btn = document.getElementById('bacsConfirmBtn');
  if (btn) btn.disabled = sel.length === 0;
}

function _bacsDownloadCsv(run, invoices) {
  const esc = v => `"${String(v == null ? '' : v).replace(/"/g, '""')}"`;
  const rows = [['Supplier', 'Invoice Ref', 'PO Ref', 'Invoice Date', 'Due Date', 'Gross'].map(esc).join(',')];
  const bySup = {};
  for (const inv of invoices) {
    rows.push([inv.supplier_name, inv.invoice_ref || '', inv.po_reference || '',
               String(inv.invoice_date || '').slice(0, 10), String(inv.due_date || '').slice(0, 10),
               Number(inv.gross || 0).toFixed(2)].map(esc).join(','));
    bySup[inv.supplier_name] = (bySup[inv.supplier_name] || 0) + Number(inv.gross || 0);
  }
  rows.push('');
  rows.push([esc('PAYMENT PER SUPPLIER'), '', '', '', '', ''].join(','));
  for (const [name, amt] of Object.entries(bySup).sort((a, b) => a[0].localeCompare(b[0])))
    rows.push([esc(name), '', '', '', '', amt.toFixed(2)].join(','));
  rows.push(['', '', '', '', esc('TOTAL'), Number(run.total_gross || 0).toFixed(2)].join(','));
  const blob = new Blob(['\ufeff' + rows.join('\r\n')], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `${run.run_ref || 'payment-run'}.csv`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 5000);
}

async function confirmBacsRun() {
  const sel = _bacsCandidates.filter(i => _bacsSelected.has(i.id));
  if (!sel.length) return;
  const runDate = document.getElementById('bacsRunDate').value;
  if (!runDate) { toast('Pick a payment date', 'error'); return; }
  const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const total = sumMoney(sel, i => i.gross);
  const suppliers = new Set(sel.map(i => i.supplier_id)).size;

  const okGo = await bamaConfirm({
    title: 'Confirm BACS run',
    message: `Mark ${sel.length} invoice${sel.length === 1 ? '' : 's'} across ${suppliers} supplier${suppliers === 1 ? '' : 's'} as paid — total £${fmt2(total)}?\n\nA CSV summary will download and a remittance PDF will be saved to SharePoint for each supplier.`,
    confirmText: 'Run it'
  });
  if (!okGo) return;

  const btn = document.getElementById('bacsConfirmBtn');
  btn.disabled = true;
  setLoading(true);
  try {
    const res = await api.post('/api/supplier-payment-runs', {
      run_date: runDate,
      method: 'BACS',
      run_ref: document.getElementById('bacsRunRef').value.trim() || null,
      period_from: document.getElementById('bacsFrom').value || null,
      period_to: document.getElementById('bacsTo').value || null,
      invoice_ids: sel.map(i => i.id)
    });
    const run = res.run || {};
    const invoices = res.invoices || sel;
    babcockCascadeToast(res.babcock);

    _bacsDownloadCsv(run, invoices);

    // Per-supplier remittance PDFs → SharePoint (non-fatal)
    let remitOk = 0, remitFail = 0;
    const bySupplier = {};
    for (const inv of invoices) (bySupplier[inv.supplier_id] = bySupplier[inv.supplier_id] || []).push(inv);
    for (const [supplierId, invs] of Object.entries(bySupplier)) {
      try {
        const supplier = await _invGetSupplier(parseInt(supplierId));
        const supplierName = (supplier && supplier.supplier_name) || invs[0].supplier_name || 'Supplier';
        const pdfBlob = await renderBamaRemittancePDF({
          supplierName,
          supplierAddress: supplier ? [
            supplier.address_line1, supplier.address_line2,
            [supplier.city, supplier.county].filter(Boolean).join(', '),
            supplier.postcode
          ].filter(Boolean) : [],
          contactName: (supplier && supplier.contact_name) || '',
          payDate: runDate, method: 'BACS', payRef: run.run_ref || '',
          rows: invs.map(inv => ({
            poRef: inv.po_reference || '',
            invRef: inv.invoice_ref || '—',
            invDate: inv.invoice_date || null,
            gross: Number(inv.gross || 0)
          })),
          total: sumMoney(invs, i => i.gross)
        });
        const folder = await _findOrCreateRemittanceFolder(runDate);
        const fileName = sanitizeSpFilename(`Remittance - ${supplierName} - ${runDate}.pdf`);
        await uploadFileToFolder(folder.id, fileName, pdfBlob, 'application/pdf');
        remitOk++;
      } catch (e) {
        console.warn('BACS remittance failed for supplier', supplierId, e);
        remitFail++;
      }
    }

    closeBacsRunModal();
    toast(`BACS run ${run.run_ref || ''} complete ✓ — ${invoices.length} invoices paid` +
          (remitFail ? ` (${remitFail} remittance PDF${remitFail === 1 ? '' : 's'} failed to save)` : ''),
          remitFail ? 'error' : 'success');
    _invRemitSelected.clear();
    await loadInvoicingData();
    renderInvSupplierTable();
  } catch (e) {
    toast('BACS run failed: ' + (e.message || 'unknown error'), 'error');
  } finally {
    btn.disabled = false;
    setLoading(false);
  }
}

// ═════════════════════════════════════════════════════════════════════════
// PAY & REMIT — mark supplier invoices paid + remittance advice PDF + email
// (single-supplier flow; selection is SupplierInvoices ledger rows)
// ═════════════════════════════════════════════════════════════════════════
let _invRemitSelected = new Set();   // SupplierInvoices ids ticked
let _invSuppliersCache = null;       // /api/suppliers (lazy)

function invRemitToggle(invId, checked) {
  if (checked) _invRemitSelected.add(invId);
  else _invRemitSelected.delete(invId);
  _invRemitUpdateBtn();
}

// Header checkbox: (de)select every UNPAID row in the current filtered view.
function invRemitToggleAll(checked) {
  const unpaidVisible = _invSupplierFiltered().filter(i => !i.paid_at);
  for (const inv of unpaidVisible) {
    if (checked) _invRemitSelected.add(inv.id);
    else _invRemitSelected.delete(inv.id);
  }
  renderInvSupplierTable();
}

function _invRemitUpdateBtn() {
  const btn = document.getElementById('invPayRemitBtn');
  const cnt = document.getElementById('invPayRemitCount');
  if (cnt) cnt.textContent = String(_invRemitSelected.size);
  if (btn) btn.disabled = _invRemitSelected.size === 0;
  const mBtn = document.getElementById('invSupMatchBtn');
  const mCnt = document.getElementById('invSupMatchCount');
  if (mCnt) mCnt.textContent = String(_invRemitSelected.size);
  if (mBtn) mBtn.disabled = _invRemitSelected.size === 0;
}

function _invRemitSelection() {
  return _invSupInvoices.filter(i => _invRemitSelected.has(i.id));
}

async function _invGetSupplier(supplierId) {
  if (!_invSuppliersCache) {
    try { _invSuppliersCache = await api.get('/api/suppliers'); }
    catch (e) { _invSuppliersCache = []; }
  }
  return (_invSuppliersCache || []).find(s => s.id === supplierId) || null;
}

function openPayRemitModal() {
  const sel = _invRemitSelection();
  if (!sel.length) { toast('Tick at least one unpaid supplier invoice first', 'error'); return; }
  const supplierIds = [...new Set(sel.map(inv => inv.supplier_id))];
  if (supplierIds.length > 1) {
    toast('One remittance covers one supplier — please select invoices from a single supplier', 'error');
    return;
  }
  document.getElementById('invRemitSupplierLabel').textContent =
    `${sel.length} invoice${sel.length === 1 ? '' : 's'} from ${sel[0].supplier_name || 'supplier'}`;
  document.getElementById('invRemitDate').value = new Date().toISOString().slice(0, 10);
  document.getElementById('invRemitMethod').value = 'BACS';
  document.getElementById('invRemitRef').value = '';

  const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const total = sel.reduce((s, inv) => s + Number(inv.gross || 0), 0);
  document.getElementById('invRemitList').innerHTML = `
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead><tr>
        <th style="text-align:left;padding:5px 8px;font-size:10px;color:var(--muted);text-transform:uppercase;border-bottom:1px solid var(--border)">PO Ref</th>
        <th style="text-align:left;padding:5px 8px;font-size:10px;color:var(--muted);text-transform:uppercase;border-bottom:1px solid var(--border)">Invoice #</th>
        <th style="text-align:left;padding:5px 8px;font-size:10px;color:var(--muted);text-transform:uppercase;border-bottom:1px solid var(--border)">Inv Date</th>
        <th style="text-align:right;padding:5px 8px;font-size:10px;color:var(--muted);text-transform:uppercase;border-bottom:1px solid var(--border)">Gross (£)</th>
      </tr></thead>
      <tbody>${sel.map(inv => `
        <tr>
          <td style="padding:5px 8px;font-family:var(--font-mono);border-bottom:1px solid var(--border)">${escapeHtml(inv.po_reference || '—')}</td>
          <td style="padding:5px 8px;border-bottom:1px solid var(--border)">${escapeHtml(inv.invoice_ref || '—')}</td>
          <td style="padding:5px 8px;border-bottom:1px solid var(--border)">${_invSupFmtDate(inv.invoice_date)}</td>
          <td style="padding:5px 8px;text-align:right;border-bottom:1px solid var(--border)">£${fmt2(inv.gross)}</td>
        </tr>`).join('')}
      </tbody>
    </table>`;
  document.getElementById('invRemitTotal').textContent = '£' + fmt2(total);
  document.getElementById('invRemitModal').classList.add('active');
}

function closePayRemitModal() {
  document.getElementById('invRemitModal').classList.remove('active');
}

async function _findOrCreateRemittanceFolder(payDate) {
  // 01 - Accounts/06 - Remittances/{YYYY}/{MM}/
  const base = await _findOrCreateAccountsSubfolder('06 - Remittances');
  return await _appendYearMonthFolders(base, payDate);
}

async function confirmPayRemit() {
  const sel = _invRemitSelection();
  if (!sel.length) { closePayRemitModal(); return; }
  const payDate = document.getElementById('invRemitDate').value;
  if (!payDate) { toast('Please pick a payment date', 'error'); return; }
  const method = document.getElementById('invRemitMethod').value || 'BACS';
  const payRef = document.getElementById('invRemitRef').value.trim();
  const btn = document.getElementById('invRemitConfirmBtn');

  btn.disabled = true;
  setLoading(true);
  try {
    const supplier = await _invGetSupplier(sel[0].supplier_id);
    const supplierName = (supplier && supplier.supplier_name) || sel[0].supplier_name || 'Supplier';
    const total = +sel.reduce((s, inv) => s + Number(inv.gross || 0), 0).toFixed(2);

    // 1. Render the remittance PDF (deterministic, native jsPDF)
    const pdfData = {
      supplierName,
      supplierAddress: supplier ? [
        supplier.address_line1, supplier.address_line2,
        [supplier.city, supplier.county].filter(Boolean).join(', '),
        supplier.postcode
      ].filter(Boolean) : [],
      contactName: (supplier && supplier.contact_name) || '',
      payDate, method, payRef,
      rows: sel.map(inv => ({
        poRef: inv.po_reference || '',
        invRef: inv.invoice_ref || '—',
        invDate: inv.invoice_date || null,
        gross: Number(inv.gross || 0)
      })),
      total
    };
    const pdfBlob = await renderBamaRemittancePDF(pdfData);

    // 2. Create a payment run for these invoices — marks each paid
    const runRes = await api.post('/api/supplier-payment-runs', {
      run_date: payDate,
      method,
      run_ref: payRef || null,
      invoice_ids: sel.map(inv => inv.id),
      notes: `Pay & Remit — ${supplierName}`
    });
    babcockCascadeToast(runRes && runRes.babcock);

    // 3. Upload the remittance to SharePoint (non-fatal — fall back to a tab)
    let spOk = false;
    const fileName = sanitizeSpFilename(`Remittance - ${supplierName} - ${payDate}.pdf`);
    try {
      const folder = await _findOrCreateRemittanceFolder(payDate);
      await uploadFileToFolder(folder.id, fileName, pdfBlob, 'application/pdf');
      spOk = true;
    } catch (e) {
      console.warn('Remittance SharePoint upload failed:', e);
      try { window.open(URL.createObjectURL(pdfBlob), '_blank'); } catch (e2) { /* */ }
    }

    _invRemitSelected.clear();
    closePayRemitModal();
    toast(`${sel.length} invoice${sel.length === 1 ? '' : 's'} marked paid ✓${spOk ? '' : ' (remittance opened in a tab — SharePoint save failed)'}`,
          spOk ? 'success' : 'error');

    // 4. Email the remittance to the supplier (last mile)
    const contentBase64 = await new Promise((res, rej) => {
      const r = new FileReader();
      r.onload = () => res(String(r.result).split(',')[1]);
      r.onerror = () => rej(new Error('Failed to encode PDF'));
      r.readAsDataURL(pdfBlob);
    });
    const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const payDateUk = new Date(payDate + 'T00:00:00').toLocaleDateString('en-GB');
    const invoiceList = sel.map(inv =>
      `  \u2022 ${inv.invoice_ref || inv.po_reference || ('#' + inv.id)}${inv.invoice_ref && inv.po_reference ? ' (our PO ' + inv.po_reference + ')' : ''} \u2014 \u00a3${fmt2(inv.gross)}`
    ).join('\n');

    await openBabcockEmailModal({
      templateKey: 'emailRemittance',
      title: `Remittance Advice — ${supplierName}`,
      to: (supplier && supplier.email) || '',
      tokens: {
        supplier_name: supplierName,
        contact_name: (supplier && supplier.contact_name) || 'Sir/Madam',
        payment_total: `\u00a3${fmt2(total)}`,
        payment_date: payDateUk,
        payment_method: method,
        payment_ref_line: payRef ? ` (reference ${payRef})` : '',
        invoice_list: invoiceList
      },
      attachment: { name: fileName, contentType: 'application/pdf', contentBase64 },
      aiDraft: {
        defaultTone: 'brief',
        context: `Write a short remittance advice email from BAMA Fabrication Ltd (structural steel fabricator, Peterborough) to a supplier. The remittance advice PDF is attached.

Payment details:
- Supplier: ${supplierName}${pdfData.contactName ? ' (contact: ' + pdfData.contactName + ')' : ''}
- Amount paid: \u00a3${fmt2(total)} by ${method} on ${payDateUk}${payRef ? '\n- Payment reference: ' + payRef : ''}
- Invoices covered:\n${invoiceList}
- Ask them to allocate the payment against the invoices listed.`
      }
    });

    await loadInvoicingData();
    renderInvSupplierTable();
  } catch (err) {
    console.error('Pay & remit failed', err);
    toast('Pay & remit failed: ' + (err.message || 'unknown error'), 'error');
  } finally {
    btn.disabled = false;
    setLoading(false);
  }
}

// ── Remittance advice PDF (native jsPDF — drawDnPDF conventions) ──────────
async function renderBamaRemittancePDF(d) {
  const JsPDFCtor = await _resolveJsPDF();
  const logo = (await loadLogoDataUri().catch(() => '')) || '';
  return drawBamaRemittancePDF(JsPDFCtor, d, logo);
}

function drawBamaRemittancePDF(jsPDF, d, logoDataUri) {
  const fmtNum = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const fmtDate = s => {
    if (!s) return '';
    const m = String(s).match(/^(\d{4})-(\d{2})-(\d{2})/);
    return m ? `${m[3]}/${m[2]}/${m[1]}` : s;
  };

  const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  try {
    doc.setProperties({
      title: `BAMA Remittance Advice — ${d.supplierName || ''}`.trim(),
      author: 'BAMA Fabrication', creator: 'BAMA Fabrication ERP'
    });
  } catch (e) { /* */ }

  const pageW = 210, pageH = 297;
  const marginL = 14, marginR = 14;
  const usableW = pageW - marginL - marginR;
  const RED = [208, 2, 27], NAVY = [31, 53, 82];
  const TEXT = [34, 34, 34], MUTED = [85, 85, 85], RULE = [212, 212, 212];
  const setText = rgb => doc.setTextColor(rgb[0], rgb[1], rgb[2]);
  const setFill = rgb => doc.setFillColor(rgb[0], rgb[1], rgb[2]);
  const setDraw = rgb => doc.setDrawColor(rgb[0], rgb[1], rgb[2]);

  // Header: logo left, title right
  let y = marginL;
  if (logoDataUri) {
    try { doc.addImage(logoDataUri, 'PNG', marginL, y, 75, 32, undefined, 'FAST'); }
    catch (e) {
      doc.setFont('helvetica', 'bold'); doc.setFontSize(22); setText(RED);
      doc.text('BAMA FABRICATION', marginL, y + 12);
    }
  } else {
    doc.setFont('helvetica', 'bold'); doc.setFontSize(22); setText(RED);
    doc.text('BAMA FABRICATION', marginL, y + 12);
  }
  doc.setFont('helvetica', 'normal'); doc.setFontSize(24); setText([43, 43, 43]);
  doc.text('Remittance Advice', pageW - marginR, y + 14, { align: 'right' });

  y = marginL + 42;

  // Two columns: From + To (left) | payment meta (right)
  const leftColW = usableW * 0.58;
  const rightColX = marginL + leftColW + 6;
  let leftY = y, rightY = y;

  setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5);
  doc.text('From', marginL, leftY); leftY += 4.5;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  ['BAMA Fabrication Ltd', '11 Enterprise Way, Enterprise Park, Yaxley,',
   'PE7 3WY, Peterborough', '01733 855212', 'accounts@bamafabrication.co.uk']
    .forEach(line => { doc.text(line, marginL + 4, leftY); leftY += 4; });
  leftY += 4;

  doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5);
  doc.text('To', marginL, leftY); leftY += 4.5;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  const toLines = [d.supplierName, ...(d.supplierAddress || [])].filter(Boolean);
  toLines.forEach(line => {
    doc.splitTextToSize(String(line), leftColW - 4).forEach(w => { doc.text(w, marginL + 4, leftY); leftY += 4; });
  });

  // Right: payment meta box
  const metaRows = [
    ['Payment date', fmtDate(d.payDate)],
    ['Method', d.method || ''],
    ['Reference', d.payRef || '—'],
    ['Total paid', '£' + fmtNum(d.total)]
  ];
  setDraw(RULE);
  metaRows.forEach(([k, v], i) => {
    setText(MUTED); doc.setFont('helvetica', 'bold'); doc.setFontSize(8.5);
    doc.text(k.toUpperCase(), rightColX, rightY);
    setText(i === metaRows.length - 1 ? RED : TEXT);
    doc.setFont('helvetica', i === metaRows.length - 1 ? 'bold' : 'normal'); doc.setFontSize(10);
    doc.text(String(v), pageW - marginR, rightY, { align: 'right' });
    rightY += 3;
    doc.line(rightColX, rightY, pageW - marginR, rightY);
    rightY += 5.5;
  });

  y = Math.max(leftY, rightY) + 8;

  // Invoice table
  const cols = [
    { label: 'Our PO Ref', w: 34, align: 'left' },
    { label: 'Your Invoice #', w: 56, align: 'left' },
    { label: 'Invoice Date', w: 34, align: 'left' },
    { label: 'Amount Paid (£)', w: usableW - 34 - 56 - 34, align: 'right' }
  ];
  const drawTableHead = () => {
    setFill(NAVY);
    doc.rect(marginL, y, usableW, 8, 'F');
    setText([255, 255, 255]); doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
    let x = marginL;
    cols.forEach(c => {
      doc.text(c.label, c.align === 'right' ? x + c.w - 3 : x + 3, y + 5.4, { align: c.align });
      x += c.w;
    });
    y += 8;
  };
  drawTableHead();

  doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5);
  (d.rows || []).forEach((r, i) => {
    if (y > pageH - 40) { doc.addPage(); y = marginL; drawTableHead(); doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5); }
    if (i % 2 === 1) { setFill([245, 245, 245]); doc.rect(marginL, y, usableW, 7, 'F'); }
    setText(TEXT);
    let x = marginL;
    const vals = [r.poRef, r.invRef, fmtDate(r.invDate), fmtNum(r.gross)];
    cols.forEach((c, ci) => {
      doc.text(String(vals[ci] || ''), c.align === 'right' ? x + c.w - 3 : x + 3, y + 4.9, { align: c.align });
      x += c.w;
    });
    y += 7;
  });
  setDraw([68, 68, 68]); doc.line(marginL, y, pageW - marginR, y);
  y += 6;

  // Total pill
  const pillW = 74, pillH = 11;
  setFill(NAVY); doc.roundedRect(pageW - marginR - pillW, y, pillW, pillH, 2, 2, 'F');
  setText([255, 255, 255]); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
  doc.text('TOTAL PAID', pageW - marginR - pillW + 4, y + 7.2);
  doc.setFontSize(12);
  doc.text('£' + fmtNum(d.total), pageW - marginR - 4, y + 7.4, { align: 'right' });
  y += pillH + 10;

  // Note
  setText(TEXT); doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5);
  doc.splitTextToSize(
    `Payment of £${fmtNum(d.total)} has been made by ${d.method || 'bank transfer'} to your account` +
    (d.payRef ? ` under reference ${d.payRef}` : '') +
    '. Please allocate against the invoices listed above. Any queries: accounts@bamafabrication.co.uk.',
    usableW
  ).forEach(line => { doc.text(line, marginL, y); y += 4.5; });

  // Registration footer
  setText(MUTED); doc.setFontSize(8);
  doc.text('BAMA Fabrication Ltd · Registered in England & Wales, Company No. 14680571 · VAT Registration No. 435 0591 07',
           pageW / 2, pageH - 8, { align: 'center' });

  const blob = doc.output('blob');
  console.log('Remittance PDF blob size:', blob.size, blob.size < 8192 ? '⚠ suspiciously small' : 'ok');
  return blob;
}

// ═════════════════════════════════════════════════════════════════════════
// RETENTION HELD — sales-side card + one-click release invoice
// ═════════════════════════════════════════════════════════════════════════
let _invRetentionOpen = false;

function toggleInvRetention() {
  _invRetentionOpen = !_invRetentionOpen;
  const body = document.getElementById('invRetBody');
  const chev = document.getElementById('invRetChevron');
  if (body) body.style.display = _invRetentionOpen ? '' : 'none';
  if (chev) chev.textContent = _invRetentionOpen ? '▼' : '▶';
}

function _invRetentionHeld() {
  // Invoices with retention held that have no active release invoice yet
  return (_invInvoiceList || []).filter(i =>
    i.kind === 'invoice' &&
    !i.is_retention_release &&
    ['Issued', 'Partially Paid', 'Paid'].includes(i.status) &&
    Number(i.retention_amount || 0) > 0.005 &&
    !(_invInvoiceList || []).some(r =>
      r.is_retention_release && r.parent_invoice_id === i.id &&
      !['Void', 'Cancelled'].includes(r.status))
  );
}

function renderInvRetention() {
  const body = document.getElementById('invRetBody');
  const headline = document.getElementById('invRetHeadline');
  if (!body || !headline) return;

  const rows = _invRetentionHeld();
  const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const total = rows.reduce((s, i) => s + Number(i.retention_amount || 0), 0);
  headline.textContent = `£${fmt2(total)} across ${rows.length} invoice${rows.length === 1 ? '' : 's'}`;

  if (!rows.length) {
    body.innerHTML = '<div style="font-size:12px;color:var(--muted)">No retention currently held awaiting release.</div>';
    return;
  }

  const todayStr = new Date().toISOString().slice(0, 10);
  const th = t => `<th style="padding:6px 8px;font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;text-align:left;border-bottom:1px solid var(--border)">${t}</th>`;
  body.innerHTML = `
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead><tr>${th('Invoice')}${th('Customer')}${th('Project')}${th('Retention (£)')}${th('Release Due')}${th('')}</tr></thead>
      <tbody>${rows.map(i => {
        const dueStr = _invToDateStr(i.retention_due_date);
        const overdue = dueStr && dueStr <= todayStr;
        return `
        <tr style="cursor:pointer" onclick="openInvoiceDetail(${i.id})"
            onmouseover="this.style.background='var(--surface2)'" onmouseout="this.style.background=''">
          <td style="padding:6px 8px;font-family:var(--font-mono);font-weight:600;border-bottom:1px solid var(--border)">${escapeHtml(i.ref)}</td>
          <td style="padding:6px 8px;border-bottom:1px solid var(--border)">${escapeHtml(i.client_company_name || i.customer_text || '—')}</td>
          <td style="padding:6px 8px;border-bottom:1px solid var(--border)">${escapeHtml(i.project_number || '')}</td>
          <td style="padding:6px 8px;font-weight:600;border-bottom:1px solid var(--border)">£${fmt2(i.retention_amount)}</td>
          <td style="padding:6px 8px;border-bottom:1px solid var(--border);${overdue ? 'color:var(--red);font-weight:600' : ''}">${dueStr ? new Date(dueStr + 'T00:00:00').toLocaleDateString('en-GB') + (overdue ? ' — due now' : '') : '—'}</td>
          <td style="padding:6px 8px;border-bottom:1px solid var(--border);text-align:right">
            <button class="btn btn-primary" style="padding:3px 10px;font-size:11px"
                    onclick="event.stopPropagation(); raiseRetentionRelease(${i.id})">🔓 Raise Release Invoice</button>
          </td>
        </tr>`;
      }).join('')}</tbody>
    </table>`;
}

async function raiseRetentionRelease(invoiceId) {
  const src = (_invInvoiceList || []).find(i => i.id === invoiceId);
  if (!src) return;
  const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const proceed = await bamaConfirm({
    title: 'Raise retention release invoice',
    body: `Create a Draft invoice for £${fmt2(src.retention_amount)} to release the retention held under ${src.ref}? You can review and edit it before issuing.`,
    icon: '🔓',
    confirmText: 'Create Draft'
  });
  if (!proceed) return;

  setLoading(true);
  try {
    // Full detail carries client VAT treatment + payment terms
    const detail = await api.get(`/api/invoices/${invoiceId}`);
    const net = +(Number(detail.retention_amount || 0)).toFixed(2);
    if (!(net > 0)) { toast('No retention amount on this invoice', 'error'); return; }

    const treatment = detail.client_id
      ? (['standard', 'reverse_charge', 'zero'].includes(detail.client_vat_treatment) ? detail.client_vat_treatment : 'reverse_charge')
      : 'standard';
    const vatApplies = treatment === 'standard';
    const cisReverse = treatment === 'reverse_charge';
    const vat = vatApplies ? +(net * 0.20).toFixed(2) : 0;
    const reverseCharge = cisReverse ? +(net * 0.20).toFixed(2) : 0;
    const gross = +(net + vat).toFixed(2);

    const today = new Date();
    const invoiceDate = today.toISOString().slice(0, 10);
    const terms = Number(detail.client_payment_terms || 30);
    const due = new Date(today.getTime() + terms * 86400000).toISOString().slice(0, 10);

    const projectLabel = detail.project_number
      ? ` — ${detail.project_number}${detail.project_name ? ' ' + detail.project_name : ''}` : '';
    const description = `Release of retention held under invoice ${detail.ref}${projectLabel}`;

    const createdInv = await api.post('/api/invoices', {
      kind: 'invoice',
      is_retention_release: 1,
      parent_invoice_id: detail.id,
      invoice_date: invoiceDate,
      due_date: due,
      client_id: detail.client_id || null,
      customer_text: detail.client_id ? null : (detail.customer_text || null),
      project_id: detail.project_id || null,
      vat_applies: vatApplies ? 1 : 0,
      cis_reverse_charge: cisReverse ? 1 : 0,
      net_amount: net,
      vat_amount: vat,
      reverse_charge_amount: reverseCharge,
      retention_pct: null,
      retention_amount: 0,
      retention_due_date: null,
      gross_amount: gross,
      total_outstanding: gross,
      notes: null,
      line_items: [{ line_no: 1, description, quantity: 1, unit: null, unit_price: net, line_total: net }]
    });

    toast(`Retention release ${createdInv.ref} created as Draft ✓`, 'success');
    await loadInvoicingData();
    renderInvSalesTable();
    openInvoiceDetail(createdInv.id);
  } catch (err) {
    console.error('Raise retention release failed', err);
    toast('Failed to raise release invoice: ' + (err.message || 'unknown error'), 'error');
  } finally {
    setLoading(false);
  }
}

function invStatusBadge(status) {
  if (!status) return '';
  const s = String(status).toLowerCase();
  let bg = 'rgba(120,120,120,.15)', fg = 'var(--muted)';
  if (s === 'paid' || s === 'certified' || s === 'matched')        { bg = 'rgba(62,207,142,.15)'; fg = 'var(--green)'; }
  else if (s === 'draft' || s === 'unmatched')                      { bg = 'rgba(120,120,120,.15)'; fg = 'var(--muted)'; }
  else if (s === 'submitted' || s === 'issued' || s === 'partially paid') { bg = 'rgba(59,130,246,.15)'; fg = '#60a5fa'; }
  else if (s === 'invoiced')                                        { bg = 'rgba(255,165,0,.15)'; fg = '#ffa500'; }
  else if (s === 'cancelled' || s === 'void' || s === 'discrepancy'){ bg = 'rgba(208,2,27,.15)'; fg = 'var(--red)'; }
  return `<span style="display:inline-block;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600;background:${bg};color:${fg}">${escapeHtml(status)}</span>`;
}

// ═══════════════════════════════════════════════════════════════════════════
// AFP (Applications for Payment) — Commit 3 implementation
// ═══════════════════════════════════════════════════════════════════════════
// Two-pane layout, SOV snapshot from QuoteLineItems (AFP01) or prior AFP
// (AFP02+), per-line previous % carry-forward from most-recent Certified AFP,
// Submit → render AFP PDF → upload to ProjectFolder/Application for Payment/,
// Cert upload + Claude vision OCR (header + per-line), Confirm Certified
// Figures → status=Certified, Generate Invoice → new Draft Invoice with
// source_afp_id, lines + retention copied across.
// ───────────────────────────────────────────────────────────────────────────

// Module-level state for the AFP modals
let _afpEditing = null;            // currently-edited AFP (null = new)
let _afpModalProjectId = null;     // project locked for the modal
let _afpLineRows = [];             // working SOV rows in the modal
let _afpDetailCurrent = null;      // currently-open AFP in the detail modal
let _afpCertFile = null;           // raw File for the cert upload
let _afpCertParsed = null;         // OCR result staged
let _afpImportMeta = null;         // { application_no } when SOV came from an AFP import

// ── Project picker (opens when user clicks + New AFP without selecting one) ──
function openAfpProjectPicker() {
  if (_afpSelectedProjectId) {
    openNewAfpModal(_afpSelectedProjectId);
    return;
  }
  const sel = document.getElementById('afpPickerProjectSelect');
  const projects = (_invProjectsCache || []).slice().sort((a, b) =>
    (a.project_name || '').localeCompare(b.project_name || '')
  );
  sel.innerHTML = '<option value="">— pick a project —</option>'
    + projects.map(p => `<option value="${p.id}">${escapeHtml(p.project_number || '')} — ${escapeHtml(p.project_name || '')}</option>`).join('');
  document.getElementById('afpProjectPickerModal').classList.add('active');
}
function closeAfpProjectPicker() {
  document.getElementById('afpProjectPickerModal').classList.remove('active');
}
function confirmAfpProjectPick() {
  const pid = parseInt(document.getElementById('afpPickerProjectSelect').value);
  if (!pid) { toast('Please pick a project', 'error'); return; }
  closeAfpProjectPicker();
  openNewAfpModal(pid);
}

// ── New / Edit AFP modal ──
async function openNewAfpModal(projectId) {
  _afpEditing = null;
  _afpModalProjectId = projectId;
  _afpLineRows = [];
  _afpImportMeta = null;

  const project = (_invProjectsCache || []).find(p => p.id === projectId);
  if (!project) { toast('Project not found', 'error'); return; }

  document.getElementById('afpNewProjectLabel').textContent =
    `${project.project_number || ''} — ${project.project_name || ''}`;

  // Default period = current calendar month
  const today = new Date();
  const monthStart = new Date(today.getFullYear(), today.getMonth(), 1).toISOString().slice(0, 10);
  const monthEnd   = new Date(today.getFullYear(), today.getMonth() + 1, 0).toISOString().slice(0, 10);
  document.getElementById('afpNewPeriodStart').value = monthStart;
  document.getElementById('afpNewPeriodEnd').value   = monthEnd;
  document.getElementById('afpNewIsFinal').checked = false;
  document.getElementById('afpNewRetentionPct').value = '5';
  // Applications for payment are not VAT documents — VAT is applied at the
  // invoice stage. Default OFF (toggle stays available for odd contracts).
  document.getElementById('afpNewVatApplies').checked = false;
  document.getElementById('afpNewNotes').value = '';
  document.getElementById('afpNewContractNo').value = '';
  document.getElementById('afpNewPrevCert').value = '0';

  // Allocate the next AFP ref for this project
  try {
    const r = await api.get(`/api/applications-next-ref?project_id=${projectId}`);
    document.getElementById('afpNewRef').value = r?.ref || 'AFP??';
  } catch (e) {
    document.getElementById('afpNewRef').value = 'AFP??';
  }

  // Pre-populate SOV (handles AFP01 from quote lines OR AFP02+ from prior AFP)
  await _afpPopulateSov(projectId);

  document.getElementById('afpNewModal').classList.add('active');
  recalcAfpTotals();
}

function closeAfpNewModal() {
  document.getElementById('afpNewModal').classList.remove('active');
}

// ── AFP v2: grouped SOV (Measured Works / Variations / Materials) ──────────
// Row model (flat array, grouped by section+item_no for display):
//   { section, item_no, item_description, item_quote_ref, item_wo_no,
//     source_quote_line_item_id, description, contract_value,
//     previous_pct_complete  (cumulative % at last CERTIFIED AFP),
//     this_app_pct_complete  (cumulative % NOW — the sheet's "% Complete"),
//     gross_amount_paid      (cumulative £ certified/paid to date) }
// This-app £ per line = contract × (cum − prev)%. Summary maths mirrors the
// company's Excel: Value of Application (cumulative) − Less Previous
// Contractor Certificate = GROSS Valuation this period − retention = due.
const _AFP_SECTIONS = ['measured', 'variation', 'materials'];
const _AFP_SECTION_LABELS = {
  measured: 'A. Measured Works',
  variation: 'B. Variations',
  materials: 'C. Materials On / Off Site'
};

function _afpRenumberLines() {
  const order = { measured: 0, variation: 1, materials: 2 };
  _afpLineRows.sort((a, b) => {
    const so = (order[a.section] ?? 0) - (order[b.section] ?? 0);
    if (so !== 0) return so;
    return Number(a.item_no || 0) - Number(b.item_no || 0);
  });
  _afpLineRows.forEach((l, i) => { l.line_no = i + 1; });
}

async function _afpPopulateSov(projectId) {
  // All non-cancelled AFPs in this project, most-recent first
  const projectAfps = _invAfpList
    .filter(a => a.project_id === projectId && a.status !== 'Cancelled')
    .sort((a, b) => b.application_no - a.application_no);

  // Most-recent CERTIFIED (or Invoiced) AFP → prev % + paid carry-forward
  const lastCertified = projectAfps.find(a => a.status === 'Certified' || a.status === 'Invoiced');
  let lastCertifiedLines = [];
  if (lastCertified) {
    try {
      const detail = await api.get(`/api/applications/${lastCertified.id}`);
      lastCertifiedLines = detail.line_items || [];
    } catch (e) { /* fall through with empty */ }
  }
  const findCertLine = (sourceQliId, description) => {
    let match = null;
    if (sourceQliId) match = lastCertifiedLines.find(l => l.source_quote_line_item_id === sourceQliId);
    if (!match) match = lastCertifiedLines.find(l => (l.description || '').trim() === (description || '').trim());
    return match || null;
  };

  // Project quotes: primary → Measured Works, additional → Variations
  let projectQuotes = [];
  try { projectQuotes = await api.get(`/api/project-quotes?project_id=${projectId}`) || []; }
  catch (e) { console.warn('Could not load project quotes:', e); }

  const contractNoNow = () => document.getElementById('afpNewContractNo')?.value || '';

  const linesFromQuote = async (pq, section, itemNo) => {
    let qlis = [];
    if (pq.tender_id) {
      qlis = await api.get(`/api/quote-line-items?tender_id=${pq.tender_id}`).catch(() => []) || [];
    }
    const mapped = (qlis || [])
      .filter(l => (Number(l.quantity || 0) * Number(l.unit_price || 0)) !== 0)
      .map(l => ({
        section, item_no: itemNo,
        item_description: pq.quote_project_name || pq.reference || '',
        item_quote_ref: pq.reference || '',
        item_wo_no: contractNoNow(),
        source_quote_line_item_id: l.id,
        description: l.description || l.category || '',
        contract_value: +(Number(l.quantity || 0) * Number(l.unit_price || 0)).toFixed(2),
        previous_pct_complete: 0,
        this_app_pct_complete: 0,
        gross_amount_paid: 0
      }));
    // Fallback: quote has no usable line items (e.g. attached QB quote or a
    // tender without a breakdown) — emit one line carrying the quote value so
    // the item still appears in the SOV.
    if (!mapped.length && Number(pq.quote_value || 0) !== 0) {
      mapped.push({
        section, item_no: itemNo,
        item_description: pq.quote_project_name || pq.reference || '',
        item_quote_ref: pq.reference || '',
        item_wo_no: contractNoNow(),
        source_quote_line_item_id: null,
        description: 'Contract works (as quoted)',
        contract_value: +Number(pq.quote_value || 0).toFixed(2),
        previous_pct_complete: 0,
        this_app_pct_complete: 0,
        gross_amount_paid: 0
      });
    }
    return mapped;
  };

  _afpLineRows = [];

  if (projectAfps.length === 0) {
    // ── AFP01 — build from project quotes
    let mItem = 0, vItem = 0;
    for (const pq of projectQuotes) {
      const section = pq.is_primary ? 'measured' : 'variation';
      const itemNo = pq.is_primary ? ++mItem : ++vItem;
      const lines = await linesFromQuote(pq, section, itemNo);
      _afpLineRows = _afpLineRows.concat(lines);
    }
    if (!_afpLineRows.length) {
      // No quote lines available — start with one empty measured item
      _afpLineRows.push({
        section: 'measured', item_no: 1, item_description: '', item_quote_ref: '',
        item_wo_no: contractNoNow(), source_quote_line_item_id: null, description: '',
        contract_value: 0, previous_pct_complete: 0, this_app_pct_complete: 0, gross_amount_paid: 0
      });
    }
  } else {
    // ── AFP02+ — copy most-recent AFP's SOV, carry prev % / paid from last
    //    CERTIFIED, then auto-pull newly attached quotes as fresh Variations.
    const prevAfp = projectAfps[0];
    try {
      const detail = await api.get(`/api/applications/${prevAfp.id}`);
      _afpLineRows = (detail.line_items || []).map(l => {
        const cert = findCertLine(l.source_quote_line_item_id, l.description);
        return {
          section: l.section || 'measured',
          item_no: l.item_no != null ? Number(l.item_no) : 1,
          item_description: l.item_description || '',
          item_quote_ref: l.item_quote_ref || '',
          item_wo_no: l.item_wo_no || '',
          source_quote_line_item_id: l.source_quote_line_item_id,
          description: l.description,
          contract_value: Number(l.contract_value || 0),
          previous_pct_complete: cert ? Number(cert.this_app_pct_complete || 0) : Number(l.previous_pct_complete || 0),
          this_app_pct_complete: Number(l.this_app_pct_complete || 0),
          gross_amount_paid: cert ? Number(cert.gross_amount_paid || 0) : Number(l.gross_amount_paid || 0)
        };
      });
    } catch (e) { _afpLineRows = []; }

    // VO auto-pull: any project quote whose reference isn't in the SOV yet
    const knownRefs = new Set(_afpLineRows.map(l => (l.item_quote_ref || '').trim()).filter(Boolean));
    let vItem = _afpLineRows.filter(l => l.section === 'variation')
      .reduce((m, l) => Math.max(m, Number(l.item_no || 0)), 0);
    const pulled = [];
    for (const pq of projectQuotes) {
      const ref = String(pq.reference || '').trim();
      if (!ref || knownRefs.has(ref)) continue;
      const lines = await linesFromQuote(pq, 'variation', ++vItem);
      if (lines.length) { _afpLineRows = _afpLineRows.concat(lines); pulled.push(ref); }
      else vItem--;
    }
    if (pulled.length) toast(`Pulled in new quote${pulled.length > 1 ? 's' : ''} as Variation: ${pulled.join(', ')}`, 'success');
  }

  _afpRenumberLines();

  // Banner: "no certified prior AFP" warning
  const banner = document.getElementById('afpNewPrevPctBanner');
  if (banner) banner.style.display = (projectAfps.length > 0 && !lastCertified) ? '' : 'none';

  // "Less Previous Contractor Certificate" auto-suggest — Σ certified net of
  // all prior certified/invoiced AFPs (editable; matches the Excel's E28)
  if (!_afpEditing) {
    const prevCertSum = projectAfps
      .filter(a => a.status === 'Certified' || a.status === 'Invoiced')
      .reduce((s, a) => s + Number(a.certified_value_net || 0), 0);
    const prevCertEl = document.getElementById('afpNewPrevCert');
    if (prevCertEl) prevCertEl.value = prevCertSum ? prevCertSum.toFixed(2) : '0';

    // Contract No + retention % carried from the most recent AFP (per-project sticky)
    if (projectAfps.length) {
      const last = projectAfps[0];
      if (last.contract_no) {
        const cEl = document.getElementById('afpNewContractNo');
        if (cEl && !cEl.value) cEl.value = last.contract_no;
      }
      if (last.retention_pct != null) {
        document.getElementById('afpNewRetentionPct').value = Number(last.retention_pct);
      }
      const wo = document.getElementById('afpNewContractNo')?.value || '';
      if (wo) _afpLineRows.forEach(l => { if (!l.item_wo_no) l.item_wo_no = wo; });
    }
  }

  renderAfpLineRows();
}

function toggleAfpFinal() {
  if (document.getElementById('afpNewIsFinal').checked) {
    _afpLineRows.forEach(l => { l.this_app_pct_complete = 100; });
    renderAfpLineRows();
    recalcAfpTotals();
  }
}

// ── Item / line management ─────────────────────────────────────────────────
function _afpAddItem(section) {
  const nextItem = _afpLineRows.filter(l => l.section === section)
    .reduce((m, l) => Math.max(m, Number(l.item_no || 0)), 0) + 1;
  _afpLineRows.push({
    section, item_no: nextItem, item_description: '', item_quote_ref: '',
    item_wo_no: document.getElementById('afpNewContractNo')?.value || '',
    source_quote_line_item_id: null, description: '',
    contract_value: 0, previous_pct_complete: 0, this_app_pct_complete: 0, gross_amount_paid: 0
  });
  _afpRenumberLines();
  renderAfpLineRows();
}

function _afpAddLineToItem(section, itemNo) {
  const sibling = _afpLineRows.find(l => l.section === section && Number(l.item_no || 0) === Number(itemNo || 0));
  _afpLineRows.push({
    section,
    item_no: itemNo != null ? Number(itemNo) : (section === 'materials' ? 1 : 1),
    item_description: sibling ? sibling.item_description : '',
    item_quote_ref: sibling ? sibling.item_quote_ref : '',
    item_wo_no: sibling ? sibling.item_wo_no : (document.getElementById('afpNewContractNo')?.value || ''),
    source_quote_line_item_id: null, description: '',
    contract_value: 0, previous_pct_complete: 0, this_app_pct_complete: 0, gross_amount_paid: 0
  });
  _afpRenumberLines();
  renderAfpLineRows();
  recalcAfpTotals();
}

function removeAfpItem(section, itemNo) {
  _afpLineRows = _afpLineRows.filter(l => !(l.section === section && Number(l.item_no || 0) === Number(itemNo || 0)));
  // Re-sequence item numbers within the section so display stays 1, 2, 3…
  const items = [...new Set(_afpLineRows.filter(l => l.section === section).map(l => Number(l.item_no || 0)))].sort((a, b) => a - b);
  const remap = new Map(items.map((n, i) => [n, i + 1]));
  _afpLineRows.forEach(l => { if (l.section === section) l.item_no = remap.get(Number(l.item_no || 0)) || 1; });
  _afpRenumberLines();
  renderAfpLineRows();
  recalcAfpTotals();
}

function removeAfpLineRow(idx) {
  const row = _afpLineRows[idx];
  _afpLineRows.splice(idx, 1);
  if (row) {
    const left = _afpLineRows.some(l => l.section === row.section && Number(l.item_no || 0) === Number(row.item_no || 0));
    if (!left && row.section !== 'materials') { removeAfpItem(row.section, row.item_no); return; }
  }
  _afpRenumberLines();
  renderAfpLineRows();
  recalcAfpTotals();
}

function _afpUpdateItemMeta(section, itemNo, field, value) {
  _afpLineRows.forEach(l => {
    if (l.section === section && Number(l.item_no || 0) === Number(itemNo || 0)) l[field] = value;
  });
}

// ── Grouped SOV rendering ──────────────────────────────────────────────────
function renderAfpLineRows() {
  const el = document.getElementById('afpNewLineItems');
  if (!el) return;

  let html = '';
  for (const section of _AFP_SECTIONS) {
    const rows = _afpLineRows.map((l, idx) => ({ l, idx })).filter(r => r.l.section === section);
    if (!rows.length && section === 'measured') continue;
    if (!rows.length && section !== 'measured') {
      // still render the section bar with its add button so it's discoverable
      html += `
        <div style="display:flex;justify-content:space-between;align-items:center;background:var(--surface2);
                    padding:5px 10px;border-radius:6px;margin-top:8px">
          <span style="font-size:11px;font-weight:700;letter-spacing:.5px;text-transform:uppercase;color:var(--muted)">
            ${_AFP_SECTION_LABELS[section]}</span>
          <button type="button" class="btn btn-ghost" style="padding:2px 8px;font-size:10px"
                  onclick="${section === 'materials' ? "_afpAddLineToItem('materials', 1)" : "_afpAddItem('variation')"}">+ Add</button>
        </div>`;
      continue;
    }
    html += `
      <div style="display:flex;justify-content:space-between;align-items:center;background:var(--surface2);
                  padding:5px 10px;border-radius:6px;margin-top:8px">
        <span style="font-size:11px;font-weight:700;letter-spacing:.5px;text-transform:uppercase">
          ${_AFP_SECTION_LABELS[section]}</span>
        <button type="button" class="btn btn-ghost" style="padding:2px 8px;font-size:10px"
                onclick="${section === 'materials' ? "_afpAddLineToItem('materials', 1)" : `_afpAddItem('${section}')`}">+ Add ${section === 'materials' ? 'Line' : 'Item'}</button>
      </div>`;

    if (section === 'materials') {
      html += rows.map(({ l, idx }) => _afpLineRowHtml(l, idx)).join('');
      continue;
    }

    // group by item_no
    const itemNos = [...new Set(rows.map(r => Number(r.l.item_no || 0)))].sort((a, b) => a - b);
    for (const itemNo of itemNos) {
      const itemRows = rows.filter(r => Number(r.l.item_no || 0) === itemNo);
      const meta = itemRows[0].l;
      html += `
        <div style="display:grid;grid-template-columns:34px 1fr 105px 125px 26px 26px;gap:6px;align-items:center;
                    margin-top:6px;padding:4px 4px 4px 0;border-left:3px solid var(--accent);background:rgba(255,255,255,.02);border-radius:4px">
          <div style="text-align:center;font-family:var(--font-mono);font-weight:700;color:var(--accent)">${itemNo}</div>
          <input type="text" class="field-input" placeholder="Item description (scope)" style="font-weight:600"
                 value="${escapeHtml(meta.item_description || '')}"
                 oninput="_afpUpdateItemMeta('${section}', ${itemNo}, 'item_description', this.value)">
          <input type="text" class="field-input" placeholder="Quote No" style="font-family:var(--font-mono);font-size:12px"
                 value="${escapeHtml(meta.item_quote_ref || '')}"
                 oninput="_afpUpdateItemMeta('${section}', ${itemNo}, 'item_quote_ref', this.value)">
          <input type="text" class="field-input" placeholder="WO / Contract No" style="font-family:var(--font-mono);font-size:12px"
                 value="${escapeHtml(meta.item_wo_no || '')}"
                 oninput="_afpUpdateItemMeta('${section}', ${itemNo}, 'item_wo_no', this.value)">
          <button type="button" class="btn btn-ghost" title="Add line to this item"
                  style="padding:2px 6px;font-size:12px" onclick="_afpAddLineToItem('${section}', ${itemNo})">＋</button>
          <button type="button" class="btn btn-ghost" title="Remove whole item"
                  style="padding:2px 6px;font-size:12px;color:var(--red);border-color:var(--red)"
                  onclick="removeAfpItem('${section}', ${itemNo})">✕</button>
        </div>`;
      html += itemRows.map(({ l, idx }) => _afpLineRowHtml(l, idx)).join('');
    }
  }
  el.innerHTML = html || '<div style="color:var(--muted);font-size:12px;padding:8px">No lines — use + Add buttons above.</div>';
  recalcAfpTotals();
}

function _afpLineRowHtml(l, idx) {
  const cv = Number(l.contract_value || 0);
  const prev = Number(l.previous_pct_complete || 0);
  const cum = Number(l.this_app_pct_complete || 0);
  const thisApp = cv * (cum - prev) / 100;
  return `
    <div data-afp-idx="${idx}"
         style="display:grid;grid-template-columns:1fr 92px 48px 92px 62px 92px 26px;gap:6px;align-items:center;margin-top:4px;padding-left:37px">
      <input type="text" class="field-input" placeholder="Description" style="font-size:12px;padding:5px 8px"
             value="${escapeHtml(l.description || '')}"
             oninput="_afpLineRows[${idx}].description = this.value">
      <input type="number" step="0.01" class="field-input" placeholder="Value £" style="font-size:12px;padding:5px 8px;text-align:right"
             value="${cv || ''}"
             oninput="_afpLineRows[${idx}].contract_value = parseFloat(this.value) || 0; updateAfpLineRowCalc(${idx})">
      <div class="afp-prev" title="Cumulative % at last certified AFP"
           style="font-size:11px;text-align:center;color:var(--muted)">${prev.toFixed(0)}%</div>
      <input type="range" min="0" max="100" step="5" value="${cum}"
             style="width:100%;accent-color:var(--accent)"
             oninput="syncAfpPct(${idx}, this.value, true)">
      <input type="number" step="0.5" min="0" max="100" class="field-input afp-cum"
             style="font-size:12px;padding:5px 6px;text-align:center" value="${cum}"
             oninput="syncAfpPct(${idx}, this.value, false)">
      <div class="afp-thisapp" title="This application £ (cum − prev)"
           style="font-size:12px;text-align:right;font-family:var(--font-mono)">£${Number(thisApp).toLocaleString('en-GB', { minimumFractionDigits: 2 })}</div>
      <button type="button" class="btn btn-ghost" style="padding:2px 6px;font-size:12px;color:var(--red);border-color:var(--red)"
              onclick="removeAfpLineRow(${idx})">×</button>
    </div>`;
}

// Slider ↔ number sync + targeted recalc (no full re-render, keeps focus)
function syncAfpPct(idx, val, fromSlider) {
  const l = _afpLineRows[idx];
  if (!l) return;
  l.this_app_pct_complete = Math.min(100, Math.max(0, parseFloat(val) || 0));
  const row = document.querySelector(`#afpNewLineItems [data-afp-idx="${idx}"]`);
  if (row) {
    const slider = row.querySelector('input[type="range"]');
    const num = row.querySelector('.afp-cum');
    if (fromSlider && num) num.value = l.this_app_pct_complete;
    if (!fromSlider && slider) slider.value = l.this_app_pct_complete;
  }
  updateAfpLineRowCalc(idx);
}

function updateAfpLineRowCalc(idx) {
  const l = _afpLineRows[idx];
  if (!l) return;
  const thisApp = Number(l.contract_value || 0) * (Number(l.this_app_pct_complete || 0) - Number(l.previous_pct_complete || 0)) / 100;
  const row = document.querySelector(`#afpNewLineItems [data-afp-idx="${idx}"]`);
  if (row) {
    const cell = row.querySelector('.afp-thisapp');
    if (cell) cell.textContent = '£' + Number(thisApp).toLocaleString('en-GB', { minimumFractionDigits: 2 });
  }
  recalcAfpTotals();
}

// ── Summary maths (mirrors the company Excel) ──────────────────────────────
function _afpComputeTotals() {
  const cumTotal = _afpLineRows.reduce((s, l) =>
    s + Number(l.contract_value || 0) * Number(l.this_app_pct_complete || 0) / 100, 0);
  const prevCert = Number(document.getElementById('afpNewPrevCert')?.value || 0);
  const grossVal = cumTotal - prevCert;                       // this application
  const retentionPct = Number(document.getElementById('afpNewRetentionPct')?.value || 0);
  const retention = +(grossVal * retentionPct / 100).toFixed(2);
  const vatApplies = document.getElementById('afpNewVatApplies')?.checked;
  const vat = vatApplies ? +((grossVal - retention) * 0.20).toFixed(2) : 0;
  const due = +(grossVal - retention + vat).toFixed(2);
  return { cumTotal: +cumTotal.toFixed(2), prevCert, grossVal: +grossVal.toFixed(2), retentionPct, retention, vat, due };
}

function recalcAfpTotals() {
  const t = _afpComputeTotals();
  const fmt = v => '£' + Number(v).toLocaleString('en-GB', { minimumFractionDigits: 2 });
  const set = (id, v) => { const e = document.getElementById(id); if (e) e.textContent = v; };
  set('afpTotalCum', fmt(t.cumTotal));
  set('afpTotalPrevCert', fmt(t.prevCert));
  set('afpTotalNet', fmt(t.grossVal));
  set('afpTotalRetention', fmt(t.retention));
  set('afpTotalVat', fmt(t.vat));
  set('afpTotalGross', fmt(t.due));
}

// ═══ AFP IMPORT — onboard a mid-project job from its latest AFP file ═══════
// Two-engine rule: the strict SheetJS parser (or Claude for PDFs / drifted
// layouts) only READS the document; all cumulative maths stays in JS.
// Flow: pick .xlsx/.pdf → parse → populate SOV + header fields → user reviews
// in the modal → Save Draft / Submit as usual.

async function importAfpFromFile(file) {
  if (!file) return;
  const ext = (file.name.split('.').pop() || '').toLowerCase();
  if (!['xlsx', 'xls', 'pdf'].includes(ext)) {
    toast('Please upload an .xlsx, .xls or .pdf AFP', 'error');
    return;
  }
  try {
    setLoading(true);
    let parsed = null;
    if (ext === 'pdf') {
      toast('Reading AFP PDF with AI…', 'info');
      parsed = await parseAfpWithAI({ kind: 'pdf', file });
    } else {
      if (typeof XLSX === 'undefined') throw new Error('XLSX library not loaded on this page');
      const buf = await file.arrayBuffer();
      const wb = XLSX.read(buf, { type: 'array' });
      try {
        parsed = parseAfpWorkbook(wb);
        if (!parsed.items.length) throw new Error('no items found');
      } catch (strictErr) {
        console.warn('Strict AFP parse failed, falling back to AI:', strictErr.message);
        toast('Standard parse failed — reading with AI…', 'info');
        const csv = wb.SheetNames.map(n => XLSX.utils.sheet_to_csv(wb.Sheets[n])).join('\n\n');
        parsed = await parseAfpWithAI({ kind: 'csv', text: csv });
      }
    }
    _applyImportedAfp(parsed);
  } catch (err) {
    console.error('AFP import failed', err);
    toast('Import failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    setLoading(false);
    const inp = document.getElementById('afpImportFile');
    if (inp) inp.value = '';
  }
}

// Deterministic parser for BAMA's own AFP workbook layout.
// Landmarks: 'Contract No:' row, 'Less Previous Contractor certificate' row,
// '(Less Retention @ X%)' row, section heads A./B./C., 'Item No.' table
// headers, item rows (numeric col B), sub-lines (text col C + numeric col I).
function parseAfpWorkbook(wb) {
  const ws = wb.Sheets['Application'] || wb.Sheets[wb.SheetNames[0]];
  const rows = XLSX.utils.sheet_to_json(ws, { header: 1, raw: true, defval: null });
  const cell = (r, c) => (rows[r] && rows[r][c] != null) ? rows[r][c] : null;
  const str = v => v == null ? '' : String(v).trim();

  const out = { contract_no: null, previous_certificate_value: null, retention_pct: null,
                valuation_no: null, period_end: null, items: [] };

  let section = null;      // 'measured' | 'variation' | 'materials'
  let currentItem = null;
  const itemCounters = { measured: 0, variation: 0, materials: 0 };

  for (let r = 0; r < rows.length; r++) {
    const a = str(cell(r, 0)), b = cell(r, 1), c = str(cell(r, 2));

    // Header landmarks
    const valMatch = a.match(/^valuation no\s*(\d+)/i);
    if (valMatch) {
      out.valuation_no = Number(valMatch[1]);
      const dm = c.match(/up to\s+(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\s+(\d{4})/i);
      if (dm) {
        const dt = new Date(`${dm[1]} ${dm[2]} ${dm[3]}`);
        if (!isNaN(dt)) out.period_end = dt.toISOString().slice(0, 10);
      }
    }
    if (/^contract no:?$/i.test(a) && c) out.contract_no = c;
    if (/less previous contractor certificate/i.test(c)) {
      const v = Number(cell(r, 4));
      if (!isNaN(v)) out.previous_certificate_value = v;
    }
    const retMatch = c.match(/less retention @\s*([\d.]+)\s*%/i);
    if (retMatch) out.retention_pct = Number(retMatch[1]);

    // Section switches — the table headings (summary rows A./B./C. also match
    // on text, so require the *long* headings used above the tables)
    if (/measured works complete/i.test(c)) { section = 'measured'; currentItem = null; continue; }
    if (section && /^variations$/i.test(c) && a === 'B.') { section = 'variation'; currentItem = null; continue; }
    if (/materials off site/i.test(c)) { section = 'materials'; currentItem = null; continue; }
    if (!section) continue;

    // Section total rows end the current item
    if (/^total /i.test(c) || /^total\b/i.test(c) && /variations|measured|materials/i.test(c)) { currentItem = null; continue; }

    const bNum = (typeof b === 'number') ? b : (b != null && String(b).trim() !== '' && !isNaN(Number(b)) ? Number(b) : null);
    const iVal = Number(cell(r, 8));   // col I — Gross Application Value
    const jPct = cell(r, 9);           // col J — % Complete (fraction)
    const lPaid = Number(cell(r, 11)); // col L — Gross Amount Paid

    // Item start: numeric col B + descriptive col C
    if (bNum != null && c) {
      itemCounters[section]++;
      currentItem = {
        section,
        item_no: itemCounters[section],
        description: c,
        quote_ref: str(cell(r, 3)),
        wo_no: str(cell(r, 4)),
        lines: []
      };
      out.items.push(currentItem);
      // Single-line item (value on the item row itself, e.g. "Additional day of drilling")
      if (!isNaN(iVal) && iVal !== 0) {
        currentItem.lines.push({
          description: c,
          value: iVal,
          pct_complete: jPct != null ? Number(jPct) * 100 : 0,
          gross_amount_paid: !isNaN(lPaid) ? lPaid : 0
        });
      }
      continue;
    }

    // Sub-line: col C text + col I numeric, inside an item
    if (currentItem && c && !isNaN(iVal) && cell(r, 8) != null) {
      currentItem.lines.push({
        description: c,
        value: iVal,
        pct_complete: jPct != null ? Number(jPct) * 100 : 0,
        gross_amount_paid: !isNaN(lPaid) ? lPaid : 0
      });
    }
  }

  out.items = out.items.filter(it => it.lines.length);
  return out;
}

// AI fallback / PDF path — Claude reads and extracts, JS does all maths.
async function parseAfpWithAI({ kind, file, text }) {
  const prompt = `Extract the full schedule of values from this UK construction Application for Payment. Return ONLY JSON, no markdown:
{
  "contract_no": "client contract/WO no e.g. S-CM0665/0028 or null",
  "valuation_no": 6,
  "period_end": "YYYY-MM-DD (the 'works carried out up to' date, null if absent)",
  "previous_certificate_value": 0,
  "retention_pct": 5,
  "items": [
    {
      "section": "measured|variation|materials",
      "item_no": 1,
      "description": "the item heading / scope text",
      "quote_ref": "BAMA quote no e.g. Q250911 or empty",
      "wo_no": "works order no or empty",
      "lines": [
        { "description": "Prelims", "value": 672.00, "pct_complete": 85, "gross_amount_paid": 504.00 }
      ]
    }
  ]
}
Rules:
- section: Measured Works table → "measured"; Variations table → "variation"; Materials → "materials".
- value = the line's Gross Application Value £ (the contract value, NOT the completed total).
- pct_complete = the % Complete column as 0–100.
- gross_amount_paid = the Gross Amount Paid column (0 if blank).
- Include every item and every sub-line, including 0% ones. Numbers without currency symbols or thousands separators.`;

  const content = [];
  if (kind === 'pdf') {
    const dataUri = await _fileToDataUri(file);
    content.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: dataUri.split(',')[1] } });
    content.push({ type: 'text', text: prompt });
  } else {
    content.push({ type: 'text', text: prompt + '\n\nSpreadsheet contents as CSV:\n' + text });
  }

  const result = await callClaude({
    model: 'claude-sonnet-4-6',
    max_tokens: 8000,
    messages: [{ role: 'user', content }]
  });
  const raw = (result.content?.find(bl => bl.type === 'text')?.text || '').trim();
  const js = raw.indexOf('{'), je = raw.lastIndexOf('}');
  if (js < 0 || je < 0) throw new Error('AI returned no JSON');
  const parsed = JSON.parse(raw.slice(js, je + 1));
  parsed.items = (parsed.items || []).filter(it => (it.lines || []).length);
  return parsed;
}

// Map an imported AFP into the working SOV. The imported document is the
// LATEST application, so its cumulative % becomes the new AFP's starting
// point (prev = cum = imported %), and its Paid column carries forward.
function _applyImportedAfp(parsed) {
  const woDefault = parsed.contract_no || document.getElementById('afpNewContractNo')?.value || '';
  const counters = { measured: 0, variation: 0, materials: 0 };
  const rows = [];
  for (const item of (parsed.items || [])) {
    const section = ['measured', 'variation', 'materials'].includes(item.section) ? item.section : 'measured';
    const itemNo = ++counters[section];
    for (const l of (item.lines || [])) {
      const pct = Math.min(100, Math.max(0, Number(l.pct_complete || 0)));
      rows.push({
        section, item_no: itemNo,
        item_description: item.description || '',
        item_quote_ref: item.quote_ref || '',
        item_wo_no: item.wo_no || woDefault,
        source_quote_line_item_id: null,
        description: l.description || '',
        contract_value: +Number(l.value || 0).toFixed(2),
        previous_pct_complete: pct,
        this_app_pct_complete: pct,
        gross_amount_paid: +Number(l.gross_amount_paid || 0).toFixed(2)
      });
    }
  }
  if (!rows.length) { toast('Nothing usable found in that file', 'error'); return; }

  _afpLineRows = rows;
  _afpRenumberLines();

  if (parsed.contract_no) document.getElementById('afpNewContractNo').value = parsed.contract_no;
  if (parsed.retention_pct != null) document.getElementById('afpNewRetentionPct').value = Number(parsed.retention_pct);

  // The import RECREATES the document itself (e.g. AFP06) — its own number,
  // period and "Less Previous Certificate". The next AFP raised afterwards
  // continues the sequence automatically (server allocates MAX+1).
  document.getElementById('afpNewPrevCert').value =
    parsed.previous_certificate_value != null ? Number(parsed.previous_certificate_value).toFixed(2) : '0';

  _afpImportMeta = null;
  if (parsed.valuation_no != null && Number(parsed.valuation_no) > 0 && !_afpEditing) {
    _afpImportMeta = { application_no: Math.floor(Number(parsed.valuation_no)) };
    const refStr = 'AFP' + String(_afpImportMeta.application_no).padStart(2, '0');
    document.getElementById('afpNewRef').value = refStr;
  }
  if (parsed.period_end) {
    document.getElementById('afpNewPeriodEnd').value = parsed.period_end;
    const pe = new Date(parsed.period_end);
    if (!isNaN(pe)) {
      const ps = new Date(pe.getFullYear(), pe.getMonth(), 1);
      document.getElementById('afpNewPeriodStart').value =
        `${ps.getFullYear()}-${String(ps.getMonth() + 1).padStart(2, '0')}-01`;
    }
  }

  renderAfpLineRows();
  recalcAfpTotals();
  const nItems = counters.measured + counters.variation + counters.materials;
  toast(`Imported ${_afpImportMeta ? 'AFP ' + _afpImportMeta.application_no + ' — ' : ''}${nItems} items / ${rows.length} lines ✓. This recreates the imported application; the next AFP will number itself automatically.`, 'success');
}

function _afpFormatPeriodLabel(start, end) {
  if (!start || !end) return '';
  const s = new Date(start), e = new Date(end);
  const dd = (d) => d.toLocaleDateString('en-GB');
  return `${dd(s)} – ${dd(e)}`;
}

function _buildAfpPayload() {
  if (_afpLineRows.length === 0 || _afpLineRows.every(l => !(l.description || '').trim())) {
    toast('Please add at least one line item', 'error'); return null;
  }
  if (!document.getElementById('afpNewPeriodStart').value || !document.getElementById('afpNewPeriodEnd').value) {
    toast('Period start and end dates required', 'error'); return null;
  }
  const t = _afpComputeTotals();
  const cleanLines = _afpLineRows
    .filter(l => l.description && l.description.trim())
    .map((l, i) => {
      const cv = Number(l.contract_value || 0);
      const cumPct = Number(l.this_app_pct_complete || 0);
      const prevPct = Number(l.previous_pct_complete || 0);
      return {
        line_no: i + 1,
        section: l.section || 'measured',
        item_no: l.item_no != null ? Number(l.item_no) : null,
        item_description: (l.item_description || '').trim() || null,
        item_quote_ref: (l.item_quote_ref || '').trim() || null,
        item_wo_no: (l.item_wo_no || '').trim() || null,
        source_quote_line_item_id: l.source_quote_line_item_id || null,
        description: l.description.trim(),
        contract_value: cv,
        previous_pct_complete: prevPct,
        this_app_pct_complete: cumPct,
        this_app_value: +(cv * (cumPct - prevPct) / 100).toFixed(2),
        cumulative_value: +(cv * cumPct / 100).toFixed(2),
        gross_amount_paid: l.gross_amount_paid != null ? Number(l.gross_amount_paid) : null
      };
    });

  return {
    project_id:        _afpModalProjectId,
    application_no:    (!_afpEditing && _afpImportMeta) ? _afpImportMeta.application_no : undefined,
    period_start:      document.getElementById('afpNewPeriodStart').value,
    period_end:        document.getElementById('afpNewPeriodEnd').value,
    period_label:      _afpFormatPeriodLabel(
                          document.getElementById('afpNewPeriodStart').value,
                          document.getElementById('afpNewPeriodEnd').value
                       ),
    is_final:          document.getElementById('afpNewIsFinal').checked ? 1 : 0,
    applied_value_net: t.grossVal,
    applied_vat:       t.vat,
    applied_retention: t.retention,
    applied_gross:     t.due,
    cumulative_value_net:        t.cumTotal,
    previous_certificate_value:  t.prevCert,
    retention_pct:               t.retentionPct,
    contract_no:       (document.getElementById('afpNewContractNo')?.value || '').trim() || null,
    notes:             document.getElementById('afpNewNotes').value || null,
    line_items:        cleanLines
  };
}

async function saveAfpDraft() {
  const payload = _buildAfpPayload();
  if (!payload) return;
  const btn = document.getElementById('afpSaveDraftBtn');
  try {
    if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
    let saved;
    if (_afpEditing) {
      saved = await api.put(`/api/applications/${_afpEditing.id}`, payload);
    } else {
      saved = await api.post('/api/applications', payload);
      _afpEditing = saved;
      _afpImportMeta = null;
    }
    toast(`AFP ${saved.ref} saved as Draft ✓`, 'success');
    closeAfpNewModal();
    await loadInvoicingData();
    _afpSelectedProjectId = payload.project_id;
    renderInvAfpsTable();
  } catch (err) {
    console.error('Save AFP failed', err);
    toast('Save failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Save Draft'; }
  }
}

async function saveAndSubmitAfp() {
  const payload = _buildAfpPayload();
  if (!payload) return;
  const btn = document.getElementById('afpSubmitBtn');
  try {
    if (btn) { btn.disabled = true; btn.textContent = 'Submitting…'; }
    setLoading(true);
    let saved;
    if (_afpEditing) {
      saved = await api.put(`/api/applications/${_afpEditing.id}`, payload);
    } else {
      saved = await api.post('/api/applications', payload);
      // Creation succeeded — from here on the AFP EXISTS. Switch the modal to
      // edit mode immediately so any failure below (PDF/SharePoint) leaves a
      // retry that UPDATEs instead of re-creating ("AFP number already exists").
      _afpEditing = saved;
      _afpImportMeta = null;
    }
    const full = await api.get(`/api/applications/${saved.id}`);
    await loadLogoDataUri();
    const pdfData = _buildAfpPdfData(full);
    const pdfBlob = await renderBamaAfpPDF(pdfData);

    // SharePoint upload — best effort. Each project gets its own
    // "08 - Application for payment" folder under its OWN project folder; if
    // the project has no folder set (or Graph fails), fall back to opening
    // the PDF in a tab and still submit.
    let driveItem = null;
    const project = (_invProjectsCache || []).find(p => p.id === saved.project_id);
    if (project && project.sharepoint_folder_id) {
      try {
        const afpFolder = await getOrCreateSubfolder(project.sharepoint_folder_id, '08 - Application for payment', BAMA_DRIVE_ID);
        const fileName = sanitizeSpFilename(`${saved.ref}.pdf`);
        driveItem = await uploadFileToFolder(afpFolder.id, fileName, pdfBlob, 'application/pdf');
      } catch (spErr) {
        console.warn('AFP SharePoint upload failed, falling back to tab:', spErr);
      }
    }
    if (!driveItem) {
      try { window.open(URL.createObjectURL(pdfBlob), '_blank'); } catch (e) { /* popup blocked */ }
    }
    await api.post(`/api/applications/${saved.id}/submit`, driveItem ? {
      sharepoint_pdf_id:  driveItem.id,
      sharepoint_pdf_url: driveItem.webUrl
    } : {});
    if (driveItem) {
      toast(`AFP ${saved.ref} submitted ✓`, 'success');
    } else {
      toast(`AFP ${saved.ref} submitted ✓ — no SharePoint folder on this project, PDF opened in a new tab (save it manually or set the folder in Projects tracker and re-submit)`, 'warning');
    }
    closeAfpNewModal();
    await loadInvoicingData();
    _afpSelectedProjectId = saved.project_id;
    renderInvAfpsTable();
  } catch (err) {
    console.error('Submit AFP failed', err);
    toast('Submit failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    setLoading(false);
    if (btn) { btn.disabled = false; btn.textContent = 'Save & Submit'; }
  }
}

// ═════════════════════════════════════════════════════════════════════════
// AFP DETAIL MODAL
// ═════════════════════════════════════════════════════════════════════════
function _afpDetailLinesHtml(lines) {
  const fmt = v => '£' + Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 });
  const td = 'padding:6px 8px;border-bottom:1px solid var(--border)';
  const sections = ['measured', 'variation', 'materials'];
  let html = '';
  for (const section of sections) {
    const rows = lines.filter(l => (l.section || 'measured') === section);
    if (!rows.length) continue;
    html += `<tr><td colspan="8" style="padding:6px 8px;background:var(--surface2);font-size:11px;
             font-weight:700;text-transform:uppercase;letter-spacing:.5px">${_AFP_SECTION_LABELS[section] || section}</td></tr>`;
    const itemNos = [...new Set(rows.map(l => Number(l.item_no || 0)))].sort((a, b) => a - b);
    for (const itemNo of itemNos) {
      const itemRows = rows.filter(l => Number(l.item_no || 0) === itemNo);
      const meta = itemRows[0];
      if (section !== 'materials' && (meta.item_description || meta.item_quote_ref)) {
        html += `<tr><td colspan="8" style="padding:6px 8px;border-bottom:1px solid var(--border);
                 background:rgba(255,255,255,.02)">
          <span style="font-family:var(--font-mono);font-weight:700;color:var(--accent)">${itemNo}</span>
          <span style="font-weight:600;margin-left:8px">${escapeHtml(meta.item_description || '')}</span>
          <span style="float:right;font-family:var(--font-mono);font-size:11px;color:var(--muted)">
            ${escapeHtml(meta.item_quote_ref || '')}${meta.item_wo_no ? ' · ' + escapeHtml(meta.item_wo_no) : ''}</span>
        </td></tr>`;
      }
      html += itemRows.map(l => {
        const paid = l.gross_amount_paid != null ? Number(l.gross_amount_paid) : null;
        return `<tr>
          <td style="${td};padding-left:24px">${escapeHtml(l.description || '')}</td>
          <td style="${td};text-align:right">${fmt(l.contract_value)}</td>
          <td style="${td};text-align:center;color:var(--muted)">${Number(l.previous_pct_complete || 0).toFixed(0)}%</td>
          <td style="${td};text-align:center;font-weight:600">${Number(l.this_app_pct_complete || 0).toFixed(0)}%</td>
          <td style="${td};text-align:right">${fmt(l.this_app_value)}</td>
          <td style="${td};text-align:right">${fmt(l.cumulative_value)}</td>
          <td style="${td};text-align:right;color:var(--muted)">${paid != null ? fmt(paid) : '—'}</td>
          <td style="${td};text-align:right">${l.certified_this_app_value != null ? fmt(l.certified_this_app_value) : '—'}</td>
        </tr>`;
      }).join('');
    }
  }
  return html;
}

async function openAfpDetail(id) {
  try {
    const afp = await api.get(`/api/applications/${id}`);
    _afpDetailCurrent = afp;

    document.getElementById('afpDetailRef').textContent = afp.ref;
    document.getElementById('afpDetailStatus').innerHTML = invStatusBadge(afp.status);
    document.getElementById('afpDetailProject').textContent =
      `${afp.project_number || ''} — ${afp.project_name || ''}`;
    document.getElementById('afpDetailPeriod').textContent =
      _afpFormatPeriodLabel(afp.period_start, afp.period_end) || afp.period_label || '—';
    document.getElementById('afpDetailFinal').textContent = afp.is_final ? 'YES (Final Application)' : 'No';

    // v2 summary strip: cumulative application / less prev cert / contract no
    const v2Strip = document.getElementById('afpDetailV2Strip');
    if (v2Strip) {
      const fmtV = v => '£' + Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 });
      v2Strip.innerHTML = `
        <div><div style="color:var(--muted);font-size:11px;text-transform:uppercase">Value of Application (Cum)</div>
             <div style="font-weight:600">${afp.cumulative_value_net != null ? fmtV(afp.cumulative_value_net) : '—'}</div></div>
        <div><div style="color:var(--muted);font-size:11px;text-transform:uppercase">Less Previous Certificate</div>
             <div style="font-weight:600">${afp.previous_certificate_value != null ? fmtV(afp.previous_certificate_value) : '—'}</div></div>
        <div><div style="color:var(--muted);font-size:11px;text-transform:uppercase">Contract No</div>
             <div style="font-family:var(--font-mono)">${escapeHtml(afp.contract_no || '—')}</div></div>`;
    }

    // Applied totals
    document.getElementById('afpDetailAppliedNet').textContent      = '£' + Number(afp.applied_value_net || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 });
    document.getElementById('afpDetailAppliedRet').textContent      = '£' + Number(afp.applied_retention || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 });
    document.getElementById('afpDetailAppliedVat').textContent      = '£' + Number(afp.applied_vat || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 });
    document.getElementById('afpDetailAppliedGross').textContent    = '£' + Number(afp.applied_gross || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 });

    // Certified totals (blank if not yet certified)
    const isCert = (afp.status === 'Certified' || afp.status === 'Invoiced');
    document.getElementById('afpDetailCertifiedNet').textContent    = isCert ? '£' + Number(afp.certified_value_net || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 }) : '—';
    document.getElementById('afpDetailCertifiedRet').textContent    = isCert ? '£' + Number(afp.certified_retention || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 }) : '—';
    document.getElementById('afpDetailCertifiedVat').textContent    = isCert ? '£' + Number(afp.certified_vat || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 }) : '—';
    document.getElementById('afpDetailCertifiedGross').textContent  = isCert ? '£' + Number(afp.certified_gross || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 }) : '—';

    // Line items table — grouped by section → item
    document.getElementById('afpDetailLines').innerHTML =
      _afpDetailLinesHtml(afp.line_items || []) ||
      '<tr><td colspan="8" style="padding:10px;color:var(--muted)">No line items</td></tr>';

    // PDF + Cert links
    const pdfBtn  = document.getElementById('afpDetailPdfBtn');
    const certBtn = document.getElementById('afpDetailCertOpenBtn');
    if (afp.sharepoint_pdf_url) {
      pdfBtn.style.display = '';
      pdfBtn.onclick = () => window.open(afp.sharepoint_pdf_url, '_blank');
    } else { pdfBtn.style.display = 'none'; }

    const certAtt = (afp.attachments || []).find(a => a.kind === 'certificate');
    if (certAtt) {
      certBtn.style.display = '';
      certBtn.onclick = () => window.open(certAtt.sharepoint_url, '_blank');
    } else { certBtn.style.display = 'none'; }

    // Action buttons gated by status
    const editBtn        = document.getElementById('afpDetailEditBtn');
    const submitBtn      = document.getElementById('afpDetailSubmitBtn');
    const certUploadBtn  = document.getElementById('afpDetailCertUploadBtn');
    const genInvBtn      = document.getElementById('afpDetailGenInvBtn');
    const cancelBtn      = document.getElementById('afpDetailCancelBtn');

    editBtn.style.display       = (afp.status === 'Draft') ? '' : 'none';
    submitBtn.style.display     = (afp.status === 'Draft') ? '' : 'none';
    certUploadBtn.style.display = (afp.status === 'Submitted') ? '' : 'none';
    genInvBtn.style.display     = (afp.status === 'Certified') ? '' : 'none';
    const uncertBtn = document.getElementById('afpDetailUncertifyBtn');
    if (uncertBtn) uncertBtn.style.display = (afp.status === 'Certified') ? '' : 'none';
    const linkInvBtn = document.getElementById('afpDetailLinkInvBtn');
    if (linkInvBtn) linkInvBtn.style.display =
      ((afp.status === 'Certified' || afp.status === 'Submitted') && !afp.invoice_id) ? '' : 'none';
    cancelBtn.style.display     = (afp.status !== 'Cancelled' && afp.status !== 'Invoiced') ? '' : 'none';

    // Linked invoice ref
    const invLink = document.getElementById('afpDetailInvLink');
    if (afp.invoice_ref) {
      invLink.style.display = '';
      invLink.innerHTML = `Generated invoice: <a href="javascript:openInvoiceDetail(${afp.invoice_id})" style="color:var(--accent);font-family:var(--font-mono);font-weight:600">${escapeHtml(afp.invoice_ref)}</a>`;
    } else { invLink.style.display = 'none'; }

    document.getElementById('afpDetailModal').classList.add('active');
  } catch (err) {
    console.error('Open AFP detail failed', err);
    toast('Failed to load AFP: ' + (err.message || 'unknown'), 'error');
  }
}

function closeAfpDetail() {
  document.getElementById('afpDetailModal').classList.remove('active');
  _afpDetailCurrent = null;
}

async function editAfpFromDetail() {
  if (!_afpDetailCurrent) return;
  const afp = _afpDetailCurrent;
  closeAfpDetail();
  _afpEditing = afp;
  _afpModalProjectId = afp.project_id;
  _afpImportMeta = null;
  const project = (_invProjectsCache || []).find(p => p.id === afp.project_id);
  if (project) {
    document.getElementById('afpNewProjectLabel').textContent =
      `${project.project_number || ''} — ${project.project_name || ''}`;
  }
  document.getElementById('afpNewRef').value = afp.ref;
  document.getElementById('afpNewPeriodStart').value = afp.period_start ? String(afp.period_start).slice(0, 10) : '';
  document.getElementById('afpNewPeriodEnd').value   = afp.period_end   ? String(afp.period_end).slice(0, 10)   : '';
  document.getElementById('afpNewIsFinal').checked   = !!afp.is_final;
  document.getElementById('afpNewRetentionPct').value =
    afp.applied_retention && afp.applied_value_net
      ? (Number(afp.applied_retention) / Number(afp.applied_value_net) * 100).toFixed(2)
      : '5';
  document.getElementById('afpNewVatApplies').checked = Number(afp.applied_vat || 0) > 0;
  document.getElementById('afpNewNotes').value = afp.notes || '';
  document.getElementById('afpNewContractNo').value = afp.contract_no || '';
  document.getElementById('afpNewPrevCert').value =
    afp.previous_certificate_value != null ? Number(afp.previous_certificate_value) : '0';
  if (afp.retention_pct != null) {
    document.getElementById('afpNewRetentionPct').value = Number(afp.retention_pct);
  }

  _afpLineRows = (afp.line_items || []).map(l => ({
    line_no: l.line_no,
    section: l.section || 'measured',
    item_no: l.item_no != null ? Number(l.item_no) : 1,
    item_description: l.item_description || '',
    item_quote_ref: l.item_quote_ref || '',
    item_wo_no: l.item_wo_no || '',
    source_quote_line_item_id: l.source_quote_line_item_id,
    description: l.description,
    contract_value: Number(l.contract_value || 0),
    previous_pct_complete: Number(l.previous_pct_complete || 0),
    this_app_pct_complete: Number(l.this_app_pct_complete || 0),
    gross_amount_paid: l.gross_amount_paid != null ? Number(l.gross_amount_paid) : 0
  }));
  renderAfpLineRows();
  recalcAfpTotals();
  document.getElementById('afpNewModal').classList.add('active');
}

async function submitAfpFromDetail() {
  if (!_afpDetailCurrent) return;
  const afp = _afpDetailCurrent;
  const btn = document.getElementById('afpDetailSubmitBtn');
  try {
    if (btn) { btn.disabled = true; btn.textContent = 'Submitting…'; }
    setLoading(true);
    await loadLogoDataUri();
    const pdfData = _buildAfpPdfData(afp);
    const pdfBlob = await renderBamaAfpPDF(pdfData);
    let driveItem = null;
    const project = (_invProjectsCache || []).find(p => p.id === afp.project_id);
    if (project && project.sharepoint_folder_id) {
      try {
        const afpFolder = await getOrCreateSubfolder(project.sharepoint_folder_id, '08 - Application for payment', BAMA_DRIVE_ID);
        const fileName = sanitizeSpFilename(`${afp.ref}.pdf`);
        driveItem = await uploadFileToFolder(afpFolder.id, fileName, pdfBlob, 'application/pdf');
      } catch (spErr) {
        console.warn('AFP SharePoint upload failed, falling back to tab:', spErr);
      }
    }
    if (!driveItem) {
      try { window.open(URL.createObjectURL(pdfBlob), '_blank'); } catch (e) { /* popup blocked */ }
    }
    await api.post(`/api/applications/${afp.id}/submit`, driveItem ? {
      sharepoint_pdf_id:  driveItem.id,
      sharepoint_pdf_url: driveItem.webUrl
    } : {});
    toast(driveItem
      ? `AFP ${afp.ref} submitted ✓`
      : `AFP ${afp.ref} submitted ✓ — no SharePoint folder on this project, PDF opened in a new tab`, driveItem ? 'success' : 'warning');
    closeAfpDetail();
    await loadInvoicingData();
    renderInvAfpsTable();
  } catch (err) {
    toast('Submit failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    setLoading(false);
    if (btn) { btn.disabled = false; btn.textContent = 'Submit + PDF'; }
  }
}

async function cancelAfp() {
  if (!_afpDetailCurrent) return;
  const afp = _afpDetailCurrent;
  const confirmed = await showConfirmAsync(
    'Cancel AFP?',
    `<p>Cancelling <b>${escapeHtml(afp.ref)}</b> burns its number — the next AFP for this project will skip it. This is irreversible.</p>`,
    { okLabel: 'Cancel AFP', cancelLabel: 'Keep' }
  );
  if (!confirmed) return;
  try {
    await api.post(`/api/applications/${afp.id}/cancel`, {});
    toast('AFP cancelled', 'success');
    closeAfpDetail();
    await loadInvoicingData();
    renderInvAfpsTable();
  } catch (err) {
    toast('Cancel failed: ' + (err.message || 'unknown'), 'error');
  }
}

async function downloadAfpPdf() {
  if (!_afpDetailCurrent) return;
  const afp = _afpDetailCurrent;
  try {
    setLoading(true);
    await loadLogoDataUri();
    const pdfData = _buildAfpPdfData(afp);
    const pdfBlob = await renderBamaAfpPDF(pdfData);
    const url = URL.createObjectURL(pdfBlob);
    const a = document.createElement('a');
    a.href = url; a.download = `${afp.ref}.pdf`;
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  } catch (err) {
    toast('PDF generation failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    setLoading(false);
  }
}

