function openCertUploadModal() {
  if (!_afpDetailCurrent) return;
  _afpCertFile = null;
  _afpCertParsed = null;
  document.getElementById('afpCertFile').value = '';
  document.getElementById('afpCertOcrStatus').style.display = 'none';
  document.getElementById('afpCertRef').value = '';
  document.getElementById('afpCertDate').value = new Date().toISOString().slice(0, 10);
  document.getElementById('afpCertNetVal').value = '';
  document.getElementById('afpCertVat').value = '';
  document.getElementById('afpCertRet').value = '';
  document.getElementById('afpCertGross').value = '';
  renderAfpCertLineFields();
  document.getElementById('afpCertModal').classList.add('active');
}

function closeCertUploadModal() {
  document.getElementById('afpCertModal').classList.remove('active');
}

// Tolerant JSON extraction for AI responses: strips markdown fences and, if
// the payload was truncated mid-array (max_tokens), cuts back to the last
// complete object and balances the brackets.
function _extractJsonLoose(raw) {
  let t = String(raw || '').trim().replace(/```json|```/g, '');
  const s = t.indexOf('{');
  if (s < 0) throw new Error('no JSON in AI response');
  t = t.slice(s);
  const e = t.lastIndexOf('}');
  if (e >= 0) {
    try { return JSON.parse(t.slice(0, e + 1)); } catch (_) { /* salvage below */ }
  }
  let cut = t.lastIndexOf('},');
  if (cut < 0) cut = t.lastIndexOf('}');
  if (cut < 0) throw new Error('unparseable AI JSON');
  let frag = t.slice(0, cut + 1);
  const opens = [];
  for (const ch of frag) {
    if (ch === '{' || ch === '[') opens.push(ch);
    else if (ch === '}' && opens[opens.length - 1] === '{') opens.pop();
    else if (ch === ']' && opens[opens.length - 1] === '[') opens.pop();
  }
  while (opens.length) frag += (opens.pop() === '[' ? ']' : '}');
  const parsed = JSON.parse(frag);
  parsed._truncated = true;
  return parsed;
}

function renderAfpCertLineFields() {
  const wrap = document.getElementById('afpCertLineFields');
  if (!wrap || !_afpDetailCurrent) return;
  const fmt = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 });
  wrap.innerHTML = (_afpDetailCurrent.line_items || []).map((l, i) => {
    const appliedCum = l.cumulative_value != null
      ? Number(l.cumulative_value)
      : Number(l.contract_value || 0) * Number(l.this_app_pct_complete || 0) / 100;
    const prevPaid = Number(l.gross_amount_paid || 0);
    return `
    <div style="display:grid;grid-template-columns:1fr 92px 92px 100px;gap:6px;align-items:center;font-size:12px">
      <div style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap"
           title="${escapeHtml(l.description || '')}">${l.item_quote_ref ? `<span style="font-family:var(--font-mono);color:var(--muted);font-size:11px">${escapeHtml(l.item_quote_ref)}</span> · ` : ''}${escapeHtml(l.description || '')}</div>
      <div style="text-align:right;color:var(--muted)" title="Our applied cumulative">£${fmt(appliedCum)}</div>
      <div style="text-align:right;color:var(--subtle)" title="Previously paid">£${fmt(prevPaid)}</div>
      <input type="number" step="0.01" class="field-input" placeholder="Cert cum £"
             data-line-id="${l.id}" data-line-idx="${i}" data-applied-cum="${appliedCum.toFixed(2)}"
             style="font-size:12px;padding:4px 6px;text-align:right">
    </div>`;
  }).join('');
}

// Manual fallback / fast path: no OCR needed — copy our applied figures as the
// certified figures (they certified in full). Everything stays editable after.
function certifyAfpInFull() {
  if (!_afpDetailCurrent) return;
  const afp = _afpDetailCurrent;
  document.getElementById('afpCertNetVal').value = Number(afp.applied_value_net || 0).toFixed(2);
  document.getElementById('afpCertRet').value    = Number(afp.applied_retention || 0).toFixed(2);
  document.getElementById('afpCertVat').value    = Number(afp.applied_vat || 0).toFixed(2);
  document.getElementById('afpCertGross').value  = Number(afp.applied_gross || 0).toFixed(2);
  document.querySelectorAll('#afpCertLineFields input').forEach(inp => {
    inp.value = inp.dataset.appliedCum || '';
  });
  toast('Copied applied figures — adjust any line they paid less on', 'info');
}

async function onCertFilePicked(file) {
  if (!file || !_afpDetailCurrent) return;
  _afpCertFile = file;
  const dropLabel = document.getElementById('afpCertDropLabel');
  if (dropLabel) dropLabel.innerHTML = `📎 <b>${escapeHtml(file.name)}</b> <span style="font-size:11px;color:var(--subtle)">(drop or click to replace)</span>`;
  const statusEl = document.getElementById('afpCertOcrStatus');
  statusEl.style.display = '';
  statusEl.style.background = 'var(--bg-darker)';
  statusEl.innerHTML = '<div class="spinner" style="display:inline-block;width:14px;height:14px;vertical-align:middle"></div> Parsing payment notice with AI…';

  try {
    const dataUri = await _fileToDataUri(file);
    const isImg = file.type.startsWith('image/');
    const linesDesc = (_afpDetailCurrent.line_items || [])
      .map((l, i) => {
        const appliedCum = l.cumulative_value != null
          ? Number(l.cumulative_value)
          : Number(l.contract_value || 0) * Number(l.this_app_pct_complete || 0) / 100;
        return `  ${i + 1}. ${l.item_quote_ref ? l.item_quote_ref + ' · ' : ''}${l.description} (applied cum £${appliedCum.toFixed(2)}, prev paid £${Number(l.gross_amount_paid || 0).toFixed(2)})`;
      })
      .join('\n');
    const result = await callClaude({
      model: 'claude-sonnet-4-6',
      max_tokens: 8000,
      messages: [{
        role: 'user',
        content: [
          isImg
            ? { type: 'image',    source: { type: 'base64', media_type: file.type, data: dataUri.split(',')[1] } }
            : { type: 'document', source: { type: 'base64', media_type: file.type, data: dataUri.split(',')[1] } },
          {
            type: 'text',
            text: `Extract from this UK construction payment / payless notice or certificate. Return ONLY compact JSON, no markdown:
{
  "certificate_ref": "their reference (contract/cert no) or null",
  "certificate_date": "YYYY-MM-DD or null",
  "certified_value_net": 0,
  "certified_retention": 0,
  "certified_vat": 0,
  "certified_gross": 0,
  "line_items": [
    { "line_index": 1, "certified_cumulative_value": 0 }
  ]
}
Header rules:
- certified_value_net = the THIS-PERIOD certified net before retention. If the notice shows a "This Payment" column, use its pre-retention subtotal. If it only shows cumulative figures, use: cumulative gross valuation minus previously paid (pre-retention).
- certified_retention = this-period retention deduction; certified_gross = the payment due this period. certified_vat = 0 unless VAT is explicitly shown.
Line rules:
- certified_cumulative_value = the client's certified CUMULATIVE value-to-date for the line (in RG Carter style notices this is the "Current Value" under the Certification columns).
- Match against our application lines below by description and order. Only include lines you can match confidently; skip headers/subtotals.
- Keep each line_items entry on one line, no extra whitespace.

Our application lines:
${linesDesc}`
          }
        ]
      }]
    });
    const text = (result.content?.find(b => b.type === 'text')?.text || '').trim();
    const parsed = _extractJsonLoose(text);
    _afpCertParsed = parsed;

    if (parsed.certificate_ref)         document.getElementById('afpCertRef').value    = parsed.certificate_ref;
    if (parsed.certificate_date)        document.getElementById('afpCertDate').value   = parsed.certificate_date;
    if (parsed.certified_value_net != null) document.getElementById('afpCertNetVal').value = parsed.certified_value_net;
    if (parsed.certified_vat       != null) document.getElementById('afpCertVat').value    = parsed.certified_vat;
    if (parsed.certified_retention != null) document.getElementById('afpCertRet').value    = parsed.certified_retention;
    if (parsed.certified_gross     != null) document.getElementById('afpCertGross').value  = parsed.certified_gross;

    let matched = 0;
    if (Array.isArray(parsed.line_items)) {
      parsed.line_items.forEach(item => {
        const inp = document.querySelector(`#afpCertLineFields input[data-line-idx="${item.line_index - 1}"]`);
        if (inp && item.certified_cumulative_value != null) { inp.value = item.certified_cumulative_value; matched++; }
      });
    }
    // Flag payless lines: certified cum < applied cum
    let payless = 0;
    document.querySelectorAll('#afpCertLineFields input').forEach(inp => {
      const cert = parseFloat(inp.value), applied = parseFloat(inp.dataset.appliedCum);
      if (!isNaN(cert) && !isNaN(applied) && applied - cert > 0.01) {
        inp.style.borderColor = 'var(--red)'; inp.style.color = 'var(--red)';
        payless++;
      } else {
        inp.style.borderColor = ''; inp.style.color = '';
      }
    });
    statusEl.style.background = payless ? 'rgba(208,2,27,.1)' : 'rgba(62,207,142,.1)';
    statusEl.innerHTML = payless
      ? `⚠ Parsed — matched ${matched} lines, <b style="color:var(--red)">${payless} line${payless > 1 ? 's' : ''} certified BELOW applied</b> (highlighted red). Review, then "Upload & Confirm".${parsed._truncated ? ' <i>(response was truncated — double-check the last lines)</i>' : ''}`
      : `✓ Parsed — matched ${matched} lines, no payless detected. Review, then "Upload & Confirm".${parsed._truncated ? ' <i>(response was truncated — double-check the last lines)</i>' : ''}`;
  } catch (err) {
    console.error('Cert OCR failed', err);
    statusEl.style.background = 'rgba(255,165,0,.1)';
    statusEl.innerHTML = `⚠ Could not parse automatically — fill the figures manually below, or click <b>✓ Certify in full</b> and adjust. (${escapeHtml(err.message || 'unknown')})`;
  }
}

async function uploadCertAndContinue() {
  if (!_afpDetailCurrent) return;
  const afp = _afpDetailCurrent;
  const btn = document.getElementById('afpCertUploadContinueBtn');
  try {
    if (btn) { btn.disabled = true; btn.textContent = 'Uploading…'; }
    setLoading(true);

    // Certificate file is OPTIONAL — you can certify on manually-entered
    // figures (client sent no formal cert, or test AFPs for invoice preview).
    if (_afpCertFile) {
      const project = (_invProjectsCache || []).find(p => p.id === afp.project_id);
      if (project && project.sharepoint_folder_id) {
        try {
          const afpFolder = await getOrCreateSubfolder(project.sharepoint_folder_id, '08 - Application for payment', BAMA_DRIVE_ID);
          const ext = (_afpCertFile.name.split('.').pop() || 'pdf').toLowerCase();
          const fileName = sanitizeSpFilename(`${afp.ref}-Certificate.${ext}`);
          const driveItem = await uploadFileToFolder(afpFolder.id, fileName, _afpCertFile, _afpCertFile.type || 'application/octet-stream');
          await api.post(`/api/applications/${afp.id}/certificate`, {
            sharepoint_id:  driveItem.id,
            sharepoint_url: driveItem.webUrl,
            filename:       fileName
          });
        } catch (spErr) {
          console.warn('Cert SharePoint upload failed — certifying without the file:', spErr);
          toast('Certificate file could not be saved to SharePoint — certifying on the entered figures anyway', 'warning');
        }
      } else {
        toast('Project has no SharePoint folder — certifying on the entered figures without saving the file', 'warning');
      }
    }

    const perLineFields = document.querySelectorAll('#afpCertLineFields input');
    const lineItems = [];
    perLineFields.forEach(inp => {
      const lineId = parseInt(inp.dataset.lineId);
      const val = parseFloat(inp.value);
      if (lineId && !isNaN(val)) {
        // Cumulative certified — the server derives this-period from it and
        // sets the line's paid-to-date directly.
        lineItems.push({ id: lineId, certified_cumulative_value: val });
      }
    });

    await api.put(`/api/applications/${afp.id}/certificate`, {
      certificate_ref:      document.getElementById('afpCertRef').value || null,
      certificate_date:     document.getElementById('afpCertDate').value || null,
      certified_value_net:  Number(document.getElementById('afpCertNetVal').value) || 0,
      certified_vat:        Number(document.getElementById('afpCertVat').value) || 0,
      certified_retention:  Number(document.getElementById('afpCertRet').value) || 0,
      certified_gross:      Number(document.getElementById('afpCertGross').value) || 0,
      line_items:           lineItems
    });

    toast(`AFP ${afp.ref} certified ✓`, 'success');
    closeCertUploadModal();
    closeAfpDetail();
    await loadInvoicingData();
    renderInvAfpsTable();
  } catch (err) {
    console.error('Cert upload failed', err);
    toast('Cert upload failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    setLoading(false);
    if (btn) { btn.disabled = false; btn.textContent = 'Upload & Confirm'; }
  }
}

// Revert a Certified AFP back to Submitted — clears cert figures and unwinds
// per-line paid so it can be re-certified cleanly.
async function uncertifyAfp() {
  if (!_afpDetailCurrent) return;
  const afp = _afpDetailCurrent;
  const confirmed = await showConfirmAsync(
    'Un-certify AFP?',
    `<p>This reverts <b>${escapeHtml(afp.ref)}</b> to <b>Submitted</b> — certified figures are cleared and per-line paid returns to its pre-certificate state. The certificate file (if uploaded) stays attached.</p>`,
    { okLabel: 'Un-certify', cancelLabel: 'Keep' }
  );
  if (!confirmed) return;
  try {
    await api.post(`/api/applications/${afp.id}/uncertify`, {});
    toast(`${afp.ref} reverted to Submitted ✓`, 'success');
    closeAfpDetail();
    await loadInvoicingData();
    renderInvAfpsTable();
  } catch (err) {
    toast('Un-certify failed: ' + (err.message || 'unknown'), 'error');
  }
}

// Match an EXISTING invoice to this AFP (legacy invoices raised before the
// AFP was onboarded) instead of generating a duplicate.
async function linkInvoiceToAfp(afpId) {
  let afp = _afpDetailCurrent && _afpDetailCurrent.id === afpId ? _afpDetailCurrent : null;
  if (!afp) {
    try { afp = await api.get(`/api/applications/${afpId}`); }
    catch (e) { toast('Failed to load AFP', 'error'); return; }
  }

  // Candidates: same-project (or project-less) invoices, not void, and not
  // already matched to another AFP.
  const linkedInvIds = new Set((_invAfpList || [])
    .filter(a => a.invoice_id != null && a.id !== afp.id)
    .map(a => a.invoice_id));
  const candidates = (_invInvoiceList || []).filter(inv =>
    inv.status !== 'Void' && inv.status !== 'Cancelled' &&
    (inv.project_id == null || inv.project_id === afp.project_id) &&
    !linkedInvIds.has(inv.id) && (inv.kind || 'invoice') === 'invoice');

  if (!candidates.length) {
    toast('No unmatched invoices found for this project — use Generate Invoice instead', 'info');
    return;
  }

  const fmt = v => '£' + Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 });
  const options = candidates.map(inv =>
    `<option value="${inv.id}">${escapeHtml(inv.ref)} — ${fmt(inv.gross_total != null ? inv.gross_total : inv.net_total)} (${escapeHtml(inv.status || '')}${inv.invoice_date ? ', ' + String(inv.invoice_date).slice(0, 10) : ''})</option>`
  ).join('');
  const confirmed = await showConfirmAsync(
    `Match invoice to ${escapeHtml(afp.ref)}`,
    `<p>Pick the existing invoice that covers this application. The AFP will be marked <b>Invoiced</b> and linked — no new invoice is created.</p>
     <select id="afpLinkInvSelect" class="field-input" style="width:100%">${options}</select>`,
    { okLabel: 'Match', cancelLabel: 'Cancel' }
  );
  if (!confirmed) return;
  const sel = document.getElementById('afpLinkInvSelect');
  const invoiceId = sel ? parseInt(sel.value) : null;
  if (!invoiceId) return;
  try {
    const updated = await api.post(`/api/applications/${afp.id}/link-invoice`, { invoice_id: invoiceId });
    toast(`${afp.ref} matched to invoice ${updated.invoice_ref} ✓`, 'success');
    if (_afpDetailCurrent && _afpDetailCurrent.id === afp.id) closeAfpDetail();
    await loadInvoicingData();
    renderInvAfpsTable();
  } catch (err) {
    toast('Match failed: ' + (err.message || 'unknown'), 'error');
  }
}

async function generateInvoiceFromAfp() {
  if (!_afpDetailCurrent) return;
  const afp = _afpDetailCurrent;
  const confirmed = await showConfirmAsync(
    'Generate Invoice from AFP?',
    `<p>This will create a new Draft invoice based on the certified figures from <b>${escapeHtml(afp.ref)}</b>.</p>
     <p>Retention £${Number(afp.certified_retention || 0).toFixed(2)} will carry over. Review + Issue from the Sales Invoices tab afterwards.</p>`,
    { okLabel: 'Generate', cancelLabel: 'Cancel' }
  );
  if (!confirmed) return;
  const btn = document.getElementById('afpDetailGenInvBtn');
  try {
    if (btn) { btn.disabled = true; btn.textContent = 'Generating…'; }
    const result = await api.post(`/api/applications/${afp.id}/generate-invoice`, {});
    toast(`Invoice ${result.invoice.ref} generated as Draft — review in Sales tab ✓`, 'success');
    closeAfpDetail();
    await loadInvoicingData();
    renderInvAfpsTable();
  } catch (err) {
    toast('Generate failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Generate Invoice'; }
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// INVOICE TRACKER — Commit 2 implementation
// ═══════════════════════════════════════════════════════════════════════════
// Full CRUD for Sales Invoices, Supplier Invoices (PO extension), Receipts,
// shared PDF renderer for BAMA invoices and POs, OCR pipelines for receipts
// and supplier invoices using `callClaude` (vision input).
// ───────────────────────────────────────────────────────────────────────────

// Module-level state used by the new modals
let _invEditing = null;          // currently-edited invoice (null = new)
let _invLineRows = [];           // working line items in the new/edit modal
let _invSelectedClient = null;   // chosen client object (or null for free-text)
let _invSelectedProject = null;  // chosen project object (or null)
let _invDetailCurrent = null;    // currently-open invoice in the detail modal
let _invSupInvPo = null;         // PO currently being attached a supplier invoice
let _invSupInvParsed = null;
let _invSupInvFile = null;


// ── Number helpers ────────────────────────────────────────────────────────
function _invFmt2(v) {
  return Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function _invToDateStr(d) {
  if (!d) return '';
  if (d instanceof Date) return d.toISOString().slice(0, 10);
  const m = String(d).match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${m[1]}-${m[2]}-${m[3]}` : '';
}
let _invPaymentTermsDays = 30;   // active client payment terms for due-date auto-fill

function _invDueDefault(invDate, termsDays) {
  // Default due: invoice date + payment terms (client-specific, default 30)
  if (!invDate) return '';
  const d = new Date(invDate);
  if (isNaN(d.getTime())) return '';
  d.setDate(d.getDate() + (Number(termsDays) > 0 ? Number(termsDays) : _invPaymentTermsDays));
  return d.toISOString().slice(0, 10);
}

// Called by the invoice-date input's onchange — respects client payment terms
function _invApplyDueDate(dateStr) {
  const el = document.getElementById('invNewDueDate');
  if (el) el.value = _invDueDefault(dateStr);
}

// Map DB flags -> treatment select value
function _invTreatmentFromFlags(vatApplies, cisReverse) {
  if (cisReverse) return 'reverse_charge';
  return vatApplies ? 'standard' : 'zero';
}

// ═════════════════════════════════════════════════════════════════════════
// NEW / EDIT INVOICE — open + close
// ═════════════════════════════════════════════════════════════════════════
async function openNewInvoiceModal() {
  _invEditing = null;
  _invSelectedClient = null;
  _invSelectedProject = null;
  _invLineRows = [];

  // Reset form fields
  document.getElementById('invNewKind').value = 'invoice';
  document.getElementById('invNewDate').value = new Date().toISOString().slice(0, 10);
  document.getElementById('invNewDueDate').value = _invDueDefault(document.getElementById('invNewDate').value);
  document.getElementById('invNewCustomerSearch').value = '';
  document.getElementById('invNewCustomerSelected').textContent = '';
  document.getElementById('invNewCustomerDropdown').innerHTML = '';
  document.getElementById('invNewProjectSearch').value = '';
  document.getElementById('invNewProjectSelected').textContent = '';
  document.getElementById('invNewProjectDropdown').innerHTML = '';
  _invPaymentTermsDays = 30;
  clearInvParent();
  document.getElementById('invNewParentWrap').style.display = 'none';
  document.getElementById('invNewModalTitle').textContent = '🧾 New Invoice';
  document.getElementById('invNewVatTreatment').value = 'reverse_charge';
  document.getElementById('invNewVatHint').textContent = '';
  document.getElementById('invNewRetentionMode').value = 'none';
  document.getElementById('invNewRetentionPct').value = '';
  document.getElementById('invNewRetentionAmt').value = '';
  document.getElementById('invNewRetentionDue').value = '';
  document.getElementById('invNewNotes').value = '';
  _invToggleRetentionFields();
  _invAddLineRow();

  // Allocate the next ref so the user sees what they're about to create
  try {
    const r = await api.get('/api/invoices-next-ref?kind=invoice');
    document.getElementById('invNewRef').value = r?.ref || 'INV????';
  } catch (e) {
    document.getElementById('invNewRef').value = 'INV????';
  }

  document.getElementById('invNewModal').classList.add('active');
  recalcInvoiceTotals();
}

function closeInvNewModal() {
  document.getElementById('invNewModal').classList.remove('active');
}

// When the kind toggle changes, re-fetch the next ref for that kind
let _invSelectedParent = null;   // parent invoice a credit note is raised against

async function onInvKindChange() {
  const kind = document.getElementById('invNewKind').value;
  const parentWrap = document.getElementById('invNewParentWrap');
  if (parentWrap) parentWrap.style.display = (kind === 'credit_note') ? '' : 'none';
  if (kind !== 'credit_note') clearInvParent();
  try {
    const r = await api.get(`/api/invoices-next-ref?kind=${encodeURIComponent(kind)}`);
    document.getElementById('invNewRef').value = r?.ref || '????';
  } catch (e) { /* show placeholder */ }
}

// ── Parent-invoice autocomplete (credit notes) ────────────────────────────
function filterInvParents(q) {
  const dropdown = document.getElementById('invNewParentDropdown');
  if (!dropdown) return;
  const lower = (q || '').toLowerCase().trim();
  if (!lower) { dropdown.innerHTML = ''; return; }
  const matches = (_invInvoiceList || [])
    .filter(i => i.kind === 'invoice' && ['Issued', 'Partially Paid', 'Paid'].includes(i.status))
    .filter(i => (`${i.ref} ${i.client_company_name || i.customer_text || ''}`).toLowerCase().includes(lower))
    .slice(0, 8);
  dropdown.innerHTML = `<div style="position:absolute;top:0;left:0;right:0;background:var(--surface);
       border:1px solid var(--border);border-radius:6px;max-height:240px;overflow:auto;z-index:30">
    ${matches.map(i => `
      <div style="padding:8px 12px;cursor:pointer;font-size:13px;border-bottom:1px solid var(--border)"
           onmousedown="selectInvParent(${i.id})"
           onmouseover="this.style.background='var(--surface2)'"
           onmouseout="this.style.background=''">
        <span style="font-family:var(--font-mono);font-weight:600">${escapeHtml(i.ref)}</span>
        — ${escapeHtml(i.client_company_name || i.customer_text || '')}
        <span style="color:var(--muted);font-size:11px">· £${Number(i.gross_amount || 0).toLocaleString('en-GB', { minimumFractionDigits: 2 })} · ${escapeHtml(i.status)}</span>
      </div>`).join('')}
    ${matches.length === 0 ? '<div style="padding:8px 12px;color:var(--subtle);font-size:12px">No matching issued invoices</div>' : ''}
    <div style="padding:8px 12px;cursor:pointer;font-size:13px;color:var(--muted);font-style:italic"
         onmousedown="clearInvParent()"
         onmouseover="this.style.background='var(--surface2)'"
         onmouseout="this.style.background=''">
      Clear (standalone credit note)
    </div>
  </div>`;
}
function selectInvParent(id) {
  const i = (_invInvoiceList || []).find(x => x.id === id);
  if (!i) return;
  _invSelectedParent = i;
  document.getElementById('invNewParentSearch').value = `${i.ref} — ${i.client_company_name || i.customer_text || ''}`;
  document.getElementById('invNewParentSelected').textContent =
    `✓ Will be allocated against ${i.ref} on issue (reduces its outstanding balance)`;
  document.getElementById('invNewParentDropdown').innerHTML = '';
  // Prefill customer + project from the parent for consistency
  if (i.client_id && !_invSelectedClient) selectInvCustomer(i.client_id);
  else if (!_invSelectedClient && (i.customer_text || i.client_company_name)) {
    document.getElementById('invNewCustomerSearch').value = i.client_company_name || i.customer_text;
    document.getElementById('invNewCustomerSelected').textContent = `✓ "${i.client_company_name || i.customer_text}" (from ${i.ref})`;
  }
  if (i.project_id && !_invSelectedProject) {
    const p = (_invProjectsCache || []).find(x => x.id === i.project_id);
    if (p) selectInvProject(p.id);
  }
}
function clearInvParent() {
  _invSelectedParent = null;
  const s = document.getElementById('invNewParentSearch');
  if (s) s.value = '';
  const sel = document.getElementById('invNewParentSelected');
  if (sel) sel.textContent = '';
  const dd = document.getElementById('invNewParentDropdown');
  if (dd) dd.innerHTML = '';
}

// ── Customer + Project autocomplete (Tenders-style) ──
function filterInvCustomers(q) {
  const dropdown = document.getElementById('invNewCustomerDropdown');
  if (!dropdown) return;
  const lower = (q || '').toLowerCase().trim();
  if (!lower) { dropdown.innerHTML = ''; return; }
  const matches = _invClientsCache
    .filter(c => (c.company_name || '').toLowerCase().includes(lower))
    .slice(0, 8);
  dropdown.innerHTML = `<div style="position:absolute;top:0;left:0;right:0;background:var(--surface);
       border:1px solid var(--border);border-radius:6px;max-height:240px;overflow:auto;z-index:30">
    ${matches.map(c => `
      <div style="padding:8px 12px;cursor:pointer;font-size:13px;border-bottom:1px solid var(--border)"
           onmousedown="selectInvCustomer(${c.id})"
           onmouseover="this.style.background='var(--surface2)'"
           onmouseout="this.style.background=''">
        ${escapeHtml(c.company_name || '')}
      </div>`).join('')}
    <div style="padding:8px 12px;cursor:pointer;font-size:13px;color:var(--muted);font-style:italic"
         onmousedown="useInvCustomerFreeText()"
         onmouseover="this.style.background='var(--surface2)'"
         onmouseout="this.style.background=''">
      Use "${escapeHtml(q)}" as free-text (not in clients list)
    </div>
  </div>`;
}
function selectInvCustomer(id) {
  const c = _invClientsCache.find(x => x.id === id);
  if (!c) return;
  _invSelectedClient = c;
  document.getElementById('invNewCustomerSearch').value = c.company_name || '';
  document.getElementById('invNewCustomerSelected').textContent = `✓ ${c.company_name} (from Clients)`;
  document.getElementById('invNewCustomerDropdown').innerHTML = '';

  // Apply the client's invoicing defaults (still overridable per invoice)
  const treatment = ['standard','reverse_charge','zero'].includes(c.vat_treatment) ? c.vat_treatment : 'reverse_charge';
  const treatEl = document.getElementById('invNewVatTreatment');
  if (treatEl) treatEl.value = treatment;
  _invPaymentTermsDays = Number(c.payment_terms_days) > 0 ? Number(c.payment_terms_days) : 30;
  _invApplyDueDate(document.getElementById('invNewDate').value);
  const hint = document.getElementById('invNewVatHint');
  if (hint) hint.textContent = `Client default: ${treatment === 'standard' ? 'Standard VAT' : treatment === 'zero' ? 'Zero / no VAT' : 'Domestic reverse charge'} · ${_invPaymentTermsDays}-day terms`;
  recalcInvoiceTotals();
}
function useInvCustomerFreeText() {
  const q = document.getElementById('invNewCustomerSearch').value;
  _invSelectedClient = null;
  document.getElementById('invNewCustomerSelected').textContent = `✓ "${q}" (free-text)`;
  document.getElementById('invNewCustomerDropdown').innerHTML = '';
}

function filterInvProjects(q) {
  const dropdown = document.getElementById('invNewProjectDropdown');
  if (!dropdown) return;
  const lower = (q || '').toLowerCase().trim();
  if (!lower) { dropdown.innerHTML = ''; return; }
  const matches = _invProjectsCache
    .filter(p => ((p.project_number || '') + ' ' + (p.project_name || '')).toLowerCase().includes(lower))
    .slice(0, 8);
  dropdown.innerHTML = `<div style="position:absolute;top:0;left:0;right:0;background:var(--surface);
       border:1px solid var(--border);border-radius:6px;max-height:240px;overflow:auto;z-index:30">
    ${matches.map(p => `
      <div style="padding:8px 12px;cursor:pointer;font-size:13px;border-bottom:1px solid var(--border)"
           onmousedown="selectInvProject(${p.id})"
           onmouseover="this.style.background='var(--surface2)'"
           onmouseout="this.style.background=''">
        <span style="font-family:var(--font-mono);font-weight:600">${escapeHtml(p.project_number || '')}</span>
        — ${escapeHtml(p.project_name || '')}
      </div>`).join('')}
    ${matches.length === 0 ? '<div style="padding:8px 12px;color:var(--subtle);font-size:12px">No matching projects</div>' : ''}
    <div style="padding:8px 12px;cursor:pointer;font-size:13px;color:var(--muted);font-style:italic"
         onmousedown="clearInvProject()"
         onmouseover="this.style.background='var(--surface2)'"
         onmouseout="this.style.background=''">
      Clear (no project link)
    </div>
  </div>`;
}
function selectInvProject(id) {
  const p = _invProjectsCache.find(x => x.id === id);
  if (!p) return;
  _invSelectedProject = p;
  document.getElementById('invNewProjectSearch').value = `${p.project_number || ''} — ${p.project_name || ''}`;
  document.getElementById('invNewProjectSelected').textContent = `✓ ${p.project_number || ''}`;
  document.getElementById('invNewProjectDropdown').innerHTML = '';
}
function clearInvProject() {
  _invSelectedProject = null;
  document.getElementById('invNewProjectSearch').value = '';
  document.getElementById('invNewProjectSelected').textContent = '';
  document.getElementById('invNewProjectDropdown').innerHTML = '';
}

// ── Line items ──
function _invAddLineRow(line) {
  const row = line || { description: '', quantity: 1, unit: '', unit_price: 0 };
  _invLineRows.push(row);
  renderInvLineRows();
}
function removeInvLineRow(idx) {
  _invLineRows.splice(idx, 1);
  renderInvLineRows();
  recalcInvoiceTotals();
}
function renderInvLineRows() {
  const el = document.getElementById('invNewLineItems');
  if (!el) return;
  el.innerHTML = _invLineRows.map((l, i) => `
    <div style="display:grid;grid-template-columns:1fr 80px 70px 100px 110px 30px;gap:6px;align-items:center">
      <input type="text" class="field-input" placeholder="Description"
             value="${escapeHtml(l.description || '')}"
             oninput="_invLineRows[${i}].description = this.value">
      <input type="number" step="0.01" class="field-input" placeholder="Qty"
             value="${l.quantity ?? 1}"
             oninput="_invLineRows[${i}].quantity = parseFloat(this.value) || 0; recalcInvoiceTotals()">
      <input type="text" class="field-input" placeholder="Unit"
             value="${escapeHtml(l.unit || '')}"
             oninput="_invLineRows[${i}].unit = this.value">
      <input type="number" step="0.01" class="field-input" placeholder="Unit £"
             value="${l.unit_price ?? 0}"
             oninput="_invLineRows[${i}].unit_price = parseFloat(this.value) || 0; recalcInvoiceTotals()">
      <input type="text" class="field-input" readonly tabindex="-1"
             style="background:var(--bg-darker);text-align:right"
             value="£${_invFmt2((l.quantity || 0) * (l.unit_price || 0))}">
      <button type="button" class="btn btn-ghost"
              style="padding:4px 8px;color:var(--red);border-color:var(--red)"
              onclick="removeInvLineRow(${i})">×</button>
    </div>
  `).join('');
}
function _invToggleRetentionFields() {
  const mode = document.getElementById('invNewRetentionMode').value;
  document.getElementById('invRetentionPctWrap').style.display  = (mode === 'pct') ? '' : 'none';
  document.getElementById('invRetentionAmtWrap').style.display  = (mode === 'amt') ? '' : 'none';
  document.getElementById('invRetentionDueWrap').style.display  = (mode === 'none') ? 'none' : '';
  recalcInvoiceTotals();
}

// ── Totals recalc ──
function recalcInvoiceTotals() {
  // MUST match _invPayload()'s maths exactly, or the preview shows one total
  // and the saved/printed invoice shows another. Per-line 2dp then summed —
  // the same rule the PDF prints, so the invoice always adds up.
  const net = sumMoney(_invLineRows, l => Number(l.quantity || 0) * Number(l.unit_price || 0));
  const treatment = document.getElementById('invNewVatTreatment').value;
  const vatApplies = treatment === 'standard';
  const cisReverse = treatment === 'reverse_charge';

  let retention = 0;
  const mode = document.getElementById('invNewRetentionMode').value;
  if (mode === 'pct') {
    retention = pctOf(net, document.getElementById('invNewRetentionPct').value || 0);
  } else if (mode === 'amt') {
    retention = _r2(document.getElementById('invNewRetentionAmt').value || 0);
  }

  // VAT calculated on net minus retention (standard UK practice).
  // Under CIS domestic reverse charge, the supplier does NOT add VAT to
  // the gross (the customer accounts for VAT to HMRC). The VAT amount
  // is still computed and shown for information, but as a "reverse
  // charge" figure rather than a billable VAT line.
  const vatBase = _r2(net - retention);
  const standardVat = vatApplies ? pctOf(vatBase, 20) : 0;
  const vat = cisReverse ? 0 : standardVat;
  const reverseCharge = cisReverse ? pctOf(vatBase, 20) : 0;
  const gross = _r2(net - retention + vat);

  document.getElementById('invTotalNet').textContent       = '£' + _invFmt2(net);
  document.getElementById('invTotalRetention').textContent = '£' + _invFmt2(retention);
  document.getElementById('invTotalVat').textContent       = '£' + _invFmt2(vat);
  document.getElementById('invTotalReverse').textContent   = '£' + _invFmt2(reverseCharge);
  document.getElementById('invTotalGross').textContent     = '£' + _invFmt2(gross);

  // Hide the VAT row entirely when CIS reverse applies — no VAT on the invoice.
  // Show the reverse-charge row only when CIS reverse is on.
  document.getElementById('invTotalVatRow').style.display     = cisReverse ? 'none' : '';
  document.getElementById('invTotalReverseRow').style.display = cisReverse ? '' : 'none';
}

// ── Save (Draft) — no PDF yet ──
async function saveInvoiceDraft() {
  const payload = _buildInvoicePayload();
  if (!payload) return;
  const btn = document.getElementById('invSaveDraftBtn');
  try {
    if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
    let saved;
    if (_invEditing) {
      saved = await api.put(`/api/invoices/${_invEditing.id}`, payload);
    } else {
      saved = await api.post('/api/invoices', payload);
    }
    toast(`Invoice ${saved.ref} saved as Draft ✓`, 'success');
    closeInvNewModal();
    await loadInvoicingData();
    switchInvTab('sales');
  } catch (err) {
    console.error('Save invoice failed', err);
    toast('Save failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Save Draft'; }
  }
}

// ── Save + Issue (Draft → Issued, generates PDF, uploads to SharePoint) ──
async function saveAndIssueInvoice() {
  const payload = _buildInvoicePayload();
  if (!payload) return;
  const btn = document.getElementById('invIssueBtn');
  try {
    if (btn) { btn.disabled = true; btn.textContent = 'Issuing…'; }
    setLoading(true);

    // 1. Save draft first (DB row needed for ref allocation + FK on attachment)
    let saved;
    if (_invEditing) {
      saved = await api.put(`/api/invoices/${_invEditing.id}`, payload);
    } else {
      saved = await api.post('/api/invoices', payload);
    }

    // 2. Build PDF locally
    await loadLogoDataUri();
    const pdfData = await _buildInvoicePdfData(saved);
    const pdfBlob = await renderBamaInvoicePDF(pdfData);
    const fileName = sanitizeSpFilename(`${saved.ref}.pdf`);

    // 3. Upload to SharePoint: 01 - Accounts/03 - Sales Invoices/{YYYY}/{MM}/
    const folder = await _findOrCreateInvoiceFolder(saved.invoice_date);
    const driveItem = await uploadFileToFolder(folder.id, fileName, pdfBlob, 'application/pdf');

    // 4. Tell the API to mark as Issued and store the SharePoint link
    await api.post(`/api/invoices/${saved.id}/issue`, {
      sharepoint_pdf_id: driveItem.id,
      sharepoint_pdf_url: driveItem.webUrl
    });

    toast(`${saved.kind === 'credit_note' ? 'Credit note' : 'Invoice'} ${saved.ref} issued and uploaded to SharePoint ✓`, 'success');
    await _invAllocateCreditNote(saved);
    closeInvNewModal();
    await loadInvoicingData();
    switchInvTab('sales');
    // Last mile: open the email composer with the PDF attached
    await _openInvoiceEmailComposer(await api.get(`/api/invoices/${saved.id}`));
  } catch (err) {
    console.error('Issue invoice failed', err);
    toast('Issue failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    setLoading(false);
    if (btn) { btn.disabled = false; btn.textContent = 'Save & Issue'; }
  }
}

function _buildInvoicePayload() {
  // Validate
  const kind = document.getElementById('invNewKind').value;
  const invoiceDate = document.getElementById('invNewDate').value;
  if (!invoiceDate) { toast('Please pick an invoice date', 'error'); return null; }
  if (!_invSelectedClient && !document.getElementById('invNewCustomerSearch').value.trim()) {
    toast('Please pick a customer or enter free-text', 'error'); return null;
  }
  if (_invLineRows.length === 0 || _invLineRows.every(l => !l.description.trim())) {
    toast('Please add at least one line item', 'error'); return null;
  }

  const treatment = document.getElementById('invNewVatTreatment').value;
  const vatApplies = treatment === 'standard';
  const cisReverse = treatment === 'reverse_charge';
  const mode = document.getElementById('invNewRetentionMode').value;

  const cleanLines = _invLineRows
    .filter(l => l.description && l.description.trim())
    .map((l, i) => ({
      line_no: i + 1,
      description: l.description.trim(),
      quantity: Number(l.quantity || 0),
      unit: l.unit || null,
      unit_price: Number(l.unit_price || 0),
      line_total: _r2(Number(l.quantity || 0) * Number(l.unit_price || 0))
    }));

  const net = sumMoney(cleanLines, l => l.line_total);
  let retention = 0, retention_pct = null;
  if (mode === 'pct') {
    retention_pct = Number(document.getElementById('invNewRetentionPct').value || 0);
    retention = pctOf(net, retention_pct);
  } else if (mode === 'amt') {
    retention = _r2(document.getElementById('invNewRetentionAmt').value || 0);
  }
  const vatBase = _r2(net - retention);
  // CIS domestic reverse charge: VAT is shown for info as reverse charge,
  // but NOT added to the supplier's gross — customer accounts for it.
  const standardVat = vatApplies ? pctOf(vatBase, 20) : 0;
  const vat = cisReverse ? 0 : standardVat;
  const reverseCharge = cisReverse ? pctOf(vatBase, 20) : 0;
  const gross = _r2(net - retention + vat);

  return {
    kind,
    invoice_date: invoiceDate,
    due_date: document.getElementById('invNewDueDate').value || null,
    client_id: _invSelectedClient ? _invSelectedClient.id : null,
    customer_text: _invSelectedClient ? null : document.getElementById('invNewCustomerSearch').value.trim(),
    project_id: _invSelectedProject ? _invSelectedProject.id : null,
    parent_invoice_id: (kind === 'credit_note' && _invSelectedParent) ? _invSelectedParent.id
                     : (_invEditing && _invEditing.is_retention_release ? (_invEditing.parent_invoice_id || null) : null),
    is_retention_release: (_invEditing && _invEditing.is_retention_release) ? 1 : 0,
    vat_applies: vatApplies ? 1 : 0,
    cis_reverse_charge: cisReverse ? 1 : 0,
    net_amount: _r2(net),
    vat_amount: vat,
    reverse_charge_amount: reverseCharge,
    retention_pct,
    retention_amount: retention,
    retention_due_date: mode === 'none' ? null : (document.getElementById('invNewRetentionDue').value || null),
    gross_amount: gross,
    total_outstanding: gross,
    notes: document.getElementById('invNewNotes').value || null,
    line_items: cleanLines
  };
}

// ── Build the data structure the PDF renderer expects ─────────────────────
async function _buildInvoicePdfData(inv) {
  // Re-fetch if the saved object lacks line items or AFP join metadata
  let lines = inv.line_items;
  if (!Array.isArray(lines) || (inv.source_afp_id && !inv.afp_ref) || (inv.parent_invoice_id && !inv.parent_invoice_ref)) {
    const detail = await api.get(`/api/invoices/${inv.id}`);
    lines = detail.line_items || [];
    inv = { ...detail, ...{} };
  }
  const customer = inv.client_company_name
    || (_invSelectedClient && _invSelectedClient.company_name)
    || inv.customer_text
    || '—';
  // Full Bill To block: name + address. Address comes from (in order) the
  // detail-join columns, the in-page selected client, or the clients cache.
  const _cli = (inv.client_address_line1 !== undefined) ? {
        address_line1: inv.client_address_line1, address_line2: inv.client_address_line2,
        city: inv.client_city, county: inv.client_county, postcode: inv.client_postcode
      }
    : (_invSelectedClient && _invSelectedClient.company_name === customer) ? _invSelectedClient
    : (inv.client_id ? ((typeof _invClientsCache !== 'undefined' ? _invClientsCache : []) || []).find(c => c.id === inv.client_id) : null);
  const _addrLines = _cli ? [
    _cli.address_line1,
    _cli.address_line2,
    [_cli.city, _cli.county].filter(Boolean).join(', '),
    _cli.postcode
  ].map(x => String(x || '').trim()).filter(Boolean) : [];
  let billToBlock = [customer, ..._addrLines].join('\n');
  // No address on the client record — offer to capture it right here (saves
  // to Clients so every future document has it). Skippable.
  if (_addrLines.length === 0 && inv.client_id && typeof showConfirmAsync === 'function') {
    const wants = await showConfirmAsync(
      'Add customer address?',
      `<p><b>${escapeHtml(customer)}</b> has no address on record — many clients reject invoices without one.</p>
       <input type="text" id="cliFixL1" class="field-input" placeholder="Address line 1" style="width:100%;margin-bottom:6px">
       <input type="text" id="cliFixL2" class="field-input" placeholder="Address line 2 (optional)" style="width:100%;margin-bottom:6px">
       <div style="display:grid;grid-template-columns:1fr 1fr 120px;gap:6px">
         <input type="text" id="cliFixCity" class="field-input" placeholder="City">
         <input type="text" id="cliFixCounty" class="field-input" placeholder="County (optional)">
         <input type="text" id="cliFixPc" class="field-input" placeholder="Postcode">
       </div>`,
      { okLabel: 'Save & use', cancelLabel: 'Skip for now' }
    );
    if (wants) {
      const upd = {
        address_line1: (document.getElementById('cliFixL1')?.value || '').trim() || null,
        address_line2: (document.getElementById('cliFixL2')?.value || '').trim() || null,
        city:          (document.getElementById('cliFixCity')?.value || '').trim() || null,
        county:        (document.getElementById('cliFixCounty')?.value || '').trim() || null,
        postcode:      (document.getElementById('cliFixPc')?.value || '').trim() || null
      };
      if (upd.address_line1 || upd.postcode) {
        try {
          const savedCli = await api.put(`/api/clients/${inv.client_id}`, upd);
          const cache = (typeof _invClientsCache !== 'undefined' ? _invClientsCache : []) || [];
          const idx = cache.findIndex(c => c.id === inv.client_id);
          if (idx >= 0) cache[idx] = { ...cache[idx], ...savedCli };
          const newLines = [savedCli.address_line1, savedCli.address_line2,
            [savedCli.city, savedCli.county].filter(Boolean).join(', '), savedCli.postcode]
            .map(x => String(x || '').trim()).filter(Boolean);
          billToBlock = [customer, ...newLines].join('\n');
          toast('Client address saved ✓', 'success');
        } catch (e) {
          toast('Could not save address: ' + (e.message || 'unknown'), 'error');
        }
      }
    }
  } else if (_addrLines.length === 0 && typeof toast === 'function') {
    toast('⚠ No customer address on this invoice — many clients reject invoices without one. Add it to the client record.', 'warning');
  }
  const projectLabel = _invSelectedProject
    ? `${_invSelectedProject.project_number || ''} — ${_invSelectedProject.project_name || ''}`
    : (inv.project_number ? `${inv.project_number} — ${inv.project_name || ''}` : '');

  return {
    kind: inv.kind || 'invoice',
    ref: inv.ref,
    invoiceDate: inv.invoice_date,
    dueDate: inv.due_date,
    billTo: billToBlock,
    project: projectLabel,
    vatApplies: !!inv.vat_applies,
    cisReverse: !!inv.cis_reverse_charge,
    retention: Number(inv.retention_amount || 0),
    retentionDueDate: inv.retention_due_date,
    net: Number(inv.net_amount || 0),
    vat: Number(inv.vat_amount || 0),
    reverseCharge: Number(inv.reverse_charge_amount || 0),
    gross: Number(inv.gross_amount || 0),
    afpRef: inv.afp_ref || null,
    certRef: inv.afp_certificate_ref || null,
    certDate: inv.afp_certificate_date || null,
    parentRef: inv.parent_invoice_ref || null,
    isRetentionRelease: !!inv.is_retention_release,
    notes: inv.notes || '',
    lineItems: lines.map((l, i) => ({
      itemNum: i + 1,
      description: l.description,
      quantity: l.quantity,
      unit: l.unit,
      unitPrice: l.unit_price,
      amount: l.line_total
    }))
  };
}

// ── SharePoint folder for the invoice PDF ─────────────────────────────────
// D0 taxonomy: BAMA / 07 - Accounts / {Sales|Purchase} Invoices / <NN - YYYY> / MM /
// Year folders use the spYearName() convention (e.g. "04 - 2026") like the rest
// of the tree; parent IDs come from SP_TAX. Resolved folder IDs are cached per
// (parentId, childName) so a multi-file import doesn't re-POST the same
// year/month folder for every file (each re-POST logs a harmless 409).
const _spFolderCache = new Map();

async function _cachedSubfolder(parentId, childName) {
  const key = parentId + '|' + childName;
  if (_spFolderCache.has(key)) return _spFolderCache.get(key);
  const folder = await getOrCreateSubfolder(parentId, childName, BAMA_DRIVE_ID);
  _spFolderCache.set(key, folder);
  return folder;
}

async function _findOrCreateInvoiceFolder(invoiceDate) {
  // 07 - Accounts / <sales invoices> / <NN - YYYY> / MM /
  return await _appendTaxYearMonth(SP_TAX.salesInvoices, invoiceDate);
}

async function _findOrCreateSupplierInvoiceFolder(invoiceDate) {
  // 07 - Accounts / <purchase invoices> / <NN - YYYY> / MM /
  return await _appendTaxYearMonth(SP_TAX.purchaseInvoices, invoiceDate);
}

// Given a SP_TAX parent folder id, append the D0-style year folder ("04 - 2026")
// then a numeric month folder ("07"). Falls back to the current date when the
// invoice date is missing or unparseable, so a PDF is never stranded rootless.
async function _appendTaxYearMonth(parentId, dateStr) {
  const d = new Date(dateStr);
  const valid = !isNaN(d);
  const yyyy = valid ? d.getFullYear() : new Date().getFullYear();
  const mm = valid ? String(d.getMonth() + 1).padStart(2, '0')
                   : String(new Date().getMonth() + 1).padStart(2, '0');
  const yearFolder = await _cachedSubfolder(parentId, spYearName(yyyy));
  return await _cachedSubfolder(yearFolder.id, mm);
}

// ═════════════════════════════════════════════════════════════════════════
// PDF RENDERER — shared BAMA template family (Invoice, Pro Forma, Credit Note, PO)
// Mirrors drawBabcockQuotePDF — same letterhead, brand colours, layout.
// ═════════════════════════════════════════════════════════════════════════

// Resolve the jsPDF constructor (mirrors the renderBabcockQuotePDF path)
async function _resolveJsPDF() {
  if (typeof window.jspdf !== 'undefined' && typeof window.jspdf.jsPDF === 'function') return window.jspdf.jsPDF;
  if (typeof window.jsPDF === 'function') return window.jsPDF;
  if (typeof window.html2pdf !== 'undefined' && typeof window.html2pdf.jsPDF === 'function') return window.html2pdf.jsPDF;

  // Dynamic load fallback
  await new Promise((resolve, reject) => {
    const existing = document.querySelector('script[data-jspdf-loaded]');
    if (existing) {
      let tries = 0;
      const tick = () => {
        if (window.jspdf && window.jspdf.jsPDF) return resolve();
        if (++tries > 50) return reject(new Error('jsPDF load timed out'));
        setTimeout(tick, 100);
      };
      tick();
      return;
    }
    const s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
    s.dataset.jspdfLoaded = '1';
    s.onload = resolve;
    s.onerror = () => reject(new Error('Failed to load jsPDF from CDN'));
    document.head.appendChild(s);
  });
  if (window.jspdf && window.jspdf.jsPDF) return window.jspdf.jsPDF;
  throw new Error('jsPDF unavailable');
}

async function renderBamaInvoicePDF(d) {
  const JsPDFCtor = await _resolveJsPDF();
  const logo = _logoDataUriCache || '';
  return drawBamaInvoicePDF(JsPDFCtor, d, logo);
}

function drawBamaInvoicePDF(jsPDF, d, logoDataUri) {
  const fmtNum = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const fmtDate = s => {
    if (!s) return '';
    const m = String(s).match(/^(\d{4})-(\d{2})-(\d{2})/);
    return m ? `${m[3]}/${m[2]}/${m[1]}` : s;
  };

  const titleByKind = {
    invoice:     'Invoice',
    pro_forma:   'Pro Forma',
    credit_note: 'Credit Note'
  };
  const title = titleByKind[d.kind] || 'Invoice';

  const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  try {
    doc.setProperties({
      title: `BAMA ${title} ${d.ref || ''}`.trim(),
      subject: `${title} for ${String(d.billTo || '').split('\n')[0]}`,
      author: 'BAMA Fabrication',
      creator: 'BAMA Fabrication ERP'
    });
  } catch (e) { /* */ }

  const pageW = 210, pageH = 297;
  const marginL = 14, marginR = 14, marginB = 14;
  const usableW = pageW - marginL - marginR;

  const RED = [208, 2, 27], NAVY = [31, 53, 82];
  const TEXT = [34, 34, 34], MUTED = [85, 85, 85];
  const RULE = [212, 212, 212], HEADRULE = [68, 68, 68];

  const setText = (rgb) => doc.setTextColor(rgb[0], rgb[1], rgb[2]);
  const setFill = (rgb) => doc.setFillColor(rgb[0], rgb[1], rgb[2]);
  const setDraw = (rgb) => doc.setDrawColor(rgb[0], rgb[1], rgb[2]);

  // ── Header: logo left, title right ──
  let y = marginL;
  if (logoDataUri) {
    try { doc.addImage(logoDataUri, 'PNG', marginL, y, 75, 32, undefined, 'FAST'); }
    catch (e) {
      doc.setFont('helvetica', 'bold'); doc.setFontSize(22); setText(RED);
      doc.text('BAMA FABRICATION', marginL, y + 12);
    }
  } else {
    doc.setFont('helvetica', 'bold'); doc.setFontSize(22); setText(RED);
    doc.text('BAMA FABRICATION', marginL, y + 12);
  }

  doc.setFont('helvetica', 'normal'); doc.setFontSize(34); setText([43, 43, 43]);
  doc.text(title, pageW - marginR, y + 16, { align: 'right' });

  y = marginL + 42;

  // ── Two-column body header: company / bill-to | meta table ──
  const leftColW = usableW * 0.6;
  const rightColX = marginL + leftColW + 4;
  const rightColW = usableW - leftColW - 4;
  let leftY = y, rightY = y;

  // LEFT: Company Address
  setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5);
  doc.text('From', marginL, leftY); leftY += 4.5;
  setText(TEXT); doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  ['BAMA Fabrication Ltd', '11 Enterprise Way, Enterprise Park, Yaxley,',
   'PE7 3WY, Peterborough', '01733 855212', 'accounts@bamafabrication.co.uk']
    .forEach(line => { doc.text(line, marginL + 4, leftY); leftY += 4; });
  leftY += 4;

  // LEFT: Bill To
  setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5);
  doc.text('Bill To', marginL, leftY); leftY += 4.5;
  setText(TEXT); doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  if (d.billTo) {
    const wrapped = doc.splitTextToSize(String(d.billTo), leftColW - 4);
    wrapped.forEach(line => { doc.text(line, marginL + 4, leftY); leftY += 4; });
  }
  if (d.project) {
    leftY += 1;
    setText(MUTED); doc.setFontSize(9);
    doc.text(`Project: ${d.project}`, marginL + 4, leftY); leftY += 4;
    setText(TEXT); doc.setFontSize(10);
  }
  if (d.parentRef) {
    setText(MUTED); doc.setFontSize(9);
    doc.text(d.isRetentionRelease
      ? `Release of retention held under Invoice ${d.parentRef}`
      : `Credit against Invoice ${d.parentRef}`, marginL + 4, leftY); leftY += 4;
    setText(TEXT); doc.setFontSize(10);
  }
  if (d.afpRef) {
    setText(MUTED); doc.setFontSize(9);
    let reLine = `Re: Application for Payment ${d.afpRef}`;
    if (d.certRef) {
      reLine += ` · Payment Certificate ${d.certRef}`;
      if (d.certDate) reLine += ` dated ${fmtDate(d.certDate)}`;
    }
    const reWrapped = doc.splitTextToSize(reLine, leftColW - 4);
    reWrapped.forEach(line => { doc.text(line, marginL + 4, leftY); leftY += 4; });
    setText(TEXT); doc.setFontSize(10);
  }
  leftY += 3;

  // RIGHT: Meta table
  const metaLabel = title === 'Credit Note' ? 'Credit Note #' : (title === 'Pro Forma' ? 'Pro Forma #' : 'Invoice #');
  const metaRows = [
    { label: 'Date',          value: fmtDate(d.invoiceDate) },
    { label: metaLabel,       value: d.ref || '' },
    { label: 'Due Date',      value: fmtDate(d.dueDate), gapAfter: true }
  ];
  doc.setFontSize(10);
  const labelColX = rightColX, labelColW = rightColW * 0.55, valueColX = rightColX + labelColW + 2;
  for (const row of metaRows) {
    setText(TEXT); doc.setFont('helvetica', 'bold');
    doc.text(row.label, labelColX + labelColW, rightY, { align: 'right' });
    setText(TEXT); doc.setFont('helvetica', 'normal');
    doc.text(String(row.value || ''), valueColX, rightY);
    rightY += row.gapAfter ? 7.5 : 4.5;
  }

  y = Math.max(leftY, rightY) + 4;

  // ── Optional notes ──
  if (d.notes && String(d.notes).trim()) {
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5);
    doc.text('Notes', marginL, y); y += 4.5;
    setText(TEXT); doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
    const wrapped = doc.splitTextToSize(String(d.notes).trim(), usableW - 4);
    wrapped.forEach(line => {
      if (y > pageH - marginB - 20) { doc.addPage(); y = marginL; }
      doc.text(line, marginL + 4, y); y += 4.2;
    });
    y += 4;
  }

  // ── Line items table ──
  const colItem  = { x: marginL, w: 12, align: 'center' };
  const colAmt   = { w: 28, align: 'right' };
  const colQty   = { w: 18, align: 'center' };
  const colPrice = { w: 26, align: 'right' };
  const colDesc  = { w: usableW - colItem.w - colPrice.w - colQty.w - colAmt.w, align: 'left' };
  colDesc.x = colItem.x + colItem.w;
  colPrice.x = colDesc.x + colDesc.w;
  colQty.x = colPrice.x + colPrice.w;
  colAmt.x = colQty.x + colQty.w;

  doc.setFont('helvetica', 'bold'); doc.setFontSize(11); setText(TEXT);
  doc.text('#',           colItem.x + colItem.w / 2,  y, { align: 'center' });
  doc.text('Description', colDesc.x + 1,               y);
  doc.text('Unit £',      colPrice.x + colPrice.w - 1, y, { align: 'right' });
  doc.text('Qty',         colQty.x + colQty.w / 2,     y, { align: 'center' });
  doc.text('Amount',      colAmt.x + colAmt.w - 1,     y, { align: 'right' });
  y += 1.5;
  setDraw(HEADRULE); doc.setLineWidth(0.4);
  doc.line(marginL, y, pageW - marginR, y);
  y += 3;

  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  setDraw(RULE); doc.setLineWidth(0.15);
  for (let i = 0; i < (d.lineItems || []).length; i++) {
    const l = d.lineItems[i];
    const desc = String(l.description || '');
    const descLines = doc.splitTextToSize(desc, colDesc.w - 2);
    const rowH = Math.max(5, descLines.length * 4.2 + 1);
    if (y + rowH > pageH - marginB - 50) { doc.addPage(); y = marginL + 6; }

    setText(MUTED);
    doc.text(String(l.itemNum ?? (i + 1)), colItem.x + colItem.w / 2, y + 3.5, { align: 'center' });

    setText(TEXT);
    let descY = y + 3.5;
    for (const line of descLines) { doc.text(line, colDesc.x + 1, descY); descY += 4.2; }

    if (l.unitPrice != null) doc.text(fmtNum(l.unitPrice), colPrice.x + colPrice.w - 1, y + 3.5, { align: 'right' });
    if (l.quantity  != null) doc.text(String(l.quantity), colQty.x + colQty.w / 2, y + 3.5, { align: 'center' });
    doc.text(fmtNum(l.amount), colAmt.x + colAmt.w - 1, y + 3.5, { align: 'right' });

    setDraw(RULE); doc.setLineWidth(0.15);
    doc.line(marginL, y + rowH, pageW - marginR, y + rowH);
    y += rowH;
  }

  y += 6;

  // ── Totals block (right-aligned) ──
  if (y > pageH - marginB - 60) { doc.addPage(); y = marginL + 6; }
  const tlX = pageW - marginR - 80;
  const labelX = tlX, amtX = pageW - marginR;
  const lineH = 6;
  const drawTotal = (label, value, bold) => {
    setText(TEXT);
    doc.setFont('helvetica', bold ? 'bold' : 'normal');
    doc.setFontSize(bold ? 11 : 10);
    doc.text(label, labelX, y);
    doc.text('£' + fmtNum(value), amtX, y, { align: 'right' });
    y += lineH;
  };
  drawTotal('Subtotal (Net)', d.net);
  if (Number(d.retention) > 0) drawTotal(`Less Retention${d.retentionDueDate ? ` (due ${fmtDate(d.retentionDueDate)})` : ''}`, -d.retention);
  // VAT line only shown when standard VAT is being charged. Under CIS
  // domestic reverse charge, no VAT is on the invoice — only the
  // notice line below ("customer to account for £X VAT to HMRC").
  if (d.vatApplies && !d.cisReverse) drawTotal('VAT (20%)', d.vat);
  if (d.cisReverse) {
    setText(MUTED); doc.setFont('helvetica', 'italic'); doc.setFontSize(9);
    doc.text('Domestic reverse charge: VAT Act 1994 Section 55A applies.', labelX, y);
    y += 4;
    doc.text(`Customer to account to HMRC for the reverse charge output tax`, labelX, y);
    y += 4;
    doc.text(`of £${fmtNum(d.reverseCharge)} (VAT at 20%) on the above amount.`, labelX, y);
    y += lineH;
  }

  // TOTAL pill
  y += 2;
  setFill(NAVY);
  doc.rect(tlX, y - 2, 80, 9, 'F');
  doc.setFont('helvetica', 'bold'); doc.setFontSize(12); setText([255, 255, 255]);
  doc.text('TOTAL DUE', tlX + 3, y + 4);
  doc.setFontSize(13);
  doc.text('£' + fmtNum(d.gross), amtX - 2, y + 4, { align: 'right' });
  y += 14;

  // ── Bank details + footer ──
  if (y > pageH - marginB - 20) { doc.addPage(); y = marginL + 6; }
  setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
  doc.text('Payment Details', marginL, y); y += 4.5;
  setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5);
  ['Account name: Bama Fabrication Ltd',
   'Sort code: 30-99-50',
   'Account number: 26816462',
   'Reference: ' + (d.ref || ''),
   '',
   'If you have any questions about this invoice please contact: accounts@bamafabrication.co.uk'
  ].forEach(line => { doc.text(line, marginL, y); y += 4; });

  // Registration footer — bottom of the last page
  setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
  doc.text('BAMA Fabrication Ltd · Registered in England & Wales, Company No. 14680571 · VAT Registration No. 435 0591 07',
           pageW / 2, pageH - 8, { align: 'center' });

  return doc.output('blob');
}

// ═════════════════════════════════════════════════════════════════════════
// INVOICE DETAIL MODAL — view / payments / void / download PDF
// ═════════════════════════════════════════════════════════════════════════
async function openInvoiceDetail(id) {
  try {
    const inv = await api.get(`/api/invoices/${id}`);
    _invDetailCurrent = inv;
    document.getElementById('invDetailRef').textContent = inv.ref;
    document.getElementById('invDetailKind').textContent =
      inv.kind === 'pro_forma' ? 'Pro Forma' : (inv.kind === 'credit_note' ? 'Credit Note' : 'Invoice');
    document.getElementById('invDetailCustomer').textContent =
      inv.client_company_name || inv.customer_text || '—';
    document.getElementById('invDetailProject').textContent =
      (inv.kind === 'credit_note' && inv.parent_invoice_ref)
        ? `Credits ${inv.parent_invoice_ref}${inv.project_number ? ` · ${inv.project_number}` : ''}`
        : (inv.is_retention_release && inv.parent_invoice_ref)
        ? `Retention release for ${inv.parent_invoice_ref}${inv.project_number ? ` · ${inv.project_number}` : ''}`
        : (inv.project_number ? `${inv.project_number} — ${inv.project_name || ''}` : '—');
    document.getElementById('invDetailDate').textContent =
      inv.invoice_date ? new Date(inv.invoice_date).toLocaleDateString('en-GB') : '—';
    document.getElementById('invDetailDue').textContent =
      inv.due_date ? new Date(inv.due_date).toLocaleDateString('en-GB') : '—';
    document.getElementById('invDetailNet').textContent      = '£' + _invFmt2(inv.net_amount);
    document.getElementById('invDetailVat').textContent      = '£' + _invFmt2(inv.vat_amount);
    document.getElementById('invDetailRet').textContent      = '£' + _invFmt2(inv.retention_amount);
    document.getElementById('invDetailGross').textContent    = '£' + _invFmt2(inv.gross_amount);
    document.getElementById('invDetailOutstanding').textContent = '£' + _invFmt2(inv.total_outstanding);
    document.getElementById('invDetailStatus').innerHTML = invStatusBadge(inv.status);

    // PDF link
    const pdfBtn = document.getElementById('invDetailPdfBtn');
    if (inv.sharepoint_pdf_url) {
      pdfBtn.style.display = '';
      pdfBtn.onclick = () => window.open(inv.sharepoint_pdf_url, '_blank');
    } else {
      pdfBtn.style.display = 'none';
    }

    // Buttons
    const issueBtn = document.getElementById('invDetailIssueBtn');
    const payBtn = document.getElementById('invDetailPayBtn');
    const delBtn = document.getElementById('invDetailDeleteBtn');
    if (delBtn) delBtn.style.display = (inv.status === 'Draft' || inv.status === 'Void') ? '' : 'none';
    const voidBtn = document.getElementById('invDetailVoidBtn');
    issueBtn.style.display = (inv.status === 'Draft')     ? '' : 'none';
    const editBtn = document.getElementById('invDetailEditBtn');
    if (editBtn) editBtn.style.display = (inv.status === 'Draft') ? '' : 'none';
    const emailBtn = document.getElementById('invDetailEmailBtn');
    if (emailBtn) emailBtn.style.display =
      (inv.status === 'Issued' || inv.status === 'Partially Paid' || inv.status === 'Paid') ? '' : 'none';
    const chaseBtn = document.getElementById('invDetailChaseBtn');
    if (chaseBtn) chaseBtn.style.display =
      ((inv.status === 'Issued' || inv.status === 'Partially Paid') && Number(inv.total_outstanding || 0) > 0.005 && inv.kind === 'invoice') ? '' : 'none';
    const reopenBtn = document.getElementById('invDetailReopenBtn');
    if (reopenBtn) reopenBtn.style.display =
      (inv.status === 'Paid' && (inv.payments || []).length === 0) ? '' : 'none';
    payBtn.style.display   = (inv.status === 'Issued' || inv.status === 'Partially Paid') ? '' : 'none';
    voidBtn.style.display  = (inv.status !== 'Void' && inv.status !== 'Cancelled') ? '' : 'none';

    // Line items table
    document.getElementById('invDetailLines').innerHTML = (inv.line_items || []).map(l => `
      <tr>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border)">${escapeHtml(l.description || '')}</td>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border);text-align:right">${Number(l.quantity || 0)}</td>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border);text-align:right">£${_invFmt2(l.unit_price)}</td>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border);text-align:right">£${_invFmt2(l.line_total)}</td>
      </tr>`).join('') || '<tr><td colspan="4" style="padding:10px;color:var(--muted)">No line items</td></tr>';

    // Payments table
    document.getElementById('invDetailPayments').innerHTML = (inv.payments || []).map(p => `
      <tr>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border)">${p.payment_date ? new Date(p.payment_date).toLocaleDateString('en-GB') : ''}</td>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border)">${escapeHtml(p.method || '')}${p.is_retention_release ? ' <span style="font-size:10px;color:var(--muted)">(retention)</span>' : ''}</td>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border)">${escapeHtml(p.reference || '')}</td>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border);text-align:right">£${_invFmt2(p.amount)}</td>
        <td style="padding:6px 8px;border-bottom:1px solid var(--border);text-align:center">
          <button class="btn btn-ghost" style="padding:2px 6px;font-size:11px;color:var(--red);border-color:var(--red)"
                  onclick="deleteInvPayment(${p.id})">×</button>
        </td>
      </tr>`).join('') || '<tr><td colspan="5" style="padding:10px;color:var(--muted)">No payments recorded</td></tr>';

    document.getElementById('invDetailModal').classList.add('active');
  } catch (err) {
    console.error('Open invoice detail failed', err);
    toast('Failed to load invoice', 'error');
  }
}

function closeInvDetail() {
  document.getElementById('invDetailModal').classList.remove('active');
  _invDetailCurrent = null;
}

// ── Edit a Draft invoice: reuse the New Invoice modal prefilled ──────────
async function editInvoiceFromDetail() {
  if (!_invDetailCurrent) return;
  const inv = _invDetailCurrent;
  if (inv.status !== 'Draft') { toast('Only Draft invoices can be edited', 'error'); return; }

  _invEditing = inv;
  _invSelectedClient = inv.client_id ? (_invClientsCache.find(c => c.id === inv.client_id) || null) : null;
  _invSelectedProject = inv.project_id ? (_invProjectsCache.find(p => p.id === inv.project_id) || null) : null;
  _invPaymentTermsDays = Number(inv.client_payment_terms) > 0 ? Number(inv.client_payment_terms) : 30;

  document.getElementById('invNewModalTitle').textContent = `✏️ Edit ${inv.ref}`;
  document.getElementById('invNewKind').value = inv.kind || 'invoice';
  document.getElementById('invNewRef').value = inv.ref || '';
  document.getElementById('invNewDate').value = _invToDateStr(inv.invoice_date);
  document.getElementById('invNewDueDate').value = _invToDateStr(inv.due_date);

  // Customer + project
  document.getElementById('invNewCustomerSearch').value =
    inv.client_company_name || inv.customer_text || '';
  document.getElementById('invNewCustomerSelected').textContent =
    _invSelectedClient ? `✓ ${_invSelectedClient.company_name} (from Clients)`
                       : (inv.customer_text ? `✓ "${inv.customer_text}" (free-text)` : '');
  document.getElementById('invNewCustomerDropdown').innerHTML = '';
  document.getElementById('invNewProjectSearch').value =
    inv.project_number ? `${inv.project_number} — ${inv.project_name || ''}` : '';
  document.getElementById('invNewProjectSelected').textContent =
    inv.project_number ? `✓ ${inv.project_number}` : '';
  document.getElementById('invNewProjectDropdown').innerHTML = '';

  // Credit note parent
  const parentWrap = document.getElementById('invNewParentWrap');
  if (parentWrap) parentWrap.style.display = (inv.kind === 'credit_note') ? '' : 'none';
  clearInvParent();
  if (inv.kind === 'credit_note' && inv.parent_invoice_id) {
    const parent = (_invInvoiceList || []).find(x => x.id === inv.parent_invoice_id);
    if (parent) selectInvParent(parent.id);
  }

  // VAT treatment from stored flags
  document.getElementById('invNewVatTreatment').value =
    _invTreatmentFromFlags(!!inv.vat_applies, !!inv.cis_reverse_charge);
  document.getElementById('invNewVatHint').textContent =
    inv.source_afp_id && inv.afp_ref ? `Generated from ${inv.afp_ref} — line + VAT fully editable while Draft` : '';

  // Retention
  const retAmt = Number(inv.retention_amount || 0);
  const retPct = inv.retention_pct != null ? Number(inv.retention_pct) : null;
  const modeEl = document.getElementById('invNewRetentionMode');
  if (retPct != null && retPct > 0) {
    modeEl.value = 'pct';
    document.getElementById('invNewRetentionPct').value = retPct;
  } else if (retAmt > 0) {
    modeEl.value = 'amt';
    document.getElementById('invNewRetentionAmt').value = retAmt;
  } else {
    modeEl.value = 'none';
    document.getElementById('invNewRetentionPct').value = '';
    document.getElementById('invNewRetentionAmt').value = '';
  }
  document.getElementById('invNewRetentionDue').value = _invToDateStr(inv.retention_due_date);
  _invToggleRetentionFields();

  document.getElementById('invNewNotes').value = inv.notes || '';

  // Line items
  _invLineRows = (inv.line_items || []).map(l => ({
    description: l.description || '',
    quantity: Number(l.quantity || 1),
    unit: l.unit || '',
    unit_price: Number(l.unit_price || 0)
  }));
  if (_invLineRows.length === 0) _invLineRows = [{ description: '', quantity: 1, unit: '', unit_price: 0 }];
  renderInvLineRows();
  recalcInvoiceTotals();

  closeInvDetail();
  document.getElementById('invNewModal').classList.add('active');
}

// ═════════════════════════════════════════════════════════════════════════
// HISTORICAL INVOICE IMPORT — bulk OCR + backfill (Phase 3)
// ═════════════════════════════════════════════════════════════════════════
let _invImportRows = [];      // [{file, fileName, ref, invoice_date, due_date, customer, client_id, net, vat, retention, gross, treatment, status, dup, committed}]
let _invImportBusy = false;

function openInvImportModal() {
  _invImportRows = [];
  _invImportBusy = false;
  document.getElementById('invImportProgress').textContent = '';
  document.getElementById('invImportSummary').innerHTML = '';
  document.getElementById('invImportCommitBtn').disabled = true;
  renderInvImportRows();
  document.getElementById('invImportModal').classList.add('active');
}
function closeInvImportModal() {
  if (_invImportBusy) { toast('Import in progress — please wait', 'error'); return; }
  document.getElementById('invImportModal').classList.remove('active');
}

// ── Fuzzy client match against the clients cache ──────────────────────────
function _invImportMatchClient(name) {
  if (!name) return null;
  const n = String(name).toLowerCase().replace(/\b(ltd|limited|plc|llp)\b/g, '').replace(/[^a-z0-9 ]/g, '').trim();
  if (!n) return null;
  let best = null;
  for (const c of _invClientsCache) {
    const cn = String(c.company_name || '').toLowerCase().replace(/\b(ltd|limited|plc|llp)\b/g, '').replace(/[^a-z0-9 ]/g, '').trim();
    if (!cn) continue;
    if (cn === n || cn.includes(n) || n.includes(cn)) { best = c; break; }
  }
  return best;
}

// Normalise refs like "INV0012 rev02", "inv 12", "Invoice #: INV0028" → INV0012 / INV0028.
// Falls back to scanning the filename if the parsed ref is unusable.
function _invImportNormaliseRef(raw, fileName) {
  const scan = (s) => {
    const m = String(s || '').toUpperCase().match(/(INV|PRO|CN)\s*[-_#:]*\s*0*(\d{1,6})/);
    if (!m) return null;
    return m[1] + String(parseInt(m[2], 10)).padStart(4, '0');
  };
  return scan(raw) || scan(fileName) || String(raw || '').toUpperCase().trim();
}

function _invImportExistingRefs() {
  const set = new Set((_invInvoiceList || []).map(i => String(i.ref || '').toUpperCase()));
  return set;
}

// ── File pick → sequential OCR ────────────────────────────────────────────
async function invImportFilesPicked(files) {
  const list = Array.from(files || []);
  document.getElementById('invImportFiles').value = '';
  if (!list.length) return;
  _invImportBusy = true;
  const prog = document.getElementById('invImportProgress');
  const pickBtn = document.getElementById('invImportPickBtn');
  if (pickBtn) pickBtn.disabled = true;

  for (let i = 0; i < list.length; i++) {
    const file = list[i];
    prog.textContent = `⏳ Reading ${file.name} (${i + 1}/${list.length})…`;
    try {
      const parsed = await _invImportParsePdf(file);
      parsed.ref = _invImportNormaliseRef(parsed.ref, file.name);
      const client = _invImportMatchClient(parsed.customer);
      const treatment = parsed.reverse_charge ? 'reverse_charge'
                      : (Number(parsed.vat || 0) > 0 ? 'standard' : 'zero');
      _invImportRows.push({
        file, fileName: file.name,
        ref: String(parsed.ref || '').toUpperCase(),
        invoice_date: parsed.invoice_date || '',
        due_date: parsed.due_date || '',
        customer: client ? client.company_name : (parsed.customer || ''),
        client_id: client ? client.id : null,
        line_description: parsed.description || null,
        net: Number(parsed.net || 0),
        vat: Number(parsed.vat || 0),
        retention: Number(parsed.retention || 0),
        gross: Number(parsed.gross || 0),
        treatment, status: 'Paid',
        dup: false, committed: false, error: null
      });
    } catch (err) {
      _invImportRows.push({
        file, fileName: file.name, ref: '', invoice_date: '', due_date: '',
        customer: '', client_id: null, line_description: null,
        net: 0, vat: 0, retention: 0, gross: 0,
        treatment: 'reverse_charge', status: 'Paid',
        dup: false, committed: false, error: 'Read failed: ' + err.message
      });
    }
    _invImportFlagDups();
    renderInvImportRows();
  }
  prog.textContent = `✓ ${list.length} file(s) read — review and commit`;
  _invImportBusy = false;
  if (pickBtn) pickBtn.disabled = false;
  document.getElementById('invImportCommitBtn').disabled = _invImportRows.length === 0;
}

function _invImportFlagDups() {
  const existing = _invImportExistingRefs();
  const seen = new Set();
  for (const r of _invImportRows) {
    const ref = String(r.ref || '').toUpperCase();
    r.dup = !!ref && (existing.has(ref) || seen.has(ref));
    if (ref) seen.add(ref);
  }
}

// ── Claude OCR for one invoice PDF (429 retry once after 30s) ─────────────
async function _invImportParsePdf(file) {
  const base64 = await new Promise((res, rej) => {
    const reader = new FileReader();
    reader.onload = () => res(reader.result.split(',')[1]);
    reader.onerror = () => rej(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });

  const call = async () => {
    const response = await fetch(API_BASE + '/api/claude-proxy', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${await getToken()}` },
      body: JSON.stringify({
        model: 'claude-sonnet-4-6',
        max_tokens: 1500,
        messages: [{
          role: 'user',
          content: [
            { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64 } },
            { type: 'text', text: `This is a historical BAMA Fabrication sales document — an invoice, credit note, or pro forma. Extract its details.

Return ONLY a JSON object, no markdown, no explanation:
{
  "ref": "invoice reference, normalised — e.g. 'Invoice #: INV0012 rev02' -> 'INV0012' (strip rev/revision suffixes and spaces; keep CN/PRO prefix if a credit note / pro forma)",
  "invoice_date": "YYYY-MM-DD or null",
  "due_date": "YYYY-MM-DD or null",
  "customer": "the BILL TO / customer company name only, first line of the Bill To block (NOT Bama Fabrication — that is the sender)",
  "description": "one short line summarising the works/project billed, max 120 chars, or null",
  "net": number or null (the SUBTOTAL before VAT),
  "vat": number or null (VAT actually charged and ADDED to the total; 0 if reverse charge or none),
  "retention": number or null (retention deducted, as a positive number; 0 if none),
  "gross": number or null (the TOTAL DUE / amount payable),
  "reverse_charge": true/false
}

Rules:
- Dates may appear as DD/MM/YYYY or DD.MM.YYYY — always UK day-first; convert to YYYY-MM-DD.
- If the due date is text like "On receipt" or "As Soon as Possible", return the invoice_date as due_date.
- Amounts may use comma decimals and space thousands (e.g. "£3 100,00" = 3100.00, "20.443.27" = 20443.27). Return plain numbers.
- reverse_charge is true if wording like "REVERSE CHARGE SUPPLY", "customer to pay VAT to HMRC", "customer to account for VAT", or "VAT Act 1994 Section 55A" appears. In that case vat = 0 (the ~20% figure shown is informational, not charged).
- If a "VAT 20%" line is added into the TOTAL DUE, reverse_charge is false and vat is that amount.
- Ignore "ALREADY PAID" lines for amounts — net is the stated SUBTOTAL, gross is the stated TOTAL DUE.
- If the document is a CREDIT NOTE, the ref starts CN (e.g. CN0003). Return all amounts as POSITIVE numbers even if shown negative or in brackets.
- If it is a PRO FORMA, keep the PRO prefix on the ref.` }
          ]
        }]
      })
    });
    return response;
  };

  let response = await call();
  if (response.status === 429) {
    document.getElementById('invImportProgress').textContent = '⏳ Rate limited — waiting 30s…';
    await new Promise(r => setTimeout(r, 30000));
    response = await call();
  }
  if (!response.ok) throw new Error(`AI error ${response.status}`);
  const data = await response.json();
  const text = (data.content || []).map(c => c.text || '').join('').trim();
  const clean = text.replace(/^```json\s*/, '').replace(/\s*```$/, '').trim();
  try { return JSON.parse(clean); }
  catch { throw new Error('AI returned invalid JSON'); }
}

// ═══════════════════════════════════════════════════════════════════════════
// FILL INVOICE FROM CLIENT PURCHASE ORDER (AI extraction → deterministic fill)
// Two-engine rule: Claude reads the PO and returns structured fields ONLY.
// All totals are recomputed by recalcInvoiceTotals(); nothing AI-computed is
// trusted for arithmetic — the PO's stated net is used purely as a sanity
// cross-check shown in the hint line.
// ═══════════════════════════════════════════════════════════════════════════
async function parseInvoicePO(input) {
  const file = input && input.files && input.files[0];
  if (input) input.value = '';               // allow re-picking the same file
  if (!file) return;
  const hint = document.getElementById('invPoParseHint');
  const btn  = document.getElementById('invPoParseBtn');
  if (btn) btn.disabled = true;
  if (hint) { hint.style.color = 'var(--muted)'; hint.textContent = '⏳ Reading PO…'; }

  try {
    const parsed = await _invParsePOFile(file);
    await _invApplyParsedPO(parsed);
    if (hint) {
      // Deterministic sanity check: our recomputed net vs the PO's stated net
      const ourNet = _invLineRows.reduce((s, l) => s + (Number(l.quantity || 0) * Number(l.unit_price || 0)), 0);
      const poNet  = Number(parsed.net_total);
      if (isFinite(poNet) && poNet > 0 && Math.abs(ourNet - poNet) > 0.011) {
        hint.style.color = 'var(--red)';
        hint.textContent = `⚠ Lines total £${_invFmt2(ourNet)} but PO states £${_invFmt2(poNet)} — check lines`;
      } else {
        hint.style.color = 'var(--green)';
        hint.textContent = `✓ Filled from PO ${parsed.po_number || ''}`.trim();
      }
    }
  } catch (err) {
    console.error('PO parse failed:', err);
    if (hint) { hint.style.color = 'var(--red)'; hint.textContent = '✗ ' + err.message; }
    toast('Could not read that PO: ' + err.message, 'error');
  } finally {
    if (btn) btn.disabled = false;
  }
}

// Claude vision call — accepts PDF or image POs. 429 retry once after 30s.
async function _invParsePOFile(file) {
  const base64 = await new Promise((res, rej) => {
    const reader = new FileReader();
    reader.onload = () => res(reader.result.split(',')[1]);
    reader.onerror = () => rej(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
  const isPdf = /pdf$/i.test(file.type) || /\.pdf$/i.test(file.name);
  const mediaBlock = isPdf
    ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64 } }
    : { type: 'image',    source: { type: 'base64', media_type: file.type || 'image/png', data: base64 } };

  const prompt = `This is a PURCHASE ORDER sent TO BAMA Fabrication Ltd by one of its customers. BAMA will now raise a sales invoice against it. Extract the details BAMA needs.

Return ONLY a JSON object, no markdown, no explanation:
{
  "customer": "the company that ISSUED this PO (the letterhead / 'from' company — NOT Bama, Bama is the recipient shown in the deliver-to / supplier block)",
  "po_number": "the purchase order number, e.g. '772', 'PO-4451'",
  "po_date": "YYYY-MM-DD or null",
  "your_order_no": "the 'Your Order No' / supplier reference field if present, else null",
  "lines": [ { "description": "line description", "quantity": number, "unit": "unit text like 'ea'/'m'/'hrs' or empty string", "unit_price": number } ],
  "address_line1": "first line of the ISSUER's own address (street), or null",
  "address_line2": "second street line or building/works name, or null",
  "city": "issuer's town/city or null",
  "county": "issuer's county or null",
  "postcode": "issuer's postcode or null",
  "contact_email": "issuer's email on the PO or null",
  "contact_phone": "issuer's phone on the PO or null",
  "net_total": number or null (the stated total NET / subtotal before VAT),
  "vat_amount": number or null (VAT amount stated on the PO, 0 if none shown),
  "carriage": number or null (delivery/carriage charge, 0 if none)
}

Rules:
- Dates may be DD/MM/YYYY or DD.MM.YYYY — always UK day-first; convert to YYYY-MM-DD.
- Amounts may use comma decimals / space thousands; return plain numbers.
- SKIP zero-value message/comment lines (e.g. product code M1 "Message Line" at 0.00) — but if such a line carries descriptive text and a priced line has a vague description like "Miscellaneous", merge that text into the priced line's description instead.
- Pricing units like "per hundred" / "HUND": convert so quantity × unit_price = the stated line net.
- If carriage is charged, include it as its own line { "description": "Carriage / delivery", ... } as well as in "carriage".
- The address/contact fields are the ISSUER'S OWN details (letterhead / header block) — NOT the deliver-to / supplier block, which is Bama's address. Never return a Bama/Yaxley/Enterprise Way address.
- Copy descriptions as written (trim codes/noise); do NOT invent content.`;

  const _tok = await getToken();
  const call = () => fetch(API_BASE + '/api/claude-proxy', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${_tok}` },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 2000,
      messages: [{ role: 'user', content: [ mediaBlock, { type: 'text', text: prompt } ] }]
    })
  });

  let response = await call();
  if (response.status === 429) {
    const hint = document.getElementById('invPoParseHint');
    if (hint) hint.textContent = '⏳ Rate limited — waiting 30s…';
    await new Promise(r => setTimeout(r, 30000));
    response = await call();
  }
  if (!response.ok) throw new Error(`AI error ${response.status}`);
  const data = await response.json();
  const text = (data.content || []).map(c => c.text || '').join('').trim();
  const clean = text.replace(/^```json\s*/, '').replace(/\s*```$/, '').trim();
  let parsed;
  try { parsed = JSON.parse(clean); }
  catch { throw new Error('AI returned invalid JSON'); }
  if (!parsed || !Array.isArray(parsed.lines) || parsed.lines.length === 0) {
    throw new Error('No line items found on that document');
  }
  return parsed;
}

// Deterministic application of the parsed PO onto the open invoice modal.
// Also keeps the Clients register in sync: unknown customers are SAVED as
// new clients (name + address + contact from the PO), and known clients
// with a missing address get it backfilled — so the next invoice to that
// customer prints a full Bill To without touching the PO again.
async function _invApplyParsedPO(parsed) {
  const _poAddr = {
    address_line1: String(parsed.address_line1 || '').trim() || null,
    address_line2: String(parsed.address_line2 || '').trim() || null,
    city:          String(parsed.city || '').trim() || null,
    county:        String(parsed.county || '').trim() || null,
    postcode:      String(parsed.postcode || '').trim() || null
  };
  const _poHasAddr = !!(_poAddr.address_line1 || _poAddr.postcode);

  // ── Customer: fuzzy match to Clients (applies its VAT treatment + terms);
  //    unknown customer → CREATE it so details are reused next time.
  const name = String(parsed.customer || '').trim();
  if (name) {
    let client = _invImportMatchClient(name);
    if (client && _poHasAddr && !client.address_line1 && !client.postcode) {
      // Known client with no saved address → backfill from the PO
      try {
        const upd = await api.put(`/api/clients/${client.id}`, {
          ..._poAddr,
          contact_email: client.contact_email || String(parsed.contact_email || '').trim() || undefined,
          contact_phone: client.contact_phone || String(parsed.contact_phone || '').trim() || undefined
        });
        Object.assign(client, upd || _poAddr);
        toast(`Client "${client.company_name}" had no address — backfilled from the PO`, 'success');
      } catch (e) { console.warn('Client address backfill failed:', e); }
    }
    if (!client) {
      // Brand-new customer → save to Clients so it's there for next time
      try {
        client = await api.post('/api/clients', {
          company_name: name,
          ..._poAddr,
          contact_email: String(parsed.contact_email || '').trim() || null,
          contact_phone: String(parsed.contact_phone || '').trim() || null,
          vat_treatment: Number(parsed.vat_amount) > 0 ? 'standard' : 'reverse_charge',
          payment_terms_days: 30
        });
        if (client && client.id) {
          _invClientsCache.push(client);
          toast(`New client "${name}" saved to Clients${_poHasAddr ? ' with address' : ''} — review VAT treatment & terms there`, 'success');
        }
      } catch (e) {
        console.warn('Client auto-create failed:', e);
        client = null;
      }
    }
    if (client && client.id) {
      selectInvCustomer(client.id);
      if (!client.address_line1 && !client.postcode) {
        toast('⚠ No address found on the PO or client record — add one before issuing (clients often reject invoices without it)', 'warning');
      }
    } else {
      document.getElementById('invNewCustomerSearch').value = name;
      _invSelectedClient = null;
      document.getElementById('invNewCustomerSelected').textContent = `✓ "${name}" (from PO — could not save to Clients)`;
      document.getElementById('invNewCustomerDropdown').innerHTML = '';
      const treatEl = document.getElementById('invNewVatTreatment');
      if (treatEl && Number(parsed.vat_amount) > 0) treatEl.value = 'standard';
    }
    // Conflict hint: client says reverse charge but the PO adds VAT (or vice versa)
    if (_invSelectedClient) {
      const t = document.getElementById('invNewVatTreatment').value;
      const poHasVat = Number(parsed.vat_amount) > 0;
      const vh = document.getElementById('invNewVatHint');
      if (vh && poHasVat && t === 'reverse_charge') {
        vh.textContent += ' · ⚠ PO shows VAT added but client default is reverse charge — check treatment';
      } else if (vh && !poHasVat && t === 'standard') {
        vh.textContent += ' · ⚠ PO shows no VAT but client default is Standard — check treatment';
      }
    }
  }

  // ── Line items: wholesale replace with the PO's lines
  const lines = (parsed.lines || [])
    .map(l => ({
      description: String(l.description || '').trim(),
      quantity:    Number(l.quantity) > 0 ? Number(l.quantity) : 1,
      unit:        String(l.unit || '').trim(),
      unit_price:  Number(l.unit_price) || 0
    }))
    .filter(l => l.description || l.unit_price);
  if (lines.length) {
    _invLineRows = lines;
    renderInvLineRows();
  }

  // ── Notes: reference the PO so it prints on the invoice PDF
  const poBits = [];
  if (parsed.po_number) poBits.push(`Purchase Order No. ${parsed.po_number}`);
  if (parsed.po_date) {
    const d = new Date(parsed.po_date + 'T00:00:00');
    if (!isNaN(d)) poBits.push(`dated ${d.toLocaleDateString('en-GB')}`);
  }
  if (poBits.length) {
    const notesEl = document.getElementById('invNewNotes');
    const poLine = `As per your ${poBits.join(' ')}`;
    if (notesEl && !String(notesEl.value).includes(poLine)) {
      notesEl.value = (notesEl.value ? notesEl.value.trim() + '\n' : '') + poLine;
    }
  }

  recalcInvoiceTotals();
}

// ── Review grid ───────────────────────────────────────────────────────────
function renderInvImportRows() {
  const el = document.getElementById('invImportRows');
  if (!el) return;
  if (!_invImportRows.length) {
    el.innerHTML = '<div style="padding:14px;color:var(--muted);font-size:13px">No files added yet.</div>';
    return;
  }
  el.innerHTML = _invImportRows.map((r, i) => {
    const border = r.committed ? 'var(--green)' : (r.dup || r.error ? 'var(--red)' : 'var(--border)');
    const dis = r.committed ? 'disabled' : '';
    return `
    <div style="border:1px solid ${border};border-radius:6px;padding:6px;opacity:${r.committed ? '.55' : '1'}">
      <div style="display:grid;grid-template-columns:110px 105px 1fr 95px 85px 85px 95px 130px 90px 30px;gap:6px;align-items:center">
        <input type="text" class="field-input" style="font-family:var(--font-mono);font-size:12px" ${dis}
               value="${escapeHtml(r.ref)}" oninput="_invImportRows[${i}].ref = this.value.toUpperCase(); _invImportFlagDups(); _invImportRefreshMeta(${i})">
        <input type="date" class="field-input" style="font-size:12px" ${dis}
               value="${escapeHtml(r.invoice_date)}" oninput="_invImportRows[${i}].invoice_date = this.value">
        <input type="text" class="field-input" style="font-size:12px" ${dis}
               value="${escapeHtml(r.customer)}"
               oninput="_invImportRows[${i}].customer = this.value; _invImportRows[${i}].client_id = (_invImportMatchClient(this.value) || {}).id || null; _invImportRefreshMeta(${i})">
        <input type="number" step="0.01" class="field-input" style="font-size:12px" ${dis}
               value="${r.net}" oninput="_invImportRows[${i}].net = parseFloat(this.value) || 0">
        <input type="number" step="0.01" class="field-input" style="font-size:12px" ${dis}
               value="${r.vat}" oninput="_invImportRows[${i}].vat = parseFloat(this.value) || 0">
        <input type="number" step="0.01" class="field-input" style="font-size:12px" ${dis}
               value="${r.retention}" oninput="_invImportRows[${i}].retention = parseFloat(this.value) || 0">
        <input type="number" step="0.01" class="field-input" style="font-size:12px" ${dis}
               value="${r.gross}" oninput="_invImportRows[${i}].gross = parseFloat(this.value) || 0">
        <select class="field-input" style="font-size:12px" ${dis}
                onchange="_invImportRows[${i}].treatment = this.value">
          <option value="reverse_charge" ${r.treatment === 'reverse_charge' ? 'selected' : ''}>Reverse charge</option>
          <option value="standard" ${r.treatment === 'standard' ? 'selected' : ''}>Standard VAT</option>
          <option value="zero" ${r.treatment === 'zero' ? 'selected' : ''}>Zero / none</option>
        </select>
        <select class="field-input" style="font-size:12px" ${dis}
                onchange="_invImportRows[${i}].status = this.value">
          <option value="Paid" ${r.status === 'Paid' ? 'selected' : ''}>Paid</option>
          <option value="Issued" ${r.status === 'Issued' ? 'selected' : ''}>Issued</option>
        </select>
        <button class="btn btn-ghost" style="padding:2px 6px;font-size:12px;color:var(--red)" ${dis}
                onclick="_invImportRows.splice(${i},1); _invImportFlagDups(); renderInvImportRows()">×</button>
      </div>
      <div id="invImportMeta${i}" style="font-size:11px;color:var(--muted);margin-top:3px;padding-left:2px">
        ${_invImportMetaText(r)}
      </div>
    </div>`;
  }).join('');
}

function _invImportMetaText(r) {
  const bits = [`📄 ${escapeHtml(r.fileName)}`];
  if (r.committed) bits.push('<span style="color:var(--green)">✓ imported</span>');
  else if (r.error) bits.push(`<span style="color:var(--red)">${escapeHtml(r.error)}</span>`);
  else if (r.dup) bits.push('<span style="color:var(--red)">⚠ ref already exists — will be skipped</span>');
  if (r.client_id) bits.push('<span style="color:var(--green)">✓ matched to Clients</span>');
  else if (r.customer) bits.push('free-text customer');
  return bits.join(' · ');
}
function _invImportRefreshMeta(i) {
  const el = document.getElementById('invImportMeta' + i);
  if (el && _invImportRows[i]) el.innerHTML = _invImportMetaText(_invImportRows[i]);
}

// ── Commit: upload each original PDF, then bulk insert ────────────────────
async function commitInvImport() {
  const rows = _invImportRows.filter(r => !r.committed && !r.dup && r.ref && r.invoice_date);
  if (!rows.length) { toast('Nothing valid to import', 'error'); return; }
  const btn = document.getElementById('invImportCommitBtn');
  const prog = document.getElementById('invImportProgress');
  _invImportBusy = true;
  btn.disabled = true; btn.textContent = 'Importing…';
  try {
    // 1. Upload the original PDFs to SharePoint (sequential, non-fatal per file)
    for (let i = 0; i < rows.length; i++) {
      const r = rows[i];
      prog.textContent = `⏳ Uploading ${r.fileName} (${i + 1}/${rows.length})…`;
      try {
        const folder = await _findOrCreateInvoiceFolder(r.invoice_date);
        const fileName = sanitizeSpFilename(`${r.ref}.pdf`);
        const item = await uploadFileToFolder(folder.id, fileName, r.file, 'application/pdf');
        r.sharepoint_pdf_id = item.id;
        r.sharepoint_pdf_url = item.webUrl;
      } catch (e) {
        console.warn('Import PDF upload failed for', r.ref, e);
        r.sharepoint_pdf_id = null;
        r.sharepoint_pdf_url = null;
      }
    }

    // 2. Bulk insert
    prog.textContent = '⏳ Saving to database…';
    const payload = {
      invoices: rows.map(r => ({
        ref: r.ref,
        invoice_date: r.invoice_date,
        due_date: r.due_date || null,
        client_id: r.client_id,
        customer_text: r.client_id ? null : (r.customer || null),
        vat_applies: r.treatment === 'standard' ? 1 : 0,
        cis_reverse_charge: r.treatment === 'reverse_charge' ? 1 : 0,
        net_amount: r.net,
        vat_amount: r.treatment === 'standard' ? r.vat : 0,
        reverse_charge_amount: r.treatment === 'reverse_charge' ? (r.vat || +(((r.net - r.retention) * 0.2)).toFixed(2)) : 0,
        retention_amount: r.retention || null,
        gross_amount: r.gross,
        status: r.status,
        line_description: r.line_description,
        sharepoint_pdf_id: r.sharepoint_pdf_id,
        sharepoint_pdf_url: r.sharepoint_pdf_url
      }))
    };
    const result = await api.post('/api/invoices-import', payload);

    const insertedRefs = new Set((result.inserted || []).map(x => x.ref));
    for (const r of _invImportRows) {
      if (insertedRefs.has(r.ref)) r.committed = true;
    }
    _invImportFlagDups();
    renderInvImportRows();

    const skippedHtml = (result.skipped || []).length
      ? `<div style="color:var(--red);margin-top:4px">Skipped: ${result.skipped.map(s => `${escapeHtml(s.ref)} (${escapeHtml(s.reason)})`).join(', ')}</div>`
      : '';
    document.getElementById('invImportSummary').innerHTML =
      `<span style="color:var(--green);font-weight:600">✓ Imported ${(result.inserted || []).length} invoice(s)</span>${skippedHtml}`;
    prog.textContent = '';
    toast(`Imported ${(result.inserted || []).length} invoice(s) ✓`, 'success');
    await loadInvoicingData();
    if (typeof renderInvSalesTable === 'function') renderInvSalesTable();
  } catch (err) {
    console.error('Invoice import failed', err);
    toast('Import failed: ' + err.message, 'error');
  } finally {
    _invImportBusy = false;
    btn.disabled = false; btn.textContent = 'Commit Import';
  }
}

// ── Issue from detail (Draft → Issued, generates PDF, uploads to SharePoint) ──
async function issueInvoiceFromDetail() {
  if (!_invDetailCurrent) return;
  const inv = _invDetailCurrent;
  const btn = document.getElementById('invDetailIssueBtn');
  try {
    if (btn) { btn.disabled = true; btn.textContent = 'Issuing…'; }
    setLoading(true);
    await loadLogoDataUri();
    const pdfData = await _buildInvoicePdfData(inv);
    const pdfBlob = await renderBamaInvoicePDF(pdfData);
    const fileName = sanitizeSpFilename(`${inv.ref}.pdf`);
    const folder = await _findOrCreateInvoiceFolder(inv.invoice_date);
    const driveItem = await uploadFileToFolder(folder.id, fileName, pdfBlob, 'application/pdf');
    await api.post(`/api/invoices/${inv.id}/issue`, {
      sharepoint_pdf_id: driveItem.id,
      sharepoint_pdf_url: driveItem.webUrl
    });
    toast(`${inv.kind === 'credit_note' ? 'Credit note' : 'Invoice'} ${inv.ref} issued ✓`, 'success');
    await _invAllocateCreditNote(inv);
    closeInvDetail();
    await loadInvoicingData();
    switchInvTab('sales');
    // Last mile: offer the email straight away with the PDF attached
    const issued = _invInvoiceList.find(x => x.id === inv.id);
    await _openInvoiceEmailComposer(issued ? await api.get(`/api/invoices/${inv.id}`) : inv);
  } catch (err) {
    console.error('Issue failed', err);
    toast('Issue failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    setLoading(false);
    if (btn) { btn.disabled = false; btn.textContent = 'Issue + PDF'; }
  }
}

// ── Credit note allocation: post a "payment" on the parent invoice ────────
// Allocating CN gross against the parent reduces its outstanding via the
// existing payments machinery (status auto-updates to Partially Paid/Paid).
async function _invAllocateCreditNote(cn) {
  if (!cn || cn.kind !== 'credit_note' || !cn.parent_invoice_id) return;
  try {
    await api.post(`/api/invoices/${cn.parent_invoice_id}/payments`, {
      payment_date: new Date().toISOString().slice(0, 10),
      amount: Number(cn.gross_amount || 0),
      method: 'Credit Note',
      reference: cn.ref,
      notes: `Credit note ${cn.ref} allocated`
    });
    toast(`${cn.ref} allocated against parent invoice ✓`, 'success');
  } catch (err) {
    console.error('Credit note allocation failed', err);
    toast(`${cn.ref} issued, but allocation to the parent invoice failed — record it manually via + Record Payment`, 'error');
  }
}

// ── Email the invoice PDF to the client (Graph sendMail via composer) ─────
async function emailInvoiceFromDetail() {
  if (!_invDetailCurrent) return;
  await _openInvoiceEmailComposer(_invDetailCurrent);
}

