async function _openInvoiceEmailComposer(inv, mode) {
  try {
    setLoading(true);
    await loadLogoDataUri();

    // Regenerate the PDF for attachment (deterministic renderer)
    const pdfData = await _buildInvoicePdfData(inv);
    const pdfBlob = await renderBamaInvoicePDF(pdfData);
    const contentBase64 = await new Promise((res, rej) => {
      const r = new FileReader();
      r.onload = () => res(String(r.result).split(',')[1]);
      r.onerror = () => rej(new Error('Failed to encode PDF'));
      r.readAsDataURL(pdfBlob);
    });

    // Recipient: client's contact email from the clients cache
    const client = inv.client_id
      ? (_invClientsCache || []).find(c => c.id === inv.client_id)
      : null;
    const to = (client && client.contact_email) || '';
    const contactName = (client && client.contact_name) || 'Sir/Madam';
    const customer = inv.client_company_name || (client && client.company_name) || inv.customer_text || '';

    const fmt2 = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const dueUk = inv.due_date ? new Date(inv.due_date).toLocaleDateString('en-GB') : 'on receipt';
    const projectLabel = inv.project_number ? `${inv.project_number} — ${inv.project_name || ''}`.trim() : '';
    const vatNote = inv.cis_reverse_charge
      ? `This invoice is subject to the CIS domestic reverse charge \u2014 please account to HMRC for the VAT of \u00a3${fmt2(inv.reverse_charge_amount)} shown.\n\n`
      : '';

    // Chase context: outstanding + days overdue
    const isChase = !!(mode && mode.chase);
    const outstanding = Number(inv.total_outstanding || inv.gross_amount || 0);
    let daysOverdue = 0;
    if (inv.due_date) {
      daysOverdue = Math.floor((Date.now() - new Date(_invToDateStr(inv.due_date) + 'T00:00:00').getTime()) / 86400000);
    }
    const overduePhrase = daysOverdue > 0
      ? `is now ${daysOverdue} day${daysOverdue === 1 ? '' : 's'} overdue (due ${dueUk})`
      : `was due ${dueUk} and remains outstanding`;

    await openBabcockEmailModal({
      templateKey: isChase ? 'emailInvoiceChase' : 'emailInvoiceIssue',
      title: isChase ? `Chase Payment — ${inv.ref}` : `Email Invoice ${inv.ref}`,
      to,
      tokens: {
        invoice_ref: inv.ref || '',
        contact_name: contactName,
        customer_name: customer,
        project_suffix: projectLabel ? ` \u2014 ${projectLabel}` : '',
        project_line: projectLabel ? ` for ${projectLabel}` : '',
        gross_total: `\u00a3${fmt2(inv.gross_amount)}`,
        outstanding_total: `\u00a3${fmt2(outstanding)}`,
        overdue_phrase: overduePhrase,
        due_date: dueUk,
        vat_note: vatNote
      },
      attachment: {
        name: `${inv.ref}.pdf`,
        contentType: 'application/pdf',
        contentBase64
      },
      aiDraft: {
        defaultTone: isChase ? (daysOverdue > 30 ? 'firm' : 'warm') : 'warm',
        context: isChase
          ? `Write a payment chase-up email from BAMA Fabrication Ltd, a structural steel fabrication company in Peterborough, to a client about an unpaid invoice. A copy of the invoice PDF is attached.

Invoice details:
- Reference: ${inv.ref}
- Client contact: ${contactName}${customer ? ' at ' + customer : ''}
${projectLabel ? '- Project: ' + projectLabel : ''}
- Outstanding amount: \u00a3${fmt2(outstanding)}${outstanding < Number(inv.gross_amount || 0) ? ' (partially paid, original \u00a3' + fmt2(inv.gross_amount) + ')' : ''}
- ${daysOverdue > 0 ? 'Now ' + daysOverdue + ' days overdue \u2014 due date was ' + dueUk : 'Due date: ' + dueUk}
- Ask them to use ${inv.ref} as the payment reference.
- Acknowledge payment may have crossed in the post \u2014 ask them to disregard if already settled.
- Invite them to flag any query holding up payment.${daysOverdue > 45 ? '\n- This is significantly overdue: be firmer, request payment or a payment date by return, while remaining professional.' : ''}`
          : `Write a covering email from BAMA Fabrication Ltd, a structural steel fabrication company in Peterborough, to a client. The ${inv.kind === 'credit_note' ? 'credit note' : inv.kind === 'pro_forma' ? 'pro forma invoice' : 'invoice'} PDF is attached to the email.

Document details:
- Reference: ${inv.ref}
- Client contact: ${contactName}${customer ? ' at ' + customer : ''}
${projectLabel ? '- Project: ' + projectLabel : ''}
${inv.kind === 'credit_note' && inv.parent_invoice_ref ? '- This credit note is issued against invoice ' + inv.parent_invoice_ref : ''}
- Amount: \u00a3${fmt2(inv.gross_amount)}${inv.kind === 'credit_note' ? ' credited' : ', due ' + dueUk}
${inv.cis_reverse_charge ? '- CIS domestic reverse charge applies: the customer must account to HMRC for VAT of \u00a3' + fmt2(inv.reverse_charge_amount) + ' — mention this briefly.' : ''}
${inv.kind !== 'credit_note' ? '- Ask them to use ' + inv.ref + ' as the payment reference.' : ''}`
      }
    });
  } catch (err) {
    console.error('Invoice email composer failed', err);
    toast('Could not open email composer: ' + (err.message || 'unknown'), 'error');
  } finally {
    setLoading(false);
  }
}

async function downloadInvoicePdf() {
  if (!_invDetailCurrent) return;
  const inv = _invDetailCurrent;
  try {
    setLoading(true);
    await loadLogoDataUri();
    const pdfData = await _buildInvoicePdfData(inv);
    const pdfBlob = await renderBamaInvoicePDF(pdfData);
    const url = URL.createObjectURL(pdfBlob);
    const a = document.createElement('a');
    a.href = url; a.download = `${inv.ref}.pdf`;
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  } catch (err) {
    toast('PDF generation failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    setLoading(false);
  }
}

// ── Payment recording ──
function openRecordPaymentModal() {
  if (!_invDetailCurrent) return;
  document.getElementById('invPayDate').value = new Date().toISOString().slice(0, 10);
  document.getElementById('invPayAmount').value = Number(_invDetailCurrent.total_outstanding || 0).toFixed(2);
  document.getElementById('invPayMethod').value = 'bank_transfer';
  document.getElementById('invPayRef').value = '';
  document.getElementById('invPayNotes').value = '';
  document.getElementById('invPayRetention').checked = false;
  document.getElementById('invRecordPaymentModal').classList.add('active');
}
function closeRecordPaymentModal() {
  document.getElementById('invRecordPaymentModal').classList.remove('active');
}
async function saveInvPayment() {
  if (!_invDetailCurrent) return;
  const payload = {
    payment_date: document.getElementById('invPayDate').value,
    amount: Number(document.getElementById('invPayAmount').value),
    method: document.getElementById('invPayMethod').value,
    reference: document.getElementById('invPayRef').value || null,
    notes: document.getElementById('invPayNotes').value || null,
    is_retention_release: document.getElementById('invPayRetention').checked ? 1 : 0
  };
  if (!payload.payment_date || !payload.amount || payload.amount <= 0) {
    toast('Enter a valid date and amount', 'error'); return;
  }
  try {
    const payRes = await api.post(`/api/invoices/${_invDetailCurrent.id}/payments`, payload);
    toast('Payment recorded ✓', 'success');
    babcockCascadeToast(payRes && payRes.babcock);
    closeRecordPaymentModal();
    // Refresh detail + list
    await openInvoiceDetail(_invDetailCurrent.id);
    await loadInvoicingData();
  } catch (err) {
    toast('Payment save failed: ' + (err.message || 'unknown'), 'error');
  }
}
async function deleteInvPayment(pid) {
  if (!_invDetailCurrent) return;
  const confirmed = await showConfirmAsync('Delete payment', 'Are you sure you want to remove this payment record?');
  if (!confirmed) return;
  try {
    await api.delete(`/api/invoices/${_invDetailCurrent.id}/payments/${pid}`);
    toast('Payment removed', 'success');
    await openInvoiceDetail(_invDetailCurrent.id);
    await loadInvoicingData();
  } catch (err) {
    toast('Delete failed: ' + (err.message || 'unknown'), 'error');
  }
}

