// ═════════════════════════════════════════════════════════════════════════
// SUPPLIER INVOICES — attach to existing PO + OCR
// ═════════════════════════════════════════════════════════════════════════
async function openAttachSupplierInvoiceModal(preSelectPoId) {
  // Show a picker for un-attached received POs
  try {
    const allPos = await api.get('/api/purchase-orders');
    const pickList = (allPos || []).filter(po =>
      !po.supplier_invoice_received_at && po.status !== 'Cancelled'
    );
    const sel = document.getElementById('invSupInvPoSelect');
    sel.innerHTML = '<option value="">— pick a PO —</option>'
      + pickList.map(po => `<option value="${po.id}"${po.id === preSelectPoId ? ' selected' : ''}>${escapeHtml(po.reference || '')} — ${escapeHtml(po.supplier_name || '')} — £${_invFmt2(po.total_value)}</option>`).join('');
    _invSupInvPo = null;
    _invSupInvFile = null;
    _invSupInvParsed = null;
    document.getElementById('invSupInvFile').value = '';
    document.getElementById('invSupInvOcrStatus').style.display = 'none';
    document.getElementById('invSupInvRef').value = '';
    document.getElementById('invSupInvDate').value = new Date().toISOString().slice(0, 10);
    document.getElementById('invSupInvNet').value = '';
    document.getElementById('invSupInvVat').value = '';
    document.getElementById('invSupInvGross').value = '';
    document.getElementById('invSupInvNotes').value = '';
    document.getElementById('invSupInvModal').classList.add('active');
    // If a PO was pre-selected, trigger the lookup
    if (preSelectPoId) onSupInvPoPicked(preSelectPoId);
  } catch (err) {
    toast('Failed to load POs', 'error');
  }
}

function closeSupInvModal() {
  document.getElementById('invSupInvModal').classList.remove('active');
}

function onSupInvPoPicked(poId) {
  if (!poId) { _invSupInvPo = null; return; }
  // The latest list was just fetched, but to be safe re-look it up from the cache:
  // we don't keep a cache, so fetch detail
  api.get(`/api/purchase-orders/${poId}`).then(po => { _invSupInvPo = po; }).catch(() => {});
}

async function onSupInvFilePicked(file) {
  if (!file) return;
  _invSupInvFile = file;
  const statusEl = document.getElementById('invSupInvOcrStatus');
  statusEl.style.display = '';
  statusEl.style.background = 'var(--bg-darker)';
  statusEl.innerHTML = '<div class="spinner" style="display:inline-block;width:14px;height:14px;vertical-align:middle"></div> Parsing supplier invoice with AI…';

  try {
    const dataUri = await _fileToDataUri(file);
    const isImg = file.type.startsWith('image/');
    const result = await callClaude({
      model: 'claude-sonnet-4-6',
      max_tokens: 800,
      messages: [{
        role: 'user',
        content: [
          isImg
            ? { type: 'image',    source: { type: 'base64', media_type: file.type, data: dataUri.split(',')[1] } }
            : { type: 'document', source: { type: 'base64', media_type: file.type, data: dataUri.split(',')[1] } },
          {
            type: 'text',
            text: `Extract from this UK supplier invoice. Return ONLY JSON, no markdown:
{
  "invoice_ref": "supplier's invoice number",
  "invoice_date": "YYYY-MM-DD",
  "net_amount": 0,
  "vat_amount": 0,
  "gross_amount": 0
}
Set fields to null if unclear.
IMPORTANT: Use the final printed net total and gross total from the invoice — not a goods-only subtotal. If the invoice has no delivery or other extra charges, the printed total is still correct as-is.`
          }
        ]
      }]
    });
    const text = (result.content?.find(b => b.type === 'text')?.text || '').trim();
    const jsonStart = text.indexOf('{'), jsonEnd = text.lastIndexOf('}');
    const parsed = JSON.parse(text.slice(jsonStart, jsonEnd + 1));
    _invSupInvParsed = parsed;

    if (parsed.invoice_ref)  document.getElementById('invSupInvRef').value  = parsed.invoice_ref;
    if (parsed.invoice_date) document.getElementById('invSupInvDate').value = parsed.invoice_date;
    if (parsed.net_amount   != null) document.getElementById('invSupInvNet').value   = parsed.net_amount;
    if (parsed.vat_amount   != null) document.getElementById('invSupInvVat').value   = parsed.vat_amount;
    if (parsed.gross_amount != null) document.getElementById('invSupInvGross').value = parsed.gross_amount;

    statusEl.style.background = 'rgba(62,207,142,.1)';
    statusEl.innerHTML = '✓ Parsed — please review';
  } catch (err) {
    console.error('Supplier invoice OCR failed', err);
    statusEl.style.background = 'rgba(208,2,27,.1)';
    statusEl.innerHTML = `⚠ Could not parse — please fill manually. (${escapeHtml(err.message || 'unknown')})`;
  }
}

async function saveSupplierInvoice() {
  const poId = Number(document.getElementById('invSupInvPoSelect').value);
  if (!poId) { toast('Pick a PO first', 'error'); return; }
  if (!_invSupInvFile) { toast('Upload the supplier invoice file', 'error'); return; }

  const ref = document.getElementById('invSupInvRef').value.trim();
  const date = document.getElementById('invSupInvDate').value;
  const net = Number(document.getElementById('invSupInvNet').value || 0);
  const vat = Number(document.getElementById('invSupInvVat').value || 0);
  const gross = Number(document.getElementById('invSupInvGross').value || 0);

  if (!gross) { toast('Enter the gross amount', 'error'); return; }

  const btn = document.getElementById('invSupInvSaveBtn');
  try {
    if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
    setLoading(true);

    // 1. Upload to SharePoint
    const folder = await _findOrCreateSupplierInvoiceFolder(date);
    const supplierName = (_invSupInvPo && _invSupInvPo.supplier_name) || 'supplier';
    const stamp = supplierName.replace(/\s+/g, '_').slice(0, 30);
    const ext = (_invSupInvFile.name.split('.').pop() || 'pdf').toLowerCase();
    const fileName = sanitizeSpFilename(`${date}_${stamp}_${ref || 'no-ref'}.${ext}`);
    const driveItem = await uploadFileToFolder(folder.id, fileName, _invSupInvFile, _invSupInvFile.type || 'application/octet-stream');

    // 2. Attach to PO via the new endpoint
    await api.post('/api/supplier-invoices', {
      supplier_id:         _invSupInvPo && _invSupInvPo.supplier_id,
      po_id:               poId,
      invoice_ref:         ref || null,
      invoice_date:        date || null,
      net:                 net || null,
      vat:                 vat || null,
      gross:               gross,
      sharepoint_file_id:  driveItem.id,
      sharepoint_file_url: driveItem.webUrl,
      filename:            fileName,
      notes:               document.getElementById('invSupInvNotes').value || null
    });

    toast(`Supplier invoice attached to PO ${(_invSupInvPo && _invSupInvPo.reference) || poId} ✓`, 'success');
    closeSupInvModal();
    await loadInvoicingData();
    switchInvTab('supplier');
  } catch (err) {
    console.error('Save supplier invoice failed', err);
    toast('Save failed: ' + (err.message || 'unknown'), 'error');
  } finally {
    setLoading(false);
    if (btn) { btn.disabled = false; btn.textContent = 'Attach to PO'; }
  }
}

// ═════════════════════════════════════════════════════════════════════════
// AFP PDF RENDERER — same letterhead family as Invoice / Quote PDFs
// Title: "Application for Payment"; banner "FINAL APPLICATION" if is_final;
// 7-column SOV table: # | Description | Contract £ | Prev Cum £ | This App £
//                     | Cum to Date £ | % To Date
// ═════════════════════════════════════════════════════════════════════════

function _buildAfpPdfData(afp) {
  // Zero-value lines stay editable in the modal but are omitted from the PDF
  const lines = (afp.line_items || []).filter(l => Number(l.contract_value || 0) !== 0);
  const bySection = (s) => lines.filter(l => (l.section || 'measured') === s);

  const groupItems = (sectionLines) => {
    const itemNos = [...new Set(sectionLines.map(l => Number(l.item_no || 0)))].sort((a, b) => a - b);
    return itemNos.map(n => {
      const itemLines = sectionLines.filter(l => Number(l.item_no || 0) === n);
      const meta = itemLines[0] || {};
      return {
        itemNo: n,
        itemDescription: meta.item_description || '',
        quoteRef: meta.item_quote_ref || '',
        woNo: meta.item_wo_no || '',
        lines: itemLines.map(l => {
          const cv = Number(l.contract_value || 0);
          const cumPct = Number(l.this_app_pct_complete || 0);
          const cumVal = l.cumulative_value != null ? Number(l.cumulative_value) : cv * cumPct / 100;
          const paid = l.gross_amount_paid != null ? Number(l.gross_amount_paid) : 0;
          return {
            description: l.description || '',
            contractValue: cv,
            cumPct,
            cumValue: cumVal,
            paid,
            outstanding: cumVal - paid
          };
        })
      };
    });
  };

  const sections = {
    measured: groupItems(bySection('measured')),
    variation: groupItems(bySection('variation')),
    materials: groupItems(bySection('materials'))
  };
  const sumSection = (items) => items.reduce((acc, it) => {
    it.lines.forEach(l => {
      acc.value += l.contractValue; acc.cum += l.cumValue;
      acc.paid += l.paid; acc.outstanding += l.outstanding;
    });
    return acc;
  }, { value: 0, cum: 0, paid: 0, outstanding: 0 });
  const sectionTotals = {
    measured: sumSection(sections.measured),
    variation: sumSection(sections.variation),
    materials: sumSection(sections.materials)
  };

  const cumTotal = afp.cumulative_value_net != null
    ? Number(afp.cumulative_value_net)
    : sectionTotals.measured.cum + sectionTotals.variation.cum + sectionTotals.materials.cum;
  const prevCert = afp.previous_certificate_value != null ? Number(afp.previous_certificate_value) : 0;
  const grossVal = Number(afp.applied_value_net != null ? afp.applied_value_net : (cumTotal - prevCert));

  return {
    ref:           afp.ref,
    valuationNo:   afp.application_no,
    submittedDate: afp.submitted_at,
    periodStart:   afp.period_start,
    periodEnd:     afp.period_end,
    isFinal:       !!afp.is_final,
    projectTitle:  `${afp.project_number || ''} — ${afp.project_name || ''}`.replace(/^ — /, ''),
    client:        afp.client_company_name || '',
    contractNo:    afp.contract_no || '',
    notes:         afp.notes || '',
    retentionPct:  afp.retention_pct != null ? Number(afp.retention_pct) : null,
    prevCert, cumTotal, grossVal,
    retention:     Number(afp.applied_retention || 0),
    vat:           Number(afp.applied_vat || 0),
    due:           Number(afp.applied_gross || 0),
    predictedFinal: sectionTotals.measured.value + sectionTotals.variation.value,
    sections, sectionTotals
  };
}

async function renderBamaAfpPDF(d) {
  const JsPDFCtor = await _resolveJsPDF();
  const logo = _logoDataUriCache || '';
  return drawBamaAfpPDF(JsPDFCtor, d, logo);
}

// AFP PDF v2 — landscape A4 mirroring the company's Excel application:
// Page 1 summary (A/B/C/D + Value of Application → Amount Due), then grouped
// SOV pages per section (items with quote refs, sub-lines with cumulative %,
// paid-to-date and outstanding columns).
function drawBamaAfpPDF(jsPDF, d, logoDataUri) {
  const fmtNum = v => Number(v || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const fmtMoney = v => Number(v || 0) === 0 ? '-' : fmtNum(v);
  const fmtDate = s => {
    if (!s) return '';
    const m = String(s).match(/^(\d{4})-(\d{2})-(\d{2})/);
    return m ? `${m[3]}/${m[2]}/${m[1]}` : s;
  };

  const doc = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'landscape' });
  try {
    doc.setProperties({
      title:   `BAMA Application for Payment ${d.ref || ''}`.trim(),
      subject: `Application for Payment for ${d.projectTitle || ''}`,
      author:  'BAMA Fabrication',
      creator: 'BAMA Fabrication ERP'
    });
  } catch (e) { /* */ }

  const pageW = 297, pageH = 210;
  const marginL = 14, marginR = 14, marginT = 12, marginB = 14;
  const usableW = pageW - marginL - marginR;

  const RED = [208, 2, 27], NAVY = [31, 53, 82];
  const TEXT = [34, 34, 34], MUTED = [85, 85, 85];
  const RULE = [212, 212, 212], HEADRULE = [68, 68, 68];
  const ITEMFILL = [238, 242, 247];

  const setText = (rgb) => doc.setTextColor(rgb[0], rgb[1], rgb[2]);
  const setFill = (rgb) => doc.setFillColor(rgb[0], rgb[1], rgb[2]);
  const setDraw = (rgb) => doc.setDrawColor(rgb[0], rgb[1], rgb[2]);

  // ── Shared page header (logo right, project title left) ──
  const drawPageHeader = () => {
    if (logoDataUri) {
      try {
        const props = doc.getImageProperties(logoDataUri);
        const logoW = 46, logoH = logoW * props.height / props.width;
        doc.addImage(logoDataUri, 'PNG', pageW - marginR - logoW, marginT - 3, logoW, logoH, undefined, 'FAST');
      } catch (e) {
        doc.setFont('helvetica', 'bold'); doc.setFontSize(15); setText(RED);
        doc.text('BAMA FABRICATION', pageW - marginR, marginT + 4, { align: 'right' });
      }
    } else {
      doc.setFont('helvetica', 'bold'); doc.setFontSize(15); setText(RED);
      doc.text('BAMA FABRICATION', pageW - marginR, marginT + 4, { align: 'right' });
    }
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(13);
    doc.text(String(d.projectTitle || ''), marginL, marginT + 4);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9); setText(MUTED);
    doc.text(`Valuation No ${d.valuationNo || ''}:  Works carried out up to ${fmtDate(d.periodEnd)}`, marginL, marginT + 10);
    return marginT + 17;
  };

  // ════ PAGE 1 — SUMMARY ════
  let y = drawPageHeader();

  // Meta block
  doc.setFontSize(9); setText(MUTED);
  const meta = [];
  if (d.client)     meta.push(['Client:', d.client]);
  if (d.contractNo) meta.push(['Contract No:', d.contractNo]);
  meta.push(['Date:', d.submittedDate ? fmtDate(d.submittedDate) : 'Draft']);
  meta.push(['AFP Ref:', d.ref || '']);
  for (const [label, value] of meta) {
    setText(MUTED); doc.setFont('helvetica', 'bold');
    doc.text(label, marginL, y);
    setText(TEXT); doc.setFont('helvetica', 'normal');
    doc.text(String(value), marginL + 26, y);
    y += 4.6;
  }
  y += 6;

  // Title
  doc.setFont('helvetica', 'bold'); doc.setFontSize(16); setText(TEXT);
  doc.text('Application for Payment', pageW / 2, y, { align: 'center' });
  if (d.isFinal) {
    y += 7;
    setFill(RED);
    doc.rect(pageW / 2 - 32, y - 4.5, 64, 6.5, 'F');
    setText([255, 255, 255]); doc.setFontSize(10);
    doc.text('FINAL APPLICATION', pageW / 2, y, { align: 'center' });
  }
  y += 14;

  // Summary block — mirrors the Excel exactly
  const sumLabelX = pageW / 2 - 75, sumAmtX = pageW / 2 + 75;
  const sumRow = (letter, label, value, opts = {}) => {
    setText(opts.muted ? MUTED : TEXT);
    doc.setFont('helvetica', opts.bold ? 'bold' : 'normal');
    doc.setFontSize(opts.big ? 12 : 10.5);
    if (letter) { doc.setFont('helvetica', 'bold'); doc.text(letter, sumLabelX - 10, y); doc.setFont('helvetica', opts.bold ? 'bold' : 'normal'); }
    doc.text(label, sumLabelX, y);
    doc.text('£', sumAmtX - 30, y);
    doc.text(fmtMoney(value), sumAmtX, y, { align: 'right' });
    if (opts.underline) {
      setDraw(HEADRULE); doc.setLineWidth(0.3);
      doc.line(sumAmtX - 34, y + 1.2, sumAmtX + 1, y + 1.2);
    }
    y += opts.gap != null ? opts.gap : 7;
  };

  doc.setFont('helvetica', 'bold'); doc.setFontSize(10); setText(MUTED);
  doc.text('CONTRACT SUM — SUMMARY', sumLabelX - 10, y); y += 8;

  sumRow('A.', 'Measured Works',    d.sectionTotals.measured.cum);
  sumRow('B.', 'Variations',        d.sectionTotals.variation.cum);
  sumRow('C.', 'Materials on site', d.sectionTotals.materials.cum);
  sumRow('D.', 'Predicted Final Account', d.predictedFinal, { bold: true, underline: true, gap: 10 });
  sumRow(null, 'Value of Application', d.cumTotal);
  sumRow(null, 'Less Previous Contractor Certificate', d.prevCert, { gap: 10 });
  sumRow(null, 'GROSS Valuation', d.grossVal, { bold: true });
  sumRow(null, `(Less Retention${d.retentionPct != null ? ' @ ' + Number(d.retentionPct) + '%' : ''})`, d.retention, { muted: true });
  if (Number(d.vat) > 0) sumRow(null, 'VAT (20%)', d.vat);
  y += 2;

  // Amount due — navy pill
  setFill(NAVY);
  doc.rect(sumLabelX - 12, y - 5.5, (sumAmtX + 4) - (sumLabelX - 12), 9.5, 'F');
  setText([255, 255, 255]); doc.setFont('helvetica', 'bold'); doc.setFontSize(12);
  doc.text('AMOUNT DUE', sumLabelX - 8, y + 0.5);
  doc.setFontSize(13);
  doc.text('£' + fmtNum(d.due), sumAmtX, y + 0.5, { align: 'right' });
  y += 14;

  // Notes
  if (d.notes && String(d.notes).trim()) {
    setText(TEXT); doc.setFont('helvetica', 'bold'); doc.setFontSize(9.5);
    doc.text('Notes', marginL, y); y += 4.5;
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9); setText(MUTED);
    const wrapped = doc.splitTextToSize(String(d.notes).trim(), usableW - 8);
    wrapped.forEach(line => {
      if (y > pageH - marginB - 8) return;
      doc.text(line, marginL + 4, y); y += 4;
    });
  }

  // ════ SECTION PAGES ════
  // Columns: Item | Description | Quote No | Unit | Value £ | % | Total £ | Paid £ | Outstanding £
  const col = {};
  col.item  = { x: marginL, w: 9,  align: 'center' };
  col.desc  = { w: 118, align: 'left' };
  col.quote = { w: 22,  align: 'left' };
  col.unit  = { w: 10,  align: 'center' };
  col.value = { w: 24,  align: 'right' };
  col.pct   = { w: 12,  align: 'center' };
  col.total = { w: 24,  align: 'right' };
  col.paid  = { w: 24,  align: 'right' };
  col.out   = { w: 24,  align: 'right' };
  col.desc.x  = col.item.x  + col.item.w;
  col.quote.x = col.desc.x  + col.desc.w;
  col.unit.x  = col.quote.x + col.quote.w;
  col.value.x = col.unit.x  + col.unit.w;
  col.pct.x   = col.value.x + col.value.w;
  col.total.x = col.pct.x   + col.pct.w;
  col.paid.x  = col.total.x + col.total.w;
  col.out.x   = col.paid.x  + col.paid.w;
  const tableRightX = col.out.x + col.out.w;

  const drawTableHead = () => {
    doc.setFont('helvetica', 'bold'); doc.setFontSize(8); setText(TEXT);
    doc.text('Item',        col.item.x + col.item.w / 2,  y, { align: 'center' });
    doc.text('Description', col.desc.x + 1,               y);
    doc.text('Quote No',    col.quote.x + 1,              y);
    doc.text('Unit',        col.unit.x + col.unit.w / 2,  y, { align: 'center' });
    doc.text('Value £',     col.value.x + col.value.w - 1, y, { align: 'right' });
    doc.text('% Comp',      col.pct.x + col.pct.w / 2,    y, { align: 'center' });
    doc.text('Total £',     col.total.x + col.total.w - 1, y, { align: 'right' });
    doc.text('Paid £',      col.paid.x + col.paid.w - 1,  y, { align: 'right' });
    doc.text('Outstanding', col.out.x + col.out.w - 1,    y, { align: 'right' });
    y += 1.5;
    setDraw(HEADRULE); doc.setLineWidth(0.4);
    doc.line(marginL, y, tableRightX, y);
    y += 3.5;
  };

  const newSectionPage = (sectionTitle) => {
    doc.addPage();
    y = drawPageHeader();
    doc.setFont('helvetica', 'bold'); doc.setFontSize(11); setText(NAVY);
    doc.text(sectionTitle, marginL, y);
    y += 6;
    drawTableHead();
  };

  const ensureRoom = (rowH, sectionTitle) => {
    if (y + rowH > pageH - marginB - 6) {
      doc.addPage();
      y = drawPageHeader();
      doc.setFont('helvetica', 'bold'); doc.setFontSize(9); setText(MUTED);
      doc.text(sectionTitle + ' (continued)', marginL, y);
      y += 5;
      drawTableHead();
    }
  };

  const sectionDefs = [
    { key: 'measured',  title: 'A.  Measured Works Complete To Date', totalLabel: 'TOTAL Measured Works To Date of Application' },
    { key: 'variation', title: 'B.  Variations / Additions / Extras', totalLabel: 'Total Variations / Additions / Extras' },
    { key: 'materials', title: 'C.  Materials Off Site / Delivered To Site', totalLabel: 'Total Materials' }
  ];

  for (const def of sectionDefs) {
    const items = d.sections[def.key] || [];
    if (!items.length) continue;
    newSectionPage(def.title);

    for (const item of items) {
      // Item header row
      const metaText = String(item.itemDescription || '');
      // Measure with the font it PRINTS in (bold 8.5) — splitting while a
      // smaller/normal font is active under-measures and the printed bold
      // text overflows into the Quote No column.
      doc.setFont('helvetica', 'bold'); doc.setFontSize(8.5);
      const metaLines = doc.splitTextToSize(metaText, col.desc.w - 4);
      const headH = Math.max(6, metaLines.length * 3.6 + 2.5);
      ensureRoom(headH + 5, def.title);

      setFill(ITEMFILL);
      doc.rect(marginL, y - 1, tableRightX - marginL, headH, 'F');
      setText(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(8.5);
      doc.text(String(item.itemNo || ''), col.item.x + col.item.w / 2, y + 2.6, { align: 'center' });
      let metaY = y + 2.6;
      for (const line of metaLines) { doc.text(line, col.desc.x + 1, metaY); metaY += 3.6; }
      doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5); setText(MUTED);
      doc.text(String(item.quoteRef || ''), col.quote.x + 1, y + 2.6);
      if (item.woNo) doc.text(String(item.woNo), col.unit.x + 1, y + 2.6);
      y += headH + 1;

      // Sub-lines
      doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
      for (const l of item.lines) {
        const descLines = doc.splitTextToSize(String(l.description || ''), col.desc.w - 6);
        const rowH = Math.max(4.6, descLines.length * 3.5 + 1.1);
        ensureRoom(rowH, def.title);

        setText(TEXT);
        let dY = y + 3;
        for (const line of descLines) { doc.text(line, col.desc.x + 4, dY); dY += 3.5; }
        doc.text('sum', col.unit.x + col.unit.w / 2, y + 3, { align: 'center' });
        doc.text(fmtNum(l.contractValue), col.value.x + col.value.w - 1, y + 3, { align: 'right' });
        doc.text(Number(l.cumPct || 0).toFixed(0) + '%', col.pct.x + col.pct.w / 2, y + 3, { align: 'center' });
        doc.text(fmtMoney(l.cumValue), col.total.x + col.total.w - 1, y + 3, { align: 'right' });
        doc.text(fmtMoney(l.paid), col.paid.x + col.paid.w - 1, y + 3, { align: 'right' });
        setText(Math.abs(l.outstanding) >= 0.01 ? RED : MUTED);
        doc.text(fmtMoney(l.outstanding), col.out.x + col.out.w - 1, y + 3, { align: 'right' });
        setText(TEXT);

        setDraw(RULE); doc.setLineWidth(0.12);
        doc.line(marginL, y + rowH, tableRightX, y + rowH);
        y += rowH;
      }
      y += 2;
    }

    // Section total row
    const t = d.sectionTotals[def.key];
    ensureRoom(9, def.title);
    setDraw(HEADRULE); doc.setLineWidth(0.4);
    doc.line(marginL, y, tableRightX, y);
    y += 4;
    doc.setFont('helvetica', 'bold'); doc.setFontSize(8.5); setText(TEXT);
    doc.text(def.totalLabel, col.desc.x + 1, y);
    doc.text(fmtNum(t.value), col.value.x + col.value.w - 1, y, { align: 'right' });
    const avgPct = t.value ? (t.cum / t.value * 100) : 0;
    doc.text(avgPct.toFixed(0) + '%', col.pct.x + col.pct.w / 2, y, { align: 'center' });
    doc.text(fmtNum(t.cum), col.total.x + col.total.w - 1, y, { align: 'right' });
    doc.text(fmtNum(t.paid), col.paid.x + col.paid.w - 1, y, { align: 'right' });
    setText(Math.abs(t.outstanding) >= 0.01 ? RED : TEXT);
    doc.text(fmtNum(t.outstanding), col.out.x + col.out.w - 1, y, { align: 'right' });
    setText(TEXT);
    y += 6;
  }

  // ── Page X of Y footer on every page ──
  const pageCount = doc.getNumberOfPages();
  for (let p = 1; p <= pageCount; p++) {
    doc.setPage(p);
    setText(MUTED); doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.text(`${d.ref || 'AFP'} · Page ${p} of ${pageCount}`, pageW - marginR, pageH - 6, { align: 'right' });
    doc.text('BAMA Fabrication Ltd · Company No. 14680571 · VAT Reg No. 435 0591 07 · accounts@bamafabrication.co.uk', marginL, pageH - 6);
  }

  const blob = doc.output('blob');
  console.log(`[AFP PDF] ${d.ref}: ${pageCount} pages, ${(blob.size / 1024).toFixed(1)} KB`);
  return blob;
}


// ═════════════════════════════════════════════════════════════════════════
// BANK RECONCILIATION — page logic (reconcile.html)
// ═════════════════════════════════════════════════════════════════════════
// Commit 1: PIN gate, bank tiles with donut charts, Add/Edit bank modal.
// Commit 2 will add statement upload + transaction table.
// Commit 3 will add document matching.
// ─────────────────────────────────────────────────────────────────────────

let _recBankList        = [];   // loaded from /api/bank-accounts
let _recStmtList        = [];   // statements for selected bank
let _recSelectedBankId  = null; // currently active tile
let _recSelectedStmtId  = null; // currently active statement
let _recTxnList         = [];   // transactions for current statement view
let _recTxnOffset       = 0;    // pagination offset
const REC_TXN_PAGE      = 50;   // rows per page
let _recSelectedTxnIds  = new Set(); // checked rows for bulk clear
let _recClearTargetId   = null; // single-clear target
let _recPendingPinUser  = null;

// ── Init ─────────────────────────────────────────────────────────────────
// initReconcilePage() is called from init() in shared.js when CURRENT_PAGE === 'reconcile'

async function initReconcilePage() {
  // Data already loaded by init() — just build the employee grid
  const grid = document.getElementById('recEmployeeGrid');
  if (grid) {
    const emps = (state.timesheetData.employees || []).filter(e => e.active !== false);
    if (!emps.length) {
      grid.innerHTML = '<div class="empty-state">No employees found</div>';
    } else {
      grid.innerHTML = emps.map(e => `
        <div class="emp-card" onclick="recSelectEmployee('${e.id}')">
          <div class="emp-avatar" style="width:48px;height:48px;font-size:20px;margin:0 auto 8px">
            ${initials(e.name)}
          </div>
          <div style="font-size:13px;font-weight:600;text-align:center">${e.name}</div>
        </div>
      `).join('');
    }
  }

  // If already logged in via another tracker page, skip straight in
  const authed = pinSessionGet();
  if (authed) {
    currentManagerUser = authed;
    enterReconcilePage();
  } else {
    showScreen('screenRecSelect');
  }
}

function recSelectEmployee(empId) {
  const emp = state.timesheetData.employees.find(e => String(e.id) === String(empId));
  if (!emp) return;

  // Check if already authed
  const authed = pinSessionGet();
  if (authed) {
    currentManagerUser = authed;
    enterReconcilePage();
    return;
  }

  _recPendingPinUser = { empId, name: emp.name };
  document.getElementById('recPinUser').textContent = emp.name;
  document.getElementById('recPinInput').value = '';
  document.getElementById('recPinError').textContent = '';
  document.getElementById('recPinModal').classList.add('active');
  setTimeout(() => document.getElementById('recPinInput').focus(), 100);
}

async function verifyRecPin() {
  if (!_recPendingPinUser) return;
  const pin = document.getElementById('recPinInput').value.trim();
  if (!pin) { document.getElementById('recPinError').textContent = 'Enter your PIN'; return; }

  try {
    const res = await api.post('/api/auth/verify-pin', { employee_id: _recPendingPinUser.empId, pin });
    if (!res.valid) { document.getElementById('recPinError').textContent = 'Incorrect PIN'; return; }
  } catch {
    document.getElementById('recPinError').textContent = 'Could not verify PIN';
    return;
  }

  currentManagerUser = _recPendingPinUser.name;
  pinSessionSet(currentManagerUser);

  // Bootstrap: if nobody has reconcile perm yet, grant it to the first login
  await loadUserAccessData();
  const hasAny = Object.values(userAccessData.users || {})
    .some(u => u.permissions && u.permissions.reconcile);
  if (!hasAny) {
    await api.put(`/api/user-access/${_recPendingPinUser.empId}`, { reconcile: true });
    if (userAccessData.users[currentManagerUser]) {
      userAccessData.users[currentManagerUser].permissions.reconcile = true;
    }
    toast('Bootstrap: reconcile permission granted to ' + currentManagerUser, 'success');
  }

  document.getElementById('recPinModal').classList.remove('active');
  enterReconcilePage();
}

async function enterReconcilePage() {
  await loadUserAccessData();
  const perms = getUserPermissions(currentManagerUser) || {};
  if (!perms.reconcile) {
    document.getElementById('recPinError').textContent = 'You do not have reconcile permission';
    document.getElementById('recPinModal').classList.add('active');
    return;
  }

  updateRecSidebar();
  document.getElementById('screenRecSelect').classList.remove('active');
  document.getElementById('recLayout').style.display = '';

  await loadRecBanks();
}

function updateRecSidebar() {
  const perms = getUserPermissions(currentManagerUser) || {};
  const set = (id, show, label) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.style.display = show ? '' : 'none';
    if (!show) el.title = `No ${label} permission`;
  };
  set('sidebarBtnEstimatingDashboard', !!perms.estimatingDashboard,               'Estimating Dashboard');
  set('sidebarBtnBabcockQuotes',  true,                                            'Babcock');
  set('sidebarBtnProjectTracker', !!(perms.viewProjects || perms.editProjects),    'Projects');
  set('sidebarBtnPurchaseOrders', !!(perms.viewPurchaseOrders || perms.editPurchaseOrders), 'POs');
  set('sidebarBtnInvoicing',      !!perms.invoicing,                               'Invoicing');
}

// ── Load + render bank tiles ───────────────────────────────────────────────
async function loadRecBanks() {
  try {
    const res = await api.get('/api/bank-accounts');
    console.log('[Reconcile] loadRecBanks response:', res);
    _recBankList = Array.isArray(res) ? res : [];
    console.log('[Reconcile] _recBankList length:', _recBankList.length);
    renderRecTiles();
  } catch (err) {
    console.error('[Reconcile] loadRecBanks error:', err);
    toast('Failed to load bank accounts: ' + err.message, 'error');
  }
}

function renderRecTiles() {
  const grid = document.getElementById('recTilesGrid');
  if (!grid) return;

  if (!_recBankList.length) {
    grid.innerHTML = `
      <div class="empty-state" style="grid-column:1/-1;padding:40px">
        <div style="font-size:32px;margin-bottom:10px">🏦</div>
        <div>No bank accounts yet</div>
        <div style="margin-top:8px;font-size:12px;color:var(--subtle)">Click "+ Add Bank" to get started</div>
      </div>`;
    return;
  }

  grid.innerHTML = _recBankList.map(bank => {
    const total    = Number(bank.total_transactions) || 0;
    const resolved = Number(bank.resolved_transactions) || 0;
    const unmatched= Number(bank.unmatched_transactions) || 0;
    const isActive = _recSelectedBankId === bank.id;

    const typeLabel = { current: 'Current', savings: 'Savings', credit_card: 'Credit Card' }[bank.account_type] || bank.account_type;
    const metaParts = [bank.sort_code, bank.account_number].filter(Boolean);

    return `
      <div class="rec-bank-tile${isActive ? ' active' : ''}" onclick="selectRecBank(${bank.id})">
        <span class="tile-type ${bank.account_type}">${typeLabel}</span>
        <div class="tile-name">${escapeHtml(bank.bank_name)}</div>
        <div class="tile-meta">${metaParts.length ? metaParts.join(' · ') : 'No account details'}</div>
        ${buildRecDonut(total, resolved, unmatched)}
      </div>`;
  }).join('');
}

function buildRecDonut(total, resolved, unmatched) {
  const cleared  = total - resolved - unmatched;
  const matched  = resolved - cleared;
  const r = 20;
  const circ = 2 * Math.PI * r; // ~125.7

  let matchedArc = 0, clearedArc = 0, unmatchedArc = 0;
  if (total > 0) {
    matchedArc  = (matched  / total) * circ;
    clearedArc  = (cleared  / total) * circ;
    unmatchedArc= (unmatched/ total) * circ;
  }

  const pct = total > 0 ? Math.round((resolved / total) * 100) : 0;

  // Build the three arcs: matched (green), cleared (grey), unmatched (amber)
  // Each arc starts where the previous one ended
  let offset = circ / 4; // start at top (12 o'clock)

  const matchedDash  = `${matchedArc.toFixed(1)} ${(circ - matchedArc).toFixed(1)}`;
  const matchedOff   = -offset.toFixed(1);
  offset += matchedArc;

  const clearedDash  = `${clearedArc.toFixed(1)} ${(circ - clearedArc).toFixed(1)}`;
  const clearedOff   = -(offset).toFixed(1);
  offset += clearedArc;

  const unmatchedDash= `${unmatchedArc.toFixed(1)} ${(circ - unmatchedArc).toFixed(1)}`;
  const unmatchedOff = -(offset).toFixed(1);

  const cx = 26, cy = 26, size = 52;
  const stroke = 7;

  return `
    <div class="donut-row">
      <svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
        <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--border)" stroke-width="${stroke}"/>
        ${matchedArc > 0 ? `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--green)"
          stroke-width="${stroke}" stroke-dasharray="${matchedDash}" stroke-dashoffset="${matchedOff}"/>` : ''}
        ${clearedArc > 0 ? `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--muted)"
          stroke-width="${stroke}" stroke-dasharray="${clearedDash}" stroke-dashoffset="${clearedOff}"/>` : ''}
        ${unmatchedArc > 0 ? `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--warn)"
          stroke-width="${stroke}" stroke-dasharray="${unmatchedDash}" stroke-dashoffset="${unmatchedOff}"/>` : ''}
        <text x="${cx}" y="${cy + 4}" text-anchor="middle" font-size="10" font-weight="600"
              fill="var(--text)">${pct}%</text>
      </svg>
      <div class="donut-legend">
        <div class="dl-row"><span class="dl-dot dl-green"></span>Matched<span class="dl-cnt">${matched}</span></div>
        <div class="dl-row"><span class="dl-dot dl-grey"></span>Cleared<span class="dl-cnt">${cleared}</span></div>
        <div class="dl-row"><span class="dl-dot dl-amber"></span>Unmatched<span class="dl-cnt">${unmatched}</span></div>
      </div>
    </div>`;
}

// ── Select bank tile → show two-pane ─────────────────────────────────────
async function selectRecBank(bankId) {
  _recSelectedBankId = bankId;
  _recSelectedStmtId = null;
  _recTxnList = [];
  _recSelectedTxnIds.clear();
  renderRecTiles();

  const bank = _recBankList.find(b => b.id === bankId);
  if (!bank) return;

  document.getElementById('recTwoPane').style.display = '';
  document.getElementById('recStmtPaneTitle').textContent = `${bank.bank_name} — statements`;
  document.getElementById('recTxnPaneTitle').textContent = 'Transactions';
  document.getElementById('recTxnPaneCount').textContent = '';
  document.getElementById('recEditBankBtn').style.display = '';

  // Clear transaction table
  document.getElementById('recTxnTableWrap').innerHTML =
    '<div class="rec-empty"><div class="rec-empty-icon">💳</div>Select a statement to view transactions</div>';
  document.getElementById('recShowMore').style.display = 'none';

  // Load statements from API
  await loadRecStatements(bankId);
}

async function loadRecStatements(bankAccountId) {
  const el = document.getElementById('recStmtList');
  try {
    const res = await api.get(`/api/bank-statements?bank_account_id=${bankAccountId}`);
    _recStmtList = Array.isArray(res) ? res : [];
    renderRecStmtList();
  } catch (err) {
    if (el) el.innerHTML = '<div class="rec-empty" style="color:var(--red)">Failed to load statements</div>';
  }
}

function renderRecStmtList() {
  const el = document.getElementById('recStmtList');
  if (!el) return;
  const bank = _recBankList.find(b => b.id === _recSelectedBankId);
  if (!_recStmtList.length) {
    el.innerHTML = '<div class="rec-empty"><div class="rec-empty-icon">📄</div>No statements yet<br><span style="font-size:11px">Click Upload to add one</span></div>';
    return;
  }
  el.innerHTML = _recStmtList.map(s => {
    const unmatched = (s.total_transactions || 0) - (s.matched_count || 0);
    const label = s.date_from && s.date_to
      ? `${_fmtRecDate(s.date_from)} – ${_fmtRecDate(s.date_to)}`
      : escapeHtml(s.filename || 'Statement');
    return `
      <div class="stmt-row${_recSelectedStmtId === s.id ? ' active' : ''}" onclick="selectRecStmt(${s.id})">
        <div style="display:flex;align-items:center;justify-content:space-between">
          <div class="sr-name">${label}</div>
          <button class="row-icon-btn" style="font-size:12px;color:var(--red)" title="Delete statement"
                  onclick="event.stopPropagation();deleteRecStatement(${s.id})">🗑</button>
        </div>
        <div class="sr-meta">${s.total_transactions} txns · ${s.matched_count} matched · ${unmatched} unmatched</div>
      </div>`;
  }).join('');
}

async function selectRecStmt(stmtId) {
  _recSelectedStmtId = stmtId;
  _recTxnOffset = 0;
  _recSelectedTxnIds.clear();
  clearRecSelection();

  const stmt = _recStmtList.find(s => s.id === stmtId);
  if (stmt) {
    document.getElementById('recTxnPaneTitle').textContent =
      `${stmt.date_from ? _fmtRecDate(stmt.date_from) + ' – ' + _fmtRecDate(stmt.date_to) : escapeHtml(stmt.filename)}`;
  }

  renderRecStmtList(); // re-render to update active state

  // Load transactions
  document.getElementById('recTxnTableWrap').innerHTML =
    '<div class="rec-empty"><div class="spinner"></div></div>';
  try {
    const res = await api.get(`/api/bank-transactions?bank_account_id=${_recSelectedBankId}&statement_id=${stmtId}`);
    _recTxnList = Array.isArray(res) ? res : [];
    _recTxnOffset = 0;
    renderRecTxnTable();
  } catch (err) {
    document.getElementById('recTxnTableWrap').innerHTML =
      `<div class="rec-empty" style="color:var(--red)">Failed to load transactions: ${escapeHtml(err.message)}</div>`;
  }
}

async function deleteRecStatement(stmtId) {
  const stmt = _recStmtList.find(s => s.id === stmtId);
  if (!stmt) return;
  const label = stmt.date_from ? `${_fmtRecDate(stmt.date_from)} – ${_fmtRecDate(stmt.date_to)}` : stmt.filename;
  if (!await showConfirmAsync(`Delete statement "${label}" and all its transactions?`, 'Delete')) return;
  try {
    await api.delete(`/api/bank-statements/${stmtId}`);
    if (_recSelectedStmtId === stmtId) {
      _recSelectedStmtId = null;
      _recTxnList = [];
      renderRecTxnTable();
    }
    toast('Statement deleted', 'success');
    await loadRecStatements(_recSelectedBankId);
    await refreshRecTileStats();
  } catch (err) {
    toast('Delete failed: ' + err.message, 'error');
  }
}

function _fmtRecDate(d) {
  if (!d) return '';
  const s = String(d).split('T')[0];
  const [y, m, day] = s.split('-');
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return `${parseInt(day, 10)} ${months[parseInt(m, 10) - 1]} ${y}`;
}

// ── Transaction table ─────────────────────────────────────────────────────
function renderRecTxnTable() {
  const wrap = document.getElementById('recTxnTableWrap');
  if (!_recTxnList.length) {
    wrap.innerHTML = '<div class="rec-empty"><div class="rec-empty-icon">💳</div>No transactions to show</div>';
    document.getElementById('recShowMore').style.display = 'none';
    return;
  }

  const search = (document.getElementById('recTxnSearch')?.value || '').toLowerCase().trim();
  const statusFilter = document.getElementById('recTxnStatusFilter')?.value || '';

  let filtered = _recTxnList.filter(t => {
    if (statusFilter && t.status !== statusFilter) return false;
    if (search) {
      const haystack = [t.transaction_date, t.description, String(t.amount), t.reference, t.cardholder]
        .filter(Boolean).join(' ').toLowerCase();
      if (!haystack.includes(search)) return false;
    }
    return true;
  });

  // Newest first (already sorted from API — just slice for pagination)
  const page = filtered.slice(0, _recTxnOffset + REC_TXN_PAGE);
  const hasMore = filtered.length > page.length;

  const bank = _recBankList.find(b => b.id === _recSelectedBankId);
  const isCreditCard = bank?.account_type === 'credit_card';

  document.getElementById('recTxnPaneCount').textContent = `${filtered.length} transaction${filtered.length !== 1 ? 's' : ''}`;
  document.getElementById('recShowMore').style.display = hasMore ? '' : 'none';

  wrap.innerHTML = `
    <table class="rec-txn-table">
      <thead>
        <tr>
          <th style="width:32px"><input type="checkbox" class="rec-cb" id="recSelectAll" onchange="toggleRecSelectAll(this.checked)"></th>
          <th onclick="sortRecTxns('transaction_date')" data-col="transaction_date">Date <span class="sort-arrow">↕</span></th>
          <th onclick="sortRecTxns('description')" data-col="description">Description <span class="sort-arrow">↕</span></th>
          ${isCreditCard ? '<th onclick="sortRecTxns(\'cardholder\')" data-col="cardholder">Cardholder <span class="sort-arrow">↕</span></th>' : ''}
          <th onclick="sortRecTxns('amount')" data-col="amount" style="text-align:right">Amount <span class="sort-arrow">↕</span></th>
          <th onclick="sortRecTxns('status')" data-col="status">Status <span class="sort-arrow">↕</span></th>
          <th style="width:90px"></th>
        </tr>
      </thead>
      <tbody>
        ${page.map(t => buildRecTxnRow(t, isCreditCard)).join('')}
      </tbody>
    </table>`;

  updateRecBulkToolbar();
}

function buildRecTxnRow(t, isCreditCard) {
  const isCredit = Number(t.amount) >= 0;
  const amtClass = isCredit ? 'amt-credit' : 'amt-debit';
  const amtStr   = (isCredit ? '+' : '') + '£' + Math.abs(Number(t.amount)).toLocaleString('en-GB', { minimumFractionDigits: 2 });
  const fxLine   = (t.original_currency && t.original_currency.trim() && t.original_currency.trim() !== 'GBP')
    ? `<div class="amt-fx">${t.original_currency} ${Number(t.original_amount).toLocaleString('en-GB', { minimumFractionDigits: 2 })}</div>`
    : '';

  const pillMap = {
    matched:      '<span class="status-pill pill-matched">✓ Matched</span>',
    manual_match: '<span class="status-pill pill-manual">Manual</span>',
    cleared:      `<span class="status-pill pill-cleared" title="${escapeHtml(t.clear_reason || '')}">Cleared</span>`,
    unmatched:    '<span class="status-pill pill-unmatched">Unmatched</span>'
  };
  const pill = pillMap[t.status] || pillMap.unmatched;

  const hasDoc = t.doc_count > 0;
  const previewBtn = `<button class="row-icon-btn${hasDoc ? '' : ' dimmed'}" title="${hasDoc ? 'View document' : 'No document attached'}"
    onclick="${hasDoc ? `previewRecTxnDoc(${t.id})` : ''}">📎</button>`;
  const editBtn = `<button class="row-icon-btn" title="Edit transaction" onclick="openRecTxnEdit(${t.id})">✏️</button>`;

  const actionCell = t.status === 'unmatched'
    ? `<div class="row-actions">${previewBtn}${editBtn}<button class="attach-btn" onclick="openRecClearModal(${t.id})">Clear</button></div>`
    : `<div class="row-actions">${previewBtn}${editBtn}</div>`;

  const checked = _recSelectedTxnIds.has(t.id);

  return `
    <tr class="${t.status === 'matched' || t.status === 'manual_match' ? 'row-matched' : ''}" data-txn-id="${t.id}">
      <td><input type="checkbox" class="rec-cb rec-row-cb" data-id="${t.id}"
          ${checked ? 'checked' : ''} onchange="toggleRecRowSelect(${t.id}, this.checked)"></td>
      <td>${escapeHtml(t.transaction_date || '')}</td>
      <td>
        <div style="font-size:12px">${escapeHtml(t.description || '')}</div>
        ${t.reference ? `<div style="font-size:10px;color:var(--subtle)">${escapeHtml(t.reference)}</div>` : ''}
        ${t.spending_category ? `<div style="font-size:10px;color:var(--muted)">${escapeHtml(t.spending_category)}</div>` : ''}
      </td>
      ${isCreditCard ? `<td style="font-size:11px;color:var(--muted)">${escapeHtml(t.cardholder || '—')}</td>` : ''}
      <td style="text-align:right">
        <div class="${amtClass}">${amtStr}</div>${fxLine}
      </td>
      <td>${pill}</td>
      <td>${actionCell}</td>
    </tr>`;
}

// ── Sorting ───────────────────────────────────────────────────────────────
let _recSortCol = 'transaction_date';
let _recSortDir = 'desc';

function sortRecTxns(col) {
  if (_recSortCol === col) {
    _recSortDir = _recSortDir === 'asc' ? 'desc' : 'asc';
  } else {
    _recSortCol = col;
    _recSortDir = col === 'transaction_date' ? 'desc' : 'asc';
  }
  _recTxnList.sort((a, b) => {
    let va = a[col] ?? '', vb = b[col] ?? '';
    if (col === 'amount') { va = Number(va); vb = Number(vb); }
    if (va < vb) return _recSortDir === 'asc' ? -1 : 1;
    if (va > vb) return _recSortDir === 'asc' ? 1 : -1;
    return 0;
  });
  renderRecTxnTable();

  // Update sort arrows
  document.querySelectorAll('.rec-txn-table th[data-col]').forEach(th => {
    th.classList.toggle('sorted', th.dataset.col === col);
    const arrow = th.querySelector('.sort-arrow');
    if (arrow) arrow.textContent = th.dataset.col === col ? (_recSortDir === 'asc' ? '↑' : '↓') : '↕';
  });
}

// ── Search ────────────────────────────────────────────────────────────────
function onRecTxnSearch(val) {
  document.getElementById('recTxnSearchClear').style.display = val ? '' : 'none';
  _recTxnOffset = 0;
  renderRecTxnTable();
}
function clearRecTxnSearch() {
  document.getElementById('recTxnSearch').value = '';
  document.getElementById('recTxnSearchClear').style.display = 'none';
  _recTxnOffset = 0;
  renderRecTxnTable();
}

// ── Pagination ────────────────────────────────────────────────────────────
function recLoadMoreTxns() {
  _recTxnOffset += REC_TXN_PAGE;
  renderRecTxnTable();
}

// ── Checkbox / bulk select ─────────────────────────────────────────────────
function toggleRecRowSelect(id, checked) {
  if (checked) _recSelectedTxnIds.add(id);
  else _recSelectedTxnIds.delete(id);
  updateRecBulkToolbar();
}
function toggleRecSelectAll(checked) {
  document.querySelectorAll('.rec-row-cb').forEach(cb => {
    const id = Number(cb.dataset.id);
    cb.checked = checked;
    if (checked) _recSelectedTxnIds.add(id);
    else _recSelectedTxnIds.delete(id);
  });
  updateRecBulkToolbar();
}
function clearRecSelection() {
  _recSelectedTxnIds.clear();
  document.querySelectorAll('.rec-row-cb').forEach(cb => cb.checked = false);
  const sa = document.getElementById('recSelectAll');
  if (sa) sa.checked = false;
  updateRecBulkToolbar();
}
function updateRecBulkToolbar() {
  const toolbar = document.getElementById('recBulkToolbar');
  const cnt     = document.getElementById('recBulkCount');
  if (!toolbar) return;
  const n = _recSelectedTxnIds.size;
  toolbar.style.display = n > 0 ? '' : 'none';
  if (cnt) cnt.textContent = `${n} selected`;
}

// ── Single clear modal ─────────────────────────────────────────────────────
function openRecClearModal(txnId) {
  const txn = _recTxnList.find(t => t.id === txnId);
  if (!txn) return;
  _recClearTargetId = txnId;
  document.getElementById('recClearTxnInfo').textContent =
    `${txn.transaction_date}  ·  ${txn.description}  ·  £${Math.abs(txn.amount).toFixed(2)}`;
  document.getElementById('recClearReason').value = '';
  document.getElementById('recClearModal').classList.add('active');
  setTimeout(() => document.getElementById('recClearReason').focus(), 100);
}

async function confirmClearTxn() {
  if (!_recClearTargetId) return;
  const reason = document.getElementById('recClearReason').value.trim();
  try {
    await api.put(`/api/bank-transactions/${_recClearTargetId}/match`, {
      status: 'cleared',
      clear_reason: reason || null,
      matched_by: currentManagerUser
    });
    const txn = _recTxnList.find(t => t.id === _recClearTargetId);
    if (txn) { txn.status = 'cleared'; txn.clear_reason = reason; }
    document.getElementById('recClearModal').classList.remove('active');
    _recClearTargetId = null;
    renderRecTxnTable();
    await refreshRecTileStats();
    toast('Transaction cleared', 'success');
  } catch (err) {
    toast('Clear failed: ' + err.message, 'error');
  }
}

// ── Bulk clear modal ───────────────────────────────────────────────────────
function openBulkClearModal() {
  const ids = [..._recSelectedTxnIds];
  if (!ids.length) return;
  const txns = _recTxnList.filter(t => ids.includes(t.id));
  document.getElementById('recBulkClearCount').textContent =
    `${txns.length} transaction${txns.length !== 1 ? 's' : ''} selected`;
  document.getElementById('recBulkClearReason').value = '';
  document.getElementById('recBulkClearList').innerHTML = txns.map(t => `
    <label style="display:flex;align-items:center;gap:8px;font-size:12px;padding:4px 0">
      <input type="checkbox" class="rec-cb bulk-clear-cb" data-id="${t.id}" checked>
      <span style="flex:1">${escapeHtml(t.description)}</span>
      <span style="color:var(--muted);font-family:var(--font-mono)">£${Math.abs(Number(t.amount)).toFixed(2)}</span>
      <span style="color:var(--muted)">${t.transaction_date}</span>
    </label>`).join('');
  document.getElementById('recBulkClearModal').classList.add('active');
}

async function confirmBulkClear() {
  const checked = [...document.querySelectorAll('.bulk-clear-cb:checked')].map(cb => Number(cb.dataset.id));
  if (!checked.length) { toast('No transactions selected', 'error'); return; }
  const reason = document.getElementById('recBulkClearReason').value.trim();

  let cleared = 0;
  for (const id of checked) {
    try {
      await api.put(`/api/bank-transactions/${id}/match`, {
        status: 'cleared', clear_reason: reason || null, matched_by: currentManagerUser
      });
      const txn = _recTxnList.find(t => t.id === id);
      if (txn) { txn.status = 'cleared'; txn.clear_reason = reason; }
      cleared++;
    } catch { /* continue */ }
  }

  _recSelectedTxnIds.clear();
  document.getElementById('recBulkClearModal').classList.remove('active');
  renderRecTxnTable();
  await refreshRecTileStats();
  toast(`${cleared} transaction${cleared !== 1 ? 's' : ''} cleared`, 'success');
}

// ── Tile stats refresh ─────────────────────────────────────────────────────
async function refreshRecTileStats() {
  try {
    _recBankList = await api.get('/api/bank-accounts');
    renderRecTiles();
  } catch { /* silently ignore */ }
}

// ── Add / Edit bank modal ─────────────────────────────────────────────────
function openAddBankModal() {
  document.getElementById('recBankModalTitle').textContent = '🏦 Add Bank Account';
  document.getElementById('recBankEditId').value = '';
  document.getElementById('recBankName').value = '';
  document.getElementById('recBankAcctNo').value = '';
  document.getElementById('recBankSortCode').value = '';
  document.getElementById('recBankType').value = 'current';
  document.getElementById('recBankModal').classList.add('active');
  setTimeout(() => document.getElementById('recBankName').focus(), 100);
}

function openEditBankModal() {
  const bank = _recBankList.find(b => b.id === _recSelectedBankId);
  if (!bank) return;
  document.getElementById('recBankModalTitle').textContent = '✏️ Edit Bank Account';
  document.getElementById('recBankEditId').value = bank.id;
  document.getElementById('recBankName').value = bank.bank_name;
  document.getElementById('recBankAcctNo').value = bank.account_number || '';
  document.getElementById('recBankSortCode').value = bank.sort_code || '';
  document.getElementById('recBankType').value = bank.account_type || 'current';
  document.getElementById('recBankModal').classList.add('active');
  setTimeout(() => document.getElementById('recBankName').focus(), 100);
}

function closeRecBankModal() {
  document.getElementById('recBankModal').classList.remove('active');
}

async function saveRecBank() {
  const name     = document.getElementById('recBankName').value.trim();
  const acctNo   = document.getElementById('recBankAcctNo').value.trim();
  const sortCode = document.getElementById('recBankSortCode').value.trim();
  const type     = document.getElementById('recBankType').value;
  const editId   = document.getElementById('recBankEditId').value;

  if (!name) { toast('Bank name is required', 'error'); return; }

  const btn = document.getElementById('recBankSaveBtn');
  btn.disabled = true; btn.textContent = 'Saving…';

  try {
    const payload = { bank_name: name, account_number: acctNo || null, sort_code: sortCode || null, account_type: type };
    if (editId) {
      const updated = await api.put(`/api/bank-accounts/${editId}`, payload);
      // Patch local list immediately
      const idx = _recBankList.findIndex(b => String(b.id) === String(editId));
      if (idx >= 0 && updated && updated.id) _recBankList[idx] = { ..._recBankList[idx], ...updated };
      renderRecTiles();
      toast('Bank account updated', 'success');
    } else {
      const saved = await api.post('/api/bank-accounts', payload);
      console.log('[Reconcile] saveRecBank POST response:', saved);
      // Add to local list immediately so tile appears without waiting for GET
      if (saved && saved.id) {
        _recBankList.push({ ...saved, total_transactions: 0, resolved_transactions: 0, unmatched_transactions: 0 });
      }
      renderRecTiles();
      toast('Bank account added', 'success');
    }
    closeRecBankModal();
    // Refresh from server in background to get accurate stats
    loadRecBanks();
  } catch (err) {
    toast('Save failed: ' + err.message, 'error');
  } finally {
    btn.disabled = false; btn.textContent = 'Save';
  }
}

// ── Drag-and-drop (fully wired) ───────────────────────────────────────────
function onRecDragOver(e)  { e.preventDefault(); document.getElementById('recDropZone').classList.add('drag-over'); }
function onRecDragLeave(e) { document.getElementById('recDropZone').classList.remove('drag-over'); }
function onRecDrop(e) {
  e.preventDefault();
  document.getElementById('recDropZone').classList.remove('drag-over');
  const file = e.dataTransfer?.files?.[0];
  if (file) onRecDocFilePicked(file);
}

let _recPendingDocFile  = null;   // file staged for matching
let _recPendingDocParsed = null;  // Claude/parsed result for staged file
let _recManualMatchTxnList = [];  // unmatched transactions for manual picker
let _recPreviewTxnId = null;      // transaction open in preview modal

async function onRecDocFilePicked(file) {
  if (!file) return;
  if (!_recSelectedBankId) { toast('Select a bank account first', 'error'); return; }

  _recPendingDocFile = file;
  _recPendingDocParsed = null;

  const banner = document.getElementById('recMatchBanner');
  banner.style.display = '';
  banner.className = 'rec-match-banner';
  banner.style.background = 'var(--bg-darker)';
  banner.style.border = '1px solid var(--border)';
  banner.style.color = 'var(--muted)';
  banner.innerHTML = `⏳ Reading <strong>${escapeHtml(file.name)}</strong>…`;

  try {
    // Parse the document via Claude
    const parsed = await _parseRecDocument(file);
    _recPendingDocParsed = parsed;

    if (parsed.multiple && parsed.receipts && parsed.receipts.length > 1) {
      // Multiple receipts — show review step
      _showMultiReceiptReview(parsed.receipts, file);
      return;
    }

    // Single receipt — attempt auto-match
    const receipt = parsed.receipts ? parsed.receipts[0] : parsed;
    await _attemptRecAutoMatch(receipt, file);

  } catch (err) {
    banner.className = 'rec-match-banner warn';
    banner.innerHTML = `✗ Failed to read document: ${escapeHtml(err.message)}`;
  }
}

// ── Claude document parser ────────────────────────────────────────────────
async function _parseRecDocument(file) {
  const base64 = await new Promise((res, rej) => {
    const reader = new FileReader();
    reader.onload = () => res(reader.result.split(',')[1]);
    reader.onerror = () => rej(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });

  const isImage = file.type.startsWith('image/');
  const isPdf   = file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf');
  const mediaType = isImage ? (file.type || 'image/jpeg') : 'application/pdf';
  const contentType = isImage ? 'image' : 'document';

  const response = await fetch('/api/claude-proxy', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${await getToken()}` },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 2000,
      messages: [{
        role: 'user',
        content: [
          { type: contentType, source: { type: 'base64', media_type: mediaType, data: base64 } },
          { type: 'text', text: `Analyse this document. It may contain one or multiple receipts/invoices.

Return ONLY a JSON object with no markdown, no explanation:
{
  "multiple": true/false,
  "receipts": [
    {
      "supplier": "string",
      "date": "YYYY-MM-DD or null",
      "total": number or null,
      "net": number or null,
      "vat": number or null,
      "vat_number": "string or null",
      "currency": "GBP"
    }
  ]
}

If there is only one receipt, "multiple" should be false and "receipts" should have one item.
All amounts as numbers without currency symbols. Dates as YYYY-MM-DD.` }
        ]
      }]
    })
  });

  if (!response.ok) throw new Error(`Claude error: ${response.status}`);
  const data = await response.json();
  const text = (data.content || []).map(c => c.text || '').join('').trim();
  const clean = text.replace(/^```json\s*/,'').replace(/\s*```$/,'').trim();
  try { return JSON.parse(clean); }
  catch { throw new Error('Claude returned invalid JSON'); }
}

// ── Auto-match logic ──────────────────────────────────────────────────────
async function _attemptRecAutoMatch(receipt, file, txnListOverride) {
  const banner = document.getElementById('recMatchBanner');

  // Load unmatched transactions for this bank if not already loaded
  const candidates = txnListOverride || _recTxnList.filter(t => t.status === 'unmatched');

  const match = _findBestRecMatch(receipt, candidates);

  if (match && match.confidence >= 0.6) {
    // Show confirmation banner
    banner.className = 'rec-match-banner success';
    banner.innerHTML = `
      ✓ Auto-matched: <strong>${escapeHtml(match.txn.description)}</strong>
      · £${Math.abs(Number(match.txn.amount)).toFixed(2)}
      · ${match.txn.transaction_date}
      &nbsp;
      <button class="btn btn-ghost" style="font-size:11px;padding:3px 10px;margin-left:8px"
              onclick="confirmRecDocMatch(${match.txn.id})">Confirm</button>
      <button class="btn btn-ghost" style="font-size:11px;padding:3px 10px"
              onclick="openManualMatchModal()">Pick different</button>`;

    // Highlight matching row
    document.querySelectorAll('.rec-txn-table tr').forEach(tr => {
      tr.style.outline = String(tr.dataset.txnId) === String(match.txn.id)
        ? '2px solid var(--green)' : '';
    });
  } else {
    // No confident match
    banner.className = 'rec-match-banner warn';
    banner.innerHTML = `
      ⚠ No auto-match found for <strong>${escapeHtml(receipt.supplier || file.name)}</strong>
      · ${receipt.total ? '£' + Number(receipt.total).toFixed(2) : 'unknown amount'}
      &nbsp;
      <button class="btn btn-ghost" style="font-size:11px;padding:3px 10px;margin-left:8px"
              onclick="openManualMatchModal()">Pick manually</button>
      <button class="btn btn-ghost" style="font-size:11px;padding:3px 10px"
              onclick="dismissRecMatchBanner()">Dismiss</button>`;
  }
}

function _findBestRecMatch(receipt, candidates) {
  if (!candidates.length) return null;
  const targetAmt = Number(receipt.total);
  const targetDate = receipt.date ? new Date(receipt.date) : null;
  const targetSupplier = (receipt.supplier || '').toLowerCase().trim();

  let best = null, bestScore = 0;

  for (const txn of candidates) {
    let score = 0;
    const txnAmt = Math.abs(Number(txn.amount));

    // Amount: exact match = 0.5, within 1% = 0.3
    if (targetAmt && Math.abs(txnAmt - targetAmt) < 0.01) score += 0.5;
    else if (targetAmt && Math.abs(txnAmt - targetAmt) / targetAmt < 0.01) score += 0.3;
    else if (targetAmt) continue; // amount is required, skip if no match

    // Date: within 2 days = 0.3, within 5 days = 0.1
    if (targetDate) {
      const txnDate = new Date(txn.transaction_date);
      const diffDays = Math.abs((txnDate - targetDate) / 86400000);
      if (diffDays <= 2) score += 0.3;
      else if (diffDays <= 5) score += 0.1;
    }

    // Supplier: fuzzy similarity = up to 0.2
    if (targetSupplier && txn.description) {
      const txnDesc = txn.description.toLowerCase();
      const sim = _recStringSimilarity(targetSupplier, txnDesc);
      score += sim * 0.2;
    }

    if (score > bestScore) { bestScore = score; best = { txn, confidence: score }; }
  }

  return best;
}

function _recStringSimilarity(a, b) {
  // Checks if any word from a appears in b or vice versa
  const wordsA = a.split(/\s+/).filter(w => w.length > 2);
  const wordsB = b.split(/\s+/).filter(w => w.length > 2);
  if (!wordsA.length || !wordsB.length) return 0;
  let matches = 0;
  for (const w of wordsA) {
    if (wordsB.some(wb => wb.includes(w) || w.includes(wb))) matches++;
  }
  return matches / wordsA.length;
}

async function confirmRecDocMatch(txnId) {
  if (!_recPendingDocFile || !_recPendingDocParsed) return;
  const receipt = _recPendingDocParsed.receipts ? _recPendingDocParsed.receipts[0] : _recPendingDocParsed;
  await _attachDocToTxn(txnId, _recPendingDocFile, receipt, 'matched');
}

async function _attachDocToTxn(txnId, file, parsedData, status) {
  const banner = document.getElementById('recMatchBanner');
  banner.innerHTML = '⏳ Saving…';

  try {
    // 1. Upload file to SharePoint
    let sharepointUrl = null;
    try {
      const folder = await _findOrCreateAccountsSubfolder('07 - Receipts for Dext');
      const uploadFolder = await getOrCreateSubfolder(folder.id, 'Upload to Dext', BAMA_DRIVE_ID);
      const uploaded = await uploadFileToFolder(uploadFolder.id, file.name, await file.arrayBuffer(), file.type, BAMA_DRIVE_ID);
      sharepointUrl = uploaded?.webUrl || null;
    } catch (spErr) {
      console.warn('[Reconcile] SharePoint upload failed (non-fatal):', spErr.message);
    }

    // 2. POST document to API
    await api.post(`/api/bank-transactions/${txnId}/documents`, {
      filename:        file.name,
      sharepoint_url:  sharepointUrl,
      parsed_supplier: parsedData.supplier || null,
      parsed_date:     parsedData.date || null,
      parsed_amount:   parsedData.total || null,
      parsed_net:      parsedData.net || null,
      parsed_vat:      parsedData.vat || null,
      uploaded_by:     currentManagerUser,
      set_status:      status
    });

    // 3. Update local state
    const txn = _recTxnList.find(t => t.id === txnId);
    if (txn) { txn.status = status; txn.doc_count = (txn.doc_count || 0) + 1; }

    // Clear pending
    _recPendingDocFile = null;
    _recPendingDocParsed = null;

    // Clear highlight
    document.querySelectorAll('.rec-txn-table tr').forEach(tr => tr.style.outline = '');

    banner.className = 'rec-match-banner success';
    banner.innerHTML = `✓ Document attached and transaction matched`;
    setTimeout(() => { banner.style.display = 'none'; }, 3000);

    renderRecTxnTable();
    await refreshRecTileStats();
    toast('Document matched', 'success');

  } catch (err) {
    banner.className = 'rec-match-banner warn';
    banner.innerHTML = `✗ Failed: ${escapeHtml(err.message)}`;
  }
}

function dismissRecMatchBanner() {
  const banner = document.getElementById('recMatchBanner');
  banner.style.display = 'none';
  _recPendingDocFile = null;
  _recPendingDocParsed = null;
  document.querySelectorAll('.rec-txn-table tr').forEach(tr => tr.style.outline = '');
}

// ── Multi-receipt review ──────────────────────────────────────────────────
let _recMultiReceipts = [];

function _showMultiReceiptReview(receipts, file) {
  _recMultiReceipts = receipts.map(r => ({ ...r, _file: file, _matched: false, _txnId: null }));
  const banner = document.getElementById('recMatchBanner');
  banner.className = 'rec-match-banner';
  banner.style.background = 'rgba(99,102,241,.08)';
  banner.style.border = '1px solid rgba(99,102,241,.25)';
  banner.style.color = 'var(--text)';
  banner.innerHTML = `
    📎 <strong>${receipts.length} receipts found</strong> in one file — review each below:
    ${receipts.map((r, i) => `
      <div style="display:flex;align-items:center;gap:8px;margin-top:6px;padding:6px 10px;
                  background:var(--bg-darker);border-radius:6px;font-size:12px">
        <span style="flex:1">${escapeHtml(r.supplier || 'Unknown')}</span>
        <span style="font-family:var(--font-mono)">${r.total ? '£'+Number(r.total).toFixed(2) : '—'}</span>
        <span style="color:var(--muted)">${r.date || '—'}</span>
        <button class="btn btn-ghost" style="font-size:11px;padding:2px 8px"
                onclick="matchMultiReceipt(${i})">Match</button>
      </div>`).join('')}`;
}

async function matchMultiReceipt(idx) {
  const receipt = _recMultiReceipts[idx];
  if (!receipt) return;
  _recPendingDocParsed = { receipts: [receipt] };
  _recPendingDocFile = receipt._file;
  await _attemptRecAutoMatch(receipt, receipt._file);
}

// ── Manual match picker ───────────────────────────────────────────────────
function openManualMatchModal() {
  const unmatched = _recTxnList.filter(t => t.status === 'unmatched');
  _recManualMatchTxnList = unmatched;
  _renderManualMatchList(unmatched);

  const parsed = _recPendingDocParsed?.receipts?.[0] || _recPendingDocParsed;
  const docInfo = parsed
    ? `${escapeHtml(parsed.supplier || 'Unknown supplier')} · ${parsed.total ? '£'+Number(parsed.total).toFixed(2) : '—'} · ${parsed.date || '—'}`
    : '';
  document.getElementById('recManualMatchDoc').innerHTML = docInfo;
  document.getElementById('recManualMatchSearch').value = '';
  document.getElementById('recManualMatchModal').classList.add('active');
}

function closeManualMatchModal() {
  document.getElementById('recManualMatchModal').classList.remove('active');
}

function filterManualMatchList(search) {
  const s = search.toLowerCase();
  const filtered = s
    ? _recManualMatchTxnList.filter(t =>
        (t.description || '').toLowerCase().includes(s) ||
        String(Math.abs(t.amount)).includes(s) ||
        (t.transaction_date || '').includes(s))
    : _recManualMatchTxnList;
  _renderManualMatchList(filtered);
}

function _renderManualMatchList(txns) {
  const el = document.getElementById('recManualMatchList');
  if (!txns.length) {
    el.innerHTML = '<div style="padding:20px;text-align:center;color:var(--muted)">No unmatched transactions found</div>';
    return;
  }
  el.innerHTML = txns.map(t => `
    <div style="display:flex;align-items:center;gap:10px;padding:9px 14px;
                border-bottom:1px solid var(--border);cursor:pointer"
         onclick="selectManualMatch(${t.id})"
         onmouseover="this.style.background='var(--bg-darker)'"
         onmouseout="this.style.background=''">
      <span style="font-size:12px;flex:1">${escapeHtml(t.description || '')}</span>
      <span style="font-family:var(--font-mono);font-size:12px;
                   color:${Number(t.amount) >= 0 ? 'var(--green)' : 'var(--red)'}">
        ${Number(t.amount) >= 0 ? '+' : ''}£${Math.abs(Number(t.amount)).toFixed(2)}
      </span>
      <span style="font-size:11px;color:var(--muted)">${t.transaction_date}</span>
    </div>`).join('');
}

async function selectManualMatch(txnId) {
  closeManualMatchModal();
  if (!_recPendingDocFile) return;
  const parsed = _recPendingDocParsed?.receipts?.[0] || _recPendingDocParsed || {};
  await _attachDocToTxn(txnId, _recPendingDocFile, parsed, 'manual_match');
}

// ── Document preview ──────────────────────────────────────────────────────
async function previewRecTxnDoc(txnId) {
  _recPreviewTxnId = txnId;
  const txn = _recTxnList.find(t => t.id === txnId);
  const modal = document.getElementById('recDocPreviewModal');
  const body  = document.getElementById('recDocPreviewBody');
  const title = document.getElementById('recDocPreviewTitle');

  if (txn) title.textContent = `📎 ${escapeHtml(txn.description)} · £${Math.abs(Number(txn.amount)).toFixed(2)}`;
  body.innerHTML = '<div style="padding:20px;text-align:center"><div class="spinner"></div></div>';
  modal.classList.add('active');

  try {
    const docs = await api.get(`/api/bank-transactions/${txnId}/documents`);
    const docList = Array.isArray(docs) ? docs : [];

    if (!docList.length) {
      body.innerHTML = '<div style="padding:30px;text-align:center;color:var(--muted)">No documents attached</div>';
      return;
    }

    body.innerHTML = docList.map(doc => `
      <div style="padding:14px 16px;border-bottom:1px solid var(--border)">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
          <span style="font-size:13px;font-weight:600;flex:1">${escapeHtml(doc.filename)}</span>
          <button class="btn btn-ghost" style="font-size:11px;padding:3px 9px;color:var(--red)"
                  onclick="deleteRecDoc(${doc.id}, ${txnId})">🗑 Remove</button>
          ${doc.sharepoint_url ? `<a href="${escapeHtml(doc.sharepoint_url)}" target="_blank"
            class="btn btn-ghost" style="font-size:11px;padding:3px 9px">📂 Open in SharePoint</a>` : ''}
        </div>
        <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;font-size:12px">
          ${doc.parsed_supplier ? `<div><div style="color:var(--muted);font-size:10px">SUPPLIER</div>${escapeHtml(doc.parsed_supplier)}</div>` : ''}
          ${doc.parsed_date     ? `<div><div style="color:var(--muted);font-size:10px">DATE</div>${escapeHtml(String(doc.parsed_date).split('T')[0])}</div>` : ''}
          ${doc.parsed_amount   ? `<div><div style="color:var(--muted);font-size:10px">TOTAL</div>£${Number(doc.parsed_amount).toFixed(2)}</div>` : ''}
          ${doc.parsed_vat      ? `<div><div style="color:var(--muted);font-size:10px">VAT</div>£${Number(doc.parsed_vat).toFixed(2)}</div>` : ''}
        </div>
        <div style="font-size:10px;color:var(--subtle);margin-top:6px">
          Uploaded ${escapeHtml(String(doc.uploaded_at).split('T')[0])} by ${escapeHtml(doc.uploaded_by || '—')}
        </div>
      </div>`).join('');

  } catch (err) {
    body.innerHTML = `<div style="padding:20px;color:var(--red)">Failed to load: ${escapeHtml(err.message)}</div>`;
  }
}

async function deleteRecDoc(docId, txnId) {
  if (!await showConfirmAsync('Remove this document from the transaction?', 'Remove')) return;
  try {
    await api.delete(`/api/bank-transaction-docs/${docId}`);
    toast('Document removed', 'success');
    await previewRecTxnDoc(txnId); // reload preview
    // Reload transaction to update doc_count
    const txn = _recTxnList.find(t => t.id === txnId);
    if (txn && txn.doc_count > 0) txn.doc_count--;
    renderRecTxnTable();
  } catch (err) {
    toast('Failed: ' + err.message, 'error');
  }
}

async function unmatchRecTxnFromPreview() {
  if (!_recPreviewTxnId) return;
  if (!await showConfirmAsync('Unmatch this transaction? It will return to unmatched status.', 'Unmatch')) return;
  try {
    await api.put(`/api/bank-transactions/${_recPreviewTxnId}/unmatch`, {});
    const txn = _recTxnList.find(t => t.id === _recPreviewTxnId);
    if (txn) txn.status = 'unmatched';
    document.getElementById('recDocPreviewModal').classList.remove('active');
    renderRecTxnTable();
    await refreshRecTileStats();
    toast('Transaction unmatched', 'success');
  } catch (err) {
    toast('Failed: ' + err.message, 'error');
  }
}

// ── Transaction inline edit ───────────────────────────────────────────────
function openRecTxnEdit(txnId) {
  const txn = _recTxnList.find(t => t.id === txnId);
  if (!txn) return;
  document.getElementById('recEditTxnId').value = txnId;
  document.getElementById('recEditDesc').value = txn.description || '';
  document.getElementById('recEditDate').value = txn.transaction_date || '';
  document.getElementById('recEditAmount').value = txn.amount || '';
  document.getElementById('recEditCategory').value = txn.spending_category || '';
  document.getElementById('recEditCardholder').value = txn.cardholder || '';
  document.getElementById('recEditReference').value = txn.reference || '';
  document.getElementById('recTxnEditModal').classList.add('active');
}

async function saveRecTxnEdit() {
  const id = Number(document.getElementById('recEditTxnId').value);
  const payload = {
    description:       document.getElementById('recEditDesc').value.trim(),
    transaction_date:  document.getElementById('recEditDate').value,
    amount:            Number(document.getElementById('recEditAmount').value),
    spending_category: document.getElementById('recEditCategory').value.trim() || null,
    cardholder:        document.getElementById('recEditCardholder').value.trim() || null,
    reference:         document.getElementById('recEditReference').value.trim() || null
  };
  try {
    const updated = await api.put(`/api/bank-transactions/${id}/edit`, payload);
    const txn = _recTxnList.find(t => t.id === id);
    if (txn && updated) Object.assign(txn, updated);
    document.getElementById('recTxnEditModal').classList.remove('active');
    renderRecTxnTable();
    toast('Transaction updated', 'success');
  } catch (err) {
    toast('Save failed: ' + err.message, 'error');
  }
}

// ═════════════════════════════════════════════════════════════════════════
// STATEMENT UPLOAD — parse, preview, duplicate check, auto-clear, import
// ═════════════════════════════════════════════════════════════════════════

let _recStmtFile       = null;
let _recStmtParsed     = [];   // parsed transactions array
let _recStmtSelected   = [];   // bool[] — which rows are ticked in preview
let _recStmtAutoClear  = [];   // { idx, reason, checked }[]

function openUploadStatementModal() {
  if (!_recSelectedBankId) { toast('Select a bank first', 'error'); return; }

  // Populate bank select
  const sel = document.getElementById('recStmtBankSelect');
  if (sel) {
    sel.innerHTML = _recBankList.map(b =>
      `<option value="${b.id}" ${b.id === _recSelectedBankId ? 'selected' : ''}>${escapeHtml(b.bank_name)}</option>`
    ).join('');
  }

  // Reset state
  _recStmtFile = null;
  _recStmtParsed = [];
  _recStmtSelected = [];
  _recStmtAutoClear = [];
  document.getElementById('recStmtFileInput').value = '';
  document.getElementById('recStmtParseStatus').style.display = 'none';
  document.getElementById('recStmtParseBtn').disabled = true;
  _recStmtShowStep(1);
  document.getElementById('recUploadStmtModal').classList.add('active');
}

function closeRecUploadStmtModal() {
  document.getElementById('recUploadStmtModal').classList.remove('active');
}

function _recStmtShowStep(n) {
  [1,2,3].forEach(i => {
    const el = document.getElementById(`recStmtStep${i}`);
    if (el) el.style.display = i === n ? '' : 'none';
  });
}

function onRecStmtFilePicked(file) {
  if (!file) return;
  _recStmtFile = file;
  document.getElementById('recStmtParseBtn').disabled = false;
  const status = document.getElementById('recStmtParseStatus');
  status.style.display = '';
  status.style.background = 'var(--bg-darker)';
  status.style.color = 'var(--muted)';
  status.textContent = `📎 ${file.name} (${(file.size / 1024).toFixed(1)} KB) — click Parse to continue`;
}

async function parseRecStatement() {
  if (!_recStmtFile) return;
  const btn = document.getElementById('recStmtParseBtn');
  const status = document.getElementById('recStmtParseStatus');
  btn.disabled = true;
  btn.textContent = 'Parsing…';
  status.style.display = '';
  status.style.color = 'var(--accent)';
  status.textContent = '⏳ Reading file…';

  try {
    const ext = _recStmtFile.name.split('.').pop().toLowerCase();
    let transactions = [];

    if (['xlsx','xls','csv'].includes(ext)) {
      transactions = await _parseRecStatementStructured(_recStmtFile, ext);
      status.textContent = `✓ Parsed ${transactions.length} transactions from ${ext.toUpperCase()}`;
    } else {
      // PDF or image — send to Claude
      status.textContent = '⏳ Sending to Claude for extraction…';
      transactions = await _parseRecStatementClaude(_recStmtFile);
      status.textContent = `✓ Claude extracted ${transactions.length} transactions`;
    }

    status.style.color = 'var(--green)';
    _recStmtParsed = transactions;
    _recStmtSelected = transactions.map(() => true);

    // Check for duplicates
    status.textContent = `✓ ${transactions.length} transactions — checking for duplicates…`;
    const bankId = Number(document.getElementById('recStmtBankSelect').value);
    let dupeIndices = [];
    try {
      const dupeRes = await api.post('/api/bank-transactions/check-duplicates', {
        bank_account_id: bankId,
        transactions: transactions.map(t => ({
          transaction_date: t.transaction_date,
          amount: t.amount,
          description: t.description
        }))
      });
      dupeIndices = dupeRes.dupeIndices || [];
    } catch { /* non-fatal */ }

    if (dupeIndices.length) {
      status.textContent = `✓ ${transactions.length} transactions — ${dupeIndices.length} duplicates flagged`;
      // Pre-deselect duplicates
      dupeIndices.forEach(i => { _recStmtSelected[i] = false; });
    } else {
      status.textContent = `✓ ${transactions.length} transactions — no duplicates found`;
    }

    _recRenderStmtPreview(dupeIndices);
    _recStmtShowStep(2);

    const selected = _recStmtSelected.filter(Boolean).length;
    document.getElementById('recStmtPreviewMeta').textContent =
      `${transactions.length} parsed · ${dupeIndices.length} duplicates pre-deselected · ${selected} selected to import`;

  } catch (err) {
    status.style.color = 'var(--red)';
    status.textContent = '✗ ' + err.message;
  } finally {
    btn.disabled = false;
    btn.textContent = 'Parse Statement';
  }
}

function _recRenderStmtPreview(dupeIndices = []) {
  const tbody = document.getElementById('recStmtPreviewTbody');
  if (!tbody) return;
  tbody.innerHTML = _recStmtParsed.map((t, i) => {
    const isDupe = dupeIndices.includes(i);
    const isCredit = Number(t.amount) >= 0;
    const amtStr = (isCredit ? '+' : '') + '£' + Math.abs(Number(t.amount)).toLocaleString('en-GB', { minimumFractionDigits: 2 });
    const amtClass = isCredit ? 'color:var(--green)' : 'color:var(--red)';
    const rowBg = isDupe ? 'background:rgba(245,158,11,.08)' : '';
    return `
      <tr style="${rowBg}" data-idx="${i}">
        <td style="padding:6px 10px">
          <input type="checkbox" class="rec-cb rec-stmt-cb" data-idx="${i}"
                 ${_recStmtSelected[i] ? 'checked' : ''}
                 onchange="recStmtToggleRow(${i}, this.checked)">
        </td>
        <td style="padding:6px 10px;white-space:nowrap">${escapeHtml(t.transaction_date || '')}</td>
        <td style="padding:6px 10px">
          <div>${escapeHtml(t.description || '')}</div>
          ${t.cardholder ? `<div style="font-size:10px;color:var(--muted)">${escapeHtml(t.cardholder)}</div>` : ''}
        </td>
        <td style="padding:6px 10px;text-align:right;font-family:var(--font-mono);${amtClass}">${amtStr}</td>
        <td style="padding:6px 10px;font-size:11px;color:var(--muted)">${escapeHtml(t.transaction_type || '')}</td>
        <td style="padding:6px 10px">
          ${isDupe ? '<span style="font-size:11px;padding:2px 7px;border-radius:10px;background:rgba(245,158,11,.15);color:var(--warn)">Duplicate</span>' : ''}
        </td>
      </tr>`;
  }).join('');
}

function recStmtToggleRow(idx, checked) {
  _recStmtSelected[idx] = checked;
  const sel = _recStmtSelected.filter(Boolean).length;
  document.getElementById('recStmtPreviewMeta').textContent =
    `${_recStmtParsed.length} parsed · ${sel} selected to import`;
}

function recStmtSelectAll(checked) {
  _recStmtSelected = _recStmtParsed.map(() => checked);
  document.querySelectorAll('.rec-stmt-cb').forEach(cb => cb.checked = checked);
  const sel = _recStmtSelected.filter(Boolean).length;
  document.getElementById('recStmtPreviewMeta').textContent =
    `${_recStmtParsed.length} parsed · ${sel} selected to import`;
}

function recStmtBackToStep1() { _recStmtShowStep(1); }
function recStmtBackToStep2() { _recStmtShowStep(2); }

function recStmtGoToStep3() {
  // Build auto-clear suggestions from the selected transactions
  const selected = _recStmtParsed.filter((_, i) => _recStmtSelected[i]);
  _recStmtAutoClear = [];

  const PATTERNS = [
    { re: /wages?|salary|payroll|week\s*\d/i,        reason: 'Wages' },
    { re: /transfer|bama\s*fab|internal|tfr/i,        reason: 'Internal transfer' },
    { re: /direct\s*debit|dd$/i,                      reason: 'Direct debit' },
    { re: /bank\s*charge|service\s*charge|interest/i, reason: 'Bank charge' },
    { re: /card\s*payment|virtual.*transfer|settlement/i, reason: 'Card payment settlement' },
    { re: /standing\s*order|s\.?o\.?/i,               reason: 'Standing order' },
    { re: /hmrc|paye|vat|tax/i,                       reason: 'HMRC / Tax' },
    { re: /pension|nest|aviva/i,                      reason: 'Pension' },
  ];

  _recStmtParsed.forEach((t, i) => {
    if (!_recStmtSelected[i]) return;
    const desc = (t.description || '') + ' ' + (t.transaction_type || '') + ' ' + (t.reference || '');
    for (const p of PATTERNS) {
      if (p.re.test(desc)) {
        _recStmtAutoClear.push({ idx: i, reason: p.reason, checked: true });
        break;
      }
    }
  });

  const el = document.getElementById('recStmtAutoClearList');
  const meta = document.getElementById('recStmtAutoClearMeta');

  if (!_recStmtAutoClear.length) {
    meta.textContent = 'No auto-clear suggestions for this statement.';
    el.innerHTML = '<div style="padding:14px;color:var(--muted);font-size:13px;text-align:center">No transactions matched the auto-clear patterns.</div>';
  } else {
    meta.textContent = `${_recStmtAutoClear.length} transaction${_recStmtAutoClear.length !== 1 ? 's' : ''} suggested for auto-clear — untick any you want to keep as unmatched.`;
    el.innerHTML = _recStmtAutoClear.map((ac, n) => {
      const t = _recStmtParsed[ac.idx];
      const amtStr = '£' + Math.abs(Number(t.amount)).toLocaleString('en-GB', { minimumFractionDigits: 2 });
      return `
        <label style="display:flex;align-items:center;gap:10px;padding:8px 14px;border-bottom:1px solid var(--border);cursor:pointer">
          <input type="checkbox" class="rec-cb rec-autoclear-cb" data-n="${n}" checked
                 onchange="_recStmtAutoClear[${n}].checked = this.checked">
          <span style="flex:1;font-size:12px">${escapeHtml(t.description)}</span>
          <span style="font-family:var(--font-mono);font-size:12px;color:var(--muted)">${amtStr}</span>
          <span style="font-size:11px;color:var(--muted);white-space:nowrap">${escapeHtml(t.transaction_date || '')}</span>
          <input type="text" class="field-input" value="${escapeHtml(ac.reason)}"
                 style="width:160px;font-size:11px;padding:3px 6px"
                 oninput="_recStmtAutoClear[${n}].reason = this.value"
                 onclick="event.stopPropagation()">
        </label>`;
    }).join('');
  }

  _recStmtShowStep(3);
}

async function confirmRecStatementImport() {
  const bankId = Number(document.getElementById('recStmtBankSelect').value);
  const toImport = _recStmtParsed.filter((_, i) => _recStmtSelected[i]);

  if (!toImport.length) { toast('No transactions selected', 'error'); return; }

  const btn = document.getElementById('recStmtConfirmBtn');
  btn.disabled = true;
  btn.textContent = 'Importing…';

  try {
    // 1. Get date range from transactions
    const dates = toImport.map(t => t.transaction_date).filter(Boolean).sort();
    const dateFrom = dates[0] || null;
    const dateTo   = dates[dates.length - 1] || null;

    // 2. POST statement + transactions
    const result = await api.post('/api/bank-statements', {
      bank_account_id: bankId,
      filename:        _recStmtFile.name,
      date_from:       dateFrom,
      date_to:         dateTo,
      transactions:    toImport
    });

    const stmtId = result.statement?.id;

    // 3. Apply auto-clears
    if (stmtId) {
      const autoClearItems = _recStmtAutoClear.filter(ac => ac.checked && _recStmtSelected[ac.idx]);
      // Map back to inserted transactions by date+amount+description
      if (autoClearItems.length) {
        const txnRes = await api.get(`/api/bank-transactions?bank_account_id=${bankId}&statement_id=${stmtId}`);
        const txns = Array.isArray(txnRes) ? txnRes : [];
        for (const ac of autoClearItems) {
          const t = _recStmtParsed[ac.idx];
          const match = txns.find(tx =>
            tx.transaction_date === t.transaction_date &&
            Math.abs(Number(tx.amount) - Number(t.amount)) < 0.01 &&
            tx.description === t.description
          );
          if (match) {
            await api.put(`/api/bank-transactions/${match.id}/match`, {
              status: 'cleared',
              clear_reason: ac.reason || null,
              matched_by: currentManagerUser
            }).catch(() => {});
          }
        }
      }
    }

    closeRecUploadStmtModal();
    toast(`Imported ${result.inserted} transactions`, 'success');

    // Refresh
    await loadRecStatements(bankId);
    if (stmtId) await selectRecStmt(stmtId);
    await refreshRecTileStats();

  } catch (err) {
    toast('Import failed: ' + err.message, 'error');
  } finally {
    btn.disabled = false;
    btn.textContent = '✓ Import Statement';
  }
}

// ── Structured parser (XLSX / XLS / CSV) ─────────────────────────────────
async function _parseRecStatementStructured(file, ext) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target.result);
        const wb   = XLSX.read(data, { type: 'array', cellDates: true });
        const ws   = wb.Sheets[wb.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '' });
        if (rows.length < 2) { reject(new Error('No data rows found')); return; }

        const headers = rows[0].map(h => String(h || '').trim().toLowerCase());
        const fmt = _detectRecBankFormat(headers);
        const transactions = [];

        for (let i = 1; i < rows.length; i++) {
          const row = rows[i];
          const t = fmt.parseRow(row, headers);
          if (!t || !t.transaction_date || t.amount === null || t.amount === undefined) continue;
          // Normalise date to YYYY-MM-DD
          t.transaction_date = _normaliseRecDate(t.transaction_date);
          if (!t.transaction_date) continue;
          transactions.push(t);
        }
        resolve(transactions);
      } catch (err) {
        reject(new Error('Failed to parse file: ' + err.message));
      }
    };
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsArrayBuffer(file);
  });
}

// ── Bank format detector ──────────────────────────────────────────────────
function _detectRecBankFormat(headers) {
  const h = headers.join('|');

  // Starling: Date | Counter Party | Reference | Type | Amount (GBP) | Balance (GBP) | Spending Category
  if (headers.includes('counter party') && headers.includes('amount (gbp)')) {
    return {
      name: 'Starling',
      parseRow: (row, hdrs) => {
        const get = (name) => row[hdrs.indexOf(name)] ?? '';
        const amt = Number(get('amount (gbp)'));
        return {
          transaction_date:  get('date'),
          description:       String(get('counter party')),
          reference:         String(get('reference')),
          transaction_type:  String(get('type')),
          amount:            isNaN(amt) ? null : amt,
          spending_category: String(get('spending category')),
          cardholder:        null,
          original_amount:   null,
          original_currency: null
        };
      }
    };
  }

  // Capital On Tap: Clearance Date | Authorisation Date | Description | Amount | Merchant Name | Card Ending | Cardholder Name | Transaction Type | Category
  if (headers.includes('clearance date') && headers.includes('cardholder name')) {
    return {
      name: 'Capital On Tap',
      parseRow: (row, hdrs) => {
        const get = (name) => row[hdrs.indexOf(name)] ?? '';
        const amt = Number(get('amount'));
        const origAmt = Number(get('original amount'));
        const origCcy = String(get('original currency')).trim();
        return {
          transaction_date:  get('clearance date'),
          description:       String(get('merchant name') || get('description')),
          reference:         String(get('description')),
          transaction_type:  String(get('transaction type')),
          amount:            isNaN(amt) ? null : (amt > 0 ? -amt : -amt), // CoT amounts are positive for purchases
          original_amount:   isNaN(origAmt) ? null : origAmt,
          original_currency: (origCcy && origCcy !== 'GBP' && origCcy !== '') ? origCcy : null,
          spending_category: String(get('category')),
          cardholder:        String(get('cardholder name'))
        };
      }
    };
  }

  // Lloyds CSV: Date | Description | Type | Money In | Money Out | Balance
  if ((headers.includes('money in') || headers.includes('money in (£)')) &&
      (headers.includes('money out') || headers.includes('money out (£)'))) {
    const inKey  = headers.includes('money in (£)') ? 'money in (£)' : 'money in';
    const outKey = headers.includes('money out (£)') ? 'money out (£)' : 'money out';
    return {
      name: 'Lloyds',
      parseRow: (row, hdrs) => {
        const get = (name) => row[hdrs.indexOf(name)] ?? '';
        const moneyIn  = Number(String(get(inKey)).replace(/[£,]/g, '')) || 0;
        const moneyOut = Number(String(get(outKey)).replace(/[£,]/g, '')) || 0;
        const amt = moneyIn > 0 ? moneyIn : (moneyOut > 0 ? -moneyOut : null);
        if (amt === null) return null;
        return {
          transaction_date:  get('date'),
          description:       String(get('description')),
          reference:         null,
          transaction_type:  String(get('type')),
          amount:            amt,
          original_amount:   null,
          original_currency: null,
          spending_category: null,
          cardholder:        null
        };
      }
    };
  }

  // Generic fallback: look for date-like, description-like, amount-like columns
  const dateCol   = headers.findIndex(h => /date/i.test(h));
  const descCol   = headers.findIndex(h => /desc|narrat|payee|merchant|counter|name/i.test(h));
  const amtCol    = headers.findIndex(h => /amount|value|debit|credit/i.test(h));
  return {
    name: 'Generic',
    parseRow: (row) => {
      if (dateCol < 0 || amtCol < 0) return null;
      const amt = Number(String(row[amtCol] || '').replace(/[£,$,]/g, ''));
      return {
        transaction_date:  row[dateCol],
        description:       descCol >= 0 ? String(row[descCol]) : 'Transaction',
        reference:         null,
        transaction_type:  null,
        amount:            isNaN(amt) ? null : amt,
        original_amount:   null,
        original_currency: null,
        spending_category: null,
        cardholder:        null
      };
    }
  };
}

function _normaliseRecDate(val) {
  if (!val) return null;
  // Already a JS Date object (from SheetJS cellDates)
  if (val instanceof Date) {
    if (isNaN(val.getTime())) return null;
    const y = val.getFullYear();
    const m = String(val.getMonth() + 1).padStart(2, '0');
    const d = String(val.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }
  const s = String(val).trim();
  // YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  // DD/MM/YYYY or DD-MM-YYYY
  const dmy = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
  if (dmy) {
    const [, d, m, y] = dmy;
    const year = y.length === 2 ? '20' + y : y;
    return `${year}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
  }
  // DD Mon YY or DD Mon YYYY (e.g. "02 Apr 26")
  const dmy2 = s.match(/^(\d{1,2})\s+([A-Za-z]{3})\s+(\d{2,4})/);
  if (dmy2) {
    const months = { jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12 };
    const [, d, mon, y] = dmy2;
    const m = months[mon.toLowerCase()];
    if (!m) return null;
    const year = y.length === 2 ? '20' + y : y;
    return `${year}-${String(m).padStart(2, '0')}-${d.padStart(2, '0')}`;
  }
  return null;
}

// ── Claude parser (PDF / image) ───────────────────────────────────────────
async function _parseRecStatementClaude(file) {
  const base64 = await new Promise((res, rej) => {
    const reader = new FileReader();
    reader.onload = () => res(reader.result.split(',')[1]);
    reader.onerror = () => rej(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });

  const isImage = file.type.startsWith('image/');
  const mediaType = isImage ? (file.type || 'image/jpeg') : 'application/pdf';
  const contentType = isImage ? 'image' : 'document';

  const response = await fetch('/api/claude-proxy', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${await getToken()}`
    },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 4000,
      messages: [{
        role: 'user',
        content: [
          {
            type: contentType,
            source: { type: 'base64', media_type: mediaType, data: base64 }
          },
          {
            type: 'text',
            text: `Extract ALL transactions from this bank statement. Return ONLY a JSON array, no markdown, no explanation.
Each item must have these exact fields:
- transaction_date: "YYYY-MM-DD"
- description: string (payee/merchant name)
- reference: string or null
- transaction_type: string or null (e.g. "FASTER PAYMENT", "DIRECT DEBIT")
- amount: number (negative for debits/money out, positive for credits/money in)
- spending_category: string or null
- cardholder: string or null (for credit card statements)
- original_amount: number or null (for foreign currency)
- original_currency: string or null (e.g. "EUR", "USD")

Return ONLY the JSON array starting with [ and ending with ].`
          }
        ]
      }]
    })
  });

  if (!response.ok) throw new Error(`Claude API error: ${response.status}`);
  const data = await response.json();
  const text = (data.content || []).map(c => c.text || '').join('').trim();
  const clean = text.replace(/^```json\s*/,'').replace(/\s*```$/,'').trim();

  let parsed;
  try { parsed = JSON.parse(clean); } catch { throw new Error('Claude returned invalid JSON'); }
  if (!Array.isArray(parsed)) throw new Error('Claude did not return an array');
  return parsed;
}

// previewRecTxnDoc and openRecTxnEdit are fully implemented above


// ═════════════════════════════════════════════════════════════════════════
// GLOBAL INVOICE DROPZONE — office dashboard header
// Drop any supplier invoice; system parses supplier name + PO ref,
// fuzzy-matches against Suppliers, loads that supplier's open POs,
// then runs the same review-and-save flow as the per-supplier dropzone.
// ═════════════════════════════════════════════════════════════════════════

let _gInvQueue    = [];   // File[]
let _gInvQueueIdx = 0;
let _gInvState    = 'idle'; // idle | parsing | review | saving
let _gInvFile     = null;
let _gInvParsed   = null;
let _gInvSupplier = null;   // matched Suppliers row
let _gInvPos      = [];     // open POs for matched supplier
let _gInvMatchedPoId = null;

function initGlobalInvDz() {
  const box = document.getElementById('globalInvDz');
  if (!box) return;
  box.innerHTML = `
    <div id="gInvDrop"
         style="border:2px dashed var(--border);border-radius:10px;padding:10px 20px;
                display:flex;align-items:center;gap:14px;cursor:pointer;
                transition:border-color .15s,background .15s;background:var(--surface)"
         onclick="document.getElementById('gInvFileInput').click()"
         ondragover="event.preventDefault();this.style.borderColor='var(--accent)';this.style.background='rgba(255,255,255,.03)'"
         ondragleave="this.style.borderColor='var(--border)';this.style.background='var(--surface)'"
         ondrop="event.preventDefault();this.style.borderColor='var(--border)';this.style.background='var(--surface)';_gInvOnFiles(event.dataTransfer.files)">
      <div style="font-size:22px;flex-shrink:0">📥</div>
      <div>
        <div style="font-size:13px;font-weight:600;color:var(--text)">Drop invoices to match</div>
        <div style="font-size:11px;color:var(--subtle)">Any supplier · PDF, PNG or JPG · multiple OK</div>
      </div>
      <input type="file" id="gInvFileInput" accept="application/pdf,image/*" multiple
             style="display:none" onchange="_gInvOnFiles(this.files)">
    </div>`;
}

async function _gInvOnFiles(files) {
  if (!files || !files.length) return;
  _gInvQueue    = Array.from(files);
  _gInvQueueIdx = 0;
  await _gInvProcessNext();
}

async function _gInvProcessNext() {
  if (_gInvQueueIdx >= _gInvQueue.length) {
    _gInvQueue = []; _gInvQueueIdx = 0;
    _gInvState = 'idle'; _gInvFile = null; _gInvParsed = null;
    _gInvSupplier = null; _gInvPos = []; _gInvMatchedPoId = null;
    document.getElementById('globalInvModal')?.classList.remove('active');
    return;
  }
  _gInvFile  = _gInvQueue[_gInvQueueIdx];
  _gInvState = 'parsing';
  _gInvParsed = null; _gInvSupplier = null; _gInvPos = []; _gInvMatchedPoId = null;
  _gInvOpenModal();
  _gInvRender();

  // Ensure suppliers are loaded (may not be if Suppliers tab hasn't been opened)
  if (!_suppliers || _suppliers.length === 0) {
    try { _suppliers = await api.get('/api/suppliers'); } catch { _suppliers = []; }
  }

  try {
    const dataUri = await _fileToDataUri(_gInvFile);
    const isImg   = _gInvFile.type.startsWith('image/');
    const result  = await callClaude({
      model: 'claude-sonnet-4-6',
      max_tokens: 800,
      messages: [{ role: 'user', content: [
        isImg
          ? { type: 'image',    source: { type: 'base64', media_type: _gInvFile.type, data: dataUri.split(',')[1] } }
          : { type: 'document', source: { type: 'base64', media_type: _gInvFile.type, data: dataUri.split(',')[1] } },
        { type: 'text', text: `Extract from this UK supplier invoice. Return ONLY JSON, no markdown:
{
  "supplier_name": "the supplier/vendor company name as printed on the invoice",
  "invoice_ref": "supplier's invoice number",
  "invoice_date": "YYYY-MM-DD",
  "net_amount": 0,
  "vat_amount": 0,
  "gross_amount": 0,
  "po_reference": "BAMA's PO reference if shown — looks like P260501 (P + 6 digits)"
}
Set any field to null if not clearly shown. The PO reference is the customer order number printed under "Your Order", "Order Ref", "PO Number" or similar.
IMPORTANT: Use the final printed net total and gross total from the invoice — not a goods-only subtotal. If the invoice has no delivery or other extra charges, the printed total is still correct as-is.` }
      ]}]
    });
    const text  = (result.content?.find(b => b.type === 'text')?.text || '').trim();
    const start = text.indexOf('{'), end = text.lastIndexOf('}');
    _gInvParsed = JSON.parse(text.slice(start, end + 1));

    // Fuzzy-match supplier name against loaded suppliers
    _gInvSupplier = _gInvFuzzyMatchSupplier(_gInvParsed.supplier_name || '');

    // Load open POs for matched supplier
    if (_gInvSupplier) {
      try {
        const allPos = await api.get(`/api/purchase-orders?supplier_id=${_gInvSupplier.id}`);
        _gInvPos = (allPos || []).filter(p => !p.supplier_invoice_received_at);
      } catch { _gInvPos = []; }
    }

    // Auto-match PO
    _gInvMatchedPoId = _gInvMatchPo();
    _gInvState = 'review';
  } catch (err) {
    console.error('Global invoice OCR failed', err);
    _gInvParsed = { _error: err.message || 'Could not read invoice' };
    _gInvState  = 'review';
  }
  _gInvRender();
}

function _gInvFuzzyMatchSupplier(name) {
  if (!name || !_suppliers?.length) return null;
  const n = name.toLowerCase().replace(/[^a-z0-9 ]/g, '').trim();
  if (!n) return null;
  let best = null, bestScore = 0;
  // Filter both sides: only words >= 3 chars; ignore common filler words
  const STOP = new Set(['ltd','plc','inc','llc','the','and','for','uk','co','group','limited']);
  const sig = w => w.length >= 3 && !STOP.has(w);
  const qWords = n.split(/\s+/).filter(sig);
  if (!qWords.length) return null;
  for (const s of _suppliers) {
    const sn = (s.supplier_name || '').toLowerCase().replace(/[^a-z0-9 ]/g, '');
    const snWords = sn.split(/\s+/).filter(sig);
    // Exact word match only (no startsWith to avoid false positives)
    const score = qWords.filter(w => snWords.includes(w)).length;
    if (score > bestScore) { bestScore = score; best = s; }
  }
  // Require 2+ matching words, OR 1 match where the word is 5+ chars (e.g. "Amazon", "Hilti")
  const hasLongMatch = best && bestScore >= 1 &&
    qWords.some(w => w.length >= 5 && (best.supplier_name||'').toLowerCase().replace(/[^a-z0-9 ]/g,'').split(/\s+/).includes(w));
  return (bestScore >= 2 || hasLongMatch) ? best : null;
}

function _gInvMatchPo() {
  if (!_gInvPos.length || !_gInvParsed) return null;
  // 1. PO ref exact match
  const ref = (_gInvParsed.po_reference || '').replace(/\s+/g, '').toUpperCase();
  if (ref) {
    const hit = _gInvPos.find(p => (p.reference || '').replace(/\s+/g, '').toUpperCase() === ref);
    if (hit) return hit.id;
  }
  // 2. Net value match within £1
  const net = Number(_gInvParsed.net_amount);
  if (Number.isFinite(net) && net > 0) {
    const close = _gInvPos
      .map(p => ({ p, diff: Math.abs(_poNet(p) - net) }))
      .filter(x => x.diff <= 1)
      .sort((a, b) => a.diff - b.diff);
    if (close.length === 1) return close[0].p.id;
  }
  return null;
}

function _gInvOpenModal() {
  document.getElementById('globalInvModal')?.classList.add('active');
}

function _gInvRender() {
  const prog = document.getElementById('globalInvProgress');
  const body = document.getElementById('globalInvModalBody');
  if (!body) return;

  const qTotal = _gInvQueue.length;
  const qIdx   = _gInvQueueIdx + 1;
  if (prog) prog.textContent = qTotal > 1 ? `${qIdx} of ${qTotal}` : '';

  if (_gInvState === 'parsing') {
    body.innerHTML = `
      <div style="display:flex;align-items:center;gap:14px;padding:20px 0">
        <div class="spinner" style="width:20px;height:20px;flex-shrink:0"></div>
        <div>
          <div style="font-size:14px;font-weight:600">Reading invoice…</div>
          <div style="font-size:12px;color:var(--muted);margin-top:3px">${escapeHtml(_gInvFile?.name || '')}</div>
        </div>
      </div>`;
    return;
  }

  if (_gInvState === 'saving') {
    body.innerHTML = `
      <div style="display:flex;align-items:center;gap:14px;padding:20px 0">
        <div class="spinner" style="width:20px;height:20px;flex-shrink:0"></div>
        <div style="font-size:14px;font-weight:600">Uploading and saving…</div>
      </div>`;
    return;
  }

  // review state
  const parsed  = _gInvParsed || {};
  const allSuppliers = (_suppliers || []).filter(s => s.is_active !== false);

  // Supplier match banner
  let supplierBanner = '';
  if (parsed._error) {
    supplierBanner = `<div style="background:rgba(208,2,27,.1);border:1px solid var(--red);color:var(--red);padding:8px 12px;border-radius:6px;font-size:12px;margin-bottom:12px">⚠ Could not read file — fill in below manually. (${escapeHtml(parsed._error)})</div>`;
  } else if (_gInvSupplier) {
    supplierBanner = `<div style="background:rgba(62,207,142,.1);border:1px solid var(--green);color:var(--green);padding:8px 12px;border-radius:6px;font-size:12px;margin-bottom:12px">✓ Supplier matched: <b>${escapeHtml(_gInvSupplier.supplier_name)}</b>${parsed.supplier_name ? ` (parsed: "${escapeHtml(parsed.supplier_name)}")` : ''}</div>`;
  } else {
    supplierBanner = `<div style="background:rgba(245,158,11,.1);border:1px solid var(--amber);color:var(--amber);padding:8px 12px;border-radius:6px;font-size:12px;margin-bottom:12px">⚠ Supplier "${escapeHtml(parsed.supplier_name || '?')}" not matched — pick one below.</div>`;
  }

  // Supplier dropdown
  const suppOpts = ['<option value="">— select supplier —</option>']
    .concat(allSuppliers.map(s =>
      `<option value="${s.id}"${_gInvSupplier?.id === s.id ? ' selected' : ''}>${escapeHtml(s.supplier_name)}</option>`
    )).join('');

  // PO dropdown
  const matched = _gInvMatchedPoId ? _gInvPos.find(p => p.id === _gInvMatchedPoId) : null;
  const poMatchInfo = matched ? (() => {
    const poN  = _poNet(matched);
    const invN = Number(parsed.net_amount);
    const hasN = Number.isFinite(invN) && invN > 0;
    const ok   = hasN && Math.abs(poN - invN) <= 1;
    const warn = hasN && !ok;
    const col  = warn ? 'var(--amber)' : 'var(--green)';
    const bg   = warn ? 'rgba(245,158,11,.1)' : 'rgba(62,207,142,.1)';
    const fmtN = v => `£${Number(v).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
    return `
      <div style="background:${bg};border:1px solid ${col};border-radius:8px;padding:10px 14px;margin-top:8px">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:12px">
          <div style="color:${col};font-size:12px;font-weight:600">✓ PO matched: ${escapeHtml(matched.reference)}</div>
          ${hasN ? `<div style="font-size:11px;color:${col};font-weight:600">${ok ? '✓ Values match' : '⚠ Value mismatch'}</div>` : ''}
        </div>
        ${hasN ? `<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:8px">
          <div style="background:rgba(0,0,0,.2);border-radius:6px;padding:6px 10px">
            <div style="font-size:10px;color:var(--muted);margin-bottom:2px">PO VALUE (NET)</div>
            <div style="font-size:14px;font-weight:700;font-family:var(--font-mono);color:var(--text)">${fmtN(poN)}</div>
          </div>
          <div style="background:rgba(0,0,0,.2);border-radius:6px;padding:6px 10px">
            <div style="font-size:10px;color:var(--muted);margin-bottom:2px">INVOICE NET</div>
            <div style="font-size:14px;font-weight:700;font-family:var(--font-mono);color:${ok ? 'var(--text)' : 'var(--amber)'}">${fmtN(invN)}</div>
          </div>
        </div>` : ''}
      </div>`;
  })() : '';

  const poOpts = ['<option value="">— pick a PO —</option>']
    .concat((_gInvPos).map(p => {
      const project = p.project_number || p.cost_centre || '—';
      return `<option value="${p.id}"${p.id === _gInvMatchedPoId ? ' selected' : ''}>${escapeHtml(p.reference || '—')} · £${_poNet(p).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})} net · ${escapeHtml(project)} · ${escapeHtml((p.description||'').slice(0,35))}</option>`;
    })).join('');

  const skipLabel = qTotal > 1 ? 'Skip' : 'Cancel';

  body.innerHTML = `
    ${supplierBanner}
    <div style="margin-bottom:12px">
      <label style="display:block;color:var(--muted);margin-bottom:4px;font-size:11px;text-transform:uppercase;letter-spacing:.05em">Supplier</label>
      <select id="gInvSupplierSel" class="field-input" style="width:100%;font-size:13px"
              onchange="_gInvOnSupplierChange(this.value)">${suppOpts}</select>
    </div>
    <div style="margin-bottom:12px">
      <label style="display:block;color:var(--muted);margin-bottom:4px;font-size:11px;text-transform:uppercase;letter-spacing:.05em">PO to attach to</label>
      <select id="gInvPoSel" class="field-input" style="width:100%;font-size:13px">${poOpts}</select>
      ${poMatchInfo}
    </div>
    <!-- Hidden inputs carry values to _gInvSave -->
    <input type="hidden" id="gInvNet"   value="${parsed.net_amount??0}">
    <input type="hidden" id="gInvVat"   value="${parsed.vat_amount??0}">
    <input type="hidden" id="gInvGross" value="${parsed.gross_amount??0}">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px">
      <div>
        <label style="display:block;color:var(--muted);margin-bottom:4px;font-size:11px;text-transform:uppercase;letter-spacing:.05em">Invoice ref</label>
        <input id="gInvRef" class="field-input" type="text" value="${escapeHtml(parsed.invoice_ref||'')}" style="width:100%">
      </div>
      <div>
        <label style="display:block;color:var(--muted);margin-bottom:4px;font-size:11px;text-transform:uppercase;letter-spacing:.05em">Invoice date</label>
        <input id="gInvDate" class="field-input" type="date" value="${escapeHtml(parsed.invoice_date||new Date().toISOString().slice(0,10))}" style="width:100%">
      </div>
    </div>
    <!-- Read-only financial summary -->
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:14px">
      ${[['Net',parsed.net_amount],['VAT',parsed.vat_amount],['Gross',parsed.gross_amount]].map(([lbl,val])=>`
        <div style="background:var(--bg-darker,var(--bg));border:1px solid var(--border);border-radius:6px;padding:8px 12px">
          <div style="font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:3px">${lbl} £</div>
          <div style="font-size:15px;font-weight:600;font-family:var(--font-mono);color:${Number(val)<0?'var(--red)':' var(--text)'}">${val!=null?'£'+Number(val).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2}):'—'}</div>
        </div>`).join('')}
    </div>
    <div style="display:flex;align-items:center;justify-content:space-between;gap:10px">
      <div style="font-size:11px;color:var(--subtle);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">📄 ${escapeHtml(_gInvFile?.name||'')}</div>
      <div style="display:flex;gap:8px;flex-shrink:0">
        <button class="btn btn-ghost" style="font-size:12px;padding:6px 14px" onclick="_gInvSkip()">${skipLabel}</button>
        <button class="btn btn-primary" style="font-size:12px;padding:6px 14px" onclick="_gInvSave()">Save Invoice</button>
      </div>
    </div>`;
}

async function _gInvOnSupplierChange(supplierId) {
  const id = parseInt(supplierId);
  _gInvSupplier = (_suppliers || []).find(s => s.id === id) || null;
  _gInvMatchedPoId = null;
  if (_gInvSupplier) {
    try {
      const allPos = await api.get(`/api/purchase-orders?supplier_id=${id}`);
      _gInvPos = (allPos || []).filter(p => !p.supplier_invoice_received_at);
    } catch { _gInvPos = []; }
    _gInvMatchedPoId = _gInvMatchPo();
  } else {
    _gInvPos = [];
  }
  _gInvRender();
}

function _gInvSkip() {
  _gInvQueueIdx++;
  _gInvProcessNext();
}

async function _gInvSave() {
  const supplierId = parseInt(document.getElementById('gInvSupplierSel')?.value);
  const poId       = parseInt(document.getElementById('gInvPoSel')?.value);
  const ref        = document.getElementById('gInvRef')?.value.trim();
  const date       = document.getElementById('gInvDate')?.value;
  const net        = Number(document.getElementById('gInvNet')?.value || 0);
  const vat        = Number(document.getElementById('gInvVat')?.value || 0);
  const gross      = Number(document.getElementById('gInvGross')?.value || 0);

  if (!supplierId) { toast('Select a supplier', 'error'); return; }
  if (!poId)       { toast('Pick a PO to attach this invoice to', 'error'); return; }
  if (!gross)      { toast('Gross amount is required', 'error'); return; }

  const supplier = (_suppliers || []).find(s => s.id === supplierId);
  const po       = _gInvPos.find(p => p.id === poId);
  if (!po) { toast('PO not found', 'error'); return; }

  _gInvState = 'saving';
  _gInvRender();
  setLoading(true);
  try {
    const folder    = await _findOrCreateSupplierInvoiceFolder(date);
    const stamp     = (supplier?.supplier_name || 'supplier').replace(/\s+/g, '_').slice(0, 30);
    const ext       = (_gInvFile.name.split('.').pop() || 'pdf').toLowerCase();
    const fileName  = sanitizeSpFilename(`${date}_${stamp}_${ref || 'no-ref'}.${ext}`);
    const driveItem = await uploadFileToFolder(folder.id, fileName, _gInvFile, _gInvFile.type || 'application/octet-stream');

    await api.post('/api/supplier-invoices', {
      supplier_id:         supplierId,
      po_id:               poId,
      invoice_ref:         ref || null,
      invoice_date:        date || null,
      net:                 net || null,
      vat:                 vat || null,
      gross:               gross,
      sharepoint_file_id:  driveItem.id,
      sharepoint_file_url: driveItem.webUrl,
      filename:            fileName,
    });

    toast(`Invoice attached to ${po.reference} ✓`, 'success');
    _gInvQueueIdx++;
    await _gInvProcessNext();
  } catch (err) {
    console.error('Global invoice save failed', err);
    toast('Failed to save: ' + (err.message || 'unknown error'), 'error');
    _gInvState = 'review';
    _gInvRender();
  } finally {
    setLoading(false);
  }
}


// ═══════════════════════════════════════════════════════════════════════════
// COMPANY DOCUMENT LIBRARY (D1 v2, 2026-07-29) — Office › Company Docs tab
// Register in SQL (/api/company-documents); files in SharePoint under
// BAMA / 01 - Company Management (SP_TAX). Drag & drop → Claude reads each
// PDF/image (reader-only, nulls when not printed) → editable review card →
// save uploads the file to the right folder and writes the register row.
// UI is injected into #tab-docs on office.html; modal self-injects.
// ═══════════════════════════════════════════════════════════════════════════

const DOC_CATS = {
  insurance:     { label: 'Insurance',        color: '#3b82f6' },
  policy:        { label: 'Policy',           color: '#a855f7' },
  accreditation: { label: 'Accreditation',    color: '#22c55e' },
  coshh:         { label: 'COSHH / SDS',      color: '#eab308' },
  ra_ssow:       { label: 'RA / SSoW',        color: '#ef4444' },
  hs:            { label: 'H&S (general)',    color: '#f97316' },
  other:         { label: 'Other',            color: '#94a3b8' }
};
const DOC_CAT_OPTIONS = Object.entries(DOC_CATS)
  .map(([k, c]) => `<option value="${k}">${c.label}</option>`).join('');
// Categories that carry a read-and-sign obligation (mobile Sign Policies tile).
const DOC_SIGNABLE = ['policy', 'hs', 'ra_ssow'];

let _docRows = null, _docFilter = 'all', _docEditing = null, _docRenewing = null;
let _docQueue = [];   // [{file, parsed, state:'parsing'|'review'|'saving'|'done'|'error', err}]

// ── SharePoint destination by category ──────────────────────────────────────
async function docTargetFolder(category, issueDate) {
  const D = BAMA_DRIVE_ID;
  switch (category) {
    case 'insurance': {
      const y = issueDate ? new Date(issueDate).getFullYear() : new Date().getFullYear();
      return await getOrCreateSubfolder(SP_TAX.insurances, spYearName(y), D);
    }
    case 'policy':        return await getOrCreateSubfolder(SP_TAX.companyMgmt, '02 - Policies & Procedures', D);
    case 'accreditation': return await getOrCreateSubfolder(SP_TAX.companyMgmt, '03 - Accreditations & Certifications', D);
    case 'coshh': {
      const hs = await getOrCreateSubfolder(SP_TAX.companyMgmt, '04 - H&S', D);
      return await getOrCreateSubfolder(hs.id, '03 - COSHH', D);
    }
    case 'ra_ssow': {
      const hs = await getOrCreateSubfolder(SP_TAX.companyMgmt, '04 - H&S', D);
      return await getOrCreateSubfolder(hs.id, '05 - Risk Assessments & SSoW', D);
    }
    case 'hs':            return await getOrCreateSubfolder(SP_TAX.companyMgmt, '04 - H&S', D);
    default:              return { id: SP_TAX.companyMgmt };
  }
}

// ── Tab shell ────────────────────────────────────────────────────────────────
